## 3) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var name: String
    var notes: String = ""
    var createdAt: Date = Date()
    var completionDates: [Date] = []

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streakCount
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDateInToday($0) }
    }

    mutating func toggleCompletionForToday() {
        let calendar = Calendar.current
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }
}
```

