## 2) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var targetDaysPerWeek: Int
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        details: String = "",
        targetDaysPerWeek: Int = 7,
        colorHex: String = "#4F46E5"
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.targetDaysPerWeek = targetDaysPerWeek
        self.colorHex = colorHex
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completions
            .map { $0.date }
            .sorted(by: >)

        guard let firstDate = sortedDates.first else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())
        var datesSet = Set(sortedDates.map { calendar.startOfDay(for: $0) })

        while datesSet.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
            currentDate = previousDay
        }

        return streak
    }

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.startOfDay(for: $0.date) == today }
    }
}
```

