import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @State private var showingEditHabit = false

    let habit: Habit

    var body: some View {
        List {
            Section("Overview") {
                HStack {
                    Text("Streak")
                    Spacer()
                    Text("\(habit.streakCount) days")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Target")
                    Spacer()
                    Text("\(habit.targetDaysPerWeek) days/week")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Status")
                    Spacer()
                    Text(habit.completedToday ? "Completed today" : "Not completed")
                        .foregroundStyle(habit.completedToday ? .green : .secondary)
                }
            }

            Section("Actions") {
                Button {
                    toggleCompletionForToday()
                } label: {
                    Text(habit.completedToday ? "Unmark Today" : "Mark Completed Today")
                }
            }

            Section("History") {
                if habit.completions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.completions.sorted(by: { $0.date > $1.date })) { completion in
                        Text(completion.date.formatted(date: .abbreviated, time: .shortened))
                    }
                }
            }
        }
        .navigationTitle(habit.name)
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                Button("Edit") {
                    showingEditHabit = true
                }
            }
        }
        .sheet(isPresented: $showingEditHabit) {
            AddEditHabitView(habit: habit)
        }
    }

    private func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            Calendar.current.startOfDay(for: $0.date) == today
        }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }
    }
}
