import SwiftUI
import SwiftData

struct AddEditHabitView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    var habit: Habit?

    @State private var name: String = ""
    @State private var details: String = ""
    @State private var targetDaysPerWeek: Int = 7
    @State private var colorHex: String = "#4F46E5"

    private let colorOptions: [String] = [
        "#4F46E5", "#EF4444", "#10B981", "#F59E0B", "#8B5CF6", "#06B6D4", "#EC4899"
    ]

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit Info") {
                    TextField("Name", text: $name)
                    TextField("Details", text: $details, axis: .vertical)
                        .lineLimit(3, reservesSpace: true)
                }

                Section("Goal") {
                    Stepper("Target days per week: \(targetDaysPerWeek)", value: $targetDaysPerWeek, in: 1...7)
                }

                Section("Color") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack {
                            ForEach(colorOptions, id: \.self) { hex in
                                Circle()
                                    .fill(Color(hex: hex))
                                    .frame(width: 32, height: 32)
                                    .overlay(
                                        Circle()
                                            .stroke(Color.primary, lineWidth: colorHex == hex ? 3 : 0)
                                    )
                                    .onTapGesture {
                                        colorHex = hex
                                    }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }
            }
            .navigationTitle(habit == nil ? "New Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        saveHabit()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear {
                if let habit {
                    name = habit.name
                    details = habit.details
                    targetDaysPerWeek = habit.targetDaysPerWeek
                    colorHex = habit.colorHex
                }
            }
        }
    }

    private func saveHabit() {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)

        if let habit {
            habit.name = trimmedName
            habit.details = details
            habit.targetDaysPerWeek = targetDaysPerWeek
            habit.colorHex = colorHex
        } else {
            let newHabit = Habit(
                name: trimmedName,
                details: details,
                targetDaysPerWeek: targetDaysPerWeek,
                colorHex: colorHex
            )
            modelContext.insert(newHabit)
        }

        dismiss()
    }
}
