## 3) `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "saved_habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, emoji: String) {
        let habit = Habit(name: name, emoji: emoji)
        habits.insert(habit, at: 0)
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existingIndex = habits[index].completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            habits[index].completedDates.remove(at: existingIndex)
        } else {
            habits[index].completedDates.append(Date())
        }
    }

    func resetAll() {
        habits.removeAll()
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else {
            habits = sampleHabits
            return
        }

        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
            habits = sampleHabits
        }
    }

    private var sampleHabits: [Habit] {
        [
            Habit(name: "Drink Water", emoji: "💧"),
            Habit(name: "Read 10 Pages", emoji: "📚"),
            Habit(name: "Exercise", emoji: "🏃"),
        ]
    }
}
