## 2) Models

### `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerDay: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerDay: Int = 1
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerDay = targetPerDay
    }

    var completionCount: Int {
        completions.count
    }

    func completions(on date: Date) -> Int {
        completions.filter { Calendar.current.isDate($0.date, inSameDayAs: date) }.count
    }

    func isCompletedToday: Bool {
        completions(on: Date()) >= targetPerDay
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let groupedDates = Set(completions.map { calendar.startOfDay(for: $0.date) })
        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while groupedDates.contains(day) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }
}
```

