```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
    }

    var streak: Int {
        let sorted = completions.sorted { $0.date > $1.date }
        guard !sorted.isEmpty else { return 0 }

        var streakCount = 0
        var currentDate = Calendar.current.startOfDay(for: Date())

        for completion in sorted {
            let completionDate = Calendar.current.startOfDay(for: completion.date)
            if completionDate == currentDate {
                streakCount += 1
                currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if completionDate < currentDate {
                break
            }
        }

        return streakCount
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains {
            Calendar.current.startOfDay(for: $0.date) == today
        }
    }
}
