                        ForEach(habit.completions.sorted(by: { $0.date > $1.date })) { completion in
                            HStack {
                                Image(systemName: "checkmark.circle.fill")
                                    .foregroundStyle(.green)
                                Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                                Spacer()
                            }
                            .padding(.vertical, 4)
                        }
                    }
                }
            }
            .padding()
        }
        .navigationTitle("Habit")
        .navigationBarTitleDisplayMode(.inline)
    }

    private func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            Calendar.current.startOfDay(for: $0.date) == today
        }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }
    }
}
