### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
        self.isArchived = false
    }

    var streak: Int {
        let sorted = completions
            .filter { Calendar.current.isDateInToday($0.date) || $0.date < Date() }
            .map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sorted.isEmpty else { return 0 }

        var currentStreak = 1
        var currentDate = sorted[0]

        for date in sorted.dropFirst() {
            let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate)!
            if Calendar.current.isDate(date, inSameDayAs: expected) {
                currentStreak += 1
                currentDate = date
            } else if !Calendar.current.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return currentStreak
    }

    var totalCompletions: Int {
        completions.count
    }

    func completed(on date: Date) -> Bool {
        completions.contains { Calendar.current.isDate($0.date, inSameDayAs: date) }
    }
}
