```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7,
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
        self.isArchived = isArchived
        self.completions = []
    }

    var streak: Int {
        let sorted = completions
            .filter { Calendar.current.isDateInToday($0.date) || $0.date < Date() }
            .map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sorted.isEmpty else { return 0 }

        var streak = 1
        var currentDate = sorted[0]

        for date in sorted.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               Calendar.current.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !Calendar.current.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    var completedToday: Bool {
        completions.contains { Calendar.current.isDateInToday($0.date) }
    }

    var totalCompletions: Int {
        completions.count
    }
}
