    var name: String
    var detail: String
    var createdAt: Date
    var colorHex: String
    var completions: [Date]

    init(name: String, detail: String = "", colorHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.detail = detail
        self.createdAt = Date()
        self.colorHex = colorHex
        self.completions = []
    }

    var completionCount: Int {
        completions.count
    }

    var isCompletedToday: Bool {
        Calendar.current.isDate(completions.last, inSameDayAs: Date())
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completions.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previousDay
            } else if day < expectedDate {
                break
            }
        }

        return streak
    }

    func markCompletedToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if !completions.contains(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completions.append(Date())
        }
    }

    func unmarkCompletedToday() {
        let calendar = Calendar.current
        completions.removeAll { calendar.isDate($0, inSameDayAs: Date()) }
    }
}
