import SwiftUI

struct FlowLayout<Data: RandomAccessCollection, Content: View>: View where Data.Element: Hashable {
    let items: Data
    let spacing: CGFloat
    let content: (Data.Element) -> Content

    init(items: Data, spacing: CGFloat = 8, @ViewBuilder content: @escaping (Data.Element) -> Content) {
        self.items = items
        self.spacing = spacing
        self.content = content
    }

    var body: some View {
        FlexibleView(data: Array(items), spacing: spacing, content: content)
    }
}

struct FlexibleView<Data: RandomAccessCollection, Content: View>: View where Data.Element: Hashable {
    let data: [Data.Element]
    let spacing: CGFloat
    let content: (Data.Element) -> Content

    init(data: [Data.Element], spacing: CGFloat = 8, @ViewBuilder content: @escaping (Data.Element) -> Content) {
        self.data = data
        self.spacing = spacing
        self.content = content
    }

    var body: some View {
        GeometryReader { geometry in
            let width = geometry.size.width
            var currentRowWidth: CGFloat = 0
            var rows: [[Data.Element]] = [[]]

            for item in data {
                let itemWidth: CGFloat = 32 + spacing
                if currentRowWidth + itemWidth > width {
                    rows.append([item])
                    currentRowWidth = itemWidth
                } else {
                    rows[rows.count - 1].append(item)
                    currentRowWidth += itemWidth
                }
            }

            VStack(alignment: .leading, spacing: spacing) {
                ForEach(rows.indices, id: \.self) { rowIndex in
                    HStack(spacing: spacing) {
                        ForEach(rows[rowIndex], id: \.self) { item in
                            content(item)
                        }
                    }
                }
            }
        }
        .frame(minHeight: 40)
    }
}
