### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var symbol: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var streak: Int
    var completionsData: Data

    init(name: String, symbol: String = "checkmark.circle.fill") {
        self.name = name
        self.symbol = symbol
        self.createdAt = Date()
        self.lastCompletedAt = nil
        self.streak = 0
        self.completionsData = Data()
    }

    var completions: Set<String> {
        get {
            guard let decoded = try? JSONDecoder().decode([String].self, from: completionsData) else {
                return []
            }
            return Set(decoded)
        }
        set {
            let encoded = Array(newValue)
            if let data = try? JSONEncoder().encode(encoded) {
                completionsData = data
            }
        }
    }

    func markCompleted(for date: Date = Date()) {
        let key = Self.dayKey(for: date)
        var current = completions
        guard !current.contains(key) else { return }

        current.insert(key)
        completions = current
        lastCompletedAt = date
        updateStreak(for: date)
    }

    func isCompleted(for date: Date = Date()) -> Bool {
        completions.contains(Self.dayKey(for: date))
    }

    private func updateStreak(for date: Date) {
        let calendar = Calendar.current
        let todayKey = Self.dayKey(for: date)

        guard let last = lastCompletedAt else {
            streak = 1
            return
        }

        let lastDay = calendar.startOfDay(for: last)
        let currentDay = calendar.startOfDay(for: date)

        if calendar.isDate(lastDay, inSameDayAs: currentDay) {
            streak = max(streak, 1)
            return
        }

        if let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay),
           calendar.isDate(lastDay, inSameDayAs: yesterday) {
            streak += 1
        } else if !completions.contains(todayKey) {
            streak = 1
        }
    }

    static func dayKey(for date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale.current
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }
}
