### `Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable, Hashable {
    var id: UUID = UUID()
    var name: String
    var icon: String
    var colorHex: String
    var creationDate: Date = Date()
    var completedDates: [Date] = []

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted()

        guard let lastDate = sortedDates.last else { return 0 }

        var streakCount = 1
        var currentDate = lastDate

        while let previousDate = calendar.date(byAdding: .day, value: -1, to: currentDate),
              sortedDates.contains(calendar.startOfDay(for: previousDate)) {
            streakCount += 1
            currentDate = previousDate
        }

        return streakCount
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completedDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }
}
