### `HabitStore.swift`
```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "habits_storage_key"

    init() {
        loadHabits()
    }

    func addHabit(name: String, icon: String, colorHex: String) {
        let habit = Habit(name: name, icon: icon, colorHex: colorHex)
        habits.append(habit)
    }

    func updateHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index] = habit
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let today = Calendar.current.startOfDay(for: Date())
        if habits[index].completedDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            habits[index].completedDates.removeAll { Calendar.current.isDate($0, inSameDayAs: today) }
        } else {
            habits[index].completedDates.append(Date())
        }
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else { return }
        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
        }
    }
}
