## 2) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var icon: String
    var colorHex: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        icon: String = "checkmark.circle",
        colorHex: String = "#4CAF50",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.icon = icon
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: yesterday) {
                streak += 1
                currentDate = date
            } else if calendar.isDate(date, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    var totalCompletions: Int {
        let uniqueDays = Set(completionDates.map { Calendar.current.startOfDay(for: $0) })
        return uniqueDays.count
    }
}
