## 4) `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "saved_habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, icon: String, colorHex: String) {
        let habit = Habit(name: name, icon: icon, colorHex: colorHex)
        habits.insert(habit, at: 0)
    }

    func updateHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index] = habit
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
    }

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let today = Calendar.current.startOfDay(for: Date())
        if let completionIndex = habits[index].completionDates.firstIndex(where: {
            Calendar.current.isDateInToday($0)
        }) {
            habits[index].completionDates.remove(at: completionIndex)
        } else {
            habits[index].completionDates.append(today)
        }
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else {
            habits = sampleHabits
            return
        }

        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
            habits = sampleHabits
        }
    }

    private var sampleHabits: [Habit] {
        [
            Habit(name: "Drink Water", icon: "drop.fill", colorHex: "#2196F3"),
            Habit(name: "Read 10 Pages", icon: "book.fill", colorHex: "#9C27B0"),
            Habit(name: "Workout", icon: "figure.run", colorHex: "#FF5722")
        ]
    }
}
