### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(name: String, details: String = "", colorHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
    }

    var completionCount: Int {
        completions.count
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completions.map { $0.date }.sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = calendar.startOfDay(for: first)

        for date in sortedDates.dropFirst() {
            let normalized = calendar.startOfDay(for: date)
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(normalized, inSameDayAs: expected) {
                streak += 1
                currentDate = normalized
            } else if calendar.isDate(normalized, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    var longestStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Array(Set(completions.map { calendar.startOfDay(for: $0.date) })).sorted()
        guard !uniqueDays.isEmpty else { return 0 }

        var longest = 1
        var current = 1

        for i in 1..<uniqueDays.count {
            let previous = uniqueDays[i - 1]
            let currentDay = uniqueDays[i]

            if let expected = calendar.date(byAdding: .day, value: 1, to: previous),
               calendar.isDate(expected, inSameDayAs: currentDay) {
                current += 1
                longest = max(longest, current)
            } else {
                current = 1
            }
        }

        return longest
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completions.contains { calendar.isDateInToday($0.date) }
    }
}
```

