struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var body: some View {
        Form {
            Section {
                HStack {
                    Text("Streak")
                    Spacer()
                    Text("\(habit.currentStreak)")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Longest Streak")
                    Spacer()
                    Text("\(habit.longestStreak)")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Total Completions")
                    Spacer()
                    Text("\(habit.completionCount)")
                        .foregroundStyle(.secondary)
                }
            }

            Section("Today") {
                if habit.isCompletedToday() {
                    Button(role: .destructive) {
                        removeTodayCompletion()
                    } label: {
                        Text("Mark as Incomplete")
                    }
                } else {
                    Button {
                        markComplete()
                    } label: {
                        Text("Mark Complete")
                    }
                }
            }

            Section("Completion History") {
                if habit.completions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.completions.sorted(by: { $0.date > $1.date })) { completion in
                        HStack {
                            Text(completion.date.formatted(date: .abbreviated, time: .shortened))
                            Spacer()
                            Button(role: .destructive) {
                                modelContext.delete(completion)
                            } label: {
                                Image(systemName: "trash")
                            }
                            .buttonStyle(.borderless)
                        }
                    }
                }
            }
        }
        .navigationTitle(habit.name)
    }

    private func markComplete() {
        let completion = HabitCompletion(date: Date(), habit: habit)
        modelContext.insert(completion)
        habit.completions.append(completion)
    }

    private func removeTodayCompletion() {
        let todayCompletions = habit.completions.filter { Calendar.current.isDateInToday($0.date) }
        for completion in todayCompletions {
            modelContext.delete(completion)
        }
    }
}
