## 2) Data model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var completedDates: [Date]

    init(name: String,
         habitDescription: String = "",
         createdAt: Date = .now,
         colorHex: String = "#4F46E5",
         completedDates: [Date] = []) {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: .now) })
    }

    var streak: Int {
        let calendar = Calendar.current
        let days = Set(completedDates.map { calendar.startOfDay(for: $0) }).sorted()
        guard !days.isEmpty else { return 0 }

        var streakCount = 1
        var currentDay = days.last!

        for index in stride(from: days.count - 2, through: 0, by: -1) {
            let previousDay = days[index]
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDay),
               calendar.isDate(previousDay, inSameDayAs: expected) {
                streakCount += 1
                currentDay = previousDay
            } else {
                break
            }
        }
        return streakCount
    }

    func toggleTodayCompletion() {
        let today = Calendar.current.startOfDay(for: .now)
        if let index = completedDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
```

