## 5) Add/Edit screen

### `HabitEditorView.swift`
```swift
import SwiftUI
import SwiftData

struct HabitEditorView: View {
    enum Mode {
        case add
        case edit(Habit)
    }

    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    let mode: Mode

    @State private var name: String = ""
    @State private var habitDescription: String = ""
    @State private var colorHex: String = "#4F46E5"

    init(mode: Mode) {
        self.mode = mode
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit") {
                    TextField("Name", text: $name)
                    TextField("Description", text: $habitDescription, axis: .vertical)
                        .lineLimit(3...6)
                }

                Section("Appearance") {
                    TextField("Color Hex", text: $colorHex)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                }
            }
            .navigationTitle(title)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") { save() }
                        .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear {
                loadInitialValues()
            }
        }
    }

    private var title: String {
        switch mode {
        case .add: return "New Habit"
        case .edit: return "Edit Habit"
        }
    }

    private func loadInitialValues() {
        switch mode {
        case .add:
            break
        case .edit(let habit):
            name = habit.name
            habitDescription = habit.habitDescription
            colorHex = habit.colorHex
        }
    }

    private func save() {
        switch mode {
        case .add:
            let habit = Habit(
                name: name.trimmingCharacters(in: .whitespacesAndNewlines),
                habitDescription: habitDescription.trimmingCharacters(in: .whitespacesAndNewlines),
                colorHex: colorHex
            )
            modelContext.insert(habit)

        case .edit(let habit):
            habit.name = name.trimmingCharacters(in: .whitespacesAndNewlines)
            habit.habitDescription = habitDescription.trimmingCharacters(in: .whitespacesAndNewlines)
            habit.colorHex = colorHex
        }

        try? modelContext.save()
        dismiss()
    }
}
