### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
    }

    var completionCount: Int {
        completions.count
    }

    var currentStreak: Int {
        let sorted = completions.map { $0.date }.sorted(by: >)
        guard !sorted.isEmpty else { return 0 }

        var streak = 0
        var currentDate = Date().startOfDay

        if !Calendar.current.isDate(sorted.first!, inSameDayAs: currentDate) {
            currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        let completionDays = Set(sorted.map { $0.startOfDay })

        while completionDays.contains(currentDate) {
            streak += 1
            currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        return streak
    }

    var lastCompletedDate: Date? {
        completions.map { $0.date }.max()
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let day = date.startOfDay
        return completions.contains { $0.date.startOfDay == day }
    }
}
```

