import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var name: String
    var symbol: String
    var colorHex: String
    var createdAt: Date = Date()

    // Track completion dates as ISO strings for easy Codable support
    var completionDates: [Date] = []

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates.sorted()

        guard let lastDate = sortedDates.last else { return 0 }

        var currentStreak = 0
        var date = calendar.startOfDay(for: lastDate)
        let today = calendar.startOfDay(for: Date())

        while date <= today {
            if sortedDates.contains(where: { calendar.isDate($0, inSameDayAs: date) }) {
                currentStreak += 1
                if let previous = calendar.date(byAdding: .day, value: -1, to: date) {
                    date = previous
                } else {
                    break
                }
            } else {
                break
            }
        }
        return currentStreak
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains(where: { calendar.isDate($0, inSameDayAs: Date()) })
    }
}
