```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var isArchived: Bool
    var targetPerWeek: Int
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        isArchived: Bool = false,
        targetPerWeek: Int = 7,
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.targetPerWeek = targetPerWeek
        self.colorHex = colorHex
    }

    var completedToday: Bool {
        let calendar = Calendar.current
        return completions.contains { calendar.isDate($0.date, inSameDayAs: Date()) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sorted = completions.map(\.date).sorted(by: >)
        guard let first = sorted.first else { return 0 }

        var streak = 1
        var currentDate = calendar.startOfDay(for: first)

        for date in sorted.dropFirst() {
            let day = calendar.startOfDay(for: date)
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(day, inSameDayAs: expected) {
                streak += 1
                currentDate = day
            } else if calendar.isDate(day, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }
        return streak
    }

    var totalCompletions: Int {
        completions.count
    }
}
