```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var notes: String
    var colorHex: String
    var createdAt: Date
    var targetPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        notes: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = .now,
        targetPerWeek: Int = 7
    ) {
        self.id = id
        self.name = name
        self.notes = notes
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.targetPerWeek = targetPerWeek
    }

    var completedToday: Bool {
        completions.contains { Calendar.current.isDateInToday($0.date) }
    }

    var currentStreak: Int {
        let sortedDates = completions.map(\.date).sorted(by: >)
        guard let firstDate = sortedDates.first else { return 0 }

        var streak = 0
        var currentDate = Calendar.current.startOfDay(for: Date())
        let uniqueDays = Set(sortedDates.map { Calendar.current.startOfDay(for: $0) })

        while uniqueDays.contains(currentDate) {
            streak += 1
            guard let previousDay = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) else { break }
            currentDate = previousDay
        }

        return streak
    }

    var totalCompletions: Int {
        completions.count
    }
}
