## 11) Important note about the editor

`@Bindable var habit: Habit?` is not ideal for optional binding in SwiftUI. A cleaner approach is to use separate modes for create/edit. Here is a better version of the editor that you should use instead.

### Replace `HabitEditorView.swift` with this improved version

```swift
import SwiftUI
import SwiftData

struct HabitEditorView: View {
    enum Mode {
        case create
        case edit(Habit)
    }

    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    let mode: Mode

    @State private var name: String = ""
    @State private var notes: String = ""
    @State private var colorHex: String = "#4F46E5"
    @State private var targetPerWeek: Int = 7

    init(mode: Mode = .create) {
        self.mode = mode

        switch mode {
        case .create:
            _name = State(initialValue: "")
            _notes = State(initialValue: "")
            _colorHex = State(initialValue: "#4F46E5")
            _targetPerWeek = State(initialValue: 7)
        case .edit(let habit):
            _name = State(initialValue: habit.name)
            _notes = State(initialValue: habit.notes)
            _colorHex = State(initialValue: habit.colorHex)
            _targetPerWeek = State(initialValue: habit.targetPerWeek)
        }
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit") {
                    TextField("Name", text: $name)
                    TextField("Notes", text: $notes, axis: .vertical)
                        .lineLimit(3...6)
                }

                Section("Appearance") {
                    TextField("Color Hex", text: $colorHex)
                }

                Section("Goal") {
                    Stepper("Target per week: \(targetPerWeek)", value: $targetPerWeek, in: 1...7)
                }
            }
            .navigationTitle(modeTitle)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") { save() }
                        .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
    }

    private var modeTitle: String {
        switch mode {
        case .create: return "New Habit"
        case .edit: return "Edit Habit"
        }
    }

    private func save() {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)

        switch mode {
        case .create:
            let newHabit = Habit(
                name: trimmedName,
                notes: notes,
                colorHex: colorHex,
                targetPerWeek: targetPerWeek
            )
            modelContext.insert(newHabit)

        case .edit(let habit):
            habit.name = trimmedName
            habit.notes = notes
            habit.colorHex = colorHex
            habit.targetPerWeek = targetPerWeek
        }

        dismiss()
    }
}
```

