## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
    }

    var completionsSorted: [HabitCompletion] {
        completions.sorted { $0.date > $1.date }
    }

    var completedDates: Set<String> {
        Set(completions.map { $0.dayKey })
    }

    func isCompleted(on date: Date) -> Bool {
        completedDates.contains(date.dayKey)
    }

    func markCompleted(on date: Date = Date()) {
        guard !isCompleted(on: date) else { return }
        let completion = HabitCompletion(date: date, habit: self)
        completions.append(completion)
    }

    func unmarkCompleted(on date: Date = Date()) {
        let key = date.dayKey
        completions.removeAll { $0.dayKey == key }
    }

    var currentStreak: Int {
        let days = Set(completions.map { $0.dayKey })
        var streak = 0
        var cursor = Date().startOfDay

        while days.contains(cursor.dayKey) {
            streak += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: cursor) else { break }
            cursor = previous.startOfDay
        }

        return streak
    }
}
```

