    var notes: String = ""
    var createdAt: Date = Date()

    /// Dates when the habit was completed.
    var completionDates: [Date] = []

    var isCompletedToday: Bool {
        completionDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expectedPrevious = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expectedPrevious) {
                streak += 1
                currentDate = date
            } else if calendar.isDate(date, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    mutating func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())
        if let index = completionDates.firstIndex(where: { Calendar.current.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
