## 3) Model: `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var completions: [Date]

    init(
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        completions: [Date] = []
    ) {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completions = completions
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completions.sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 0
        var currentDate = calendar.startOfDay(for: Date())
        var lastDate = calendar.startOfDay(for: first)

        // If latest completion isn't today or yesterday, streak is 0
        let diff = calendar.dateComponents([.day], from: lastDate, to: currentDate).day ?? 0
        if diff > 1 { return 0 }

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if day == currentDate {
                streakCount += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
            } else if day == currentDate {
                streakCount += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
            } else if day < currentDate {
                let gap = calendar.dateComponents([.day], from: day, to: currentDate).day ?? 0
                if gap == 0 {
                    streakCount += 1
                    currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
                } else if gap == 1 {
                    continue
                } else {
                    break
                }
            }
        }

        return streakCount
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completions.contains { calendar.startOfDay(for: $0) == today }
    }

    func toggleCompletionForToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let index = completions.firstIndex(where: { calendar.startOfDay(for: $0) == today }) {
            completions.remove(at: index)
        } else {
            completions.append(today)
        }
    }
}
```

