import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var notes: String
    var colorHex: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(name: String, notes: String = "", colorHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.notes = notes
        self.colorHex = colorHex
        self.createdAt = Date()
    }

    var streak: Int {
        let sortedDates = completions.map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var currentStreak = 1
        var previousDate = first

        for date in sortedDates.dropFirst() {
            if let expectedDate = Calendar.current.date(byAdding: .day, value: -1, to: previousDate),
               Calendar.current.isDate(date, inSameDayAs: expectedDate) {
                currentStreak += 1
                previousDate = date
            } else if !Calendar.current.isDate(date, inSameDayAs: previousDate) {
                break
            }
        }

        return currentStreak
    }

    func completedOnToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: today) }
    }
}
