import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    private let calendar = Calendar.current

    var body: some View {
        List {
            Section {
                HStack {
                    Text("Streak")
                    Spacer()
                    Text("\(habit.streak) days")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Total completions")
                    Spacer()
                    Text("\(habit.totalCompletions)")
                        .foregroundStyle(.secondary)
                }
            }

            Section("Today") {
                Button {
                    toggleTodayCompletion()
                } label: {
                    HStack {
                        Image(systemName: habit.isCompleted(on: .now) ? "checkmark.circle.fill" : "circle")
                            .foregroundStyle(habit.isCompleted(on: .now) ? .green : .secondary)
                        Text(habit.isCompleted(on: .now) ? "Marked complete" : "Mark as complete")
                    }
                }
            }

            Section("Recent Completions") {
                let sorted = habit.completions.sorted { $0.date > $1.date }
                if sorted.isEmpty {
                    Text("No completions yet")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(sorted.prefix(30)) { completion in
                        Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                    }
                }
            }
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }

    private func toggleTodayCompletion() {
        let today = Date().startOfDay

        if let existing = habit.completions.first(where: { $0.date.isSameDay(as: today) }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: today, habit: habit)
            modelContext.insert(completion)
        }

        try? modelContext.save()
    }
}
