## 2) `Models/Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var emoji: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        emoji: String = "✅",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.emoji = emoji
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompleted(on date: Date = Date(), calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    mutating func toggleCompletion(for date: Date = Date(), calendar: Calendar = .current) {
        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: date) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(date)
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sorted = completedDates.sorted(by: >)

        guard !sorted.isEmpty else { return 0 }

        var count = 0
        var currentDate = Date()

        while true {
            if sorted.contains(where: { calendar.isDate($0, inSameDayAs: currentDate) }) {
                count += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previousDay
            } else {
                break
            }
        }

        return count
    }
}
```

