## 2) Data model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var title: String
    var notes: String
    var createdAt: Date
    var isArchived: Bool

    /// Comma-separated weekdays or simple schedule marker for now
    /// Example: "daily", "weekdays", "weekends"
    var scheduleType: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        title: String,
        notes: String = "",
        scheduleType: String = "daily",
        createdAt: Date = .now,
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.title = title
        self.notes = notes
        self.scheduleType = scheduleType
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completions = []
    }

    var currentStreak: Int {
        let sorted = completions.sorted { $0.date > $1.date }
        guard !sorted.isEmpty else { return 0 }

        var streak = 0
        var calendar = Calendar.current
        var expectedDate = calendar.startOfDay(for: Date())

        for completion in sorted {
            let completionDay = calendar.startOfDay(for: completion.date)
            if completionDay == expectedDate {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate)!
            } else if completionDay < expectedDate {
                // If we missed a day, streak ends
                break
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completions.contains { calendar.startOfDay(for: $0.date) == today }
    }
}
```

