                    Text(habit.scheduleType.capitalized)
                        .foregroundStyle(.secondary)
                }
            }

            if !habit.notes.isEmpty {
                Section("Notes") {
                    Text(habit.notes)
                }
            }

            Section("Actions") {
                Button {
                    toggleCompletionForToday()
                } label: {
                    Label(
                        habit.isCompletedToday() ? "Mark Incomplete" : "Mark Complete",
                        systemImage: habit.isCompletedToday() ? "xmark.circle" : "checkmark.circle"
                    )
                }

                Button {
                    showingEdit = true
                } label: {
                    Label("Edit Habit", systemImage: "pencil")
                }
            }

            if !habit.completions.isEmpty {
                Section("History") {
                    ForEach(habit.completions.sorted(by: { $0.date > $1.date })) { completion in
                        Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                    }
                }
            }
        }
        .navigationTitle(habit.title)
        .sheet(isPresented: $showingEdit) {
            AddEditHabitView(habitToEdit: habit)
        }
    }

    private func toggleCompletionForToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = habit.completions.first(where: { calendar.startOfDay(for: $0.date) == today }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }
    }
}
