## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var targetPerDay: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        targetPerDay: Int = 1,
        isArchived: Bool = false
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.targetPerDay = targetPerDay
        self.isArchived = isArchived
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else if calendar.isDate(date, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streakCount
    }

    func completions(on date: Date) -> [HabitCompletion] {
        let calendar = Calendar.current
        return completions.filter { calendar.isDate($0.date, inSameDayAs: date) }
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        completions(on: date).count >= targetPerDay
    }
}
```

