                LabeledContent("Today", value: "\(habit.completions(on: Date()).count)/\(habit.targetPerDay)")
            }

            Section("Actions") {
                Button {
                    toggleCompletionForToday()
                } label: {
                    Text(habit.isCompleted() ? "Undo Today's Completion" : "Mark Completed Today")
                }
            }

            Section("Recent Completions") {
                let recent = habit.completions
                    .sorted { $0.date > $1.date }
                    .prefix(10)

                if recent.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(Array(recent)) { completion in
                        Text(completion.date.formattedShort())
                    }
                }
            }
        }
        .navigationTitle(habit.name)
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                Button("Edit") {
                    showingEditHabit = true
                }
            }
        }
        .sheet(isPresented: $showingEditHabit) {
            AddEditHabitView(habitToEdit: habit)
        }
    }

    private func toggleCompletionForToday() {
        let todayCompletions = habit.completions(on: Date())

        if todayCompletions.count >= habit.targetPerDay {
            // Remove one completion for today
            if let completion = todayCompletions.last {
                modelContext.delete(completion)
            }
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }
    }
}
