## 3) Model layer

### `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var icon: String
    var colorHex: String
    var createdAt: Date
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        habitDescription: String = "",
        icon: String = "checkmark.circle",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.icon = icon
        self.colorHex = colorHex
        self.createdAt = Date()
        self.targetDaysPerWeek = targetDaysPerWeek
    }

    var completionCount: Int {
        completions.count
    }

    var currentStreak: Int {
        let sorted = completions.map { $0.date }.sorted(by: >)
        guard !sorted.isEmpty else { return 0 }

        let calendar = Calendar.current
        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sorted {
            let day = calendar.startOfDay(for: date)
            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if day < expectedDate {
                // Allow skipping to earlier dates only if sequence remains continuous
                if calendar.isDate(day, inSameDayAs: calendar.date(byAdding: .day, value: 0, to: expectedDate)!) {
                    continue
                } else {
                    break
                }
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: today) }
    }
}
