### `HabitStore.swift`

```swift
import Foundation
import SwiftData

@MainActor
final class HabitStore: ObservableObject {
    func addHabit(
        name: String,
        description: String,
        icon: String,
        colorHex: String,
        targetDaysPerWeek: Int,
        context: ModelContext
    ) {
        let habit = Habit(
            name: name,
            habitDescription: description,
            icon: icon,
            colorHex: colorHex,
            targetDaysPerWeek: targetDaysPerWeek
        )
        context.insert(habit)
        try? context.save()
    }

    func toggleTodayCompletion(for habit: Habit, context: ModelContext) {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: { Calendar.current.isDate($0.date, inSameDayAs: today) }) {
            context.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            habit.completions.append(completion)
            context.insert(completion)
        }

        try? context.save()
    }

    func deleteHabit(_ habit: Habit, context: ModelContext) {
        context.delete(habit)
        try? context.save()
    }
}
