### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completionDates = completionDates
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates.sorted(by: >)

        guard let firstDate = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = calendar.startOfDay(for: firstDate)

        for date in sortedDates.dropFirst() {
            let nextDate = calendar.startOfDay(for: date)
            if let expectedDate = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(nextDate, inSameDayAs: expectedDate) {
                streak += 1
                currentDate = nextDate
            } else if calendar.isDate(nextDate, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: Date()) }
    }

    func markCompletedToday() {
        guard !isCompletedToday() else { return }
        completionDates.append(Date())
    }

    func unmarkCompletedToday() {
        let calendar = Calendar.current
        completionDates.removeAll { calendar.isDate($0, inSameDayAs: Date()) }
    }
}
