## 2) Data model

### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int
    var completedDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
        self.completedDates = []
    }

    var isCompletedToday: Bool {
        Calendar.current.isDateInToday(completedDates.last ?? .distantPast)
    }

    var completionCount: Int {
        completedDates.count
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        var currentStreak = 0
        var expectedDate = Date()

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                currentStreak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if calendar.isDate(date, inSameDayAs: calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate) {
                currentStreak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else {
                break
            }
        }
        return currentStreak
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let index = completedDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
```

