## 3) Streak utility

### `Utilities/HabitStreakCalculator.swift`
```swift
import Foundation

struct HabitStreakCalculator {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let completionDays = Set(habit.completions.map { calendar.startOfDay(for: $0.date) })

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while completionDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }

    static func completedToday(for habit: Habit) -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completions.contains { Calendar.current.startOfDay(for: $0.date) == today }
    }
}
```

