    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        notes: String = "",
        createdAt: Date = .now,
        targetPerDay: Int = 1,
        isArchived: Bool = false,
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.notes = notes
        self.createdAt = createdAt
        self.targetPerDay = targetPerDay
        self.isArchived = isArchived
        self.completions = completions
    }

    var completedTodayCount: Int {
        let calendar = Calendar.current
        return completions.filter { calendar.isDate($0.completedAt, inSameDayAs: Date()) }.count
    }

    var isCompletedToday: Bool {
        completedTodayCount >= targetPerDay
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let groupedDates = Set(completions.map { calendar.startOfDay(for: $0.completedAt) })

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while groupedDates.contains(day) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }
}
