## 13) Optional improvement: streak logic for targetPerDay

If you want streaks to respect `targetPerDay`, replace `currentStreak` with:

```swift
var currentStreak: Int {
    let calendar = Calendar.current
    let grouped = Dictionary(grouping: completions) { calendar.startOfDay(for: $0.completedAt) }

    var streak = 0
    var day = calendar.startOfDay(for: Date())

    while true {
        let count = grouped[day]?.count ?? 0
        if count >= targetPerDay {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        } else {
            break
        }
    }

    return streak
}
```

