## 5) Store / helper logic

### `ViewModels/HabitStore.swift`
```swift
import Foundation
import SwiftData

@MainActor
final class HabitStore: ObservableObject {
    func toggleCompletion(for habit: Habit, in context: ModelContext) {
        let today = Date().startOfDay

        if let existing = habit.completions.first(where: { $0.date.isSameDay(as: today) }) {
            context.delete(existing)
        } else {
            let completion = HabitCompletion(date: today, habit: habit)
            context.insert(completion)
            habit.completions.append(completion)
        }

        try? context.save()
    }

    func isCompletedToday(_ habit: Habit) -> Bool {
        let today = Date().startOfDay
        return habit.completions.contains { $0.date.isSameDay(as: today) }
    }

    func streak(for habit: Habit) -> Int {
        let sortedDates = habit.completions.map { $0.date.startOfDay }.sorted(by: >)
        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var current = first

        for date in sortedDates.dropFirst() {
            guard let expected = Calendar.current.date(byAdding: .day, value: -1, to: current) else { break }
            if date == expected {
                streak += 1
                current = date
            } else if date < expected {
                break
            }
        }

        return streak
    }

    func completionCountThisWeek(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let now = Date()

        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: now) else { return 0 }

        return habit.completions.filter {
            weekInterval.contains($0.date)
        }.count
    }
}
```

