# 2) Data model

## `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var isArchived: Bool

    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#007AFF",
        createdAt: Date = .now,
        isArchived: Bool = false,
        completionDates: [Date] = []
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completionDates = completionDates
    }

    var currentStreak: Int {
        let sorted = completionDates.map { $0.startOfDay }.sorted(by: >)
        guard let first = sorted.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sorted.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               date == expected {
                streak += 1
                currentDate = date
            } else if date == currentDate {
                continue
            } else {
                break
            }
        }

        return streak
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    func toggleCompletionForToday() {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(.now)
        }
    }
}
```

