# 2) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var isActive: Bool
    var createdAt: Date
    var lastCompletedAt: Date?
    var currentStreak: Int
    var bestStreak: Int
    var totalCompletions: Int
    var targetPerWeek: Int

    init(
        name: String,
        habitDescription: String = "",
        isActive: Bool = true,
        createdAt: Date = Date(),
        lastCompletedAt: Date? = nil,
        currentStreak: Int = 0,
        bestStreak: Int = 0,
        totalCompletions: Int = 0,
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.isActive = isActive
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.currentStreak = currentStreak
        self.bestStreak = bestStreak
        self.totalCompletions = totalCompletions
        self.targetPerWeek = targetPerWeek
    }

    var isCompletedToday: Bool {
        guard let lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }

    func markCompleted() {
        let now = Date()

        if let lastCompletedAt {
            let calendar = Calendar.current
            let yesterday = calendar.date(byAdding: .day, value: -1, to: Date())!
            if calendar.isDate(lastCompletedAt, inSameDayAs: yesterday) {
                currentStreak += 1
            } else if !calendar.isDateInToday(lastCompletedAt) {
                currentStreak = 1
            }
        } else {
            currentStreak = 1
        }

        bestStreak = max(bestStreak, currentStreak)
        lastCompletedAt = now
        totalCompletions += 1
    }

    func resetCompletionForToday() {
        guard let lastCompletedAt else { return }
        if Calendar.current.isDateInToday(lastCompletedAt) {
            totalCompletions = max(0, totalCompletions - 1)
            self.lastCompletedAt = nil
            currentStreak = 0
        }
    }
}
```

