### `HabitStore.swift`
```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "habits_storage_key"

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        habits.append(Habit(name: trimmed))
    }

    func toggleCompletion(for habit: Habit) {
        let today = Self.todayString()
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        if habits[index].completions.contains(today) {
            habits[index].completions.removeAll { $0 == today }
        } else {
            habits[index].completions.append(today)
        }
    }

    func isCompletedToday(_ habit: Habit) -> Bool {
        habit.completions.contains(Self.todayString())
    }

    private func saveHabits() {
        do {
