### `HabitListView.swift`
```swift
import SwiftUI
import SwiftData

struct HabitListView: View {
    @Environment(\.modelContext) private var modelContext
    @Query(sort: \Habit.createdAt, order: .reverse) private var habits: [Habit]

    @State private var showingAddHabit = false

    var body: some View {
        NavigationStack {
            List {
                ForEach(habits) { habit in
                    HStack {
                        VStack(alignment: .leading, spacing: 4) {
                            Text(habit.name)
                                .font(.headline)

                            Text("Streak: \(habit.streak)")
                                .font(.subheadline)
                                .foregroundStyle(.secondary)
                        }

                        Spacer()

                        Button {
                            completeHabit(habit)
                        } label: {
                            Image(systemName: isCompletedToday(habit) ? "checkmark.circle.fill" : "circle")
                                .font(.title2)
                                .foregroundStyle(isCompletedToday(habit) ? .green : .gray)
                        }
                        .buttonStyle(.plain)
                    }
                    .padding(.vertical, 4)
                }
                .onDelete(perform: deleteHabits)
            }
            .navigationTitle("Habits")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        showingAddHabit = true
                    } label: {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView()
            }
        }
    }

    private func completeHabit(_ habit: Habit) {
        let today = Calendar.current.startOfDay(for: .now)

        if let lastCompletedAt = habit.lastCompletedAt {
            let lastDay = Calendar.current.startOfDay(for: lastCompletedAt)
            if lastDay == today {
                return // already completed today
            }

            let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: today)!
            if lastDay == yesterday {
                habit.streak += 1
            } else {
                habit.streak = 1
            }
        } else {
            habit.streak = 1
        }

        habit.lastCompletedAt = .now
    }

    private func isCompletedToday(_ habit: Habit) -> Bool {
        guard let lastCompletedAt = habit.lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }

    private func deleteHabits(at offsets: IndexSet) {
        for index in offsets {
            modelContext.delete(habits[index])
        }
    }
}
