```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, createdAt: Date = .now, completedDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDate($0, inSameDayAs: .now) }
    }

    func markCompletedToday() {
        guard !isCompletedToday() else { return }
        completedDates.append(.now)
    }

    var totalCompletions: Int {
        completedDates.count
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        var streak = 0
        var expectedDate = calendar.startOfDay(for: .now)

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)

            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previousDay
            } else if day < expectedDate {
                continue
            } else {
                break
            }
        }

        return streak
    }
}
