```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, createdAt: Date = .now, completedDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: .now)
        return completedDates.contains { Calendar.current.startOfDay(for: $0) == today }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDays = Set(completedDates.map { calendar.startOfDay(for: $0) })
            .sorted(by: >)

        guard let first = sortedDays.first else { return 0 }

        var currentDay = first
        var count = 1

        for day in sortedDays.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDay),
               calendar.isDate(day, inSameDayAs: expected) {
                count += 1
                currentDay = day
            } else {
                break
            }
        }

        return count
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: .now)

        if let index = completedDates.firstIndex(where: { Calendar.current.startOfDay(for: $0) == today }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
