import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completions: [Date]

    init(id: UUID = UUID(), name: String, completions: [Date] = []) {
        self.id = id
        self.name = name
        self.completions = completions
    }

    func completed(on date: Date) -> Bool {
        Calendar.current.isDate(completions.last, inSameDayAs: date)
    }

    var streak: Int {
        let calendar = Calendar.current
        let sorted = completions.sorted(by: >)
        var count = 0
        var currentDate = Date()

        for completion in sorted {
            if calendar.isDate(completion, inSameDayAs: currentDate) {
                count += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else {
                break
            }
        }
        return count
    }
}
