import Foundation
import SwiftUI

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let saveKey = "saved_habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        guard !name.trimmingCharacters(in: .whitespaces).isEmpty else { return }
        habits.append(Habit(name: name))
    }

    func toggleCompletedToday(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let calendar = Calendar.current
        if let existingIndex = habits[index].completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            habits[index].completedDates.remove(at: existingIndex)
        } else {
            habits[index].completedDates.append(Date())
        }
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: saveKey),
              let decoded = try? JSONDecoder().decode([Habit].self, from: data) else {
            return
        }
        habits = decoded
    }
}
