import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var streak: Int
    var lastCompletedDate: Date?

    init(id: UUID = UUID(), name: String, streak: Int = 0, lastCompletedDate: Date? = nil) {
        self.id = id
        self.name = name
        self.streak = streak
        self.lastCompletedDate = lastCompletedDate
    }

    mutating func markCompleted() {
        let today = Calendar.current.startOfDay(for: Date())
        let lastDate = lastCompletedDate.map { Calendar.current.startOfDay(for: $0) }

        if lastDate != today {
            streak += 1
            lastCompletedDate = Date()
        }
    }

    var isCompletedToday: Bool {
        guard let lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastCompletedDate)
    }
}
