import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completions: [Date]

    init(name: String, createdAt: Date = .now, completions: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completions = completions
    }

    func completedToday() -> Bool {
        let calendar = Calendar.current
        return completions.contains { calendar.isDate($0, inSameDayAs: .now) }
    }

    func markCompletedToday() {
        guard !completedToday() else { return }
        completions.append(.now)
    }

    var completionCount: Int {
        completions.count
    }
}
