## 5) Repository

### `BankRepository.kt`
```kotlin
class BankRepository(
    private val api: BankApiService,
    private val tokenStorage: TokenStorage
) {
    suspend fun login(username: String, password: String): Boolean {
        val response = api.login(AuthRequest(username, password))
        tokenStorage.saveAccessToken(response.accessToken)
        tokenStorage.saveRefreshToken(response.refreshToken)
        return true
    }

    suspend fun getAccounts(): List<Account> {
        val token = tokenStorage.getAccessToken() ?: return emptyList()
        return api.getAccounts("Bearer $token")
    }

    suspend fun getTransactions(): List<Transaction> {
        val token = tokenStorage.getAccessToken() ?: return emptyList()
        return api.getTransactions("Bearer $token")
    }

    fun logout() {
        tokenStorage.clear()
    }

    fun isLoggedIn(): Boolean = !tokenStorage.getAccessToken().isNullOrBlank()
}
