## 8) Navigation / MainActivity

### `MainActivity.kt`
```kotlin
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.runtime.*
import androidx.lifecycle.viewmodel.compose.viewModel

class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        val tokenStorage = TokenStorage(this)
        val repository = BankRepository(NetworkModule.api, tokenStorage)

        setContent {
            val authViewModel: AuthViewModel = viewModel(factory = SimpleViewModelFactory { AuthViewModel(repository) })
            val dashboardViewModel: DashboardViewModel = viewModel(factory = SimpleViewModelFactory { DashboardViewModel(repository) })

            val authState by authViewModel.uiState.collectAsState()
            val dashboardState by dashboardViewModel.uiState.collectAsState()

            if (authState.loggedIn) {
                LaunchedEffect(Unit) {
                    dashboardViewModel.loadData()
                }

                DashboardScreen(
                    accounts = dashboardState.accounts,
                    transactions = dashboardState.transactions,
                    onLogout = { authViewModel.logout() }
                )
            } else {
                LoginScreen(
                    onLogin = { username, password ->
                        authViewModel.login(username, password)
                    }
                )
            }
        }
    }
}
```

