    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    fun transfer(fromAccountId: String, toAccountNumber: String, amount: Double) {
        viewModelScope.launch {
            _loading.value = true
            val ok = repository.transfer(fromAccountId, toAccountNumber, amount)
            _status.value = if (ok) "Transfer successful" else "Transfer failed"
            _loading.value = false
        }
    }
}
