## 5) Repository
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.api.BankingApi
import com.example.bankapp.data.api.LoginRequest
import com.example.bankapp.data.api.Account
import com.example.bankapp.data.security.SecureTokenStore

class BankingRepository(
    private val api: BankingApi,
    private val tokenStore: SecureTokenStore
) {
    suspend fun login(username: String, password: String): Result<String> {
        return runCatching {
            val response = api.login(LoginRequest(username, password))
            tokenStore.saveAccessToken(response.accessToken)
            response.userName
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return runCatching { api.getAccounts() }
    }

    fun logout() {
        tokenStore.clear()
    }
}
```

## 6) ViewModel
```kotlin
package com.example.bankapp.ui.screens

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.api.Account
import com.example.bankapp.data.repository.BankingRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class DashboardUiState(
    val loading: Boolean = false,
    val userName: String? = null,
    val accounts: List<Account> = emptyList(),
    val error: String? = null
)

class DashboardViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(DashboardUiState())
    val uiState: StateFlow<DashboardUiState> = _uiState.asStateFlow()

    fun login(username: String, password: String) {
        viewModelScope.launch {
            _uiState.value = DashboardUiState(loading = true)
            repository.login(username, password)
                .onSuccess { name ->
                    _uiState.value = DashboardUiState(userName = name)
                    loadAccounts()
                }
                .onFailure { e ->
                    _uiState.value = DashboardUiState(error = e.message ?: "Login failed")
                }
        }
    }

    fun loadAccounts() {
        viewModelScope.launch {
            repository.getAccounts()
                .onSuccess { accounts ->
                    _uiState.value = _uiState.value.copy(accounts = accounts)
                }
                .onFailure { e ->
                    _uiState.value = _uiState.value.copy(error = e.message ?: "Failed to load accounts")
                }
        }
    }

    fun logout() {
        repository.logout()
        _uiState.value = DashboardUiState()
    }
}
```

