### `data/repo/BankRepositoryImpl.kt`
```kotlin
package com.example.bankapp.data.repo

import com.example.bankapp.data.api.BankApi
import com.example.bankapp.data.model.AccountDto
import com.example.bankapp.data.model.TransactionDto
import com.example.bankapp.data.model.AuthRequest
import com.example.bankapp.data.secure.SecureTokenStore
import com.example.bankapp.domain.repo.BankRepository
import javax.inject.Inject

class BankRepositoryImpl @Inject constructor(
    private val api: BankApi,
    private val tokenStore: SecureTokenStore
) : BankRepository {

    override suspend fun login(email: String, password: String): Boolean {
        val response = api.login(AuthRequest(email, password))
        tokenStore.saveAccessToken(response.accessToken)
        tokenStore.saveRefreshToken(response.refreshToken)
        return true
    }

    override suspend fun getAccounts(): List<AccountDto> {
        return api.getAccounts()
    }

    override suspend fun getTransactions(accountId: String): List<TransactionDto> {
        return api.getTransactions(accountId)
    }
}
