package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import kotlinx.coroutines.delay
import java.util.UUID

class FakeBankRepository : BankRepository {

    private val accounts = listOf(
        Account(id = "1", name = "Checking", type = "Checking", balance = 2450.75),
        Account(id = "2", name = "Savings", type = "Savings", balance = 12000.00)
    )

    private val transactions = listOf(
        Transaction(
            id = UUID.randomUUID().toString(),
            accountId = "1",
            title = "Grocery Store",
            amount = -84.20,
            timestamp = System.currentTimeMillis() - 86_400_000,
            category = "Food"
        ),
        Transaction(
            id = UUID.randomUUID().toString(),
            accountId = "1",
            title = "Salary",
            amount = 3200.00,
            timestamp = System.currentTimeMillis() - 172_800_000,
            category = "Income"
        )
    )

    override suspend fun getAccounts(): List<Account> {
        delay(500)
        return accounts
    }

    override suspend fun getTransactions(accountId: String): List<Transaction> {
        delay(500)
        return transactions.filter { it.accountId == accountId }
    }

    override suspend fun transfer(fromAccountId: String, toAccountNumber: String, amount: Double): Boolean {
        delay(1000)
        return amount > 0 && toAccountNumber.isNotBlank() && fromAccountId.isNotBlank()
    }
}
