```kotlin
package com.example.bankapp.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.repository.BankRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

data class AccountsUiState(
    val isLoading: Boolean = false,
    val accounts: List<Account> = emptyList(),
    val error: String? = null
)

class AccountsViewModel(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(AccountsUiState(isLoading = true))
    val uiState: StateFlow<AccountsUiState> = _uiState

    init {
        loadAccounts()
    }

    fun loadAccounts() {
        viewModelScope.launch {
            _uiState.value = AccountsUiState(isLoading = true)
            try {
                val accounts = repository.getAccounts()
                _uiState.value = AccountsUiState(accounts = accounts)
            } catch (e: Exception) {
                _uiState.value = AccountsUiState(error = e.message ?: "Unknown error")
            }
        }
    }
}
```

### `TransferViewModel.kt`
```kotlin
package com.example.bankapp.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.repository.BankRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

data class TransferUiState(
    val isLoading: Boolean = false,
    val success: Boolean = false,
    val error: String? = null
)

class TransferViewModel(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState

    fun transfer(fromAccountId: String, toAccountNumber: String, amount: Double) {
        viewModelScope.launch {
            _uiState.value = TransferUiState(isLoading = true)
            try {
                val result = repository.transfer(fromAccountId, toAccountNumber, amount)
                _uiState.value = if (result) {
                    TransferUiState(success = true)
                } else {
                    TransferUiState(error = "Transfer failed")
                }
            } catch (e: Exception) {
                _uiState.value = TransferUiState(error = e.message ?: "Unknown error")
            }
        }
    }
}
