```kotlin
package com.example.bankapp.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.BankRepository
import com.example.bankapp.model.Account
import com.example.bankapp.model.Transaction
import com.example.bankapp.model.TransferRequest
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class BankViewModel @Inject constructor(
    private val repository: BankRepository
) : ViewModel() {

    private val _accounts = MutableStateFlow<List<Account>>(emptyList())
    val accounts: StateFlow<List<Account>> = _accounts.asStateFlow()

    private val _transactions = MutableStateFlow<List<Transaction>>(emptyList())
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    private val _loading = MutableStateFlow(false)
    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    fun login(username: String, password: String) {
        viewModelScope.launch {
            _loading.value = true
            _error.value = null
            try {
                repository.login(username, password)
                loadAccounts()
            } catch (e: Exception) {
                _error.value = "Login failed"
            } finally {
                _loading.value = false
            }
        }
    }

    fun loadAccounts() {
        viewModelScope.launch {
            try {
                _accounts.value = repository.getAccounts()
            } catch (e: Exception) {
                _error.value = "Failed to load accounts"
            }
        }
    }

    fun loadTransactions(accountId: String) {
        viewModelScope.launch {
            try {
                _transactions.value = repository.getTransactions(accountId)
            } catch (e: Exception) {
                _error.value = "Failed to load transactions"
            }
        }
    }

    fun transfer(fromAccountId: String, toAccountNumber: String, amount: Double, note: String?) {
        viewModelScope.launch {
            _loading.value = true
            try {
                repository.transfer(
                    TransferRequest(
                        fromAccountId = fromAccountId,
                        toAccountNumber = toAccountNumber,
                        amount = amount,
                        note = note
                    )
                )
                loadAccounts()
            } catch (e: Exception) {
                _error.value = "Transfer failed"
            } finally {
                _loading.value = false
            }
        }
    }

    fun logout() {
        repository.logout()
        _accounts.value = emptyList()
        _transactions.value = emptyList()
    }
}
