package com.example.bankapp.ui.transfer

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.BankRepository
import com.example.bankapp.models.TransferRequest
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class TransferUiState(
    val fromAccountId: String = "",
    val toAccountNumber: String = "",
    val amount: String = "",
    val note: String = "",
    val loading: Boolean = false,
    val successMessage: String? = null,
    val error: String? = null
)

@HiltViewModel
class TransferViewModel @Inject constructor(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState.asStateFlow()

    fun onFromAccountChange(value: String) {
        _uiState.value = _uiState.value.copy(fromAccountId = value)
    }

    fun onToAccountChange(value: String) {
        _uiState.value = _uiState.value.copy(toAccountNumber = value)
    }

    fun onAmountChange(value: String) {
        _uiState.value = _uiState.value.copy(amount = value)
    }

    fun onNoteChange(value: String) {
        _uiState.value = _uiState.value.copy(note = value)
    }

    fun submitTransfer() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(loading = true, error = null, successMessage = null)
            try {
                repository.transfer(
                    TransferRequest(
                        fromAccountId = _uiState.value.fromAccountId,
                        toAccountNumber = _uiState.value.toAccountNumber,
                        amount = _uiState.value.amount.toDoubleOrNull() ?: 0.0,
                        note = _uiState.value.note.ifBlank { null }
                    )
                )
                _uiState.value = _uiState.value.copy(
                    loading = false,
                    successMessage = "Transfer submitted successfully"
                )
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(loading = false, error = e.message)
            }
        }
    }
}
