### `repository/BankRepositoryImpl.kt`
```kotlin
package com.example.bankapp.repository

import com.example.bankapp.db.AccountEntity
import com.example.bankapp.db.BankDao
import com.example.bankapp.db.TransactionEntity
import com.example.bankapp.model.Account
import com.example.bankapp.model.AuthRequest
import com.example.bankapp.model.AuthResponse
import com.example.bankapp.model.Transaction
import com.example.bankapp.network.BankApiService
import com.example.bankapp.security.TokenStorage
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import javax.inject.Inject

class BankRepositoryImpl @Inject constructor(
    private val api: BankApiService,
    private val dao: BankDao,
    private val tokenStorage: TokenStorage
) : BankRepository {

    override suspend fun login(username: String, password: String): Result<AuthResponse> =
        withContext(Dispatchers.IO) {
            runCatching {
                val response = api.login(AuthRequest(username, password))
                tokenStorage.saveAccessToken(response.accessToken)
                response
            }
        }

    override suspend fun getAccounts(): Result<List<Account>> =
        withContext(Dispatchers.IO) {
            runCatching {
                val remote = api.getAccounts()
                dao.saveAccounts(remote.map {
                    AccountEntity(it.id, it.name, it.numberMasked, it.balance, it.currency)
                })
                remote
            }.recoverCatching {
                dao.getAccounts().map {
                    Account(it.id, it.name, it.numberMasked, it.balance, it.currency)
                }
            }
        }

    override suspend fun getTransactions(): Result<List<Transaction>> =
        withContext(Dispatchers.IO) {
            runCatching {
                val remote = api.getTransactions()
                dao.saveTransactions(remote.map {
                    TransactionEntity(it.id, it.accountId, it.title, it.amount, it.currency, it.timestamp, it.type)
                })
                remote
            }.recoverCatching {
                dao.getTransactions().map {
                    Transaction(it.id, it.accountId, it.title, it.amount, it.currency, it.timestamp, it.type)
                }
            }
        }
}
