    fun submit() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, message = null)
            val success = transferUseCase(
                _uiState.value.fromAccountId,
                _uiState.value.toAccount,
                _uiState.value.amount.toDoubleOrNull() ?: 0.0
            )
            _uiState.value = _uiState.value.copy(
                isLoading = false,
                message = if (success) "Transfer successful" else "Transfer failed"
            )
        }
    }
}
