    val state by viewModel.accountsState.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.loadAccounts()
    }

    Column(Modifier.fillMaxSize().padding(16.dp)) {
        Text("Dashboard", style = MaterialTheme.typography.headlineMedium)
