)

@Composable
fun BankApp() {
    var balance by remember { mutableStateOf(1250.75) }
    val transactions = remember {
        mutableStateListOf(
            Transaction("Salary", "2026-09-01", 2000.00),
            Transaction("Groceries", "2026-09-03", -84.32),
            Transaction("Utilities", "2026-09-05", -120.50)
        )
    }

    var recipient by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }
    var status by remember { mutableStateOf("Ready") }

    Scaffold(
        topBar = {
            TopAppBar(title = { Text("MiniBank Demo") })
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .padding(16.dp)
                .fillMaxSize(),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("Current Balance", style = MaterialTheme.typography.titleMedium)
                    Text(
                        formatCurrency(balance),
                        style = MaterialTheme.typography.headlineMedium,
                        fontWeight = FontWeight.Bold
                    )
                }
            }

            Card {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("Transfer Money", style = MaterialTheme.typography.titleMedium)
                    Spacer(Modifier.height(12.dp))

                    OutlinedTextField(
                        value = recipient,
                        onValueChange = { recipient = it },
                        label = { Text("Recipient") },
                        modifier = Modifier.fillMaxWidth()
                    )

                    Spacer(Modifier.height(8.dp))

                    OutlinedTextField(
                        value = amountText,
                        onValueChange = { amountText = it },
                        label = { Text("Amount") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                        modifier = Modifier.fillMaxWidth()
                    )

                    Spacer(Modifier.height(12.dp))

                    Button(
                        onClick = {
                            val amount = amountText.toDoubleOrNull()
                            if (recipient.isBlank()) {
                                status = "Enter a recipient"
                            } else if (amount == null || amount <= 0) {
                                status = "Enter a valid amount"
                            } else if (amount > balance) {
                                status = "Insufficient funds"
                            } else {
                                balance -= amount
                                transactions.add(
                                    0,
                                    Transaction("Transfer to $recipient", "2026-09-16", -amount)
                                )
                                status = "Transfer completed (demo only)"
                                recipient = ""
                                amountText = ""
                            }
                        },
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text("Send")
                    }

                    Spacer(Modifier.height(8.dp))
                    Text(status, style = MaterialTheme.typography.bodyMedium)
                }
            }

            Card(modifier = Modifier.fillMaxHeight()) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("Recent Transactions", style = MaterialTheme.typography.titleMedium)
                    Spacer(Modifier.height(8.dp))

                    LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        items(transactions) { tx ->
                            TransactionRow(tx)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun TransactionRow(tx: Transaction) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(tx.title, fontWeight = FontWeight.Medium)
            Text(tx.date, style = MaterialTheme.typography.bodySmall)
        }
        Text(
            formatCurrency(tx.amount),
            color = if (tx.amount < 0) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
        )
    }
}

fun formatCurrency(amount: Double): String {
    val formatter = NumberFormat.getCurrencyInstance(Locale.US)
    return formatter.format(amount)
}
