## 3) Mock repository

### `BankRepository.kt`
```kotlin
package com.example.minibank

object BankRepository {
    private var currentUser: User? = null

    private val accounts = mutableListOf(
        Account(id = "1", type = "Checking", balance = 2450.75),
        Account(id = "2", type = "Savings", balance = 10250.00)
    )

    private val transactions = mutableListOf(
        Transaction(id = "t1", title = "Salary", amount = 3200.00, date = "2026-09-01"),
        Transaction(id = "t2", title = "Rent", amount = -1200.00, date = "2026-09-03"),
        Transaction(id = "t3", title = "Coffee", amount = -4.75, date = "2026-09-04")
    )

    fun login(username: String, password: String): User? {
        // Demo-only auth logic
        return if (username.isNotBlank() && password.length >= 4) {
            currentUser = User(username, "Demo User")
            currentUser
        } else null
    }

    fun logout() {
        currentUser = null
    }

    fun getCurrentUser(): User? = currentUser

    fun getAccounts(): List<Account> = accounts.toList()

    fun getTransactions(): List<Transaction> = transactions.toList()

    fun transfer(amount: Double, toAccount: String): Boolean {
        if (amount <= 0) return false
        val checkingIndex = accounts.indexOfFirst { it.type == "Checking" }
        if (checkingIndex == -1) return false

        val checking = accounts[checkingIndex]
        if (checking.balance < amount) return false

        accounts[checkingIndex] = checking.copy(balance = checking.balance - amount)
        transactions.add(
            0,
            Transaction(
                id = "t${System.currentTimeMillis()}",
                title = "Transfer to $toAccount",
                amount = -amount,
                date = "2026-09-16"
            )
        )
        return true
    }
}
```

