## 4) ViewModel

### `BankViewModel.kt`
```kotlin
package com.example.minibank

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

class BankViewModel : ViewModel() {
    var user by mutableStateOf(BankRepository.getCurrentUser())
        private set

    var accounts by mutableStateOf(BankRepository.getAccounts())
        private set

    var transactions by mutableStateOf(BankRepository.getTransactions())
        private set

    var loginError by mutableStateOf<String?>(null)
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    fun login(username: String, password: String) {
        val result = BankRepository.login(username, password)
        if (result != null) {
            user = result
            accounts = BankRepository.getAccounts()
            transactions = BankRepository.getTransactions()
            loginError = null
        } else {
            loginError = "Invalid credentials"
        }
    }

    fun logout() {
        BankRepository.logout()
        user = null
    }

    fun makeTransfer(amount: Double, toAccount: String) {
        val success = BankRepository.transfer(amount, toAccount)
        if (success) {
            accounts = BankRepository.getAccounts()
            transactions = BankRepository.getTransactions()
            transferMessage = "Transfer successful"
        } else {
            transferMessage = "Transfer failed"
        }
    }

    fun clearMessages() {
        loginError = null
        transferMessage = null
    }
}
