        private set

    var currentUser by mutableStateOf<User?>(null)
        private set

    val account = Account(
        accountNumber = "**** 4821",
        balance = 12540.75
    )

    val transactions = listOf(
        Transaction("1", "Salary Deposit", 3200.00, "2026-09-01"),
