        Transaction("4", "Coffee Shop", -5.75, "2026-09-06")
    )

    fun login(username: String, password: String): Boolean {
        // Mock authentication only
        return if (username.isNotBlank() && password.isNotBlank()) {
            currentUser = User(username = username, displayName = username.replaceFirstChar { it.uppercase() })
            isLoggedIn = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn = false
        currentUser = null
