data class Transaction(
    val title: String,
    val amount: Double,
    val type: String
)

@Composable
fun MiniBankApp() {
    var loggedIn by remember { mutableStateOf(false) }
    var balance by remember { mutableStateOf(1520.75) }
    var transactions by remember {
        mutableStateOf(
            listOf(
                Transaction("Salary", 2500.00, "credit"),
                Transaction("Rent", -900.00, "debit"),
                Transaction("Groceries", -79.25, "debit")
            )
        )
    }

    if (!loggedIn) {
        LoginScreen(onLogin = { loggedIn = true })
    } else {
        DashboardScreen(
            balance = balance,
            transactions = transactions,
            onTransfer = { recipient, amount ->
                balance -= amount
                transactions = listOf(
                    Transaction("Transfer to $recipient", -amount, "debit")
                ) + transactions
            },
            onLogout = { loggedIn = false }
        )
    }
}

