import androidx.compose.ui.unit.dp
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.foundation.text.KeyboardOptions
import java.text.NumberFormat
import java.util.Locale

data class Transaction(
    val title: String,
    val amount: Double,
    val type: String
)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                BankingApp()
            }
        }
    }
}

@Composable
fun BankingApp() {
    var balance by remember { mutableStateOf(1250.00) }
    var amountText by remember { mutableStateOf("") }
    val transactions = remember {
        mutableStateListOf(
            Transaction("Salary", 2000.00, "credit"),
            Transaction("Groceries", -120.50, "debit"),
            Transaction("Electric Bill", -89.99, "debit")
        )
    }

    val formatter = remember {
        NumberFormat.getCurrencyInstance(Locale.US)
    }

    fun addTransaction(title: String, amount: Double, type: String) {
        transactions.add(0, Transaction(title, amount, type))
    }

    Scaffold(
        topBar = {
            TopAppBar(title = { Text("MiniBank") })
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize()
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("Available Balance", style = MaterialTheme.typography.titleMedium)
                    Text(
                        text = formatter.format(balance),
                        style = MaterialTheme.typography.headlineMedium
                    )
                }
            }

            OutlinedTextField(
                value = amountText,
                onValueChange = { amountText = it },
                label = { Text("Amount") },
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Decimal,
                    imeAction = ImeAction.Done
                ),
                modifier = Modifier.fillMaxWidth()
            )

            Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Button(
                    onClick = {
                        val amount = amountText.toDoubleOrNull()
                        if (amount != null && amount > 0) {
                            balance += amount
                            addTransaction("Deposit", amount, "credit")
                            amountText = ""
                        }
                    },
                    modifier = Modifier.weight(1f)
                ) {
                    Text("Deposit")
                }

                Button(
                    onClick = {
                        val amount = amountText.toDoubleOrNull()
                        if (amount != null && amount > 0 && balance >= amount) {
                            balance -= amount
                            addTransaction("Withdrawal", -amount, "debit")
                            amountText = ""
                        }
                    },
                    modifier = Modifier.weight(1f)
                ) {
                    Text("Withdraw")
                }
            }

            Text("Recent Transactions", style = MaterialTheme.typography.titleMedium)

            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(transactions) { tx ->
                    Card {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column {
                                Text(tx.title, style = MaterialTheme.typography.bodyLarge)
                                Text(
                                    if (tx.type == "credit") "Credit" else "Debit",
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            }
                            Text(
                                text = formatter.format(tx.amount),
                                color = if (tx.amount >= 0) MaterialTheme.colorScheme.primary
                                else MaterialTheme.colorScheme.error
                            )
                        }
                    }
                }
            }
        }
    }
}
