## 4) `BankViewModel.kt`

```kotlin
package com.example.minibank.ui

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

data class Transaction(
    val title: String,
    val amount: Double,
    val type: String
)

data class BankUiState(
    val loggedIn: Boolean = false,
    val username: String = "",
    val balance: Double = 1540.75,
    val transactions: List<Transaction> = listOf(
        Transaction("Salary", 2500.00, "credit"),
        Transaction("Rent", -900.00, "debit"),
        Transaction("Coffee Shop", -6.50, "debit")
    ),
    val transferStatus: String = ""
)

class BankViewModel : ViewModel() {
    var uiState by mutableStateOf(BankUiState())
        private set

    fun login(username: String, password: String) {
        if (username.isNotBlank() && password.isNotBlank()) {
            uiState = uiState.copy(loggedIn = true, username = username, transferStatus = "")
        } else {
            uiState = uiState.copy(transferStatus = "Enter username and password")
        }
    }

    fun logout() {
        uiState = BankUiState()
    }

    fun transfer(recipient: String, amountText: String) {
        val amount = amountText.toDoubleOrNull()
        if (recipient.isBlank() || amount == null || amount <= 0) {
            uiState = uiState.copy(transferStatus = "Invalid transfer details")
            return
        }

        if (amount > uiState.balance) {
            uiState = uiState.copy(transferStatus = "Insufficient balance")
            return
        }

        val newTransaction = Transaction("Transfer to $recipient", -amount, "debit")
        uiState = uiState.copy(
            balance = uiState.balance - amount,
            transactions = listOf(newTransaction) + uiState.transactions,
            transferStatus = "Transfer successful"
        )
    }
}
