@Composable
fun DashboardScreen(
    balance: Double,
    transactions: List<Transaction>,
    onTransfer: (String, Double) -> Unit,
    onLogout: () -> Unit
) {
    var recipient by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("My Account") },
                actions = {
                    TextButton(onClick = onLogout) {
                        Text("Logout")
