package com.example.mbank

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

data class Transaction(
    val description: String,
    val date: String,
    val amount: Double
)

class BankingViewModel : ViewModel() {
    var loggedIn by mutableStateOf(false)
        private set

    var errorMessage by mutableStateOf<String?>(null)
        private set

    var balance by mutableStateOf(1250.75)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction("Salary", "2026-09-01", 2500.00),
            Transaction("Rent", "2026-09-03", -900.00),
            Transaction("Groceries", "2026-09-05", -120.25)
        )
    )
        private set

    fun login(username: String, password: String) {
        if (username == "user" && password == "1234") {
            loggedIn = true
            errorMessage = null
        } else {
            errorMessage = "Invalid credentials"
        }
    }

    fun logout() {
        loggedIn = false
    }

    fun transfer(recipient: String, amount: Double) {
        if (amount <= 0 || amount > balance) return
        balance -= amount
        transactions = listOf(
            Transaction("Transfer to $recipient", "2026-09-16", -amount)
        ) + transactions
    }
}
