                            onClick = {
                                val amount = transferAmount.toDoubleOrNull()
                                if (amount != null && amount > 0 && transferRecipient.isNotBlank() && balance >= amount) {
                                    balance -= amount
                                    transactions.add(
                                        0,
                                        Transaction("Transfer to $transferRecipient", "2026-09-16", -amount)
                                    )
                                    statusMessage = "Transfer completed in demo mode."
                                    transferRecipient = ""
                                    transferAmount = ""
                                } else {
                                    statusMessage = "Invalid transfer."
                                }
                            },
                            modifier = Modifier.fillMaxWidth()
