# Local storage layer

This example uses a simple repository abstraction. In production, use:
- **SQLite** for structured offline data,
- **MMKV** or **AsyncStorage** for small metadata,
- or **Realm** if you want a richer local DB.

## `storage.ts`

```ts
import AsyncStorage from "@react-native-async-storage/async-storage";

const SURVEYS_KEY = "surveys";
const OUTBOX_KEY = "outbox";
const LAST_SYNC_KEY = "lastSyncAt";

export async function getSurveys(): Promise<any[]> {
  const raw = await AsyncStorage.getItem(SURVEYS_KEY);
  return raw ? JSON.parse(raw) : [];
}

export async function saveSurveys(surveys: any[]): Promise<void> {
  await AsyncStorage.setItem(SURVEYS_KEY, JSON.stringify(surveys));
}

export async function getOutbox(): Promise<any[]> {
  const raw = await AsyncStorage.getItem(OUTBOX_KEY);
  return raw ? JSON.parse(raw) : [];
}

export async function saveOutbox(outbox: any[]): Promise<void> {
  await AsyncStorage.setItem(OUTBOX_KEY, JSON.stringify(outbox));
}

export async function getLastSyncAt(): Promise<string | null> {
  return await AsyncStorage.getItem(LAST_SYNC_KEY);
}

export async function setLastSyncAt(value: string): Promise<void> {
  await AsyncStorage.setItem(LAST_SYNC_KEY, value);
}
```

