# Survey repository

This handles local CRUD and outbox creation.

## `surveyRepository.ts`

```ts
import { v4 as uuidv4 } from "uuid";
import { getSurveys, saveSurveys, getOutbox, saveOutbox } from "./storage";

export type Survey = {
  id: string;
  name: string;
  locationLat: number;
  locationLng: number;
  notes?: string;
  status: "draft" | "submitted" | "synced";
  updatedAt: string;
  version: number;
  deleted?: boolean;
};

export async function listSurveys(): Promise<Survey[]> {
  const surveys = await getSurveys();
  return surveys.filter((s) => !s.deleted);
}

export async function getSurveyById(id: string): Promise<Survey | undefined> {
  const surveys = await getSurveys();
  return surveys.find((s) => s.id === id && !s.deleted);
}

export async function createSurvey(input: Omit<Survey, "id" | "updatedAt" | "version">) {
  const surveys = await getSurveys();
  const outbox = await getOutbox();
  const now = new Date().toISOString();

  const survey: Survey = {
    id: uuidv4(),
    ...input,
    updatedAt: now,
    version: 1,
  };

  surveys.push(survey);
  outbox.push({
    id: uuidv4(),
    entityType: "survey",
    entityId: survey.id,
    operation: "create",
    payload: survey,
    createdAt: now,
    retries: 0,
  });

  await saveSurveys(surveys);
  await saveOutbox(outbox);

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Survey>) {
  const surveys = await getSurveys();
  const outbox = await getOutbox();
  const now = new Date().toISOString();

  const idx = surveys.findIndex((s) => s.id === id);
  if (idx === -1) throw new Error("Survey not found");

  const updated: Survey = {
    ...surveys[idx],
    ...patch,
    updatedAt: now,
    version: surveys[idx].version + 1,
  };

  surveys[idx] = updated;

  outbox.push({
    id: uuidv4(),
    entityType: "survey",
    entityId: id,
    operation: "update",
    payload: patch,
    createdAt: now,
    retries: 0,
  });

  await saveSurveys(surveys);
  await saveOutbox(outbox);

  return updated;
}

export async function deleteSurvey(id: string) {
  const surveys = await getSurveys();
  const outbox = await getOutbox();
  const now = new Date().toISOString();

  const idx = surveys.findIndex((s) => s.id === id);
  if (idx === -1) throw new Error("Survey not found");

  surveys[idx] = {
    ...surveys[idx],
    deleted: true,
    updatedAt: now,
    version: surveys[idx].version + 1,
  };

  outbox.push({
    id: uuidv4(),
    entityType: "survey",
    entityId: id,
    operation: "delete",
    payload: { id },
    createdAt: now,
    retries: 0,
  });

  await saveSurveys(surveys);
  await saveOutbox(outbox);
}
```

