# Sync service

This pushes local outbox items to the server and pulls remote updates.

## `syncService.ts`

```ts
import { getOutbox, saveOutbox, getSurveys, saveSurveys, getLastSyncAt, setLastSyncAt } from "./storage";

const API_BASE = "https://your-api.example.com";

async function apiFetch(path: string, options: RequestInit = {}) {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
    ...options,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`API error ${res.status}: ${text}`);
  }

  return res.json();
}

export async function syncNow() {
  const outbox = await getOutbox();
  if (outbox.length === 0) {
    await pullRemoteChanges();
    return;
  }

  const remaining: any[] = [];

  for (const item of outbox) {
    try {
      await pushOutboxItem(item);
    } catch (err) {
      item.retries = (item.retries || 0) + 1;
      remaining.push(item);
    }
  }

  await saveOutbox(remaining);
  await pullRemoteChanges();
}

async function pushOutboxItem(item: any) {
  switch (item.operation) {
    case "create":
      await apiFetch("/surveys", {
        method: "POST",
        body: JSON.stringify(item.payload),
      });
      break;

    case "update":
      await apiFetch(`/surveys/${item.entityId}`, {
        method: "PATCH",
        body: JSON.stringify(item.payload),
      });
      break;

    case "delete":
      await apiFetch(`/surveys/${item.entityId}`, {
        method: "DELETE",
      });
      break;
  }
}

async function pullRemoteChanges() {
  const lastSyncAt = await getLastSyncAt();
  const result = await apiFetch(`/surveys/changes?since=${encodeURIComponent(lastSyncAt || "")}`);

  // Expected response: { surveys: Survey[], serverTime: string }
  const { surveys, serverTime } = result;

  const local = await getSurveys();
  const merged = mergeLocalAndRemote(local, surveys);

  await saveSurveys(merged);
  await setLastSyncAt(serverTime || new Date().toISOString());
}

function mergeLocalAndRemote(local: any[], remote: any[]) {
  const map = new Map<string, any>();

  for (const item of local) map.set(item.id, item);

  for (const serverItem of remote) {
    const existing = map.get(serverItem.id);

    if (!existing) {
      map.set(serverItem.id, serverItem);
      continue;
    }

    // Simple last-write-wins conflict resolution
    const localTime = new Date(existing.updatedAt).getTime();
    const remoteTime = new Date(serverItem.updatedAt).getTime();

    if (remoteTime > localTime) {
      map.set(serverItem.id, serverItem);
    }
  }

  return Array.from(map.values());
}
```

