# Auto-sync on reconnect

## `useSyncOnReconnect.ts`

```ts
import { useEffect } from "react";
import { subscribeToConnectivity } from "./network";
import { syncNow } from "./syncService";

export function useSyncOnReconnect() {
  useEffect(() => {
    let syncing = false;

    const unsubscribe = subscribeToConnectivity(async (online) => {
      if (online && !syncing) {
        syncing = true;
        try {
          await syncNow();
        } catch (err) {
          console.warn("Sync failed:", err);
        } finally {
          syncing = false;
        }
      }
    });

    return () => unsubscribe();
  }, []);
}
```

