# Server API example

Your backend should support:

- `POST /surveys`
- `PATCH /surveys/:id`
- `DELETE /surveys/:id`
- `GET /surveys/changes?since=timestamp`

## Example Express route sketch

```ts
import express from "express";
const app = express();
app.use(express.json());

let surveys: any[] = [];

app.post("/surveys", (req, res) => {
  const survey = { ...req.body, version: 1, updatedAt: new Date().toISOString() };
  surveys.push(survey);
  res.json(survey);
});

app.patch("/surveys/:id", (req, res) => {
  const idx = surveys.findIndex((s) => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Not found" });

  surveys[idx] = {
    ...surveys[idx],
    ...req.body,
    version: (surveys[idx].version || 1) + 1,
    updatedAt: new Date().toISOString(),
  };

  res.json(surveys[idx]);
});

app.delete("/surveys/:id", (req, res) => {
  const idx = surveys.findIndex((s) => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Not found" });

  surveys[idx].deleted = true;
  surveys[idx].updatedAt = new Date().toISOString();
  res.json({ ok: true });
});

app.get("/surveys/changes", (req, res) => {
  const since = req.query.since ? new Date(String(req.query.since)).getTime() : 0;
  const changed = surveys.filter((s) => new Date(s.updatedAt).getTime() > since);
  res.json({
    surveys: changed,
    serverTime: new Date().toISOString(),
  });
});

app.listen(3000, () => console.log("Server running on 3000"));
```

