## 3) `src/db.ts`

```ts
import * as SQLite from 'expo-sqlite';
import { SurveyRecord } from './types';

const db = SQLite.openDatabase('survey.db');

export const initDb = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(
      tx => {
        tx.executeSql(`
          CREATE TABLE IF NOT EXISTS survey_records (
            id TEXT PRIMARY KEY NOT NULL,
            title TEXT NOT NULL,
            location TEXT NOT NULL,
            notes TEXT,
            latitude REAL,
            longitude REAL,
            updatedAt TEXT NOT NULL,
            synced INTEGER NOT NULL DEFAULT 0
          );
        `);

        tx.executeSql(`
          CREATE TABLE IF NOT EXISTS sync_queue (
            id TEXT PRIMARY KEY NOT NULL,
            recordId TEXT NOT NULL,
            action TEXT NOT NULL,
            payload TEXT NOT NULL,
            createdAt TEXT NOT NULL
          );
        `);
      },
      error => reject(error),
      () => resolve()
    );
  });
};

export const getAllRecords = (): Promise<SurveyRecord[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM survey_records ORDER BY updatedAt DESC;',
        [],
        (_, result) => {
          resolve(result.rows._array as SurveyRecord[]);
        },
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const upsertLocalRecord = (record: SurveyRecord): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `
        INSERT OR REPLACE INTO survey_records
        (id, title, location, notes, latitude, longitude, updatedAt, synced)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?);
        `,
        [
          record.id,
          record.title,
          record.location,
          record.notes,
          record.latitude,
          record.longitude,
          record.updatedAt,
          record.synced,
        ],
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const deleteLocalRecord = (id: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'DELETE FROM survey_records WHERE id = ?;',
        [id],
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const addToSyncQueue = (
  recordId: string,
  action: 'create' | 'update' | 'delete',
  payload: object
): Promise<void> => {
  return new Promise((resolve, reject) => {
    const id = `${recordId}-${Date.now()}`;
    db.transaction(tx => {
      tx.executeSql(
        `
        INSERT INTO sync_queue (id, recordId, action, payload, createdAt)
        VALUES (?, ?, ?, ?, ?);
        `,
        [id, recordId, action, JSON.stringify(payload), new Date().toISOString()],
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getSyncQueue = (): Promise<any[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM sync_queue ORDER BY createdAt ASC;',
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const clearSyncQueueItem = (id: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'DELETE FROM sync_queue WHERE id = ?;',
        [id],
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};
```

