## 4) `src/sync.ts`

This example uses a placeholder API endpoint. Replace with your backend.

```ts
import NetInfo from '@react-native-community/netinfo';
import { getSyncQueue, clearSyncQueueItem, upsertLocalRecord } from './db';
import { SurveyRecord } from './types';

const API_URL = 'https://your-api.example.com';

export const isOnline = async (): Promise<boolean> => {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
};

export const syncPendingChanges = async (): Promise<void> => {
  const online = await isOnline();
  if (!online) return;

  const queue = await getSyncQueue();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      let response: Response;

      if (item.action === 'create') {
        response = await fetch(`${API_URL}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'update') {
        response = await fetch(`${API_URL}/surveys/${item.recordId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else {
        response = await fetch(`${API_URL}/surveys/${item.recordId}`, {
          method: 'DELETE',
        });
      }

      if (!response.ok) {
        throw new Error(`Sync failed for ${item.id}`);
      }

      await clearSyncQueueItem(item.id);

      if (item.action !== 'delete') {
        const serverRecord = (await response.json()) as SurveyRecord;
        await upsertLocalRecord({ ...serverRecord, synced: 1 });
      }
    } catch (error) {
      console.warn('Sync error:', error);
      // stop on first failure to preserve order
      break;
    }
  }
};
```

