## 7) `App.tsx`

```tsx
import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDb } from './src/db';
import { syncPendingChanges } from './src/sync';
import SurveyListScreen from './src/screens/SurveyListScreen';
import SurveyFormScreen from './src/screens/SurveyFormScreen';
import { SurveyRecord } from './src/types';

export default function App() {
  const [ready, setReady] = useState(false);
  const [screen, setScreen] = useState<'list' | 'form'>('list');
  const [editing, setEditing] = useState<SurveyRecord | undefined>(undefined);

  useEffect(() => {
    (async () => {
      await initDb();
      setReady(true);
    })();
  }, []);

  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected && state.isInternetReachable) {
        syncPendingChanges();
      }
    });

    return () => unsubscribe();
  }, []);

  if (!ready) {
    return (
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
        <ActivityIndicator />
      </View>
    );
  }

  if (screen === 'form') {
    return (
      <SurveyFormScreen
        record={editing}
        onSaved={() => {
          setEditing(undefined);
          setScreen('list');
        }}
      />
    );
  }

  return (
    <SurveyListScreen
      onCreate={() => {
        setEditing(undefined);
        setScreen('form');
      }}
      onEdit={(record) => {
        setEditing(record);
        setScreen('form');
      }}
      onSync={() => syncPendingChanges()}
    />
  );
}
