## Local repository

### `surveyRepository.ts`
```ts
import { dbPromise } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  siteId: string;
  title: string;
  notes?: string;
  status: 'draft' | 'submitted' | 'approved';
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
};

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const rows = [];
  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }
  return rows as Survey[];
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
    [id]
  );

  if (result.rows.length === 0) return null;
  return result.rows.item(0) as Survey;
}

export async function upsertLocalSurvey(survey: Survey): Promise<void> {
  const db = await dbPromise;
  await db.executeSql(
    `
    INSERT INTO surveys (id, siteId, title, notes, status, version, updatedAt, deletedAt)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      siteId=excluded.siteId,
      title=excluded.title,
      notes=excluded.notes,
      status=excluded.status,
      version=excluded.version,
      updatedAt=excluded.updatedAt,
      deletedAt=excluded.deletedAt
    `,
    [
      survey.id,
      survey.siteId,
      survey.title,
      survey.notes ?? null,
      survey.status,
      survey.version,
      survey.updatedAt,
      survey.deletedAt ?? null,
    ]
  );
}

export async function createSurveyLocal(input: Omit<Survey, 'id' | 'version' | 'updatedAt' | 'deletedAt'>) {
  const survey: Survey = {
    id: uuidv4(),
    ...input,
    version: 0,
    updatedAt: new Date().toISOString(),
    deletedAt: null,
  };

  await upsertLocalSurvey(survey);
  return survey;
}

export async function markSurveyDeletedLocal(id: string) {
  const db = await dbPromise;
  await db.executeSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ? WHERE id = ?`,
    [new Date().toISOString(), new Date().toISOString(), id]
  );
}
