## Sync queue repository

### `syncQueueRepository.ts`
```ts
import { dbPromise } from './db';
import { v4 as uuidv4 } from 'uuid';

export type SyncAction = 'CREATE' | 'UPDATE' | 'DELETE';

export type SyncQueueItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  action: SyncAction;
  payload: string;
  createdAt: string;
  attempts: number;
  lastError?: string | null;
};

export async function enqueueSyncItem(item: Omit<SyncQueueItem, 'id' | 'createdAt' | 'attempts' | 'lastError'>) {
  const db = await dbPromise;
  const id = uuidv4();
  await db.executeSql(
    `
    INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, attempts, lastError)
    VALUES (?, ?, ?, ?, ?, ?, 0, NULL)
    `,
    [id, item.entityType, item.entityId, item.action, item.payload, new Date().toISOString()]
  );
  return id;
}

export async function getPendingSyncItems(): Promise<SyncQueueItem[]> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  const rows = [];
  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }
  return rows as SyncQueueItem[];
}

export async function deleteSyncItem(id: string) {
  const db = await dbPromise;
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function incrementAttempt(id: string, errorMessage?: string) {
  const db = await dbPromise;
  await db.executeSql(
    `UPDATE sync_queue SET attempts = attempts + 1, lastError = ? WHERE id = ?`,
    [errorMessage ?? null, id]
  );
}
```

