## Sync engine

### `syncEngine.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingSyncItems, deleteSyncItem, incrementAttempt } from './syncQueueRepository';
import { getSurveyById, upsertLocalSurvey } from './surveyRepository';
import { syncSurveyCreate, syncSurveyUpdate, syncSurveyDelete, fetchServerChanges } from './api';

let syncing = false;
let lastSyncAt = new Date(0).toISOString();

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    const pending = await getPendingSyncItems();

    for (const item of pending) {
      try {
        if (item.entityType !== 'survey') continue;

        const survey = await getSurveyById(item.entityId);

        if (item.action === 'CREATE' && survey) {
          const serverSurvey = await syncSurveyCreate(survey);
          await upsertLocalSurvey(serverSurvey);
          await deleteSyncItem(item.id);
        }

        if (item.action === 'UPDATE' && survey) {
          const serverSurvey = await syncSurveyUpdate(survey);
          await upsertLocalSurvey(serverSurvey);
          await deleteSyncItem(item.id);
        }

        if (item.action === 'DELETE') {
          const version = survey?.version ?? 0;
          await syncSurveyDelete(item.entityId, version);
          await deleteSyncItem(item.id);
        }
      } catch (err: any) {
        await incrementAttempt(item.id, err.message || 'Sync failed');
      }
    }

    // Pull server changes
    const changes = await fetchServerChanges(lastSyncAt);
    for (const survey of changes.surveys ?? []) {
      await upsertLocalSurvey(survey);
    }
    lastSyncAt = new Date().toISOString();
  } finally {
    syncing = false;
  }
}

export function startAutoSync(onSynced?: () => void) {
  return NetInfo.addEventListener(async (state) => {
    if (state.isConnected) {
      await syncNow();
      onSynced?.();
    }
  });
}
```

