    entityType: 'survey',
    entityId: survey.id,
    action: 'CREATE',
    payload: JSON.stringify(survey),
  });

  return survey;
}

export async function updateSurvey(survey: Survey) {
  const updated: Survey = {
    ...survey,
    updatedAt: new Date().toISOString(),
  };

  await upsertLocalSurvey(updated);

  await enqueueSyncItem({
    entityType: 'survey',
    entityId: updated.id,
    action: 'UPDATE',
    payload: JSON.stringify(updated),
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  await markSurveyDeletedLocal(id);

  await enqueueSyncItem({
    entityType: 'survey',
    entityId: id,
    action: 'DELETE',
    payload: JSON.stringify({ id }),
  });
}
```

