# 3) Repository layer

This layer handles local writes and queueing.

## `surveyRepository.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import { getDb } from './db';

export type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photoUri?: string;
  status: 'draft' | 'submitted';
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
};

export async function listSurveys(): Promise<Survey[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const items: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function getSurvey(id: string): Promise<Survey | null> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE id = ? AND deletedAt IS NULL LIMIT 1`,
    [id]
  );

  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

async function enqueueAction(action: {
  entityType: 'survey';
  entityId: string;
  action: 'CREATE' | 'UPDATE' | 'DELETE';
  payload: any;
}) {
  const db = await getDb();
  await db.executeSql(
    `INSERT INTO pending_actions (id, entityType, entityId, action, payload, createdAt, retries, lastError)
     VALUES (?, ?, ?, ?, ?, ?, 0, NULL)`,
    [
      uuidv4(),
      action.entityType,
      action.entityId,
      action.action,
      JSON.stringify(action.payload),
      new Date().toISOString(),
    ]
  );
}

export async function createSurvey(input: Omit<Survey, 'id' | 'version' | 'updatedAt' | 'deletedAt'>) {
  const db = await getDb();
  const now = new Date().toISOString();
  const survey: Survey = {
    id: uuidv4(),
    ...input,
    version: 1,
    updatedAt: now,
    deletedAt: null,
  };

  await db.executeSql(
    `INSERT INTO surveys (id, siteName, latitude, longitude, notes, photoUri, status, version, updatedAt, deletedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.siteName,
      survey.latitude,
      survey.longitude,
      survey.notes,
      survey.photoUri ?? null,
      survey.status,
      survey.version,
      survey.updatedAt,
      survey.deletedAt,
    ]
  );

  await enqueueAction({
    entityType: 'survey',
    entityId: survey.id,
    action: 'CREATE',
    payload: survey,
  });

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Omit<Survey, 'id'>>) {
  const db = await getDb();
  const current = await getSurvey(id);
  if (!current) throw new Error('Survey not found');

  const updated: Survey = {
    ...current,
    ...patch,
    version: current.version + 1,
    updatedAt: new Date().toISOString(),
  };

  await db.executeSql(
    `UPDATE surveys
     SET siteName = ?, latitude = ?, longitude = ?, notes = ?, photoUri = ?, status = ?, version = ?, updatedAt = ?, deletedAt = ?
     WHERE id = ?`,
    [
      updated.siteName,
      updated.latitude,
      updated.longitude,
      updated.notes,
      updated.photoUri ?? null,
      updated.status,
      updated.version,
      updated.updatedAt,
      updated.deletedAt ?? null,
      id,
    ]
  );

  await enqueueAction({
    entityType: 'survey',
    entityId: id,
    action: 'UPDATE',
    payload: updated,
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const db = await getDb();
  const current = await getSurvey(id);
  if (!current) return;

  const deletedAt = new Date().toISOString();

  await db.executeSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ?, version = version + 1 WHERE id = ?`,
    [deletedAt, deletedAt, id]
  );

  await enqueueAction({
    entityType: 'survey',
    entityId: id,
    action: 'DELETE',
    payload: { id, deletedAt },
  });
}
```

