# 4) Sync service

This sends queued actions to your backend.

## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';

const API_URL = 'https://your-api.example.com';

type PendingActionRow = {
  id: string;
  entityType: string;
  entityId: string;
  action: 'CREATE' | 'UPDATE' | 'DELETE';
  payload: string;
  createdAt: string;
  retries: number;
  lastError?: string | null;
};

async function fetchPendingActions(): Promise<PendingActionRow[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM pending_actions ORDER BY createdAt ASC`
  );

  const items: PendingActionRow[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

async function removePendingAction(id: string) {
  const db = await getDb();
  await db.executeSql(`DELETE FROM pending_actions WHERE id = ?`, [id]);
}

async function markActionFailed(id: string, error: string) {
  const db = await getDb();
  await db.executeSql(
    `UPDATE pending_actions SET retries = retries + 1, lastError = ? WHERE id = ?`,
    [error, id]
  );
}

async function applyServerResponse(serverSurvey: any) {
  const db = await getDb();
  await db.executeSql(
    `INSERT OR REPLACE INTO surveys
     (id, siteName, latitude, longitude, notes, photoUri, status, version, updatedAt, deletedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      serverSurvey.id,
      serverSurvey.siteName,
      serverSurvey.latitude,
      serverSurvey.longitude,
      serverSurvey.notes,
      serverSurvey.photoUri ?? null,
      serverSurvey.status,
      serverSurvey.version,
      serverSurvey.updatedAt,
      serverSurvey.deletedAt ?? null,
    ]
  );
}

export async function syncPendingActions() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const actions = await fetchPendingActions();
  if (actions.length === 0) return;

  for (const action of actions) {
    try {
      const payload = JSON.parse(action.payload);

      const response = await fetch(`${API_URL}/sync/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: action.action,
          payload,
        }),
      });

      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Sync failed: ${response.status} ${text}`);
      }

      const result = await response.json();

      if (result.serverSurvey) {
        await applyServerResponse(result.serverSurvey);
      }

      await removePendingAction(action.id);
    } catch (err: any) {
      await markActionFailed(action.id, err.message ?? 'Unknown error');
      // Stop on first failure to preserve order
      break;
    }
  }
}
```

