# 7) Backend sync endpoint

Here’s a simple Node/Express example.

## `server.js`

```js
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map();

app.post('/sync/surveys', (req, res) => {
  const { action, payload } = req.body;

  if (!action || !payload) {
    return res.status(400).json({ error: 'Missing action or payload' });
  }

  let serverSurvey = null;

  switch (action) {
    case 'CREATE':
    case 'UPDATE': {
      const incoming = payload;
      const existing = surveys.get(incoming.id);

      // Simple conflict rule: accept if newer version
      if (!existing || incoming.version >= existing.version) {
        const next = {
          ...incoming,
          version: (existing?.version ?? 0) + 1,
          updatedAt: new Date().toISOString(),
        };
        surveys.set(incoming.id, next);
        serverSurvey = next;
      } else {
        return res.status(409).json({
          error: 'Conflict',
          serverSurvey: existing,
        });
      }
      break;
    }

    case 'DELETE': {
      const { id } = payload;
      surveys.delete(id);
      serverSurvey = { id, deletedAt: new Date().toISOString() };
      break;
    }

    default:
      return res.status(400).json({ error: 'Unknown action' });
  }

  res.json({ ok: true, serverSurvey });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

