## 5) Survey repository

### `src/db/surveyRepo.ts`
```ts
import { execSql, queryAll, queryOne } from './index';
import { SurveyRecord } from '../types/survey';

export function getAllSurveys(): SurveyRecord[] {
  return queryAll<SurveyRecord>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
}

export function getSurveyById(id: string): SurveyRecord | undefined {
  return queryOne<SurveyRecord>(`SELECT * FROM surveys WHERE id = ?`, [id]);
}

export function upsertSurvey(record: SurveyRecord) {
  execSql(
    `
    INSERT INTO surveys (
      id, remoteId, title, locationLat, locationLng, notes,
      status, updatedAt, createdAt, deletedAt, version
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      remoteId=excluded.remoteId,
      title=excluded.title,
      locationLat=excluded.locationLat,
      locationLng=excluded.locationLng,
      notes=excluded.notes,
      status=excluded.status,
      updatedAt=excluded.updatedAt,
      deletedAt=excluded.deletedAt,
      version=excluded.version
    `,
    [
      record.id,
      record.remoteId ?? null,
      record.title,
      record.locationLat,
      record.locationLng,
      record.notes,
      record.status,
      record.updatedAt,
      record.createdAt,
      record.deletedAt ?? null,
      record.version,
    ]
  );
}

export function markSurveyDeleted(id: string, deletedAt: string) {
  execSql(
    `UPDATE surveys SET deletedAt = ?, status = ?, updatedAt = ?, version = version + 1 WHERE id = ?`,
    [deletedAt, 'draft', deletedAt, id]
  );
}
