```ts
import { execSql, queryAll } from './index';
import { SyncQueueItem } from '../types/survey';

export function enqueue(item: SyncQueueItem) {
  execSql(
    `INSERT INTO sync_queue (id, actionType, entityId, payload, createdAt, attempts, lastError)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      item.id,
      item.actionType,
      item.entityId,
      item.payload,
      item.createdAt,
      item.attempts,
      item.lastError ?? null,
    ]
  );
}

export function getPendingQueue(): SyncQueueItem[] {
  return queryAll<SyncQueueItem>(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );
}

export function removeQueueItem(id: string) {
  execSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function incrementAttempts(id: string, error: string) {
  execSql(
    `UPDATE sync_queue SET attempts = attempts + 1, lastError = ? WHERE id = ?`,
    [error, id]
  );
}
```

