## 8) Sync logic

### `src/api/sync.ts`
```ts
import { api } from './client';
import { getPendingQueue, removeQueueItem, incrementAttempts } from '../db/queueRepo';
import { getSurveyById, upsertSurvey } from '../db/surveyRepo';
import { SurveyRecord, SyncQueueItem } from '../types/survey';

async function syncUpsertSurvey(item: SyncQueueItem) {
  const payload = JSON.parse(item.payload) as SurveyRecord;

  const response = await api.post('/surveys/sync', {
    localId: payload.id,
    remoteId: payload.remoteId,
    title: payload.title,
    locationLat: payload.locationLat,
    locationLng: payload.locationLng,
    notes: payload.notes,
    version: payload.version,
    updatedAt: payload.updatedAt,
    deletedAt: payload.deletedAt,
  });

  const serverRecord = response.data as Partial<SurveyRecord>;

  const merged: SurveyRecord = {
    ...payload,
    remoteId: serverRecord.remoteId ?? payload.remoteId ?? null,
    version: serverRecord.version ?? payload.version,
    status: 'synced',
  };

  upsertSurvey(merged);
  removeQueueItem(item.id);
}

async function syncDeleteSurvey(item: SyncQueueItem) {
  const payload = JSON.parse(item.payload) as { id: string; remoteId?: string | null };

  await api.delete(`/surveys/${payload.remoteId ?? payload.id}`);
  removeQueueItem(item.id);
}

export async function syncPendingQueue() {
  const queue = getPendingQueue();

  for (const item of queue) {
    try {
      if (item.actionType === 'UPSERT_SURVEY') {
        await syncUpsertSurvey(item);
      } else if (item.actionType === 'DELETE_SURVEY') {
        await syncDeleteSurvey(item);
      }
    } catch (err: any) {
      incrementAttempts(item.id, err?.message ?? 'Sync failed');
    }
  }
}

export async function pullLatestSurveys() {
  const response = await api.get('/surveys');
  const records = response.data as SurveyRecord[];

  for (const record of records) {
    upsertSurvey({
      ...record,
      status: 'synced',
      deletedAt: record.deletedAt ?? null,
    });
  }
}
```

