## 10) Sync hook

### `src/hooks/useSync.ts`
```ts
import { useEffect, useState } from 'react';
import { syncPendingQueue, pullLatestSurveys } from '../api/sync';

export function useSync(isOnline: boolean) {
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    if (!isOnline) return;

    let cancelled = false;

    async function run() {
      setSyncing(true);
      try {
        await syncPendingQueue();
        await pullLatestSurveys();
      } finally {
        if (!cancelled) setSyncing(false);
      }
    }

    run();

    return () => {
      cancelled = true;
    };
  }, [isOnline]);

  return { syncing };
}
```

