## 3) SQLite storage layer

### `db.ts`

```ts
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export type Survey = {
  id: string;
  serverId?: string | null;
  title: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  syncStatus: 'pending' | 'synced' | 'failed' | 'deleted';
  dirty: number; // 0 or 1
};

export function initDb(): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          serverId TEXT,
          title TEXT NOT NULL,
          latitude REAL NOT NULL,
          longitude REAL NOT NULL,
          notes TEXT,
          updatedAt TEXT NOT NULL,
          syncStatus TEXT NOT NULL,
          dirty INTEGER NOT NULL DEFAULT 1
        );`,
        [],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function upsertSurvey(survey: Survey): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
          (id, serverId, title, latitude, longitude, notes, updatedAt, syncStatus, dirty)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.serverId ?? null,
          survey.title,
          survey.latitude,
          survey.longitude,
          survey.notes,
          survey.updatedAt,
          survey.syncStatus,
          survey.dirty,
        ],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getAllSurveys(): Promise<Survey[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updatedAt DESC`,
        [],
        (_, result) => {
          resolve(result.rows._array as Survey[]);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getPendingSurveys(): Promise<Survey[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE dirty = 1 AND syncStatus != 'deleted' ORDER BY updatedAt ASC`,
        [],
        (_, result) => {
          resolve(result.rows._array as Survey[]);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSurveySynced(id: string, serverId: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET serverId = ?, syncStatus = 'synced', dirty = 0
         WHERE id = ?`,
        [serverId, id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSurveyFailed(id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET syncStatus = 'failed', dirty = 1
         WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function deleteSurveyLocal(id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM surveys WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

