## 6) Sync engine

This is the core offline-first logic.

### `sync.ts`

```ts
import { getPendingSurveys, markSurveySynced, markSurveyFailed, Survey } from './db';
import { createSurveyRemote } from './api';

export async function syncPendingSurveys(): Promise<void> {
  const pending = await getPendingSurveys();

  for (const survey of pending) {
    try {
      const remote = await createSurveyRemote({
        title: survey.title,
        latitude: survey.latitude,
        longitude: survey.longitude,
        notes: survey.notes,
        updatedAt: survey.updatedAt,
        clientId: survey.id,
      });

      await markSurveySynced(survey.id, remote.id);
    } catch (err) {
      console.warn('Sync failed for survey', survey.id, err);
      await markSurveyFailed(survey.id);
    }
  }
}
```

