## 3) `db.ts` — SQLite helpers

```ts
// db.ts
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export type Survey = {
  id: string;
  name: string;
  location: string;
  notes?: string;
  updatedAt: string;
  synced: number; // 0 = no, 1 = yes
};

export type QueueItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  action: 'create' | 'update' | 'delete';
  payload: string; // JSON string
  createdAt: string;
};

export const initDb = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          name TEXT NOT NULL,
          location TEXT NOT NULL,
          notes TEXT,
          updatedAt TEXT NOT NULL,
          synced INTEGER NOT NULL DEFAULT 0
        );`
      );

      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS sync_queue (
          id TEXT PRIMARY KEY NOT NULL,
          entityType TEXT NOT NULL,
          entityId TEXT NOT NULL,
          action TEXT NOT NULL,
          payload TEXT NOT NULL,
          createdAt TEXT NOT NULL
        );`
      );
    },
    err => reject(err),
    () => resolve());
  });
};

export const runSql = (sql: string, params: any[] = []): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const querySql = <T = any>(sql: string, params: any[] = []): Promise<T[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => {
          const rows: T[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            rows.push(result.rows.item(i));
          }
          resolve(rows);
        },
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};
