## 4) `sync.ts` — sync logic

This sends queued changes to your backend and marks them synced on success.

```ts
// sync.ts
import NetInfo from '@react-native-community/netinfo';
import { querySql, runSql, QueueItem, Survey } from './db';

const API_BASE = 'https://your-api.example.com';

export const isOnline = async (): Promise<boolean> => {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
};

export const enqueueChange = async (
  entityType: 'survey',
  entityId: string,
  action: 'create' | 'update' | 'delete',
  payload: object
) => {
  const item: QueueItem = {
    id: crypto.randomUUID(),
    entityType,
    entityId,
    action,
    payload: JSON.stringify(payload),
    createdAt: new Date().toISOString(),
  };

  await runSql(
    `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [item.id, item.entityType, item.entityId, item.action, item.payload, item.createdAt]
  );
};

export const syncPendingChanges = async () => {
  if (!(await isOnline())) return;

  const queue = await querySql<QueueItem>(`SELECT * FROM sync_queue ORDER BY createdAt ASC`);

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      let response: Response;

      if (item.action === 'create') {
        response = await fetch(`${API_BASE}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'update') {
        response = await fetch(`${API_BASE}/surveys/${item.entityId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else {
        response = await fetch(`${API_BASE}/surveys/${item.entityId}`, {
          method: 'DELETE',
        });
      }

      if (!response.ok) {
        throw new Error(`Sync failed for ${item.id}`);
      }

      await runSql(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);
      await runSql(`UPDATE surveys SET synced = 1 WHERE id = ?`, [item.entityId]);
    } catch (err) {
      console.warn('Sync item failed, will retry later:', item.id, err);
      break; // stop on first failure to preserve order
    }
  }
};

export const pullLatestSurveys = async () => {
  if (!(await isOnline())) return;

  const response = await fetch(`${API_BASE}/surveys`);
  if (!response.ok) throw new Error('Failed to fetch surveys');

  const surveys: Survey[] = await response.json();

  // simple strategy: replace local data with server data
  await runSql(`DELETE FROM surveys`);

  for (const survey of surveys) {
    await runSql(
      `INSERT INTO surveys (id, name, location, notes, updatedAt, synced)
       VALUES (?, ?, ?, ?, ?, 1)`,
      [survey.id, survey.name, survey.location, survey.notes ?? null, survey.updatedAt]
    );
  }
};
```

