## 5) `surveyService.ts` — local CRUD operations

These write locally first, then queue sync.

```ts
// surveyService.ts
import { querySql, runSql, Survey } from './db';
import { enqueueChange, syncPendingChanges } from './sync';

export const getSurveys = async (): Promise<Survey[]> => {
  return querySql<Survey>(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
};

export const addSurvey = async (survey: Omit<Survey, 'synced'>) => {
  await runSql(
    `INSERT INTO surveys (id, name, location, notes, updatedAt, synced)
     VALUES (?, ?, ?, ?, ?, 0)`,
    [survey.id, survey.name, survey.location, survey.notes ?? null, survey.updatedAt]
  );

  await enqueueChange('survey', survey.id, 'create', survey);
};

export const updateSurvey = async (survey: Survey) => {
  await runSql(
    `UPDATE surveys
     SET name = ?, location = ?, notes = ?, updatedAt = ?, synced = 0
     WHERE id = ?`,
    [survey.name, survey.location, survey.notes ?? null, survey.updatedAt, survey.id]
  );

  await enqueueChange('survey', survey.id, 'update', survey);
};

export const deleteSurvey = async (id: string) => {
  await runSql(`DELETE FROM surveys WHERE id = ?`, [id]);
  await enqueueChange('survey', id, 'delete', { id });
};

export const forceSync = async () => {
  await syncPendingChanges();
};
