## 6) `App.tsx` — UI with auto-sync on reconnect

```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { View, Text, TextInput, Button, FlatList, TouchableOpacity, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDb, Survey } from './db';
import { addSurvey, deleteSurvey, forceSync, getSurveys, updateSurvey } from './surveyService';
import { pullLatestSurveys, syncPendingChanges } from './sync';

export default function App() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [online, setOnline] = useState(false);

  const load = async () => {
    const data = await getSurveys();
    setSurveys(data);
  };

  const refreshFromServer = async () => {
    try {
      await pullLatestSurveys();
      await load();
    } catch (e) {
      console.warn(e);
    }
  };

  useEffect(() => {
    (async () => {
      await initDb();
      await load();
      await syncPendingChanges();
      await refreshFromServer();
    })();

    const unsubscribe = NetInfo.addEventListener(async state => {
      const nowOnline = !!state.isConnected && !!state.isInternetReachable;
      setOnline(nowOnline);

      if (nowOnline) {
        await syncPendingChanges();
        await refreshFromServer();
      }
    });

    return () => unsubscribe();
  }, []);

  const resetForm = () => {
    setName('');
    setLocation('');
    setNotes('');
    setEditingId(null);
  };

  const save = async () => {
    if (!name || !location) {
      Alert.alert('Validation', 'Name and location are required.');
      return;
    }

    const survey: Survey = {
      id: editingId ?? crypto.randomUUID(),
      name,
      location,
      notes,
      updatedAt: new Date().toISOString(),
      synced: 0,
    };

    if (editingId) {
      await updateSurvey(survey);
    } else {
      await addSurvey(survey);
    }

    await load();
    resetForm();
  };

  const edit = (item: Survey) => {
    setEditingId(item.id);
    setName(item.name);
    setLocation(item.location);
    setNotes(item.notes ?? '');
  };

  const remove = async (id: string) => {
    await deleteSurvey(id);
    await load();
  };

  return (
    <View style={{ flex: 1, padding: 20, marginTop: 40 }}>
      <Text style={{ fontSize: 24, fontWeight: 'bold' }}>Field Survey App</Text>
      <Text style={{ marginVertical: 8 }}>
        Status: {online ? 'Online' : 'Offline'}
      </Text>

      <TextInput
        placeholder="Survey name"
        value={name}
        onChangeText={setName}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />
      <TextInput
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />

      <Button title={editingId ? 'Update Survey' : 'Add Survey'} onPress={save} />

      {editingId && (
        <View style={{ marginTop: 8 }}>
          <Button title="Cancel Edit" onPress={resetForm} />
        </View>
      )}

      <View style={{ marginVertical: 16 }}>
        <Button
          title="Sync Now"
          onPress={async () => {
            await forceSync();
            await refreshFromServer();
            await load();
          }}
        />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={{ borderWidth: 1, padding: 12, marginBottom: 8 }}>
            <Text style={{ fontWeight: 'bold' }}>{item.name}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text>{item.synced ? 'Synced' : 'Pending sync'}</Text>

            <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
              <TouchableOpacity onPress={() => edit(item)}>
                <Text style={{ color: 'blue' }}>Edit</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => remove(item.id)}>
                <Text style={{ color: 'red' }}>Delete</Text>
              </TouchableOpacity>
            </View>
          </View>
        )}
      />
    </View>
  );
}
