import express from 'express';
const app = express();
app.use(express.json());

let surveys: any[] = [];

app.get('/surveys', (req, res) => {
  res.json(surveys);
});

app.post('/surveys', (req, res) => {
  surveys.push(req.body);
  res.status(201).json(req.body);
});

app.put('/surveys/:id', (req, res) => {
  surveys = surveys.map(s => s.id === req.params.id ? req.body : s);
  res.json(req.body);
});

app.delete('/surveys/:id', (req, res) => {
  surveys = surveys.filter(s => s.id !== req.params.id);
  res.status(204).send();
});

app.listen(3000);
