## 3) SQLite database helper

**`src/db.js`**

```js
import * as SQLite from "expo-sqlite";

const db = SQLite.openDatabase("survey.db");

export function initDb() {
  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `CREATE TABLE IF NOT EXISTS surveys (
            id TEXT PRIMARY KEY NOT NULL,
            remoteId TEXT,
            siteName TEXT NOT NULL,
            latitude REAL,
            longitude REAL,
            notes TEXT,
            createdAt TEXT NOT NULL,
            updatedAt TEXT NOT NULL,
            syncStatus TEXT NOT NULL DEFAULT 'pending',
            deleted INTEGER NOT NULL DEFAULT 0
          );`
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}

export function insertSurvey(survey) {
  const {
    id,
    remoteId = null,
    siteName,
    latitude = null,
    longitude = null,
    notes = "",
    createdAt,
    updatedAt,
    syncStatus = "pending",
    deleted = 0,
  } = survey;

  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `INSERT INTO surveys
           (id, remoteId, siteName, latitude, longitude, notes, createdAt, updatedAt, syncStatus, deleted)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);`,
          [
            id,
            remoteId,
            siteName,
            latitude,
            longitude,
            notes,
            createdAt,
            updatedAt,
            syncStatus,
            deleted,
          ]
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}

export function updateSurvey(survey) {
  const {
    id,
    remoteId = null,
    siteName,
    latitude = null,
    longitude = null,
    notes = "",
    updatedAt,
    syncStatus = "pending",
    deleted = 0,
  } = survey;

  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `UPDATE surveys
           SET remoteId = ?, siteName = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncStatus = ?, deleted = ?
           WHERE id = ?;`,
          [
            remoteId,
            siteName,
            latitude,
            longitude,
            notes,
            updatedAt,
            syncStatus,
            deleted,
            id,
          ]
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}

export function deleteSurvey(id) {
  return new Promise((resolve, reject) => {
    const now = new Date().toISOString();
    db.transaction(
      (tx) => {
        tx.executeSql(
          `UPDATE surveys
           SET deleted = 1, syncStatus = 'pending', updatedAt = ?
           WHERE id = ?;`,
          [now, id]
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}

export function getAllSurveys() {
  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `SELECT * FROM surveys ORDER BY updatedAt DESC;`,
          [],
          (_, result) => resolve(result.rows._array),
          (_, err) => {
            reject(err);
            return false;
          }
        );
      },
      (err) => reject(err)
    );
  });
}

export function getPendingSurveys() {
  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `SELECT * FROM surveys WHERE syncStatus = 'pending' ORDER BY updatedAt ASC;`,
          [],
          (_, result) => resolve(result.rows._array),
          (_, err) => {
            reject(err);
            return false;
          }
        );
      },
      (err) => reject(err)
    );
  });
}

export function markSurveySynced(id, remoteId) {
  const now = new Date().toISOString();
  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `UPDATE surveys
           SET syncStatus = 'synced', remoteId = ?, updatedAt = ?
           WHERE id = ?;`,
          [remoteId, now, id]
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}

export function markSurveyFailed(id) {
  return new Promise((resolve, reject) => {
    db.transaction(
      (tx) => {
        tx.executeSql(
          `UPDATE surveys
           SET syncStatus = 'failed'
           WHERE id = ?;`,
          [id]
        );
      },
      (err) => reject(err),
      () => resolve()
    );
  });
}
