## 4) Sync service

This service uploads pending records to your backend when online.

**`src/sync.js`**

```js
import * as Network from "expo-network";
import {
  getPendingSurveys,
  markSurveySynced,
  markSurveyFailed,
} from "./db";

const API_BASE = "https://your-api.example.com";

async function uploadSurvey(survey) {
  const response = await fetch(`${API_BASE}/surveys/sync`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(survey),
  });

  if (!response.ok) {
    throw new Error(`Upload failed: ${response.status}`);
  }

  return response.json();
}

export async function syncPendingSurveys() {
  const networkState = await Network.getNetworkStateAsync();

  if (!networkState.isConnected) {
    return { synced: 0, skipped: true };
  }

  const pending = await getPendingSurveys();
  let synced = 0;

  for (const survey of pending) {
    try {
      const result = await uploadSurvey(survey);
      await markSurveySynced(survey.id, result.remoteId || result.id || survey.remoteId);
      synced += 1;
    } catch (error) {
      console.warn("Sync failed for survey", survey.id, error);
      await markSurveyFailed(survey.id);
    }
  }

  return { synced, skipped: false };
}
```

