## 6) Repository layer

### `surveyRepository.ts`

```ts
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: boolean;
};

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const items: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      id: row.id,
      siteName: row.siteName,
      latitude: row.latitude,
      longitude: row.longitude,
      notes: row.notes,
      updatedAt: row.updatedAt,
      version: row.version,
      deleted: row.deleted === 1,
    });
  }
  return items;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);

  if (result.rows.length === 0) return null;
  const row = result.rows.item(0);

  return {
    id: row.id,
    siteName: row.siteName,
    latitude: row.latitude,
    longitude: row.longitude,
    notes: row.notes,
    updatedAt: row.updatedAt,
    version: row.version,
    deleted: row.deleted === 1,
  };
}

export async function upsertSurvey(survey: Survey) {
  const db = await getDb();
  await db.executeSql(
    `INSERT OR REPLACE INTO surveys
      (id, siteName, latitude, longitude, notes, updatedAt, version, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.siteName,
      survey.latitude,
      survey.longitude,
      survey.notes,
      survey.updatedAt,
      survey.version,
      survey.deleted ? 1 : 0,
    ]
  );
}

export async function createSurveyLocal(data: Omit<Survey, 'id' | 'updatedAt' | 'version' | 'deleted'>) {
  const survey: Survey = {
    id: uuidv4(),
    ...data,
    updatedAt: new Date().toISOString(),
    version: 1,
    deleted: false,
  };
  await upsertSurvey(survey);
  return survey;
}

export async function markSurveyDeleted(id: string) {
  const existing = await getSurveyById(id);
  if (!existing) return;

  await upsertSurvey({
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  });
}
```

