## 7) Outbox queue

### `outbox.ts`

```ts
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

export type OutboxItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
  retries: number;
};

export async function enqueueOperation(item: Omit<OutboxItem, 'id' | 'createdAt' | 'retries'>) {
  const db = await getDb();
  const outboxItem: OutboxItem = {
    id: uuidv4(),
    createdAt: new Date().toISOString(),
    retries: 0,
    ...item,
  };

  await db.executeSql(
    `INSERT INTO outbox (id, entityType, entityId, operation, payload, createdAt, retries)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      outboxItem.id,
      outboxItem.entityType,
      outboxItem.entityId,
      outboxItem.operation,
      outboxItem.payload,
      outboxItem.createdAt,
      outboxItem.retries,
    ]
  );

  return outboxItem;
}

export async function getPendingOperations(): Promise<OutboxItem[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM outbox ORDER BY createdAt ASC`);

  const items: OutboxItem[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function removeOperation(id: string) {
  const db = await getDb();
  await db.executeSql(`DELETE FROM outbox WHERE id = ?`, [id]);
}

export async function incrementRetry(id: string) {
  const db = await getDb();
  await db.executeSql(`UPDATE outbox SET retries = retries + 1 WHERE id = ?`, [id]);
}
```

