## 8) API client

### `api.ts`

```ts
export type RemoteSurvey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: boolean;
};

const BASE_URL = 'https://your-api.example.com';

export async function pushSurveyOperation(operation: {
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
}) {
  const res = await fetch(`${BASE_URL}/sync/surveys`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(operation),
  });

  if (!res.ok) {
    throw new Error(`Push failed: ${res.status}`);
  }

  return res.json();
}

export async function fetchRemoteSurveys(since?: string): Promise<RemoteSurvey[]> {
  const url = since
    ? `${BASE_URL}/surveys?since=${encodeURIComponent(since)}`
    : `${BASE_URL}/surveys`;

  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Fetch failed: ${res.status}`);
  }

  return res.json();
}
```

