## 9) Sync engine

### `syncEngine.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingOperations, removeOperation, incrementRetry } from './outbox';
import { fetchRemoteSurveys, pushSurveyOperation } from './api';
import { getDb } from './db';
import { upsertSurvey } from './surveyRepository';

async function getSyncCursor(): Promise<string | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT value FROM sync_state WHERE key = 'lastSyncAt'`);
  if (result.rows.length === 0) return null;
  return result.rows.item(0).value;
}

async function setSyncCursor(value: string) {
  const db = await getDb();
  await db.executeSql(
    `INSERT OR REPLACE INTO sync_state (key, value) VALUES ('lastSyncAt', ?)`,
    [value]
  );
}

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  // 1) Push local changes
  const pending = await getPendingOperations();
  for (const op of pending) {
    try {
      await pushSurveyOperation({
        entityId: op.entityId,
        operation: op.operation,
        payload: JSON.parse(op.payload),
      });
      await removeOperation(op.id);
    } catch (e) {
      await incrementRetry(op.id);
    }
  }

  // 2) Pull remote changes
  const since = await getSyncCursor();
  const remoteSurveys = await fetchRemoteSurveys(since || undefined);

  for (const remote of remoteSurveys) {
    await upsertSurvey(remote);
  }

  await setSyncCursor(new Date().toISOString());
}

export function startAutoSync() {
  const unsubscribe = NetInfo.addEventListener(async state => {
    if (state.isConnected) {
      try {
        await syncNow();
      } catch (err) {
        console.warn('Sync failed', err);
      }
    }
  });

  return unsubscribe;
}
```

