## 10) Save/edit survey with offline queueing

### `surveyService.ts`

```ts
import { createSurveyLocal, getSurveyById, upsertSurvey, markSurveyDeleted } from './surveyRepository';
import { enqueueOperation } from './outbox';

export async function createSurvey(data: {
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
}) {
  const survey = await createSurveyLocal(data);

  await enqueueOperation({
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: JSON.stringify(survey),
  });

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<{
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
}>) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await upsertSurvey(updated);

  await enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: JSON.stringify(updated),
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  await markSurveyDeleted(id);

  const existing = await getSurveyById(id);
  if (!existing) return;

  await enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: JSON.stringify({ id }),
  });
}
```

