## 11) App initialization

### `App.tsx`

```tsx
import React, { useEffect, useState } from 'react';
import { View, Text, Button, FlatList } from 'react-native';
import { initDb } from './db';
import { getAllSurveys } from './surveyRepository';
import { createSurvey } from './surveyService';
import { startAutoSync, syncNow } from './syncEngine';

export default function App() {
  const [surveys, setSurveys] = useState<any[]>([]);

  async function refresh() {
    const items = await getAllSurveys();
    setSurveys(items);
  }

  useEffect(() => {
    (async () => {
      await initDb();
      await refresh();
      const unsubscribe = startAutoSync();
      return unsubscribe;
    })();
  }, []);

  async function handleAdd() {
    await createSurvey({
      siteName: 'New Site',
      latitude: 12.34,
      longitude: 56.78,
      notes: 'Offline-created survey',
    });
    await refresh();
  }

  async function handleSync() {
    await syncNow();
    await refresh();
  }

  return (
    <View style={{ padding: 20, flex: 1 }}>
      <Text style={{ fontSize: 22, fontWeight: 'bold' }}>Field Survey App</Text>

      <Button title="Add Survey" onPress={handleAdd} />
      <Button title="Sync Now" onPress={handleSync} />

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={{ paddingVertical: 12 }}>
            <Text>{item.siteName}</Text>
            <Text>
              {item.latitude}, {item.longitude}
            </Text>
            <Text>{item.notes}</Text>
          </View>
        )}
      />
    </View>
  );
}
