## 3) Local database: `src/db.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('surveys.db');

export const initDb = () => {
  db.transaction(tx => {
    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        local_id TEXT UNIQUE,
        title TEXT NOT NULL,
        notes TEXT,
        latitude REAL,
        longitude REAL,
        synced INTEGER DEFAULT 0,
        created_at TEXT NOT NULL
      );
    `);

    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity_type TEXT NOT NULL,
        entity_local_id TEXT NOT NULL,
        action TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at TEXT NOT NULL
      );
    `);
  });
};

export const insertSurvey = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys 
          (local_id, title, notes, latitude, longitude, synced, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.local_id,
          survey.title,
          survey.notes || '',
          survey.latitude || null,
          survey.longitude || null,
          survey.synced || 0,
          survey.created_at
        ],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY datetime(created_at) DESC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const markSurveySynced = (localId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE local_id = ?`,
        [localId],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const addToSyncQueue = (item) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (entity_type, entity_local_id, action, payload, created_at)
         VALUES (?, ?, ?, ?, ?)`,
        [
          item.entity_type,
          item.entity_local_id,
          item.action,
          JSON.stringify(item.payload),
          item.created_at
        ],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getSyncQueue = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY id ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const removeFromSyncQueue = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};
```

