## 5) Sync logic: `src/sync.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getSyncQueue, removeFromSyncQueue, markSurveySynced } from './db';
import { createSurveyOnServer } from './api';

let syncing = false;

export const syncPendingItems = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected || !state.isInternetReachable) {
      syncing = false;
      return;
    }

    const queue = await getSyncQueue();

    for (const item of queue) {
      try {
        const payload = JSON.parse(item.payload);

        if (item.entity_type === 'survey' && item.action === 'create') {
          await createSurveyOnServer(payload);
          await markSurveySynced(item.entity_local_id);
          await removeFromSyncQueue(item.id);
        }
      } catch (err) {
        console.log('Sync failed for item:', item.id, err.message);
      }
    }
  } finally {
    syncing = false;
  }
};

export const watchConnectivity = (onOnline) => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected && state.isInternetReachable) {
      onOnline?.();
    }
  });
};
```

