## 8) Main app: `App.js`

```javascript
import React, { useEffect, useState } from 'react';
import { SafeAreaView, View, Text, StyleSheet } from 'react-native';
import { initDb, insertSurvey, getAllSurveys, addToSyncQueue } from './src/db';
import SurveyForm from './src/SurveyForm';
import SurveyList from './src/SurveyList';
import { syncPendingItems, watchConnectivity } from './src/sync';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(false);

  const loadSurveys = async () => {
    const data = await getAllSurveys();
    setSurveys(data);
  };

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = watchConnectivity(async () => {
      setOnline(true);
      await syncPendingItems();
      await loadSurveys();
    });

    return () => unsubscribe();
  }, []);

  const handleSaveSurvey = async (data) => {
    const local_id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const created_at = new Date().toISOString();

    const survey = {
      local_id,
      title: data.title,
      notes: data.notes,
      latitude: null,
      longitude: null,
      synced: 0,
      created_at,
    };

    await insertSurvey(survey);
    await addToSyncQueue({
      entity_type: 'survey',
      entity_local_id: local_id,
      action: 'create',
      payload: survey,
      created_at,
    });

    await loadSurveys();
    await syncPendingItems();
    await loadSurveys();
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Field Survey App</Text>
        <Text style={styles.status}>
          {online ? 'Online' : 'Offline'}
        </Text>
      </View>

      <SurveyForm onSubmit={handleSaveSurvey} />
      <SurveyList surveys={surveys} />
    </SafeAreaView>
  );
}

