# 2) Local repository

## `surveyRepository.ts`

```ts
import { executeSqlAsync } from './db';

export type SurveyRecord = {
  id: string;
  serverId?: string;
  plotName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  updatedAt: number;
  syncedAt?: number;
  deleted?: boolean;
};

export type PendingActionType = 'CREATE' | 'UPDATE' | 'DELETE';

export async function createSurvey(record: SurveyRecord) {
  await executeSqlAsync(
    `INSERT INTO survey_records
      (id, serverId, plotName, latitude, longitude, notes, updatedAt, syncedAt, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.serverId ?? null,
      record.plotName,
      record.latitude,
      record.longitude,
      record.notes ?? null,
      record.updatedAt,
      record.syncedAt ?? null,
      record.deleted ? 1 : 0,
    ]
  );
}

export async function updateSurvey(record: SurveyRecord) {
  await executeSqlAsync(
    `UPDATE survey_records
     SET serverId = ?, plotName = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncedAt = ?, deleted = ?
     WHERE id = ?`,
    [
      record.serverId ?? null,
      record.plotName,
      record.latitude,
      record.longitude,
      record.notes ?? null,
      record.updatedAt,
      record.syncedAt ?? null,
      record.deleted ? 1 : 0,
      record.id,
    ]
  );
}

export async function markSurveyDeleted(id: string, updatedAt: number) {
  await executeSqlAsync(
    `UPDATE survey_records
     SET deleted = 1, updatedAt = ?
     WHERE id = ?`,
    [updatedAt, id]
  );
}

export async function getSurveyById(id: string): Promise<SurveyRecord | null> {
  const result: any = await executeSqlAsync(
    `SELECT * FROM survey_records WHERE id = ? LIMIT 1`,
    [id]
  );

  if (result.rows.length === 0) return null;
  const row = result.rows.item(0);

  return {
    ...row,
    deleted: !!row.deleted,
  };
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const result: any = await executeSqlAsync(
    `SELECT * FROM survey_records WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const items: SurveyRecord[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      ...row,
      deleted: !!row.deleted,
    });
  }
  return items;
}

export async function addPendingAction(
  type: PendingActionType,
  entityId: string,
  payload?: object
) {
  await executeSqlAsync(
    `INSERT INTO pending_actions (id, type, entityId, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      crypto.randomUUID(),
      type,
      entityId,
      payload ? JSON.stringify(payload) : null,
      Date.now(),
    ]
  );
}

export async function getPendingActions() {
  const result: any = await executeSqlAsync(
    `SELECT * FROM pending_actions ORDER BY createdAt ASC`
  );

  const actions: any[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    actions.push(result.rows.item(i));
  }
  return actions;
}

export async function deletePendingAction(id: string) {
  await executeSqlAsync(`DELETE FROM pending_actions WHERE id = ?`, [id]);
}
```

