# 3) Sync service

This service sends queued actions to the backend when online.

## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingActions,
  deletePendingAction,
  getSurveyById,
  updateSurvey,
} from './surveyRepository';

const API_BASE = 'https://your-api.example.com';

async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
}

async function apiCreateSurvey(payload: any) {
  const res = await fetch(`${API_BASE}/surveys`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`Create failed: ${res.status}`);
  return res.json();
}

async function apiUpdateSurvey(serverId: string, payload: any) {
  const res = await fetch(`${API_BASE}/surveys/${serverId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`Update failed: ${res.status}`);
  return res.json();
}

async function apiDeleteSurvey(serverId: string) {
  const res = await fetch(`${API_BASE}/surveys/${serverId}`, {
    method: 'DELETE',
  });
  if (!res.ok) throw new Error(`Delete failed: ${res.status}`);
}

export async function syncPendingActions() {
  if (!(await isOnline())) return;

  const actions = await getPendingActions();

  for (const action of actions) {
    try {
      const localRecord = await getSurveyById(action.entityId);
      const payload = action.payload ? JSON.parse(action.payload) : null;

      if (action.type === 'CREATE') {
        if (!localRecord) {
          await deletePendingAction(action.id);
          continue;
        }

        const serverResult = await apiCreateSurvey({
          ...localRecord,
          serverId: undefined,
        });

        await updateSurvey({
          ...localRecord,
          serverId: serverResult.id,
          syncedAt: Date.now(),
        });

      } else if (action.type === 'UPDATE') {
        if (!localRecord) {
          await deletePendingAction(action.id);
          continue;
        }

        if (!localRecord.serverId) {
          // not yet on server, treat as create later
          continue;
        }

        await apiUpdateSurvey(localRecord.serverId, {
          ...localRecord,
          serverId: undefined,
        });

        await updateSurvey({
          ...localRecord,
          syncedAt: Date.now(),
        });

      } else if (action.type === 'DELETE') {
        if (!localRecord?.serverId) {
          await deletePendingAction(action.id);
          continue;
        }

        await apiDeleteSurvey(localRecord.serverId);
      }

      await deletePendingAction(action.id);
    } catch (err) {
      console.warn('Sync failed for action', action.id, err);
      // stop on first error to retry later
      break;
    }
  }
}
```

