# 8) Backend API example

A simple Node/Express backend could look like this:

## `server.ts`

```ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.post('/surveys', (req, res) => {
  const id = crypto.randomUUID();
  const survey = { ...req.body, id };
  surveys.set(id, survey);
  res.json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const id = req.params.id;
  if (!surveys.has(id)) return res.status(404).json({ error: 'Not found' });

  const existing = surveys.get(id);
  const updated = { ...existing, ...req.body, id };
  surveys.set(id, updated);
  res.json(updated);
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  res.status(204).send();
});

app.get('/surveys', (req, res) => {
  res.json([...surveys.values()]);
});

app.listen(3000, () => console.log('API running on port 3000'));
```

