### `src/db/index.ts`

```ts
import SQLite from "react-native-sqlite-storage";
import { CREATE_SURVEYS_TABLE, CREATE_SYNC_QUEUE_TABLE } from "./schema";
import { Survey } from "../types/survey";

SQLite.enablePromise(true);

const dbPromise = SQLite.openDatabase({ name: "survey.db", location: "default" });

export async function initDb() {
  const db = await dbPromise;
  await db.executeSql(CREATE_SURVEYS_TABLE);
  await db.executeSql(CREATE_SYNC_QUEUE_TABLE);
  return db;
}

export async function insertSurvey(survey: Survey) {
  const db = await dbPromise;
  await db.executeSql(
    `INSERT OR REPLACE INTO surveys
     (id, title, location, notes, latitude, longitude, createdAt, updatedAt, status, syncVersion)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.location,
      survey.notes ?? null,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.createdAt,
      survey.updatedAt,
      survey.status,
      survey.syncVersion,
    ]
  );
}

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  const [result] = await db.executeSql(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
  const rows = result.rows;
  const surveys: Survey[] = [];
  for (let i = 0; i < rows.length; i++) {
    surveys.push(rows.item(i));
  }
  return surveys;
}

export async function enqueueSync(operation: string, entityType: string, entityId: string, payload: any) {
  const db = await dbPromise;
  await db.executeSql(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt, retryCount)
     VALUES (?, ?, ?, ?, ?, 0)`,
    [entityType, entityId, operation, JSON.stringify(payload), new Date().toISOString()]
  );
}

export async function getSyncQueue() {
  const db = await dbPromise;
  const [result] = await db.executeSql(`SELECT * FROM sync_queue ORDER BY id ASC`);
  const rows = result.rows;
  const items: any[] = [];
  for (let i = 0; i < rows.length; i++) items.push(rows.item(i));
  return items;
}

export async function deleteQueueItem(id: number) {
  const db = await dbPromise;
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function markSurveySynced(id: string, syncVersion: number) {
  const db = await dbPromise;
  await db.executeSql(
    `UPDATE surveys SET status = 'synced', syncVersion = ?, updatedAt = ? WHERE id = ?`,
    [syncVersion, new Date().toISOString(), id]
  );
}
```

