## 7) Sync logic

### `src/api/sync.ts`

```ts
import { api } from "./client";
import { getSyncQueue, deleteQueueItem, markSurveySynced } from "../db";
import { Survey } from "../types/survey";

export async function syncPendingChanges() {
  const queue = await getSyncQueue();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.entityType === "survey" && item.operation === "create") {
        const res = await api.post("/surveys", payload);
        await markSurveySynced(payload.id, res.data.syncVersion ?? 1);
      }

      if (item.entityType === "survey" && item.operation === "update") {
        const res = await api.put(`/surveys/${payload.id}`, payload);
        await markSurveySynced(payload.id, res.data.syncVersion ?? payload.syncVersion + 1);
      }

      if (item.entityType === "survey" && item.operation === "delete") {
        await api.delete(`/surveys/${payload.id}`);
      }

      await deleteQueueItem(item.id);
    } catch (err) {
      // increment retry count logic could go here
      console.error("Sync failed for queue item", item.id, err);
    }
  }
}

export async function pullLatestSurveys() {
  const res = await api.get("/surveys");
  return res.data as Survey[];
}
```

