## 10) App entry with auto-sync

### `src/App.tsx`

```tsx
import React, { useEffect, useState } from "react";
import { SafeAreaView, Button, View, Text } from "react-native";
import { initDb } from "./db";
import SurveyForm from "./screens/SurveyForm";
import SurveyList from "./screens/SurveyList";
import { useConnectivity } from "./hooks/useConnectivity";
import { syncPendingChanges, pullLatestSurveys } from "./api/sync";
import { insertSurvey } from "./db";

export default function App() {
  const isOnline = useConnectivity();
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    (async () => {
      await initDb();
    })();
  }, []);

  useEffect(() => {
    if (isOnline) {
      (async () => {
        await syncPendingChanges();

        // Optional: pull server updates and merge locally
        const remoteSurveys = await pullLatestSurveys();
        for (const s of remoteSurveys) {
          await insertSurvey({ ...s, status: "synced" });
        }

        setRefreshKey((k) => k + 1);
      })();
    }
  }, [isOnline]);

  return (
    <SafeAreaView style={{ flex: 1 }}>
      <View style={{ padding: 12 }}>
        <Text>Connectivity: {isOnline ? "Online" : "Offline"}</Text>
        <Button title="Refresh" onPress={() => setRefreshKey((k) => k + 1)} />
      </View>

      <SurveyForm onSaved={() => setRefreshKey((k) => k + 1)} />
      <SurveyList refreshKey={refreshKey} />
    </SafeAreaView>
  );
}
