## 11) Example backend endpoints

You can use any backend. Here’s a minimal Express example.

### `server.js`

```js
const express = require("express");
const app = express();
app.use(express.json());

let surveys = [];

app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

app.post("/api/surveys", (req, res) => {
  const survey = { ...req.body, syncVersion: 1 };
  surveys.push(survey);
  res.status(201).json(survey);
});

app.put("/api/surveys/:id", (req, res) => {
  const idx = surveys.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Not found" });

  surveys[idx] = { ...surveys[idx], ...req.body, syncVersion: (surveys[idx].syncVersion || 0) + 1 };
  res.json(surveys[idx]);
});

app.delete("/api/surveys/:id", (req, res) => {
  surveys = surveys.filter(s => s.id !== req.params.id);
  res.status(204).send();
});

app.listen(3000, () => console.log("Server running on 3000"));
