## 3) Local repository

### `surveyRepository.ts`

```ts
import { getDb } from './db';
import { Survey } from './types';
import { v4 as uuidv4 } from 'uuid';

export async function getAllSurveys(): Promise<Survey[]> {
  const db = getDb();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE isDeleted = 0 ORDER BY updatedAt DESC`,
        [],
        (_, result) => {
          const rows = result.rows._array as Survey[];
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = getDb();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
        [id],
        (_, result) => {
          const row = result.rows.length > 0 ? (result.rows.item(0) as Survey) : null;
          resolve(row);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function upsertSurvey(input: Omit<Survey, 'id' | 'createdAt' | 'updatedAt' | 'isDeleted' | 'syncStatus'> & { id?: string }): Promise<Survey> {
  const db = getDb();
  const now = new Date().toISOString();
  const id = input.id ?? uuidv4();

  const existing = await getSurveyById(id);
  const createdAt = existing?.createdAt ?? now;

  const syncStatus = existing ? 'pending_update' : 'pending_create';

  const survey: Survey = {
    id,
    siteName: input.siteName,
    latitude: input.latitude,
    longitude: input.longitude,
    notes: input.notes,
    createdAt,
    updatedAt: now,
    isDeleted: false,
    syncStatus,
  };

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
         (id, siteName, latitude, longitude, notes, createdAt, updatedAt, isDeleted, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.siteName,
          survey.latitude,
          survey.longitude,
          survey.notes ?? null,
          survey.createdAt,
          survey.updatedAt,
          survey.isDeleted ? 1 : 0,
          survey.syncStatus,
        ],
        () => resolve(survey),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function deleteSurvey(id: string): Promise<void> {
  const db = getDb();
  const now = new Date().toISOString();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET isDeleted = 1, updatedAt = ?, syncStatus = ?
         WHERE id = ?`,
        [now, 'pending_delete', id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

