## 4) Sync queue

Every local create/update/delete should also create a queue item.

### `syncQueue.ts`

```ts
import { getDb } from './db';

export type QueueOperation = 'CREATE' | 'UPDATE' | 'DELETE';

export async function enqueueChange(
  entityType: string,
  entityId: string,
  operation: QueueOperation,
  payload: object
): Promise<void> {
  const db = getDb();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
         VALUES (?, ?, ?, ?, ?)`,
        [entityType, entityId, operation, JSON.stringify(payload), new Date().toISOString()],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getQueueItems(): Promise<any[]> {
  const db = getDb();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY id ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function removeQueueItem(id: number): Promise<void> {
  const db = getDb();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

