## 6) Sync engine

This is the core. It:
- checks connectivity,
- sends queued operations,
- pulls remote changes,
- updates local DB.

### `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { getQueueItems, removeQueueItem } from './syncQueue';
import { createSurveyRemote, deleteSurveyRemote, fetchSurveysRemote, updateSurveyRemote } from './api';
import { getDb } from './db';

async function markSurveySynced(id: string) {
  const db = getDb();
  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

async function applyRemoteSurveyToLocal(survey: any) {
  const db = getDb();
  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
         (id, siteName, latitude, longitude, notes, createdAt, updatedAt, isDeleted, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.siteName,
          survey.latitude,
          survey.longitude,
          survey.notes ?? null,
          survey.createdAt,
          survey.updatedAt,
          survey.isDeleted ? 1 : 0,
          'synced',
        ],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function syncNow(): Promise<void> {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return;

  // 1) Push local queue
  const queue = await getQueueItems();

  for (const item of queue) {
    const payload = JSON.parse(item.payload);

    try {
      if (item.operation === 'CREATE') {
        await createSurveyRemote(payload);
      } else if (item.operation === 'UPDATE') {
        await updateSurveyRemote(payload);
      } else if (item.operation === 'DELETE') {
        await deleteSurveyRemote(item.entityId);
      }

      await removeQueueItem(item.id);
      await markSurveySynced(item.entityId);
    } catch (err) {
      // Stop on first failure to avoid cascading issues
      console.warn('Sync failed for item', item.id, err);
      break;
    }
  }

  // 2) Pull remote state
  const remoteSurveys = await fetchSurveysRemote();
  for (const remote of remoteSurveys) {
    await applyRemoteSurveyToLocal(remote);
  }
}
```

