# 3) Local repository

This handles CRUD locally and queues sync operations.

```ts
// src/repository.ts
import { v4 as uuidv4 } from 'uuid';
import { db } from './db';
import { SurveyRecord } from './types';

export function getAllSurveys(): SurveyRecord[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  return rows.map((r) => ({
    ...r,
    deleted: !!r.deleted,
  }));
}

export function createSurvey(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus'>) {
  const now = new Date().toISOString();
  const id = uuidv4();

  const survey: SurveyRecord = {
    id,
    ...input,
    createdAt: now,
    updatedAt: now,
    syncStatus: 'pending',
  };

  db.runSync(
    `INSERT INTO surveys (id, siteName, latitude, longitude, notes, createdAt, updatedAt, syncStatus, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0)`,
    [
      survey.id,
      survey.siteName,
      survey.latitude,
      survey.longitude,
      survey.notes,
      survey.createdAt,
      survey.updatedAt,
      survey.syncStatus,
    ]
  );

  enqueueMutation('survey', survey.id, 'create', survey);
  return survey;
}

export function updateSurvey(id: string, patch: Partial<Omit<SurveyRecord, 'id' | 'createdAt'>>) {
  const existing = db.getFirstSync<any>(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    syncStatus: 'pending',
  };

  db.runSync(
    `UPDATE surveys
     SET siteName = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [
      updated.siteName,
      updated.latitude,
      updated.longitude,
      updated.notes,
      updated.updatedAt,
      updated.syncStatus,
      id,
    ]
  );

  enqueueMutation('survey', id, 'update', updated);
  return updated as SurveyRecord;
}

export function deleteSurvey(id: string) {
  const existing = db.getFirstSync<any>(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!existing) throw new Error('Survey not found');

  db.runSync(`UPDATE surveys SET deleted = 1, syncStatus = 'pending', updatedAt = ? WHERE id = ?`, [
    new Date().toISOString(),
    id,
  ]);

  enqueueMutation('survey', id, 'delete', { id });
}

function enqueueMutation(
  entityType: 'survey',
  entityId: string,
  operation: 'create' | 'update' | 'delete',
  payload: any
) {
  db.runSync(
    `INSERT INTO sync_queue (id, entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [uuidv4(), entityType, entityId, operation, JSON.stringify(payload), new Date().toISOString()]
  );
}
