# 5) Sync service

This runs when online and pushes local queue, then pulls remote changes.

```ts
// src/syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { db } from './db';
import { pushMutation, pullChanges } from './api';

let syncing = false;

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const queue = db.getAllSync<any>(
      `SELECT * FROM sync_queue ORDER BY createdAt ASC`
    );

    // Push queued mutations
    for (const item of queue) {
      const payload = JSON.parse(item.payload);
      await pushMutation({
        entityType: item.entityType,
        entityId: item.entityId,
        operation: item.operation,
        payload,
      });

      db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);

      if (item.entityType === 'survey') {
        db.runSync(`UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`, [item.entityId]);
      }
    }

    // Pull remote changes
    const lastSyncRow = db.getFirstSync<any>(`SELECT value FROM meta WHERE key = 'lastSyncAt'`);
    const since = lastSyncRow?.value ?? '1970-01-01T00:00:00.000Z';

    const changes = await pullChanges(since);

    for (const survey of changes.surveys) {
      const existing = db.getFirstSync<any>(`SELECT * FROM surveys WHERE id = ?`, [survey.id]);

      if (!existing) {
        db.runSync(
          `INSERT INTO surveys (id, siteName, latitude, longitude, notes, createdAt, updatedAt, syncStatus, deleted)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'synced', ?)`,
          [
            survey.id,
            survey.siteName,
            survey.latitude,
            survey.longitude,
            survey.notes,
            survey.createdAt,
            survey.updatedAt,
            survey.deleted ? 1 : 0,
          ]
        );
      } else {
        // Simple last-write-wins strategy
        if (new Date(survey.updatedAt) > new Date(existing.updatedAt)) {
          db.runSync(
            `UPDATE surveys
             SET siteName = ?, latitude = ?, longitude = ?, notes = ?, createdAt = ?, updatedAt = ?, syncStatus = 'synced', deleted = ?
             WHERE id = ?`,
            [
              survey.siteName,
              survey.latitude,
              survey.longitude,
              survey.notes,
              survey.createdAt,
              survey.updatedAt,
              survey.deleted ? 1 : 0,
              survey.id,
            ]
          );
        }
      }
    }

    db.runSync(
      `INSERT OR REPLACE INTO meta (key, value) VALUES ('lastSyncAt', ?)`,
      [changes.serverTime]
    );
  } finally {
    syncing = false;
  }
}

export function startAutoSync() {
  NetInfo.addEventListener((state) => {
    if (state.isConnected && state.isInternetReachable) {
      syncNow().catch(console.error);
    }
  });
}
```

