# 8) Backend sync endpoint example

Here’s a simple Node/Express backend pattern.

```ts
// server.ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();
let serverTime = new Date().toISOString();

app.post('/api/sync', (req, res) => {
  const { entityType, entityId, operation, payload } = req.body;

  if (entityType !== 'survey') {
    return res.status(400).json({ error: 'Unsupported entity type' });
  }

  if (operation === 'create' || operation === 'update') {
    surveys.set(entityId, payload);
  } else if (operation === 'delete') {
    const existing = surveys.get(entityId);
    if (existing) {
      surveys.set(entityId, { ...existing, deleted: true, updatedAt: new Date().toISOString() });
    }
  }

  serverTime = new Date().toISOString();
  res.json({ ok: true, serverTime });
});

app.get('/api/sync', (req, res) => {
  const since = String(req.query.since || '1970-01-01T00:00:00.000Z');

  const changedSurveys = [...surveys.values()].filter(
    (s) => new Date(s.updatedAt) > new Date(since)
  );

  res.json({
    surveys: changedSurveys,
    serverTime,
  });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

