  id: string;
  entityType: "survey";
  entityId: string;
  operation: "upsert" | "delete";
  payload: any;
  createdAt: string;
  retryCount: number;
};

class FieldSurveyDB extends Dexie {
  surveys!: Table<Survey, string>;
  syncQueue!: Table<SyncOperation, string>;

  constructor() {
    super("FieldSurveyDB");
    this.version(1).stores({
      surveys: "id, projectId, updatedAt, deleted, version",
      syncQueue: "id, entityType, entityId, operation, createdAt, retryCount",
    });
  }
}

export const db = new FieldSurveyDB();
