# 4) Offline-first repository layer

This is the core of the app: write locally first, queue sync ops, then sync later.

## `surveyRepository.ts`

```ts
import { db, Survey, SyncOperation } from "./db";
import { pushSurveyDelete, pushSurveyUpsert, fetchSurveysSince } from "./api";
import { v4 as uuidv4 } from "uuid";

export async function getAllLocalSurveys() {
  return db.surveys.where("deleted").notEqual(1).toArray();
}

export async function saveSurveyOffline(input: Omit<Survey, "id" | "updatedAt" | "version"> & { id?: string }) {
  const now = new Date().toISOString();
  const id = input.id ?? uuidv4();

  const existing = await db.surveys.get(id);
  const version = (existing?.version ?? 0) + 1;

  const survey: Survey = {
    id,
    projectId: input.projectId,
    siteName: input.siteName,
    latitude: input.latitude,
    longitude: input.longitude,
    notes: input.notes,
    photos: input.photos ?? [],
    updatedAt: now,
    deleted: false,
    version,
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(survey);

    const op: SyncOperation = {
      id: uuidv4(),
      entityType: "survey",
      entityId: id,
      operation: "upsert",
      payload: survey,
      createdAt: now,
      retryCount: 0,
    };

    await db.syncQueue.put(op);
  });

  return survey;
}

export async function deleteSurveyOffline(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const now = new Date().toISOString();
  const deletedSurvey: Survey = {
    ...existing,
    deleted: true,
    updatedAt: now,
    version: existing.version + 1,
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(deletedSurvey);

    const op: SyncOperation = {
      id: uuidv4(),
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: { id, version: deletedSurvey.version },
      createdAt: now,
      retryCount: 0,
    };

    await db.syncQueue.put(op);
  });
}

export async function syncNow() {
  if (!navigator.onLine) return;

  // 1) Push queued operations
  const queue = await db.syncQueue.orderBy("createdAt").toArray();

  for (const op of queue) {
    try {
      if (op.operation === "upsert") {
        await pushSurveyUpsert(op.payload);
      } else if (op.operation === "delete") {
        await pushSurveyDelete(op.entityId, op.payload.version);
      }

      await db.syncQueue.delete(op.id);
    } catch (err) {
      op.retryCount += 1;
      await db.syncQueue.put(op);
      // optionally break on first failure to preserve ordering
    }
  }

  // 2) Pull remote updates
  const lastSync = localStorage.getItem("lastSyncAt") || "1970-01-01T00:00:00.000Z";
  const updates = await fetchSurveysSince(lastSync);

  await db.transaction("rw", db.surveys, async () => {
    for (const remote of updates) {
      const local = await db.surveys.get(remote.id);

      // Simple conflict rule:
      // keep the record with the higher version, or server wins if equal
      if (!local || remote.version >= local.version) {
        await db.surveys.put(remote);
      }
    }
  });

  localStorage.setItem("lastSyncAt", new Date().toISOString());
}
```

