# 6) Backend API

A simple Express server with in-memory storage for demonstration. Replace with a real DB in production.

## `server.ts`

```ts
import express from "express";
import cors from "cors";

type Survey = {
  id: string;
  projectId: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  updatedAt: string;
  deleted?: boolean;
  version: number;
};

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map<string, Survey>();

app.get("/surveys", (req, res) => {
  const since = String(req.query.since || "1970-01-01T00:00:00.000Z");
  const result = [...surveys.values()].filter((s) => s.updatedAt > since);
  res.json(result);
});

app.put("/surveys/:id", (req, res) => {
  const id = req.params.id;
  const incoming: Survey = req.body;

  const existing = surveys.get(id);
  if (existing && incoming.version < existing.version) {
    return res.status(409).json({ error: "Version conflict", existing });
  }

  surveys.set(id, { ...incoming, id });
  res.json({ ok: true });
});

app.delete("/surveys/:id", (req, res) => {
  const id = req.params.id;
  const { version } = req.body;

  const existing = surveys.get(id);
  if (existing && version < existing.version) {
    return res.status(409).json({ error: "Version conflict", existing });
  }

  if (existing) {
    surveys.set(id, {
      ...existing,
      deleted: true,
      version: version ?? existing.version + 1,
      updatedAt: new Date().toISOString(),
    });
  }

  res.json({ ok: true });
});

app.listen(3000, () => {
  console.log("API running on http://localhost:3000");
});
```

