# 3) Survey service for local CRUD

## `surveyService.ts`

```ts
import db from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  remote_id?: string | null;
  name: string;
  latitude?: number | null;
  longitude?: number | null;
  notes?: string | null;
  status: 'draft' | 'submitted' | 'synced';
  dirty: number;
  deleted: number;
  updated_at: string;
};

function now() {
  return new Date().toISOString();
}

export function createSurvey(data: {
  name: string;
  latitude?: number;
  longitude?: number;
  notes?: string;
}) {
  const id = uuidv4();
  const updatedAt = now();

  return new Promise<string>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, name, latitude, longitude, notes, status, dirty, deleted, updated_at)
         VALUES (?, ?, ?, ?, ?, 'draft', 1, 0, ?)`,
        [id, data.name, data.latitude ?? null, data.longitude ?? null, data.notes ?? null, updatedAt],
        () => {
          tx.executeSql(
            `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at)
             VALUES (?, ?, ?, ?, ?)`,
            [
              'survey',
              id,
              'create',
              JSON.stringify({ id, ...data, updated_at: updatedAt }),
              updatedAt,
            ],
            () => resolve(id),
            (_, err) => {
              reject(err);
              return false;
            }
          );
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function updateSurvey(
  id: string,
  data: Partial<{
    name: string;
    latitude: number;
    longitude: number;
    notes: string;
    status: 'draft' | 'submitted' | 'synced';
  }>
) {
  const updatedAt = now();

  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET name = COALESCE(?, name),
             latitude = COALESCE(?, latitude),
             longitude = COALESCE(?, longitude),
             notes = COALESCE(?, notes),
             status = COALESCE(?, status),
             dirty = 1,
             updated_at = ?
         WHERE id = ?`,
        [data.name ?? null, data.latitude ?? null, data.longitude ?? null, data.notes ?? null, data.status ?? null, updatedAt, id],
        () => {
          tx.executeSql(
            `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at)
             VALUES (?, ?, ?, ?, ?)`,
            ['survey', id, 'update', JSON.stringify({ id, ...data, updated_at: updatedAt }), updatedAt],
            () => resolve(),
            (_, err) => {
              reject(err);
              return false;
            }
          );
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function deleteSurvey(id: string) {
  const updatedAt = now();

  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET deleted = 1, dirty = 1, updated_at = ? WHERE id = ?`,
        [updatedAt, id],
        () => {
          tx.executeSql(
            `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at)
             VALUES (?, ?, ?, ?, ?)`,
            ['survey', id, 'delete', JSON.stringify({ id, updated_at: updatedAt }), updatedAt],
            () => resolve(),
            (_, err) => {
              reject(err);
              return false;
            }
          );
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getSurveys(): Promise<Survey[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updated_at DESC`,
        [],
        (_, result) => {
          resolve(result.rows._array as Survey[]);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getPendingQueue(): Promise<any[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY id ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function clearQueueItem(id: number) {
  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSynced(localId: string, remoteId: string) {
  return new Promise<void>((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET remote_id = ?, dirty = 0, status = 'synced' WHERE id = ?`,
        [remoteId, localId],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

