# 4) Sync service

This pushes queued changes to the backend when online.

## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { clearQueueItem, getPendingQueue, markSynced } from './surveyService';

const API_URL = 'https://your-api.example.com';

async function sendToServer(action: string, payload: any) {
  let url = `${API_URL}/surveys`;
  let method = 'POST';

  if (action === 'update' || action === 'delete') {
    if (!payload.remote_id && !payload.id) throw new Error('Missing ID');
    const serverId = payload.remote_id || payload.id;
    url = `${API_URL}/surveys/${serverId}`;
    method = action === 'delete' ? 'DELETE' : 'PUT';
  }

  const body = action === 'delete' ? undefined : JSON.stringify(payload);

  const res = await fetch(url, {
    method,
    headers: {
      'Content-Type': 'application/json',
    },
    body,
  });

  if (!res.ok) {
    throw new Error(`Sync failed: ${res.status}`);
  }

  return res.json().catch(() => ({}));
}

export async function syncPendingChanges() {
  const net = await NetInfo.fetch();
  if (!net.isConnected || !net.isInternetReachable) {
    return { synced: 0, skipped: true };
  }

  const queue = await getPendingQueue();
  let synced = 0;

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);
      const result = await sendToServer(item.action, payload);

      if (item.action === 'create' && result?.id) {
        await markSynced(item.entity_id, result.id);
      }

      await clearQueueItem(item.id);
      synced++;
    } catch (err) {
      console.warn('Sync error for item', item.id, err);
      // stop on first failure to preserve order
      break;
    }
  }

  return { synced, skipped: false };
}
```

