// surveyRepo.ts
import { db } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  status: 'draft' | 'submitted';
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
  version: number;
};

export async function getAllSurveys(): Promise<Survey[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`,
        [],
        (_, result) => resolve(result.rows._array as Survey[]),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function saveSurveyLocal(
  survey: Omit<Survey, 'id' | 'createdAt' | 'updatedAt' | 'version'> & Partial<Pick<Survey, 'id'>>
): Promise<Survey> {
  const now = new Date().toISOString();
  const id = survey.id ?? uuidv4();

  const existing = await getSurveyById(id);
  const createdAt = existing?.createdAt ?? now;
  const version = (existing?.version ?? 0) + 1;

  const record: Survey = {
    id,
    siteName: survey.siteName,
    latitude: survey.latitude,
    longitude: survey.longitude,
    notes: survey.notes,
    status: survey.status,
    createdAt,
    updatedAt: now,
    deletedAt: null,
    version,
  };

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
         (id, siteName, latitude, longitude, notes, status, createdAt, updatedAt, deletedAt, version)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          record.id,
          record.siteName,
          record.latitude,
          record.longitude,
          record.notes,
          record.status,
          record.createdAt,
          record.updatedAt,
          record.deletedAt,
          record.version,
        ],
        () => resolve(record),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
        [id],
        (_, result) => {
          resolve(result.rows.length ? (result.rows.item(0) as Survey) : null);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function deleteSurveyLocal(id: string): Promise<void> {
  const now = new Date().toISOString();
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET deletedAt = ?, updatedAt = ?, version = version + 1 WHERE id = ?`,
        [now, now, id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
