### 3) Outbox / pending mutation queue

```ts
// outbox.ts
import { db } from './db';
import { v4 as uuidv4 } from 'uuid';

export type MutationOperation = 'create' | 'update' | 'delete';

export async function enqueueMutation(
  entityType: 'survey',
  entityId: string,
  operation: MutationOperation,
  payload: any
): Promise<void> {
  const id = uuidv4();
  const createdAt = new Date().toISOString();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO pending_mutations
         (id, entityType, entityId, operation, payload, createdAt, retryCount)
         VALUES (?, ?, ?, ?, ?, ?, 0)`,
        [id, entityType, entityId, operation, JSON.stringify(payload), createdAt],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getPendingMutations(): Promise<any[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM pending_mutations ORDER BY createdAt ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function removePendingMutation(id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM pending_mutations WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function incrementRetryCount(id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE pending_mutations SET retryCount = retryCount + 1 WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

