### 4) Sync service

This pushes local changes to the server and then pulls remote updates.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingMutations, removePendingMutation, incrementRetryCount } from './outbox';
import { getSyncState, setSyncState } from './syncState';
import { saveSurveyLocal, deleteSurveyLocal } from './surveyRepo';

const API_BASE = 'https://your-api.example.com';

async function apiFetch(path: string, options: RequestInit = {}) {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  if (!res.ok) {
    throw new Error(`API error ${res.status}`);
  }
  return res.json();
}

export async function syncNow(): Promise<void> {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  // 1) Push local mutations
  const mutations = await getPendingMutations();
  for (const m of mutations) {
    try {
      const payload = JSON.parse(m.payload);

      if (m.entityType === 'survey') {
        if (m.operation === 'create') {
          await apiFetch('/surveys', {
            method: 'POST',
            body: JSON.stringify(payload),
          });
        } else if (m.operation === 'update') {
          await apiFetch(`/surveys/${m.entityId}`, {
            method: 'PUT',
            body: JSON.stringify(payload),
          });
        } else if (m.operation === 'delete') {
          await apiFetch(`/surveys/${m.entityId}`, {
            method: 'DELETE',
          });
        }
      }

      await removePendingMutation(m.id);
    } catch (err) {
      await incrementRetryCount(m.id);
      // Stop on first failure to preserve ordering
      break;
    }
  }

  // 2) Pull server changes since last sync
  const lastSync = (await getSyncState('lastSyncAt')) || '1970-01-01T00:00:00.000Z';
  const changes = await apiFetch(`/sync?since=${encodeURIComponent(lastSync)}`);

  for (const item of changes.surveys || []) {
    if (item.deletedAt) {
      await deleteSurveyLocal(item.id);
    } else {
      await saveSurveyLocal(item);
    }
  }

  await setSyncState('lastSyncAt', new Date().toISOString());
}

export function startAutoSync() {
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncNow().catch(console.error);
    }
  });
}
```

