// db.ts
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabaseSync('field-survey.db');

export function initDb() {
  db.execSync(`
    PRAGMA journal_mode = WAL;

    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      serverId TEXT,
      title TEXT NOT NULL,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      notes TEXT NOT NULL,
      updatedAt INTEGER NOT NULL,
      syncedAt INTEGER,
      syncStatus TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sync_queue (
      id TEXT PRIMARY KEY NOT NULL,
      entityType TEXT NOT NULL,
      entityId TEXT NOT NULL,
      operation TEXT NOT NULL,
      payload TEXT NOT NULL,
      createdAt INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0
    );
  `);
}

export function insertSurvey(survey: any) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, serverId, title, latitude, longitude, notes, updatedAt, syncedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.serverId ?? null,
      survey.title,
      survey.latitude,
      survey.longitude,
      survey.notes,
      survey.updatedAt,
      survey.syncedAt ?? null,
      survey.syncStatus,
    ]
  );
}

export function getSurveys() {
  return db.getAllSync(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
}

export function getPendingQueue() {
  return db.getAllSync(`SELECT * FROM sync_queue ORDER BY createdAt ASC`);
}

export function enqueueChange(item: any) {
  db.runSync(
    `INSERT OR REPLACE INTO sync_queue
      (id, entityType, entityId, operation, payload, createdAt, attempts)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.operation,
      item.payload,
      item.createdAt,
      item.attempts ?? 0,
    ]
  );
}

export function removeQueueItem(id: string) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function markSurveySynced(id: string, serverId: string) {
  db.runSync(
    `UPDATE surveys
     SET serverId = ?, syncedAt = ?, syncStatus = 'synced'
     WHERE id = ?`,
    [serverId, Date.now(), id]
  );
}

export function markSurveyPending(id: string) {
  db.runSync(
    `UPDATE surveys
     SET syncStatus = 'pending'
     WHERE id = ?`,
    [id]
  );
}

export function markSurveyError(id: string) {
  db.runSync(
    `UPDATE surveys
     SET syncStatus = 'error'
     WHERE id = ?`,
    [id]
  );
}
