# 3) Sync service

This service sends queued changes to the server and updates local state.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingQueue,
  removeQueueItem,
  markSurveySynced,
  markSurveyError,
  enqueueChange,
} from './db';

const API_BASE = 'https://your-api.example.com';

async function sendToServer(item: any) {
  const response = await fetch(`${API_BASE}/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      entityType: item.entityType,
      entityId: item.entityId,
      operation: item.operation,
      payload: JSON.parse(item.payload),
      clientTimestamp: item.createdAt,
    }),
  });

  if (!response.ok) {
    throw new Error(`Sync failed: ${response.status}`);
  }

  return response.json();
}

export async function syncPendingChanges() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const queue = getPendingQueue();

  for (const item of queue) {
    try {
      const result = await sendToServer(item);

      if (item.entityType === 'survey' && result.serverId) {
        markSurveySynced(item.entityId, result.serverId);
      }

      removeQueueItem(item.id);
    } catch (err) {
      // increase attempts and keep queued
      enqueueChange({
        ...item,
        attempts: (item.attempts ?? 0) + 1,
      });

      markSurveyError(item.entityId);
      break; // stop if server/network issue
    }
  }
}
```

