### `surveyRepository.ts`

```ts
import { db } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  title: string;
  location: string;
  notes: string;
  latitude?: number;
  longitude?: number;
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
  syncStatus: 'synced' | 'pending' | 'conflict';
};

export function getAllSurveys(): Survey[] {
  return db.getAllSync<Survey>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
}

export function getSurveyById(id: string): Survey | null {
  const row = db.getFirstSync<Survey>(
    `SELECT * FROM surveys WHERE id = ? AND deletedAt IS NULL`,
    [id]
  );
  return row ?? null;
}

export function upsertSurvey(input: Partial<Survey> & { title: string; location: string; notes: string }) {
  const now = new Date().toISOString();
  const id = input.id ?? uuidv4();

  const existing = getSurveyById(id);
  const createdAt = existing?.createdAt ?? now;

  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, title, location, notes, latitude, longitude, createdAt, updatedAt, deletedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      id,
      input.title,
      input.location,
      input.notes,
      input.latitude ?? null,
      input.longitude ?? null,
      createdAt,
      now,
      null,
      'pending',
    ]
  );

  enqueueSync({
    entityType: 'survey',
    entityId: id,
    operation: existing ? 'update' : 'create',
    payload: {
      id,
      title: input.title,
      location: input.location,
      notes: input.notes,
      latitude: input.latitude ?? null,
      longitude: input.longitude ?? null,
      createdAt,
      updatedAt: now,
      deletedAt: null,
    },
  });

  return id;
}

export function deleteSurvey(id: string) {
  const now = new Date().toISOString();

  db.runSync(
    `UPDATE surveys
     SET deletedAt = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [now, now, 'pending', id]
  );

  enqueueSync({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id, deletedAt: now, updatedAt: now },
  });
}

function enqueueSync(job: {
  entityType: string;
  entityId: string;
  operation: string;
  payload: any;
}) {
  db.runSync(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      job.entityType,
      job.entityId,
      job.operation,
      JSON.stringify(job.payload),
      new Date().toISOString(),
    ]
  );
}

export function getPendingSyncJobs() {
  return db.getAllSync<{
    id: number;
    entityType: string;
    entityId: string;
    operation: string;
    payload: string;
    createdAt: string;
  }>(`SELECT * FROM sync_queue ORDER BY id ASC`);
}

export function removeSyncJob(id: number) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function markSynced(id: string) {
  db.runSync(`UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`, [id]);
}

export function markConflict(id: string) {
  db.runSync(`UPDATE surveys SET syncStatus = 'conflict' WHERE id = ?`, [id]);
}
