import {
  getPendingSyncJobs,
  removeSyncJob,
  markSynced,
  markConflict,
} from './surveyRepository';

const API_URL = 'https://your-api.example.com';

async function apiRequest(path: string, options: RequestInit = {}) {
  const res = await fetch(`${API_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`API ${res.status}: ${text}`);
  }

  return res.json().catch(() => null);
}

export async function syncNow() {
  const jobs = getPendingSyncJobs();

  for (const job of jobs) {
    try {
      const payload = JSON.parse(job.payload);

      if (job.operation === 'create' || job.operation === 'update') {
        const serverRecord = await apiRequest(`/surveys/${payload.id}`, {
          method: 'PUT',
          body: JSON.stringify(payload),
        });

        if (serverRecord?.conflict) {
          markConflict(payload.id);
        } else {
          markSynced(payload.id);
          removeSyncJob(job.id);
        }
      }

      if (job.operation === 'delete') {
        await apiRequest(`/surveys/${payload.id}`, {
          method: 'DELETE',
        });

        removeSyncJob(job.id);
      }
    } catch (err) {
      console.warn('Sync failed for job', job.id, err);
      // stop on first failure to preserve order
      break;
    }
  }

  // Pull latest server state after pushing local changes
  await pullLatestSurveys();
}

