## 6) Merge strategy

A simple conflict rule: **latest `updatedAt` wins**.

### `merge.ts`

```ts
import { db } from './db';
import { Survey } from './surveyRepository';

export function mergeServerSurveys(serverSurveys: Survey[]) {
  for (const remote of serverSurveys) {
    const local = db.getFirstSync<Survey>(`SELECT * FROM surveys WHERE id = ?`, [remote.id]);

    if (!local) {
      db.runSync(
        `INSERT INTO surveys
          (id, title, location, notes, latitude, longitude, createdAt, updatedAt, deletedAt, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          remote.id,
          remote.title,
          remote.location,
          remote.notes,
          remote.latitude ?? null,
          remote.longitude ?? null,
          remote.createdAt,
          remote.updatedAt,
          remote.deletedAt ?? null,
          'synced',
        ]
      );
      continue;
    }

    const localUpdated = new Date(local.updatedAt).getTime();
    const remoteUpdated = new Date(remote.updatedAt).getTime();

    if (remoteUpdated > localUpdated) {
      db.runSync(
        `UPDATE surveys
         SET title = ?, location = ?, notes = ?, latitude = ?, longitude = ?,
             createdAt = ?, updatedAt = ?, deletedAt = ?, syncStatus = ?
         WHERE id = ?`,
        [
          remote.title,
          remote.location,
          remote.notes,
          remote.latitude ?? null,
          remote.longitude ?? null,
          remote.createdAt,
          remote.updatedAt,
          remote.deletedAt ?? null,
          'synced',
          remote.id,
        ]
      );
    }
  }
}
