## 8) Example backend API

Here’s a minimal Express backend for sync.

### `server.ts`

```ts
import express from 'express';

const app = express();
app.use(express.json());

type Survey = {
  id: string;
  title: string;
  location: string;
  notes: string;
  latitude?: number | null;
  longitude?: number | null;
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
};

const surveys = new Map<string, Survey>();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.put('/surveys/:id', (req, res) => {
  const incoming: Survey = req.body;
  const existing = surveys.get(req.params.id);

  if (existing) {
    const existingTime = new Date(existing.updatedAt).getTime();
    const incomingTime = new Date(incoming.updatedAt).getTime();

    if (incomingTime < existingTime) {
      return res.status(409).json({ conflict: true, serverRecord: existing });
    }
  }

  surveys.set(req.params.id, incoming);
  res.json(incoming);
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  res.json({ ok: true });
});

app.listen(3000, () => {
  console.log('API listening on http://localhost:3000');
});
