## 2) Local database layer

Create `src/db.ts`:

```ts
import * as SQLite from "expo-sqlite";

const db = SQLite.openDatabase("survey_app.db");

export type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  createdAt: string;
  synced: number; // 0 = false, 1 = true
};

export function initDb() {
  db.transaction((tx) => {
    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        siteName TEXT NOT NULL,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        notes TEXT,
        createdAt TEXT NOT NULL,
        synced INTEGER NOT NULL DEFAULT 0
      );
    `);
  });
}

export function insertSurvey(survey: SurveyRecord) {
  return new Promise<void>((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys (id, siteName, latitude, longitude, notes, createdAt, synced)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.siteName,
          survey.latitude,
          survey.longitude,
          survey.notes,
          survey.createdAt,
          survey.synced,
        ],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getUnsyncedSurveys(): Promise<SurveyRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE synced = 0 ORDER BY createdAt ASC`,
        [],
        (_, result) => {
          resolve(result.rows._array as SurveyRecord[]);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSurveySynced(id: string) {
  return new Promise<void>((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getAllSurveys(): Promise<SurveyRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY createdAt DESC`,
        [],
        (_, result) => resolve(result.rows._array as SurveyRecord[]),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

