## 4) Sync manager

Create `src/sync.ts`:

```ts
import NetInfo from "@react-native-community/netinfo";
import { getUnsyncedSurveys, markSurveySynced } from "./db";
import { syncSurvey } from "./api";

let syncing = false;

export async function syncPendingSurveys() {
  if (syncing) return;
  syncing = true;

  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected) return;

    const pending = await getUnsyncedSurveys();

    for (const survey of pending) {
      try {
        await syncSurvey(survey);
        await markSurveySynced(survey.id);
      } catch (err) {
        console.warn("Failed to sync survey:", survey.id, err);
        // stop on first failure to avoid hammering a bad connection
        break;
      }
    }
  } finally {
    syncing = false;
  }
}
```

