// db.ts
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabaseSync('field_survey.db');

export function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      siteId TEXT NOT NULL,
      observerId TEXT NOT NULL,
      timestamp TEXT NOT NULL,
      latitude REAL,
      longitude REAL,
      notes TEXT,
      status TEXT NOT NULL DEFAULT 'draft',
      version INTEGER NOT NULL DEFAULT 1,
      updatedAt TEXT NOT NULL,
      deletedAt TEXT,
      syncedAt TEXT
    );

    CREATE TABLE IF NOT EXISTS pending_operations (
      id TEXT PRIMARY KEY,
      entityType TEXT NOT NULL,
      entityId TEXT NOT NULL,
      operation TEXT NOT NULL,
      payload TEXT NOT NULL,
      baseVersion INTEGER,
      createdAt TEXT NOT NULL,
      retryCount INTEGER NOT NULL DEFAULT 0,
      lastError TEXT
    );

    CREATE TABLE IF NOT EXISTS sync_state (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
  `);
}

export function run(sql: string, params: any[] = []) {
  return db.runSync(sql, params);
}

export function getAll<T = any>(sql: string, params: any[] = []): T[] {
  return db.getAllSync(sql, params) as T[];
}

export function getOne<T = any>(sql: string, params: any[] = []): T | null {
  return db.getFirstSync(sql, params) as T | null;
}
