## Survey repository
```ts
// surveyRepository.ts
import { run, getAll, getOne } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  siteId: string;
  observerId: string;
  timestamp: string;
  latitude?: number;
  longitude?: number;
  notes?: string;
  status: string;
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
  syncedAt?: string | null;
};

export function createSurvey(input: Omit<Survey, 'id' | 'version' | 'updatedAt' | 'deletedAt' | 'syncedAt'>) {
  const id = uuidv4();
  const now = new Date().toISOString();

  run(
    `INSERT INTO surveys (id, siteId, observerId, timestamp, latitude, longitude, notes, status, version, updatedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [id, input.siteId, input.observerId, input.timestamp, input.latitude ?? null, input.longitude ?? null, input.notes ?? null, input.status, 1, now]
  );

  run(
    `INSERT INTO pending_operations (id, entityType, entityId, operation, payload, baseVersion, createdAt)
     VALUES (?, 'survey', ?, 'create', ?, ?, ?)`,
    [uuidv4(), id, JSON.stringify({ ...input, id }), 0, now]
  );

  return id;
}

export function updateSurvey(id: string, patch: Partial<Survey>) {
  const existing = getOne<Survey>(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated = { ...existing, ...patch, updatedAt: now, version: existing.version + 1 };

  run(
    `UPDATE surveys
     SET siteId = ?, observerId = ?, timestamp = ?, latitude = ?, longitude = ?, notes = ?, status = ?, version = ?, updatedAt = ?
     WHERE id = ?`,
    [
      updated.siteId,
      updated.observerId,
      updated.timestamp,
      updated.latitude ?? null,
      updated.longitude ?? null,
      updated.notes ?? null,
      updated.status,
      updated.version,
      updated.updatedAt,
      id,
    ]
  );

  run(
    `INSERT INTO pending_operations (id, entityType, entityId, operation, payload, baseVersion, createdAt)
     VALUES (?, 'survey', ?, 'update', ?, ?, ?)`,
    [uuidv4(), id, JSON.stringify(patch), existing.version, now]
  );
}

export function deleteSurvey(id: string) {
  const existing = getOne<Survey>(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();

  run(`UPDATE surveys SET deletedAt = ?, updatedAt = ?, version = version + 1 WHERE id = ?`, [now, now, id]);

  run(
    `INSERT INTO pending_operations (id, entityType, entityId, operation, payload, baseVersion, createdAt)
     VALUES (?, 'survey', ?, 'delete', ?, ?, ?)`,
    [uuidv4(), id, JSON.stringify({ deletedAt: now }), existing.version, now]
  );
}

export function listSurveys() {
  return getAll<Survey>(`SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`);
}
