# 7) Sync engine

```ts
// syncEngine.ts
import NetInfo from '@react-native-community/netinfo';
import { getAll, run, getOne } from './db';

const API_BASE = 'https://your-api.example.com';

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const pending = getAll<any>(`SELECT * FROM pending_operations ORDER BY createdAt ASC`);
  if (pending.length > 0) {
    const res = await fetch(`${API_BASE}/sync/push`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ operations: pending }),
    });

    if (!res.ok) throw new Error(`Push failed: ${res.status}`);
    const data = await res.json();

    for (const ack of data.acknowledged) {
      run(`DELETE FROM pending_operations WHERE id = ?`, [ack.operationId]);

      if (ack.entityType === 'survey' && ack.entity) {
        const e = ack.entity;
        run(
          `UPDATE surveys
           SET siteId = ?, observerId = ?, timestamp = ?, latitude = ?, longitude = ?, notes = ?, status = ?, version = ?, updatedAt = ?, deletedAt = ?, syncedAt = ?
           WHERE id = ?`,
          [
            e.siteId,
            e.observerId,
            e.timestamp,
            e.latitude ?? null,
            e.longitude ?? null,
            e.notes ?? null,
            e.status,
            e.version,
            e.updatedAt,
            e.deletedAt ?? null,
            new Date().toISOString(),
            e.id,
          ]
        );
      }
    }

    for (const conflict of data.conflicts ?? []) {
      run(`UPDATE pending_operations SET retryCount = retryCount + 1, lastError = ? WHERE id = ?`, [
        conflict.reason,
        conflict.operationId,
      ]);
    }
  }

  const lastPullToken = getOne<{ value: string }>(`SELECT value FROM sync_state WHERE key = 'lastPullToken'`);
  const pullRes = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(lastPullToken?.value ?? '')}`);
  if (!pullRes.ok) throw new Error(`Pull failed: ${pullRes.status}`);

  const pullData = await pullRes.json();

  for (const survey of pullData.surveys ?? []) {
    run(
      `INSERT INTO surveys (id, siteId, observerId, timestamp, latitude, longitude, notes, status, version, updatedAt, deletedAt, syncedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         siteId=excluded.siteId,
         observerId=excluded.observerId,
         timestamp=excluded.timestamp,
         latitude=excluded.latitude,
         longitude=excluded.longitude,
         notes=excluded.notes,
         status=excluded.status,
         version=excluded.version,
         updatedAt=excluded.updatedAt,
         deletedAt=excluded.deletedAt,
         syncedAt=excluded.syncedAt`,
      [
        survey.id,
        survey.siteId,
        survey.observerId,
        survey.timestamp,
        survey.latitude ?? null,
        survey.longitude ?? null,
        survey.notes ?? null,
        survey.status,
        survey.version,
        survey.updatedAt,
        survey.deletedAt ?? null,
        new Date().toISOString(),
      ]
    );
  }

  if (pullData.nextToken) {
    run(
      `INSERT INTO sync_state (key, value) VALUES ('lastPullToken', ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      [pullData.nextToken]
    );
  }
}
