### `server/src/db.ts`
A simple in-memory DB for initial implementation. Replace with PostgreSQL later.

```ts
export type Survey = {
  id: string;
  siteId: string;
  observerName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  status: 'draft' | 'submitted' | 'verified';
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
};

const surveys = new Map<string, Survey>();

export function listSurveysSince(since: string | null): Survey[] {
  const sinceDate = since ? new Date(since).getTime() : 0;
  return [...surveys.values()].filter((s) => new Date(s.updatedAt).getTime() > sinceDate);
}

export function upsertSurvey(survey: Survey): Survey {
  const existing = surveys.get(survey.id);

  if (!existing) {
    surveys.set(survey.id, survey);
    return survey;
  }

  // Simple conflict rule: higher version wins
  if (survey.version >= existing.version) {
    surveys.set(survey.id, survey);
    return survey;
  }

  return existing;
}

export function getSurvey(id: string): Survey | undefined {
  return surveys.get(id);
}

export function seedSurvey(s: Survey) {
  surveys.set(s.id, s);
}
```

