import { Router } from 'express';
import { getSurvey, listSurveysSince, upsertSurvey } from '../db';

export const surveyRouter = Router();

// Pull updates since last sync
surveyRouter.get('/changes', (req, res) => {
  const since = (req.query.since as string) || null;
  const changes = listSurveysSince(since);
  res.json({ changes, serverTime: new Date().toISOString() });
});

// Push local changes
surveyRouter.post('/sync', (req, res) => {
  const { changes } = req.body as { changes: any[] };

  const results = changes.map((change) => {
    const existing = getSurvey(change.id);

    // Basic conflict detection
    if (existing && existing.version > change.version) {
      return {
        id: change.id,
        status: 'conflict',
        serverRecord: existing,
      };
    }

    const saved = upsertSurvey({
      ...change,
      version: (existing?.version || 0) + 1,
      updatedAt: new Date().toISOString(),
    });

    return {
      id: change.id,
      status: 'ok',
      record: saved,
    };
  });

  res.json({
    results,
    serverTime: new Date().toISOString(),
  });
});
