## 6) Sync engine

### `client/src/sync.ts`

```ts
import { db, Survey } from './db';
import { pullChanges, pushChanges } from './api';

export async function saveSurveyLocally(survey: Survey) {
  await db.surveys.put(survey);
  await db.outbox.add({
    entityType: 'survey',
    entityId: survey.id,
    operation: 'upsert',
    payload: survey,
    createdAt: new Date().toISOString(),
  });
}

export async function syncNow() {
  const lastSync = (await db.meta.get('lastSync'))?.value || null;

  // 1) Push outbox items
  const pending = await db.outbox.orderBy('createdAt').toArray();
  if (pending.length > 0) {
    const result = await pushChanges(pending.map((item) => item.payload));

    // Remove successfully synced items
    const okIds = new Set(
      result.results
        .filter((r: any) => r.status === 'ok')
        .map((r: any) => r.id)
    );

    for (const item of pending) {
      if (okIds.has(item.entityId)) {
        await db.outbox.delete(item.id!);
      }
    }

    // Handle conflicts
    const conflicts = result.results.filter((r: any) => r.status === 'conflict');
    for (const conflict of conflicts) {
      console.warn('Conflict detected for', conflict.id, conflict.serverRecord);
      // Initial strategy: keep server version locally and notify user
      await db.surveys.put(conflict.serverRecord);
      await db.outbox.delete(
        pending.find((p) => p.entityId === conflict.id)?.id!
      );
    }
  }

  // 2) Pull server changes
  const pulled = await pullChanges(lastSync);
  for (const change of pulled.changes) {
    await db.surveys.put(change);
  }

  // 3) Update last sync time
  await db.meta.put({
    key: 'lastSync',
    value: pulled.serverTime,
  });
}
```

