export async function updateSurvey(
  id: string,
  updates: {
    title?: string;
    locationLat?: number;
    locationLng?: number;
    notes?: string;
  }
) {
  const db = getDb();
  const now = Date.now();

  const existing = db.getFirstSync<{ version: number }>(
    `SELECT version FROM surveys WHERE id = ?`,
    [id]
  );

  if (!existing) throw new Error('Survey not found');

  db.runSync(
    `UPDATE surveys SET
      title = COALESCE(?, title),
      location_lat = COALESCE(?, location_lat),
      location_lng = COALESCE(?, location_lng),
      notes = COALESCE(?, notes),
      updated_at = ?,
      version = version + 1,
      sync_status = 'pending'
     WHERE id = ?`,
    [
      updates.title ?? null,
      updates.locationLat ?? null,
      updates.locationLng ?? null,
      updates.notes ?? null,
      now,
      id,
    ]
  );

  db.runSync(
    `INSERT INTO sync_queue (
      id, entity_type, entity_id, operation, payload, created_at
    ) VALUES (?, ?, ?, ?, ?, ?)`,
