## `syncService.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';

const API_BASE = 'https://api.example.com';

async function postJson(path: string, body: any) {
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      // Authorization: `Bearer ...`
    },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    throw new Error(`HTTP ${res.status}`);
  }

  return res.json();
}

async function getJson(path: string) {
  const res = await fetch(`${API_BASE}${path}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

export async function syncNow() {
  const db = getDb();

  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  // 1. Push queued mutations
  const mutations = db.getAllSync<any>(
    `SELECT * FROM sync_queue ORDER BY created_at ASC LIMIT 100`
  );

  if (mutations.length > 0) {
    const payload = {
      deviceId: 'device-123',
      mutations: mutations.map((m) => ({
        mutationId: m.id,
        entityType: m.entity_type,
        entityId: m.entity_id,
        operation: m.operation,
        payload: JSON.parse(m.payload),
      })),
    };

    const result = await postJson('/sync/push', payload);

    for (const r of result.results ?? []) {
      if (r.status === 'ok') {
        db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [r.mutationId]);

        db.runSync(
          `UPDATE surveys
           SET server_id = COALESCE(?, server_id),
               version = ?,
               updated_at = ?,
               sync_status = 'synced'
           WHERE id = ?`,
          [r.serverId ?? null, r.version, r.updatedAt, mutations.find((m: any) => m.id === r.mutationId)?.entity_id]
        );
      } else if (r.status === 'conflict') {
        db.runSync(
          `UPDATE surveys SET sync_status = 'conflict' WHERE id = ?`,
          [mutations.find((m: any) => m.id === r.mutationId)?.entity_id]
        );
      }
    }
  }

  // 2. Pull remote changes
  const lastTokenRow = db.getFirstSync<{ value: string }>(
    `SELECT value FROM sync_state WHERE key = 'last_sync_token'`
  );

  const since = lastTokenRow?.value ?? '';
  const pull = await getJson(`/sync/pull?since=${encodeURIComponent(since)}`);

  for (const change of pull.changes ?? []) {
    if (change.entityType === 'survey') {
      const existing = db.getFirstSync<any>(
        `SELECT id FROM surveys WHERE server_id = ?`,
        [change.serverId]
      );

      if (change.operation === 'delete') {
        if (existing) {
          db.runSync(`UPDATE surveys SET deleted_at = ?, sync_status = 'synced' WHERE id = ?`, [
            change.updatedAt,
            existing.id,
          ]);
        }
      } else {
        if (existing) {
          db.runSync(
            `UPDATE surveys SET
               title = ?,
               notes = ?,
               version = ?,
               updated_at = ?,
               sync_status = 'synced'
             WHERE id = ?`,
            [
              change.payload.title,
              change.payload.notes ?? null,
              change.version,
              change.updatedAt,
              existing.id,
            ]
          );
        } else {
          db.runSync(
            `INSERT INTO surveys (
               id, server_id, title, notes, updated_at, created_at,
               version, sync_status
             ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              change.payload.id ?? change.serverId,
              change.serverId,
              change.payload.title,
              change.payload.notes ?? null,
              change.updatedAt,
              change.updatedAt,
              change.version,
              'synced',
            ]
          );
        }
      }
    }
  }

  db.runSync(
    `INSERT OR REPLACE INTO sync_state (key, value) VALUES ('last_sync_token', ?)`,
    [pull.nextToken ?? since]
  );
}
```

