## `server.js`
```js
const express = require('express');
const app = express();

app.use(express.json());

const surveys = new Map(); // replace with real DB
const changes = [];
let syncToken = 1;

app.post('/sync/push', (req, res) => {
  const { mutations } = req.body;
  const results = [];

  for (const m of mutations) {
    if (m.entityType !== 'survey') continue;

    if (m.operation === 'create') {
      const serverId = `srv-${Math.floor(Math.random() * 100000)}`;
      const version = 1;

      surveys.set(serverId, {
        serverId,
        ...m.payload,
        version,
        updatedAt: Date.now(),
      });

      changes.push({
        token: syncToken++,
        entityType: 'survey',
        operation: 'create',
        serverId,
        payload: m.payload,
        version,
        updatedAt: Date.now(),
      });

      results.push({
        mutationId: m.mutationId,
        status: 'ok',
        serverId,
        version,
        updatedAt: Date.now(),
      });
    } else if (m.operation === 'update') {
      // naive example: accept all updates
      results.push({
        mutationId: m.mutationId,
        status: 'ok',
        version: 2,
        updatedAt: Date.now(),
      });
    } else if (m.operation === 'delete') {
      results.push({
        mutationId: m.mutationId,
        status: 'ok',
        updatedAt: Date.now(),
      });
    }
  }

  res.json({ results });
});

app.get('/sync/pull', (req, res) => {
  const since = Number(req.query.since || 0);
  const newChanges = changes.filter((c) => c.token > since);

  res.json({
    nextToken: syncToken - 1,
    changes: newChanges,
  });
});

app.listen(3000, () => console.log('Server running on 3000'));
