## 6) Sync engine

The sync engine:
- checks network state
- pulls unsynced local mutations from outbox
- sends them to backend
- applies server response
- retries failures with backoff

### Network listener

```ts
import NetInfo from '@react-native-community/netinfo';

export function startNetworkSyncListener(syncNow: () => Promise<void>) {
  return NetInfo.addEventListener(state => {
    if (state.isConnected && state.isInternetReachable) {
      syncNow().catch(console.error);
    }
  });
}
```

### Sync function

```ts
export async function syncOutbox() {
  const pending = db.getAllSync(`
    SELECT * FROM outbox ORDER BY createdAt ASC
  `) as any[];

  if (!pending.length) return;

  for (const item of pending) {
    try {
      const response = await fetch('https://api.example.com/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${await getAuthToken()}`,
        },
        body: JSON.stringify({
          mutationId: item.id,
          entityType: item.entityType,
          entityId: item.entityId,
          operation: item.operation,
          payload: JSON.parse(item.payload),
        }),
      });

      if (!response.ok) {
        throw new Error(`Sync failed: ${response.status}`);
      }

      const result = await response.json();

      // Apply canonical server state if returned
      if (result.entity) {
        const e = result.entity;
        db.runSync(
          `UPDATE surveys
           SET siteName = ?, latitude = ?, longitude = ?, notes = ?, status = ?, updatedAt = ?, version = ?, deletedAt = ?
           WHERE id = ?`,
          [
            e.siteName,
            e.latitude,
            e.longitude,
            e.notes ?? null,
            e.status,
            e.updatedAt,
            e.version,
            e.deletedAt ?? null,
            e.id,
          ]
        );
      }

      db.runSync(`DELETE FROM outbox WHERE id = ?`, [item.id]);
    } catch (error: any) {
      db.runSync(
        `UPDATE outbox SET retryCount = retryCount + 1, lastError = ? WHERE id = ?`,
        [error.message ?? 'Unknown error', item.id]
      );
    }
  }
}
```

