import Dexie, { Table } from "dexie";

export type SyncStatus = "pending" | "synced" | "error";

export interface SurveyRecord {
  id: string;
  projectId: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photos?: string[]; // local URLs or base64 for initial version
  updatedAt: string;
  syncStatus: SyncStatus;
  deleted?: boolean;
}

export interface OutboxItem {
  id?: number;
  entityType: "survey";
  entityId: string;
  operation: "create" | "update" | "delete";
  payload: any;
  createdAt: string;
  retryCount: number;
  lastError?: string;
}

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  outbox!: Table<OutboxItem, number>;

  constructor() {
    super("survey-db");
    this.version(1).stores({
      surveys: "id, projectId, syncStatus, updatedAt, deleted",
      outbox: "++id, entityType, entityId, operation, createdAt, retryCount",
    });
  }
}

export const db = new SurveyDB();
