## `src/api.ts`
Simple API client for syncing.

```ts
import { SurveyRecord } from "./db";

const API_BASE = "http://localhost:4000/api";

export async function pushSurveyMutation(
  operation: "create" | "update" | "delete",
  record: SurveyRecord
) {
  const url =
    operation === "create"
      ? `${API_BASE}/surveys`
      : `${API_BASE}/surveys/${record.id}`;

  const method =
    operation === "create" ? "POST" : operation === "update" ? "PUT" : "DELETE";

  const body =
    operation === "delete"
      ? undefined
      : JSON.stringify(record);

  const res = await fetch(url, {
    method,
    headers: {
      "Content-Type": "application/json",
    },
    body,
  });

  if (!res.ok) {
    throw new Error(`Sync failed: ${res.status}`);
  }

  return res.json();
}

export async function fetchServerSurveys() {
  const res = await fetch(`${API_BASE}/surveys`);
  if (!res.ok) throw new Error("Failed to fetch surveys");
  return res.json();
}
