## `src/sync.ts`
Sync logic for the outbox.

```ts
import { db } from "./db";
import { pushSurveyMutation } from "./api";

export async function syncOutbox() {
  const items = await db.outbox.orderBy("createdAt").toArray();

  for (const item of items) {
    try {
      const record = await db.surveys.get(item.entityId);
      if (!record && item.operation !== "delete") {
        await db.outbox.delete(item.id!);
        continue;
      }

      if (item.operation === "delete") {
        await pushSurveyMutation("delete", {
          id: item.entityId,
          projectId: "",
          siteName: "",
          latitude: 0,
          longitude: 0,
          updatedAt: new Date().toISOString(),
          syncStatus: "synced",
        });
        await db.outbox.delete(item.id!);
        continue;
      }

      if (record) {
        await pushSurveyMutation(item.operation, record);
        await db.surveys.update(record.id, { syncStatus: "synced" });
      }

      await db.outbox.delete(item.id!);
    } catch (error: any) {
      await db.outbox.update(item.id!, {
        retryCount: item.retryCount + 1,
        lastError: error?.message ?? "Unknown sync error",
      });
    }
  }
}
```

