```tsx
import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { db, SurveyRecord } from "./db";
import { useOnlineSync } from "./useOnlineSync";

export default function App() {
  useOnlineSync();

  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [siteName, setSiteName] = useState("");
  const [notes, setNotes] = useState("");
  const [latitude, setLatitude] = useState<number>(0);
  const [longitude, setLongitude] = useState<number>(0);

  async function loadSurveys() {
    const items = await db.surveys.where("deleted").notEqual(true).toArray();
    setSurveys(items);
  }

  useEffect(() => {
    loadSurveys();
  }, []);

  async function addSurvey() {
    const id = uuidv4();
    const record: SurveyRecord = {
      id,
      projectId: "default-project",
      siteName,
      notes,
      latitude,
      longitude,
      updatedAt: new Date().toISOString(),
      syncStatus: "pending",
    };

    await db.surveys.put(record);
    await db.outbox.add({
      entityType: "survey",
      entityId: id,
      operation: "create",
      payload: record,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });

    setSiteName("");
    setNotes("");
    setLatitude(0);
    setLongitude(0);
    await loadSurveys();
  }

  async function markDeleted(id: string) {
    const record = await db.surveys.get(id);
    if (!record) return;

    await db.surveys.update(id, {
      deleted: true,
      syncStatus: "pending",
      updatedAt: new Date().toISOString(),
    });

    await db.outbox.add({
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: { id },
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });

    await loadSurveys();
  }

  return (
    <div style={{ padding: 24, maxWidth: 800 }}>
      <h1>Field Survey App</h1>
      <p>
        Status: {navigator.onLine ? "Online" : "Offline"}{" "}
        <button onClick={() => window.location.reload()}>Refresh</button>
      </p>

      <section style={{ marginBottom: 24 }}>
        <h2>New Survey</h2>
        <input
          placeholder="Site name"
          value={siteName}
          onChange={(e) => setSiteName(e.target.value)}
        />
        <br />
        <input
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <br />
        <input
          type="number"
          placeholder="Latitude"
          value={latitude}
          onChange={(e) => setLatitude(Number(e.target.value))}
        />
        <br />
        <input
          type="number"
          placeholder="Longitude"
          value={longitude}
          onChange={(e) => setLongitude(Number(e.target.value))}
        />
        <br />
        <button onClick={addSurvey}>Save Survey</button>
      </section>

      <section>
        <h2>Local Surveys</h2>
        <ul>
          {surveys.map((s) => (
            <li key={s.id}>
              <strong>{s.siteName}</strong> — {s.notes} —{" "}
              {s.syncStatus}{" "}
              <button onClick={() => markDeleted(s.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}
