import express from "express";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

type Survey = {
  id: string;
  projectId: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photos?: string[];
  updatedAt: string;
};

const surveys = new Map<string, Survey>();

app.get("/api/surveys", (_req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post("/api/surveys", (req, res) => {
  const survey: Survey = req.body;
  surveys.set(survey.id, survey);
  res.status(201).json({ ok: true, survey });
});

app.put("/api/surveys/:id", (req, res) => {
  const id = req.params.id;
  const survey: Survey = req.body;
  surveys.set(id, { ...survey, id });
  res.json({ ok: true, survey: surveys.get(id) });
});

app.delete("/api/surveys/:id", (req, res) => {
  surveys.delete(req.params.id);
  res.json({ ok: true });
});

app.listen(4000, () => {
  console.log("API running on http://localhost:4000");
});
