## 6) Initial implementation: local DB + outbox

Below is a simple TypeScript-style implementation using a local storage abstraction. You can adapt it to SQLite/IndexedDB.

### `types.ts`

```ts
export type Survey = {
  id: string;
  serverId?: string;
  title: string;
  description?: string;
  latitude: number;
  longitude: number;
  photos: string[];
  status: 'draft' | 'submitted' | 'synced';
  updatedAt: string;
  createdAt: string;
  version: number;
  deleted?: boolean;
};

export type PendingMutation = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: Partial<Survey>;
  createdAt: string;
  retries: number;
  lastError?: string;
};

export type SyncResult = {
  mutationId: string;
