```ts
import { Survey, PendingMutation } from './types';

class LocalStore {
  private surveys = new Map<string, Survey>();
  private outbox: PendingMutation[] = [];

  async getSurvey(id: string): Promise<Survey | undefined> {
    return this.surveys.get(id);
  }

  async upsertSurvey(survey: Survey): Promise<void> {
    this.surveys.set(survey.id, survey);
  }

  async deleteSurvey(id: string): Promise<void> {
    const existing = this.surveys.get(id);
    if (existing) {
      this.surveys.set(id, { ...existing, deleted: true, updatedAt: new Date().toISOString() });
    }
  }

  async listSurveys(): Promise<Survey[]> {
    return [...this.surveys.values()].filter(s => !s.deleted);
  }

  async addToOutbox(mutation: PendingMutation): Promise<void> {
    this.outbox.push(mutation);
  }

  async getOutbox(): Promise<PendingMutation[]> {
    return [...this.outbox];
  }

  async removeOutboxMutation(id: string): Promise<void> {
    this.outbox = this.outbox.filter(m => m.id !== id);
  }

  async updateOutboxMutation(id: string, patch: Partial<PendingMutation>): Promise<void> {
    this.outbox = this.outbox.map(m => (m.id === id ? { ...m, ...patch } : m));
  }
}

export const localStore = new LocalStore();
```

