### `surveyService.ts`

```ts
import { localStore } from './localStore';
import { PendingMutation, Survey } from './types';

const uuid = () => crypto.randomUUID();

export async function createSurvey(input: Omit<Survey, 'id' | 'createdAt' | 'updatedAt' | 'version' | 'status'>) {
  const now = new Date().toISOString();
  const survey: Survey = {
    id: uuid(),
    ...input,
    status: 'draft',
    createdAt: now,
    updatedAt: now,
    version: 1,
  };

  await localStore.upsertSurvey(survey);

  const mutation: PendingMutation = {
    id: uuid(),
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    createdAt: now,
    retries: 0,
  };

  await localStore.addToOutbox(mutation);

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Survey>) {
  const existing = await localStore.getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const updated: Survey = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await localStore.upsertSurvey(updated);

  const mutation: PendingMutation = {
    id: uuid(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: patch,
    createdAt: new Date().toISOString(),
    retries: 0,
  };

  await localStore.addToOutbox(mutation);

  return updated;
}

export async function deleteSurvey(id: string) {
  await localStore.deleteSurvey(id);

  const mutation: PendingMutation = {
    id: uuid(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { deleted: true },
    createdAt: new Date().toISOString(),
    retries: 0,
  };

  await localStore.addToOutbox(mutation);
}
