## 7) Sync engine

### `syncService.ts`

```ts
import { localStore } from './localStore';
import { PendingMutation, SyncResult, Survey } from './types';

const API_URL = 'https://your-api.example.com/api/surveys/sync';

async function postMutations(mutations: PendingMutation[]) {
  const res = await fetch(API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      deviceId: 'device-123',
      mutations,
    }),
  });

  if (!res.ok) throw new Error(`Sync failed: ${res.status}`);
  return res.json();
}

export async function syncOutbox() {
  const outbox = await localStore.getOutbox();
  if (outbox.length === 0) return { synced: 0 };

  try {
    const response: { results: SyncResult[] } = await postMutations(outbox);

    for (const result of response.results) {
      const mutation = outbox.find(m => m.id === result.mutationId);
      if (!mutation) continue;

      if (result.status === 'applied' && result.serverRecord) {
        await localStore.upsertSurvey({
          ...result.serverRecord,
          status: 'synced',
        } as Survey);

        await localStore.removeOutboxMutation(mutation.id);
      } else if (result.status === 'conflict') {
        await localStore.updateOutboxMutation(mutation.id, {
          retries: mutation.retries + 1,
          lastError: result.error || 'Conflict detected',
        });
      } else {
        await localStore.updateOutboxMutation(mutation.id, {
          retries: mutation.retries + 1,
          lastError: result.error || 'Unknown sync failure',
        });
      }
    }

    return { synced: response.results.filter(r => r.status === 'applied').length };
  } catch (err: any) {
    // If offline or server unreachable, keep outbox intact
    return { synced: 0, error: err.message };
  }
}
```

