## 10) Backend initial implementation

Here’s a simple Express server that accepts mutations and stores surveys in memory or PostgreSQL later.

### `server.ts`

```ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.post('/api/surveys/sync', (req, res) => {
  const { mutations } = req.body;

  const results = mutations.map((m: any) => {
    if (m.operation === 'delete') {
      surveys.delete(m.entityId);
      return { mutationId: m.id, status: 'applied' };
    }

    const payload = m.payload || {};
    const existing = surveys.get(m.entityId);

    const serverRecord = {
      serverId: existing?.serverId || `srv-${Math.floor(Math.random() * 100000)}`,
      clientId: m.entityId,
      version: (existing?.version || 0) + 1,
      ...existing,
      ...payload,
      updatedAt: new Date().toISOString(),
    };

    surveys.set(m.entityId, serverRecord);

    return {
      mutationId: m.id,
      status: 'applied',
      serverRecord,
    };
  });

  res.json({ results });
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

