# 7) Sync engine

This is the heart of offline-first behavior.

## `src/api/sync.ts`

```ts
import { db } from '../db/schema';
import { apiClient } from './client';
import { OutboxItem, SurveyRecord } from '../types/survey';

export async function syncOutbox() {
  const pendingItems = await db.outbox.where('status').equals('pending').sortBy('createdAt');

  for (const item of pendingItems) {
    try {
      if (item.entityType === 'surveyRecord') {
        if (item.operation === 'create') {
          await apiClient.createSurveyRecord(item.payload);
        } else if (item.operation === 'update') {
          await apiClient.updateSurveyRecord(item.entityId, item.payload);
        } else if (item.operation === 'delete') {
          await apiClient.deleteSurveyRecord(item.entityId);
        }
      }

      await db.outbox.update(item.id, { status: 'sent' });

      if (item.operation === 'delete') {
        await db.surveyRecords.delete(item.entityId);
      } else {
        const local = await db.surveyRecords.get(item.entityId);
        if (local) {
          await db.surveyRecords.update(item.entityId, { syncStatus: 'synced' });
        }
      }
    } catch (error) {
      await db.outbox.update(item.id, {
        retries: item.retries + 1,
        status: item.retries >= 3 ? 'failed' : 'pending',
      });

      if (item.entityId) {
        await db.surveyRecords.update(item.entityId, { syncStatus: 'error' });
      }
    }
  }
}

export async function pullLatestRecords() {
  const remoteRecords: SurveyRecord[] = await apiClient.getSurveyRecords();

  for (const record of remoteRecords) {
    const local = await db.surveyRecords.get(record.id);

    if (!local || new Date(record.updatedAt) > new Date(local.updatedAt)) {
      await db.surveyRecords.put({
        ...record,
        syncStatus: 'synced',
      });
    }
  }
}
```

