# 9) Survey CRUD hook

## `src/hooks/useSurveyRecords.ts`

```ts
import { useEffect, useState } from 'react';
import { db } from '../db/schema';
import { SurveyRecord } from '../types/survey';
import { syncOutbox, pullLatestRecords } from '../api/sync';

export function useSurveyRecords(isOnline: boolean) {
  const [records, setRecords] = useState<SurveyRecord[]>([]);

  const loadRecords = async () => {
    const all = await db.surveyRecords.orderBy('updatedAt').reverse().toArray();
    setRecords(all);
  };

  useEffect(() => {
    loadRecords();
  }, []);

  useEffect(() => {
    const handleSync = async () => {
      if (isOnline) {
        await syncOutbox();
        await pullLatestRecords();
        await loadRecords();
      }
    };

    handleSync();
  }, [isOnline]);

  const saveRecord = async (record: SurveyRecord) => {
    const now = new Date().toISOString();
    const existing = await db.surveyRecords.get(record.id);

    const updatedRecord: SurveyRecord = {
      ...record,
      updatedAt: now,
      syncStatus: isOnline ? 'synced' : 'pending',
    };

    await db.surveyRecords.put(updatedRecord);

    await db.outbox.add({
      id: crypto.randomUUID(),
      entityType: 'surveyRecord',
      entityId: record.id,
      operation: existing ? 'update' : 'create',
      payload: updatedRecord,
      createdAt: now,
      retries: 0,
      status: 'pending',
    });

    setRecords(await db.surveyRecords.orderBy('updatedAt').reverse().toArray());
  };

  const deleteRecord = async (id: string) => {
    const now = new Date().toISOString();

    await db.outbox.add({
      id: crypto.randomUUID(),
      entityType: 'surveyRecord',
      entityId: id,
      operation: 'delete',
      payload: null,
      createdAt: now,
      retries: 0,
      status: 'pending',
    });

    await db.surveyRecords.delete(id);
    setRecords(await db.surveyRecords.orderBy('updatedAt').reverse().toArray());
  };

  return { records, saveRecord, deleteRecord, reload: loadRecords };
}
```

