# 12) Initial backend API

A minimal Node/Express backend.

## `server/index.ts`

```ts
import express from 'express';
import cors from 'cors';
import { randomUUID } from 'crypto';

const app = express();
app.use(cors());
app.use(express.json());

type SurveyRecord = {
  id: string;
  projectId: string;
  fieldAgentId: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  createdAt: string;
  updatedAt: string;
};

const records = new Map<string, SurveyRecord>();

app.get('/survey-records', (_req, res) => {
  res.json(Array.from(records.values()));
});

app.post('/survey-records', (req, res) => {
  const record: SurveyRecord = {
    id: req.body.id || randomUUID(),
    ...req.body,
  };
  records.set(record.id, record);
  res.status(201).json(record);
});

app.put('/survey-records/:id', (req, res) => {
  const id = req.params.id;
  const existing = records.get(id);

  if (!existing) {
    return res.status(404).json({ error: 'Not found' });
  }

  const updated = { ...existing, ...req.body, id };
  records.set(id, updated);
  res.json(updated);
});

app.delete('/survey-records/:id', (req, res) => {
  records.delete(req.params.id);
  res.status(204).send();
});

app.listen(3000, () => {
  console.log('API listening on http://localhost:3000');
});
```

