### `src/db/surveyRepo.ts`

```ts
import db from './index';
import { SurveyRecord } from '../types/survey';

export const surveyRepo = {
  upsert(record: SurveyRecord) {
    db.runSync(
      `INSERT INTO surveys (
        id, siteId, surveyorId, title, notes, latitude, longitude,
        photos, status, createdAt, updatedAt, deletedAt, version
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        siteId=excluded.siteId,
        surveyorId=excluded.surveyorId,
        title=excluded.title,
        notes=excluded.notes,
        latitude=excluded.latitude,
        longitude=excluded.longitude,
        photos=excluded.photos,
        status=excluded.status,
        createdAt=excluded.createdAt,
        updatedAt=excluded.updatedAt,
        deletedAt=excluded.deletedAt,
        version=excluded.version`,
      [
        record.id,
        record.siteId,
        record.surveyorId,
        record.title,
        record.notes ?? null,
        record.latitude ?? null,
        record.longitude ?? null,
        JSON.stringify(record.photos ?? []),
        record.status,
        record.createdAt,
        record.updatedAt,
        record.deletedAt ?? null,
        record.version,
      ]
    );
  },

  getAll(): SurveyRecord[] {
    const rows = db.getAllSync<any>(`SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`);
    return rows.map((r) => ({
      ...r,
      photos: JSON.parse(r.photos || '[]'),
    }));
  },

  getById(id: string): SurveyRecord | null {
    const row = db.getFirstSync<any>(`SELECT * FROM surveys WHERE id = ?`, [id]);
    if (!row) return null;
    return { ...row, photos: JSON.parse(row.photos || '[]') };
  },
};
```

