### `src/db/queueRepo.ts`

```ts
import db from './index';
import { PendingOperation } from '../types/survey';

export const queueRepo = {
  add(op: PendingOperation) {
    db.runSync(
      `INSERT INTO pending_operations (
        id, entityType, entityId, operation, payload, createdAt, retryCount, lastError
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        op.id,
        op.entityType,
        op.entityId,
        op.operation,
        JSON.stringify(op.payload),
        op.createdAt,
        op.retryCount,
        op.lastError ?? null,
      ]
    );
  },

  getAll(): PendingOperation[] {
    const rows = db.getAllSync<any>(`SELECT * FROM pending_operations ORDER BY createdAt ASC`);
    return rows.map((r) => ({
      ...r,
      payload: JSON.parse(r.payload),
    }));
  },

  remove(id: string) {
    db.runSync(`DELETE FROM pending_operations WHERE id = ?`, [id]);
  },

  incrementRetry(id: string, error: string) {
    db.runSync(
      `UPDATE pending_operations
       SET retryCount = retryCount + 1, lastError = ?
       WHERE id = ?`,
      [error, id]
    );
  },
};
```

