### `src/api/sync.ts`

```ts
import { apiFetch } from './client';
import { queueRepo } from '../db/queueRepo';
import { surveyRepo } from '../db/surveyRepo';
import db from '../db';

export async function syncPendingOperations() {
  const ops = queueRepo.getAll();

  for (const op of ops) {
    try {
      if (op.entityType === 'survey') {
        if (op.operation === 'create') {
          const created = await apiFetch('/surveys', {
            method: 'POST',
            body: JSON.stringify(op.payload),
          });
          surveyRepo.upsert(created);
        } else if (op.operation === 'update') {
          const updated = await apiFetch(`/surveys/${op.entityId}`, {
            method: 'PUT',
            body: JSON.stringify(op.payload),
          });
          surveyRepo.upsert(updated);
        } else if (op.operation === 'delete') {
          await apiFetch(`/surveys/${op.entityId}`, {
            method: 'DELETE',
          });
        }
      }

      queueRepo.remove(op.id);
    } catch (err: any) {
      queueRepo.incrementRetry(op.id, err.message || 'Sync failed');
    }
  }
}

export async function pullRemoteUpdates(lastSyncAt: string | null) {
  const query = lastSyncAt ? `?since=${encodeURIComponent(lastSyncAt)}` : '';
  const updates = await apiFetch(`/surveys/changes${query}`);

  for (const record of updates) {
    surveyRepo.upsert(record);
  }

  const now = new Date().toISOString();
  db.runSync(
    `INSERT INTO sync_state (key, value) VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    ['lastSyncAt', now]
  );
}

export function getLastSyncAt(): string | null {
  const row = db.getFirstSync<any>(`SELECT value FROM sync_state WHERE key = ?`, ['lastSyncAt']);
  return row?.value ?? null;
}
```

