### `src/hooks/useSync.ts`

```ts
import { useEffect } from 'react';
import { syncPendingOperations, pullRemoteUpdates, getLastSyncAt } from '../api/sync';

export function useSync(isOnline: boolean) {
  useEffect(() => {
    if (!isOnline) return;

    let cancelled = false;

    const run = async () => {
      if (cancelled) return;
      const lastSyncAt = getLastSyncAt();
      await syncPendingOperations();
      await pullRemoteUpdates(lastSyncAt);
    };

    run();

    return () => {
      cancelled = true;
    };
  }, [isOnline]);
}
```

