## Survey service

```ts
export class SurveyService {
  constructor(private store: LocalStore) {}

  async createSurvey(title: string): Promise<Survey> {
    const now = new Date().toISOString();
    const survey: Survey = {
      id: crypto.randomUUID(),
      title,
      status: "draft",
      createdAt: now,
      updatedAt: now,
      version: 1,
      deleted: false,
    };

    await this.store.saveSurvey(survey);
    await this.store.addPendingOperation({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: survey.id,
      operation: "upsert",
      payload: survey,
      createdAt: now,
      status: "pending",
    });

    return survey;
  }

  async updateSurvey(survey: Survey): Promise<void> {
    const updated = {
      ...survey,
      updatedAt: new Date().toISOString(),
      version: survey.version + 1,
    };

    await this.store.saveSurvey(updated);
    await this.store.addPendingOperation({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: updated.id,
      operation: "upsert",
      payload: updated,
      createdAt: updated.updatedAt,
      status: "pending",
    });
  }

  async deleteSurvey(id: string): Promise<void> {
    const survey = await this.store.getSurvey(id);
    if (!survey) return;

    const deleted = {
      ...survey,
      deleted: true,
      updatedAt: new Date().toISOString(),
      version: survey.version + 1,
    };

    await this.store.saveSurvey(deleted);
    await this.store.addPendingOperation({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: deleted,
      createdAt: deleted.updatedAt,
      status: "pending",
    });
  }
}
```

