## Sync service

```ts
type SyncResponse = {
  success: boolean;
  conflicts?: Array<{
    entityType: string;
    entityId: string;
    reason: string;
    serverValue?: any;
  }>;
  serverChanges?: Survey[];
  nextSyncToken?: string;
};

export class SyncService {
  constructor(
    private store: LocalStore,
    private apiBaseUrl: string
  ) {}

  async sync(): Promise<void> {
    const pendingOps = await this.store.listPendingOperations();
    const lastSyncToken = await this.store.getLastSyncToken();

    if (pendingOps.length === 0 && !lastSyncToken) {
      return;
    }

    const uploadResult = await this.uploadPendingOperations(pendingOps);
    if (!uploadResult.success) {
      return;
    }

    for (const op of pendingOps) {
      await this.store.markOperationSynced(op.id);
    }

    const remoteChanges = await this.downloadRemoteChanges(lastSyncToken);
    for (const survey of remoteChanges.serverChanges ?? []) {
      await this.store.applyRemoteSurvey(survey);
    }

    if (remoteChanges.nextSyncToken) {
      await this.store.setLastSyncToken(remoteChanges.nextSyncToken);
    }
  }

  private async uploadPendingOperations(
    ops: SyncOperation[]
  ): Promise<SyncResponse> {
    const res = await fetch(`${this.apiBaseUrl}/sync/upload`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ operations: ops }),
    });

    if (!res.ok) {
      return { success: false };
    }

    return await res.json();
  }

  private async downloadRemoteChanges(
    syncToken: string | null
  ): Promise<SyncResponse> {
    const url = new URL(`${this.apiBaseUrl}/sync/download`);
    if (syncToken) url.searchParams.set("syncToken", syncToken);

    const res = await fetch(url.toString());
    if (!res.ok) {
      return { success: false };
    }

    return await res.json();
  }
}
```

