## 5) Sync engine

This is the heart of offline-first.

### `sync.ts`
```ts
import { db, PendingMutation, SurveyRecord } from './db';
import { syncMutation } from './api';

export async function enqueueMutation(mutation: Omit<PendingMutation, 'id' | 'createdAt' | 'retryCount' | 'status'>) {
  await db.pendingMutations.add({
    ...mutation,
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    retryCount: 0,
    status: 'pending',
  });
}

export async function syncPendingMutations() {
  const pending = await db.pendingMutations
    .where('status')
    .anyOf(['pending', 'failed'])
    .sortBy('createdAt');

  for (const mutation of pending) {
    try {
      await db.pendingMutations.update(mutation.id, { status: 'syncing' });

      const serverRecord = await syncMutation(mutation);

      if (serverRecord) {
        await db.surveyRecords.put(serverRecord);
      }

      await db.pendingMutations.delete(mutation.id);
    } catch (err) {
      const retryCount = mutation.retryCount + 1;
      const status = retryCount >= 3 ? 'failed' : 'pending';

      await db.pendingMutations.update(mutation.id, {
        retryCount,
        status,
      });
    }
  }
}
```

