## 6) Record operations

### `records.ts`
```ts
import { db, SurveyRecord } from './db';
import { enqueueMutation } from './sync';

export async function createSurveyRecord(record: Omit<SurveyRecord, 'id' | 'updatedAt' | 'version'>) {
  const newRecord: SurveyRecord = {
    ...record,
    id: crypto.randomUUID(),
    updatedAt: new Date().toISOString(),
    version: 1,
  };

  await db.surveyRecords.put(newRecord);

  await enqueueMutation({
    entityId: newRecord.id,
    type: 'create',
    payload: newRecord,
  });

  return newRecord;
}

export async function updateSurveyRecord(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveyRecords.get(id);
  if (!existing) throw new Error('Record not found');

  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await db.surveyRecords.put(updated);

  await enqueueMutation({
    entityId: id,
    type: 'update',
    payload: updated,
  });

  return updated;
}

export async function deleteSurveyRecord(id: string) {
  const existing = await db.surveyRecords.get(id);
  if (!existing) throw new Error('Record not found');

  const deleted: SurveyRecord = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await db.surveyRecords.put(deleted);

  await enqueueMutation({
    entityId: id,
    type: 'delete',
    payload: { id, deleted: true },
  });

  return deleted;
}
```

