## 7) React hook to load and sync

### `useSurveyRecords.ts`
```ts
import { useEffect, useState } from 'react';
import { db, SurveyRecord } from './db';
import { fetchSurveyRecords } from './api';
import { syncPendingMutations } from './sync';

export function useSurveyRecords() {
  const [records, setRecords] = useState<SurveyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  async function refreshLocal() {
    const local = await db.surveyRecords.where('deleted').notEqual(true).toArray();
    setRecords(local);
  }

  async function bootstrap() {
    setLoading(true);

    // Load local immediately
    await refreshLocal();

    // If online, optionally refresh from server
    if (navigator.onLine) {
      try {
        const remote = await fetchSurveyRecords();
        await db.transaction('rw', db.surveyRecords, async () => {
          await db.surveyRecords.clear();
          await db.surveyRecords.bulkPut(remote);
        });
        await refreshLocal();
      } catch {
        // Keep local data if fetch fails
      }
    }

    setLoading(false);
  }

  useEffect(() => {
    bootstrap();

    const onOnline = async () => {
      setIsOnline(true);
      await syncPendingMutations();
      await bootstrap();
    };

    const onOffline = () => setIsOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  return {
    records,
    loading,
    isOnline,
    refreshLocal,
  };
}
```

