## 9) Backend example

Here’s a minimal Express backend.

### `server.ts`
```ts
import express from 'express';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

type SurveyRecord = {
  id: string;
  siteId: string;
  observerName: string;
  observedAt: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  updatedAt: string;
  version: number;
  deleted?: boolean;
};

const store = new Map<string, SurveyRecord>();

app.get('/api/survey-records', (_req, res) => {
  const records = [...store.values()].filter(r => !r.deleted);
  res.json(records);
});

app.post('/api/survey-records/sync', (req, res) => {
  const mutation = req.body as any;
  const payload = mutation.payload as SurveyRecord;

  const existing = store.get(payload.id);

  if (mutation.type === 'delete') {
    if (existing && existing.version > payload.version) {
      return res.status(409).json({ message: 'Conflict' });
    }
    store.set(payload.id, { ...payload, deleted: true });
    return res.json({ ...payload, deleted: true });
  }

  if (existing && existing.version > payload.version) {
    return res.status(409).json({ message: 'Conflict' });
  }

  store.set(payload.id, payload);
  res.json(payload);
});

app.listen(3001, () => {
  console.log('API running on http://localhost:3001');
});
```

