# 8) Sync engine

This processes the queue when online.

## `src/api/sync.ts`

```ts
import { getPendingMutations, deletePendingMutation, incrementRetry } from '../db/queueRepo';
import { getSurveyById, markSurveySynced, markSurveyFailed } from '../db/surveyRepo';
import { api } from './client';

export async function syncPendingMutations() {
  const mutations = getPendingMutations();

  for (const mutation of mutations) {
    try {
      const payload = JSON.parse(mutation.payload);
      const localSurvey = getSurveyById(mutation.entityId);

      if (!localSurvey) {
        deletePendingMutation(mutation.id);
        continue;
      }

      if (mutation.operation === 'create') {
        const res = await api.createSurvey(payload);
        markSurveySynced(localSurvey.id, res.serverId);
      }

      if (mutation.operation === 'update') {
        if (!localSurvey.serverId) throw new Error('Missing serverId for update');
        await api.updateSurvey(localSurvey.serverId, payload);
        markSurveySynced(localSurvey.id, localSurvey.serverId);
      }

      if (mutation.operation === 'delete') {
        if (localSurvey.serverId) {
          await api.deleteSurvey(localSurvey.serverId);
        }
      }

      deletePendingMutation(mutation.id);
    } catch (err) {
      console.warn('Sync failed for mutation', mutation.id, err);
      incrementRetry(mutation.id);

      if (mutation.retryCount >= 3) {
        markSurveyFailed(mutation.entityId);
      }
    }
  }
}
```

