import { upsertSurvey } from '../db/surveyRepo';
import { enqueueMutation } from '../db/queueRepo';
import { uuid } from '../utils/uuid';

export function saveSurveyLocally(input: {
  id?: string;
  title: string;
  notes?: string;
  latitude?: number;
  longitude?: number;
}) {
  const now = new Date().toISOString();
  const id = input.id ?? uuid();

  const record = {
    id,
    title: input.title,
    notes: input.notes ?? null,
    latitude: input.latitude ?? null,
    longitude: input.longitude ?? null,
    createdAt: now,
    updatedAt: now,
    syncStatus: 'pending' as const,
    deletedAt: null,
  };

  upsertSurvey(record);

  enqueueMutation({
    id: uuid(),
    entityType: 'survey',
    entityId: id,
    operation: input.id ? 'update' : 'create',
    payload: JSON.stringify(record),
    createdAt: now,
    retryCount: 0,
  });

  return record;
}
