import { getDb } from './index';
import { Survey } from '../types/models';

export const surveyRepo = {
  upsert(survey: Survey) {
    const db = getDb();
    db.runSync(
      `INSERT OR REPLACE INTO surveys
      (id, title, description, status, createdAt, updatedAt, deletedAt, version, lastSyncedAt, syncState)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        survey.id,
        survey.title,
        survey.description ?? null,
        survey.status,
        survey.createdAt,
        survey.updatedAt,
        survey.deletedAt ?? null,
        survey.version,
        survey.lastSyncedAt ?? null,
        survey.syncState,
      ]
    );
  },

  getAll(): Survey[] {
    const db = getDb();
    const rows = db.getAllSync<any>(`SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`);
    return rows as Survey[];
  },

  getById(id: string): Survey | null {
    const db = getDb();
    const row = db.getFirstSync<any>(`SELECT * FROM surveys WHERE id = ?`, [id]);
    return row ? (row as Survey) : null;
  },

  markDeleted(id: string, updatedAt: string) {
    const db = getDb();
    db.runSync(
      `UPDATE surveys SET deletedAt = ?, updatedAt = ?, syncState = 'pending' WHERE id = ?`,
      [updatedAt, updatedAt, id]
    );
  },
};
```

