import { getDb } from './index';
import { OutboxOperation } from '../types/models';

export const outboxRepo = {
  add(op: OutboxOperation) {
    const db = getDb();
    db.runSync(
      `INSERT INTO outbox (id, entityType, entityId, operation, payload, createdAt, retries, lastError)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [op.id, op.entityType, op.entityId, op.operation, op.payload, op.createdAt, op.retries, op.lastError ?? null]
    );
  },

  getAll(): OutboxOperation[] {
    const db = getDb();
    return db.getAllSync<OutboxOperation>(`SELECT * FROM outbox ORDER BY createdAt ASC`);
  },

  remove(id: string) {
    const db = getDb();
    db.runSync(`DELETE FROM outbox WHERE id = ?`, [id]);
  },

  incrementRetry(id: string, error: string) {
    const db = getDb();
    db.runSync(
      `UPDATE outbox SET retries = retries + 1, lastError = ? WHERE id = ?`,
      [error, id]
    );
  },
};
```

