## `src/api/sync.ts`

```ts
import { outboxRepo } from '../db/outboxRepo';
import { surveyRepo } from '../db/surveyRepo';
import { apiClient } from './client';

export async function syncOutbox() {
  const ops = outboxRepo.getAll();

  for (const op of ops) {
    try {
      const result = await apiClient.syncOperation(op);

      // If server returns updated entity, store it locally
      if (result.entityType === 'survey' && result.entity) {
        surveyRepo.upsert({
          ...result.entity,
          syncState: 'synced',
          lastSyncedAt: new Date().toISOString(),
        });
      }

      outboxRepo.remove(op.id);
    } catch (err: any) {
      outboxRepo.incrementRetry(op.id, err.message);
    }
  }
}
```

