# 6) Backend sync endpoint example

Here’s a minimal Node.js/Express endpoint for syncing.

## `POST /sync`

```ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.post('/sync', (req, res) => {
  const op = req.body;

  if (op.entityType === 'survey') {
    const incoming = JSON.parse(op.payload);
    const existing = surveys.get(incoming.id);

    if (!existing) {
      surveys.set(incoming.id, { ...incoming, version: 1 });
      return res.json({ entityType: 'survey', entity: surveys.get(incoming.id) });
    }

    if (incoming.version !== existing.version) {
      return res.status(409).json({
        error: 'Conflict',
        serverEntity: existing,
      });
    }

    const updated = { ...existing, ...incoming, version: existing.version + 1 };
    surveys.set(incoming.id, updated);
    return res.json({ entityType: 'survey', entity: updated });
  }

  return res.status(400).json({ error: 'Unsupported entity type' });
});

app.listen(3000, () => console.log('API running on 3000'));
```

