# 8) Sync engine

This is the heart of offline-first behavior.

## `api/sync.ts`

```ts
import { apiFetch } from './client';
import { getPendingOutboxItems, deleteOutboxItem, incrementOutboxAttempts } from '../db/outboxRepo';
import { getAllSurveys, upsertSurvey } from '../db/surveyRepo';

export async function syncOutbox() {
  const items = getPendingOutboxItems();

  for (const item of items) {
    try {
      if (item.operation === 'create') {
        const serverSurvey = await apiFetch('/surveys', {
          method: 'POST',
          body: JSON.stringify(item.payload),
        });

        upsertSurvey({
          ...serverSurvey,
          photos: serverSurvey.photos || [],
          syncStatus: 'synced',
        });
      }

      if (item.operation === 'update') {
        const serverSurvey = await apiFetch(`/surveys/${item.entityId}`, {
          method: 'PUT',
          body: JSON.stringify(item.payload),
        });

        upsertSurvey({
          ...serverSurvey,
          photos: serverSurvey.photos || [],
          syncStatus: 'synced',
        });
      }

      if (item.operation === 'delete') {
        await apiFetch(`/surveys/${item.entityId}`, {
          method: 'DELETE',
        });
      }

      deleteOutboxItem(item.id);
    } catch (error: any) {
      incrementOutboxAttempts(item.id, error.message || 'Unknown sync error');
    }
  }
}

export async function pullRemoteChanges(lastSyncAt?: string) {
  const path = lastSyncAt
    ? `/surveys/changes?since=${encodeURIComponent(lastSyncAt)}`
    : `/surveys`;

  const remoteSurveys = await apiFetch(path);

  for (const survey of remoteSurveys) {
    upsertSurvey({
      ...survey,
      photos: survey.photos || [],
      syncStatus: 'synced',
    });
  }

  return new Date().toISOString();
}
```

