# 10) Sync hook

## `hooks/useSync.ts`

```ts
import { useEffect, useState } from 'react';
import { syncOutbox, pullRemoteChanges } from '../api/sync';

export function useSync(isOnline: boolean) {
  const [syncing, setSyncing] = useState(false);
  const [lastSyncAt, setLastSyncAt] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (!isOnline) return;

    let cancelled = false;

    async function runSync() {
      setSyncing(true);
      try {
        await syncOutbox();
        const newLastSyncAt = await pullRemoteChanges(lastSyncAt);
        if (!cancelled) setLastSyncAt(newLastSyncAt);
      } finally {
        if (!cancelled) setSyncing(false);
      }
    }

    runSync();

    return () => {
      cancelled = true;
    };
  }, [isOnline]);

  return { syncing, lastSyncAt };
}
```

