    longitude: input.longitude,
    notes: input.notes,
    photos: input.photos,
    status: 'draft' as const,
    createdAt: now,
    updatedAt: now,
    deletedAt: null,
    syncStatus: isNew ? 'pending_create' : 'pending_update',
    version: 0,
  };

  upsertSurvey(survey);

  addOutboxItem({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: isNew ? 'create' : 'update',
    payload: survey,
    createdAt: now,
    attempts: 0,
    lastError: null,
  });

  return survey;
