# 12) Delete flow

Soft-delete locally, queue delete remotely.

```ts
import { addOutboxItem } from '../db/outboxRepo';
import { upsertSurvey, getSurveyById } from '../db/surveyRepo';
import { v4 as uuidv4 } from 'uuid';

export function deleteSurvey(id: string) {
  const existing = getSurveyById(id);
  if (!existing) return;

  const now = new Date().toISOString();

  upsertSurvey({
    ...existing,
    deletedAt: now,
    updatedAt: now,
    syncStatus: 'pending_delete',
  });

  addOutboxItem({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id },
    createdAt: now,
    attempts: 0,
    lastError: null,
  });
}
