### 6.7 Sync engine

```ts
// src/api/sync.ts
import { getPendingQueueItems, markQueueItemFailed, markQueueItemSynced } from '../db/queueRepo';
import { apiRequest } from './client';
import { db } from '../db';

export async function syncLocalChanges() {
  const pending = getPendingQueueItems();

  for (const item of pending) {
    try {
      const result = await apiRequest('/sync/survey', {
        method: 'POST',
        body: JSON.stringify({
          operation: item.operation,
          entityId: item.entityId,
          payload: item.payload,
          clientQueueId: item.id,
        }),
      });

      // Update local record with authoritative server version
      if (result.survey) {
        db.runSync(
          `
          INSERT INTO surveys (
            id, projectId, siteName, latitude, longitude, notes,
            version, createdAt, updatedAt, deletedAt, syncStatus
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(id) DO UPDATE SET
            projectId=excluded.projectId,
            siteName=excluded.siteName,
            latitude=excluded.latitude,
            longitude=excluded.longitude,
            notes=excluded.notes,
            version=excluded.version,
            createdAt=excluded.createdAt,
            updatedAt=excluded.updatedAt,
            deletedAt=excluded.deletedAt,
            syncStatus=excluded.syncStatus
          `,
          [
            result.survey.id,
            result.survey.projectId,
            result.survey.siteName,
            result.survey.latitude,
            result.survey.longitude,
            result.survey.notes ?? null,
            result.survey.version,
            result.survey.createdAt,
            result.survey.updatedAt,
            result.survey.deletedAt ?? null,
            'synced',
          ]
        );
      }

      markQueueItemSynced(item.id);
    } catch (err: any) {
      markQueueItemFailed(item.id, err.message);
    }
  }

  // Pull remote updates since last sync
  const lastSync = db.getFirstSync<any>(
    `SELECT value FROM sync_meta WHERE key = 'lastSyncAt'`
  )?.value;

  const updates = await apiRequest(
    `/sync/survey/updates?since=${encodeURIComponent(lastSync || '')}`
  );

  for (const survey of updates.surveys || []) {
    db.runSync(
      `
      INSERT INTO surveys (
        id, projectId, siteName, latitude, longitude, notes,
        version, createdAt, updatedAt, deletedAt, syncStatus
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        projectId=excluded.projectId,
        siteName=excluded.siteName,
        latitude=excluded.latitude,
        longitude=excluded.longitude,
        notes=excluded.notes,
        version=excluded.version,
        createdAt=excluded.createdAt,
        updatedAt=excluded.updatedAt,
        deletedAt=excluded.deletedAt,
        syncStatus='synced'
      `,
      [
        survey.id,
        survey.projectId,
        survey.siteName,
        survey.latitude,
        survey.longitude,
        survey.notes ?? null,
        survey.version,
        survey.createdAt,
        survey.updatedAt,
        survey.deletedAt ?? null,
        'synced',
      ]
    );
  }

  db.runSync(
    `
    INSERT INTO sync_meta (key, value)
    VALUES ('lastSyncAt', ?)
    ON CONFLICT(key) DO UPDATE SET value = excluded.value
    `,
    [new Date().toISOString()]
  );
}
