  latitude: number;
  longitude: number;
  notes?: string;
}) {
  const now = new Date().toISOString();
  const id = input.id ?? uuidv4();

  const survey = {
    id,
    projectId: input.projectId,
    siteName: input.siteName,
    latitude: input.latitude,
    longitude: input.longitude,
    notes: input.notes,
    version: 0,
    createdAt: now,
    updatedAt: now,
    deletedAt: null,
    syncStatus: 'pending' as const,
  };

  upsertSurveyLocal(survey);

  enqueueChange({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: input.id ? 'update' : 'create',
    payload: survey,
    status: 'pending',
    attempts: 0,
    createdAt: now,
  });

  return survey;
}
