## 6) Survey service with offline write + queue

### `src/surveyService.ts`
```ts
import { db, Survey, SyncQueueItem } from './db';
import { v4 as uuidv4 } from 'uuid';

function now() {
  return new Date().toISOString();
}

export async function listSurveys(): Promise<Survey[]> {
  return db.surveys.where('deletedAt').equals(undefined as any).toArray();
}

export async function createSurvey(input: Omit<Survey, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus' | 'version' | 'deletedAt'>) {
  const id = uuidv4();
  const survey: Survey = {
    id,
    ...input,
    createdAt: now(),
    updatedAt: now(),
    deletedAt: null,
    syncStatus: 'pending',
    version: 1
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    action: 'create',
    payload: survey,
    createdAt: now(),
    attempts: 0
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(survey);
    await db.syncQueue.add(queueItem);
  });

  return survey;
}

export async function updateSurvey(id: string, changes: Partial<Survey>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const updated: Survey = {
    ...existing,
    ...changes,
    updatedAt: now(),
    syncStatus: 'pending',
    version: existing.version + 1
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    action: 'update',
    payload: updated,
    createdAt: now(),
    attempts: 0
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(updated);
    await db.syncQueue.add(queueItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const deleted: Survey = {
    ...existing,
    deletedAt: now(),
    updatedAt: now(),
    syncStatus: 'pending',
    version: existing.version + 1
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    action: 'delete',
    payload: { id, deletedAt: deleted.deletedAt, version: deleted.version },
    createdAt: now(),
    attempts: 0
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(deleted);
    await db.syncQueue.add(queueItem);
  });

  return deleted;
}
```

