## 7) Sync engine

### `src/sync.ts`
```ts
import { db, SyncQueueItem } from './db';
import { apiFetch } from './api';

async function pushQueueItem(item: SyncQueueItem) {
  const endpointMap = {
    create: '/surveys',
    update: `/surveys/${item.entityId}`,
    delete: `/surveys/${item.entityId}`
  } as const;

  const methodMap = {
    create: 'POST',
    update: 'PUT',
    delete: 'DELETE'
  } as const;

  const response = await apiFetch<any>(endpointMap[item.action], {
    method: methodMap[item.action],
    body: JSON.stringify(item.payload)
  });

  return response;
}

export async function syncPendingChanges() {
  const items = await db.syncQueue.orderBy('createdAt').toArray();

  for (const item of items) {
    try {
      const result = await pushQueueItem(item);

      if (item.action === 'delete') {
        await db.surveys.delete(item.entityId);
      } else {
        await db.surveys.update(item.entityId, {
          ...result,
          syncStatus: 'synced'
        });
      }

      await db.syncQueue.delete(item.id);
    } catch (err: any) {
      await db.syncQueue.update(item.id, {
        attempts: item.attempts + 1,
        lastError: err.message || 'Sync failed'
      });

      await db.surveys.update(item.entityId, {
        syncStatus: 'error'
      });

      // stop on first failure to preserve ordering
      break;
    }
  }
}

export function startAutoSync() {
  const onlineHandler = () => {
    syncPendingChanges().catch(console.error);
  };

  window.addEventListener('online', onlineHandler);

  // initial attempt if already online
  if (navigator.onLine) {
    syncPendingChanges().catch(console.error);
  }

  return () => window.removeEventListener('online', onlineHandler);
}
```

