## Local storage layer

### IndexedDB example wrapper
```ts
// db.ts
export class LocalDB {
  private dbName = 'field-survey-app';
  private version = 1;
  private db: IDBDatabase | null = null;

  async init() {
    return new Promise<void>((resolve, reject) => {
      const req = indexedDB.open(this.dbName, this.version);

      req.onupgradeneeded = () => {
        const db = req.result;

        if (!db.objectStoreNames.contains('surveys')) {
          const store = db.createObjectStore('surveys', { keyPath: 'id' });
          store.createIndex('updatedAt', 'updatedAt', { unique: false });
        }

        if (!db.objectStoreNames.contains('syncQueue')) {
          const queue = db.createObjectStore('syncQueue', { keyPath: 'id' });
          queue.createIndex('createdAt', 'createdAt', { unique: false });
        }
      };

      req.onsuccess = () => {
        this.db = req.result;
        resolve();
      };

      req.onerror = () => reject(req.error);
    });
  }

  private tx(storeName: string, mode: IDBTransactionMode) {
    if (!this.db) throw new Error('DB not initialized');
    return this.db.transaction(storeName, mode).objectStore(storeName);
  }

  async upsertSurvey(survey: Survey) {
    return new Promise<void>((resolve, reject) => {
      const req = this.tx('surveys', 'readwrite').put(survey);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  async getSurvey(id: string): Promise<Survey | undefined> {
    return new Promise((resolve, reject) => {
      const req = this.tx('surveys', 'readonly').get(id);
      req.onsuccess = () => resolve(req.result as Survey | undefined);
      req.onerror = () => reject(req.error);
    });
  }

  async listSurveys(): Promise<Survey[]> {
    return new Promise((resolve, reject) => {
      const req = this.tx('surveys', 'readonly').getAll();
      req.onsuccess = () => resolve(req.result as Survey[]);
      req.onerror = () => reject(req.error);
    });
  }

  async addToQueue(item: SyncAction) {
    return new Promise<void>((resolve, reject) => {
      const req = this.tx('syncQueue', 'readwrite').put(item);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  async getQueueItems(): Promise<SyncAction[]> {
    return new Promise((resolve, reject) => {
      const req = this.tx('syncQueue', 'readonly').getAll();
      req.onsuccess = () => resolve(req.result as SyncAction[]);
      req.onerror = () => reject(req.error);
    });
  }

  async removeQueueItem(id: string) {
    return new Promise<void>((resolve, reject) => {
      const req = this.tx('syncQueue', 'readwrite').delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }
}
