## Sync service

```ts
// sync.ts
import { LocalDB } from './db';

type ApiSurvey = Survey & { serverVersion: number };

export class SyncService {
  constructor(private db: LocalDB, private apiBaseUrl: string) {}

  async sync() {
    if (!navigator.onLine) return;

    const queue = await this.db.getQueueItems();

    for (const item of queue) {
      try {
        await this.pushAction(item);
        await this.db.removeQueueItem(item.id);
      } catch (err: any) {
        item.retries += 1;
        item.lastError = err?.message ?? 'Sync failed';
        await this.db.addToQueue(item);
      }
    }

    await this.pullRemoteChanges();
  }

  private async pushAction(item: SyncAction) {
    const res = await fetch(`${this.apiBaseUrl}/sync`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(item),
    });

    if (!res.ok) {
      throw new Error(`Push failed: ${res.status}`);
    }
  }

  private async pullRemoteChanges() {
    const res = await fetch(`${this.apiBaseUrl}/surveys/changes`);
    if (!res.ok) throw new Error('Failed to pull changes');

    const changes: Survey[] = await res.json();
    for (const survey of changes) {
      await this.db.upsertSurvey(survey);
    }
  }
}
```

