## CRUD operations with offline queueing

```ts
// surveyService.ts
import { LocalDB } from './db';

export class SurveyService {
  constructor(private db: LocalDB) {}

  async createSurvey(input: Omit<Survey, 'id' | 'version' | 'updatedAt' | 'deleted'>) {
    const survey: Survey = {
      ...input,
      id: crypto.randomUUID(),
      version: 1,
      updatedAt: new Date().toISOString(),
      deleted: false,
      status: navigator.onLine ? 'submitted' : 'draft',
    };

    await this.db.upsertSurvey(survey);

    await this.db.addToQueue({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: survey.id,
      action: 'create',
      payload: survey,
      createdAt: new Date().toISOString(),
      retries: 0,
    });

    return survey;
  }

  async updateSurvey(id: string, updates: Partial<Survey>) {
    const existing = await this.db.getSurvey(id);
    if (!existing) throw new Error('Survey not found');

    const updated: Survey = {
      ...existing,
      ...updates,
      version: existing.version + 1,
      updatedAt: new Date().toISOString(),
    };

    await this.db.upsertSurvey(updated);

    await this.db.addToQueue({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: id,
      action: 'update',
      payload: updated,
      createdAt: new Date().toISOString(),
      retries: 0,
    });

    return updated;
  }

  async deleteSurvey(id: string) {
    const existing = await this.db.getSurvey(id);
    if (!existing) throw new Error('Survey not found');

    const deleted: Survey = {
      ...existing,
      deleted: true,
      version: existing.version + 1,
      updatedAt: new Date().toISOString(),
    };

    await this.db.upsertSurvey(deleted);

    await this.db.addToQueue({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: id,
      action: 'delete',
      payload: deleted,
      createdAt: new Date().toISOString(),
      retries: 0,
    });
  }
}
