# 7) Sync engine

## `src/services/sync.ts`
```ts
import { db } from "../db/db";
import { api } from "./api";
import { OutboxItem, Survey } from "../types/survey";

export async function syncOutbox() {
  const items = await db.outbox.orderBy("createdAt").toArray();

  for (const item of items) {
    try {
      if (item.entityType !== "survey") continue;

      if (item.operation === "create") {
        const local = await db.surveys.get(item.entityId);
        if (!local) continue;

        const created = await api.createSurvey(local);
        await db.surveys.put({ ...created, status: "synced" });
      }

      if (item.operation === "update") {
        const local = await db.surveys.get(item.entityId);
        if (!local) continue;

        const updated = await api.updateSurvey(
          item.entityId,
          local,
          local.version
        );
        await db.surveys.put({ ...updated, status: "synced" });
      }

      if (item.operation === "delete") {
        const local = await db.surveys.get(item.entityId);
        const version = local?.version ?? 0;
        await api.deleteSurvey(item.entityId, version);
        await db.surveys.delete(item.entityId);
      }

      await db.outbox.delete(item.id);
    } catch (error: any) {
      await db.outbox.update(item.id, {
        attempts: item.attempts + 1,
        lastError: error?.message || "Sync failed",
      });
    }
  }
}

export async function enqueueSurveyOperation(
  operation: OutboxItem["operation"],
  survey: Survey
) {
  const outboxItem: OutboxItem = {
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: survey.id,
    operation,
    payload: survey,
    createdAt: new Date().toISOString(),
    attempts: 0,
  };

  await db.outbox.add(outboxItem);
}
```

