# 12) Basic backend API example

Here’s a minimal Node/Express server.

## `server.ts`
```ts
import express from "express";
import cors from "cors";
import { randomUUID } from "crypto";

const app = express();
app.use(cors());
app.use(express.json());

let surveys: any[] = [];

app.get("/surveys", (_req, res) => {
  res.json(surveys);
});

app.post("/surveys", (req, res) => {
  const survey = {
    ...req.body,
    id: req.body.id || randomUUID(),
    version: 1,
    status: "synced",
    updatedAt: new Date().toISOString(),
  };
  surveys.push(survey);
  res.json(survey);
});

app.put("/surveys/:id", (req, res) => {
  const idx = surveys.findIndex((s) => s.id === req.params.id);
  if (idx === -1) return res.status(404).send("Not found");

  const existing = surveys[idx];
  if (req.body.version !== existing.version) {
    return res.status(409).send("Version conflict");
  }

  const updated = {
    ...existing,
    ...req.body,
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
  };

  surveys[idx] = updated;
  res.json(updated);
});

app.delete("/surveys/:id", (req, res) => {
  surveys = surveys.filter((s) => s.id !== req.params.id);
  res.status(204).send();
});

app.listen(3000, () => console.log("API running on port 3000"));
```

