```js
import express from "express";
import cors from "cors";
import fs from "fs";

const app = express();
const PORT = 3001;
const DB_FILE = "./db.json";

app.use(cors());
app.use(express.json());

function readDB() {
  return JSON.parse(fs.readFileSync(DB_FILE, "utf-8"));
}

function writeDB(data) {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
}

// Get all surveys
app.get("/surveys", (req, res) => {
  const db = readDB();
  res.json(db.surveys);
});

// Sync endpoint: accepts local changes and returns server state
app.post("/sync", (req, res) => {
  const { clientSurveys = [], lastSyncAt = 0 } = req.body;
  const db = readDB();

  const serverById = new Map(db.surveys.map((s) => [s.id, s]));

  // Merge client changes into server
  for (const local of clientSurveys) {
    const existing = serverById.get(local.id);

    if (!existing) {
      db.surveys.push(local);
      serverById.set(local.id, local);
      continue;
    }

    // Simple last-write-wins
    if ((local.updatedAt || 0) > (existing.updatedAt || 0)) {
      const idx = db.surveys.findIndex((s) => s.id === local.id);
      db.surveys[idx] = local;
      serverById.set(local.id, local);
    }
  }

  writeDB(db);

  // Return all server records updated since last sync
  const changed = db.surveys.filter((s) => (s.updatedAt || 0) > lastSyncAt);

  res.json({
    ok: true,
    serverTime: Date.now(),
    surveys: changed
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

