## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import {
  getLocalSurveys,
  saveLocalSurveys,
  getPendingQueue,
  savePendingQueue,
  getLastSyncAt,
  setLastSyncAt
} from "./db";
import { syncSurveys } from "./api";

function newSurvey(name, notes) {
  return {
    id: crypto.randomUUID(),
    name,
    notes,
    updatedAt: Date.now(),
    deleted: false
  };
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("Loading...");

  useEffect(() => {
    const handleOnline = () => setOnline(true);
    const handleOffline = () => setOnline(false);

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    loadData();

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  async function loadData() {
    const local = await getLocalSurveys();
    setSurveys(local);
    setStatus("Ready");

    if (navigator.onLine) {
      await doSync();
    }
  }

  async function persist(next) {
    setSurveys(next);
    await saveLocalSurveys(next);
  }

  async function addSurvey() {
    if (!name.trim()) return;

    const survey = newSurvey(name.trim(), notes.trim());
    const next = [...surveys, survey];

    await persist(next);

    const queue = await getPendingQueue();
    queue.push({ type: "UPSERT", survey });
    await savePendingQueue(queue);

    setName("");
    setNotes("");
    setStatus(navigator.onLine ? "Saved locally, syncing..." : "Saved offline");
  }

  async function doSync() {
    try {
      const queue = await getPendingQueue();
      const local = await getLocalSurveys();
      const lastSyncAt = await getLastSyncAt();

      // In a minimal app, send all local surveys
      const result = await syncSurveys({
        clientSurveys: local,
        lastSyncAt
      });

      // Merge server changes
      const serverSurveys = result.surveys || [];
      const mergedMap = new Map(local.map((s) => [s.id, s]));

      for (const s of serverSurveys) {
        const existing = mergedMap.get(s.id);
        if (!existing || (s.updatedAt || 0) > (existing.updatedAt || 0)) {
          mergedMap.set(s.id, s);
        }
      }

      const merged = Array.from(mergedMap.values());
      await saveLocalSurveys(merged);
      setSurveys(merged);
      await savePendingQueue([]);
      await setLastSyncAt(result.serverTime || Date.now());
      setStatus("Synced");
    } catch (e) {
      setStatus("Sync failed; will retry when online");
    }
  }

  useEffect(() => {
    if (online) {
      doSync();
    }
  }, [online]);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "2rem auto" }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status: <strong>{status}</strong> | Network:{" "}
        <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <div style={{ display: "grid", gap: 8, marginBottom: 16 }}>
        <input
          placeholder="Survey name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button onClick={addSurvey}>Save Survey</button>
        <button onClick={doSync} disabled={!online}>
          Sync Now
        </button>
      </div>

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.notes}{" "}
            <small>({new Date(s.updatedAt).toLocaleString()})</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

