# 6) Frontend logic: `public/app.js`

```js
const form = document.getElementById("surveyForm");
const siteNameInput = document.getElementById("siteName");
const notesInput = document.getElementById("notes");
const surveyList = document.getElementById("surveyList");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("syncBtn");

const DB_NAME = "survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

let db;

// IndexedDB helpers
function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function saveLocalSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function clearLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.clear();

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function renderSurveys(surveys) {
  surveyList.innerHTML = "";

  if (surveys.length === 0) {
    surveyList.innerHTML = "<li>No surveys saved yet.</li>";
    return;
  }

  for (const s of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${escapeHtml(s.siteName)}</strong><br />
      <small>${new Date(s.createdAt).toLocaleString()}</small><br />
      ${escapeHtml(s.notes)}<br />
      <small>Status: ${s.synced ? "Synced" : "Pending sync"}</small>
    `;
    surveyList.appendChild(li);
  }
}

function updateConnectionStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

async function refreshLocalList() {
  const surveys = await getAllLocalSurveys();
  renderSurveys(surveys.sort((a, b) => b.createdAt - a.createdAt));
}

async function syncSurveys() {
  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when connection is restored.");
    return;
  }

  const localSurveys = await getAllLocalSurveys();
  const pending = localSurveys.filter((s) => !s.synced);

  if (pending.length === 0) {
    alert("Nothing to sync.");
    return;
  }

  const response = await fetch("/api/sync", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ surveys: pending })
  });

  if (!response.ok) {
    throw new Error("Sync failed");
  }

  // Mark all as synced locally
  for (const survey of pending) {
    survey.synced = true;
    await saveLocalSurvey(survey);
  }

  await refreshLocalList();
  alert(`Synced ${pending.length} survey(s).`);
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

// Form submit
form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    siteName: siteNameInput.value.trim(),
    notes: notesInput.value.trim(),
    createdAt: Date.now(),
    synced: false
  };

  await saveLocalSurvey(survey);
  form.reset();
  await refreshLocalList();

  if (navigator.onLine) {
    try {
      await syncSurveys();
    } catch (err) {
      console.error(err);
      alert("Saved locally, but sync failed.");
    }
  } else {
    alert("Saved locally. Will sync when online.");
  }
});

// Sync button
syncBtn.addEventListener("click", async () => {
  try {
    await syncSurveys();
  } catch (err) {
    console.error(err);
    alert("Sync error: " + err.message);
  }
});

// Auto-sync when connection returns
window.addEventListener("online", async () => {
  updateConnectionStatus();
  try {
    await syncSurveys();
  } catch (err) {
    console.error(err);
  }
});

window.addEventListener("offline", updateConnectionStatus);

// Init
(async function init() {
  db = await openDB();
  updateConnectionStatus();
  await refreshLocalList();
})();
```

