## `src/db.ts`
```ts
import * as SQLite from 'expo-sqlite';
import { SurveyRecord } from './types';

const db = SQLite.openDatabaseSync('survey.db');

export function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      siteName TEXT NOT NULL,
      notes TEXT NOT NULL,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL,
      synced INTEGER NOT NULL DEFAULT 0
    );
  `);
}

export function insertSurvey(record: SurveyRecord) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
     (id, siteName, notes, latitude, longitude, createdAt, updatedAt, synced)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.siteName,
      record.notes,
      record.latitude,
      record.longitude,
      record.createdAt,
      record.updatedAt,
      record.synced,
    ]
  );
}

export function getPendingSurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(
    `SELECT * FROM surveys WHERE synced = 0 ORDER BY createdAt ASC`
  );
}

export function markSurveySynced(id: string) {
  db.runSync(`UPDATE surveys SET synced = 1 WHERE id = ?`, [id]);
}

export function getAllSurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(
    `SELECT * FROM surveys ORDER BY createdAt DESC`
  );
}
```

