## `src/sync.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingSurveys, markSurveySynced } from './db';
import { sendSurvey } from './api';

export async function syncPendingSurveys() {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return;

  const pending = getPendingSurveys();

  for (const record of pending) {
    try {
      await sendSurvey(record);
      markSurveySynced(record.id);
    } catch (err) {
      // Stop on first failure to avoid hammering the server
      break;
    }
  }
}
```

