import React, { useEffect, useState } from 'react';
import {
  SafeAreaView,
  Text,
  TextInput,
  Button,
  View,
  FlatList,
  Alert,
} from 'react-native';
import { v4 as uuidv4 } from 'uuid';
import NetInfo from '@react-native-community/netinfo';

import { initDb, insertSurvey, getAllSurveys } from './src/db';
import { syncPendingSurveys } from './src/sync';
import { SurveyRecord } from './src/types';

export default function App() {
  const [siteName, setSiteName] = useState('');
  const [notes, setNotes] = useState('');
  const [latitude, setLatitude] = useState('');
  const [longitude, setLongitude] = useState('');
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [isOnline, setIsOnline] = useState(false);

  const refresh = () => setSurveys(getAllSurveys());

  useEffect(() => {
    initDb();
    refresh();

    const unsubscribe = NetInfo.addEventListener((state) => {
      setIsOnline(!!state.isConnected);
      if (state.isConnected) {
        syncPendingSurveys().then(refresh);
      }
    });

    return () => unsubscribe();
  }, []);

  const saveSurvey = async () => {
    if (!siteName || !notes || !latitude || !longitude) {
      Alert.alert('Missing fields', 'Please fill in all fields.');
      return;
    }

    const now = new Date().toISOString();
    const record: SurveyRecord = {
      id: uuidv4(),
      siteName,
      notes,
      latitude: parseFloat(latitude),
      longitude: parseFloat(longitude),
      createdAt: now,
      updatedAt: now,
      synced: 0,
    };

    insertSurvey(record);
    refresh();

    setSiteName('');
    setNotes('');
    setLatitude('');
    setLongitude('');

    // Try syncing immediately if online
    await syncPendingSurveys();
    refresh();
  };

  return (
    <SafeAreaView style={{ flex: 1, padding: 16 }}>
      <Text style={{ fontSize: 24, fontWeight: 'bold', marginBottom: 8 }}>
        Field Survey App
      </Text>

      <Text style={{ marginBottom: 12 }}>
        Status: {isOnline ? 'Online' : 'Offline'}
      </Text>

      <TextInput
        placeholder="Site name"
        value={siteName}
        onChangeText={setSiteName}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />
      <TextInput
        placeholder="Latitude"
        value={latitude}
        onChangeText={setLatitude}
        keyboardType="numeric"
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />
      <TextInput
        placeholder="Longitude"
        value={longitude}
        onChangeText={setLongitude}
        keyboardType="numeric"
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />

      <Button title="Save Survey" onPress={saveSurvey} />

      <View style={{ marginTop: 20, flex: 1 }}>
        <Text style={{ fontSize: 18, marginBottom: 8 }}>Saved Surveys</Text>
        <FlatList
          data={surveys}
          keyExtractor={(item) => item.id}
          renderItem={({ item }) => (
            <View style={{ paddingVertical: 8, borderBottomWidth: 1 }}>
              <Text>{item.siteName}</Text>
