const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = [];

app.post('/surveys', (req, res) => {
  const record = req.body;

  if (!record || !record.id) {
    return res.status(400).json({ error: 'Invalid survey record' });
  }

  const existingIndex = surveys.findIndex((s) => s.id === record.id);
  if (existingIndex >= 0) {
    surveys[existingIndex] = record;
  } else {
    surveys.push(record);
  }

  res.json({ ok: true, id: record.id });
});

app.get('/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
