## `server/index.js`

```js
import express from 'express';
import cors from 'cors';
import fs from 'fs/promises';
import { nanoid } from 'nanoid';

const app = express();
const PORT = 3001;
const DB_FILE = './db.json';

app.use(cors());
app.use(express.json());

async function readDB() {
  const raw = await fs.readFile(DB_FILE, 'utf-8');
  return JSON.parse(raw);
}

async function writeDB(data) {
  await fs.writeFile(DB_FILE, JSON.stringify(data, null, 2));
}

app.get('/records', async (req, res) => {
  const db = await readDB();
  res.json(db.records);
});

app.post('/records/bulk', async (req, res) => {
  const { records } = req.body;
  if (!Array.isArray(records)) {
    return res.status(400).json({ error: 'records must be an array' });
  }

  const db = await readDB();
  const existingIds = new Set(db.records.map(r => r.id));

  const inserted = [];
  for (const record of records) {
    if (!record.id) record.id = nanoid();
    if (!existingIds.has(record.id)) {
      db.records.push(record);
      inserted.push(record);
      existingIds.add(record.id);
    } else {
      // replace existing if incoming is newer
      const idx = db.records.findIndex(r => r.id === record.id);
      if (idx >= 0) {
        const current = db.records[idx];
        if (new Date(record.updatedAt) > new Date(current.updatedAt)) {
          db.records[idx] = record;
          inserted.push(record);
        }
      }
    }
  }

  await writeDB(db);
  res.json({ ok: true, insertedCount: inserted.length });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

