## `client/src/App.jsx`

```jsx
import { useEffect, useState } from 'react';
import { addRecord, getRecords, saveRecords } from './storage';
import { fetchRemoteRecords, syncRecords } from './api';
import { nanoid } from 'nanoid';

function nowISO() {
  return new Date().toISOString();
}

export default function App() {
  const [records, setRecords] = useState([]);
  const [siteName, setSiteName] = useState('');
  const [notes, setNotes] = useState('');
  const [latitude, setLatitude] = useState('');
  const [longitude, setLongitude] = useState('');
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState('');

  async function loadLocal() {
    const local = await getRecords();
    setRecords(local);
  }

  async function createRecord(e) {
    e.preventDefault();

    const record = {
      id: nanoid(),
      siteName,
      notes,
      latitude: latitude === '' ? null : Number(latitude),
      longitude: longitude === '' ? null : Number(longitude),
      createdAt: nowISO(),
      updatedAt: nowISO(),
      syncStatus: navigator.onLine ? 'pending' : 'pending'
    };

    const next = await addRecord(record);
    setRecords(next);
    setSiteName('');
    setNotes('');
    setLatitude('');
    setLongitude('');
    setStatus('Saved locally.');
  }

  async function doSync() {
    try {
      setStatus('Syncing...');

      const local = await getRecords();
      const pending = local.filter(r => r.syncStatus !== 'synced');

      if (pending.length === 0) {
        setStatus('Nothing to sync.');
        return;
      }

      await syncRecords(pending);

      const synced = local.map(r =>
        pending.some(p => p.id === r.id)
          ? { ...r, syncStatus: 'synced' }
          : r
      );

      await saveRecords(synced);
      setRecords(synced);
      setStatus(`Synced ${pending.length} record(s).`);
    } catch (err) {
      console.error(err);
      setStatus('Sync failed; will retry when online.');
    }
  }

  async function refreshFromServer() {
    try {
      const remote = await fetchRemoteRecords();
      // minimal merge strategy: prefer local pending items, otherwise remote
      const local = await getRecords();
      const pendingLocal = local.filter(r => r.syncStatus !== 'synced');

      const merged = [...remote];
      for (const p of pendingLocal) {
        if (!merged.some(r => r.id === p.id)) merged.push(p);
      }

      await saveRecords(merged);
      setRecords(merged);
    } catch (e) {
      console.warn('Could not refresh remote records');
    }
  }

  useEffect(() => {
    loadLocal();
    refreshFromServer();

    const onOnline = async () => {
      setOnline(true);
      await doSync();
      await refreshFromServer();
    };

    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  return (
    <div style={{ maxWidth: 800, margin: '40px auto', fontFamily: 'sans-serif' }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Network: <strong>{online ? 'Online' : 'Offline'}</strong>
      </p>

      <form onSubmit={createRecord} style={{ display: 'grid', gap: 8, marginBottom: 20 }}>
        <input
          placeholder="Site name"
          value={siteName}
          onChange={e => setSiteName(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
          rows={4}
        />
        <div style={{ display: 'flex', gap: 8 }}>
          <input
            placeholder="Latitude"
            value={latitude}
            onChange={e => setLatitude(e.target.value)}
          />
          <input
            placeholder="Longitude"
            value={longitude}
            onChange={e => setLongitude(e.target.value)}
          />
        </div>
        <button type="submit">Save locally</button>
      </form>

      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        <button onClick={doSync} disabled={!online}>
          Sync now
        </button>
        <button onClick={refreshFromServer} disabled={!online}>
          Refresh from server
        </button>
      </div>

      {status && <p><em>{status}</em></p>}

      <h2>Survey records</h2>
      <ul style={{ padding: 0, listStyle: 'none' }}>
        {records.map(r => (
          <li key={r.id} style={{ border: '1px solid #ddd', padding: 12, marginBottom: 8 }}>
            <div><strong>{r.siteName}</strong></div>
            <div>{r.notes}</div>
            <div>
              {r.latitude ?? '—'}, {r.longitude ?? '—'}
            </div>
            <small>
              {r.createdAt} | {r.syncStatus}
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

