## `client/app.js`

```js
const API_URL = "http://localhost:3000";

const connectionStatus = document.getElementById("connectionStatus");
const surveyForm = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open("fieldSurveyDB", 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      const store = db.createObjectStore("surveys", { keyPath: "localId" });
      store.createIndex("synced", "synced", { unique: false });
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction("surveys", "readonly");
    const store = tx.objectStore("surveys");
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function saveSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction("surveys", "readwrite");
    const store = tx.objectStore("surveys");
    const request = store.put(survey);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function updateSurvey(localId, updates) {
  return new Promise(async (resolve, reject) => {
    try {
      const tx = db.transaction("surveys", "readwrite");
      const store = tx.objectStore("surveys");
      const getReq = store.get(localId);

      getReq.onsuccess = () => {
        const existing = getReq.result;
        if (!existing) {
          resolve();
          return;
        }
        const updated = { ...existing, ...updates };
        store.put(updated);
        resolve();
      };

      getReq.onerror = () => reject(getReq.error);
    } catch (err) {
      reject(err);
    }
  });
}

function renderSurveys(items) {
  surveyList.innerHTML = "";

  if (items.length === 0) {
    surveyList.innerHTML = "<li>No surveys yet.</li>";
    return;
  }

  for (const item of items) {
    const li = document.createElement("li");
    li.className = item.synced ? "synced" : "pending";
    li.innerHTML = `
      <strong>${item.name}</strong><br/>
      ${item.notes || ""}<br/>
      Lat: ${item.lat}, Lng: ${item.lng}<br/>
      <small>${new Date(item.createdAt).toLocaleString()}</small><br/>
      <small>Status: ${item.synced ? "Synced" : "Pending sync"}</small>
    `;
    surveyList.appendChild(li);
  }
}

function updateConnectionStatus() {
  connectionStatus.textContent = navigator.onLine ? "Online" : "Offline";
  connectionStatus.style.color = navigator.onLine ? "green" : "red";
}

async function refreshList() {
  const items = await getAllSurveys();
  renderSurveys(items.sort((a, b) => b.createdAt - a.createdAt));
}

async function syncPending() {
  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when connection returns.");
    return;
  }

  const items = await getAllSurveys();
  const pending = items.filter(item => !item.synced);

  if (pending.length === 0) {
    alert("Nothing to sync.");
    return;
  }

  try {
    const res = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ items: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    for (const item of pending) {
      await updateSurvey(item.localId, { synced: true, syncedAt: new Date().toISOString() });
    }

    await refreshList();
    alert(`Synced ${pending.length} survey(s).`);
  } catch (err) {
    console.error(err);
    alert("Sync failed. Will retry later.");
  }
}

surveyForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById("surveyName").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    lat: Number(document.getElementById("lat").value),
    lng: Number(document.getElementById("lng").value),
    createdAt: Date.now(),
    synced: false
  };

  await saveSurvey(survey);
  surveyForm.reset();
  await refreshList();

  if (navigator.onLine) {
    syncPending();
  }
});

syncBtn.addEventListener("click", syncPending);

window.addEventListener("online", async () => {
  updateConnectionStatus();
  await syncPending();
});

window.addEventListener("offline", updateConnectionStatus);

(async function init() {
  db = await openDB();
  updateConnectionStatus();
  await refreshList();

  if (navigator.onLine) {
    await syncPending();
  }
})();
```

