import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export async function getDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      const store = db.createObjectStore('surveys', { keyPath: 'id' });
      store.createIndex('synced', 'synced');
      store.createIndex('createdAt', 'createdAt');
    }
  });
}

export async function saveSurvey(survey) {
  const db = await getDB();
  await db.put('surveys', survey);
}

export async function getSurveys() {
  const db = await getDB();
  return db.getAll('surveys');
}

export async function getPendingSurveys() {
  const db = await getDB();
  return db.getAllFromIndex('surveys', 'synced', false);
}

export async function markSurveySynced(id) {
  const db = await getDB();
  const survey = await db.get('surveys', id);
  if (survey) {
    survey.synced = true;
    survey.syncedAt = new Date().toISOString();
    await db.put('surveys', survey);
  }
}
