### `client/src/App.jsx`
```jsx
import React, { useEffect, useState } from 'react';
import {
  saveSurvey,
  getSurveys,
  getPendingSurveys,
  markSurveySynced
} from './db';
import { syncSurvey, fetchRemoteSurveys } from './api';

function uid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState('');
  const [site, setSite] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState('');

  async function refreshLocal() {
    const items = await getSurveys();
    items.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setSurveys(items);
  }

  async function trySyncPending() {
    if (!navigator.onLine) return;

    const pending = await getPendingSurveys();
    if (pending.length === 0) return;

    setStatus(`Syncing ${pending.length} pending survey(s)...`);

    for (const survey of pending) {
      try {
        await syncSurvey(survey);
        await markSurveySynced(survey.id);
      } catch (e) {
        console.error(e);
        setStatus('Sync failed. Will retry when online.');
        return;
      }
    }

    setStatus('Sync complete.');
    await refreshLocal();
  }

  useEffect(() => {
    refreshLocal();
    trySyncPending();

    const onOnline = () => {
      setOnline(true);
      trySyncPending();
    };

    const onOffline = () => {
      setOnline(false);
      setStatus('Offline mode: saving locally.');
    };

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function handleSave(e) {
    e.preventDefault();

    const survey = {
      id: uid(),
      name,
      site,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveSurvey(survey);
    setName('');
    setSite('');
    setNotes('');
    setStatus(online ? 'Saved locally. Syncing...' : 'Saved offline.');
    await refreshLocal();

    if (online) {
      try {
        await syncSurvey(survey);
        await markSurveySynced(survey.id);
        setStatus('Saved and synced.');
        await refreshLocal();
      } catch {
        setStatus('Saved locally. Sync will retry later.');
      }
    }
  }

  async function handlePullRemote() {
    if (!navigator.onLine) {
      setStatus('Cannot fetch remote data while offline.');
      return;
    }

    try {
      const remote = await fetchRemoteSurveys();
      setStatus(`Remote server has ${remote.length} survey(s).`);
    } catch (e) {
      setStatus('Failed to fetch remote surveys.');
    }
  }

  return (
    <div style={{ fontFamily: 'sans-serif', maxWidth: 800, margin: '2rem auto' }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <b>{online ? 'Online' : 'Offline'}</b>
      </p>
      <p>{status}</p>

      <form onSubmit={handleSave} style={{ display: 'grid', gap: '0.75rem' }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
        />
        <input
          placeholder="Site name"
          value={site}
          onChange={e => setSite(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <div style={{ marginTop: '1rem' }}>
        <button onClick={trySyncPending}>Sync Pending</button>{' '}
        <button onClick={handlePullRemote}>Check Remote Count</button>
      </div>

      <h2 style={{ marginTop: '2rem' }}>Local Surveys</h2>
      <ul>
        {surveys.map(s => (
          <li key={s.id} style={{ marginBottom: '0.75rem' }}>
            <div><b>{s.site}</b> — {s.name}</div>
            <div>{s.notes}</div>
            <small>
              Created: {new Date(s.createdAt).toLocaleString()} |{' '}
              {s.synced ? `Synced at ${new Date(s.syncedAt).toLocaleString()}` : 'Pending sync'}
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

