### `server/index.js`
```js
import express from "express";
import cors from "cors";
import fs from "fs/promises";
import path from "path";
import { fileURLToPath } from "url";

const app = express();
const PORT = 3001;

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_FILE = path.join(__dirname, "data.json");

app.use(cors());
app.use(express.json());

async function readData() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf-8");
    return JSON.parse(raw);
  } catch {
    return { surveys: [] };
  }
}

async function writeData(data) {
  await fs.writeFile(DATA_FILE, JSON.stringify(data, null, 2));
}

app.get("/api/surveys", async (req, res) => {
  const data = await readData();
  res.json(data.surveys);
});

app.post("/api/surveys/batch", async (req, res) => {
  const { surveys } = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const data = await readData();
  const existingIds = new Set(data.surveys.map(s => s.id));

  const inserted = [];
  for (const survey of surveys) {
    if (!existingIds.has(survey.id)) {
      data.surveys.push({
        ...survey,
        syncedAt: new Date().toISOString()
      });
      inserted.push(survey.id);
      existingIds.add(survey.id);
    }
  }

  await writeData(data);
  res.json({ ok: true, inserted });
});

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

