  const pending = await getPendingSurveys();
  if (pending.length === 0) {
    setStatus();
    return;
  }

  try {
    const response = await fetch(`${API_BASE}/surveys/batch`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ surveys: pending })
    });

    if (!response.ok) throw new Error("Sync failed");

    const result = await response.json();
    await markSynced(result.inserted);
    await renderSurveys();
    setStatus();
  } catch (err) {
    console.error(err);
    setStatus();
  }
}

form.addEventListener("submit", async (e) => {
