```js
import express from "express";
import cors from "cors";
import fs from "fs";

const app = express();
const PORT = 3001;
const DB_FILE = "./db.json";

app.use(cors());
app.use(express.json());

function readDB() {
  return JSON.parse(fs.readFileSync(DB_FILE, "utf-8"));
}

function writeDB(data) {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
}

app.get("/surveys", (req, res) => {
  const db = readDB();
  res.json(db.surveys);
});

app.post("/sync", (req, res) => {
  const { changes } = req.body; // array of {id, name, location, notes, updatedAt}
  const db = readDB();

  for (const change of changes) {
    const idx = db.surveys.findIndex(s => s.id === change.id);
    if (idx >= 0) {
      // last-write-wins
      if (!db.surveys[idx].updatedAt || change.updatedAt > db.surveys[idx].updatedAt) {
        db.surveys[idx] = change;
      }
    } else {
      db.surveys.push(change);
    }
  }

  writeDB(db);
  res.json({ ok: true, surveys: db.surveys });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

