import { openDB } from "idb";

export const dbPromise = openDB("survey-app-db", 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      db.createObjectStore("surveys", { keyPath: "id" });
    }
    if (!db.objectStoreNames.contains("queue")) {
      db.createObjectStore("queue", { keyPath: "id" });
    }
  }
});

export async function getSurveys() {
  const db = await dbPromise;
  return db.getAll("surveys");
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  return db.put("surveys", survey);
}

export async function saveManySurveys(surveys) {
  const db = await dbPromise;
  const tx = db.transaction("surveys", "readwrite");
  for (const s of surveys) tx.store.put(s);
  await tx.done;
}

export async function addToQueue(change) {
  const db = await dbPromise;
  return db.put("queue", change);
}

export async function getQueue() {
  const db = await dbPromise;
  return db.getAll("queue");
}

export async function clearQueue() {
  const db = await dbPromise;
  return db.clear("queue");
}
```

