## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import {
  getSurveys,
  saveSurvey,
  saveManySurveys,
  addToQueue,
  getQueue,
  clearQueue
} from "./db";
import { fetchSurveys, syncChanges } from "./api";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [form, setForm] = useState({
    name: "",
    location: "",
    notes: ""
  });

  async function loadLocal() {
    const local = await getSurveys();
    setSurveys(local);
  }

  async function initialLoad() {
    await loadLocal();

    if (navigator.onLine) {
      try {
        const remote = await fetchSurveys();
        await saveManySurveys(remote);
        setSurveys(remote);
      } catch {}
    }
  }

  async function flushQueue() {
    if (!navigator.onLine) return;

    const queue = await getQueue();
    if (queue.length === 0) return;

    try {
      await syncChanges(queue);
      await clearQueue();
      const remote = await fetchSurveys();
      await saveManySurveys(remote);
      setSurveys(remote);
    } catch {
      // keep queue until next reconnect
    }
  }

  useEffect(() => {
    initialLoad();

    const onOnline = async () => {
      setOnline(true);
      await flushQueue();
    };

    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uuid(),
      name: form.name,
      location: form.location,
      notes: form.notes,
      updatedAt: Date.now()
    };

    await saveSurvey(survey);
    await addToQueue(survey);

    setSurveys(prev => [survey, ...prev]);
    setForm({ name: "", location: "", notes: "" });

    if (navigator.onLine) {
      await flushQueue();
    }
  }

  return (
    <div className="container">
      <h1>Offline Survey App</h1>
      <p className={online ? "status online" : "status offline"}>
        {online ? "Online" : "Offline"} — data is saved locally and synced later.
      </p>

      <form onSubmit={handleSubmit} className="card">
        <input
          placeholder="Survey name"
          value={form.name}
          onChange={e => setForm({ ...form, name: e.target.value })}
          required
        />
        <input
          placeholder="Location"
          value={form.location}
          onChange={e => setForm({ ...form, location: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={e => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <div className="card">
        <h2>Saved Surveys</h2>
        {surveys.length === 0 ? (
          <p>No surveys yet.</p>
        ) : (
          <ul>
            {surveys.map(s => (
              <li key={s.id}>
                <strong>{s.name}</strong> — {s.location}
                <div>{s.notes}</div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
```

