```javascript
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const connectionStatus = document.getElementById("connectionStatus");
const syncBtn = document.getElementById("syncBtn");

const API_URL = "http://localhost:3000/api/surveys";

function setConnectionStatus() {
  connectionStatus.textContent = navigator.onLine
    ? "Online"
    : "Offline - data will sync later";
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = "";

  if (surveys.length === 0) {
    surveyList.innerHTML = "<li>No surveys saved yet.</li>";
    return;
  }

  for (const survey of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <div><strong>${survey.siteName}</strong> by ${survey.surveyorName}</div>
      <div>${survey.notes || ""}</div>
      <div>${new Date(survey.createdAt).toLocaleString()}</div>
      <div class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending Sync"}
      </div>
    `;
    surveyList.appendChild(li);
  }
}

async function syncPendingSurveys() {
  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when connection is restored.");
    return;
  }

  const pending = await getPendingSurveys();
  if (pending.length === 0) {
    alert("No pending surveys to sync.");
    return;
  }

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey),
      });

      if (!res.ok) throw new Error("Sync failed");

      await markSurveySynced(survey.id);
    } catch (err) {
      console.error("Sync error:", err);
      alert("Some surveys could not be synced.");
      break;
    }
  }

  await renderSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    surveyorName: document.getElementById("surveyorName").value.trim(),
    siteName: document.getElementById("siteName").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: Date.now(),
    synced: false,
  };

  await saveSurvey(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
});

syncBtn.addEventListener("click", syncPendingSurveys);

window.addEventListener("online", async () => {
  setConnectionStatus();
  await syncPendingSurveys();
});

window.addEventListener("offline", setConnectionStatus);

setConnectionStatus();
renderSurveys();
