```javascript
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const receivedSurveys = [];

app.post("/api/surveys", (req, res) => {
  const survey = req.body;

  if (!survey || !survey.id || !survey.surveyorName || !survey.siteName) {
    return res.status(400).json({ error: "Invalid survey data" });
  }

  receivedSurveys.push({
    ...survey,
    receivedAt: Date.now(),
  });

  console.log("Received survey:", survey.id);
  res.status(201).json({ ok: true });
});

app.get("/api/surveys", (req, res) => {
  res.json(receivedSurveys);
});

app.listen(3000, () => {
  console.log("Survey server running on http://localhost:3000");
});
