## 6) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:3000";
const DB_NAME = "field-survey-db";
const DB_VERSION = 1;
const SURVEYS_STORE = "surveys";
const QUEUE_STORE = "queue";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");

let db;

function setStatus(online) {
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;

      if (!db.objectStoreNames.contains(SURVEYS_STORE)) {
        db.createObjectStore(SURVEYS_STORE, { keyPath: "id" });
      }

      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        db.createObjectStore(QUEUE_STORE, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function tx(storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

function getAll(storeName) {
  return new Promise((resolve, reject) => {
    const request = tx(storeName).getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function put(storeName, value) {
  return new Promise((resolve, reject) => {
    const request = tx(storeName, "readwrite").put(value);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function del(storeName, id) {
  return new Promise((resolve, reject) => {
    const request = tx(storeName, "readwrite").delete(id);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

async function loadSurveys() {
  const surveys = await getAll(SURVEYS_STORE);
  surveyList.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((survey) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <strong>${survey.name}</strong><br/>
        Location: ${survey.location}<br/>
        Notes: ${survey.notes || ""}<br/>
        <small>Status: ${survey.synced ? "Synced" : "Pending sync"}</small>
      `;
      surveyList.appendChild(li);
    });
}

async function saveSurveyLocally(survey) {
  await put(SURVEYS_STORE, survey);
  await put(QUEUE_STORE, survey);
  await loadSurveys();
}

async function syncQueue() {
  if (!navigator.onLine) {
    setStatus(false);
    return;
  }

  const queued = await getAll(QUEUE_STORE);

  for (const survey of queued) {
    try {
      const res = await fetch(`${API_URL}/surveys`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey),
      });

      if (!res.ok) throw new Error("Sync failed");

      await put(SURVEYS_STORE, { ...survey, synced: true });
      await del(QUEUE_STORE, survey.id);
    } catch (err) {
      console.error("Sync error:", err);
      break;
    }
  }

  await loadSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false,
  };

  await saveSurveyLocally(survey);
  form.reset();

  if (navigator.onLine) {
    await syncQueue();
  }
});

syncBtn.addEventListener("click", syncQueue);

window.addEventListener("online", async () => {
  setStatus(true);
  await syncQueue();
});

window.addEventListener("offline", () => {
  setStatus(false);
});

(async function init() {
  db = await openDB();
  setStatus(navigator.onLine);
  await loadSurveys();
  await syncQueue();
})();
```

