import express from "express";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

let surveys = []; // in-memory demo store

app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

app.post("/api/sync", (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: "changes must be an array" });
  }

  for (const change of changes) {
    if (change.type === "upsert") {
      const idx = surveys.findIndex((s) => s.id === change.data.id);
      if (idx >= 0) surveys[idx] = change.data;
      else surveys.push(change.data);
    } else if (change.type === "delete") {
      surveys = surveys.filter((s) => s.id !== change.id);
    }
  }

  res.json({ ok: true, surveys });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
