import localforage from "localforage";

export const surveyStore = localforage.createInstance({
  name: "survey-app",
  storeName: "surveys"
});

export const outboxStore = localforage.createInstance({
  name: "survey-app",
  storeName: "outbox"
});

export async function getAllSurveys() {
  const items = [];
  await surveyStore.iterate((value) => items.push(value));
  return items;
}

export async function saveSurvey(survey) {
  await surveyStore.setItem(survey.id, survey);
}

export async function deleteSurvey(id) {
  await surveyStore.removeItem(id);
}

export async function addToOutbox(change) {
  const key = `${Date.now()}-${Math.random()}`;
  await outboxStore.setItem(key, change);
}

export async function getOutbox() {
  const items = [];
  await outboxStore.iterate((value, key) => items.push({ key, value }));
  return items;
}

export async function clearOutboxItem(key) {
  await outboxStore.removeItem(key);
}
```

