### `client/src/App.jsx`
```jsx
import { useEffect, useState } from "react";
import {
  getAllSurveys,
  saveSurvey,
  deleteSurvey,
  addToOutbox,
  getOutbox,
  clearOutboxItem
} from "./db";
import { fetchServerSurveys, syncChanges } from "./api";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [connected, setConnected] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  async function loadLocal() {
    const items = await getAllSurveys();
    setSurveys(items);
  }

  async function createSurvey() {
    if (!name.trim()) return;

    const survey = {
      id: uuid(),
      name,
      location,
      createdAt: new Date().toISOString()
    };

    await saveSurvey(survey);
    await addToOutbox({ type: "upsert", data: survey });

    setName("");
    setLocation("");
    await loadLocal();
    setStatus("Saved locally");
  }

  async function removeSurvey(id) {
    await deleteSurvey(id);
    await addToOutbox({ type: "delete", id });
    await loadLocal();
    setStatus("Deleted locally");
  }

  async function sync() {
    if (!navigator.onLine) {
      setStatus("Offline, cannot sync");
      return;
    }

    try {
      const outbox = await getOutbox();
      if (outbox.length === 0) {
        setStatus("Nothing to sync");
        return;
      }

      const changes = outbox.map((x) => x.value);
      await syncChanges(changes);

      for (const item of outbox) {
        await clearOutboxItem(item.key);
      }

      const serverData = await fetchServerSurveys();
      // overwrite local store with server state for this minimal demo
      for (const s of serverData) {
        await saveSurvey(s);
      }

      await loadLocal();
      setStatus("Synced successfully");
    } catch (e) {
      setStatus(`Sync failed: ${e.message}`);
    }
  }

  useEffect(() => {
    loadLocal();

    const onOnline = async () => {
      setConnected(true);
      await sync();
    };

    const onOffline = () => setConnected(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, maxWidth: 700 }}>
      <h1>Offline Survey App</h1>

      <p>
        Status:{" "}
        <strong style={{ color: connected ? "green" : "red" }}>
          {connected ? "Online" : "Offline"}
        </strong>
      </p>

      <button onClick={sync}>Sync now</button>
      <p>{status}</p>

      <hr />

      <h2>New Survey</h2>
      <input
        placeholder="Survey name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <input
        placeholder="Location"
        value={location}
        onChange={(e) => setLocation(e.target.value)}
        style={{ marginLeft: 8 }}
      />
      <button onClick={createSurvey} style={{ marginLeft: 8 }}>
        Save
      </button>

      <hr />

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.location}{" "}
            <button onClick={() => removeSurvey(s.id)} style={{ marginLeft: 8 }}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
