app.post("/api/surveys/bulk", (req, res) => {
  const incoming = req.body.surveys || [];

  for (const item of incoming) {
    const idx = surveys.findIndex(s => s.id === item.id);
    if (idx >= 0) {
      // last write wins
      if ((item.updatedAt || 0) >= (surveys[idx].updatedAt || 0)) {
        surveys[idx] = item;
      }
    } else {
      surveys.push(item);
    }
  }

  res.json({ ok: true, count: incoming.length });
});

