## 5) IndexedDB helper

### `client/src/db.js`
```js
import { openDB } from "idb";

const DB_NAME = "survey-db";
const DB_VERSION = 1;

export async function getDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      const surveys = db.createObjectStore("surveys", { keyPath: "id" });
      surveys.createIndex("updatedAt", "updatedAt");

      db.createObjectStore("pending", { keyPath: "id" });
    }
  });
}

export async function getAllSurveys() {
  const db = await getDB();
  return db.getAll("surveys");
}

export async function saveSurvey(survey) {
  const db = await getDB();
  await db.put("surveys", survey);
}

export async function savePendingChange(record) {
  const db = await getDB();
  await db.put("pending", record);
}

export async function getPendingChanges() {
  const db = await getDB();
  return db.getAll("pending");
}

export async function clearPendingChange(id) {
  const db = await getDB();
  await db.delete("pending", id);
}

export async function replaceAllSurveys(items) {
  const db = await getDB();
  const tx = db.transaction("surveys", "readwrite");
  await tx.objectStore("surveys").clear();
  for (const item of items) {
    await tx.objectStore("surveys").put(item);
  }
  await tx.done;
}
```

