## 6) Sync logic

### `client/src/sync.js`
```js
import {
  getPendingChanges,
  clearPendingChange,
  replaceAllSurveys,
  saveSurvey
} from "./db";

const API = "http://localhost:4000/api";

export async function syncNow() {
  if (!navigator.onLine) return { ok: false, reason: "offline" };

  // 1) Push pending local changes
  const pending = await getPendingChanges();
  if (pending.length > 0) {
    const surveys = pending.map(p => p.data);

    const res = await fetch(`${API}/surveys/bulk`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ surveys })
    });

    if (!res.ok) throw new Error("Failed to push pending changes");

    for (const item of pending) {
      await clearPendingChange(item.id);
    }
  }

  // 2) Pull latest from server
  const res = await fetch(`${API}/surveys`);
  if (!res.ok) throw new Error("Failed to fetch surveys");

  const serverSurveys = await res.json();
  await replaceAllSurveys(serverSurveys);

  return { ok: true, count: serverSurveys.length };
}

export async function queueSurveyChange(survey) {
  await saveSurvey(survey);
  await savePendingChange({
    id: survey.id,
    data: survey
  });
}
