import React, { useEffect, useState } from "react";
import { getAllSurveys } from "./db";
import { queueSurveyChange, syncNow } from "./sync";

function makeId() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [status, setStatus] = useState(navigator.onLine ? "Online" : "Offline");
  const [syncMsg, setSyncMsg] = useState("");

  async function refresh() {
    const items = await getAllSurveys();
    setSurveys(items.sort((a, b) => b.updatedAt - a.updatedAt));
  }

  useEffect(() => {
    refresh();

    const onOnline = async () => {
      setStatus("Online");
      try {
        setSyncMsg("Syncing...");
        await syncNow();
        await refresh();
        setSyncMsg("Synced");
      } catch (e) {
        setSyncMsg("Sync failed");
      }
    };

    const onOffline = () => setStatus("Offline");

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function addSurvey(e) {
    e.preventDefault();

    const survey = {
      id: makeId(),
      name,
      location,
      updatedAt: Date.now()
    };

    await queueSurveyChange(survey);
    await refresh();

    setName("");
    setLocation("");
    setSyncMsg(navigator.onLine ? "Saved locally and queued for sync" : "Saved offline");
  }

  async function manualSync() {
    try {
      setSyncMsg("Syncing...");
      await syncNow();
      await refresh();
      setSyncMsg("Synced successfully");
    } catch (e) {
      setSyncMsg("Sync failed");
    }
  }

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "40px auto" }}>
      <h1>Offline Field Survey App</h1>
