## `server/index.js`

```js
import express from "express";
import cors from "cors";
import sqlite3 from "sqlite3";
import { open } from "sqlite";

const app = express();
app.use(cors());
app.use(express.json());

const db = await open({
  filename: "./survey.db",
  driver: sqlite3.Database
});

await db.exec(`
  CREATE TABLE IF NOT EXISTS surveys (
    id TEXT PRIMARY KEY,
    siteName TEXT NOT NULL,
    observer TEXT NOT NULL,
    notes TEXT,
    latitude REAL,
    longitude REAL,
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL
  );
`);

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

app.get("/surveys", async (req, res) => {
  const rows = await db.all("SELECT * FROM surveys ORDER BY createdAt DESC");
  res.json(rows);
});

app.post("/sync", async (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: "records must be an array" });
  }

  const results = [];

  for (const record of records) {
    const {
      id,
      siteName,
      observer,
      notes,
      latitude,
      longitude,
      createdAt,
      updatedAt
    } = record;

    if (!id || !siteName || !observer || !createdAt || !updatedAt) {
      results.push({ id: id || null, status: "error", error: "missing fields" });
      continue;
    }

    await db.run(
      `
      INSERT INTO surveys (id, siteName, observer, notes, latitude, longitude, createdAt, updatedAt)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        siteName=excluded.siteName,
        observer=excluded.observer,
        notes=excluded.notes,
        latitude=excluded.latitude,
        longitude=excluded.longitude,
        updatedAt=excluded.updatedAt
      `,
      [id, siteName, observer, notes || "", latitude ?? null, longitude ?? null, createdAt, updatedAt]
    );

    results.push({ id, status: "ok" });
  }

  res.json({ results });
});

const port = process.env.PORT || 3001;
app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
```

