import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import {
  getAllSurveys,
  getPendingSurveys,
  saveSurvey
} from "./db";
import { syncSurveys, fetchServerSurveys } from "./api";

export default function App() {
  const [form, setForm] = useState({
    siteName: "",
    observer: "",
    notes: "",
    latitude: "",
    longitude: ""
  });
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [message, setMessage] = useState("");

  async function loadLocal() {
    const items = await getAllSurveys();
    items.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
    setSurveys(items);
  }

  async function syncPending() {
    if (!navigator.onLine) return;

    const pending = await getPendingSurveys();
    if (pending.length === 0) return;

    try {
      const result = await syncSurveys(pending);

      const syncedIds = new Set(
        result.results.filter(r => r.status === "ok").map(r => r.id)
      );

      const updated = pending.map(r =>
        syncedIds.has(r.id) ? { ...r, syncStatus: "synced" } : r
      );

      for (const record of updated) {
        await saveSurvey(record);
      }

      setMessage(`Synced ${syncedIds.size} record(s).`);
      await loadLocal();
    } catch (err) {
      setMessage(`Sync failed: ${err.message}`);
    }
  }

  useEffect(() => {
    loadLocal();
    syncPending();

    const onOnline = () => {
      setOnline(true);
      syncPending();
    };

    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const record = {
      id: uuidv4(),
      siteName: form.siteName,
      observer: form.observer,
      notes: form.notes,
      latitude: form.latitude ? Number(form.latitude) : null,
      longitude: form.longitude ? Number(form.longitude) : null,
      createdAt: now,
      updatedAt: now,
      syncStatus: navigator.onLine ? "pending" : "pending"
    };

    await saveSurvey(record);
    setForm({
      siteName: "",
      observer: "",
      notes: "",
      latitude: "",
      longitude: ""
    });

    setMessage("Saved locally.");
    await loadLocal();
    await syncPending();
  }

  async function refreshFromServer() {
    if (!navigator.onLine) {
      setMessage("Cannot refresh while offline.");
      return;
    }

    const serverRecords = await fetchServerSurveys();
    setMessage(`Server has ${serverRecords.length} record(s).`);
  }

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 800, margin: "2rem auto" }}>
      <h1>Offline Survey App</h1>

      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>

      {message && <p>{message}</p>}

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "0.75rem" }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Observer"
          value={form.observer}
          onChange={(e) => setForm({ ...form, observer: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <input
          placeholder="Latitude"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
        />
        <input
          placeholder="Longitude"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <div style={{ marginTop: "1rem" }}>
        <button onClick={syncPending}>Sync Pending</button>{" "}
        <button onClick={refreshFromServer}>Check Server Count</button>
      </div>

      <h2 style={{ marginTop: "2rem" }}>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: "1rem" }}>
            <strong>{s.siteName}</strong> — {s.observer}
            <br />
            Status: {s.syncStatus}
            <br />
            Notes: {s.notes || "-"}
            <br />
            Lat/Lng: {s.latitude ?? "-"}, {s.longitude ?? "-"}
          </li>
        ))}
      </ul>
    </div>
  );
}
