## 5) Sync logic

### `client/src/sync.js`
```js
import { getUnsyncedSurveys, markSurveySynced } from "./db";

const API_URL = "http://localhost:3001/api/surveys";

export async function syncSurveys() {
  if (!navigator.onLine) return { synced: 0 };

  const unsynced = await getUnsyncedSurveys();
  let syncedCount = 0;

  for (const survey of unsynced) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await markSurveySynced(survey.id);
        syncedCount++;
      }
    } catch {
      // stop if network fails mid-sync
      break;
    }
  }

  return { synced: syncedCount };
}
```

