    e.preventDefault();

    const survey = {
      id: crypto.randomUUID(),
      name: form.name,
      location: form.location,
      notes: form.notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveSurvey(survey);
    setForm({ name: "", location: "", notes: "" });
    await loadSurveys();
    setMessage("Saved locally. Will sync when online.");
  }

  async function handleSync() {
    const result = await syncSurveys();
    await loadSurveys();
    setMessage(`Synced ${result.synced} record(s).`);
  }

  useEffect(() => {
    loadSurveys();

    const onOnline = async () => {
      setOnline(true);
      setMessage("Back online. Syncing...");
      await handleSync();
    };

    const onOffline = () => {
      setOnline(false);
      setMessage("Offline mode.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "2rem auto" }}>
      <h1>Offline Field Survey App</h1>
      <p>Status: <strong>{online ? "Online" : "Offline"}</strong></p>
      <button onClick={handleSync}>Sync Now</button>
      <p>{message}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "0.75rem", marginTop: "1rem" }}>
        <input
          placeholder="Survey name"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
          required
        />
        <input
          placeholder="Location"
          value={form.location}
          onChange={(e) => setForm({ ...form, location: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2 style={{ marginTop: "2rem" }}>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.location}
            {s.synced ? " ✅ synced" : " ⏳ pending"}
          </li>
        ))}
      </ul>
    </div>
  );
}
