```js
import express from "express";
import cors from "cors";
import Database from "better-sqlite3";

const app = express();
app.use(cors());
app.use(express.json());

const db = new Database("db.sqlite");

db.exec(`
  CREATE TABLE IF NOT EXISTS surveys (
    id TEXT PRIMARY KEY,
    siteName TEXT,
    latitude REAL,
    longitude REAL,
    notes TEXT,
    updatedAt INTEGER,
    deleted INTEGER DEFAULT 0
  );
`);

app.get("/surveys", (req, res) => {
  const rows = db.prepare("SELECT * FROM surveys WHERE deleted = 0").all();
  res.json(rows);
});

app.post("/sync", (req, res) => {
  const { changes = [], lastSync = 0 } = req.body;

  const upsert = db.prepare(`
    INSERT INTO surveys (id, siteName, latitude, longitude, notes, updatedAt, deleted)
    VALUES (@id, @siteName, @latitude, @longitude, @notes, @updatedAt, @deleted)
    ON CONFLICT(id) DO UPDATE SET
      siteName = excluded.siteName,
      latitude = excluded.latitude,
      longitude = excluded.longitude,
      notes = excluded.notes,
      updatedAt = excluded.updatedAt,
      deleted = excluded.deleted
    WHERE excluded.updatedAt >= surveys.updatedAt
  `);

  const serverChanges = db.prepare(`
    SELECT * FROM surveys
    WHERE updatedAt > ? 
  `).all(lastSync);

  const tx = db.transaction((items) => {
    for (const item of items) {
      upsert.run({
        ...item,
        deleted: item.deleted ? 1 : 0
      });
    }
  });

  tx(changes);

  const newServerChanges = db.prepare(`
    SELECT * FROM surveys
    WHERE updatedAt > ?
  `).all(lastSync);

  res.json({
    ok: true,
    changes: newServerChanges,
    serverTime: Date.now()
  });
});

app.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

