# 5) Frontend: IndexedDB storage

## `client/src/db.js`

```js
const DB_NAME = "survey-db";
const DB_VERSION = 1;
const SURVEYS = "surveys";
const OUTBOX = "outbox";
const META = "meta";

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);

    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(SURVEYS)) {
        db.createObjectStore(SURVEYS, { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains(OUTBOX)) {
        db.createObjectStore(OUTBOX, { keyPath: "id", autoIncrement: true });
      }
      if (!db.objectStoreNames.contains(META)) {
        db.createObjectStore(META, { keyPath: "key" });
      }
    };

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function withStore(storeName, mode, fn) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);
    const result = fn(store);
    tx.oncomplete = () => resolve(result);
    tx.onerror = () => reject(tx.error);
  });
}

export async function getAllSurveys() {
  return withStore(SURVEYS, "readonly", (store) => {
    return new Promise((resolve) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result.filter((x) => !x.deleted));
    });
  });
}

export async function saveSurvey(survey) {
  await withStore(SURVEYS, "readwrite", (store) => store.put(survey));
  await withStore(OUTBOX, "readwrite", (store) => store.add({ type: "upsert", survey }));
}

export async function deleteSurvey(id) {
  const existing = await getSurvey(id);
  if (!existing) return;
  const deleted = { ...existing, deleted: true, updatedAt: Date.now() };
  await withStore(SURVEYS, "readwrite", (store) => store.put(deleted));
  await withStore(OUTBOX, "readwrite", (store) => store.add({ type: "delete", survey: deleted }));
}

export async function getSurvey(id) {
  return withStore(SURVEYS, "readonly", (store) => {
    return new Promise((resolve) => {
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result);
    });
  });
}

export async function getOutbox() {
  return withStore(OUTBOX, "readonly", (store) => {
    return new Promise((resolve) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result);
    });
  });
}

export async function clearOutbox() {
  return withStore(OUTBOX, "readwrite", (store) => store.clear());
}

export async function getMeta(key) {
  return withStore(META, "readonly", (store) => {
    return new Promise((resolve) => {
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result?.value);
    });
  });
}

export async function setMeta(key, value) {
  return withStore(META, "readwrite", (store) => store.put({ key, value }));
}
```

