# 7) Frontend: App UI

## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import {
  getAllSurveys,
  saveSurvey,
  deleteSurvey,
  getOutbox,
  clearOutbox,
  getMeta,
  setMeta
} from "./db";
import { fetchSurveys, syncChanges } from "./api";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [form, setForm] = useState({
    siteName: "",
    latitude: "",
    longitude: "",
    notes: ""
  });

  async function refreshLocal() {
    const items = await getAllSurveys();
    setSurveys(items);
  }

  async function syncNow() {
    if (!navigator.onLine) return;

    const outbox = await getOutbox();
    const changes = outbox.map((item) => item.survey);
    const lastSync = (await getMeta("lastSync")) || 0;

    if (changes.length === 0) {
      const remote = await fetchSurveys();
      setSurveys(remote);
      return;
    }

    const result = await syncChanges(changes, lastSync);

    if (result.ok) {
      for (const s of result.changes) {
        await saveSurvey({ ...s, deleted: !!s.deleted });
      }
      await clearOutbox();
      await setMeta("lastSync", result.serverTime);
      await refreshLocal();
    }
  }

  useEffect(() => {
    refreshLocal();
    syncNow();

    const onOnline = async () => {
      setOnline(true);
      await syncNow();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uuid(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      updatedAt: Date.now(),
      deleted: false
    };

    await saveSurvey(survey);
    setForm({ siteName: "", latitude: "", longitude: "", notes: "" });
    await refreshLocal();
    if (navigator.onLine) await syncNow();
  }

  return (
    <div style={{ maxWidth: 700, margin: "0 auto", fontFamily: "sans-serif", padding: 16 }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 8, marginBottom: 24 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={syncNow} disabled={!online}>
        Sync Now
      </button>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <strong>{s.siteName}</strong>
            <div>
              {s.latitude}, {s.longitude}
            </div>
            <div>{s.notes}</div>
            <button onClick={async () => { await deleteSurvey(s.id); await refreshLocal(); }}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
