### `client/app.js`
```js
const DB_NAME = "survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000/api/surveys";

let db;

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("synced", "synced", { unique: false });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function id() {
  return crypto.randomUUID();
}

function setStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline - saving locally";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function saveSurvey(record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(record);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function updateSurvey(id, changes) {
  return new Promise(async (resolve, reject) => {
    try {
      const tx = db.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const getReq = store.get(id);

      getReq.onsuccess = () => {
        const existing = getReq.result;
        if (!existing) return reject(new Error("Record not found"));
        const updated = { ...existing, ...changes };
        store.put(updated).onsuccess = () => resolve();
      };

      getReq.onerror = () => reject(getReq.error);
    } catch (err) {
      reject(err);
    }
  });
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((s) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <div><strong>${s.siteName}</strong></div>
        <div>Lat: ${s.latitude}, Lng: ${s.longitude}</div>
        <div>${s.notes || ""}</div>
        <div class="${s.synced ? "synced" : "pending"}">
          ${s.synced ? "Synced" : "Pending sync"}
        </div>
      `;
      surveyList.appendChild(li);
    });
}

async function syncPendingSurveys() {
  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when reconnected.");
    return;
  }

  const surveys = await getAllSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!response.ok) throw new Error("Sync failed");

      await updateSurvey(survey.id, { synced: true, syncedAt: new Date().toISOString() });
    } catch (err) {
      console.error("Failed to sync record:", survey.id, err);
    }
  }

  await renderSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: id(),
    siteName: document.getElementById("siteName").value.trim(),
    latitude: Number(document.getElementById("latitude").value),
    longitude: Number(document.getElementById("longitude").value),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurvey(record);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
});

syncBtn.addEventListener("click", syncPendingSurveys);

window.addEventListener("online", async () => {
  setStatus();
  await syncPendingSurveys();
});

window.addEventListener("offline", setStatus);

(async function init() {
  db = await openDB();
  setStatus();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
})();
