## 6) `public/app.js`

```js
const DB_NAME = "field-survey-db";
const DB_VERSION = 1;
const STORE_NAME = "pendingSurveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function updateStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online
    ? "Online — ready to sync"
    : "Offline — saving locally";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function getAllPending() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function savePending(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(survey);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function deletePending(id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(id);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

async function renderSurveys() {
  const pending = await getAllPending();
  surveyList.innerHTML = "";

  if (pending.length === 0) {
    surveyList.innerHTML = "<li>No local surveys queued.</li>";
    return;
  }

  pending.forEach((survey) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.siteName}</strong><br />
      <small>${new Date(survey.createdAt).toLocaleString()}</small><br />
      <p>${survey.notes || ""}</p>
      <em>Status: pending sync</em>
    `;
    surveyList.appendChild(li);
  });
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await getAllPending();
  for (const survey of pending) {
    try {
      const res = await fetch("/api/surveys", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await deletePending(survey.id);
      }
    } catch (err) {
      // Stop syncing if server is unreachable
      break;
    }
  }

  await renderSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    siteName: document.getElementById("siteName").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString()
  };

  await savePending(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPending();
  }
});

window.addEventListener("online", async () => {
  updateStatus();
  await syncPending();
});

window.addEventListener("offline", updateStatus);

(async function init() {
  db = await openDB();
  updateStatus();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPending();
  }
})();
