import { openDB } from 'idb';

const DB_NAME = 'survey-db';
const DB_VERSION = 1;

export async function getDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('synced', 'synced');
      }
      if (!db.objectStoreNames.contains('queue')) {
        db.createObjectStore('queue', { keyPath: 'id' });
      }
    },
  });
}

export async function getAllSurveys() {
  const db = await getDB();
  return db.getAll('surveys');
}

export async function saveSurvey(survey) {
  const db = await getDB();
  return db.put('surveys', survey);
}

export async function getQueue() {
  const db = await getDB();
  return db.getAll('queue');
}

export async function addToQueue(item) {
  const db = await getDB();
  return db.put('queue', item);
}

export async function removeFromQueue(id) {
  const db = await getDB();
  return db.delete('queue', id);
}
```

