## 7) src/sync.js

```js
import { getQueue, removeFromQueue, saveSurvey } from './db';
import { sendSurveyToServer } from './api';

export async function syncQueue(setStatus) {
  if (!navigator.onLine) {
    setStatus('Offline');
    return;
  }

  const queue = await getQueue();
  if (queue.length === 0) {
    setStatus('All synced');
    return;
  }

  setStatus(`Syncing ${queue.length} item(s)...`);

  for (const item of queue) {
    try {
      const syncedSurvey = await sendSurveyToServer(item.data);
      await saveSurvey(syncedSurvey);
      await removeFromQueue(item.id);
    } catch (err) {
      console.error('Sync failed for item', item.id, err);
      setStatus('Sync failed');
      return;
    }
  }

  setStatus('All synced');
}
```

