```jsx
import { useEffect, useState } from 'react';
import { addToQueue, getAllSurveys, saveSurvey } from './db';
import { syncQueue } from './sync';

function uid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState(navigator.onLine ? 'Online' : 'Offline');
  const [form, setForm] = useState({
    siteName: '',
    latitude: '',
    longitude: '',
    notes: '',
  });

  async function loadSurveys() {
    const data = await getAllSurveys();
    setSurveys(data.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || '')));
  }

  useEffect(() => {
    loadSurveys();

    const onOnline = async () => {
      setStatus('Online');
      await syncQueue(setStatus);
      await loadSurveys();
    };

    const onOffline = () => setStatus('Offline');

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uid(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      createdAt: new Date().toISOString(),
      synced: false,
    };

    await saveSurvey(survey);
    await addToQueue({ id: survey.id, data: survey });

    setForm({ siteName: '', latitude: '', longitude: '', notes: '' });
    await loadSurveys();

    if (navigator.onLine) {
      await syncQueue(setStatus);
      await loadSurveys();
    } else {
      setStatus('Saved offline');
    }
  }

  return (
    <div className="app">
      <h1>Offline Survey App</h1>
      <p>Status: <strong>{status}</strong></p>

      <form onSubmit={handleSubmit} className="form">
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Survey Records</h2>
      <ul className="list">
        {surveys.map((s) => (
          <li key={s.id} className="card">
            <div><strong>{s.siteName}</strong></div>
            <div>{s.latitude}, {s.longitude}</div>
            <div>{s.notes}</div>
            <div className={s.synced ? 'synced' : 'pending'}>
              {s.synced ? 'Synced' : 'Pending sync'}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
