# 5) Frontend logic: `public/app.js`

This uses IndexedDB to store surveys locally and sync them later.

```js
const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;

const statusEl = document.getElementById('status');
const surveyListEl = document.getElementById('surveyList');
const form = document.getElementById('surveyForm');
const syncBtn = document.getElementById('syncBtn');

function setStatus() {
  statusEl.textContent = navigator.onLine
    ? 'Online - ready to sync'
    : 'Offline - saving locally';
  statusEl.className = navigator.onLine ? 'status online' : 'status offline';
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function saveLocalSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function deleteLocalSurvey(id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderSurveys() {
  const surveys = await getLocalSurveys();
  surveyListEl.innerHTML = '';

  if (surveys.length === 0) {
    surveyListEl.innerHTML = '<li>No local surveys yet.</li>';
    return;
  }

  for (const s of surveys) {
    const li = document.createElement('li');
    li.innerHTML = `
      <strong>${escapeHtml(s.name)}</strong><br/>
      ${escapeHtml(s.location)}<br/>
      <small>${escapeHtml(s.notes || '')}</small><br/>
      <small>Status: ${s.synced ? 'Synced' : 'Pending sync'}</small>
    `;
    surveyListEl.appendChild(li);
  }
}

async function syncSurveys() {
  if (!navigator.onLine) {
    alert('You are offline. Sync will happen when you reconnect.');
    return;
  }

  const surveys = await getLocalSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (pending.length === 0) {
    alert('Nothing to sync.');
    return;
  }

  const response = await fetch('/api/sync', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ items: pending })
  });

  if (!response.ok) {
    throw new Error('Sync failed');
  }

  // Mark local items as synced
  for (const item of pending) {
    item.synced = true;
    await saveLocalSurvey(item);
  }

  await renderSurveys();
  alert(`Synced ${pending.length} survey(s).`);
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById('name').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveLocalSurvey(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    try {
      await syncSurveys();
    } catch (err) {
      console.error(err);
      alert('Saved locally, but sync failed.');
    }
  } else {
    alert('Saved locally. Will sync when online.');
  }
});

syncBtn.addEventListener('click', async () => {
  try {
    await syncSurveys();
  } catch (err) {
    console.error(err);
    alert('Sync failed.');
  }
});

window.addEventListener('online', async () => {
  setStatus();
  try {
    await syncSurveys();
  } catch (err) {
    console.error(err);
  }
});

window.addEventListener('offline', setStatus);

function escapeHtml(str) {
  return str
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

(async function init() {
  await openDB();
  setStatus();
  await renderSurveys();
})();
```

