import localforage from "localforage";

export const surveyStore = localforage.createInstance({
  name: "survey-app",
  storeName: "surveys"
});

export const queueStore = localforage.createInstance({
  name: "survey-app",
  storeName: "queue"
});

export async function getAllSurveys() {
  const items = [];
  await surveyStore.iterate((value) => items.push(value));
  return items;
}

export async function saveSurvey(survey) {
  await surveyStore.setItem(survey.id, survey);
}

export async function getQueue() {
  const items = [];
  await queueStore.iterate((value) => items.push(value));
  return items;
}

export async function addToQueue(survey) {
  await queueStore.setItem(survey.id, survey);
}

export async function removeFromQueue(id) {
  await queueStore.removeItem(id);
}
```

