### `client/src/App.jsx`
```jsx
import { useEffect, useState } from "react";
import { addToQueue, getAllSurveys, getQueue, removeFromQueue, saveSurvey } from "./db";
import { fetchSurveys, postSurvey } from "./api";

function uid() {
  return crypto.randomUUID();
}

export default function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState("Loading...");
  const [online, setOnline] = useState(navigator.onLine);

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => b.createdAt - a.createdAt));
  }

  async function syncQueue() {
    const queue = await getQueue();
    if (!queue.length) return;

    for (const survey of queue) {
      try {
        await postSurvey(survey);
        await removeFromQueue(survey.id);
      } catch {
        break;
      }
    }
  }

  async function refreshFromServer() {
    try {
      const remote = await fetchSurveys();
      for (const survey of remote) {
        await saveSurvey(survey);
      }
      await loadLocal();
      setStatus("Synced with server");
    } catch {
      setStatus("Offline: showing local data");
    }
  }

  useEffect(() => {
    const init = async () => {
      await loadLocal();
      await syncQueue();
      await refreshFromServer();
    };
    init();

    const onOnline = async () => {
      setOnline(true);
      setStatus("Back online. Syncing...");
      await syncQueue();
      await refreshFromServer();
    };

    const onOffline = () => {
      setOnline(false);
      setStatus("Offline mode");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uid(),
      name,
      location,
      notes,
      createdAt: Date.now()
    };

    await saveSurvey(survey);
    await addToQueue(survey);
    setSurveys((prev) => [survey, ...prev]);
    setName("");
    setLocation("");
    setNotes("");
    setStatus("Saved locally. Will sync when online.");

    if (navigator.onLine) {
      try {
        await postSurvey(survey);
        await removeFromQueue(survey.id);
        setStatus("Saved and synced.");
      } catch {
        setStatus("Saved locally. Sync failed.");
      }
    }
  }

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 800, margin: "2rem auto", padding: 16 }}>
      <h1>Offline Survey App</h1>
      <p>
        Status: <strong>{status}</strong> | Network: <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 8, marginBottom: 24 }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={4}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      <ul style={{ paddingLeft: 16 }}>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <div><strong>{s.name}</strong> — {s.location}</div>
            <div>{s.notes}</div>
            <small>{new Date(s.createdAt).toLocaleString()}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
