```js
import { pool } from "../db.js";

export async function createRoom(req, res) {
  const { name, memberIds = [] } = req.body;

  const roomResult = await pool.query(
    "INSERT INTO rooms (name, created_by) VALUES ($1, $2) RETURNING id, name",
    [name, req.user.id]
  );

  const room = roomResult.rows[0];

  for (const memberId of memberIds) {
    await pool.query(
      "INSERT INTO room_members (room_id, user_id) VALUES ($1, $2)",
      [room.id, memberId]
    );
  }

  await pool.query(
    "INSERT INTO room_members (room_id, user_id) VALUES ($1, $2)",
    [room.id, req.user.id]
  );

  res.json(room);
}

export async function getMessages(req, res) {
  const { roomId } = req.params;

  const result = await pool.query(
    `SELECT m.id, m.room_id, m.sender_id, u.username as sender_name, m.content, m.created_at
     FROM messages m
     JOIN users u ON u.id = m.sender_id
     WHERE m.room_id = $1
     ORDER BY m.created_at ASC`,
    [roomId]
  );

  res.json(result.rows);
}

export async function sendMessage(req, res) {
  const { roomId } = req.params;
  const { content } = req.body;

  if (!content?.trim()) {
    return res.status(400).json({ error: "Empty message" });
  }

  const result = await pool.query(
    `INSERT INTO messages (room_id, sender_id, content)
     VALUES ($1, $2, $3)
     RETURNING id, room_id, sender_id, content, created_at`,
    [roomId, req.user.id, content]
  );

  const message = result.rows[0];
  const io = req.app.get("io");

  io.to(`room:${roomId}`).emit("newMessage", {
    ...message,
    sender_name: req.user.username
  });

  // send notification to room members
  const members = await pool.query(
    "SELECT user_id FROM room_members WHERE room_id = $1 AND user_id != $2",
    [roomId, req.user.id]
  );

  for (const member of members.rows) {
    io.to(`user:${member.user_id}`).emit("notification", {
      type: "new_message",
      roomId,
      text: `${req.user.username} sent a message`
    });
  }

  res.json(message);
}
```

