import React, { useEffect, useState } from "react";
import { apiFetch } from "../api";

export default function Chat({ socket, token }) {
  const [roomId, setRoomId] = useState(1);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!socket) return;

    socket.emit("joinRoom", roomId);

    socket.on("newMessage", (msg) => {
      if (String(msg.roomId) === String(roomId)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.off("newMessage");
    };
  }, [socket, roomId]);

  useEffect(() => {
    apiFetch(`/chat/rooms/${roomId}/messages`, token)
      .then(setMessages)
      .catch(console.error);
  }, [roomId, token]);

  async function send() {
    if (!content.trim()) return;

    await apiFetch(`/chat/rooms/${roomId}/messages`, token, {
      method: "POST",
      body: JSON.stringify({ content })
    });

    setContent("");
  }

  return (
    <div>
      <h2>Chat Room #{roomId}</h2>
      <div style={{ border: "1px solid #ccc", height: 300, overflowY: "auto", padding: 10 }}>
        {messages.map((m) => (
          <div key={m.id || `${m.created_at}-${m.content}`}>
            <strong>{m.sender_name || m.from || "User"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message..."
      />
      <button onClick={send}>Send</button>
    </div>
  );
}
