## `server/src/routes/messages.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";
import { auth } from "../middleware/auth.js";

export default function createMessagesRouter(io) {
  const router = express.Router();

  router.get("/conversation/:userId", auth, async (req, res) => {
    try {
      const otherUserId = req.params.userId;
      const messages = await Message.find({
        $or: [
          { sender: req.user._id, recipient: otherUserId },
          { sender: otherUserId, recipient: req.user._id }
        ]
      }).sort({ createdAt: 1 });

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  router.post("/", auth, async (req, res) => {
    try {
      const { recipientId, content } = req.body;

      const message = await Message.create({
        sender: req.user._id,
        recipient: recipientId,
        content
      });

      const recipient = await User.findById(recipientId);
      if (recipient) {
        const notif = await Notification.create({
          user: recipient._id,
          type: "message",
          title: "New message",
          body: `${req.user.username} sent you a message`,
          metadata: { messageId: message._id, senderId: req.user._id }
        });

        io.to(String(recipient._id)).emit("message:new", message);
        io.to(String(recipient._id)).emit("notification:new", notif);
      }

      res.json(message);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
}
```

