import express from "express";
import { stripe } from "../config/stripe.js";
import { auth } from "../middleware/auth.js";
import Purchase from "../models/Purchase.js";
import User from "../models/User.js";

export default function createPaymentsRouter(io) {
  const router = express.Router();

  router.post("/create-checkout-session", auth, async (req, res) => {
    try {
      const { credits = 100 } = req.body;

      const session = await stripe.checkout.sessions.create({
        mode: "payment",
        payment_method_types: ["card"],
        line_items: [
          {
            price_data: {
              currency: "usd",
              product_data: { name: `${credits} App Credits` },
              unit_amount: credits * 10
            },
            quantity: 1
          }
        ],
        success_url: process.env.STRIPE_SUCCESS_URL,
        cancel_url: process.env.STRIPE_CANCEL_URL,
        metadata: {
          userId: String(req.user._id),
          credits: String(credits)
        }
      });

      await Purchase.create({
        user: req.user._id,
        stripeSessionId: session.id,
        amount: credits * 10,
        currency: "usd",
        status: "pending"
      });

      res.json({ url: session.url });
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  // Demo endpoint to simulate payment confirmation
  router.post("/confirm", auth, async (req, res) => {
    try {
      const { credits = 100 } = req.body;

      const user = await User.findByIdAndUpdate(
        req.user._id,
        { $inc: { tokens: credits }, isPremium: true },
        { new: true }
      );

      io.to(String(user._id)).emit("purchase:complete", {
        tokens: user.tokens,
        isPremium: user.isPremium
      });

      res.json({ message: "Purchase confirmed", tokens: user.tokens, isPremium: user.isPremium });
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
}
