import { useEffect, useState } from "react";
import { http } from "../api/http";

export default function Notifications({ socket }) {
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    http.get("/notifications").then(({ data }) => setNotifications(data));
  }, []);

  useEffect(() => {
    if (!socket) return;

    const onNew = (notif) => setNotifications((prev) => [notif, ...prev]);
    socket.on("notification:new", onNew);

    return () => socket.off("notification:new", onNew);
  }, [socket]);

  async function markRead(id) {
    await http.patch(`/notifications/${id}/read`);
    setNotifications((prev) => prev.map((n) => (n._id === id ? { ...n, read: true } : n)));
  }

  return (
    <div>
      <h3>Notifications</h3>
      {notifications.map((n) => (
        <div key={n._id} style={{ opacity: n.read ? 0.6 : 1 }}>
          <strong>{n.title}</strong>
          <p>{n.body}</p>
          {!n.read && <button onClick={() => markRead(n._id)}>Mark read</button>}
        </div>
      ))}
    </div>
  );
}
