import { useEffect, useState } from "react";
import { http } from "../api/http";
import { useAuth } from "../context/AuthContext";

export default function ChatBox({ socket, recipientId }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const { user } = useAuth();

  useEffect(() => {
    if (!recipientId) return;
    http.get(`/messages/conversation/${recipientId}`).then(({ data }) => setMessages(data));
  }, [recipientId]);

  useEffect(() => {
    if (!socket) return;
    const onNew = (msg) => {
      const senderId = typeof msg.sender === "object" ? msg.sender._id : msg.sender;
      const recipient = typeof msg.recipient === "object" ? msg.recipient._id : msg.recipient;

      if (
        (senderId === recipientId && recipient === user.id) ||
        (senderId === user.id && recipient === recipientId)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("message:new", onNew);
    return () => socket.off("message:new", onNew);
  }, [socket, recipientId, user]);

  async function send() {
    if (!content.trim()) return;
    const { data } = await http.post("/messages", { recipientId, content });
    setMessages((prev) => [...prev, data]);
    setContent("");
  }

  return (
    <div>
      <h3>Chat</h3>
      <div style={{ border: "1px solid #ccc", minHeight: 200, padding: 8 }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{String(m.sender) === user.id ? "You" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>
      <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type message..." />
      <button onClick={send}>Send</button>
    </div>
  );
}
