import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import bcrypt from "bcryptjs";
import { PrismaClient } from "@prisma/client";
import { authMiddleware, signToken } from "./auth.js";
import { initSocket } from "./socket.js";
import { stripe, createCheckoutSession } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const prisma = new PrismaClient();
const io = initSocket(server, prisma);

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

// Auth
app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;
  const passwordHash = await bcrypt.hash(password, 10);

  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  });

  await prisma.subscription.create({
    data: { userId: user.id, tier: "free", active: true }
  });

  const token = signToken(user);
  res.json({ token, user });
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({ token, user });
});

// Conversations
app.post("/api/conversations", authMiddleware, async (req, res) => {
  const { memberIds } = req.body; // include current user id too
  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: memberIds.map((userId) => ({ userId }))
      }
    },
    include: { members: true }
  });
  res.json(conversation);
});

app.get("/api/conversations", authMiddleware, async (req, res) => {
  const conversations = await prisma.conversation.findMany({
    where: {
      members: { some: { userId: req.user.id } }
    },
    include: {
      members: { include: { user: true } },
      messages: {
        orderBy: { createdAt: "desc" },
        take: 20
      }
    }
  });
  res.json(conversations);
});

app.get("/api/messages/:conversationId", authMiddleware, async (req, res) => {
  const messages = await prisma.message.findMany({
    where: { conversationId: req.params.conversationId },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

// Notifications
app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

// Monetization
app.post("/api/billing/checkout", authMiddleware, async (req, res) => {
  const { tier } = req.body;
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });

  const session = await createCheckoutSession({
    userId: user.id,
    email: user.email,
    tier
  });

  res.json({ url: session.url });
});

// Stripe webhook
app.post(
  "/api/billing/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;
      const tier = session.metadata.tier;

      await prisma.subscription.upsert({
        where: { userId },
        update: {
          tier,
          active: true,
          stripeCustomerId: session.customer,
          stripeSubscriptionId: session.subscription
        },
        create: {
          userId,
          tier,
          active: true,
          stripeCustomerId: session.customer,
          stripeSubscriptionId: session.subscription
        }
      });
    }

    res.json({ received: true });
  }
);

server.listen(process.env.PORT, () => {
  console.log(`Server running on port ${process.env.PORT}`);
});
