### `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";
import Chat from "./components/Chat";
import Notifications from "./components/Notifications";
import Monetize from "./components/Monetize";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);
  const [conversations, setConversations] = useState([]);
  const [activeConversationId, setActiveConversationId] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    const s = createSocket(token);
    setSocket(s);

    s.on("newMessage", (message) => {
      if (message.conversationId === activeConversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    s.on("newNotification", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    return () => s.disconnect();
  }, [token, activeConversationId]);

  useEffect(() => {
    if (!token) return;
    (async () => {
      const convos = await api("/api/conversations", "GET", null, token);
      const notifs = await api("/api/notifications", "GET", null, token);
      setConversations(convos);
      setNotifications(notifs);
      if (convos[0]) setActiveConversationId(convos[0].id);
    })();
  }, [token]);

  useEffect(() => {
    if (!token || !activeConversationId) return;
    (async () => {
      const msgs = await api(`/api/messages/${activeConversationId}`, "GET", null, token);
      setMessages(msgs);
    })();
  }, [token, activeConversationId]);

  async function loginDemo() {
    const res = await api("/api/login", "POST", {
      email: "demo@example.com",
      password: "password123"
    });
    localStorage.setItem("token", res.token);
    setToken(res.token);
    setUser(res.user);
  }

  async function registerDemo() {
    const res = await api("/api/register", "POST", {
      email: "demo@example.com",
      password: "password123",
      name: "Demo User"
    });
    localStorage.setItem("token", res.token);
    setToken(res.token);
    setUser(res.user);
  }

  async function sendMessage(content) {
    socket.emit("sendMessage", { conversationId: activeConversationId, content });
  }

  async function markRead(id) {
    socket.emit("markNotificationRead", id);
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
  }

  async function upgrade(tier) {
    const res = await api("/api/billing/checkout", "POST", { tier }, token);
    window.location.href = res.url;
  }

  if (!token) {
    return (
      <div>
        <h1>Social Messaging App</h1>
        <button onClick={registerDemo}>Register Demo</button>
        <button onClick={loginDemo}>Login Demo</button>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gap: 20 }}>
      <h1>Welcome {user?.name || "User"}</h1>

      <div>
        <h3>Conversations</h3>
        {conversations.map((c) => (
          <button key={c.id} onClick={() => setActiveConversationId(c.id)}>
            {c.id}
          </button>
        ))}
      </div>

      <Chat
        socket={socket}
        conversationId={activeConversationId}
        messages={messages}
        onSend={sendMessage}
      />

      <Notifications notifications={notifications} onMarkRead={markRead} />

      <Monetize onUpgrade={upgrade} />
    </div>
  );
}
