## 5) Socket.IO real-time layer

### `server/src/sockets/index.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import dotenv from "dotenv";
dotenv.config();

export function initSocket(server) {
  const io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      methods: ["GET", "POST"],
    },
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    console.log("User connected:", socket.user.id);

    socket.join(`user:${socket.user.id}`);

    socket.on("send_message", async ({ toUserId, text }) => {
      // In production, save to DB first
      const message = {
        id: Date.now().toString(),
        fromUserId: socket.user.id,
        toUserId,
        text,
        createdAt: new Date().toISOString(),
      };

      io.to(`user:${toUserId}`).emit("new_message", message);
      io.to(`user:${toUserId}`).emit("new_notification", {
        type: "message",
        title: "New message",
        body: `You received a message from ${socket.user.username}`,
      });
    });

    socket.on("disconnect", () => {
      console.log("User disconnected:", socket.user.id);
    });
  });

  return io;
}
```

