import React, { useEffect, useState } from "react";
import { apiFetch } from "../api";

export default function ChatWindow({ socket, token }) {
  const [messages, setMessages] = useState([]);
  const [toUserId, setToUserId] = useState("");
  const [text, setText] = useState("");

  useEffect(() => {
    if (!socket) return;

    socket.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => socket.off("new_message");
  }, [socket]);

  async function send() {
    if (!socket || !toUserId || !text) return;
    socket.emit("send_message", { toUserId: Number(toUserId), text });

    const saved = await apiFetch("/api/chat/messages", token, {
      method: "POST",
      body: JSON.stringify({ toUserId: Number(toUserId), text }),
    });

    setMessages((prev) => [...prev, saved]);
    setText("");
  }

  return (
    <div>
      <h2>Chat</h2>
      <input
        placeholder="To user ID"
        value={toUserId}
        onChange={(e) => setToUserId(e.target.value)}
      />
      <br />
      <textarea
        placeholder="Message..."
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      <br />
      <button onClick={send}>Send</button>

      <div style={{ marginTop: 20 }}>
        {messages.map((m) => (
          <div key={m.id} style={{ padding: 8, borderBottom: "1px solid #ddd" }}>
            <b>{m.fromUserId || m.from_user_id}</b>: {m.text}
          </div>
        ))}
      </div>
    </div>
  );
}
