import { useEffect, useState } from "react";
import { api } from "../api";
import { createSocket } from "../socket";

export function Chat({ conversationId }: { conversationId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const [socket, setSocket] = useState<any>(null);

  useEffect(() => {
    api.get(`/chat/conversation/${conversationId}/messages`).then((res) => {
      setMessages(res.data);
    });

    const s = createSocket();
    setSocket(s);
    s.emit("joinConversation", conversationId);

    s.on("newMessage", (message: any) => {
      if (message.conversationId === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => s.disconnect();
  }, [conversationId]);

  const sendMessage = async () => {
    const res = await api.post(`/chat/conversation/${conversationId}/messages`, { content });
    setMessages((prev) => [...prev, res.data]);
    socket?.emit("sendMessage", {
      conversationId,
      content,
      senderId: res.data.senderId
    });
    setContent("");
  };

  return (
    <div>
      <h2>Chat</h2>
      <div style={{ border: "1px solid #ccc", padding: 12, minHeight: 200 }}>
        {messages.map((m) => (
          <div key={m.id || `${m.createdAt}-${m.content}`}>
            <b>{m.senderId || "Me"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message..."
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
