# 5) Socket.IO for real-time messaging + notifications

## `server/src/sockets/index.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { pool } from "../config/db.js";

let io;

export function initSocket(server) {
  io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    console.log("Connected:", socket.user.id);

    socket.join(`user:${socket.user.id}`);

    socket.on("message:send", async ({ receiverId, content, isPaid = false, coinCost = 0 }) => {
      const result = await pool.query(
        `INSERT INTO messages (sender_id, receiver_id, content, is_paid, coin_cost)
         VALUES ($1, $2, $3, $4, $5)
         RETURNING *`,
        [socket.user.id, receiverId, content, isPaid, coinCost]
      );

      const message = result.rows[0];

      io.to(`user:${receiverId}`).emit("message:new", message);

      io.to(`user:${receiverId}`).emit("notification:new", {
        type: "message",
        title: "New message",
        body: `You received a new message`
      });
    });

    socket.on("disconnect", () => {
      console.log("Disconnected:", socket.user.id);
    });
  });

  return io;
}

export function getIO() {
  if (!io) throw new Error("Socket.IO not initialized");
  return io;
}
```

