router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  const { productType } = req.body;

  let lineItems = [];
  let amountCents = 0;

  if (productType === "coins_100") {
    lineItems = [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "100 Coins" },
          unit_amount: 499
        },
        quantity: 1
      }
