    amountCents = 499;
  } else if (productType === "premium_monthly") {
    lineItems = [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Monthly" },
          unit_amount: 999
        },
        quantity: 1
      }
    ];
    amountCents = 999;
  } else {
    return res.status(400).json({ error: "Invalid product type" });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: lineItems,
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: {
      userId: req.user.id,
      productType
    }
  });

  await pool.query(
    `INSERT INTO purchases (user_id, stripe_session_id, product_type, amount_cents, status)
     VALUES ($1, $2, $3, $4, 'pending')`,
    [req.user.id, session.id, productType, amountCents]
  );

  res.json({ url: session.url });
});

