      body: JSON.stringify({ productType: "coins_100" })
    });

    if (data.url) window.location.href = data.url;
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>Social Messaging App</h1>

      {!token ? (
        <Login onLogin={(t) => setToken(t)} />
      ) : (
        <>
          <button onClick={loadInbox}>Load Inbox</button>
          <button onClick={buyCoins}>Buy 100 Coins</button>

          <div style={{ marginTop: 20 }}>
            <h2>Send Message</h2>
            <input
              placeholder="Receiver ID"
              value={receiverId}
              onChange={(e) => setReceiverId(e.target.value)}
            />
            <br />
            <textarea
              placeholder="Message"
              value={content}
              onChange={(e) => setContent(e.target.value)}
            />
            <br />
            <button onClick={sendMessage}>Send</button>
          </div>

          <div style={{ marginTop: 20 }}>
            <h2>Notifications</h2>
            {notifications.map((n) => (
              <div key={n.id || Math.random()}>
                <strong>{n.title}</strong> - {n.body}
              </div>
            ))}
          </div>

          <div style={{ marginTop: 20 }}>
            <h2>Messages</h2>
            {messages.map((m) => (
              <div key={m.id}>
                <b>{m.sender_id}</b> → <b>{m.receiver_id}</b>: {m.content}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function Login({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  async function login() {
    const res = await fetch("http://localhost:4000/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password })
    });
    const data = await res.json();
    if (data.token) {
      localStorage.setItem("token", data.token);
      onLogin(data.token);
    } else {
      alert(data.error || "Login failed");
    }
  }

  return (
    <div>
      <h2>Login</h2>
      <input placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <br />
      <input
        placeholder="Password"
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />
      <br />
      <button onClick={login}>Login</button>
    </div>
  );
}
