# 15) Example: add coin deduction for paid messages

If you want paid messages, update your send logic like this:

```js
socket.on("message:send", async ({ receiverId, content, isPaid = false, coinCost = 0 }) => {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    if (isPaid && coinCost > 0) {
      const userResult = await client.query(`SELECT coins FROM users WHERE id = $1`, [socket.user.id]);
      const coins = userResult.rows[0].coins;

      if (coins < coinCost) {
        await client.query("ROLLBACK");
        socket.emit("error", { message: "Insufficient coins" });
        return;
      }

      await client.query(`UPDATE users SET coins = coins - $1 WHERE id = $2`, [
        coinCost,
        socket.user.id
      ]);
    }

    const result = await client.query(
      `INSERT INTO messages (sender_id, receiver_id, content, is_paid, coin_cost)
       VALUES ($1, $2, $3, $4, $5)
       RETURNING *`,
      [socket.user.id, receiverId, content, isPaid, coinCost]
    );

    await client.query("COMMIT");

    const message = result.rows[0];
    io.to(`user:${receiverId}`).emit("message:new", message);
  } catch (e) {
    await client.query("ROLLBACK");
    socket.emit("error", { message: "Failed to send message" });
  } finally {
    client.release();
  }
});
```

