import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

export async function createCheckoutSession(req, res) {
  const { pack } = req.body;

  const packs = {
    small: { amount: 500, credits: 100 },
    medium: { amount: 1200, credits: 300 },
    large: { amount: 2500, credits: 700 }
  };

  const selected = packs[pack];
  if (!selected) {
    return res.status(400).json({ error: "Invalid pack" });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: `${pack} credit pack`
          },
          unit_amount: selected.amount
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: req.user.sub,
      credits: String(selected.credits)
    },
    success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`
  });

  return res.json({ url: session.url });
}

export async function handleStripeWebhook(req, res) {
  // For production: verify signature with stripe.webhooks.constructEvent
  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const credits = parseInt(session.metadata.credits, 10);

    await prisma.user.update({
      where: { id: userId },
      data: { balance: { increment: credits } }
    });
  }

  res.json({ received: true });
}
