import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import bcrypt from "bcryptjs";
import { PrismaClient } from "@prisma/client";
import { authMiddleware, signToken } from "./auth.js";
import { setupSocket } from "./socket.js";
import { createCheckoutSession, handleStripeWebhook } from "./stripe.js";

dotenv.config();

const prisma = new PrismaClient();
const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

setupSocket(io);

app.post("/api/register", async (req, res) => {
  const { email, username, password } = req.body;
  const passwordHash = await bcrypt.hash(password, 10);

  try {
    const user = await prisma.user.create({
      data: { email, username, passwordHash }
    });

    const token = signToken(user);
    res.json({ token, user: { id: user.id, email, username, balance: user.balance } });
  } catch (e) {
    res.status(400).json({ error: "User already exists or invalid data" });
  }
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });

  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({
    token,
    user: { id: user.id, email: user.email, username: user.username, balance: user.balance }
  });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.sub } });
  res.json({
    id: user.id,
    email: user.email,
    username: user.username,
    balance: user.balance
  });
});

app.get("/api/messages/:otherUserId", authMiddleware, async (req, res) => {
  const me = req.user.sub;
  const other = req.params.otherUserId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.sub },
    orderBy: { createdAt: "desc" }
  });

  res.json(notifications);
});

app.post("/api/notifications/:id/read", authMiddleware, async (req, res) => {
  const notification = await prisma.notification.update({
    where: { id: req.params.id },
    data: { read: true }
  });
  res.json(notification);
});

app.post("/api/checkout", authMiddleware, createCheckoutSession);

app.post("/api/stripe/webhook", express.raw({ type: "application/json" }), handleStripeWebhook);

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
