## `client/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";
import { socket } from "../socket";

export default function Chat({ user }) {
  const [otherUserId, setOtherUserId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!user) return;

    const onMessage = (msg) => setMessages((prev) => [...prev, msg]);
    const onNotification = (n) => setNotifications((prev) => [n, ...prev]);

    socket.on("new_message", onMessage);
    socket.on("new_notification", onNotification);

    return () => {
      socket.off("new_message", onMessage);
      socket.off("new_notification", onNotification);
    };
  }, [user]);

  const loadMessages = async () => {
    const res = await api.get(`/messages/${otherUserId}`);
    setMessages(res.data);
  };

  const send = () => {
    socket.emit("send_message", {
      senderId: user.id,
      receiverId: otherUserId,
      content
    });
    setContent("");
  };

  const loadNotifications = async () => {
    const res = await api.get("/notifications");
    setNotifications(res.data);
  };

  if (!user) return <div>Please log in.</div>;

  return (
    <div>
      <h2>Chat</h2>

      <div>
        <input
          placeholder="Other user ID"
          value={otherUserId}
          onChange={(e) => setOtherUserId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Chat</button>
      </div>

      <div style={{ marginTop: 10 }}>
        <input
          placeholder="Message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button onClick={send}>Send</button>
      </div>

      <h3>Messages</h3>
      <ul>
        {messages.map((m) => (
          <li key={m.id}>
            <b>{m.senderId === user.id ? "Me" : "Them"}:</b> {m.content}
          </li>
        ))}
      </ul>

      <h3>Notifications</h3>
      <button onClick={loadNotifications}>Refresh Notifications</button>
      <ul>
        {notifications.map((n) => (
          <li key={n.id} style={{ opacity: n.read ? 0.5 : 1 }}>
            {n.title} - {n.body}
          </li>
        ))}
      </ul>
    </div>
  );
}
