import { stripe } from "../config/stripe.js";
import User from "../models/User.js";
import Subscription from "../models/Subscription.js";

export const createCheckoutSession = async (req, res) => {
  try {
    const userId = req.user._id;

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      payment_method_types: ["card"],
      line_items: [
        {
          price: process.env.STRIPE_PRICE_ID,
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/pricing?success=1`,
      cancel_url: `${process.env.CLIENT_URL}/pricing?canceled=1`,
      metadata: { userId: String(userId) }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

export const stripeWebhook = async (req, res) => {
  let event = req.body;

  // In production, verify signature using raw body:
  // const sig = req.headers["stripe-signature"];
  // event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);

  try {
    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await User.findByIdAndUpdate(userId, { premium: true });
      await Subscription.findOneAndUpdate(
        { user: userId },
        {
          user: userId,
          stripeCustomerId: session.customer || "",
          stripeSubscriptionId: session.subscription || "",
          status: "active",
          plan: "premium"
        },
        { upsert: true, new: true }
      );
    }

    res.json({ received: true });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

export const buyCoins = async (req, res) => {
  try {
    const { coins } = req.body;
    const amount = coins * 100; // example pricing: $1 per coin

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${coins} Coins` },
            unit_amount: amount
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/chat?coins=success`,
      cancel_url: `${process.env.CLIENT_URL}/chat?coins=canceled`,
      metadata: { userId: String(req.user._id), coins: String(coins) }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};
