## `client/src/components/ChatWindow.jsx`

```jsx
import { useEffect, useState } from "react";
import api from "../api/axios";
import { socket } from "../socket";

export default function ChatWindow({ userId, otherUserId }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    const loadMessages = async () => {
      const res = await api.get(`/chat/${otherUserId}`);
      setMessages(res.data);
    };

    loadMessages();

    socket.connect();
    socket.emit("join", userId);

    socket.on("new_message", (msg) => {
      if (
        (msg.sender === otherUserId && msg.receiver === userId) ||
        (msg.sender === userId && msg.receiver === otherUserId)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.off("new_message");
    };
  }, [userId, otherUserId]);

  const send = async () => {
    socket.emit("send_message", {
      senderId: userId,
      receiverId: otherUserId,
      content
    });
    setContent("");
  };

  return (
    <div>
      <div style={{ height: 300, overflow: "auto", border: "1px solid #ccc" }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{String(m.sender) === String(userId) ? "You" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

