## `server/src/routes/chat.routes.ts`

```ts
import { Router } from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth, AuthRequest } from "../middleware";
import { notifyConversation, notifyUser } from "../services/notification.service";

const prisma = new PrismaClient();
const router = Router();

router.post("/conversation", requireAuth, async (req: AuthRequest, res) => {
  const { memberIds } = req.body; // array of user IDs including current user
  const currentUserId = req.user!.id;

  const ids = Array.from(new Set([currentUserId, ...(memberIds || [])]));

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: ids.map((userId) => ({ userId }))
      }
    },
    include: { members: true }
  });

  res.json(conversation);
});

router.get("/conversations", requireAuth, async (req: AuthRequest, res) => {
  const userId = req.user!.id;

  const conversations = await prisma.conversation.findMany({
    where: { members: { some: { userId } } },
    include: {
      members: { include: { user: { select: { id: true, name: true, email: true } } } },
      messages: { orderBy: { createdAt: "desc" }, take: 1 }
    }
  });

  res.json(conversations);
});

router.get("/messages/:conversationId", requireAuth, async (req: AuthRequest, res) => {
  const { conversationId } = req.params;

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

router.post("/messages", requireAuth, async (req: AuthRequest, res) => {
  const { conversationId, content } = req.body;
  const senderId = req.user!.id;

  const message = await prisma.message.create({
    data: { conversationId, senderId, content }
  });

  const members = await prisma.conversationMember.findMany({
    where: { conversationId },
    select: { userId: true }
  });

  notifyConversation(conversationId, message);

  for (const m of members) {
    if (m.userId !== senderId) {
      notifyUser(m.userId, {
        type: "message",
        title: "New message",
        body: content.slice(0, 80),
        conversationId
      });
    }
  }

  res.json(message);
});

export default router;
```

