```ts
import { Router } from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth, AuthRequest } from "../middleware";
import { createCheckoutSession, handleStripeWebhook } from "../services/billing.service";

const prisma = new PrismaClient();
const router = Router();

router.get("/me", requireAuth, async (req: AuthRequest, res) => {
  const sub = await prisma.subscription.findUnique({
    where: { userId: req.user!.id }
  });
  res.json(sub);
});

router.post("/checkout", requireAuth, async (req: AuthRequest, res) => {
  const session = await createCheckoutSession(req.user!.id, req.user!.email);
  res.json({ url: session.url });
});

router.post("/webhook", async (req, res) => {
  const sig = req.headers["stripe-signature"] as string;
  const rawBody = (req as any).rawBody as Buffer;

  try {
    const event = await handleStripeWebhook(rawBody, sig);

    if (event.type === "checkout.session.completed") {
      const session = event.data.object as any;
      const userId = session.metadata?.userId;

      if (userId) {
        await prisma.subscription.upsert({
          where: { userId },
          update: {
            status: "active",
            plan: "premium",
            stripeCustomerId: session.customer as string
          },
          create: {
            userId,
            status: "active",
            plan: "premium",
            stripeCustomerId: session.customer as string
          }
        });
      }
    }

    res.json({ received: true });
  } catch (err: any) {
    res.status(400).send(`Webhook Error: ${err.message}`);
  }
});

export default router;
