import { PrismaClient } from "@prisma/client";
import { authMiddleware, signToken } from "./auth.js";
import { stripe } from "./stripe.js";
import { setupSocket } from "./socket.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const prisma = new PrismaClient();
const io = setupSocket(server, prisma);

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

// --- Auth ---
app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) return res.status(400).json({ error: "Email already exists" });

  const passwordHash = await bcrypt.hash(password, 10);

  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  });

  const token = signToken(user);
  res.json({ token, user });
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({ token, user });
});

// --- Current user ---
app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.sub },
    select: { id: true, email: true, name: true, balance: true, createdAt: true }
  });
  res.json({ user });
});

// --- Users list ---
app.get("/api/users", authMiddleware, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.sub } },
    select: { id: true, name: true, email: true }
  });
  res.json({ users });
});

// --- Messages ---
app.get("/api/messages/:userId", authMiddleware, async (req, res) => {
  const me = req.user.sub;
  const other = req.params.userId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json({ messages });
});

// --- Notifications ---
app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.sub },
    orderBy: { createdAt: "desc" }
  });
  res.json({ notifications });
});

app.post("/api/notifications/:id/read", authMiddleware, async (req, res) => {
  const notification = await prisma.notification.update({
    where: { id: req.params.id },
    data: { read: true }
  });
  res.json({ notification });
});

// --- Monetization: buy credits ---
app.post("/api/buy-credits", authMiddleware, async (req, res) => {
  const { credits } = req.body;

  const priceMap = {
    100: 199,
    500: 799,
    1000: 1299
  };

  if (!priceMap[credits]) {
    return res.status(400).json({ error: "Invalid credit package" });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${credits} app credits` },
          unit_amount: priceMap[credits]
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: req.user.sub,
      credits: String(credits)
    }
  });

  await prisma.payment.create({
    data: {
      userId: req.user.sub,
      stripeSessionId: session.id,
      amount: priceMap[credits],
      currency: "usd",
      status: "pending"
    }
  });

  res.json({ url: session.url });
});

// --- Stripe webhook ---
app.post(
  "/api/stripe-webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;
      const credits = Number(session.metadata.credits);

      await prisma.$transaction([
        prisma.user.update({
          where: { id: userId },
          data: { balance: { increment: credits } }
        }),
        prisma.payment.update({
          where: { stripeSessionId: session.id },
          data: { status: "paid" }
        })
      ]);

      io.to(userId).emit("credits_updated", { credits });
      io.to(userId).emit("new_notification", {
        id: `payment-${session.id}`,
        type: "payment",
        title: "Purchase successful",
        body: `You received ${credits} credits.`,
        read: false
      });
    }

    res.json({ received: true });
  }
);

app.get("/", (_, res) => res.send("API running"));

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
```

