import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";
import Login from "./pages/Login";
import Chat from "./pages/Chat";
import Wallet from "./pages/Wallet";

export default function App() {
  const [user, setUser] = useState(null);
  const [view, setView] = useState("chat");
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    api.get("/me").then((res) => setUser(res.data.user)).catch(() => {
      localStorage.removeItem("token");
    });
  }, []);

  useEffect(() => {
    if (!user) return;

    const s = createSocket();
    setSocket(s);

    s.on("new_notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    s.on("credits_updated", () => {
      api.get("/me").then((res) => setUser(res.data.user));
    });

    api.get("/notifications").then((res) => setNotifications(res.data.notifications));

    return () => s.disconnect();
  }, [user]);

  if (!localStorage.getItem("token")) {
    return <Login onLogin={setUser} />;
  }

  if (!user) return <div>Loading...</div>;

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h2>Social Messaging App</h2>
      <div>
        <strong>{user.name}</strong> | Balance: {user.balance} credits
      </div>

      <div style={{ marginTop: 10 }}>
        <button onClick={() => setView("chat")}>Chat</button>
        <button onClick={() => setView("wallet")}>Wallet</button>
      </div>

      <h3>Notifications</h3>
      <ul>
        {notifications.map((n) => (
          <li key={n.id} style={{ opacity: n.read ? 0.5 : 1 }}>
            <strong>{n.title}</strong>: {n.body}
          </li>
        ))}
      </ul>

      {view === "chat" ? (
        <Chat socket={socket} currentUser={user} />
      ) : (
        <Wallet />
      )}
    </div>
  );
}
