## `client/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ socket, currentUser }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api.get("/users").then((res) => setUsers(res.data.users));
  }, []);

  useEffect(() => {
    if (!selectedUser) return;

    api.get(`/messages/${selectedUser.id}`).then((res) => setMessages(res.data.messages));
  }, [selectedUser]);

  useEffect(() => {
    if (!socket) return;

    socket.on("new_message", (msg) => {
      if (
        selectedUser &&
        ((msg.senderId === selectedUser.id && msg.receiverId === currentUser.id) ||
          (msg.senderId === currentUser.id && msg.receiverId === selectedUser.id))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => socket.off("new_message");
  }, [socket, selectedUser, currentUser]);

  const send = () => {
    if (!selectedUser || !content.trim()) return;
    socket.emit("send_message", {
      receiverId: selectedUser.id,
      content
    });
    setContent("");
  };

  return (
    <div style={{ display: "flex", gap: 20, marginTop: 20 }}>
      <div>
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => setSelectedUser(u)}>{u.name}</button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h4>Chat {selectedUser ? `with ${selectedUser.name}` : ""}</h4>
        <div style={{ border: "1px solid #ccc", minHeight: 200, padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === currentUser.id ? "Me" : selectedUser?.name}:</b>{" "}
              {m.content}
            </div>
          ))}
        </div>

        <input
          style={{ width: "80%" }}
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message"
        />
        <button onClick={send}>Send</button>
      </div>
    </div>
  );
}
