import { useEffect, useState } from "react";
import api from "../services/api";
import { io } from "socket.io-client";

const socket = io(import.meta.env.VITE_SOCKET_URL, {
  autoConnect: false,
  auth: { token: localStorage.getItem("token") }
});

export default function Chat({ otherUserId }) {
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    const load = async () => {
      const res = await api.get(`/messages/${otherUserId}`);
      setMessages(res.data);
    };

    socket.auth = { token: localStorage.getItem("token") };
    socket.connect();
    socket.on("new_message", (message) => {
      if (message.senderId === otherUserId || message.receiverId === otherUserId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    load();

    return () => {
      socket.off("new_message");
      socket.disconnect();
    };
  }, [otherUserId]);

  const send = async () => {
    if (!text.trim()) return;
    const res = await api.post("/messages", { receiverId: otherUserId, text });
    setMessages((prev) => [...prev, res.data]);
    setText("");
  };

  return (
    <div>
      <div style={{ border: "1px solid #ccc", padding: 12, height: 300, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{String(m.senderId) === String(otherUserId) ? "Them" : "You"}:</b> {m.text}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 12 }}>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Type a message" />
        <button onClick={send}>Send</button>
      </div>
    </div>
  );
}
