# 2) Database schema (Prisma)

**`backend/prisma/schema.prisma`**
```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum Role {
  USER
  PREMIUM
  ADMIN
}

model User {
  id            String    @id @default(cuid())
  email         String    @unique
  passwordHash  String
  name          String
  role          Role      @default(USER)
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  messages      Message[]
  sentNotifs    Notification[] @relation("SentNotifications")
  receivedNotifs Notification[] @relation("ReceivedNotifications")
  subscriptions Subscription?
}

model Conversation {
  id          String     @id @default(cuid())
  createdAt   DateTime   @default(now())
  updatedAt   DateTime   @updatedAt

  participants ConversationParticipant[]
  messages     Message[]
}

model ConversationParticipant {
  id              String        @id @default(cuid())
  conversationId  String
  userId          String
  conversation    Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([conversationId, userId])
}

model Message {
  id             String        @id @default(cuid())
  conversationId String
  senderId       String
  content        String
  createdAt      DateTime      @default(now())
  readAt         DateTime?

  conversation   Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         User          @relation(fields: [senderId], references: [id], onDelete: Cascade)
}

model Notification {
  id          String   @id @default(cuid())
  type        String
  title       String
  body        String
  senderId    String?
  receiverId  String
  createdAt   DateTime @default(now())
  readAt      DateTime?

  sender      User?    @relation("SentNotifications", fields: [senderId], references: [id])
  receiver    User     @relation("ReceivedNotifications", fields: [receiverId], references: [id], onDelete: Cascade)
}

model Subscription {
  id                  String   @id @default(cuid())
  userId              String   @unique
  stripeCustomerId    String?
  stripeSubscriptionId String?
  status              String   @default("inactive")
  currentPeriodEnd    DateTime?

  user                User     @relation(fields: [userId], references: [id], onDelete: Cascade)
}
```

