# 5) Monetization with Stripe

This example supports:
- buying coins
- subscribing to premium plans

## `server/src/routes/monetization.routes.ts`

```ts
import { Router } from "express";
import Stripe from "stripe";
import { prisma } from "../prisma";
import { requireAuth, AuthRequest } from "../auth";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "", {
  apiVersion: "2024-06-20"
});

router.post("/create-checkout-session", requireAuth, async (req: AuthRequest, res) => {
  const { type } = req.body as { type: "coins" | "premium" };

  const session = await stripe.checkout.sessions.create({
    mode: type === "premium" ? "subscription" : "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: type === "premium" ? "Premium Subscription" : "100 Coins"
          },
          unit_amount: type === "premium" ? 999 : 499
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/success`,
    cancel_url: `${process.env.CLIENT_URL}/cancel`,
    metadata: {
      userId: req.userId!,
      type
    }
  });

  res.json({ url: session.url });
});

router.post("/webhook", expressRawBody(), async (req, res) => {
  // In production: verify Stripe signature here
  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const type = session.metadata.type;

    if (type === "coins") {
      await prisma.wallet.upsert({
        where: { userId },
        update: { balance: { increment: 100 } },
        create: { userId, balance: 100 }
      });
    }

    if (type === "premium") {
      await prisma.subscription.create({
        data: {
          userId,
          plan: "premium",
          active: true
        }
      });
    }
  }

  res.json({ received: true });
});

function expressRawBody() {
  const express = require("express");
  return express.raw({ type: "application/json" });
}

export default router;
```

> Note: Stripe webhooks should be signature-verified in production.

