## `server/src/socket.ts`

```ts
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

export function setupSocket(io: Server) {
  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("joinConversation", (conversationId: string) => {
      socket.join(conversationId);
    });

    socket.on("sendMessage", async (data) => {
      const { conversationId, senderId, content, isPaid = false, price = 0 } = data;

      const message = await prisma.message.create({
        data: { conversationId, senderId, content, isPaid, price }
      });

      io.to(conversationId).emit("newMessage", message);

      const participants = await prisma.participant.findMany({
        where: { conversationId },
        include: { user: true }
      });

      for (const p of participants) {
        if (p.userId !== senderId) {
          await prisma.notification.create({
            data: {
              userId: p.userId,
              title: "New message",
              body: `You received a new message in conversation ${conversationId}`
            }
          });

          io.to(p.userId).emit("newNotification", {
            title: "New message",
            body: `You received a new message`
          });
        }
      }
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}
