    const session = await createCheckoutSession(userId);
    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

router.post("/buy-coins", async (req, res) => {
  try {
    const { userId, amount } = req.body;

    await prisma.user.update({
      where: { id: userId },
      data: { balance: { increment: amount } }
    });

    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: "Failed to buy coins" });
  }
});

router.post("/send-paid-message", async (req, res) => {
  try {
    const { senderId, conversationId, content, price } = req.body;

    const sender = await prisma.user.findUnique({ where: { id: senderId } });
    if (!sender || sender.balance < price) {
      return res.status(400).json({ error: "Insufficient balance" });
    }

    await prisma.user.update({
      where: { id: senderId },
      data: { balance: { decrement: price } }
    });

    const message = await prisma.message.create({
      data: {
        senderId,
        conversationId,
        content,
        isPaid: true,
        price
      }
    });

    res.json(message);
  } catch (err) {
    res.status(500).json({ error: "Failed to send paid message" });
  }
});

