```js
import React, { useEffect, useState } from "react";
import { View, TextInput, Button, FlatList, Text } from "react-native";
import axios from "axios";
import { socket } from "./socket";

export default function ChatScreen({ route }) {
  const { currentUserId, receiverId, token } = route.params;
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    socket.emit("join", currentUserId);

    axios
      .get(`http://YOUR_SERVER_IP:5000/api/chat/messages/${receiverId}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => setMessages(res.data));

    socket.on("message:new", (message) => {
      if (
        (message.senderId === receiverId && message.receiverId === currentUserId) ||
        (message.senderId === currentUserId && message.receiverId === receiverId)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off("message:new");
    };
  }, []);

  const sendMessage = () => {
    socket.emit("send:message", {
      senderId: currentUserId,
      receiverId,
      content: text,
    });
    setText("");
  };

  return (
    <View style={{ padding: 20 }}>
      <FlatList
        data={messages}
        keyExtractor={(item) => item._id}
        renderItem={({ item }) => <Text>{item.content}</Text>}
      />
      <TextInput
        value={text}
        onChangeText={setText}
        placeholder="Type a message"
        style={{ borderWidth: 1, marginVertical: 10, padding: 8 }}
      />
      <Button title="Send" onPress={sendMessage} />
    </View>
  );
}
```

