# 6) Messaging routes + real-time notifications

## `backend/src/messages.js`

```js
import express from "express";
import { PrismaClient } from "@prisma/client";
import { authMiddleware } from "./middleware.js";

const router = express.Router();
const prisma = new PrismaClient();

export default function messagesRoutes(io) {
  router.post("/conversation", authMiddleware, async (req, res) => {
    const { participantIds } = req.body; // array of user IDs
    const userId = req.user.id;

    try {
      const conversation = await prisma.conversation.create({
        data: {
          participants: {
            create: [
              { userId },
              ...participantIds.map((id) => ({ userId: id }))
            ]
          }
        },
        include: { participants: true }
      });

      res.json(conversation);
    } catch {
      res.status(500).json({ error: "Could not create conversation" });
    }
  });

  router.get("/conversation/:id/messages", authMiddleware, async (req, res) => {
    const { id } = req.params;

    const messages = await prisma.message.findMany({
      where: { conversationId: id },
      orderBy: { createdAt: "asc" }
    });

    res.json(messages);
  });

  router.post("/send", authMiddleware, async (req, res) => {
    const { conversationId, content } = req.body;
    const senderId = req.user.id;

    try {
      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId,
          content
        }
      });

      // Create notifications for all participants except sender
      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId }
      });

      const recipientIds = participants
        .map((p) => p.userId)
        .filter((id) => id !== senderId);

      await prisma.notification.createMany({
        data: recipientIds.map((userId) => ({
          userId,
          type: "message",
          content: `New message in conversation ${conversationId}`
        }))
      });

      // Real-time emit
      io.to(conversationId).emit("newMessage", message);
      io.to(conversationId).emit("newNotification", {
        type: "message",
        content: `New message received`
      });

      res.json(message);
    } catch {
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  return router;
}
```

