# 9) Monetization with Stripe

This example supports:
- **One-time coin packs**
- **Subscription plans**

## `backend/src/routes/billing.js`

```js
import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";
import { requireAuth } from "../auth.js";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

export const billingRouter = express.Router();

billingRouter.post("/checkout/coins", requireAuth, async (req, res) => {
  try {
    const { packId } = req.body;

    const packs = {
      small: { amount: 499, coins: 500 },
      medium: { amount: 999, coins: 1200 },
      large: { amount: 1999, coins: 3000 }
    };

    const pack = packs[packId];
    if (!pack) return res.status(400).json({ error: "Invalid pack" });

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${pack.coins} Coins` },
            unit_amount: pack.amount
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/success`,
      cancel_url: `${process.env.CLIENT_URL}/cancel`,
      metadata: {
        userId: req.user.userId,
        packId
      }
    });

    res.json({ url: session.url });
  } catch {
    res.status(500).json({ error: "Checkout failed" });
  }
});

billingRouter.post("/subscribe", requireAuth, async (req, res) => {
  try {
    const { plan } = req.body;

    const plans = {
      premium: { amount: 999, name: "Premium Monthly" }
    };

    const selected = plans[plan];
    if (!selected) return res.status(400).json({ error: "Invalid plan" });

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: selected.name },
            recurring: { interval: "month" },
            unit_amount: selected.amount
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/success`,
      cancel_url: `${process.env.CLIENT_URL}/cancel`,
      metadata: {
        userId: req.user.userId,
        plan
      }
    });

    res.json({ url: session.url });
  } catch {
    res.status(500).json({ error: "Subscription checkout failed" });
  }
});
```

> In production, you should use **Stripe webhooks** to confirm payment before crediting coins or activating subscriptions.

