## `mobile/App.js`

```js
import React, { useEffect, useState } from "react";
import { View, Text, TextInput, Button, FlatList } from "react-native";
import { io } from "socket.io-client";
import { apiFetch } from "./src/api";

const BASE_URL = "http://localhost:4000";

export default function App() {
  const [token, setToken] = useState(null);
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);

  const [email, setEmail] = useState("test@example.com");
  const [password, setPassword] = useState("password");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  const conversationId = "YOUR_CONVERSATION_ID";

  useEffect(() => {
    if (!token) return;

    const s = io(BASE_URL, {
      auth: { token }
    });

    s.on("connect", () => {
      s.emit("joinConversation", conversationId);
    });

    s.on("newMessage", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    s.on("newNotification", (notification) => {
      console.log("Notification:", notification);
    });

    setSocket(s);
    return () => s.disconnect();
  }, [token]);

  async function login() {
    const data = await apiFetch("/auth/login", null, {
      method: "POST",
      body: JSON.stringify({ email, password })
    });
    setToken(data.token);
    setUser(data.user);
  }

  async function sendMessage() {
    if (!socket || !content.trim()) return;
    socket.emit("sendMessage", { conversationId, content });
    setContent("");
  }

  if (!token) {
    return (
      <View style={{ padding: 24, marginTop: 60 }}>
        <Text>Login</Text>
        <TextInput value={email} onChangeText={setEmail} placeholder="Email" />
        <TextInput value={password} onChangeText={setPassword} placeholder="Password" secureTextEntry />
        <Button title="Login" onPress={login} />
      </View>
    );
  }

  return (
    <View style={{ padding: 24, marginTop: 60, flex: 1 }}>
      <Text>Welcome {user?.username}</Text>

      <FlatList
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <Text style={{ marginVertical: 4 }}>
            {item.sender?.username || item.senderId}: {item.content}
          </Text>
        )}
      />

      <TextInput
        value={content}
        onChangeText={setContent}
        placeholder="Write a message..."
        style={{ borderWidth: 1, padding: 10, marginVertical: 10 }}
      />
      <Button title="Send" onPress={sendMessage} />
    </View>
  );
}
```

