## `server/src/routes/messages.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";
import Transaction from "../models/Transaction.js";
import { authMiddleware } from "../middleware/authMiddleware.js";

export default function messagesRouter(io) {
  const router = express.Router();

  router.get("/:userId", authMiddleware, async (req, res) => {
    const me = req.user.userId;
    const other = req.params.userId;

    const messages = await Message.find({
      $or: [
        { senderId: me, recipientId: other },
        { senderId: other, recipientId: me }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  });

  router.post("/", authMiddleware, async (req, res) => {
    const { recipientId, content, isPremium = false } = req.body;
    const senderId = req.user.userId;

    const sender = await User.findById(senderId);
    const recipient = await User.findById(recipientId);

    if (!recipient) return res.status(404).json({ error: "Recipient not found" });

    // Monetization rule: premium messages cost 1 credit
    if (isPremium) {
      if (sender.credits < 1) {
        return res.status(402).json({ error: "Not enough credits" });
      }

      sender.credits -= 1;
      await sender.save();

      await Transaction.create({
        userId: senderId,
        type: "spend",
        amount: 1,
        description: "Premium message sent"
      });
    }

    const message = await Message.create({
      senderId,
      recipientId,
      content,
      isPremium
    });

    const notification = await Notification.create({
      userId: recipientId,
      type: "message",
      title: "New message",
      body: `${sender.displayName || sender.username} sent you a message`
    });

    io.to(String(recipientId)).emit("notification", notification);
    io.to(String(recipientId)).emit("message", message);

    res.json(message);
  });

  return router;
}
