import express from "express";
import User from "../models/User.js";
import Transaction from "../models/Transaction.js";
import Notification from "../models/Notification.js";
import { authMiddleware } from "../middleware/authMiddleware.js";

export default function monetizationRouter(io) {
  const router = express.Router();

  // Simulated purchase endpoint
  router.post("/buy-credits", authMiddleware, async (req, res) => {
    const { credits = 10 } = req.body;
    const userId = req.user.userId;

    const user = await User.findById(userId);
    user.credits += credits;
    await user.save();

    await Transaction.create({
      userId,
      type: "purchase",
      amount: credits,
      description: `Purchased ${credits} credits`
    });

    const notification = await Notification.create({
      userId,
      type: "credit_purchase",
      title: "Credits added",
      body: `You received ${credits} credits`
    });

    io.to(String(userId)).emit("notification", notification);

    res.json({ credits: user.credits });
  });

  router.post("/unlock-premium", authMiddleware, async (req, res) => {
    const userId = req.user.userId;

    const user = await User.findById(userId);
    if (user.credits < 5) {
      return res.status(402).json({ error: "Need 5 credits to unlock premium" });
    }

    user.credits -= 5;
    user.isPremium = true;
    await user.save();

    await Transaction.create({
      userId,
      type: "spend",
      amount: 5,
      description: "Unlocked premium"
    });

    const notification = await Notification.create({
      userId,
      type: "premium_unlock",
      title: "Premium unlocked",
      body: "You are now a premium user"
    });

    io.to(String(userId)).emit("notification", notification);

    res.json({ isPremium: true, credits: user.credits });
  });

  router.get("/wallet", authMiddleware, async (req, res) => {
    const user = await User.findById(req.user.userId);
    const transactions = await Transaction.find({ userId: req.user.userId }).sort({
      createdAt: -1
    });

    res.json({
      credits: user.credits,
      isPremium: user.isPremium,
      transactions
    });
  });

  return router;
}
