import React, { useEffect, useState } from "react";
import { apiFetch } from "../api";
import { createSocket } from "../socket";

export default function Chat({ token }) {
  const [socket, setSocket] = useState(null);
  const [recipientId, setRecipientId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [isPremium, setIsPremium] = useState(false);

  useEffect(() => {
    const s = createSocket(token);
    setSocket(s);

    s.on("message", (msg) => setMessages(prev => [...prev, msg]));
    s.on("notification", (n) => setNotifications(prev => [n, ...prev]));

    return () => s.disconnect();
  }, [token]);

  async function loadMessages() {
    if (!recipientId) return;
    const data = await apiFetch(`/messages/${recipientId}`, "GET", null, token);
    setMessages(data);
  }

  async function sendMessage() {
    await apiFetch("/messages", "POST", {
      recipientId,
      content,
      isPremium
    }, token);
    setContent("");
  }

  return (
    <div>
      <h2>Chat</h2>

      <div>
        <input
          placeholder="Recipient user ID"
          value={recipientId}
          onChange={e => setRecipientId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Conversation</button>
      </div>

      <div>
        <label>
          <input
            type="checkbox"
            checked={isPremium}
            onChange={e => setIsPremium(e.target.checked)}
          />
          Premium message (costs 1 credit)
        </label>
      </div>

      <textarea
        placeholder="Write a message"
        value={content}
        onChange={e => setContent(e.target.value)}
      />
      <br />
      <button onClick={sendMessage}>Send</button>

      <h3>Messages</h3>
      <ul>
        {messages.map(m => (
          <li key={m._id}>
            {m.isPremium ? "⭐ " : ""}
            {m.content}
          </li>
        ))}
      </ul>

      <h3>Notifications</h3>
      <ul>
        {notifications.map(n => (
          <li key={n._id}>
            <strong>{n.title}:</strong> {n.body}
          </li>
        ))}
      </ul>
    </div>
  );
}
