```jsx
import { useEffect, useState } from "react";
import api from "../api/axios";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

export default function Chat({ currentUser, selectedUser }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!currentUser) return;
    socket.emit("register", currentUser.id);
  }, [currentUser]);

  useEffect(() => {
    if (!selectedUser) return;

    api.get(`/messages/${selectedUser.id}`).then((res) => setMessages(res.data));

    socket.on("new_message", (message) => {
      const isRelevant =
        (message.sender === currentUser.id && message.receiver === selectedUser.id) ||
        (message.sender === selectedUser.id && message.receiver === currentUser.id);

      if (isRelevant) setMessages((prev) => [...prev, message]);
    });

    return () => socket.off("new_message");
  }, [selectedUser, currentUser]);

  const sendMessage = () => {
    if (!content.trim()) return;

    socket.emit("send_message", {
      senderId: currentUser.id,
      receiverId: selectedUser.id,
      content
    });

    setContent("");
  };

  return (
    <div>
      <h3>Chat with {selectedUser?.username}</h3>
      <div style={{ border: "1px solid #ccc", padding: 10, height: 300, overflowY: "auto" }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{m.sender === currentUser.id ? "You" : selectedUser.username}:</b> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
```

