## 3) Database schema (Prisma)

This is a good initial schema for users, conversations, messages, notifications, and purchases.

### `server/prisma/schema.prisma`
```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum NotificationType {
  MESSAGE
  FOLLOW
  PURCHASE
  SYSTEM
}

enum PurchaseType {
  SUBSCRIPTION
  ONE_TIME
}

enum MessageStatus {
  SENT
  DELIVERED
  READ
}

model User {
  id              String          @id @default(cuid())
  email           String          @unique
  username        String          @unique
  passwordHash    String
  displayName     String?
  avatarUrl       String?
  bio             String?
  createdAt       DateTime        @default(now())
  updatedAt       DateTime        @updatedAt

  conversations   ConversationMember[]
  messages        Message[]
  notifications   Notification[]
  purchases       Purchase[]
  sentFollows     Follow[]        @relation("sentFollows")
  receivedFollows Follow[]        @relation("receivedFollows")

  blockedUsers    Block[]         @relation("blocker")
  blockedBy       Block[]         @relation("blocked")
}

model Conversation {
  id            String              @id @default(cuid())
  createdAt     DateTime            @default(now())
  updatedAt     DateTime            @updatedAt
  members       ConversationMember[]
  messages      Message[]
}

model ConversationMember {
  id             String        @id @default(cuid())
  conversationId String
  userId         String
  lastReadAt     DateTime?

  conversation   Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([conversationId, userId])
}

model Message {
  id             String         @id @default(cuid())
  conversationId String
  senderId       String
  content        String
  status         MessageStatus   @default(SENT)
  createdAt      DateTime        @default(now())
  updatedAt      DateTime        @updatedAt

  conversation   Conversation   @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         User           @relation(fields: [senderId], references: [id], onDelete: Cascade)
}

model Notification {
  id          String            @id @default(cuid())
  userId      String
  type        NotificationType
  title       String
  body        String
  readAt      DateTime?
  metadata    Json?
  createdAt   DateTime          @default(now())

  user        User              @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model Follow {
  id          String   @id @default(cuid())
  senderId    String
  receiverId  String
  createdAt   DateTime @default(now())

  sender      User     @relation("sentFollows", fields: [senderId], references: [id], onDelete: Cascade)
  receiver    User     @relation("receivedFollows", fields: [receiverId], references: [id], onDelete: Cascade)

  @@unique([senderId, receiverId])
}

model Block {
  id          String   @id @default(cuid())
  blockerId   String
  blockedId   String
  createdAt   DateTime @default(now())

  blocker     User     @relation("blocker", fields: [blockerId], references: [id], onDelete: Cascade)
  blocked     User     @relation("blocked", fields: [blockedId], references: [id], onDelete: Cascade)

  @@unique([blockerId, blockedId])
}

model Purchase {
  id              String        @id @default(cuid())
  userId          String
  type            PurchaseType
  stripeSessionId String?       @unique
  stripePaymentId String?       @unique
  amountCents     Int
  currency        String
  productId       String
  status          String
  createdAt      DateTime      @default(now())

  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)
}
