import { Request, Response } from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";
import { AuthRequest } from "../middleware/auth";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: "2024-06-20",
});

export const createCheckoutSession = async (req: AuthRequest, res: Response) => {
  const { productId, type } = req.body;

  const session = await stripe.checkout.sessions.create({
    mode: type === "SUBSCRIPTION" ? "subscription" : "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price: productId, // Stripe Price ID
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: {
      userId: req.userId!,
      productId,
      type,
    },
  });

  return res.json({ url: session.url });
};

export const stripeWebhook = async (req: Request, res: Response) => {
  // In production, verify signature with raw body parser
  // This is a simplified initial implementation

  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const productId = session.metadata.productId;
    const type = session.metadata.type;

    await prisma.purchase.create({
      data: {
        userId,
        type,
        stripeSessionId: session.id,
        amountCents: session.amount_total,
        currency: session.currency,
        productId,
        status: "COMPLETED",
      },
    });

    await prisma.notification.create({
      data: {
        userId,
        type: "PURCHASE",
        title: "Purchase successful",
        body: "Your premium purchase was completed successfully.",
        metadata: { productId, type },
      },
    });
  }

  return res.status(200).json({ received: true });
};
