# 6) Real-Time Messaging + Notifications with Socket.IO

## `sockets/index.ts`

```ts
import { Server } from "socket.io";
import http from "http";
import jwt from "jsonwebtoken";

let io: Server;

export const initSocket = (server: http.Server) => {
  io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true,
    },
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET!) as any;
      socket.data.user = { id: decoded.id, email: decoded.email };
      next();
    } catch {
      next(new Error("Invalid token"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.data.user.id;
    socket.join(`user:${userId}`);

    socket.on("message:send", async (payload) => {
      // payload: { conversationId, content, recipientIds }
      // Save message to DB in service layer
      // Then emit to conversation members
      io.to(`user:${payload.recipientId}`).emit("message:new", {
        conversationId: payload.conversationId,
        content: payload.content,
        senderId: userId,
      });

      io.to(`user:${payload.recipientId}`).emit("notification:new", {
        type: "MESSAGE",
        title: "New message",
        body: payload.content.slice(0, 80),
      });
    });

    socket.on("typing:start", ({ conversationId, recipientIds }) => {
      recipientIds.forEach((id: string) => {
        io.to(`user:${id}`).emit("typing:update", {
          conversationId,
          userId,
          isTyping: true,
        });
      });
    });

    socket.on("typing:stop", ({ conversationId, recipientIds }) => {
      recipientIds.forEach((id: string) => {
        io.to(`user:${id}`).emit("typing:update", {
          conversationId,
          userId,
          isTyping: false,
        });
      });
    });

    socket.on("disconnect", () => {
      // presence updates can be handled here
    });
  });

  return io;
};

export const getIO = () => {
  if (!io) throw new Error("Socket.IO not initialized");
  return io;
};
```

