## 8) Real-Time Messaging with Socket.IO

### `sockets/index.ts`
```ts
import { Server } from "socket.io";
import { Server as HttpServer } from "http";

let io: Server;

export function initSocket(server: HttpServer) {
  io = new Server(server, {
    cors: {
      origin: true,
      credentials: true,
    },
  });

  io.use((socket, next) => {
    // TODO: verify JWT from socket.handshake.auth.token
    next();
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("join_conversation", (conversationId: string) => {
      socket.join(conversationId);
    });

    socket.on("send_message", async (payload) => {
      // payload: { conversationId, senderId, content, contentType }
      // TODO: persist message in DB
      io.to(payload.conversationId).emit("new_message", payload);

      // TODO: create notification for other participants
    });

    socket.on("typing", (payload) => {
      socket.to(payload.conversationId).emit("typing", {
        userId: payload.userId,
        conversationId: payload.conversationId,
      });
    });

    socket.on("mark_read", (payload) => {
      socket.to(payload.conversationId).emit("message_read", payload);
      // TODO: update lastReadMessageId in DB
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}

export function getIO() {
  if (!io) throw new Error("Socket not initialized");
  return io;
}
```

