## 6) Real-time socket implementation

### `src/realtime/socket.ts`
```ts
import { Server } from "socket.io";
import http from "http";

let io: Server;

export function initSocket(server: http.Server) {
  io = new Server(server, {
    cors: {
      origin: "*",
      methods: ["GET", "POST"]
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("join", (userId: string) => {
      socket.join(`user:${userId}`);
    });

    socket.on("message:send", async (payload) => {
      // payload: { conversationId, senderId, content }
      // 1) persist message
      // 2) emit to conversation participants
      io.to(`conversation:${payload.conversationId}`).emit("message:new", payload);
    });

    socket.on("notification:read", ({ userId, notificationId }) => {
      io.to(`user:${userId}`).emit("notification:read", { notificationId });
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });

  return io;
}

export function getIO() {
  if (!io) throw new Error("Socket.io not initialized");
  return io;
}
```

