### Chat component example
```tsx
import { useEffect, useState } from "react";
import { socket } from "../services/socket";

export function Chat({ userId, conversationId }: { userId: string; conversationId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    socket.emit("join", userId);

    socket.on("message:new", (message) => {
      if (message.conversationId === conversationId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off("message:new");
    };
  }, [userId, conversationId]);

  const send = async () => {
    await fetch(`http://localhost:4000/api/chats/${conversationId}/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ senderId: userId, content })
    });
    setContent("");
  };

  return (
    <div>
      <div>
        {messages.map(m => (
          <div key={m.id}><b>{m.senderId}:</b> {m.content}</div>
        ))}
      </div>

      <input value={content} onChange={e => setContent(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

