const stripe = require('../config/stripe');
const pool = require('../config/db');
const { v4: uuidv4 } = require('uuid');

async function createCheckoutSession({ userId, product }) {
  const session = await stripe.checkout.sessions.create({
    mode: product.product_type === 'subscription' ? 'subscription' : 'payment',
    line_items: [{ price: product.stripe_price_id, quantity: 1 }],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: {
      userId,
      productId: product.id
    }
  });

  await pool.query(
    `INSERT INTO purchases (id, user_id, product_id, stripe_session_id, status)
     VALUES ($1, $2, $3, $4, $5)`,
    [uuidv4(), userId, product.id, session.id, 'pending']
  );

  return session;
}

module.exports = { createCheckoutSession };
```

