import { getIO } from "../socket";
import { prisma } from "../prismaClient";

export async function createNotification(userId: string, payload: {
  type: string;
  title: string;
  body: string;
  data?: any;
}) {
  const notification = await prisma.notification.create({
    data: {
      userId,
      type: payload.type,
      title: payload.title,
      body: payload.body,
      data: payload.data,
    },
  });

  getIO().to(`user:${userId}`).emit("notification:new", notification);
  return notification;
}
