## C) Example Purchase Endpoint
```ts
import { Router } from "express";
import { prisma } from "../prismaClient";

const router = Router();

router.post("/topup", async (req, res) => {
  const { userId, amountCents } = req.body;

  const wallet = await prisma.wallet.upsert({
    where: { userId },
    update: { balanceCents: { increment: amountCents } },
    create: { userId, balanceCents: amountCents, currency: "USD" },
  });

  await prisma.transaction.create({
    data: {
      userId,
      type: "purchase",
      amountCents,
      currency: "USD",
      provider: "stripe",
      status: "completed",
    },
  });

  res.json(wallet);
});

export default router;
```

