### `src/controllers/chat.controller.js`
```js
const prisma = require("../prisma");
const { getIO } = require("../socket");

async function createConversation(req, res) {
  const userId = req.user.id;
  const { memberIds } = req.body; // array of user IDs

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [
          { userId },
          ...memberIds.map((id) => ({ userId: id })),
        ],
      },
    },
    include: { members: true },
  });

  res.json(conversation);
}

async function getMessages(req, res) {
  const conversationId = req.params.id;

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    include: { sender: true },
  });

  res.json(messages);
}

async function sendMessage(req, res) {
  const conversationId = req.params.id;
  const senderId = req.user.id;
  const { content } = req.body;

  const message = await prisma.message.create({
    data: {
      conversationId,
      senderId,
      content,
    },
    include: { sender: true },
  });

  const conversation = await prisma.conversation.findUnique({
    where: { id: conversationId },
    include: { members: true },
  });

  const io = getIO();

  // Emit message to all conversation members
  conversation.members.forEach((member) => {
    io.to(`user:${member.userId}`).emit("message:new", message);
    io.to(`user:${member.userId}`).emit("notification:new", {
      type: "MESSAGE",
      title: "New message",
      body: `${message.sender.username}: ${message.content.slice(0, 50)}`,
    });
  });

  res.json(message);
}

module.exports = { createConversation, getMessages, sendMessage };
```

