import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";

// Replace with Prisma/DB calls
const users = [];

export async function register(req, res) {
  const { email, password, username, displayName } = req.body;

  if (!email || !password || !username) {
    return res.status(400).json({ error: "Missing fields" });
  }

  const existing = users.find(u => u.email === email || u.username === username);
  if (existing) return res.status(409).json({ error: "User already exists" });

  const passwordHash = await bcrypt.hash(password, 10);
  const user = {
    id: String(users.length + 1),
    email,
    username,
    displayName: displayName || username,
    passwordHash
  };

  users.push(user);

  const token = jwt.sign(
    { id: user.id, email: user.email, username: user.username },
    process.env.JWT_SECRET,
    { expiresIn: "7d" }
  );

  res.status(201).json({ token, user: { id: user.id, email, username, displayName: user.displayName } });
}

export async function login(req, res) {
  const { email, password } = req.body;

  const user = users.find(u => u.email === email);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = jwt.sign(
    { id: user.id, email: user.email, username: user.username },
    process.env.JWT_SECRET,
    { expiresIn: "7d" }
  );

  res.json({ token, user: { id: user.id, email: user.email, username: user.username, displayName: user.displayName } });
}
