import React, { useEffect, useState } from "react";
import { View, TextInput, Button, FlatList, Text } from "react-native";
import socket, { connectUser, sendMessage, onNewMessage } from "./socket";

export default function ChatScreen({ userId, recipientId, conversationId }) {
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    connectUser(userId);

    onNewMessage((msg) => {
      if (msg.conversationId === conversationId) {
        setMessages((prev) => [...prev, msg]);
      }
    });
  }, []);

  const handleSend = () => {
    if (!text.trim()) return;
    sendMessage({
      conversationId,
      senderId: userId,
      recipientId,
      content: text
    });
    setText("");
  };

  return (
    <View style={{ padding: 16 }}>
      <FlatList
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text>{item.senderId}: {item.content}</Text>}
      />
      <TextInput value={text} onChangeText={setText} placeholder="Type a message" />
      <Button title="Send" onPress={handleSend} />
    </View>
  );
}
