  const result = await pool.query(
    `INSERT INTO users (id, email, password_hash, username, display_name)
     VALUES ($1, $2, $3, $4, $5)
     RETURNING id, email, username, display_name, avatar_url, bio, created_at`,
    [id, email, passwordHash, username, displayName]
  );

  await pool.query("INSERT INTO wallets (user_id, balance_cents) VALUES ($1, 0)", [id]);

  return result.rows[0];
}

export async function loginUser({ email, password }) {
  const result = await pool.query(`SELECT * FROM users WHERE email = $1`, [email]);
  const user = result.rows[0];
  if (!user) throw new Error("Invalid credentials");

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) throw new Error("Invalid credentials");

  const token = jwt.sign(
    { id: user.id, email: user.email, username: user.username },
    process.env.JWT_SECRET,
    { expiresIn: "7d" }
  );

  return {
    token,
    user: {
      id: user.id,
      email: user.email,
      username: user.username,
      display_name: user.display_name,
      avatar_url: user.avatar_url,
      bio: user.bio
    }
  };
}
