### `src/sockets/index.js`
```js
import jwt from "jsonwebtoken";
import { sendMessage } from "../services/messaging.service.js";
import { createNotification } from "../services/notification.service.js";

export function initSocket(io) {
  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("Unauthorized"));
      socket.user = jwt.verify(token, process.env.JWT_SECRET);
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    socket.join(`user:${socket.user.id}`);

    socket.on("message:send", async (payload, ack) => {
      try {
        const result = await sendMessage({
          conversationId: payload.conversationId,
          senderId: socket.user.id,
          content: payload.content,
          messageType: payload.messageType
        });

        for (const memberId of result.members) {
          io.to(`user:${memberId}`).emit("message:new", result.message);
          if (memberId !== socket.user.id) {
            await createNotification({
              userId: memberId,
              type: "new_message",
              title: "New message",
              body: payload.content.slice(0, 80),
              data: { conversationId: payload.conversationId, messageId: result.message.id }
            });
            io.to(`user:${memberId}`).emit("notification:new", {
              type: "new_message",
              title: "New message",
              body: payload.content.slice(0, 80)
            });
          }
        }

        ack?.({ ok: true, message: result.message });
      } catch (err) {
        ack?.({ ok: false, error: err.message });
      }
    });
  });
}
```

