```ts
import { Request, Response } from "express";
import { pool } from "../config/db";
import { hashPassword, verifyPassword } from "../utils/password";
import { signToken } from "../utils/jwt";
import { randomUUID } from "crypto";

export async function register(req: Request, res: Response) {
  const { email, username, password, displayName } = req.body;

  if (!email || !username || !password) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existing = await pool.query(
    "SELECT id FROM users WHERE email = $1 OR username = $2",
    [email, username]
  );
  if (existing.rowCount) {
    return res.status(409).json({ error: "User already exists" });
  }

  const id = randomUUID();
  const passwordHash = await hashPassword(password);

  await pool.query(
    `INSERT INTO users (id, email, username, password_hash, display_name)
     VALUES ($1, $2, $3, $4, $5)`,
    [id, email, username, passwordHash, displayName || null]
  );

  await pool.query(`INSERT INTO wallets (user_id, balance_cents) VALUES ($1, 0)`, [id]);

  const token = signToken({ id, email, username });
  return res.status(201).json({ token, user: { id, email, username, displayName } });
}

export async function login(req: Request, res: Response) {
  const { email, password } = req.body;

  const result = await pool.query(
    "SELECT id, email, username, password_hash, display_name FROM users WHERE email = $1",
    [email]
  );
  if (!result.rowCount) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const user = result.rows[0];
  const ok = await verifyPassword(password, user.password_hash);
  if (!ok) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = signToken({ id: user.id, email: user.email, username: user.username });
  return res.json({
    token,
    user: {
      id: user.id,
      email: user.email,
      username: user.username,
      displayName: user.display_name,
    },
  });
}

export async function me(req: any, res: Response) {
  const result = await pool.query(
    "SELECT id, email, username, display_name, avatar_url FROM users WHERE id = $1",
    [req.user.id]
  );
  return res.json({ user: result.rows[0] });
}
```

