### `src/controllers/conversationController.ts`
```ts
import { Response } from "express";
import { pool } from "../config/db";
import { randomUUID } from "crypto";
import { AuthRequest } from "../middleware/auth";
import { emitNotification, emitMessage } from "../config/socket";

export async function createConversation(req: AuthRequest, res: Response) {
  const { participantId } = req.body;
  if (!participantId) return res.status(400).json({ error: "participantId required" });

  const conversationId = randomUUID();

  await pool.query("BEGIN");
  try {
    await pool.query("INSERT INTO conversations (id) VALUES ($1)", [conversationId]);
    await pool.query(
      "INSERT INTO conversation_members (conversation_id, user_id) VALUES ($1, $2), ($1, $3)",
      [conversationId, req.user!.id, participantId]
    );
    await pool.query("COMMIT");
    res.status(201).json({ conversationId });
  } catch (e) {
    await pool.query("ROLLBACK");
    res.status(500).json({ error: "Failed to create conversation" });
  }
}

export async function listConversations(req: AuthRequest, res: Response) {
  const result = await pool.query(
    `SELECT c.id, c.created_at
     FROM conversations c
     JOIN conversation_members cm ON cm.conversation_id = c.id
     WHERE cm.user_id = $1
     ORDER BY c.updated_at DESC`,
    [req.user!.id]
  );
  res.json({ conversations: result.rows });
}

export async function getMessages(req: AuthRequest, res: Response) {
  const { id } = req.params;
  const result = await pool.query(
    `SELECT id, conversation_id, sender_id, content, created_at, read_at, is_paid, paid_amount_cents
     FROM messages
     WHERE conversation_id = $1
     ORDER BY created_at ASC`,
    [id]
  );
  res.json({ messages: result.rows });
}

export async function sendMessage(req: AuthRequest, res: Response) {
  const { id } = req.params;
  const { content } = req.body;
  if (!content) return res.status(400).json({ error: "content required" });

  const messageId = randomUUID();

  const result = await pool.query(
    `INSERT INTO messages (id, conversation_id, sender_id, content)
     VALUES ($1, $2, $3, $4)
     RETURNING *`,
    [messageId, id, req.user!.id, content]
  );

  await pool.query(`UPDATE conversations SET updated_at = NOW() WHERE id = $1`, [id]);

  const members = await pool.query(
    `SELECT user_id FROM conversation_members WHERE conversation_id = $1 AND user_id <> $2`,
    [id, req.user!.id]
  );

  for (const member of members.rows) {
    await pool.query(
      `INSERT INTO notifications (id, user_id, type, title, body, data)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [
        randomUUID(),
        member.user_id,
        "new_message",
        "New message",
        content.slice(0, 120),
        JSON.stringify({ conversationId: id, messageId }),
      ]
    );
    emitNotification(member.user_id, {
      type: "new_message",
      title: "New message",
      body: content.slice(0, 120),
      data: { conversationId: id, messageId },
    });
  }

  emitMessage(id, result.rows[0]);
  res.status(201).json({ message: result.rows[0] });
}

export async function markConversationRead(req: AuthRequest, res: Response) {
  const { id } = req.params;
  await pool.query(
    `UPDATE messages
     SET read_at = NOW()
     WHERE conversation_id = $1 AND sender_id <> $2 AND read_at IS NULL`,
    [id, req.user!.id]
  );
  res.json({ success: true });
}
