### `src/controllers/billingController.ts`
```ts
import { Request, Response } from "express";
import Stripe from "stripe";
import { env } from "../config/env";
import { pool } from "../config/db";
import { randomUUID } from "crypto";
import { AuthRequest } from "../middleware/auth";

const stripe = new Stripe(env.stripeSecretKey, { apiVersion: "2024-06-20" as any });

export async function createCheckoutSession(req: AuthRequest, res: Response) {
  const { mode, priceId, amountCents } = req.body;

  const session = await stripe.checkout.sessions.create({
    mode: mode || "payment",
    payment_method_types: ["card"],
    line_items: priceId
      ? [{ price: priceId, quantity: 1 }]
      : [{
          price_data: {
            currency: "usd",
            product_data: { name: "Wallet Top-Up" },
            unit_amount: amountCents || 500,
          },
          quantity: 1,
        }],
    success_url: "https://yourapp.com/success",
    cancel_url: "https://yourapp.com/cancel",
    metadata: {
      userId: req.user!.id,
    },
  });

  res.json({ url: session.url });
}

export async function stripeWebhook(req: Request, res: Response) {
  // In production, verify signature using raw body and webhook secret.
  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata?.userId;
    const amount = session.amount_total || 0;

    if (userId) {
      await pool.query(
        `INSERT INTO transactions (id, user_id, type, provider, provider_ref, amount_cents, currency, status)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
        [randomUUID(), userId, "purchase", "stripe", session.id, amount, session.currency || "usd", "succeeded"]
      );

      await pool.query(
        `UPDATE wallets SET balance_cents = balance_cents + $1, updated_at = NOW() WHERE user_id = $2`,
        [amount, userId]
      );
    }
  }

  res.json({ received: true });
}

export async function getSubscription(req: AuthRequest, res: Response) {
  const result = await pool.query(
    `SELECT id, plan, status, current_period_end
     FROM subscriptions
     WHERE user_id = $1
     ORDER BY created_at DESC
     LIMIT 1`,
    [req.user!.id]
  );
  res.json({ subscription: result.rows[0] || null });
}

export async function topUpWallet(req: AuthRequest, res: Response) {
  const { amountCents } = req.body;
  if (!amountCents || amountCents < 100) {
    return res.status(400).json({ error: "Invalid amount" });
  }

  const txId = randomUUID();
  await pool.query(
    `INSERT INTO transactions (id, user_id, type, provider, amount_cents, currency, status)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [txId, req.user!.id, "purchase", "internal", amountCents, "usd", "pending"]
  );

  res.json({ transactionId: txId, status: "pending" });
}
```

