# 5) Socket service for real-time messaging + notifications

## `backend/src/services/socket.service.ts`

```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { env } from "../config/env";

export function initSocket(server: any) {
  const io = new Server(server, {
    cors: {
      origin: env.CLIENT_URL,
      credentials: true,
    },
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const user = jwt.verify(token, env.JWT_SECRET) as { id: string; email: string };
      socket.data.user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.data.user.id;
    socket.join(`user:${userId}`);

    socket.on("joinConversation", (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("sendMessage", async (payload) => {
      // handled via HTTP in initial implementation; keep socket event for future expansion
      socket.emit("messageError", { error: "Use REST endpoint for sending messages in v1" });
    });
  });

  return io;
}

export function emitToUser(io: Server, userId: string, event: string, payload: any) {
  io.to(`user:${userId}`).emit(event, payload);
}

export function emitToConversation(io: Server, conversationId: string, event: string, payload: any) {
  io.to(`conversation:${conversationId}`).emit(event, payload);
}
```

