## `backend/src/controllers/chat.controller.ts`

```ts
import { Response } from "express";
import { prisma } from "../config/prisma";
import { AuthRequest } from "../middleware/auth";
import { io } from "../index";
import { emitToConversation, emitToUser } from "../services/socket.service";

export async function createConversation(req: AuthRequest, res: Response) {
  const userId = req.user!.id;
  const { participantIds } = req.body as { participantIds: string[] };

  const conversation = await prisma.conversation.create({
    data: {
      participants: {
        create: [{ userId }, ...participantIds.map((id) => ({ userId: id }))],
      },
    },
    include: { participants: true },
  });

  return res.json(conversation);
}

export async function getMessages(req: AuthRequest, res: Response) {
  const conversationId = req.params.id;

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    include: { sender: { select: { id: true, displayName: true, avatarUrl: true } } },
  });

  return res.json(messages);
}

export async function sendMessage(req: AuthRequest, res: Response) {
  const conversationId = req.params.id;
  const senderId = req.user!.id;
  const { content } = req.body;

  if (!content?.trim()) return res.status(400).json({ error: "Message content required" });

  const message = await prisma.message.create({
    data: { conversationId, senderId, content },
    include: { sender: { select: { id: true, displayName: true, avatarUrl: true } } },
  });

  const participants = await prisma.conversationParticipant.findMany({
    where: { conversationId },
    select: { userId: true },
  });

  emitToConversation(io, conversationId, "newMessage", message);

  for (const p of participants) {
    if (p.userId !== senderId) {
      await prisma.notification.create({
        data: {
          userId: p.userId,
          type: "MESSAGE",
          title: "New message",
          body: `${message.sender.displayName}: ${content.slice(0, 80)}`,
        },
      });

      emitToUser(io, p.userId, "newNotification", {
        type: "MESSAGE",
        title: "New message",
        body: `${message.sender.displayName}: ${content.slice(0, 80)}`,
      });
    }
  }

  return res.json(message);
}
```

