import { useEffect, useState } from "react";
import { apiFetch } from "../api/client";
import { useSocket } from "../context/SocketContext";

type Message = {
  id: string;
  content: string;
  sender: { id: string; displayName: string };
  createdAt: string;
};

export function ChatWindow({ conversationId, token }: { conversationId: string; token: string }) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [content, setContent] = useState("");
  const socket = useSocket();

  useEffect(() => {
    apiFetch(`/chat/conversation/${conversationId}/messages`, {}, token).then(setMessages);

    socket?.emit("joinConversation", conversationId);
    socket?.on("newMessage", (msg: Message) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => {
      socket?.off("newMessage");
    };
  }, [conversationId, socket, token]);

  async function send() {
    const msg = await apiFetch(
      `/chat/conversation/${conversationId}/message`,
      { method: "POST", body: JSON.stringify({ content }) },
      token
    );
    setContent("");
    return msg;
  }

  return (
    <div>
      <div style={{ border: "1px solid #ddd", padding: 12, minHeight: 300 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.sender.displayName}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 12 }}>
        <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type a message..." />
        <button onClick={send}>Send</button>
      </div>
    </div>
  );
}
