# 6) Real-time socket layer

## `server/src/socket/index.ts`

```ts
import { Server } from "http";
import { PrismaClient } from "@prisma/client";
import { Server as SocketIOServer } from "socket.io";
import jwt from "jsonwebtoken";
import { config } from "../config";

const prisma = new PrismaClient();

export function initSocket(server: Server) {
  const io = new SocketIOServer(server, {
    cors: {
      origin: config.clientUrl,
      credentials: true
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, config.jwtSecret) as { id: string; email: string };
      socket.data.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    const userId = socket.data.user.id;
    socket.join(`user:${userId}`);

    socket.on("conversation:join", (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("message:send", async (payload: { conversationId: string; content: string; recipientId?: string }) => {
      const message = await prisma.message.create({
        data: {
          conversationId: payload.conversationId,
          senderId: userId,
          recipientId: payload.recipientId,
          content: payload.content
        }
      });

      io.to(`conversation:${payload.conversationId}`).emit("message:new", message);

      if (payload.recipientId) {
        const notif = await prisma.notification.create({
          data: {
            userId: payload.recipientId,
            type: "MESSAGE",
            title: "New message",
            body: payload.content.slice(0, 120),
            data: { messageId: message.id, conversationId: payload.conversationId }
          }
        });

        io.to(`user:${payload.recipientId}`).emit("notification:new", notif);
      }
    });
  });

  return io;
}
```

