import { Router } from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth, AuthRequest } from "../middleware/auth";

const router = Router();
const prisma = new PrismaClient();

router.get("/conversation/:id", requireAuth, async (req: AuthRequest, res) => {
  const conversationId = req.params.id;
  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

router.post("/conversation", requireAuth, async (req: AuthRequest, res) => {
  const { participantIds } = req.body; // includes other users
  const userId = req.user!.id;

  const conversation = await prisma.conversation.create({
    data: {
      participants: {
        create: [userId, ...participantIds].map((id) => ({ userId: id }))
      }
    },
    include: { participants: true }
  });

  res.json(conversation);
});

export default router;
