## 8) Messaging API

**`app/api/messages/route.ts`**
```ts
import { prisma } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export async function GET() {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Unauthorized" }, { status: 401 });

  const messages = await prisma.message.findMany({
    where: {
      OR: [{ senderId: user.id }, { receiverId: user.id }],
    },
    orderBy: { createdAt: "desc" },
    take: 50,
    include: { sender: true, receiver: true },
  });

  return Response.json({ messages });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Unauthorized" }, { status: 401 });

  const { receiverId, content, priority } = await req.json();

  if (priority && user.credits < 1) {
    return Response.json({ error: "Not enough credits" }, { status: 402 });
  }

  const message = await prisma.message.create({
    data: {
      senderId: user.id,
      receiverId,
      content,
      priority: !!priority,
    },
  });

  if (priority) {
    await prisma.user.update({
      where: { id: user.id },
      data: { credits: { decrement: 1 } },
    });

    await prisma.creditLedger.create({
      data: { userId: user.id, amount: -1, reason: "Priority message" },
    });
  }

  await prisma.notification.create({
    data: {
      userId: receiverId,
      title: "New message",
      body: `${user.name ?? user.email} sent you a message`,
    },
  });

  return Response.json({ ok: true, message });
}
```

