## 11) Socket.IO server

Next.js alone doesn’t handle Socket.IO cleanly in the App Router, so use a small custom server.

**`server.ts`**
```ts
import next from "next";
import http from "http";
import { Server } from "socket.io";

const dev = process.env.NODE_ENV !== "production";
const app = next({ dev });
const handle = app.getRequestHandler();

app.prepare().then(() => {
  const server = http.createServer((req, res) => handle(req, res));
  const io = new Server(server, {
    cors: { origin: "*" },
  });

  io.on("connection", (socket) => {
    socket.on("join", (userId) => {
      socket.join(userId);
    });

    socket.on("send-message", ({ toUserId, message }) => {
      io.to(toUserId).emit("new-message", message);
      io.to(toUserId).emit("new-notification", {
        title: "New message",
        body: "You received a new message",
      });
    });

    socket.on("disconnect", () => {});
  });

  server.listen(3000, () => {
    console.log("> Ready on http://localhost:3000");
  });
});
```

