## 13) Chat component

**`components/Chat.tsx`**
```tsx
"use client";

import { useEffect, useState } from "react";
import { socket } from "@/lib/socket";

export default function Chat({ userId }: { userId: string }) {
  const [toUserId, setToUserId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState<any[]>([]);

  useEffect(() => {
    socket.connect();
    socket.emit("join", userId);

    socket.on("new-message", (msg) => {
      setMessages((prev) => [msg, ...prev]);
    });

    return () => {
      socket.off("new-message");
      socket.disconnect();
    };
  }, [userId]);

  async function sendMessage() {
    const res = await fetch("/api/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ receiverId: toUserId, content }),
    });

    const data = await res.json();
    if (data.ok) {
      socket.emit("send-message", { toUserId, message: data.message });
      setMessages((prev) => [data.message, ...prev]);
      setContent("");
    } else {
      alert(data.error || "Failed");
    }
  }

  return (
    <div>
      <h2>Chat</h2>
      <input placeholder="Receiver userId" value={toUserId} onChange={(e) => setToUserId(e.target.value)} />
      <input placeholder="Message" value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>

      <ul>
        {messages.map((m) => (
          <li key={m.id}>
            {m.content} {m.priority ? "⭐" : ""}
          </li>
        ))}
      </ul>
    </div>
  );
}
```

