## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initDb } from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const db = await initDb();

// In-memory online user map: userId -> socketId
const onlineUsers = new Map();

function emitNotification(userId, notification) {
  const socketId = onlineUsers.get(String(userId));
  if (socketId) {
    io.to(socketId).emit("notification", notification);
  }
}

function emitMessage(receiverId, message) {
  const socketId = onlineUsers.get(String(receiverId));
  if (socketId) {
    io.to(socketId).emit("message", message);
  }
}

// Register / login (MVP-style)
app.post("/auth", async (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  let user = await db.get("SELECT * FROM users WHERE username = ?", username);

  if (!user) {
    const result = await db.run(
      "INSERT INTO users (username, coins) VALUES (?, ?)",
      username,
      100
    );
    user = await db.get("SELECT * FROM users WHERE id = ?", result.lastID);
  }

  res.json(user);
});

// Get users
app.get("/users", async (_req, res) => {
  const users = await db.all("SELECT id, username, coins FROM users");
  res.json(users);
});

// Get messages between two users
app.get("/messages", async (req, res) => {
  const { userId, otherUserId } = req.query;
  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (senderId = ? AND receiverId = ?)
        OR (senderId = ? AND receiverId = ?)
     ORDER BY createdAt ASC`,
    userId, otherUserId, otherUserId, userId
  );
  res.json(messages);
});

// Send message
app.post("/messages", async (req, res) => {
  const { senderId, receiverId, content, isPremium = false } = req.body;

  if (!senderId || !receiverId || !content) {
    return res.status(400).json({ error: "missing fields" });
  }

  const sender = await db.get("SELECT * FROM users WHERE id = ?", senderId);
  if (!sender) return res.status(404).json({ error: "sender not found" });

  const cost = isPremium ? 10 : 0;
  if (sender.coins < cost) {
    return res.status(400).json({ error: "not enough coins" });
  }

  if (cost > 0) {
    await db.run("UPDATE users SET coins = coins - ? WHERE id = ?", cost, senderId);
  }

  const result = await db.run(
    "INSERT INTO messages (senderId, receiverId, content, isPremium) VALUES (?, ?, ?, ?)",
    senderId, receiverId, content, isPremium ? 1 : 0
  );

  const message = await db.get("SELECT * FROM messages WHERE id = ?", result.lastID);

  const notificationText = isPremium
    ? `You received a premium message from user ${senderId}`
    : `You received a new message from user ${senderId}`;

  await db.run(
    "INSERT INTO notifications (userId, type, content) VALUES (?, ?, ?)",
    receiverId,
    "message",
    notificationText
  );

  emitMessage(receiverId, message);
  emitNotification(receiverId, {
    type: "message",
    content: notificationText
  });

  res.json(message);
});

// Buy coins
app.post("/wallet/buy", async (req, res) => {
  const { userId, amount = 100 } = req.body;
  if (!userId) return res.status(400).json({ error: "userId required" });

  // MVP: no real payment provider; just simulate purchase
  await db.run("UPDATE users SET coins = coins + ? WHERE id = ?", amount, userId);

  const user = await db.get("SELECT * FROM users WHERE id = ?", userId);

  await db.run(
    "INSERT INTO notifications (userId, type, content) VALUES (?, ?, ?)",
    userId,
    "wallet",
    `You purchased ${amount} coins`
  );

  emitNotification(userId, {
    type: "wallet",
    content: `You purchased ${amount} coins`
  });

  res.json(user);
});

// Get notifications
