import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";
import { api } from "./api";

const socket = io("http://localhost:4000");

export default function App() {
  const [username, setUsername] = useState("");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [content, setContent] = useState("");
  const [premium, setPremium] = useState(false);

  async function login() {
    const res = await api.post("/auth", { username });
    setUser(res.data);
    socket.emit("register", res.data.id);
  }

  async function loadUsers() {
    const res = await api.get("/users");
    setUsers(res.data.filter((u) => u.id !== user?.id));
  }

  async function loadMessages(otherUserId) {
    const res = await api.get("/messages", {
      params: { userId: user.id, otherUserId }
    });
    setMessages(res.data);
  }

  async function loadNotifications() {
    const res = await api.get("/notifications", {
      params: { userId: user.id }
    });
    setNotifications(res.data);
  }

  async function sendMessage() {
    if (!selectedUserId || !content) return;
    await api.post("/messages", {
      senderId: user.id,
      receiverId: selectedUserId,
      content,
      isPremium: premium
    });
    setContent("");
    loadMessages(selectedUserId);
    loadUsers();
    loadNotifications();
  }

  async function buyCoins() {
    await api.post("/wallet/buy", {
      userId: user.id,
      amount: 100
    });
    const updated = await api.post("/auth", { username: user.username });
    setUser(updated.data);
    loadNotifications();
  }

  useEffect(() => {
    if (!user) return;

    loadUsers();
    loadNotifications();

    socket.on("message", (msg) => {
      if (
        (msg.senderId === selectedUserId && msg.receiverId === user.id) ||
        (msg.senderId === user.id && msg.receiverId === selectedUserId)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [
        { id: Date.now(), ...notif, read: 0 },
        ...prev
      ]);
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [user, selectedUserId]);

  useEffect(() => {
    if (user && selectedUserId) {
      loadMessages(selectedUserId);
    }
  }, [selectedUserId]);

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App MVP</h2>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={login}>Login / Register</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 220 }}>
        <h3>{user.username}</h3>
        <p>Coins: {user.coins}</p>
        <button onClick={buyCoins}>Buy 100 Coins</button>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button
              onClick={() => {
                setSelectedUserId(u.id);
                loadMessages(u.id);
              }}
            >
              {u.username} ({u.coins})
            </button>
          </div>
        ))}

        <h4>Notifications</h4>
        <div style={{ maxHeight: 300, overflow: "auto" }}>
          {notifications.map((n, idx) => (
            <div key={n.id || idx} style={{ borderBottom: "1px solid #ddd" }}>
              {n.content}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat</h3>
        {!selectedUserId ? (
          <p>Select a user to start chatting</p>
        ) : (
          <>
            <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto", padding: 10 }}>
              {messages.map((m) => (
                <div key={m.id}>
                  <b>{m.senderId === user.id ? "You" : "Them"}:</b>{" "}
                  {m.content} {m.isPremium ? "⭐" : ""}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 10 }}>
              <input
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Type a message"
                style={{ width: "70%" }}
              />
              <label style={{ marginLeft: 10 }}>
                <input
                  type="checkbox"
                  checked={premium}
                  onChange={(e) => setPremium(e.target.checked)}
                />
                Premium (10 coins)
              </label>
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
