## `server/socket.js`

```js
import { Server } from "socket.io";
import { verifySocketToken } from "./auth.js";

export function setupSocket(httpServer, db) {
  const io = new Server(httpServer, {
    cors: { origin: "http://localhost:5173" }
  });

  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("Missing token"));
      socket.user = verifySocketToken(token);
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    socket.join(`user:${socket.user.id}`);

    socket.on("joinConversation", (conversationId) => {
      socket.join(`conv:${conversationId}`);
    });

    socket.on("sendMessage", async ({ conversationId, content, isPremium }) => {
      const senderId = socket.user.id;
      const premium = isPremium ? 1 : 0;

      if (premium) {
        const user = await db.get("SELECT credits FROM users WHERE id = ?", senderId);
        if (!user || user.credits < 1) {
          socket.emit("errorMessage", { error: "Not enough credits" });
          return;
        }
        await db.run("UPDATE users SET credits = credits - 1 WHERE id = ?", senderId);
      }

      const result = await db.run(
        `INSERT INTO messages (conversation_id, sender_id, content, is_premium)
         VALUES (?, ?, ?, ?)`,
        conversationId,
        senderId,
        content,
        premium
      );

      const message = {
        id: result.lastID,
        conversationId,
        senderId,
        content,
        isPremium: !!premium,
        createdAt: new Date().toISOString()
      };

      io.to(`conv:${conversationId}`).emit("newMessage", message);

      // Notify the other participant
      const conv = await db.get(
        "SELECT user1_id, user2_id FROM conversations WHERE id = ?",
        conversationId
      );
      const otherUserId = conv.user1_id === senderId ? conv.user2_id : conv.user1_id;

      io.to(`user:${otherUserId}`).emit("notification", {
        type: premium ? "premium_message" : "message",
        conversationId,
        message: premium ? "You received a premium message" : "You received a new message"
      });

      // Send updated credits to sender
      const updated = await db.get("SELECT credits FROM users WHERE id = ?", senderId);
      io.to(`user:${senderId}`).emit("creditsUpdated", { credits: updated.credits });
    });
  });

  return io;
}
```

