import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import http from "http";
import { initDb } from "./db.js";
import { signToken, requireAuth } from "./auth.js";
import { setupSocket } from "./socket.js";

const app = express();
app.use(cors({ origin: "http://localhost:5173" }));
app.use(express.json());

const db = await initDb();
const server = http.createServer(app);
setupSocket(server, db);

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  try {
    const hash = await bcrypt.hash(password, 10);
    const result = await db.run(
      "INSERT INTO users (username, password_hash, credits) VALUES (?, ?, 3)",
      username,
      hash
    );

    const user = { id: result.lastID, username };
    const token = signToken(user);
    res.json({ token, user: { ...user, credits: 3 } });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", username);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({
    token,
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

app.get("/api/me", requireAuth, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", req.user.id);
  res.json(user);
});

app.get("/api/users", requireAuth, async (req, res) => {
  const users = await db.all(
    "SELECT id, username, credits FROM users WHERE id != ?",
    req.user.id
  );
  res.json(users);
});

app.post("/api/conversations", requireAuth, async (req, res) => {
  const { otherUserId } = req.body;
  const a = Math.min(req.user.id, otherUserId);
  const b = Math.max(req.user.id, otherUserId);

  let conv = await db.get(
    "SELECT * FROM conversations WHERE user1_id = ? AND user2_id = ?",
    a,
    b
  );

  if (!conv) {
    const result = await db.run(
      "INSERT INTO conversations (user1_id, user2_id) VALUES (?, ?)",
      a,
      b
    );
    conv = { id: result.lastID, user1_id: a, user2_id: b };
  }

  res.json(conv);
});

app.get("/api/conversations", requireAuth, async (req, res) => {
  const convs = await db.all(
    `SELECT * FROM conversations
     WHERE user1_id = ? OR user2_id = ?`,
    req.user.id,
    req.user.id
  );
  res.json(convs);
});

app.get("/api/messages/:conversationId", requireAuth, async (req, res) => {
  const messages = await db.all(
    `SELECT * FROM messages
     WHERE conversation_id = ?
     ORDER BY created_at ASC`,
    req.params.conversationId
  );
  res.json(messages);
});

app.post("/api/credits/buy", requireAuth, async (req, res) => {
  const { amount } = req.body;
  const add = Number(amount || 0);
  if (add <= 0) return res.status(400).json({ error: "Invalid amount" });

  await db.run("UPDATE users SET credits = credits + ? WHERE id = ?", add, req.user.id);
  const user = await db.get("SELECT credits FROM users WHERE id = ?", req.user.id);
  res.json({ credits: user.credits });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
