import React, { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const [users, setUsers] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [selectedConv, setSelectedConv] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [isPremium, setIsPremium] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => (token ? createSocket(token) : null), [token]);

  useEffect(() => {
    if (!token) return;
    api("/me", token).then(setUser);
    api("/users", token).then(setUsers);
    api("/conversations", token).then(setConversations);
  }, [token]);

  useEffect(() => {
    if (!socket) return;

    socket.on("newMessage", (msg) => {
      if (selectedConv && Number(selectedConv.id) === Number(msg.conversationId)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [{ ...n, id: Date.now() }, ...prev]);
    });

    socket.on("creditsUpdated", ({ credits }) => {
      setUser((u) => (u ? { ...u, credits } : u));
    });

    socket.on("errorMessage", ({ error }) => {
      alert(error);
    });

    return () => socket.disconnect();
  }, [socket, selectedConv]);

  useEffect(() => {
    if (!selectedConv || !socket) return;
    socket.emit("joinConversation", selectedConv.id);
    api(`/messages/${selectedConv.id}`, token).then(setMessages);
  }, [selectedConv, socket, token]);

  async function handleAuth() {
    const path = authMode === "login" ? "/login" : "/register";
    const data = await api(path, null, "POST", { username, password });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function openConversation(otherUserId) {
    const conv = await api("/conversations", token, "POST", { otherUserId });
    setSelectedConv(conv);
    const convs = await api("/conversations", token);
    setConversations(convs);
  }

  function sendMessage() {
    if (!socket || !selectedConv || !message.trim()) return;
    socket.emit("sendMessage", {
      conversationId: selectedConv.id,
      content: message,
      isPremium
    });
    setMessage("");
  }

  async function buyCredits() {
    const data = await api("/credits/buy", token, "POST", { amount: 5 });
    setUser((u) => ({ ...u, credits: data.credits }));
  }

  if (!token) {
    return (
      <div className="auth">
        <h1>Messaging App</h1>
        <div className="card">
          <h2>{authMode}</h2>
          <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
          <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
          <button onClick={handleAuth}>{authMode}</button>
          <button onClick={() => setAuthMode(authMode === "login" ? "register" : "login")}>
            Switch to {authMode === "login" ? "register" : "login"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="layout">
      <aside className="sidebar">
        <h2>{user?.username}</h2>
        <p>Credits: {user?.credits ?? 0}</p>
        <button onClick={buyCredits}>Buy 5 Credits</button>

        <h3>Users</h3>
        {users.map((u) => (
          <button key={u.id} onClick={() => openConversation(u.id)}>
            {u.username}
          </button>
        ))}

        <h3>Notifications</h3>
        <div className="notifications">
          {notifications.map((n) => (
            <div key={n.id} className="notification">
              {n.message}
            </div>
          ))}
        </div>
      </aside>

      <main className="chat">
        <h2>
          {selectedConv ? `Conversation #${selectedConv.id}` : "Select a user"}
        </h2>

        <div className="messages">
          {messages.map((m) => (
            <div key={m.id} className={`message ${m.isPremium ? "premium" : ""}`}>
              <strong>{m.senderId === user?.id ? "You" : `User ${m.senderId}`}</strong>: {m.content}
              {m.isPremium && <span className="badge">Premium</span>}
            </div>
          ))}
        </div>

        <div className="composer">
          <input value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Type a message..." />
          <label>
            <input type="checkbox" checked={isPremium} onChange={(e) => setIsPremium(e.target.checked)} />
            Premium send (costs 1 credit)
          </label>
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>
    </div>
  );
}
