### `frontend/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";
import { socket } from "../socket";

export default function Chat() {
  const user = JSON.parse(localStorage.getItem("user"));
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    socket.connect();
    socket.emit("join", user.id);

    socket.on("new_message", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("new_notification", (n) => setNotifications((prev) => [n, ...prev]));

    return () => {
      socket.off("new_message");
      socket.off("new_notification");
    };
  }, []);

  const loadMessages = async () => {
    const res = await api.get(`/chat/messages/${receiverId}`);
    setMessages(res.data);
  };

  const send = () => {
    socket.emit("send_message", {
      senderId: user.id,
      receiverId,
      content
    });
    setContent("");
  };

  return (
    <div>
      <h2>Chat</h2>
      <input placeholder="Receiver ID" value={receiverId} onChange={(e) => setReceiverId(e.target.value)} />
      <button onClick={loadMessages}>Load conversation</button>

      <div>
        {messages.map((m) => (
          <div key={m.id}>{m.content}</div>
        ))}
      </div>

      <input placeholder="Message" value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send</button>

      <h3>Notifications</h3>
      {notifications.map((n) => (
        <div key={n.id}>{n.title}: {n.body}</div>
      ))}
    </div>
  );
}
```

