# 11) Real-time chat client

## `src/components/ChatClient.tsx`

```tsx
"use client";

import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io();

type Message = {
  id: string;
  content: string;
  createdAt: string;
  sender: { id: string; name: string };
};

export default function ChatClient() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    fetch("/api/messages")
      .then((r) => r.json())
      .then((d) => setMessages(d.messages || []));

    socket.on("message:new", (msg: Message) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification:new", (n) => {
      alert(`${n.title}: ${n.body}`);
    });

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
    };
  }, []);

  async function sendMessage() {
    const res = await fetch("/api/messages", {
      method: "POST",
      body: JSON.stringify({ content }),
    });
    const data = await res.json();
    if (res.ok) {
      socket.emit("message:new", data.message);
      setContent("");
    } else {
      alert(data.error || "Failed");
    }
  }

  async function supportApp() {
    const res = await fetch("/api/stripe/checkout", { method: "POST" });
    const data = await res.json();
    if (data.url) window.location.href = data.url;
  }

  return (
    <div style={{ padding: 24 }}>
      <h2>Chat</h2>
      <button onClick={supportApp}>Support the App ($4.99)</button>

      <div style={{ marginTop: 20, border: "1px solid #ccc", padding: 12, height: 300, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.sender.name}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 12 }}>
        <input value={content} onChange={(e) => setContent(e.target.value)} />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
```

