      `INSERT INTO users (username, password, credits, premium) VALUES (?, ?, 0, 0)`
    );
    const info = stmt.run(username, hash);
    const user = { id: info.lastInsertRowid, username };
    const token = signToken(user);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;

  const user = db.prepare(`SELECT * FROM users WHERE username = ?`).get(username);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = bcrypt.compareSync(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({
    token,
    user: { id: user.id, username: user.username, credits: user.credits, premium: user.premium }
  });
});

app.get("/api/me", authMiddleware, (req, res) => {
  const user = db.prepare(`SELECT id, username, credits, premium FROM users WHERE id = ?`).get(req.user.id);
  res.json(user);
});

app.get("/api/messages/:otherUserId", authMiddleware, (req, res) => {
