});

app.post("/api/messages", authMiddleware, (req, res) => {
  const { receiverId, content, premium = false } = req.body;
  const senderId = req.user.id;

  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = db.prepare(`SELECT * FROM users WHERE id = ?`).get(senderId);
  const receiver = db.prepare(`SELECT * FROM users WHERE id = ?`).get(receiverId);
  if (!receiver) return res.status(404).json({ error: "Receiver not found" });

  // Premium message costs 1 credit
  if (premium) {
    if (sender.credits < 1) return res.status(400).json({ error: "Not enough credits" });
    db.prepare(`UPDATE users SET credits = credits - 1 WHERE id = ?`).run(senderId);
  }

  const info = db.prepare(`
    INSERT INTO messages (senderId, receiverId, content)
    VALUES (?, ?, ?)
  `).run(senderId, receiverId, premium ? `[PREMIUM] ${content}` : content);

  const message = {
    id: info.lastInsertRowid,
    senderId,
    receiverId,
    content: premium ? `[PREMIUM] ${content}` : content,
    createdAt: new Date().toISOString()
  };

  io.to(`user:${receiverId}`).emit("message", message);
  addNotification(receiverId, "message", `New message from ${sender.username}`);

  res.json(message);
});

app.get("/api/notifications", authMiddleware, (req, res) => {
