import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [content, setContent] = useState("");
  const [premium, setPremium] = useState(false);
  const [error, setError] = useState("");

  async function loadApp(tok) {
    const user = await api("/me", "GET", null, tok);
    setMe(user);
    const us = await api("/users", "GET", null, tok);
    setUsers(us);
    const notifs = await api("/notifications", "GET", null, tok);
    setNotifications(notifs);
  }

  useEffect(() => {
    if (!token) return;

    loadApp(token).catch((e) => setError(e.message));

    const s = createSocket(token);
    setSocket(s);

    s.on("message", (msg) => {
      if (selectedUser && Number(selectedUser.id) === msg.senderId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    s.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    return () => s.disconnect();
  }, [token, selectedUser]);

  async function handleRegister() {
    setError("");
    const data = await api("/register", "POST", { username, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
  }

  async function handleLogin() {
    setError("");
    const data = await api("/login", "POST", { username, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
  }

  async function selectUser(user) {
    setSelectedUser(user);
    const msgs = await api(`/messages/${user.id}`, "GET", null, token);
    setMessages(msgs);
  }

  async function sendMessage() {
    if (!selectedUser) return;
    const msg = await api("/messages", "POST", {
      receiverId: selectedUser.id,
      content,
      premium
    }, token);

    setMessages((prev) => [...prev, msg]);
    setContent("");
  }

  async function buyCredits() {
    const data = await api("/buy-credits", "POST", { amount: 10 }, token);
    setMe(data.user);
  }

  async function unlockPremium() {
    const data = await api("/unlock-premium", "POST", {}, token);
    setMe(data);
  }

  async function markNotificationsRead() {
    await api("/notifications/read", "POST", {}, token);
    setNotifications((prev) => prev.map((n) => ({ ...n, read: 1 })));
  }

  if (!token) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h2>Social Messaging App</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <br />
        <button onClick={handleRegister}>Register</button>
        <button onClick={handleLogin}>Login</button>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20, fontFamily: "sans-serif" }}>
      <div style={{ width: 220 }}>
        <h3>Me</h3>
        {me && (
          <div>
            <div>@{me.username}</div>
            <div>Credits: {me.credits}</div>
            <div>Premium: {me.premium ? "Yes" : "No"}</div>
          </div>
        )}
        <button onClick={buyCredits}>Buy 10 Credits</button>
        <button onClick={unlockPremium}>Unlock Premium (5)</button>

        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => selectUser(u)}>
              {u.username} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === me?.id ? "You" : selectedUser?.username}:</b> {m.content}
            </div>
          ))}
        </div>

        <div style={{ marginTop: 10 }}>
          <input
            style={{ width: "70%" }}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message"
          />
          <label style={{ marginLeft: 10 }}>
            <input
              type="checkbox"
              checked={premium}
              onChange={(e) => setPremium(e.target.checked)}
            />
            Premium (costs 1 credit)
          </label>
          <button onClick={sendMessage}>Send</button>
        </div>

        <h3>Notifications</h3>
        <button onClick={markNotificationsRead}>Mark all read</button>
        <ul>
          {notifications.map((n) => (
            <li key={n.id} style={{ fontWeight: n.read ? "normal" : "bold" }}>
              [{n.type}] {n.content}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
