import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import { initDB } from "./db.js";

const JWT_SECRET = "dev_secret_change_me";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const db = await initDB();

function createToken(user) {
  return jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, {
    expiresIn: "7d"
  });
}

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "Missing token" });

  const token = auth.split(" ")[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

async function addNotification(userId, type, content) {
  const result = await db.run(
    `INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)`,
    [userId, type, content]
  );

  const notification = {
    id: result.lastID,
    userId,
    type,
    content
  };

  io.to(`user:${userId}`).emit("notification", notification);
  return notification;
}

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

// Register
app.post("/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  try {
    const passwordHash = await bcrypt.hash(password, 10);
    const result = await db.run(
      `INSERT INTO users (username, password_hash) VALUES (?, ?)`,
      [username, passwordHash]
    );

    const user = { id: result.lastID, username };
    const token = createToken(user);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

// Login
app.post("/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get(`SELECT * FROM users WHERE username = ?`, [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = createToken(user);
  res.json({
    token,
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

// Current user
app.get("/me", authMiddleware, async (req, res) => {
  const user = await db.get(`SELECT id, username, credits FROM users WHERE id = ?`, [
    req.user.id
  ]);
  res.json(user);
});

// List users
app.get("/users", authMiddleware, async (req, res) => {
  const users = await db.all(
    `SELECT id, username, credits FROM users WHERE id != ?`,
    [req.user.id]
  );
  res.json(users);
});

// Get messages with another user
app.get("/messages/:otherUserId", authMiddleware, async (req, res) => {
  const otherUserId = Number(req.params.otherUserId);
  const messages = await db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
    `,
    [req.user.id, otherUserId, otherUserId, req.user.id]
  );
  res.json(messages);
});

// Send message
app.post("/messages", authMiddleware, async (req, res) => {
  const { receiverId, content, premium } = req.body;
  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  const isPremium = premium ? 1 : 0;

  if (isPremium) {
    const sender = await db.get(`SELECT credits FROM users WHERE id = ?`, [
      req.user.id
    ]);
    if (sender.credits < 1) {
      return res.status(400).json({ error: "Not enough credits" });
    }
    await db.run(`UPDATE users SET credits = credits - 1 WHERE id = ?`, [
      req.user.id
    ]);
  }

  const result = await db.run(
    `INSERT INTO messages (sender_id, receiver_id, content, is_premium) VALUES (?, ?, ?, ?)`,
    [req.user.id, receiverId, content, isPremium]
  );

  const message = {
    id: result.lastID,
    sender_id: req.user.id,
    receiver_id: receiverId,
    content,
    is_premium: isPremium
  };

  io.to(`user:${receiverId}`).emit("message", message);
  await addNotification(
    receiverId,
    "message",
    `New message from user ${req.user.username}`
  );

  res.json({ ok: true, message });
});

// Buy credits (demo monetization)
app.post("/buy-credits", authMiddleware, async (req, res) => {
  const { amount } = req.body;
  const creditsToAdd = Number(amount || 0);

  if (creditsToAdd <= 0) {
    return res.status(400).json({ error: "Invalid amount" });
  }

  await db.run(`UPDATE users SET credits = credits + ? WHERE id = ?`, [
    creditsToAdd,
    req.user.id
  ]);

  await addNotification(
    req.user.id,
    "purchase",
    `You purchased ${creditsToAdd} credits`
  );

  const user = await db.get(`SELECT id, username, credits FROM users WHERE id = ?`, [
    req.user.id
  ]);

  res.json({ ok: true, user });
});

// Notifications
app.get("/notifications", authMiddleware, async (req, res) => {
  const notifications = await db.all(
    `SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC`,
    [req.user.id]
  );
  res.json(notifications);
});

