import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:3001";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [content, setContent] = useState("");
  const [premium, setPremium] = useState(false);
  const [form, setForm] = useState({ username: "", password: "" });

  const socket = useMemo(() => io(API), []);

  async function api(path, options = {}) {
    const res = await fetch(`${API}${path}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(options.headers || {})
      }
    });
    return res.json();
  }

  async function loadMe(tkn = token) {
    if (!tkn) return;
    const res = await fetch(`${API}/me`, {
      headers: { Authorization: `Bearer ${tkn}` }
    });
    const data = await res.json();
    if (data.error) return;
    setUser(data);
  }

  async function loadUsers() {
    const data = await api("/users");
    setUsers(data);
  }

  async function loadNotifications() {
    const data = await api("/notifications");
    setNotifications(data);
  }

  async function loadMessages(otherUserId) {
    const data = await api(`/messages/${otherUserId}`);
    setMessages(data);
  }

  useEffect(() => {
    if (user?.id) {
      socket.emit("join", user.id);
      loadUsers();
      loadNotifications();
    }
  }, [user]);

  useEffect(() => {
    socket.on("message", (msg) => {
      if (selectedUser && msg.sender_id === selectedUser.id) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
      if (n.type === "purchase") {
        loadMe();
      }
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [selectedUser]);

  useEffect(() => {
    if (token) loadMe();
  }, [token]);

  async function register(e) {
    e.preventDefault();
    const data = await api("/register", {
      method: "POST",
      body: JSON.stringify(form)
    });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function login(e) {
    e.preventDefault();
    const data = await api("/login", {
      method: "POST",
      body: JSON.stringify(form)
    });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function selectUser(u) {
    setSelectedUser(u);
    await loadMessages(u.id);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const data = await api("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content,
        premium
      })
    });

    if (data.error) {
      alert(data.error);
      return;
    }

    setMessages((prev) => [...prev, data.message]);
    setContent("");
    setPremium(false);
    await loadMe();
  }

  async function buyCredits() {
    const data = await api("/buy-credits", {
      method: "POST",
      body: JSON.stringify({ amount: 5 })
    });
    if (data.error) alert(data.error);
    else setUser(data.user);
  }

  if (!user) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h2>Social Messaging MWV</h2>
        <form onSubmit={register}>
          <input
            placeholder="username"
            value={form.username}
            onChange={(e) => setForm({ ...form, username: e.target.value })}
          />
          <input
            placeholder="password"
            type="password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />
          <button type="submit">Register</button>
          <button type="button" onClick={login}>Login</button>
        </form>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", fontFamily: "sans-serif", height: "100vh" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 12 }}>
        <h3>{user.username}</h3>
        <p>Credits: {user.credits ?? 0}</p>
        <button onClick={buyCredits}>Buy 5 Credits</button>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => selectUser(u)}>{u.username}</button>
          </div>
        ))}

        <h4>Notifications</h4>
        {notifications.map((n) => (
          <div key={n.id} style={{ fontSize: 12, marginBottom: 8 }}>
            <b>{n.type}</b>: {n.content}
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 12 }}>
        {selectedUser ? (
          <>
            <h3>Chat with {selectedUser.username}</h3>
            <div style={{ height: 400, overflow: "auto", border: "1px solid #ddd", padding: 8 }}>
              {messages.map((m) => (
                <div key={m.id}>
                  <b>{m.sender_id === user.id ? "You" : selectedUser.username}:</b>{" "}
                  {m.content} {m.is_premium ? "⭐" : ""}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 12 }}>
              <input
                style={{ width: "60%" }}
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Type a message"
              />
              <label style={{ marginLeft: 8 }}>
                <input
                  type="checkbox"
                  checked={premium}
                  onChange={(e) => setPremium(e.target.checked)}
                />
                Premium message (1 credit)
              </label>
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a user to start chatting.</p>
        )}
      </div>
    </div>
  );
}
