## 3.6 Stripe route: `server/src/stripe.js`

```js
import express from "express";
import Stripe from "stripe";

export function stripeRoutes(prisma) {
  const router = express.Router();
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

  router.post("/checkout", async (req, res) => {
    const { userId, credits } = req.body;

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${credits} Credits` },
            unit_amount: credits * 100
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
      cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`,
      metadata: { userId, credits: String(credits) }
    });

    res.json({ url: session.url });
  });

  // NOTE: For minimal demo, webhook verification can be added later.
  // In production, use raw body + signature verification.
  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    res.status(200).json({ received: true });
  });

  return router;
}
```

