## 3.8 Main server: `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import { PrismaClient } from "@prisma/client";
import { createServer } from "http";
import { Server } from "socket.io";
import { authRoutes } from "./auth.js";
import { authMiddleware } from "./middleware.js";
import { setupSocket } from "./socket.js";
import { stripeRoutes } from "./stripe.js";

dotenv.config();

const app = express();
const server = createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

app.use("/auth", authRoutes(prisma));
app.use("/stripe", stripeRoutes(prisma));

app.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  res.json(user);
});

app.get("/users", authMiddleware, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, credits: true }
  });
  res.json(users);
});

app.get("/messages/:otherUserId", authMiddleware, async (req, res) => {
  const { otherUserId } = req.params;
  const userId = req.user.id;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: userId, receiverId: otherUserId },
        { senderId: otherUserId, receiverId: userId }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.post("/send", authMiddleware, async (req, res) => {
  const { receiverId, text, boosted } = req.body;
  const senderId = req.user.id;

  const user = await prisma.user.findUnique({ where: { id: senderId } });
  if (boosted && user.credits < 1) {
    return res.status(400).json({ error: "Not enough credits" });
  }

  const message = await prisma.message.create({
    data: { senderId, receiverId, text, boosted: !!boosted }
  });

  if (boosted) {
    await prisma.user.update({
      where: { id: senderId },
      data: { credits: { decrement: 1 } }
    });
  }

  const sender = await prisma.user.findUnique({ where: { id: senderId } });
  await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      content: `New message from ${sender.name}`
    }
  });

  io.to(receiverId).emit("new_message", { ...message, sender });
  io.to(receiverId).emit("notification", {
    type: "message",
    content: `New message from ${sender.name}`
  });

  res.json({ ok: true, message });
});

app.post("/buy-credits", authMiddleware, async (req, res) => {
  const { credits } = req.body;
  await prisma.user.update({
    where: { id: req.user.id },
    data: { credits: { increment: credits } }
  });
  res.json({ ok: true });
});

setupSocket(io, prisma);

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on http://localhost:${process.env.PORT || 4000}`);
});
```

