        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => loadMessages(u)}>
              {u.name} ({u.credits})
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat {selected ? `with ${selected.name}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
