## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { initDb } from "./db.js";
import { authMiddleware, signToken } from "./auth.js";
import { makeStripe } from "./stripe.js";

dotenv.config();

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL }
});

const db = await initDb();
const stripe = makeStripe(process.env.STRIPE_SECRET_KEY);
const requireAuth = authMiddleware(process.env.JWT_SECRET);

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(String(userId), socket.id);
    socket.join(`user:${userId}`);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

// Auth
app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const hash = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      "INSERT INTO users (username, password_hash) VALUES (?, ?)",
      [username, hash]
    );
    const user = { id: result.lastID, username, premium: 0 };
    const token = signToken(user, process.env.JWT_SECRET);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = signToken(user, process.env.JWT_SECRET);
  res.json({
    token,
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

// Users
app.get("/api/users", requireAuth, async (req, res) => {
  const users = await db.all("SELECT id, username, premium FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

// Messages
app.get("/api/messages/:otherUserId", requireAuth, async (req, res) => {
  const me = req.user.id;
  const other = Number(req.params.otherUserId);

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (sender_id = ? AND recipient_id = ?)
        OR (sender_id = ? AND recipient_id = ?)
     ORDER BY created_at ASC`,
    [me, other, other, me]
  );

  res.json(messages);
});

app.post("/api/messages", requireAuth, async (req, res) => {
  const { recipientId, content } = req.body;
  if (!recipientId || !content) return res.status(400).json({ error: "Missing fields" });

  const result = await db.run(
    "INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)",
    [req.user.id, recipientId, content]
  );

  const message = {
    id: result.lastID,
    sender_id: req.user.id,
    recipient_id: recipientId,
    content,
    created_at: new Date().toISOString()
  };

  // Emit to recipient if online
  io.to(`user:${recipientId}`).emit("message:new", message);
  io.to(`user:${recipientId}`).emit("notification:new", {
    type: "message",
    text: `New message from ${req.user.username}`
  });

  res.json(message);
});

// Premium monetization
app.post("/api/create-checkout-session", requireAuth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: process.env.STRIPE_SUCCESS_URL,
    cancel_url: process.env.STRIPE_CANCEL_URL,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Unlock" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: String(req.user.id)
    }
  });

  res.json({ url: session.url });
});

// Minimal success endpoint for MVP
app.post("/api/mark-premium", requireAuth, async (req, res) => {
  await db.run("UPDATE users SET premium = 1 WHERE id = ?", [req.user.id]);
  res.json({ ok: true });
});

app.get("/api/me", requireAuth, async (req, res) => {
  const user = await db.get("SELECT id, username, premium FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on http://localhost:${process.env.PORT || 4000}`);
});
```

