```jsx
import React, { useEffect, useState } from "react";
import { api, setToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setLocalToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notice, setNotice] = useState("");
  const [unread, setUnread] = useState(0);

  useEffect(() => {
    if (!token) return;
    setToken(token);
    loadMeAndUsers();
    socket.connect();
    socket.on("message:new", (msg) => {
      if (selectedUser && String(msg.sender_id) === String(selectedUser.id)) {
        setMessages((m) => [...m, msg]);
      } else {
        setUnread((n) => n + 1);
      }
    });
    socket.on("notification:new", (n) => setNotice(n.text));
    return () => {
      socket.off("message:new");
      socket.off("notification:new");
      socket.disconnect();
    };
  }, [token, selectedUser]);

  async function loadMeAndUsers() {
    const me = await api.get("/me");
    setUser(me.data);
    const us = await api.get("/users");
    setUsers(us.data);
    socket.emit("register", me.data.id);
  }

  async function auth(endpoint, username, password) {
    const res = await api.post(endpoint, { username, password });
    localStorage.setItem("token", res.data.token);
    setLocalToken(res.data.token);
    setUser(res.data.user);
  }

  async function openChat(other) {
    setSelectedUser(other);
    setUnread(0);
    const res = await api.get(`/messages/${other.id}`);
    setMessages(res.data);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const res = await api.post("/messages", {
      recipientId: selectedUser.id,
      content
    });
    setMessages((m) => [...m, res.data]);
    setContent("");
  }

  async function buyPremium() {
    const res = await api.post("/create-checkout-session");
    window.location.href = res.data.url;
  }

  async function markPremium() {
    await api.post("/mark-premium");
    const me = await api.get("/me");
    setUser(me.data);
  }

  if (!token) {
    return <AuthScreen onLogin={(u, p) => auth("/login", u, p)} onRegister={(u, p) => auth("/register", u, p)} />;
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, display: "grid", gap: 12 }}>
      <h2>Social Messaging MVP</h2>

      <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
        <div>Logged in as: <b>{user?.username}</b> {user?.premium ? "⭐ Premium" : ""}</div>
        <button onClick={buyPremium}>Unlock Premium $4.99</button>
        <button onClick={markPremium}>Mark Premium (dev)</button>
        <div>Unread: {unread}</div>
      </div>

      {notice && <div style={{ background: "#eef", padding: 8 }}>{notice}</div>}

      <div style={{ display: "grid", gridTemplateColumns: "220px 1fr", gap: 12 }}>
        <div style={{ border: "1px solid #ccc", padding: 8 }}>
          <h4>Users</h4>
          {users.map((u) => (
            <div key={u.id}>
              <button onClick={() => openChat(u)}>
                {u.username} {u.premium ? "⭐" : ""}
              </button>
            </div>
          ))}
        </div>

        <div style={{ border: "1px solid #ccc", padding: 8 }}>
          <h4>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h4>
          <div style={{ minHeight: 250, border: "1px solid #eee", padding: 8, marginBottom: 8 }}>
            {messages.map((m) => (
              <div key={m.id}>
                <b>{String(m.sender_id) === String(user?.id) ? "Me" : selectedUser?.username}:</b>{" "}
                {m.content}
              </div>
            ))}
          </div>

          <input
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message..."
            style={{ width: "80%" }}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}

function AuthScreen({ onLogin, onRegister }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20 }}>
      <h2>Login / Register</h2>
      <input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="username" />
      <br />
      <input value={password} onChange={(e) => setPassword(e.target.value)} placeholder="password" type="password" />
      <br />
      <button onClick={() => onLogin(username, password)}>Login</button>
      <button onClick={() => onRegister(username, password)}>Register</button>
    </div>
  );
}
