import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import { createServer } from "http";
import { Server } from "socket.io";
import db from "./db.js";
import { requireAuth, signToken } from "./auth.js";
import { stripe } from "./stripe.js";

dotenv.config();

const app = express();
const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use("/webhook", express.raw({ type: "application/json" }));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("auth", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

// Auth
app.post("/api/register", async (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) return res.status(400).json({ error: "Missing fields" });

  const hash = await bcrypt.hash(password, 10);
  try {
    const stmt = db.prepare("INSERT INTO users (email, password) VALUES (?, ?)");
    const result = stmt.run(email, hash);
    const user = db.prepare("SELECT id, email, plan FROM users WHERE id = ?").get(result.lastInsertRowid);
    const token = signToken(user);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Email already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = db.prepare("SELECT * FROM users WHERE email = ?").get(email);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const safeUser = { id: user.id, email: user.email, plan: user.plan };
  const token = signToken(safeUser);
  res.json({ token, user: safeUser });
});

app.get("/api/me", requireAuth, (req, res) => {
  const user = db.prepare("SELECT id, email, plan FROM users WHERE id = ?").get(req.user.id);
  res.json({ user });
});

// Users list
app.get("/api/users", requireAuth, (req, res) => {
  const users = db.prepare("SELECT id, email, plan FROM users WHERE id != ?").all(req.user.id);
  res.json({ users });
});

// Messages
app.get("/api/messages/:userId", requireAuth, (req, res) => {
  const otherId = Number(req.params.userId);
  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
  `).all(req.user.id, otherId, otherId, req.user.id);

  res.json({ messages });
});

app.post("/api/messages", requireAuth, (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const me = db.prepare("SELECT * FROM users WHERE id = ?").get(req.user.id);
  const countToday = db.prepare(`
    SELECT COUNT(*) as count FROM messages
    WHERE sender_id = ? AND date(created_at) = date('now')
  `).get(req.user.id).count;

  if (me.plan === "free" && countToday >= 20) {
    return res.status(402).json({ error: "Free limit reached. Upgrade to premium." });
  }

  const result = db.prepare(
    "INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)"
  ).run(req.user.id, receiverId, content);

  const message = db.prepare("SELECT * FROM messages WHERE id = ?").get(result.lastInsertRowid);

  const receiverSocketId = onlineUsers.get(String(receiverId));
  if (receiverSocketId) {
    io.to(receiverSocketId).emit("message:new", message);
    io.to(receiverSocketId).emit("notification", {
      type: "message",
      text: `New message from ${req.user.email}`
    });
  }

  res.json({ message });
});

app.post("/api/messages/:id/read", requireAuth, (req, res) => {
  db.prepare("UPDATE messages SET read_at = CURRENT_TIMESTAMP WHERE id = ? AND receiver_id = ?")
    .run(req.params.id, req.user.id);
  res.json({ ok: true });
});

app.get("/api/unread-count", requireAuth, (req, res) => {
  const unread = db.prepare(`
    SELECT COUNT(*) as count FROM messages
    WHERE receiver_id = ? AND read_at IS NULL
  `).get(req.user.id).count;
  res.json({ unread });
});

// Stripe checkout
app.post("/api/create-checkout-session", requireAuth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Messaging Plan" },
          unit_amount: 999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId: String(req.user.id) }
  });

  res.json({ url: session.url });
});

// Stripe webhook
app.post("/webhook", (req, res) => {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    db.prepare("UPDATE users SET plan = 'premium' WHERE id = ?").run(userId);
  }

  res.json({ received: true });
});

httpServer.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
