import React, { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [unread, setUnread] = useState(0);
  const [notif, setNotif] = useState("");

  const socket = useMemo(() => createSocket(), []);

  useEffect(() => {
    if (!token) return;
    api("/me", "GET", null, token).then(({ user }) => setUser(user));
    api("/users", "GET", null, token).then(({ users }) => setUsers(users));
    api("/unread-count", "GET", null, token).then(({ unread }) => setUnread(unread));
  }, [token]);

  useEffect(() => {
    if (!user) return;
    socket.emit("auth", user.id);

    socket.on("message:new", (msg) => {
      if (selectedUser && String(msg.sender_id) === String(selectedUser.id)) {
        setMessages((m) => [...m, msg]);
      }
      api("/unread-count", "GET", null, token).then(({ unread }) => setUnread(unread));
    });

    socket.on("notification", (n) => {
      setNotif(n.text);
      setTimeout(() => setNotif(""), 3000);
    });

    return () => {
      socket.off("message:new");
      socket.off("notification");
    };
  }, [user, selectedUser, socket, token]);

  async function handleAuth(type) {
    const data = await api(`/` + type, "POST", { email, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
  }

  async function openChat(u) {
    setSelectedUser(u);
    const { messages } = await api(`/messages/${u.id}`, "GET", null, token);
    setMessages(messages);
  }

  async function sendMessage() {
    const { message } = await api("/messages", "POST", {
      receiverId: selectedUser.id,
      content
    }, token);

    setMessages((m) => [...m, message]);
    setContent("");
  }

  async function upgrade() {
    const { url } = await api("/create-checkout-session", "POST", {}, token);
    window.location.href = url;
  }

  if (!token) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Social Messaging App</h1>
        <input placeholder="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <br />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <br />
        <button onClick={() => handleAuth("register")}>Register</button>
        <button onClick={() => handleAuth("login")}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 260, borderRight: "1px solid #ddd", padding: 16 }}>
        <h2>Inbox {unread > 0 ? `(${unread})` : ""}</h2>
        <p>{user?.email} — {user?.plan}</p>
        {user?.plan === "free" && <button onClick={upgrade}>Upgrade to Premium</button>}
        <hr />
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.email} {u.plan === "premium" ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        {notif && <div style={{ background: "#eef", padding: 8 }}>{notif}</div>}
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.email}</h2>
            <div style={{ height: "70vh", overflowY: "auto", border: "1px solid #ccc", padding: 12 }}>
              {messages.map((m) => (
                <div key={m.id} style={{ marginBottom: 8 }}>
                  <b>{String(m.sender_id) === String(user.id) ? "You" : selectedUser.email}:</b> {m.content}
                </div>
              ))}
            </div>
            <div style={{ marginTop: 12 }}>
              <input
                style={{ width: "70%" }}
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Type a message"
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <h3>Select a user to start chatting</h3>
        )}
      </div>
    </div>
  );
}
