```js
import "dotenv/config";
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { db } from "./db.js";
import { authMiddleware, signToken } from "./auth.js";
import { stripe } from "./stripe.js";

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL }
});

const onlineUsers = new Map(); // userId -> socketId

function emitNotification(userId, notification) {
  const socketId = onlineUsers.get(String(userId));
  if (socketId) {
    io.to(socketId).emit("notification", notification);
  }
}

async function createNotification(userId, type, content) {
  const result = await db.run(
    "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
    [userId, type, content]
  );
  const notification = {
    id: result.lastID,
    user_id: userId,
    type,
    content,
    read: 0,
    created_at: new Date().toISOString()
  };
  emitNotification(userId, notification);
  return notification;
}

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const hash = await bcrypt.hash(password, 10);
  try {
    const result = await db.run(
      "INSERT INTO users (username, password_hash, credits) VALUES (?, ?, 5)",
      [username, hash]
    );
    const user = { id: result.lastID, username };
    res.json({ token: signToken(user), user: { ...user, credits: 5 } });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/users", authMiddleware, async (req, res) => {
  const users = await db.all("SELECT id, username FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

app.get("/api/messages/:otherUserId", authMiddleware, async (req, res) => {
  const me = req.user.id;
  const other = Number(req.params.otherUserId);

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (sender_id = ? AND recipient_id = ?)
        OR (sender_id = ? AND recipient_id = ?)
     ORDER BY created_at ASC`,
    [me, other, other, me]
  );

  res.json(messages);
});

app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await db.all(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 20",
    [req.user.id]
  );
  res.json(notifications);
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { recipientId, content, premium = false } = req.body;
  if (!recipientId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = await db.get("SELECT * FROM users WHERE id = ?", [req.user.id]);
  if (!sender) return res.status(404).json({ error: "User not found" });

  if (premium) {
    if (sender.credits < 1) {
      return res.status(402).json({ error: "Not enough credits" });
    }
    await db.run("UPDATE users SET credits = credits - 1 WHERE id = ?", [sender.id]);
  }

  const result = await db.run(
    "INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)",
    [sender.id, recipientId, content]
  );

  const message = {
    id: result.lastID,
    sender_id: sender.id,
    recipient_id: recipientId,
    content,
    created_at: new Date().toISOString()
  };

  io.to(onlineUsers.get(String(recipientId)) || "").emit("message", message);

  await createNotification(
    recipientId,
    "message",
    `${sender.username} sent you a ${premium ? "premium " : ""}message`
  );

  res.json({ ok: true, message });
});

app.post("/api/stripe/create-checkout-session", authMiddleware, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "10 Credits" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId: String(req.user.id), credits: "10" }
  });

  res.json({ url: session.url });
});

app.post("/api/stripe/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // Minimal placeholder:
  // In production, verify Stripe signature here.
  res.sendStatus(200);
});

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
