      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [user, selectedUser]);

  useEffect(() => {
    if (!selectedUser) return;
    api.get(`/messages/${selectedUser.id}`).then(({ data }) => setMessages(data));
  }, [selectedUser]);

  async function register(e) {
    e.preventDefault();
    const { data } = await api.post("/register", auth);
    localStorage.setItem("token", data.token);
    setLocalToken(data.token);
    setUser(data.user);
  }

  async function login(e) {
    e.preventDefault();
    const { data } = await api.post("/login", auth);
    localStorage.setItem("token", data.token);
    setLocalToken(data.token);
    setUser(data.user);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const { data } = await api.post("/messages", {
      recipientId: selectedUser.id,
      content,
      premium
    });
    setMessages((prev) => [...prev, data.message]);
    setContent("");
  }

  async function buyCredits() {
    const { data } = await api.post("/stripe/create-checkout-session");
    window.location.href = data.url;
  }

  if (!user) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Messaging App</h1>
        <form>
          <input
            placeholder="username"
            value={auth.username}
            onChange={(e) => setAuth({ ...auth, username: e.target.value })}
          />
          <input
            placeholder="password"
            type="password"
            value={auth.password}
            onChange={(e) => setAuth({ ...auth, password: e.target.value })}
          />
          <div style={{ marginTop: 8 }}>
            <button onClick={register}>Register</button>
            <button onClick={login} type="button">Login</button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "240px 1fr 280px", height: "100vh" }}>
      <aside style={{ padding: 16, borderRight: "1px solid #ddd" }}>
        <h3>{user.username}</h3>
        <p>Credits: {user.credits}</p>
        <button onClick={buyCredits}>Buy 10 Credits</button>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => setSelectedUser(u)}>{u.username}</button>
          </div>
        ))}
      </aside>

      <main style={{ padding: 16 }}>
        <h2>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h2>
        <div style={{ minHeight: 400, border: "1px solid #ddd", padding: 12, marginBottom: 12 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.sender_id === user.id ? "You" : selectedUser?.username}:</b> {m.content}
            </div>
          ))}
        </div>

        <label>
          <input
            type="checkbox"
            checked={premium}
            onChange={(e) => setPremium(e.target.checked)}
          />
          Premium message (costs 1 credit)
        </label>

        <div style={{ marginTop: 8 }}>
          <input
            style={{ width: "70%" }}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>

      <aside style={{ padding: 16, borderLeft: "1px solid #ddd" }}>
        <h3>Notifications</h3>
        {notifications.map((n) => (
          <div key={n.id} style={{ marginBottom: 8, padding: 8, border: "1px solid #eee" }}>
            {n.content}
          </div>
        ))}
      </aside>
    </div>
  );
}
