## `server/index.js`
```js
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import http from "http";
import { Server } from "socket.io";
import { db } from "./db.js";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = 3001;
const JWT_SECRET = "dev_secret_change_me";

app.use(cors());
app.use(express.json());

function auth(req, res, next) {
  const header = req.headers.authorization || "";
  const token = header.startsWith("Bearer ") ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: "No token" });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function createNotification(userId, type, content) {
  const stmt = db.prepare(
    "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)"
  );
  const info = stmt.run(userId, type, content);
  const notification = db
    .prepare("SELECT * FROM notifications WHERE id = ?")
    .get(info.lastInsertRowid);

  io.to(`user:${userId}`).emit("notification", notification);
  return notification;
}

// Register
app.post("/api/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const existing = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (existing) return res.status(400).json({ error: "Username taken" });

  const hash = bcrypt.hashSync(password, 10);
  const info = db
    .prepare("INSERT INTO users (username, password_hash) VALUES (?, ?)")
    .run(username, hash);

  const user = db.prepare("SELECT id, username, credits, premium FROM users WHERE id = ?").get(info.lastInsertRowid);
  const token = jwt.sign(user, JWT_SECRET, { expiresIn: "7d" });

  res.json({ token, user });
});

// Login
app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  const user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = bcrypt.compareSync(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const safeUser = { id: user.id, username: user.username, credits: user.credits, premium: user.premium };
  const token = jwt.sign(safeUser, JWT_SECRET, { expiresIn: "7d" });

  res.json({ token, user: safeUser });
});

// Me
app.get("/api/me", auth, (req, res) => {
  const user = db.prepare("SELECT id, username, credits, premium FROM users WHERE id = ?").get(req.user.id);
  res.json({ user });
});

// Search users
app.get("/api/users", auth, (req, res) => {
  const users = db.prepare(
    "SELECT id, username, credits, premium FROM users WHERE id != ? ORDER BY username"
  ).all(req.user.id);
  res.json({ users });
});

// Get conversation
app.get("/api/messages/:otherUserId", auth, (req, res) => {
  const otherUserId = Number(req.params.otherUserId);
  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
  `).all(req.user.id, otherUserId, otherUserId, req.user.id);

  res.json({ messages });
});

// Send message
app.post("/api/messages", auth, (req, res) => {
  const { receiverId, content, premium = false } = req.body;
  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = db.prepare("SELECT * FROM users WHERE id = ?").get(req.user.id);
  const receiver = db.prepare("SELECT * FROM users WHERE id = ?").get(receiverId);
  if (!receiver) return res.status(404).json({ error: "Receiver not found" });

  // Premium message costs 1 credit
  if (premium) {
    if (sender.credits < 1) return res.status(402).json({ error: "Not enough credits" });
    db.prepare("UPDATE users SET credits = credits - 1 WHERE id = ?").run(sender.id);
  }

  const info = db.prepare(
    "INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)"
  ).run(sender.id, receiver.id, content);

  const message = db.prepare("SELECT * FROM messages WHERE id = ?").get(info.lastInsertRowid);

  io.to(`user:${receiver.id}`).emit("message", message);
  createNotification(receiver.id, "message", `New message from ${sender.username}`);

  res.json({ message });
});

// Notifications
app.get("/api/notifications", auth, (req, res) => {
  const notifications = db.prepare(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 50"
  ).all(req.user.id);

  res.json({ notifications });
});

app.post("/api/notifications/:id/read", auth, (req, res) => {
  db.prepare("UPDATE notifications SET read = 1 WHERE id = ? AND user_id = ?")
    .run(req.params.id, req.user.id);
  res.json({ ok: true });
});

// Buy credits (mock monetization)
app.post("/api/buy-credits", auth, (req, res) => {
  const { amount = 10 } = req.body;

  // Mock payment success
  db.prepare("UPDATE users SET credits = credits + ? WHERE id = ?").run(amount, req.user.id);

  createNotification(req.user.id, "payment", `You purchased ${amount} credits`);
  const user = db.prepare("SELECT id, username, credits, premium FROM users WHERE id = ?").get(req.user.id);

  res.json({ user });
});

// Unlock premium
app.post("/api/unlock-premium", auth, (req, res) => {
  const user = db.prepare("SELECT * FROM users WHERE id = ?").get(req.user.id);
  if (user.credits < 5) return res.status(402).json({ error: "Need 5 credits" });

  db.prepare("UPDATE users SET credits = credits - 5, premium = 1 WHERE id = ?").run(user.id);
  createNotification(user.id, "premium", "Premium unlocked!");
  const updated = db.prepare("SELECT id, username, credits, premium FROM users WHERE id = ?").get(user.id);

  res.json({ user: updated });
});

// Socket auth + rooms
io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

