import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { request } from "./api.js";

const socket = io("http://localhost:3001");

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [content, setContent] = useState("");
  const [premium, setPremium] = useState(false);
  const [error, setError] = useState("");

  async function loadMe(t = token) {
    const data = await request("/me", "GET", null, t);
    setUser(data.user);
    socket.emit("join", data.user.id);
  }

  async function loadUsers(t = token) {
    const data = await request("/users", "GET", null, t);
    setUsers(data.users);
  }

  async function loadNotifications(t = token) {
    const data = await request("/notifications", "GET", null, t);
    setNotifications(data.notifications);
  }

  useEffect(() => {
    if (!token) return;
    loadMe().then(loadUsers).then(loadNotifications).catch(() => {});
  }, [token]);

  useEffect(() => {
    socket.on("message", (msg) => {
      if (selectedUser && msg.sender_id === selectedUser.id) {
        setMessages((m) => [...m, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [selectedUser]);

  async function handleAuth() {
    setError("");
    try {
      const path = authMode === "login" ? "/login" : "/register";
      const data = await request(path, "POST", { username, password });
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
      socket.emit("join", data.user.id);
      await loadUsers(data.token);
      await loadNotifications(data.token);
    } catch (e) {
      setError(e.message);
    }
  }

  async function selectUser(u) {
    setSelectedUser(u);
    const data = await request(`/messages/${u.id}`, "GET", null, token);
    setMessages(data.messages);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    try {
      const data = await request(
        "/messages",
        "POST",
        { receiverId: selectedUser.id, content, premium },
        token
      );
      setMessages((prev) => [...prev, data.message]);
      setContent("");
    } catch (e) {
      setError(e.message);
    }
  }

  async function buyCredits() {
    const data = await request("/buy-credits", "POST", { amount: 10 }, token);
    setUser(data.user);
    await loadMe();
  }

  async function unlockPremium() {
    try {
      const data = await request("/unlock-premium", "POST", {}, token);
      setUser(data.user);
      await loadMe();
    } catch (e) {
      setError(e.message);
    }
  }

  if (!token || !user) {
    return (
      <div style={{ padding: 24, fontFamily: "sans-serif" }}>
        <h2>Social Messaging MVP</h2>
        <div>
          <button onClick={() => setAuthMode("login")}>Login</button>
          <button onClick={() => setAuthMode("register")}>Register</button>
        </div>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <button onClick={handleAuth}>{authMode}</button>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "240px 1fr 260px", height: "100vh", fontFamily: "sans-serif" }}>
      <aside style={{ padding: 16, borderRight: "1px solid #ddd" }}>
        <h3>{user.username}</h3>
        <p>Credits: {user.credits}</p>
        <p>Premium: {user.premium ? "Yes" : "No"}</p>
        <button onClick={buyCredits}>Buy 10 Credits</button>
        <button onClick={unlockPremium} style={{ marginLeft: 8 }}>Unlock Premium (5)</button>
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => selectUser(u)}>
              {u.username} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </aside>

      <main style={{ padding: 16 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h3>
        <div style={{ border: "1px solid #ddd", height: "75vh", overflow: "auto", padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id} style={{ marginBottom: 8 }}>
              <b>{m.sender_id === user.id ? "You" : selectedUser?.username}:</b> {m.content}
              {m.id && <small style={{ marginLeft: 8, color: "#777" }}>{m.created_at}</small>}
            </div>
          ))}
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            style={{ width: "70%" }}
            placeholder={premium ? "Premium message..." : "Message..."}
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
          <label style={{ marginLeft: 8 }}>
            <input type="checkbox" checked={premium} onChange={(e) => setPremium(e.target.checked)} />
            Premium (1 credit)
          </label>
          <button onClick={sendMessage}>Send</button>
        </div>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </main>

      <aside style={{ padding: 16, borderLeft: "1px solid #ddd" }}>
        <h4>Notifications</h4>
        {notifications.map((n) => (
          <div key={n.id} style={{ borderBottom: "1px solid #eee", padding: "8px 0" }}>
            <b>{n.type}</b>
            <div>{n.content}</div>
            <small>{n.read ? "Read" : "Unread"}</small>
          </div>
        ))}
      </aside>
    </div>
  );
}
