## `server/src/socket.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { db } from "./db.js";

export function setupSocket(httpServer) {
  const io = new Server(httpServer, {
    cors: { origin: process.env.CLIENT_URL, credentials: true }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("No token"));
    try {
      socket.user = jwt.verify(token, process.env.JWT_SECRET);
      next();
    } catch {
      next(new Error("Invalid token"));
    }
  });

  io.on("connection", async (socket) => {
    socket.join(`user:${socket.user.id}`);

    socket.on("joinChat", (chatId) => {
      socket.join(`chat:${chatId}`);
    });

    socket.on("sendMessage", async ({ chatId, content, boosted = false }) => {
      const result = await db.run(
        `INSERT INTO messages (chat_id, user_id, content, boosted) VALUES (?, ?, ?, ?)`,
        [chatId, socket.user.id, content, boosted ? 1 : 0]
      );

      const message = await db.get(
        `SELECT m.*, u.username FROM messages m JOIN users u ON u.id = m.user_id WHERE m.id = ?`,
        [result.lastID]
      );

      io.to(`chat:${chatId}`).emit("newMessage", message);

      // Notify all members except sender
      const members = await db.all(
        `SELECT user_id FROM chat_members WHERE chat_id = ?`,
        [chatId]
      );

      for (const member of members) {
        if (member.user_id !== socket.user.id) {
          io.to(`user:${member.user_id}`).emit("notification", {
            type: "message",
            chatId,
            message: `New message from ${message.username}`
          });
        }
      }
    });
  });

  return io;
}
```

