## `server/src/routes.js`

```js
import express from "express";
import bcrypt from "bcryptjs";
import { db } from "./db.js";
import { signToken, requireAuth } from "./auth.js";
import { stripe } from "./stripe.js";

export const router = express.Router();

router.post("/auth/register", async (req, res) => {
  const { username, password } = req.body;
  const hashed = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      `INSERT INTO users (username, password) VALUES (?, ?)`,
      [username, hashed]
    );
    const user = { id: result.lastID, username };
    res.json({ token: signToken(user), user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

router.post("/auth/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get(`SELECT * FROM users WHERE username = ?`, [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username, coins: user.coins, premium: user.premium }
  });
});

router.get("/me", requireAuth, async (req, res) => {
  const user = await db.get(
    `SELECT id, username, coins, premium FROM users WHERE id = ?`,
    [req.user.id]
  );
  res.json(user);
});

router.get("/chats", requireAuth, async (req, res) => {
  const chats = await db.all(
    `SELECT c.* FROM chats c
     JOIN chat_members cm ON cm.chat_id = c.id
     WHERE cm.user_id = ?`,
    [req.user.id]
  );
  res.json(chats);
});

router.post("/chats", requireAuth, async (req, res) => {
  const { name, memberIds = [] } = req.body;
  const result = await db.run(`INSERT INTO chats (name) VALUES (?)`, [name]);
  const chatId = result.lastID;

  await db.run(`INSERT INTO chat_members (chat_id, user_id) VALUES (?, ?)`, [
    chatId,
    req.user.id
  ]);

  for (const id of memberIds) {
    await db.run(`INSERT INTO chat_members (chat_id, user_id) VALUES (?, ?)`, [
      chatId,
      id
    ]);
  }

  res.json({ id: chatId, name });
});

router.get("/messages/:chatId", requireAuth, async (req, res) => {
  const messages = await db.all(
    `SELECT m.*, u.username
     FROM messages m
     JOIN users u ON u.id = m.user_id
     WHERE m.chat_id = ?
     ORDER BY m.created_at ASC`,
    [req.params.chatId]
  );
  res.json(messages);
});

router.post("/premium/checkout", requireAuth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/wallet?cancel=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "100 Coins" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    metadata: { userId: String(req.user.id), coins: "100" }
  });

  res.json({ url: session.url });
});

router.post(
  "/stripe/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = Number(session.metadata.userId);
      const coins = Number(session.metadata.coins || 0);

      await db.run(
        `UPDATE users SET coins = coins + ? WHERE id = ?`,
        [coins, userId]
      );
    }

    res.json({ received: true });
  }
);
```

