## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api, setToken } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setLocalToken] = useState(localStorage.getItem("token"));
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [chats, setChats] = useState([]);
  const [messages, setMessages] = useState([]);
  const [chatId, setChatId] = useState("");
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!token) return;
    setToken(token);
    api.get("/me").then(r => setUser(r.data));
    api.get("/chats").then(r => setChats(r.data));

    const s = createSocket(token);
    setSocket(s);

    s.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    s.on("newMessage", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => s.disconnect();
  }, [token]);

  const register = async () => {
    const username = prompt("Username");
    const password = prompt("Password");
    const res = await api.post("/auth/register", { username, password });
    localStorage.setItem("token", res.data.token);
    setLocalToken(res.data.token);
  };

  const login = async () => {
    const username = prompt("Username");
    const password = prompt("Password");
    const res = await api.post("/auth/login", { username, password });
    localStorage.setItem("token", res.data.token);
    setLocalToken(res.data.token);
  };

  const loadChat = async (id) => {
    setChatId(id);
    const res = await api.get(`/messages/${id}`);
    setMessages(res.data);
    socket?.emit("joinChat", id);
  };

  const send = () => {
    socket?.emit("sendMessage", { chatId, content });
    setContent("");
  };

  const buyCoins = async () => {
    const res = await api.post("/premium/checkout");
    window.location.href = res.data.url;
  };

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Messaging App</h1>
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "200px 1fr 250px", height: "100vh" }}>
      <div style={{ borderRight: "1px solid #ccc", padding: 10 }}>
        <h3>Chats</h3>
        {chats.map((c) => (
          <div key={c.id}>
            <button onClick={() => loadChat(c.id)}>{c.name}</button>
          </div>
        ))}
        <button
          onClick={async () => {
            const name = prompt("Chat name");
            await api.post("/chats", { name });
            const res = await api.get("/chats");
            setChats(res.data);
          }}
        >
          + New Chat
        </button>
      </div>

      <div style={{ padding: 10 }}>
        <h3>Chat {chatId}</h3>
        <div style={{ minHeight: 400, border: "1px solid #ddd", padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.username}:</b> {m.content} {m.boosted ? "⭐" : ""}
            </div>
          ))}
        </div>
        <input value={content} onChange={(e) => setContent(e.target.value)} />
        <button onClick={send}>Send</button>
      </div>

      <div style={{ borderLeft: "1px solid #ccc", padding: 10 }}>
        <h3>Wallet</h3>
        <div>Coins: {user?.coins}</div>
        <div>Premium: {user?.premium ? "Yes" : "No"}</div>
        <button onClick={buyCoins}>Buy 100 Coins</button>

        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i}>{n.message}</div>
        ))}
      </div>
    </div>
  );
}
```

