  id           String         @id @default(cuid())
  email        String         @unique
  name         String?
  passwordHash String
  isPremium    Boolean        @default(false)
  createdAt    DateTime       @default(now())
  messagesSent Message[]      @relation("sentMessages")
  messagesRecv Message[]      @relation("recvMessages")
