# 12) Chat UI

## `frontend/components/ChatBox.tsx`

```tsx
"use client";

import { useEffect, useState } from "react";
import { api } from "../lib/api";
import { createSocket } from "../lib/socket";

export default function ChatBox({ userId, otherUserId }: { userId: string; otherUserId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api(`/messages/${userId}/${otherUserId}`).then(setMessages);
  }, [userId, otherUserId]);

  useEffect(() => {
    const socket = createSocket(userId);
    socket.on("message:new", (msg) => {
      if (
        (msg.senderId === userId && msg.receiverId === otherUserId) ||
        (msg.senderId === otherUserId && msg.receiverId === userId)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.disconnect();
    };
  }, [userId, otherUserId]);

  async function sendMessage() {
    const msg = await api("/messages", {
      method: "POST",
      body: JSON.stringify({ senderId: userId, receiverId: otherUserId, content })
    });

    setMessages((prev) => [...prev, msg.message]);
    setContent("");
  }

  return (
    <div>
      <div style={{ border: "1px solid #ccc", padding: 12, minHeight: 200 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === userId ? "Me" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
```

