## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import { db } from "./db.js";
import { signToken, verifyToken, hashPassword, comparePassword } from "./auth.js";
import { stripe } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    credentials: true
  }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("send_message", async ({ senderId, receiverId, content }) => {
    const result = await db.run(
      "INSERT INTO messages (senderId, receiverId, content) VALUES (?, ?, ?)",
      [senderId, receiverId, content]
    );

    const message = {
      id: result.lastID,
      senderId,
      receiverId,
      content,
      createdAt: new Date().toISOString()
    };

    const receiverSocketId = onlineUsers.get(String(receiverId));
    if (receiverSocketId) {
      io.to(receiverSocketId).emit("new_message", message);
      io.to(receiverSocketId).emit("notification", {
        type: "message",
        text: `New message from user ${senderId}`
      });
    }

    socket.emit("message_sent", message);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

app.post("/auth/register", async (req, res) => {
  const { email, password, name } = req.body;
  const hashed = await hashPassword(password);

  try {
    const result = await db.run(
      "INSERT INTO users (email, password, name) VALUES (?, ?, ?)",
      [email, hashed, name]
    );
    const user = { id: result.lastID, email, name, premium: 0 };
    res.json({ token: signToken(user), user });
  } catch (e) {
    res.status(400).json({ error: "User already exists" });
  }
});

app.post("/auth/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE email = ?", [email]);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await comparePassword(password, user.password);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, email: user.email, name: user.name, premium: user.premium }
  });
});

app.get("/users", verifyToken, async (req, res) => {
  const users = await db.all("SELECT id, email, name, premium FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

app.get("/messages/:otherUserId", verifyToken, async (req, res) => {
  const userId = req.user.id;
  const otherUserId = Number(req.params.otherUserId);

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (senderId = ? AND receiverId = ?)
        OR (senderId = ? AND receiverId = ?)
     ORDER BY createdAt ASC`,
    [userId, otherUserId, otherUserId, userId]
  );

  res.json(messages);
});

app.post("/checkout", verifyToken, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Upgrade" },
          unit_amount: 999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId: String(req.user.id) }
  });

  await db.run(
    "INSERT INTO payments (userId, stripeSessionId, status) VALUES (?, ?, ?)",
    [req.user.id, session.id, "pending"]
  );

  res.json({ url: session.url });
});

app.post(
  "/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = Number(session.metadata.userId);

      await db.run("UPDATE users SET premium = 1 WHERE id = ?", [userId]);
      await db.run("UPDATE payments SET status = 'paid' WHERE stripeSessionId = ?", [session.id]);
    }

    res.json({ received: true });
  }
);

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
```

