## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api, setToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [form, setForm] = useState({ email: "", password: "", name: "" });
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const saved = localStorage.getItem("token");
    const savedUser = localStorage.getItem("user");
    if (saved && savedUser) {
      setToken(saved);
      const u = JSON.parse(savedUser);
      setUser(u);
      connectSocket(u.id);
      loadUsers();
    }
  }, []);

  useEffect(() => {
    socket.on("new_message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, [selectedUser]);

  async function connectSocket(userId) {
    socket.connect();
    socket.emit("join", userId);
  }

  async function loadUsers() {
    const { data } = await api.get("/users");
    setUsers(data);
  }

  async function handleAuth(e) {
    e.preventDefault();
    const url = authMode === "login" ? "/auth/login" : "/auth/register";
    const payload = authMode === "login"
      ? { email: form.email, password: form.password }
      : { email: form.email, password: form.password, name: form.name };

    const { data } = await api.post(url, payload);
    localStorage.setItem("token", data.token);
    localStorage.setItem("user", JSON.stringify(data.user));
    setToken(data.token);
    setUser(data.user);
    connectSocket(data.user.id);
    loadUsers();
  }

  async function openChat(u) {
    setSelectedUser(u);
    const { data } = await api.get(`/messages/${u.id}`);
    setMessages(data);
  }

  async function sendMessage() {
    if (!message.trim() || !selectedUser) return;
    socket.emit("send_message", {
      senderId: user.id,
      receiverId: selectedUser.id,
      content: message
    });
    setMessage("");
    const { data } = await api.get(`/messages/${selectedUser.id}`);
    setMessages(data);
  }

  async function upgrade() {
    const { data } = await api.post("/checkout");
    window.location.href = data.url;
  }

  if (!user) {
    return (
      <div className="container">
        <h1>Social Messaging MVP</h1>
        <form onSubmit={handleAuth} className="card">
          {authMode === "register" && (
            <input
              placeholder="Name"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
          )}
          <input
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />
          <input
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />
          <button type="submit">{authMode}</button>
