            Switch to {authMode === "login" ? "register" : "login"}
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="container layout">
      <aside className="sidebar">
        <h2>{user.name} {user.premium ? "⭐" : ""}</h2>
        <button onClick={upgrade}>Upgrade Premium</button>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id} className="user" onClick={() => openChat(u)}>
            {u.name} {u.premium ? "⭐" : ""}
          </div>
        ))}
      </aside>

      <main className="chat">
        <h2>{selectedUser ? `Chat with ${selectedUser.name}` : "Select a user"}</h2>

        <div className="notifications">
          {notifications.slice(0, 3).map((n, i) => (
            <div key={i} className="notification">{n.text}</div>
          ))}
        </div>

        <div className="messages">
          {messages.map((m) => (
            <div key={m.id} className={m.senderId === user.id ? "msg me" : "msg"}>
              {m.content}
            </div>
          ))}
        </div>

        <div className="composer">
          <input
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type a message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>
    </div>
  );
}
