## `server/src/routes.js`

```js
import bcrypt from "bcryptjs";
import { signToken, requireAuth } from "./auth.js";

export function createRoutes({ app, prisma, jwtSecret, io }) {
  const auth = requireAuth(jwtSecret);

  app.post("/api/register", async (req, res) => {
    const { username, password } = req.body;
    if (!username || !password) return res.status(400).json({ error: "Missing fields" });

    const existing = await prisma.user.findUnique({ where: { username } });
    if (existing) return res.status(400).json({ error: "Username taken" });

    const passwordHash = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: { username, passwordHash },
    });

    const token = signToken(user, jwtSecret);
    res.json({ token, user: { id: user.id, username: user.username, credits: user.credits } });
  });

  app.post("/api/login", async (req, res) => {
    const { username, password } = req.body;
    const user = await prisma.user.findUnique({ where: { username } });
    if (!user) return res.status(400).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.passwordHash);
    if (!ok) return res.status(400).json({ error: "Invalid credentials" });

    const token = signToken(user, jwtSecret);
    res.json({ token, user: { id: user.id, username: user.username, credits: user.credits } });
  });

  app.get("/api/me", auth, async (req, res) => {
    const user = await prisma.user.findUnique({
      where: { id: req.user.sub },
      select: { id: true, username: true, credits: true },
    });
    res.json(user);
  });

  app.get("/api/users", auth, async (req, res) => {
    const users = await prisma.user.findMany({
      select: { id: true, username: true, credits: true },
      orderBy: { createdAt: "asc" },
    });
    res.json(users.filter(u => u.id !== req.user.sub));
  });

  app.get("/api/messages/:userId", auth, async (req, res) => {
    const me = req.user.sub;
    const other = req.params.userId;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: me, receiverId: other },
          { senderId: other, receiverId: me },
        ],
      },
      orderBy: { createdAt: "asc" },
    });

    res.json(messages);
  });

  app.get("/api/notifications", auth, async (req, res) => {
    const notifications = await prisma.notification.findMany({
      where: { userId: req.user.sub },
      orderBy: { createdAt: "desc" },
    });
    res.json(notifications);
  });

  app.post("/api/notifications/read", auth, async (req, res) => {
    await prisma.notification.updateMany({
      where: { userId: req.user.sub, isRead: false },
      data: { isRead: true },
    });
    res.json({ ok: true });
  });

  app.post("/api/topup", auth, async (req, res) => {
    const { amount = 10 } = req.body;
    const user = await prisma.user.update({
      where: { id: req.user.sub },
      data: { credits: { increment: amount } },
      select: { id: true, username: true, credits: true },
    });

    await prisma.notification.create({
      data: {
        userId: user.id,
        type: "topup",
        text: `You received ${amount} credits.`,
      },
    });

    io.to(user.id).emit("notification", {
      type: "topup",
      text: `You received ${amount} credits.`,
    });

    res.json(user);
  });

  app.post("/api/messages", auth, async (req, res) => {
    const { receiverId, content, isPriority = false } = req.body;
    if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

    const sender = await prisma.user.findUnique({ where: { id: req.user.sub } });
    if (!sender) return res.status(404).json({ error: "Sender not found" });

    if (isPriority && sender.credits < 1) {
      return res.status(400).json({ error: "Not enough credits" });
    }

    const message = await prisma.$transaction(async (tx) => {
      if (isPriority) {
        await tx.user.update({
          where: { id: sender.id },
          data: { credits: { decrement: 1 } },
        });
      }

      const msg = await tx.message.create({
        data: {
          senderId: sender.id,
          receiverId,
          content,
          isPriority,
        },
      });

      await tx.notification.create({
        data: {
          userId: receiverId,
          type: "message",
          text: `${sender.username} sent you a${isPriority ? " priority" : ""} message.`,
        },
      });

      return msg;
    });

    io.to(receiverId).emit("message", message);
    io.to(receiverId).emit("notification", {
      type: "message",
      text: `${sender.username} sent you a${isPriority ? " priority" : ""} message.`,
    });

    res.json(message);
  });
}
```

