## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [content, setContent] = useState("");
  const [priority, setPriority] = useState(false);
  const [error, setError] = useState("");

  async function loadAll(tk) {
    const meData = await api("/me", "GET", null, tk);
    setMe(meData);
    const u = await api("/users", "GET", null, tk);
    setUsers(u);
    const n = await api("/notifications", "GET", null, tk);
    setNotifications(n);
  }

  useEffect(() => {
    if (token) {
      loadAll(token).catch(e => setError(e.message));
    }
  }, [token]);

  useEffect(() => {
    if (!me) return;
    socket.emit("join", me.id);

    socket.on("message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages((m) => [...m, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [{ id: crypto.randomUUID(), ...n, isRead: false }, ...prev]);
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [me, selectedUser]);

  async function handleAuth(e) {
    e.preventDefault();
    setError("");
    try {
      const data = await api(`/${authMode}`, "POST", { username, password });
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setMe(data.user);
    } catch (e) {
      setError(e.message);
    }
  }

  async function openChat(user) {
    setSelectedUser(user);
    const msgs = await api(`/messages/${user.id}`, "GET", null, token);
    setMessages(msgs);
  }

  async function sendMessage() {
    if (!selectedUser || !content) return;
    try {
      const msg = await api("/messages", "POST", {
        receiverId: selectedUser.id,
        content,
        isPriority: priority,
      }, token);
      setMessages((m) => [...m, msg]);
      setContent("");
    } catch (e) {
      setError(e.message);
    }
  }

  async function topUp() {
    try {
      const updated = await api("/topup", "POST", { amount: 10 }, token);
      setMe(updated);
      loadAll(token);
    } catch (e) {
      setError(e.message);
    }
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Social Messaging MVP</h1>
        <form onSubmit={handleAuth}>
          <select value={authMode} onChange={(e) => setAuthMode(e.target.value)}>
            <option value="login">Login</option>
            <option value="register">Register</option>
          </select>
          <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
          <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
          <button type="submit">{authMode}</button>
        </form>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "240px 1fr 280px", gap: 16, padding: 20 }}>
      <div>
        <h2>{me?.username}</h2>
        <p>Credits: {me?.credits}</p>
        <button onClick={topUp}>Buy 10 Credits</button>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.username} ({u.credits} cr)
            </button>
          </div>
        ))}
      </div>

      <div>
        <h2>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h2>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === me.id ? "You" : selectedUser?.username}:</b> {m.content}
              {m.isPriority && " ⭐"}
            </div>
          ))}
        </div>
        <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Message..." />
        <label>
          <input type="checkbox" checked={priority} onChange={(e) => setPriority(e.target.checked)} />
          Priority (1 credit)
        </label>
        <button onClick={sendMessage}>Send</button>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>

      <div>
        <h2>Notifications</h2>
        {notifications.map((n) => (
          <div key={n.id} style={{ marginBottom: 8, opacity: n.isRead ? 0.6 : 1 }}>
            {n.text}
          </div>
        ))}
      </div>
    </div>
  );
}
```

