## `server/index.js`
```js
require("dotenv").config();

const express = require("express");
const cors = require("cors");
const http = require("http");
const { Server } = require("socket.io");
const { PrismaClient } = require("@prisma/client");
const stripe = require("./stripe");

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use(express.json());

// --- Mock auth helper ---
async function getOrCreateUser(email, name) {
  return prisma.user.upsert({
    where: { email },
    update: { name: name || undefined },
    create: { email, name }
  });
}

// --- Create/login user ---
app.post("/api/auth", async (req, res) => {
  try {
    const { email, name } = req.body;
    if (!email) return res.status(400).json({ error: "Email required" });

    const user = await getOrCreateUser(email, name);
    res.json(user);
  } catch (err) {
    res.status(500).json({ error: "Auth failed" });
  }
});

// --- Get rooms ---
app.get("/api/rooms", async (req, res) => {
  const rooms = await prisma.room.findMany({ orderBy: { createdAt: "desc" } });
  res.json(rooms);
});

// --- Create room ---
app.post("/api/rooms", async (req, res) => {
  try {
    const { name } = req.body;
    if (!name) return res.status(400).json({ error: "Room name required" });

    const room = await prisma.room.create({ data: { name } });
    res.json(room);
  } catch (err) {
    res.status(500).json({ error: "Could not create room" });
  }
});

// --- Get messages by room ---
app.get("/api/rooms/:roomId/messages", async (req, res) => {
  const { roomId } = req.params;
  const messages = await prisma.message.findMany({
    where: { roomId },
    include: { user: true },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

// --- Get notifications by user ---
app.get("/api/users/:userId/notifications", async (req, res) => {
  const { userId } = req.params;
  const notifications = await prisma.notification.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

// --- Mark notification read ---
app.post("/api/notifications/:id/read", async (req, res) => {
  const { id } = req.params;
  const notif = await prisma.notification.update({
    where: { id },
    data: { read: true }
  });
  res.json(notif);
});

// --- Stripe checkout ---
app.post("/api/checkout", async (req, res) => {
  try {
    const { userId } = req.body;

    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) return res.status(404).json({ error: "User not found" });

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price: process.env.STRIPE_PRICE_ID,
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}?success=1`,
      cancel_url: `${process.env.CLIENT_URL}?canceled=1`,
      metadata: { userId }
    });

    res.json({ url: session.url });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "Checkout failed" });
  }
});

// --- Stripe webhook ---
app.post(
  "/api/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await prisma.user.update({
        where: { id: userId },
        data: { premium: true }
      });

      await prisma.notification.create({
        data: {
          userId,
          type: "payment",
          text: "Thanks for upgrading to Premium!"
        }
      });

      io.to(userId).emit("notification", {
        type: "payment",
        text: "Thanks for upgrading to Premium!"
      });
    }

    res.json({ received: true });
  }
);

// --- Socket.IO ---
io.on("connection", (socket) => {
  socket.on("join_user", (userId) => {
    socket.join(userId);
  });

  socket.on("join_room", (roomId) => {
    socket.join(roomId);
  });

  socket.on("send_message", async ({ content, userId, roomId }) => {
    if (!content || !userId || !roomId) return;

    const message = await prisma.message.create({
      data: { content, userId, roomId },
      include: { user: true }
    });

    io.to(roomId).emit("new_message", message);

    // Create notifications for users in same room (minimal: all users except sender)
    const users = await prisma.user.findMany({
      where: { id: { not: userId } }
    });

    for (const u of users) {
      const notif = await prisma.notification.create({
        data: {
          userId: u.id,
          type: "message",
          text: `New message in room ${roomId}`
        }
      });
      io.to(u.id).emit("notification", notif);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

