## `client/components/Chat.jsx`
```jsx
"use client";

import { useEffect, useState } from "react";
import axios from "axios";
import socket from "../lib/socket";

const SERVER = process.env.NEXT_PUBLIC_SERVER_URL || "http://localhost:4000";

export default function Chat({ room, user }) {
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    axios.get(`${SERVER}/api/rooms/${room.id}/messages`).then((res) => setMessages(res.data));

    const onMessage = (msg) => {
      if (msg.roomId === room.id) setMessages((prev) => [...prev, msg]);
    };

    socket.on("new_message", onMessage);
    return () => socket.off("new_message", onMessage);
  }, [room.id]);

  const send = () => {
    if (!text.trim()) return;
    socket.emit("send_message", {
      content: text,
      userId: user.id,
      roomId: room.id
    });
    setText("");
  };

  return (
    <div>
      <h2>{room.name}</h2>
      <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 12 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.user?.name || m.user?.email}:</strong> {m.content}
          </div>
        ))}
      </div>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Type a message" />
      <button onClick={send}>Send</button>
    </div>
  );
}
