## `client/components/Notifications.jsx`
```jsx
"use client";

import { useEffect, useState } from "react";
import axios from "axios";
import socket from "../lib/socket";

const SERVER = process.env.NEXT_PUBLIC_SERVER_URL || "http://localhost:4000";

export default function Notifications({ user }) {
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    axios.get(`${SERVER}/api/users/${user.id}/notifications`).then((res) => setNotifications(res.data));

    const onNotif = (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    };

    socket.on("notification", onNotif);
    return () => socket.off("notification", onNotif);
  }, [user.id]);

  const markRead = async (id) => {
    await axios.post(`${SERVER}/api/notifications/${id}/read`);
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
  };

  return (
    <div>
      <h3>Notifications</h3>
      {notifications.map((n) => (
        <div key={n.id} style={{ opacity: n.read ? 0.5 : 1 }}>
          <p>{n.text}</p>
          {!n.read && <button onClick={() => markRead(n.id)}>Mark read</button>}
        </div>
      ))}
    </div>
  );
}
