# 3) Backend: `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const { Server } = require("socket.io");
const Database = require("better-sqlite3");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const db = new Database("app.db");

// --- DB setup ---
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    premium INTEGER DEFAULT 0
  );

  CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    content TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(user_id) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    content TEXT NOT NULL,
    read INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(user_id) REFERENCES users(id)
  );
`);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// --- Helpers ---
function getOrCreateUser(username) {
  let user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) {
    const info = db.prepare("INSERT INTO users (username) VALUES (?)").run(username);
    user = db.prepare("SELECT * FROM users WHERE id = ?").get(info.lastInsertRowid);
  }
  return user;
}

function createNotification(userId, type, content) {
  const info = db
    .prepare("INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)")
    .run(userId, type, content);

  const notif = db.prepare("SELECT * FROM notifications WHERE id = ?").get(info.lastInsertRowid);
  io.to(`user:${userId}`).emit("notification", notif);
  return notif;
}

// --- API ---
app.post("/api/login", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username is required" });

  const user = getOrCreateUser(username);
  res.json(user);
});

app.get("/api/messages", (req, res) => {
  const messages = db.prepare(`
    SELECT messages.*, users.username
    FROM messages
    JOIN users ON users.id = messages.user_id
    ORDER BY messages.created_at ASC
    LIMIT 100
  `).all();

  res.json(messages);
});

app.post("/api/messages", (req, res) => {
  const { username, content } = req.body;
  if (!username || !content) {
    return res.status(400).json({ error: "username and content are required" });
  }

  const user = getOrCreateUser(username);

  const info = db
    .prepare("INSERT INTO messages (user_id, content) VALUES (?, ?)")
    .run(user.id, content);

  const message = db.prepare(`
    SELECT messages.*, users.username
    FROM messages
    JOIN users ON users.id = messages.user_id
    WHERE messages.id = ?
  `).get(info.lastInsertRowid);

  // Broadcast new message
  io.emit("message", message);

  // Notify all other connected users
  const allUsers = db.prepare("SELECT * FROM users WHERE id != ?").all(user.id);
  for (const u of allUsers) {
    createNotification(u.id, "message", `${user.username} sent a new message`);
  }

  res.json(message);
});

app.get("/api/notifications/:username", (req, res) => {
  const { username } = req.params;
  const user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) return res.json([]);

  const notifications = db.prepare(`
    SELECT * FROM notifications
    WHERE user_id = ?
    ORDER BY created_at DESC
    LIMIT 50
  `).all(user.id);

  res.json(notifications);
});

app.post("/api/notifications/read", (req, res) => {
  const { username } = req.body;
  const user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) return res.status(404).json({ error: "User not found" });

  db.prepare("UPDATE notifications SET read = 1 WHERE user_id = ?").run(user.id);
  res.json({ success: true });
});

// --- Monetization: minimal premium purchase flow ---
app.post("/api/premium/buy", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username is required" });

  const user = getOrCreateUser(username);

  // Mock purchase success
  db.prepare("UPDATE users SET premium = 1 WHERE id = ?").run(user.id);

  createNotification(user.id, "premium", "Premium activated successfully!");

  res.json({ success: true, premium: 1 });
});

app.get("/api/me/:username", (req, res) => {
  const user = db.prepare("SELECT * FROM users WHERE username = ?").get(req.params.username);
  if (!user) return res.status(404).json({ error: "User not found" });
  res.json(user);
});

// --- Socket.IO ---
io.on("connection", (socket) => {
  socket.on("join", ({ username }) => {
    const user = getOrCreateUser(username);
    socket.join(`user:${user.id}`);
    socket.emit("joined", user);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

