# 6) Frontend logic: `public/client.js`

```js
const socket = io();

let currentUser = null;

const authDiv = document.getElementById("auth");
const appDiv = document.getElementById("app");
const usernameInput = document.getElementById("username");
const loginBtn = document.getElementById("loginBtn");
const currentUserEl = document.getElementById("currentUser");
const premiumBadge = document.getElementById("premiumBadge");
const buyPremiumBtn = document.getElementById("buyPremiumBtn");

const messageList = document.getElementById("messageList");
const messageInput = document.getElementById("messageInput");
const sendBtn = document.getElementById("sendBtn");

const notificationList = document.getElementById("notificationList");

function renderMessage(m) {
  const div = document.createElement("div");
  div.className = "message";
  div.textContent = `${m.username}: ${m.content}`;
  messageList.appendChild(div);
  messageList.scrollTop = messageList.scrollHeight;
}

function renderNotification(n) {
  const li = document.createElement("li");
  li.textContent = `${n.type.toUpperCase()}: ${n.content}`;
  notificationList.prepend(li);
}

async function loadMessages() {
  const res = await fetch("/api/messages");
  const messages = await res.json();
  messageList.innerHTML = "";
  messages.forEach(renderMessage);
}

async function loadNotifications(username) {
  const res = await fetch(`/api/notifications/${encodeURIComponent(username)}`);
  const notifications = await res.json();
  notificationList.innerHTML = "";
  notifications.reverse().forEach(renderNotification);
}

async function refreshMe(username) {
  const res = await fetch(`/api/me/${encodeURIComponent(username)}`);
  const user = await res.json();
  if (user.premium) {
    premiumBadge.classList.remove("hidden");
    buyPremiumBtn.classList.add("hidden");
  }
}

loginBtn.onclick = async () => {
  const username = usernameInput.value.trim();
  if (!username) return alert("Enter a username");

  const res = await fetch("/api/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username })
  });

  const user = await res.json();
  currentUser = user.username;

  authDiv.classList.add("hidden");
  appDiv.classList.remove("hidden");
  currentUserEl.textContent = currentUser;

  socket.emit("join", { username: currentUser });

  await loadMessages();
  await loadNotifications(currentUser);
  await refreshMe(currentUser);
};

sendBtn.onclick = async () => {
  const content = messageInput.value.trim();
  if (!content || !currentUser) return;

  await fetch("/api/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username: currentUser, content })
  });

  messageInput.value = "";
};

buyPremiumBtn.onclick = async () => {
  const res = await fetch("/api/premium/buy", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username: currentUser })
  });

  const data = await res.json();
  if (data.success) {
    premiumBadge.classList.remove("hidden");
    buyPremiumBtn.classList.add("hidden");
    alert("Premium unlocked!");
  }
};

socket.on("message", (message) => {
  renderMessage(message);
});

socket.on("notification", (notif) => {
  if (currentUser) renderNotification(notif);
});

socket.on("joined", (user) => {
  // optional hook
});
```

