## `server/src/stripe.js`

```js
import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post("/checkout", async (req, res) => {
  const { userId, product } = req.body;

  const priceMap = {
    credits10: { name: "10 Credits", amount: 499 },
    premium: { name: "Premium", amount: 999 }
  };

  const item = priceMap[product];
  if (!item) return res.status(400).json({ error: "Invalid product" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: item.name },
          unit_amount: item.amount
        },
        quantity: 1
      }
    ],
    metadata: { userId, product },
    success_url: `${process.env.CLIENT_URL}/pricing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/pricing?canceled=1`
  });

  res.json({ url: session.url });
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];

  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  const alreadyProcessed = await prisma.paymentEvent.findUnique({
    where: { stripeEventId: event.id }
  });
  if (alreadyProcessed) return res.json({ received: true });

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const { userId, product } = session.metadata;

    if (product === "credits10") {
      await prisma.user.update({
        where: { id: userId },
        data: { credits: { increment: 10 } }
      });
    }

    if (product === "premium") {
      await prisma.user.update({
        where: { id: userId },
        data: { premium: true }
      });
    }

    await prisma.paymentEvent.create({
      data: { stripeEventId: event.id }
    });
  }

  res.json({ received: true });
});

export default router;
```

