## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import dotenv from "dotenv";
import { PrismaClient } from "@prisma/client";
import authRoutes from "./auth.js";
import stripeRoutes from "./stripe.js";
import { authRequired } from "./middleware.js";
import { setupSocket } from "./socket.js";

dotenv.config();

const prisma = new PrismaClient();
const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

app.use("/auth", authRoutes);
app.use("/stripe", stripeRoutes);

setupSocket(io);

app.get("/me", authRequired, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  res.json({ id: user.id, email: user.email, name: user.name, credits: user.credits, premium: user.premium });
});

app.get("/users", authRequired, async (req, res) => {
  const users = await prisma.user.findMany({
    select: { id: true, name: true, email: true, premium: true }
  });
  res.json(users);
});

app.get("/messages/:userId", authRequired, async (req, res) => {
  const me = req.user.id;
  const other = req.params.userId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.get("/notifications", authRequired, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

server.listen(4000, () => console.log("Server running on http://localhost:4000"));
```

