## `client/app/chat/page.jsx`

```jsx
"use client";
import { useEffect, useState } from "react";
import { api } from "../../lib/api";
import { createSocket } from "../../lib/socket";

export default function ChatPage() {
  const [users, setUsers] = useState([]);
  const [messages, setMessages] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [content, setContent] = useState("");
  const [socket, setSocket] = useState(null);

  const token = typeof window !== "undefined" ? localStorage.getItem("token") : null;
  const me = typeof window !== "undefined" ? JSON.parse(localStorage.getItem("user") || "null") : null;

  useEffect(() => {
    if (!token) window.location.href = "/";
    api("/users", token).then(setUsers);

    const s = createSocket();
    setSocket(s);

    s.on("connect", () => {
      if (me?.id) s.emit("join", me.id);
    });

    s.on("new_message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages(prev => [...prev, msg]);
      }
    });

    return () => s.disconnect();
  }, []);

  async function openChat(user) {
    setSelectedUser(user);
    const msgs = await api(`/messages/${user.id}`, token);
    setMessages(msgs);
  }

  function send() {
    socket.emit("send_message", {
      senderId: me.id,
      receiverId: selectedUser.id,
      content
    });
    setContent("");
  }

  return (
    <main style={{ display: "flex", gap: 24, padding: 24 }}>
      <aside style={{ width: 240 }}>
        <h3>Users</h3>
        {users.filter(u => u.id !== me?.id).map(u => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.name} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
        <a href="/notifications">Notifications</a><br />
        <a href="/pricing">Pricing</a>
      </aside>

      <section style={{ flex: 1 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.name}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto", padding: 8 }}>
          {messages.map(m => (
            <div key={m.id}>
              <b>{m.senderId === me?.id ? "Me" : selectedUser?.name}:</b> {m.content}
            </div>
          ))}
        </div>
        <input value={content} onChange={e => setContent(e.target.value)} />
        <button disabled={!selectedUser} onClick={send}>Send</button>
      </section>
    </main>
  );
}
