      }

      .grid {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <div class="dashboard">
    <aside class="sidebar">
      <h1>Live Metrics</h1>
      <p>Interactive dashboard with real-time updates and form-driven data entry.</p>

      <div class="stat">
        <div class="label">Current Value</div>
        <div class="value" id="currentValue">0</div>
      </div>

      <div class="stat">
        <div class="label">Average</div>
        <div class="value" id="averageValue">0</div>
      </div>

      <div class="stat">
        <div class="label">Status</div>
        <div class="value" id="statusValue" style="font-size:1.1rem;">Running</div>
      </div>
    </aside>

    <main class="main">
      <div class="topbar">
        <div>
          <h2 style="margin:0;">Real-Time Dashboard</h2>
          <div style="color: var(--muted); margin-top: 4px;">Live chart and form handling demo</div>
        </div>
        <div class="controls">
          <button id="toggleBtn">Pause</button>
          <button class="secondary" id="resetBtn">Reset</button>
        </div>
      </div>

      <div class="grid">
        <section class="panel">
          <h2>Live Chart</h2>
          <canvas id="chart" width="900" height="320"></canvas>
        </section>

        <section class="panel">
          <h2>Add Data Point</h2>
          <form id="dataForm">
            <div class="form-row">
              <label>
                Label
                <input type="text" id="labelInput" placeholder="e.g. Sensor A" required />
              </label>
              <label>
                Value
                <input type="number" id="valueInput" placeholder="e.g. 42" required />
              </label>
            </div>

            <label>
              Category
              <select id="categoryInput">
                <option value="manual">Manual</option>
                <option value="sensor">Sensor</option>
                <option value="api">API</option>
              </select>
            </label>

            <button type="submit">Add Point</button>
          </form>

          <div class="feed" id="feed"></div>
        </section>
      </div>
    </main>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const statusValueEl = document.getElementById("statusValue");
    const feedEl = document.getElementById("feed");

    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");
    const dataForm = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");
    const categoryInput = document.getElementById("categoryInput");

    let running = true;
    let data = Array.from({ length: 20 }, (_, i) => ({
      label: `P${i + 1}`,
      value: Math.floor(Math.random() * 100),
      category: "sensor",
      time: new Date().toLocaleTimeString()
    }));

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 40;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      const maxVal = Math.max(...data.map(d => d.value), 100);
      const minVal = Math.min(...data.map(d => d.value), 0);

      // Axes
      ctx.strokeStyle = "rgba(255,255,255,0.15)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, canvas.height - padding);
      ctx.lineTo(canvas.width - padding, canvas.height - padding);
      ctx.stroke();

      // Grid lines
      ctx.fillStyle = "rgba(255,255,255,0.5)";
      ctx.font = "12px sans-serif";
      for (let i = 0; i <= 4; i++) {
        const y = padding + (chartHeight / 4) * i;
        const val = Math.round(maxVal - ((maxVal - minVal) / 4) * i);

        ctx.strokeStyle = "rgba(255,255,255,0.06)";
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(canvas.width - padding, y);
        ctx.stroke();

        ctx.fillText(val.toString(), 8, y + 4);
      }

      // Line chart
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + (chartWidth / (data.length - 1)) * index;
        const y = padding + chartHeight - ((point.value - minVal) / (maxVal - minVal || 1)) * chartHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + (chartWidth / (data.length - 1)) * index;
        const y = padding + chartHeight - ((point.value - minVal) / (maxVal - minVal || 1)) * chartHeight;

        ctx.fillStyle = "#22c55e";
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      // X labels
      ctx.fillStyle = "rgba(255,255,255,0.65)";
      data.forEach((point, index) => {
        const x = padding + (chartWidth / (data.length - 1)) * index;
        if (index % 2 === 0) {
          ctx.fillText(point.label, x - 10, canvas.height - 15);
        }
      });
    }

    function updateStats() {
      const latest = data[data.length - 1]?.value ?? 0;
      const avg = data.reduce((sum, d) => sum + d.value, 0) / data.length;

      currentValueEl.textContent = latest.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      statusValueEl.textContent = running ? "Running" : "Paused";
    }

    function addFeedItem(label, value, category) {
      const item = document.createElement("div");
      item.className = "feed-item";
      item.innerHTML = `
        <strong>${label}</strong> — ${value} <span style="color:#38bdf8;">(${category})</span>
        <small>${new Date().toLocaleTimeString()}</small>
      `;
      feedEl.prepend(item);

      // Keep feed manageable
      while (feedEl.children.length > 8) {
        feedEl.removeChild(feedEl.lastChild);
      }
    }

    function pushRandomData() {
      const value = Math.floor(Math.random() * 100);
      const label = `P${data.length + 1}`;
      data.push({
        label,
        value,
        category: "sensor",
        time: new Date().toLocaleTimeString()
      });

      if (data.length > 20) data.shift();

      addFeedItem(label, value, "sensor");
      drawChart();
      updateStats();
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);
      const category = categoryInput.value;

      if (!label || Number.isNaN(value)) return;

      data.push({
        label,
        value,
        category,
        time: new Date().toLocaleTimeString()
      });

      if (data.length > 20) data.shift();

      addFeedItem(label, value, category);
      drawChart();
      updateStats();

      dataForm.reset();
      labelInput.focus();
    });

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      updateStats();
    });

    resetBtn.addEventListener("click", () => {
      data = Array.from({ length: 20 }, (_, i) => ({
        label: `P${i + 1}`,
        value: Math.floor(Math.random() * 100),
        category: "sensor",
        time: new Date().toLocaleTimeString()
      }));
      feedEl.innerHTML = "";
      drawChart();
      updateStats();
    });

    // Initial render
    drawChart();
    updateStats();

    // Real-time loop
    setInterval(() => {
      if (running) pushRandomData();
    }, 1500);
  </script>
</body>
</html>
