<body>
  <header>
    <h1>Real-Time Operations Dashboard</h1>
    <p><span class="status-dot"></span>Live data stream active</p>
  </header>

  <main class="container">
    <section class="summary">
      <div class="card">
        <div class="metric-label">Current Value</div>
        <div class="metric-value" id="currentValue">0</div>
        <div class="metric-change" id="currentChange">+0% from last update</div>
      </div>
      <div class="card">
        <div class="metric-label">Average</div>
        <div class="metric-value" id="averageValue">0</div>
