              <label for="eventType">Type</label>
              <select id="eventType">
                <option value="Info">Info</option>
                <option value="Warning">Warning</option>
                <option value="Critical">Critical</option>
              </select>
            </div>

            <div class="field-group">
              <label for="eventValue">Value</label>
              <input type="number" id="eventValue" placeholder="42" required />
            </div>
          </div>

          <div class="field-group">
            <label for="eventNote">Note</label>
            <textarea id="eventNote" rows="3" placeholder="Optional details..."></textarea>
          </div>

          <button type="submit">Submit Event</button>
        </form>
      </div>

      <div class="card">
        <h2 style="margin-top:0;">Activity Feed</h2>
