  <script>
    const currentValueEl = document.getElementById("currentValue");
    const currentChangeEl = document.getElementById("currentChange");
    const averageValueEl = document.getElementById("averageValue");
    const eventCountEl = document.getElementById("eventCount");
    const activityFeedEl = document.getElementById("activityFeed");
    const eventForm = document.getElementById("eventForm");

    const labels = [];
    const dataPoints = [];
    const maxPoints = 20;
    let lastValue = 50;
    let eventCount = 0;

    const lineCtx = document.getElementById("lineChart").getContext("2d");
    const barCtx = document.getElementById("barChart").getContext("2d");

    const lineChart = new Chart(lineCtx, {
      type: "line",
      data: {
        labels: labels,
        datasets: [{
          label: "Live Value",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.18)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const barChart = new Chart(barCtx, {
      type: "bar",
      data: {
        labels: ["Info", "Warning", "Critical"],
        datasets: [{
          label: "Events",
          data: [0, 0, 0],
          backgroundColor: ["#38bdf8", "#f59e0b", "#ef4444"]
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" },
            beginAtZero: true
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function addFeedItem(title, detail) {
      const item = document.createElement("div");
      item.className = "feed-item";
      item.innerHTML = `
        <strong>${title}</strong>
        <small>${detail}</small>
      `;
      activityFeedEl.prepend(item);

      while (activityFeedEl.children.length > 8) {
        activityFeedEl.removeChild(activityFeedEl.lastChild);
      }
    }

    function updateLiveData() {
      const now = new Date();
      const timeLabel = now.toLocaleTimeString();

      const change = Math.floor(Math.random() * 21) - 10;
      const newValue = Math.max(0, lastValue + change);

      labels.push(timeLabel);
      dataPoints.push(newValue);

      if (labels.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }

      lineChart.update();

      const avg = Math.round(dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length);
      const pctChange = lastValue === 0 ? 0 : Math.round(((newValue - lastValue) / lastValue) * 100);

      currentValueEl.textContent = newValue;
      averageValueEl.textContent = avg;
      currentChangeEl.textContent = `${pctChange >= 0 ? "+" : ""}${pctChange}% from last update`;
      currentChangeEl.style.color = pctChange >= 0 ? "#22c55e" : "#ef4444";

      lastValue = newValue;
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const type = document.getElementById("eventType").value;
      const value = Number(document.getElementById("eventValue").value);
      const note = document.getElementById("eventNote").value.trim();

      if (!name || Number.isNaN(value)) return;

      eventCount++;
      eventCountEl.textContent = eventCount;

      const typeIndex = { Info: 0, Warning: 1, Critical: 2 }[type];
      barChart.data.datasets[0].data[typeIndex] += 1;
      barChart.update();

      addFeedItem(
        `${type}: ${name}`,
        `Value: ${value}${note ? " — " + note : ""}`
      );

      eventForm.reset();
      document.getElementById("eventName").focus();
    });

    // Seed initial feed
    addFeedItem("System boot", "Dashboard initialized successfully");
    addFeedItem("Data stream", "Connected to live simulation source");

    // Start live updates
    updateLiveData();
    setInterval(updateLiveData, 1000);
  </script>
</body>
