      display: inline-block;
      margin-left: 8px;
      font-size: 0.8rem;
      padding: 4px 8px;
      border-radius: 999px;
      background: rgba(34, 197, 94, 0.15);
      color: #86efac;
      border: 1px solid rgba(34, 197, 94, 0.3);
    }

    .error {
      color: #fca5a5;
      font-size: 0.85rem;
      display: none;
