    @media (max-width: 1024px) {
      .stats {
        grid-template-columns: repeat(2, 1fr);
      }
      .chart-card, .form-card {
        grid-column: span 12;
      }
    }

    @media (max-width: 640px) {
      .stats {
        grid-template-columns: 1fr;
      }
      .dashboard {
        padding: 12px;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Real-Time Analytics Dashboard <span class="status">Live</span></h1>
    <p>Interactive browser-based dashboard with real-time charting and form submission.</p>
  </header>

  <main class="dashboard">
    <section class="stats">
      <div class="stat">
        <div class="label">Active Users</div>
        <div class="value" id="activeUsers">0</div>
        <div class="trend">+12% from last hour</div>
      </div>
      <div class="stat">
        <div class="label">Requests / min</div>
        <div class="value" id="requestsPerMin">0</div>
        <div class="trend">Stable traffic</div>
      </div>
      <div class="stat">
        <div class="label">Conversion Rate</div>
        <div class="value" id="conversionRate">0%</div>
        <div class="trend">Improving</div>
      </div>
      <div class="stat">
        <div class="label">Errors</div>
        <div class="value" id="errorCount">0</div>
        <div class="trend" style="color: #fca5a5;">Needs attention</div>
      </div>
    </section>

    <section class="card chart-card">
      <h2>Live Traffic</h2>
      <div class="chart-wrap">
        <canvas id="trafficChart"></canvas>
      </div>
    </section>

    <section class="card form-card">
      <h2>Update Settings</h2>
      <form id="settingsForm">
        <div>
          <label for="username">Display Name</label>
          <input type="text" id="username" name="username" placeholder="Enter your name" required />
        </div>

        <div>
          <label for="refreshRate">Refresh Rate (ms)</label>
          <input type="number" id="refreshRate" name="refreshRate" min="500" step="100" value="2000" required />
        </div>

        <div>
          <label for="theme">Theme</label>
          <select id="theme" name="theme">
            <option value="dark">Dark</option>
            <option value="midnight">Midnight</option>
            <option value="blue">Blue</option>
          </select>
        </div>

        <div>
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" rows="4" placeholder="Add a note..."></textarea>
        </div>

        <button type="submit">Save Settings</button>
        <div class="error" id="formError">Please fill in all required fields correctly.</div>
      </form>
    </section>

    <section class="card log-card">
      <h2>Event Log</h2>
      <ul class="log-list" id="eventLog"></ul>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const conversionRateEl = document.getElementById("conversionRate");
    const errorCountEl = document.getElementById("errorCount");
    const eventLogEl = document.getElementById("eventLog");
    const form = document.getElementById("settingsForm");
    const formError = document.getElementById("formError");
    const refreshRateInput = document.getElementById("refreshRate");
    const themeSelect = document.getElementById("theme");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `-${11 - i}m`);
    const trafficData = labels.map(() => Math.floor(Math.random() * 100) + 50);

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function addLog(message) {
      const li = document.createElement("li");
      li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLogEl.prepend(li);

      while (eventLogEl.children.length > 10) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    function updateStats() {
      const activeUsers = Math.floor(Math.random() * 500) + 100;
      const requests = Math.floor(Math.random() * 300) + 200;
      const conversion = (Math.random() * 5 + 1).toFixed(2);
      const errors = Math.floor(Math.random() * 10);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requests;
      conversionRateEl.textContent = conversion + "%";
      errorCountEl.textContent = errors;

      const nextValue = Math.floor(Math.random() * 100) + 50;
      trafficData.push(nextValue);
      trafficData.shift();
      chart.update();

      addLog(`Metrics refreshed: users=${activeUsers}, requests=${requests}, conversion=${conversion}%, errors=${errors}`);
    }

    let intervalId = setInterval(updateStats, parseInt(refreshRateInput.value, 10));

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const username = document.getElementById("username").value.trim();
      const refreshRate = parseInt(refreshRateInput.value, 10);
      const theme = themeSelect.value;
      const notes = document.getElementById("notes").value.trim();

      if (!username || isNaN(refreshRate) || refreshRate < 500) {
        formError.style.display = "block";
        return;
      }

      formError.style.display = "none";

      clearInterval(intervalId);
      intervalId = setInterval(updateStats, refreshRate);

      document.body.dataset.theme = theme;
      applyTheme(theme);

      addLog(`Settings saved by ${username}. Refresh rate set to ${refreshRate}ms. Theme: ${theme}.`);
      if (notes) addLog(`Note added: ${notes}`);
    });

    function applyTheme(theme) {
      const themes = {
        dark: {
          bg: "#0f172a",
          panel: "#111827",
          panel2: "#1f2937",
          text: "#e5e7eb",
          accent: "#38bdf8"
        },
        midnight: {
          bg: "#020617",
          panel: "#0f172a",
          panel2: "#1e293b",
          text: "#f8fafc",
          accent: "#8b5cf6"
        },
        blue: {
          bg: "#0b1220",
          panel: "#10203a",
          panel2: "#1b3358",
          text: "#e0f2fe",
          accent: "#0ea5e9"
        }
      };

      const t = themes[theme] || themes.dark;
      document.documentElement.style.setProperty("--bg", t.bg);
      document.documentElement.style.setProperty("--panel", t.panel);
      document.documentElement.style.setProperty("--panel-2", t.panel2);
      document.documentElement.style.setProperty("--text", t.text);
      document.documentElement.style.setProperty("--accent", t.accent);
    }

    themeSelect.addEventListener("change", () => applyTheme(themeSelect.value));

    // Initial render
    updateStats();
    addLog("Dashboard initialized.");
  </script>
</body>
</html>
```

