<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Live metrics, streaming chart updates, and form-based event tracking.</p>
  </header>

  <main class="container">
    <section class="metrics">
      <div class="card">
        <div class="metric-label">Active Users</div>
        <div class="metric-value" id="activeUsers">0</div>
        <div class="metric-sub">Updated every second</div>
      </div>
      <div class="card">
        <div class="metric-label">Requests / Min</div>
        <div class="metric-value" id="requestsPerMin">0</div>
        <div class="metric-sub">Rolling simulated traffic</div>
      </div>
      <div class="card">
        <div class="metric-label">Error Rate</div>
        <div class="metric-value" id="errorRate">0%</div>
        <div class="metric-sub">Based on recent events</div>
      </div>
      <div class="card">
        <div class="metric-label">System Status</div>
        <div class="metric-value" id="systemStatus">OK</div>
        <div class="metric-sub">Health indicator</div>
      </div>
    </section>

    <section class="grid">
      <div class="card">
        <h2 class="panel-title">Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="card">
        <h2 class="panel-title">Event Form</h2>
        <form id="eventForm">
          <div>
            <label for="eventName">Event Name</label>
            <input id="eventName" type="text" placeholder="e.g. Signup" required />
          </div>

          <div class="row">
            <div>
              <label for="eventType">Type</label>
              <select id="eventType" required>
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="error">Error</option>
              </select>
            </div>
            <div>
              <label for="eventValue">Value</label>
              <input id="eventValue" type="number" min="0" step="1" value="1" required />
            </div>
          </div>

          <div>
            <label for="eventDescription">Description</label>
            <textarea id="eventDescription" rows="4" placeholder="Optional details"></textarea>
          </div>

          <button type="submit">Submit Event</button>
        </form>
        <div class="footer-note">Submitted events are added to the live event log below.</div>
      </div>
    </section>

    <section class="card">
      <h2 class="panel-title">Event Log</h2>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Event</th>
              <th>Type</th>
              <th>Value</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody id="eventLog"></tbody>
        </table>
      </div>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemStatusEl = document.getElementById("systemStatus");
    const eventLogEl = document.getElementById("eventLog");
    const eventForm = document.getElementById("eventForm");

    const labels = [];
    const trafficData = [];

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests / Min",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        }
      }
    });

    const recentEvents = [];
    let totalEvents = 0;
    let errorEvents = 0;

    function pad(n) {
      return String(n).padStart(2, "0");
    }

    function timeString(date = new Date()) {
      return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
    }

    function addLogRow({ time, name, type, value, description }) {
      const tr = document.createElement("tr");
      const statusClass = type === "error" ? "bad" : type === "warning" ? "warn" : "ok";

      tr.innerHTML = `
        <td>${time}</td>
        <td>${name}</td>
        <td><span class="status ${statusClass}">${type.toUpperCase()}</span></td>
        <td>${value}</td>
        <td>${description || "-"}</td>
      `;

      eventLogEl.prepend(tr);
    }

    function updateMetrics() {
      const activeUsers = Math.floor(80 + Math.random() * 120);
      const requestsPerMin = Math.floor(300 + Math.random() * 500);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;

      const errorRate = totalEvents === 0 ? 0 : Math.round((errorEvents / totalEvents) * 100);
      errorRateEl.textContent = `${errorRate}%`;

      if (errorRate < 10) {
        systemStatusEl.textContent = "OK";
        systemStatusEl.style.color = "#86efac";
      } else if (errorRate < 25) {
        systemStatusEl.textContent = "WARN";
        systemStatusEl.style.color = "#fcd34d";
      } else {
        systemStatusEl.textContent = "CRITICAL";
        systemStatusEl.style.color = "#fca5a5";
      }

      const now = new Date();
      const label = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
      labels.push(label);
      trafficData.push(requestsPerMin);

      if (labels.length > 20) {
        labels.shift();
        trafficData.shift();
      }

      trafficChart.update();
    }

    function seedInitialEvents() {
      const samples = [
        { name: "User Signup", type: "info", value: 1, description: "New user created" },
        { name: "Cache Refresh", type: "warning", value: 2, description: "Cache miss spike detected" },
        { name: "API Failure", type: "error", value: 5, description: "Endpoint timeout" }
      ];

      samples.forEach(sample => {
        totalEvents++;
        if (sample.type === "error") errorEvents++;

        addLogRow({
          time: timeString(),
          ...sample
        });
      });
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const type = document.getElementById("eventType").value;
      const value = document.getElementById("eventValue").value;
      const description = document.getElementById("eventDescription").value.trim();

      if (!name) return;

      totalEvents++;
      if (type === "error") errorEvents++;

      const event = {
        time: timeString(),
        name,
        type,
        value,
        description
      };

      recentEvents.unshift(event);
      if (recentEvents.length > 10) recentEvents.pop();

      addLogRow(event);
      eventForm.reset();
      document.getElementById("eventValue").value = 1;
    });

    seedInitialEvents();
    updateMetrics();
    setInterval(updateMetrics, 1000);
  </script>
</body>
</html>
