<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Live data visualization, interactive filtering, and form submission</p>
  </header>

  <main class="container">
    <section class="stats">
      <div class="card">
        <div class="stat-title">Active Users</div>
        <div class="stat-value" id="activeUsers">0</div>
        <div class="stat-sub">Updated every second</div>
      </div>
      <div class="card">
        <div class="stat-title">Requests / Min</div>
        <div class="stat-value" id="requestsPerMin">0</div>
        <div class="stat-sub">Simulated live traffic</div>
      </div>
      <div class="card">
        <div class="stat-title">Error Rate</div>
        <div class="stat-value" id="errorRate">0%</div>
        <div class="stat-sub">Based on recent events</div>
      </div>
      <div class="card">
        <div class="stat-title">System Status</div>
        <div class="stat-value" id="systemStatus">OK</div>
        <div class="stat-sub">Health indicator</div>
      </div>
    </section>

    <section class="grid">
      <div class="card">
        <h2 style="margin-top:0;">Live Traffic Chart</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="controls">
        <div class="card">
          <h2 style="margin-top:0;">Add Event</h2>
          <form id="eventForm">
            <div class="form-group">
              <label for="eventName">Event Name</label>
              <input type="text" id="eventName" placeholder="e.g. Login Success" required />
            </div>

            <div class="form-group">
              <label for="eventType">Event Type</label>
              <select id="eventType" required>
                <option value="info">Info</option>
                <option value="success">Success</option>
                <option value="warning">Warning</option>
                <option value="error">Error</option>
              </select>
            </div>

            <div class="form-group">
              <label for="eventNotes">Notes</label>
              <textarea id="eventNotes" placeholder="Optional details..."></textarea>
            </div>

            <button type="submit">Submit Event</button>
          </form>
        </div>

        <div class="card">
          <h2 style="margin-top:0;">Filter Events</h2>
          <div class="toolbar">
            <select id="filterType">
              <option value="all">All</option>
              <option value="info">Info</option>
              <option value="success">Success</option>
              <option value="warning">Warning</option>
              <option value="error">Error</option>
            </select>
            <input type="text" id="searchInput" placeholder="Search events..." />
          </div>
        </div>
      </div>
    </section>

    <section class="card">
      <h2 style="margin-top:0;">Event Feed</h2>
      <div class="list" id="eventList"></div>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemStatusEl = document.getElementById("systemStatus");
    const eventListEl = document.getElementById("eventList");

    const eventForm = document.getElementById("eventForm");
    const eventNameInput = document.getElementById("eventName");
    const eventTypeInput = document.getElementById("eventType");
    const eventNotesInput = document.getElementById("eventNotes");
    const filterType = document.getElementById("filterType");
    const searchInput = document.getElementById("searchInput");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `${i + 1}s`);
    const trafficData = Array.from({ length: 12 }, () => Math.floor(Math.random() * 80) + 20);

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.1)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.1)" }
          }
        }
      }
    });

    let events = [
      { name: "Server started", type: "success", notes: "Initial boot completed", time: new Date() },
      { name: "Cache warmed", type: "info", notes: "All cache nodes ready", time: new Date() },
      { name: "API latency spike", type: "warning", notes: "Temporary increase detected", time: new Date() }
    ];

    function renderEvents() {
      const typeFilter = filterType.value;
      const search = searchInput.value.toLowerCase();

      const filtered = events.filter(event => {
        const matchesType = typeFilter === "all" || event.type === typeFilter;
        const matchesSearch =
          event.name.toLowerCase().includes(search) ||
          event.notes.toLowerCase().includes(search);
        return matchesType && matchesSearch;
      });

      eventListEl.innerHTML = "";

      if (filtered.length === 0) {
        eventListEl.innerHTML = `<div class="muted">No events match your filters.</div>`;
        return;
      }

      filtered.forEach(event => {
        const item = document.createElement("div");
        item.className = "item";

        const badgeClass =
          event.type === "success" ? "ok" :
          event.type === "error" ? "warn" :
          event.type === "warning" ? "warn" : "ok";

        item.innerHTML = `
          <div class="item-top">
            <strong>${event.name}</strong>
            <span class="badge ${badgeClass}">${event.type.toUpperCase()}</span>
          </div>
          <div class="muted">${event.notes || "No additional notes."}</div>
          <div class="muted" style="margin-top:8px;">${event.time.toLocaleTimeString()}</div>
        `;

        eventListEl.appendChild(item);
      });
    }

    function updateStats() {
      const activeUsers = Math.floor(Math.random() * 300) + 50;
      const requestsPerMin = Math.floor(Math.random() * 1200) + 200;
      const errorRate = (Math.random() * 8).toFixed(1);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;

      systemStatusEl.textContent = errorRate < 2 ? "OK" : errorRate < 5 ? "DEGRADED" : "ALERT";
      systemStatusEl.style.color = errorRate < 2 ? "#22c55e" : errorRate < 5 ? "#f59e0b" : "#ef4444";
    }

    function updateChart() {
      trafficData.shift();
      trafficData.push(Math.floor(Math.random() * 80) + 20);
      chart.update();
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const newEvent = {
        name: eventNameInput.value.trim(),
        type: eventTypeInput.value,
        notes: eventNotesInput.value.trim(),
        time: new Date()
      };

      events.unshift(newEvent);
      eventForm.reset();
      renderEvents();
    });

    filterType.addEventListener("change", renderEvents);
    searchInput.addEventListener("input", renderEvents);

    renderEvents();
    updateStats();

    setInterval(() => {
      updateStats();
      updateChart();
    }, 1000);
  </script>
</body>
</html>
