  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = [];
    const trafficData = [];

    for (let i = 19; i >= 0; i--) {
      labels.push(`${i}s ago`);
      trafficData.push(Math.floor(Math.random() * 100) + 20);
    }

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemStatusEl = document.getElementById("systemStatus");
    const summaryTextEl = document.getElementById("summaryText");
    const eventsTableEl = document.getElementById("eventsTable");
    const searchInput = document.getElementById("searchInput");

    const eventForm = document.getElementById("eventForm");
    const eventNameInput = document.getElementById("eventName");
    const eventTypeInput = document.getElementById("eventType");
    const eventValueInput = document.getElementById("eventValue");

    let events = [];
    let trafficIndex = 20;

    function getTimeString() {
      return new Date().toLocaleTimeString();
    }

    function updateMetrics() {
      const activeUsers = Math.floor(Math.random() * 500) + 100;
      const requestsPerMin = Math.floor(Math.random() * 2000) + 300;
      const errorRate = (Math.random() * 5).toFixed(1);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;

      if (errorRate < 1.5) {
        systemStatusEl.textContent = "OK";
        systemStatusEl.style.color = "#4ade80";
      } else if (errorRate < 3.5) {
        systemStatusEl.textContent = "DEGRADED";
        systemStatusEl.style.color = "#fbbf24";
      } else {
        systemStatusEl.textContent = "ALERT";
        systemStatusEl.style.color = "#f87171";
      }
    }

    function updateChart() {
      const newValue = Math.floor(Math.random() * 100) + 20;
      trafficChart.data.labels.shift();
      trafficChart.data.labels.push(`${trafficIndex++}s`);
      trafficChart.data.datasets[0].data.shift();
      trafficChart.data.datasets[0].data.push(newValue);
      trafficChart.update();
    }

    function renderEvents(filteredEvents = events) {
      eventsTableEl.innerHTML = "";

      if (filteredEvents.length === 0) {
        eventsTableEl.innerHTML = `
          <tr>
            <td colspan="4" class="muted">No matching events found.</td>
          </tr>
        `;
        summaryTextEl.textContent = "No events to display.";
        return;
      }

      filteredEvents.slice().reverse().forEach(event => {
        const row = document.createElement("tr");
        row.innerHTML = `
          <td>${event.time}</td>
          <td>${event.name}</td>
          <td><span class="badge ${event.type}">${event.type.toUpperCase()}</span></td>
          <td>${event.value}</td>
        `;
        eventsTableEl.appendChild(row);
      });

      const latest = filteredEvents[filteredEvents.length - 1];
      summaryTextEl.textContent = `Latest event: ${latest.name} (${latest.type}) with value ${latest.value}.`;
    }

    function addEvent(name, type, value) {
      const event = {
        time: getTimeString(),
        name,
        type,
        value
      };
      events.push(event);
      renderEvents(getFilteredEvents());
    }

    function getFilteredEvents() {
      const query = searchInput.value.trim().toLowerCase();
      if (!query) return events;
      return events.filter(event =>
        event.name.toLowerCase().includes(query) ||
        event.type.toLowerCase().includes(query) ||
        String(event.value).includes(query)
      );
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = eventNameInput.value.trim();
      const type = eventTypeInput.value;
      const value = Number(eventValueInput.value);

      if (!name || Number.isNaN(value)) return;

      addEvent(name, type, value);

      eventForm.reset();
      eventNameInput.focus();
    });

    searchInput.addEventListener("input", () => {
      renderEvents(getFilteredEvents());
    });

    // Initial seed data
    addEvent("Server boot", "success", 1);
    addEvent("Cache warmup", "warning", 12);
    addEvent("Login spike", "success", 48);

    // Simulated real-time updates
    setInterval(() => {
      updateMetrics();
      updateChart();

      const eventTypes = ["success", "warning", "danger"];
      const names = ["API call", "DB query", "User login", "Payment", "Sync job", "Webhook"];
      const randomName = names[Math.floor(Math.random() * names.length)];
      const randomType = eventTypes[Math.floor(Math.random() * eventTypes.length)];
      const randomValue = Math.floor(Math.random() * 1000);

      addEvent(randomName, randomType, randomValue);
    }, 1000);

    // Initial render
    updateMetrics();
    renderEvents();
  </script>
</body>
</html>
```

