    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const openTicketsEl = document.getElementById("openTickets");
    const tableBody = document.getElementById("eventsTableBody");
    const emptyState = document.getElementById("emptyState");
    const searchInput = document.getElementById("search");
    const filterCategory = document.getElementById("filterCategory");
    const eventForm = document.getElementById("eventForm");

    const labels = Array.from({ length: 12 }, (_, i) => `${i + 1}s`);
    const trafficData = labels.map(() => randomInt(40, 120));

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { labels: { color: "#e5e7eb" } }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.15)" }
          }
        }
      }
    });

    const events = [
      makeEvent("Login spike detected", "Info", "Auth Team", 18),
      makeEvent("Cache miss rate rising", "Warning", "Platform", 63),
      makeEvent("Payment gateway timeout", "Critical", "Payments", 91)
    ];

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function makeEvent(title, category, owner, value) {
      return {
        time: new Date().toLocaleTimeString(),
        title,
        category,
        owner,
        value,
        status: value < 50 ? "ok" : value < 80 ? "warn" : "bad"
      };
    }

    function statusLabel(status) {
      return status === "ok" ? "Healthy" : status === "warn" ? "Degraded" : "Critical";
    }

    function statusClass(status) {
      return status === "ok" ? "ok" : status === "warn" ? "warn" : "bad";
    }

    function renderTable() {
      const q = searchInput.value.toLowerCase().trim();
      const category = filterCategory.value;

      const filtered = events.filter(e => {
        const matchesQuery =
          e.title.toLowerCase().includes(q) ||
          e.owner.toLowerCase().includes(q) ||
          e.category.toLowerCase().includes(q);
        const matchesCategory = !category || e.category === category;
        return matchesQuery && matchesCategory;
      });

      tableBody.innerHTML = "";

      if (filtered.length === 0) {
        emptyState.style.display = "block";
        return;
      }

      emptyState.style.display = "none";

      filtered.forEach(event => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
          <td>${event.time}</td>
          <td>${event.title}</td>
          <td>${event.category}</td>
          <td>${event.owner}</td>
          <td>${event.value}</td>
          <td><span class="status ${statusClass(event.status)}">${statusLabel(event.status)}</span></td>
        `;
        tableBody.appendChild(tr);
      });
    }

    function updateStats() {
      const activeUsers = randomInt(120, 500);
      const requestsPerMin = trafficData[trafficData.length - 1];
      const errors = randomInt(1, 12);
      const total = randomInt(100, 250);
      const errorRate = ((errors / total) * 100).toFixed(1);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;
      openTicketsEl.textContent = events.filter(e => e.category === "Critical").length;
    }

    function updateChart() {
      trafficData.push(randomInt(40, 140));
      trafficData.shift();
      trafficChart.data.datasets[0].data = trafficData;
      trafficChart.update();
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const title = document.getElementById("title").value.trim();
      const category = document.getElementById("category").value;
      const owner = document.getElementById("owner").value.trim();
      const value = Number(document.getElementById("value").value);

      events.unshift(makeEvent(title, category, owner, value));
      eventForm.reset();
      renderTable();
      updateStats();
    });

    searchInput.addEventListener("input", renderTable);
    filterCategory.addEventListener("change", renderTable);

    renderTable();
    updateStats();

    setInterval(() => {
      updateChart();
      updateStats();
    }, 1000);
  </script>
</body>
