            <tr>
              <td>10:15:02</td>
              <td>Page View</td>
              <td><span class="pill">User</span></td>
              <td>Low</td>
            </tr>
            <tr>
              <td>10:15:18</td>
              <td>Checkout Started</td>
              <td><span class="pill">Payment</span></td>
              <td>High</td>
            </tr>
          </tbody>
        </table>
