  <div class="toast" id="toast"></div>

  <script>
    const ctx = document.getElementById('trafficChart').getContext('2d');
    const labels = Array.from({ length: 12 }, (_, i) => `${i * 5}m`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 100) + 50);

    const trafficChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Traffic',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: '#38bdf8'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById('activeUsers');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const avgResponseEl = document.getElementById('avgResponse');
    const eventsTable = document.getElementById('eventsTable');
    const toast = document.getElementById('toast');

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(showToast.timer);
      showToast.timer = setTimeout(() => toast.classList.remove('show'), 2200);
    }

    function formatTime() {
      return new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
    }

    function updateMetrics() {
      const activeUsers = 1000 + Math.floor(Math.random() * 500);
      const requests = 7000 + Math.floor(Math.random() * 2500);
      const errorRate = (1 + Math.random() * 2).toFixed(1);
      const response = 180 + Math.floor(Math.random() * 90);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requests.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;
      avgResponseEl.textContent = `${response}ms`;
    }

    function updateChart() {
      trafficChart.data.datasets[0].data.shift();
      trafficChart.data.datasets[0].data.push(Math.floor(Math.random() * 100) + 50);
      trafficChart.update();
    }

    function addEventRow(eventName, category, priority) {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${formatTime()}</td>
        <td>${eventName}</td>
        <td><span class="pill">${category}</span></td>
        <td>${priority}</td>
      `;
      eventsTable.prepend(row);
    }

    document.getElementById('eventForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const eventName = document.getElementById('eventName').value.trim();
      const category = document.getElementById('category').value;
      const priority = document.getElementById('priority').value;

      if (!eventName) return;

      addEventRow(eventName, category, priority);
      showToast(`Event "${eventName}" added successfully`);

      e.target.reset();
      document.getElementById('priority').value = 'Medium';
    });

    setInterval(() => {
      updateMetrics();
      updateChart();
    }, 2000);
  </script>
</body>
</html>
