  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const responseTimeEl = document.getElementById("responseTime");
    const activeUsersTrendEl = document.getElementById("activeUsersTrend");
    const requestsTrendEl = document.getElementById("requestsTrend");
    const errorTrendEl = document.getElementById("errorTrend");
    const responseTrendEl = document.getElementById("responseTrend");
    const formMessageEl = document.getElementById("formMessage");
    const eventsTableEl = document.getElementById("eventsTable");
    const filterTypeEl = document.getElementById("filterType");
    const liveStatusEl = document.getElementById("liveStatus");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const chartData = {
      labels: Array.from({ length: 12 }, (_, i) => `-${11 - i}m`),
      datasets: [
        {
          label: "Requests",
          data: Array.from({ length: 12 }, () => Math.floor(Math.random() * 100) + 50),
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true
        }
      ]
    };

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: chartData,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    let metrics = {
      activeUsers: 1200,
      requestsPerMin: 850,
      errorRate: 1.8,
      responseTime: 210
    };

    let previousMetrics = { ...metrics };
    let events = [
      {
        time: new Date().toLocaleTimeString(),
        name: "System Boot",
        type: "info",
        notes: "Dashboard initialized successfully."
      }
    ];

    function updateMetrics() {
      previousMetrics = { ...metrics };

      metrics.activeUsers += Math.floor(Math.random() * 40 - 10);
      metrics.requestsPerMin += Math.floor(Math.random() * 60 - 20);
      metrics.errorRate = Math.max(0, +(metrics.errorRate + (Math.random() * 0.8 - 0.4)).toFixed(1));
      metrics.responseTime = Math.max(50, Math.floor(metrics.responseTime + Math.random() * 30 - 15));

      activeUsersEl.textContent = metrics.activeUsers.toLocaleString();
      requestsPerMinEl.textContent = metrics.requestsPerMin.toLocaleString();
      errorRateEl.textContent = metrics.errorRate.toFixed(1) + "%";
      responseTimeEl.textContent = metrics.responseTime + " ms";

      const activeChange = ((metrics.activeUsers - previousMetrics.activeUsers) / previousMetrics.activeUsers) * 100;
      const requestChange = ((metrics.requestsPerMin - previousMetrics.requestsPerMin) / previousMetrics.requestsPerMin) * 100;
      const errorChange = metrics.errorRate - previousMetrics.errorRate;
      const responseChange = metrics.responseTime - previousMetrics.responseTime;

      activeUsersTrendEl.textContent = `${activeChange >= 0 ? "+" : ""}${activeChange.toFixed(1)}% from last minute`;
      requestsTrendEl.textContent = `${requestChange >= 0 ? "+" : ""}${requestChange.toFixed(1)}% from last minute`;
      errorTrendEl.textContent = `${metrics.errorRate.toFixed(1)}% current error rate`;
      responseTrendEl.textContent = `${responseChange > 0 ? "Slower" : "Faster"} by ${Math.abs(responseChange)} ms`;

      activeUsersTrendEl.className = `trend ${activeChange >= 0 ? "up" : "down"}`;
      requestsTrendEl.className = `trend ${requestChange >= 0 ? "up" : "down"}`;
      errorTrendEl.className = `trend ${errorChange > 0 ? "down" : "up"}`;
      responseTrendEl.className = `trend ${responseChange > 0 ? "down" : "up"}`;
    }

    function updateChart() {
      const nextValue = Math.floor(Math.random() * 100) + 50;
      trafficChart.data.datasets[0].data.push(nextValue);
      trafficChart.data.datasets[0].data.shift();
      trafficChart.update();

      liveStatusEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;
    }

    function renderEvents() {
      const filter = filterTypeEl.value;
      const filteredEvents = filter === "all"
        ? events
        : events.filter(event => event.type === filter);

      eventsTableEl.innerHTML = filteredEvents.map(event => {
        const pillClass = event.type === "info" ? "success"
                        : event.type === "warning" ? "warning"
                        : "danger";

        return `
          <tr>
            <td>${event.time}</td>
            <td>${event.name}</td>
            <td><span class="pill ${pillClass}">${event.type}</span></td>
            <td>${event.notes}</td>
          </tr>
        `;
      }).join("");
    }

    document.getElementById("eventForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const type = document.getElementById("eventType").value;
      const notes = document.getElementById("eventNotes").value.trim();

      if (!name || !type || !notes) return;

      events.unshift({
        time: new Date().toLocaleTimeString(),
        name,
        type,
        notes
      });

      renderEvents();

      formMessageEl.style.display = "block";
      formMessageEl.textContent = `Event "${name}" submitted successfully.`;

      this.reset();

      setTimeout(() => {
        formMessageEl.style.display = "none";
      }, 3000);
    });

    filterTypeEl.addEventListener("change", renderEvents);

    // Initial render
    updateMetrics();
    updateChart();
    renderEvents();

    // Real-time updates
    setInterval(() => {
      updateMetrics();
      updateChart();
    }, 3000);
  </script>
</body>
</html>
