          <button type="button" class="secondary-btn" id="toggleFeedBtn">Pause Feed</button>
          <button type="button" class="danger-btn" id="resetBtn">Reset Data</button>
        </div>
      </form>

      <div class="log" id="eventLog" aria-live="polite"></div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const labels = [];
    const dataPoints = [];
    const MAX_POINTS = 20;

    let updateCount = 0;
    let feedRunning = true;
    let chartType = "line";
    let feedInterval = null;

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const updateCountEl = document.getElementById("updateCount");
    const logEl = document.getElementById("eventLog");
    const feedStatusEl = document.getElementById("feedStatus");

    function logMessage(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(item);
    }

    function getAverage(arr) {
      if (!arr.length) return 0;
      return (arr.reduce((sum, val) => sum + val, 0) / arr.length).toFixed(2);
    }

    const chart = new Chart(ctx, {
      type: chartType,
      data: {
        labels: labels,
        datasets: [{
          label: "Sensor Value",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.2)",
          tension: 0.35,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        }
      }
    });

    function updateChart(value) {
      const timeLabel = new Date().toLocaleTimeString();

      labels.push(timeLabel);
      dataPoints.push(value);

      if (labels.length > MAX_POINTS) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();

      currentValueEl.textContent = value;
      averageValueEl.textContent = getAverage(dataPoints);
      updateCountEl.textContent = ++updateCount;

      if (value >= Number(document.getElementById("threshold").value)) {
        logMessage(`Alert: value ${value} exceeded threshold!`);
      } else {
        logMessage(`New value received: ${value}`);
      }
    }

    function generateRandomValue() {
      return Math.floor(Math.random() * 100);
    }

    function startFeed() {
      if (feedInterval) clearInterval(feedInterval);

      feedInterval = setInterval(() => {
        if (!feedRunning) return;
        updateChart(generateRandomValue());
      }, 1000);

      logMessage("Live feed started.");
      feedStatusEl.textContent = "Live feed running";
    }

    function pauseFeed() {
      feedRunning = false;
      feedStatusEl.textContent = "Feed paused";
      logMessage("Live feed paused.");
    }

    function resumeFeed() {
      feedRunning = true;
      feedStatusEl.textContent = "Live feed running";
      logMessage("Live feed resumed.");
    }

    document.getElementById("dashboardForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const threshold = document.getElementById("threshold").value;
      const mode = document.getElementById("mode").value;
      const notes = document.getElementById("notes").value.trim();

      chart.config.type = mode;
      chartType = mode;

      // Rebuild dataset for chart type changes
      chart.destroy();
      const newCtx = document.getElementById("liveChart").getContext("2d");
      window.liveChartInstance = new Chart(newCtx, {
        type: chartType,
        data: {
          labels: labels,
          datasets: [{
            label: "Sensor Value",
            data: dataPoints,
            borderColor: "#38bdf8",
            backgroundColor: chartType === "bar" ? "#38bdf8" : "rgba(56, 189, 248, 0.2)",
            tension: 0.35,
            fill: chartType === "line"
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          plugins: {
            legend: {
              labels: { color: "#e5e7eb" }
            }
          },
          scales: {
            x: {
              ticks: { color: "#9ca3af" },
              grid: { color: "rgba(51, 65, 85, 0.4)" }
            },
            y: {
              ticks: { color: "#9ca3af" },
              grid: { color: "rgba(51, 65, 85, 0.4)" }
            }
          }
        }
      });

      logMessage(
        `Settings saved by ${name}. Threshold=${threshold}, Mode=${mode}, Notes="${notes || "none"}"`
      );
    });

    document.getElementById("toggleFeedBtn").addEventListener("click", (e) => {
      if (feedRunning) {
        pauseFeed();
        e.target.textContent = "Resume Feed";
      } else {
        resumeFeed();
        e.target.textContent = "Pause Feed";
      }
    });

    document.getElementById("resetBtn").addEventListener("click", () => {
      labels.length = 0;
      dataPoints.length = 0;
      updateCount = 0;

      chart.destroy();
      const newCtx = document.getElementById("liveChart").getContext("2d");
      window.liveChartInstance = new Chart(newCtx, {
        type: chartType,
        data: {
          labels: labels,
          datasets: [{
            label: "Sensor Value",
            data: dataPoints,
            borderColor: "#38bdf8",
            backgroundColor: chartType === "bar" ? "#38bdf8" : "rgba(56, 189, 248, 0.2)",
            tension: 0.35,
            fill: chartType === "line"
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          plugins: {
            legend: {
              labels: { color: "#e5e7eb" }
            }
          },
          scales: {
            x: {
              ticks: { color: "#9ca3af" },
              grid: { color: "rgba(51, 65, 85, 0.4)" }
            },
            y: {
              ticks: { color: "#9ca3af" },
              grid: { color: "rgba(51, 65, 85, 0.4)" }
            }
          }
        }
      });

      currentValueEl.textContent = "0";
      averageValueEl.textContent = "0";
      updateCountEl.textContent = "0";
      logMessage("Dashboard data reset.");
    });

    startFeed();
  </script>
</body>
</html>
