    function updateCards() {
      const latestVisits = dataSets.visits.at(-1) ?? 0;
      const latestSignups = dataSets.signups.at(-1) ?? 0;
      const latestPurchases = dataSets.purchases.at(-1) ?? 0;
      const latestCustom = dataSets.custom.at(-1) ?? 0;

      el("visitsValue").textContent = latestVisits;
