      const prevVisits = dataSets.visits.at(-2) ?? latestVisits;
      const prevSignups = dataSets.signups.at(-2) ?? latestSignups;
      const prevPurchases = dataSets.purchases.at(-2) ?? latestPurchases;

      const pct = (current, prev) => {
        if (prev === 0) return current === 0 ? 0 : 100;
        return Math.round(((current - prev) / prev) * 100);
      };

      el("visitsTrend").textContent = `${pct(latestVisits, prevVisits) >= 0 ? "+" : ""}${pct(latestVisits, prevVisits)}% vs previous`;
      el("signupsTrend").textContent = `${pct(latestSignups, prevSignups) >= 0 ? "+" : ""}${pct(latestSignups, prevSignups)}% vs previous`;
      el("purchasesTrend").textContent = `${pct(latestPurchases, prevPurchases) >= 0 ? "+" : ""}${pct(latestPurchases, prevPurchases)}% vs previous`;

      if (latestCustom > 0) {
        el("customTrend").textContent = "Custom metric updated";
        el("customTrend").classList.remove("muted");
      }
    }

    function applyFilter() {
      const subtitle = el("chartSubtitle");
      const datasets = chart.data.datasets;

      datasets.forEach(ds => ds.hidden = false);

      if (filterMetric !== "all") {
        datasets.forEach(ds => {
          ds.hidden = ds.label.toLowerCase() !== filterMetric;
        });
        subtitle.textContent = `Showing ${filterMetric} only`;
      } else {
        subtitle.textContent = "Showing all metrics";
      }

      chart.update();
    }

    function pushDataPoint(metric, value) {
      if (!labels.length || labels.length > 30) {
        labels.push(`T${tick}`);
        Object.values(dataSets).forEach(arr => arr.push(null));
      } else {
        labels.push(`T${tick}`);
      }

      if (labels.length > 30) {
        labels.shift();
        Object.values(dataSets).forEach(arr => arr.shift());
      }

      dataSets.visits[dataSets.visits.length - 1] = metric === "visits" ? value : (dataSets.visits.at(-1) ?? 0);
      dataSets.signups[dataSets.signups.length - 1] = metric === "signups" ? value : (dataSets.signups.at(-1) ?? 0);
      dataSets.purchases[dataSets.purchases.length - 1] = metric === "purchases" ? value : (dataSets.purchases.at(-1) ?? 0);
      dataSets.custom[dataSets.custom.length - 1] = metric === "custom" ? value : (dataSets.custom.at(-1) ?? 0);

      chart.update();
      updateCards();
      applyFilter();
    }

    function simulateStream() {
      if (!streaming) return;

      tick++;
      const visits = Math.floor(100 + Math.random() * 80);
      const signups = Math.floor(10 + Math.random() * 20);
      const purchases = Math.floor(3 + Math.random() * 10);

      pushDataPoint("visits", visits);
      pushDataPoint("signups", signups);
      pushDataPoint("purchases", purchases);

      log(`Stream update: visits=${visits}, signups=${signups}, purchases=${purchases}`);
    }

    el("streamToggle").addEventListener("click", () => {
      streaming = !streaming;
      el("streamToggle").textContent = streaming ? "Pause Stream" : "Resume Stream";
      log(streaming ? "Streaming resumed" : "Streaming paused");
    });

    el("chartType").addEventListener("change", (e) => {
      chartType = e.target.value;
      chart.config.type = chartType;
      chart.update();
      log(`Chart type changed to ${chartType}`);
    });

    el("filterMetric").addEventListener("change", (e) => {
      filterMetric = e.target.value;
      applyFilter();
      log(`Filter set to ${filterMetric}`);
    });

    el("addDataBtn").addEventListener("click", () => {
      const metric = el("manualMetric").value.trim().toLowerCase();
      const value = Number(el("manualValue").value);

      if (!metric || Number.isNaN(value)) {
        alert("Please enter both a metric name and a numeric value.");
        return;
      }

      tick++;
      if (!dataSets[metric]) {
        dataSets[metric] = [];
        chart.data.datasets.push({
          label: metric.charAt(0).toUpperCase() + metric.slice(1),
          data: dataSets[metric],
          borderColor: "#f472b6",
          backgroundColor: "rgba(244, 114, 182, 0.2)",
          tension: 0.3,
          fill: true
        });
      }

      if (!labels.length || labels.length > 30) {
        labels.push(`T${tick}`);
        Object.values(dataSets).forEach(arr => arr.push(null));
      } else {
        labels.push(`T${tick}`);
      }

      if (labels.length > 30) {
        labels.shift();
        Object.values(dataSets).forEach(arr => arr.shift());
      }

      dataSets[metric][dataSets[metric].length - 1] = value;

      chart.update();
      updateCards();
      applyFilter();

      log(`Manual data added: ${metric}=${value}`);

      el("manualMetric").value = "";
      el("manualValue").value = "";
    });

    el("resetBtn").addEventListener("click", () => {
      labels.length = 0;
      Object.keys(dataSets).forEach(k => dataSets[k].length = 0);
      chart.data.datasets = chart.data.datasets.filter(ds => ["Visits", "Signups", "Purchases", "Custom"].includes(ds.label));
      tick = 0;
      el("activityLog").innerHTML = "";
      updateCards();
      chart.update();
      applyFilter();
      log("Dashboard reset");
    });

    // Initial data
    for (let i = 0; i < 5; i++) {
      simulateStream();
    }

    // Real-time stream
    setInterval(simulateStream, 2000);
    updateCards();
    applyFilter();
    log("Dashboard initialized");
  </script>
</body>
</html>
