  <header>
    <h1>Real-Time Operations Dashboard</h1>
    <p>Live metrics, interactive form handling, and real-time updates.</p>
  </header>

  <main class="container">
    <section class="panel">
      <h2>Live Analytics</h2>

      <div class="stats">
        <div class="stat-card">
          <div class="label">Active Users</div>
          <div class="value" id="activeUsers">0</div>
        </div>
        <div class="stat-card">
          <div class="label">Requests / Min</div>
          <div class="value" id="requestsPerMin">0</div>
        </div>
        <div class="stat-card">
          <div class="label">Error Rate</div>
          <div class="value" id="errorRate">0%</div>
        </div>
      </div>

      <div class="controls">
        <select id="metricFilter">
          <option value="all">All Metrics</option>
          <option value="users">Users</option>
          <option value="requests">Requests</option>
          <option value="errors">Errors</option>
        </select>

        <button class="secondary" id="toggleStreamBtn">Pause Stream</button>
        <button class="secondary" id="resetBtn">Reset Data</button>
