      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>

      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Event</th>
              <th>Value</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody id="eventTable"></tbody>
        </table>
      </div>
    </section>

    <aside class="panel">
      <h2>Add New Event</h2>
      <form id="eventForm">
        <div class="form-grid">
          <input type="text" id="eventName" placeholder="Event name" required />
          <input type="number" id="eventValue" placeholder="Value" required min="0" />
        </div>

        <div class="form-grid">
          <select id="eventType" required>
            <option value="users">User Event</option>
            <option value="requests">Request Event</option>
            <option value="errors">Error Event</option>
          </select>

          <select id="eventStatus" required>
            <option value="ok">OK</option>
            <option value="warn">Warning</option>
            <option value="err">Error</option>
          </select>
        </div>

        <div class="form-actions">
          <button type="submit">Add Event</button>
          <button type="button" class="secondary" id="autoFillBtn">Auto Fill</button>
        </div>

        <p class="muted">Submitting the form updates the chart and table immediately.</p>
      </form>
