  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = [];
    const usersData = [];
    const requestsData = [];
    const errorsData = [];

    const maxPoints = 20;
    let streaming = true;
    let currentFilter = 'all';

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [
          {
            label: 'Active Users',
            data: usersData,
            borderColor: '#38bdf8',
            backgroundColor: 'rgba(56, 189, 248, 0.15)',
            tension: 0.35,
            fill: true
          },
          {
            label: 'Requests / Min',
            data: requestsData,
            borderColor: '#22c55e',
            backgroundColor: 'rgba(34, 197, 94, 0.15)',
            tension: 0.35,
            fill: true
          },
          {
            label: 'Errors',
            data: errorsData,
            borderColor: '#ef4444',
            backgroundColor: 'rgba(239, 68, 68, 0.15)',
            tension: 0.35,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById('activeUsers');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const eventTable = document.getElementById('eventTable');

    const metricFilter = document.getElementById('metricFilter');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');
    const resetBtn = document.getElementById('resetBtn');
    const eventForm = document.getElementById('eventForm');
    const autoFillBtn = document.getElementById('autoFillBtn');

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function getRandomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateStats() {
      const lastUsers = usersData.at(-1) ?? 0;
      const lastRequests = requestsData.at(-1) ?? 0;
      const lastErrors = errorsData.at(-1) ?? 0;

      activeUsersEl.textContent = lastUsers;
      requestsPerMinEl.textContent = lastRequests;
      errorRateEl.textContent = `${Math.min(100, lastErrors)}%`;
    }

    function addTableRow(eventName, value, status) {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${nowTime()}</td>
        <td>${eventName}</td>
        <td>${value}</td>
        <td><span class="badge ${status}">${status.toUpperCase()}</span></td>
      `;
      eventTable.prepend(row);

      // keep only latest 10 rows
      while (eventTable.children.length > 10) {
        eventTable.removeChild(eventTable.lastChild);
      }
    }

    function pushDataPoint(users, requests, errors, label) {
      labels.push(label);
      usersData.push(users);
      requestsData.push(requests);
      errorsData.push(errors);

      if (labels.length > maxPoints) {
        labels.shift();
        usersData.shift();
        requestsData.shift();
        errorsData.shift();
      }

      applyFilter();
      chart.update();
      updateStats();
    }

    function applyFilter() {
      const filter = currentFilter;

      chart.data.datasets[0].hidden = !(filter === 'all' || filter === 'users');
      chart.data.datasets[1].hidden = !(filter === 'all' || filter === 'requests');
      chart.data.datasets[2].hidden = !(filter === 'all' || filter === 'errors');
    }

    function seedInitialData() {
      for (let i = 0; i < 10; i++) {
        pushDataPoint(
          getRandomInt(40, 120),
          getRandomInt(80, 200),
          getRandomInt(0, 10),
          `T-${10 - i}`
        );
      }
    }

    function simulateStream() {
      if (!streaming) return;

      pushDataPoint(
        getRandomInt(40, 140),
        getRandomInt(70, 220),
        getRandomInt(0, 12),
        nowTime()
      );

      addTableRow('Auto Stream', 'Live update', 'ok');
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const eventName = document.getElementById('eventName').value.trim();
      const eventValue = Number(document.getElementById('eventValue').value);
      const eventType = document.getElementById('eventType').value;
      const eventStatus = document.getElementById('eventStatus').value;

      if (!eventName || Number.isNaN(eventValue)) return;

      const latestUsers = usersData.at(-1) ?? 0;
      const latestRequests = requestsData.at(-1) ?? 0;
      const latestErrors = errorsData.at(-1) ?? 0;

      if (eventType === 'users') {
        pushDataPoint(eventValue, latestRequests, latestErrors, nowTime());
      } else if (eventType === 'requests') {
        pushDataPoint(latestUsers, eventValue, latestErrors, nowTime());
      } else if (eventType === 'errors') {
        pushDataPoint(latestUsers, latestRequests, eventValue, nowTime());
      }

      addTableRow(eventName, eventValue, eventStatus);
      eventForm.reset();
    });

    metricFilter.addEventListener('change', (e) => {
      currentFilter = e.target.value;
      applyFilter();
      chart.update();
    });

    toggleStreamBtn.addEventListener('click', () => {
      streaming = !streaming;
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
    });

    resetBtn.addEventListener('click', () => {
      labels.length = 0;
      usersData.length = 0;
      requestsData.length = 0;
      errorsData.length = 0;
      eventTable.innerHTML = '';
      seedInitialData();
      chart.update();
      updateStats();
    });

    autoFillBtn.addEventListener('click', () => {
      document.getElementById('eventName').value = 'Synthetic Event';
      document.getElementById('eventValue').value = getRandomInt(10, 150);
      document.getElementById('eventType').value = ['users', 'requests', 'errors'][getRandomInt(0, 2)];
      document.getElementById('eventStatus').value = ['ok', 'warn', 'err'][getRandomInt(0, 2)];
    });

    seedInitialData();
    updateStats();
    setInterval(simulateStream, 2000);
  </script>
</body>
</html>
