<body>
  <div class="container">
    <header>
      <div>
        <h1>Real-Time Analytics Dashboard</h1>
        <p style="margin:6px 0 0; color: var(--muted);">Live metrics, chart updates, and form submission handling</p>
      </div>
      <div class="status">
        <span class="status-dot"></span>
        Live feed active
      </div>
    </header>

    <section class="grid">
      <div class="card metric">
        <h3>Active Users</h3>
        <p class="value" id="activeUsers">1,248</p>
        <div class="delta up" id="activeUsersDelta">+4.2% from last minute</div>
      </div>

      <div class="card metric">
        <h3>Requests / Min</h3>
        <p class="value" id="requestsPerMin">8,430</p>
        <div class="delta up" id="requestsDelta">+2.1% from last minute</div>
      </div>

      <div class="card metric">
        <h3>Error Rate</h3>
        <p class="value" id="errorRate">0.8%</p>
        <div class="delta down" id="errorDelta">-0.3% from last minute</div>
      </div>

      <div class="card metric">
        <h3>Avg. Response</h3>
        <p class="value" id="avgResponse">214ms</p>
        <div class="delta down" id="responseDelta">-18ms from last minute</div>
      </div>

      <div class="card chart-card">
        <h2>Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="card form-card">
        <h2>Submit Alert</h2>
        <form id="alertForm" novalidate>
          <label>
            Alert Name
            <input type="text" id="alertName" placeholder="e.g. High CPU Usage" />
          </label>
          <div class="error" id="nameError"></div>

          <label>
            Severity
            <select id="severity">
              <option value="">Select severity</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
          </label>
          <div class="error" id="severityError"></div>

          <label>
            Details
            <textarea id="details" placeholder="Describe the issue..."></textarea>
          </label>
          <div class="error" id="detailsError"></div>

          <button type="submit">Send Alert</button>
          <div class="success" id="formSuccess"></div>
        </form>
      </div>

      <div class="card log-card">
        <h2>Event Log</h2>
        <ul class="log-list" id="logList"></ul>
      </div>
    </section>
  </div>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const avgResponseEl = document.getElementById("avgResponse");

    const activeUsersDeltaEl = document.getElementById("activeUsersDelta");
    const requestsDeltaEl = document.getElementById("requestsDelta");
    const errorDeltaEl = document.getElementById("errorDelta");
    const responseDeltaEl = document.getElementById("responseDelta");

    const logList = document.getElementById("logList");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const dataPoints = labels.map(() => Math.floor(600 + Math.random() * 500));

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.12)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        }
      }
    });

    function formatNumber(n) {
      return new Intl.NumberFormat().format(n);
    }

    function addLog(message, type = "info") {
      const li = document.createElement("li");
      li.className = "log-item";
      const time = new Date().toLocaleTimeString();
      li.innerHTML = `
        <span>${message}</span>
        <small>${time}</small>
      `;
      logList.prepend(li);

      while (logList.children.length > 8) {
        logList.removeChild(logList.lastChild);
      }
    }

    function updateMetrics() {
      const activeUsers = 1100 + Math.floor(Math.random() * 400);
      const requests = 7800 + Math.floor(Math.random() * 1800);
      const errorRate = (0.4 + Math.random() * 1.2).toFixed(1);
      const response = 180 + Math.floor(Math.random() * 90);

      activeUsersEl.textContent = formatNumber(activeUsers);
      requestsPerMinEl.textContent = formatNumber(requests);
      errorRateEl.textContent = `${errorRate}%`;
      avgResponseEl.textContent = `${response}ms`;

      const activeDelta = (Math.random() * 6 - 1).toFixed(1);
      const requestDelta = (Math.random() * 5 - 0.5).toFixed(1);
      const errorDelta = (Math.random() * 0.8 - 0.4).toFixed(1);
      const responseDelta = Math.floor(Math.random() * 30 - 20);

      activeUsersDeltaEl.textContent = `${activeDelta > 0 ? "+" : ""}${activeDelta}% from last minute`;
      requestsDeltaEl.textContent = `${requestDelta > 0 ? "+" : ""}${requestDelta}% from last minute`;
      errorDeltaEl.textContent = `${errorDelta > 0 ? "+" : ""}${errorDelta}% from last minute`;
      responseDeltaEl.textContent = `${responseDelta > 0 ? "+" : ""}${responseDelta}ms from last minute`;

      activeUsersDeltaEl.className = `delta ${activeDelta >= 0 ? "up" : "down"}`;
      requestsDeltaEl.className = `delta ${requestDelta >= 0 ? "up" : "down"}`;
      errorDeltaEl.className = `delta ${errorDelta >= 0 ? "up" : "down"}`;
      responseDeltaEl.className = `delta ${responseDelta >= 0 ? "up" : "down"}`;
    }

    function updateChart() {
      const newValue = Math.floor(600 + Math.random() * 500);
      trafficChart.data.datasets[0].data.shift();
      trafficChart.data.datasets[0].data.push(newValue);
      trafficChart.update();
    }

    function simulateFeed() {
      updateMetrics();
      updateChart();
      addLog(`Live traffic updated: ${trafficChart.data.datasets[0].data.at(-1)} req/s`);
    }

    setInterval(simulateFeed, 3000);

    // Form handling
    const form = document.getElementById("alertForm");
    const alertName = document.getElementById("alertName");
    const severity = document.getElementById("severity");
    const details = document.getElementById("details");

    const nameError = document.getElementById("nameError");
    const severityError = document.getElementById("severityError");
    const detailsError = document.getElementById("detailsError");
    const formSuccess = document.getElementById("formSuccess");

    function clearErrors() {
      nameError.textContent = "";
      severityError.textContent = "";
      detailsError.textContent = "";
      formSuccess.textContent = "";
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      let valid = true;

      if (alertName.value.trim().length < 3) {
        nameError.textContent = "Alert name must be at least 3 characters.";
        valid = false;
      }

      if (!severity.value) {
        severityError.textContent = "Please select a severity.";
        valid = false;
      }

      if (details.value.trim().length < 10) {
        detailsError.textContent = "Please provide at least 10 characters of details.";
        valid = false;
      }

      if (!valid) return;

      const payload = {
        name: alertName.value.trim(),
        severity: severity.value,
        details: details.value.trim(),
        timestamp: new Date().toISOString()
      };

      formSuccess.textContent = "Alert submitted successfully.";
      addLog(`Alert submitted: ${payload.name} [${payload.severity}]`);

      // Simulate async submission
      console.log("Submitted payload:", payload);

      form.reset();
    });

    // Initial log
    addLog("Dashboard initialized");
    updateMetrics();
  </script>
</body>
</html>
```

