  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const completionRateEl = document.getElementById("completionRate");
    const itemListEl = document.getElementById("itemList");
    const itemCountEl = document.getElementById("itemCount");
    const activityFeedEl = document.getElementById("activityFeed");
    const form = document.getElementById("itemForm");
    const formStatus = document.getElementById("formStatus");
    const searchInput = document.getElementById("searchInput");
    const filterSelect = document.getElementById("filterSelect");
    const resetBtn = document.getElementById("resetBtn");
    const canvas = document.getElementById("lineChart");
    const ctx = canvas.getContext("2d");

    let items = [
      { id: 1, title: "Deploy API", status: "in-progress", description: "Release the new backend service.", createdAt: new Date() },
      { id: 2, title: "Design landing page", status: "new", description: "Create a responsive hero section.", createdAt: new Date() },
      { id: 3, title: "QA regression test", status: "done", description: "Verify core workflows after update.", createdAt: new Date() }
    ];

    let metrics = {
      activeUsers: 128,
      requestsPerMin: 420
    };

    let chartData = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100) + 50);

    function formatTime(date) {
      return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function updateMetrics() {
      metrics.activeUsers += Math.floor(Math.random() * 7 - 3);
      metrics.requestsPerMin += Math.floor(Math.random() * 20 - 10);

      metrics.activeUsers = Math.max(0, metrics.activeUsers);
      metrics.requestsPerMin = Math.max(0, metrics.requestsPerMin);

      activeUsersEl.textContent = metrics.activeUsers;
      requestsPerMinEl.textContent = metrics.requestsPerMin;

      const completed = items.filter(item => item.status === "done").length;
      const completionRate = items.length ? Math.round((completed / items.length) * 100) : 0;
      completionRateEl.textContent = `${completionRate}%`;

      chartData.push(metrics.requestsPerMin);
      if (chartData.length > 20) chartData.shift();
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 30;
      const width = canvas.width - padding * 2;
      const height = canvas.height - padding * 2;

      const maxVal = Math.max(...chartData, 100);
      const minVal = Math.min(...chartData, 0);
      const range = maxVal - minVal || 1;

      // grid
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = padding + (height / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(padding + width, y);
        ctx.stroke();
      }

      // line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      chartData.forEach((value, index) => {
        const x = padding + (width / (chartData.length - 1)) * index;
        const y = padding + height - ((value - minVal) / range) * height;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // fill
      ctx.lineTo(padding + width, padding + height);
      ctx.lineTo(padding, padding + height);
      ctx.closePath();
      ctx.fillStyle = "rgba(56, 189, 248, 0.12)";
      ctx.fill();

      // points
      chartData.forEach((value, index) => {
        const x = padding + (width / (chartData.length - 1)) * index;
        const y = padding + height - ((value - minVal) / range) * height;

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = "#7dd3fc";
        ctx.fill();
      });
    }

    function addActivity(message, type = "info") {
      const item = document.createElement("div");
      item.className = "item";
      item.innerHTML = `
        <div>
          <strong>${message}</strong>
          <small>${formatTime(new Date())}</small>
        </div>
        <span class="badge">${type}</span>
      `;
      activityFeedEl.prepend(item);

      while (activityFeedEl.children.length > 6) {
        activityFeedEl.removeChild(activityFeedEl.lastChild);
      }
    }

    function renderItems() {
      const query = searchInput.value.toLowerCase().trim();
      const filter = filterSelect.value;

      const filtered = items.filter(item => {
        const matchesSearch =
          item.title.toLowerCase().includes(query) ||
          item.description.toLowerCase().includes(query);
        const matchesFilter = filter === "all" || item.status === filter;
        return matchesSearch && matchesFilter;
      });

      itemListEl.innerHTML = "";

      filtered.forEach(item => {
        const el = document.createElement("div");
        el.className = "item";
        el.innerHTML = `
          <div>
            <strong>${item.title}</strong>
            <small>${item.description}</small>
          </div>
          <span class="badge">${item.status}</span>
        `;
        itemListEl.appendChild(el);
      });

      itemCountEl.textContent = `${filtered.length} item${filtered.length !== 1 ? "s" : ""}`;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const title = document.getElementById("title").value.trim();
      const status = document.getElementById("status").value;
      const description = document.getElementById("description").value.trim();

      if (!title || !description) {
        formStatus.textContent = "Please fill in all fields.";
        formStatus.className = "status error";
        return;
      }

      const newItem = {
        id: Date.now(),
        title,
        status,
        description,
        createdAt: new Date()
      };

      items.unshift(newItem);
      renderItems();
      updateMetrics();

      form.reset();
      formStatus.textContent = "Item added successfully.";
      formStatus.className = "status success";

      addActivity(`Added item: ${title}`, "created");
    });

    searchInput.addEventListener("input", renderItems);
    filterSelect.addEventListener("change", renderItems);

    resetBtn.addEventListener("click", () => {
      searchInput.value = "";
      filterSelect.value = "all";
      renderItems();
      formStatus.textContent = "Filters reset.";
      formStatus.className = "status";
    });

    // Initial render
    renderItems();
    updateMetrics();
    drawChart();
    addActivity("Dashboard initialized", "system");

    // Real-time updates
    setInterval(() => {
      updateMetrics();
      renderItems();
      drawChart();

      // occasional activity
      if (Math.random() > 0.75) {
        const actions = [
          "User joined the dashboard",
          "New request received",
          "Task status updated",
          "Background sync completed"
        ];
        addActivity(actions[Math.floor(Math.random() * actions.length)], "live");
      }
    }, 1000);

    // Resize canvas for crisp rendering
    function resizeCanvasForDPR() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = Math.round(rect.width * dpr);
      canvas.height = Math.round(rect.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    window.addEventListener("resize", resizeCanvasForDPR);
    setTimeout(resizeCanvasForDPR, 50);
  </script>
</body>
</html>
