  <script>
    const ctx = document.getElementById("realtimeChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const chartData = {
      traffic: labels.map(() => Math.floor(Math.random() * 100) + 50),
      errors: labels.map(() => Math.floor(Math.random() * 10)),
      latency: labels.map(() => Math.floor(Math.random() * 300) + 100)
    };

    let currentMode = "traffic";

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: chartData.traffic,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        }
      }
    });

    function updateChart(mode) {
      currentMode = mode;
      chart.data.datasets[0].label =
        mode.charAt(0).toUpperCase() + mode.slice(1);
      chart.data.datasets[0].data = chartData[mode];

      const colors = {
        traffic: "#38bdf8",
        errors: "#ef4444",
        latency: "#f59e0b"
      };

      chart.data.datasets[0].borderColor = colors[mode];
      chart.data.datasets[0].backgroundColor = hexToRgba(colors[mode], 0.15);
      chart.update();

      document.getElementById("chartStatus").textContent =
        `Showing ${mode} data`;
    }

    function hexToRgba(hex, alpha) {
      const r = parseInt(hex.slice(1, 3), 16);
      const g = parseInt(hex.slice(3, 5), 16);
      const b = parseInt(hex.slice(5, 7), 16);
      return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }

    function pushNewData() {
      Object.keys(chartData).forEach((key) => {
        chartData[key].shift();

        if (key === "traffic") {
          chartData[key].push(Math.floor(Math.random() * 100) + 50);
        } else if (key === "errors") {
          chartData[key].push(Math.floor(Math.random() * 10));
        } else {
          chartData[key].push(Math.floor(Math.random() * 300) + 100);
        }
      });

      if (currentMode) updateChart(currentMode);

      // Update metrics
      const activeUsers = 1200 + Math.floor(Math.random() * 120);
      const requests = 8200 + Math.floor(Math.random() * 300);
      const errors = (Math.random() * 1.2).toFixed(1);
      const latency = 190 + Math.floor(Math.random() * 60);

      document.getElementById("activeUsers").textContent = activeUsers.toLocaleString();
      document.getElementById("requestsPerMin").textContent = requests.toLocaleString();
      document.getElementById("errorRate").textContent = `${errors}%`;
      document.getElementById("latency").textContent = `${latency} ms`;

      document.getElementById("activeUsersDelta").textContent =
        `${Math.random() > 0.5 ? "+" : "-"}${(Math.random() * 5).toFixed(1)}% from last minute`;
      document.getElementById("requestsDelta").textContent =
        `${Math.random() > 0.5 ? "+" : "-"}${(Math.random() * 3).toFixed(1)}% from last minute`;
      document.getElementById("errorDelta").textContent =
        errors < 1 ? "Stable" : "Slight increase detected";
      document.getElementById("latencyDelta").textContent =
        `${Math.floor(Math.random() * 20) - 5} ms from last minute`;
    }

    setInterval(pushNewData, 1000);

    document.querySelectorAll(".controls button").forEach((btn) => {
      btn.addEventListener("click", () => {
        document.querySelectorAll(".controls button").forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        updateChart(btn.dataset.mode);
      });
    });

    const form = document.getElementById("eventForm");
    const logList = document.getElementById("logList");

    function addLogItem(name, category, value, notes) {
      const li = document.createElement("li");
      li.className = "log-item";
      li.innerHTML = `
        <div>
          <strong>${name}</strong> <span style="color:#94a3b8">(${category})</span><br />
          <span style="color:#cbd5e1">Value: ${value}</span>
          ${notes ? `<div style="margin-top:4px;color:#94a3b8">${notes}</div>` : ""}
        </div>
        <small>${new Date().toLocaleTimeString()}</small>
      `;
      logList.prepend(li);
    }

    function clearErrors() {
      ["nameError", "categoryError", "valueError", "formSuccess"].forEach(id => {
        document.getElementById(id).textContent = "";
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const value = document.getElementById("value").value.trim();
      const notes = document.getElementById("notes").value.trim();

      let valid = true;

      if (!name) {
        document.getElementById("nameError").textContent = "Event name is required.";
        valid = false;
      }

      if (!category) {
        document.getElementById("categoryError").textContent = "Please select a category.";
        valid = false;
      }

      if (value === "" || isNaN(value)) {
        document.getElementById("valueError").textContent = "Please enter a valid number.";
        valid = false;
      }

      if (!valid) return;

      addLogItem(name, category, value, notes);
      document.getElementById("formSuccess").textContent = "Event submitted successfully!";
      form.reset();
    });

    // Initial log items
    addLogItem("System Boot", "system", "1", "Dashboard initialized");
    addLogItem("API Sync", "system", "24", "Connected to live feed");
    addLogItem("Signup", "conversion", "12", "Campaign A");

    updateChart(currentMode);
  </script>
</body>
