      <h2>Quick Action Form</h2>
      <form id="actionForm">
        <label>
          Action Type
          <select id="actionType" required>
            <option value="">Select action</option>
            <option value="email">Send Email</option>
            <option value="report">Generate Report</option>
            <option value="alert">Create Alert</option>
          </select>
        </label>

        <label>
          Target
          <input type="text" id="target" placeholder="Enter target name or email" required />
        </label>

        <label>
          Notes
          <textarea id="notes" rows="4" placeholder="Optional notes"></textarea>
        </label>

        <button type="submit">Submit Action</button>
      </form>

      <div id="formStatus" class="status"></div>
    </section>

    <section class="card chart-card">
      <h2>Real-Time Traffic Chart</h2>
      <canvas id="trafficChart"></canvas>
    </section>

    <section class="card">
      <h2>Event Feed</h2>
      <div id="eventFeed" class="feed"></div>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const ordersPerMinEl = document.getElementById("ordersPerMin");
    const serverLoadEl = document.getElementById("serverLoad");
    const revenueEl = document.getElementById("revenue");
    const eventFeedEl = document.getElementById("eventFeed");
    const formStatusEl = document.getElementById("formStatus");

    const labels = [];
    const trafficData = [];

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function formatCurrency(value) {
      return "$" + value.toLocaleString();
    }

    function updateMetrics() {
      const activeUsers = randomInt(120, 1200);
      const ordersPerMin = randomInt(5, 80);
      const serverLoad = randomInt(20, 98);
      const revenue = randomInt(1000, 50000);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      ordersPerMinEl.textContent = ordersPerMin;
      serverLoadEl.textContent = serverLoad + "%";
      revenueEl.textContent = formatCurrency(revenue);

      addFeedItem(
        `Metrics updated: ${activeUsers} users, ${ordersPerMin} orders/min, ${serverLoad}% load, ${formatCurrency(revenue)} revenue`
      );
    }

    function updateChart() {
      const now = new Date().toLocaleTimeString();
      const value = randomInt(50, 200);

      if (labels.length >= 12) {
        labels.shift();
        trafficData.shift();
      }

      labels.push(now);
      trafficData.push(value);
      trafficChart.update();
    }

    function addFeedItem(message) {
      const item = document.createElement("div");
      item.className = "feed-item";
      item.innerHTML = `
        ${message}
        <small>${new Date().toLocaleString()}</small>
      `;
      eventFeedEl.prepend(item);

      // keep feed manageable
      while (eventFeedEl.children.length > 8) {
        eventFeedEl.removeChild(eventFeedEl.lastChild);
      }
    }

    document.getElementById("actionForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const actionType = document.getElementById("actionType").value;
      const target = document.getElementById("target").value.trim();
      const notes = document.getElementById("notes").value.trim();

      if (!actionType || !target) {
        formStatusEl.style.display = "block";
        formStatusEl.style.background = "rgba(239, 68, 68, 0.12)";
        formStatusEl.style.color = "#fca5a5";
        formStatusEl.style.borderColor = "rgba(239, 68, 68, 0.3)";
        formStatusEl.textContent = "Please fill in all required fields.";
        return;
      }

      formStatusEl.style.display = "block";
      formStatusEl.style.background = "rgba(34, 197, 94, 0.12)";
      formStatusEl.style.color = "#86efac";
      formStatusEl.style.borderColor = "rgba(34, 197, 94, 0.3)";
      formStatusEl.textContent = `Action "${actionType}" submitted for ${target}.`;

      addFeedItem(
        `Form submitted: ${actionType} for ${target}${notes ? " — " + notes : ""}`
      );

      this.reset();
    });

    // initial load
    updateMetrics();
    updateChart();
    addFeedItem("Dashboard initialized.");

    // simulate real-time updates
    setInterval(updateMetrics, 3000);
    setInterval(updateChart, 1000);
  </script>
</body>
</html>
```

