  <main class="container">
    <section class="card">
      <h2>Live Metrics</h2>

      <div class="stats">
        <div class="stat">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Updates</div>
          <div class="value" id="updateCount">0</div>
        </div>
      </div>

      <div class="controls">
        <select id="timeRange">
          <option value="20">Last 20 points</option>
          <option value="50" selected>Last 50 points</option>
          <option value="100">Last 100 points</option>
        </select>

        <button id="toggleLive">Pause Live Updates</button>
        <button id="resetData" class="danger">Reset Data</button>
      </div>

      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>
    </section>

    <aside class="sidebar">
      <section class="card">
        <h2>Add Data Entry</h2>
        <form id="dataForm">
          <div class="row">
            <input type="text" id="itemName" placeholder="Item name" required />
            <input type="number" id="itemValue" placeholder="Value" required min="0" step="1" />
          </div>
          <button type="submit">Add Item</button>
        </form>
        <p class="small">Submitted items appear in the list below and can be removed individually.</p>
      </section>

      <section class="card">
        <h2>Entries</h2>
        <ul id="entryList"></ul>
      </section>
    </aside>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const updateCountEl = document.getElementById("updateCount");
    const timeRangeEl = document.getElementById("timeRange");
    const toggleLiveBtn = document.getElementById("toggleLive");
    const resetDataBtn = document.getElementById("resetData");

    const dataForm = document.getElementById("dataForm");
    const itemNameEl = document.getElementById("itemName");
    const itemValueEl = document.getElementById("itemValue");
    const entryList = document.getElementById("entryList");

    let labels = [];
    let dataPoints = [];
    let updateCount = 0;
    let liveRunning = true;
    let tick = 0;
    let entries = [];

    function generatePoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1] : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 12 - 6)));
      tick++;
      labels.push(`T${tick}`);
      dataPoints.push(Math.round(next));

      const maxPoints = parseInt(timeRangeEl.value, 10);
      if (labels.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }

      updateCount++;
      refreshStats();
      chart.update();
    }

    function refreshStats() {
      const current = dataPoints[dataPoints.length - 1] ?? 0;
      const avg = dataPoints.length
        ? (dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length).toFixed(1)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      updateCountEl.textContent = updateCount;
    }

    function renderEntries() {
      entryList.innerHTML = "";

      entries.forEach((entry, index) => {
        const li = document.createElement("li");
        li.innerHTML = `
          <div>
            <strong>${entry.name}</strong><br />
            <span class="tag">Value: ${entry.value}</span>
          </div>
          <button data-index="${index}" class="danger">Remove</button>
        `;
        entryList.appendChild(li);
      });

      entryList.querySelectorAll("button").forEach(btn => {
        btn.addEventListener("click", (e) => {
          const idx = Number(e.target.dataset.index);
          entries.splice(idx, 1);
          renderEntries();
        });
      });
    }

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Value",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc",
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 250 },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            min: 0,
            max: 100,
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        }
      }
    });

    timeRangeEl.addEventListener("change", () => {
      const maxPoints = parseInt(timeRangeEl.value, 10);
      while (labels.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }
      chart.update();
      refreshStats();
    });

    toggleLiveBtn.addEventListener("click", () => {
      liveRunning = !liveRunning;
      toggleLiveBtn.textContent = liveRunning ? "Pause Live Updates" : "Resume Live Updates";
    });

    resetDataBtn.addEventListener("click", () => {
      labels = [];
      dataPoints = [];
      updateCount = 0;
      tick = 0;
      chart.update();
      refreshStats();
    });

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = itemNameEl.value.trim();
      const value = Number(itemValueEl.value);

      if (!name || Number.isNaN(value)) return;

      entries.unshift({ name, value });
      renderEntries();

      itemNameEl.value = "";
      itemValueEl.value = "";
    });

    renderEntries();
    refreshStats();

    setInterval(() => {
      if (liveRunning) generatePoint();
    }, 1000);
  </script>
</body>
</html>
