              <option value="100">Last 100 points</option>
            </select>
            <button id="toggleStream">Pause Stream</button>
          </div>
        </div>
        <canvas id="trafficChart"></canvas>
      </div>

      <div class="card panel">
        <h2>Add Record</h2>
        <form id="recordForm" class="form-grid">
          <div class="form-row">
            <div class="form-group">
              <label for="name">Name</label>
              <input id="name" type="text" placeholder="e.g. Alice" required />
            </div>
            <div class="form-group">
              <label for="role">Role</label>
              <select id="role" required>
                <option value="Admin">Admin</option>
                <option value="Analyst">Analyst</option>
                <option value="Operator">Operator</option>
                <option value="Guest">Guest</option>
              </select>
            </div>
          </div>

          <div class="form-row">
            <div class="form-group">
              <label for="score">Score</label>
              <input id="score" type="number" min="0" max="100" value="50" required />
            </div>
            <div class="form-group">
              <label for="status">Status</label>
              <select id="status" required>
                <option value="Online">Online</option>
                <option value="Idle">Idle</option>
                <option value="Offline">Offline</option>
              </select>
            </div>
          </div>

          <button type="submit">Add to Table</button>
        </form>

        <div>
          <div class="chart-header" style="margin-top: 10px;">
            <h2>Records</h2>
            <input id="search" type="text" placeholder="Search records..." />
          </div>

          <div class="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Role</th>
                  <th>Score</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody id="recordsTable"></tbody>
            </table>
          </div>
        </div>

        <div class="footer-note">
          Tip: The dashboard simulates live data locally. You can replace the generator with a WebSocket or API feed.
        </div>
      </div>
    </section>
  </main>

  <script>
    // ----- State -----
    const state = {
      running: true,
      maxPoints: 50,
      labels: [],
      trafficData: [],
      records: [
        { name: "Alice", role: "Admin", score: 92, status: "Online" },
        { name: "Bob", role: "Analyst", score: 68, status: "Idle" },
        { name: "Carol", role: "Operator", score: 41, status: "Offline" },
      ],
    };

    // ----- DOM -----
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const lastUpdateEl = document.getElementById("lastUpdate");
    const recordsTableEl = document.getElementById("recordsTable");
    const searchEl = document.getElementById("search");
    const recordForm = document.getElementById("recordForm");
    const toggleStreamBtn = document.getElementById("toggleStream");
    const timeRangeEl = document.getElementById("timeRange");

    // ----- Chart -----
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels: state.labels,
        datasets: [
          {
            label: "Requests",
            data: state.trafficData,
            borderColor: "#38bdf8",
            backgroundColor: "rgba(56, 189, 248, 0.15)",
            tension: 0.35,
            fill: true,
            pointRadius: 2,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" },
          },
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" },
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" },
          },
        },
      },
    });

    // ----- Helpers -----
    function getTimeString() {
      return new Date().toLocaleTimeString();
    }

    function getBadgeClass(score) {
      if (score >= 75) return "ok";
      if (score >= 50) return "mid";
      return "low";
    }

    function renderRecords() {
      const query = searchEl.value.trim().toLowerCase();
      const filtered = state.records.filter((r) =>
        [r.name, r.role, r.status, String(r.score)].some((v) =>
          v.toLowerCase().includes(query)
        )
      );

      recordsTableEl.innerHTML = filtered
        .map(
          (r) => `
            <tr>
              <td>${escapeHtml(r.name)}</td>
              <td>${escapeHtml(r.role)}</td>
              <td>${r.score}</td>
              <td><span class="badge ${getBadgeClass(r.score)}">${escapeHtml(r.status)}</span></td>
            </tr>
          `
        )
        .join("");
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function updateStats() {
      const activeUsers = Math.floor(120 + Math.random() * 80);
      const requestsPerMin = Math.floor(300 + Math.random() * 500);
      const errorRate = (Math.random() * 5).toFixed(1);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;
      lastUpdateEl.textContent = getTimeString();
    }

    function updateChart() {
      const nextValue = Math.floor(50 + Math.random() * 100);
      const label = new Date().toLocaleTimeString();

      state.labels.push(label);
      state.trafficData.push(nextValue);

      if (state.labels.length > state.maxPoints) {
        state.labels.shift();
        state.trafficData.shift();
      }

      trafficChart.data.labels = state.labels;
      trafficChart.data.datasets[0].data = state.trafficData;
      trafficChart.update();
    }

    function simulateStream() {
      if (!state.running) return;
      updateStats();
      updateChart();
    }

    // ----- Events -----
    recordForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const role = document.getElementById("role").value;
      const score = Number(document.getElementById("score").value);
      const status = document.getElementById("status").value;

      state.records.unshift({ name, role, score, status });
      renderRecords();
      recordForm.reset();
      document.getElementById("score").value = 50;
    });

    searchEl.addEventListener("input", renderRecords);

    toggleStreamBtn.addEventListener("click", () => {
      state.running = !state.running;
      toggleStreamBtn.textContent = state.running ? "Pause Stream" : "Resume Stream";
    });

    timeRangeEl.addEventListener("change", () => {
      state.maxPoints = Number(timeRangeEl.value);

      while (state.labels.length > state.maxPoints) {
        state.labels.shift();
        state.trafficData.shift();
      }

      trafficChart.update();
    });

    // ----- Initial Render -----
    renderRecords();
    updateStats();
    updateChart();

    // ----- Real-time loop -----
    setInterval(simulateStream, 2000);
  </script>
</body>
</html>
```

