<body>
  <header>
    <h1>Real-Time Interactive Dashboard</h1>
    <p>Live metrics, chart updates, filtering, and form-based data entry.</p>
  </header>

  <main class="dashboard">
    <section class="card">
      <div class="metrics">
        <div class="metric">
          <div class="label">Total Records</div>
          <div class="value" id="totalRecords">0</div>
        </div>
        <div class="metric">
          <div class="label">Average Value</div>
          <div class="value" id="avgValue">0.0</div>
        </div>
        <div class="metric">
          <div class="label">Last Update</div>
          <div class="value" id="lastUpdate">--:--:--</div>
        </div>
      </div>

      <div class="controls">
        <select id="categoryFilter">
          <option value="all">All Categories</option>
          <option value="Sales">Sales</option>
          <option value="Marketing">Marketing</option>
          <option value="Operations">Operations</option>
        </select>

        <button id="simulateBtn">Simulate Real-Time Update</button>
        <button id="resetBtn">Reset Data</button>
      </div>

      <div class="chart-wrap">
        <canvas id="dataChart"></canvas>
      </div>

      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Category</th>
              <th>Value</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody id="dataTable"></tbody>
        </table>
      </div>
    </section>

    <section class="card">
      <h2 style="margin-top: 0;">Add New Data Point</h2>
      <form id="dataForm" class="form-grid">
        <div class="form-row">
          <div class="field">
            <label for="category">Category</label>
            <select id="category" required>
              <option value="">Select category</option>
              <option value="Sales">Sales</option>
              <option value="Marketing">Marketing</option>
              <option value="Operations">Operations</option>
            </select>
            <div class="error" id="categoryError"></div>
          </div>

          <div class="field">
            <label for="value">Value</label>
            <input type="number" id="value" min="0" step="1" placeholder="Enter value" required />
            <div class="error" id="valueError"></div>
          </div>
        </div>

        <div class="form-row">
          <div class="field">
            <label for="source">Source</label>
            <input type="text" id="source" placeholder="e.g. Manual entry" />
          </div>

          <div class="field">
            <label for="note">Note</label>
            <input type="text" id="note" placeholder="Optional note" />
          </div>
        </div>

        <button type="submit">Add Record</button>
        <div class="success" id="formMessage"></div>
      </form>
    </section>
  </main>

  <script>
    const ctx = document.getElementById('dataChart').getContext('2d');

    let records = [
      { time: new Date().toLocaleTimeString(), category: 'Sales', value: 42, status: 'OK', source: 'Seed', note: '' },
      { time: new Date().toLocaleTimeString(), category: 'Marketing', value: 28, status: 'OK', source: 'Seed', note: '' },
      { time: new Date().toLocaleTimeString(), category: 'Operations', value: 35, status: 'OK', source: 'Seed', note: '' }
    ];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: records.map(r => r.time),
        datasets: [
          {
            label: 'Value',
            data: records.map(r => r.value),
            borderColor: '#38bdf8',
            backgroundColor: 'rgba(56, 189, 248, 0.15)',
            tension: 0.35,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(51, 65, 85, 0.4)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(51, 65, 85, 0.4)' }
          }
        }
      }
    });

    const totalRecordsEl = document.getElementById('totalRecords');
    const avgValueEl = document.getElementById('avgValue');
    const lastUpdateEl = document.getElementById('lastUpdate');
    const dataTableEl = document.getElementById('dataTable');
    const categoryFilterEl = document.getElementById('categoryFilter');
    const form = document.getElementById('dataForm');
    const formMessage = document.getElementById('formMessage');

    function render() {
      const filter = categoryFilterEl.value;
      const filtered = filter === 'all'
        ? records
        : records.filter(r => r.category === filter);

      chart.data.labels = filtered.map(r => r.time);
      chart.data.datasets[0].data = filtered.map(r => r.value);
      chart.update();

      totalRecordsEl.textContent = filtered.length;
      avgValueEl.textContent = filtered.length
        ? (filtered.reduce((sum, r) => sum + r.value, 0) / filtered.length).toFixed(1)
        : '0.0';
      lastUpdateEl.textContent = records.length ? records[records.length - 1].time : '--:--:--';

      dataTableEl.innerHTML = filtered.map(r => `
        <tr>
          <td>${r.time}</td>
          <td>${r.category}</td>
          <td>${r.value}</td>
          <td><span class="status">${r.status}</span></td>
        </tr>
      `).join('');
    }

    function validateForm() {
      let valid = true;
      const category = document.getElementById('category').value;
      const value = document.getElementById('value').value;

      document.getElementById('categoryError').textContent = '';
      document.getElementById('valueError').textContent = '';

      if (!category) {
        document.getElementById('categoryError').textContent = 'Please select a category.';
        valid = false;
      }

      if (value === '' || Number(value) < 0) {
        document.getElementById('valueError').textContent = 'Please enter a valid non-negative value.';
        valid = false;
      }

      return valid;
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      formMessage.textContent = '';

      if (!validateForm()) return;

      const category = document.getElementById('category').value;
      const value = Number(document.getElementById('value').value);
      const source = document.getElementById('source').value.trim();
      const note = document.getElementById('note').value.trim();

      records.push({
        time: new Date().toLocaleTimeString(),
        category,
        value,
        status: value >= 50 ? 'High' : 'OK',
        source,
        note
      });

      form.reset();
      formMessage.textContent = 'Record added successfully.';
      render();
    });

    categoryFilterEl.addEventListener('change', render);

    document.getElementById('simulateBtn').addEventListener('click', () => {
      const categories = ['Sales', 'Marketing', 'Operations'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      const value = Math.floor(Math.random() * 100);

      records.push({
        time: new Date().toLocaleTimeString(),
        category,
        value,
        status: value >= 50 ? 'High' : 'OK',
        source: 'Simulated',
        note: ''
      });

      render();
    });

    document.getElementById('resetBtn').addEventListener('click', () => {
      records = [
        { time: new Date().toLocaleTimeString(), category: 'Sales', value: 42, status: 'OK', source: 'Seed', note: '' },
        { time: new Date().toLocaleTimeString(), category: 'Marketing', value: 28, status: 'OK', source: 'Seed', note: '' },
        { time: new Date().toLocaleTimeString(), category: 'Operations', value: 35, status: 'OK', source: 'Seed', note: '' }
      ];
      formMessage.textContent = 'Data reset to initial state.';
      render();
    });

    // Simulate real-time updates every 5 seconds
    setInterval(() => {
      const categories = ['Sales', 'Marketing', 'Operations'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      const value = Math.floor(Math.random() * 100);

      records.push({
        time: new Date().toLocaleTimeString(),
        category,
        value,
        status: value >= 50 ? 'High' : 'OK',
        source: 'Auto',
        note: ''
      });

      render();
    }, 5000);

    render();
  </script>
</body>
</html>
