</head>
<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
    <p>Live metrics, chart updates, and form submissions in the browser.</p>
  </header>

  <main class="container">
    <section class="metrics">
      <div class="card">
        <div class="metric-label">Active Users</div>
        <div class="metric-value" id="activeUsers">0</div>
      </div>
      <div class="card">
        <div class="metric-label">Requests / min</div>
        <div class="metric-value" id="requestsPerMin">0</div>
      </div>
      <div class="card">
        <div class="metric-label">Error Rate</div>
        <div class="metric-value" id="errorRate">0%</div>
      </div>
      <div class="card">
        <div class="metric-label">Uptime</div>
        <div class="metric-value" id="uptime">100%</div>
      </div>
    </section>

    <section class="grid">
      <div class="panel">
        <h2>Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
        <div class="footer-note">Chart updates every 2 seconds with simulated real-time data.</div>
      </div>

      <div class="panel">
        <h2>Controls & Form</h2>

        <div class="status" style="margin-bottom: 14px;">
          <span class="dot"></span>
          <span>System online</span>
        </div>

        <form id="dataForm" class="controls">
          <div class="form-group">
            <label for="name">Name</label>
            <input id="name" name="name" type="text" placeholder="Enter your name" required />
          </div>

          <div class="form-group">
            <label for="category">Category</label>
            <select id="category" name="category" required>
              <option value="">Select category</option>
              <option value="Sales">Sales</option>
              <option value="Support">Support</option>
              <option value="Engineering">Engineering</option>
              <option value="Marketing">Marketing</option>
            </select>
          </div>

          <div class="form-group">
            <label for="value">Value</label>
            <input id="value" name="value" type="number" min="0" step="1" placeholder="Enter a value" required />
          </div>

          <button type="submit">Submit Entry</button>
        </form>
      </div>
    </section>

    <section class="panel">
      <h2>Recent Entries</h2>
      <table>
        <thead>
          <tr>
            <th>Time</th>
            <th>Name</th>
            <th>Category</th>
            <th>Value</th>
          </tr>
        </thead>
        <tbody id="entriesTable">
          <tr>
            <td colspan="4" style="color: var(--muted);">No entries yet.</td>
          </tr>
        </tbody>
      </table>
    </section>
  </main>

  <script>
    // Initial metrics
    let activeUsers = 120;
    let requestsPerMin = 340;
    let errorRate = 2.4;
    let uptime = 99.98;

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const uptimeEl = document.getElementById("uptime");

    function updateMetrics() {
      activeUsers += Math.floor(Math.random() * 11 - 5);
      requestsPerMin += Math.floor(Math.random() * 21 - 10);
      errorRate += (Math.random() * 0.6 - 0.3);
      uptime += (Math.random() * 0.01 - 0.005);

      activeUsers = Math.max(0, activeUsers);
      requestsPerMin = Math.max(0, requestsPerMin);
      errorRate = Math.min(10, Math.max(0, errorRate));
      uptime = Math.min(100, Math.max(95, uptime));

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      errorRateEl.textContent = errorRate.toFixed(1) + "%";
      uptimeEl.textContent = uptime.toFixed(2) + "%";
    }

    // Chart setup
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 100) + 50);

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function updateChart() {
      const newValue = Math.floor(Math.random() * 100) + 50;
      trafficChart.data.labels.push(new Date().toLocaleTimeString());
      trafficChart.data.datasets[0].data.push(newValue);

      if (trafficChart.data.labels.length > 12) {
        trafficChart.data.labels.shift();
        trafficChart.data.datasets[0].data.shift();
      }

      trafficChart.update();
    }

    // Form handling and table updates
    const form = document.getElementById("dataForm");
    const entriesTable = document.getElementById("entriesTable");
    const recentEntries = [];

    function renderEntries() {
      if (recentEntries.length === 0) {
        entriesTable.innerHTML = `<tr><td colspan="4" style="color: var(--muted);">No entries yet.</td></tr>`;
        return;
      }

      entriesTable.innerHTML = recentEntries.map(entry => `
        <tr>
          <td>${entry.time}</td>
          <td>${entry.name}</td>
          <td><span class="tag">${entry.category}</span></td>
          <td>${entry.value}</td>
        </tr>
      `).join("");
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const value = document.getElementById("value").value.trim();

      if (!name || !category || !value) return;

      recentEntries.unshift({
        time: new Date().toLocaleTimeString(),
        name,
        category,
        value
      });

      if (recentEntries.length > 5) recentEntries.pop();

      renderEntries();
      form.reset();
    });

    // Simulated real-time updates
    updateMetrics();
    renderEntries();

    setInterval(() => {
      updateMetrics();
      updateChart();
    }, 2000);
  </script>
</body>
</html>
```

