## 3) `app.js`

```javascript
const visitorsValue = document.getElementById("visitorsValue");
const ordersValue = document.getElementById("ordersValue");
const revenueValue = document.getElementById("revenueValue");
const conversionValue = document.getElementById("conversionValue");
const activityLog = document.getElementById("activityLog");
const eventForm = document.getElementById("eventForm");
const toggleUpdatesBtn = document.getElementById("toggleUpdatesBtn");
const connectionStatus = document.getElementById("connectionStatus");

let updatesRunning = true;
let updateTimer = null;

let metrics = {
  visitors: 1200,
  orders: 87,
  revenue: 15420,
};

const chartLabels = [];
const chartData = [];

const ctx = document.getElementById("activityChart").getContext("2d");
const activityChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: chartLabels,
    datasets: [
      {
        label: "Activity Score",
        data: chartData,
        borderColor: "#60a5fa",
        backgroundColor: "rgba(96, 165, 250, 0.2)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e2e8f0" },
      },
    },
  },
});

function formatCurrency(value) {
  return `$${value.toLocaleString()}`;
}

function formatTime(date = new Date()) {
  return date.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function updateMetricsDisplay() {
  visitorsValue.textContent = metrics.visitors.toLocaleString();
  ordersValue.textContent = metrics.orders.toLocaleString();
  revenueValue.textContent = formatCurrency(metrics.revenue);

  const conversion = ((metrics.orders / metrics.visitors) * 100).toFixed(1);
  conversionValue.textContent = `${conversion}%`;
}

function addLogEntry(message) {
  const li = document.createElement("li");
  li.innerHTML = `<span class="log-time">[${formatTime()}]</span>${message}`;
  activityLog.prepend(li);

  if (activityLog.children.length > 8) {
    activityLog.removeChild(activityLog.lastChild);
  }
}

function pushChartPoint() {
  const now = new Date().toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });

  const activityScore = Math.floor(Math.random() * 100) + 20;

  chartLabels.push(now);
  chartData.push(activityScore);

  if (chartLabels.length > 12) {
    chartLabels.shift();
    chartData.shift();
  }

  activityChart.update();
}

function simulateLiveUpdate() {
  if (!updatesRunning) return;

  const visitorDelta = Math.floor(Math.random() * 25) + 5;
  const orderDelta = Math.floor(Math.random() * 4);
  const revenueDelta = orderDelta * (Math.floor(Math.random() * 120) + 40);

  metrics.visitors += visitorDelta;
  metrics.orders += orderDelta;
  metrics.revenue += revenueDelta;

  updateMetricsDisplay();
  pushChartPoint();
  addLogEntry(
    `Live update: +${visitorDelta} visitors, +${orderDelta} orders, +${formatCurrency(revenueDelta)} revenue`
  );
}

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const eventName = document.getElementById("eventName").value.trim();
  const eventType = document.getElementById("eventType").value;
  const eventValue = parseInt(document.getElementById("eventValue").value, 10);

  if (!eventName || !eventType || Number.isNaN(eventValue)) {
    addLogEntry("Form submission failed: invalid input");
    return;
  }

  // Basic form-driven metric updates
  if (eventType === "traffic") {
    metrics.visitors += eventValue;
  } else if (eventType === "sales") {
    metrics.orders += Math.max(1, Math.floor(eventValue / 10));
    metrics.revenue += eventValue;
  } else if (eventType === "support") {
    metrics.revenue -= Math.min(metrics.revenue, Math.floor(eventValue / 2));
  }

  updateMetricsDisplay();
  pushChartPoint();
  addLogEntry(`Submitted event: "${eventName}" (${eventType}) with value ${eventValue}`);

  eventForm.reset();
});

toggleUpdatesBtn.addEventListener("click", () => {
  updatesRunning = !updatesRunning;

  if (updatesRunning) {
    toggleUpdatesBtn.textContent = "Pause Updates";
    connectionStatus.textContent = "● Live";
    connectionStatus.style.background = "#052e16";
    connectionStatus.style.color = "#4ade80";
    addLogEntry("Real-time updates resumed");
  } else {
    toggleUpdatesBtn.textContent = "Resume Updates";
    connectionStatus.textContent = "● Paused";
    connectionStatus.style.background = "#3f1d1d";
    connectionStatus.style.color = "#f87171";
    addLogEntry("Real-time updates paused");
  }
});

function initializeDashboard() {
  updateMetricsDisplay();

  // Seed chart with initial data
  for (let i = 0; i < 6; i++) {
    chartLabels.push(`T-${6 - i}`);
    chartData.push(Math.floor(Math.random() * 100) + 20);
  }
  activityChart.update();

  addLogEntry("Dashboard initialized");
  updateTimer = setInterval(simulateLiveUpdate, 2000);
}

initializeDashboard();
```

