      margin: 0.35rem 0 0;
      opacity: 0.9;
    }

    .container {
      max-width: 1400px;
      margin: 0 auto;
      padding: 1.5rem;
    }

    .grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 1.5rem;
      align-items: start;
    }

    .card {
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: 1.25rem;
    }

    .card h2 {
      margin: 0 0 1rem;
      font-size: 1.1rem;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
      margin-bottom: 1.5rem;
    }

    .stat {
      background: linear-gradient(180deg, #fff, #f8fafc);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 1rem;
    }

    .stat .label {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .stat .value {
      font-size: 1.5rem;
      font-weight: 700;
      margin-top: 0.35rem;
    }

    .chart-wrap {
      height: 420px;
    }

    form {
      display: grid;
      gap: 0.9rem;
    }

    .field {
      display: grid;
      gap: 0.35rem;
    }

    label {
      font-size: 0.9rem;
      color: var(--muted);
    }

    input, select, textarea {
      width: 100%;
      padding: 0.8rem 0.9rem;
      border: 1px solid var(--border);
      border-radius: 10px;
