  </style>
</head>
<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Interactive dashboard with live chart updates and form-driven data entry.</p>
  </header>

  <main class="container">
    <section class="stats">
      <div class="stat">
        <div class="label">Current Value</div>
        <div class="value" id="currentValue">0</div>
      </div>
      <div class="stat">
        <div class="label">Average</div>
        <div class="value" id="averageValue">0</div>
      </div>
      <div class="stat">
        <div class="label">Total Points</div>
        <div class="value" id="pointCount">0</div>
      </div>
    </section>

    <section class="grid">
      <div class="card">
        <h2>Live Data Visualization</h2>
        <div class="chart-wrap">
          <canvas id="liveChart"></canvas>
        </div>
        <div class="footer-note">
          Data updates every 2 seconds automatically. You can also add your own entries using the form.
        </div>
      </div>

      <div class="card">
        <h2>Add Data Point</h2>
        <form id="dataForm">
          <div class="field">
            <label for="label">Label</label>
            <input type="text" id="label" placeholder="e.g. Q1, Sensor A, Event 1" required />
          </div>

          <div class="field">
            <label for="value">Value</label>
            <input type="number" id="value" placeholder="Enter numeric value" required />
          </div>

          <div class="field">
            <label for="category">Category</label>
            <select id="category">
              <option value="ok">Normal</option>
              <option value="warn">Warning</option>
            </select>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" rows="3" placeholder="Optional notes"></textarea>
          </div>

          <div class="actions">
            <button type="submit">Add Data</button>
            <button type="button" class="secondary" id="resetBtn">Reset Dashboard</button>
          </div>
        </form>

        <h2 style="margin-top: 1.5rem;">Latest Entries</h2>
        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Value</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody id="dataTableBody"></tbody>
        </table>
      </div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    let dataPoints = [
      { label: 'Init 1', value: 12, status: 'ok' },
      { label: 'Init 2', value: 18, status: 'ok' },
      { label: 'Init 3', value: 14, status: 'warn' },
      { label: 'Init 4', value: 22, status: 'ok' }
    ];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: dataPoints.map(p => p.label),
        datasets: [{
          label: 'Metric Value',
          data: dataPoints.map(p => p.value),
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.12)',
          fill: true,
          tension: 0.35,
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            display: true
          }
        },
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const pointCountEl = document.getElementById('pointCount');
    const tableBody = document.getElementById('dataTableBody');
    const form = document.getElementById('dataForm');
    const resetBtn = document.getElementById('resetBtn');

    function updateStats() {
      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1] ?? 0;
      const average = values.length ? (values.reduce((a, b) => a + b, 0) / values.length) : 0;

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = average.toFixed(1);
      pointCountEl.textContent = dataPoints.length;
    }

    function renderTable() {
      tableBody.innerHTML = '';
      [...dataPoints].slice(-8).reverse().forEach(point => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${point.label}</td>
          <td>${point.value}</td>
          <td><span class="status ${point.status}">${point.status === 'ok' ? 'Normal' : 'Warning'}</span></td>
        `;
        tableBody.appendChild(row);
      });
    }

    function updateChart() {
      chart.data.labels = dataPoints.map(p => p.label);
      chart.data.datasets[0].data = dataPoints.map(p => p.value);
      chart.update();
    }

    function refreshDashboard() {
      updateStats();
      renderTable();
      updateChart();
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = document.getElementById('label').value.trim();
      const value = Number(document.getElementById('value').value);
      const status = document.getElementById('category').value;
      const notes = document.getElementById('notes').value.trim();

      if (!label || Number.isNaN(value)) return;

      dataPoints.push({ label, value, status, notes });
      refreshDashboard();
      form.reset();
    });

    resetBtn.addEventListener('click', () => {
      dataPoints = [
        { label: 'Init 1', value: 12, status: 'ok' },
        { label: 'Init 2', value: 18, status: 'ok' },
        { label: 'Init 3', value: 14, status: 'warn' },
        { label: 'Init 4', value: 22, status: 'ok' }
      ];
      refreshDashboard();
    });

    // Simulated real-time updates
    setInterval(() => {
      const lastValue = dataPoints[dataPoints.length - 1]?.value ?? 20;
      const change = Math.floor(Math.random() * 11) - 5;
      const nextValue = Math.max(0, lastValue + change);
      const status = nextValue > 25 ? 'warn' : 'ok';

      dataPoints.push({
        label: `Auto ${dataPoints.length + 1}`,
        value: nextValue,
        status
      });

      // Keep data manageable
      if (dataPoints.length > 20) {
        dataPoints.shift();
      }

      refreshDashboard();
    }, 2000);

    refreshDashboard();
  </script>
</body>
</html>
```

