## 3) `src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  Legend,
} from "recharts";

const initialMetrics = [
  { time: "10:00", value: 20, users: 5 },
  { time: "10:01", value: 35, users: 8 },
  { time: "10:02", value: 28, users: 11 },
  { time: "10:03", value: 42, users: 15 },
  { time: "10:04", value: 50, users: 18 },
];

export default function App() {
  const [metrics, setMetrics] = useState(initialMetrics);
  const [form, setForm] = useState({
    name: "",
    email: "",
    alertThreshold: 40,
    enabled: true,
  });
  const [submitted, setSubmitted] = useState(null);

  // Simulated real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics((prev) => {
        const last = prev[prev.length - 1];
        const nextValue = Math.max(0, Math.min(100, last.value + (Math.random() * 16 - 8)));
        const nextUsers = Math.max(0, last.users + Math.floor(Math.random() * 5 - 2));

        const now = new Date();
        const time = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });

        const next = [...prev.slice(-11), { time, value: Math.round(nextValue), users: nextUsers }];
        return next;
      });
    }, 2500);

    return () => clearInterval(interval);
  }, []);

  const latest = metrics[metrics.length - 1];

  const summary = useMemo(() => {
    const avgValue = metrics.reduce((sum, m) => sum + m.value, 0) / metrics.length;
    const totalUsers = metrics[metrics.length - 1]?.users ?? 0;
    return {
      avgValue: avgValue.toFixed(1),
      totalUsers,
      status: latest.value >= form.alertThreshold ? "Alert" : "Normal",
    };
  }, [metrics, latest, form.alertThreshold]);

  function handleChange(e) {
    const { name, value, type, checked } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : name === "alertThreshold" ? Number(value) : value,
    }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    setSubmitted({
      ...form,
      submittedAt: new Date().toLocaleString(),
    });
  }

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Real-Time Dashboard</h1>
          <p>Interactive browser-based dashboard with live data and form handling</p>
        </div>
        <div className={`badge ${summary.status === "Alert" ? "alert" : "normal"}`}>
          {summary.status}
        </div>
      </header>

      <section className="cards">
        <div className="card">
          <h3>Latest Value</h3>
          <p className="big">{latest.value}</p>
        </div>
        <div className="card">
          <h3>Average Value</h3>
          <p className="big">{summary.avgValue}</p>
        </div>
        <div className="card">
          <h3>Active Users</h3>
          <p className="big">{summary.totalUsers}</p>
        </div>
      </section>

      <section className="grid">
        <div className="panel">
          <h2>Live Trend</h2>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={metrics}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="time" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line type="monotone" dataKey="value" stroke="#4f46e5" strokeWidth={3} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div className="panel">
          <h2>Users Over Time</h2>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={metrics}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="time" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="users" fill="#10b981" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      <section className="grid">
        <div className="panel">
          <h2>Settings Form</h2>
          <form onSubmit={handleSubmit} className="form">
            <label>
              Name
              <input
                type="text"
                name="name"
                value={form.name}
                onChange={handleChange}
                placeholder="Enter your name"
              />
            </label>

            <label>
              Email
              <input
                type="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                placeholder="Enter your email"
              />
            </label>

            <label>
              Alert Threshold: {form.alertThreshold}
              <input
                type="range"
                name="alertThreshold"
                min="0"
                max="100"
                value={form.alertThreshold}
                onChange={handleChange}
              />
            </label>

            <label className="checkbox">
              <input
                type="checkbox"
                name="enabled"
                checked={form.enabled}
                onChange={handleChange}
              />
              Enable notifications
            </label>

            <button type="submit">Save Settings</button>
          </form>
        </div>

        <div className="panel">
          <h2>Submitted Data</h2>
          {submitted ? (
            <div className="submitted">
              <p><strong>Name:</strong> {submitted.name}</p>
              <p><strong>Email:</strong> {submitted.email}</p>
              <p><strong>Threshold:</strong> {submitted.alertThreshold}</p>
              <p><strong>Notifications:</strong> {submitted.enabled ? "Enabled" : "Disabled"}</p>
              <p><strong>Submitted At:</strong> {submitted.submittedAt}</p>
            </div>
          ) : (
            <p>No form submitted yet.</p>
          )}
        </div>
      </section>
    </div>
  );
}
```

