      padding: 4px 8px;
      border-radius: 999px;
      font-size: 0.8rem;
      font-weight: 600;
    }

    .status.ok {
      background: rgba(34, 197, 94, 0.15);
      color: #86efac;
    }

    .status.warn {
      background: rgba(245, 158, 11, 0.15);
      color: #fcd34d;
    }

