        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
    <p>Live metrics, chart updates, and form-driven data entry.</p>
  </header>

  <main class="container">
    <section class="kpis">
      <div class="card">
        <h3>Active Users</h3>
        <div class="value" id="activeUsers">0</div>
      </div>
      <div class="card">
        <h3>Requests / min</h3>
        <div class="value" id="requestsPerMin">0</div>
      </div>
      <div class="card">
        <h3>Avg. Response Time</h3>
        <div class="value" id="avgResponse">0 ms</div>
      </div>
      <div class="card">
        <h3>Errors</h3>
        <div class="value" id="errorCount">0</div>
      </div>
    </section>

    <section class="grid">
      <div class="panel">
        <h2>Real-Time Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="panel">
        <h2>Add Record</h2>
        <form id="recordForm">
          <div>
            <label for="name">Name</label>
            <input id="name" type="text" placeholder="Enter name" required />
          </div>

          <div>
            <label for="type">Type</label>
            <select id="type" required>
              <option value="">Select type</option>
              <option value="User">User</option>
              <option value="Order">Order</option>
              <option value="Alert">Alert</option>
            </select>
          </div>

          <div>
            <label for="value">Value</label>
            <input id="value" type="number" placeholder="Enter value" min="0" required />
          </div>

          <button type="submit">Add Entry</button>
          <div class="error" id="formError"></div>
        </form>
      </div>
    </section>

    <section class="panel">
      <h2>Submitted Records</h2>
      <table class="table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Type</th>
            <th>Value</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody id="recordsTable">
          <!-- Records inserted here -->
        </tbody>
      </table>
    </section>
  </main>

  <script>
    // KPI state
    let activeUsers = 120;
    let requestsPerMin = 340;
    let avgResponse = 240;
    let errorCount = 3;

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const avgResponseEl = document.getElementById("avgResponse");
    const errorCountEl = document.getElementById("errorCount");

    function updateKpis() {
      // Simulate live movement
      activeUsers += Math.floor(Math.random() * 11 - 5);
      requestsPerMin += Math.floor(Math.random() * 21 - 10);
      avgResponse += Math.floor(Math.random() * 21 - 10);
      errorCount += Math.random() > 0.8 ? 1 : 0;

      activeUsers = Math.max(0, activeUsers);
      requestsPerMin = Math.max(0, requestsPerMin);
      avgResponse = Math.max(50, avgResponse);
      errorCount = Math.max(0, errorCount);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      avgResponseEl.textContent = `${avgResponse} ms`;
      errorCountEl.textContent = errorCount;
    }

    // Chart setup
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const labels = Array.from({ length: 12 }, (_, i) => `${i + 1}s`);
    const trafficData = Array.from({ length: 12 }, () => Math.floor(Math.random() * 100) + 50);

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function updateChart() {
      trafficData.shift();
      trafficData.push(Math.floor(Math.random() * 100) + 50);
      trafficChart.update();
    }

    // Form handling
    const form = document.getElementById("recordForm");
    const formError = document.getElementById("formError");
    const recordsTable = document.getElementById("recordsTable");

    function getStatus(value) {
      if (value >= 80) return { label: "Good", className: "ok" };
      if (value >= 40) return { label: "Warning", className: "warn" };
      return { label: "Critical", className: "bad" };
    }

    function addRecord(name, type, value) {
      const status = getStatus(value);

      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${name}</td>
        <td>${type}</td>
        <td>${value}</td>
        <td><span class="status ${status.className}">${status.label}</span></td>
      `;
      recordsTable.prepend(row);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      formError.textContent = "";

      const name = document.getElementById("name").value.trim();
      const type = document.getElementById("type").value;
      const value = Number(document.getElementById("value").value);

      if (!name || !type || Number.isNaN(value)) {
        formError.textContent = "Please fill out all fields correctly.";
        return;
      }

      addRecord(name, type, value);
      form.reset();
    });

    // Seed initial records
    addRecord("Alice", "User", 92);
    addRecord("Order #1024", "Order", 61);
    addRecord("Server Alert", "Alert", 28);

    // Real-time updates
    updateKpis();
    setInterval(() => {
      updateKpis();
      updateChart();
    }, 1000);
  </script>
</body>
</html>
```

