## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const ordersEl = document.getElementById("orders");
const revenueEl = document.getElementById("revenue");
const conversionRateEl = document.getElementById("conversionRate");
const eventLogEl = document.getElementById("eventLog");
const metricForm = document.getElementById("metricForm");
const pauseBtn = document.getElementById("pauseBtn");

const inputUsers = document.getElementById("inputUsers");
const inputOrders = document.getElementById("inputOrders");
const inputRevenue = document.getElementById("inputRevenue");
const inputConversion = document.getElementById("inputConversion");

let isPaused = false;

let metrics = {
  activeUsers: 120,
  orders: 45,
  revenue: 1890.5,
  conversionRate: 3.4
};

const labels = [];
const trendData = [];

const ctx = document.getElementById("trendChart").getContext("2d");
const trendChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Active Users",
        data: trendData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      }
    }
  }
});

function formatCurrency(value) {
  return `$${value.toFixed(2)}`;
}

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  // Keep log manageable
  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function renderMetrics() {
  activeUsersEl.textContent = metrics.activeUsers.toLocaleString();
  ordersEl.textContent = metrics.orders.toLocaleString();
  revenueEl.textContent = formatCurrency(metrics.revenue);
  conversionRateEl.textContent = `${metrics.conversionRate.toFixed(1)}%`;
}

function pushTrendPoint(value) {
  const now = new Date().toLocaleTimeString();

  labels.push(now);
  trendData.push(value);

  if (labels.length > 12) {
    labels.shift();
    trendData.shift();
  }

  trendChart.update();
}

function randomLiveUpdate() {
  if (isPaused) return;

  const userDelta = Math.floor(Math.random() * 21) - 10;
  const orderDelta = Math.floor(Math.random() * 7);
  const revenueDelta = Math.random() * 250;
  const conversionDelta = (Math.random() * 0.4) - 0.2;

  metrics.activeUsers = Math.max(0, metrics.activeUsers + userDelta);
  metrics.orders = Math.max(0, metrics.orders + orderDelta);
  metrics.revenue = Math.max(0, metrics.revenue + revenueDelta);
  metrics.conversionRate = Math.max(0, Math.min(100, metrics.conversionRate + conversionDelta));

  renderMetrics();
  pushTrendPoint(metrics.activeUsers);
  addLog(`Live update received: users ${metrics.activeUsers}, orders ${metrics.orders}`);
}

metricForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const users = inputUsers.value !== "" ? Number(inputUsers.value) : metrics.activeUsers;
  const orders = inputOrders.value !== "" ? Number(inputOrders.value) : metrics.orders;
  const revenue = inputRevenue.value !== "" ? Number(inputRevenue.value) : metrics.revenue;
  const conversion = inputConversion.value !== "" ? Number(inputConversion.value) : metrics.conversionRate;

  if ([users, orders, revenue, conversion].some((v) => Number.isNaN(v))) {
    addLog("Form submission failed: invalid input.");
    return;
  }

  metrics = {
    activeUsers: Math.max(0, users),
    orders: Math.max(0, orders),
    revenue: Math.max(0, revenue),
    conversionRate: Math.max(0, Math.min(100, conversion))
  };

  renderMetrics();
  pushTrendPoint(metrics.activeUsers);
  addLog("Metrics updated from form.");

  metricForm.reset();
});

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume" : "Pause";
  addLog(isPaused ? "Live updates paused." : "Live updates resumed.");
});

// Initial render
renderMetrics();
pushTrendPoint(metrics.activeUsers);
addLog("Dashboard initialized.");

// Simulated real-time updates every 2 seconds
setInterval(randomLiveUpdate, 2000);
```

