## 4) `app.js`

```javascript
const ctx = document.getElementById("metricsChart").getContext("2d");
const toggleFeedBtn = document.getElementById("toggleFeedBtn");
const settingsForm = document.getElementById("settingsForm");
const settingsPreview = document.getElementById("settingsPreview");

const cpuValue = document.getElementById("cpuValue");
const memoryValue = document.getElementById("memoryValue");
const requestsValue = document.getElementById("requestsValue");

const displayNameInput = document.getElementById("displayName");
const thresholdInput = document.getElementById("threshold");
const refreshRateInput = document.getElementById("refreshRate");
const enableAlertsInput = document.getElementById("enableAlerts");

let feedRunning = true;
let feedInterval = null;
let refreshRate = 1000;

const labels = [];
const cpuData = [];
const memoryData = [];

function randomBetween(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "CPU %",
        data: cpuData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
      {
        label: "Memory %",
        data: memoryData,
        borderColor: "#f97316",
        backgroundColor: "rgba(249, 115, 22, 0.15)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        beginAtZero: true,
        max: 100,
      },
    },
  },
});

let requestCount = 0;

function updateStats() {
  const cpu = randomBetween(10, 95);
  const memory = randomBetween(15, 90);

  requestCount += randomBetween(1, 8);

  const timeLabel = new Date().toLocaleTimeString();

  labels.push(timeLabel);
  cpuData.push(cpu);
  memoryData.push(memory);

  if (labels.length > 12) {
    labels.shift();
    cpuData.shift();
    memoryData.shift();
  }

  chart.update();

  cpuValue.textContent = `${cpu}%`;
  memoryValue.textContent = `${memory}%`;
  requestsValue.textContent = `${requestCount}`;

  const threshold = Number(thresholdInput.value);
  const alertsEnabled = enableAlertsInput.checked;

  if (alertsEnabled && cpu > threshold) {
    cpuValue.style.color = "#ef4444";
  } else {
    cpuValue.style.color = "#38bdf8";
  }
}

function startFeed() {
  stopFeed();
  feedInterval = setInterval(updateStats, refreshRate);
  feedRunning = true;
  toggleFeedBtn.textContent = "Pause Feed";
  document.getElementById("connectionStatus").textContent = "Live";
}

function stopFeed() {
  if (feedInterval) {
    clearInterval(feedInterval);
    feedInterval = null;
  }
  feedRunning = false;
  toggleFeedBtn.textContent = "Resume Feed";
  document.getElementById("connectionStatus").textContent = "Paused";
}

toggleFeedBtn.addEventListener("click", () => {
  if (feedRunning) {
    stopFeed();
  } else {
    startFeed();
  }
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const settings = {
    displayName: displayNameInput.value.trim(),
    threshold: Number(thresholdInput.value),
    refreshRate: Number(refreshRateInput.value),
    enableAlerts: enableAlertsInput.checked,
  };

  refreshRate = settings.refreshRate;

  settingsPreview.textContent = JSON.stringify(settings, null, 2);

  if (feedRunning) {
    startFeed(); // restart interval with new refresh rate
  }
});

startFeed();
updateStats();
```

