## 3) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const ordersCountEl = document.getElementById("ordersCount");
const revenueValueEl = document.getElementById("revenueValue");
const errorCountEl = document.getElementById("errorCount");
const activityLogEl = document.getElementById("activityLog");
const eventForm = document.getElementById("eventForm");
const toggleFeedBtn = document.getElementById("toggleFeedBtn");
const clearLogBtn = document.getElementById("clearLogBtn");
const connectionStatus = document.getElementById("connectionStatus");

const eventNameEl = document.getElementById("eventName");
const eventCategoryEl = document.getElementById("eventCategory");
const eventValueEl = document.getElementById("eventValue");

let activeUsers = 128;
let ordersCount = 42;
let revenue = 8640;
let errors = 3;

let feedRunning = true;
let tickInterval = null;

const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
const dataPoints = Array.from({ length: 12 }, () => Math.floor(Math.random() * 100) + 20);

const ctx = document.getElementById("metricsChart").getContext("2d");
const metricsChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests / min",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

function formatCurrency(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(value);
}

function updateKpis() {
  activeUsersEl.textContent = activeUsers.toString();
  ordersCountEl.textContent = ordersCount.toString();
  revenueValueEl.textContent = formatCurrency(revenue);
  errorCountEl.textContent = errors.toString();
}

function addLog(message, category = "info") {
  const li = document.createElement("li");
  li.className = category;

  const now = new Date();
  const time = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });

  li.innerHTML = `
    <strong>${message}</strong>
    <span class="activity-meta">${category.toUpperCase()} • ${time}</span>
  `;

  activityLogEl.prepend(li);
}

function simulateFeedTick() {
  if (!feedRunning) return;

  activeUsers += Math.floor(Math.random() * 7) - 2;
  activeUsers = Math.max(0, activeUsers);

  ordersCount += Math.random() > 0.7 ? 1 : 0;
  revenue += Math.random() > 0.5 ? Math.floor(Math.random() * 250) : 0;
  errors += Math.random() > 0.85 ? 1 : 0;

  const newMetric = Math.floor(Math.random() * 100) + 20;
  metricsChart.data.labels.shift();
  metricsChart.data.labels.push(new Date().toLocaleTimeString([], { minute: "2-digit", second: "2-digit" }));
  metricsChart.data.datasets[0].data.shift();
  metricsChart.data.datasets[0].data.push(newMetric);
  metricsChart.update();

  updateKpis();

  if (Math.random() > 0.75) {
    addLog(`Auto event: ${newMetric} metric spike detected`, "warning");
  }
}

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = eventNameEl.value.trim();
  const category = eventCategoryEl.value;
  const value = Number(eventValueEl.value);

  if (!name || !category || Number.isNaN(value)) {
    addLog("Form validation failed. Please fill in all fields.", "error");
    return;
  }

  addLog(`Manual event submitted: ${name} (${value})`, category);

  if (category === "success") {
    ordersCount += 1;
    revenue += value;
  } else if (category === "warning") {
    errors += 1;
  } else if (category === "error") {
    errors += 2;
  } else {
    activeUsers += Math.floor(value / 10);
  }

  updateKpis();
  eventForm.reset();
});

toggleFeedBtn.addEventListener("click", () => {
  feedRunning = !feedRunning;
  toggleFeedBtn.textContent = feedRunning ? "Pause Feed" : "Resume Feed";
  connectionStatus.textContent = feedRunning ? "● Live" : "● Paused";
  connectionStatus.style.background = feedRunning ? "rgba(34, 197, 94, 0.12)" : "rgba(245, 158, 11, 0.12)";
  connectionStatus.style.color = feedRunning ? "#86efac" : "#fcd34d";
  connectionStatus.style.borderColor = feedRunning
    ? "rgba(34, 197, 94, 0.25)"
    : "rgba(245, 158, 11, 0.25)";
});

clearLogBtn.addEventListener("click", () => {
  activityLogEl.innerHTML = "";
  addLog("Activity log cleared.", "info");
});

updateKpis();
addLog("Dashboard initialized successfully.", "success");
addLog("Real-time feed started.", "info");

tickInterval = setInterval(simulateFeedTick, 2000);
```

