```tsx
import { useEffect, useMemo, useState } from 'react';
import DataChart from './DataChart';
import DataForm from './DataForm';
import StatsCard from './StatsCard';

type DataPoint = {
  time: string;
  value: number;
};

type FormState = {
  label: string;
  threshold: number;
  enabled: boolean;
};

export default function Dashboard() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [formState, setFormState] = useState<FormState>({
    label: 'Sensor A',
    threshold: 50,
    enabled: true,
  });

  // Simulated real-time data stream
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date().toLocaleTimeString();
      const newValue = Math.floor(Math.random() * 100);

      setData((prev) => {
        const next = [...prev, { time: now, value: newValue }];
        return next.slice(-20); // keep last 20 points
      });
    }, 1500);

    return () => clearInterval(interval);
  }, []);

  const latestValue = data.length ? data[data.length - 1].value : 0;
  const averageValue = useMemo(() => {
    if (!data.length) return 0;
    return Math.round(data.reduce((sum, p) => sum + p.value, 0) / data.length);
  }, [data]);

  const aboveThreshold = latestValue > formState.threshold;

  const handleFormSubmit = (values: FormState) => {
    setFormState(values);
  };

  return (
    <div className="dashboard">
      <header className="dashboard__header">
        <h1>Real-Time Dashboard</h1>
        <p>Interactive browser-based dashboard with live data and form controls.</p>
      </header>

      <section className="stats-grid">
        <StatsCard title="Latest Value" value={latestValue} highlight={aboveThreshold} />
        <StatsCard title="Average Value" value={averageValue} />
        <StatsCard title="Threshold" value={formState.threshold} />
      </section>

      <section className="content-grid">
        <div className="panel">
          <h2>Live Data Chart</h2>
          <DataChart data={data} />
        </div>

        <div className="panel">
          <h2>Configuration Form</h2>
          <DataForm initialValues={formState} onSubmit={handleFormSubmit} />
        </div>
      </section>
    </div>
  );
}
