### `src/components/DataForm.tsx`

```tsx
import { useState } from 'react';

type FormState = {
  label: string;
  threshold: number;
  enabled: boolean;
};

type Props = {
  initialValues: FormState;
  onSubmit: (values: FormState) => void;
};

export default function DataForm({ initialValues, onSubmit }: Props) {
  const [label, setLabel] = useState(initialValues.label);
  const [threshold, setThreshold] = useState(initialValues.threshold);
  const [enabled, setEnabled] = useState(initialValues.enabled);
  const [message, setMessage] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({ label, threshold, enabled });
    setMessage('Settings saved successfully.');
    setTimeout(() => setMessage(''), 2000);
  };

  return (
    <form className="form" onSubmit={handleSubmit}>
      <label>
        Label
        <input
          type="text"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          placeholder="Enter label"
        />
      </label>

      <label>
        Threshold
        <input
          type="number"
          value={threshold}
          onChange={(e) => setThreshold(Number(e.target.value))}
          min={0}
          max={100}
        />
      </label>

      <label className="checkbox">
        <input
          type="checkbox"
          checked={enabled}
          onChange={(e) => setEnabled(e.target.checked)}
        />
        Enabled
      </label>

      <button type="submit">Save Settings</button>

      {message && <p className="form-message">{message}</p>}
    </form>
  );
}
