          <label>Latency</label>
          <strong id="latencyMetric">0 ms</strong>
        </div>
      </div>
    </section>

    <section class="grid">
      <div class="card">
        <h2>Real-Time Chart</h2>
        <canvas id="realtimeChart"></canvas>
      </div>

      <div class="card">
        <h2>Control Panel</h2>
        <form id="controlForm">
          <div class="field">
            <label for="threshold">Alert Threshold</label>
            <input id="threshold" name="threshold" type="number" min="0" max="100" value="75" />
          </div>

          <div class="field">
            <label for="mode">Dashboard Mode</label>
            <select id="mode" name="mode">
              <option value="auto">Auto</option>
              <option value="manual">Manual</option>
              <option value="paused">Paused</option>
            </select>
          </div>

          <div class="field">
            <label for="note">Operator Note</label>
            <textarea id="note" name="note" rows="4" placeholder="Enter a note..."></textarea>
          </div>

          <div class="actions">
            <button type="submit">Apply Settings</button>
            <button type="button" class="secondary" id="resetBtn">Reset</button>
          </div>

          <div class="status" id="formStatus"></div>
        </form>
      </div>
    </section>

    <section class="card">
      <h2>Event Log</h2>
      <div class="log" id="eventLog"></div>
      <p class="footer-note">New events are appended in real time as the dashboard updates.</p>
    </section>
  </main>

  <script>
    // --- State ---
    const state = {
      requests: 120,
      users: 38,
      errorRate: 2.1,
      latency: 180,
      chartData: Array.from({ length: 12 }, () => Math.floor(Math.random() * 100))
    };

    // --- Elements ---
    const requestsMetric = document.getElementById("requestsMetric");
    const usersMetric = document.getElementById("usersMetric");
    const errorMetric = document.getElementById("errorMetric");
    const latencyMetric = document.getElementById("latencyMetric");
    const eventLog = document.getElementById("eventLog");
    const formStatus = document.getElementById("formStatus");
    const controlForm = document.getElementById("controlForm");
    const resetBtn = document.getElementById("resetBtn");

    // --- Chart ---
    const ctx = document.getElementById("realtimeChart").getContext("2d");
    const realtimeChart = new Chart(ctx, {
      type: "line",
      data: {
        labels: state.chartData.map((_, i) => `T-${state.chartData.length - i}`),
        datasets: [{
          label: "Traffic",
          data: state.chartData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        }
      }
    });

    // --- Helpers ---
    function updateMetrics() {
      requestsMetric.textContent = state.requests;
      usersMetric.textContent = state.users;
      errorMetric.textContent = `${state.errorRate.toFixed(1)}%`;
      latencyMetric.textContent = `${state.latency} ms`;
    }

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);
    }

    function randomDelta(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    // --- Real-time simulation ---
    function tick() {
      // Update state
      state.requests = Math.max(0, state.requests + randomDelta(-8, 15));
      state.users = Math.max(0, state.users + randomDelta(-2, 4));
      state.errorRate = Math.max(0, Math.min(100, state.errorRate + (Math.random() - 0.5) * 1.2));
      state.latency = Math.max(20, state.latency + randomDelta(-20, 25));

      // Update chart
      state.chartData.push(state.requests);
      state.chartData.shift();

      realtimeChart.data.labels.push(new Date().toLocaleTimeString());
      realtimeChart.data.labels.shift();
      realtimeChart.data.datasets[0].data = [...state.chartData];
      realtimeChart.update();

      // Update metrics
      updateMetrics();

      // Log notable events
      if (state.errorRate > 5) {
        addLog(`Warning: error rate elevated at ${state.errorRate.toFixed(1)}%`);
      } else {
        addLog(`Metrics refreshed: ${state.requests} req/min, ${state.users} users`);
      }
    }

    // --- Form handling ---
    controlForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const threshold = Number(document.getElementById("threshold").value);
      const mode = document.getElementById("mode").value;
      const note = document.getElementById("note").value.trim();

      formStatus.textContent = `Settings applied: threshold=${threshold}, mode=${mode}`;
      addLog(`Control updated: threshold set to ${threshold}, mode=${mode}${note ? `, note="${note}"` : ""}`);

      if (threshold < 10 || threshold > 90) {
        formStatus.style.color = "var(--danger)";
        formStatus.textContent = "Threshold is outside the recommended range.";
      } else {
        formStatus.style.color = "var(--success)";
      }
    });

    resetBtn.addEventListener("click", () => {
      controlForm.reset();
      document.getElementById("threshold").value = 75;
      formStatus.textContent = "Form reset to default values.";
      formStatus.style.color = "var(--success)";
      addLog("Control panel reset to defaults");
    });

    // --- Init ---
    updateMetrics();
    addLog("Dashboard initialized");
    setInterval(tick, 2000);
  </script>
</body>
</html>
