<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
    <p>Live data visualization, filtering, and form-based data entry.</p>
  </header>

  <main class="dashboard">
    <section class="panel">
      <h2>Live Metrics</h2>

      <div class="stats">
        <div class="stat">
          <label>Current Value</label>
          <strong id="currentValue">0</strong>
        </div>
        <div class="stat">
          <label>Average</label>
          <strong id="averageValue">0</strong>
        </div>
        <div class="stat">
          <label>Total Entries</label>
          <strong id="entryCount">0</strong>
        </div>
      </div>

      <div class="top-controls">
        <select id="timeRange">
          <option value="20">Last 20 points</option>
          <option value="50">Last 50 points</option>
          <option value="100">Last 100 points</option>
        </select>

        <button class="secondary-btn" id="toggleLive">Pause Live Updates</button>
      </div>

      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>
    </section>

    <aside class="panel">
      <h2>Add Data Point</h2>

      <form id="dataForm">
        <div class="field">
          <label for="label">Label</label>
          <input type="text" id="label" placeholder="e.g. Sensor A" required />
        </div>

        <div class="field">
          <label for="value">Value</label>
          <input type="number" id="value" placeholder="Enter numeric value" required />
        </div>

        <div class="field">
          <label for="category">Category</label>
          <select id="category" required>
            <option value="">Select category</option>
            <option value="Operations">Operations</option>
            <option value="Marketing">Marketing</option>
            <option value="Sales">Sales</option>
          </select>
        </div>

        <div class="row">
          <button type="submit">Add Entry</button>
          <button type="button" class="secondary-btn" id="clearData">Clear Data</button>
        </div>

        <div id="formMessage" class="message"></div>
      </form>

      <div class="table-wrap">
        <h2 style="margin-top: 22px;">Recent Entries</h2>
        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Value</th>
              <th>Category</th>
            </tr>
          </thead>
          <tbody id="dataTableBody"></tbody>
        </table>
      </div>
    </aside>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const maxPointsSelect = document.getElementById("timeRange");
    const toggleLiveBtn = document.getElementById("toggleLive");
    const clearDataBtn = document.getElementById("clearData");
    const dataForm = document.getElementById("dataForm");
    const formMessage = document.getElementById("formMessage");
    const dataTableBody = document.getElementById("dataTableBody");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const entryCountEl = document.getElementById("entryCount");

    let isLive = true;
    let dataPoints = [];
    let labels = [];
    let liveInterval;

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Data",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointHoverRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        }
      }
    });

    function updateStats() {
      const count = dataPoints.length;
      const current = count ? dataPoints[count - 1] : 0;
      const average = count ? (dataPoints.reduce((a, b) => a + b, 0) / count).toFixed(2) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = average;
      entryCountEl.textContent = count;
    }

    function renderTable() {
      dataTableBody.innerHTML = "";

      const recentEntries = JSON.parse(localStorage.getItem("dashboardEntries") || "[]").slice(-10).reverse();

      recentEntries.forEach(entry => {
        const row = document.createElement("tr");
        row.innerHTML = `
          <td>${entry.label}</td>
          <td>${entry.value}</td>
          <td>${entry.category}</td>
        `;
        dataTableBody.appendChild(row);
      });
    }

    function saveEntry(entry) {
      const existing = JSON.parse(localStorage.getItem("dashboardEntries") || "[]");
      existing.push(entry);
      localStorage.setItem("dashboardEntries", JSON.stringify(existing));
    }

    function addDataPoint(value, label = `Point ${labels.length + 1}`) {
      labels.push(label);
      dataPoints.push(value);

      const maxPoints = parseInt(maxPointsSelect.value, 10);
      if (dataPoints.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      updateStats();
    }

    function generateRandomPoint() {
      if (!isLive) return;
      const value = Math.floor(Math.random() * 100) + 1;
      addDataPoint(value, new Date().toLocaleTimeString());
    }

    function showMessage(text, type = "") {
      formMessage.textContent = text;
      formMessage.className = `message ${type}`;
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = document.getElementById("label").value.trim();
      const value = Number(document.getElementById("value").value);
      const category = document.getElementById("category").value;

      if (!label || Number.isNaN(value) || !category) {
        showMessage("Please complete all fields with valid values.", "error");
        return;
      }

      const entry = {
        label,
        value,
        category,
        timestamp: new Date().toISOString()
      };

      saveEntry(entry);
      addDataPoint(value, label);
      renderTable();

      dataForm.reset();
      showMessage("Entry added successfully.", "success");
    });

    maxPointsSelect.addEventListener("change", () => {
      const maxPoints = parseInt(maxPointsSelect.value, 10);
      while (dataPoints.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }
      chart.update();
      updateStats();
    });

    toggleLiveBtn.addEventListener("click", () => {
      isLive = !isLive;
      toggleLiveBtn.textContent = isLive ? "Pause Live Updates" : "Resume Live Updates";
    });

    clearDataBtn.addEventListener("click", () => {
      dataPoints = [];
      labels = [];
      chart.data.labels = labels;
      chart.data.datasets[0].data = dataPoints;
      chart.update();

      localStorage.removeItem("dashboardEntries");
      renderTable();
      updateStats();
      showMessage("All data cleared.", "success");
    });

    // Load initial sample data
    for (let i = 0; i < 10; i++) {
      addDataPoint(Math.floor(Math.random() * 100) + 1, `Init ${i + 1}`);
    }

    renderTable();
    updateStats();

    // Start live updates
    liveInterval = setInterval(generateRandomPoint, 2000);
  </script>
</body>
</html>
```

