## 4) `app.js`

```javascript
const ctx = document.getElementById("activityChart");

const requestsCountEl = document.getElementById("requestsCount");
const errorsCountEl = document.getElementById("errorsCount");
const latencyValueEl = document.getElementById("latencyValue");
const usersCountEl = document.getElementById("usersCount");
const eventLogEl = document.getElementById("eventLog");
const formFeedbackEl = document.getElementById("formFeedback");
const trafficInput = document.getElementById("trafficInput");
const trafficValue = document.getElementById("trafficValue");
const intervalInput = document.getElementById("intervalInput");
const modeSelect = document.getElementById("modeSelect");
const alertsToggle = document.getElementById("alertsToggle");
const settingsForm = document.getElementById("settingsForm");
const resetDataBtn = document.getElementById("resetDataBtn");
const connectionStatus = document.getElementById("connectionStatus");

let updateIntervalMs = 1000;
let trafficLevel = 5;
let alertsEnabled = true;
let mode = "normal";
let timer = null;

const state = {
  requests: 0,
  errors: 0,
  latency: 0,
  users: 0,
  labels: [],
  values: []
};

const maxPoints = 20;

function logEvent(message, type = "") {
  const li = document.createElement("li");
  if (type) li.classList.add(type);
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 20) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  requestsCountEl.textContent = state.requests.toLocaleString();
  errorsCountEl.textContent = state.errors.toLocaleString();
  latencyValueEl.textContent = `${Math.round(state.latency)} ms`;
  usersCountEl.textContent = state.users.toLocaleString();
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: state.labels,
    datasets: [
      {
        label: "Traffic",
        data: state.values,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      }
    }
  }
});

function simulateIncomingData() {
  const trafficMultiplier = trafficLevel / 5;
  const requestsDelta = Math.floor(Math.random() * 20 + 10) * trafficMultiplier;
  const errorChance = Math.random() < 0.15 + (trafficLevel * 0.01);
  const latency = 80 + Math.random() * 220 * trafficMultiplier;
  const usersDelta = Math.floor(Math.random() * 8 * trafficMultiplier);

  state.requests += Math.round(requestsDelta);
  state.errors += errorChance ? 1 : 0;
  state.latency = latency;
  state.users = Math.max(0, state.users + usersDelta - Math.floor(Math.random() * 4));

  const now = new Date().toLocaleTimeString();
  const value = Math.round(requestsDelta);

  state.labels.push(now);
  state.values.push(value);

  if (state.labels.length > maxPoints) {
    state.labels.shift();
    state.values.shift();
  }

  chart.update();
  updateMetrics();

  logEvent(`Received ${value} new requests`, "success");

  if (errorChance) {
    logEvent("An error occurred while processing data", "error");
    if (alertsEnabled) {
      connectionStatus.textContent = "● Alert";
      connectionStatus.style.background = "rgba(239, 68, 68, 0.15)";
      connectionStatus.style.color = "#fecaca";
      connectionStatus.style.borderColor = "rgba(239, 68, 68, 0.25)";
    }
  } else {
    connectionStatus.textContent = "● Live";
    connectionStatus.style.background = "rgba(34, 197, 94, 0.15)";
    connectionStatus.style.color = "#86efac";
    connectionStatus.style.borderColor = "rgba(34, 197, 94, 0.25)";
  }
}

function startStreaming() {
  if (timer) clearInterval(timer);
  timer = setInterval(simulateIncomingData, updateIntervalMs);
}

function resetDashboard() {
  state.requests = 0;
  state.errors = 0;
  state.latency = 0;
  state.users = 0;
  state.labels = [];
  state.values = [];

  chart.data.labels = state.labels;
  chart.data.datasets[0].data = state.values;
  chart.update();
  updateMetrics();

  eventLogEl.innerHTML = "";
  logEvent("Dashboard reset", "success");
  formFeedbackEl.textContent = "";
}

trafficInput.addEventListener("input", () => {
  trafficLevel = Number(trafficInput.value);
  trafficValue.textContent = trafficLevel;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const newInterval = Number(intervalInput.value);
  const newMode = modeSelect.value;
  const newAlertsEnabled = alertsToggle.checked;

  if (Number.isNaN(newInterval) || newInterval < 250) {
    formFeedbackEl.textContent = "Please enter an interval of at least 250 ms.";
    return;
  }

  updateIntervalMs = newInterval;
  mode = newMode;
  alertsEnabled = newAlertsEnabled;

  document.body.dataset.mode = mode;

  if (mode === "compact") {
    document.documentElement.style.fontSize = "14px";
  } else if (mode === "focus") {
    document.documentElement.style.fontSize = "16px";
  } else {
    document.documentElement.style.fontSize = "15px";
  }

  startStreaming();

  formFeedbackEl.textContent = `Settings applied: interval ${updateIntervalMs}ms, mode ${mode}, alerts ${alertsEnabled ? "on" : "off"}.`;
  logEvent("Settings updated", "success");
});

resetDataBtn.addEventListener("click", resetDashboard);

intervalInput.addEventListener("change", () => {
  const value = Number(intervalInput.value);
  if (!Number.isNaN(value) && value >= 250) {
    updateIntervalMs = value;
    startStreaming();
    logEvent(`Update interval changed to ${updateIntervalMs}ms`, "success");
  }
});

window.addEventListener("load", () => {
  logEvent("Dashboard initialized", "success");
  updateMetrics();
  startStreaming();
});
```

