  <script>
    // Initial state
    let visitors = 1240;
    let conversions = 86;
    let revenue = 15420;
    let activeUsers = 34;

    const visitorsEl = document.getElementById("visitors");
    const conversionsEl = document.getElementById("conversions");
    const revenueEl = document.getElementById("revenue");
    const activeUsersEl = document.getElementById("activeUsers");

    const visitorsDeltaEl = document.getElementById("visitorsDelta");
    const conversionsDeltaEl = document.getElementById("conversionsDelta");
    const revenueDeltaEl = document.getElementById("revenueDelta");
    const activeUsersDeltaEl = document.getElementById("activeUsersDelta");

    const activityLog = document.getElementById("activityLog");
    const form = document.getElementById("eventForm");

    function formatCurrency(value) {
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0
      }).format(value);
    }

    function updateCards() {
      visitorsEl.textContent = visitors.toLocaleString();
      conversionsEl.textContent = conversions.toLocaleString();
      revenueEl.textContent = formatCurrency(revenue);
      activeUsersEl.textContent = activeUsers.toLocaleString();

      visitorsDeltaEl.textContent = `+${Math.floor(Math.random() * 20 + 1)} today`;
      conversionsDeltaEl.textContent = `+${Math.floor(Math.random() * 5 + 1)} today`;
      revenueDeltaEl.textContent = `+${Math.floor(Math.random() * 1200 + 100)} today`;
      activeUsersDeltaEl.textContent = `+${Math.floor(Math.random() * 4 + 1)} now`;
    }

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `<strong>${new Date().toLocaleTimeString()}</strong><br>${message}`;
      activityLog.prepend(item);

      // Keep only latest 8 items
      while (activityLog.children.length > 8) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    // Chart setup
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const labels = ["12:00", "12:02", "12:04", "12:06", "12:08", "12:10", "12:12", "12:14"];
    const trafficData = [40, 55, 48, 68, 72, 65, 80, 76];

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.5)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.5)" }
          }
        }
      }
    });

    function updateChart() {
      const lastValue = trafficChart.data.datasets[0].data.at(-1);
      const nextValue = Math.max(10, lastValue + Math.floor(Math.random() * 21 - 10));

      const now = new Date();
      const timeLabel = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

      trafficChart.data.labels.push(timeLabel);
      trafficChart.data.datasets[0].data.push(nextValue);

      if (trafficChart.data.labels.length > 10) {
        trafficChart.data.labels.shift();
        trafficChart.data.datasets[0].data.shift();
      }

      trafficChart.update();
    }

    function simulateLiveData() {
      visitors += Math.floor(Math.random() * 15);
      conversions += Math.floor(Math.random() * 3);
      revenue += Math.floor(Math.random() * 500);
      activeUsers = Math.max(10, activeUsers + Math.floor(Math.random() * 7 - 3));

      updateCards();
      updateChart();
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const type = document.getElementById("type").value;
      const notes = document.getElementById("notes").value.trim();

      const message = `${name} submitted a <strong>${type}</strong> event${notes ? `: ${notes}` : ""}.`;
      addLog(message);

      // Simple form feedback
      form.reset();
    });

    // Initial render
    updateCards();
    addLog("Dashboard initialized.");
    addLog("Live data stream connected.");

    // Real-time simulation
    setInterval(simulateLiveData, 2000);
  </script>
</body>
