## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const formFeedbackEl = document.getElementById("formFeedback");
const connectionStatusEl = document.getElementById("connectionStatus");

const settingsForm = document.getElementById("settingsForm");
const alertThresholdInput = document.getElementById("alertThreshold");
const refreshIntervalInput = document.getElementById("refreshInterval");
const dashboardModeSelect = document.getElementById("dashboardMode");

const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const clearLogBtn = document.getElementById("clearLogBtn");

let isStreaming = true;
let refreshInterval = 1000;
let alertThreshold = 100;
let streamTimer = null;

const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
const trafficData = Array(12).fill(0);

const ctx = document.getElementById("trafficChart").getContext("2d");
const trafficChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests / min",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

function logEvent(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);
}

function updateMetrics() {
  const activeUsers = Math.floor(Math.random() * 500) + 50;
  const requestsPerMin = Math.floor(Math.random() * 300) + 20;
  const errorRate = (Math.random() * 8).toFixed(1);

  activeUsersEl.textContent = activeUsers;
  requestsPerMinEl.textContent = requestsPerMin;
  errorRateEl.textContent = `${errorRate}%`;

  trafficData.shift();
  trafficData.push(requestsPerMin);
  trafficChart.update();

  if (requestsPerMin > alertThreshold) {
    logEvent(`Alert threshold exceeded: ${requestsPerMin} req/min`);
  }
}

function startStreaming() {
  stopStreaming();
  streamTimer = setInterval(() => {
    if (isStreaming) updateMetrics();
  }, refreshInterval);
  connectionStatusEl.textContent = "Live";
}

function stopStreaming() {
  if (streamTimer) clearInterval(streamTimer);
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  alertThreshold = Number(alertThresholdInput.value);
  refreshInterval = Number(refreshIntervalInput.value);
  const mode = dashboardModeSelect.value;

  document.body.dataset.mode = mode;

  formFeedbackEl.textContent = "Settings applied successfully.";
  logEvent(
    `Settings updated: threshold=${alertThreshold}, refresh=${refreshInterval}ms, mode=${mode}`
  );

  startStreaming();
});

toggleStreamBtn.addEventListener("click", () => {
  isStreaming = !isStreaming;
  toggleStreamBtn.textContent = isStreaming ? "Pause" : "Resume";
  connectionStatusEl.textContent = isStreaming ? "Live" : "Paused";
  logEvent(isStreaming ? "Streaming resumed" : "Streaming paused");
});

clearLogBtn.addEventListener("click", () => {
  eventLogEl.innerHTML = "";
  logEvent("Event log cleared");
});

// Initial state
logEvent("Dashboard initialized");
updateMetrics();
startStreaming();
```

