## 4) `app.js`

```javascript
const visitorsValue = document.getElementById("visitorsValue");
const ordersValue = document.getElementById("ordersValue");
const revenueValue = document.getElementById("revenueValue");
const eventLog = document.getElementById("eventLog");
const eventForm = document.getElementById("eventForm");
const toggleLiveBtn = document.getElementById("toggleLiveBtn");
const connectionDot = document.getElementById("connectionDot");
const connectionText = document.getElementById("connectionText");

const ctx = document.getElementById("trendChart").getContext("2d");

let liveUpdates = true;
let visitors = 120;
let orders = 18;
let revenue = 2450;

const chartData = {
  labels: [],
  datasets: [
    {
      label: "Visitors",
      data: [],
      borderColor: "#60a5fa",
      backgroundColor: "rgba(96, 165, 250, 0.15)",
      tension: 0.3,
      fill: true,
    },
    {
      label: "Orders",
      data: [],
      borderColor: "#22c55e",
      backgroundColor: "rgba(34, 197, 94, 0.15)",
      tension: 0.3,
      fill: true,
    },
  ],
};

const trendChart = new Chart(ctx, {
  type: "line",
  data: chartData,
  options: {
    responsive: true,
    maintainAspectRatio: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "#1f2937" },
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "#1f2937" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e2e8f0" },
      },
    },
  },
});

function updateMetrics() {
  visitorsValue.textContent = visitors.toLocaleString();
  ordersValue.textContent = orders.toLocaleString();
  revenueValue.textContent = `$${revenue.toLocaleString()}`;
}

function addLogEntry(message) {
  const li = document.createElement("li");
  const time = new Date().toLocaleTimeString();
  li.innerHTML = `<strong>[${time}]</strong> ${message}`;
  eventLog.prepend(li);
}

function pushChartPoint() {
  const time = new Date().toLocaleTimeString();

  if (chartData.labels.length >= 12) {
    chartData.labels.shift();
    chartData.datasets[0].data.shift();
    chartData.datasets[1].data.shift();
  }

  chartData.labels.push(time);
  chartData.datasets[0].data.push(visitors);
  chartData.datasets[1].data.push(orders);
  trendChart.update();
}

function simulateLiveUpdate() {
  if (!liveUpdates) return;

  visitors += Math.floor(Math.random() * 10) - 2;
  orders += Math.floor(Math.random() * 4);
  revenue += Math.floor(Math.random() * 250);

  visitors = Math.max(visitors, 0);

  updateMetrics();
  pushChartPoint();
  addLogEntry(`Live update received: visitors=${visitors}, orders=${orders}, revenue=$${revenue}`);
}

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = document.getElementById("eventName").value.trim();
  const value = Number(document.getElementById("eventValue").value);
  const category = document.getElementById("eventCategory").value;

  if (!name || Number.isNaN(value) || !category) return;

  if (category === "traffic") visitors += value;
  if (category === "sales") {
    orders += Math.max(1, Math.floor(value / 10));
    revenue += value * 5;
  }
  if (category === "engagement") visitors += Math.floor(value / 2);

  updateMetrics();
  pushChartPoint();
  addLogEntry(`Manual event added: ${name} (${category}) with value ${value}`);

  eventForm.reset();
});

toggleLiveBtn.addEventListener("click", () => {
  liveUpdates = !liveUpdates;
  toggleLiveBtn.textContent = liveUpdates ? "Pause Live Updates" : "Resume Live Updates";
  connectionDot.style.background = liveUpdates ? "#22c55e" : "#f59e0b";
  connectionDot.style.boxShadow = liveUpdates ? "0 0 8px #22c55e" : "0 0 8px #f59e0b";
  connectionText.textContent = liveUpdates ? "Connected" : "Paused";
});

updateMetrics();
pushChartPoint();
addLogEntry("Dashboard initialized successfully.");

setInterval(simulateLiveUpdate, 2000);
```

