        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="card">
        <h2 class="panel-title">Submit Event</h2>
        <form id="eventForm">
          <div>
            <label for="name">Event Name</label>
            <input id="name" name="name" type="text" placeholder="e.g. Signup" required />
          </div>

          <div>
            <label for="type">Type</label>
            <select id="type" name="type" required>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="critical">Critical</option>
            </select>
          </div>

          <div>
            <label for="details">Details</label>
            <textarea id="details" name="details" placeholder="Add details..." required></textarea>
          </div>

          <button type="submit">Submit Event</button>
        </form>

        <div class="log" id="eventLog" aria-live="polite">
          <div class="log-entry">System initialized.</div>
        </div>
      </div>
    </section>
  </main>

  <script>
    // Chart setup
    const ctx = document.getElementById('trafficChart').getContext('2d');
    const labels = Array.from({ length: 12 }, (_, i) => `${12 - i}m ago`).reverse();
    const trafficData = labels.map(() => Math.floor(Math.random() * 100) + 50);

    const trafficChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Requests',
          data: trafficData,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: '#38bdf8'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(55, 65, 81, 0.4)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(55, 65, 81, 0.4)' }
          }
        }
      }
    });

    // Dashboard state
    const activeUsersEl = document.getElementById('activeUsers');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const responseTimeEl = document.getElementById('responseTime');

    const activeUsersTrendEl = document.getElementById('activeUsersTrend');
    const requestsTrendEl = document.getElementById('requestsTrend');
    const errorTrendEl = document.getElementById('errorTrend');
    const responseTrendEl = document.getElementById('responseTrend');

    let activeUsers = 120;
    let requestsPerMin = 340;
    let errorRate = 1.8;
    let responseTime = 220;

    function updateStats() {
      const userDelta = Math.floor(Math.random() * 11 - 3);
      const reqDelta = Math.floor(Math.random() * 21 - 5);
      const errDelta = (Math.random() * 0.4 - 0.15);
      const respDelta = Math.floor(Math.random() * 30 - 10);

      activeUsers = Math.max(0, activeUsers + userDelta);
      requestsPerMin = Math.max(0, requestsPerMin + reqDelta);
      errorRate = Math.max(0, +(errorRate + errDelta).toFixed(2));
      responseTime = Math.max(50, responseTime + respDelta);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;
      responseTimeEl.textContent = `${responseTime} ms`;

      activeUsersTrendEl.textContent = `${userDelta >= 0 ? '+' : ''}${userDelta}% this minute`;
      requestsTrendEl.textContent = reqDelta >= 0 ? 'Increasing' : 'Decreasing';
      errorTrendEl.textContent = errorRate < 2 ? 'Within threshold' : 'Needs attention';
      responseTrendEl.textContent = responseTime < 300 ? 'Good performance' : 'Latency high';
    }

    function updateChart() {
      trafficData.shift();
      trafficData.push(Math.floor(Math.random() * 100) + 50);
      trafficChart.update();
    }

    // Form handling
    const eventForm = document.getElementById('eventForm');
    const eventLog = document.getElementById('eventLog');

    function addLogEntry(message, type = 'info') {
      const entry = document.createElement('div');
      entry.className = 'log-entry';
      entry.innerHTML = `<strong>[${type.toUpperCase()}]</strong> ${message}`;
      eventLog.prepend(entry);
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(eventForm);
      const name = formData.get('name');
      const type = formData.get('type');
      const details = formData.get('details');

      addLogEntry(`${name} — ${details}`, type);

      // Simulate form submission side effects
      if (type === 'critical') {
        errorRate = Math.min(100, errorRate + 1.2);
        responseTime += 40;
      }

      eventForm.reset();
      updateStats();
    });

    // Initial render
    updateStats();

    // Real-time updates
    setInterval(() => {
      updateStats();
      updateChart();
    }, 2000);
  </script>
</body>
</html>
```

