## 4) `app.js`

```javascript
const eventFeed = document.getElementById("eventFeed");
const eventForm = document.getElementById("eventForm");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatus = document.getElementById("connectionStatus");

const activeUsersEl = document.getElementById("activeUsers");
const revenueEl = document.getElementById("revenue");
const conversionRateEl = document.getElementById("conversionRate");
const ordersEl = document.getElementById("orders");

const categoryTotals = {
  Sales: 120,
  Marketing: 90,
  Support: 60,
  Product: 100,
};

let streamRunning = true;

const activityCtx = document.getElementById("activityChart").getContext("2d");
const categoryCtx = document.getElementById("categoryChart").getContext("2d");

const activityChart = new Chart(activityCtx, {
  type: "line",
  data: {
    labels: Array.from({ length: 10 }, (_, i) => `T-${9 - i}`),
    datasets: [
      {
        label: "Live Activity",
        data: [12, 19, 15, 22, 18, 26, 24, 30, 28, 34],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

const categoryChart = new Chart(categoryCtx, {
  type: "doughnut",
  data: {
    labels: Object.keys(categoryTotals),
    datasets: [
      {
        data: Object.values(categoryTotals),
        backgroundColor: ["#38bdf8", "#22c55e", "#f59e0b", "#a78bfa"],
        borderWidth: 0,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function formatCurrency(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(value);
}

function addEventToFeed(name, category, value, source = "manual") {
  const li = document.createElement("li");
  const time = new Date().toLocaleTimeString();

  li.innerHTML = `
    <div>
      <strong>${name}</strong>
      <div class="event-meta">${category} • ${time} • ${source}</div>
    </div>
    <div class="event-value">${value}</div>
  `;

  eventFeed.prepend(li);

  while (eventFeed.children.length > 8) {
    eventFeed.removeChild(eventFeed.lastChild);
  }
}

function updateMetrics(deltaValue) {
  const activeUsers = parseInt(activeUsersEl.textContent.replace(/,/g, ""), 10);
  const revenue = parseInt(revenueEl.textContent.replace(/[$,]/g, ""), 10);
  const orders = parseInt(ordersEl.textContent.replace(/,/g, ""), 10);
  const conversionRate = parseFloat(conversionRateEl.textContent.replace("%", ""));

  activeUsersEl.textContent = (activeUsers + Math.floor(Math.random() * 12)).toLocaleString();
  revenueEl.textContent = formatCurrency(revenue + deltaValue * 5);
  ordersEl.textContent = (orders + Math.max(1, Math.floor(deltaValue / 10))).toLocaleString();
  conversionRateEl.textContent = (conversionRate + (Math.random() * 0.2 - 0.05)).toFixed(1) + "%";
}

function updateCharts(newValue) {
  activityChart.data.labels.push(new Date().toLocaleTimeString());
  activityChart.data.datasets[0].data.push(newValue);

  if (activityChart.data.labels.length > 12) {
    activityChart.data.labels.shift();
    activityChart.data.datasets[0].data.shift();
  }

  activityChart.update();

  categoryChart.data.datasets[0].data = Object.values(categoryTotals);
  categoryChart.update();
}

function simulateRealtimeEvent() {
  const categories = Object.keys(categoryTotals);
  const category = categories[Math.floor(Math.random() * categories.length)];
  const value = Math.floor(Math.random() * 40) + 10;

  categoryTotals[category] += value;

  updateMetrics(value);
  updateCharts(value);
  addEventToFeed(`Auto ${category} Event`, category, value, "auto");
}

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = document.getElementById("eventName").value.trim();
  const category = document.getElementById("eventCategory").value;
  const value = parseInt(document.getElementById("eventValue").value, 10);

  if (!name || !category || Number.isNaN(value) || value <= 0) return;

  categoryTotals[category] = (categoryTotals[category] || 0) + value;

  updateMetrics(value);
  updateCharts(value);
  addEventToFeed(name, category, value, "manual");

  eventForm.reset();
});

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;

  if (streamRunning) {
    toggleStreamBtn.textContent = "Pause Stream";
    connectionStatus.textContent = "● Live";
    connectionStatus.style.background = "rgba(34, 197, 94, 0.12)";
    connectionStatus.style.color = "#86efac";
  } else {
    toggleStreamBtn.textContent = "Resume Stream";
    connectionStatus.textContent = "● Paused";
    connectionStatus.style.background = "rgba(245, 158, 11, 0.12)";
    connectionStatus.style.color = "#fbbf24";
  }
});

addEventToFeed("Dashboard initialized", "System", 1, "system");

setInterval(() => {
  if (streamRunning) simulateRealtimeEvent();
}, 2500);
```

