## 4) `app.js`

```javascript
const usersOnlineEl = document.getElementById("usersOnline");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const avgLatencyEl = document.getElementById("avgLatency");
const eventLogEl = document.getElementById("eventLog");
const formOutputEl = document.getElementById("formOutput");
const thresholdInput = document.getElementById("threshold");
const thresholdValueEl = document.getElementById("thresholdValue");
const updateIntervalInput = document.getElementById("updateInterval");
const settingsForm = document.getElementById("settingsForm");
const pauseBtn = document.getElementById("pauseBtn");
const resetBtn = document.getElementById("resetBtn");
const connectionStatus = document.getElementById("connectionStatus");

const ctx = document.getElementById("activityChart").getContext("2d");

let isPaused = false;
let updateInterval = Number(updateIntervalInput.value);
let timer = null;

const dataPoints = {
  labels: [],
  users: [],
  requests: [],
  errors: [],
  latency: [],
};

function randomBetween(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addLog(message) {
  const item = document.createElement("li");
  item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(item);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: dataPoints.labels,
    datasets: [
      {
        label: "Users Online",
        data: dataPoints.users,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
      },
      {
        label: "Requests/min",
        data: dataPoints.requests,
        borderColor: "#22c55e",
        backgroundColor: "rgba(34, 197, 94, 0.15)",
        tension: 0.35,
      },
      {
        label: "Latency (ms)",
        data: dataPoints.latency,
        borderColor: "#f59e0b",
        backgroundColor: "rgba(245, 158, 11, 0.15)",
        tension: 0.35,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
  },
});

function updateMetrics() {
  const usersOnline = randomBetween(80, 500);
  const requestsPerMin = randomBetween(200, 1500);
  const errorRate = (Math.random() * 5).toFixed(2);
  const avgLatency = randomBetween(50, 450);

  usersOnlineEl.textContent = usersOnline;
  requestsPerMinEl.textContent = requestsPerMin;
  errorRateEl.textContent = `${errorRate}%`;
  avgLatencyEl.textContent = `${avgLatency} ms`;

  const timestamp = new Date().toLocaleTimeString();

  dataPoints.labels.push(timestamp);
  dataPoints.users.push(usersOnline);
  dataPoints.requests.push(requestsPerMin);
  dataPoints.latency.push(avgLatency);

  if (dataPoints.labels.length > 12) {
    dataPoints.labels.shift();
    dataPoints.users.shift();
    dataPoints.requests.shift();
    dataPoints.latency.shift();
  }

  chart.update();

  if (Number(errorRate) > Number(thresholdInput.value) / 20) {
    addLog(`Warning: error rate elevated at ${errorRate}%`);
  } else {
    addLog(`Metrics updated: ${usersOnline} users, ${requestsPerMin} req/min`);
  }
}

function startStreaming() {
  clearInterval(timer);
  timer = setInterval(() => {
    if (!isPaused) {
      updateMetrics();
    }
  }, updateInterval);
}

thresholdInput.addEventListener("input", () => {
  thresholdValueEl.textContent = thresholdInput.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const email = document.getElementById("alertEmail").value;
  const alertsEnabled = document.getElementById("enableAlerts").checked;
  const newInterval = Number(updateIntervalInput.value);

  if (newInterval >= 500) {
    updateInterval = newInterval;
    startStreaming();
  }

  formOutputEl.textContent = `Saved settings: interval=${updateInterval}ms, threshold=${thresholdInput.value}, alerts=${alertsEnabled ? "enabled" : "disabled"}${email ? `, email=${email}` : ""}`;
  addLog("Settings saved successfully.");
});

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume" : "Pause";
  connectionStatus.textContent = isPaused ? "Paused" : "Live";
  connectionStatus.style.background = isPaused ? "rgba(245, 158, 11, 0.15)" : "rgba(34, 197, 94, 0.15)";
  connectionStatus.style.color = isPaused ? "#fcd34d" : "#86efac";
  connectionStatus.style.borderColor = isPaused ? "rgba(245, 158, 11, 0.3)" : "rgba(34, 197, 94, 0.3)";
  addLog(isPaused ? "Live updates paused." : "Live updates resumed.");
});

resetBtn.addEventListener("click", () => {
  dataPoints.labels.length = 0;
  dataPoints.users.length = 0;
  dataPoints.requests.length = 0;
  dataPoints.latency.length = 0;

  chart.update();

  usersOnlineEl.textContent = "0";
  requestsPerMinEl.textContent = "0";
  errorRateEl.textContent = "0%";
  avgLatencyEl.textContent = "0 ms";

  eventLogEl.innerHTML = "";
  addLog("Dashboard reset.");
});

startStreaming();
updateMetrics();
addLog("Dashboard initialized.");
```

