## 4) `app.js`

```javascript
const requestsEl = document.getElementById("requestsPerSec");
const usersEl = document.getElementById("activeUsers");
const errorRateEl = document.getElementById("errorRate");
const latencyEl = document.getElementById("avgLatency");
const feedEl = document.getElementById("activityFeed");
const submissionOutput = document.getElementById("submissionOutput");
const thresholdValue = document.getElementById("thresholdValue");
const connectionStatus = document.getElementById("connectionStatus");
const refreshBtn = document.getElementById("refreshBtn");
const settingsForm = document.getElementById("settingsForm");

const ctx = document.getElementById("realtimeChart").getContext("2d");

const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
const dataPoints = labels.map(() => Math.floor(Math.random() * 100));

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests/sec",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      y: {
        beginAtZero: true,
        grid: { color: "rgba(255,255,255,0.08)" },
        ticks: { color: "#9ca3af" },
      },
      x: {
        grid: { color: "rgba(255,255,255,0.05)" },
        ticks: { color: "#9ca3af" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function randomMetric(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addActivity(message) {
  const li = document.createElement("li");
  li.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
  feedEl.prepend(li);

  while (feedEl.children.length > 8) {
    feedEl.removeChild(feedEl.lastChild);
  }
}

function updateMetrics() {
  const requests = randomMetric(20, 180);
  const users = randomMetric(100, 1200);
  const errorRate = (Math.random() * 5).toFixed(2);
  const latency = randomMetric(80, 600);

  requestsEl.textContent = requests;
  usersEl.textContent = users;
  errorRateEl.textContent = `${errorRate}%`;
  latencyEl.textContent = `${latency} ms`;

  chart.data.labels.push(new Date().toLocaleTimeString());
  chart.data.datasets[0].data.push(requests);

  if (chart.data.labels.length > 12) {
    chart.data.labels.shift();
    chart.data.datasets[0].data.shift();
  }

  chart.update();

  if (parseFloat(errorRate) > 4) {
    addActivity(`High error rate detected: ${errorRate}%`);
  } else {
    addActivity(`Metrics updated: ${requests} req/s, ${users} users`);
  }
}

function setConnectionState(connected) {
  if (connected) {
    connectionStatus.textContent = "● Connected";
    connectionStatus.style.background = "rgba(34, 197, 94, 0.15)";
    connectionStatus.style.color = "#86efac";
  } else {
    connectionStatus.textContent = "● Disconnected";
    connectionStatus.style.background = "rgba(239, 68, 68, 0.15)";
    connectionStatus.style.color = "#fca5a5";
  }
}

document.querySelector('input[name="threshold"]').addEventListener("input", (e) => {
  thresholdValue.textContent = e.target.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(settingsForm);
  const payload = {
    dashboardName: formData.get("dashboardName"),
    threshold: formData.get("threshold"),
    mode: formData.get("mode"),
    notifications: formData.get("notifications") === "on",
    submittedAt: new Date().toISOString(),
  };

  submissionOutput.textContent = JSON.stringify(payload, null, 2);
  addActivity(`Settings saved for "${payload.dashboardName}" in ${payload.mode} mode`);
});

refreshBtn.addEventListener("click", () => {
  updateMetrics();
  addActivity("Manual refresh triggered");
});

setInterval(() => {
  updateMetrics();
}, 3000);

// Simulate occasional connection changes
setInterval(() => {
  const connected = Math.random() > 0.1;
  setConnectionState(connected);
}, 10000);

// Initial render
updateMetrics();
addActivity("Dashboard initialized");
```

