## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const settingsForm = document.getElementById("settingsForm");
const settingsOutput = document.getElementById("settingsOutput");
const thresholdValue = document.getElementById("thresholdValue");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatus = document.getElementById("connectionStatus");

const dashboardNameInput = settingsForm.elements["dashboardName"];
const refreshIntervalInput = settingsForm.elements["refreshInterval"];
const alertThresholdInput = settingsForm.elements["alertThreshold"];

let streamActive = true;
let refreshInterval = Number(refreshIntervalInput.value);
let streamTimer = null;

let trafficData = Array.from({ length: 10 }, () => Math.floor(Math.random() * 100));
let labels = trafficData.map((_, i) => `T-${9 - i}`);

let categoryData = [35, 25, 20, 20];

function addLog(message) {
  const li = document.createElement("li");
  const now = new Date().toLocaleTimeString();
  li.textContent = `[${now}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 12) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const categoryCtx = document.getElementById("categoryChart").getContext("2d");

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

const categoryChart = new Chart(categoryCtx, {
  type: "doughnut",
  data: {
    labels: ["API", "Auth", "Payments", "Other"],
    datasets: [
      {
        data: categoryData,
        backgroundColor: ["#38bdf8", "#22c55e", "#f59e0b", "#a855f7"],
        borderColor: "#111827",
        borderWidth: 2,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function updateDashboard() {
  const newRequests = randomInt(40, 180);
  const newUsers = randomInt(1200, 5000);
  const newErrorRate = randomInt(0, 12);

  trafficData.push(newRequests);
  labels.push(new Date().toLocaleTimeString());

  if (trafficData.length > 10) trafficData.shift();
  if (labels.length > 10) labels.shift();

  categoryData = [
    randomInt(20, 50),
    randomInt(10, 35),
    randomInt(10, 30),
    randomInt(5, 20),
  ];

  activeUsersEl.textContent = newUsers.toLocaleString();
  requestsPerMinEl.textContent = newRequests.toLocaleString();
  errorRateEl.textContent = `${newErrorRate}%`;

  trafficChart.data.labels = labels;
  trafficChart.data.datasets[0].data = trafficData;
  trafficChart.update();

  categoryChart.data.datasets[0].data = categoryData;
  categoryChart.update();

  if (newErrorRate >= Number(alertThresholdInput.value)) {
    addLog(`Alert: error rate exceeded threshold (${newErrorRate}%)`);
  } else {
    addLog(`Updated metrics: ${newRequests} req/min, ${newUsers} users`);
  }
}

function startStream() {
  stopStream();
  streamTimer = setInterval(updateDashboard, refreshInterval);
  connectionStatus.textContent = "● Connected";
  connectionStatus.style.background = "rgba(34, 197, 94, 0.15)";
  connectionStatus.style.color = "#86efac";
}

function stopStream() {
  if (streamTimer) clearInterval(streamTimer);
  streamTimer = null;
}

toggleStreamBtn.addEventListener("click", () => {
  streamActive = !streamActive;

  if (streamActive) {
    toggleStreamBtn.textContent = "Pause Stream";
    startStream();
    addLog("Stream resumed");
  } else {
    toggleStreamBtn.textContent = "Resume Stream";
    stopStream();
    connectionStatus.textContent = "● Paused";
    connectionStatus.style.background = "rgba(239, 68, 68, 0.15)";
    connectionStatus.style.color = "#fca5a5";
    addLog("Stream paused");
  }
});

alertThresholdInput.addEventListener("input", () => {
  thresholdValue.textContent = alertThresholdInput.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(settingsForm);
  const settings = Object.fromEntries(formData.entries());

  settings.refreshInterval = Number(settings.refreshInterval);
  settings.alertThreshold = Number(settings.alertThreshold);

  dashboardNameInput.value = settings.dashboardName;
  refreshInterval = settings.refreshInterval;

  settingsOutput.textContent = JSON.stringify(settings, null, 2);
  addLog(`Settings applied for "${settings.dashboardName}"`);

  if (streamActive) {
    startStream();
  }
});

settingsOutput.textContent = JSON.stringify(
  {
    dashboardName: "My Dashboard",
    refreshInterval,
    alertThreshold: Number(alertThresholdInput.value),
  },
  null,
  2
);

thresholdValue.textContent = alertThresholdInput.value;
addLog("Dashboard initialized");
startStream();
updateDashboard();
```

