const memoryValueEl = document.getElementById("memoryValue");
const latencyValueEl = document.getElementById("latencyValue");
const requestsValueEl = document.getElementById("requestsValue");

const dashboardTitleInput = document.getElementById("dashboardTitle");
const refreshIntervalInput = document.getElementById("refreshInterval");
const alertThresholdInput = document.getElementById("alertThreshold");
const enableAlertsInput = document.getElementById("enableAlerts");

let refreshIntervalMs = 2000;
let timer = null;
let chart;
let dataPoints = {
  cpu: [],
  memory: [],
  latency: [],
  requests: []
};
let labels = [];

function nowTime() {
  return new Date().toLocaleTimeString();
}

function pushLog(message) {
  const li = document.createElement("li");
  li.innerHTML = `<span class="time">[${nowTime()}]</span>${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function randomMetric(base, variance, min = 0, max = 100) {
  const value = base + (Math.random() * variance * 2 - variance);
  return Math.max(min, Math.min(max, Math.round(value)));
}

function generateData() {
  return {
    cpu: randomMetric(55, 20),
    memory: randomMetric(62, 15),
    latency: randomMetric(120, 50, 10, 500),
    requests: randomMetric(900, 250, 100, 2000)
  };
}

function updateStats(data) {
  cpuValueEl.textContent = `${data.cpu}%`;
  memoryValueEl.textContent = `${data.memory}%`;
  latencyValueEl.textContent = `${data.latency} ms`;
  requestsValueEl.textContent = `${data.requests}/s`;
}

function updateChart(data) {
  const label = nowTime();
  labels.push(label);
  dataPoints.cpu.push(data.cpu);
  dataPoints.memory.push(data.memory);
  dataPoints.latency.push(data.latency);
  dataPoints.requests.push(data.requests);

  if (labels.length > 12) {
    labels.shift();
    dataPoints.cpu.shift();
    dataPoints.memory.shift();
    dataPoints.latency.shift();
    dataPoints.requests.shift();
  }

  chart.data.labels = labels;
  chart.data.datasets[0].data = dataPoints.cpu;
  chart.data.datasets[1].data = dataPoints.memory;
  chart.data.datasets[2].data = dataPoints.latency;
  chart.data.datasets[3].data = dataPoints.requests;
  chart.update();
}

function updateLastUpdated() {
  lastUpdatedEl.textContent = `Last updated: ${new Date().toLocaleString()}`;
}

function tick() {
  const data = generateData();
  updateStats(data);
  updateChart(data);
  updateLastUpdated();

  if (enableAlertsInput.checked && data.cpu > Number(alertThresholdInput.value)) {
    pushLog(`⚠️ CPU alert triggered: ${data.cpu}% exceeded threshold ${alertThresholdInput.value}%`);
  } else {
    pushLog(`Metrics refreshed: CPU ${data.cpu}%, Memory ${data.memory}%, Latency ${data.latency}ms`);
  }
}

function startPolling() {
  if (timer) clearInterval(timer);
  timer = setInterval(tick, refreshIntervalMs);
  connectionStatusEl.textContent = "Live";
  connectionStatusEl.style.background = "rgba(34, 197, 94, 0.15)";
  connectionStatusEl.style.color = "#86efac";
  connectionStatusEl.style.borderColor = "rgba(34, 197, 94, 0.3)";
}

function initChart() {
  chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: [],
      datasets: [
        {
          label: "CPU %",
          data: [],
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35
        },
        {
          label: "Memory %",
          data: [],
          borderColor: "#22c55e",
          backgroundColor: "rgba(34, 197, 94, 0.15)",
          tension: 0.35
        },
        {
          label: "Latency ms",
          data: [],
          borderColor: "#f59e0b",
          backgroundColor: "rgba(245, 158, 11, 0.15)",
          tension: 0.35
        },
        {
          label: "Requests/sec",
          data: [],
          borderColor: "#a78bfa",
          backgroundColor: "rgba(167, 139, 250, 0.15)",
          tension: 0.35
        }
      ]
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          labels: {
            color: "#e5e7eb"
          }
        }
      },
      scales: {
        x: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(255,255,255,0.06)" }
        },
        y: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(255,255,255,0.06)" }
        }
      }
    }
  });
}

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = dashboardTitleInput.value.trim();
  const interval = Number(refreshIntervalInput.value);
  const threshold = Number(alertThresholdInput.value);

  if (!title || Number.isNaN(interval) || Number.isNaN(threshold)) {
    feedbackEl.textContent = "Please fill out all fields correctly.";
    feedbackEl.style.color = "#fca5a5";
    return;
  }

  document.querySelector(".topbar h1").textContent = title;
  refreshIntervalMs = interval;

  feedbackEl.textContent = "Settings applied successfully.";
  feedbackEl.style.color = "#86efac";

  pushLog(`Settings updated: title="${title}", refresh=${interval}ms, threshold=${threshold}%`);
  startPolling();
});

dashboardTitleInput.value = "Real-Time Dashboard";
initChart();
tick();
startPolling();
