  <script>
    const ctx = document.getElementById('chart').getContext('2d');
    const logEl = document.getElementById('log');
    const latestValueEl = document.getElementById('latestValue');
    const averageValueEl = document.getElementById('averageValue');
    const pointCountEl = document.getElementById('pointCount');
    const form = document.getElementById('dataForm');
    const toggleLiveBtn = document.getElementById('toggleLive');
    const resetDataBtn = document.getElementById('resetData');

    let live = true;
    let counter = 0;
    let dataPoints = [
      { label: 'T1', value: 12 },
      { label: 'T2', value: 19 },
      { label: 'T3', value: 8 },
      { label: 'T4', value: 15 }
    ];

    function addLog(message) {
      const li = document.createElement('li');
      li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(li);
    }

    function updateStats() {
      const values = dataPoints.map(d => d.value);
      const latest = values[values.length - 1] ?? 0;
      const avg = values.length
        ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1)
        : 0;

      latestValueEl.textContent = latest;
      averageValueEl.textContent = avg;
      pointCountEl.textContent = dataPoints.length;
    }

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: dataPoints.map(d => d.label),
        datasets: [{
          label: 'Metric',
          data: dataPoints.map(d => d.value),
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          fill: true,
          tension: 0.35,
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { ticks: { color: '#cbd5e1' }, grid: { color: '#1f2937' } },
          y: { ticks: { color: '#cbd5e1' }, grid: { color: '#1f2937' } }
        },
        plugins: {
          legend: { labels: { color: '#e5e7eb' } }
        }
      }
    });

    function renderChart() {
      chart.data.labels = dataPoints.map(d => d.label);
      chart.data.datasets[0].data = dataPoints.map(d => d.value);
      chart.update();
      updateStats();
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const label = document.getElementById('label').value.trim();
      const value = Number(document.getElementById('value').value);

      if (!label || Number.isNaN(value)) return;

      dataPoints.push({ label, value });
      renderChart();
      addLog(`Added point ${label} = ${value}`);
      form.reset();
    });

    toggleLiveBtn.addEventListener('click', () => {
      live = !live;
      toggleLiveBtn.textContent = live ? 'Pause Live' : 'Resume Live';
      addLog(live ? 'Live updates resumed' : 'Live updates paused');
    });

    resetDataBtn.addEventListener('click', () => {
      dataPoints = [];
      renderChart();
      addLog('Data reset');
    });

    // Simulate realtime updates
    setInterval(() => {
      if (!live) return;

      counter++;
      const value = Math.floor(Math.random() * 100);
      const label = `R${counter}`;

      dataPoints.push({ label, value });

      // Keep only latest 12 points
      if (dataPoints.length > 12) dataPoints.shift();

      renderChart();
      addLog(`Live update: ${label} = ${value}`);
    }, 1000);

    updateStats();
    addLog('Dashboard initialized');
  </script>
</body>
</html>
