              <option>Alpha</option>
              <option>Beta</option>
              <option>Gamma</option>
            </select>
          </label>
          <label>
            Value
            <input type="number" id="value" min="0" max="100" value="50" required />
          </label>
          <button type="submit">Submit</button>
        </form>
      </div>

