    const chart = document.getElementById('chart');
    const ctx = chart.getContext('2d');
    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const countValueEl = document.getElementById('countValue');
    const submissionsEl = document.getElementById('submissions');
    const clockEl = document.getElementById('clock');

    const data = Array.from({ length: 30 }, () => Math.floor(Math.random() * 100));
    const submissions = [];

    function drawChart() {
      ctx.clearRect(0, 0, chart.width, chart.height);

      // Grid
      ctx.strokeStyle = '#1f2937';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (chart.height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(chart.width, y);
        ctx.stroke();
      }

      // Line
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((val, i) => {
        const x = (chart.width / (data.length - 1)) * i;
        const y = chart.height - (val / 100) * chart.height;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // Points
      ctx.fillStyle = '#22c55e';
      data.forEach((val, i) => {
        const x = (chart.width / (data.length - 1)) * i;
        const y = chart.height - (val / 100) * chart.height;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function updateMetrics() {
      const current = data[data.length - 1];
      const avg = data.reduce((a, b) => a + b, 0) / data.length;

      currentValueEl.textContent = current.toFixed(0);
      avgValueEl.textContent = avg.toFixed(1);
      countValueEl.textContent = data.length;
    }

    function tick() {
      data.push(Math.floor(Math.random() * 100));
      if (data.length > 30) data.shift();
      drawChart();
      updateMetrics();
      clockEl.textContent = new Date().toLocaleTimeString();
    }

    document.getElementById('dataForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const category = document.getElementById('category').value;
      const value = Number(document.getElementById('value').value);

      submissions.unshift({ name, category, value });
      if (submissions.length > 5) submissions.pop();

      submissionsEl.innerHTML = submissions.map(item => `
        <li><strong>${item.name}</strong> — ${item.category} — ${item.value}</li>
      `).join('');

      // Add submitted value to chart
      data.push(value);
      if (data.length > 30) data.shift();
      drawChart();
      updateMetrics();

      e.target.reset();
      document.getElementById('value').value = 50;
    });

    drawChart();
    updateMetrics();
    setInterval(tick, 1000);
  </script>
</body>
