    const data = [12, 19, 8, 15, 22];
    const chart = document.getElementById("chart");
    const ctx = chart.getContext("2d");

    const latestValue = document.getElementById("latestValue");
    const averageValue = document.getElementById("averageValue");
    const pointCount = document.getElementById("pointCount");
    const entryList = document.getElementById("entryList");
    const dataForm = document.getElementById("dataForm");
    const valueInput = document.getElementById("valueInput");

    function updateMetrics() {
      const latest = data[data.length - 1];
      const avg = data.reduce((a, b) => a + b, 0) / data.length;

      latestValue.textContent = latest.toFixed(1);
      averageValue.textContent = avg.toFixed(1);
      pointCount.textContent = data.length;
    }

    function renderList() {
      entryList.innerHTML = "";
      data.slice().reverse().forEach((value, index) => {
        const li = document.createElement("li");
        li.textContent = `#${data.length - index}: ${value}`;
        entryList.appendChild(li);
      });
    }

    function drawChart() {
      ctx.clearRect(0, 0, chart.width, chart.height);

      const padding = 30;
      const max = Math.max(...data, 1);
      const min = Math.min(...data, 0);
      const range = max - min || 1;

      // axes
      ctx.strokeStyle = "#334155";
      ctx.beginPath();
      ctx.moveTo(padding, 10);
      ctx.lineTo(padding, chart.height - padding);
      ctx.lineTo(chart.width - 10, chart.height - padding);
      ctx.stroke();

      // line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, i) => {
        const x = padding + (i * (chart.width - padding - 20)) / (data.length - 1 || 1);
        const y = chart.height - padding - ((value - min) / range) * (chart.height - padding - 20);

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);

        // points
        ctx.fillStyle = "#22c55e";
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      ctx.stroke();
    }

    function render() {
      updateMetrics();
      renderList();
      drawChart();
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = parseFloat(valueInput.value);
      if (Number.isNaN(value)) return;

      data.push(value);
      valueInput.value = "";
      render();
    });

    // Simulate real-time updates every 2 seconds
    setInterval(() => {
      const last = data[data.length - 1];
      const next = Math.max(0, last + (Math.random() * 10 - 5));
      data.push(Number(next.toFixed(1)));
      if (data.length > 20) data.shift();
      render();
    }, 2000);

    render();
  </script>
