    <h1>Minimal Real-Time Dashboard</h1>
  </header>

  <main class="container">
    <section class="card">
      <h2>Live Data Visualization</h2>
      <div class="controls">
        <button class="start" id="startBtn">Start</button>
        <button class="stop" id="stopBtn">Stop</button>
        <button class="reset" id="resetBtn">Reset</button>
      </div>
      <canvas id="liveChart" height="120"></canvas>
      <div class="status" id="status">Status: stopped</div>
    </section>

    <aside class="card">
      <h2>Form Handling</h2>
      <form id="itemForm">
        <input type="text" id="itemInput" placeholder="Enter an item..." required />
        <button class="add" type="submit">Add</button>
      </form>
      <ul id="itemList"></ul>
    </aside>
  </main>

  <script>
    // ----- Chart setup -----
    const ctx = document.getElementById('liveChart').getContext('2d');
    const labels = [];
    const dataPoints = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: dataPoints,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true,
            suggestedMax: 100
          }
        }
      }
    });

    let timer = null;
    let tick = 0;

    function addDataPoint() {
      tick++;
      const value = Math.floor(Math.random() * 100);

      labels.push(tick.toString());
      dataPoints.push(value);

      if (labels.length > 20) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
    }

    document.getElementById('startBtn').addEventListener('click', () => {
      if (!timer) {
        timer = setInterval(addDataPoint, 1000);
        document.getElementById('status').textContent = 'Status: running';
      }
    });

    document.getElementById('stopBtn').addEventListener('click', () => {
      clearInterval(timer);
      timer = null;
      document.getElementById('status').textContent = 'Status: stopped';
    });

    document.getElementById('resetBtn').addEventListener('click', () => {
      clearInterval(timer);
      timer = null;
      tick = 0;
      labels.length = 0;
      dataPoints.length = 0;
      chart.update();
      document.getElementById('status').textContent = 'Status: reset';
    });

    // ----- Form handling -----
    const form = document.getElementById('itemForm');
    const input = document.getElementById('itemInput');
    const list = document.getElementById('itemList');

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const value = input.value.trim();
      if (!value) return;

      const li = document.createElement('li');
      li.textContent = value;
      list.appendChild(li);

      input.value = '';
      input.focus();
    });
  </script>
</body>
</html>
