      e.preventDefault();

      const value = input.value.trim();
      if (!value) return;

      const li = document.createElement('li');
      li.textContent = value;
      list.prepend(li);

      status.textContent = `Added: "${value}"`;
      input.value = '';
      input.focus();

      setTimeout(() => {
