      if (labels.length > 12) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();

      updateCount++;
      document.getElementById("currentValue").textContent = value;
      document.getElementById("averageValue").textContent =
        Math.round(dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length);
      document.getElementById("updateCount").textContent = updateCount;
    }

    updateLiveData();
    setInterval(updateLiveData, 1000);

    // ----- Form handling -----
    const form = document.getElementById("itemForm");
    const itemList = document.getElementById("itemList");

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("itemName").value.trim();
      const value = document.getElementById("itemValue").value.trim();

      if (!name || value === "") return;

      const li = document.createElement("li");
      li.innerHTML = `
        <span>${name}</span>
        <span class="badge">${value}</span>
      `;

      itemList.prepend(li);
      form.reset();
      document.getElementById("itemName").focus();
    });
  </script>
</body>
</html>
