    <p>Live chart + form handling + simple real-time updates</p>
  </header>

  <main class="container">
    <section class="card">
      <h2>Real-time Data Visualization</h2>
      <div class="controls">
        <button id="startBtn">Start Feed</button>
        <button id="stopBtn" class="secondary">Stop Feed</button>
        <button id="resetBtn" class="secondary">Reset</button>
      </div>

      <canvas id="chart" width="900" height="280"></canvas>

      <div class="stats">
        <div class="stat">
          <span>Latest Value</span>
          <strong id="latestValue">0</strong>
        </div>
        <div class="stat">
          <span>Average</span>
          <strong id="avgValue">0</strong>
        </div>
        <div class="stat">
          <span>Status</span>
          <strong id="statusText">Stopped</strong>
        </div>
      </div>
    </section>

    <section class="card">
      <h2>Task Form</h2>
      <form id="taskForm">
        <input id="taskInput" type="text" placeholder="Enter a task..." required />
        <button type="submit">Add</button>
      </form>

      <ul id="taskList"></ul>
    </section>
  </main>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");
    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const statusTextEl = document.getElementById("statusText");

    const taskForm = document.getElementById("taskForm");
    const taskInput = document.getElementById("taskInput");
    const taskList = document.getElementById("taskList");

    let data = [];
    let timer = null;
    const maxPoints = 30;

    function generateValue() {
      return Math.floor(Math.random() * 100);
    }

    function updateStats() {
      const latest = data[data.length - 1] ?? 0;
      const avg = data.length
        ? (data.reduce((a, b) => a + b, 0) / data.length).toFixed(1)
        : 0;

      latestValueEl.textContent = latest;
      avgValueEl.textContent = avg;
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background grid
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 10; i++) {
        const y = (canvas.height / 10) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      if (data.length === 0) return;

      // Line chart
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = (canvas.width / (maxPoints - 1)) * index;
        const y = canvas.height - (value / 100) * canvas.height;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#e5e7eb";
      data.forEach((value, index) => {
        const x = (canvas.width / (maxPoints - 1)) * index;
        const y = canvas.height - (value / 100) * canvas.height;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function pushData() {
      data.push(generateValue());
      if (data.length > maxPoints) data.shift();
      updateStats();
      drawChart();
    }

    function startFeed() {
      if (timer) return;
      statusTextEl.textContent = "Running";
      timer = setInterval(pushData, 1000);
      pushData(); // immediate first point
    }

    function stopFeed() {
      clearInterval(timer);
      timer = null;
      statusTextEl.textContent = "Stopped";
    }

    function resetDashboard() {
      stopFeed();
      data = [];
      updateStats();
      drawChart();
    }

    startBtn.addEventListener("click", startFeed);
    stopBtn.addEventListener("click", stopFeed);
    resetBtn.addEventListener("click", resetDashboard);

    taskForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const task = taskInput.value.trim();
      if (!task) return;

      const li = document.createElement("li");
      li.innerHTML = `<span>${task}</span><span class="badge">New</span>`;
      taskList.prepend(li);

      taskInput.value = "";
      taskInput.focus();
    });

    // Initial render
    drawChart();
    updateStats();
  </script>
</body>
</html>
