      <h2>Add Data Point</h2>
      <form id="dataForm">
        <input type="text" id="label" placeholder="Label" required />
        <input type="number" id="value" placeholder="Value" required />
        <button type="submit">Add</button>
      </form>

      <div class="stats">
        <div class="stat">
          <strong>Total Points</strong>
          <div id="totalPoints">0</div>
        </div>
        <div class="stat">
          <strong>Latest Value</strong>
          <div id="latestValue">0</div>
        </div>
      </div>
    </div>

    <div class="card">
      <h2>Live Chart</h2>
      <canvas id="chart"></canvas>
    </div>

    <div class="card full">
      <h2>Data Entries</h2>
      <ul id="dataList"></ul>
    </div>
  </div>

  <script>
    const labels = ["A", "B", "C"];
    const values = [10, 20, 15];

    const ctx = document.getElementById("chart").getContext("2d");
    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels: labels,
        datasets: [{
          label: "Live Values",
          data: values,
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.15)",
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    const dataList = document.getElementById("dataList");
    const totalPoints = document.getElementById("totalPoints");
    const latestValue = document.getElementById("latestValue");

    function renderList() {
      dataList.innerHTML = "";
      labels.forEach((label, i) => {
        const li = document.createElement("li");
        li.textContent = `${label}: ${values[i]}`;
        dataList.appendChild(li);
      });

      totalPoints.textContent = values.length;
      latestValue.textContent = values[values.length - 1] ?? 0;
    }

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const label = document.getElementById("label").value.trim();
      const value = Number(document.getElementById("value").value);

      if (!label || Number.isNaN(value)) return;

      labels.push(label);
      values.push(value);

      chart.update();
      renderList();

      e.target.reset();
    });

    // Simulate real-time updates every 3 seconds
    setInterval(() => {
      const nextLabel = `P${labels.length + 1}`;
      const nextValue = Math.floor(Math.random() * 50) + 5;

      labels.push(nextLabel);
      values.push(nextValue);

      chart.update();
      renderList();
    }, 3000);

    renderList();
  </script>
</body>
</html>
