## `background.js`

This service worker loads custom blocked domains from storage and updates dynamic rules.

```js
const DYNAMIC_RULE_BASE_ID = 1000;

async function updateDynamicRules() {
  const data = await chrome.storage.sync.get({ blockedDomains: [] });
  const blockedDomains = data.blockedDomains || [];

  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const removeRuleIds = existingRules.map(rule => rule.id);

  const addRules = blockedDomains.map((domain, index) => ({
    id: DYNAMIC_RULE_BASE_ID + index,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: [
        "script",
        "sub_frame",
        "xmlhttprequest",
        "image",
        "ping",
        "font",
        "media",
        "other"
      ]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules
  });
}

chrome.runtime.onInstalled.addListener(() => {
  updateDynamicRules();
});

chrome.runtime.onStartup.addListener(() => {
  updateDynamicRules();
});

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "sync" && changes.blockedDomains) {
    updateDynamicRules();
  }
});
```

