async function loadDomains() {
  const data = await chrome.storage.sync.get({ blockedDomains: [] });
  document.getElementById("domains").value = (data.blockedDomains || []).join("\n");
}

async function saveDomains() {
  const text = document.getElementById("domains").value;
  const blockedDomains = text
    .split("\n")
    .map(line => line.trim())
    .filter(Boolean);

  await chrome.storage.sync.set({ blockedDomains });
  document.getElementById("saved").textContent = "Saved.";
  setTimeout(() => {
    document.getElementById("saved").textContent = "";
  }, 1500);
}

document.getElementById("save").addEventListener("click", saveDomains);
loadDomains();
