## `content.js`

This script removes common tracking parameters from URLs and hides common tracker elements in the DOM.

```js
(() => {
  const TRACKING_PARAMS = [
    "utm_source",
    "utm_medium",
    "utm_campaign",
    "utm_term",
    "utm_content",
    "utm_id",
    "gclid",
    "fbclid",
    "msclkid",
    "igshid",
    "mc_cid",
    "mc_eid"
  ];

  function cleanUrl(urlString) {
    try {
      const url = new URL(urlString);
      let changed = false;

      for (const param of TRACKING_PARAMS) {
        if (url.searchParams.has(param)) {
          url.searchParams.delete(param);
          changed = true;
        }
      }

      return changed ? url.toString() : null;
    } catch {
      return null;
    }
  }

  function cleanCurrentUrl() {
    const cleaned = cleanUrl(window.location.href);
    if (cleaned && cleaned !== window.location.href) {
      history.replaceState(null, "", cleaned);
    }
  }

  function removeTrackerElements(root = document) {
    const selectors = [
      'script[src*="google-analytics"]',
      'script[src*="googletagmanager"]',
      'script[src*="doubleclick"]',
      'iframe[src*="doubleclick"]',
      'img[src*="google-analytics"]',
      'img[src*="facebook.com/tr"]',
      'a[href*="utm_"]'
    ];

    for (const selector of selectors) {
      root.querySelectorAll(selector).forEach((el) => {
        if (el.tagName === "A") {
          const cleaned = cleanUrl(el.href);
          if (cleaned) el.href = cleaned;
        } else {
          el.remove();
        }
      });
    }
  }

  function observeMutations() {
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (node.nodeType === Node.ELEMENT_NODE) {
            removeTrackerElements(node);
          }
        }
      }
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  }

  cleanCurrentUrl();
  removeTrackerElements();
  observeMutations();
})();
```

