## `content.js`

This script removes some common tracking-related page elements and disables certain tracking-related DOM features. It does **not** replace network blocking, but it helps reduce client-side tracking UI.

```js
(() => {
  const removeTrackingElements = () => {
    const selectors = [
      'iframe[src*="doubleclick.net"]',
      'iframe[src*="googletagmanager.com"]',
      'iframe[src*="facebook.net"]',
      'script[src*="google-analytics.com"]',
      'script[src*="googletagmanager.com"]',
      'script[src*="connect.facebook.net"]',
      'img[src*="doubleclick.net"]',
      'img[src*="scorecardresearch.com"]',
      '[data-tracker]',
      '[data-analytics]',
      '.tracking',
      '.tracker',
      '.ad',
      '.ads'
    ];

    for (const selector of selectors) {
      document.querySelectorAll(selector).forEach(el => el.remove());
    }
  };

  const disableBeacon = () => {
    if (navigator.sendBeacon) {
      const original = navigator.sendBeacon.bind(navigator);
      navigator.sendBeacon = function(url, data) {
        const blocked = [
          "google-analytics.com",
          "googletagmanager.com",
          "facebook.com",
          "facebook.net",
          "mixpanel.com",
          "segment.com",
          "scorecardresearch.com"
        ];

        try {
          const target = String(url);
          if (blocked.some(domain => target.includes(domain))) {
            return true; // pretend success, but don't send
          }
        } catch (_) {}

        return original(url, data);
      };
    }
  };

  const observeMutations = () => {
    const observer = new MutationObserver(() => {
      removeTrackingElements();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  };

  removeTrackingElements();
  disableBeacon();
  observeMutations();
})();
```

