## `background.js`

This keeps track of whether blocking is enabled and updates the ruleset accordingly.

```js
const RULESET_ID = "tracker_rules";

async function setBlockingEnabled(enabled) {
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });

  await chrome.storage.local.set({ blockingEnabled: enabled });
}

async function init() {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");

  if (blockingEnabled === undefined) {
    await setBlockingEnabled(true);
  } else {
    await setBlockingEnabled(blockingEnabled);
  }
}

chrome.runtime.onInstalled.addListener(init);
chrome.runtime.onStartup.addListener(init);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    setBlockingEnabled(Boolean(message.enabled))
      .then(() => sendResponse({ ok: true }))
      .catch((err) => sendResponse({ ok: false, error: String(err) }));
    return true;
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    chrome.storage.local.get("blockingEnabled").then((result) => {
      sendResponse({ ok: true, enabled: result.blockingEnabled ?? true });
    });
    return true;
  }
});
```

