## `popup.js`

```js
const toggleBtn = document.getElementById("toggle");
const statusEl = document.getElementById("status");

async function getState() {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ type: "GET_BLOCKING_ENABLED" }, (response) => {
      resolve(response?.enabled ?? true);
    });
  });
}

async function setState(enabled) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage(
      { type: "SET_BLOCKING_ENABLED", enabled },
      () => resolve()
    );
  });
}

function render(enabled) {
  toggleBtn.textContent = enabled ? "Enabled" : "Disabled";
  toggleBtn.className = enabled ? "on" : "off";
  statusEl.textContent = enabled
    ? "Common tracking requests are being blocked."
    : "Blocking is turned off.";
}

(async () => {
  let enabled = await getState();
  render(enabled);

  toggleBtn.addEventListener("click", async () => {
    enabled = !enabled;
    await setState(enabled);
    render(enabled);
  });
})();
```

