## `popup.js`

```javascript
const stateText = document.getElementById("stateText");
const toggleBtn = document.getElementById("toggleBtn");
const statusText = document.getElementById("statusText");

async function loadState() {
  const state = await chrome.runtime.sendMessage({ type: "GET_STATE" });
  renderState(state.enabled);
}

function renderState(enabled) {
  stateText.textContent = enabled ? "Protection is ON" : "Protection is OFF";
  toggleBtn.textContent = enabled ? "Disable" : "Enable";
  toggleBtn.className = enabled ? "disabled" : "enabled";
  statusText.textContent = enabled
    ? "Tracking requests are being blocked."
    : "Blocking is currently paused.";
}

toggleBtn.addEventListener("click", async () => {
  const state = await chrome.runtime.sendMessage({ type: "GET_STATE" });
  const next = !state.enabled;
  await chrome.runtime.sendMessage({ type: "SET_ENABLED", enabled: next });
  renderState(next);
});

loadState();
```

