## `background.js`

This service worker loads custom block rules from storage and applies them dynamically.

```js
const DEFAULT_BLOCKLIST = [
  "doubleclick.net",
  "googletagmanager.com",
  "google-analytics.com",
  "facebook.net",
  "connect.facebook.net"
];

async function getCustomBlocklist() {
  const result = await chrome.storage.sync.get({ blocklist: [] });
  return Array.isArray(result.blocklist) ? result.blocklist : [];
}

function normalizeDomain(domain) {
  return String(domain || "").trim().toLowerCase();
}

function makeRule(id, domain) {
  return {
    id,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping", "other"]
    }
  };
}

async function updateDynamicRules() {
  const customBlocklist = await getCustomBlocklist();
  const allDomains = [...new Set([...DEFAULT_BLOCKLIST, ...customBlocklist.map(normalizeDomain)].filter(Boolean))];

  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const removeRuleIds = existingRules.map(rule => rule.id);

  const addRules = allDomains.map((domain, index) => makeRule(1000 + index, domain));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules
  });
}

chrome.runtime.onInstalled.addListener(() => {
  updateDynamicRules();
});

chrome.runtime.onStartup.addListener(() => {
  updateDynamicRules();
});

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "sync" && changes.blocklist) {
    updateDynamicRules();
  }
});
```

