## `content.js`

This removes obvious inline tracking scripts and common analytics tags after the page loads.

```js
(function () {
  const TRACKER_PATTERNS = [
    /google-analytics/i,
    /googletagmanager/i,
    /gtag/i,
    /fbq\s*\(/i,
    /connect\.facebook\.net/i,
    /doubleclick/i,
    /hotjar/i,
    /segment/i,
    /mixpanel/i
  ];

  function looksLikeTrackerScript(script) {
    const src = script.getAttribute("src") || "";
    const text = script.textContent || "";
    const combined = `${src}\n${text}`;
    return TRACKER_PATTERNS.some((re) => re.test(combined));
  }

  function removeTrackingElements(root = document) {
    const scripts = root.querySelectorAll("script");
    scripts.forEach((script) => {
      if (looksLikeTrackerScript(script)) {
        script.remove();
      }
    });

    const iframes = root.querySelectorAll("iframe");
    iframes.forEach((frame) => {
      const src = frame.getAttribute("src") || "";
      if (TRACKER_PATTERNS.some((re) => re.test(src))) {
        frame.remove();
      }
    });
  }

  // Initial cleanup
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => removeTrackingElements());
  } else {
    removeTrackingElements();
  }

  // Watch for dynamically inserted trackers
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;

        if (node.tagName === "SCRIPT" && looksLikeTrackerScript(node)) {
          node.remove();
          continue;
        }

        if (node.tagName === "IFRAME") {
          const src = node.getAttribute("src") || "";
          if (TRACKER_PATTERNS.some((re) => re.test(src))) {
            node.remove();
            continue;
          }
        }

        removeTrackingElements(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

