## `service_worker.js`

This handles enabling/disabling the blocking rules based on the popup toggle.

```javascript
const RULESET_ID = "tracking_rules";
const STORAGE_KEY = "blockingEnabled";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }

  await chrome.storage.sync.set({ [STORAGE_KEY]: enabled });
}

async function getBlockingEnabled() {
  const result = await chrome.storage.sync.get(STORAGE_KEY);
  return result[STORAGE_KEY] ?? true;
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getBlockingEnabled();
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const enabled = await getBlockingEnabled();
  await setBlockingEnabled(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    setBlockingEnabled(message.enabled)
      .then(() => sendResponse({ success: true }))
      .catch((error) => sendResponse({ success: false, error: String(error) }));
    return true;
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    getBlockingEnabled()
      .then((enabled) => sendResponse({ enabled }))
      .catch((error) => sendResponse({ enabled: true, error: String(error) }));
    return true;
  }
});
```

