## `popup.js`

```javascript
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");

async function getBlockingEnabled() {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ type: "GET_BLOCKING_ENABLED" }, (response) => {
      resolve(response?.enabled ?? true);
    });
  });
}

async function setBlockingEnabled(enabled) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage(
      { type: "SET_BLOCKING_ENABLED", enabled },
      (response) => resolve(response)
    );
  });
}

function render(enabled) {
  statusEl.textContent = enabled ? "Blocking is ON" : "Blocking is OFF";
  toggleBtn.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
  toggleBtn.className = enabled ? "disabled" : "enabled";
}

toggleBtn.addEventListener("click", async () => {
  const current = await getBlockingEnabled();
  const next = !current;
  await setBlockingEnabled(next);
  render(next);
});

(async () => {
  const enabled = await getBlockingEnabled();
  render(enabled);
})();
```

