## `content.js`

This removes some common tracking elements from pages after load and watches for newly added ones.

```js
(function () {
  const TRACKING_SELECTORS = [
    'iframe[src*="doubleclick.net"]',
    'iframe[src*="googletagmanager.com"]',
    'iframe[src*="facebook.net"]',
    'script[src*="google-analytics.com"]',
    'script[src*="googletagmanager.com"]',
    'script[src*="doubleclick.net"]',
    'img[src*="google-analytics.com"]',
    'img[src*="doubleclick.net"]',
    'img[src*="pixel"]',
    'link[href*="doubleclick.net"]'
  ];

  function removeTrackingElements(root = document) {
    for (const selector of TRACKING_SELECTORS) {
      root.querySelectorAll(selector).forEach((el) => {
        el.remove();
      });
    }
  }

  // Remove existing tracking elements ASAP
  removeTrackingElements();

  // Watch for dynamically inserted trackers
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        // If the node itself matches, remove it
        if (TRACKING_SELECTORS.some((sel) => node.matches(sel))) {
          node.remove();
          continue;
        }

        // Otherwise remove matching descendants
        removeTrackingElements(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

