## `background.js`

This stores a simple enabled/disabled state and can be extended later.

```js
const DEFAULT_STATE = { enabled: true };

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.local.get(DEFAULT_STATE);
  if (typeof current.enabled === "undefined") {
    await chrome.storage.local.set(DEFAULT_STATE);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATE") {
    chrome.storage.local.get(DEFAULT_STATE).then((state) => sendResponse(state));
    return true;
  }

  if (message?.type === "SET_STATE") {
    chrome.storage.local.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

