## `background.js`

This keeps track of whether blocking is enabled and can dynamically disable/enable the ruleset.

```js
const RULESET_ID = "default_rules";
const STORAGE_KEY = "blockingEnabled";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }

  await chrome.storage.local.set({ [STORAGE_KEY]: enabled });
}

async function initialize() {
  const data = await chrome.storage.local.get(STORAGE_KEY);
  const enabled = data[STORAGE_KEY] ?? true;
  await setBlockingEnabled(enabled);
}

chrome.runtime.onInstalled.addListener(() => {
  initialize();
});

chrome.runtime.onStartup.addListener(() => {
  initialize();
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    setBlockingEnabled(Boolean(message.enabled))
      .then(() => sendResponse({ ok: true }))
      .catch((err) => sendResponse({ ok: false, error: String(err) }));
    return true; // keep message channel open for async response
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    chrome.storage.local.get(STORAGE_KEY).then((data) => {
      sendResponse({ enabled: data[STORAGE_KEY] ?? true });
    });
    return true;
  }
});
```

