## 4) `content.js`

This is a lightweight DOM-level cleanup script. It does not replace network blocking, but can help remove obvious tracking elements.

```js
(() => {
  const removeTrackingElements = () => {
    const selectors = [
      'iframe[src*="doubleclick.net"]',
      'iframe[src*="facebook.com"]',
      'script[src*="google-analytics.com"]',
      'script[src*="googletagmanager.com"]',
      'img[src*="google-analytics.com"]'
    ];

    for (const selector of selectors) {
      document.querySelectorAll(selector).forEach((el) => el.remove());
    }
  };

  removeTrackingElements();

  const observer = new MutationObserver(() => {
    removeTrackingElements();
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

