const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");

function render(enabled) {
  statusEl.textContent = enabled ? "Protection is ON" : "Protection is OFF";
  toggleBtn.textContent = enabled ? "Disable Protection" : "Enable Protection";
  toggleBtn.className = enabled ? "enabled" : "disabled";
}

chrome.runtime.sendMessage({ type: "GET_STATUS" }, (response) => {
  render(response?.enabled ?? true);
});

toggleBtn.addEventListener("click", () => {
  chrome.runtime.sendMessage({ type: "GET_STATUS" }, (response) => {
    const current = response?.enabled ?? true;
    const next = !current;

    chrome.runtime.sendMessage({ type: "SET_STATUS", enabled: next }, () => {
      render(next);
    });
  });
});
