## 3) `background.js`

This service worker handles:
- basic initialization
- storing user settings
- optional dynamic blocking of known tracking script patterns

```js
const DEFAULT_SETTINGS = {
  enabled: true,
  blockInlineTrackers: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await chrome.storage.sync.set({
    ...DEFAULT_SETTINGS,
    ...current
  });
});

// Example dynamic rules for script URLs that may be added later.
// For now, this is a simple placeholder showing how to manage rules.
async function updateDynamicRules(enable) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const ruleIds = existingRules.map(rule => rule.id);

  if (!enable) {
    if (ruleIds.length > 0) {
      await chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: ruleIds
      });
    }
    return;
  }

  const dynamicRules = [
    {
      id: 1001,
      priority: 1,
      action: { type: "block" },
      condition: {
        urlFilter: "tracker",
        resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
      }
    },
    {
      id: 1002,
      priority: 1,
      action: { type: "block" },
      condition: {
        urlFilter: "pixel",
        resourceTypes: ["image", "xmlhttprequest", "ping", "other"]
      }
    }
  ];

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: ruleIds,
    addRules: dynamicRules
  });
}

// Keep dynamic rules in sync with settings
chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName !== "sync") return;

  if (changes.enabled) {
    await updateDynamicRules(changes.enabled.newValue);
  }
});

// Initialize dynamic rules on startup
(async () => {
  const { enabled } = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await updateDynamicRules(enabled);
})();
```

