## 4) `content.js`

This script runs at document start and removes some common inline tracking patterns by blocking obvious tracker-related globals and script injections. This is intentionally conservative to avoid breaking sites too much.

```js
(() => {
  const { blockInlineTrackers } = { blockInlineTrackers: true };

  if (!blockInlineTrackers) return;

  // Prevent some common tracker globals from being initialized if possible.
  const blockedGlobals = [
    "ga",
    "gtag",
    "_gaq",
    "_hmt",
    "fbq",
    "mixpanel"
  ];

  for (const name of blockedGlobals) {
    try {
      Object.defineProperty(window, name, {
        configurable: false,
        enumerable: false,
        get() {
          return undefined;
        },
        set() {
          // no-op
        }
      });
    } catch (_) {
      // Ignore if property cannot be redefined
    }
  }

  // Block injection of obvious tracking scripts by intercepting script src assignment.
  const originalSetAttribute = Element.prototype.setAttribute;
  Element.prototype.setAttribute = function (name, value) {
    if (
      this.tagName === "SCRIPT" &&
      name.toLowerCase() === "src" &&
      typeof value === "string"
    ) {
      const v = value.toLowerCase();
      const suspicious = [
        "google-analytics",
        "googletagmanager",
        "doubleclick",
        "facebook.net",
        "hotjar",
        "mixpanel",
        "segment",
        "amplitude"
      ];
      if (suspicious.some(part => v.includes(part))) {
        return;
      }
    }
    return originalSetAttribute.call(this, name, value);
  };

  // Prevent common beacon/pixel image loads from being added.
  const originalAppendChild = Node.prototype.appendChild;
  Node.prototype.appendChild = function (node) {
    try {
      if (node && node.tagName === "IMG" && typeof node.src === "string") {
        const v = node.src.toLowerCase();
        const suspicious = [
          "google-analytics",
          "doubleclick",
          "facebook.com/tr",
          "pixel",
          "hotjar",
          "mixpanel",
          "segment"
        ];
        if (suspicious.some(part => v.includes(part))) {
          return node;
        }
      }
    } catch (_) {}
    return originalAppendChild.call(this, node);
  };
})();
```

