const DEFAULT_SETTINGS = {
  blockingEnabled: true
};

async function loadSettings() {
  const settings = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  const toggle = document.getElementById("blockingToggle");
  const status = document.getElementById("status");

  toggle.checked = settings.blockingEnabled;
  status.textContent = settings.blockingEnabled
    ? "Blocking is enabled."
    : "Blocking is disabled.";
}

async function saveSettings(enabled) {
  await chrome.storage.sync.set({ blockingEnabled: enabled });
  const status = document.getElementById("status");
  status.textContent = enabled ? "Blocking is enabled." : "Blocking is disabled.";
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadSettings();

  document.getElementById("blockingToggle").addEventListener("change", (e) => {
    saveSettings(e.target.checked);
  });

  document.getElementById("openOptions").addEventListener("click", () => {
    chrome.runtime.openOptionsPage();
  });
});
