    .map(s => s.trim())
    .filter(Boolean);

  await chrome.storage.sync.set({ blockedDomains });

  document.getElementById("message").textContent =
    `Saved ${blockedDomains.length} custom blocked domain(s).`;
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadOptions();
  document.getElementById("saveBlockedDomains").addEventListener("click", saveOptions);
});
