// Initial tracker patterns for dynamic rule generation.
// In a real extension, you would maintain and update this list carefully.

const TRACKER_PATTERNS = [
  "doubleclick.net",
  "googlesyndication.com",
  "google-analytics.com",
  "googletagmanager.com",
  "facebook.net",
  "connect.facebook.net",
  "adsystem.com",
  "adnxs.com",
  "scorecardresearch.com",
  "googletagservices.com",
  "hotjar.com",
  "mixpanel.com",
  "segment.com",
  "fullstory.com",
  "clarity.ms",
  "amplitude.com"
];

function buildDynamicRules() {
  return TRACKER_PATTERNS.map((domain, index) => ({
    id: 1000 + index,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping", "font", "media"]
    }
  }));
}
```

