## 3) `background.js`

This service worker loads the rules and installs them dynamically. It also supports a simple enable/disable toggle stored in `chrome.storage`.

```js
importScripts("rules.js");

const ENABLED_KEY = "enabled";

async function updateRules(enabled) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existingRules.map(rule => rule.id);

  if (enabled) {
    const rules = buildDynamicRules();

    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingIds,
      addRules: rules
    });
  } else {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingIds,
      addRules: []
    });
  }
}

async function init() {
  const data = await chrome.storage.sync.get({ [ENABLED_KEY]: true });
  await updateRules(data[ENABLED_KEY]);
}

chrome.runtime.onInstalled.addListener(() => {
  init();
});

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "sync" && changes[ENABLED_KEY]) {
    updateRules(changes[ENABLED_KEY].newValue);
  }
});
```

