## 2) `background.js`

This script registers dynamic blocking rules for known tracking domains and script URLs.

```js
const DEFAULT_ENABLED = true;

const TRACKING_DOMAINS = [
  "google-analytics.com",
  "googletagmanager.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "analytics.twitter.com",
  "static.hotjar.com",
  "script.hotjar.com",
  "mixpanel.com",
  "segment.com",
  "cdn.segment.com",
  "fullstory.com",
  "cdn.fullstory.com",
  "amplitude.com",
  "cdn.amplitude.com",
  "clarity.ms",
  "bat.bing.com",
  "scorecardresearch.com",
  "quantserve.com",
  "taboola.com",
  "outbrain.com"
];

async function getEnabled() {
  const result = await chrome.storage.sync.get({ enabled: DEFAULT_ENABLED });
  return result.enabled;
}

async function setRules(enabled) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingRuleIds = existingRules.map(r => r.id);

  if (existingRuleIds.length) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingRuleIds
    });
  }

  if (!enabled) return;

  const rules = TRACKING_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: ["script", "xmlhttprequest", "sub_frame", "image", "font", "media", "stylesheet", "ping", "other"]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    addRules: rules
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getEnabled();
  await setRules(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const enabled = await getEnabled();
  await setRules(enabled);
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "sync" && changes.enabled) {
    await setRules(changes.enabled.newValue);
  }
});
```

