## 3) `content.js`

This content script removes some common tracking-related DOM elements and inline tracker patterns after page load.

```js
(function () {
  const BLOCKED_PATTERNS = [
    /google-analytics/i,
    /gtag/i,
    /googletagmanager/i,
    /fbq/i,
    /hotjar/i,
    /mixpanel/i,
    /segment/i,
    /amplitude/i,
    /clarity/i,
    /fullstory/i
  ];

  function removeKnownTrackingScripts() {
    const scripts = document.querySelectorAll("script");
    for (const script of scripts) {
      const src = script.src || "";
      const text = script.textContent || "";

      if (BLOCKED_PATTERNS.some(re => re.test(src) || re.test(text))) {
        script.remove();
      }
    }
  }

  function removeTrackingIframesAndPixels() {
    const elements = document.querySelectorAll("iframe, img, link");
    for (const el of elements) {
      const src = el.src || el.href || "";
      if (BLOCKED_PATTERNS.some(re => re.test(src))) {
        el.remove();
      }
    }
  }

  function cleanup() {
    removeKnownTrackingScripts();
    removeTrackingIframesAndPixels();
  }

  // Initial cleanup
  cleanup();

  // Watch for scripts injected after load
  const observer = new MutationObserver(() => cleanup());
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

