## 3) `background.js`

This handles the enabled/disabled state and can later be extended for dynamic rule management.

```js
const DEFAULT_STATE = { enabled: true };

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.local.get(DEFAULT_STATE);
  if (typeof current.enabled !== "boolean") {
    await chrome.storage.local.set(DEFAULT_STATE);
  }
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area !== "local" || !changes.enabled) return;

  const enabled = changes.enabled.newValue;

  // Enable/disable the static ruleset
  chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ["tracking_rules"] : [],
    disableRulesetIds: enabled ? [] : ["tracking_rules"]
  });
});

// Initialize ruleset based on stored state
(async function init() {
  const { enabled } = await chrome.storage.local.get(DEFAULT_STATE);

  chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ["tracking_rules"] : [],
    disableRulesetIds: enabled ? [] : ["tracking_rules"]
  });
})();
```

