## 3) `background.js`

This service worker initializes settings and can later be extended to manage dynamic rules.

```js
const DEFAULT_SETTINGS = {
  enabled: true,
  blockScripts: true,
  blockAnalytics: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await chrome.storage.sync.set({
    enabled: current.enabled ?? DEFAULT_SETTINGS.enabled,
    blockScripts: current.blockScripts ?? DEFAULT_SETTINGS.blockScripts,
    blockAnalytics: current.blockAnalytics ?? DEFAULT_SETTINGS.blockAnalytics
  });
});

chrome.runtime.onStartup?.addListener(async () => {
  // Placeholder for future dynamic rule updates or sync logic.
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.sync.get(DEFAULT_SETTINGS).then((settings) => {
      sendResponse({ ok: true, settings });
    });
    return true;
  }

  if (message?.type === "SET_ENABLED") {
    chrome.storage.sync.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

