## 4) `content.js`

This content script removes common tracking query parameters from links and forms on the page.

```js
const TRACKING_PARAMS = new Set([
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "utm_id",
  "gclid",
  "fbclid",
  "msclkid",
  "mc_cid",
  "mc_eid",
  "igshid"
]);

function cleanUrl(rawUrl) {
  try {
    const url = new URL(rawUrl, window.location.href);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        changed = true;
      }
    }

    return changed ? url.toString() : rawUrl;
  } catch {
    return rawUrl;
  }
}

function cleanAnchors(root = document) {
  const anchors = root.querySelectorAll?.("a[href]") || [];
  for (const a of anchors) {
    const cleaned = cleanUrl(a.href);
    if (cleaned !== a.href) {
      a.href = cleaned;
    }
  }
}

function cleanForms(root = document) {
  const forms = root.querySelectorAll?.("form[action]") || [];
  for (const form of forms) {
    const cleaned = cleanUrl(form.action);
    if (cleaned !== form.action) {
      form.action = cleaned;
    }
  }
}

function observeMutations() {
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE) {
          cleanAnchors(node);
          cleanForms(node);
        }
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
}

(async function init() {
  const { enabled, stripTrackingParams } = await chrome.storage.sync.get([
    "enabled",
    "stripTrackingParams"
  ]);

  if (enabled === false) return;

  if (stripTrackingParams !== false) {
    cleanAnchors();
    cleanForms();
    observeMutations();
  }
})();
```

