A simple service worker that initializes state and can later be extended with custom allow/block lists.

```js
chrome.runtime.onInstalled.addListener(async () => {
  const defaults = {
    enabled: true
  };

  const current = await chrome.storage.local.get(defaults);
  if (current.enabled === undefined) {
    await chrome.storage.local.set(defaults);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.local.get({ enabled: true }).then((result) => {
      sendResponse(result);
    });
    return true;
  }

  if (message?.type === "SET_ENABLED") {
    chrome.storage.local.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

