## 3) `background.js`

A simple service worker that initializes extension state and can be expanded later for dynamic rule management.

```js
chrome.runtime.onInstalled.addListener(async () => {
  const defaults = {
    enabled: true,
    blockedCount: 0
  };

  const current = await chrome.storage.local.get(Object.keys(defaults));
  const merged = { ...defaults, ...current };

  await chrome.storage.local.set(merged);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.local.get(["enabled", "blockedCount"]).then((data) => {
      sendResponse(data);
    });
    return true;
  }

  if (message?.type === "TOGGLE_ENABLED") {
    chrome.storage.local.get(["enabled"]).then(async (data) => {
      const next = !data.enabled;
      await chrome.storage.local.set({ enabled: next });
      sendResponse({ enabled: next });
    });
    return true;
  }
});
```

