This background script handles extension state and provides a place to add future features like dynamic rule updates or per-site allowlists.

```js
const DEFAULTS = {
  enabled: true,
  blockedCount: 0
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULTS);
  await chrome.storage.sync.set({
    enabled: current.enabled ?? true,
    blockedCount: current.blockedCount ?? 0
  });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "TRACKER_BLOCKED") {
    chrome.storage.sync.get({ blockedCount: 0 }).then(({ blockedCount }) => {
      chrome.storage.sync.set({ blockedCount: blockedCount + 1 });
    });
    sendResponse({ ok: true });
    return true;
  }

  if (message?.type === "GET_STATUS") {
    chrome.storage.sync.get(DEFAULTS).then((data) => sendResponse(data));
    return true;
  }

  if (message?.type === "SET_ENABLED") {
    chrome.storage.sync.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

