## `content.js`

This script removes common tracker-related script tags and can observe future DOM insertions.

```js
(async function () {
  const { enabled = true } = await chrome.runtime.sendMessage({ type: "GET_STATE" });

  if (!enabled) return;

  const trackerPatterns = [
    /google-analytics\.com/i,
    /googletagmanager\.com/i,
    /doubleclick\.net/i,
    /facebook\.net/i,
    /connect\.facebook\.net/i,
    /segment\.com/i,
    /mixpanel\.com/i,
    /hotjar\.com/i,
    /clarity\.ms/i,
    /amplitude\.com/i,
    /optimizely\.com/i
  ];

  function isTrackerUrl(url) {
    return trackerPatterns.some((pattern) => pattern.test(url));
  }

  function removeTrackerScripts(root = document) {
    const scripts = root.querySelectorAll?.("script[src]") || [];
    scripts.forEach((script) => {
      const src = script.src || "";
      if (isTrackerUrl(src)) {
        script.remove();
      }
    });
  }

  // Remove already present scripts
  removeTrackerScripts();

  // Observe future script insertions
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        if (node.tagName === "SCRIPT" && node.src && isTrackerUrl(node.src)) {
          node.remove();
          continue;
        }

        removeTrackerScripts(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

