## 3) `background.js`

This service worker manages extension state and can later be extended to support custom allow/block lists.

```js
const DEFAULT_SETTINGS = {
  enabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  if (typeof current.enabled === "undefined") {
    await chrome.storage.sync.set(DEFAULT_SETTINGS);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.sync.get(DEFAULT_SETTINGS).then((data) => {
      sendResponse({ enabled: data.enabled });
    });
    return true;
  }

  if (message?.type === "SET_STATUS") {
    chrome.storage.sync.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

