## 4) `content.js`

This removes tracking script tags that are already in the DOM or injected later.

```js
const TRACKER_PATTERNS = [
  /doubleclick\.net/i,
  /googletagmanager\.com/i,
  /google-analytics\.com/i,
  /google-analytics\.js/i,
  /analytics\.js/i,
  /facebook\.net/i,
  /connect\.facebook\.net/i,
  /segment\.com/i
];

function isTrackerScript(src = "") {
  return TRACKER_PATTERNS.some((re) => re.test(src));
}

function removeTrackerScripts(root = document) {
  const scripts = root.querySelectorAll("script[src]");
  scripts.forEach((script) => {
    const src = script.getAttribute("src") || "";
    if (isTrackerScript(src)) {
      script.remove();
    }
  });
}

// Remove existing tracker scripts as early as possible
removeTrackerScripts();

// Watch for dynamically added scripts
const observer = new MutationObserver((mutations) => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (!(node instanceof Element)) continue;

      if (node.tagName === "SCRIPT") {
        const src = node.getAttribute("src") || "";
        if (isTrackerScript(src)) {
          node.remove();
          continue;
        }
      }

      removeTrackerScripts(node);
    }
  }
});

observer.observe(document.documentElement, {
  childList: true,
  subtree: true
});
```

