## `background.js`

This enables/disables the rules based on a stored toggle.

```js
const RULESET_ID = "tracking_rules";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled = true } = await chrome.storage.sync.get("blockingEnabled");
  await setBlockingEnabled(blockingEnabled);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.blockingEnabled) {
    await setBlockingEnabled(changes.blockingEnabled.newValue);
  }
});
```

