## 3) `background.js`

This stores whether blocking is enabled. When disabled, the rules are turned off.

```js
const RULESET_ID = "default_rules";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({
    blockingEnabled: true
  });
  await setBlockingEnabled(blockingEnabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({
    blockingEnabled: true
  });
  await setBlockingEnabled(blockingEnabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "setBlockingEnabled") {
    chrome.storage.sync.set({ blockingEnabled: message.enabled }, async () => {
      await setBlockingEnabled(message.enabled);
      sendResponse({ ok: true });
    });
    return true;
  }

  if (message?.type === "getBlockingEnabled") {
    chrome.storage.sync.get({ blockingEnabled: true }, (result) => {
      sendResponse({ enabled: result.blockingEnabled });
    });
    return true;
  }
});
```

