## `content.js`
```js
(() => {
  const trackerPatterns = [
    /google-analytics\.com/i,
    /googletagmanager\.com/i,
    /doubleclick\.net/i,
    /facebook\.net/i,
    /connect\.facebook\.net/i,
    /scorecardresearch\.com/i,
    /hotjar\.com/i,
    /mixpanel\.com/i
  ];

  function isTracker(src) {
    return trackerPatterns.some((re) => re.test(src));
  }

  function removeTrackingScripts() {
    const scripts = document.querySelectorAll("script[src], script");
    for (const script of scripts) {
      const src = script.src || "";
      const text = script.textContent || "";

      if (isTracker(src) || /gtag|ga\(|fbq\(|mixpanel/i.test(text)) {
        script.remove();
      }
    }
  }

  removeTrackingScripts();

  const observer = new MutationObserver(() => {
    removeTrackingScripts();
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

