## `background.js`

This keeps track of whether blocking is enabled. If disabled, it removes the dynamic rules.

```js
const STORAGE_KEY = "trackerBlockerEnabled";

async function setEnabled(enabled) {
  await chrome.storage.local.set({ [STORAGE_KEY]: enabled });

  if (enabled) {
    // Re-enable rules by reloading the extension's static ruleset
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["base_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["base_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(STORAGE_KEY);
  if (typeof data[STORAGE_KEY] === "undefined") {
    await chrome.storage.local.set({ [STORAGE_KEY]: true });
  }
  const current = (await chrome.storage.local.get(STORAGE_KEY))[STORAGE_KEY];
  await setEnabled(current);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATE") {
    chrome.storage.local.get(STORAGE_KEY).then((data) => {
      sendResponse({ enabled: !!data[STORAGE_KEY] });
    });
    return true;
  }

  if (message?.type === "SET_STATE") {
    setEnabled(!!message.enabled).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

