## `content.js`

This removes obvious tracking scripts from the page and keeps watching for new ones.

```js
const BLOCKED_PATTERNS = [
  "googletagmanager",
  "google-analytics",
  "doubleclick",
  "facebook.net",
  "segment.com",
  "mixpanel",
  "hotjar",
  "matomo"
];

function looksLikeTracker(url) {
  if (!url) return false;
  return BLOCKED_PATTERNS.some(pattern => url.includes(pattern));
}

function removeTrackingScripts(root = document) {
  const scripts = root.querySelectorAll("script[src], iframe[src]");
  for (const el of scripts) {
    const src = el.getAttribute("src") || "";
    if (looksLikeTracker(src)) {
      el.remove();
    }
  }
}

removeTrackingScripts();

const observer = new MutationObserver(mutations => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (node.nodeType !== Node.ELEMENT_NODE) continue;

      if (node.tagName === "SCRIPT" || node.tagName === "IFRAME") {
        const src = node.getAttribute("src") || "";
        if (looksLikeTracker(src)) {
          node.remove();
          continue;
        }
      }

      removeTrackingScripts(node);
    }
  }
});

observer.observe(document.documentElement, {
  childList: true,
  subtree: true
});
```

