<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Interactive Stock Heatmap</title>
  <style>
    :root {
      --bg: #0b1020;
      --panel: #121a33;
      --grid-gap: 8px;
      --text: #e7ecff;
      --muted: #9aa7c7;
