      backdrop-filter: blur(10px);
      box-shadow: 0 8px 30px var(--shadow);
      z-index: 10;
    }

    .toolbar h1 {
      font-size: 16px;
      margin: 0;
      font-weight: 700;
      letter-spacing: 0.2px;
    }

    .toolbar .spacer {
      flex: 1;
    }

    .btn {
      background: #1a2550;
      color: var(--text);
      border: 1px solid var(--border);
      padding: 8px 12px;
      border-radius: 10px;
      cursor: pointer;
      transition: 0.15s ease;
      font-weight: 600;
    }

    .btn:hover {
      transform: translateY(-1px);
      background: #22306a;
    }

    .status {
