      padding: 16px;
    }

    .grid {
      display: grid;
      grid-template-columns: repeat(10, minmax(110px, 1fr));
      gap: var(--grid-gap);
      width: max-content;
    }

    .cell {
      width: 110px;
      height: 90px;
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,0.08);
