      box-shadow: 0 10px 24px rgba(0,0,0,0.18);
      transition: transform 0.12s ease, box-shadow 0.12s ease;
      position: relative;
      overflow: hidden;
    }

    .cell:hover {
      transform: scale(1.03);
      box-shadow: 0 14px 26px rgba(0,0,0,0.28);
      z-index: 2;
    }

    .ticker {
      font-size: 14px;
      font-weight: 800;
      letter-spacing: 0.3px;
    }

    .price {
      font-size: 13px;
      color: rgba(255,255,255,0.92);
    }

    .change {
      font-size: 12px;
      font-weight: 700;
      opacity: 0.95;
