    .tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(7, 10, 20, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: white;
      padding: 10px 12px;
      border-radius: 12px;
      font-size: 13px;
      line-height: 1.4;
      box-shadow: 0 18px 40px rgba(0,0,0,0.35);
      transform: translate(12px, 12px);
