  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <span class="hint">Wheel = zoom • Drag = pan • Hover = details</span>
      <div class="spacer"></div>
      <button class="btn" id="resetBtn">Reset View</button>
      <button class="btn" id="toggleBtn">Pause Updates</button>
      <div class="status" id="status">Live</div>
    </div>

    <div class="viewport" id="viewport">
      <div class="heatmap" id="heatmap">
        <div class="grid" id="grid"></div>
      </div>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const toggleBtn = document.getElementById('toggleBtn');
    const statusEl = document.getElementById('status');

    // Sample stock universe
    const tickers = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','NFLX','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','CSCO','IBM','SAP','UBER','SONY',
      'BABA','SHOP','SQ','PYPL','COST','WMT','JPM','BAC','V','MA',
      'XOM','CVX','PFE','MRK','JNJ','LLY','NKE','DIS','PEP','KO',
      'MCD','SBUX','TMO','GE','BA','CAT','SPOT','PLTR','SNOW','NOW'
    ];

    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
      live: true,
      stocks: []
    };

    // Initialize stock data
    function initStocks() {
      state.stocks = tickers.map(ticker => {
        const price = +(Math.random() * 500 + 20).toFixed(2);
        const prevClose = +(price * (1 + (Math.random() - 0.5) * 0.08)).toFixed(2);
        const changePct = ((price - prevClose) / prevClose) * 100;
        return { ticker, price, prevClose, changePct };
      });
    }

    function clamp(n, min, max) {
      return Math.max(min, Math.min(max, n));
    }

    function formatMoney(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatPct(v) {
      return `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`;
    }

    // Map changePct to color
    function getColor(changePct) {
      const maxAbs = 8; // saturate around +/-8%
      const t = clamp(changePct / maxAbs, -1, 1);

      // Red -> dark -> green
      if (t < 0) {
        const a = Math.abs(t);
        const r = Math.round(185 + (255 - 185) * (1 - a));
        const g = Math.round(28 + (99 - 28) * (1 - a));
        const b = Math.round(28 + (132 - 28) * (1 - a));
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        const a = t;
        const r = Math.round(31 + (34 - 31) * a);
        const g = Math.round(41 + (197 - 41) * a);
        const b = Math.round(55 + (94 - 55) * a);
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function render() {
      grid.innerHTML = '';
      state.stocks.forEach(stock => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.ticker = stock.ticker;

        const bg = getColor(stock.changePct);
        cell.style.background = `linear-gradient(180deg, color-mix(in srgb, ${bg} 92%, white 8%), ${bg})`;

        const textColor = Math.abs(stock.changePct) > 4 ? '#fff' : '#f5f7ff';
        cell.style.color = textColor;

        cell.innerHTML = `
          <div class="ticker">${stock.ticker}</div>
          <div class="price">${formatMoney(stock.price)}</div>
          <div class="change">${formatPct(stock.changePct)}</div>
        `;

        cell.addEventListener('mouseenter', (e) => showTooltip(e, stock));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);

        grid.appendChild(cell);
      });

      applyTransform();
    }

    function updateCells() {
      const cells = grid.children;
      state.stocks.forEach((stock, i) => {
        const cell = cells[i];
        if (!cell) return;

        cell.style.background = `linear-gradient(180deg, color-mix(in srgb, ${getColor(stock.changePct)} 92%, white 8%), ${getColor(stock.changePct)})`;
        cell.innerHTML = `
          <div class="ticker">${stock.ticker}</div>
          <div class="price">${formatMoney(stock.price)}</div>
          <div class="change">${formatPct(stock.changePct)}</div>
        `;
      });
    }

    function simulateRealTimeUpdate() {
      if (!state.live) return;

      state.stocks = state.stocks.map(stock => {
        const drift = (Math.random() - 0.5) * 0.012; // small random movement
        const newPrice = Math.max(1, stock.price * (1 + drift));
        const changePct = ((newPrice - stock.prevClose) / stock.prevClose) * 100;

        return {
          ...stock,
          price: +newPrice.toFixed(2),
          changePct: +changePct.toFixed(2)
        };
      });

      updateCells();
      statusEl.textContent = `Live • ${new Date().toLocaleTimeString()}`;
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.x = 0;
      state.y = 0;
      applyTransform();
    }

    function showTooltip(e, stock) {
      tooltip.style.opacity = '1';
      tooltip.innerHTML = `
        <strong>${stock.ticker}</strong><br/>
        Price: ${formatMoney(stock.price)}<br/>
        Prev Close: ${formatMoney(stock.prevClose)}<br/>
        Change: ${formatPct(stock.changePct)}
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const pad = 16;
      const x = clamp(e.clientX + 12, pad, window.innerWidth - 220);
      const y = clamp(e.clientY + 12, pad, window.innerHeight - 120);
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = '0';
    }

    // Pan interactions
    viewport.addEventListener('mousedown', (e) => {
      if (e.target.closest('.cell')) return;
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.x;
      state.panStartY = state.y;
      viewport.style.cursor = 'grabbing';
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) return;
      state.x = state.panStartX + (e.clientX - state.dragStartX);
      state.y = state.panStartY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      viewport.style.cursor = 'default';
    });

    // Zoom interactions
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - state.x) / state.scale;
      const worldY = (mouseY - state.y) / state.scale;

      state.scale = newScale;
      state.x = mouseX - worldX * state.scale;
      state.y = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    // Touch/pointer support could be added here if desired.

    resetBtn.addEventListener('click', resetView);

    toggleBtn.addEventListener('click', () => {
      state.live = !state.live;
      toggleBtn.textContent = state.live ? 'Pause Updates' : 'Resume Updates';
      statusEl.textContent = state.live ? 'Live' : 'Paused';
    });

    // Auto-update every second
    initStocks();
    render();
    setInterval(simulateRealTimeUpdate, 1000);

    // Optional: keep tooltip hidden on resize
    window.addEventListener('resize', hideTooltip);
  </script>
</body>
</html>
```

