      --text: #e8eefc;
      --muted: #93a4c3;
      --grid: rgba(255,255,255,0.08);
      --border: rgba(255,255,255,0.12);
    }

    html, body {
      margin: 0;
      height: 100%;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      overflow: hidden;
    }

    .app {
      display: grid;
      grid-template-rows: auto 1fr auto;
      height: 100vh;
    }

    .toolbar {
      display: flex;
      gap: 12px;
      align-items: center;
      padding: 12px 16px;
      background: var(--panel);
      border-bottom: 1px solid var(--border);
      flex-wrap: wrap;
    }

    .toolbar h1 {
      font-size: 16px;
      margin: 0;
      font-weight: 600;
    }

    .toolbar .spacer {
      flex: 1;
    }

    .toolbar button {
      background: #1d2a52;
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
