      cursor: pointer;
    }

    .toolbar button:hover {
      background: #243463;
    }

    .toolbar .hint {
      color: var(--muted);
      font-size: 13px;
    }

    .viewport {
      position: relative;
      overflow: hidden;
      touch-action: none;
      background:
        linear-gradient(to bottom, rgba(255,255,255,0.03), transparent),
        var(--bg);
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 15, 30, 0.95);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 8px;
      padding: 8px 10px;
      color: white;
      font-size: 13px;
      line-height: 1.35;
      transform: translate(12px, 12px);
      white-space: nowrap;
      display: none;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    }

    .statusbar {
      display: flex;
      justify-content: space-between;
      padding: 8px 16px;
      background: var(--panel);
      border-top: 1px solid var(--border);
