      display: flex;
      align-items: center;
      gap: 10px;
    }

    .swatch {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #d73027, #fee08b, #1a9850);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="hint">Wheel to zoom • Drag to pan • Hover for details</div>
      <div class="spacer"></div>
      <button id="resetBtn">Reset View</button>
      <button id="toggleStreamBtn">Pause Stream</button>
    </div>

    <div id="viewport" class="viewport">
      <canvas id="heatmap"></canvas>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="statusbar">
      <div class="legend">
        <span>Performance:</span>
        <div class="swatch"></div>
        <span>Red = down, Green = up</span>
      </div>
      <div id="status">Connected</div>
    </div>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById("heatmap");
      const viewport = document.getElementById("viewport");
      const tooltip = document.getElementById("tooltip");
      const status = document.getElementById("status");
      const resetBtn = document.getElementById("resetBtn");
      const toggleStreamBtn = document.getElementById("toggleStreamBtn");

      const ctx = canvas.getContext("2d");

      // ----- Data model -----
      const rows = 40;   // stocks
      const cols = 120;  // time buckets
      const symbols = Array.from({ length: rows }, (_, i) => `STK${String(i + 1).padStart(3, "0")}`);

      // Heatmap values: percentage change from baseline, roughly [-8, +8]
      const data = Array.from({ length: rows }, () =>
        Array.from({ length: cols }, () => (Math.random() - 0.5) * 4)
      );

      // ----- View transform -----
      let scale = 1;
      let offsetX = 0;
      let offsetY = 0;

      let dpr = Math.max(1, window.devicePixelRatio || 1);
      let viewW = 0;
      let viewH = 0;

      // Cell size in world coordinates
      const cellW = 18;
      const cellH = 18;
      const labelW = 72;
      const labelH = 18;

      // Interaction state
      let isDragging = false;
      let dragStart = { x: 0, y: 0 };
      let panStart = { x: 0, y: 0 };
      let streamEnabled = true;

      // Mouse position for hover
      let mouse = { x: 0, y: 0, inside: false };

      function resize() {
        dpr = Math.max(1, window.devicePixelRatio || 1);
        viewW = viewport.clientWidth;
        viewH = viewport.clientHeight;

        canvas.width = Math.floor(viewW * dpr);
        canvas.height = Math.floor(viewH * dpr);
        canvas.style.width = viewW + "px";
        canvas.style.height = viewH + "px";

        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

        if (offsetX === 0 && offsetY === 0) {
          // initial fit
          const contentW = labelW + cols * cellW;
          const contentH = rows * cellH;
          const fitScale = Math.min(viewW / contentW, viewH / contentH) * 0.95;
          scale = Math.max(0.5, Math.min(2, fitScale));
          offsetX = (viewW - contentW * scale) / 2;
          offsetY = (viewH - contentH * scale) / 2;
        }

        render();
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function worldToScreen(wx, wy) {
        return {
          x: wx * scale + offsetX,
          y: wy * scale + offsetY
        };
      }

      function screenToWorld(sx, sy) {
        return {
          x: (sx - offsetX) / scale,
          y: (sy - offsetY) / scale
        };
      }

      function valueToColor(v) {
        // Map roughly [-8, +8] to red-yellow-green
        const min = -8, max = 8;
        const t = clamp((v - min) / (max - min), 0, 1);

        // Interpolate red -> yellow -> green
        let r, g, b;
        if (t < 0.5) {
          const u = t / 0.5;
          r = 215 + (254 - 215) * u;
          g = 48 + (224 - 48) * u;
          b = 39 + (139 - 39) * u;
        } else {
          const u = (t - 0.5) / 0.5;
          r = 254 + (26 - 254) * u;
          g = 224 + (152 - 224) * u;
          b = 139 + (80 - 139) * u;
        }
        return `rgb(${r|0},${g|0},${b|0})`;
      }

      function drawGridLines(x0, y0, w, h, stepX, stepY) {
        ctx.strokeStyle = "rgba(255,255,255,0.06)";
        ctx.lineWidth = 1;

        ctx.beginPath();
        for (let x = x0; x <= x0 + w + 0.5; x += stepX) {
          ctx.moveTo(x, y0);
          ctx.lineTo(x, y0 + h);
        }
        for (let y = y0; y <= y0 + h + 0.5; y += stepY) {
          ctx.moveTo(x0, y);
          ctx.lineTo(x0 + w, y);
        }
        ctx.stroke();
      }

      function render() {
        ctx.clearRect(0, 0, viewW, viewH);

        // Background
        ctx.fillStyle = "#0b1020";
        ctx.fillRect(0, 0, viewW, viewH);

        const contentX = labelW;
        const contentY = 0;
        const contentW = cols * cellW;
        const contentH = rows * cellH;

        const screen = worldToScreen(0, 0);
        const sx0 = contentX * scale + offsetX;
        const sy0 = contentY * scale + offsetY;

        // Clip to viewport
        ctx.save();
        ctx.beginPath();
        ctx.rect(0, 0, viewW, viewH);
        ctx.clip();

        // Draw row labels
        ctx.font = `${12 * scale}px system-ui, sans-serif`;
        ctx.textBaseline = "middle";
        ctx.fillStyle = "rgba(232,238,252,0.92)";
        for (let r = 0; r < rows; r++) {
          const y = (r * cellH + cellH / 2) * scale + offsetY;
          if (y < -20 || y > viewH + 20) continue;
          ctx.fillText(symbols[r], 10 * scale + offsetX, y);
        }

        // Draw cells
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const x = (contentX + c * cellW) * scale + offsetX;
            const y = (contentY + r * cellH) * scale + offsetY;
            const w = cellW * scale;
            const h = cellH * scale;

            if (x > viewW || y > viewH || x + w < 0 || y + h < 0) continue;

            ctx.fillStyle = valueToColor(data[r][c]);
            ctx.fillRect(x, y, w, h);

            // subtle cell border
            if (scale > 0.7) {
              ctx.strokeStyle = "rgba(255,255,255,0.06)";
              ctx.strokeRect(x, y, w, h);
            }
          }
        }

        // Highlight hovered cell
        if (mouse.inside) {
          const world = screenToWorld(mouse.x, mouse.y);
          const col = Math.floor((world.x - labelW) / cellW);
          const row = Math.floor(world.y / cellH);

          if (row >= 0 && row < rows && col >= 0 && col < cols) {
            const x = (labelW + col * cellW) * scale + offsetX;
            const y = (row * cellH) * scale + offsetY;
            const w = cellW * scale;
            const h = cellH * scale;

            ctx.strokeStyle = "rgba(255,255,255,0.9)";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
          }
        }

        ctx.restore();

        // Grid overlay for labels area
        if (scale > 0.6) {
          const gridX = labelW * scale + offsetX;
          drawGridLines(gridX, offsetY, cols * cellW * scale, rows * cellH * scale, cellW * scale, cellH * scale);
        }

        // Axis labels (simple)
        ctx.fillStyle = "rgba(147,164,195,0.95)";
        ctx.font = `${11 * scale}px system-ui, sans-serif`;
        ctx.fillText("Stocks", 10, 14);
        ctx.fillText("Time →", labelW * scale + offsetX + 8, 14);
      }

      function updateTooltip() {
        if (!mouse.inside) {
          tooltip.style.display = "none";
          return;
        }

        const world = screenToWorld(mouse.x, mouse.y);
        const col = Math.floor((world.x - labelW) / cellW);
        const row = Math.floor(world.y / cellH);

        if (row >= 0 && row < rows && col >= 0 && col < cols) {
          const v = data[row][col];
          tooltip.style.display = "block";
          tooltip.style.left = mouse.x + "px";
          tooltip.style.top = mouse.y + "px";
          tooltip.innerHTML = `
            <div><strong>${symbols[row]}</strong></div>
            <div>Bucket: ${col}</div>
            <div>Change: <strong style="color:${v >= 0 ? '#7CFF9B' : '#FF8A8A'}">${v.toFixed(2)}%</strong></div>
          `;
        } else {
          tooltip.style.display = "none";
        }
      }

      function zoomAt(screenX, screenY, zoomFactor) {
        const before = screenToWorld(screenX, screenY);
        scale = clamp(scale * zoomFactor, 0.35, 4);
        const after = screenToWorld(screenX, screenY);

        offsetX += (after.x - before.x) * scale;
        offsetY += (after.y - before.y) * scale;

        render();
        updateTooltip();
      }

      // ----- Interaction handlers -----
      viewport.addEventListener("pointerdown", (e) => {
        isDragging = true;
        viewport.setPointerCapture(e.pointerId);
        dragStart = { x: e.clientX, y: e.clientY };
        panStart = { x: offsetX, y: offsetY };
      });

      viewport.addEventListener("pointermove", (e) => {
        mouse = { x: e.clientX - viewport.getBoundingClientRect().left, y: e.clientY - viewport.getBoundingClientRect().top, inside: true };

        if (isDragging) {
          offsetX = panStart.x + (e.clientX - dragStart.x);
          offsetY = panStart.y + (e.clientY - dragStart.y);
          render();
        }
        updateTooltip();
      });

      viewport.addEventListener("pointerup", (e) => {
        isDragging = false;
        try { viewport.releasePointerCapture(e.pointerId); } catch {}
      });

      viewport.addEventListener("pointerleave", () => {
        mouse.inside = false;
        tooltip.style.display = "none";
        render();
      });

      viewport.addEventListener("wheel", (e) => {
        e.preventDefault();
        const rect = viewport.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;
        const zoomFactor = Math.exp(-e.deltaY * 0.0015);
        zoomAt(sx, sy, zoomFactor);
      }, { passive: false });

      // Double click to zoom in
      viewport.addEventListener("dblclick", (e) => {
        const rect = viewport.getBoundingClientRect();
        zoomAt(e.clientX - rect.left, e.clientY - rect.top, 1.4);
      });

      // ----- Real-time updates (simulated stream) -----
      function tickStream() {
        if (!streamEnabled) return;

        // Update a subset of cells to simulate live feed
        for (let i = 0; i < 70; i++) {
          const r = Math.floor(Math.random() * rows);
          const c = Math.floor(Math.random() * cols);

          // random walk with mild mean reversion
          const current = data[r][c];
          const drift = (Math.random() - 0.5) * 0.8;
          const meanRevert = -current * 0.02;
          data[r][c] = clamp(current + drift + meanRevert, -10, 10);
        }

        status.textContent = `Connected • ${new Date().toLocaleTimeString()}`;
        render();
        updateTooltip();
      }

      let streamTimer = setInterval(tickStream, 250);

      // ----- Controls -----
      resetBtn.addEventListener("click", () => {
        offsetX = 0;
        offsetY = 0;
        scale = 1;
        resize();
      });

      toggleStreamBtn.addEventListener("click", () => {
        streamEnabled = !streamEnabled;
        toggleStreamBtn.textContent = streamEnabled ? "Pause Stream" : "Resume Stream";
        status.textContent = streamEnabled ? "Connected" : "Stream paused";
      });

      // ----- Initialize -----
      window.addEventListener("resize", resize);
      resize();

      // Optional: simulate a real connection status
      setInterval(() => {
        if (streamEnabled) {
          status.textContent = `Connected • ${new Date().toLocaleTimeString()}`;
        }
      }, 1000);
    })();
  </script>
</body>
</html>
```

---

### How it works

- **Canvas** is used for fast drawing of many cells.
- **Real-time updates** are simulated with a timer that mutates random cells.
- **Zoom** is handled with the mouse wheel and double-click.
- **Pan** is handled by dragging.
- **Hover tooltips** show the stock symbol, time bucket, and current percentage change.

