      svg.attr("viewBox", `0 0 ${width} ${height}`);

      const contentWidth = cols * cellW;
      const rows = Math.ceil(data.length / cols);
      const contentHeight = rows * cellH;

      const scale = Math.min(
        (width - margin.left - margin.right) / contentWidth,
        (height - margin.top - margin.bottom) / contentHeight
      ) * 0.98;

      const tx = (width - contentWidth * scale) / 2;
      const ty = (height - contentHeight * scale) / 2;

      transform = d3.zoomIdentity.translate(tx, ty).scale(scale);
      svg.call(zoomBehavior.transform, transform);

      render();
    }

    const zoomBehavior = d3.zoom()
      .scaleExtent([0.5, 4])
      .on("zoom", (event) => {
        transform = event.transform;
        zoomLayer.attr("transform", transform);
      });

    svg.call(zoomBehavior);

    function render() {
      const cells = gridLayer.selectAll(".cell")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell")
        .on("mouseenter", (event, d) => showTooltip(event, d))
        .on("mousemove", (event, d) => moveTooltip(event, d))
        .on("mouseleave", hideTooltip)
        .on("click", (event, d) => {
          d.pinned = !d.pinned;
          pinnedStock = d.pinned ? d : null;
          updateSelectedPanel();
          render();
        });

      cellsEnter.append("rect");
      cellsEnter.append("text");

      const merged = cellsEnter.merge(cells);

      merged
        .classed("pinned", d => d.pinned)
        .transition()
        .duration(250)
        .attr("transform", d => `translate(${d.col * cellW + 10}, ${d.row * cellH + 10})`);

      merged.select("rect")
        .transition()
        .duration(250)
        .attr("width", cellW - 20)
        .attr("height", cellH - 20)
        .attr("fill", d => color(d.changePct));

      merged.select("text")
        .text(d => d.symbol)
        .attr("x", (cellW - 20) / 2)
        .attr("y", 22);

      merged.each(function(d) {
        const g = d3.select(this);
        const rect = g.select("rect");
        const label = g.select("text");

        const showPrice = (cellW - 20) > 90 && (cellH - 20) > 52;
        const existing = g.selectAll(".price-line").data(showPrice ? [d] : []);
        existing.join(
          enter => enter.append("text")
            .attr("class", "price-line")
            .attr("x", (cellW - 20) / 2)
            .attr("y", 42)
            .style("fill", "rgba(255,255,255,0.92)")
            .style("font-size", "10px")
            .style("font-weight", "500")
            .style("text-anchor", "middle")
            .text(dd => `$${dd.price.toFixed(2)} (${dd.changePct >= 0 ? "+" : ""}${dd.changePct.toFixed(2)}%)`),
          update => update.text(dd => `$${dd.price.toFixed(2)} (${dd.changePct >= 0 ? "+" : ""}${dd.changePct.toFixed(2)}%)`),
          exit => exit.remove()
        );
      });

      cells.exit().remove();
    }

    function showTooltip(event, d) {
      tooltip.style("opacity", 1);
      moveTooltip(event, d);
    }

    function moveTooltip(event, d) {
      const [x, y] = d3.pointer(event, document.body);
      tooltip
        .html(`
          <div class="name">${d.symbol}${d.pinned ? " ★" : ""}</div>
          <div>Price: <strong>$${d.price.toFixed(2)}</strong></div>
          <div>Change: <strong style="color:${d.changePct >= 0 ? '#4ade80' : '#f87171'}">
            ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          </strong></div>
          <div>Prev Close: $${d.prevClose.toFixed(2)}</div>
          <div>Volume: ${d.volume.toLocaleString()}</div>
        `)
        .style("left", `${x + 14}px`)
        .style("top", `${y + 14}px`);
    }

    function hideTooltip() {
      if (!pinnedStock) tooltip.style("opacity", 0);
    }

    function updateSelectedPanel() {
      if (!pinnedStock) {
        selectedInfo.text("None pinned");
        return;
      }
      selectedInfo.html(`
        <div><strong>${pinnedStock.symbol}</strong></div>
        <div>Price: $${pinnedStock.price.toFixed(2)}</div>
        <div>Change: ${pinnedStock.changePct >= 0 ? "+" : ""}${pinnedStock.changePct.toFixed(2)}%</div>
        <div>Volume: ${pinnedStock.volume.toLocaleString()}</div>
      `);
    }

    function simulateTick() {
      if (!streaming) return;

      const updatesPerTick = 4 + Math.floor(Math.random() * 5);

      for (let i = 0; i < updatesPerTick; i++) {
        const d = data[Math.floor(Math.random() * data.length)];
        const drift = (Math.random() - 0.5) * 2.2;
        const shock = (Math.random() - 0.5) * 0.8;
        const pctMove = drift + shock;

        d.price = Math.max(1, d.price * (1 + pctMove / 100));
        d.volume += Math.floor(Math.random() * 5000);

        d.changePct = ((d.price - d.prevClose) / d.prevClose) * 100;
        d.changePct = Math.max(-5, Math.min(5, d.changePct));
      }

      render();

      if (pinnedStock) {
        const fresh = data.find(x => x.symbol === pinnedStock.symbol);
        pinnedStock = fresh;
        updateSelectedPanel();
      }
    }

    toggleStreamBtn.addEventListener("click", () => {
      streaming = !streaming;
      statusEl.textContent = `Streaming: ${streaming ? "ON" : "PAUSED"}`;
      toggleStreamBtn.textContent = streaming ? "Pause Stream" : "Resume Stream";
    });

    resetZoomBtn.addEventListener("click", () => {
      resize();
    });

    window.addEventListener("resize", resize);

    render();
    resize();
    updateSelectedPanel();

    setInterval(simulateTick, 900);
  </script>
</body>
</html>
```

---

## How it works

### 1. Heatmap layout
Each stock is a tile in a grid. The grid is rendered in SVG for easier zooming and interaction.

### 2. Real-time updates
A `setInterval()` simulates incoming market data by randomly adjusting stock prices and volume. In production, you’d replace `simulateTick()` with:

- WebSocket messages
- SSE
- polling an API every N seconds

### 3. Zoom and pan
D3’s `zoom()` behavior handles:
- mouse wheel zoom
- click-drag pan
- programmatic reset

### 4. Color mapping
The tile color is based on percentage change using a linear scale:
- red = negative
- dark = near flat
- green = positive

### 5. Hover and pin
- Hover shows a tooltip
- Click toggles a pinned state
- Pinned stock is shown in the sidebar

