<body>
  <div class="app">
    <header>
      <div class="toolbar">
        <h1>Stock Price Heatmap</h1>
        <button id="resetView">Reset View</button>
        <button id="toggleLive">Pause Live Updates</button>
        <div class="hint">Drag to pan · Scroll to zoom · Hover tiles for details</div>
      </div>
    </header>

    <div id="chartWrap">
      <svg id="chart" aria-label="Stock heatmap chart"></svg>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <footer>
      Client-side demo with simulated real-time updates. Replace the data generator with a WebSocket/API feed for production use.
    </footer>
  </div>

  <script>
    const svg = document.getElementById("chart");
    const chartWrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetViewBtn = document.getElementById("resetView");
    const toggleLiveBtn = document.getElementById("toggleLive");

    // --- Demo data ---
    const sectors = [
      "Tech", "Finance", "Health", "Energy", "Retail",
      "Media", "Auto", "Travel", "Industrials", "Crypto"
    ];

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","JPM","BAC","WFC",
      "PFE","JNJ","UNH","XOM","CVX","WMT","TGT","COST","DIS","NFLX",
      "F","GM","UBER","LYFT","BA","CAT","GE","AMD","INTC","COIN"
    ];

    const rows = 6;
    const cols = 5;
    const tiles = [];
    let live = true;

    // View transform
    let view = {
      scale: 1,
      tx: 0,
      ty: 0
    };

    // Layout
    function resizeSVG() {
      const rect = chartWrap.getBoundingClientRect();
      svg.setAttribute("viewBox", `0 0 ${rect.width} ${rect.height}`);
      render();
    }

    window.addEventListener("resize", resizeSVG);

    // Generate initial tiles
    function randomTile(i) {
      const sector = sectors[i % sectors.length];
      const symbol = symbols[i % symbols.length];
      return {
        id: i,
        symbol,
        sector,
        price: +(50 + Math.random() * 450).toFixed(2),
        changePct: +(Math.random() * 8 - 4).toFixed(2),
        volume: Math.floor(100000 + Math.random() * 900000)
      };
    }

    for (let i = 0; i < rows * cols; i++) {
      tiles.push(randomTile(i));
    }

    // Color scale: red -> yellow -> green
    function colorForChange(changePct) {
      const min = -5, max = 5;
      const t = Math.max(0, Math.min(1, (changePct - min) / (max - min)));

      // interpolate red (#dc2626) -> yellow (#f59e0b) -> green (#22c55e)
      const stops = [
        { t: 0.0, c: [220, 38, 38] },
        { t: 0.5, c: [245, 158, 11] },
        { t: 1.0, c: [34, 197, 94] }
      ];

      let a = stops[0], b = stops[2];
      if (t <= 0.5) { a = stops[0]; b = stops[1]; }
      else { a = stops[1]; b = stops[2]; }

      const localT = (t - a.t) / (b.t - a.t);
      const rgb = a.c.map((v, i) => Math.round(v + (b.c[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function textColorForChange(changePct) {
      return Math.abs(changePct) > 2.2 ? "white" : "#f8fafc";
    }

    function render() {
      const rect = chartWrap.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      const padding = 24;
      const gap = 12;
      const tileW = (width - padding * 2 - gap * (cols - 1)) / cols;
      const tileH = (height - padding * 2 - gap * (rows - 1)) / rows;

      svg.innerHTML = "";

      const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
      g.setAttribute("transform", `translate(${view.tx}, ${view.ty}) scale(${view.scale})`);
      svg.appendChild(g);

      tiles.forEach((d, i) => {
        const r = Math.floor(i / cols);
        const c = i % cols;

        const x = padding + c * (tileW + gap);
        const y = padding + r * (tileH + gap);

        const tile = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        tile.setAttribute("class", "tile");
        tile.setAttribute("x", x);
        tile.setAttribute("y", y);
        tile.setAttribute("width", tileW);
        tile.setAttribute("height", tileH);
        tile.setAttribute("fill", colorForChange(d.changePct));

        tile.addEventListener("mouseenter", (e) => showTooltip(e, d));
        tile.addEventListener("mousemove", (e) => moveTooltip(e));
        tile.addEventListener("mouseleave", hideTooltip);

        g.appendChild(tile);

        const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
        label.setAttribute("class", "label");
        label.setAttribute("x", x + tileW / 2);
        label.setAttribute("y", y + tileH / 2 - 8);
        label.setAttribute("fill", textColorForChange(d.changePct));
        label.textContent = d.symbol;
        g.appendChild(label);

        const sub = document.createElementNS("http://www.w3.org/2000/svg", "text");
        sub.setAttribute("class", "subLabel");
        sub.setAttribute("x", x + tileW / 2);
        sub.setAttribute("y", y + tileH / 2 + 10);
        sub.setAttribute("fill", textColorForChange(d.changePct));
        sub.textContent = `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`;
        g.appendChild(sub);
      });
    }

    function showTooltip(e, d) {
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong> · ${d.sector}<br/>
        Price: $${d.price.toFixed(2)}<br/>
        Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%<br/>
        Volume: ${d.volume.toLocaleString()}
      `;
      tooltip.classList.add("visible");
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const wrapRect = chartWrap.getBoundingClientRect();
      const x = e.clientX - wrapRect.left;
      const y = e.clientY - wrapRect.top;

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // --- Real-time updates (simulated) ---
    function updatePrices() {
      if (!live) return;

      tiles.forEach(d => {
        const delta = (Math.random() - 0.5) * 0.6;
        d.price = Math.max(1, +(d.price + delta).toFixed(2));
        d.changePct = Math.max(-9.99, Math.min(9.99, +(d.changePct + (Math.random() - 0.5) * 0.25).toFixed(2)));
        d.volume += Math.floor(Math.random() * 5000);
      });

      render();
    }

    setInterval(updatePrices, 1000);

    // --- Zoom & pan ---
    let isPanning = false;
    let startX = 0, startY = 0;
    let baseTx = 0, baseTy = 0;

    chartWrap.addEventListener("pointerdown", (e) => {
      isPanning = true;
      chartWrap.setPointerCapture(e.pointerId);
      startX = e.clientX;
      startY = e.clientY;
      baseTx = view.tx;
      baseTy = view.ty;
      hideTooltip();
    });

    chartWrap.addEventListener("pointermove", (e) => {
      if (!isPanning) return;
      view.tx = baseTx + (e.clientX - startX);
      view.ty = baseTy + (e.clientY - startY);
      render();
    });

    chartWrap.addEventListener("pointerup", () => {
      isPanning = false;
    });

    chartWrap.addEventListener("pointercancel", () => {
      isPanning = false;
    });

    chartWrap.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = chartWrap.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = Math.max(0.5, Math.min(4, view.scale * zoomFactor));

      // Zoom around mouse position
      const worldX = (mx - view.tx) / view.scale;
      const worldY = (my - view.ty) / view.scale;

      view.scale = nextScale;
      view.tx = mx - worldX * view.scale;
      view.ty = my - worldY * view.scale;

      render();
    }, { passive: false });

    // --- Controls ---
    resetViewBtn.addEventListener("click", () => {
      view.scale = 1;
      view.tx = 0;
      view.ty = 0;
      render();
    });

    toggleLiveBtn.addEventListener("click", () => {
      live = !live;
      toggleLiveBtn.textContent = live ? "Pause Live Updates" : "Resume Live Updates";
    });

    // Initial render
    resizeSVG();
  </script>
</body>
</html>
