    .main {
      position: relative;
      overflow: hidden;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background:
        radial-gradient(circle at 20% 20%, rgba(82, 113, 255, 0.08), transparent 30%),
        radial-gradient(circle at 80% 70%, rgba(0, 255, 170, 0.05), transparent 30%),
        var(--bg);
      cursor: grab;
