      position: absolute;
      pointer-events: none;
      background: rgba(10, 14, 28, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: white;
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 12px;
      line-height: 1.45;
      box-shadow: 0 12px 30px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      transition: opacity 120ms ease;
      max-width: 220px;
      z-index: 10;
    }

    .tooltip .sym {
      font-weight: 800;
      font-size: 13px;
      margin-bottom: 4px;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 18px 14px;
      border-top: 1px solid var(--border);
      background: rgba(255,255,255,0.02);
      color: var(--muted);
      font-size: 12px;
    }

    .legendBar {
      width: 240px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(90deg, #b71c1c, #ff7043, #263238, #66bb6a, #1b5e20);
      border: 1px solid rgba(255,255,255,0.12);
    }

    .hint {
      margin-left: auto;
    }

    .selected {
      stroke: #ffd54f !important;
      stroke-width: 2 !important;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="topbar">
      <div>
        <div class="title">Interactive Stock Price Heatmap</div>
        <div style="color: var(--muted); font-size: 12px; margin-top: 4px;">
          Drag to pan · Scroll to zoom · Hover for details · Click to pin
        </div>
      </div>

      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <button id="pauseBtn">Pause Updates</button>
        <div class="stats">
          <div>Last update: <span id="lastUpdate">—</span></div>
          <div>Selected: <span id="selectedInfo">None</span></div>
        </div>
      </div>
    </div>

    <div class="main" id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="legend">
      <div class="legendBar"></div>
      <div>Red = down, gray = flat, green = up</div>
      <div class="hint">Live prices simulated every 500ms</div>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const lastUpdate = document.getElementById("lastUpdate");
    const selectedInfo = document.getElementById("selectedInfo");

    const width = () => wrap.clientWidth;
    const height = () => wrap.clientHeight;

    const cols = 8;
    const rows = 5;
    const gap = 10;
    const padding = 24;

    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","AMD",
      "NFLX","INTC","ORCL","CRM","UBER","SHOP","QCOM","AVGO",
      "JPM","BAC","WMT","COST","DIS","PEP","KO","XOM",
      "CVX","BA","GE","IBM","ADBE","SNOW","PLTR","SQ",
      "PYPL","MCD","NKE","T","V","MA","LLY","PFE"
    ];

    let paused = false;
    let selectedSymbol = null;

    // Create mock stock data
    const data = symbols.map((sym, i) => {
      const price = 50 + Math.random() * 500;
      const prevClose = price * (1 + (Math.random() - 0.5) * 0.02);
      return {
        symbol: sym,
        sector: ["Tech", "Finance", "Retail", "Energy", "Health"][i % 5],
        price,
        prevClose,
        change: ((price - prevClose) / prevClose) * 100,
        volume: Math.floor(1e6 + Math.random() * 9e6)
      };
    });

    const color = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#b71c1c", "#ff7043", "#263238", "#66bb6a", "#1b5e20"])
      .clamp(true);

    const priceFmt = d3.format("$.2f");
    const pctFmt = d3.format("+.2f");
    const volFmt = d3.format(",");

    const g = svg.append("g").attr("class", "root");
    const cellsG = g.append("g").attr("class", "cells");

    const zoom = d3.zoom()
      .scaleExtent([0.6, 6])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    function layout() {
      const w = width();
      const h = height();
      svg.attr("viewBox", `0 0 ${w} ${h}`);

      const cellW = (w - padding * 2 - gap * (cols - 1)) / cols;
      const cellH = (h - padding * 2 - gap * (rows - 1)) / rows;

      data.forEach((d, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        d.x = padding + col * (cellW + gap);
        d.y = padding + row * (cellH + gap);
        d.w = cellW;
        d.h = cellH;
      });

      render();
    }

    function render() {
      const cells = cellsG.selectAll("g.cellGroup")
        .data(data, d => d.symbol);

      const enter = cells.enter()
        .append("g")
        .attr("class", "cellGroup")
        .style("cursor", "pointer")
        .on("mouseenter", (event, d) => showTooltip(event, d))
        .on("mousemove", (event, d) => moveTooltip(event, d))
        .on("mouseleave", () => hideTooltip())
        .on("click", (event, d) => {
          selectedSymbol = d.symbol;
          selectedInfo.textContent = `${d.symbol} (${pctFmt(d.change)}%)`;
          updateSelectionStyles();
          event.stopPropagation();
        });

      enter.append("rect")
        .attr("class", "cell");

      enter.append("text")
        .attr("class", "label")
        .attr("x", 12)
        .attr("y", 22)
        .text(d => d.symbol);

      enter.append("text")
        .attr("class", "subLabel")
        .attr("x", 12)
        .attr("y", 40)
        .text(d => `${priceFmt(d.price)}  ${pctFmt(d.change)}%`);

      const merged = enter.merge(cells);

      merged.attr("transform", d => `translate(${d.x},${d.y})`);

      merged.select("rect.cell")
        .attr("width", d => d.w)
        .attr("height", d => d.h)
        .attr("fill", d => color(d.change))
        .classed("selected", d => d.symbol === selectedSymbol);

      merged.select("text.label")
        .text(d => d.symbol);

      merged.select("text.subLabel")
        .text(d => `${priceFmt(d.price)}  ${pctFmt(d.change)}%`);

      cells.exit().remove();
    }

    function showTooltip(event, d) {
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <div class="sym">${d.symbol}</div>
        <div>Price: <strong>${priceFmt(d.price)}</strong></div>
        <div>Change: <strong style="color:${d.change >= 0 ? '#7CFC9A' : '#FF8A80'}">${pctFmt(d.change)}%</strong></div>
        <div>Prev Close: <strong>${priceFmt(d.prevClose)}</strong></div>
        <div>Volume: <strong>${volFmt(d.volume)}</strong></div>
        <div>Sector: <strong>${d.sector}</strong></div>
      `;
      moveTooltip(event, d);
    }

    function moveTooltip(event) {
      const rect = wrap.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      if (selectedSymbol) return; // keep selection visible only via highlight, tooltip still hides
      tooltip.style.opacity = 0;
    }

    function updateSelectionStyles() {
      cellsG.selectAll("g.cellGroup rect")
        .classed("selected", d => d.symbol === selectedSymbol);
    }

    function tick() {
      if (paused) return;

      // Randomly update a subset each tick
      const updates = Math.max(4, Math.floor(data.length * 0.22));
      for (let i = 0; i < updates; i++) {
        const d = data[Math.floor(Math.random() * data.length)];
        const drift = (Math.random() - 0.5) * 0.02; // +/- 1%
        d.prevClose = d.prevClose || d.price;
        d.price = Math.max(1, d.price * (1 + drift));
        d.change = ((d.price - d.prevClose) / d.prevClose) * 100;
        d.volume += Math.floor(Math.random() * 50000);
      }

      lastUpdate.textContent = new Date().toLocaleTimeString();
      render();
    }

    // Reset view
    document.getElementById("resetBtn").addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    // Pause/resume updates
    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      paused = !paused;
      e.target.textContent = paused ? "Resume Updates" : "Pause Updates";
    });

    // Click background to clear selection
    svg.on("click", () => {
      selectedSymbol = null;
      selectedInfo.textContent = "None";
      tooltip.style.opacity = 0;
      updateSelectionStyles();
    });

    // Resize handling
    const ro = new ResizeObserver(() => layout());
    ro.observe(wrap);

    // Initial render
    layout();
    lastUpdate.textContent = new Date().toLocaleTimeString();

    // Simulated live feed
    setInterval(tick, 500);

    // Optional: keyboard shortcuts
    window.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        selectedSymbol = null;
        selectedInfo.textContent = "None";
        tooltip.style.opacity = 0;
        updateSelectionStyles();
      }
    });
  </script>
</body>
