  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <button id="resetBtn">Reset View</button>
      <button id="toggleRealtimeBtn">Pause Updates</button>
      <button id="randomizeBtn">Randomize Data</button>
      <div class="status" id="status">Live</div>
    </div>

    <div class="viewport" id="viewport">
      <canvas id="canvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="legend">
      <span>Loss</span>
      <div class="bar"></div>
      <span>Gain</span>
      <span style="margin-left: 12px;">Mouse wheel: zoom · Drag: pan · Hover: details</span>
    </div>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('canvas');
      const ctx = canvas.getContext('2d');
      const viewport = document.getElementById('viewport');
      const tooltip = document.getElementById('tooltip');
      const statusEl = document.getElementById('status');

      const resetBtn = document.getElementById('resetBtn');
      const toggleRealtimeBtn = document.getElementById('toggleRealtimeBtn');
      const randomizeBtn = document.getElementById('randomizeBtn');

      const cols = 12;
      const rows = 8;
      const stocks = [];
      let realtime = true;

      // View transform
      const view = {
        scale: 1,
        tx: 40,
        ty: 40
      };

      let dragging = false;
      let dragStart = { x: 0, y: 0 };
      let viewStart = { tx: 0, ty: 0 };

      let hoveredIndex = -1;
      let lastMouse = { x: 0, y: 0 };

      function resizeCanvas() {
        const dpr = window.devicePixelRatio || 1;
        const rect = viewport.getBoundingClientRect();
        canvas.width = Math.floor(rect.width * dpr);
        canvas.height = Math.floor(rect.height * dpr);
        canvas.style.width = rect.width + 'px';
        canvas.style.height = rect.height + 'px';
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        render();
      }

      function initStocks() {
        stocks.length = 0;
        const symbols = [];
        for (let i = 0; i < cols * rows; i++) {
          symbols.push(`STK${String(i + 1).padStart(3, '0')}`);
        }

        for (let i = 0; i < cols * rows; i++) {
          stocks.push({
            symbol: symbols[i],
            price: 50 + Math.random() * 450,
            prevClose: 50 + Math.random() * 450,
            volume: Math.floor(100000 + Math.random() * 900000),
            changePct: 0
          });
          stocks[i].changePct = pctChange(stocks[i].price, stocks[i].prevClose);
        }
      }

      function pctChange(price, prevClose) {
        return ((price - prevClose) / prevClose) * 100;
      }

      function lerp(a, b, t) {
        return a + (b - a) * t;
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function colorForChange(change) {
        // Map -10% to +10% to red -> yellow -> green
        const t = clamp((change + 10) / 20, 0, 1);
        if (t < 0.5) {
          const u = t / 0.5;
          return {
            r: Math.round(lerp(215, 254, u)),
            g: Math.round(lerp(48, 224, u)),
            b: Math.round(lerp(39, 139, u))
          };
        } else {
          const u = (t - 0.5) / 0.5;
          return {
            r: Math.round(lerp(254, 26, u)),
            g: Math.round(lerp(224, 152, u)),
            b: Math.round(lerp(139, 80, u))
          };
        }
      }

      function rgba({ r, g, b }, a = 1) {
        return `rgba(${r},${g},${b},${a})`;
      }

      function updateData() {
        if (!realtime) return;

        for (const s of stocks) {
          const drift = (Math.random() - 0.5) * 2.5;
          s.price = Math.max(1, s.price + drift);
          s.volume = Math.max(0, s.volume + Math.floor((Math.random() - 0.45) * 5000));
          s.changePct = pctChange(s.price, s.prevClose);
        }

        statusEl.textContent = 'Live';
        render();
      }

      function randomizeData() {
        for (const s of stocks) {
          s.prevClose = 50 + Math.random() * 450;
          s.price = s.prevClose * (0.95 + Math.random() * 0.10);
          s.volume = Math.floor(100000 + Math.random() * 900000);
          s.changePct = pctChange(s.price, s.prevClose);
        }
        render();
      }

      function resetView() {
        view.scale = 1;
        view.tx = 40;
        view.ty = 40;
        render();
      }

      function worldToScreen(x, y) {
        return {
          x: x * view.scale + view.tx,
          y: y * view.scale + view.ty
        };
      }

      function screenToWorld(x, y) {
        return {
          x: (x - view.tx) / view.scale,
          y: (y - view.ty) / view.scale
        };
      }

      function render() {
        const rect = viewport.getBoundingClientRect();
        ctx.clearRect(0, 0, rect.width, rect.height);

        // Background grid
        drawGrid(rect.width, rect.height);

        const cellW = 120;
        const cellH = 90;
        const gap = 10;
        const radius = 12;

        hoveredIndex = -1;

        const mouseWorld = screenToWorld(lastMouse.x, lastMouse.y);

        for (let i = 0; i < stocks.length; i++) {
          const row = Math.floor(i / cols);
          const col = i % cols;

          const x = col * (cellW + gap);
          const y = row * (cellH + gap);

          const screen = worldToScreen(x, y);
          const sw = cellW * view.scale;
          const sh = cellH * view.scale;

          const stock = stocks[i];
          const fill = colorForChange(stock.changePct);

          const isHover = mouseWorld.x >= x && mouseWorld.x <= x + cellW &&
                          mouseWorld.y >= y && mouseWorld.y <= y + cellH;

          if (isHover) hoveredIndex = i;

          // Cell shadow
          ctx.save();
          ctx.shadowColor = 'rgba(0,0,0,0.35)';
          ctx.shadowBlur = 12 * view.scale;
          ctx.shadowOffsetY = 4 * view.scale;

          roundRect(ctx, screen.x, screen.y, sw, sh, radius * view.scale);
          ctx.fillStyle = rgba(fill, 0.92);
          ctx.fill();
          ctx.restore();

          // Border
          ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.12)';
          ctx.lineWidth = isHover ? 2 : 1;
          roundRect(ctx, screen.x, screen.y, sw, sh, radius * view.scale);
          ctx.stroke();

          // Text
          const pad = 12 * view.scale;
          ctx.fillStyle = '#0b1020';
          ctx.font = `${Math.max(10, 13 * view.scale)}px Inter, system-ui, sans-serif`;
          ctx.textBaseline = 'top';

          ctx.fillText(stock.symbol, screen.x + pad, screen.y + pad);

          ctx.font = `${Math.max(11, 15 * view.scale)}px Inter, system-ui, sans-serif`;
          ctx.fillText(`$${stock.price.toFixed(2)}`, screen.x + pad, screen.y + 32 * view.scale);

          ctx.font = `${Math.max(9, 12 * view.scale)}px Inter, system-ui, sans-serif`;
          const changeText = `${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%`;
          ctx.fillText(changeText, screen.x + pad, screen.y + 56 * view.scale);

          // Hover highlight overlay
          if (isHover) {
            ctx.fillStyle = 'rgba(255,255,255,0.10)';
            roundRect(ctx, screen.x, screen.y, sw, sh, radius * view.scale);
            ctx.fill();
          }
        }

        if (hoveredIndex >= 0) {
          showTooltip(stocks[hoveredIndex]);
        } else {
          tooltip.style.display = 'none';
        }
      }

      function drawGrid(width, height) {
        ctx.save();
        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 1;

        const spacing = 40;
        for (let x = 0; x < width; x += spacing) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
          ctx.stroke();
        }
        for (let y = 0; y < height; y += spacing) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();
        }
        ctx.restore();
      }

      function roundRect(ctx, x, y, w, h, r) {
        const radius = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function showTooltip(stock) {
        tooltip.style.display = 'block';
        tooltip.innerHTML = `
          <strong>${stock.symbol}</strong><br/>
          Price: $${stock.price.toFixed(2)}<br/>
          Prev Close: $${stock.prevClose.toFixed(2)}<br/>
          Change: <span style="color:${stock.changePct >= 0 ? '#63e6a5' : '#ff7b7b'}">
            ${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%
          </span><br/>
          Volume: ${stock.volume.toLocaleString()}
        `;

        const rect = viewport.getBoundingClientRect();
        const x = clamp(lastMouse.x + 14, 8, rect.width - 220);
        const y = clamp(lastMouse.y + 14, 8, rect.height - 120);
        tooltip.style.left = x + 'px';
        tooltip.style.top = y + 'px';
      }

      viewport.addEventListener('mousemove', (e) => {
        const rect = viewport.getBoundingClientRect();
        lastMouse.x = e.clientX - rect.left;
        lastMouse.y = e.clientY - rect.top;

        if (dragging) {
          view.tx = viewStart.tx + (lastMouse.x - dragStart.x);
          view.ty = viewStart.ty + (lastMouse.y - dragStart.y);
          render();
        } else {
          render();
        }
      });

      viewport.addEventListener('mousedown', (e) => {
        dragging = true;
        viewport.classList.add('dragging');
        dragStart.x = lastMouse.x;
        dragStart.y = lastMouse.y;
        viewStart.tx = view.tx;
        viewStart.ty = view.ty;
      });

      window.addEventListener('mouseup', () => {
        dragging = false;
        viewport.classList.remove('dragging');
      });

      viewport.addEventListener('wheel', (e) => {
        e.preventDefault();

        const rect = viewport.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        const newScale = clamp(view.scale * zoomFactor, 0.5, 4);

        // Zoom around mouse position
        const worldBefore = screenToWorld(mx, my);
        view.scale = newScale;
        view.tx = mx - worldBefore.x * view.scale;
        view.ty = my - worldBefore.y * view.scale;

        render();
      }, { passive: false });

      viewport.addEventListener('mouseleave', () => {
        tooltip.style.display = 'none';
      });

      resetBtn.addEventListener('click', resetView);

      toggleRealtimeBtn.addEventListener('click', () => {
        realtime = !realtime;
        toggleRealtimeBtn.textContent = realtime ? 'Pause Updates' : 'Resume Updates';
        statusEl.textContent = realtime ? 'Live' : 'Paused';
      });

      randomizeBtn.addEventListener('click', randomizeData);

      window.addEventListener('resize', resizeCanvas);

      // Init
      initStocks();
      resizeCanvas();
      render();

      // Simulated real-time updates
      setInterval(updateData, 1000);
    })();
  </script>
</body>
</html>
