<!-- D3 for zooming and scales -->
<script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
<script>
(() => {
  const svg = d3.select("#svg");
  const stage = document.getElementById("stage");
  const tooltip = document.getElementById("tooltip");
  const resetBtn = document.getElementById("resetBtn");
  const pauseBtn = document.getElementById("pauseBtn");
  const statusChip = document.getElementById("statusChip");

  const rows = 24;
  const cols = 80;
  const symbols = Array.from({ length: rows }, (_, i) => `SYM${String(i + 1).padStart(2, "0")}`);

  let paused = false;

  // Generate synthetic time series data
  const data = symbols.map(symbol => ({
    symbol,
    values: Array.from({ length: cols }, () => randomReturn())
  }));

  function randomReturn() {
    // Simulated percentage return between roughly -4% and +4%
    return (Math.random() - 0.5) * 0.08;
  }

  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function colorForValue(v) {
    // Diverging color scale centered at 0
    const scale = d3.scaleDiverging()
      .domain([-0.04, 0, 0.04])
      .interpolator(d3.interpolateRdYlGn);
    return scale(v);
  }

  const margin = { top: 30, right: 20, bottom: 30, left: 80 };

  const root = svg.append("g").attr("class", "root");
  const gridLayer = root.append("g").attr("class", "grid-layer");
  const labelLayer = root.append("g").attr("class", "label-layer");
  const overlayLayer = root.append("g").attr("class", "overlay-layer");

  let width = 0;
  let height = 0;
  let cellW = 0;
  let cellH = 0;

  const zoom = d3.zoom()
    .scaleExtent([1, 12])
    .on("zoom", (event) => {
      root.attr("transform", event.transform);
    });

  svg.call(zoom);

  function resize() {
    width = stage.clientWidth;
    height = stage.clientHeight;

    svg.attr("viewBox", `0 0 ${width} ${height}`);

    cellW = (width - margin.left - margin.right) / cols;
    cellH = (height - margin.top - margin.bottom) / rows;

    render();
  }

  function render() {
    gridLayer.selectAll("*").remove();
    labelLayer.selectAll("*").remove();
    overlayLayer.selectAll("*").remove();

    // Background grid area
    gridLayer.append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", cols * cellW)
      .attr("height", rows * cellH)
      .attr("fill", "rgba(255,255,255,0.02)")
      .attr("stroke", "rgba(255,255,255,0.08)");

    // Cells
    const rowGroups = gridLayer.selectAll(".row")
      .data(data)
      .join("g")
      .attr("class", "row")
      .attr("transform", (d, r) => `translate(0, ${margin.top + r * cellH})`);

    rowGroups.each(function(rowData, r) {
      const g = d3.select(this);
      g.selectAll("rect.cell")
        .data(rowData.values.map((value, c) => ({ value, c, r, symbol: rowData.symbol })))
        .join("rect")
        .attr("class", "cell cell-border")
        .attr("x", d => margin.left + d.c * cellW)
        .attr("y", 0)
        .attr("width", cellW)
        .attr("height", cellH)
        .attr("fill", d => colorForValue(d.value))
        .on("mousemove", (event, d) => showTooltip(event, d))
        .on("mouseleave", hideTooltip);
    });

    // Axis labels
    labelLayer.selectAll(".row-label")
      .data(symbols)
      .join("text")
      .attr("class", "grid-label")
      .attr("x", margin.left - 8)
      .attr("y", (_, i) => margin.top + i * cellH + cellH * 0.68)
      .attr("text-anchor", "end")
      .text(d => d);

    // Column labels every 5 columns
    const colTicks = d3.range(0, cols, 5);
    labelLayer.selectAll(".col-label")
      .data(colTicks)
      .join("text")
      .attr("class", "grid-label")
      .attr("x", d => margin.left + d * cellW + cellW * 0.5)
      .attr("y", margin.top - 8)
      .attr("text-anchor", "middle")
      .text(d => `T${d + 1}`);

    // Axes lines
    labelLayer.append("line")
      .attr("class", "axis-line")
      .attr("x1", margin.left)
      .attr("y1", margin.top)
      .attr("x2", margin.left + cols * cellW)
      .attr("y2", margin.top);

    labelLayer.append("line")
      .attr("class", "axis-line")
      .attr("x1", margin.left)
      .attr("y1", margin.top)
      .attr("x2", margin.left)
      .attr("y2", margin.top + rows * cellH);
  }

  function showTooltip(event, d) {
    const rect = stage.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    const valPct = (d.value * 100).toFixed(2);
    tooltip.innerHTML = `
      <strong>${d.symbol}</strong><br/>
      Time: ${d.c + 1}<br/>
      Return: <span style="color:${d.value >= 0 ? '#8ef0a8' : '#ff9e9e'}">${valPct}%</span>
    `;

    tooltip.style.left = `${x}px`;
    tooltip.style.top = `${y}px`;
    tooltip.style.opacity = 1;
  }

  function hideTooltip() {
    tooltip.style.opacity = 0;
  }

  function updateRandomCells() {
    if (paused) return;

    // Update a subset of cells each tick to simulate live feed
    const updatesPerTick = 35;
    for (let i = 0; i < updatesPerTick; i++) {
      const r = Math.floor(Math.random() * rows);
      const c = Math.floor(Math.random() * cols);
      data[r].values[c] = clamp(data[r].values[c] + randomReturn() * 0.25, -0.12, 0.12);
    }

    // Re-render only fills
    gridLayer.selectAll("rect.cell")
      .attr("fill", d => colorForValue(data[d.r].values[d.c]));
  }

  // Simulated real-time updates
  setInterval(updateRandomCells, 400);

  resetBtn.addEventListener("click", () => {
    svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
  });

  pauseBtn.addEventListener("click", () => {
    paused = !paused;
    pauseBtn.textContent = paused ? "Resume Feed" : "Pause Feed";
    statusChip.textContent = paused ? "Paused" : "Live";
    statusChip.style.color = paused ? "#ffd37a" : "#97ffb1";
  });

  // Keep tooltip within viewport
  stage.addEventListener("mousemove", (event) => {
    const rect = stage.getBoundingClientRect();
    const tw = tooltip.offsetWidth || 160;
    const th = tooltip.offsetHeight || 60;
    let x = event.clientX - rect.left + 12;
    let y = event.clientY - rect.top + 12;

    if (x + tw > rect.width) x = rect.width - tw - 12;
    if (y + th > rect.height) y = rect.height - th - 12;

    tooltip.style.left = `${x}px`;
    tooltip.style.top = `${y}px`;
  });

  window.addEventListener("resize", resize);

  resize();
})();
</script>
</body>
</html>
