<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Heatmap</h1>

      <div class="group">
        <button id="resetBtn">Reset view</button>
        <button id="shuffleBtn">Shuffle data</button>
        <button id="pauseBtn">Pause updates</button>
      </div>

      <div class="group">
        <label>
          Columns
          <select id="colsSelect">
            <option>4</option>
            <option selected>5</option>
            <option>6</option>
            <option>7</option>
            <option>8</option>
          </select>
        </label>
        <label>
          Cell size
          <input id="sizeRange" type="range" min="60" max="140" value="92" />
        </label>
      </div>

      <div class="group">
        <label>
          Update speed
          <input id="speedRange" type="range" min="250" max="3000" value="900" />
        </label>
      </div>

      <div class="hint">Wheel to zoom • Drag to pan • Double-click to center</div>
    </div>

    <div id="viewport" class="viewport">
      <div id="scene" class="scene">
        <div id="grid" class="grid"></div>
      </div>
      <div id="crosshair" class="crosshair"></div>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="footer">
      <div class="legend">
        <span><span class="swatch" style="background: var(--down)"></span>Down</span>
        <span><span class="swatch" style="background: var(--neutral)"></span>Flat</span>
        <span><span class="swatch" style="background: var(--up)"></span>Up</span>
      </div>
      <div class="status">
        <span><span id="liveDot" class="dot live"></span><span id="liveText">Live</span></span>
        <span id="stats">0 symbols</span>
      </div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const scene = document.getElementById('scene');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const crosshair = document.getElementById('crosshair');
    const stats = document.getElementById('stats');
    const resetBtn = document.getElementById('resetBtn');
    const shuffleBtn = document.getElementById('shuffleBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const colsSelect = document.getElementById('colsSelect');
    const sizeRange = document.getElementById('sizeRange');
    const speedRange = document.getElementById('speedRange');

    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','ORCL',
      'INTC','CRM','ADBE','QCOM','AVGO','CSCO','IBM','UBER','SHOP','SQ',
      'BA','JPM','V','MA','DIS','PYPL','PEP','KO','NKE','XOM',
      'CVX','WMT','TGT','COST','PFE','MRNA','GE','CAT','SPOT','SNOW'
    ];

    let data = [];
    let cols = +colsSelect.value;
    let cellSize = +sizeRange.value;
    let updateInterval = +speedRange.value;
    let paused = false;

    let view = { x: 0, y: 0, scale: 1 };
    let dragging = false;
    let dragStart = { x: 0, y: 0, vx: 0, vy: 0 };
    let hoverTile = null;
    let timer = null;

    function rand(min, max) { return Math.random() * (max - min) + min; }
    function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

    function generateData() {
      data = symbols.map(sym => {
        const price = rand(20, 900);
        const changePct = rand(-8, 8);
        return {
          symbol: sym,
          price,
          changePct,
          prevPrice: price / (1 + changePct / 100)
        };
      });
      render();
    }

    function colorForChange(changePct) {
      const max = 8;
      const t = clamp(Math.abs(changePct) / max, 0, 1);
      const alpha = 0.18 + t * 0.72;
      if (Math.abs(changePct) < 0.15) return `rgba(42,53,86,${0.95})`;

      if (changePct > 0) {
        return `rgba(29,185,84,${alpha})`;
      }
      return `rgba(255,77,79,${alpha})`;
    }

    function textColor(changePct) {
      return Math.abs(changePct) < 0.15 ? '#dbe5ff' : '#ffffff';
    }

    function render() {
      cols = +colsSelect.value;
      cellSize = +sizeRange.value;

      grid.style.gridTemplateColumns = `repeat(${cols}, ${cellSize}px)`;
      grid.innerHTML = '';

      data.forEach((d, i) => {
        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.dataset.index = i;
        tile.style.width = `${cellSize}px`;
        tile.style.height = `${Math.max(64, cellSize * 0.72)}px`;
        tile.style.background = colorForChange(d.changePct);
        tile.style.color = textColor(d.changePct);

        tile.innerHTML = `
          <div class="symbol">${d.symbol}</div>
          <div class="price">$${d.price.toFixed(2)}</div>
          <div class="change">${d.changePct >= 0 ? '+' : ''}${d.changePct.toFixed(2)}%</div>
        `;

        tile.addEventListener('mouseenter', () => {
          hoverTile = tile;
          crosshair.style.display = 'block';
          tooltip.style.display = 'block';
          updateTooltip(tile);
        });

        tile.addEventListener('mouseleave', () => {
          hoverTile = null;
          crosshair.style.display = dragging ? 'block' : 'none';
          tooltip.style.display = 'none';
        });

        grid.appendChild(tile);
      });

      stats.textContent = `${data.length} symbols`;
      applyTransform();
    }

    function applyTransform() {
      scene.style.transform = `translate(${view.x}px, ${view.y}px) scale(${view.scale})`;
    }

    function centerScene() {
      const rect = viewport.getBoundingClientRect();
      const gridRect = grid.getBoundingClientRect();

      const contentW = gridRect.width || (cols * (cellSize + 4) + 24);
      const contentH = gridRect.height || (Math.ceil(data.length / cols) * (Math.max(64, cellSize * 0.72) + 4) + 24);

      view.x = (rect.width - contentW * view.scale) / 2;
      view.y = (rect.height - contentH * view.scale) / 2;
      applyTransform();
    }

    function updateTooltip(tile, clientX, clientY) {
      const i = +tile.dataset.index;
      const d = data[i];
      tooltip.innerHTML = `
        <div class="t1">${d.symbol}</div>
        <div>Price: <strong>$${d.price.toFixed(2)}</strong></div>
        <div>Change: <strong style="color:${d.changePct >= 0 ? '#7CFFB2' : '#FF9A9A'}">
          ${d.changePct >= 0 ? '+' : ''}${d.changePct.toFixed(2)}%
        </strong></div>
        <div class="muted">Real-time simulated update</div>
      `;

      const vp = viewport.getBoundingClientRect();
      const tileRect = tile.getBoundingClientRect();
      const x = clientX ?? (tileRect.right + 10);
      const y = clientY ?? tileRect.top;

      tooltip.style.left = `${clamp(x - vp.left + 14, 8, vp.width - 240)}px`;
      tooltip.style.top = `${clamp(y - vp.top + 14, 8, vp.height - 120)}px`;
    }

    function updateRandomTile() {
      if (!data.length) return;
      const i = Math.floor(Math.random() * data.length);
      const d = data[i];

      const drift = rand(-1.2, 1.2);
      d.prevPrice = d.price;
      d.price = Math.max(1, d.price + drift);

      const pct = ((d.price - d.prevPrice) / d.prevPrice) * 100;
      d.changePct = clamp(d.changePct * 0.72 + pct * 0.28 + rand(-0.15, 0.15), -15, 15);

      const tile = grid.children[i];
      if (tile) {
        tile.style.background = colorForChange(d.changePct);
        tile.style.color = textColor(d.changePct);
        tile.querySelector('.price').textContent = `$${d.price.toFixed(2)}`;
        tile.querySelector('.change').textContent = `${d.changePct >= 0 ? '+' : ''}${d.changePct.toFixed(2)}%`;
        if (hoverTile === tile) updateTooltip(tile);
      }
    }

    function startUpdates() {
      stopUpdates();
      timer = setInterval(() => {
        if (!paused) updateRandomTile();
      }, updateInterval);
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    viewport.addEventListener('pointerdown', (e) => {
      dragging = true;
      viewport.setPointerCapture(e.pointerId);
      dragStart = { x: e.clientX, y: e.clientY, vx: view.x, vy: view.y };
      crosshair.style.display = 'block';
    });

    viewport.addEventListener('pointermove', (e) => {
      if (dragging) {
        view.x = dragStart.vx + (e.clientX - dragStart.x);
        view.y = dragStart.vy + (e.clientY - dragStart.y);
        applyTransform();
      }
      if (hoverTile) updateTooltip(hoverTile, e.clientX, e.clientY);
    });

    viewport.addEventListener('pointerup', () => {
      dragging = false;
      if (!hoverTile) crosshair.style.display = 'none';
    });

    viewport.addEventListener('dblclick', () => {
      centerScene();
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoom = Math.exp(-e.deltaY * 0.0012);
      const nextScale = clamp(view.scale * zoom, 0.4, 3);

      const worldX = (mx - view.x) / view.scale;
      const worldY = (my - view.y) / view.scale;

      view.scale = nextScale;
      view.x = mx - worldX * view.scale;
      view.y = my - worldY * view.scale;

      applyTransform();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      view = { x: 0, y: 0, scale: 1 };
      applyTransform();
      centerScene();
    });

    shuffleBtn.addEventListener('click', () => {
      data.sort(() => Math.random() - 0.5);
      render();
      centerScene();
    });

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume updates' : 'Pause updates';
      document.getElementById('liveDot').classList.toggle('live', !paused);
      document.getElementById('liveText').textContent = paused ? 'Paused' : 'Live';
    });

    colsSelect.addEventListener('change', () => { render(); centerScene(); });
    sizeRange.addEventListener('input', () => { render(); centerScene(); });
    speedRange.addEventListener('input', () => {
      updateInterval = +speedRange.value;
      startUpdates();
    });

    window.addEventListener('resize', centerScene);

    generateData();
    startUpdates();
    requestAnimationFrame(() => setTimeout(centerScene, 0));
  </script>
</body>
</html>
