      border-radius: 999px;
      background: linear-gradient(90deg, var(--red), #2a355a 50%, var(--green));
      border: 1px solid rgba(255,255,255,0.12);
    }

    .viewport {
      position: relative;
      overflow: hidden;
      touch-action: none;
      cursor: grab;
    }
    .viewport.dragging { cursor: grabbing; }

    .heatmap {
      position: absolute;
      left: 0;
      top: 0;
      transform-origin: 0 0;
      will-change: transform;
    }

    .cell {
      position: absolute;
      display: flex;
      flex-direction: column;
      justify-content: center;
      padding: 8px;
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 10px;
      overflow: hidden;
      user-select: none;
      transition: background-color 180ms linear, transform 120ms ease, border-color 120ms ease;
      box-shadow: 0 1px 0 rgba(255,255,255,0.04) inset;
