    .cell:hover {
      transform: scale(1.03);
      border-color: rgba(255,255,255,0.18);
      z-index: 2;
    }

    .ticker {
      font-weight: 700;
      font-size: 14px;
      line-height: 1.1;
    }
    .price, .change {
      font-size: 12px;
      opacity: 0.95;
      line-height: 1.2;
      margin-top: 3px;
    }

    .tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(10, 15, 30, 0.96);
      border: 1px solid rgba(255,255,255,0.12);
      color: var(--text);
      padding: 10px 12px;
      border-radius: 12px;
      font-size: 12px;
      box-shadow: 0 12px 30px rgba(0,0,0,0.35);
      transform: translate(12px, 12px);
      opacity: 0;
      transition: opacity 120ms ease;
      z-index: 100;
      min-width: 180px;
    }
    .tooltip.visible { opacity: 1; }

    .hint {
      position: absolute;
      left: 16px;
      bottom: 16px;
      color: rgba(232,238,252,0.75);
      font-size: 12px;
      background: rgba(17,24,45,0.72);
      border: 1px solid rgba(255,255,255,0.08);
      padding: 8px 10px;
      border-radius: 10px;
      backdrop-filter: blur(8px);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Live Stock Heatmap</h1>
      <button id="resetBtn" class="btn">Reset View</button>
      <button id="pauseBtn" class="btn">Pause Updates</button>
      <select id="symbolCount" class="select">
        <option value="36">36 symbols</option>
        <option value="64" selected>64 symbols</option>
        <option value="100">100 symbols</option>
        <option value="144">144 symbols</option>
      </select>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <div class="spacer"></div>
      <div id="status" class="status">Connecting…</div>
    </div>

    <div id="viewport" class="viewport">
      <div id="heatmap" class="heatmap"></div>
      <div class="hint">Drag to pan • Mouse wheel to zoom • Hover for details</div>
    </div>
  </div>

  <div id="tooltip" class="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const symbolCountSel = document.getElementById('symbolCount');

    let symbols = [];
    let cells = new Map();

    let view = { x: 20, y: 20, scale: 1 };
    let dragging = false;
    let dragStart = { x: 0, y: 0, vx: 0, vy: 0 };
    let paused = false;
    let updateTimer = null;
    let lastUpdateAt = Date.now();

    const palette = (t) => {
      t = Math.max(-1, Math.min(1, t));
      const abs = Math.abs(t);
      const base = t < 0
        ? lerpColor([42, 53, 90], [255, 92, 92], abs)
        : lerpColor([42, 53, 90], [46, 204, 113], abs);
      return `rgb(${base[0]}, ${base[1]}, ${base[2]})`;
    };

    function lerpColor(a, b, t) {
      return [
        Math.round(a[0] + (b[0] - a[0]) * t),
        Math.round(a[1] + (b[1] - a[1]) * t),
        Math.round(a[2] + (b[2] - a[2]) * t)
      ];
    }

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function makeSymbols(n) {
      const prefixes = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P'];
      const out = [];
      for (let i = 0; i < n; i++) {
        const ticker = prefixes[i % prefixes.length] + String.fromCharCode(65 + (i % 26)) + (i >= 26 ? String(Math.floor(i / 26)) : '');
        const price = rand(12, 500);
        const prevClose = price * rand(0.97, 1.03);
        out.push({
          ticker,
          price,
          prevClose,
          changePct: ((price - prevClose) / prevClose) * 100,
          vol: Math.floor(rand(100_000, 15_000_000))
        });
      }
      return out;
    }

    function layoutCells() {
      heatmap.innerHTML = '';
      cells.clear();

      const n = symbols.length;
      const cols = Math.ceil(Math.sqrt(n));
      const rows = Math.ceil(n / cols);
      const cellW = 170;
      const cellH = 110;
      const gap = 10;

      heatmap.style.width = `${cols * (cellW + gap) + gap}px`;
      heatmap.style.height = `${rows * (cellH + gap) + gap}px`;

      symbols.forEach((s, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const el = document.createElement('div');
        el.className = 'cell';
        el.style.left = `${gap + col * (cellW + gap)}px`;
        el.style.top = `${gap + row * (cellH + gap)}px`;
        el.style.width = `${cellW}px`;
        el.style.height = `${cellH}px`;
        el.dataset.ticker = s.ticker;

        el.innerHTML = `
          <div class="ticker">${s.ticker}</div>
          <div class="price">$${s.price.toFixed(2)}</div>
          <div class="change">${formatChange(s.changePct)}</div>
        `;

        el.addEventListener('mouseenter', (e) => showTooltip(e, s));
        el.addEventListener('mousemove', (e) => moveTooltip(e, s));
        el.addEventListener('mouseleave', hideTooltip);

        heatmap.appendChild(el);
        cells.set(s.ticker, el);
      });

      applyView();
      renderAll();
    }

    function formatChange(v) {
      const sign = v >= 0 ? '+' : '';
      return `${sign}${v.toFixed(2)}%`;
    }

    function applyView() {
      heatmap.style.transform = `translate(${view.x}px, ${view.y}px) scale(${view.scale})`;
    }

    function resetView() {
      view = { x: 20, y: 20, scale: 1 };
      applyView();
    }

    function renderAll() {
      symbols.forEach(s => {
        const el = cells.get(s.ticker);
        if (!el) return;
        const change = s.changePct;
        el.style.background = palette(change / 5);
        el.querySelector('.price').textContent = `$${s.price.toFixed(2)}`;
        el.querySelector('.change').textContent = formatChange(change);
        el.querySelector('.change').style.color = change >= 0 ? '#bff3d0' : '#ffb3b3';
      });
      const age = ((Date.now() - lastUpdateAt) / 1000).toFixed(1);
      statusEl.textContent = paused
        ? `Paused • ${symbols.length} symbols`
        : `Live • updated ${age}s ago • ${symbols.length} symbols`;
    }

    function updateSimulation() {
      if (paused) return;

      symbols.forEach(s => {
        const drift = rand(-0.25, 0.25);
        const shock = Math.random() < 0.08 ? rand(-1.4, 1.4) : 0;
        const deltaPct = drift + shock;

        s.price = Math.max(0.5, s.price * (1 + deltaPct / 100));
        s.changePct = ((s.price - s.prevClose) / s.prevClose) * 100;
        s.vol = Math.max(0, Math.floor(s.vol * rand(0.995, 1.01)));
      });

      lastUpdateAt = Date.now();
      renderAll();
    }

    function startUpdates() {
      clearInterval(updateTimer);
      updateTimer = setInterval(updateSimulation, 1000);
    }

    function showTooltip(e, s) {
      tooltip.classList.add('visible');
      tooltip.innerHTML = `
        <strong>${s.ticker}</strong><br/>
        Price: $${s.price.toFixed(2)}<br/>
        Prev Close: $${s.prevClose.toFixed(2)}<br/>
        Change: ${formatChange(s.changePct)}<br/>
        Volume: ${s.vol.toLocaleString()}
      `;
      moveTooltip(e, s);
    }

    function moveTooltip(e) {
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove('visible');
    }

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      dragStart = { x: e.clientX, y: e.clientY, vx: view.x, vy: view.y };
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      view.x = dragStart.vx + (e.clientX - dragStart.x);
      view.y = dragStart.vy + (e.clientY - dragStart.y);
      applyView();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = view.scale;
      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newScale = Math.min(3, Math.max(0.4, oldScale * zoomFactor));

      const worldX = (mx - view.x) / oldScale;
      const worldY = (my - view.y) / oldScale;

      view.scale = newScale;
      view.x = mx - worldX * newScale;
      view.y = my - worldY * newScale;

      applyView();
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume Updates' : 'Pause Updates';
      pauseBtn.classList.toggle('active', paused);
      renderAll();
    });

    symbolCountSel.addEventListener('change', () => {
      symbols = makeSymbols(Number(symbolCountSel.value));
      layoutCells();
      resetView();
    });

    window.addEventListener('resize', () => {
      applyView();
    });

    symbols = makeSymbols(Number(symbolCountSel.value));
    layoutCells();
    startUpdates();
    renderAll();
  </script>
</body>
</html>
```

