    }

    button:hover {
      background: #273556;
    }

    .status {
      color: var(--muted);
      font-size: 13px;
    }

    #chart {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background: linear-gradient(180deg, #0b1220 0%, #08101c 100%);
    }

    .axis text {
      fill: var(--muted);
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: rgba(255,255,255,0.12);
    }

    .cell {
      stroke: rgba(255,255,255,0.08);
      stroke-width: 1;
      shape-rendering: crispEdges;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: white;
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 12px;
      border: 1px solid rgba(255,255,255,0.12);
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      white-space: nowrap;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      color: var(--muted);
      font-size: 12px;
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(90deg, #b91c1c, #f97316, #facc15, #22c55e, #16a34a);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
  <div class="app">
    <header>
      <h1>Interactive Stock Price Heatmap</h1>
      <div class="controls">
        <div class="legend">
          <span>Change %</span>
          <div class="legend-bar"></div>
          <span>Loss → Gain</span>
        </div>
        <button id="toggleLive">Pause Live</button>
        <button id="resetZoom">Reset Zoom</button>
        <div class="status" id="status">Live updates: on</div>
      </div>
    </header>

    <div id="chart">
      <svg id="svg"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = d3.select("#svg");
    const chart = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleLiveBtn = document.getElementById("toggleLive");
    const resetZoomBtn = document.getElementById("resetZoom");

    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "IBM", "QCOM", "ADBE"
    ];

    const timeWindow = 40; // columns shown
    const updateIntervalMs = 1000;

    let live = true;
    let data = [];
    let currentTime = 0;

    // Dimensions
    let width = 0, height = 0;
    let margin = { top: 30, right: 20, bottom: 60, left: 80 };

    const gRoot = svg.append("g").attr("class", "root");
    const gCells = gRoot.append("g").attr("class", "cells");
    const gXAxis = gRoot.append("g").attr("class", "axis x-axis");
    const gYAxis = gRoot.append("g").attr("class", "axis y-axis");

    const color = d3.scaleSequential()
      .domain([-5, 5])
      .interpolator(d3.interpolateRdYlGn);

    const xScale = d3.scaleBand().padding(0.08);
    const yScale = d3.scaleBand().padding(0.08);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [5000, 5000]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function initData() {
      data = [];
      for (const stock of stocks) {
        let prev = 100 + Math.random() * 50;
        for (let t = 0; t < timeWindow; t++) {
          const change = (Math.random() - 0.5) * 2;
          prev = Math.max(1, prev * (1 + change / 100));
          data.push({
            stock,
            t,
            price: prev,
            changePct: change
          });
        }
      }
      currentTime = timeWindow - 1;
    }

    function resize() {
      const rect = chart.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      svg.attr("viewBox", `0 0 ${width} ${height}`);
      render();
    }

    function render() {
      const innerW = width - margin.left - margin.right;
      const innerH = height - margin.top - margin.bottom;

      const visibleTimes = d3.range(Math.max(0, currentTime - timeWindow + 1), currentTime + 1);

      xScale.domain(visibleTimes).range([0, innerW]);
      yScale.domain(stocks).range([0, innerH]);

      gRoot.attr("transform", `translate(${margin.left},${margin.top})`);

      const cells = gCells.selectAll("rect.cell")
        .data(data.filter(d => visibleTimes.includes(d.t)), d => `${d.stock}-${d.t}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 2)
        .attr("ry", 2)
        .merge(cells)
        .attr("x", d => xScale(d.t))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => color(d.changePct))
        .on("mousemove", (event, d) => {
          const [x, y] = d3.pointer(event, chart);
          tooltip.style.opacity = 1;
          tooltip.style.left = `${x}px`;
          tooltip.style.top = `${y}px`;
          tooltip.innerHTML = `
            <strong>${d.stock}</strong><br/>
            Time: ${d.t}<br/>
            Price: $${d.price.toFixed(2)}<br/>
            Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          `;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cells.exit().remove();

      const xAxis = d3.axisBottom(xScale)
        .tickValues(visibleTimes.filter((d, i) => i % 2 === 0))
        .tickFormat(d => `T${d}`);

      const yAxis = d3.axisLeft(yScale).tickSize(0);

      gXAxis
        .attr("transform", `translate(0,${innerH})`)
        .call(xAxis);

      gYAxis.call(yAxis);

      gXAxis.selectAll("text").attr("dy", "1.2em");
      gYAxis.selectAll("text").attr("dx", "-0.4em");
    }

    function addLivePoint() {
      // Shift data window forward by one time step for each stock
      currentTime += 1;

      for (const stock of stocks) {
        const last = data.filter(d => d.stock === stock).slice(-1)[0];
        const base = last ? last.price : 100;
        const change = (Math.random() - 0.5) * 2.5; // -1.25% to +1.25%
        const price = Math.max(1, base * (1 + change / 100));

        data.push({
          stock,
          t: currentTime,
          price,
          changePct: change
        });
      }

      // Keep only needed history
      const minT = currentTime - timeWindow + 1;
      data = data.filter(d => d.t >= minT);

      render();
      statusEl.textContent = `Live updates: ${live ? "on" : "paused"} | T=${currentTime}`;
    }

    function zoomed(event) {
      const transform = event.transform;
      const innerW = width - margin.left - margin.right;
      const innerH = height - margin.top - margin.bottom;

      const zx = transform.rescaleX(xScale.copy().range([0, innerW]));
      const zy = transform.rescaleY(yScale.copy().range([0, innerH]));

      gCells.selectAll("rect.cell")
        .attr("x", d => zx(d.t))
        .attr("y", d => zy(d.stock))
        .attr("width", zx.bandwidth ? zx.bandwidth() : xScale.bandwidth() * transform.k)
        .attr("height", zy.bandwidth ? zy.bandwidth() : yScale.bandwidth() * transform.k);

      gXAxis.call(d3.axisBottom(zx).tickFormat(d => `T${d}`));
      gYAxis.call(d3.axisLeft(zy).tickSize(0));
    }

    toggleLiveBtn.addEventListener("click", () => {
      live = !live;
      toggleLiveBtn.textContent = live ? "Pause Live" : "Resume Live";
      statusEl.textContent = `Live updates: ${live ? "on" : "paused"} | T=${currentTime}`;
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    // Simulated real-time feed
    setInterval(() => {
      if (live) addLivePoint();
    }, updateIntervalMs);

    // Resize handling
    const ro = new ResizeObserver(resize);
    ro.observe(chart);

    initData();
    resize();
  </script>
</body>
</html>
```

---

## How it works
- Each cell represents a stock at a time step.
- The heatmap color is based on `changePct`.
- New live data is appended every second.
- Old data is trimmed to keep the visible window fixed.
- D3 zoom/pan lets you inspect the heatmap interactively.

---

## To connect real market data
Replace the `addLivePoint()` simulation with:
- a **WebSocket** feed from your backend, or
- a `fetch()` call to an API endpoint every few seconds.

Example sketch:

```js
async function fetchLatestData() {
  const res = await fetch("/api/stock-heatmap");
  const latest = await res.json();
  data = latest;
  render();
}
```

