    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(90deg, var(--down), #3b4a7a 48%, var(--up));
      border: 1px solid rgba(255,255,255,0.12);
    }

    .statusbar {
      justify-content: space-between;
      font-size: 13px;
      color: var(--muted);
    }

    .pill {
      padding: 6px 10px;
