      color: var(--muted);
    }
  </style>
</head>
<body>
<div class="app">
  <div class="topbar">
    <div class="brand">
      <div class="dot"></div>
      <div>Stock Heatmap</div>
    </div>
    <div class="controls">
      <button id="resetBtn">Reset View</button>
      <button id="pauseBtn">Pause Updates</button>
      <select id="sectorSelect">
        <option value="all">All Sectors</option>
        <option value="tech">Technology</option>
        <option value="finance">Financials</option>
        <option value="health">Healthcare</option>
        <option value="energy">Energy</option>
        <option value="consumer">Consumer</option>
      </select>
      <input id="searchInput" type="search" placeholder="Search ticker..." />
    </div>
  </div>

  <div class="toolbar">
    <div class="legend">
      <span>Performance</span>
      <div class="legend-bar"></div>
      <span>-10%</span>
      <span>0%</span>
      <span>+10%</span>
    </div>
    <div class="hint">Mouse wheel / trackpad to zoom, drag to pan, click a tile for details.</div>
  </div>

  <div class="workspace">
    <canvas id="heatmap"></canvas>
  </div>

  <div class="statusbar">
    <div class="pill" id="statusLeft">Ready</div>
    <div class="pill" id="statusCenter">Zoom: 100%</div>
    <div class="pill" id="statusRight">Updates: live</div>
  </div>
</div>

<script>
(() => {
  const canvas = document.getElementById('heatmap');
  const ctx = canvas.getContext('2d');
  const resetBtn = document.getElementById('resetBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const sectorSelect = document.getElementById('sectorSelect');
  const searchInput = document.getElementById('searchInput');
  const statusLeft = document.getElementById('statusLeft');
  const statusCenter = document.getElementById('statusCenter');
  const statusRight = document.getElementById('statusRight');

  const sectors = {
    tech: ['AAPL','MSFT','NVDA','AMD','ORCL','CRM','ADBE','INTC','QCOM','AVGO','NOW','SNOW'],
    finance: ['JPM','BAC','WFC','GS','MS','C','AXP','BLK','SCHW','USB','PNC','TFC'],
    health: ['LLY','JNJ','PFE','MRK','UNH','ABBV','TMO','DHR','AMGN','BMY','GILD','ISRG'],
    energy: ['XOM','CVX','COP','SLB','EOG','OXY','PSX','MPC','KMI','VLO','HAL','BKR'],
    consumer: ['AMZN','WMT','COST','HD','NKE','MCD','SBUX','TGT','LOW','PG','KO','PEP']
  };

  let items = [];
  let zoom = 1;
  let panX = 0;
  let panY = 0;
  let isDragging = false;
  let dragStart = {x:0, y:0, panX:0, panY:0};
  let paused = false;
  let hovered = null;
  let selected = null;
  let dpr = window.devicePixelRatio || 1;
  let lastTick = performance.now();

  function rand(min, max) { return Math.random() * (max - min) + min; }
  function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

  function buildItems() {
    items = [];
    const sectorNames = Object.keys(sectors);
    for (const sector of sectorNames) {
      for (const ticker of sectors[sector]) {
        const price = rand(20, 900);
        const change = rand(-8, 8);
        items.push({
          ticker,
          sector,
          price,
          prevPrice: price,
          change,
          volume: Math.floor(rand(1e6, 2e7)),
          x: 0, y: 0, w: 0, h: 0
        });
      }
    }
  }

  function filteredItems() {
    const sector = sectorSelect.value;
    const q = searchInput.value.trim().toUpperCase();
    return items.filter(it => (sector === 'all' || it.sector === sector) && (!q || it.ticker.includes(q)));
  }

  function colorForChange(change) {
    const t = clamp((change + 10) / 20, 0, 1);
    const r1 = [234,57,67], r2 = [42,53,88], r3 = [22,199,132];
    let a, b, u;
    if (t < 0.5) {
      a = r1; b = r2; u = t / 0.5;
    } else {
      a = r2; b = r3; u = (t - 0.5) / 0.5;
    }
    const rgb = a.map((v,i) => Math.round(v + (b[i]-v)*u));
    return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
  }

  function resize() {
    dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(canvas.clientWidth * dpr);
    canvas.height = Math.floor(canvas.clientHeight * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }

  function layout() {
    const list = filteredItems();
    const pad = 16;
    const gap = 10;
    const vw = canvas.clientWidth;
    const vh = canvas.clientHeight;

    const cols = Math.max(2, Math.floor(Math.sqrt(list.length * vw / vh)));
    const rows = Math.ceil(list.length / cols);
    const cellW = (vw - pad * 2 - gap * (cols - 1)) / cols;
    const cellH = (vh - pad * 2 - gap * (rows - 1)) / rows;

    list.forEach((it, idx) => {
      const c = idx % cols;
      const r = Math.floor(idx / cols);
      it.x = pad + c * (cellW + gap);
      it.y = pad + r * (cellH + gap);
      it.w = cellW;
      it.h = cellH;
    });

    return list;
  }

  function worldToScreen(x, y) {
    const cx = canvas.clientWidth / 2;
    const cy = canvas.clientHeight / 2;
    return {
      x: (x - panX) * zoom + cx,
      y: (y - panY) * zoom + cy
    };
  }

  function screenToWorld(x, y) {
    const cx = canvas.clientWidth / 2;
    const cy = canvas.clientHeight / 2;
    return {
      x: (x - cx) / zoom + panX,
      y: (y - cy) / zoom + panY
    };
  }

  function hitTest(mx, my, list) {
    const w = screenToWorld(mx, my);
    for (let i = list.length - 1; i >= 0; i--) {
      const it = list[i];
      if (w.x >= it.x && w.x <= it.x + it.w && w.y >= it.y && w.y <= it.y + it.h) return it;
    }
    return null;
  }

  function drawGrid() {
    const step = 80 * zoom;
    if (step < 24) return;
    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;
    const cx = canvas.clientWidth / 2;
    const cy = canvas.clientHeight / 2;
    const startX = ((-panX * zoom + cx) % step + step) % step;
    const startY = ((-panY * zoom + cy) % step + step) % step;

    for (let x = startX; x < canvas.clientWidth; x += step) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvas.clientHeight);
      ctx.stroke();
    }
    for (let y = startY; y < canvas.clientHeight; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.clientWidth, y);
      ctx.stroke();
    }
    ctx.restore();
  }

  function draw() {
    const list = layout();
    ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);

    drawGrid();

    ctx.save();
    ctx.translate(canvas.clientWidth / 2, canvas.clientHeight / 2);
    ctx.scale(zoom, zoom);
    ctx.translate(-panX, -panY);

    for (const it of list) {
      const isHover = hovered === it;
      const isSel = selected === it;
      const fill = colorForChange(it.change);

      ctx.fillStyle = fill;
      ctx.strokeStyle = isSel ? '#ffffff' : isHover ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.12)';
      ctx.lineWidth = isSel ? 3 / zoom : 1 / zoom;

      roundRect(ctx, it.x, it.y, it.w, it.h, 14);
      ctx.fill();
      ctx.stroke();

      const pad = Math.max(10, Math.min(18, it.w * 0.08));
      ctx.save();
      ctx.beginPath();
      roundRect(ctx, it.x + 1, it.y + 1, it.w - 2, it.h - 2, 13);
      ctx.clip();

      ctx.fillStyle = 'rgba(255,255,255,0.95)';
      ctx.font = `700 ${Math.max(12, Math.min(22, it.w * 0.14))}px Inter, sans-serif`;
      ctx.fillText(it.ticker, it.x + pad, it.y + pad + 16);

      ctx.fillStyle = 'rgba(255,255,255,0.88)';
      ctx.font = `600 ${Math.max(10, Math.min(16, it.w * 0.09))}px Inter, sans-serif`;
      ctx.fillText(`$${it.price.toFixed(2)}`, it.x + pad, it.y + pad + 40);

      const ch = `${it.change >= 0 ? '+' : ''}${it.change.toFixed(2)}%`;
      ctx.fillStyle = it.change >= 0 ? '#bff5de' : '#ffd0d3';
      ctx.fillText(ch, it.x + pad, it.y + pad + 62);

      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.font = `500 ${Math.max(9, Math.min(13, it.w * 0.07))}px Inter, sans-serif`;
      ctx.fillText(it.sector.toUpperCase(), it.x + pad, it.y + it.h - pad);

      ctx.restore();
    }
    ctx.restore();

    if (hovered) {
      statusLeft.textContent = `${hovered.ticker} • ${hovered.sector} • $${hovered.price.toFixed(2)} • ${hovered.change >= 0 ? '+' : ''}${hovered.change.toFixed(2)}%`;
    } else {
      statusLeft.textContent = 'Ready';
    }
    statusCenter.textContent = `Zoom: ${Math.round(zoom * 100)}%`;
    statusRight.textContent = paused ? 'Updates: paused' : 'Updates: live';
  }

  function roundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function animatePrices() {
    if (!paused) {
      for (const it of items) {
        const delta = rand(-0.8, 0.8);
        it.prevPrice = it.price;
        it.price = Math.max(1, it.price + delta);
        it.change = clamp(it.change * 0.92 + rand(-0.6, 0.6), -12, 12);
        it.volume = Math.max(0, Math.floor(it.volume + rand(-50000, 50000)));
      }
      draw();
    }
  }

  canvas.addEventListener('pointerdown', (e) => {
    canvas.setPointerCapture(e.pointerId);
    isDragging = true;
    canvas.classList.add('dragging');
    dragStart = { x: e.clientX, y: e.clientY, panX, panY };
  });

  canvas.addEventListener('pointermove', (e) => {
    const list = layout();
    hovered = hitTest(e.clientX, e.clientY, list);

    if (isDragging) {
      const dx = (e.clientX - dragStart.x) / zoom;
      const dy = (e.clientY - dragStart.y) / zoom;
      panX = dragStart.panX - dx;
      panY = dragStart.panY - dy;
      draw();
    } else {
      draw();
    }
  });

  canvas.addEventListener('pointerup', (e) => {
    isDragging = false;
    canvas.classList.remove('dragging');
    const list = layout();
    const hit = hitTest(e.clientX, e.clientY, list);
    if (hit) {
      selected = hit;
      draw();
    }
  });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const mouse = { x: e.clientX, y: e.clientY };
    const before = screenToWorld(mouse.x, mouse.y);
    const factor = Math.exp(-e.deltaY * 0.0012);
    zoom = clamp(zoom * factor, 0.4, 4);
    const after = screenToWorld(mouse.x, mouse.y);
    panX += before.x - after.x;
    panY += before.y - after.y;
    draw();
  }, { passive: false });

  resetBtn.addEventListener('click', () => {
    zoom = 1;
    panX = 0;
    panY = 0;
    selected = null;
    hovered = null;
    draw();
  });

  pauseBtn.addEventListener('click', () => {
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume Updates' : 'Pause Updates';
    draw();
  });

  sectorSelect.addEventListener('change', () => {
    selected = null;
    hovered = null;
    panX = 0;
    panY = 0;
    zoom = 1;
    draw();
  });

  searchInput.addEventListener('input', () => {
    selected = null;
    hovered = null;
    draw();
  });

  window.addEventListener('resize', resize);

  buildItems();
  resize();
  draw();

  setInterval(animatePrices, 1000);

  // Smooth redraw loop for hover/interaction state
  function raf() {
    const now = performance.now();
    if (now - lastTick > 16) {
      lastTick = now;
      draw();
    }
    requestAnimationFrame(raf);
  }
  raf();
})();
</script>
</body>
</html>
