<body>
  <div class="app">
    <div class="header">
      <div class="title">
        <h1>Stock Price Heatmap</h1>
        <p>Drag to pan · Scroll to zoom · Hover for details · Updates every second</p>
      </div>
      <div class="controls">
        <div class="legend">
          <span>Loss</span>
          <div class="legend-bar"></div>
          <span>Gain</span>
        </div>
        <button id="resetBtn">Reset View</button>
      </div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");

    const state = {
      width: 0,
      height: 0,
      cols: 8,
      rows: 5,
      cellGap: 12,
      data: [],
      transform: d3.zoomIdentity
    };

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "JPM","BAC","WMT","COST","DIS","ORCL","AMD","INTC",
      "IBM","ADBE","CRM","PYPL","QCOM","AVGO","TXN","CSCO",
      "XOM","CVX","PFE","JNJ","UNH","HD","NKE","MCD",
      "SPY","QQQ","DIA","IWM","BA","GE","CAT","MMM"
    ];

    function randomStock(symbol) {
      const base = 50 + Math.random() * 450;
      const change = (Math.random() - 0.5) * 8; // -4% to +4%
      return {
        symbol,
        price: base,
        prevClose: base / (1 + change / 100),
        changePct: change,
        volume: Math.floor(1e6 + Math.random() * 50e6)
      };
    }

    function initData() {
      state.data = symbols.map(randomStock);
    }

    function updateData() {
      state.data = state.data.map(d => {
        const drift = (Math.random() - 0.5) * 0.8;
        const newChange = Math.max(-12, Math.min(12, d.changePct + drift));
        const price = d.prevClose * (1 + newChange / 100);
        return {
          ...d,
          price,
          changePct: newChange,
          volume: Math.max(100000, d.volume + Math.floor((Math.random() - 0.5) * 500000))
        };
      });
      render();
    }

    function colorScale(v) {
      const scale = d3.scaleLinear()
        .domain([-12, -4, 0, 4, 12])
        .range(["#8b0000", "#d73027", "#2a2f45", "#66bd63", "#006837"])
        .clamp(true);
      return scale(v);
    }

    function resize() {
      state.width = wrap.clientWidth;
      state.height = wrap.clientHeight;
      svg.attr("viewBox", `0 0 ${state.width} ${state.height}`);
      render();
    }

    function computeLayout() {
      const padding = 24;
      const usableW = state.width - padding * 2;
      const usableH = state.height - padding * 2;
      const cellW = (usableW - (state.cols - 1) * state.cellGap) / state.cols;
      const cellH = (usableH - (state.rows - 1) * state.cellGap) / state.rows;
      return { padding, cellW, cellH };
    }

    function render() {
      if (!state.width || !state.height || !state.data.length) return;

      const { padding, cellW, cellH } = computeLayout();

      const root = svg.selectAll("g.root").data([null]);
      const rootEnter = root.enter().append("g").attr("class", "root");
      const g = rootEnter.merge(root);

      const cells = g.selectAll("g.cell")
        .data(state.data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell")
        .style("cursor", "pointer")
        .on("mouseenter", (event, d) => {
          tooltip.style.opacity = 1;
          d3.select(event.currentTarget).select("rect")
            .attr("stroke", "rgba(255,255,255,0.35)")
            .attr("stroke-width", 2);
          showTooltip(event, d);
        })
        .on("mousemove", (event, d) => showTooltip(event, d))
        .on("mouseleave", (event) => {
          tooltip.style.opacity = 0;
          d3.select(event.currentTarget).select("rect")
            .attr("stroke", "rgba(255,255,255,0.12)")
            .attr("stroke-width", 1);
        });

      cellsEnter.append("rect");
      cellsEnter.append("text").attr("class", "symbol").attr("y", -6);
      cellsEnter.append("text").attr("class", "change").attr("y", 12);

      const merged = cellsEnter.merge(cells);

      merged.transition().duration(300)
        .attr("transform", (d, i) => {
          const col = i % state.cols;
          const row = Math.floor(i / state.cols);
          const x = padding + col * (cellW + state.cellGap);
          const y = padding + row * (cellH + state.cellGap);
          return `translate(${x},${y})`;
        });

      merged.select("rect")
        .transition().duration(300)
        .attr("width", cellW)
        .attr("height", cellH)
        .attr("fill", d => colorScale(d.changePct));

      merged.select("text.symbol")
        .text(d => d.symbol)
        .attr("x", cellW / 2)
        .attr("y", cellH / 2 - 8)
        .style("font-size", `${Math.max(11, Math.min(16, cellW / 6))}px`);

      merged.select("text.change")
        .text(d => `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`)
        .attr("x", cellW / 2)
        .attr("y", cellH / 2 + 12)
        .style("font-size", `${Math.max(10, Math.min(13, cellW / 8))}px`);

      cells.exit().remove();

      g.attr("transform", state.transform);
    }

    function showTooltip(event, d) {
      const rect = wrap.getBoundingClientRect();
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br/>
        Price: $${d.price.toFixed(2)}<br/>
        Change: <span style="color:${d.changePct >= 0 ? '#7CFC98' : '#FF7B7B'}">
          ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
        </span><br/>
        Volume: ${d.volume.toLocaleString()}
      `;
      tooltip.style.left = `${event.clientX - rect.left}px`;
      tooltip.style.top = `${event.clientY - rect.top}px`;
    }

    const zoom = d3.zoom()
      .scaleExtent([0.7, 4])
      .on("zoom", (event) => {
        state.transform = event.transform;
        svg.select("g.root").attr("transform", state.transform);
      });

    svg.call(zoom);

    resetBtn.addEventListener("click", () => {
      svg.transition().duration(350).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    initData();
    resize();
    render();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
