const ws = new WebSocket("wss://your-feed.example.com");

ws.onmessage = (event) => {
  const updates = JSON.parse(event.data);
  // updates = [{ symbol, price, changePct, volume }, ...]
  state.data = state.data.map(stock => {
    const u = updates.find(x => x.symbol === stock.symbol);
    return u ? { ...stock, ...u } : stock;
  });
  render();
};
