  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    let width = 0, height = 0;

    // Example stocks and sectors
    const sectors = ["Tech", "Finance", "Healthcare", "Energy", "Consumer", "Industrials"];
    const symbols = [
      "AAPL","MSFT","NVDA","GOOGL","AMZN","META",
      "JPM","BAC","GS","WFC","C","MS",
      "PFE","JNJ","UNH","MRK","LLY","ABBV",
      "XOM","CVX","COP","SLB","EOG","PSX",
      "WMT","COST","TGT","HD","MCD","SBUX",
      "CAT","BA","GE","HON","UPS","DE"
    ];

    const data = symbols.map((symbol, i) => ({
      symbol,
      sector: sectors[Math.floor(i / 6)],
      price: 50 + Math.random() * 300,
      change: (Math.random() - 0.5) * 8, // percent change
      volume: Math.floor(1e6 + Math.random() * 5e6)
    }));

    let selectedSymbol = null;

    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#ef4444", "#111827", "#22c55e"])
      .clamp(true);

    const formatPct = d3.format("+.2f");
    const formatPrice = d3.format("$.2f");
    const formatVol = d3.format(",");

    const root = svg.append("g").attr("class", "root");
    const cellsG = root.append("g").attr("class", "cells");
    const labelsG = root.append("g").attr("class", "labels");

    const zoom = d3.zoom()
      .scaleExtent([0.8, 10])
      .on("zoom", (event) => {
        root.attr("transform", event.transform);
      });

    svg.call(zoom);

    function resize() {
      width = wrap.clientWidth;
      height = wrap.clientHeight;
      svg.attr("viewBox", `0 0 ${width} ${height}`);
      render();
    }

    function layoutCells() {
      const cols = Math.ceil(Math.sqrt(data.length));
      const rows = Math.ceil(data.length / cols);

      const cellW = Math.max(90, (width - margin.left - margin.right) / cols);
      const cellH = Math.max(70, (height - margin.top - margin.bottom) / rows);

      return { cols, rows, cellW, cellH };
    }

    function render() {
      if (!width || !height) return;

      const { cols, cellW, cellH } = layoutCells();

      const cells = cellsG.selectAll("rect")
        .data(data, d => d.symbol);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 10)
          .attr("ry", 10)
          .attr("x", (d, i) => margin.left + (i % cols) * cellW)
          .attr("y", (d, i) => margin.top + Math.floor(i / cols) * cellH)
          .attr("width", cellW - 8)
          .attr("height", cellH - 8)
          .attr("fill", d => color(d.change))
          .on("mousemove", (event, d) => showTooltip(event, d))
          .on("mouseleave", hideTooltip)
          .on("click", (event, d) => {
            selectedSymbol = d.symbol;
            render();
            event.stopPropagation();
          }),
        update => update
          .attr("x", (d, i) => margin.left + (i % cols) * cellW)
          .attr("y", (d, i) => margin.top + Math.floor(i / cols) * cellH)
          .attr("width", cellW - 8)
          .attr("height", cellH - 8)
          .attr("fill", d => color(d.change)),
        exit => exit.remove()
      )
      .classed("selected", d => d.symbol === selectedSymbol);

      const labels = labelsG.selectAll("g")
        .data(data, d => d.symbol);

      const labelEnter = labels.enter().append("g");

      labelEnter.append("text")
        .attr("class", "label")
        .attr("text-anchor", "start")
        .attr("x", 14)
        .attr("y", 24)
        .text(d => d.symbol);

      labelEnter.append("text")
        .attr("class", "subLabel")
        .attr("text-anchor", "start")
        .attr("x", 14)
        .attr("y", 42)
        .text(d => `${formatPct(d.change)}%`);

      labelEnter.merge(labels)
        .attr("transform", (d, i) => {
          const x = margin.left + (i % cols) * cellW;
          const y = margin.top + Math.floor(i / cols) * cellH;
          return `translate(${x}, ${y})`;
        });

      labels.select(".label").text(d => d.symbol);
      labels.select(".subLabel").text(d => `${formatPct(d.change)}%`);

      labels.exit().remove();
    }

    function showTooltip(event, d) {
      tooltip.innerHTML = `
        <div class="sym">${d.symbol}</div>
        <div>Sector: ${d.sector}</div>
        <div>Price: ${formatPrice(d.price)}</div>
        <div>Change: ${formatPct(d.change)}%</div>
        <div>Volume: ${formatVol(d.volume)}</div>
      `;
      tooltip.style.left = `${event.offsetX}px`;
      tooltip.style.top = `${event.offsetY}px`;
      tooltip.style.opacity = 1;
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    function updateLiveData() {
      data.forEach(d => {
        const drift = (Math.random() - 0.5) * 0.8;
        d.change = Math.max(-10, Math.min(10, d.change + drift));
        d.price = Math.max(1, d.price * (1 + d.change / 1000));
        d.volume = Math.max(1000, d.volume + Math.floor((Math.random() - 0.5) * 100000));
      });

      statusEl.textContent = `Live • ${new Date().toLocaleTimeString()}`;
      render();
    }

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    svg.on("click", () => {
      selectedSymbol = null;
      render();
    });

    window.addEventListener("resize", resize);

    resize();
    render();

    // Simulated real-time updates
    setInterval(updateLiveData, 1000);
  </script>
</body>
</html>
