  <script>
    const viewport = document.getElementById('viewport');
    const world = document.getElementById('world');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const toggleBtn = document.getElementById('toggleUpdates');
    const resetBtn = document.getElementById('resetView');

    const rows = 12;
    const cols = 18;

    const stocks = [];
    const cellEls = new Map();

    let updatesEnabled = true;

    let view = {
      scale: 1,
      x: 40,
      y: 40
    };

    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let viewStart = { x: 0, y: 0 };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatChange(v) {
      const sign = v >= 0 ? '+' : '';
      return `${sign}${v.toFixed(2)}%`;
    }

    function colorForChange(change) {
      // change in percent, roughly from -8 to +8
      const min = -8, max = 8;
      const t = clamp((change - min) / (max - min), 0, 1);

      // interpolate between red -> dark neutral -> green
      const red = [214, 69, 69];
      const mid = [45, 51, 79];
      const green = [46, 204, 113];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = mid; localT = t / 0.5;
      } else {
        c1 = mid; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, i) => Math.round(v + (c2[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function createData() {
      const tickers = [
        'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','INTC','NFLX',
        'ORCL','CRM','UBER','SHOP','SQ','BA','JPM','XOM','COST','DIS',
        'NKE','PFE','KO','PEP','WMT','V','MA','PYPL','ADBE','QCOM',
        'CSCO','AVGO','TXN','IBM','GE','HON','CAT','TMO','LLY','MRK',
        'ABNB','BKNG','SBUX','MCD','NOW','SNOW','PANW','ZS','PLTR','ROKU',
        'F','GM','NIO','RIVN','SPOT','DOCU','ZM','DASH','LYFT','SHOP2',
        'TM','SONY','SAP','ASML','UBS','HSBC','BABA','TCEHY','BIDU','JD',
        'T','VZ','CMCSA','TGT','LOW','HD','EL','CL','KHC','MNST',
        'DE','LMT','RTX','NOC','GD','CVX','BP','SHEL','RIO','BHP',
        'SQ2','CRWD','DDOG','NET','OKTA','TEAM','MDB','WDAY','ANET','MU',
        'AMAT','LRCX','KLAC','NXPI','ADI','MRVL','ARM','SMCI','HPE','DELL'
      ];

      const data = [];
      for (let i = 0; i < rows * cols; i++) {
        const base = rand(20, 900);
        const change = rand(-6, 6);
        data.push({
          ticker: tickers[i % tickers.length] + (i >= tickers.length ? `.${Math.floor(i / tickers.length)}` : ''),
          price: base,
          prevClose: base / (1 + change / 100),
          change
        });
      }
      return data;
    }

    function buildGrid() {
      grid.style.gridTemplateColumns = `repeat(${cols}, 92px)`;
      stocks.forEach((s, idx) => {
        const cell = document.createElement('button');
        cell.className = 'cell';
        cell.type = 'button';
        cell.dataset.index = idx;

        const ticker = document.createElement('div');
        ticker.className = 'ticker';

        const price = document.createElement('div');
        price.className = 'price';

        const change = document.createElement('div');
        change.className = 'change';

        cell.appendChild(ticker);
        cell.appendChild(price);
        cell.appendChild(change);

        cell.addEventListener('mouseenter', (e) => showTooltip(e, s));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);
        cell.addEventListener('click', () => {
          alert(
            `${s.ticker}\n` +
            `Price: ${formatPrice(s.price)}\n` +
            `Change: ${formatChange(s.change)}`
          );
        });

        grid.appendChild(cell);
        cellEls.set(idx, { cell, ticker, price, change });
      });

      updateGrid();
    }

    function updateGrid() {
      stocks.forEach((s, idx) => {
        const el = cellEls.get(idx);
        const bg = colorForChange(s.change);
        el.cell.style.background = bg;

        // Improve contrast based on brightness
        const isDark = s.change > -1 && s.change < 1;
        el.cell.style.color = isDark ? '#f3f6ff' : 'white';

        el.ticker.textContent = s.ticker;
        el.price.textContent = formatPrice(s.price);
        el.change.textContent = formatChange(s.change);
      });
    }

    function simulateRealTimeUpdate() {
      if (!updatesEnabled) return;

      // Update a subset each tick
      const count = Math.max(6, Math.floor(stocks.length * 0.12));
      for (let i = 0; i < count; i++) {
        const idx = Math.floor(Math.random() * stocks.length);
        const s = stocks[idx];

        // random walk
        const deltaPct = rand(-1.4, 1.4);
        s.change = clamp(s.change + deltaPct * 0.35, -10, 10);
        s.price = Math.max(0.5, s.price * (1 + deltaPct / 100));
      }

      updateGrid();
      statusEl.textContent = `Live updates: on • ${new Date().toLocaleTimeString()}`;
    }

    function applyView() {
      world.style.transform = `translate(${view.x}px, ${view.y}px) scale(${view.scale})`;
    }

    function resetView() {
      view = { scale: 1, x: 40, y: 40 };
      applyView();
    }

    function zoomAt(clientX, clientY, delta) {
      const rect = viewport.getBoundingClientRect();
      const mx = clientX - rect.left;
      const my = clientY - rect.top;

      const oldScale = view.scale;
      const zoomFactor = delta > 0 ? 0.9 : 1.1;
      const newScale = clamp(oldScale * zoomFactor, 0.5, 3);

      // Keep point under cursor stable
      const worldX = (mx - view.x) / oldScale;
      const worldY = (my - view.y) / oldScale;

      view.scale = newScale;
      view.x = mx - worldX * newScale;
      view.y = my - worldY * newScale;

      applyView();
    }

    function showTooltip(e, s) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <div class="name">${s.ticker}</div>
        <div>Price: <strong>${formatPrice(s.price)}</strong></div>
        <div>Change: <strong style="color:${s.change >= 0 ? '#53e08a' : '#ff7b7b'}">${formatChange(s.change)}</strong></div>
        <div class="muted">Prev close: ${formatPrice(s.prevClose)}</div>
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const pad = 16;
      const tw = tooltip.offsetWidth || 200;
      const th = tooltip.offsetHeight || 100;
      let x = e.clientX + 14;
      let y = e.clientY + 14;

      if (x + tw + pad > window.innerWidth) x = e.clientX - tw - 14;
      if (y + th + pad > window.innerHeight) y = e.clientY - th - 14;

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      dragStart = { x: e.clientX, y: e.clientY };
      viewStart = { x: view.x, y: view.y };
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      view.x = viewStart.x + (e.clientX - dragStart.x);
      view.y = viewStart.y + (e.clientY - dragStart.y);
      applyView();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      zoomAt(e.clientX, e.clientY, e.deltaY);
    }, { passive: false });

    toggleBtn.addEventListener('click', () => {
      updatesEnabled = !updatesEnabled;
      toggleBtn.textContent = updatesEnabled ? 'Pause updates' : 'Resume updates';
      statusEl.textContent = updatesEnabled ? 'Live updates: on' : 'Live updates: paused';
    });

    resetBtn.addEventListener('click', resetView);

    // Init
    stocks.push(...createData());
    buildGrid();
    applyView();

    // Real-time updates
    setInterval(simulateRealTimeUpdate, 900);

    // Optional: resize-aware centering
    window.addEventListener('resize', () => {
      if (view.scale === 1 && view.x === 40 && view.y === 40) applyView();
    });
  </script>
</body>
</html>
```

---

### How it works

- **Heatmap cells** represent stocks.
- Each cell color is based on percentage change:
  - red = negative
  - neutral = flat
  - green = positive
- **Real-time updates** are simulated with `setInterval`.
- **Zoom** uses the mouse wheel and keeps the cursor-centered point stable.
- **Pan** works by dragging the viewport.
- **Tooltip** shows stock details on hover.

