  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetBtn">Reset View</button>
      <button id="pauseBtn">Pause Updates</button>
      <button id="randomizeBtn">Randomize Prices</button>
      <div class="status" id="status">Live updates: ON</div>
    </div>

    <div class="viewport" id="viewport">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="legend">
      <span>Daily % change</span>
      <div class="swatch"></div>
      <span>-10%</span>
      <span style="margin-left:auto;">0%</span>
      <span>+10%</span>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const resetBtn = document.getElementById("resetBtn");
    const pauseBtn = document.getElementById("pauseBtn");
    const randomizeBtn = document.getElementById("randomizeBtn");

    let dpr = window.devicePixelRatio || 1;
    let width = 0, height = 0;

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let offsetStart = { x: 0, y: 0 };

    let paused = false;

    // Heatmap data
    const rows = 12;
    const cols = 18;
    const stocks = [];

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
      "CRM","ORCL","ADBE","PYPL","QCOM","AVGO","UBER","SHOP","SQ","SNOW",
      "BABA","DIS","PEP","KO","MCD","COST","WMT","JNJ","PFE","MRK",
      "XOM","CVX","BA","GE","CAT","NKE","SPOT","UBS","V","MA",
      "T","VZ","TMUS","IBM","CSCO","HPQ","DELL","SONY","SONO","RBLX",
      "PANW","CRWD","ZS","OKTA","DDOG","NET","DOCU","TEAM","NOW","INTU",
      "SBUX","BKNG","ABNB","LYFT","DAL","UAL","AAL","JPM","BAC","WFC",
      "GS","MS","AXP","BLK","SCHW","TGT","HD","LOW","F","GM",
      "LULU","ROKU","PINS","SNAP","TWLO","SQM","RIO","BHP","NIO","XPEV",
      "PLTR","SOFI","HOOD","C","ET","K","DHR","LLY","UNH","AMAT",
      "MU","KLAC","LRCX","ASML","TSM","ARM","SMCI","WDC","STX","MRNA",
      "GILD","BIIB","REGN","BMY","AZN","SHEL","BP","COP","SLB","OXY",
      "DE","MMM","RTX","LMT","HON","UPS","FDX","PGR","ALL","TRV",
      "AON","CB","MMC","ICE","CME","SPGI","NDAQ","RELX","WBA","CVS",
      "EL","NOC","TMO","ISRG","VRTX","DXCM","ZTS","SHW","EOG","PSX",
      "FIS","FICO","PAYX","ADP","MELI","SE","PDD","JD","NTES","EA",
      "TTD","RIVN","LCID","XOM","CVX","WBD","PARA","HUM","CI","UNP",
      "NSC","CSX","KHC","CL","GIS","MDLZ","HST","MAR","HLT","EXPE",
      "ETSY","EBAY","ZM","BIDU","BMRN","ALGN","TEL","APH","MCHP","ON"
    ];

    function initData() {
      stocks.length = 0;
      const total = rows * cols;
      for (let i = 0; i < total; i++) {
        const base = 20 + Math.random() * 480;
        const change = (Math.random() - 0.5) * 20; // -10% to +10%
        stocks.push({
          symbol: symbols[i % symbols.length] + (i >= symbols.length ? `.${Math.floor(i / symbols.length)}` : ""),
          sector: ["Tech","Finance","Health","Energy","Consumer","Industrial"][i % 6],
          price: base,
          prevClose: base / (1 + change / 100),
          changePct: change,
          volume: Math.floor(1e5 + Math.random() * 9e6),
          x: i % cols,
          y: Math.floor(i / cols)
        });
      }
    }

    function resize() {
      const rect = viewport.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(pct) {
      // Map -10..+10 to red-white-green
      const t = clamp((pct + 10) / 20, 0, 1);
      // interpolate:
      // 0 => deep red, 0.5 => near white, 1 => deep green
      let r, g, b;
      if (t < 0.5) {
        const u = t / 0.5;
        r = Math.round(185 + (248 - 185) * u);
        g = Math.round(28 + (250 - 28) * u);
        b = Math.round(28 + (250 - 28) * u);
      } else {
        const u = (t - 0.5) / 0.5;
        r = Math.round(248 + (22 - 248) * u);
        g = Math.round(250 + (163 - 250) * u);
        b = Math.round(250 + (74 - 250) * u);
      }
      return `rgb(${r},${g},${b})`;
    }

    function drawRoundedRect(x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.save();
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;
      const gridSize = 40 * scale;
      for (let x = (offsetX % gridSize); x < width; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = (offsetY % gridSize); y < height; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }
      ctx.restore();

      const padding = 16;
      const gap = 10;
      const baseCellW = (width - padding * 2 - gap * (cols - 1)) / cols;
      const baseCellH = (height - padding * 2 - gap * (rows - 1)) / rows;

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      for (const s of stocks) {
        const x = padding + s.x * (baseCellW + gap);
        const y = padding + s.y * (baseCellH + gap);
        const w = baseCellW;
        const h = baseCellH;

        // Only draw visible-ish items
        if (x + w < -200 || y + h < -200 || x > width / scale + 200 || y > height / scale + 200) continue;

        ctx.fillStyle = colorForChange(s.changePct);
        drawRoundedRect(x, y, w, h, 12);
        ctx.fill();

        ctx.strokeStyle = "rgba(255,255,255,0.10)";
        ctx.stroke();

        // Text
        ctx.fillStyle = s.changePct >= 0 ? "#06210f" : "#2b0a0a";
        ctx.font = "bold 14px system-ui, sans-serif";
        ctx.fillText(s.symbol, x + 10, y + 22);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 10, y + 42);

        const sign = s.changePct >= 0 ? "+" : "";
        ctx.fillText(`${sign}${s.changePct.toFixed(2)}%`, x + 10, y + 60);
      }

      ctx.restore();
    }

    function screenToWorld(px, py) {
      return {
        x: (px - offsetX) / scale,
        y: (py - offsetY) / scale
      };
    }

    function hitTest(px, py) {
      const world = screenToWorld(px, py);
      const padding = 16;
      const gap = 10;
      const baseCellW = (width - padding * 2 - gap * (cols - 1)) / cols;
      const baseCellH = (height - padding * 2 - gap * (rows - 1)) / rows;

      for (const s of stocks) {
        const x = padding + s.x * (baseCellW + gap);
        const y = padding + s.y * (baseCellH + gap);
        const w = baseCellW;
        const h = baseCellH;
        if (world.x >= x && world.x <= x + w && world.y >= y && world.y <= y + h) return s;
      }
      return null;
    }

    function updateTooltip(e) {
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      const item = hitTest(mx, my);

      if (!item) {
        tooltip.style.display = "none";
        return;
      }

      const sign = item.changePct >= 0 ? "+" : "";
      tooltip.innerHTML = `
        <div><strong>${item.symbol}</strong> <span style="color:#8a93b8">(${item.sector})</span></div>
        <div>Price: <strong>$${item.price.toFixed(2)}</strong></div>
        <div>Prev Close: $${item.prevClose.toFixed(2)}</div>
        <div>Change: <strong style="color:${item.changePct >= 0 ? '#4ade80' : '#f87171'}">${sign}${item.changePct.toFixed(2)}%</strong></div>
        <div>Volume: ${item.volume.toLocaleString()}</div>
      `;
      tooltip.style.left = mx + "px";
      tooltip.style.top = my + "px";
      tooltip.style.display = "block";
    }

    function randomWalkUpdate() {
      for (const s of stocks) {
        const delta = (Math.random() - 0.5) * 1.2;
        s.changePct = clamp(s.changePct + delta, -15, 15);
        s.price = Math.max(0.5, s.price * (1 + delta / 100));
        s.volume = Math.max(0, s.volume + Math.floor((Math.random() - 0.5) * 50000));
      }
      draw();
    }

    // Zoom around cursor
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 4);

      const worldX = (mx - offsetX) / scale;
      const worldY = (my - offsetY) / scale;

      scale = newScale;
      offsetX = mx - worldX * scale;
      offsetY = my - worldY * scale;

      draw();
    }, { passive: false });

    // Pan
    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      viewport.classList.add("dragging");
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      if (isDragging) {
        offsetX = offsetStart.x + (e.clientX - dragStart.x);
        offsetY = offsetStart.y + (e.clientY - dragStart.y);
        draw();
      }
      updateTooltip(e);
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume Updates" : "Pause Updates";
      statusEl.textContent = paused ? "Live updates: PAUSED" : "Live updates: ON";
    });

    randomizeBtn.addEventListener("click", () => {
      for (const s of stocks) {
        s.changePct = (Math.random() - 0.5) * 20;
        s.price = 20 + Math.random() * 480;
        s.prevClose = s.price / (1 + s.changePct / 100);
        s.volume = Math.floor(1e5 + Math.random() * 9e6);
      }
      draw();
    });

    window.addEventListener("resize", resize);

    // Init
    initData();
    resize();

    // Simulated real-time updates
    setInterval(() => {
      if (!paused) randomWalkUpdate();
    }, 1000);
  </script>
</body>
</html>
```

