<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="legend">
        <span>Loss</span>
        <div class="bar"></div>
        <span>Gain</span>
      </div>
      <div class="spacer"></div>
      <div class="status" id="status">Streaming updates: ON</div>
      <button id="resetBtn">Reset View</button>
      <button id="pauseBtn">Pause Updates</button>
    </div>

    <div class="viewport" id="viewport">
      <div class="heatmap" id="heatmap"></div>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const statusEl = document.getElementById('status');

    const tickers = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','COST','PEP','KO','MCD','JPM',
      'BAC','WMT','DIS','UBER','PYPL','SHOP','SNAP','SQ','BABA','T'
    ];

    const state = {
      prices: new Map(),
      prevPrices: new Map(),
      updateTimer: null,
      paused: false,
      scale: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0
    };

    function randomBasePrice() {
      return Math.round((20 + Math.random() * 900) * 100) / 100;
    }

    function initData() {
      tickers.forEach(t => {
        const p = randomBasePrice();
        state.prices.set(t, p);
        state.prevPrices.set(t, p);
      });
    }

    function formatPrice(n) {
      return `$${n.toFixed(2)}`;
    }

    function formatChange(delta, pct) {
      const sign = delta >= 0 ? '+' : '';
      return `${sign}${delta.toFixed(2)} (${sign}${pct.toFixed(2)}%)`;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(pct) {
      // pct roughly in [-5, 5] mapped to red -> yellow -> green
      const t = clamp((pct + 5) / 10, 0, 1);
      const hue = 120 * t; // 0 red, 60 yellow, 120 green
      const sat = 70;
      const light = 32 + 18 * Math.abs(t - 0.5) * 2;
      return `hsl(${hue}, ${sat}%, ${light}%)`;
    }

    function render() {
      const cols = Math.ceil(Math.sqrt(tickers.length));
      heatmap.style.gridTemplateColumns = `repeat(${cols}, 92px)`;

      heatmap.innerHTML = tickers.map(ticker => {
        const price = state.prices.get(ticker);
        const prev = state.prevPrices.get(ticker);
        const delta = price - prev;
        const pct = prev ? (delta / prev) * 100 : 0;
        const bg = colorForChange(pct);

        return `
          <div class="cell" data-ticker="${ticker}" style="background:${bg}">
            <div class="ticker">${ticker}</div>
            <div class="price">${formatPrice(price)}</div>
            <div class="change">${formatChange(delta, pct)}</div>
          </div>
        `;
      }).join('');

      applyTransform();
      bindCellEvents();
    }

    function bindCellEvents() {
      heatmap.querySelectorAll('.cell').forEach(cell => {
        cell.addEventListener('mouseenter', onCellEnter);
        cell.addEventListener('mousemove', onCellMove);
        cell.addEventListener('mouseleave', onCellLeave);
      });
    }

    function onCellEnter(e) {
      const ticker = e.currentTarget.dataset.ticker;
      const price = state.prices.get(ticker);
      const prev = state.prevPrices.get(ticker);
      const delta = price - prev;
      const pct = prev ? (delta / prev) * 100 : 0;

      tooltip.innerHTML = `
        <strong>${ticker}</strong><br/>
        Price: ${formatPrice(price)}<br/>
        Change: ${formatChange(delta, pct)}<br/>
        Updated: ${new Date().toLocaleTimeString()}
      `;
      tooltip.classList.add('visible');
    }

    function onCellMove(e) {
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function onCellLeave() {
      tooltip.classList.remove('visible');
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.panX = 0;
      state.panY = 0;
      applyTransform();
    }

    function updatePrices() {
      if (state.paused) return;

      tickers.forEach(ticker => {
        const current = state.prices.get(ticker);
        state.prevPrices.set(ticker, current);

        // Simulate a small random walk
        const volatility = current < 50 ? 0.035 : current < 250 ? 0.02 : 0.012;
        const changePct = (Math.random() - 0.5) * volatility * 2;
        const next = Math.max(0.5, current * (1 + changePct));

        state.prices.set(ticker, Math.round(next * 100) / 100);
      });

      render();
    }

    function startStreaming() {
      stopStreaming();
      state.updateTimer = setInterval(updatePrices, 1000);
    }

    function stopStreaming() {
      if (state.updateTimer) clearInterval(state.updateTimer);
      state.updateTimer = null;
    }

    // Zoom with mouse wheel
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const nextScale = clamp(state.scale * zoomFactor, 0.4, 4);

      // Zoom around cursor
      const worldX = (mouseX - state.panX) / state.scale;
      const worldY = (mouseY - state.panY) / state.scale;

      state.panX = mouseX - worldX * nextScale;
      state.panY = mouseY - worldY * nextScale;
      state.scale = nextScale;

      applyTransform();
    }, { passive: false });

    // Pan with drag
    viewport.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (state.dragging) {
        state.panX = state.startPanX + (e.clientX - state.dragStartX);
        state.panY = state.startPanY + (e.clientY - state.dragStartY);
        applyTransform();
      }
    });

    viewport.addEventListener('pointerup', () => {
      state.dragging = false;
    });

    viewport.addEventListener('pointercancel', () => {
      state.dragging = false;
    });

    resetBtn.addEventListener('click', resetView);

    pauseBtn.addEventListener('click', () => {
      state.paused = !state.paused;
      pauseBtn.textContent = state.paused ? 'Resume Updates' : 'Pause Updates';
      statusEl.textContent = state.paused ? 'Streaming updates: PAUSED' : 'Streaming updates: ON';
    });

    // Hide tooltip when leaving viewport
    viewport.addEventListener('mouseleave', () => {
      tooltip.classList.remove('visible');
    });

    // Initialize
    initData();
    render();
    startStreaming();

    // Re-render on resize to keep layout stable
    window.addEventListener('resize', () => {
      applyTransform();
    });
  </script>
</body>
</html>
