    const tickers = [
      ['AAPL','Apple'], ['MSFT','Microsoft'], ['NVDA','NVIDIA'], ['AMZN','Amazon'],
      ['GOOGL','Alphabet'], ['META','Meta'], ['TSLA','Tesla'], ['AMD','AMD'],
      ['NFLX','Netflix'], ['INTC','Intel'], ['ORCL','Oracle'], ['CRM','Salesforce'],
      ['JPM','JPMorgan'], ['BAC','Bank of America'], ['V','Visa'], ['MA','Mastercard'],
      ['XOM','Exxon Mobil'], ['CVX','Chevron'], ['KO','Coca-Cola'], ['PEP','PepsiCo'],
      ['WMT','Walmart'], ['COST','Costco'], ['DIS','Disney'], ['UBER','Uber'],
