    function buildData() {
      state.data = tickers.map(([symbol, name]) => {
        const price = rand(20, 500);
        const prevClose = price * (1 + rand(-0.03, 0.03));
        return {
          symbol,
          name,
          price,
          prevClose,
          changePct: ((price - prevClose) / prevClose) * 100,
          spark: '↔'
        };
      });
    }

    function renderGrid() {
      grid.innerHTML = '';
      const cols = 4;
      grid.style.gridTemplateColumns = `repeat(${cols}, 140px)`;
      state.data.forEach((d, i) => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.index = i;
        cell.innerHTML = `
          <div class="ticker">${d.symbol}</div>
          <div class="name">${d.name}</div>
          <div class="spark">${d.spark}</div>
          <div class="price"></div>
          <div class="change"></div>
        `;
        grid.appendChild(cell);
      });
      updateCells(true);
    }

    function updateCells(initial = false) {
      const cells = grid.querySelectorAll('.cell');
      cells.forEach((cell, i) => {
        const d = state.data[i];
        const priceEl = cell.querySelector('.price');
        const changeEl = cell.querySelector('.change');
        const sparkEl = cell.querySelector('.spark');

        priceEl.textContent = `$${d.price.toFixed(2)}`;
        changeEl.textContent = `${d.changePct >= 0 ? '+' : ''}${d.changePct.toFixed(2)}%`;
        sparkEl.textContent = d.changePct >= 0 ? '▲' : '▼';

        cell.style.background = priceColor(d.changePct);
        cell.style.color = textColor(d.changePct);
        changeEl.style.color = d.changePct >= 0 ? '#bff3cf' : '#ffd0d0';

        if (!initial && animateToggle.checked) {
          cell.animate(
            [
              { transform: 'scale(1)', filter: 'brightness(1)' },
              { transform: 'scale(1.03)', filter: 'brightness(1.12)' },
              { transform: 'scale(1)', filter: 'brightness(1)' }
            ],
            { duration: 260, easing: 'ease-out' }
          );
        }
      });
    }

    function updateTransform() {
      world.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
      zoomSlider.value = state.scale.toFixed(2);
    }

    function centerWorld() {
      const rect = viewport.getBoundingClientRect();
      const contentW = grid.offsetWidth + 32;
      const contentH = grid.offsetHeight + 32;
      state.scale = 1;
      state.x = Math.max(0, (rect.width - contentW) / 2);
      state.y = Math.max(0, (rect.height - contentH) / 2);
      updateTransform();
    }

    function zoomAt(clientX, clientY, nextScale) {
      const rect = viewport.getBoundingClientRect();
      const px = clientX - rect.left;
      const py = clientY - rect.top;

      nextScale = clamp(nextScale, 0.4, 3);

      const worldX = (px - state.x) / state.scale;
      const worldY = (py - state.y) / state.scale;

      state.scale = nextScale;
      state.x = px - worldX * state.scale;
      state.y = py - worldY * state.scale;
      updateTransform();
    }

    function onWheel(e) {
      e.preventDefault();
      const delta = -e.deltaY * 0.0015;
      const nextScale = state.scale * (1 + delta);
      zoomAt(e.clientX, e.clientY, nextScale);
    }

    function onPointerDown(e) {
      viewport.setPointerCapture(e.pointerId);
      state.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (state.pointers.size === 1) {
        state.dragging = true;
        viewport.classList.add('dragging');
        state.dragStartX = e.clientX;
        state.dragStartY = e.clientY;
        state.startX = state.x;
        state.startY = state.y;
      } else if (state.pointers.size === 2) {
        const pts = [...state.pointers.values()];
        state.pinchStartDist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
        state.pinchStartScale = state.scale;
        state.pinchCenter = {
          x: (pts[0].x + pts[1].x) / 2,
          y: (pts[0].y + pts[1].y) / 2
        };
      }
    }

    function onPointerMove(e) {
      if (!state.pointers.has(e.pointerId)) return;
      state.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (state.pointers.size === 1 && state.dragging) {
        const dx = e.clientX - state.dragStartX;
        const dy = e.clientY - state.dragStartY;
        state.x = state.startX + dx;
        state.y = state.startY + dy;
        updateTransform();
      } else if (state.pointers.size === 2) {
        const pts = [...state.pointers.values()];
        const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
        const nextScale = clamp(state.pinchStartScale * (dist / state.pinchStartDist), 0.4, 3);
        zoomAt(state.pinchCenter.x, state.pinchCenter.y, nextScale);
      }
    }

    function onPointerUp(e) {
      state.pointers.delete(e.pointerId);
      if (state.pointers.size === 0) {
        state.dragging = false;
        viewport.classList.remove('dragging');
      }
    }

    function simulateFeed() {
      if (!liveToggle.checked) return;

      state.data.forEach(d => {
        const drift = rand(-0.8, 0.8);
        const shock = Math.random() < 0.08 ? rand(-3, 3) : 0;
        d.price = Math.max(1, d.price + drift + shock);

        if (Math.random() < 0.02) {
          d.prevClose = d.price * (1 + rand(-0.02, 0.02));
        }

        d.changePct = ((d.price - d.prevClose) / d.prevClose) * 100;
      });

      updateCells(false);
      statusEl.textContent = `Live updates · ${new Date().toLocaleTimeString()}`;
    }

    zoomSlider.addEventListener('input', () => {
      const rect = viewport.getBoundingClientRect();
      const cx = rect.width / 2;
      const cy = rect.height / 2;
      zoomAt(rect.left + cx, rect.top + cy, parseFloat(zoomSlider.value));
    });

    resetBtn.addEventListener('click', centerWorld);
    viewport.addEventListener('wheel', onWheel, { passive: false });
    viewport.addEventListener('pointerdown', onPointerDown);
    viewport.addEventListener('pointermove', onPointerMove);
    viewport.addEventListener('pointerup', onPointerUp);
    viewport.addEventListener('pointercancel', onPointerUp);
    viewport.addEventListener('pointerleave', onPointerUp);

    liveToggle.addEventListener('change', () => {
      statusEl.textContent = liveToggle.checked ? 'Connected to simulated feed' : 'Live updates paused';
    });

    window.addEventListener('resize', centerWorld);

    buildData();
    renderGrid();
    requestAnimationFrame(() => {
      centerWorld();
      updateTransform();
    });

    setInterval(simulateFeed, 1000);
  </script>
</body>
</html>
```

