```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Interactive Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      font-family: Arial, sans-serif;
      background: #0b1020;
      color: #fff;
    }

    #app {
      position: relative;
      width: 100vw;
      height: 100vh;
      user-select: none;
      cursor: grab;
    }

    #app.dragging {
      cursor: grabbing;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(20, 24, 40, 0.95);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.4;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
      white-space: nowrap;
    }

    .legend {
      position: absolute;
      left: 12px;
      bottom: 12px;
      background: rgba(20, 24, 40, 0.85);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 12px;
      z-index: 10;
    }

    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(to right, #d73027, #f46d43, #fdae61, #ffffbf, #a6d96a, #66bd63, #1a9850);
      margin-top: 8px;
      border: 1px solid rgba(255,255,255,0.12);
    }

    .status {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(20, 24, 40, 0.85);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 12px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="canvas"></canvas>
    <div id="tooltip" class="tooltip"></div>
    <div class="status" id="status">Loading stocks...</div>
    <div class="legend">
      <div><strong>Price Change Heatmap</strong></div>
      <div>Red = down, Green = up</div>
      <div class="legend-bar"></div>
    </div>
  </div>

  <script>
    const app = document.getElementById('app');
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    // View transform
    const view = {
      x: 0,
      y: 0,
      scale: 1
    };

    // Interaction state
    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let viewStart = { x: 0, y: 0 };

    // Heatmap config
    const tileSize = 90;
    const tileGap = 8;
    const cols = 20;
    const rows = 15;
    const stocks = [];
    const symbols = [];

    // Generate fake stock symbols
    function randomSymbol() {
      const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
      let s = '';
      for (let i = 0; i < 3 + Math.floor(Math.random() * 2); i++) {
        s += letters[Math.floor(Math.random() * letters.length)];
      }
      return s;
    }

    function uniqueSymbol(existing) {
      let s;
      do {
        s = randomSymbol();
      } while (existing.has(s));
      existing.add(s);
      return s;
    }

    const existing = new Set();
    for (let i = 0; i < rows * cols; i++) {
      const symbol = uniqueSymbol(existing);
      const base = 20 + Math.random() * 980;
      const change = (Math.random() - 0.5) * 10;
      stocks.push({
        symbol,
        price: base,
        prevPrice: base,
        change,
        volume: Math.floor(100000 + Math.random() * 5000000),
        sector: ['Tech', 'Finance', 'Energy', 'Health', 'Retail'][Math.floor(Math.random() * 5)]
      });
    }

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener('resize', resize);

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(changePct) {
      // changePct in [-5, 5] roughly
      const min = -5;
      const max = 5;
      const t = clamp((changePct - min) / (max - min), 0, 1);

      // Red -> Yellow -> Green
      const r1 = [215, 48, 39];
      const r2 = [255, 255, 191];
      const r3 = [26, 152, 80];

      let c;
      if (t < 0.5) {
        const u = t / 0.5;
        c = [
          Math.round(r1[0] + (r2[0] - r1[0]) * u),
          Math.round(r1[1] + (r2[1] - r1[1]) * u),
          Math.round(r1[2] + (r2[2] - r1[2]) * u)
        ];
      } else {
        const u = (t - 0.5) / 0.5;
        c = [
          Math.round(r2[0] + (r3[0] - r2[0]) * u),
          Math.round(r2[1] + (r3[1] - r2[1]) * u),
          Math.round(r2[2] + (r3[2] - r2[2]) * u)
        ];
      }
      return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
    }

    function getTileRect(index) {
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = col * (tileSize + tileGap);
      const y = row * (tileSize + tileGap);
      return { x, y, w: tileSize, h: tileSize };
    }

    function worldToScreen(x, y) {
      return {
        x: x * view.scale + view.x,
        y: y * view.scale + view.y
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - view.x) / view.scale,
        y: (y - view.y) / view.scale
      };
    }

    function drawGridBackground() {
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      // subtle grid
      ctx.save();
      ctx.globalAlpha = 0.12;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      const step = 40;
      for (let x = (view.x % step); x < width; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = (view.y % step); y < height; y += step) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }
      ctx.restore();
    }

    function draw() {
      drawGridBackground();

      const totalW = cols * tileSize + (cols - 1) * tileGap;
      const totalH = rows * tileSize + (rows - 1) * tileGap;

      ctx.save();
      ctx.translate(view.x, view.y);
      ctx.scale(view.scale, view.scale);

      for (let i = 0; i < stocks.length; i++) {
        const stock = stocks[i];
        const rect = getTileRect(i);

        const changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
        const fill = priceToColor(changePct);

        // Tile
        ctx.fillStyle = fill;
        ctx.fillRect(rect.x, rect.y, rect.w, rect.h);

        // Border
        ctx.strokeStyle = 'rgba(255,255,255,0.18)';
        ctx.lineWidth = 1 / view.scale;
        ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);

        // Text
        ctx.fillStyle = '#111';
        ctx.font = `${12 / view.scale}px Arial`;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillText(stock.symbol, rect.x + 8, rect.y + 8);

        ctx.font = `${11 / view.scale}px Arial`;
        ctx.fillText(`$${stock.price.toFixed(2)}`, rect.x + 8, rect.y + 28);

        const ch = changePct >= 0 ? '+' : '';
        ctx.fillText(`${ch}${changePct.toFixed(2)}%`, rect.x + 8, rect.y + 46);
      }

      ctx.restore();

      statusEl.textContent = `Stocks: ${stocks.length} | Zoom: ${view.scale.toFixed(2)}x`;
    }

    // Simulated real-time updates
    function updatePrices() {
      for (const stock of stocks) {
        stock.prevPrice = stock.price;
        const drift = (Math.random() - 0.5) * 2.5;
        const volatility = stock.price * (Math.random() - 0.5) * 0.01;
        stock.price = Math.max(1, stock.price + drift + volatility);
        stock.volume += Math.floor(Math.random() * 1000);
      }
      draw();
    }

    setInterval(updatePrices, 1000);

    // Hover hit testing
    function hitTest(screenX, screenY) {
      const world = screenToWorld(screenX, screenY);
      for (let i = 0; i < stocks.length; i++) {
        const rect = getTileRect(i);
        if (
          world.x >= rect.x &&
          world.x <= rect.x + rect.w &&
          world.y >= rect.y &&
          world.y <= rect.y + rect.h
        ) {
          return { stock: stocks[i], rect, index: i };
        }
      }
      return null;
    }

    function showTooltip(e, hit) {
      const stock = hit.stock;
      const changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
      const ch = changePct >= 0 ? '+' : '';
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br/>
        Price: $${stock.price.toFixed(2)}<br/>
        Change: ${ch}${changePct.toFixed(2)}%<br/>
        Volume: ${stock.volume.toLocaleString()}<br/>
        Sector: ${stock.sector}
      `;
      tooltip.style.display = 'block';
      tooltip.style.left = (e.clientX + 12) + 'px';
      tooltip.style.top = (e.clientY + 12) + 'px';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    app.addEventListener('mousemove', (e) => {
      if (dragging) {
        view.x = viewStart.x + (e.clientX - dragStart.x);
        view.y = viewStart.y + (e.clientY - dragStart.y);
        draw();
        return;
      }

      const hit = hitTest(e.clientX, e.clientY);
      if (hit) {
        showTooltip(e, hit);
      } else {
        hideTooltip();
      }
    });

    app.addEventListener('mouseleave', hideTooltip);

    app.addEventListener('mousedown', (e) => {
      dragging = true;
      app.classList.add('dragging');
      dragStart.x = e.clientX;
      dragStart.y = e.clientY;
      viewStart.x = view.x;
      viewStart.y = view.y;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      app.classList.remove('dragging');
    });

    // Zoom with mouse wheel centered on cursor
    app.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldScale = view.scale;
      const newScale = clamp(oldScale * zoomFactor, 0.4, 4);

      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // Keep cursor position stable while zooming
      const worldBefore = screenToWorld(mouseX, mouseY);
      view.scale = newScale;
      const screenAfter = worldToScreen(worldBefore.x, worldBefore.y);

      view.x += mouseX - screenAfter.x;
      view.y += mouseY - screenAfter.y;

      draw();
    }, { passive: false });

    // Double click to reset view
    app.addEventListener('dblclick', () => {
      view.x = 20;
      view.y = 20;
      view.scale = 1;
      draw();
    });

    // Initial layout
    function centerView() {
      const totalW = cols * tileSize + (cols - 1) * tileGap;
      const totalH = rows * tileSize + (rows - 1) * tileGap;
      view.scale = 1;
      view.x = Math.max(20, (width - totalW) / 2);
      view.y = Math.max(20, (height - totalH) / 2);
    }

    resize();
    centerView();
    draw();
  </script>
</body>
