      will-change: transform;
    }

    .grid {
      display: grid;
      gap: 1px;
      background: var(--grid);
      border: 1px solid rgba(255,255,255,0.08);
      box-shadow: 0 0 0 1px rgba(255,255,255,0.04) inset;
    }

    .cell {
      width: 72px;
      height: 44px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      font-weight: 600;
      position: relative;
      color: rgba(255,255,255,0.9);
      transition: background-color 120ms linear;
    }

    .cell:hover {
      outline: 2px solid rgba(255,255,255,0.35);
      z-index: 2;
    }

    .labels {
      display: grid;
      grid-template-columns: 120px 1fr;
      gap: 0;
      align-items: stretch;
    }

    .row-labels, .col-labels {
      display: grid;
      gap: 1px;
      background: var(--grid);
    }

    .row-label, .col-label {
      background: rgba(255,255,255,0.03);
      color: var(--text);
      font-size: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0 8px;
      white-space: nowrap;
    }

    .row-label {
      width: 120px;
      height: 44px;
      justify-content: flex-start;
      font-weight: 700;
    }

    .col-label {
      width: 72px;
      height: 28px;
      writing-mode: vertical-rl;
      transform: rotate(180deg);
      font-weight: 600;
    }

    .sidebar {
      border-left: 1px solid rgba(255,255,255,0.08);
      background: rgba(255,255,255,0.02);
      padding: 16px;
      overflow: auto;
    }

    .card {
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 12px;
      padding: 14px;
      margin-bottom: 14px;
    }

    .card h2 {
      margin: 0 0 10px;
      font-size: 14px;
    }

    .tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(8, 12, 24, 0.96);
      border: 1px solid rgba(255,255,255,0.12);
      color: white;
      padding: 10px 12px;
      border-radius: 10px;
      font-size: 12px;
      line-height: 1.4;
      box-shadow: 0 10px 30px rgba(0,0,0,0.35);
      display: none;
      z-index: 9999;
      min-width: 180px;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 8px;
    }

    .legend-bar {
      height: 12px;
      flex: 1;
      border-radius: 999px;
      background: linear-gradient(90deg, #d94b4b, #f1c24b, #4bd97e);
      border: 1px solid rgba(255,255,255,0.15);
    }

    .small {
      font-size: 12px;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <button id="toggleUpdates">Pause Updates</button>
      <button id="resetView">Reset View</button>
      <button id="randomize">Randomize Prices</button>
      <span class="stat" id="status">Live</span>
      <span class="stat">Wheel: zoom · Drag: pan · Hover: details</span>
    </div>

    <div class="layout">
      <div class="viewport" id="viewport">
        <div class="canvas" id="canvas">
          <div class="labels">
            <div class="row-labels" id="rowLabels"></div>
            <div>
              <div class="col-labels" id="colLabels" style="grid-auto-flow: column;"></div>
              <div class="grid" id="grid"></div>
            </div>
          </div>
        </div>
      </div>

      <aside class="sidebar">
        <div class="card">
          <h2>Selected Cell</h2>
          <div id="selectionInfo" class="small">Hover a cell to inspect live values.</div>
        </div>

        <div class="card">
          <h2>Legend</h2>
          <div class="legend">
            <span class="small">-5%</span>
            <div class="legend-bar"></div>
            <span class="small">+5%</span>
          </div>
          <p class="small" style="margin-top:10px;">
            Green = positive price change, red = negative change, yellow = near flat.
          </p>
        </div>

        <div class="card">
          <h2>Notes</h2>
          <p class="small">
            This demo simulates live stock updates client-side. Replace the update loop with a WebSocket or SSE feed for real market data.
          </p>
        </div>
      </aside>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const canvas = document.getElementById('canvas');
    const grid = document.getElementById('grid');
    const rowLabels = document.getElementById('rowLabels');
    const colLabels = document.getElementById('colLabels');
    const tooltip = document.getElementById('tooltip');
    const selectionInfo = document.getElementById('selectionInfo');
    const toggleUpdatesBtn = document.getElementById('toggleUpdates');
    const resetViewBtn = document.getElementById('resetView');
    const randomizeBtn = document.getElementById('randomize');
    const status = document.getElementById('status');

    const stocks = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'TSLA', 'META', 'NFLX', 'AMD', 'INTC'
    ];

    const timeSteps = 24;

    const state = {
      scale: 1,
      panX: 20,
      panY: 20,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      updatesRunning: true,
      prices: [],
      basePrices: {},
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function initData() {
      state.prices = stocks.map(symbol => {
        const base = rand(80, 500);
        state.basePrices[symbol] = base;
        return Array.from({ length: timeSteps }, (_, i) => ({
          symbol,
          time: i,
          price: base + rand(-8, 8),
        }));
      });
    }

    function buildLabels() {
      rowLabels.innerHTML = '';
      colLabels.innerHTML = '';

      stocks.forEach(symbol => {
        const el = document.createElement('div');
        el.className = 'row-label';
        el.textContent = symbol;
        rowLabels.appendChild(el);
      });

      for (let i = 0; i < timeSteps; i++) {
        const el = document.createElement('div');
        el.className = 'col-label';
        el.textContent = `T-${timeSteps - i - 1}`;
        colLabels.appendChild(el);
      }
    }

    function priceChangePct(symbol, price) {
      const base = state.basePrices[symbol];
      return ((price - base) / base) * 100;
    }

    function colorForChange(pct) {
      // Clamp to [-5, 5] for display
      const x = clamp(pct, -5, 5);
      const t = (x + 5) / 10; // 0..1
      const red = [217, 75, 75];
      const yellow = [241, 194, 75];
      const green = [75, 217, 126];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = yellow; localT = t / 0.5;
      } else {
        c1 = yellow; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, i) => Math.round(v + (c2[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function renderGrid() {
      grid.innerHTML = '';
      grid.style.gridTemplateColumns = `repeat(${timeSteps}, 72px)`;

      state.prices.forEach((row, rowIndex) => {
        row.forEach((cellData, colIndex) => {
          const pct = priceChangePct(cellData.symbol, cellData.price);
          const cell = document.createElement('div');
          cell.className = 'cell';
          cell.dataset.symbol = cellData.symbol;
          cell.dataset.time = cellData.time;
          cell.dataset.price = cellData.price.toFixed(2);
          cell.dataset.pct = pct.toFixed(2);
          cell.style.background = colorForChange(pct);
          cell.textContent = cellData.price.toFixed(0);

          cell.addEventListener('mousemove', (e) => {
            tooltip.style.display = 'block';
            tooltip.style.left = `${e.clientX + 14}px`;
            tooltip.style.top = `${e.clientY + 14}px`;
            tooltip.innerHTML = `
              <strong>${cellData.symbol}</strong><br/>
              Time: ${cellData.time}<br/>
              Price: $${cellData.price.toFixed(2)}<br/>
              Change: ${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%
            `;

            selectionInfo.innerHTML = `
              <strong>${cellData.symbol}</strong><br/>
              Time index: ${cellData.time}<br/>
              Price: $${cellData.price.toFixed(2)}<br/>
              Change vs base: ${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%
            `;
          });

          cell.addEventListener('mouseleave', () => {
            tooltip.style.display = 'none';
          });

          grid.appendChild(cell);
        });
      });
    }

    function updateLiveData() {
      state.prices.forEach(row => {
        row.forEach(cell => {
          const drift = rand(-1.2, 1.2);
          const volatility = rand(-0.8, 0.8);
          cell.price = Math.max(1, cell.price + drift + volatility);
        });
      });

      // Update DOM in place
      const cells = grid.querySelectorAll('.cell');
      cells.forEach((cell, idx) => {
        const rowIndex = Math.floor(idx / timeSteps);
        const colIndex = idx % timeSteps;
        const data = state.prices[rowIndex][colIndex];
        const pct = priceChangePct(data.symbol, data.price);
        cell.dataset.price = data.price.toFixed(2);
        cell.dataset.pct = pct.toFixed(2);
        cell.style.background = colorForChange(pct);
        cell.textContent = data.price.toFixed(0);
      });
    }

    function randomizePrices() {
      state.prices.forEach(row => {
        row.forEach(cell => {
          cell.price = state.basePrices[cell.symbol] + rand(-20, 20);
        });
      });
      updateLiveData();
    }

    function applyTransform() {
      canvas.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.panX = 20;
      state.panY = 20;
      applyTransform();
    }

    viewport.addEventListener('mousedown', (e) => {
      state.dragging = true;
      viewport.classList.add('dragging');
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) return;
      state.panX = state.startPanX + (e.clientX - state.dragStartX);
      state.panY = state.startPanY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - state.panX) / state.scale;
      const worldY = (mouseY - state.panY) / state.scale;

      state.scale = newScale;
      state.panX = mouseX - worldX * state.scale;
      state.panY = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    toggleUpdatesBtn.addEventListener('click', () => {
      state.updatesRunning = !state.updatesRunning;
      toggleUpdatesBtn.textContent = state.updatesRunning ? 'Pause Updates' : 'Resume Updates';
      status.textContent = state.updatesRunning ? 'Live' : 'Paused';
    });

    resetViewBtn.addEventListener('click', resetView);
    randomizeBtn.addEventListener('click', randomizePrices);

    // Init
    initData();
    buildLabels();
    renderGrid();
    applyTransform();

    // Real-time update loop
    setInterval(() => {
      if (state.updatesRunning) updateLiveData();
    }, 1000);

    // Keep tooltip inside viewport
    window.addEventListener('mousemove', (e) => {
      const pad = 16;
      const rect = tooltip.getBoundingClientRect();
      let x = e.clientX + 14;
      let y = e.clientY + 14;

      if (x + rect.width + pad > window.innerWidth) x = e.clientX - rect.width - 14;
      if (y + rect.height + pad > window.innerHeight) y = e.clientY - rect.height - 14;

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    });
  </script>
</body>
</html>
