    #toolbar button {
      background: #1f2937;
      color: #e5e7eb;
      border: 1px solid #374151;
      border-radius: 8px;
      padding: 8px 12px;
      cursor: pointer;
    }

    #toolbar button:hover {
      background: #374151;
    }

    #status {
      margin-left: auto;
      font-size: 14px;
      color: #9ca3af;
    }

    #heatmapWrap {
      position: relative;
      flex: 1;
      overflow: hidden;
      background: #0b1020;
      user-select: none;
      cursor: grab;
    }

    #heatmapWrap:active {
      cursor: grabbing;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    #tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(17, 24, 39, 0.95);
      color: white;
      border: 1px solid #374151;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.4;
      transform: translate(12px, 12px);
      display: none;
      z-index: 3;
      white-space: nowrap;
      box-shadow: 0 8px 24px rgba(0,0,0,0.25);
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: #9ca3af;
    }

    .legendBar {
      width: 140px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(to right, #b91c1c, #111827, #15803d);
      border: 1px solid #374151;
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <button id="resetView">Reset View</button>
      <button id="toggleStream">Pause Stream</button>
      <div class="legend">
        <span>-5%</span>
        <div class="legendBar"></div>
        <span>+5%</span>
      </div>
      <div id="status">Live</div>
    </div>
    <div id="heatmapWrap">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    // -----------------------------
    // Data model
    // -----------------------------
    const STOCKS = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "CRM", "ORCL", "ADBE", "QCOM", "AVGO", "CSCO"
    ];

    const TIME_SLOTS = 120; // columns
    const CELL_WIDTH = 18;
    const CELL_HEIGHT = 24;

    // Each cell stores a percent change value, and a timestamp
    const data = Array.from({ length: STOCKS.length }, () =>
      Array.from({ length: TIME_SLOTS }, () => ({
        pct: (Math.random() - 0.5) * 2,
        ts: Date.now()
      }))
    );

    // -----------------------------
    // Canvas setup
    // -----------------------------
    const wrap = document.getElementById("heatmapWrap");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener("resize", () => {
      dpr = window.devicePixelRatio || 1;
      resizeCanvas();
    });

    // -----------------------------
    // View state for zoom/pan
    // -----------------------------
    const view = {
      scale: 1,
      offsetX: 0,
      offsetY: 0
    };

    const minScale = 0.5;
    const maxScale = 4;

    function resetView() {
      view.scale = 1;
      view.offsetX = 0;
      view.offsetY = 0;
      draw();
    }

    // -----------------------------
    // Real-time stream simulation
    // -----------------------------
    let streaming = true;
    let tickCount = 0;

    function pushUpdate() {
      // Shift left and append a new column per stock
      for (let r = 0; r < STOCKS.length; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1]?.pct ?? 0;
        const next = prev + (Math.random() - 0.5) * 0.8;
        data[r].push({
          pct: Math.max(-10, Math.min(10, next)),
          ts: Date.now()
        });
      }
      tickCount++;
      statusEl.textContent = streaming ? `Live · updates: ${tickCount}` : `Paused · updates: ${tickCount}`;
      draw();
    }

    const streamTimer = setInterval(() => {
      if (streaming) pushUpdate();
    }, 1000);

    // -----------------------------
    // Color scale
    // -----------------------------
    function colorForPct(pct) {
      // Clamp to [-5, 5] for visualization
      const v = Math.max(-5, Math.min(5, pct));
      const t = (v + 5) / 10; // 0..1
      // Red -> dark -> green
      const r1 = [185, 28, 28];
      const r2 = [17, 24, 39];
      const g1 = [21, 128, 61];

      let c;
      if (t < 0.5) {
        const u = t / 0.5;
        c = lerpColor(r1, r2, u);
      } else {
        const u = (t - 0.5) / 0.5;
        c = lerpColor(r2, g1, u);
      }
      return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
    }

    function lerpColor(a, b, t) {
      return [
        Math.round(a[0] + (b[0] - a[0]) * t),
        Math.round(a[1] + (b[1] - a[1]) * t),
        Math.round(a[2] + (b[2] - a[2]) * t)
      ];
    }

    // -----------------------------
    // Rendering
    // -----------------------------
    function draw() {
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);
      ctx.scale(view.scale, view.scale);

      const startX = 90; // label gutter
      const startY = 20;

      // Draw stock labels
      ctx.font = "12px system-ui, sans-serif";
      ctx.textBaseline = "middle";

      for (let r = 0; r < STOCKS.length; r++) {
        const y = startY + r * CELL_HEIGHT;
        ctx.fillStyle = "#cbd5e1";
        ctx.fillText(STOCKS[r], 10, y + CELL_HEIGHT / 2);

        for (let c = 0; c < TIME_SLOTS; c++) {
          const x = startX + c * CELL_WIDTH;
          const cell = data[r][c];
          ctx.fillStyle = colorForPct(cell.pct);
          ctx.fillRect(x, y, CELL_WIDTH - 1, CELL_HEIGHT - 1);

          // subtle border
          ctx.strokeStyle = "rgba(255,255,255,0.06)";
          ctx.strokeRect(x, y, CELL_WIDTH - 1, CELL_HEIGHT - 1);
        }
      }

      // Time axis labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "11px system-ui, sans-serif";
      for (let c = 0; c < TIME_SLOTS; c += 10) {
        const x = startX + c * CELL_WIDTH;
        ctx.fillText(`${TIME_SLOTS - c}s`, x, 10);
      }

      ctx.restore();
    }

    // -----------------------------
    // Interaction: pan
    // -----------------------------
    let isPanning = false;
    let panStart = { x: 0, y: 0 };
    let panOrigin = { x: 0, y: 0 };

    wrap.addEventListener("mousedown", (e) => {
      isPanning = true;
      panStart = { x: e.clientX, y: e.clientY };
      panOrigin = { x: view.offsetX, y: view.offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      if (isPanning) {
        view.offsetX = panOrigin.x + (e.clientX - panStart.x);
        view.offsetY = panOrigin.y + (e.clientY - panStart.y);
        draw();
      }

      updateTooltip(e);
    });

    window.addEventListener("mouseup", () => {
      isPanning = false;
    });

    // -----------------------------
    // Interaction: zoom
    // -----------------------------
    wrap.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(minScale, Math.min(maxScale, view.scale * zoomFactor));

      // Zoom around cursor
      const worldX = (mouseX - view.offsetX) / view.scale;
      const worldY = (mouseY - view.offsetY) / view.scale;

      view.scale = newScale;
      view.offsetX = mouseX - worldX * view.scale;
      view.offsetY = mouseY - worldY * view.scale;

      draw();
    }, { passive: false });

    // -----------------------------
    // Tooltip
    // -----------------------------
    function updateTooltip(e) {
      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Convert screen coords to world coords
      const worldX = (mouseX - view.offsetX) / view.scale;
      const worldY = (mouseY - view.offsetY) / view.scale;

      const startX = 90;
      const startY = 20;

      const col = Math.floor((worldX - startX) / CELL_WIDTH);
      const row = Math.floor((worldY - startY) / CELL_HEIGHT);

      if (row >= 0 && row < STOCKS.length && col >= 0 && col < TIME_SLOTS) {
        const cell = data[row][col];
        tooltip.style.display = "block";
        tooltip.style.left = e.clientX + "px";
        tooltip.style.top = e.clientY + "px";
        tooltip.innerHTML = `
          <strong>${STOCKS[row]}</strong><br/>
          Change: <span style="color:${cell.pct >= 0 ? '#4ade80' : '#f87171'}">${cell.pct.toFixed(2)}%</span><br/>
          Time: ${new Date(cell.ts).toLocaleTimeString()}
        `;
      } else {
        tooltip.style.display = "none";
      }
    }

    // -----------------------------
    // Controls
    // -----------------------------
    document.getElementById("resetView").addEventListener("click", resetView);
    document.getElementById("toggleStream").addEventListener("click", (e) => {
      streaming = !streaming;
      e.target.textContent = streaming ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = streaming ? `Live · updates: ${tickCount}` : `Paused · updates: ${tickCount}`;
    });

    // Initial render
    resizeCanvas();
    resetView();
  </script>
</body>
</html>
```

