<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="pill" id="status">Live updates: connected</div>
      <div class="pill" id="lastUpdate">Last update: --</div>
      <div class="spacer"></div>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <div class="controls">
        <button id="resetView">Reset View</button>
        <button id="pauseFeed">Pause Feed</button>
      </div>
    </div>

    <div id="chart">
      <div class="tooltip" id="tooltip"></div>
      <svg id="svg"></svg>
    </div>
  </div>

  <script>
    const svg = d3.select("#svg");
    const chart = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const lastUpdateEl = document.getElementById("lastUpdate");
    const resetViewBtn = document.getElementById("resetView");
    const pauseFeedBtn = document.getElementById("pauseFeed");

    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","BRK.B","JPM","V",
      "UNH","XOM","LLY","AVGO","MA","COST","PG","HD","MRK","NFLX",
      "AMD","CRM","ADBE","PEP","KO","DIS","INTC","CSCO","TMO","ABT"
    ];

    const rows = 6;
    const cols = 5;

    let data = symbols.map((symbol, i) => ({
      symbol,
      price: 100 + Math.random() * 400,
      prevPrice: 100 + Math.random() * 400,
      volume: Math.floor(1e6 + Math.random() * 9e6),
      sector: ["Tech", "Finance", "Healthcare", "Consumer", "Energy"][i % 5]
    }));

    let paused = false;

    const margin = { top: 40, right: 20, bottom: 40, left: 60 };
    let width = 0;
    let height = 0;

    const g = svg.append("g").attr("class", "root");
    const gridG = g.append("g").attr("class", "grid");
    const cellsG = g.append("g").attr("class", "cells");
    const labelsG = g.append("g").attr("class", "labels");

    const zoom = d3.zoom()
      .scaleExtent([0.7, 8])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    function resize() {
      const rect = chart.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      render();
    }

    function getLayout() {
      const innerWidth = width - margin.left - margin.right;
      const innerHeight = height - margin.top - margin.bottom;

      const cellW = innerWidth / cols;
      const cellH = innerHeight / rows;

      return { innerWidth, innerHeight, cellW, cellH };
    }

    function priceChangePct(d) {
      return ((d.price - d.prevPrice) / d.prevPrice) * 100;
    }

    function colorScale(value) {
      // value is percentage change
      const max = 5;
      const clamped = Math.max(-max, Math.min(max, value));
      const t = (clamped + max) / (2 * max);
      return d3.interpolateRdYlGn(t);
    }

    function render() {
      if (!width || !height) return;

      const { innerWidth, innerHeight, cellW, cellH } = getLayout();

      const x = (i) => margin.left + (i % cols) * cellW;
      const y = (i) => margin.top + Math.floor(i / cols) * cellH;

      const cells = cellsG.selectAll("rect.cell")
        .data(data, d => d.symbol);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", (d, i) => x(i) + 6)
        .attr("y", (d, i) => y(i) + 6)
        .attr("width", cellW - 12)
        .attr("height", cellH - 12)
        .attr("fill", d => colorScale(priceChangePct(d)))
        .on("mousemove", (event, d) => showTooltip(event, d))
        .on("mouseleave", hideTooltip)
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", (d, i) => x(i) + 6)
        .attr("y", (d, i) => y(i) + 6)
        .attr("width", cellW - 12)
        .attr("height", cellH - 12)
        .attr("fill", d => colorScale(priceChangePct(d)));

      cells.exit().remove();

      const labels = labelsG.selectAll("g.label")
        .data(data, d => d.symbol);

      const labelEnter = labels.enter()
        .append("g")
        .attr("class", "label")
        .style("pointer-events", "none");

      labelEnter.append("text")
        .attr("class", "symbol")
        .attr("text-anchor", "middle")
        .attr("fill", "white")
        .attr("font-size", 14)
        .attr("font-weight", 700);

      labelEnter.append("text")
        .attr("class", "price")
        .attr("text-anchor", "middle")
        .attr("fill", "rgba(255,255,255,0.85)")
        .attr("font-size", 11);

      labelEnter.merge(labels)
        .transition()
        .duration(300)
        .attr("transform", (d, i) => {
          const cx = x(i) + cellW / 2;
          const cy = y(i) + cellH / 2;
          return `translate(${cx}, ${cy})`;
        });

      labelsG.selectAll("g.label .symbol")
        .text(d => d.symbol);

      labelsG.selectAll("g.label .price")
        .attr("dy", "1.4em")
        .text(d => `$${d.price.toFixed(2)} (${priceChangePct(d) >= 0 ? "+" : ""}${priceChangePct(d).toFixed(2)}%)`);

      labels.exit().remove();

      // Draw subtle grid lines
      const vLines = d3.range(cols + 1).map(i => margin.left + i * cellW);
      const hLines = d3.range(rows + 1).map(i => margin.top + i * cellH);

      const v = gridG.selectAll("line.v")
        .data(vLines);

      v.enter().append("line").attr("class", "grid-line v")
        .merge(v)
        .attr("x1", d => d).attr("x2", d => d)
        .attr("y1", margin.top).attr("y2", margin.top + innerHeight);

      v.exit().remove();

      const h = gridG.selectAll("line.h")
        .data(hLines);

      h.enter().append("line").attr("class", "grid-line h")
        .merge(h)
        .attr("x1", margin.left).attr("x2", margin.left + innerWidth)
        .attr("y1", d => d).attr("y2", d => d);

      h.exit().remove();
    }

    function showTooltip(event, d) {
      const change = priceChangePct(d);
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <div style="font-weight:700; font-size:13px; margin-bottom:4px;">${d.symbol}</div>
        <div>Price: <strong>$${d.price.toFixed(2)}</strong></div>
        <div>Change: <strong style="color:${change >= 0 ? '#4ade80' : '#f87171'}">
          ${change >= 0 ? '+' : ''}${change.toFixed(2)}%
        </strong></div>
        <div>Volume: <strong>${d3.format(",")(d.volume)}</strong></div>
        <div>Sector: <strong>${d.sector}</strong></div>
      `;

      const [mx, my] = d3.pointer(event, chart);
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    function randomWalkUpdate() {
      if (paused) return;

      data = data.map(d => {
        const prev = d.price;
        const delta = (Math.random() - 0.5) * (d.price * 0.02); // +/- 1%
        const next = Math.max(1, prev + delta);
        return {
          ...d,
          prevPrice: prev,
          price: next,
          volume: Math.max(1000, Math.floor(d.volume * (0.95 + Math.random() * 0.1)))
        };
      });

      lastUpdateEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;
      render();
    }

    let feedTimer = setInterval(randomWalkUpdate, 1200);

    pauseFeedBtn.addEventListener("click", () => {
      paused = !paused;
      pauseFeedBtn.textContent = paused ? "Resume Feed" : "Pause Feed";
      statusEl.textContent = paused ? "Live updates: paused" : "Live updates: connected";
    });

    resetViewBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    resize();
    lastUpdateEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;
  </script>
</body>
</html>
