    const margin = { top: 20, right: 20, bottom: 20, left: 20 };

    const gRoot = svg.append("g").attr("class", "root");
    const gGrid = gRoot.append("g").attr("class", "grid");
    const gXAxis = gRoot.append("g").attr("class", "axis x-axis");
    const gYAxis = gRoot.append("g").attr("class", "axis y-axis");

    const zoom = d3.zoom()
      .scaleExtent([0.6, 4])
      .on("zoom", (event) => {
        gRoot.attr("transform", event.transform);
      });

    svg.call(zoom);

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      // Center the grid nicely
      const gridW = cols * cellW + (cols - 1) * gap;
      const gridH = rows * cellH + (rows - 1) * gap;
      const offsetX = Math.max(margin.left, (width - gridW) / 2);
      const offsetY = Math.max(margin.top, (height - gridH) / 2);

      gRoot.attr("transform", `translate(${offsetX},${offsetY})`);

      draw();
    }

    window.addEventListener("resize", resize);

    // -----------------------------
    // Color scale
    // -----------------------------
    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b71c1c", "#fdd835", "#1b5e20"])
      .clamp(true);

    function textColorForBg(changePct) {
      return Math.abs(changePct) < 1.2 ? "#10131f" : "#ffffff";
    }

    // -----------------------------
    // Render
    // -----------------------------
    function draw() {
      const cells = gGrid.selectAll(".stock-cell")
        .data(stocks, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "stock-cell")
        .attr("transform", d => `translate(${d.x},${d.y})`)
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => {
          const [mx, my] = d3.pointer(event, wrap);
          tooltip.style.left = `${mx}px`;
          tooltip.style.top = `${my}px`;
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <div><strong>${d.symbol}</strong></div>
            <div>Price: $${d.price.toFixed(2)}</div>
            <div>Change: <span style="color:${d.changePct >= 0 ? '#7CFC98' : '#FF8A80'}">
              ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
            </span></div>
          `;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cellsEnter.append("rect")
        .attr("class", "cell")
        .attr("width", cellW)
        .attr("height", cellH)
        .attr("fill", d => colorScale(d.changePct));

      cellsEnter.append("text")
        .attr("class", "cell-label")
        .attr("x", 10)
        .attr("y", 22)
        .text(d => d.symbol);

      cellsEnter.append("text")
        .attr("class", "cell-sub")
        .attr("x", 10)
        .attr("y", 42)
        .text(d => `$${d.price.toFixed(2)}`);

      cellsEnter.append("text")
        .attr("class", "cell-sub")
        .attr("x", 10)
        .attr("y", 58)
        .text(d => `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);

      const merged = cellsEnter.merge(cells);

      merged.transition()
        .duration(350)
        .attr("transform", d => `translate(${d.x},${d.y})`);

      merged.select("rect")
        .transition()
        .duration(350)
        .attr("fill", d => colorScale(d.changePct));

      merged.select(".cell-label")
        .text(d => d.symbol)
        .attr("fill", d => textColorForBg(d.changePct));

      merged.selectAll(".cell-sub")
        .attr("fill", d => textColorForBg(d.changePct))
        .each(function(d, i) {
          const txt = d3.select(this);
          if (i === 0) txt.text(`$${d.price.toFixed(2)}`);
          if (i === 1) txt.text(`${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);
        });

      cells.exit().remove();
    }

    // -----------------------------
    // Real-time update simulation
    // -----------------------------
    let streamActive = true;
    let intervalId = null;

    function updatePrices() {
      if (!streamActive) return;

      // update a few random stocks each tick
      const updatesCount = 6;
      for (let i = 0; i < updatesCount; i++) {
        const idx = Math.floor(Math.random() * stocks.length);
        const s = stocks[idx];

        s.prevPrice = s.price;
        const drift = (Math.random() - 0.5) * 0.08; // +/- 4%
        s.price = Math.max(1, s.price * (1 + drift));
        s.changePct = ((s.price - s.prevPrice) / s.prevPrice) * 100;
      }

      // Occasionally apply a market-wide move
      if (Math.random() < 0.08) {
        const marketShock = (Math.random() - 0.5) * 0.03; // +/- 1.5%
        stocks.forEach(s => {
          s.prevPrice = s.price;
          s.price = Math.max(1, s.price * (1 + marketShock));
          s.changePct = ((s.price - s.prevPrice) / s.prevPrice) * 100;
        });
      }

      draw();
      const now = new Date();
      lastUpdateText.textContent = `Last update: ${now.toLocaleTimeString()}`;
    }

    function startStream() {
      intervalId = setInterval(updatePrices, 1000);
    }

    function stopStream() {
      clearInterval(intervalId);
      intervalId = null;
    }

    // -----------------------------
    // Controls
    // -----------------------------
    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("toggleStream").addEventListener("click", (e) => {
      streamActive = !streamActive;
      e.target.textContent = streamActive ? "Pause Stream" : "Resume Stream";
      statusText.textContent = `Streaming updates: ${streamActive ? "active" : "paused"}`;

      if (streamActive && !intervalId) startStream();
      if (!streamActive && intervalId) stopStream();
    });

    // -----------------------------
    // Initial render
    // -----------------------------
    resize();
    startStream();
    updatePrices(); // initial tick
  </script>
</body>
</html>
