    }

    .viewport {
      position: relative;
      flex: 1;
      overflow: hidden;
      touch-action: none;
      cursor: grab;
    }

    .viewport.dragging {
      cursor: grabbing;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 22, 38, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      color: #fff;
      font-size: 13px;
      box-shadow: 0 8px 22px rgba(0,0,0,0.35);
      transform: translate(12px, 12px);
      display: none;
      white-space: nowrap;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      color: var(--muted);
      font-size: 13px;
    }

    .swatch {
      width: 120px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(to right, #b71c1c, #f44336, #2c3e50, #4caf50, #1b5e20);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetView">Reset View</button>
      <button id="toggleStream">Pause Updates</button>
      <div class="legend">
        <span>Loss</span>
        <div class="swatch"></div>
        <span>Gain</span>
      </div>
      <div class="status" id="status">Loading...</div>
    </div>

    <div class="viewport" id="viewport">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    // -----------------------------
    // Data model
    // -----------------------------
    const STOCKS = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "ORCL", "CRM", "ADBE", "QCOM", "AVGO", "IBM"
    ];

    const state = {
      // heatmap cells: rows = stocks, cols = time buckets
      rows: STOCKS.length,
      cols: 80,
      data: [], // data[row][col] = { price, changePct, ts }
      basePrices: {},
      streaming: true,

      // viewport transform
      scale: 1,
      offsetX: 0,
      offsetY: 0,

      // interaction
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      dragOffsetX: 0,
      dragOffsetY: 0,

      // hover / selection
      hover: null,
      selected: null,

      // canvas
      dpr: window.devicePixelRatio || 1,
      width: 0,
      height: 0,

      // animation / render
      needsRender: true,
      lastUpdate: performance.now()
    };

    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");

    function seedData() {
      const now = Date.now();
      STOCKS.forEach(symbol => {
        state.basePrices[symbol] = 50 + Math.random() * 900;
      });

      for (let r = 0; r < state.rows; r++) {
        state.data[r] = [];
        let price = state.basePrices[STOCKS[r]];
        for (let c = 0; c < state.cols; c++) {
          const changePct = (Math.random() - 0.5) * 4;
          price = Math.max(1, price * (1 + changePct / 100));
          state.data[r][c] = {
            price,
            changePct,
            ts: now - (state.cols - c) * 1000
          };
        }
      }
    }

    function resize() {
      const rect = viewport.getBoundingClientRect();
      state.width = rect.width;
      state.height = rect.height;
      canvas.width = Math.floor(rect.width * state.dpr);
      canvas.height = Math.floor(rect.height * state.dpr);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      state.needsRender = true;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(changePct) {
      // Map -5%..+5% to red->neutral->green
      const t = clamp((changePct + 5) / 10, 0, 1);

      // interpolate between red -> dark -> green
      const red = [183, 28, 28];
      const neutral = [44, 62, 80];
      const green = [27, 94, 32];

      let a, b, localT;
      if (t < 0.5) {
        a = red; b = neutral; localT = t / 0.5;
      } else {
        a = neutral; b = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = a.map((v, i) => Math.round(v + (b[i] - v) * localT));
      return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
    }

    function drawGrid() {
      const cellW = 28 * state.scale;
      const cellH = 24 * state.scale;
      const originX = state.offsetX;
      const originY = state.offsetY;

      // background
      ctx.clearRect(0, 0, state.width, state.height);
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, state.width, state.height);

      // visible bounds
      const startCol = Math.max(0, Math.floor((-originX) / cellW) - 1);
      const endCol = Math.min(state.cols - 1, Math.ceil((state.width - originX) / cellW) + 1);
      const startRow = Math.max(0, Math.floor((-originY) / cellH) - 1);
      const endRow = Math.min(state.rows - 1, Math.ceil((state.height - originY) / cellH) + 1);

      ctx.font = `${Math.max(10, 12 * state.scale)}px system-ui, sans-serif`;
      ctx.textBaseline = "middle";

      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          const x = originX + c * cellW;
          const y = originY + r * cellH;
          const cell = state.data[r][c];

          // cell fill
          ctx.fillStyle = colorForChange(cell.changePct);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // highlight hover/selected
          if (state.hover && state.hover.row === r && state.hover.col === c) {
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, cellW - 3, cellH - 3);
          }
          if (state.selected && state.selected.row === r && state.selected.col === c) {
            ctx.strokeStyle = "#4f8cff";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, cellW - 3, cellH - 3);
          }

          // label only if zoomed enough
          if (state.scale >= 1.1) {
            ctx.fillStyle = "rgba(255,255,255,0.9)";
            ctx.fillText(
              `${STOCKS[r]}`,
              x + 6,
              y + cellH / 2
            );
          }
        }
      }

      // row labels when zoomed out a bit
      if (state.scale < 1.1) {
        ctx.fillStyle = "#cdd7f5";
        ctx.font = "12px system-ui, sans-serif";
        for (let r = startRow; r <= endRow; r++) {
          const y = originY + r * cellH + cellH / 2;
          ctx.fillText(STOCKS[r], 8, y);
        }
      }

      // grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.07)";
      ctx.lineWidth = 1;
      for (let r = startRow; r <= endRow + 1; r++) {
        const y = originY + r * cellH;
        ctx.beginPath();
        ctx.moveTo(originX, y);
        ctx.lineTo(originX + state.cols * cellW, y);
        ctx.stroke();
      }
      for (let c = startCol; c <= endCol + 1; c++) {
        const x = originX + c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, originY);
        ctx.lineTo(x, originY + state.rows * cellH);
        ctx.stroke();
      }

      // axis labels
      ctx.fillStyle = "#7f8bb3";
      ctx.font = "12px system-ui, sans-serif";
      ctx.fillText("Stocks ↓ / Time →", 8, 16);

      status.textContent = `Zoom: ${state.scale.toFixed(2)}x | Streaming: ${state.streaming ? "On" : "Paused"}`;
    }

    function render() {
      if (!state.needsRender) return;
      state.needsRender = false;
      drawGrid();
    }

    function scheduleRender() {
      state.needsRender = true;
      requestAnimationFrame(render);
    }

    function screenToCell(clientX, clientY) {
      const rect = viewport.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const cellW = 28 * state.scale;
      const cellH = 24 * state.scale;

      const col = Math.floor((x - state.offsetX) / cellW);
      const row = Math.floor((y - state.offsetY) / cellH);

      if (row < 0 || row >= state.rows || col < 0 || col >= state.cols) return null;
      return { row, col };
    }

    function updateTooltip(e) {
      const cell = screenToCell(e.clientX, e.clientY);
      if (!cell) {
        tooltip.style.display = "none";
        state.hover = null;
        scheduleRender();
        return;
      }

      const item = state.data[cell.row][cell.col];
      state.hover = cell;

      tooltip.style.display = "block";
      tooltip.style.left = e.clientX + "px";
      tooltip.style.top = e.clientY + "px";
      tooltip.innerHTML = `
        <strong>${STOCKS[cell.row]}</strong><br/>
        Price: $${item.price.toFixed(2)}<br/>
        Change: ${item.changePct.toFixed(2)}%
      `;
      scheduleRender();
    }

    // -----------------------------
    // Interactions
    // -----------------------------
    viewport.addEventListener("mousedown", (e) => {
      state.dragging = true;
      viewport.classList.add("dragging");
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.dragOffsetX = state.offsetX;
      state.dragOffsetY = state.offsetY;
    });

    window.addEventListener("mousemove", (e) => {
      if (state.dragging) {
        state.offsetX = state.dragOffsetX + (e.clientX - state.dragStartX);
        state.offsetY = state.dragOffsetY + (e.clientY - state.dragStartY);
        scheduleRender();
      } else {
        updateTooltip(e);
      }
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const oldScale = state.scale;
      const newScale = clamp(state.scale * zoomFactor, 0.6, 3);

      // Zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - state.offsetX) / oldScale;
      const worldY = (mouseY - state.offsetY) / oldScale;

      state.scale = newScale;
      state.offsetX = mouseX - worldX * newScale;
      state.offsetY = mouseY - worldY * newScale;

      scheduleRender();
    }, { passive: false });

    viewport.addEventListener("click", (e) => {
      const cell = screenToCell(e.clientX, e.clientY);
      if (cell) {
        state.selected = cell;
        scheduleRender();
      }
    });

    document.getElementById("resetView").addEventListener("click", () => {
      state.scale = 1;
      state.offsetX = 0;
      state.offsetY = 0;
      state.selected = null;
      scheduleRender();
    });

    document.getElementById("toggleStream").addEventListener("click", (e) => {
      state.streaming = !state.streaming;
      e.target.textContent = state.streaming ? "Pause Updates" : "Resume Updates";
      scheduleRender();
    });

    // -----------------------------
    // Real-time updates
    // -----------------------------
    function pushUpdate() {
      if (!state.streaming) return;

      const now = Date.now();

      for (let r = 0; r < state.rows; r++) {
        const prev = state.data[r][state.cols - 1];
        const drift = (Math.random() - 0.5) * 1.2;
        const shock = (Math.random() - 0.5) * 2.5;
        const changePct = drift + shock;
        const price = Math.max(1, prev.price * (1 + changePct / 100));

        state.data[r].push({
          price,
          changePct,
          ts: now
        });

        if (state.data[r].length > state.cols) {
          state.data[r].shift();
        }
      }

      state.needsRender = true;
      render();
    }

    // -----------------------------
    // Init
    // -----------------------------
    seedData();
    resize();
    scheduleRender();

    window.addEventListener("resize", () => {
      resize();
      scheduleRender();
    });

    setInterval(pushUpdate, 1000);

    // initial center-ish offset so labels are visible
    state.offsetX = 80;
    state.offsetY = 30;
    scheduleRender();
  </script>
</body>
</html>
```

---

## How it works

### Data structure
Each stock has a row, and each time bucket is a column:

```js
data[row][col] = {
  price,
  changePct,
  ts
}
```

### Rendering
The heatmap is drawn on a `<canvas>` for speed. The code only renders visible cells based on the current zoom/pan transform.

### Zoom/pan
- **Wheel** zooms around the cursor
- **Drag** pans the viewport
- Transform is controlled by:
  - `scale`
  - `offsetX`
  - `offsetY`

### Real-time updates
Every second, a new price point is appended and the oldest is dropped, simulating a live stream.

