<body>
  <div class="app">
    <div class="toolbar">
      <h1>Interactive Stock Heatmap</h1>
      <div class="chip" id="status">Connecting…</div>
      <div class="legend">
        <span>Performance</span>
        <div class="bar"></div>
        <span>Loss → Gain</span>
      </div>
      <div class="spacer"></div>
      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <button id="randomizeBtn">Simulate Tick</button>
      </div>
    </div>

    <div class="stage" id="stage">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('heatmap');
      const stage = document.getElementById('stage');
      const tooltip = document.getElementById('tooltip');
      const statusEl = document.getElementById('status');
      const resetBtn = document.getElementById('resetBtn');
      const randomizeBtn = document.getElementById('randomizeBtn');
      const ctx = canvas.getContext('2d');

      // --- Sample data model ---
      const sectors = [
        'Tech','Finance','Health','Energy','Retail','Industrials','Utilities','Materials'
      ];
      const symbols = [
        'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','JPM','BAC','V',
        'JNJ','PFE','XOM','CVX','WMT','COST','CAT','GE','NEE','LIN','AMD','INTC'
      ];

      const data = symbols.map((symbol, i) => ({
        symbol,
        sector: sectors[i % sectors.length],
        price: 50 + Math.random() * 450,
        prevClose: 50 + Math.random() * 450,
        volume: Math.floor(1e6 + Math.random() * 9e6),
        x: 0, y: 0, w: 0, h: 0
      }));

      // --- View transform (pan/zoom) ---
      const view = {
        scale: 1,
        tx: 0,
        ty: 0
      };

      let dpr = Math.max(1, window.devicePixelRatio || 1);
      let width = 0, height = 0;

      function resize() {
        const rect = stage.getBoundingClientRect();
        width = rect.width;
        height = rect.height;
        dpr = Math.max(1, window.devicePixelRatio || 1);

        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';

        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        layout();
        draw();
      }

      function layout() {
        const cols = Math.max(2, Math.floor(Math.sqrt(data.length)));
        const rows = Math.ceil(data.length / cols);
        const pad = 18;
        const headerH = 26;
        const cellW = Math.min(220, (width - pad * 2) / cols - 10);
        const cellH = Math.min(140, (height - pad * 2) / rows - 10);

        data.forEach((d, i) => {
          const col = i % cols;
          const row = Math.floor(i / cols);
          d.x = pad + col * (cellW + 10);
          d.y = pad + row * (cellH + 10);
          d.w = cellW;
          d.h = cellH;
        });

        // Center the grid initially
        const contentW = cols * cellW + (cols - 1) * 10 + pad * 2;
        const contentH = rows * cellH + (rows - 1) * 10 + pad * 2;
        if (!initialized) {
          view.scale = Math.min(width / contentW, height / contentH) * 0.95;
          view.tx = (width - contentW * view.scale) / 2;
          view.ty = (height - contentH * view.scale) / 2;
          initialized = true;
        }
      }

      function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

      function priceChangePct(d) {
        return ((d.price - d.prevClose) / d.prevClose) * 100;
      }

      function colorForChange(pct) {
        // -10% => red, 0 => yellow, +10% => green
        const t = clamp((pct + 10) / 20, 0, 1);
        const hue = 0 + t * 145; // red -> green
        const sat = 85;
        const light = 42 + Math.abs(t - 0.5) * -8 + 8;
        return `hsl(${hue} ${sat}% ${light}%)`;
      }

      function drawRoundedRect(x, y, w, h, r) {
        const rr = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + rr, y);
        ctx.arcTo(x + w, y, x + w, y + h, rr);
        ctx.arcTo(x + w, y + h, x, y + h, rr);
        ctx.arcTo(x, y + h, x, y, rr);
        ctx.arcTo(x, y, x + w, y, rr);
        ctx.closePath();
      }

      function draw() {
        ctx.clearRect(0, 0, width, height);

        // Background grid
        ctx.save();
        ctx.globalAlpha = 1;
        ctx.fillStyle = 'rgba(255,255,255,0.02)';
        ctx.fillRect(0, 0, width, height);

        // Apply transform
        ctx.translate(view.tx, view.ty);
        ctx.scale(view.scale, view.scale);

        // Draw cells
        data.forEach(d => {
          const pct = priceChangePct(d);
          const fill = colorForChange(pct);

          // cell
          drawRoundedRect(d.x, d.y, d.w, d.h, 14);
          ctx.fillStyle = fill;
          ctx.fill();

          // subtle border
          ctx.strokeStyle = 'rgba(255,255,255,0.18)';
          ctx.lineWidth = 1 / view.scale;
          ctx.stroke();

          // inner overlay
          const grad = ctx.createLinearGradient(d.x, d.y, d.x, d.y + d.h);
          grad.addColorStop(0, 'rgba(255,255,255,0.18)');
          grad.addColorStop(1, 'rgba(0,0,0,0.08)');
          drawRoundedRect(d.x, d.y, d.w, d.h, 14);
          ctx.fillStyle = grad;
          ctx.fill();

          // text
          ctx.fillStyle = 'rgba(255,255,255,0.96)';
          ctx.font = `700 ${Math.max(12, 16 / view.scale)}px Inter, system-ui, sans-serif`;
          ctx.fillText(d.symbol, d.x + 14, d.y + 24);

          ctx.font = `600 ${Math.max(10, 12 / view.scale)}px Inter, system-ui, sans-serif`;
          ctx.fillStyle = 'rgba(255,255,255,0.88)';
          ctx.fillText(`$${d.price.toFixed(2)}`, d.x + 14, d.y + 46);

          const pctText = `${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%`;
          ctx.fillStyle = pct >= 0 ? 'rgba(220,255,245,0.98)' : 'rgba(255,230,235,0.98)';
          ctx.fillText(pctText, d.x + 14, d.y + 66);

          ctx.fillStyle = 'rgba(255,255,255,0.72)';
          ctx.fillText(d.sector, d.x + 14, d.y + d.h - 16);
        });

        ctx.restore();
      }

      // --- Interaction: pan / zoom ---
      let isPanning = false;
      let panStart = { x: 0, y: 0, tx: 0, ty: 0 };

      function screenToWorld(sx, sy) {
        return {
          x: (sx - view.tx) / view.scale,
          y: (sy - view.ty) / view.scale
        };
      }

      function hitTest(sx, sy) {
        const p = screenToWorld(sx, sy);
        return data.find(d =>
          p.x >= d.x && p.x <= d.x + d.w &&
          p.y >= d.y && p.y <= d.y + d.h
        );
      }

      canvas.addEventListener('pointerdown', (e) => {
        isPanning = true;
        canvas.setPointerCapture(e.pointerId);
        panStart = { x: e.clientX, y: e.clientY, tx: view.tx, ty: view.ty };
      });

      canvas.addEventListener('pointermove', (e) => {
        const hovered = hitTest(e.clientX, e.clientY);
        if (hovered) {
          const pct = priceChangePct(hovered);
          tooltip.style.left = e.clientX + 'px';
          tooltip.style.top = e.clientY + 'px';
          tooltip.innerHTML = `
            <strong>${hovered.symbol}</strong><br/>
            Sector: ${hovered.sector}<br/>
            Price: $${hovered.price.toFixed(2)}<br/>
            Prev Close: $${hovered.prevClose.toFixed(2)}<br/>
            Change: <span style="color:${pct >= 0 ? 'var(--good)' : 'var(--bad)'}">
              ${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%
            </span><br/>
            Volume: ${hovered.volume.toLocaleString()}
          `;
          tooltip.style.opacity = 1;
        } else {
          tooltip.style.opacity = 0;
        }

        if (!isPanning) return;
        view.tx = panStart.tx + (e.clientX - panStart.x);
        view.ty = panStart.ty + (e.clientY - panStart.y);
        draw();
      });

      canvas.addEventListener('pointerup', () => {
        isPanning = false;
      });

      canvas.addEventListener('pointercancel', () => {
        isPanning = false;
      });

      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();
        const mouseX = e.clientX;
        const mouseY = e.clientY;
        const zoom = Math.exp(-e.deltaY * 0.0015);
        const newScale = clamp(view.scale * zoom, 0.45, 3.5);

        // Zoom around cursor
        const world = screenToWorld(mouseX, mouseY);
        view.scale = newScale;
        view.tx = mouseX - world.x * view.scale;
        view.ty = mouseY - world.y * view.scale;

        draw();
      }, { passive: false });

      // --- Real-time updates (initial implementation) ---
      function simulateTick() {
        data.forEach(d => {
          const drift = (Math.random() - 0.5) * 1.8;
          const shock = (Math.random() - 0.5) * 0.8;
          d.prevClose = d.prevClose * (1 + (Math.random() - 0.5) * 0.001);
          d.price = Math.max(1, d.price + drift + shock);
          d.volume = Math.max(0, d.volume + Math.floor((Math.random() - 0.5) * 200000));
        });
        statusEl.textContent = `Live • ${new Date().toLocaleTimeString()}`;
        draw();
      }

      // Optional: connect to a websocket later.
      // Example stub:
      // const ws = new WebSocket('wss://your-feed.example');
      // ws.onmessage = (msg) => { updateFromFeed(JSON.parse(msg.data)); draw(); };

      let initialized = false;
      window.addEventListener('resize', resize);
      resetBtn.addEventListener('click', () => {
        initialized = false;
        layout();
        draw();
      });
      randomizeBtn.addEventListener('click', simulateTick);

      // Initial render
      resize();
      statusEl.textContent = 'Live • Simulated feed';

      // Auto-refresh
      setInterval(simulateTick, 1200);
    })();
  </script>
</body>
</html>
```

### What this gives you
- **Client-side heatmap** rendered on a `<canvas>`
- **Real-time updates** via a simulated tick loop
- **Zoom** with mouse wheel
- **Pan** by click-drag
- **Hover tooltips** with stock details
- **Responsive resizing**

### Next steps you might want
- Replace the simulated tick with a **WebSocket / SSE / polling feed**
- Add **sector grouping**, **sorting**, or **search**
- Improve visual density for **hundreds/thousands of symbols**
- Add **selection**, **mini-map**, or **time-series drilldown**

If you want, I can turn this into a more production-ready version using **React + Canvas/WebGL**, or wire it to a **real market data API**.

Below is a solid **initial client-side implementation** of an interactive **stock price heatmap** with:

- **real-time updates** via simulated streaming data
- **zoom and pan** interactions
- **hover tooltips**
- **color scaling** based on price change
- **vanilla HTML/CSS/JS** so it can run directly in a browser

You can use this as a starting point and later swap the simulated stream for a real WebSocket/API feed.

