  <div class="app">
    <header>
      <h1>Stock Price Heatmap</h1>
      <div class="status" id="status">Connecting…</div>
    </header>

    <div class="toolbar">
      <button id="resetView">Reset View</button>
      <button id="toggleStream">Pause Updates</button>
