      <div class="grid" id="grid"></div>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    // ----- Sample stock universe -----
    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","NFLX",
      "AMD","INTC","CRM","ORCL","ADBE","QCOM","AVGO","IBM",
      "JPM","BAC","WFC","GS","MS","V","MA","PYPL",
      "XOM","CVX","COP","SLB","BP","TTE","PFE","MRNA",
      "UNH","JNJ","LLY","ABBV","TMO","DHR","COST","WMT"
    ];

    const grid = document.getElementById("grid");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");
    const resetViewBtn = document.getElementById("resetView");
    const toggleStreamBtn = document.getElementById("toggleStream");

    // ----- State -----
    const state = {
      zoom: 1,
      panX: 0,
      panY: 0,
      isPanning: false,
      startX: 0,
      startY: 0,
      startPanX: 0,
      startPanY: 0,
      streaming: true,
      cells: new Map()
    };

    // ----- Utilities -----
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPrice(n) {
      return `$${n.toFixed(2)}`;
    }

    function formatPct(n) {
      return `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;
    }

    // Red -> neutral -> green
    function getColor(changePct) {
      const maxAbs = 8; // tune for sensitivity
      const t = clamp((changePct + maxAbs) / (2 * maxAbs), 0, 1);

      // interpolate between red, dark, green
      const red = [192, 57, 43];
      const mid = [34, 43, 69];
      const green = [39, 174, 96];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = mid; localT = t / 0.5;
      } else {
        c1 = mid; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, i) => Math.round(v + (c2[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function updateTransform() {
      grid.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
    }

    function updateStatus() {
      status.textContent = state.streaming
        ? `Live updates enabled · ${state.cells.size} symbols`
        : `Updates paused · ${state.cells.size} symbols`;
    }

    // ----- Create initial cells -----
    function createCells() {
      const cols = 8;
      grid.style.gridTemplateColumns = `repeat(${cols}, 120px)`;

      symbols.forEach((symbol, index) => {
        const base = 50 + Math.random() * 450;
        const last = base;
        const changePct = (Math.random() * 10) - 5;

        const cell = document.createElement("div");
        cell.className = "cell";
        cell.dataset.symbol = symbol;

        cell.innerHTML = `
          <div class="symbol">${symbol}</div>
          <div class="price">${formatPrice(last)}</div>
          <div class="change">${formatPct(changePct)}</div>
          <div class="meta">Vol: ${(Math.random() * 5 + 0.5).toFixed(1)}M</div>
        `;

        const data = {
          symbol,
          price: last,
          changePct,
          volume: Math.random() * 5_000_000,
          lastUpdate: Date.now()
        };

        state.cells.set(symbol, data);
        applyCellStyle(cell, data);

        // Hover tooltip
        cell.addEventListener("mousemove", (e) => showTooltip(e, data));
        cell.addEventListener("mouseleave", hideTooltip);

        grid.appendChild(cell);
      });
    }

    function applyCellStyle(cell, data) {
      cell.style.background = getColor(data.changePct);

      const changeEl = cell.querySelector(".change");
      changeEl.textContent = formatPct(data.changePct);
      changeEl.style.color = data.changePct >= 0 ? "#b8f7cf" : "#ffd0cc";

      const priceEl = cell.querySelector(".price");
      priceEl.textContent = formatPrice(data.price);

      const metaEl = cell.querySelector(".meta");
      metaEl.textContent = `Vol: ${(data.volume / 1_000_000).toFixed(1)}M`;

      // subtle emphasis based on magnitude
      const mag = Math.min(Math.abs(data.changePct), 10);
      cell.style.borderColor = `rgba(255,255,255,${0.08 + mag * 0.008})`;
    }

    function showTooltip(e, data) {
      tooltip.classList.add("visible");
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
      tooltip.innerHTML = `
        <strong>${data.symbol}</strong><br/>
        Price: ${formatPrice(data.price)}<br/>
        Change: ${formatPct(data.changePct)}<br/>
        Volume: ${(data.volume / 1_000_000).toFixed(2)}M<br/>
        Updated: ${new Date(data.lastUpdate).toLocaleTimeString()}
      `;
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // ----- Simulated real-time updates -----
    function streamUpdate() {
      if (!state.streaming) return;

      const updatesPerTick = 5 + Math.floor(Math.random() * 8);
      for (let i = 0; i < updatesPerTick; i++) {
        const symbol = symbols[Math.floor(Math.random() * symbols.length)];
        const data = state.cells.get(symbol);
        const cell = grid.querySelector(`[data-symbol="${symbol}"]`);
        if (!data || !cell) continue;

        // random walk
        const pctMove = (Math.random() - 0.5) * 1.2;
        data.changePct = clamp(data.changePct + pctMove, -20, 20);
        data.price = Math.max(1, data.price * (1 + pctMove / 100));
        data.volume = Math.max(0, data.volume + (Math.random() - 0.3) * 250000);
        data.lastUpdate = Date.now();

        applyCellStyle(cell, data);
      }

      updateStatus();
    }

    // ----- Zoom and pan -----
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newZoom = clamp(state.zoom * zoomFactor, 0.5, 3);

      // zoom toward cursor
      const worldX = (mouseX - state.panX) / state.zoom;
      const worldY = (mouseY - state.panY) / state.zoom;

      state.zoom = newZoom;
      state.panX = mouseX - worldX * state.zoom;
      state.panY = mouseY - worldY * state.zoom;

      updateTransform();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      state.isPanning = true;
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
      viewport.style.cursor = "grabbing";
    });

    window.addEventListener("mousemove", (e) => {
      if (state.isPanning) {
        state.panX = state.startPanX + (e.clientX - state.startX);
        state.panY = state.startPanY + (e.clientY - state.startY);
        updateTransform();
      }
    });

    window.addEventListener("mouseup", () => {
      state.isPanning = false;
      viewport.style.cursor = "default";
    });

    // touch pan support
    let touchStartDist = null;
    let touchStartZoom = 1;
    let touchStartPan = { x: 0, y: 0 };
    let touchStartCenter = { x: 0, y: 0 };

    viewport.addEventListener("touchstart", (e) => {
      if (e.touches.length === 1) {
        state.isPanning = true;
        state.startX = e.touches[0].clientX;
        state.startY = e.touches[0].clientY;
        state.startPanX = state.panX;
        state.startPanY = state.panY;
      } else if (e.touches.length === 2) {
        const t1 = e.touches[0], t2 = e.touches[1];
        touchStartDist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        touchStartZoom = state.zoom;
        touchStartPan = { x: state.panX, y: state.panY };
        touchStartCenter = {
          x: (t1.clientX + t2.clientX) / 2,
          y: (t1.clientY + t2.clientY) / 2
        };
      }
    }, { passive: true });

    viewport.addEventListener("touchmove", (e) => {
      if (e.touches.length === 1 && state.isPanning) {
        state.panX = state.startPanX + (e.touches[0].clientX - state.startX);
        state.panY = state.startPanY + (e.touches[0].clientY - state.startY);
        updateTransform();
      } else if (e.touches.length === 2 && touchStartDist) {
        const t1 = e.touches[0], t2 = e.touches[1];
        const dist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        const scale = clamp(touchStartZoom * (dist / touchStartDist), 0.5, 3);

        const rect = viewport.getBoundingClientRect();
        const centerX = touchStartCenter.x - rect.left;
        const centerY = touchStartCenter.y - rect.top;

        const worldX = (centerX - touchStartPan.x) / touchStartZoom;
        const worldY = (centerY - touchStartPan.y) / touchStartZoom;

        state.zoom = scale;
        state.panX = centerX - worldX * state.zoom;
        state.panY = centerY - worldY * state.zoom;

        updateTransform();
      }
    }, { passive: true });

    viewport.addEventListener("touchend", () => {
      state.isPanning = false;
      touchStartDist = null;
    });

    // ----- Controls -----
    resetViewBtn.addEventListener("click", () => {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      updateTransform();
    });

    toggleStreamBtn.addEventListener("click", () => {
      state.streaming = !state.streaming;
      toggleStreamBtn.textContent = state.streaming ? "Pause Updates" : "Resume Updates";
      updateStatus();
    });

    // ----- Init -----
    createCells();
    updateTransform();
    updateStatus();

    // streaming interval
    setInterval(streamUpdate, 500);

    // keep tooltip inside viewport
    window.addEventListener("mousemove", (e) => {
      const padding = 16;
      const tw = tooltip.offsetWidth || 200;
      const th = tooltip.offsetHeight || 100;
      let x = e.clientX + 12;
      let y = e.clientY + 12;
      if (x + tw + padding > window.innerWidth) x = e.clientX - tw - 12;
      if (y + th + padding > window.innerHeight) y = e.clientY - th - 12;
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    });
  </script>
</body>
</html>
```

