## Example implementation

### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";

type StockCell = {
  symbol: string;
  name: string;
  sector: string;
  price: number;
  changePct: number;
  x: number;
  y: number;
  w: number;
  h: number;
};

type ViewTransform = {
  scale: number;
  offsetX: number;
  offsetY: number;
};

const SECTORS = [
  "Technology",
  "Healthcare",
  "Finance",
  "Energy",
  "Consumer",
  "Industrial",
];

const SYMBOLS = [
  "AAPL", "MSFT", "NVDA", "GOOGL", "AMZN", "META", "TSLA", "AMD",
  "JPM", "BAC", "GS", "C", "XOM", "CVX", "PFE", "JNJ",
  "UNH", "HD", "WMT", "DIS", "BA", "CAT", "INTC", "ORCL",
];

function randomBetween(min: number, max: number) {
  return min + Math.random() * (max - min);
}

function generateInitialData(): StockCell[] {
  return SYMBOLS.map((symbol, i) => {
    const sector = SECTORS[i % SECTORS.length];
    return {
      symbol,
      name: `${symbol} Corp.`,
      sector,
      price: randomBetween(20, 500),
      changePct: randomBetween(-5, 5),
      x: 0,
      y: 0,
      w: 0,
      h: 0,
    };
  });
}

function updatePrices(data: StockCell[]): StockCell[] {
  return data.map((d) => {
    const drift = randomBetween(-0.8, 0.8);
    const newChange = Math.max(-10, Math.min(10, d.changePct + drift));
    const priceMultiplier = 1 + drift / 100;
    return {
      ...d,
      price: Math.max(1, d.price * priceMultiplier),
      changePct: newChange,
    };
  });
}

function getHeatColor(changePct: number) {
  // Red for negative, green for positive
  const clamped = Math.max(-10, Math.min(10, changePct));
  const intensity = Math.abs(clamped) / 10;

  if (clamped >= 0) {
    const g = Math.floor(80 + intensity * 175);
    return `rgb(30, ${g}, 60)`;
  } else {
    const r = Math.floor(80 + intensity * 175);
    return `rgb(${r}, 40, 50)`;
  }
}

function layoutGrid(data: StockCell[], width: number, height: number): StockCell[] {
  const cols = Math.ceil(Math.sqrt(data.length));
  const rows = Math.ceil(data.length / cols);

  const cellW = width / cols;
  const cellH = height / rows;

  return data.map((d, i) => ({
    ...d,
    x: (i % cols) * cellW,
    y: Math.floor(i / cols) * cellH,
    w: cellW,
    h: cellH,
  }));
}

export default function StockHeatmap() {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const [stocks, setStocks] = useState<StockCell[]>(() => generateInitialData());
  const [view, setView] = useState<ViewTransform>({
    scale: 1,
    offsetX: 0,
    offsetY: 0,
  });
  const [hovered, setHovered] = useState<StockCell | null>(null);
  const [isPanning, setIsPanning] = useState(false);
  const panStart = useRef<{ x: number; y: number; ox: number; oy: number } | null>(null);

  const viewportWidth = 1200;
  const viewportHeight = 700;

  const laidOutStocks = useMemo(() => {
    return layoutGrid(stocks, viewportWidth, viewportHeight);
  }, [stocks]);

  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prev) => updatePrices(prev));
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const handleWheel = (e: React.WheelEvent<SVGSVGElement>) => {
    e.preventDefault();

    const zoomFactor = e.deltaY > 0 ? 0.92 : 1.08;
    const nextScale = Math.max(0.5, Math.min(4, view.scale * zoomFactor));

    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return;

    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Zoom around cursor
    const worldX = (mouseX - view.offsetX) / view.scale;
    const worldY = (mouseY - view.offsetY) / view.scale;

    const nextOffsetX = mouseX - worldX * nextScale;
    const nextOffsetY = mouseY - worldY * nextScale;

    setView({
      scale: nextScale,
      offsetX: nextOffsetX,
      offsetY: nextOffsetY,
    });
  };

  const handleMouseDown = (e: React.MouseEvent<SVGSVGElement>) => {
    setIsPanning(true);
    panStart.current = {
      x: e.clientX,
      y: e.clientY,
      ox: view.offsetX,
      oy: view.offsetY,
    };
  };

  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (isPanning && panStart.current) {
      const dx = e.clientX - panStart.current.x;
      const dy = e.clientY - panStart.current.y;

      setView((prev) => ({
        ...prev,
        offsetX: panStart.current!.ox + dx,
        offsetY: panStart.current!.oy + dy,
      }));
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    panStart.current = null;
  };

  const resetView = () => {
    setView({ scale: 1, offsetX: 0, offsetY: 0 });
  };

  return (
    <div style={{ fontFamily: "sans-serif", color: "#e5e7eb", background: "#0b1220", padding: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <div>
          <h2 style={{ margin: 0 }}>Stock Price Heatmap</h2>
          <div style={{ fontSize: 13, color: "#9ca3af" }}>
            Drag to pan • Wheel to zoom • Hover for details
          </div>
        </div>
        <button
          onClick={resetView}
          style={{
            background: "#1f2937",
            color: "white",
            border: "1px solid #374151",
            padding: "8px 12px",
            borderRadius: 8,
            cursor: "pointer",
          }}
        >
          Reset View
        </button>
      </div>

      <div style={{ position: "relative", width: "100%", height: 700, borderRadius: 12, overflow: "hidden", border: "1px solid #1f2937" }}>
        <svg
          ref={svgRef}
          width="100%"
          height="100%"
          viewBox={`0 0 ${viewportWidth} ${viewportHeight}`}
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          style={{ background: "#111827", cursor: isPanning ? "grabbing" : "grab" }}
        >
          <g transform={`translate(${view.offsetX}, ${view.offsetY}) scale(${view.scale})`}>
            {laidOutStocks.map((stock) => (
              <g
                key={stock.symbol}
                onMouseEnter={() => setHovered(stock)}
                onMouseLeave={() => setHovered(null)}
              >
                <rect
                  x={stock.x + 4}
                  y={stock.y + 4}
                  width={stock.w - 8}
                  height={stock.h - 8}
                  rx={10}
                  ry={10}
                  fill={getHeatColor(stock.changePct)}
                  stroke="#0f172a"
                  strokeWidth={2}
                />
                <text
                  x={stock.x + stock.w / 2}
                  y={stock.y + stock.h / 2 - 8}
                  textAnchor="middle"
                  fill="white"
                  fontSize={18}
                  fontWeight={700}
                  pointerEvents="none"
                >
                  {stock.symbol}
                </text>
                <text
                  x={stock.x + stock.w / 2}
                  y={stock.y + stock.h / 2 + 16}
                  textAnchor="middle"
                  fill="rgba(255,255,255,0.85)"
                  fontSize={13}
                  pointerEvents="none"
                >
                  {stock.changePct >= 0 ? "+" : ""}
                  {stock.changePct.toFixed(2)}%
                </text>
              </g>
            ))}
          </g>
        </svg>

        {hovered && (
          <div
            style={{
              position: "absolute",
              top: 16,
              left: 16,
              background: "rgba(17, 24, 39, 0.95)",
              border: "1px solid #374151",
              borderRadius: 10,
              padding: "10px 12px",
              color: "white",
              pointerEvents: "none",
              minWidth: 180,
              boxShadow: "0 8px 24px rgba(0,0,0,0.35)",
            }}
          >
            <div style={{ fontWeight: 700, fontSize: 16 }}>{hovered.symbol}</div>
            <div style={{ fontSize: 13, color: "#9ca3af" }}>{hovered.name}</div>
            <div style={{ marginTop: 8, fontSize: 14 }}>
              <div>Sector: {hovered.sector}</div>
              <div>Price: ${hovered.price.toFixed(2)}</div>
              <div>
                Change:{" "}
                <span style={{ color: hovered.changePct >= 0 ? "#4ade80" : "#f87171" }}>
                  {hovered.changePct >= 0 ? "+" : ""}
                  {hovered.changePct.toFixed(2)}%
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
```

