      font-weight: 600;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="topbar">
      <div class="title">
        <h1>Interactive Stock Price Heatmap</h1>
        <div class="sub">Real-time simulated updates · Zoom with wheel · Pan by drag · Hover for details</div>
      </div>
      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <button id="pauseBtn">Pause Updates</button>
        <div class="legend">
          <span>Loss</span>
          <div class="legend-bar"></div>
          <span>Gain</span>
        </div>
        <div class="status" id="status">Updating...</div>
      </div>
    </div>

    <div class="main">
      <div class="chart-wrap">
        <svg id="chart" viewBox="0 0 1200 700" aria-label="Stock heatmap chart">
          <defs>
            <clipPath id="plotClip">
              <rect x="120" y="40" width="1030" height="600" rx="8" ry="8"></rect>
            </clipPath>
          </defs>

          <!-- Static frame -->
          <rect x="120" y="40" width="1030" height="600" rx="8" ry="8"
                fill="rgba(255,255,255,0.02)" stroke="rgba(255,255,255,0.12)" />

          <!-- Plot content -->
          <g id="plot" clip-path="url(#plotClip)"></g>

          <!-- Axes labels -->
          <g id="axes"></g>
        </svg>
      </div>
      <div id="tooltip" class="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = document.getElementById('chart');
    const plot = document.getElementById('plot');
    const axes = document.getElementById('axes');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    const W = 1200, H = 700;
    const margin = { top: 40, right: 40, bottom: 60, left: 120 };
    const plotArea = {
      x: margin.left,
      y: margin.top,
      w: W - margin.left - margin.right,
      h: H - margin.top - margin.bottom
    };

    const rows = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD',
      'INTC','NFLX','ORCL','CRM','UBER','SHOP','ADBE','QCOM'
    ];
    const cols = 24;

    const cellW = plotArea.w / cols;
    const cellH = plotArea.h / rows.length;

    // Simulated data: each row is a stock, each col is a time bucket.
    const data = rows.map((symbol, r) => {
      const base = 80 + Math.random() * 220;
      return {
        symbol,
        base,
        prices: Array.from({ length: cols }, (_, c) => base + Math.sin((r + c) / 3) * 4 + (Math.random() - 0.5) * 8)
      };
    });

    let paused = false;

    // View transform for zoom/pan
    let view = {
      x: 0,
      y: 0,
      scale: 1
    };

    const minScale = 0.8;
    const maxScale = 4;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(delta) {
      // delta is percentage change around 0
      const maxAbs = 8; // +/- 8% maps to extremes
      const t = clamp((delta + maxAbs) / (2 * maxAbs), 0, 1);

      // Red -> dark -> green
      const r1 = [216, 76, 76];
      const r2 = [42, 53, 95];
      const r3 = [77, 201, 107];

      let c;
      if (t < 0.5) {
        const u = t / 0.5;
        c = r1.map((v, i) => Math.round(v + (r2[i] - v) * u));
      } else {
        const u = (t - 0.5) / 0.5;
        c = r2.map((v, i) => Math.round(v + (r3[i] - v) * u));
      }
      return `rgb(${c[0]},${c[1]},${c[2]})`;
    }

    function computeDelta(prev, curr) {
      return ((curr - prev) / prev) * 100;
    }

    function renderAxes() {
      axes.innerHTML = '';

      // Row labels
      rows.forEach((symbol, r) => {
        const y = plotArea.y + r * cellH + cellH / 2 + 4;
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', 20);
        text.setAttribute('y', y);
        text.setAttribute('class', 'axis-label');
        text.textContent = symbol;
        axes.appendChild(text);
      });

      // Column labels
      for (let c = 0; c < cols; c += 3) {
        const x = plotArea.x + c * cellW + cellW / 2;
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', x);
        text.setAttribute('y', H - 18);
        text.setAttribute('text-anchor', 'middle');
        text.setAttribute('class', 'axis-label');
        text.textContent = `${c}:00`;
        axes.appendChild(text);
      }

      // Title labels
      const xLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      xLabel.setAttribute('x', plotArea.x + plotArea.w / 2);
      xLabel.setAttribute('y', 24);
      xLabel.setAttribute('text-anchor', 'middle');
      xLabel.setAttribute('class', 'header-text');
      xLabel.textContent = 'Time';
      axes.appendChild(xLabel);

      const yLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      yLabel.setAttribute('x', 20);
      yLabel.setAttribute('y', plotArea.y - 12);
      yLabel.setAttribute('class', 'header-text');
      yLabel.textContent = 'Stocks';
      axes.appendChild(yLabel);
    }

    function renderGrid() {
      plot.innerHTML = '';

      // Grid lines
      for (let c = 0; c <= cols; c++) {
        const x = plotArea.x + c * cellW;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('y1', plotArea.y);
        line.setAttribute('x2', x);
        line.setAttribute('y2', plotArea.y + plotArea.h);
        line.setAttribute('class', 'grid-line');
        plot.appendChild(line);
      }
      for (let r = 0; r <= rows.length; r++) {
        const y = plotArea.y + r * cellH;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', plotArea.x);
        line.setAttribute('y1', y);
        line.setAttribute('x2', plotArea.x + plotArea.w);
        line.setAttribute('y2', y);
        line.setAttribute('class', 'grid-line');
        plot.appendChild(line);
      }

      // Cells
      data.forEach((row, r) => {
        for (let c = 0; c < cols; c++) {
          const price = row.prices[c];
          const prev = c === 0 ? row.base : row.prices[c - 1];
          const delta = computeDelta(prev, price);

          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', plotArea.x + c * cellW + 1);
          rect.setAttribute('y', plotArea.y + r * cellH + 1);
          rect.setAttribute('width', cellW - 2);
          rect.setAttribute('height', cellH - 2);
          rect.setAttribute('fill', priceToColor(delta));
          rect.setAttribute('class', 'cell');
          rect.dataset.symbol = row.symbol;
          rect.dataset.col = c;
          rect.dataset.price = price.toFixed(2);
          rect.dataset.delta = delta.toFixed(2);
          rect.dataset.time = `${c}:00`;

          rect.addEventListener('mousemove', onCellMove);
          rect.addEventListener('mouseenter', onCellEnter);
          rect.addEventListener('mouseleave', onCellLeave);

          plot.appendChild(rect);
        }
      });

      applyViewTransform();
    }

    function applyViewTransform() {
      // Use SVG viewBox for zoom/pan
      const baseW = W;
      const baseH = H;

      const scaledW = baseW / view.scale;
      const scaledH = baseH / view.scale;

      const maxX = baseW - scaledW;
      const maxY = baseH - scaledH;

      view.x = clamp(view.x, 0, Math.max(0, maxX));
      view.y = clamp(view.y, 0, Math.max(0, maxY));

      svg.setAttribute('viewBox', `${view.x} ${view.y} ${scaledW} ${scaledH}`);
    }

    function resetView() {
      view = { x: 0, y: 0, scale: 1 };
      applyViewTransform();
    }

    function onCellEnter(e) {
      tooltip.classList.add('visible');
      updateTooltip(e);
    }

    function onCellMove(e) {
      updateTooltip(e);
    }

    function onCellLeave() {
      tooltip.classList.remove('visible');
    }

    function updateTooltip(e) {
      const target = e.currentTarget;
      const symbol = target.dataset.symbol;
      const time = target.dataset.time;
      const price = Number(target.dataset.price);
      const delta = Number(target.dataset.delta);

      tooltip.innerHTML = `
        <strong>${symbol}</strong><br/>
        Time: ${time}<br/>
        Price: $${price.toFixed(2)}<br/>
        Change: <span style="color:${delta >= 0 ? '#4dc96b' : '#ff7b7b'}">${delta >= 0 ? '+' : ''}${delta.toFixed(2)}%</span>
      `;

      const rect = svg.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    // Zoom with wheel
    svg.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.12 : 0.89;
      const newScale = clamp(view.scale * zoomFactor, minScale, maxScale);

      const rect = svg.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Convert mouse position to world coords
      const worldX = view.x + (mouseX / rect.width) * (W / view.scale);
      const worldY = view.y + (mouseY / rect.height) * (H / view.scale);

      view.scale = newScale;

      const newScaledW = W / view.scale;
      const newScaledH = H / view.scale;

      view.x = worldX - (mouseX / rect.width) * newScaledW;
      view.y = worldY - (mouseY / rect.height) * newScaledH;

      applyViewTransform();
    }, { passive: false });

    // Pan with drag
    let dragging = false;
    let dragStart = null;

    svg.addEventListener('pointerdown', (e) => {
      dragging = true;
      dragStart = {
        x: e.clientX,
        y: e.clientY,
        viewX: view.x,
        viewY: view.y
      };
      svg.setPointerCapture(e.pointerId);
    });

    svg.addEventListener('pointermove', (e) => {
      if (!dragging || !dragStart) return;

      const rect = svg.getBoundingClientRect();
      const dx = (e.clientX - dragStart.x) / rect.width * (W / view.scale);
      const dy = (e.clientY - dragStart.y) / rect.height * (H / view.scale);

      view.x = dragStart.viewX - dx;
      view.y = dragStart.viewY - dy;
      applyViewTransform();
    });

    svg.addEventListener('pointerup', () => {
      dragging = false;
      dragStart = null;
    });

    svg.addEventListener('pointercancel', () => {
      dragging = false;
      dragStart = null;
    });

    resetBtn.addEventListener('click', resetView);

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume Updates' : 'Pause Updates';
      statusEl.textContent = paused ? 'Updates paused' : 'Updating...';
    });

    function tick() {
      if (!paused) {
        // Simulate a new price update in the last column and shift left.
        data.forEach(row => {
          const last = row.prices[row.prices.length - 1];
          const drift = (Math.random() - 0.48) * 3.5;
          const next = Math.max(1, last + drift);

          row.prices.shift();
          row.prices.push(next);
        });

        renderGrid();
        statusEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;
      }
    }

    // Initial render
    renderAxes();
    renderGrid();
    statusEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;

    // Real-time updates
    setInterval(tick, 1000);

    // Resize handling: keep view stable
    window.addEventListener('resize', () => {
      applyViewTransform();
    });
  </script>
</body>
</html>
```

