<body>
  <div class="app">
    <header>
      <h1>Stock Price Heatmap</h1>
      <p>Interactive client-side prototype with real-time updates, zoom, and pan.</p>
    </header>

    <div class="toolbar">
      <button id="resetZoom">Reset Zoom</button>
      <button id="toggleStream">Pause Updates</button>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <div class="status" id="status">Streaming: on</div>
    </div>

    <div class="main">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const width = () => svg.node().clientWidth;
    const height = () => svg.node().clientHeight;

    const margin = { top: 40, right: 20, bottom: 20, left: 90 };
    const cellW = 36;
    const cellH = 24;

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "TSLA", "META", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "ADBE", "QCOM", "AVGO"
    ];

    const maxPoints = 60;
    let streaming = true;

    // Data: each column is a time point, each row is a symbol
    let series = [];
    let currentPrices = new Map(symbols.map(s => [s, 100 + Math.random() * 50]));

    function nowLabel() {
      const d = new Date();
      return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function generateTick() {
      const timestamp = nowLabel();
      const column = symbols.map(symbol => {
        const prev = currentPrices.get(symbol);
        const change = (Math.random() - 0.5) * 2.5; // small random movement
        const next = Math.max(1, prev + change);
        currentPrices.set(symbol, next);

        const pct = ((next - prev) / prev) * 100;
        return {
          symbol,
          price: next,
          changePct: pct,
          timestamp
        };
      });

      series.push(column);
      if (series.length > maxPoints) series.shift();
    }

    // Seed initial data
    for (let i = 0; i < maxPoints; i++) generateTick();

    const color = d3.scaleSequential()
      .domain([-2, 2])
      .interpolator(d3.interpolateRdYlGn);

    const xScale = d3.scaleBand().padding(0.08);
    const yScale = d3.scaleBand().padding(0.08);

    const zoomLayer = svg.append("g").attr("class", "zoom-layer");
    const gridLayer = zoomLayer.append("g").attr("class", "grid-layer");
    const axisLayer = zoomLayer.append("g").attr("class", "axis-layer");

    const zoom = d3.zoom()
      .scaleExtent([0.5, 8])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    function render() {
      const w = width();
      const h = height();

      svg.attr("viewBox", [0, 0, w, h]);

      const innerW = w - margin.left - margin.right;
      const innerH = h - margin.top - margin.bottom;

      xScale.domain(d3.range(series.length)).range([margin.left, margin.left + innerW]);
      yScale.domain(symbols).range([margin.top, margin.top + innerH]);

      const flatData = [];
      series.forEach((col, x) => {
        col.forEach(d => flatData.push({ ...d, xIndex: x }));
      });

      const cells = gridLayer.selectAll("rect.cell")
        .data(flatData, d => `${d.symbol}-${d.xIndex}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.xIndex))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("rx", 4)
        .attr("ry", 4)
        .attr("fill", d => color(d.changePct))
        .on("mousemove", (event, d) => {
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Price: ${d.price.toFixed(2)}<br/>
            Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%<br/>
            Time: ${d.timestamp}
          `;
          const rect = svg.node().getBoundingClientRect();
          tooltip.style.left = `${event.clientX - rect.left + 12}px`;
          tooltip.style.top = `${event.clientY - rect.top + 12}px`;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cells.transition()
        .duration(300)
        .attr("x", d => xScale(d.xIndex))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => color(d.changePct));

      cells.exit().remove();

      // Symbol labels
      const labels = axisLayer.selectAll("text.axis-label")
        .data(symbols, d => d);

      labels.enter()
        .append("text")
        .attr("class", "axis-label")
        .attr("x", 12)
        .attr("y", d => yScale(d) + yScale.bandwidth() / 2 + 4)
        .text(d => d);

      labels
        .attr("x", 12)
        .attr("y", d => yScale(d) + yScale.bandwidth() / 2 + 4);

      labels.exit().remove();

      // Time labels every 5 columns
      const timeTicks = series
        .map((col, i) => ({ i, t: col[0]?.timestamp }))
        .filter(d => d.i % 5 === 0);

      const times = axisLayer.selectAll("text.time-label")
        .data(timeTicks, d => d.i);

      times.enter()
        .append("text")
        .attr("class", "time-label")
        .attr("transform", d => `translate(${xScale(d.i) + xScale.bandwidth() / 2}, ${margin.top - 10}) rotate(-45)`)
        .text(d => d.t);

      times
        .attr("transform", d => `translate(${xScale(d.i) + xScale.bandwidth() / 2}, ${margin.top - 10}) rotate(-45)`)
        .text(d => d.t);

      times.exit().remove();
    }

    function tick() {
      if (streaming) {
        generateTick();
        render();
      }
    }

    // Initial render
    render();

    // Update every second
    setInterval(tick, 1000);

    // Resize handling
    window.addEventListener("resize", render);

    // Controls
    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("toggleStream").addEventListener("click", (e) => {
      streaming = !streaming;
      e.target.textContent = streaming ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = `Streaming: ${streaming ? "on" : "paused"}`;
    });
  </script>
</body>
</html>
