      border: 1px solid rgba(148, 163, 184, 0.15);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.5;
      backdrop-filter: blur(8px);
      z-index: 5;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 6px;
    }

    .legend-bar {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #dc2626, #111827, #16a34a);
      border: 1px solid rgba(255,255,255,0.08);
    }

    .hint {
      opacity: 0.8;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="canvas"></canvas>
    <div class="hud">
      <div><strong>Stock Heatmap</strong></div>
      <div class="hint">Wheel = zoom, drag = pan</div>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
    </div>
    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const app = document.getElementById('app');
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    // View transform
    const view = {
      scale: 1,
      offsetX: 20,
      offsetY: 20
    };

    // Heatmap grid config
    const grid = {
      cols: 12,
      cellW: 110,
      cellH: 72,
      gap: 8
    };

    // Example stock universe
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','NFLX','INTC',
      'ORCL','CRM','UBER','BABA','JPM','BAC','XOM','CVX','KO','PEP',
      'DIS','WMT','COST','QCOM','AVGO','ADBE','PYPL','SHOP','SNOW','PLTR',
      'BA','GE','T','VZ','NKE','PFE','MRK','LLY','UNH','GS',
      'MS','CAT','IBM','SPOT','SQ','NOW','ZS','PANW','INTU','TXN'
    ];

    const stocks = symbols.map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 450,
      changePct: (Math.random() - 0.5) * 6,
      volume: Math.floor(1e6 + Math.random() * 9e6),
      row: Math.floor(i / grid.cols),
      col: i % grid.cols
    }));

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = canvas.clientWidth = app.clientWidth;
      height = canvas.clientHeight = app.clientHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      draw();
    }

    window.addEventListener('resize', resize);

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function colorForChange(pct) {
      // Clamp to [-5, 5]
      const x = clamp(pct, -5, 5) / 5;

      // Negative: red -> dark
      // Positive: dark -> green
      if (x < 0) {
        const t = -x;
        return {
          r: Math.round(220 * t + 17 * (1 - t)),
          g: Math.round(38 * t + 24 * (1 - t)),
          b: Math.round(38 * t + 39 * (1 - t))
        };
      } else {
        const t = x;
        return {
          r: Math.round(22 * t + 17 * (1 - t)),
          g: Math.round(163 * t + 24 * (1 - t)),
          b: Math.round(74 * t + 39 * (1 - t))
        };
      }
    }

    function stockRect(stock) {
      const x = stock.col * (grid.cellW + grid.gap);
      const y = stock.row * (grid.cellH + grid.gap);
      return { x, y, w: grid.cellW, h: grid.cellH };
    }

    function worldToScreen(x, y) {
      return {
        x: x * view.scale + view.offsetX,
        y: y * view.scale + view.offsetY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - view.offsetX) / view.scale,
        y: (y - view.offsetY) / view.scale
      };
    }

    function drawRoundedRect(x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      // Determine visible area for culling
      const worldTopLeft = screenToWorld(0, 0);
      const worldBottomRight = screenToWorld(width, height);

      const visible = stocks.filter(stock => {
        const r = stockRect(stock);
        return r.x + r.w >= worldTopLeft.x - 50 &&
               r.y + r.h >= worldTopLeft.y - 50 &&
               r.x <= worldBottomRight.x + 50 &&
               r.y <= worldBottomRight.y + 50;
      });

      // Draw cells
      for (const stock of visible) {
        const r = stockRect(stock);
        const s = worldToScreen(r.x, r.y);
        const sw = r.w * view.scale;
        const sh = r.h * view.scale;
        const gap = grid.gap * view.scale;

        const c = colorForChange(stock.changePct);
        const fill = `rgb(${c.r}, ${c.g}, ${c.b})`;

        ctx.fillStyle = fill;
        drawRoundedRect(s.x, s.y, sw, sh, 10 * view.scale);
        ctx.fill();

        // Border
        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = Math.max(1, 1 * view.scale);
        ctx.stroke();

        // Text
        const fontSize = Math.max(10, 14 * view.scale);
        if (fontSize >= 10) {
          ctx.fillStyle = 'rgba(255,255,255,0.95)';
          ctx.font = `600 ${fontSize}px system-ui, sans-serif`;
          ctx.textBaseline = 'top';
          ctx.fillText(stock.symbol, s.x + 10 * view.scale, s.y + 8 * view.scale);

          ctx.font = `500 ${Math.max(9, 12 * view.scale)}px system-ui, sans-serif`;
          ctx.fillStyle = 'rgba(255,255,255,0.88)';
          ctx.fillText(`$${stock.price.toFixed(2)}`, s.x + 10 * view.scale, s.y + 28 * view.scale);

          const pct = `${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%`;
          ctx.fillStyle = stock.changePct >= 0 ? 'rgba(187, 247, 208, 0.95)' : 'rgba(254, 202, 202, 0.95)';
          ctx.fillText(pct, s.x + 10 * view.scale, s.y + 46 * view.scale);
        }
      }
    }

    // Interaction state
    let dragging = false;
    let dragStart = null;
    let lastPointer = null;

    function getPointerPos(evt) {
      const rect = canvas.getBoundingClientRect();
      return {
        x: evt.clientX - rect.left,
        y: evt.clientY - rect.top
      };
    }

    function findStockAtScreen(x, y) {
      const p = screenToWorld(x, y);
      for (const stock of stocks) {
        const r = stockRect(stock);
        if (p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h) {
          return stock;
        }
      }
      return null;
    }

    canvas.addEventListener('pointerdown', (e) => {
      dragging = true;
      app.classList.add('dragging');
      canvas.setPointerCapture(e.pointerId);
      dragStart = getPointerPos(e);
      lastPointer = dragStart;
    });

    canvas.addEventListener('pointermove', (e) => {
      const p = getPointerPos(e);

      if (dragging && lastPointer) {
        const dx = p.x - lastPointer.x;
        const dy = p.y - lastPointer.y;
        view.offsetX += dx;
        view.offsetY += dy;
        lastPointer = p;
        draw();
      }

      const stock = findStockAtScreen(p.x, p.y);
      if (stock) {
        const rect = canvas.getBoundingClientRect();
        tooltip.style.display = 'block';
        tooltip.style.left = `${e.clientX - rect.left}px`;
        tooltip.style.top = `${e.clientY - rect.top}px`;
        tooltip.innerHTML = `
          <div><strong>${stock.symbol}</strong></div>
          <div>Price: $${stock.price.toFixed(2)}</div>
          <div>Change: <span style="color:${stock.changePct >= 0 ? '#86efac' : '#fca5a5'}">
            ${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%
          </span></div>
          <div>Volume: ${stock.volume.toLocaleString()}</div>
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('pointerup', (e) => {
      dragging = false;
      app.classList.remove('dragging');
      try { canvas.releasePointerCapture(e.pointerId); } catch {}
    });

    canvas.addEventListener('pointerleave', () => {
      tooltip.style.display = 'none';
      dragging = false;
      app.classList.remove('dragging');
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const mouse = getPointerPos(e);
      const worldBefore = screenToWorld(mouse.x, mouse.y);

      const zoomFactor = Math.exp(-e.deltaY * 0.0015);
      const nextScale = clamp(view.scale * zoomFactor, 0.4, 3.5);

      view.scale = nextScale;

      const worldAfter = worldBefore;
      view.offsetX = mouse.x - worldAfter.x * view.scale;
      view.offsetY = mouse.y - worldAfter.y * view.scale;

      draw();
    }, { passive: false });

    // Simulated real-time updates
    function updateStocks() {
      for (const stock of stocks) {
        const delta = (Math.random() - 0.5) * 2.2;
        stock.changePct = clamp(stock.changePct + delta * 0.15, -8, 8);
        stock.price = Math.max(1, stock.price * (1 + delta / 100));

        // volume fluctuation
        stock.volume = Math.max(0, stock.volume + Math.floor((Math.random() - 0.5) * 250000));
      }
      draw();
    }

    setInterval(updateStocks, 1000);

    // Initial layout
    resize();

    // Center content initially
    function centerView() {
      const totalCols = grid.cols;
      const totalRows = Math.ceil(stocks.length / grid.cols);
      const contentW = totalCols * grid.cellW + (totalCols - 1) * grid.gap;
      const contentH = totalRows * grid.cellH + (totalRows - 1) * grid.gap;

      view.scale = 1;
      view.offsetX = Math.max(20, (width - contentW) / 2);
      view.offsetY = Math.max(80, (height - contentH) / 2);
      draw();
    }

    centerView();
  </script>
</body>
</html>
