## Example implementation

### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useRef, useState, useMemo } from "react";

type StockRow = {
  symbol: string;
  values: number[]; // percent change values over time
};

type Viewport = {
  zoom: number;
  panX: number;
  panY: number;
};

type TooltipState = {
  visible: boolean;
  x: number;
  y: number;
  symbol: string;
  timeIndex: number;
  value: number;
};

const STOCKS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
  "TSLA", "META", "NFLX", "AMD", "INTC",
  "ORCL", "CRM", "ADBE", "QCOM", "IBM",
];

const TIME_BUCKETS = 60;
const CELL_WIDTH = 28;
const CELL_HEIGHT = 22;

function clamp(v: number, min: number, max: number) {
  return Math.max(min, Math.min(max, v));
}

function valueToColor(value: number) {
  // value is percent change, roughly -5 to +5
  const v = clamp(value, -5, 5);
  if (v < 0) {
    const intensity = Math.abs(v) / 5;
    const r = 220;
    const g = Math.round(220 * (1 - intensity));
    const b = Math.round(220 * (1 - intensity));
    return `rgb(${r},${g},${b})`;
  } else {
    const intensity = v / 5;
    const r = Math.round(220 * (1 - intensity));
    const g = 220;
    const b = Math.round(220 * (1 - intensity));
    return `rgb(${r},${g},${b})`;
  }
}

function generateInitialData(): StockRow[] {
  return STOCKS.map((symbol) => ({
    symbol,
    values: Array.from({ length: TIME_BUCKETS }, () => (Math.random() - 0.5) * 4),
  }));
}

function updateData(prev: StockRow[]): StockRow[] {
  return prev.map((row) => {
    const last = row.values[row.values.length - 1];
    const next = clamp(last + (Math.random() - 0.5) * 0.8, -8, 8);
    return {
      symbol: row.symbol,
      values: [...row.values.slice(1), next],
    };
  });
}

export default function StockHeatmap() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const [data, setData] = useState<StockRow[]>(() => generateInitialData());
  const [viewport, setViewport] = useState<Viewport>({
    zoom: 1,
    panX: 0,
    panY: 0,
  });
  const [tooltip, setTooltip] = useState<TooltipState>({
    visible: false,
    x: 0,
    y: 0,
    symbol: "",
    timeIndex: 0,
    value: 0,
  });

  const gridWidth = STOCKS.length * CELL_WIDTH;
  const gridHeight = TIME_BUCKETS * CELL_HEIGHT;

  const draw = useMemo(() => {
    return () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, rect.width, rect.height);

      ctx.save();
      ctx.translate(viewport.panX, viewport.panY);
      ctx.scale(viewport.zoom, viewport.zoom);

      // Background
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, gridWidth, gridHeight);

      // Draw cells
      for (let rowIndex = 0; rowIndex < data.length; rowIndex++) {
        const row = data[rowIndex];
        for (let colIndex = 0; colIndex < row.values.length; colIndex++) {
          const value = row.values[colIndex];
          ctx.fillStyle = valueToColor(value);
          ctx.fillRect(
            rowIndex * CELL_WIDTH,
            colIndex * CELL_HEIGHT,
            CELL_WIDTH - 1,
            CELL_HEIGHT - 1
          );
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1 / viewport.zoom;

      for (let i = 0; i <= data.length; i++) {
        ctx.beginPath();
        ctx.moveTo(i * CELL_WIDTH, 0);
        ctx.lineTo(i * CELL_WIDTH, gridHeight);
        ctx.stroke();
      }

      for (let j = 0; j <= TIME_BUCKETS; j++) {
        ctx.beginPath();
        ctx.moveTo(0, j * CELL_HEIGHT);
        ctx.lineTo(gridWidth, j * CELL_HEIGHT);
        ctx.stroke();
      }

      // Labels
      ctx.fillStyle = "#cbd5e1";
      ctx.font = `${12 / viewport.zoom}px sans-serif`;
      ctx.textBaseline = "middle";

      for (let i = 0; i < data.length; i++) {
        ctx.fillText(data[i].symbol, i * CELL_WIDTH + 4, 12);
      }

      ctx.restore();
    };
  }, [data, viewport, gridWidth, gridHeight]);

  useEffect(() => {
    draw();
  }, [draw]);

  useEffect(() => {
    const interval = setInterval(() => {
      setData((prev) => updateData(prev));
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    const getMousePos = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      };
    };

    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newZoom = clamp(viewport.zoom * zoomFactor, 0.5, 3);

      // Zoom around mouse position
      const worldX = (mouseX - viewport.panX) / viewport.zoom;
      const worldY = (mouseY - viewport.panY) / viewport.zoom;

      const newPanX = mouseX - worldX * newZoom;
      const newPanY = mouseY - worldY * newZoom;

      setViewport({
        zoom: newZoom,
        panX: newPanX,
        panY: newPanY,
      });
    };

    const onMouseDown = (e: MouseEvent) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    };

    const onMouseMove = (e: MouseEvent) => {
      const pos = getMousePos(e);

      if (isDragging) {
        const dx = e.clientX - lastX;
        const dy = e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;

        setViewport((prev) => ({
          ...prev,
          panX: prev.panX + dx,
          panY: prev.panY + dy,
        }));
        return;
      }

      // Tooltip hit test
      const worldX = (pos.x - viewport.panX) / viewport.zoom;
      const worldY = (pos.y - viewport.panY) / viewport.zoom;

      const rowIndex = Math.floor(worldX / CELL_WIDTH);
      const colIndex = Math.floor(worldY / CELL_HEIGHT);

      if (
        rowIndex >= 0 &&
        rowIndex < data.length &&
        colIndex >= 0 &&
        colIndex < TIME_BUCKETS
      ) {
        setTooltip({
          visible: true,
          x: e.clientX,
          y: e.clientY,
          symbol: data[rowIndex].symbol,
          timeIndex: colIndex,
          value: data[rowIndex].values[colIndex],
        });
      } else {
        setTooltip((t) => ({ ...t, visible: false }));
      }
    };

    const onMouseUp = () => {
      isDragging = false;
    };

    const onMouseLeave = () => {
      isDragging = false;
      setTooltip((t) => ({ ...t, visible: false }));
    };

    canvas.addEventListener("wheel", onWheel, { passive: false });
    canvas.addEventListener("mousedown", onMouseDown);
    canvas.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
    canvas.addEventListener("mouseleave", onMouseLeave);

    return () => {
      canvas.removeEventListener("wheel", onWheel);
      canvas.removeEventListener("mousedown", onMouseDown);
      canvas.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
      canvas.removeEventListener("mouseleave", onMouseLeave);
    };
  }, [viewport, data]);

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        height: "100vh",
        background: "#020617",
        color: "white",
