  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="stat" id="status">Live updates: on</div>
      <div class="stat" id="zoomStatus">Zoom: 100%</div>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
    </div>

    <div class="viewport" id="viewport">
      <svg id="svg" viewBox="0 0 1200 800" preserveAspectRatio="none">
        <g id="world"></g>
      </svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = document.getElementById("svg");
    const world = document.getElementById("world");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const zoomStatus = document.getElementById("zoomStatus");

    const W = 1200;
    const H = 800;

    // --- Demo stock universe ---
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
      "ORCL","CRM","ADBE","QCOM","AVGO","IBM","UBER","SHOP","SNOW","PLTR",
      "JPM","BAC","GS","MS","C","WFC","V","MA","AXP","PYPL",
      "XOM","CVX","COP","SLB","OXY","BP","TTE","SHEL","EOG","MPC"
    ];

    const stocks = symbols.map((symbol, i) => ({
      symbol,
      name: symbol,
      price: 50 + Math.random() * 450,
      prevClose: 50 + Math.random() * 450,
      volume: Math.floor(100000 + Math.random() * 900000),
      sector: ["Tech", "Finance", "Energy", "Consumer"][i % 4]
    }));

    // --- Layout ---
    const cols = 8;
    const rows = Math.ceil(stocks.length / cols);
    const pad = 24;
    const gap = 14;
    const cellW = (W - pad * 2 - gap * (cols - 1)) / cols;
    const cellH = (H - pad * 2 - gap * (rows - 1)) / rows;

    // --- Zoom/pan state ---
    const transform = {
      x: 0,
      y: 0,
      scale: 1
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function pctChange(stock) {
      return ((stock.price - stock.prevClose) / stock.prevClose) * 100;
    }

    function colorForChange(change) {
      // Map from -10%..+10% to red->yellow->dark->green
      const c = clamp(change, -10, 10);

      if (c < -5) {
        // deep red to orange
        const t = (c + 10) / 5; // 0..1
        return lerpColor([153, 27, 27], [245, 158, 11], t);
      } else if (c < 0) {
        const t = (c + 5) / 5;
        return lerpColor([245, 158, 11], [55, 65, 81], t);
      } else if (c < 5) {
        const t = c / 5;
        return lerpColor([55, 65, 81], [34, 197, 94], t);
      } else {
        const t = (c - 5) / 5;
        return lerpColor([34, 197, 94], [22, 101, 52], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const bl = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r},${g},${bl})`;
    }

    function render() {
      world.innerHTML = "";

      stocks.forEach((stock, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = pad + col * (cellW + gap);
        const y = pad + row * (cellH + gap);
        const change = pctChange(stock);
        const fill = colorForChange(change);

        const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
        g.setAttribute("data-symbol", stock.symbol);
        g.setAttribute("data-price", stock.price.toFixed(2));
        g.setAttribute("data-change", change.toFixed(2));
        g.setAttribute("data-volume", stock.volume);

        const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        rect.setAttribute("class", "cell");
        rect.setAttribute("x", x);
        rect.setAttribute("y", y);
        rect.setAttribute("width", cellW);
        rect.setAttribute("height", cellH);
        rect.setAttribute("fill", fill);

        const symbolText = document.createElementNS("http://www.w3.org/2000/svg", "text");
        symbolText.setAttribute("class", "label");
        symbolText.setAttribute("x", x + cellW / 2);
        symbolText.setAttribute("y", y + cellH / 2 - 8);
        symbolText.textContent = stock.symbol;

        const changeText = document.createElementNS("http://www.w3.org/2000/svg", "text");
        changeText.setAttribute("class", "subtext");
        changeText.setAttribute("x", x + cellW / 2);
        changeText.setAttribute("y", y + cellH / 2 + 14);
        changeText.textContent = `${change >= 0 ? "+" : ""}${change.toFixed(2)}%`;

        g.appendChild(rect);
        g.appendChild(symbolText);
        g.appendChild(changeText);
        world.appendChild(g);

        g.addEventListener("mouseenter", (e) => {
          tooltip.classList.add("visible");
          updateTooltip(e, stock);
        });

        g.addEventListener("mousemove", (e) => updateTooltip(e, stock));

        g.addEventListener("mouseleave", () => {
          tooltip.classList.remove("visible");
        });
      });

      applyTransform();
    }

    function updateTooltip(e, stock) {
      const change = pctChange(stock);
      tooltip.innerHTML = `
        <div style="font-weight:700; margin-bottom:6px;">${stock.symbol}</div>
        <div>Price: $${stock.price.toFixed(2)}</div>
        <div>Change: <span style="color:${change >= 0 ? '#4ade80' : '#f87171'}">
          ${change >= 0 ? '+' : ''}${change.toFixed(2)}%
        </span></div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
        <div style="color:#8ea0c3; margin-top:6px;">Sector: ${stock.sector}</div>
      `;
      const rect = viewport.getBoundingClientRect();
      tooltip.style.left = `${e.clientX - rect.left}px`;
      tooltip.style.top = `${e.clientY - rect.top}px`;
    }

    function applyTransform() {
      world.setAttribute(
        "transform",
        `translate(${transform.x},${transform.y}) scale(${transform.scale})`
      );
      zoomStatus.textContent = `Zoom: ${Math.round(transform.scale * 100)}%`;
    }

    // --- Zoom with mouse wheel ---
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(transform.scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const rect = svg.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - transform.x) / transform.scale;
      const worldY = (mouseY - transform.y) / transform.scale;

      transform.scale = newScale;
      transform.x = mouseX - worldX * transform.scale;
      transform.y = mouseY - worldY * transform.scale;

      applyTransform();
    }, { passive: false });

    // --- Pan with drag ---
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let originX = 0;
    let originY = 0;

    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      originX = transform.x;
      originY = transform.y;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      transform.x = originX + (e.clientX - startX);
      transform.y = originY + (e.clientY - startY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    // --- Real-time simulation ---
    function tick() {
      stocks.forEach(stock => {
        // random walk around previous close
        const drift = (Math.random() - 0.5) * 2.2;
        stock.price = Math.max(1, stock.price + drift);

        // occasionally update prevClose to simulate session movement
        if (Math.random() < 0.01) {
          stock.prevClose = stock.price * (0.98 + Math.random() * 0.04);
        }

        // random volume changes
        stock.volume = Math.max(0, stock.volume + Math.floor((Math.random() - 0.5) * 5000));
      });

      render();
    }

    // Initial render
    render();

    // Update every second
    setInterval(tick, 1000);

    // Keep tooltip hidden on resize or when leaving viewport
    viewport.addEventListener("mouseleave", () => tooltip.classList.remove("visible"));
  </script>
</body>
</html>
