      "AMD", "INTC", "ORCL", "IBM", "CRM", "ADBE", "QCOM", "AVGO"
    ];

    const timeBuckets = 60; // columns
    const rows = stocks.length;

    // Each cell stores a percent change value
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeBuckets }, () => randomInitialChange())
    );

    function randomInitialChange() {
      return (Math.random() - 0.5) * 4; // -2% to +2%
    }

    // -----------------------------
    // Canvas setup
    // -----------------------------
    const viewport = document.getElementById("viewport");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");
    const zoomLabel = document.getElementById("zoomLabel");
    const statusLabel = document.getElementById("status");

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    // View transform
    let zoom = 1;
    let panX = 0;
    let panY = 0;

    // Interaction state
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let panStart = { x: 0, y: 0 };

    // Cell geometry cached per render
    let cellRects = [];

    function resize() {
      const rect = viewport.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener("resize", resize);

    // -----------------------------
    // Color mapping
    // -----------------------------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function hexToRgb(hex) {
      const m = hex.replace("#", "");
      return {
        r: parseInt(m.slice(0, 2), 16),
        g: parseInt(m.slice(2, 4), 16),
        b: parseInt(m.slice(4, 6), 16),
      };
    }

    function rgbToCss({ r, g, b }) {
      return `rgb(${r | 0}, ${g | 0}, ${b | 0})`;
    }

    const neg = hexToRgb("#d94b4b");
    const mid = hexToRgb("#1f2a44");
    const pos = hexToRgb("#4bd97d");

    function valueToColor(v) {
      // v is percent change in range roughly [-5, 5]
      const maxAbs = 5;
      const t = clamp((v + maxAbs) / (2 * maxAbs), 0, 1);

      let c;
      if (t < 0.5) {
        const u = t / 0.5;
        c = {
          r: lerp(neg.r, mid.r, u),
          g: lerp(neg.g, mid.g, u),
          b: lerp(neg.b, mid.b, u),
        };
      } else {
        const u = (t - 0.5) / 0.5;
        c = {
          r: lerp(mid.r, pos.r, u),
          g: lerp(mid.g, pos.g, u),
          b: lerp(mid.b, pos.b, u),
        };
      }
      return rgbToCss(c);
    }

