      cellRects = [];

      const leftPad = 90;
      const topPad = 24;
      const rowHeight = 34 * zoom;
      const colWidth = 22 * zoom;

      const x0 = leftPad + panX;
      const y0 = topPad + panY;

      // Background
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, width, height);

      // Labels
      ctx.font = "12px Inter, system-ui, sans-serif";
      ctx.textBaseline = "middle";

      // Draw row labels
      for (let r = 0; r < rows; r++) {
        const y = y0 + r * rowHeight;
        if (y + rowHeight < 0 || y > height) continue;

        ctx.fillStyle = "#e6ecff";
        ctx.fillText(stocks[r], 16, y + rowHeight / 2);
