      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeBuckets; c++) {
          const x = x0 + c * colWidth;
          const y = y0 + r * rowHeight;

          if (x + colWidth < leftPad || x > width || y + rowHeight < 0 || y > height) {
            continue;
          }

          const v = data[r][c];
          ctx.fillStyle = valueToColor(v);
          ctx.fillRect(x, y, colWidth - 1, rowHeight - 1);

          // Cache rect for hover hit testing
          cellRects.push({
            row: r,
            col: c,
            x,
            y,
            w: colWidth - 1,
            h: rowHeight - 1,
            value: v
          });
        }
      }

      // Column grid line / time axis labels
      ctx.fillStyle = "#8ea0c7";
      for (let c = 0; c < timeBuckets; c += 5) {
        const x = x0 + c * colWidth;
        if (x < leftPad || x > width) continue;
        ctx.fillText(`T-${timeBuckets - c}`, x + 2, 12);
      }

      zoomLabel.textContent = `Zoom: ${zoom.toFixed(2)}x`;
    }

    // -----------------------------
    // Real-time updates
    // -----------------------------
    function updateData() {
      // Shift left and append new values
      for (let r = 0; r < rows; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] ?? 0;
        const drift = (Math.random() - 0.5) * 1.2;
        const meanRevert = -prev * 0.15;
        const next = clamp(prev + drift + meanRevert, -8, 8);
        data[r].push(next);
      }

      statusLabel.textContent = `Live updates: on • ${new Date().toLocaleTimeString()}`;
      render();
    }

    setInterval(updateData, 1000);

    // -----------------------------
    // Interaction: pan / zoom
    // -----------------------------
    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      viewport.classList.add("dragging");
      dragStart = { x: e.clientX, y: e.clientY };
      panStart = { x: panX, y: panY };
    });

    window.addEventListener("mousemove", (e) => {
      if (isDragging) {
        panX = panStart.x + (e.clientX - dragStart.x);
        panY = panStart.y + (e.clientY - dragStart.y);
        render();
      }

      // Tooltip hover
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const hit = cellRects.find(cell =>
        mx >= cell.x && mx <= cell.x + cell.w &&
        my >= cell.y && my <= cell.y + cell.h
      );

      if (hit) {
        tooltip.style.display = "block";
        tooltip.style.left = `${mx}px`;
        tooltip.style.top = `${my}px`;
        tooltip.innerHTML = `
          <strong>${stocks[hit.row]}</strong><br/>
          Bucket: ${hit.col}<br/>
          Change: ${hit.value.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = "none";
      }
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newZoom = clamp(zoom * zoomFactor, 0.5, 4);

      // Zoom around mouse position
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldX = (mx - 90 - panX) / zoom;
      const worldY = (my - 24 - panY) / zoom;

      zoom = newZoom;

      panX = mx - 90 - worldX * zoom;
      panY = my - 24 - worldY * zoom;

      render();
    }, { passive: false });

    // Touch support: basic pinch-less pan
    let touchStart = null;
    viewport.addEventListener("touchstart", (e) => {
      if (e.touches.length === 1) {
        touchStart = {
          x: e.touches[0].clientX,
          y: e.touches[0].clientY,
          panX,
          panY
        };
      }
    }, { passive: true });

    viewport.addEventListener("touchmove", (e) => {
      if (touchStart && e.touches.length === 1) {
        e.preventDefault();
        panX = touchStart.panX + (e.touches[0].clientX - touchStart.x);
        panY = touchStart.panY + (e.touches[0].clientY - touchStart.y);
        render();
      }
    }, { passive: false });

    viewport.addEventListener("touchend", () => {
      touchStart = null;
    });

    // -----------------------------
    // Init
    // -----------------------------
    resize();
    render();
  </script>
</body>
</html>
```

