export type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  volume: number;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
};

export function getColorForChange(changePct: number): string {
  // Red for negative, green for positive, neutral around 0
  const clamp = Math.max(-10, Math.min(10, changePct));
  const t = (clamp + 10) / 20; // 0..1
  const r = Math.round(220 * (1 - t) + 30 * t);
  const g = Math.round(40 * (1 - t) + 180 * t);
  const b = Math.round(50 * (1 - t) + 60 * t);
  return `rgb(${r}, ${g}, ${b})`;
}

export function formatPrice(n: number): string {
  return n.toFixed(2);
}

export function formatPct(n: number): string {
  return `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;
}
