## 3) Mock real-time stock stream

### `src/hooks/useMockStockStream.ts`
```ts
import { useEffect, useMemo, useState } from "react";
import { StockCell } from "../utils/heatmap";

const SYMBOLS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
  "AMD", "INTC", "ORCL", "CRM", "UBER", "SHOP", "ADBE", "QCOM"
];

const SECTORS = ["Tech", "Consumer", "Semis", "Cloud"];

function createInitialData(): StockCell[] {
  return SYMBOLS.map((symbol, i) => ({
    symbol,
    sector: SECTORS[i % SECTORS.length],
    price: 50 + Math.random() * 500,
    changePct: (Math.random() - 0.5) * 8,
    volume: Math.floor(1_000_000 + Math.random() * 20_000_000),
  }));
}

export function useMockStockStream(intervalMs = 1000) {
  const initial = useMemo(() => createInitialData(), []);
  const [data, setData] = useState<StockCell[]>(initial);

  useEffect(() => {
    const id = window.setInterval(() => {
      setData((prev) =>
        prev.map((cell) => {
          const drift = (Math.random() - 0.5) * 2.5;
          const newChange = Math.max(-15, Math.min(15, cell.changePct + drift));
          const newPrice = Math.max(1, cell.price * (1 + drift / 100));

          return {
            ...cell,
            price: newPrice,
            changePct: newChange,
            volume: Math.max(0, cell.volume + Math.floor((Math.random() - 0.5) * 500_000)),
          };
        })
      );
    }, intervalMs);

    return () => window.clearInterval(id);
  }, [intervalMs]);

  return data;
}
