## 4) Interactive heatmap component

### `src/components/StockHeatmap.tsx`
```tsx
import React, { useMemo, useRef, useState } from "react";
import * as d3 from "d3";
import { StockCell, getColorForChange, formatPct, formatPrice } from "../utils/heatmap";

type Props = {
  data: StockCell[];
  width?: number;
  height?: number;
};

type TooltipState = {
  visible: boolean;
  x: number;
  y: number;
  cell?: StockCell;
};

export function StockHeatmap({ data, width = 1200, height = 700 }: Props) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const [tooltip, setTooltip] = useState<TooltipState>({
    visible: false,
    x: 0,
    y: 0,
  });

  const [transform, setTransform] = useState<d3.ZoomTransform>(d3.zoomIdentity);

  const layout = useMemo(() => {
    const padding = 8;
    const cols = Math.ceil(Math.sqrt(data.length));
    const rows = Math.ceil(data.length / cols);

    const cellW = (width - padding * (cols + 1)) / cols;
    const cellH = (height - padding * (rows + 1)) / rows;

    return data.map((cell, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      return {
        ...cell,
        x: padding + col * (cellW + padding),
        y: padding + row * (cellH + padding),
        width: cellW,
        height: cellH,
      };
    });
  }, [data, width, height]);

  React.useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);
    const zoomBehavior = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 5])
      .on("zoom", (event) => {
        setTransform(event.transform);
      });

    svg.call(zoomBehavior as any);

    return () => {
      svg.on(".zoom", null);
    };
  }, []);

  const handleMouseMove = (event: React.MouseEvent, cell: StockCell) => {
    setTooltip({
      visible: true,
      x: event.clientX + 12,
      y: event.clientY + 12,
      cell,
    });
  };

  const handleMouseLeave = () => {
    setTooltip((t) => ({ ...t, visible: false }));
  };

  return (
    <div style={{ position: "relative", width, height, overflow: "hidden", border: "1px solid #ddd" }}>
      <svg ref={svgRef} width={width} height={height} style={{ display: "block", background: "#0f1115" }}>
        <g transform={transform.toString()}>
          {layout.map((cell) => (
            <g key={cell.symbol} transform={`translate(${cell.x}, ${cell.y})`}>
              <rect
                width={cell.width}
                height={cell.height}
                rx={10}
                ry={10}
                fill={getColorForChange(cell.changePct)}
                stroke="rgba(255,255,255,0.14)"
                strokeWidth={1}
                onMouseMove={(e) => handleMouseMove(e, cell)}
                onMouseLeave={handleMouseLeave}
              />
              <text x={12} y={24} fill="#fff" fontSize={18} fontWeight={700}>
                {cell.symbol}
              </text>
              <text x={12} y={48} fill="rgba(255,255,255,0.9)" fontSize={14}>
                ${formatPrice(cell.price)}
              </text>
              <text x={12} y={70} fill="rgba(255,255,255,0.85)" fontSize={14}>
                {formatPct(cell.changePct)}
              </text>
            </g>
          ))}
        </g>
      </svg>

      {tooltip.visible && tooltip.cell && (
        <div
          style={{
            position: "fixed",
            left: tooltip.x,
            top: tooltip.y,
            pointerEvents: "none",
            background: "rgba(20, 20, 25, 0.96)",
            color: "#fff",
            border: "1px solid rgba(255,255,255,0.15)",
            borderRadius: 8,
            padding: "10px 12px",
            fontSize: 13,
            boxShadow: "0 8px 24px rgba(0,0,0,0.35)",
            zIndex: 9999,
            minWidth: 180,
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 6 }}>{tooltip.cell.symbol}</div>
          <div>Sector: {tooltip.cell.sector}</div>
          <div>Price: ${formatPrice(tooltip.cell.price)}</div>
          <div>Change: {formatPct(tooltip.cell.changePct)}</div>
          <div>Volume: {tooltip.cell.volume.toLocaleString()}</div>
        </div>
      )}
    </div>
  );
}
