      </div>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    // --- Initial data ---
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AMD","NFLX","INTC",
      "ORCL","CRM","ADBE","CSCO","QCOM","IBM","UBER","SNOW","SHOP","SQ",
      "BA","JPM","BAC","WFC","C","GS","MS","V","MA","PYPL",
      "XOM","CVX","COP","SLB","BP","TTE","PFE","MRK","JNJ","UNH",
      "KO","PEP","WMT","TGT","COST","HD","LOW","NKE","SBUX","MCD"
    ];

    const state = new Map();
    const heatmap = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const viewport = document.getElementById("viewport");
    const world = document.getElementById("world");

    let paused = false;

    // View transform
    let scale = 1;
    let panX = 0;
    let panY = 0;
    let dragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let startPanX = 0;
    let startPanY = 0;

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatChange(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    // Color mapping: red -> yellow -> green
    function getColor(changePct) {
      const c = clamp(changePct, -5, 5);
      const t = (c + 5) / 10; // 0..1
      // interpolate red(231,76,60) -> yellow(243,156,18) -> green(46,204,113)
      let r, g, b;
      if (t < 0.5) {
        const u = t / 0.5;
        r = 231 + (243 - 231) * u;
        g = 76 + (156 - 76) * u;
        b = 60 + (18 - 60) * u;
      } else {
        const u = (t - 0.5) / 0.5;
        r = 243 + (46 - 243) * u;
        g = 156 + (204 - 156) * u;
        b = 18 + (113 - 18) * u;
      }
      return `rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) < 0.5 ? "#111" : "#fff";
    }

    function initData() {
      symbols.forEach(sym => {
        const price = rand(20, 1200);
        const prevClose = price / (1 + rand(-0.03, 0.03));
        const changePct = ((price - prevClose) / prevClose) * 100;
        state.set(sym, {
          symbol: sym,
          price,
          prevClose,
          changePct,
          volume: Math.floor(rand(1e5, 5e6))
        });
      });
    }

    function render() {
      heatmap.innerHTML = "";
      symbols.forEach(sym => {
        const d = state.get(sym);
        const tile = document.createElement("div");
        tile.className = "tile";
        tile.style.background = getColor(d.changePct);
        tile.style.color = textColorForBg(d.changePct);

        tile.innerHTML = `
          <div class="symbol">${d.symbol}</div>
          <div class="price">${formatPrice(d.price)}</div>
          <div class="change">${formatChange(d.changePct)}</div>
        `;

        tile.addEventListener("mouseenter", (e) => {
          tooltip.style.display = "block";
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Price: ${formatPrice(d.price)}<br/>
            Change: ${formatChange(d.changePct)}<br/>
            Prev Close: ${formatPrice(d.prevClose)}<br/>
            Volume: ${d.volume.toLocaleString()}
          `;
        });

        tile.addEventListener("mousemove", (e) => {
          tooltip.style.left = `${e.clientX}px`;
          tooltip.style.top = `${e.clientY}px`;
        });

        tile.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        heatmap.appendChild(tile);
      });
    }

    function updateRandomTick() {
      // Update a subset of symbols each tick to simulate real-time changes
      const count = Math.floor(rand(5, 15));
      for (let i = 0; i < count; i++) {
        const sym = symbols[Math.floor(Math.random() * symbols.length)];
        const d = state.get(sym);

        const drift = rand(-0.008, 0.008);
        const shock = rand(-0.02, 0.02);
        const pctMove = drift + shock;

        const newPrice = Math.max(0.5, d.price * (1 + pctMove));
        const prevClose = d.prevClose;
        const changePct = ((newPrice - prevClose) / prevClose) * 100;

        d.price = newPrice;
        d.changePct = changePct;
        d.volume += Math.floor(rand(1000, 50000));
      }
      render();
    }

    function applyTransform() {
      world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    // Pan
    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - dragStartX);
      panY = startPanY + (e.clientY - dragStartY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    // Zoom at cursor
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const nextScale = clamp(scale * zoomFactor, 0.5, 3);

      // Keep point under cursor stable
      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = nextScale;
      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      applyTransform();
    }, { passive: false });

    // Buttons
    document.getElementById("resetBtn").addEventListener("click", () => {
      scale = 1;
      panX = 0;
      panY = 0;
      applyTransform();
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      paused = !paused;
      e.target.textContent = paused ? "Resume Feed" : "Pause Feed";
    });

    // Hide tooltip if leaving viewport
    viewport.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    // --- Boot ---
    initData();
    render();
    applyTransform();

    setInterval(() => {
      if (!paused) updateRandomTick();
    }, 1000);
  </script>
</body>
</html>
```

