## Example implementation

### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";

type StockPoint = {
  symbol: string;
  sector: string;
  price: number;
  prevPrice: number;
  changePct: number;
  volume: number;
};

type HeatmapCell = {
  x: number;
  y: number;
  width: number;
  height: number;
  point: StockPoint;
};

const SYMBOLS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "META", "NVDA", "TSLA", "AMD",
  "NFLX", "INTC", "CRM", "UBER", "ORCL", "ADBE", "PYPL", "SHOP",
  "SNOW", "QCOM", "AVGO", "COST", "JPM", "BAC", "WMT", "DIS"
];

const SECTORS = [
  "Technology", "Consumer", "Finance", "Healthcare", "Energy", "Retail"
];

function randomBetween(min: number, max: number) {
  return min + Math.random() * (max - min);
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function formatPct(n: number) {
  return `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;
}

function seedStocks(): StockPoint[] {
  return SYMBOLS.map((symbol, i) => {
    const price = randomBetween(20, 500);
    return {
      symbol,
      sector: SECTORS[i % SECTORS.length],
      price,
      prevPrice: price,
      changePct: 0,
      volume: Math.floor(randomBetween(100000, 5000000)),
    };
  });
}

function updateStocks(stocks: StockPoint[]): StockPoint[] {
  return stocks.map((s) => {
    const drift = randomBetween(-0.02, 0.02); // +/-2%
    const prevPrice = s.price;
    const price = Math.max(1, prevPrice * (1 + drift));
    const changePct = ((price - prevPrice) / prevPrice) * 100;
    return {
      ...s,
      prevPrice,
      price,
      changePct,
      volume: Math.max(0, s.volume + Math.floor(randomBetween(-50000, 80000))),
    };
  });
}

function getCellColor(changePct: number) {
  // Green for positive, red for negative, intensity based on magnitude
  const intensity = clamp(Math.abs(changePct) / 3, 0, 1); // 3% => max intensity
  if (changePct >= 0) {
    const g = Math.floor(100 + 120 * intensity);
    const r = Math.floor(30 + 20 * (1 - intensity));
    return `rgb(${r}, ${g}, 60)`;
  } else {
    const r = Math.floor(100 + 120 * intensity);
    const g = Math.floor(30 + 20 * (1 - intensity));
    return `rgb(${r}, ${g}, 60)`;
  }
}

export default function StockHeatmap() {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [stocks, setStocks] = useState<StockPoint[]>(seedStocks());
  const [hovered, setHovered] = useState<StockPoint | null>(null);
  const [view, setView] = useState({ scale: 1, offsetX: 0, offsetY: 0 });

  const [dragState, setDragState] = useState<{
    dragging: boolean;
    startX: number;
    startY: number;
    startOffsetX: number;
    startOffsetY: number;
  }>({
    dragging: false,
    startX: 0,
    startY: 0,
    startOffsetX: 0,
    startOffsetY: 0,
  });

  // Real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setStocks((prev) => updateStocks(prev));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  const cells = useMemo(() => {
    const cols = 6;
    const cellWidth = 150;
    const cellHeight = 90;
    const gap = 10;

    return stocks.map((point, index) => {
      const row = Math.floor(index / cols);
      const col = index % cols;
      return {
        x: col * (cellWidth + gap),
        y: row * (cellHeight + gap),
        width: cellWidth,
        height: cellHeight,
        point,
      } as HeatmapCell;
    });
  }, [stocks]);

  const contentWidth = 6 * 160;
  const contentHeight = Math.ceil(stocks.length / 6) * 100;

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const delta = -e.deltaY;
    const zoomFactor = delta > 0 ? 1.08 : 0.92;

    setView((prev) => {
      const nextScale = clamp(prev.scale * zoomFactor, 0.5, 4);
      return { ...prev, scale: nextScale };
    });
  };

  const onMouseDown = (e: React.MouseEvent) => {
    setDragState({
      dragging: true,
      startX: e.clientX,
      startY: e.clientY,
      startOffsetX: view.offsetX,
      startOffsetY: view.offsetY,
    });
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (!dragState.dragging) return;
    const dx = e.clientX - dragState.startX;
    const dy = e.clientY - dragState.startY;
    setView((prev) => ({
      ...prev,
      offsetX: dragState.startOffsetX + dx,
      offsetY: dragState.startOffsetY + dy,
    }));
  };

  const onMouseUp = () => {
    setDragState((prev) => ({ ...prev, dragging: false }));
  };

  const resetView = () => setView({ scale: 1, offsetX: 0, offsetY: 0 });

  return (
    <div style={styles.page}>
      <div style={styles.toolbar}>
        <div>
          <strong>Stock Price Heatmap</strong>
          <span style={{ marginLeft: 12, color: "#999" }}>
            Live updates every second
          </span>
        </div>
        <div style={styles.buttons}>
          <button onClick={() => setView((v) => ({ ...v, scale: clamp(v.scale * 1.2, 0.5, 4) }))}>
            Zoom In
          </button>
          <button onClick={() => setView((v) => ({ ...v, scale: clamp(v.scale / 1.2, 0.5, 4) }))}>
            Zoom Out
          </button>
          <button onClick={resetView}>Reset</button>
        </div>
      </div>

      <div
        ref={containerRef}
        style={styles.canvas}
        onWheel={handleWheel}
        onMouseDown={onMouseDown}
        onMouseMove={(e) => {
          onMouseMove(e);
          if (!dragState.dragging) {
            const target = e.target as SVGGElement | SVGRectElement;
            const symbol = target?.getAttribute?.("data-symbol");
            if (symbol) {
              const stock = stocks.find((s) => s.symbol === symbol) || null;
              setHovered(stock);
            } else {
              setHovered(null);
            }
          }
        }}
        onMouseUp={onMouseUp}
        onMouseLeave={() => {
          onMouseUp();
          setHovered(null);
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox={`0 0 ${contentWidth} ${contentHeight}`}
          style={{ display: "block", cursor: dragState.dragging ? "grabbing" : "grab" }}
        >
          <g
            transform={`translate(${view.offsetX} ${view.offsetY}) scale(${view.scale})`}
          >
            {cells.map((cell) => {
              const { point } = cell;
              const fill = getCellColor(point.changePct);
              const isHovered = hovered?.symbol === point.symbol;

              return (
                <g key={point.symbol} transform={`translate(${cell.x} ${cell.y})`}>
                  <rect
                    data-symbol={point.symbol}
                    width={cell.width}
                    height={cell.height}
                    rx={10}
                    fill={fill}
                    stroke={isHovered ? "#fff" : "rgba(255,255,255,0.15)"}
                    strokeWidth={isHovered ? 3 : 1}
                    style={{ transition: "fill 0.4s ease, stroke 0.2s ease" }}
                  />
                  <text
                    x={12}
                    y={24}
                    fill="#fff"
                    fontSize="16"
                    fontWeight="700"
                    pointerEvents="none"
                  >
                    {point.symbol}
                  </text>
                  <text
                    x={12}
                    y={46}
                    fill="rgba(255,255,255,0.9)"
                    fontSize="13"
                    pointerEvents="none"
                  >
                    ${point.price.toFixed(2)}
                  </text>
                  <text
                    x={12}
                    y={68}
                    fill="rgba(255,255,255,0.85)"
                    fontSize="13"
                    pointerEvents="none"
                  >
                    {formatPct(point.changePct)}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>

        {hovered && (
          <div style={styles.tooltip}>
            <div><strong>{hovered.symbol}</strong> — {hovered.sector}</div>
            <div>Price: ${hovered.price.toFixed(2)}</div>
            <div>Change: {formatPct(hovered.changePct)}</div>
            <div>Volume: {hovered.volume.toLocaleString()}</div>
          </div>
        )}
      </div>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  page: {
    width: "100%",
    height: "100vh",
    background: "#0b1020",
    color: "#fff",
    fontFamily: "system-ui, sans-serif",
    display: "flex",
    flexDirection: "column",
  },
  toolbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "12px 16px",
    borderBottom: "1px solid rgba(255,255,255,0.08)",
    background: "#11162a",
  },
  buttons: {
    display: "flex",
    gap: "8px",
  },
  canvas: {
    position: "relative",
    flex: 1,
    overflow: "hidden",
    touchAction: "none",
  },
  tooltip: {
    position: "absolute",
    top: 16,
    right: 16,
    background: "rgba(10, 14, 30, 0.95)",
    border: "1px solid rgba(255,255,255,0.12)",
    borderRadius: 10,
    padding: "12px 14px",
    minWidth: 180,
    boxShadow: "0 8px 30px rgba(0,0,0,0.35)",
    pointerEvents: "none",
    lineHeight: 1.5,
  },
};
