      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <button id="resetBtn">Reset View</button>
      <div class="hint">Wheel = zoom · Drag = pan · Hover = details</div>
    </div>
    <div id="stage">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const stage = document.getElementById('stage');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const ctx = canvas.getContext('2d');

    // ----- Data model -----
    const STOCKS = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'META', 'TSLA', 'AMD', 'INTC', 'NFLX',
      'ORCL', 'CRM', 'ADBE', 'QCOM', 'AVGO'
    ];

    const TIME_WINDOW = 60; // number of visible time columns
    const MAX_HISTORY = 240; // total stored columns

    // Each column is a snapshot of all stocks at a time step
    const history = [];
    const basePrices = new Map();
    const latestPrices = new Map();

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function initPrices() {
      STOCKS.forEach(sym => {
        const p = rand(80, 400);
        basePrices.set(sym, p);
        latestPrices.set(sym, p);
      });
    }

    function generateSnapshot() {
      const snapshot = {
        ts: Date.now(),
        values: {}
      };

      for (const sym of STOCKS) {
        const prev = latestPrices.get(sym);
        const drift = rand(-0.018, 0.018); // +/-1.8%
        const next = Math.max(1, prev * (1 + drift));
        latestPrices.set(sym, next);

        const changePct = ((next - basePrices.get(sym)) / basePrices.get(sym)) * 100;
        snapshot.values[sym] = {
          price: next,
          changePct
        };
      }

      history.push(snapshot);
      if (history.length > MAX_HISTORY) history.shift();
    }

    // Seed initial history
    initPrices();
    for (let i = 0; i < TIME_WINDOW; i++) generateSnapshot();

    // ----- View transform -----
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    function resetView() {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      render();
    }

    // ----- Canvas sizing -----
    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = stage.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    // ----- Rendering -----
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function valueToColor(changePct) {
      // Diverging red/green heatmap
      const maxAbs = 8; // percent at which color saturates
      const t = clamp(changePct / maxAbs, -1, 1);

      if (t >= 0) {
        const g = Math.floor(80 + 175 * t);
        const r = Math.floor(40 + 60 * (1 - t));
        return `rgb(${r}, ${g}, 70)`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(80 + 175 * a);
        const g = Math.floor(40 + 60 * (1 - a));
        return `rgb(${r}, ${g}, 70)`;
      }
    }

    function render() {
      const rect = stage.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;

      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = '#0f1117';
      ctx.fillRect(0, 0, w, h);

      if (!history.length) return;

      const cols = Math.min(TIME_WINDOW, history.length);
      const rows = STOCKS.length;

      const cellW = 80 * scale;
      const cellH = 34 * scale;

      const gridW = cols * cellW;
      const gridH = rows * cellH;

      const startX = offsetX;
      const startY = offsetY;

      // Draw cells
      for (let c = 0; c < cols; c++) {
        const snapshot = history[history.length - cols + c];
        for (let r = 0; r < rows; r++) {
          const sym = STOCKS[r];
          const item = snapshot.values[sym];
          const x = startX + c * cellW;
          const y = startY + r * cellH;

          // Skip offscreen cells
          if (x + cellW < 0 || y + cellH < 0 || x > w || y > h) continue;

          ctx.fillStyle = valueToColor(item.changePct);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // Text
          if (cellW > 55 && cellH > 22) {
            ctx.fillStyle = '#ffffff';
            ctx.font = `${Math.max(10, 12 * scale)}px Arial`;
            ctx.textBaseline = 'middle';
            ctx.fillText(sym, x + 6, y + cellH / 2 - 5);

            ctx.fillStyle = 'rgba(255,255,255,0.9)';
            ctx.fillText(item.changePct.toFixed(2) + '%', x + 6, y + cellH / 2 + 8);
          }
        }
      }

      // Row labels on left
      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px Arial';
      for (let r = 0; r < rows; r++) {
        const y = startY + r * cellH + cellH / 2;
        if (y < 0 || y > h) continue;
        ctx.fillText(STOCKS[r], 6, y + 4);
      }

      // Grid border
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.strokeRect(startX, startY, gridW, gridH);
    }

    // ----- Interaction: pan -----
    let dragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragOffsetX = 0;
    let dragOffsetY = 0;

    stage.addEventListener('mousedown', (e) => {
      dragging = true;
      stage.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      dragOffsetX = offsetX;
      dragOffsetY = offsetY;
    });

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        offsetX = dragOffsetX + (e.clientX - dragStartX);
        offsetY = dragOffsetY + (e.clientY - dragStartY);
        render();
      }
      updateTooltip(e);
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      stage.classList.remove('dragging');
    });

    // ----- Interaction: zoom -----
    stage.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = stage.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale = newScale;
      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    // ----- Tooltip / hit testing -----
    function updateTooltip(e) {
      const rect = stage.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const cols = Math.min(TIME_WINDOW, history.length);
      const rows = STOCKS.length;
      const cellW = 80 * scale;
      const cellH = 34 * scale;

      const col = Math.floor((x - offsetX) / cellW);
      const row = Math.floor((y - offsetY) / cellH);

      if (col < 0 || col >= cols || row < 0 || row >= rows) {
        tooltip.style.display = 'none';
        return;
      }

      const snapshot = history[history.length - cols + col];
      const sym = STOCKS[row];
      const item = snapshot.values[sym];

      if (!item) {
        tooltip.style.display = 'none';
        return;
      }

      tooltip.style.display = 'block';
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
      tooltip.innerHTML = `
        <strong>${sym}</strong><br/>
        Price: $${item.price.toFixed(2)}<br/>
        Change: ${item.changePct.toFixed(2)}%<br/>
        Time: ${new Date(snapshot.ts).toLocaleTimeString()}
      `;
    }

    stage.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    // ----- Real-time updates -----
    setInterval(() => {
      generateSnapshot();
      render();
    }, 1000);

    // Initial render
    render();
  </script>
</body>
</html>
```

