<body>
  <div id="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="info">Drag to pan · Wheel to zoom · Hover for details</div>
      <div class="spacer"></div>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
      <button id="resetBtn">Reset View</button>
    </div>
    <div class="main" id="main">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const main = document.getElementById('main');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');

    // --- Data model ---
    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'AMD',
      'NFLX', 'INTC', 'ORCL', 'CRM', 'ADBE', 'QCOM', 'IBM', 'UBER'
    ];

    const timeBuckets = 80; // visible history length
    const rows = symbols.length;

    // Each cell: { symbol, timeIndex, price, prevPrice, changePct, ts }
    let data = Array.from({ length: rows }, (_, r) =>
      Array.from({ length: timeBuckets }, (_, c) => ({
        symbol: symbols[r],
        timeIndex: c,
        price: 100 + Math.random() * 50,
        prevPrice: 100 + Math.random() * 50,
        changePct: 0,
        ts: Date.now() - (timeBuckets - c) * 1000
      }))
    );

    // --- View transform ---
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // Cell sizing in world coordinates
    const baseCellW = 60;
    const baseCellH = 28;

    // Interaction state
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let dragOffsetStart = { x: 0, y: 0 };
    let hoverCell = null;

    // Resize handling
    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = main.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener('resize', resizeCanvas);

    // --- Utility ---
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function changeToColor(pct) {
      // Clamp to [-5, 5]
      const v = clamp(pct, -5, 5);
      const t = (v + 5) / 10; // 0..1
      // Red -> neutral blue-gray -> green
      const red = [217, 75, 75];
      const mid = [44, 62, 102];
      const green = [58, 199, 109];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = mid; localT = t / 0.5;
      } else {
        c1 = mid; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const r = Math.round(lerp(c1[0], c2[0], localT));
      const g = Math.round(lerp(c1[1], c2[1], localT));
      const b = Math.round(lerp(c1[2], c2[2], localT));
      return `rgb(${r},${g},${b})`;
    }

    function worldToScreen(x, y) {
      return {
        x: x * scale + offsetX,
        y: y * scale + offsetY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - offsetX) / scale,
        y: (y - offsetY) / scale
      };
    }

    function resetView() {
      scale = 1;
      offsetX = 80;
      offsetY = 40;
      render();
    }

    resetBtn.addEventListener('click', resetView);

    // --- Rendering ---
    function render() {
      const rect = main.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      // background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, rect.width, rect.height);

      const cellW = baseCellW * scale;
      const cellH = baseCellH * scale;

      // visible range
      const startCol = Math.max(0, Math.floor((-offsetX) / cellW) - 1);
      const endCol = Math.min(timeBuckets - 1, Math.ceil((rect.width - offsetX) / cellW) + 1);
      const startRow = Math.max(0, Math.floor((-offsetY) / cellH) - 1);
      const endRow = Math.min(rows - 1, Math.ceil((rect.height - offsetY) / cellH) + 1);

      // grid cells
      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          const cell = data[r][c];
          const x = offsetX + c * cellW;
          const y = offsetY + r * cellH;

          // cell background
          ctx.fillStyle = changeToColor(cell.changePct);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // subtle border
          ctx.strokeStyle = 'rgba(255,255,255,0.08)';
          ctx.strokeRect(x, y, cellW - 1, cellH - 1);

          // label at larger zoom
          if (scale >= 0.9) {
            ctx.fillStyle = 'rgba(255,255,255,0.92)';
            ctx.font = `${Math.max(10, 11 * scale)}px sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(cell.changePct.toFixed(1) + '%', x + cellW / 2, y + cellH / 2);
          }
        }
      }

      // row labels
      ctx.fillStyle = '#d6def7';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let r = startRow; r <= endRow; r++) {
        const y = offsetY + r * cellH + cellH / 2;
        ctx.fillText(symbols[r], 70, y);
      }

      // hover outline
      if (hoverCell) {
        const x = offsetX + hoverCell.c * cellW;
        const y = offsetY + hoverCell.r * cellH;
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, cellW - 3, cellH - 3);
      }

      // axis baseline
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.beginPath();
      ctx.moveTo(80, 0);
      ctx.lineTo(80, rect.height);
      ctx.stroke();
    }

    // --- Real-time update simulation ---
    function updateData() {
      // shift in one new time bucket
      const newCol = data.map((row, r) => {
        const last = row[row.length - 1];
        const prev = last.price;
        const delta = (Math.random() - 0.5) * 2.5; // simulated movement
        const price = Math.max(1, prev + delta);
        const changePct = ((price - prev) / prev) * 100;

        return {
          symbol: symbols[r],
          timeIndex: timeBuckets - 1,
          price,
          prevPrice: prev,
          changePct,
          ts: Date.now()
        };
      });

      for (let r = 0; r < rows; r++) {
        data[r].shift();
        data[r].push(newCol[r]);
      }

      render();
    }

    setInterval(updateData, 1000);

    // --- Interaction: pan / zoom ---
    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      dragOffsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener('mousemove', (e) => {
      const rect = main.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (isDragging) {
        offsetX = dragOffsetStart.x + (e.clientX - dragStart.x);
        offsetY = dragOffsetStart.y + (e.clientY - dragStart.y);
        render();
        return;
      }

      // hover detection
      const cellW = baseCellW * scale;
      const cellH = baseCellH * scale;
      const world = screenToWorld(mx, my);
      const c = Math.floor(world.x / baseCellW);
      const r = Math.floor(world.y / baseCellH);

      if (r >= 0 && r < rows && c >= 0 && c < timeBuckets) {
        hoverCell = { r, c };
        const cell = data[r][c];
        tooltip.style.display = 'block';
        tooltip.style.left = `${mx}px`;
        tooltip.style.top = `${my}px`;
        tooltip.innerHTML = `
          <div><strong>${cell.symbol}</strong></div>
          <div>Change: ${cell.changePct.toFixed(2)}%</div>
          <div>Price: $${cell.price.toFixed(2)}</div>
          <div>Time: ${new Date(cell.ts).toLocaleTimeString()}</div>
        `;
      } else {
        hoverCell = null;
        tooltip.style.display = 'none';
      }
      render();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = main.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 4);

      // Zoom around cursor
      const worldBefore = screenToWorld(mouseX, mouseY);
      scale = newScale;
      offsetX = mouseX - worldBefore.x * scale;
      offsetY = mouseY - worldBefore.y * scale;

      render();
    }, { passive: false });

    // --- Optional keyboard shortcuts ---
    window.addEventListener('keydown', (e) => {
      if (e.key === 'r') resetView();
    });

    // Initial setup
    offsetX = 80;
    offsetY = 40;
    resizeCanvas();
  </script>
</body>
</html>
