        <div class="status" id="status">Connecting to market feed...</div>
      </div>
      <div class="controls">
        <div class="legend">
          <span>Loss</span>
          <div class="swatch"></div>
          <span>Gain</span>
        </div>
        <button id="resetBtn">Reset View</button>
      </div>
    </div>

    <div class="viewport" id="viewport">
      <div class="grid" id="grid"></div>
      <div class="tooltip" id="tooltip"></div>
      <div class="hint">Drag to pan • Scroll to zoom • Hover for details</div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');

    // --- Demo stock data ---
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','META','NVDA','TSLA','NFLX','AMD','INTC',
      'ORCL','CRM','UBER','SNAP','SHOP','BABA','JPM','BAC','XOM','CVX',
      'PFE','MRK','KO','PEP','WMT','COST','DIS','BA','QCOM','IBM',
      'ADBE','PYPL','AVGO','T','VZ','MCD','NKE','LULU','SBUX','GE'
    ];

    const cells = [];
    const cols = 8;
    const cellW = 150;
    const cellH = 95;
    const gap = 10;

    // View transform
    let scale = 1;
    let panX = 40;
    let panY = 40;

    // Drag state
    let dragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let panStartX = 0;
    let panStartY = 0;

    // Stock state
    const stockData = new Map();

    function rand(min, max) {
      return min + Math.random() * (max - min);
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatChange(v) {
      return `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`;
    }

    function clamp(n, min, max) {
      return Math.max(min, Math.min(max, n));
    }

    function colorForChange(changePct) {
      // Map roughly from -5%..+5% to red->gray->green
      const t = clamp((changePct + 5) / 10, 0, 1);
      const red = { r: 192, g: 57, b: 43 };
      const gray = { r: 44, g: 62, b: 80 };
      const green = { r: 39, g: 174, b: 96 };

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = gray; localT = t / 0.5;
      } else {
        c1 = gray; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const r = Math.round(c1.r + (c2.r - c1.r) * localT);
      const g = Math.round(c1.g + (c2.g - c1.g) * localT);
      const b = Math.round(c1.b + (c2.b - c1.b) * localT);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function createGrid() {
      grid.innerHTML = '';
      symbols.forEach((symbol, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;

        const basePrice = rand(20, 500);
        const changePct = rand(-4, 4);

        stockData.set(symbol, {
          symbol,
          basePrice,
          price: basePrice * (1 + changePct / 100),
          changePct
        });

        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.symbol = symbol;
        cell.style.width = `${cellW}px`;
        cell.style.height = `${cellH}px`;
        cell.style.left = `${col * (cellW + gap)}px`;
        cell.style.top = `${row * (cellH + gap)}px`;

        cell.innerHTML = `
          <div class="symbol">${symbol}</div>
          <div class="price"></div>
          <div class="change"></div>
        `;

        cell.addEventListener('mouseenter', (e) => showTooltip(e, symbol));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);

        grid.appendChild(cell);
        cells.push(cell);
      });

      updateGridSize();
      renderAll();
    }

    function updateGridSize() {
      const rows = Math.ceil(symbols.length / cols);
      grid.style.width = `${cols * cellW + (cols - 1) * gap}px`;
      grid.style.height = `${rows * cellH + (rows - 1) * gap}px`;
    }

    function renderAll() {
      cells.forEach(cell => {
        const symbol = cell.dataset.symbol;
        const data = stockData.get(symbol);
        const bg = colorForChange(data.changePct);
        cell.style.background = bg;
        cell.querySelector('.price').textContent = formatPrice(data.price);
        cell.querySelector('.change').textContent = formatChange(data.changePct);
      });
      applyTransform();
    }

    function updateOne(symbol) {
      const data = stockData.get(symbol);

      // Simulate a live tick
      const drift = rand(-0.6, 0.6);
      const shock = rand(-1.2, 1.2);
      const nextChange = clamp(data.changePct + drift + shock * 0.12, -10, 10);

      // Keep price moving relative to base
      data.changePct = nextChange;
      data.price = data.basePrice * (1 + nextChange / 100);

      const cell = cells[symbols.indexOf(symbol)];
      cell.style.background = colorForChange(data.changePct);
      cell.querySelector('.price').textContent = formatPrice(data.price);
      cell.querySelector('.change').textContent = formatChange(data.changePct);
    }

    function tick() {
      // Update a subset each frame to simulate streaming
      const updatesPerTick = 10;
      for (let i = 0; i < updatesPerTick; i++) {
        const symbol = symbols[Math.floor(Math.random() * symbols.length)];
        updateOne(symbol);
      }
      statusEl.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
    }

    function applyTransform() {
      grid.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function resetView() {
      scale = 1;
      panX = 40;
      panY = 40;
      applyTransform();
    }

    // --- Tooltip ---
    function showTooltip(e, symbol) {
      const data = stockData.get(symbol);
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <strong>${symbol}</strong><br/>
        Price: ${formatPrice(data.price)}<br/>
        Change: ${formatChange(data.changePct)}<br/>
        Base: ${formatPrice(data.basePrice)}
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const x = e.clientX;
      const y = e.clientY;
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    // --- Pan / Zoom ---
    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      panStartX = panX;
      panStartY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        panX = panStartX + (e.clientX - dragStartX);
        panY = panStartY + (e.clientY - dragStartY);
        applyTransform();
      }
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = nextScale;
      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      applyTransform();
    }, { passive: false });

    // Touch-friendly pointer dragging
    viewport.addEventListener('pointerdown', (e) => {
      viewport.setPointerCapture(e.pointerId);
      dragging = true;
      viewport.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      panStartX = panX;
      panStartY = panY;
    });

    viewport.addEventListener('pointermove', (e) => {
      if (dragging) {
        panX = panStartX + (e.clientX - dragStartX);
        panY = panStartY + (e.clientY - dragStartY);
        applyTransform();
      }
    });

    viewport.addEventListener('pointerup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', resetView);

    // --- Init ---
    createGrid();
    resetView();
    statusEl.textContent = 'Connected. Streaming simulated market data...';

    // Simulated real-time feed
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

---

## How it works

### 1. Heatmap rendering
Each stock is a grid cell positioned absolutely in a large container. The background color is computed from the stock’s percent change:

- **red** = negative change
- **gray** = near flat
- **green** = positive change

### 2. Real-time updates
A timer updates a few random stocks every second to simulate a live feed.

### 3. Zoom and pan
- **Drag**: updates `panX` / `panY`
- **Wheel**: updates `scale`
- The transform is applied to the grid with CSS `translate(...) scale(...)`

### 4. Tooltip
Hovering a stock cell shows a fixed-position tooltip with current price and change.

