### `StockHeatmap.jsx`

```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";

const INITIAL_STOCKS = [
  { symbol: "AAPL", sector: "Tech", price: 189.12, change: 1.2 },
  { symbol: "MSFT", sector: "Tech", price: 421.33, change: -0.4 },
  { symbol: "GOOGL", sector: "Tech", price: 175.88, change: 0.8 },
  { symbol: "AMZN", sector: "Consumer", price: 182.24, change: -1.1 },
  { symbol: "META", sector: "Tech", price: 498.15, change: 2.3 },
  { symbol: "NVDA", sector: "Tech", price: 121.45, change: 3.7 },
  { symbol: "TSLA", sector: "Auto", price: 214.77, change: -2.6 },
  { symbol: "JPM", sector: "Finance", price: 198.34, change: 0.5 },
  { symbol: "V", sector: "Finance", price: 274.12, change: 0.2 },
  { symbol: "NFLX", sector: "Media", price: 642.91, change: -0.9 },
  { symbol: "DIS", sector: "Media", price: 92.44, change: 1.1 },
  { symbol: "AMD", sector: "Tech", price: 154.23, change: -0.7 },
];

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, n));
}

function randomWalk(value, volatility = 1) {
  return value + (Math.random() - 0.5) * volatility;
}

function updateStocks(stocks) {
  return stocks.map((s) => {
    const delta = (Math.random() - 0.5) * 4; // price movement
    const newPrice = Math.max(1, s.price + delta);
    const change = ((newPrice - s.price) / s.price) * 100;
    return {
      ...s,
      price: Number(newPrice.toFixed(2)),
      change: Number(change.toFixed(2)),
    };
  });
}

export default function StockHeatmap() {
  const svgRef = useRef(null);
  const containerRef = useRef(null);

  const [stocks, setStocks] = useState(INITIAL_STOCKS);
  const [selected, setSelected] = useState(null);
  const [hovered, setHovered] = useState(null);
  const [view, setView] = useState({ k: 1, x: 0, y: 0 });

  const width = 1100;
  const height = 700;
  const padding = 16;

  // Simulated real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setStocks((prev) => updateStocks(prev));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  const layout = useMemo(() => {
    const cols = Math.ceil(Math.sqrt(stocks.length));
    const rows = Math.ceil(stocks.length / cols);
    const cellW = (width - padding * 2) / cols;
    const cellH = (height - padding * 2) / rows;

    return stocks.map((s, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      return {
        ...s,
        x: padding + col * cellW,
        y: padding + row * cellH,
        w: cellW - 8,
        h: cellH - 8,
      };
    });
  }, [stocks]);

  const colorScale = useMemo(() => {
    return d3.scaleLinear().domain([-5, 0, 5]).range(["#d73027", "#f7f7f7", "#1a9850"]);
  }, []);

  useEffect(() => {
    const svg = d3.select(svgRef.current);
    const g = svg.select("g.viewport");

    const zoom = d3
      .zoom()
      .scaleExtent([0.5, 8])
      .on("zoom", (event) => {
        setView({
          k: event.transform.k,
          x: event.transform.x,
          y: event.transform.y,
        });
      });

    svg.call(zoom);

    // Optional: initialize transform
    svg.call(zoom.transform, d3.zoomIdentity.translate(0, 0).scale(1));

    return () => {
      svg.on(".zoom", null);
    };
  }, []);

  useEffect(() => {
    const svg = d3.select(svgRef.current);
    svg
      .select("g.viewport")
      .attr("transform", `translate(${view.x},${view.y}) scale(${view.k})`);
  }, [view]);

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        height: "100vh",
        background: "#0b1020",
        color: "#fff",
        overflow: "hidden",
        fontFamily: "Inter, system-ui, sans-serif",
      }}
    >
      <div style={{ padding: "12px 16px", borderBottom: "1px solid #1f2a44" }}>
        <h2 style={{ margin: 0, fontSize: 18 }}>Stock Price Heatmap</h2>
        <div style={{ fontSize: 12, opacity: 0.8 }}>
          Real-time updates • Scroll to zoom • Drag to pan • Click to select
        </div>
      </div>

      <svg
        ref={svgRef}
        width="100%"
        height="calc(100vh - 60px)"
        viewBox={`0 0 ${width} ${height}`}
        style={{ display: "block", cursor: "grab" }}
      >
        <g className="viewport">
          {layout.map((stock) => {
            const isSelected = selected?.symbol === stock.symbol;
            const isHovered = hovered?.symbol === stock.symbol;

            return (
              <g
                key={stock.symbol}
                transform={`translate(${stock.x},${stock.y})`}
                onMouseEnter={() => setHovered(stock)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => setSelected(stock)}
                style={{ cursor: "pointer" }}
              >
                <rect
                  width={stock.w}
                  height={stock.h}
                  rx={10}
                  ry={10}
                  fill={colorScale(clamp(stock.change, -5, 5))}
                  stroke={isSelected ? "#ffd166" : isHovered ? "#ffffff" : "#1f2a44"}
                  strokeWidth={isSelected ? 3 : isHovered ? 2 : 1}
                  opacity={0.95}
                />
                <text
                  x={14}
                  y={28}
                  fill="#111"
                  fontSize={18}
                  fontWeight={700}
                >
                  {stock.symbol}
                </text>
                <text x={14} y={52} fill="#111" fontSize={13}>
                  ${stock.price.toFixed(2)}
                </text>
                <text x={14} y={74} fill="#111" fontSize={13}>
                  {stock.change >= 0 ? "+" : ""}
                  {stock.change.toFixed(2)}%
                </text>
              </g>
            );
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {hovered && (
        <div
          style={{
            position: "fixed",
            left: 20,
            bottom: 20,
            background: "rgba(15, 20, 35, 0.95)",
            border: "1px solid #2a3555",
            borderRadius: 12,
            padding: "12px 14px",
            minWidth: 200,
            boxShadow: "0 10px 30px rgba(0,0,0,0.35)",
            pointerEvents: "none",
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 6 }}>{hovered.symbol}</div>
          <div style={{ fontSize: 13, opacity: 0.9 }}>Sector: {hovered.sector}</div>
          <div style={{ fontSize: 13, opacity: 0.9 }}>
            Price: ${hovered.price.toFixed(2)}
          </div>
          <div style={{ fontSize: 13, opacity: 0.9 }}>
            Change:{" "}
            <span style={{ color: hovered.change >= 0 ? "#34d399" : "#f87171" }}>
              {hovered.change >= 0 ? "+" : ""}
              {hovered.change.toFixed(2)}%
            </span>
          </div>
        </div>
      )}
    </div>
  );
}
```

