## Minimal working example

Save as `index.html` and open in a browser:

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #0b0f14;
      color: #e5e7eb;
      font-family: system-ui, sans-serif;
    }

    #toolbar {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 10;
      background: rgba(20, 25, 35, 0.85);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 10px;
      padding: 10px 12px;
      backdrop-filter: blur(8px);
      font-size: 14px;
      line-height: 1.4;
    }

    #canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }

    #canvas.dragging {
      cursor: grabbing;
    }

    .hint {
      opacity: 0.8;
      font-size: 12px;
      margin-top: 4px;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div id="status">Initializing...</div>
    <div class="hint">Wheel: zoom · Drag: pan</div>
  </div>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    // --- Data setup ---
    const cols = 40;
    const rows = 24;
    const stocks = [];

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    // Create mock stock tiles with base price and current change
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        stocks.push({
          symbol: `S${y}-${x}`,
          x,
          y,
          price: rand(20, 500),
          change: rand(-5, 5),
        });
      }
    }

    // --- View transform ---
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // --- Interaction state ---
    let dragging = false;
    let lastMouseX = 0;
    let lastMouseY = 0;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(window.innerWidth * dpr);
      canvas.height = Math.floor(window.innerHeight * dpr);
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener("resize", resize);

    function priceToColor(change) {
      // red for negative, green for positive
      const t = clamp((change + 5) / 10, 0, 1);
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      const b = 60;
      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;

      ctx.clearRect(0, 0, w, h);

      // background grid
      ctx.fillStyle = "#0b0f14";
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      const tileW = 70;
      const tileH = 50;
      const gap = 6;

      for (const s of stocks) {
        const px = s.x * (tileW + gap);
        const py = s.y * (tileH + gap);

        // tile
        ctx.fillStyle = priceToColor(s.change);
        roundRect(ctx, px, py, tileW, tileH, 8);
        ctx.fill();

        // text
        ctx.fillStyle = "rgba(255,255,255,0.95)";
        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(s.symbol, px + 8, py + 18);

        ctx.font = "bold 13px system-ui, sans-serif";
        ctx.fillText(`$${s.price.toFixed(2)}`, px + 8, py + 35);
      }

      ctx.restore();

      statusEl.textContent = `Tiles: ${stocks.length} | Zoom: ${scale.toFixed(2)}x`;
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    // --- Real-time updates ---
    function updatePrices() {
      for (const s of stocks) {
        // random walk
        s.change += rand(-0.4, 0.4);
        s.change = clamp(s.change, -5, 5);

        s.price += rand(-1.5, 1.5);
        s.price = Math.max(1, s.price);
      }
      draw();
    }

    setInterval(updatePrices, 500);

    // --- Pan ---
    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      canvas.classList.add("dragging");
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      const dx = e.clientX - lastMouseX;
      const dy = e.clientY - lastMouseY;
      offsetX += dx;
      offsetY += dy;
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
      draw();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      canvas.classList.remove("dragging");
    });

    // --- Zoom centered on mouse pointer ---
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.3, 4);

      // Keep the point under the cursor stable
      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale = newScale;
      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      draw();
    }, { passive: false });

    // Initial view
    function fitInitialView() {
      const tileW = 70;
      const tileH = 50;
      const gap = 6;
      const contentW = cols * (tileW + gap);
      const contentH = rows * (tileH + gap);

      const scaleX = window.innerWidth / (contentW + 40);
      const scaleY = window.innerHeight / (contentH + 40);
      scale = Math.min(scaleX, scaleY, 1);

      offsetX = (window.innerWidth - contentW * scale) / 2;
      offsetY = (window.innerHeight - contentH * scale) / 2;

      draw();
    }

    resize();
    fitInitialView();
  </script>
</body>
</html>
