<body>
  <div id="toolbar">
    <span class="badge">Wheel: zoom</span>
    <span class="badge">Drag: pan</span>
    <span class="badge" id="status">Live</span>
  </div>
  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const statusEl = document.getElementById('status');

    const state = {
      scale: 1,
      offsetX: 0,
      offsetY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      cols: 30,
      rows: 18,
      cellW: 90,
      cellH: 50,
      data: []
    };

    // Generate sample stock data
    const symbols = Array.from({ length: state.rows }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);
    const times = Array.from({ length: state.cols }, (_, i) => `T${i + 1}`);

    function randomPriceChange() {
      return (Math.random() - 0.5) * 4; // -2..+2
    }

    function initData() {
      state.data = Array.from({ length: state.rows }, () =>
        Array.from({ length: state.cols }, () => randomPriceChange())
      );
    }

    function updateLiveData() {
      // Randomly update a few cells
      for (let n = 0; n < 8; n++) {
        const r = Math.floor(Math.random() * state.rows);
        const c = Math.floor(Math.random() * state.cols);
        state.data[r][c] += randomPriceChange() * 0.25;
        state.data[r][c] = Math.max(-10, Math.min(10, state.data[r][c]));
      }
      statusEl.textContent = `Live • ${new Date().toLocaleTimeString()}`;
      draw();
    }

    function resize() {
      canvas.width = window.innerWidth * devicePixelRatio;
      canvas.height = window.innerHeight * devicePixelRatio;
      canvas.style.width = window.innerWidth + 'px';
      canvas.style.height = window.innerHeight + 'px';
      draw();
    }

    function valueToColor(v) {
      // Red for negative, green for positive
      const t = Math.max(-10, Math.min(10, v)) / 10;
      if (t >= 0) {
        const g = Math.round(80 + 175 * t);
        return `rgb(30, ${g}, 90)`;
      } else {
        const r = Math.round(80 + 175 * (-t));
        return `rgb(${r}, 50, 60)`;
      }
    }

    function drawGrid() {
      const w = canvas.width;
      const h = canvas.height;

      ctx.save();
      ctx.scale(devicePixelRatio, devicePixelRatio);
      ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);

      // Apply pan/zoom
      ctx.translate(state.offsetX, state.offsetY);
      ctx.scale(state.scale, state.scale);

      // Draw cells
      for (let r = 0; r < state.rows; r++) {
        for (let c = 0; c < state.cols; c++) {
          const x = c * state.cellW;
          const y = r * state.cellH;
          const v = state.data[r][c];

          ctx.fillStyle = valueToColor(v);
          ctx.fillRect(x, y, state.cellW - 2, state.cellH - 2);

          ctx.fillStyle = 'rgba(255,255,255,0.92)';
          ctx.font = '12px system-ui, sans-serif';
          ctx.fillText(v.toFixed(1), x + 8, y + 18);
        }
      }

      // Labels
      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px system-ui, sans-serif';
      for (let c = 0; c < state.cols; c++) {
        ctx.fillText(times[c], c * state.cellW + 8, -8);
      }
      for (let r = 0; r < state.rows; r++) {
        ctx.fillText(symbols[r], -50, r * state.cellH + 28);
      }

      ctx.restore();
    }

    function draw() {
      drawGrid();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Zoom around cursor
      const worldX = (mouseX - state.offsetX) / state.scale;
      const worldY = (mouseY - state.offsetY) / state.scale;

      state.scale *= zoomFactor;
      state.scale = Math.max(0.4, Math.min(4, state.scale));

      state.offsetX = mouseX - worldX * state.scale;
      state.offsetY = mouseY - worldY * state.scale;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) return;
      state.offsetX += e.clientX - state.lastX;
      state.offsetY += e.clientY - state.lastY;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    // Touch support: simple one-finger pan
    canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        state.dragging = true;
        state.lastX = e.touches[0].clientX;
        state.lastY = e.touches[0].clientY;
      }
    }, { passive: true });

    canvas.addEventListener('touchmove', (e) => {
      if (!state.dragging || e.touches.length !== 1) return;
      const t = e.touches[0];
      state.offsetX += t.clientX - state.lastX;
      state.offsetY += t.clientY - state.lastY;
      state.lastX = t.clientX;
      state.lastY = t.clientY;
      draw();
    }, { passive: true });

    canvas.addEventListener('touchend', () => {
      state.dragging = false;
    });

    window.addEventListener('resize', resize);

    initData();
    resize();
    setInterval(updateLiveData, 500);
  </script>
</body>
</html>
