    const grid = document.getElementById("grid");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");

    let stocks = symbols.map((s, i) => ({
      symbol: s,
      price: 50 + Math.random() * 450,
      change: (Math.random() - 0.5) * 10
    }));

    let scale = 1;
    let panX = 0;
    let panY = 0;
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startPanX = 0;
    let startPanY = 0;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Negative = red, positive = green
      const maxAbs = 10;
      const t = clamp(Math.abs(change) / maxAbs, 0, 1);
      const alpha = 0.25 + t * 0.75;
      if (change >= 0) {
        return `rgba(34, 197, 94, ${alpha})`;
      }
      return `rgba(239, 68, 68, ${alpha})`;
    }

    function render() {
      grid.innerHTML = "";
      stocks.forEach(stock => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = colorForChange(stock.change);
        cell.dataset.symbol = stock.symbol;
        cell.dataset.price = stock.price.toFixed(2);
        cell.dataset.change = stock.change.toFixed(2);

        cell.innerHTML = `
          <div class="ticker">${stock.symbol}</div>
          <div class="price">$${stock.price.toFixed(2)}</div>
          <div class="change">${stock.change >= 0 ? "+" : ""}${stock.change.toFixed(2)}%</div>
        `;

        cell.addEventListener("mousemove", (e) => {
          tooltip.style.left = e.clientX + "px";
          tooltip.style.top = e.clientY + "px";
          tooltip.innerHTML = `
            <strong>${stock.symbol}</strong><br/>
            Price: $${stock.price.toFixed(2)}<br/>
            Change: ${stock.change >= 0 ? "+" : ""}${stock.change.toFixed(2)}%
          `;
          tooltip.style.display = "block";
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        grid.appendChild(cell);
      });

      grid.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function randomUpdate() {
      stocks = stocks.map(s => {
        const delta = (Math.random() - 0.5) * 6;
        const nextChange = clamp(s.change + delta, -15, 15);
        const nextPrice = Math.max(1, s.price * (1 + delta / 100));
        return { ...s, price: nextPrice, change: nextChange };
      });
      render();
      status.textContent = `Live updates: on • ${new Date().toLocaleTimeString()}`;
    }

    // Zoom with mouse wheel
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = viewport.getBoundingClientRect();

      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = clamp(scale * zoomFactor, 0.5, 3);

      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    // Pan with mouse drag
    viewport.addEventListener("pointerdown", (e) => {
      dragging = true;
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      render();
    });

    viewport.addEventListener("pointerup", () => {
      dragging = false;
    });

    viewport.addEventListener("pointercancel", () => {
      dragging = false;
    });

