        symbol: s.symbol,
        price: 50 + Math.random() * 450,
        change: (Math.random() - 0.5) * 10
      }));
      render();
    });

    // Initial render
    render();

    // Real-time updates every 1.5s
    setInterval(randomUpdate, 1500);
  </script>
