    let lastX = 0;
    let lastY = 0;

    const symbols = [];
    const tiles = new Map();

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function pctToColor(pct) {
      // pct in range roughly [-5, 5]
      const t = clamp((pct + 5) / 10, 0, 1);
      const r = t < 0.5 ? 220 : Math.round(220 - (t - 0.5) * 2 * 220);
      const g = t < 0.5 ? Math.round(38 + t * 2 * 40) : Math.round(38 + (t - 0.5) * 2 * 160);
      const b = t < 0.5 ? Math.round(38 + t * 2 * 40) : Math.round(38 + (t - 0.5) * 2 * 20);
      // Simpler red -> dark -> green gradient
      if (pct < 0) {
        const a = clamp(Math.abs(pct) / 5, 0, 1);
        return `rgb(${Math.round(220)}, ${Math.round(60 * (1 - a))}, ${Math.round(60 * (1 - a))})`;
      } else {
        const a = clamp(pct / 5, 0, 1);
        return `rgb(${Math.round(40 * (1 - a))}, ${Math.round(120 + 90 * a)}, ${Math.round(60 * (1 - a))})`;
      }
    }

    function makeSymbol(i) {
      const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const len = 3 + (i % 2);
      let s = "";
      for (let j = 0; j < len; j++) s += letters[(i * 7 + j * 11) % letters.length];
      return s;
    }

    function createTiles() {
      map.style.width = (cols * (tileSize + gap) + gap) + 'px';
      map.style.height = (rows * (tileSize + gap) + gap) + 'px';

      let idx = 0;
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          const symbol = makeSymbol(idx);
          const price = rand(20, 500);
          const change = rand(-5, 5);
          const tile = document.createElement('div');
          tile.className = 'tile';
          tile.style.left = (gap + x * (tileSize + gap)) + 'px';
          tile.style.top = (gap + y * (tileSize + gap)) + 'px';
          tile.style.width = tileSize + 'px';
          tile.style.height = tileSize + 'px';
          tile.dataset.symbol = symbol;

          const data = { symbol, price, change, tile };
          tiles.set(symbol, data);
          symbols.push(symbol);

          tile.addEventListener('mouseenter', () => showTooltip(data));
          tile.addEventListener('mousemove', (e) => moveTooltip(e));
          tile.addEventListener('mouseleave', hideTooltip);

          map.appendChild(tile);
          idx++;
        }
      }
      renderAll();
    }

    function renderTile(data) {
      const { tile, symbol, price, change } = data;
      tile.style.background = pctToColor(change);
      tile.innerHTML = `
        <div style="text-align:center;">
          <div>${symbol}</div>
          <small>$${price.toFixed(2)}</small>
          <small style="color:${change >= 0 ? '#86efac' : '#fca5a5'}">
            ${change >= 0 ? '+' : ''}${change.toFixed(2)}%
          </small>
        </div>
      `;
    }

    function renderAll() {
      for (const data of tiles.values()) renderTile(data);
      applyTransform();
    }

    function applyTransform() {
      map.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`;
    }

    function showTooltip(data) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <strong>${data.symbol}</strong><br/>
        Price: $${data.price.toFixed(2)}<br/>
        Change: ${data.change >= 0 ? '+' : ''}${data.change.toFixed(2)}%
      `;
    }

    function moveTooltip(e) {
      tooltip.style.left = (e.clientX + 12) + 'px';
      tooltip.style.top = (e.clientY + 12) + 'px';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      applyTransform();
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.4, 3);

      // Zoom around mouse position
      offsetX = mouseX - (mouseX - offsetX) * (newScale / scale);
      offsetY = mouseY - (mouseY - offsetY) * (newScale / scale);
      scale = newScale;

      applyTransform();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 20;
      offsetY = 20;
      applyTransform();
    });

    // Simulated real-time updates
    function updateMarket() {
      const count = 8 + Math.floor(Math.random() * 10);
      for (let i = 0; i < count; i++) {
        const symbol = symbols[Math.floor(Math.random() * symbols.length)];
        const data = tiles.get(symbol);

        // random walk
        data.change += rand(-0.6, 0.6);
        data.change = clamp(data.change, -8, 8);

        data.price *= (1 + data.change / 1000);
        data.price = clamp(data.price, 1, 2000);

        renderTile(data);
      }
      status.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
    }

    createTiles();
    setInterval(updateMarket, 1000);
  </script>
</body>
</html>
```

