      border-radius: 6px;
      font-size: 12px;
      display: none;
      white-space: nowrap;
    }

    canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }
    canvas:active { cursor: grabbing; }
  </style>
</head>
<body>
  <div id="toolbar">
    <b>Stock Heatmap</b><br>
    Wheel: zoom · Drag: pan · Hover: tooltip
  </div>
  <div id="tooltip"></div>
  <canvas id="chart"></canvas>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const state = {
      dpr: Math.max(1, window.devicePixelRatio || 1),
      width: 0,
      height: 0,
      scale: 1,
      offsetX: 0,
      offsetY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startOffsetX: 0,
      startOffsetY: 0,
      hover: null
    };

    // Generate sample stocks
    const stocks = Array.from({ length: 120 }, (_, i) => ({
      symbol: `STK${String(i + 1).padStart(3, '0')}`,
      price: 50 + Math.random() * 250,
      change: (Math.random() - 0.5) * 4
    }));

    function resize() {
      state.dpr = Math.max(1, window.devicePixelRatio || 1);
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      render();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Red for negative, green for positive
      const t = clamp((change + 5) / 10, 0, 1); // map [-5,5] -> [0,1]
      const r = Math.round(220 * (1 - t));
      const g = Math.round(220 * t);
      const b = 70;
      return `rgb(${r},${g},${b})`;
    }

    function computeGrid() {
      const baseCellW = 110;
      const baseCellH = 70;

      const cellW = baseCellW * state.scale;
      const cellH = baseCellH * state.scale;

      const cols = Math.max(1, Math.floor(state.width / cellW));
      const positions = [];

      for (let i = 0; i < stocks.length; i++) {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const x = state.offsetX + col * cellW;
        const y = state.offsetY + row * cellH;
        positions.push({ x, y, w: cellW - 6, h: cellH - 6, row, col });
      }

      return { cellW, cellH, cols, positions };
    }

    function render() {
      ctx.clearRect(0, 0, state.width, state.height);

      // Background
      const bg = ctx.createLinearGradient(0, 0, 0, state.height);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#111827');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, state.width, state.height);

      const { positions } = computeGrid();

      // Draw cells
      for (let i = 0; i < stocks.length; i++) {
        const s = stocks[i];
        const p = positions[i];

        // Skip offscreen for minimal performance
        if (p.x + p.w < 0 || p.y + p.h < 0 || p.x > state.width || p.y > state.height) continue;

        ctx.fillStyle = colorForChange(s.change);
        roundRect(ctx, p.x, p.y, p.w, p.h, 10);
        ctx.fill();

        // Text
        ctx.fillStyle = '#fff';
        ctx.font = `${Math.max(10, 14 * state.scale)}px system-ui, sans-serif`;
        ctx.fillText(s.symbol, p.x + 10, p.y + 22);
        ctx.font = `${Math.max(9, 12 * state.scale)}px system-ui, sans-serif`;
        ctx.fillText(`$${s.price.toFixed(2)}`, p.x + 10, p.y + 42);
        ctx.fillText(`${s.change >= 0 ? '+' : ''}${s.change.toFixed(2)}%`, p.x + 10, p.y + 58);

        // Hover highlight
        if (state.hover && state.hover.index === i) {
          ctx.strokeStyle = 'rgba(255,255,255,0.9)';
          ctx.lineWidth = 2;
          roundRect(ctx, p.x, p.y, p.w, p.h, 10);
          ctx.stroke();
        }
      }
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function screenToWorld(mx, my) {
      return {
        x: (mx - state.offsetX) / state.scale,
        y: (my - state.offsetY) / state.scale
      };
    }

    function hitTest(mx, my) {
      const baseCellW = 110;
      const baseCellH = 70;
      const cellW = baseCellW * state.scale;
      const cellH = baseCellH * state.scale;
      const cols = Math.max(1, Math.floor(state.width / cellW));
      const world = screenToWorld(mx, my);

      const col = Math.floor(world.x / baseCellW);
      const row = Math.floor(world.y / baseCellH);
      const index = row * cols + col;

      if (index < 0 || index >= stocks.length) return null;

      const x = state.offsetX + col * cellW;
      const y = state.offsetY + row * cellH;
      const w = cellW - 6;
      const h = cellH - 6;

      if (mx >= x && mx <= x + w && my >= y && my <= y + h) {
        return { index, x, y, w, h };
      }
      return null;
    }

    canvas.addEventListener('mousemove', (e) => {
      if (state.dragging) {
        state.offsetX = state.startOffsetX + (e.clientX - state.dragStartX);
        state.offsetY = state.startOffsetY + (e.clientY - state.dragStartY);
        render();
        return;
      }

      const hit = hitTest(e.clientX, e.clientY);
      state.hover = hit;

      if (hit) {
        const s = stocks[hit.index];
        tooltip.style.display = 'block';
        tooltip.style.left = (e.clientX + 12) + 'px';
        tooltip.style.top = (e.clientY + 12) + 'px';
        tooltip.innerHTML = `
          <b>${s.symbol}</b><br>
          Price: $${s.price.toFixed(2)}<br>
          Change: ${s.change >= 0 ? '+' : ''}${s.change.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = 'none';
      }

      render();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startOffsetX = state.offsetX;
      state.startOffsetY = state.offsetY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // Zoom around mouse position
      const mx = e.clientX;
      const my = e.clientY;
      const worldX = (mx - state.offsetX) / state.scale;
      const worldY = (my - state.offsetY) / state.scale;

      state.scale = newScale;
      state.offsetX = mx - worldX * state.scale;
      state.offsetY = my - worldY * state.scale;

      render();
    }, { passive: false });

    // Simulated real-time updates
    setInterval(() => {
      for (const s of stocks) {
        const delta = (Math.random() - 0.5) * 2;
        s.price = Math.max(1, s.price + delta);
        s.change = clamp(s.change + (Math.random() - 0.5) * 0.6, -5, 5);
      }
      render();
    }, 1000);

    window.addEventListener('resize', resize);
    resize();
  </script>
</body>
</html>
