</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div class="muted">Wheel: zoom · Drag: pan · Hover: inspect</div>
    <div id="status" class="muted">Initializing...</div>
  </div>

  <canvas id="canvas"></canvas>
  <div id="tooltip"></div>

  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const status = document.getElementById('status');

    // --- Data setup ---
    const cols = 14;
    const rows = 10;
    const stocks = Array.from({ length: cols * rows }, (_, i) => ({
      symbol: "STK" + String(i + 1).padStart(3, "0"),
      price: 50 + Math.random() * 150,
      change: 0
    }));

    // --- View transform ---
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // --- Interaction state ---
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    // --- Resize ---
    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(window.innerWidth * dpr);
      canvas.height = Math.floor(window.innerHeight * dpr);
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }
    window.addEventListener('resize', resize);

    // --- Helpers ---
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(change) {
      // change in percent roughly -5..+5
      const t = clamp((change + 5) / 10, 0, 1);
      const r = Math.round(255 * t);
      const g = Math.round(255 * (1 - Math.abs(t - 0.5) * 2));
      const b = Math.round(255 * (1 - t));
      return `rgb(${r},${g},${b})`;
    }

    function screenToWorld(x, y) {
      return {
        x: (x - offsetX) / scale,
        y: (y - offsetY) / scale
      };
    }

    function getCellAt(x, y) {
      const cellW = 90;
      const cellH = 60;
      const pad = 8;
      const world = screenToWorld(x, y);

      const col = Math.floor(world.x / (cellW + pad));
      const row = Math.floor(world.y / (cellH + pad));

      if (col < 0 || row < 0 || col >= cols || row >= rows) return null;

      const localX = world.x - col * (cellW + pad);
      const localY = world.y - row * (cellH + pad);
      if (localX > cellW || localY > cellH) return null;

      const idx = row * cols + col;
      return { idx, col, row };
    }

    // --- Drawing ---
    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;

      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      const cellW = 90;
      const cellH = 60;
      const pad = 8;

      stocks.forEach((s, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const x = col * (cellW + pad);
        const y = row * (cellH + pad);

        // Cell
        ctx.fillStyle = priceToColor(s.change);
        ctx.fillRect(x, y, cellW, cellH);

        // Border
        ctx.strokeStyle = "rgba(255,255,255,0.14)";
        ctx.strokeRect(x, y, cellW, cellH);

        // Text
        ctx.fillStyle = "rgba(255,255,255,0.95)";
        ctx.font = "bold 13px system-ui, sans-serif";
        ctx.fillText(s.symbol, x + 8, y + 20);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText("$" + s.price.toFixed(2), x + 8, y + 38);

        const ch = s.change >= 0 ? "+" : "";
        ctx.fillText(ch + s.change.toFixed(2) + "%", x + 8, y + 53);
      });

      ctx.restore();

      status.textContent = `Zoom: ${scale.toFixed(2)}x · Stocks: ${stocks.length}`;
    }

    // --- Real-time updates (simulated) ---
    function updatePrices() {
      stocks.forEach(s => {
        const delta = (Math.random() - 0.5) * 2.5;
        s.price = Math.max(1, s.price + delta);
        s.change = clamp(s.change + (Math.random() - 0.5) * 0.6, -10, 10);
      });
      draw();
    }
    setInterval(updatePrices, 1000);

    // --- Mouse interactions ---
    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        offsetX += e.clientX - lastX;
        offsetY += e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        draw();
      }

      const hit = getCellAt(e.clientX, e.clientY);
      if (hit) {
        const s = stocks[hit.idx];
        tooltip.style.display = 'block';
        tooltip.style.left = (e.clientX + 12) + 'px';
        tooltip.style.top = (e.clientY + 12) + 'px';
        tooltip.innerHTML = `
          <strong>${s.symbol}</strong><br/>
          Price: $${s.price.toFixed(2)}<br/>
          Change: ${s.change >= 0 ? '+' : ''}${s.change.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // Zoom around mouse position
      const wx = (mouseX - offsetX) / scale;
      const wy = (mouseY - offsetY) / scale;

      scale = clamp(scale * zoomFactor, 0.5, 3);

      offsetX = mouseX - wx * scale;
      offsetY = mouseY - wy * scale;

      draw();
    }, { passive: false });

    // --- Touch support (basic pan + pinch zoom omitted for minimalism) ---
    let touchStartX = 0;
    let touchStartY = 0;

    canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        dragging = true;
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
        lastX = touchStartX;
        lastY = touchStartY;
      }
    }, { passive: true });

    canvas.addEventListener('touchmove', (e) => {
      if (dragging && e.touches.length === 1) {
        const x = e.touches[0].clientX;
        const y = e.touches[0].clientY;
        offsetX += x - lastX;
        offsetY += y - lastY;
        lastX = x;
        lastY = y;
        draw();
      }
    }, { passive: true });

    canvas.addEventListener('touchend', () => {
      dragging = false;
      tooltip.style.display = 'none';
    });

    // Init
    resize();
  </script>
</body>
</html>
