    const status = document.getElementById('status');

    // Minimal dataset
    const symbols = ['AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','INTC'];
    const cols = 120; // time buckets

    // State for zoom/pan
