    let panX = 20;
    let panY = 20;
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let dragPanX = 0;
    let dragPanY = 0;

    // Build data: each symbol has a rolling array of values in [-1, 1]
    const data = symbols.map(() => Array.from({ length: cols }, () => (Math.random() - 0.5) * 0.3));

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v in [-1, 1]
      const abs = Math.abs(v);
      if (abs < 0.08) return '#334155'; // flat
      if (v > 0) {
        const g = 90 + Math.floor(120 * abs);
        return `rgb(20, ${g}, 60)`;
      } else {
        const r = 90 + Math.floor(140 * abs);
        return `rgb(${r}, 30, 40)`;
      }
    }

    function render() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;

      let html = '';
      for (let r = 0; r < symbols.length; r++) {
        html += `<div class="row-wrap">`;
        html += `<div class="label">${symbols[r]}</div>`;
        html += `<div class="row">`;
        for (let c = 0; c < cols; c++) {
          const v = data[r][c];
          const bg = colorForValue(v);
          html += `<div class="cell" style="background:${bg}">${Math.abs(v) > 0.85 ? '!' : ''}</div>`;
        }
        html += `</div></div>`;
      }
      heatmap.innerHTML = html;
    }

    function updateLiveData() {
      // Shift left and append a new random change for each symbol
      for (let r = 0; r < data.length; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = clamp(prev * 0.7 + (Math.random() - 0.5) * 0.6, -1, 1);
        data[r].push(next);
      }
      render();
      status.textContent = `Live update: ${new Date().toLocaleTimeString()}`;
    }

    // Zoom centered on mouse position
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 4);

      // Keep point under cursor stable
      panX = mx - (mx - panX) * (newScale / scale);
      panY = my - (my - panY) * (newScale / scale);
      scale = newScale;

      render();
    }, { passive: false });

    // Pan by dragging
    viewport.addEventListener('pointerdown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      dragPanX = panX;
      dragPanY = panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      panX = dragPanX + (e.clientX - startX);
      panY = dragPanY + (e.clientY - startY);
      render();
    });

    viewport.addEventListener('pointerup', (e) => {
      dragging = false;
      viewport.classList.remove('dragging');
      try { viewport.releasePointerCapture(e.pointerId); } catch {}
    });

    viewport.addEventListener('pointercancel', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      panX = 20;
      panY = 20;
      render();
    });

    // Initial render + live updates
    render();
    setInterval(updateLiveData, 1000);
  </script>
