<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      font-family: system-ui, sans-serif;
      background: #0b1020;
      color: #fff;
    }

    #toolbar {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 10;
      background: rgba(20, 24, 40, 0.9);
      padding: 10px 12px;
      border-radius: 10px;
