      position: fixed;
      pointer-events: none;
      background: rgba(0,0,0,0.85);
      color: white;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      line-height: 1.4;
      transform: translate(12px, 12px);
      display: none;
      z-index: 20;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div>Wheel: zoom • Drag: pan</div>
  </div>
  <canvas id="heatmap"></canvas>
  <div id="tooltip" class="tooltip"></div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const dpr = window.devicePixelRatio || 1;

    // Demo symbols
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","IBM","QCOM","AVGO",
      "JPM","BAC","WFC","C","GS","MS","V","MA"
    ];

    // Generate mock stock data
    const stocks = symbols.map((s, i) => ({
      symbol: s,
      price: 50 + Math.random() * 500,
      prev: 50 + Math.random() * 500,
      x: (i % 6) * 170,
      y: Math.floor(i / 6) * 120,
      w: 150,
      h: 100
    }));

    // View transform
    let scale = 1;
    let offsetX = 40;
    let offsetY = 40;

    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      canvas.width = Math.floor(window.innerWidth * dpr);
      canvas.height = Math.floor(window.innerHeight * dpr);
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceChange(stock) {
      return ((stock.price - stock.prev) / stock.prev) * 100;
    }

    function colorForChange(chg) {
      // Red for negative, green for positive
      const abs = Math.min(Math.abs(chg), 5);
      const t = abs / 5;
      if (chg >= 0) {
        const g = Math.floor(80 + 140 * t);
        return `rgb(20, ${g}, 70)`;
      } else {
        const r = Math.floor(80 + 140 * t);
        return `rgb(${r}, 40, 40)`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

      // Background grid
      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      for (const s of stocks) {
        const chg = priceChange(s);
        const fill = colorForChange(chg);

        ctx.fillStyle = fill;
        ctx.strokeStyle = "rgba(255,255,255,0.15)";
        ctx.lineWidth = 1 / scale;
        ctx.beginPath();
        roundRect(ctx, s.x, s.y, s.w, s.h, 12);
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = "#fff";
        ctx.font = `bold ${14 / scale}px system-ui`;
        ctx.fillText(s.symbol, s.x + 12, s.y + 24);

        ctx.font = `${12 / scale}px system-ui`;
        ctx.fillText(`$${s.price.toFixed(2)}`, s.x + 12, s.y + 48);
        ctx.fillText(`${chg >= 0 ? "+" : ""}${chg.toFixed(2)}%`, s.x + 12, s.y + 70);
      }

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function screenToWorld(px, py) {
      return {
        x: (px - offsetX) / scale,
        y: (py - offsetY) / scale
      };
    }

    function hitTest(px, py) {
      const p = screenToWorld(px, py);
      return stocks.find(s =>
        p.x >= s.x && p.x <= s.x + s.w &&
        p.y >= s.y && p.y <= s.y + s.h
      );
    }

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => dragging = false);

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        offsetX += e.clientX - lastX;
        offsetY += e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        draw();
      }

      const stock = hitTest(e.clientX, e.clientY);
      if (stock) {
        const chg = priceChange(stock);
        tooltip.style.display = 'block';
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
        tooltip.innerHTML = `
          <strong>${stock.symbol}</strong><br>
          Price: $${stock.price.toFixed(2)}<br>
          Change: ${chg >= 0 ? '+' : ''}${chg.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const worldBefore = screenToWorld(mouseX, mouseY);
      scale = clamp(scale * zoomFactor, 0.5, 4);
      offsetX = mouseX - worldBefore.x * scale;
      offsetY = mouseY - worldBefore.y * scale;

      draw();
    }, { passive: false });

    // Simulated real-time updates
    setInterval(() => {
      for (const s of stocks) {
        s.prev = s.price;
        const drift = (Math.random() - 0.5) * 4;
        s.price = Math.max(1, s.price + drift);
      }
      draw();
    }, 1000);

    window.addEventListener('resize', resize);

    resize();
  </script>
</body>
</html>
