            <strong>${stock.symbol}</strong><br/>
            Price: $${stock.price.toFixed(2)}<br/>
            Change: ${changePct >= 0 ? '+' : ''}${changePct.toFixed(2)}%
          `;
        });

        cell.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        grid.appendChild(cell);
      });
    }

    function updatePrices() {
      stocks.forEach(stock => {
        stock.prev = stock.price;
        // small random walk
        stock.price = Math.max(1, stock.price * (1 + (Math.random() - 0.5) * 0.02));
      });
      render();
    }

    // Zoom around mouse pointer
    heatmap.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = heatmap.getBoundingClientRect();

      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale *= zoomFactor;
      scale = Math.max(0.5, Math.min(3, scale));

      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    heatmap.addEventListener('mousedown', (e) => {
      dragging = true;
      heatmap.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      render();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      heatmap.classList.remove('dragging');
    });

    // Initial render
    render();

    // Real-time updates
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
