    }));

    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("reset");

    const width = window.innerWidth;
    const height = window.innerHeight;

    const svg = d3.select(container)
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    const g = svg.append("g");

    const cols = 5;
    const cellW = 180;
    const cellH = 120;
    const pad = 12;

    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#d73027", "#2c2c2c", "#1a9850"]);

    function layout() {
      data.forEach((d, i) => {
        d.x = (i % cols) * (cellW + pad);
        d.y = Math.floor(i / cols) * (cellH + pad);
      });
    }

    layout();

    const cells = g.selectAll(".cell-group")
      .data(data, d => d.symbol)
      .join("g")
      .attr("class", "cell-group")
      .attr("transform", d => `translate(${d.x},${d.y})`);

    cells.append("rect")
      .attr("class", "cell")
      .attr("rx", 10)
      .attr("ry", 10)
      .attr("width", cellW)
      .attr("height", cellH)
      .attr("fill", d => color(d.change))
      .on("mousemove", (event, d) => {
        tooltip.style.display = "block";
        tooltip.style.left = (event.clientX + 12) + "px";
        tooltip.style.top = (event.clientY + 12) + "px";
        tooltip.innerHTML = `
          <strong>${d.symbol}</strong><br/>
          Price: $${d.price.toFixed(2)}<br/>
          Change: ${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%
        `;
      })
      .on("mouseleave", () => {
        tooltip.style.display = "none";
      });

    cells.append("text")
      .attr("class", "label")
      .attr("x", cellW / 2)
      .attr("y", cellH / 2 - 10)
      .text(d => d.symbol);

    cells.append("text")
      .attr("class", "label")
      .attr("x", cellW / 2)
      .attr("y", cellH / 2 + 12)
      .text(d => `$${d.price.toFixed(2)}`);

    cells.append("text")
      .attr("class", "label")
      .attr("x", cellW / 2)
      .attr("y", cellH / 2 + 30)
      .text(d => `${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%`);

    function update() {
      cells.select("rect")
        .transition()
        .duration(300)
        .attr("fill", d => color(d.change));

      cells.selectAll("text")
        .data(d => [
          d.symbol,
          `$${d.price.toFixed(2)}`,
          `${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%`
        ])
        .text(d => d);
    }

    // Zoom/pan
    const zoom = d3.zoom()
      .scaleExtent([0.5, 5])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    resetBtn.addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    // Simulated real-time updates
    setInterval(() => {
      data.forEach(d => {
        const delta = (Math.random() - 0.5) * 4;
        d.price = Math.max(1, d.price + delta);
        d.change = Math.max(-10, Math.min(10, d.change + (Math.random() - 0.5) * 1.5));
      });
      update();
    }, 1000);

    // Resize handling
    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
```

