  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const zoomInBtn = document.getElementById('zoomIn');
    const zoomOutBtn = document.getElementById('zoomOut');
    const resetBtn = document.getElementById('reset');

    // Sample stock symbols
    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','NFLX',
      'AMD','INTC','ORCL','CRM','ADBE','QCOM','AVGO','UBER',
      'SHOP','SNOW','PLTR','SQ','PYPL','BA','JPM','BAC'
    ];

    // Layout settings
    const cols = 6;
    const cellW = 160;
    const cellH = 90;
    const gap = 10;

    // View transform
    let scale = 1;
    let tx = 20;
    let ty = 20;

    // Drag state
    let dragging = false;
    let startX = 0, startY = 0;
    let startTx = 0, startTy = 0;

    // Stock data
    const stocks = symbols.map(sym => ({
      sym,
      price: 50 + Math.random() * 450,
      prev: null,
      changePct: 0
    }));

    function colorForChange(chg) {
      // Green for positive, red for negative, neutral near zero
      const max = 5; // percent
      const t = Math.max(-1, Math.min(1, chg / max));
      if (t >= 0) {
        const g = Math.floor(80 + 140 * t);
        const r = Math.floor(40 + 40 * (1 - t));
        return `rgb(${r}, ${g}, 60)`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(120 + 120 * a);
        const g = Math.floor(50 + 40 * (1 - a));
        return `rgb(${r}, ${g}, 60)`;
      }
    }

    function render() {
      heatmap.innerHTML = '';

      stocks.forEach((s, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;

        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.style.left = `${col * (cellW + gap)}px`;
        cell.style.top = `${row * (cellH + gap)}px`;
        cell.style.width = `${cellW}px`;
        cell.style.height = `${cellH}px`;
        cell.style.background = colorForChange(s.changePct);

        cell.innerHTML = `
          <div class="sym">${s.sym}</div>
          <div>$${s.price.toFixed(2)}</div>
          <div class="chg">${s.changePct >= 0 ? '+' : ''}${s.changePct.toFixed(2)}%</div>
        `;

        cell.addEventListener('mousemove', (e) => {
          tooltip.style.display = 'block';
          tooltip.style.left = `${e.clientX + 12}px`;
          tooltip.style.top = `${e.clientY + 12}px`;
          tooltip.innerHTML = `
            <strong>${s.sym}</strong><br>
            Price: $${s.price.toFixed(2)}<br>
            Change: ${s.changePct >= 0 ? '+' : ''}${s.changePct.toFixed(2)}%
          `;
        });

        cell.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        heatmap.appendChild(cell);
      });

      heatmap.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    }

    function updatePrices() {
      stocks.forEach(s => {
        s.prev = s.price;
        const delta = (Math.random() - 0.5) * (s.price * 0.01); // +/-0.5%
        s.price = Math.max(1, s.price + delta);
        s.changePct = ((s.price - s.prev) / s.prev) * 100;
      });
      render();
      document.querySelector('.status').textContent =
        `Live updates • Scale: ${scale.toFixed(2)} • Drag to pan • Wheel to zoom`;
    }

    function setScale(newScale, centerX = viewport.clientWidth / 2, centerY = viewport.clientHeight / 2) {
      const minScale = 0.4;
      const maxScale = 3;
      const clamped = Math.max(minScale, Math.min(maxScale, newScale));

      // Zoom around cursor/center
      const worldX = (centerX - tx) / scale;
      const worldY = (centerY - ty) / scale;

      scale = clamped;
      tx = centerX - worldX * scale;
      ty = centerY - worldY * scale;

      render();
    }

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startTx = tx;
      startTy = ty;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      tx = startTx + (e.clientX - startX);
      ty = startTy + (e.clientY - startY);
      render();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      setScale(scale * zoomFactor, e.clientX, e.clientY);
    }, { passive: false });

    zoomInBtn.addEventListener('click', () => setScale(scale * 1.2));
    zoomOutBtn.addEventListener('click', () => setScale(scale / 1.2));
    resetBtn.addEventListener('click', () => {
      scale = 1;
      tx = 20;
      ty = 20;
      render();
    });

    // Initial render
    render();

    // Simulated real-time updates every second
    setInterval(updatePrices, 1000);
  </script>
