    let startY = 0;
    let basePanX = 0;
    let basePanY = 0;

    // data[row][col] = value between -1 and 1
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => (Math.random() * 2 - 1))
    );

    function valueToColor(v) {
      // red for negative, green for positive
      const intensity = Math.min(255, Math.floor(Math.abs(v) * 255));
      if (v >= 0) return `rgb(0, ${80 + intensity * 0.7}, 0)`;
      return `rgb(${80 + intensity * 0.7}, 0, 0)`;
    }

    function render() {
      heatmap.innerHTML = "";

      for (let r = 0; r < rows; r++) {
        const row = document.createElement("div");
        row.className = "row";

        const label = document.createElement("div");
        label.className = "label";
        label.textContent = stocks[r];
        row.appendChild(label);

        for (let c = 0; c < cols; c++) {
          const cell = document.createElement("div");
          cell.className = "cell";
          cell.style.background = valueToColor(data[r][c]);
          cell.dataset.stock = stocks[r];
          cell.dataset.col = c;
          cell.dataset.value = data[r][c].toFixed(3);

          cell.addEventListener("mouseenter", (e) => {
            tooltip.style.display = "block";
            tooltip.textContent = `${e.target.dataset.stock} | t=${e.target.dataset.col} | ${e.target.dataset.value}`;
          });

          cell.addEventListener("mousemove", (e) => {
            tooltip.style.left = e.clientX + 12 + "px";
            tooltip.style.top = e.clientY + 12 + "px";
          });

          cell.addEventListener("mouseleave", () => {
            tooltip.style.display = "none";
          });

          row.appendChild(cell);
        }

        heatmap.appendChild(row);
      }

      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function updateRandomCell() {
      const r = Math.floor(Math.random() * rows);
      const c = Math.floor(Math.random() * cols);
      data[r][c] += (Math.random() * 0.4 - 0.2);
      data[r][c] = Math.max(-1, Math.min(1, data[r][c]));
      render();
    }

    // Real-time updates
    setInterval(updateRandomCell, 300);

    // Zoom controls
    document.getElementById("zoomIn").onclick = () => {
      scale = Math.min(3, scale * 1.2);
      render();
    };

    document.getElementById("zoomOut").onclick = () => {
      scale = Math.max(0.5, scale / 1.2);
      render();
    };

    document.getElementById("reset").onclick = () => {
      scale = 1;
      panX = 0;
      panY = 0;
      render();
    };

    // Pan interactions
    wrap.addEventListener("mousedown", (e) => {
      dragging = true;
      wrap.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      basePanX = panX;
      basePanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = basePanX + (e.clientX - startX);
      panY = basePanY + (e.clientY - startY);
      render();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      wrap.classList.remove("dragging");
    });

    // Initial render
    render();
  </script>
</body>
</html>
