      const max = 10;
      const t = Math.max(-1, Math.min(1, change / max));
      if (t >= 0) {
        const g = Math.round(80 + 175 * t);
        return `rgb(20, ${g}, 80)`;
      } else {
        const r = Math.round(80 + 175 * (-t));
        return `rgb(${r}, 40, 40)`;
      }
    }

    function render() {
      viewport.innerHTML = '';

      data.forEach((d, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = startX + col * (cellW + gap);
        const y = startY + row * (cellH + gap);

        const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        g.setAttribute('transform', `translate(${x}, ${y})`);

        const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        rect.setAttribute('width', cellW);
        rect.setAttribute('height', cellH);
        rect.setAttribute('rx', 12);
        rect.setAttribute('fill', colorForChange(d.change));
        rect.classList.add('cell');

        rect.addEventListener('mouseenter', (e) => showTooltip(e, d));
        rect.addEventListener('mousemove', (e) => moveTooltip(e));
        rect.addEventListener('mouseleave', hideTooltip);
        rect.addEventListener('click', () => alert(`${d.symbol}\nPrice: $${d.price.toFixed(2)}\nChange: ${d.change.toFixed(2)}`));

        const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        label.setAttribute('x', 16);
        label.setAttribute('y', 32);
        label.setAttribute('class', 'label');
        label.textContent = d.symbol;

        const price = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        price.setAttribute('x', 16);
        price.setAttribute('y', 62);
        price.setAttribute('class', 'label');
        price.setAttribute('font-size', '20');
        price.setAttribute('font-weight', 'bold');
        price.textContent = `$${d.price.toFixed(2)}`;

        const change = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        change.setAttribute('x', 16);
        change.setAttribute('y', 92);
        change.setAttribute('class', 'label');
        change.setAttribute('fill', d.change >= 0 ? '#86efac' : '#fca5a5');
        change.textContent = `${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}`;

        g.appendChild(rect);
        g.appendChild(label);
        g.appendChild(price);
        g.appendChild(change);
        viewport.appendChild(g);
      });

      applyTransform();
    }

    function applyTransform() {
      viewport.setAttribute(
        'transform',
        `translate(${translateX}, ${translateY}) scale(${scale})`
      );
    }

    function showTooltip(e, d) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br>
        Price: $${d.price.toFixed(2)}<br>
        Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      tooltip.style.left = (e.clientX + 12) + 'px';
      tooltip.style.top = (e.clientY + 12) + 'px';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    // Zoom with mouse wheel
    svg.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.min(4, Math.max(0.5, scale * zoomFactor));

      // Zoom around cursor
      const rect = svg.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      translateX = mx - (mx - translateX) * (newScale / scale);
      translateY = my - (my - translateY) * (newScale / scale);
      scale = newScale;

      applyTransform();
    }, { passive: false });

    // Pan with mouse drag
    svg.addEventListener('mousedown', (e) => {
      isPanning = true;
      panStart = { x: e.clientX, y: e.clientY };
      viewStart = { x: translateX, y: translateY };
    });

    window.addEventListener('mousemove', (e) => {
      if (!isPanning) return;
      translateX = viewStart.x + (e.clientX - panStart.x);
      translateY = viewStart.y + (e.clientY - panStart.y);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      isPanning = false;
    });

    // Basic touch pan
    let touchStartDist = 0;
    let touchStartScale = 1;

    svg.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        isPanning = true;
        panStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
        viewStart = { x: translateX, y: translateY };
      } else if (e.touches.length === 2) {
        isPanning = false;
        touchStartDist = distance(e.touches[0], e.touches[1]);
        touchStartScale = scale;
      }
    }, { passive: true });

    svg.addEventListener('touchmove', (e) => {
      if (e.touches.length === 1 && isPanning) {
        translateX = viewStart.x + (e.touches[0].clientX - panStart.x);
        translateY = viewStart.y + (e.touches[0].clientY - panStart.y);
        applyTransform();
      } else if (e.touches.length === 2) {
        e.preventDefault();
        const dist = distance(e.touches[0], e.touches[1]);
        const newScale = Math.min(4, Math.max(0.5, touchStartScale * (dist / touchStartDist)));
        scale = newScale;
        applyTransform();
      }
    }, { passive: false });

    svg.addEventListener('touchend', () => {
      isPanning = false;
    });

    function distance(a, b) {
      return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
    }

    resetBtn.addEventListener('click', () => {
      scale = 1;
      translateX = 0;
      translateY = 0;
      applyTransform();
    });

    // Real-time updates simulation
    setInterval(() => {
      data.forEach(d => {
        // small random walk
        d.change = Math.max(-10, Math.min(10, d.change + (Math.random() - 0.5) * 1.5));
        d.price = Math.max(1, d.price + (Math.random() - 0.5) * 4);
      });
      render();
    }, 1000);

    render();
  </script>
</body>
</html>
```

