  <script>
    const symbols = [
      "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL",
      "META", "TSLA", "AMD", "INTC", "NFLX",
      "ORCL", "CRM", "ADBE", "QCOM", "AVGO"
    ];

    const hours = Array.from({ length: 20 }, (_, i) => `T${i + 1}`);

    const heatmap = document.getElementById("heatmap");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");

    let scale = 1;
    let panX = 20;
    let panY = 20;
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startPanX = 0;
    let startPanY = 0;

    // Fake stock data
    const data = symbols.map(symbol => ({
      symbol,
      prices: hours.map(() => 100 + Math.random() * 50)
    }));

    function colorForChange(change) {
      // change in percent
      const max = 5;
      const clamped = Math.max(-max, Math.min(max, change));
      const t = (clamped + max) / (2 * max); // 0..1
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      return `rgb(${r}, ${g}, 80)`;
    }

    function buildHeatmap() {
      heatmap.innerHTML = "";

      for (let r = 0; r < symbols.length; r++) {
        const row = document.createElement("div");
        row.className = "row";

        for (let c = 0; c < hours.length; c++) {
          const cell = document.createElement("div");
          cell.className = "cell";

          const price = data[r].prices[c];
          const prev = c > 0 ? data[r].prices[c - 1] : price;
          const changePct = ((price - prev) / prev) * 100;

          cell.style.background = colorForChange(changePct);
          cell.dataset.symbol = data[r].symbol;
          cell.dataset.hour = hours[c];
          cell.dataset.price = price.toFixed(2);
          cell.dataset.change = changePct.toFixed(2);

          cell.innerHTML = `
            <div class="label">${data[r].symbol}</div>
            <div class="price">${price.toFixed(1)}</div>
          `;

          row.appendChild(cell);
        }

        heatmap.appendChild(row);
      }

      applyTransform();
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
      status.textContent = `Live updates: on | Zoom: ${scale.toFixed(2)}x`;
    }

    function resetView() {
      scale = 1;
      panX = 20;
      panY = 20;
      applyTransform();
    }

    function zoomAt(factor, cx = window.innerWidth / 2, cy = window.innerHeight / 2) {
      const rect = viewport.getBoundingClientRect();
      const x = cx - rect.left;
      const y = cy - rect.top;

      const worldX = (x - panX) / scale;
      const worldY = (y - panY) / scale;

      scale *= factor;
      scale = Math.max(0.5, Math.min(4, scale));

      panX = x - worldX * scale;
      panY = y - worldY * scale;

      applyTransform();
    }

    // Mouse wheel zoom
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 0.9;
      zoomAt(factor, e.clientX, e.clientY);
    }, { passive: false });

    // Drag pan
    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    // Tooltip
    heatmap.addEventListener("mousemove", (e) => {
      const cell = e.target.closest(".cell");
      if (!cell) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = (e.clientX + 12) + "px";
      tooltip.style.top = (e.clientY + 12) + "px";
      tooltip.innerHTML = `
        <strong>${cell.dataset.symbol}</strong> @ ${cell.dataset.hour}<br/>
        Price: $${cell.dataset.price}<br/>
        Change: ${cell.dataset.change}%
      `;
    });

    heatmap.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    // Simulated real-time updates
    function updatePrices() {
      for (const row of data) {
        const last = row.prices[row.prices.length - 1];
        const next = last * (1 + (Math.random() - 0.5) * 0.02); // ±1%
        row.prices.shift();
        row.prices.push(next);
      }
      buildHeatmap();
    }

    // Buttons
    document.getElementById("resetBtn").addEventListener("click", resetView);
    document.getElementById("zoomInBtn").addEventListener("click", () => zoomAt(1.2));
    document.getElementById("zoomOutBtn").addEventListener("click", () => zoomAt(0.8));

    buildHeatmap();
    setInterval(updatePrices, 1000);
  </script>
