    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","AMD",
      "NFLX","INTC","ORCL","IBM","CRM","ADBE","QCOM","AVGO"
    ];

    const rows = 4;
    const cols = 4;

    const viewport = document.getElementById("viewport");
    const world = document.getElementById("world");
    const grid = document.getElementById("grid");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");

    let data = symbols.map(sym => ({
      sym,
      price: 100 + Math.random() * 400,
      chg: (Math.random() - 0.5) * 6
    }));

    // View transform
    let scale = 1;
    let tx = 40;
    let ty = 40;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function updateTransform() {
      world.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    }

    function colorForChange(chg) {
      // red -> gray -> green
      const max = 6;
      const t = clamp((chg + max) / (2 * max), 0, 1);
      const r = Math.round(220 * (1 - t) + 40 * t);
      const g = Math.round(60 * (1 - t) + 180 * t);
      const b = Math.round(70 * (1 - t) + 70 * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function render() {
      grid.style.gridTemplateColumns = `repeat(${cols}, 72px)`;
      grid.innerHTML = "";
      data.forEach(item => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = colorForChange(item.chg);
        cell.dataset.sym = item.sym;
        cell.dataset.price = item.price.toFixed(2);
        cell.dataset.chg = item.chg.toFixed(2);
        cell.innerHTML = `
          <div class="sym">${item.sym}</div>
          <div class="chg">${item.chg >= 0 ? "+" : ""}${item.chg.toFixed(2)}%</div>
        `;
        grid.appendChild(cell);
      });
    }

    function updateRandomPrices() {
      data = data.map(item => {
        const delta = (Math.random() - 0.5) * 4;
        const chg = clamp(item.chg + (Math.random() - 0.5) * 0.8, -8, 8);
        return {
          sym: item.sym,
          price: Math.max(1, item.price + delta),
          chg
        };
      });
      render();
    }

    // Real-time updates
    setInterval(updateRandomPrices, 1000);

    // Zoom with mouse wheel
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(scale * zoomFactor, 0.5, 3);

      // Zoom toward mouse position
      tx = mouseX - (mouseX - tx) * (nextScale / scale);
      ty = mouseY - (mouseY - ty) * (nextScale / scale);
      scale = nextScale;

      updateTransform();
    }, { passive: false });

    // Pan with drag
    let dragging = false;
    let startX = 0, startY = 0;
    let startTx = 0, startTy = 0;

    viewport.addEventListener("pointerdown", (e) => {
