## 3) Backend — `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory data store
let boards = {
  todo: [
    { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
    { id: "task-2", title: "Design UI", description: "Create wireframes" }
  ],
  inProgress: [
    { id: "task-3", title: "Build backend", description: "Set up API and sockets" }
  ],
  done: [
    { id: "task-4", title: "Research requirements", description: "Gather user stories" }
  ]
};

function broadcastBoards() {
  io.emit("boards:update", boards);
}

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, task } = req.body;

  if (!columnId || !task?.title) {
    return res.status(400).json({ error: "columnId and task.title are required" });
  }

  const newTask = {
    id: `task-${Date.now()}`,
    title: task.title,
    description: task.description || ""
  };

  boards[columnId] = boards[columnId] || [];
  boards[columnId].push(newTask);

  broadcastBoards();
  res.status(201).json(newTask);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  for (const columnId of Object.keys(boards)) {
    const taskIndex = boards[columnId].findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      boards[columnId][taskIndex] = {
        ...boards[columnId][taskIndex],
        title: title ?? boards[columnId][taskIndex].title,
        description: description ?? boards[columnId][taskIndex].description
      };

      broadcastBoards();
      return res.json(boards[columnId][taskIndex]);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const columnId of Object.keys(boards)) {
    const taskIndex = boards[columnId].findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      const deleted = boards[columnId].splice(taskIndex, 1)[0];
      broadcastBoards();
      return res.json(deleted);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

// Move task between columns
app.post("/api/tasks/move", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  if (!taskId || !fromColumnId || !toColumnId) {
    return res.status(400).json({ error: "taskId, fromColumnId, toColumnId required" });
  }

  const fromList = boards[fromColumnId];
  const toList = boards[toColumnId];
  if (!fromList || !toList) {
    return res.status(404).json({ error: "Invalid columns" });
  }

  const fromIndex = fromList.findIndex((t) => t.id === taskId);
  if (fromIndex === -1) {
    return res.status(404).json({ error: "Task not found in source column" });
  }

  const [task] = fromList.splice(fromIndex, 1);
  const insertIndex = typeof toIndex === "number" ? toIndex : toList.length;
  toList.splice(insertIndex, 0, task);

  broadcastBoards();
  res.json({ success: true, boards });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("boards:sync", (clientBoards) => {
    boards = clientBoards;
    broadcastBoards();
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

