## 7) Frontend — `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

const initialColumns = {
  todo: { id: "todo", title: "To Do" },
  inProgress: { id: "inProgress", title: "In Progress" },
  done: { id: "done", title: "Done" }
};

function findTaskById(boards, taskId) {
  for (const columnId of Object.keys(boards)) {
    const task = boards[columnId].find((t) => t.id === taskId);
    if (task) return { task, columnId };
  }
  return null;
}

function App() {
  const [boards, setBoards] = useState({ todo: [], inProgress: [], done: [] });
  const [activeTask, setActiveTask] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDesc, setNewTaskDesc] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    axios.get(`${API_URL}/api/boards`).then((res) => setBoards(res.data));

    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
    });

    return () => {
      socket.off("boards:update");
    };
  }, []);

  const columnIds = useMemo(() => Object.keys(initialColumns), []);

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    await axios.post(`${API_URL}/api/tasks`, {
      columnId: selectedColumn,
      task: {
        title: newTaskTitle,
        description: newTaskDesc
      }
    });

    setNewTaskTitle("");
    setNewTaskDesc("");
  };

  const handleDragStart = (event) => {
    const taskId = event.active.id;
    const found = findTaskById(boards, taskId);
    setActiveTask(found?.task || null);
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    setActiveTask(null);

    if (!over) return;

    const activeId = active.id;
    const overId = over.id;

    const activeInfo = findTaskById(boards, activeId);
    if (!activeInfo) return;

    const fromColumnId = activeInfo.columnId;

    // Determine target column
    let toColumnId = overId;
    let toIndex = boards[toColumnId]?.length ?? 0;

    // If dropped over a task, infer column and index
    for (const columnId of Object.keys(boards)) {
      const idx = boards[columnId].findIndex((t) => t.id === overId);
      if (idx !== -1) {
        toColumnId = columnId;
        toIndex = idx;
        break;
      }
    }

    if (fromColumnId === toColumnId) {
      const oldIndex = boards[fromColumnId].findIndex((t) => t.id === activeId);
      const newIndex = boards[toColumnId].findIndex((t) => t.id === overId);

      if (oldIndex !== newIndex) {
        const updated = {
          ...boards,
          [fromColumnId]: arrayMove(boards[fromColumnId], oldIndex, newIndex)
        };
        setBoards(updated);
        socket.emit("boards:sync", updated);
      }
      return;
    }

    const sourceTasks = [...boards[fromColumnId]];
    const targetTasks = [...boards[toColumnId]];
    const sourceIndex = sourceTasks.findIndex((t) => t.id === activeId);

    const [movedTask] = sourceTasks.splice(sourceIndex, 1);
    targetTasks.splice(toIndex, 0, movedTask);

    const updated = {
      ...boards,
      [fromColumnId]: sourceTasks,
      [toColumnId]: targetTasks
    };

    setBoards(updated);
    socket.emit("boards:sync", updated);
  };

  const handleDeleteTask = async (taskId) => {
    await axios.delete(`${API_URL}/api/tasks/${taskId}`);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <form className="task-form" onSubmit={handleAddTask}>
        <input
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="Task title"
        />
        <input
          value={newTaskDesc}
          onChange={(e) => setNewTaskDesc(e.target.value)}
          placeholder="Task description"
        />
        <select value={selectedColumn} onChange={(e) => setSelectedColumn(e.target.value)}>
          <option value="todo">To Do</option>
          <option value="inProgress">In Progress</option>
          <option value="done">Done</option>
        </select>
        <button type="submit">Add Task</button>
      </form>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {columnIds.map((columnId) => (
            <Column
              key={columnId}
              column={initialColumns[columnId]}
              tasks={boards[columnId] || []}
              onDeleteTask={handleDeleteTask}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} dragging /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onDeleteTask }) {
  return (
    <div className="column">
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" id={column.id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} onDeleteTask={onDeleteTask} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

function TaskCard({ task, onDeleteTask, dragging = false }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging || dragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-card-top">
        <strong>{task.title}</strong>
        {!dragging && onDeleteTask && (
          <button
            className="delete-btn"
            onClick={(e) => {
              e.stopPropagation();
              onDeleteTask(task.id);
            }}
          >
            ×
          </button>
        )}
      </div>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

export default App;
```

