## 3) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory data store
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout", description: "Create wireframes and layout", status: "todo" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow", status: "todo" },
    "task-3": { id: "task-3", title: "Build drag-and-drop", description: "Kanban interactions", status: "doing" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", status = "todo" } = req.body;
  const id = `task-${Date.now()}`;

  const newTask = { id, title, description, status };
  board.tasks[id] = newTask;
  board.columns[status].taskIds.unshift(id);

  io.emit("board:update", board);
  res.status(201).json(newTask);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];

  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, status } = req.body;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  if (status && status !== task.status) {
    const oldStatus = task.status;
    board.columns[oldStatus].taskIds = board.columns[oldStatus].taskIds.filter(tid => tid !== id);
    board.columns[status].taskIds.unshift(id);
    task.status = status;
  }

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];

  if (!task) return res.status(404).json({ error: "Task not found" });

  board.columns[task.status].taskIds = board.columns[task.status].taskIds.filter(tid => tid !== id);
  delete board.tasks[id];

  io.emit("board:update", board);
  res.json({ success: true });
});

// Drag-and-drop reorder/move endpoint
app.put("/api/board/move", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  if (
    !board.columns[sourceColumnId] ||
    !board.columns[destinationColumnId] ||
    sourceIndex === undefined ||
    destinationIndex === undefined
  ) {
    return res.status(400).json({ error: "Invalid move payload" });
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  const [movedTaskId] = sourceTaskIds.splice(sourceIndex, 1);

  if (!movedTaskId) return res.status(400).json({ error: "No task at source index" });

  if (sourceColumnId === destinationColumnId) {
    sourceTaskIds.splice(destinationIndex, 0, movedTaskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
  } else {
    const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
    destinationTaskIds.splice(destinationIndex, 0, movedTaskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
    board.columns[destinationColumnId].taskIds = destinationTaskIds;
    board.tasks[movedTaskId].status = destinationColumnId;
  }

  io.emit("board:update", board);
  res.json({ success: true, board });
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("board:move", (payload) => {
    const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    const [movedTaskId] = sourceTaskIds.splice(sourceIndex, 1);

    if (!movedTaskId) return;

    if (sourceColumnId === destinationColumnId) {
      sourceTaskIds.splice(destinationIndex, 0, movedTaskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
    } else {
      const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
      destinationTaskIds.splice(destinationIndex, 0, movedTaskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
      board.columns[destinationColumnId].taskIds = destinationTaskIds;
      board.tasks[movedTaskId].status = destinationColumnId;
    }

    io.emit("board:update", board);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
