```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:3001");

const COLUMN_ORDER = ["todo", "doing", "done"];

function TaskCard({ task, listeners, attributes, setNodeRef, transform, transition, isDragging }) {
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  return (
    <TaskCard
      task={task}
      attributes={attributes}
      listeners={listeners}
      setNodeRef={setNodeRef}
      transform={transform}
      transition={transition}
      isDragging={isDragging}
    />
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <SortableTask key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [activeTaskId, setActiveTaskId] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    fetch("http://localhost:3001/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update", setBoard);
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const columnId of COLUMN_ORDER) {
      const column = board.columns[columnId];
      result[columnId] = column.taskIds.map((id) => board.tasks[id]).filter(Boolean);
    }
    return result;
  }, [board]);

  const activeTask = activeTaskId && board ? board.tasks[activeTaskId] : null;

  async function createTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    await fetch("http://localhost:3001/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDescription,
        status: "todo"
      })
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  }

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return COLUMN_ORDER.find((colId) => board.columns[colId].taskIds.includes(taskId));
  }

  async function handleDragStart(event) {
    setActiveTaskId(event.active.id);
  }

  async function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTaskId(null);

    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumnId = findColumnByTaskId(activeId);
    const destinationColumnId =
      board.columns[overId] ? overId : findColumnByTaskId(overId);

    if (!sourceColumnId || !destinationColumnId) return;

    const sourceTasks = [...tasksByColumn[sourceColumnId]];
    const destinationTasks = [...tasksByColumn[destinationColumnId]];

    const sourceIndex = sourceTasks.findIndex((t) => t.id === activeId);

    let destinationIndex;
    if (board.columns[overId]) {
      destinationIndex = destinationTasks.length;
    } else {
      destinationIndex = destinationTasks.findIndex((t) => t.id === overId);
      if (destinationIndex < 0) destinationIndex = destinationTasks.length;
    }

    if (sourceColumnId === destinationColumnId) {
      const oldIndex = sourceTasks.findIndex((t) => t.id === activeId);
      const newIndex = destinationTasks.findIndex((t) => t.id === overId);
      if (oldIndex !== newIndex) {
        const reordered = arrayMove(sourceTasks, oldIndex, newIndex);
        // optimistic update
        setBoard((prev) => {
          const next = structuredClone(prev);
          next.columns[sourceColumnId].taskIds = reordered.map((t) => t.id);
          return next;
        });
        socket.emit("board:move", {
          sourceColumnId,
          destinationColumnId,
          sourceIndex: oldIndex,
          destinationIndex: newIndex
        });
      }
    } else {
      setBoard((prev) => {
        const next = structuredClone(prev);
        next.columns[sourceColumnId].taskIds = next.columns[sourceColumnId].taskIds.filter((id) => id !== activeId);
        next.columns[destinationColumnId].taskIds.splice(destinationIndex, 0, activeId);
        next.tasks[activeId].status = destinationColumnId;
        return next;
      });

      socket.emit("board:move", {
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex
      });
    }
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>

        <form className="new-task-form" onSubmit={createTask}>
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
            placeholder="Description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {COLUMN_ORDER.map((columnId) => (
            <Column
              key={columnId}
              column={board.columns[columnId]}
              tasks={tasksByColumn[columnId]}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? (
            <div className="task-card dragging">
              <h4>{activeTask.title}</h4>
              <p>{activeTask.description}</p>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

