## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Design wireframes", description: "Create initial UI mockups" },
      { id: "t2", title: "Set up auth", description: "Implement login flow" }
    ],
    doing: [
      { id: "t3", title: "Build task board", description: "Implement drag and drop" }
    ],
    done: [
      { id: "t4", title: "Project kickoff", description: "Initial planning meeting" }
    ]
  }
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Send current state to newly connected client
  socket.emit("state:init", state);

  // Add task
  socket.on("task:add", (task) => {
    const { columnId, title, description } = task;
    const newTask = {
      id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title,
      description
    };

    state.columns[columnId].unshift(newTask);
    io.emit("state:update", state);
  });

  // Move task
  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromCol = state.columns[fromColumnId];
    const toCol = state.columns[toColumnId];

    const taskIndex = fromCol.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromCol.splice(taskIndex, 1);
    toCol.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  // Edit task
  socket.on("task:edit", ({ taskId, columnId, title, description }) => {
    const col = state.columns[columnId];
    const task = col.find((t) => t.id === taskId);
    if (!task) return;

    task.title = title;
    task.description = description;

    io.emit("state:update", state);
  });

  // Delete task
  socket.on("task:delete", ({ taskId, columnId }) => {
    const col = state.columns[columnId];
    const idx = col.findIndex((t) => t.id === taskId);
    if (idx === -1) return;

    col.splice(idx, 1);
    io.emit("state:update", state);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

