## 6) `public/app.js`

```js
const socket = io();

let appState = {
  columns: { todo: [], doing: [], done: [] }
};

const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const addTaskBtn = document.getElementById("addTaskBtn");
const cancelBtn = document.getElementById("cancelBtn");

const taskIdInput = document.getElementById("taskId");
const taskColumnInput = document.getElementById("taskColumn");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const dialogTitle = document.getElementById("dialogTitle");

let dragData = null;

socket.on("state:init", (state) => {
  appState = state;
  renderBoard();
});

socket.on("state:update", (state) => {
  appState = state;
  renderBoard();
});

function renderBoard() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    appState.columns[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        dragData = {
          taskId: task.id,
          fromColumnId: columnId,
          fromIndex: index
        };
        e.dataTransfer.effectAllowed = "move";
      });

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        openEditDialog(task, columnId);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId });
      });

      list.appendChild(taskEl);
    });

    const columnEl = document.querySelector(`.column[data-column="${columnId}"]`);
    columnEl.addEventListener("dragover", (e) => e.preventDefault());
    columnEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!dragData) return;

      const targetList = document.getElementById(columnId);
      const targetTask = e.target.closest(".task");
      const toIndex = targetTask
        ? [...targetList.children].indexOf(targetTask)
        : appState.columns[columnId].length;

      socket.emit("task:move", {
        taskId: dragData.taskId,
        fromColumnId: dragData.fromColumnId,
        toColumnId: columnId,
        toIndex
      });

      dragData = null;
    });
  });
}

function openAddDialog() {
  dialogTitle.textContent = "Add Task";
  taskIdInput.value = "";
  taskColumnInput.value = "todo";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskDialog.showModal();
}

function openEditDialog(task, columnId) {
  dialogTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskColumnInput.value = columnId;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskDialog.showModal();
}

addTaskBtn.addEventListener("click", openAddDialog);
cancelBtn.addEventListener("click", () => taskDialog.close());

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const taskId = taskIdInput.value;
  const columnId = taskColumnInput.value;
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();

  if (!title) return;

  if (taskId) {
    socket.emit("task:edit", {
      taskId,
      columnId,
      title,
      description
    });
  } else {
    socket.emit("task:add", {
      columnId,
      title,
      description
    });
  }

  taskDialog.close();
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
