  todo: [
    { id: "t1", title: "Design homepage", description: "Create wireframes" },
    { id: "t2", title: "Set up auth", description: "Login and signup flow" }
  ],
  doing: [
    { id: "t3", title: "Build API", description: "Create task endpoints" }
  ],
  done: []
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board", (req, res) => {
  board = req.body;
  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Send current board state immediately
  socket.emit("board:update", board);

  socket.on("task:add", (task) => {
    const column = task.column || "todo";
    const newTask = {
      id: `task-${Date.now()}`,
      title: task.title || "Untitled Task",
      description: task.description || ""
    };

    board[column].unshift(newTask);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const fromList = board[fromColumn];
    const toList = board[toColumn];

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);

    if (typeof toIndex === "number" && toIndex >= 0 && toIndex <= toList.length) {
      toList.splice(toIndex, 0, task);
    } else {
      toList.push(task);
    }

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, column }) => {
    if (!board[column]) return;
    board[column] = board[column].filter((t) => t.id !== taskId);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
