## 5) Frontend logic (`public/app.js`)

```js
const socket = io();

let boardState = {
  todo: [],
  doing: [],
  done: []
};

const taskTitle = document.getElementById("taskTitle");
const taskDesc = document.getElementById("taskDesc");
const taskColumn = document.getElementById("taskColumn");
const addTaskBtn = document.getElementById("addTaskBtn");

const columns = document.querySelectorAll(".column");
const lists = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let draggedTask = null;

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitle.value.trim();
  const description = taskDesc.value.trim();
  const column = taskColumn.value;

  if (!title) return;

  socket.emit("task:add", { title, description, column });

  taskTitle.value = "";
  taskDesc.value = "";
  taskTitle.focus();
});

function renderBoard() {
  Object.keys(lists).forEach((column) => {
    lists[column].innerHTML = "";

    boardState[column].forEach((task, index) => {
      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.column = column;
      card.dataset.index = index;

      card.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button data-delete="${task.id}">Delete</button>
        </div>
      `;

      card.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column,
          fromIndex: index
        };
      });

      card.addEventListener("dragend", () => {
        draggedTask = null;
      });

      card.querySelector("[data-delete]").addEventListener("click", (e) => {
        e.stopPropagation();
        socket.emit("task:delete", { taskId: task.id, column });
      });

      lists[column].appendChild(card);
    });
  });
}

columns.forEach((columnEl) => {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    if (!draggedTask) return;

    const toColumn = columnEl.dataset.column;
    const toList = boardState[toColumn];

    // Determine drop index based on mouse position
    const afterElement = getDragAfterElement(lists[toColumn], e.clientY);
    const toIndex = afterElement
      ? [...lists[toColumn].children].indexOf(afterElement)
      : toList.length;

    socket.emit("task:move", {
      taskId: draggedTask.taskId,
      fromColumn: draggedTask.fromColumn,
      toColumn,
      toIndex
    });
  });
});

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task-card:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY, element: null }
  ).element;
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

