### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { BoardState, initialBoardState } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = initialBoardState;

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/board/reset", (_req, res) => {
  boardState = initialBoardState;
  io.emit("board:update", boardState);
  res.json({ ok: true, boardState });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (payload: { title: string; description?: string; columnId: string }) => {
    const id = `task-${Date.now()}`;
    const task = {
      id,
      title: payload.title,
      description: payload.description,
      createdAt: Date.now()
    };

    boardState = {
      ...boardState,
      tasks: {
        ...boardState.tasks,
        [id]: task
      },
      columns: {
        ...boardState.columns,
        [payload.columnId]: {
          ...boardState.columns[payload.columnId],
          taskIds: [...boardState.columns[payload.columnId].taskIds, id]
        }
      }
    };

    io.emit("board:update", boardState);
  });

  socket.on(
    "task:move",
    (payload: { taskId: string; sourceColumnId: string; destinationColumnId: string; destinationIndex: number }) => {
      const source = boardState.columns[payload.sourceColumnId];
      const destination = boardState.columns[payload.destinationColumnId];

      if (!source || !destination) return;

      const sourceTaskIds = [...source.taskIds];
      const destinationTaskIds = payload.sourceColumnId === payload.destinationColumnId
        ? sourceTaskIds
        : [...destination.taskIds];

      const sourceIndex = sourceTaskIds.indexOf(payload.taskId);
      if (sourceIndex === -1) return;

      sourceTaskIds.splice(sourceIndex, 1);

      if (payload.sourceColumnId === payload.destinationColumnId) {
        sourceTaskIds.splice(payload.destinationIndex, 0, payload.taskId);
      } else {
        destinationTaskIds.splice(payload.destinationIndex, 0, payload.taskId);
      }

      boardState = {
        ...boardState,
        columns: {
          ...boardState.columns,
          [payload.sourceColumnId]: {
            ...source,
            taskIds: sourceTaskIds
          },
          [payload.destinationColumnId]: {
            ...destination,
            taskIds: destinationTaskIds
          }
        }
      };

      io.emit("board:update", boardState);
    }
  );

  socket.on("task:update", (payload: { taskId: string; title: string; description?: string; assignee?: string }) => {
    const task = boardState.tasks[payload.taskId];
    if (!task) return;

    boardState = {
      ...boardState,
      tasks: {
        ...boardState.tasks,
        [payload.taskId]: {
          ...task,
          title: payload.title,
          description: payload.description,
          assignee: payload.assignee
        }
      }
    };

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (payload: { taskId: string; columnId: string }) => {
    const column = boardState.columns[payload.columnId];
    if (!column) return;

    const taskIds = column.taskIds.filter((id) => id !== payload.taskId);
    const tasks = { ...boardState.tasks };
    delete tasks[payload.taskId];

    boardState = {
      ...boardState,
      tasks,
      columns: {
        ...boardState.columns,
        [payload.columnId]: {
          ...column,
          taskIds
        }
      }
    };

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

