import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  closestCorners,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";
import { BoardState, Task } from "./types";

const SOCKET_URL = "http://localhost:3001";

function TaskCard({
  task,
  onDelete
}: {
  task: Task;
  onDelete: () => void;
}) {
  return (
    <div className="task-card">
      <div className="task-card-header">
        <strong>{task.title}</strong>
        <button className="icon-btn" onClick={onDelete}>×</button>
      </div>
      {task.description && <p>{task.description}</p>}
      {task.assignee && <small>Assignee: {task.assignee}</small>}
    </div>
  );
}

function ColumnView({
  id,
  title,
  taskIds,
  tasks,
  onDeleteTask
}: {
  id: string;
  title: string;
  taskIds: string[];
  tasks: Record<string, Task>;
  onDeleteTask: (taskId: string) => void;
}) {
  return (
    <div className="column">
      <h2>{title}</h2>
      <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
        <div className="task-list" data-column-id={id}>
          {taskIds.map((taskId) => (
            <div key={taskId} className="task-wrapper" data-task-id={taskId}>
              <TaskCard task={tasks[taskId]} onDelete={() => onDeleteTask(taskId)} />
            </div>
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  useEffect(() => {
    const s = io(SOCKET_URL);
    setSocket(s);

    s.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const activeTask = useMemo(() => {
    if (!board || !activeTaskId) return null;
    return board.tasks[activeTaskId] ?? null;
  }, [board, activeTaskId]);

  function handleDragStart(event: { active: { id: string } }) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTaskId(null);
    if (!socket || !board) return;

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const sourceColumnId = Object.values(board.columns).find((col) =>
      col.taskIds.includes(taskId)
    )?.id;

    if (!sourceColumnId) return;

    const destinationColumnId = Object.values(board.columns).find((col) =>
      col.taskIds.includes(overId)
    )?.id || overId;

    if (!destinationColumnId) return;

    const sourceColumn = board.columns[sourceColumnId];
    const destinationColumn = board.columns[destinationColumnId];

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    const destinationIndex = destinationColumn.taskIds.indexOf(overId);

    if (sourceColumnId === destinationColumnId) {
      const reordered = arrayMove(sourceColumn.taskIds, sourceIndex, destinationIndex);
      socket.emit("task:move", {
        taskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex
      });
      return;
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex: destinationIndex >= 0 ? destinationIndex : destinationColumn.taskIds.length
    });
  }

  function createTask() {
    if (!socket || !board) return;
    const title = prompt("Task title?");
    if (!title) return;
    socket.emit("task:create", {
      title,
      description: "",
      columnId: board.columnOrder[0]
    });
  }

  function deleteTask(taskId: string) {
    if (!socket || !board) return;

    const column = Object.values(board.columns).find((col) =>
      col.taskIds.includes(taskId)
    );
    if (!column) return;

    socket.emit("task:delete", { taskId, columnId: column.id });
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <div className="topbar-actions">
          <button onClick={createTask}>+ New Task</button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columnOrder.map((columnId) => {
            const column = board.columns[columnId];
            return (
              <ColumnView
                key={column.id}
                id={column.id}
                title={column.title}
                taskIds={column.taskIds}
                tasks={board.tasks}
                onDeleteTask={deleteTask}
              />
            );
          })}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} onDelete={() => {}} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

