## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory state for demo purposes.
 * Replace with a database for production.
 */
let state = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design wireframes", description: "Create initial UI mockups" },
        { id: "t2", title: "Set up project", description: "Initialize repo and tooling" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build auth flow", description: "Login and session management" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Define requirements", description: "Gather project scope" }
      ]
    }
  ]
};

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current state to new client
  socket.emit("state:update", state);

  // Client requests state refresh
  socket.on("state:request", () => {
    socket.emit("state:update", state);
  });

  // Move task between columns / positions
  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = state.columns.find((c) => c.id === fromColumnId);
    const toColumn = state.columns.find((c) => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);
    toColumn.tasks.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  // Add a new task
  socket.on("task:add", ({ columnId, title, description }) => {
    const column = state.columns.find((c) => c.id === columnId);
    if (!column || !title) return;

    const newTask = {
      id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title,
      description: description || ""
    };

    column.tasks.unshift(newTask);
    io.emit("state:update", state);
  });

  // Delete a task
  socket.on("task:delete", ({ taskId }) => {
    for (const column of state.columns) {
      const index = column.tasks.findIndex((t) => t.id === taskId);
      if (index !== -1) {
        column.tasks.splice(index, 1);
        io.emit("state:update", state);
        break;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

