## 6) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const columnSelect = document.getElementById("columnSelect");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const connectionStatus = document.getElementById("connectionStatus");
const taskTemplate = document.getElementById("taskTemplate");

let appState = null;
let draggedTask = null;

socket.on("connect", () => {
  connectionStatus.textContent = "Connected";
  socket.emit("state:request");
});

socket.on("disconnect", () => {
  connectionStatus.textContent = "Disconnected";
});

socket.on("state:update", (state) => {
  appState = state;
  renderBoard();
  renderColumnOptions();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const columnId = columnSelect.value;
  const title = taskTitle.value.trim();
  const description = taskDescription.value.trim();

  if (!title) return;

  socket.emit("task:add", { columnId, title, description });

  taskTitle.value = "";
  taskDescription.value = "";
});

function renderColumnOptions() {
  if (!appState) return;

  columnSelect.innerHTML = appState.columns
    .map((col) => `<option value="${col.id}">${col.title}</option>`)
    .join("");
}

function renderBoard() {
  if (!appState) return;

  boardEl.innerHTML = "";

  appState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    columnEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    columnEl.addEventListener("drop", (e) => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumnId = column.id;
      const fromColumnId = draggedTask.fromColumnId;
      const taskId = draggedTask.taskId;

      const toIndex = column.tasks.length;

      socket.emit("task:move", {
        taskId,
        fromColumnId,
        toColumnId,
        toIndex
      });

      draggedTask = null;
    });

    columnEl.innerHTML = `
      <div class="column-header">
        <h2 class="column-title">${column.title}</h2>
        <span>${column.tasks.length}</span>
      </div>
      <div class="task-list"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    column.tasks.forEach((task, index) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");

      taskEl.querySelector(".task-title").textContent = task.title;
      taskEl.querySelector(".task-desc").textContent = task.description || "";

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.dataset.index = index;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: column.id
        };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskListEl.appendChild(taskNode);
    });

    boardEl.appendChild(columnEl);
  });
}
```

