## 3) Backend: `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());
app.use(express.static("../public"));

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory data store for demo purposes
let boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
    { id: "doing", title: "In Progress", taskIds: ["task-3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Design homepage", description: "Create wireframes", columnId: "todo" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow", columnId: "todo" },
    "task-3": { id: "task-3", title: "Build API", description: "Create task endpoints", columnId: "doing" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;
  const id = `task-${Date.now()}`;

  const task = {
    id,
    title,
    description: description || "",
    columnId: columnId || "todo"
  };

  boardState.tasks[id] = task;
  const column = boardState.columns.find(c => c.id === task.columnId);
  if (column) column.taskIds.push(id);

  io.emit("board:update", boardState);
  res.status(201).json(task);
});

app.put("/api/tasks/:id/move", (req, res) => {
  const { id } = req.params;
  const { columnId, taskIndex } = req.body;

  const task = boardState.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  // Remove from old column
  const oldColumn = boardState.columns.find(c => c.id === task.columnId);
  if (oldColumn) {
    oldColumn.taskIds = oldColumn.taskIds.filter(taskId => taskId !== id);
  }

  // Add to new column
  const newColumn = boardState.columns.find(c => c.id === columnId);
  if (!newColumn) return res.status(400).json({ error: "Invalid column" });

  task.columnId = columnId;

  if (typeof taskIndex === "number") {
    newColumn.taskIds.splice(taskIndex, 0, id);
  } else {
    newColumn.taskIds.push(id);
  }

  io.emit("board:update", boardState);
  res.json({ success: true });
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const column = boardState.columns.find(c => c.id === task.columnId);
  if (column) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete boardState.tasks[id];

  io.emit("board:update", boardState);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:move", ({ taskId, columnId, taskIndex }) => {
    const task = boardState.tasks[taskId];
    if (!task) return;

    const oldColumn = boardState.columns.find(c => c.id === task.columnId);
    if (oldColumn) {
      oldColumn.taskIds = oldColumn.taskIds.filter(id => id !== taskId);
    }

    const newColumn = boardState.columns.find(c => c.id === columnId);
    if (!newColumn) return;

    task.columnId = columnId;
    if (typeof taskIndex === "number") newColumn.taskIds.splice(taskIndex, 0, taskId);
    else newColumn.taskIds.push(taskId);

    io.emit("board:update", boardState);
  });

  socket.on("task:create", ({ title, description, columnId }) => {
    const id = `task-${Date.now()}`;
    const task = { id, title, description: description || "", columnId: columnId || "todo" };

    boardState.tasks[id] = task;
    const column = boardState.columns.find(c => c.id === task.columnId);
    if (column) column.taskIds.push(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId }) => {
    const task = boardState.tasks[taskId];
    if (!task) return;

    const column = boardState.columns.find(c => c.id === task.columnId);
    if (column) column.taskIds = column.taskIds.filter(id => id !== taskId);

    delete boardState.tasks[taskId];
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
