## 6) Frontend logic: `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const taskTemplate = document.getElementById("taskTemplate");
const newTaskForm = document.getElementById("newTaskForm");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");

let boardState = null;
let draggedTaskId = null;

async function loadBoard() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
      taskEl.dataset.taskId = task.id;

      taskEl.querySelector(".task-title").textContent = task.title;
      taskEl.querySelector(".task-description").textContent = task.description;

      const deleteBtn = taskEl.querySelector(".delete-task");
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
        draggedTaskId = null;
      });

      taskListEl.appendChild(taskEl);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId) return;

      const columnId = column.id;
      const taskIndex = column.taskIds.length;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        columnId,
        taskIndex
      });
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });

  setupColumnDragFeedback();
}

function setupColumnDragFeedback() {
  document.querySelectorAll(".column").forEach(column => {
    column.addEventListener("dragenter", () => column.classList.add("drag-over"));
    column.addEventListener("dragleave", () => column.classList.remove("drag-over"));
    column.addEventListener("dragend", () => column.classList.remove("drag-over"));
    column.addEventListener("drop", () => column.classList.remove("drag-over"));
  });
}

newTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  socket.emit("task:create", { title, description, columnId });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnSelect.value = "todo";
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

loadBoard();
```

