## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");
const { randomUUID } = require("crypto");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// In-memory data store
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "doing", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

// Seed tasks
const seedTasks = [
  {
    id: randomUUID(),
    title: "Design app layout",
    description: "Create the initial Kanban board UI",
    columnId: "todo",
    createdAt: Date.now()
  },
  {
    id: randomUUID(),
    title: "Set up real-time sync",
    description: "Connect client to Socket.IO",
    columnId: "doing",
    createdAt: Date.now()
  },
  {
    id: randomUUID(),
    title: "Deploy to hosting",
    description: "Prepare production deployment",
    columnId: "done",
    createdAt: Date.now()
  }
];

seedTasks.forEach(task => {
  board.tasks[task.id] = task;
  const col = board.columns.find(c => c.id === task.columnId);
  if (col) col.taskIds.push(task.id);
});

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = randomUUID();
  const task = {
    id,
    title: title.trim(),
    description: description.trim(),
    columnId,
    createdAt: Date.now()
  };

  board.tasks[id] = task;
  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, columnId } = req.body;

  if (title !== undefined) task.title = String(title).trim();
  if (description !== undefined) task.description = String(description).trim();

  if (columnId && columnId !== task.columnId) {
    const oldColumn = board.columns.find(c => c.id === task.columnId);
    const newColumn = board.columns.find(c => c.id === columnId);

    if (!newColumn) return res.status(400).json({ error: "Invalid column" });

    if (oldColumn) {
      oldColumn.taskIds = oldColumn.taskIds.filter(taskId => taskId !== id);
    }
    newColumn.taskIds.push(id);
    task.columnId = columnId;
  }

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const column = board.columns.find(c => c.id === task.columnId);
  if (column) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete board.tasks[id];

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:move", ({ taskId, toColumnId, toIndex }) => {
    const task = board.tasks[taskId];
    if (!task) return;

    const fromColumn = board.columns.find(c => c.id === task.columnId);
    const toColumn = board.columns.find(c => c.id === toColumnId);
    if (!toColumn || !fromColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter(id => id !== taskId);

    const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.taskIds.length, toColumn.taskIds.length));
    toColumn.taskIds.splice(insertIndex, 0, taskId);

    task.columnId = toColumnId;

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

