## 6) `public/app.js`

```js
const socket = io();

let boardData = null;
let editingTaskId = null;

const boardEl = document.getElementById("board");
const dialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const addTaskBtn = document.getElementById("addTaskBtn");
const cancelBtn = document.getElementById("cancelBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");

const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnInput = document.getElementById("taskColumn");
const dialogTitle = document.getElementById("dialogTitle");

function renderBoard(board) {
  boardEl.innerHTML = "";

  board.columns.forEach(column => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const listEl = columnEl.querySelector(".task-list");

    column.taskIds.forEach(taskId => {
      const task = board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button type="button" class="edit-btn">Edit</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", handleDragStart);
      taskEl.addEventListener("dragend", handleDragEnd);

      taskEl.querySelector(".edit-btn").addEventListener("click", () => openEditDialog(task.id));

      listEl.appendChild(taskEl);
    });

    listEl.addEventListener("dragover", handleDragOver);
    listEl.addEventListener("drop", handleDrop);

    boardEl.appendChild(columnEl);
  });
}

let draggedTaskId = null;

function handleDragStart(e) {
  draggedTaskId = e.currentTarget.dataset.taskId;
  e.currentTarget.style.opacity = "0.5";
}

function handleDragEnd(e) {
  e.currentTarget.style.opacity = "1";
}

function handleDragOver(e) {
  e.preventDefault();
}

function handleDrop(e) {
  e.preventDefault();
  const listEl = e.currentTarget;
  const toColumnId = listEl.dataset.columnId;
  const taskId = draggedTaskId;
  if (!taskId) return;

  const tasksInColumn = Array.from(listEl.querySelectorAll(".task"));
  const toIndex = tasksInColumn.length;

  socket.emit("task:move", {
    taskId,
    toColumnId,
    toIndex
  });

  draggedTaskId = null;
}

function openAddDialog() {
  editingTaskId = null;
  dialogTitle.textContent = "Add Task";
  deleteTaskBtn.classList.add("hidden");

  taskIdInput.value = "";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnInput.value = "todo";

  dialog.showModal();
}

function openEditDialog(taskId) {
  const task = boardData?.tasks?.[taskId];
  if (!task) return;

  editingTaskId = taskId;
  dialogTitle.textContent = "Edit Task";
  deleteTaskBtn.classList.remove("hidden");

  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskColumnInput.value = task.columnId;

  dialog.showModal();
}

addTaskBtn.addEventListener("click", openAddDialog);
cancelBtn.addEventListener("click", () => dialog.close());

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const payload = {
    title: taskTitleInput.value,
    description: taskDescriptionInput.value,
    columnId: taskColumnInput.value
  };

  if (editingTaskId) {
    await fetch(`/api/tasks/${editingTaskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  } else {
    await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  }

  dialog.close();
});

deleteTaskBtn.addEventListener("click", async () => {
  if (!editingTaskId) return;

  await fetch(`/api/tasks/${editingTaskId}`, {
    method: "DELETE"
  });

  dialog.close();
});

socket.on("board:update", (board) => {
  boardData = board;
  renderBoard(board);
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

