## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initialState, BoardState, Task } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body as {
    title: string;
    description?: string;
    columnId: string;
  };

  if (!title || !columnId || !boardState.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = `task-${Date.now()}`;
  const task: Task = {
    id,
    title,
    description,
    status: columnId,
    createdAt: Date.now()
  };

  boardState.tasks[id] = task;
  boardState.columns[columnId].taskIds.push(id);

  io.emit("board:update", boardState);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (payload: { title: string; description?: string; columnId: string }) => {
    const { title, description, columnId } = payload;

    if (!title || !columnId || !boardState.columns[columnId]) return;

    const id = `task-${Date.now()}`;
    const task: Task = {
      id,
      title,
      description,
      status: columnId,
      createdAt: Date.now()
    };

    boardState.tasks[id] = task;
    boardState.columns[columnId].taskIds.push(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:move", (payload: { taskId: string; fromColumnId: string; toColumnId: string; toIndex: number }) => {
    const { taskId, fromColumnId, toColumnId, toIndex } = payload;

    const fromColumn = boardState.columns[fromColumnId];
    const toColumn = boardState.columns[toColumnId];
    const task = boardState.tasks[taskId];

    if (!fromColumn || !toColumn || !task) return;

    fromColumn.taskIds = fromColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex = Math.max(0, Math.min(toIndex, toColumn.taskIds.length));
    toColumn.taskIds.splice(safeIndex, 0, taskId);

    task.status = toColumnId;

    io.emit("board:update", boardState);
  });

  socket.on("task:update", (payload: { taskId: string; title?: string; description?: string }) => {
    const task = boardState.tasks[payload.taskId];
    if (!task) return;

    if (typeof payload.title === "string") task.title = payload.title;
    if (typeof payload.description === "string") task.description = payload.description;

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (payload: { taskId: string }) => {
    const task = boardState.tasks[payload.taskId];
    if (!task) return;

    const column = boardState.columns[task.status];
    if (column) {
      column.taskIds = column.taskIds.filter((id) => id !== payload.taskId);
    }

    delete boardState.tasks[payload.taskId];
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

