## `client/src/App.tsx`

```tsx
import React, { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: string;
  assignee?: string;
  createdAt: number;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  columns: Record<string, Column>;
  tasks: Record<string, Task>;
};

const SERVER_URL = "http://localhost:4000";

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const [newTitle, setNewTitle] = useState("");
  const [newDescription, setNewDescription] = useState("");
  const [newColumnId, setNewColumnId] = useState("todo");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    const s = io(SERVER_URL, { transports: ["websocket"] });
    setSocket(s);

    s.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return Object.values(board.columns);
  }, [board]);

  const handleDragStart = (event: DragStartEvent) => {
    setActiveTaskId(String(event.active.id));
  };

  const handleDragOver = (_event: DragOverEvent) => {
    // Optional: live preview logic can go here
  };

  const handleDragEnd = (event: DragEndEvent) => {
    setActiveTaskId(null);

    const { active, over } = event;
    if (!board || !socket || !over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const task = board.tasks[taskId];
    if (!task) return;

    const fromColumnId = task.status;

    let toColumnId = overId;
    let toIndex = 0;

    if (!board.columns[overId]) {
      const targetTask = board.tasks[overId];
      if (!targetTask) return;

      toColumnId = targetTask.status;
      toIndex = board.columns[toColumnId].taskIds.indexOf(overId);
    } else {
      toIndex = board.columns[toColumnId].taskIds.length;
    }

    socket.emit("task:move", {
      taskId,
      fromColumnId,
      toColumnId,
      toIndex
    });
  };

  const createTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!socket || !newTitle.trim()) return;

    socket.emit("task:create", {
      title: newTitle.trim(),
      description: newDescription.trim() || undefined,
      columnId: newColumnId
    });

    setNewTitle("");
    setNewDescription("");
    setNewColumnId("todo");
  };

  const deleteTask = (taskId: string) => {
    if (!socket) return;
    socket.emit("task:delete", { taskId });
  };

  if (!board) {
    return <div className="app loading">Connecting to board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Manager</h1>
          <p>Drag tasks between columns. Updates sync in real time.</p>
        </div>
      </header>

      <section className="create-task">
        <form onSubmit={createTask} className="task-form">
          <input
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={newDescription}
            onChange={(e) => setNewDescription(e.target.value)}
            placeholder="Description"
          />
          <select value={newColumnId} onChange={(e) => setNewColumnId(e.target.value)}>
            {columns.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </section>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        <main className="board">
          {columns.map((column) => (
            <ColumnView
              key={column.id}
              column={column}
              tasks={column.taskIds.map((id) => board.tasks[id]).filter(Boolean)}
              onDelete={deleteTask}
              isActiveTask={(id) => id === activeTaskId}
            />
          ))}
        </main>
      </DndContext>
    </div>
  );
}

function ColumnView({
  column,
  tasks,
  onDelete,
  isActiveTask
}: {
  column: Column;
  tasks: Task[];
  onDelete: (taskId: string) => void;
  isActiveTask: (taskId: string) => boolean;
}) {
  return (
    <section className="column" id={column.id}>
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{tasks.length}</span>
      </div>

      <div className="task-list" data-column-id={column.id}>
        {tasks.map((task) => (
          <TaskCard
            key={task.id}
            task={task}
            onDelete={onDelete}
            active={isActiveTask(task.id)}
          />
        ))}
      </div>
    </section>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

function TaskCard({
  task,
  onDelete,
  active
}: {
  task: Task;
  onDelete: (taskId: string) => void;
  active: boolean;
}) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <article
      ref={setNodeRef}
      style={style}
      className={`task-card ${active ? "active" : ""}`}
      {...attributes}
      {...listeners}
    >
      <div className="task-card-top">
        <strong>{task.title}</strong>
        <button
          className="delete-btn"
          onClick={(e) => {
            e.stopPropagation();
            onDelete(task.id);
          }}
        >
          ×
        </button>
      </div>
      {task.description && <p>{task.description}</p>}
      <small>{new Date(task.createdAt).toLocaleString()}</small>
    </article>
  );
}
```

> Note: For a production app, move the `useSortable` import to the top of the file. I separated it here only for readability in the snippet. In real code, keep all imports at the top.

