```js
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory data store
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout", description: "Create initial UI mockups" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Add login and registration" },
    "task-3": { id: "task-3", title: "Build board drag-and-drop", description: "Implement task movement" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = `task-${Date.now()}`;
  const newTask = { id, title, description };

  board.tasks[id] = newTask;
  const column = board.columns.find((c) => c.id === columnId);
  if (column) column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(newTask);
});

app.put("/api/board/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column IDs" });
  }

  // Remove from source
  sourceColumn.taskIds.splice(sourceIndex, 1);

  // Insert into destination
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ success: true, board });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", (payload) => {
    const { title, description = "", columnId = "todo" } = payload;
    const id = `task-${Date.now()}`;
    const newTask = { id, title, description };

    board.tasks[id] = newTask;
    const column = board.columns.find((c) => c.id === columnId);
    if (column) column.taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:move", (payload) => {
    const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
