```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:3001");

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columnMap = useMemo(() => {
    if (!board) return {};
    const map = {};
    board.columns.forEach((col) => {
      map[col.id] = col;
    });
    return map;
  }, [board]);

  const handleDragStart = (e, taskId, sourceColumnId, sourceIndex) => {
    e.dataTransfer.setData(
      "application/json",
      JSON.stringify({ taskId, sourceColumnId, sourceIndex })
    );
  };

  const handleDrop = (e, destinationColumnId, destinationIndex) => {
    e.preventDefault();
    const data = JSON.parse(e.dataTransfer.getData("application/json"));

    socket.emit("task:move", {
      taskId: data.taskId,
      sourceColumnId: data.sourceColumnId,
      destinationColumnId,
      sourceIndex: data.sourceIndex,
      destinationIndex
    });
  };

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: "todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Real-time collaborative task board</p>
      </header>

      <form className="new-task-form" onSubmit={handleAddTask}>
        <input
          type="text"
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
        />
        <button type="submit">Add Task</button>
      </form>

      <div className="board">
        {board.columns.map((column) => (
          <div
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => handleDrop(e, column.id, column.taskIds.length)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <span>{column.taskIds.length}</span>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = board.tasks[taskId];
                if (!task) return null;

                return (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id, column.id, index)}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => handleDrop(e, column.id, index)}
                  >
                    <h3>{task.title}</h3>
                    <p>{task.description}</p>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
```

