### `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

app.use(cors());
app.use(express.json());

app.get("/", (req, res) => {
  res.send("Project Manager API is running");
});

// In-memory data store for demo purposes
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["1", "2"] },
    { id: "doing", title: "In Progress", taskIds: ["3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "1": { id: "1", title: "Design login screen", description: "Create wireframes and UI mockups." },
    "2": { id: "2", title: "Set up database", description: "Initialize schema and migrations." },
    "3": { id: "3", title: "Implement auth flow", description: "JWT login/logout and session handling." }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;
  const id = String(Date.now());

  board.tasks[id] = { id, title, description };
  const column = board.columns.find(c => c.id === columnId);
  if (column) column.taskIds.unshift(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    ...(title !== undefined ? { title } : {}),
    ...(description !== undefined ? { description } : {})
  };

  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  // Remove from column
  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete board.tasks[id];
  io.emit("board:update", board);
  res.json({ ok: true });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid columns" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ ok: true, board });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", (data) => {
    const id = String(Date.now());
    board.tasks[id] = { id, title: data.title, description: data.description || "" };

    const column = board.columns.find(c => c.id === (data.columnId || "todo"));
    if (column) column.taskIds.unshift(id);

    io.emit("board:update", board);
  });

  socket.on("task:update", (data) => {
    const { id, title, description } = data;
    if (board.tasks[id]) {
      board.tasks[id] = {
        ...board.tasks[id],
        ...(title !== undefined ? { title } : {}),
        ...(description !== undefined ? { description } : {})
      };
      io.emit("board:update", board);
    }
  });

  socket.on("task:delete", (taskId) => {
    if (!board.tasks[taskId]) return;

    for (const column of board.columns) {
      column.taskIds = column.taskIds.filter(id => id !== taskId);
    }
    delete board.tasks[taskId];
    io.emit("board:update", board);
  });

  socket.on("task:move", (data) => {
    const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = data;
    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

