## 5) Frontend: JavaScript with drag-and-drop + real-time updates

### `client/app.js`

```js
const socket = io("http://localhost:3000");

let boardData = null;
let editingTaskId = null;

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const cancelBtn = document.getElementById("cancelBtn");
const dialogTitle = document.getElementById("dialogTitle");

function renderBoard(board) {
  boardEl.innerHTML = "";

  board.columnOrder.forEach(columnId => {
    const column = board.columns.find(c => c.id === columnId);
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    column.taskIds.forEach(taskId => {
      const task = board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button data-action="edit">Edit</button>
          <button data-action="delete">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("taskId", task.id);
        e.dataTransfer.setData("sourceColumnId", column.id);
      });

      taskEl.querySelector('[data-action="edit"]').addEventListener("click", () => {
        openEditDialog(task.id);
      });

      taskEl.querySelector('[data-action="delete"]').addEventListener("click", () => {
        socket.emit("task:delete", task.id);
      });

      taskListEl.appendChild(taskEl);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("taskId");
      const sourceColumnId = e.dataTransfer.getData("sourceColumnId");
      const destinationColumnId = column.id;

      const afterTasks = [...taskListEl.querySelectorAll(".task")];
      const dropTarget = e.target.closest(".task");
      let destinationIndex = afterTasks.length;

      if (dropTarget) {
        destinationIndex = afterTasks.indexOf(dropTarget);
      }

      socket.emit("task:move", {
        taskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex
      });
    });

    boardEl.appendChild(columnEl);
  });
}

function openAddDialog() {
  editingTaskId = null;
  dialogTitle.textContent = "Add Task";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskDialog.showModal();
}

function openEditDialog(taskId) {
  const task = boardData.tasks[taskId];
  if (!task) return;

  editingTaskId = taskId;
  dialogTitle.textContent = "Edit Task";
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskDialog.showModal();
}

addTaskBtn.addEventListener("click", openAddDialog);
cancelBtn.addEventListener("click", () => taskDialog.close());

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();

  if (!title) return;

  if (editingTaskId) {
    socket.emit("task:update", {
      id: editingTaskId,
      title,
      description
    });
  } else {
    socket.emit("task:create", {
      title,
      description,
      columnId: "todo"
    });
  }

  taskDialog.close();
});

socket.on("board:update", (board) => {
  boardData = board;
  renderBoard(board);
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

