### `server/index.js`
```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory store for demo purposes
let boards = {
  todo: {
    id: "todo",
    title: "To Do",
    taskIds: ["task-1", "task-2"]
  },
  inprogress: {
    id: "inprogress",
    title: "In Progress",
    taskIds: ["task-3"]
  },
  done: {
    id: "done",
    title: "Done",
    taskIds: []
  }
};

let tasks = {
  "task-1": { id: "task-1", title: "Design app layout", description: "Create initial UI", status: "todo" },
  "task-2": { id: "task-2", title: "Set up auth", description: "Add login flow", status: "todo" },
  "task-3": { id: "task-3", title: "Implement drag and drop", description: "Kanban board interactions", status: "inprogress" }
};

function getState() {
  return { boards, tasks };
}

// REST endpoint to fetch initial state
app.get("/api/state", (req, res) => {
  res.json(getState());
});

// Update board/task state and broadcast
io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:init", getState());

  socket.on("task:create", (task) => {
    tasks[task.id] = task;
    boards[task.status].taskIds.unshift(task.id);
    io.emit("state:update", getState());
  });

  socket.on("task:update", (updatedTask) => {
    const oldTask = tasks[updatedTask.id];
    if (!oldTask) return;

    // If status changed, move between boards
    if (oldTask.status !== updatedTask.status) {
      boards[oldTask.status].taskIds = boards[oldTask.status].taskIds.filter(
        (id) => id !== updatedTask.id
      );
      boards[updatedTask.status].taskIds.unshift(updatedTask.id);
    }

    tasks[updatedTask.id] = updatedTask;
    io.emit("state:update", getState());
  });

  socket.on("task:move", ({ taskId, from, to, index }) => {
    if (!tasks[taskId] || !boards[from] || !boards[to]) return;

    boards[from].taskIds = boards[from].taskIds.filter((id) => id !== taskId);
    boards[to].taskIds.splice(index, 0, taskId);
    tasks[taskId].status = to;

    io.emit("state:update", getState());
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

app.get("/", (req, res) => {
  res.send("Project Manager API running");
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

