```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task, listeners, attributes, setNodeRef, transform, transition, isDragging }) {
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  return (
    <TaskCard
      task={task}
      setNodeRef={setNodeRef}
      attributes={attributes}
      listeners={listeners}
      transform={transform}
      transition={transition}
      isDragging={isDragging}
    />
  );
}

function Column({ board, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{board.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <SortableTask key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState({});
  const [tasks, setTasks] = useState({});
  const [activeTaskId, setActiveTaskId] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    socket.on("state:init", ({ boards, tasks }) => {
      setBoards(boards);
      setTasks(tasks);
    });

    socket.on("state:update", ({ boards, tasks }) => {
      setBoards(boards);
      setTasks(tasks);
    });

    return () => {
      socket.off("state:init");
      socket.off("state:update");
    };
  }, []);

  const boardList = useMemo(() => Object.values(boards), [boards]);

  const tasksByBoard = useMemo(() => {
    const result = {};
    for (const board of Object.values(boards)) {
      result[board.id] = board.taskIds.map((id) => tasks[id]).filter(Boolean);
    }
    return result;
  }, [boards, tasks]);

  function handleDragStart(event) {
    setActiveTaskId(event.active.id);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTaskId(null);

    if (!over) return;

    const activeId = active.id;
    const overId = over.id;

    // Find source board
    let fromBoard = null;
    let toBoard = null;

    for (const board of Object.values(boards)) {
      if (board.taskIds.includes(activeId)) fromBoard = board.id;
      if (board.taskIds.includes(overId)) toBoard = board.id;
    }

    // If dropped on empty column, overId may be a board id
    if (!toBoard && boards[overId]) {
      toBoard = overId;
    }

    if (!fromBoard || !toBoard) return;

    if (fromBoard === toBoard) {
      const sourceTasks = [...boards[fromBoard].taskIds];
      const oldIndex = sourceTasks.indexOf(activeId);
      const newIndex = sourceTasks.indexOf(overId);

      if (oldIndex !== newIndex && newIndex !== -1) {
        sourceTasks.splice(oldIndex, 1);
        sourceTasks.splice(newIndex, 0, activeId);

        // Broadcast move
        socket.emit("task:move", {
          taskId: activeId,
          from: fromBoard,
          to: toBoard,
          index: newIndex
        });
      }
    } else {
      const targetIndex = boards[toBoard].taskIds.indexOf(overId);
      socket.emit("task:move", {
        taskId: activeId,
        from: fromBoard,
        to: toBoard,
        index: targetIndex >= 0 ? targetIndex : 0
      });
    }
  }

  function addTask(boardId) {
    const id = `task-${Date.now()}`;
    const task = {
      id,
      title: "New Task",
      description: "Add details...",
      status: boardId
    };
    socket.emit("task:create", task);
  }

  const activeTask = activeTaskId ? tasks[activeTaskId] : null;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <p>Real-time collaborative task boards</p>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {boardList.map((board) => (
            <div key={board.id} className="board-column-wrapper">
              <Column board={board} tasks={tasksByBoard[board.id] || []} />
              <button className="add-task-btn" onClick={() => addTask(board.id)}>
                + Add Task
              </button>
            </div>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? (
            <div className="task-card dragging">
              <h4>{activeTask.title}</h4>
              <p>{activeTask.description}</p>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

