## 3) Backend: `server/index.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");
const { randomUUID } = require("crypto");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "..", "public")));

// In-memory store for demo purposes
const state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: randomUUID(), title: "Design UI wireframes", description: "Create basic layout", assignee: "Alex" },
        { id: randomUUID(), title: "Set up backend", description: "Initialize Express + Socket.IO", assignee: "Sam" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: randomUUID(), title: "Implement drag and drop", description: "Use HTML5 DnD", assignee: "Taylor" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ],
  users: {}
};

function findTask(taskId) {
  for (const board of state.boards) {
    const idx = board.tasks.findIndex((t) => t.id === taskId);
    if (idx !== -1) {
      return { board, index: idx, task: board.tasks[idx] };
    }
  }
  return null;
}

function broadcastState() {
  io.emit("state:update", state);
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, title, description = "", assignee = "" } = req.body;

  if (!boardId || !title) {
    return res.status(400).json({ error: "boardId and title are required" });
  }

  const board = state.boards.find((b) => b.id === boardId);
  if (!board) {
    return res.status(404).json({ error: "Board not found" });
  }

  const task = {
    id: randomUUID(),
    title,
    description,
    assignee
  };

  board.tasks.push(task);
  broadcastState();
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description, assignee } = req.body;

  const found = findTask(taskId);
  if (!found) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (title !== undefined) found.task.title = title;
  if (description !== undefined) found.task.description = description;
  if (assignee !== undefined) found.task.assignee = assignee;

  broadcastState();
  res.json(found.task);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  const found = findTask(taskId);
  if (!found) {
    return res.status(404).json({ error: "Task not found" });
  }

  found.board.tasks.splice(found.index, 1);
  broadcastState();
  res.json({ ok: true });
});

app.post("/api/tasks/:taskId/move", (req, res) => {
  const { taskId } = req.params;
  const { targetBoardId, targetIndex } = req.body;

  const found = findTask(taskId);
  if (!found) {
    return res.status(404).json({ error: "Task not found" });
  }

  const targetBoard = state.boards.find((b) => b.id === targetBoardId);
  if (!targetBoard) {
    return res.status(404).json({ error: "Target board not found" });
  }

  const [task] = found.board.tasks.splice(found.index, 1);
  const insertIndex =
    typeof targetIndex === "number" && targetIndex >= 0
      ? Math.min(targetIndex, targetBoard.tasks.length)
      : targetBoard.tasks.length;

  targetBoard.tasks.splice(insertIndex, 0, task);

  broadcastState();
  res.json({ ok: true, task });
});

io.on("connection", (socket) => {
  socket.emit("state:update", state);

  socket.on("user:join", (user) => {
    state.users[socket.id] = user || { name: "Anonymous" };
    io.emit("users:update", state.users);
  });

  socket.on("task:create", ({ boardId, title, description, assignee }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board || !title) return;

    board.tasks.push({
      id: randomUUID(),
      title,
      description: description || "",
      assignee: assignee || ""
    });

    broadcastState();
  });

  socket.on("task:move", ({ taskId, targetBoardId, targetIndex }) => {
    const found = findTask(taskId);
    const targetBoard = state.boards.find((b) => b.id === targetBoardId);
    if (!found || !targetBoard) return;

    const [task] = found.board.tasks.splice(found.index, 1);
    const insertIndex =
      typeof targetIndex === "number" && targetIndex >= 0
        ? Math.min(targetIndex, targetBoard.tasks.length)
        : targetBoard.tasks.length;

    targetBoard.tasks.splice(insertIndex, 0, task);

    broadcastState();
  });

  socket.on("task:update", ({ taskId, updates }) => {
    const found = findTask(taskId);
    if (!found) return;

    Object.assign(found.task, updates || {});
    broadcastState();
  });

  socket.on("task:delete", ({ taskId }) => {
    const found = findTask(taskId);
    if (!found) return;

    found.board.tasks.splice(found.index, 1);
    broadcastState();
  });

  socket.on("disconnect", () => {
    delete state.users[socket.id];
    io.emit("users:update", state.users);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

