## 6) Frontend logic: `public/app.js`

```js
const socket = io();

let appState = { boards: [], users: {} };
let draggedTaskId = null;

const boardsEl = document.getElementById("boards");
const boardSelect = document.getElementById("boardSelect");
const taskForm = document.getElementById("taskForm");
const onlineCount = document.getElementById("onlineCount");

socket.on("state:update", (state) => {
  appState = state;
  render();
});

socket.on("users:update", (users) => {
  onlineCount.textContent = Object.keys(users || {}).length;
});

socket.emit("user:join", {
  name: prompt("Enter your name:") || "Anonymous"
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const boardId = boardSelect.value;
  const title = document.getElementById("taskTitle").value.trim();
  const description = document.getElementById("taskDescription").value.trim();
  const assignee = document.getElementById("taskAssignee").value.trim();

  if (!boardId || !title) return;

  socket.emit("task:create", { boardId, title, description, assignee });

  taskForm.reset();
});

function render() {
  renderBoardSelect();
  renderBoards();
}

function renderBoardSelect() {
  boardSelect.innerHTML = appState.boards
    .map((board) => `<option value="${board.id}">${board.title}</option>`)
    .join("");
}

function renderBoards() {
  boardsEl.innerHTML = "";

  appState.boards.forEach((board) => {
    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const taskList = boardEl.querySelector(".task-list");

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drop-hover");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-hover");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drop-hover");

      if (!draggedTaskId) return;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        targetBoardId: board.id,
        targetIndex: board.tasks.length
      });

      draggedTaskId = null;
    });

    board.tasks.forEach((task) => {
      const taskNode = createTaskNode(task);
      taskList.appendChild(taskNode);
    });

    boardsEl.appendChild(boardEl);
  });
}

function createTaskNode(task) {
  const template = document.getElementById("taskTemplate");
  const node = template.content.cloneNode(true);
  const article = node.querySelector(".task");

  article.dataset.taskId = task.id;
  article.draggable = true;

  article.querySelector(".task-title").textContent = task.title;
  article.querySelector(".task-description").textContent = task.description || "";
  article.querySelector(".task-assignee").textContent = task.assignee
    ? `Assignee: ${task.assignee}`
    : "";

  article.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    article.classList.add("dragging");
  });

  article.addEventListener("dragend", () => {
    draggedTaskId = null;
    article.classList.remove("dragging");
  });

  article.querySelector(".delete-btn").addEventListener("click", () => {
    socket.emit("task:delete", { taskId: task.id });
  });

  return node;
}
```

