## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design UI mockups", description: "Create initial wireframes", priority: "high" },
        { id: "task-2", title: "Set up project repo", description: "Initialize Git repository", priority: "medium" }
      ]
    },
    {
      id: "inprogress",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build task board", description: "Implement drag and drop", priority: "high" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function findTask(taskId) {
  for (const column of boardState.columns) {
    const taskIndex = column.tasks.findIndex(t => t.id === taskId);
    if (taskIndex !== -1) {
      return { column, taskIndex, task: column.tasks[taskIndex] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", (task, callback) => {
    const column = boardState.columns.find(c => c.id === task.columnId);
    if (!column) return callback?.({ ok: false, error: "Invalid column" });

    const newTask = {
      id: `task-${Date.now()}`,
      title: task.title || "Untitled Task",
      description: task.description || "",
      priority: task.priority || "medium"
    };

    column.tasks.push(newTask);
    io.emit("board:update", boardState);
    callback?.({ ok: true, task: newTask });
  });

  socket.on("task:update", (updatedTask, callback) => {
    const found = findTask(updatedTask.id);
    if (!found) return callback?.({ ok: false, error: "Task not found" });

    found.task.title = updatedTask.title ?? found.task.title;
    found.task.description = updatedTask.description ?? found.task.description;
    found.task.priority = updatedTask.priority ?? found.task.priority;

    io.emit("board:update", boardState);
    callback?.({ ok: true });
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }, callback) => {
    const fromColumn = boardState.columns.find(c => c.id === fromColumnId);
    const toColumn = boardState.columns.find(c => c.id === toColumnId);
    if (!fromColumn || !toColumn) return callback?.({ ok: false, error: "Invalid column" });

    const idx = fromColumn.tasks.findIndex(t => t.id === taskId);
    if (idx === -1) return callback?.({ ok: false, error: "Task not found" });

    const [task] = fromColumn.tasks.splice(idx, 1);
    toColumn.tasks.splice(toIndex, 0, task);

    io.emit("board:update", boardState);
    callback?.({ ok: true });
  });

  socket.on("task:delete", ({ taskId }, callback) => {
    const found = findTask(taskId);
    if (!found) return callback?.({ ok: false, error: "Task not found" });

    found.column.tasks.splice(found.taskIndex, 1);
    io.emit("board:update", boardState);
    callback?.({ ok: true });
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

