## 6) `public/app.js`

```js
const socket = io();

let boardState = null;
let draggingTaskId = null;
let draggingFromColumnId = null;

const boardEl = document.getElementById("board");
const modal = document.getElementById("modal");
const taskForm = document.getElementById("taskForm");
const addTaskBtn = document.getElementById("addTaskBtn");
const cancelBtn = document.getElementById("cancelBtn");
const modalTitle = document.getElementById("modalTitle");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const priorityInput = document.getElementById("priority");
const columnIdInput = document.getElementById("columnId");

function openModal(task = null) {
  modal.classList.remove("hidden");

  columnIdInput.innerHTML = "";
  boardState.columns.forEach(col => {
    const option = document.createElement("option");
    option.value = col.id;
    option.textContent = col.title;
    columnIdInput.appendChild(option);
  });

  if (task) {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    titleInput.value = task.title;
    descriptionInput.value = task.description || "";
    priorityInput.value = task.priority || "medium";
    columnIdInput.value = task.columnId;
  } else {
    modalTitle.textContent = "Add Task";
    taskIdInput.value = "";
    titleInput.value = "";
    descriptionInput.value = "";
    priorityInput.value = "medium";
    columnIdInput.value = boardState.columns[0].id;
  }
}

function closeModal() {
  modal.classList.add("hidden");
  taskForm.reset();
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.innerHTML = `<h2>${column.title}</h2>`;

    const taskList = document.createElement("div");
    taskList.className = "task-list dropzone";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("dragover");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("dragover");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("dragover");

      if (!draggingTaskId || !draggingFromColumnId) return;

      const toColumnId = column.id;
      const toIndex = boardState.columns.find(c => c.id === toColumnId).tasks.length;

      socket.emit("task:move", {
        taskId: draggingTaskId,
        fromColumnId: draggingFromColumnId,
        toColumnId,
        toIndex
      });
    });

    column.tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = `task ${task.priority}`;
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h3>${task.title}</h3>
        <p>${task.description || ""}</p>
        <small>Priority: ${task.priority}</small>
        <div class="actions">
          <button data-action="edit">Edit</button>
          <button data-action="delete">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggingTaskId = task.id;
        draggingFromColumnId = column.id;
      });

      taskEl.addEventListener("dragend", () => {
        draggingTaskId = null;
        draggingFromColumnId = null;
      });

      taskEl.querySelector('[data-action="edit"]').addEventListener("click", () => {
        openModal({ ...task, columnId: column.id });
      });

      taskEl.querySelector('[data-action="delete"]').addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

socket.on("board:init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

addTaskBtn.addEventListener("click", () => openModal());

cancelBtn.addEventListener("click", closeModal);

modal.addEventListener("click", (e) => {
  if (e.target === modal) closeModal();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const taskId = taskIdInput.value.trim();
  const taskData = {
    id: taskId,
    title: titleInput.value.trim(),
    description: descriptionInput.value.trim(),
    priority: priorityInput.value,
    columnId: columnIdInput.value
  };

  if (taskId) {
    socket.emit("task:update", taskData, (res) => {
      if (res?.ok) closeModal();
      else alert(res?.error || "Failed to update task");
    });
  } else {
    socket.emit("task:create", taskData, (res) => {
      if (res?.ok) closeModal();
      else alert(res?.error || "Failed to create task");
    });
  }
});
