## 3) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for demo purposes
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project",
      description: "Initialize repo and tooling",
      status: "todo"
    },
    "task-2": {
      id: "task-2",
      title: "Design UI",
      description: "Create wireframes and layout",
      status: "todo"
    },
    "task-3": {
      id: "task-3",
      title: "Build socket sync",
      description: "Enable collaboration updates",
      status: "doing"
    }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/task", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title?.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = `task-${Date.now()}`;
  const task = { id, title: title.trim(), description, status: columnId };

  boardState.tasks[id] = task;
  boardState.columns[columnId].taskIds.unshift(id);

  io.emit("board:update", boardState);

  res.status(201).json(task);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (payload) => {
    const { title, description = "", columnId = "todo" } = payload;

    if (!title?.trim()) return;

    const id = `task-${Date.now()}`;
    const task = { id, title: title.trim(), description, status: columnId };

    boardState.tasks[id] = task;
    boardState.columns[columnId].taskIds.unshift(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:update", (payload) => {
    const { taskId, updates } = payload;
    const task = boardState.tasks[taskId];
    if (!task) return;

    boardState.tasks[taskId] = { ...task, ...updates };

    io.emit("board:update", boardState);
  });

  socket.on("task:move", (payload) => {
    const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload;

    if (!boardState.tasks[taskId]) return;

    const sourceCol = boardState.columns[sourceColumnId];
    const destCol = boardState.columns[destinationColumnId];
    if (!sourceCol || !destCol) return;

    sourceCol.taskIds = sourceCol.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof destinationIndex === "number" ? destinationIndex : destCol.taskIds.length;

    destCol.taskIds.splice(insertIndex, 0, taskId);
    boardState.tasks[taskId].status = destinationColumnId;

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId }) => {
    const task = boardState.tasks[taskId];
    if (!task) return;

    const column = boardState.columns[task.status];
    if (column) {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    }

    delete boardState.tasks[taskId];

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
