## 7) Frontend: `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:4000");

function App() {
  const [board, setBoard] = useState(null);
  const [draggingTaskId, setDraggingTaskId] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    socket.on("board:update", (state) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((colId) => board.columns[colId]);
  }, [board]);

  const getTask = (taskId) => board?.tasks?.[taskId];

  const handleDragStart = (taskId) => {
    setDraggingTaskId(taskId);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (columnId, destinationIndex = null) => {
    if (!draggingTaskId || !board) return;

    const task = board.tasks[draggingTaskId];
    if (!task) return;

    const sourceColumnId = task.status;
    if (sourceColumnId === columnId && destinationIndex === null) {
      setDraggingTaskId(null);
      return;
    }

    socket.emit("task:move", {
      taskId: draggingTaskId,
      sourceColumnId,
      destinationColumnId: columnId,
      destinationIndex
    });

    setDraggingTaskId(null);
  };

  const createTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: "todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  const deleteTask = (taskId) => {
    socket.emit("task:delete", { taskId });
  };

  const updateTaskTitle = (taskId, title) => {
    socket.emit("task:update", {
      taskId,
      updates: { title }
    });
  };

  const updateTaskDescription = (taskId, description) => {
    socket.emit("task:update", {
      taskId,
      updates: { description }
    });
  };

  if (!board) {
    return <div className="app">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>

        <form className="new-task-form" onSubmit={createTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={handleDragOver}
            onDrop={() => handleDrop(column.id)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <span>{column.taskIds.length}</span>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = getTask(taskId);
                if (!task) return null;

                return (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => handleDragStart(task.id)}
                    onDragOver={handleDragOver}
                    onDrop={(e) => {
                      e.preventDefault();
                      handleDrop(column.id, index);
                    }}
                  >
                    <input
                      className="task-title"
                      value={task.title}
                      onChange={(e) => updateTaskTitle(task.id, e.target.value)}
                    />
                    <textarea
                      className="task-desc"
                      value={task.description}
                      onChange={(e) => updateTaskDescription(task.id, e.target.value)}
                      rows={3}
                    />
                    <div className="task-actions">
                      <button onClick={() => deleteTask(task.id)}>Delete</button>
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}

export default App;
```

