# 1) Backend: `server.js`

```js
import express from "express";
import http from "http";
import { WebSocketServer } from "ws";
import cors from "cors";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(cors());
app.use(express.json());

/**
 * In-memory demo state
 */
let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "t1", title: "Design homepage", description: "Create wireframes", assignee: "Ava" },
      { id: "t2", title: "Set up auth", description: "Implement login flow", assignee: "Noah" },
    ],
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [
      { id: "t3", title: "Build API", description: "Create task endpoints", assignee: "Mia" },
    ],
  },
  {
    id: "done",
    title: "Done",
    tasks: [
      { id: "t4", title: "Project kickoff", description: "Initial planning meeting", assignee: "Liam" },
    ],
  },
];

let clients = new Set();

function broadcast(message) {
  const data = JSON.stringify(message);
  for (const client of clients) {
    if (client.readyState === 1) client.send(data);
  }
}

app.get("/api/boards", (req, res) => {
  res.json({ boards });
});

app.post("/api/tasks", (req, res) => {
  const { boardId, title, description = "", assignee = "" } = req.body;
  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const task = {
    id: uuidv4(),
    title,
    description,
    assignee,
  };

  board.tasks.push(task);

  broadcast({
    type: "task-created",
    payload: { boardId, task },
  });

  res.status(201).json({ task });
});

app.put("/api/tasks/move", (req, res) => {
  const { taskId, fromBoardId, toBoardId, toIndex } = req.body;

  const fromBoard = boards.find((b) => b.id === fromBoardId);
  const toBoard = boards.find((b) => b.id === toBoardId);

  if (!fromBoard || !toBoard) {
    return res.status(404).json({ error: "Board not found" });
  }

  const taskIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = fromBoard.tasks.splice(taskIndex, 1);
  const insertIndex = Math.max(0, Math.min(toIndex ?? toBoard.tasks.length, toBoard.tasks.length));
  toBoard.tasks.splice(insertIndex, 0, task);

  broadcast({
    type: "task-moved",
    payload: { taskId, fromBoardId, toBoardId, toIndex: insertIndex },
  });

  res.json({ ok: true });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const board of boards) {
    const index = board.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      const [removed] = board.tasks.splice(index, 1);

      broadcast({
        type: "task-deleted",
        payload: { taskId: removed.id },
      });

      return res.json({ ok: true });
    }
  }

  res.status(404).json({ error: "Task not found" });
});

wss.on("connection", (ws) => {
  clients.add(ws);

  ws.send(JSON.stringify({ type: "init", payload: { boards } }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      // Example: presence updates
      if (msg.type === "presence") {
        broadcast({
          type: "presence",
          payload: msg.payload,
        });
      }
    } catch (err) {
      console.error("Invalid message", err);
    }
  });

  ws.on("close", () => {
    clients.delete(ws);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

