# 2) Frontend: `App.tsx`

Install dependencies:

```bash
npm install react react-dom @dnd-kit/core @dnd-kit/sortable @dnd-kit/utilities
```

Then use this React app:

```tsx
import React, { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners,
} from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy, useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

type Task = {
  id: string;
  title: string;
  description?: string;
  assignee?: string;
};

type Board = {
  id: string;
  title: string;
  tasks: Task[];
};

type ServerMessage =
  | { type: "init"; payload: { boards: Board[] } }
  | { type: "task-created"; payload: { boardId: string; task: Task } }
  | { type: "task-moved"; payload: { taskId: string; fromBoardId: string; toBoardId: string; toIndex: number } }
  | { type: "task-deleted"; payload: { taskId: string } }
  | { type: "presence"; payload: any };

const API_URL = "http://localhost:4000";
const WS_URL = "ws://localhost:4000";

export default function App() {
  const [boards, setBoards] = useState<Board[]>([]);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);
  const [socket, setSocket] = useState<WebSocket | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    })
  );

  useEffect(() => {
    fetch(`${API_URL}/api/boards`)
      .then((res) => res.json())
      .then((data) => setBoards(data.boards));
  }, []);

  useEffect(() => {
    const ws = new WebSocket(WS_URL);
    setSocket(ws);

    ws.onmessage = (event) => {
      const msg: ServerMessage = JSON.parse(event.data);

      if (msg.type === "init") {
        setBoards(msg.payload.boards);
      }

      if (msg.type === "task-created") {
        setBoards((prev) =>
          prev.map((b) =>
            b.id === msg.payload.boardId ? { ...b, tasks: [...b.tasks, msg.payload.task] } : b
          )
        );
      }

      if (msg.type === "task-moved") {
        setBoards((prev) => {
          const fromBoard = prev.find((b) => b.id === msg.payload.fromBoardId);
          const toBoard = prev.find((b) => b.id === msg.payload.toBoardId);
          if (!fromBoard || !toBoard) return prev;

          const fromTasks = [...fromBoard.tasks];
          const toTasks = [...toBoard.tasks];

          const idx = fromTasks.findIndex((t) => t.id === msg.payload.taskId);
          if (idx === -1) return prev;

          const [task] = fromTasks.splice(idx, 1);
          toTasks.splice(msg.payload.toIndex, 0, task);

          return prev.map((b) => {
            if (b.id === msg.payload.fromBoardId) return { ...b, tasks: fromTasks };
            if (b.id === msg.payload.toBoardId) return { ...b, tasks: toTasks };
            return b;
          });
        });
      }

      if (msg.type === "task-deleted") {
        setBoards((prev) =>
          prev.map((b) => ({
            ...b,
            tasks: b.tasks.filter((t) => t.id !== msg.payload.taskId),
          }))
        );
      }
    };

    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "presence", payload: { userId: "demo-user", status: "online" } }));
    };

    return () => ws.close();
  }, []);

  const boardIds = useMemo(() => boards.map((b) => b.id), [boards]);

  function findBoardByTaskId(taskId: string) {
    return boards.find((b) => b.tasks.some((t) => t.id === taskId));
  }

  async function persistMove(taskId: string, fromBoardId: string, toBoardId: string, toIndex: number) {
    await fetch(`${API_URL}/api/tasks/move`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ taskId, fromBoardId, toBoardId, toIndex }),
    });
  }

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragOver(event: DragOverEvent) {
    // Optional: live preview logic can go here
  }

  async function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    setActiveTaskId(null);

    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const fromBoard = findBoardByTaskId(taskId);
    if (!fromBoard) return;

    const overBoard = boards.find((b) => b.id === overId) || findBoardByTaskId(overId);
    if (!overBoard) return;

    const toBoardId = overBoard.id;

    const fromIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
    const toIndex = overBoard.tasks.findIndex((t) => t.id === overId);

    if (fromBoard.id === toBoardId && fromIndex === toIndex) return;

    setBoards((prev) => {
      const sourceBoard = prev.find((b) => b.id === fromBoard.id)!;
      const targetBoard = prev.find((b) => b.id === toBoardId)!;

      const sourceTasks = [...sourceBoard.tasks];
      const targetTasks = sourceBoard.id === targetBoard.id ? sourceTasks : [...targetBoard.tasks];

      const srcIdx = sourceTasks.findIndex((t) => t.id === taskId);
      const [task] = sourceTasks.splice(srcIdx, 1);

      const insertIndex =
        toIndex >= 0 ? toIndex : targetTasks.length;

      if (sourceBoard.id === targetBoard.id) {
        sourceTasks.splice(insertIndex, 0, task);
        return prev.map((b) => (b.id === sourceBoard.id ? { ...b, tasks: sourceTasks } : b));
      } else {
        targetTasks.splice(insertIndex, 0, task);
        return prev.map((b) => {
          if (b.id === sourceBoard.id) return { ...b, tasks: sourceTasks };
          if (b.id === targetBoard.id) return { ...b, tasks: targetTasks };
          return b;
        });
      }
    });

    await persistMove(taskId, fromBoard.id, toBoardId, Math.max(0, toIndex));
  }

  async function addTask(boardId: string) {
    const title = prompt("Task title?");
    if (!title) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        boardId,
        title,
        description: "",
        assignee: "",
      }),
    });
  }

  async function deleteTask(taskId: string) {
    await fetch(`${API_URL}/api/tasks/${taskId}`, { method: "DELETE" });
  }

  return (
    <div style={styles.app}>
      <header style={styles.header}>
        <h1 style={{ margin: 0 }}>Project Board</h1>
        <div style={styles.headerRight}>
          <span style={styles.pill}>Real-time collaboration</span>
          <span style={styles.pill}>Drag and drop</span>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        <div style={styles.boardRow}>
          {boards.map((board) => (
            <BoardColumn
              key={board.id}
              board={board}
              onAddTask={() => addTask(board.id)}
              onDeleteTask={deleteTask}
            />
          ))}
        </div>
      </DndContext>

      {activeTaskId && <div style={styles.dragHint}>Dragging task: {activeTaskId}</div>}
    </div>
  );
}

function BoardColumn({
  board,
  onAddTask,
  onDeleteTask,
}: {
  board: Board;
  onAddTask: () => void;
  onDeleteTask: (taskId: string) => void;
}) {
  return (
    <div style={styles.column}>
      <div style={styles.columnHeader}>
        <h2 style={{ margin: 0 }}>{board.title}</h2>
        <button onClick={onAddTask} style={styles.button}>
          + Task
        </button>
      </div>

      <SortableContext items={board.tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div style={styles.taskList} id={board.id}>
          {board.tasks.map((task) => (
            <TaskCard key={task.id} task={task} onDelete={() => onDeleteTask(task.id)} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onDelete }: { task: Task; onDelete: () => void }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id,
  });

  const style: React.CSSProperties = {
    ...styles.task,
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      <div style={styles.taskTitleRow}>
        <strong>{task.title}</strong>
        <button onClick={onDelete} style={styles.deleteButton}>
          ×
        </button>
      </div>
      {task.description && <div style={styles.taskMeta}>{task.description}</div>}
      {task.assignee && <div style={styles.taskMeta}>Assignee: {task.assignee}</div>}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  app: {
    minHeight: "100vh",
    background: "#0f172a",
    color: "#e2e8f0",
    padding: 20,
    fontFamily: "Inter, system-ui, sans-serif",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: 20,
  },
  headerRight: {
    display: "flex",
    gap: 8,
  },
  pill: {
    background: "#1e293b",
    padding: "6px 10px",
