## 2) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import { createServer } from "http";
import { randomUUID } from "crypto";

const app = express();
app.use(cors());
app.use(express.json());

const server = createServer(app);
const wss = new WebSocketServer({ server });

/**
 * In-memory store for demo purposes.
 * Replace with a database for production.
 */
let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: randomUUID(), title: "Design UI", description: "Create wireframes", assignee: "Ava" },
        { id: randomUUID(), title: "Set up backend", description: "Initialize server", assignee: "Noah" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: randomUUID(), title: "Build drag and drop", description: "Use HTML5 DnD", assignee: "Mia" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: randomUUID(), title: "Project kickoff", description: "Initial planning", assignee: "Liam" }
      ]
    }
  ]
};

function broadcast(message) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(data);
    }
  }
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/task", (req, res) => {
  const { boardId, title, description = "", assignee = "" } = req.body;

  if (!boardId || !title) {
    return res.status(400).json({ error: "boardId and title are required" });
  }

  const board = state.boards.find((b) => b.id === boardId);
  if (!board) {
    return res.status(404).json({ error: "Board not found" });
  }

  const task = {
    id: randomUUID(),
    title,
    description,
    assignee
  };

  board.tasks.push(task);
  broadcast({ type: "state", state });
  res.status(201).json(task);
});

app.put("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description, assignee } = req.body;

  for (const board of state.boards) {
    const task = board.tasks.find((t) => t.id === taskId);
    if (task) {
      if (title !== undefined) task.title = title;
      if (description !== undefined) task.description = description;
      if (assignee !== undefined) task.assignee = assignee;

      broadcast({ type: "state", state });
      return res.json(task);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const board of state.boards) {
    const index = board.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      const [removed] = board.tasks.splice(index, 1);
      broadcast({ type: "state", state });
      return res.json(removed);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, fromBoardId, toBoardId, toIndex } = req.body;

  const fromBoard = state.boards.find((b) => b.id === fromBoardId);
  const toBoard = state.boards.find((b) => b.id === toBoardId);

  if (!fromBoard || !toBoard) {
    return res.status(404).json({ error: "Board not found" });
  }

  const taskIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromBoard.tasks.splice(taskIndex, 1);
  const insertIndex = Math.max(0, Math.min(toIndex ?? toBoard.tasks.length, toBoard.tasks.length));
  toBoard.tasks.splice(insertIndex, 0, task);

  broadcast({ type: "state", state });
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", state }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "sync-request") {
        ws.send(JSON.stringify({ type: "state", state }));
      }
    } catch {
      // ignore malformed messages
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

