## 5) Frontend: `client/app.js`

```js
const API_BASE = "http://localhost:3000";
const WS_URL = "ws://localhost:3000";

const boardsEl = document.getElementById("boards");
const taskForm = document.getElementById("taskForm");
const connectionStatus = document.getElementById("connectionStatus");
const taskTemplate = document.getElementById("taskTemplate");

let appState = null;
let ws = null;
let draggedTask = null;

async function fetchState() {
  const res = await fetch(`${API_BASE}/api/state`);
  appState = await res.json();
  render();
}

function connectWebSocket() {
  ws = new WebSocket(WS_URL);

  ws.addEventListener("open", () => {
    connectionStatus.textContent = "Connected";
    connectionStatus.style.color = "#22c55e";
  });

  ws.addEventListener("close", () => {
    connectionStatus.textContent = "Disconnected - reconnecting...";
    connectionStatus.style.color = "#f59e0b";
    setTimeout(connectWebSocket, 1000);
  });

  ws.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data);
    if (msg.type === "state") {
      appState = msg.state;
      render();
    }
  });
}

function render() {
  if (!appState) return;

  boardsEl.innerHTML = "";

  appState.boards.forEach((board) => {
    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const taskList = boardEl.querySelector(".task-list");

    board.tasks.forEach((task) => {
      const taskNode = createTaskNode(task, board.id);
      taskList.appendChild(taskNode);
    });

    setupDropZone(taskList, board.id);
    boardsEl.appendChild(boardEl);
  });
}

function createTaskNode(task, boardId) {
  const node = taskTemplate.content.firstElementChild.cloneNode(true);
  node.dataset.taskId = task.id;
  node.dataset.boardId = boardId;

  node.querySelector(".task-title").textContent = task.title;
  node.querySelector(".task-description").textContent = task.description || "";
  node.querySelector(".task-assignee").textContent = task.assignee ? `@${task.assignee}` : "";

  node.addEventListener("dragstart", (e) => {
    draggedTask = {
      taskId: task.id,
      fromBoardId: boardId
    };
    e.dataTransfer.setData("text/plain", task.id);
    e.dataTransfer.effectAllowed = "move";
  });

  node.querySelector(".delete-btn").addEventListener("click", async (e) => {
    e.stopPropagation();
    await fetch(`${API_BASE}/api/task/${task.id}`, { method: "DELETE" });
  });

  return node;
}

function setupDropZone(taskList, boardId) {
  taskList.addEventListener("dragover", (e) => {
    e.preventDefault();
    taskList.classList.add("drag-over");
  });

  taskList.addEventListener("dragleave", () => {
    taskList.classList.remove("drag-over");
  });

  taskList.addEventListener("drop", async (e) => {
    e.preventDefault();
    taskList.classList.remove("drag-over");

    if (!draggedTask) return;

    const children = [...taskList.querySelectorAll(".task")];
    const dropTarget = e.target.closest(".task");
    const toIndex = dropTarget ? children.indexOf(dropTarget) : children.length;

    await fetch(`${API_BASE}/api/move-task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: draggedTask.taskId,
        fromBoardId: draggedTask.fromBoardId,
        toBoardId: boardId,
        toIndex
      })
    });

    draggedTask = null;
  });
}

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const title = document.getElementById("taskTitle").value.trim();
  const description = document.getElementById("taskDescription").value.trim();
  const assignee = document.getElementById("taskAssignee").value.trim();
  const boardId = document.getElementById("taskBoard").value;

  if (!title) return;

  await fetch(`${API_BASE}/api/task`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ boardId, title, description, assignee })
  });

  taskForm.reset();
  document.getElementById("taskBoard").value = boardId;
});

fetchState();
connectWebSocket();
```

