## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory board state.
 * In production, persist this in a database.
 */
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design app layout", description: "Create initial UI mockups" },
        { id: "task-2", title: "Set up backend", description: "Initialize Express and Socket.IO" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Implement drag and drop", description: "Use HTML5 drag events" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Project scaffold", description: "Create folder structure" }
      ]
    }
  ]
};

function findTaskLocation(taskId) {
  for (const column of boardState.columns) {
    const index = column.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      return { columnId: column.id, index };
    }
  }
  return null;
}

function moveTask(taskId, targetColumnId, targetIndex) {
  const location = findTaskLocation(taskId);
  if (!location) return false;

  const sourceColumn = boardState.columns.find((c) => c.id === location.columnId);
  const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);
  if (!sourceColumn || !targetColumn) return false;

  const [task] = sourceColumn.tasks.splice(location.index, 1);

  // Clamp target index
  const safeIndex = Math.max(0, Math.min(targetIndex, targetColumn.tasks.length));
  targetColumn.tasks.splice(safeIndex, 0, task);

  return true;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current state to new client
  socket.emit("board:init", boardState);

  // Handle task move
  socket.on("task:move", ({ taskId, targetColumnId, targetIndex }) => {
    const ok = moveTask(taskId, targetColumnId, targetIndex);
    if (ok) {
      io.emit("board:update", boardState);
    }
  });

  // Handle task creation
  socket.on("task:create", ({ columnId, title, description }) => {
    const column = boardState.columns.find((c) => c.id === columnId);
    if (!column) return;

    const newTask = {
      id: `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      title: title || "Untitled Task",
      description: description || ""
    };

    column.tasks.unshift(newTask);
    io.emit("board:update", boardState);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    const location = findTaskLocation(taskId);
    if (!location) return;

    const column = boardState.columns.find((c) => c.id === location.columnId);
    column.tasks.splice(location.index, 1);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

