## 6) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");

const newTaskForm = document.getElementById("newTaskForm");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");

let boardState = null;
let draggedTaskId = null;

socket.on("board:init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const columnEl = columnNode.querySelector(".column");
    const titleEl = columnNode.querySelector(".column-title");
    const taskListEl = columnNode.querySelector(".task-list");

    titleEl.textContent = `${column.title} (${column.tasks.length})`;
    taskListEl.dataset.columnId = column.id;

    column.tasks.forEach((task, index) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const title = taskNode.querySelector(".task-title");
      const description = taskNode.querySelector(".task-description");
      const deleteBtn = taskNode.querySelector(".delete-task");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.index = index;
      title.textContent = task.title;
      description.textContent = task.description;

      taskEl.addEventListener("dragstart", onDragStart);
      taskEl.addEventListener("dragend", onDragEnd);

      deleteBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        socket.emit("task:delete", { taskId: task.id });
      });

      taskListEl.appendChild(taskNode);
    });

    taskListEl.addEventListener("dragover", onDragOver);
    taskListEl.addEventListener("dragleave", onDragLeave);
    taskListEl.addEventListener("drop", onDrop);

    boardEl.appendChild(columnEl);
  });
}

function onDragStart(e) {
  draggedTaskId = e.currentTarget.dataset.taskId;
  e.dataTransfer.setData("text/plain", draggedTaskId);
  e.dataTransfer.effectAllowed = "move";
  e.currentTarget.style.opacity = "0.5";
}

function onDragEnd(e) {
  e.currentTarget.style.opacity = "1";
  draggedTaskId = null;
  document.querySelectorAll(".task-list").forEach((list) => list.classList.remove("drag-over"));
}

function onDragOver(e) {
  e.preventDefault();
  e.currentTarget.classList.add("drag-over");
  e.dataTransfer.dropEffect = "move";
}

function onDragLeave(e) {
  e.currentTarget.classList.remove("drag-over");
}

function onDrop(e) {
  e.preventDefault();
  e.currentTarget.classList.remove("drag-over");

  const targetColumnId = e.currentTarget.dataset.columnId;
  const taskId = draggedTaskId || e.dataTransfer.getData("text/plain");
  if (!taskId) return;

  const tasksInTargetColumn = [...e.currentTarget.querySelectorAll(".task")];
  const dropY = e.clientY;

  let targetIndex = tasksInTargetColumn.length;

  for (let i = 0; i < tasksInTargetColumn.length; i++) {
    const rect = tasksInTargetColumn[i].getBoundingClientRect();
    const midpoint = rect.top + rect.height / 2;
    if (dropY < midpoint) {
      targetIndex = i;
      break;
    }
  }

  socket.emit("task:move", {
    taskId,
    targetColumnId,
    targetIndex
  });
}

newTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:create", {
    columnId: taskColumnSelect.value,
    title: taskTitleInput.value.trim(),
    description: taskDescriptionInput.value.trim()
  });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskTitleInput.focus();
});
```

