```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory state for demo purposes
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["t1", "t2"]
    },
    {
      id: "doing",
      title: "In Progress",
      taskIds: ["t3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    t1: { id: "t1", title: "Design project roadmap", description: "Draft milestones and timeline." },
    t2: { id: "t2", title: "Set up repo", description: "Initialize frontend and backend." },
    t3: { id: "t3", title: "Build auth flow", description: "Add login and session handling." }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("board:update", (newState) => {
    boardState = newState;
    socket.broadcast.emit("board:update", boardState);
  });

  socket.on("task:add", (task) => {
    const id = `t${Date.now()}`;
    boardState.tasks[id] = { id, ...task };

    const targetColumn = boardState.columns.find(c => c.id === task.columnId);
    if (targetColumn) {
      targetColumn.taskIds.push(id);
    }

    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

