import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { DragDropContext } from "@hello-pangea/dnd";
import Board from "./components/Board";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");

  useEffect(() => {
    socket.on("board:update", (state) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const onDragEnd = (result) => {
    if (!result.destination || !board) return;

    const { source, destination, draggableId } = result;

    const sourceColumnId = source.droppableId;
    const destinationColumnId = destination.droppableId;

    if (sourceColumnId === destinationColumnId && source.index === destination.index) return;

    const updated = structuredClone(board);

    // Remove from source
    const sourceColumn = updated.columns.find(c => c.id === sourceColumnId);
    const destColumn = updated.columns.find(c => c.id === destinationColumnId);
    if (!sourceColumn || !destColumn) return;

    sourceColumn.taskIds.splice(source.index, 1);
    destColumn.taskIds.splice(destination.index, 0, draggableId);

    setBoard(updated);
    socket.emit("board:update", updated);
  };

  const addTask = () => {
    if (!newTaskTitle.trim()) return;

    socket.emit("task:add", {
      title: newTaskTitle.trim(),
      description: "",
      columnId: selectedColumn
    });

    setNewTaskTitle("");
  };

  const columnOptions = useMemo(() => {
    return board?.columns ?? [];
  }, [board]);

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>

        <div className="new-task">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <select value={selectedColumn} onChange={(e) => setSelectedColumn(e.target.value)}>
            {columnOptions.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button onClick={addTask}>Add Task</button>
        </div>
      </header>

      <DragDropContext onDragEnd={onDragEnd}>
        <Board board={board} />
      </DragDropContext>
    </div>
  );
}
