import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { db } from "./store.js";

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

app.use(cors({ origin: "http://localhost:5173" }));
app.use(express.json());

function findProject(projectId) {
  return db.projects.find(p => p.id === projectId);
}

app.get("/api/projects", (req, res) => {
  res.json(db.projects);
});

app.get("/api/projects/:projectId", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });
  res.json(project);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: `p_${Date.now()}`,
    name: name || "Untitled Project",
    columns: [
      { id: "todo", title: "To Do", tasks: [] },
      { id: "doing", title: "In Progress", tasks: [] },
      { id: "done", title: "Done", tasks: [] }
    ]
  };
  db.projects.push(project);
  io.emit("project:created", project);
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { columnId, title, description = "", assignee = "" } = req.body;
  const column = project.columns.find(c => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  const task = {
    id: `t_${Date.now()}`,
    title,
    description,
    assignee
  };

  column.tasks.push(task);
  io.emit("task:created", { projectId: project.id, columnId, task });
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId/move", (req, res) => {
  const { projectId, taskId } = req.params;
  const { fromColumnId, toColumnId, toIndex } = req.body;

  const project = findProject(projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const fromColumn = project.columns.find(c => c.id === fromColumnId);
  const toColumn = project.columns.find(c => c.id === toColumnId);
  if (!fromColumn || !toColumn) return res.status(404).json({ error: "Column not found" });

  const taskIndex = fromColumn.tasks.findIndex(t => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = fromColumn.tasks.splice(taskIndex, 1);
  const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.tasks.length;
  toColumn.tasks.splice(insertIndex, 0, task);

  io.emit("task:moved", { projectId, taskId, fromColumnId, toColumnId, toIndex: insertIndex });
  res.json({ success: true });
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const project = findProject(projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  for (const column of project.columns) {
    const idx = column.tasks.findIndex(t => t.id === taskId);
    if (idx !== -1) {
      const [removed] = column.tasks.splice(idx, 1);
      io.emit("task:deleted", { projectId, taskId: removed.id });
      return res.json({ success: true });
    }
  }

  res.status(404).json({ error: "Task not found" });
});

io.on("connection", socket => {
  console.log("Client connected:", socket.id);

  socket.on("join:project", projectId => {
    socket.join(projectId);
  });

  socket.on("task:updated", payload => {
    io.to(payload.projectId).emit("task:updated", payload);
  });

  socket.on("task:moved", payload => {
    io.to(payload.projectId).emit("task:moved", payload);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
