import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function TaskCard({ task, onDragStart, onDelete }) {
  return (
    <div
      className="task-card"
      draggable
      onDragStart={(e) => onDragStart(e, task)}
    >
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
      <div className="task-meta">
        <span>{task.assignee || "Unassigned"}</span>
        <button className="delete-btn" onClick={() => onDelete(task.id)}>×</button>
      </div>
    </div>
  );
}

function Column({ column, onDropTask, onDragOver, onDragStart, onDelete }) {
  return (
    <div
      className="column"
      onDragOver={onDragOver}
      onDrop={(e) => onDropTask(e, column.id)}
    >
      <h3>{column.title}</h3>
      <div className="task-list">
        {column.tasks.map((task) => (
          <TaskCard
            key={task.id}
            task={task}
            onDragStart={onDragStart}
            onDelete={onDelete}
          />
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [projects, setProjects] = useState([]);
  const [activeProjectId, setActiveProjectId] = useState("");
  const [draggedTask, setDraggedTask] = useState(null);
  const [newProjectName, setNewProjectName] = useState("");
  const [newTask, setNewTask] = useState({
    title: "",
    description: "",
    assignee: "",
    columnId: "todo"
  });

  const activeProject = useMemo(
    () => projects.find((p) => p.id === activeProjectId),
    [projects, activeProjectId]
  );

  async function loadProjects() {
    const res = await fetch(`${API_URL}/api/projects`);
    const data = await res.json();
    setProjects(data);
    if (!activeProjectId && data.length > 0) {
      setActiveProjectId(data[0].id);
      socket.emit("join:project", data[0].id);
    }
  }

  useEffect(() => {
    loadProjects();

    socket.on("project:created", (project) => {
      setProjects((prev) => [...prev, project]);
    });

    socket.on("task:created", ({ projectId, columnId, task }) => {
      setProjects((prev) =>
        prev.map((p) =>
          p.id !== projectId
            ? p
            : {
                ...p,
                columns: p.columns.map((c) =>
                  c.id !== columnId ? c : { ...c, tasks: [...c.tasks, task] }
                )
              }
        )
      );
    });

    socket.on("task:deleted", ({ projectId, taskId }) => {
      setProjects((prev) =>
        prev.map((p) =>
          p.id !== projectId
            ? p
            : {
                ...p,
                columns: p.columns.map((c) => ({
                  ...c,
                  tasks: c.tasks.filter((t) => t.id !== taskId)
                }))
              }
        )
      );
    });

    socket.on("task:moved", ({ projectId, taskId, fromColumnId, toColumnId, toIndex }) => {
      setProjects((prev) =>
        prev.map((p) => {
          if (p.id !== projectId) return p;

          let movedTask = null;
          const columnsAfterRemove = p.columns.map((c) => {
            if (c.id !== fromColumnId) return c;
            const tasks = c.tasks.filter((t) => {
              if (t.id === taskId) {
                movedTask = t;
                return false;
              }
              return true;
            });
            return { ...c, tasks };
          });

          return {
            ...p,
            columns: columnsAfterRemove.map((c) => {
              if (c.id !== toColumnId || !movedTask) return c;
              const tasks = [...c.tasks];
              tasks.splice(toIndex, 0, movedTask);
              return { ...c, tasks };
            })
          };
        })
      );
    });

    return () => {
      socket.off("project:created");
      socket.off("task:created");
      socket.off("task:deleted");
      socket.off("task:moved");
    };
  }, []);

  useEffect(() => {
    if (activeProjectId) {
      socket.emit("join:project", activeProjectId);
    }
  }, [activeProjectId]);

  async function createProject(e) {
    e.preventDefault();
    if (!newProjectName.trim()) return;

    await fetch(`${API_URL}/api/projects`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: newProjectName })
    });

    setNewProjectName("");
  }

  async function createTask(e) {
    e.preventDefault();
    if (!newTask.title.trim() || !activeProjectId) return;

    await fetch(`${API_URL}/api/projects/${activeProjectId}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newTask)
    });

    setNewTask({ title: "", description: "", assignee: "", columnId: "todo" });
  }

  function onDragStart(e, task) {
    setDraggedTask(task);
    e.dataTransfer.effectAllowed = "move";
  }

  async function onDropTask(e, toColumnId) {
    e.preventDefault();
    if (!draggedTask || !activeProject) return;

    let fromColumnId = null;
    let toIndex = 0;

    for (const column of activeProject.columns) {
      if (column.tasks.some((t) => t.id === draggedTask.id)) {
        fromColumnId = column.id;
      }
      if (column.id === toColumnId) {
        toIndex = column.tasks.length;
      }
    }

    if (!fromColumnId) return;

    await fetch(`${API_URL}/api/projects/${activeProjectId}/tasks/${draggedTask.id}/move`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ fromColumnId, toColumnId, toIndex })
    });

    setDraggedTask(null);
  }

  function onDragOver(e) {
    e.preventDefault();
  }

  async function deleteTask(taskId) {
    await fetch(`${API_URL}/api/projects/${activeProjectId}/tasks/${taskId}`, {
      method: "DELETE"
    });
  }

  return (
    <div className="app">
      <aside className="sidebar">
        <h2>Projects</h2>
        <form onSubmit={createProject} className="form">
          <input
            value={newProjectName}
            onChange={(e) => setNewProjectName(e.target.value)}
            placeholder="New project name"
          />
          <button type="submit">Create</button>
        </form>

        <div className="project-list">
          {projects.map((project) => (
            <button
              key={project.id}
              className={`project-btn ${project.id === activeProjectId ? "active" : ""}`}
              onClick={() => setActiveProjectId(project.id)}
            >
              {project.name}
            </button>
          ))}
        </div>

        <h3>Add Task</h3>
        <form onSubmit={createTask} className="form">
          <input
            value={newTask.title}
            onChange={(e) => setNewTask((p) => ({ ...p, title: e.target.value }))}
            placeholder="Task title"
          />
          <input
            value={newTask.description}
            onChange={(e) => setNewTask((p) => ({ ...p, description: e.target.value }))}
            placeholder="Description"
          />
          <input
            value={newTask.assignee}
            onChange={(e) => setNewTask((p) => ({ ...p, assignee: e.target.value }))}
            placeholder="Assignee"
          />
          <select
            value={newTask.columnId}
            onChange={(e) => setNewTask((p) => ({ ...p, columnId: e.target.value }))}
          >
            <option value="todo">To Do</option>
            <option value="doing">In Progress</option>
            <option value="done">Done</option>
          </select>
          <button type="submit">Add Task</button>
        </form>
      </aside>

      <main className="board">
        <header>
          <h1>{activeProject ? activeProject.name : "No project selected"}</h1>
          <p>Drag and drop tasks between columns. Updates sync in real time.</p>
        </header>

        <div className="columns">
          {activeProject?.columns?.map((column) => (
            <Column
              key={column.id}
              column={column}
              onDropTask={onDropTask}
              onDragOver={onDragOver}
              onDragStart={onDragStart}
              onDelete={deleteTask}
            />
          ))}
        </div>
      </main>
    </div>
  );
}
