### `server/src/store.ts`

```ts
import { BoardState, MoveTaskPayload, Task } from "./types.js";

const now = () => new Date().toISOString();

export const store: BoardState = {
  columns: [
    { id: "todo", title: "To Do", order: 0 },
    { id: "in-progress", title: "In Progress", order: 1 },
    { id: "done", title: "Done", order: 2 }
  ],
  tasks: [
    {
      id: "task-1",
      title: "Design project overview",
      description: "Create a high-level dashboard layout",
      columnId: "todo",
      order: 0,
      updatedAt: now()
    },
    {
      id: "task-2",
      title: "Set up authentication",
      description: "Add login and session handling",
      columnId: "in-progress",
      order: 0,
      updatedAt: now()
    },
    {
      id: "task-3",
      title: "Write deployment plan",
      columnId: "done",
      order: 0,
      updatedAt: now()
    }
  ]
};

export function getBoard() {
  return {
    columns: [...store.columns].sort((a, b) => a.order - b.order),
    tasks: [...store.tasks].sort((a, b) => a.order - b.order)
  };
}

export function moveTask(payload: MoveTaskPayload) {
  const task = store.tasks.find((t) => t.id === payload.taskId);
  if (!task) throw new Error("Task not found");

  task.columnId = payload.toColumnId;
  task.order = payload.toIndex;
  task.updatedAt = now();

  // Re-normalize ordering within each column
  const grouped = new Map<string, Task[]>();
  for (const t of store.tasks) {
    if (!grouped.has(t.columnId)) grouped.set(t.columnId, []);
    grouped.get(t.columnId)!.push(t);
  }

  for (const [, tasks] of grouped) {
    tasks
      .sort((a, b) => a.order - b.order)
      .forEach((t, idx) => {
        t.order = idx;
      });
  }

  return getBoard();
}
```

### `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { getBoard, moveTask } from "./store.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(getBoard());
});

app.post("/api/tasks/move", (req, res) => {
  try {
    const board = moveTask(req.body);
    io.emit("board:updated", board);
    res.json(board);
  } catch (error) {
    res.status(400).json({ error: (error as Error).message });
  }
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:updated", getBoard());

  socket.on("board:join", () => {
    socket.emit("board:updated", getBoard());
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

