### `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter
} from "@dnd-kit/core";
import { arrayMove } from "@dnd-kit/sortable";
import type { BoardState } from "../types";
import { ColumnView } from "./Column";

export function Board({
  board,
  onMove
}: {
  board: BoardState;
  onMove: (args: {
    taskId: string;
    fromColumnId: string;
    toColumnId: string;
    toIndex: number;
  }) => void;
}) {
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const tasksByColumn = (columnId: string) =>
    board.tasks.filter((task) => task.columnId === columnId).sort((a, b) => a.order - b.order);

  const findTask = (taskId: string) => board.tasks.find((t) => t.id === taskId);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const activeTask = findTask(String(active.id));
    const overTask = findTask(String(over.id));
    if (!activeTask || !overTask) return;

    const fromColumnId = activeTask.columnId;
    const toColumnId = overTask.columnId;

    const toTasks = tasksByColumn(toColumnId);
    const overIndex = toTasks.findIndex((t) => t.id === overTask.id);

    onMove({
      taskId: activeTask.id,
      fromColumnId,
      toColumnId,
      toIndex: overIndex < 0 ? toTasks.length : overIndex
    });
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, overflowX: "auto", padding: 8 }}>
        {board.columns
          .slice()
          .sort((a, b) => a.order - b.order)
          .map((column) => (
            <ColumnView key={column.id} column={column} tasks={tasksByColumn(column.id)} />
          ))}
      </div>
    </DndContext>
  );
}
```

### `client/src/App.tsx`

```tsx
import { useEffect, useState } from "react";
import { Board } from "./components/Board";
import { fetchBoard, moveTask } from "./api";
import { socket } from "./socket";
import type { BoardState } from "./types";

const initialBoard: BoardState = { columns: [], tasks: [] };

export default function App() {
  const [board, setBoard] = useState<BoardState>(initialBoard);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBoard()
      .then(setBoard)
      .finally(() => setLoading(false));

    socket.on("board:updated", (updatedBoard: BoardState) => {
      setBoard(updatedBoard);
    });

    socket.emit("board:join");

    return () => {
      socket.off("board:updated");
    };
  }, []);

  const handleMove = async (payload: {
    taskId: string;
    fromColumnId: string;
    toColumnId: string;
    toIndex: number;
  }) => {
    await moveTask(payload);
  };

  return (
    <div style={{ fontFamily: "Inter, system-ui, sans-serif", background: "#eef1f5", minHeight: "100vh" }}>
      <header style={{ padding: "20px 24px", borderBottom: "1px solid #ddd", background: "#fff" }}>
        <h1 style={{ margin: 0 }}>Project Management</h1>
        <p style={{ margin: "6px 0 0", color: "#666" }}>Drag tasks across columns. Updates sync in real time.</p>
      </header>

      <main style={{ padding: 24 }}>
        {loading ? <p>Loading board...</p> : <Board board={board} onMove={handleMove} />}
      </main>
    </div>
  );
}
