  name: "Project Board",
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "in-progress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

export function seedBoard() {
  const t1 = {
    id: uuid(),
    title: "Set up project",
    description: "Initialize repository and tooling",
    createdAt: Date.now()
  };
  const t2 = {
    id: uuid(),
    title: "Design UI",
    description: "Create board layout and task cards",
    createdAt: Date.now()
  };
  const t3 = {
    id: uuid(),
    title: "Add real-time sync",
    description: "Wire up Socket.IO collaboration",
    createdAt: Date.now()
  };

  board.tasks[t1.id] = t1;
  board.tasks[t2.id] = t2;
  board.tasks[t3.id] = t3;

  board.columns[0].taskIds.push(t1.id, t2.id);
  board.columns[1].taskIds.push(t3.id);
}
