## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";
import { board, seedBoard, Task } from "./store";

seedBoard();

const app = express();
app.use(cors({ origin: true }));
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, columnId = "todo" } = req.body as {
    title: string;
    description?: string;
    assignee?: string;
    columnId?: string;
  };

  if (!title?.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const task: Task = {
    id: uuid(),
    title: title.trim(),
    description,
    assignee,
    createdAt: Date.now()
  };

  board.tasks[task.id] = task;
  const column = board.columns.find((c) => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const updated = { ...task, ...req.body, id: task.id };
  board.tasks[id] = updated;

  io.emit("board:update", board);
  res.json(updated);
});

app.post("/api/move", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body as {
    taskId: string;
    fromColumnId: string;
    toColumnId: string;
    toIndex: number;
  };

  const from = board.columns.find((c) => c.id === fromColumnId);
  const to = board.columns.find((c) => c.id === toColumnId);

  if (!from || !to) return res.status(400).json({ error: "Invalid column" });

  from.taskIds = from.taskIds.filter((id) => id !== taskId);
  to.taskIds.splice(toIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ ok: true });
});

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: true }
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("board:move", (payload) => {
    const { taskId, fromColumnId, toColumnId, toIndex } = payload as {
      taskId: string;
      fromColumnId: string;
      toColumnId: string;
      toIndex: number;
    };

    const from = board.columns.find((c) => c.id === fromColumnId);
    const to = board.columns.find((c) => c.id === toColumnId);

    if (!from || !to) return;

    from.taskIds = from.taskIds.filter((id) => id !== taskId);
    to.taskIds.splice(toIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:create", (payload) => {
    const { title, description, assignee, columnId = "todo" } = payload as {
      title: string;
      description?: string;
      assignee?: string;
      columnId?: string;
    };

    if (!title?.trim()) return;

    const task: Task = {
      id: uuid(),
      title: title.trim(),
      description,
      assignee,
      createdAt: Date.now()
    };

    board.tasks[task.id] = task;
    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    column.taskIds.push(task.id);
    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

