```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners,
  useDroppable
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Board, Column, Task } from "./types";

const API_URL = "http://localhost:4000";

function TaskCard({
  task,
  isOverlay = false
}: {
  task: Task;
  isOverlay?: boolean;
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging && !isOverlay ? 0.4 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
      {task.assignee && <div className="task-meta">Assigned to {task.assignee}</div>}
    </div>
  );
}

function ColumnView({
  column,
  tasks
}: {
  column: Column;
  tasks: Task[];
}) {
  const { setNodeRef, isOver } = useDroppable({ id: column.id });

  return (
    <div ref={setNodeRef} className={`column ${isOver ? "column-over" : ""}`}>
      <div className="column-header">{column.title}</div>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    const socket: Socket = io(API_URL);

    socket.on("board:update", (nextBoard: Board) => {
      setBoard(nextBoard);
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const tasksById = board?.tasks ?? {};

  const onDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveTask(null);
    if (!board || !over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const fromColumn = board.columns.find((col) => col.taskIds.includes(taskId));
    const toColumn = board.columns.find((col) => col.id === overId || col.taskIds.includes(overId));

    if (!fromColumn || !toColumn) return;

    const fromIndex = fromColumn.taskIds.indexOf(taskId);
    const toIndex =
      toColumn.id === overId
        ? toColumn.taskIds.length
        : Math.max(0, toColumn.taskIds.indexOf(overId));

    const next = structuredClone(board);

    next.columns.forEach((col) => {
      col.taskIds = col.taskIds.filter((id) => id !== taskId);
    });

    next.columns.find((c) => c.id === toColumn.id)!.taskIds.splice(toIndex, 0, taskId);

    setBoard(next);

    await fetch(`${API_URL}/api/move`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId,
        fromColumnId: fromColumn.id,
        toColumnId: toColumn.id,
        toIndex
      })
    });
  };

  const createTask = async () => {
    if (!title.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, columnId: "todo" })
    });

    setTitle("");
    setDescription("");
  };

  const columns = useMemo(() => board?.columns ?? [], [board]);

  return (
    <div className="app">
      <header className="topbar">
        <h1>{board?.name ?? "Loading..."}</h1>
        <div className="create-task">
          <input
            placeholder="Task title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <button onClick={createTask}>Add Task</button>
        </div>
      </header>

      <main className="board">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          onDragStart={(event) => {
            const task = tasksById[String(event.active.id)];
            if (task) setActiveTask(task);
          }}
          onDragEnd={onDragEnd}
          onDragCancel={() => setActiveTask(null)}
        >
          {columns.map((column) => (
            <ColumnView
              key={column.id}
              column={column}
              tasks={column.taskIds.map((id) => tasksById[id]).filter(Boolean)}
            />
          ))}

          <DragOverlay>
            {activeTask ? <TaskCard task={activeTask} isOverlay /> : null}
          </DragOverlay>
        </DndContext>
      </main>
    </div>
  );
}
