### `server/index.js`
```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let boards = {
  todo: [
    { id: "task-1", title: "Design project layout", description: "Create initial UI structure" },
    { id: "task-2", title: "Set up backend", description: "Express + Socket.IO server" }
  ],
  doing: [
    { id: "task-3", title: "Implement drag and drop", description: "Move tasks across columns" }
  ],
  done: []
};

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, task } = req.body;
  if (!columnId || !task?.title) {
    return res.status(400).json({ error: "columnId and task.title are required" });
  }

  const newTask = {
    id: `task-${Date.now()}`,
    title: task.title,
    description: task.description || ""
  };

  boards[columnId] = boards[columnId] || [];
  boards[columnId].push(newTask);

  io.emit("board:update", boards);
  res.status(201).json(newTask);
});

app.put("/api/tasks/move", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  if (!taskId || !fromColumnId || !toColumnId) {
    return res.status(400).json({ error: "taskId, fromColumnId, and toColumnId are required" });
  }

  const fromTasks = boards[fromColumnId] || [];
  const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromTasks.splice(taskIndex, 1);
  boards[toColumnId] = boards[toColumnId] || [];

  const insertIndex = typeof toIndex === "number" ? toIndex : boards[toColumnId].length;
  boards[toColumnId].splice(insertIndex, 0, task);

  io.emit("board:update", boards);
  res.json({ success: true, boards });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boards);

  socket.on("task:create", ({ columnId, task }) => {
    if (!columnId || !task?.title) return;

    const newTask = {
      id: `task-${Date.now()}`,
      title: task.title,
      description: task.description || ""
    };

    boards[columnId] = boards[columnId] || [];
    boards[columnId].push(newTask);

    io.emit("board:update", boards);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    if (!taskId || !fromColumnId || !toColumnId) return;

    const fromTasks = boards[fromColumnId] || [];
    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    boards[toColumnId] = boards[toColumnId] || [];

    const insertIndex = typeof toIndex === "number" ? toIndex : boards[toColumnId].length;
    boards[toColumnId].splice(insertIndex, 0, task);

    io.emit("board:update", boards);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

