### `client/app.js`
```js
const socket = io("http://localhost:3000");

let boardData = {
  todo: [],
  doing: [],
  done: []
};

const boardEl = document.getElementById("board");
const newTaskBtn = document.getElementById("newTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDesc = document.getElementById("taskDesc");
const taskColumn = document.getElementById("taskColumn");
const cancelBtn = document.getElementById("cancelBtn");

let draggedTask = null;

socket.on("board:update", (boards) => {
  boardData = boards;
  renderBoard();
});

function renderBoard() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    boardData[columnId].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { taskId: task.id, fromColumnId: columnId };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
        draggedTask = null;
      });

      list.appendChild(taskEl);
    });
  });
}

boardEl.querySelectorAll(".column").forEach((column) => {
  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");

    if (!draggedTask) return;

    const toColumnId = column.dataset.columnId;
    const toList = document.getElementById(toColumnId);
    const toIndex = toList.children.length;

    socket.emit("task:move", {
      ...draggedTask,
      toColumnId,
      toIndex
    });
  });
});

newTaskBtn.addEventListener("click", () => {
  taskForm.reset();
  taskDialog.showModal();
});

cancelBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const columnId = taskColumn.value;
  const task = {
    title: taskTitle.value.trim(),
    description: taskDesc.value.trim()
  };

  if (!task.title) return;

  socket.emit("task:create", { columnId, task });
  taskDialog.close();
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

