## `server/src/store.ts`

```ts
export type Task = {
  id: string;
  title: string;
  description?: string;
  columnId: string;
  order: number;
};

export type Column = {
  id: string;
  title: string;
};

export type BoardState = {
  columns: Column[];
  tasks: Task[];
};

export const initialState: BoardState = {
  columns: [
    { id: "todo", title: "To Do" },
    { id: "inprogress", title: "In Progress" },
    { id: "done", title: "Done" }
  ],
  tasks: [
    { id: "task-1", title: "Set up project", columnId: "todo", order: 0 },
    { id: "task-2", title: "Design UI", columnId: "todo", order: 1 },
    { id: "task-3", title: "Build drag-and-drop", columnId: "inprogress", order: 0 }
  ]
};

export function moveTask(
  state: BoardState,
  taskId: string,
  toColumnId: string,
  toIndex: number
): BoardState {
  const task = state.tasks.find(t => t.id === taskId);
  if (!task) return state;

  const updatedTasks = state.tasks.filter(t => t.id !== taskId);

  const sameColumnTasks = updatedTasks
    .filter(t => t.columnId === toColumnId)
    .sort((a, b) => a.order - b.order);

  const newTask: Task = {
    ...task,
    columnId: toColumnId
  };

  sameColumnTasks.splice(toIndex, 0, newTask);

  const reorderedColumnTasks = sameColumnTasks.map((t, index) => ({
    ...t,
    order: index
  }));

  const otherTasks = updatedTasks.filter(t => t.columnId !== toColumnId);

  return {
    ...state,
    tasks: [...otherTasks, ...reorderedColumnTasks]
  };
}
```

## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initialState, moveTask, BoardState } from "./store";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

let boardState: BoardState = initialState;

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks/move", (req, res) => {
  const { taskId, toColumnId, toIndex } = req.body as {
    taskId: string;
    toColumnId: string;
    toIndex: number;
  };

  boardState = moveTask(boardState, taskId, toColumnId, toIndex);

  io.emit("board:update", boardState);

  res.json({ ok: true, boardState });
});

io.on("connection", socket => {
  socket.emit("board:update", boardState);

  socket.on("task:move", (payload: { taskId: string; toColumnId: string; toIndex: number }) => {
    boardState = moveTask(boardState, payload.taskId, payload.toColumnId, payload.toIndex);
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
