  const [board, setBoard] = useState<BoardState | null>(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then(res => res.json())
      .then(setBoard);

    socket.on("connect", () => setConnected(true));
    socket.on("disconnect", () => setConnected(false));
    socket.on("board:update", (state: BoardState) => setBoard(state));

    return () => {
      socket.off("connect");
      socket.off("disconnect");
      socket.off("board:update");
    };
  }, []);

  if (!board) return <div className="app-loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <span className={connected ? "status online" : "status offline"}>
          {connected ? "Live collaboration enabled" : "Offline"}
        </span>
      </header>

      <Board board={board} />
    </div>
  );
}
```

## `client/src/components/Board.tsx`

```tsx
import { useMemo } from "react";
import { socket } from "../lib/socket";
import Column from "./Column";
import type { BoardState, Task } from "../App";

type Props = {
  board: BoardState;
};

export default function Board({ board }: Props) {
  const tasksByColumn = useMemo(() => {
    const grouped: Record<string, Task[]> = {};
    for (const col of board.columns) grouped[col.id] = [];
    for (const task of board.tasks) {
      if (!grouped[task.columnId]) grouped[task.columnId] = [];
      grouped[task.columnId].push(task);
    }
    for (const colId of Object.keys(grouped)) {
      grouped[colId].sort((a, b) => a.order - b.order);
    }
    return grouped;
  }, [board]);

  const handleDrop = (taskId: string, toColumnId: string, toIndex: number) => {
    socket.emit("task:move", { taskId, toColumnId, toIndex });
  };

  return (
    <div className="board">
      {board.columns.map(column => (
        <Column
          key={column.id}
          column={column}
          tasks={tasksByColumn[column.id] || []}
          onDropTask={handleDrop}
        />
      ))}
    </div>
  );
}
