import TaskCard from "./TaskCard";
import type { Column as ColumnType, Task } from "../App";

type Props = {
  column: ColumnType;
  tasks: Task[];
  onDropTask: (taskId: string, toColumnId: string, toIndex: number) => void;
};

export default function Column({ column, tasks, onDropTask }: Props) {
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    if (!taskId) return;
    onDropTask(taskId, column.id, tasks.length);
