  return (
    <div className="column" onDragOver={handleDragOver} onDrop={handleDrop}>
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{tasks.length}</span>
      </div>

      <div className="column-body">
        {tasks.map((task, index) => (
          <TaskCard
            key={task.id}
            task={task}
            index={index}
            columnId={column.id}
            onDropTask={onDropTask}
          />
        ))}
      </div>
    </div>
  );
