## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer } from "ws";
import { initialState, BoardState, Task } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/board/move", (req, res) => {
  const { taskId, fromColumn, toColumn, toIndex } = req.body as {
    taskId: string;
    fromColumn: string;
    toColumn: string;
    toIndex: number;
  };

  const fromTasks = boardState.columns[fromColumn] || [];
  const toTasks = boardState.columns[toColumn] || [];

  const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromTasks.splice(taskIndex, 1);
  task.status = toColumn;

  const insertIndex = Math.max(0, Math.min(toIndex, toTasks.length));
  toTasks.splice(insertIndex, 0, task);

  boardState.columns[fromColumn] = fromTasks;
  boardState.columns[toColumn] = toTasks;

  broadcastState();
  res.json({ ok: true, boardState });
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

function broadcastState() {
  const message = JSON.stringify({
    type: "board:update",
    payload: boardState
  });

  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "board:update",
      payload: boardState
    })
  );

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "task:move") {
        const { taskId, fromColumn, toColumn, toIndex } = msg.payload;
        const fromTasks = boardState.columns[fromColumn] || [];
        const toTasks = boardState.columns[toColumn] || [];

        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        task.status = toColumn;

        const insertIndex = Math.max(0, Math.min(toIndex, toTasks.length));
        toTasks.splice(insertIndex, 0, task);

        boardState.columns[fromColumn] = fromTasks;
        boardState.columns[toColumn] = toTasks;

        broadcastState();
      }
    } catch {
      // ignore malformed messages
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

