## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import type { BoardState, Task, WsMessage } from "./types";

const API_URL = "http://localhost:4000";
const WS_URL = "ws://localhost:4000";

const columnTitles: Record<string, string> = {
  todo: "To Do",
  inprogress: "In Progress",
  done: "Done"
};

export default function App() {
  const [board, setBoard] = useState<BoardState>({ columns: {} });
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [status, setStatus] = useState("Connecting...");
  const [socket, setSocket] = useState<WebSocket | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 6 }
    })
  );

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((r) => r.json())
      .then(setBoard)
      .catch(() => setStatus("Failed to load board"));
  }, []);

  useEffect(() => {
    const ws = new WebSocket(WS_URL);
    setSocket(ws);

    ws.onopen = () => setStatus("Connected");
    ws.onclose = () => setStatus("Disconnected");
    ws.onerror = () => setStatus("Connection error");

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data) as WsMessage;
      if (msg.type === "board:update") {
        setBoard(msg.payload);
      }
    };

    return () => ws.close();
  }, []);

  const columns = useMemo(() => Object.keys(board.columns || {}), [board]);

  function findTaskContainer(taskId: string): string | null {
    for (const columnId of Object.keys(board.columns)) {
      if (board.columns[columnId].some((t) => t.id === taskId)) return columnId;
    }
    return null;
  }

  function handleDragStart(event: DragStartEvent) {
    const taskId = String(event.active.id);
    const columnId = findTaskContainer(taskId);
    if (!columnId) return;
    const task = board.columns[columnId].find((t) => t.id === taskId) || null;
    setActiveTask(task);
  }

  function handleDragOver(_event: DragOverEvent) {}

  function handleDragEnd(event: DragEndEvent) {
    setActiveTask(null);

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const fromColumn = findTaskContainer(taskId);
    const toColumn = board.columns[overId] ? overId : findTaskContainer(overId);

    if (!fromColumn || !toColumn) return;

    const fromTasks = [...board.columns[fromColumn]];
    const toTasks = fromColumn === toColumn ? fromTasks : [...board.columns[toColumn]];

    const fromIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (fromIndex === -1) return;

    const task = fromTasks[fromIndex];
    const overIndex =
      board.columns[toColumn].findIndex((t) => t.id === overId) >= 0
        ? board.columns[toColumn].findIndex((t) => t.id === overId)
        : toTasks.length;

    if (fromColumn === toColumn) {
      const newItems = arrayMove(fromTasks, fromIndex, overIndex);
      setBoard({
        columns: {
          ...board.columns,
          [fromColumn]: newItems
        }
      });

      socket?.send(
        JSON.stringify({
          type: "task:move",
          payload: {
            taskId,
            fromColumn,
            toColumn,
            toIndex: overIndex
          }
        })
      );
      return;
    }

    fromTasks.splice(fromIndex, 1);
    task.status = toColumn;
    toTasks.splice(overIndex, 0, task);

    setBoard({
      columns: {
        ...board.columns,
        [fromColumn]: fromTasks,
        [toColumn]: toTasks
      }
    });

    socket?.send(
      JSON.stringify({
        type: "task:move",
        payload: {
          taskId,
          fromColumn,
          toColumn,
          toIndex: overIndex
        }
      })
    );
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <div className="status">{status}</div>
      </header>

      <main className="board">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          onDragStart={handleDragStart}
          onDragOver={handleDragOver}
          onDragEnd={handleDragEnd}
        >
          {columns.map((columnId) => (
            <Column key={columnId} id={columnId} title={columnTitles[columnId] || columnId} tasks={board.columns[columnId]} />
          ))}
        </DndContext>
      </main>

      {activeTask && (
        <div className="drag-overlay">
          <div className="task-card dragging">
            <strong>{activeTask.title}</strong>
          </div>
        </div>
      )}
    </div>
  );
}

function Column({ id, title, tasks }: { id: string; title: string; tasks: Task[] }) {
  return (
    <section className="column" data-column-id={id}>
      <h2>{title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" id={id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </section>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <article ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <strong>{task.title}</strong>
      {task.description && <p>{task.description}</p>}
    </article>
  );
}
