```ts
import { BoardState, Task, TaskStatus } from "./types";

const now = () => new Date().toISOString();

export const state: BoardState = {
  tasks: [
    {
      id: "1",
      title: "Set up project",
      description: "Initialize app structure and tooling",
      status: "todo",
      createdAt: now(),
      updatedAt: now(),
    },
    {
      id: "2",
      title: "Build drag and drop",
      description: "Implement kanban interactions",
      status: "in-progress",
      createdAt: now(),
      updatedAt: now(),
    },
    {
      id: "3",
      title: "Add realtime sync",
      description: "Broadcast board changes to all clients",
      status: "done",
      createdAt: now(),
      updatedAt: now(),
    },
  ],
};

export function addTask(task: Omit<Task, "id" | "createdAt" | "updatedAt">) {
  const newTask: Task = {
    ...task,
    id: crypto.randomUUID(),
    createdAt: now(),
    updatedAt: now(),
  };
  state.tasks.push(newTask);
  return newTask;
}

export function updateTask(
  id: string,
  patch: Partial<Omit<Task, "id" | "createdAt">>
) {
  const task = state.tasks.find((t) => t.id === id);
  if (!task) return null;

  Object.assign(task, patch, { updatedAt: now() });
  return task;
}

export function moveTask(id: string, status: TaskStatus) {
  return updateTask(id, { status });
}

export function deleteTask(id: string) {
  const idx = state.tasks.findIndex((t) => t.id === id);
  if (idx === -1) return false;
  state.tasks.splice(idx, 1);
  return true;
}
