## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { addTask, deleteTask, moveTask, state, updateTask } from "./store";
import { TaskStatus } from "./types";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
  },
});

app.get("/api/board", (_req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status, assignee } = req.body;

  if (!title || !status) {
    return res.status(400).json({ error: "title and status are required" });
  }

  const task = addTask({
    title,
    description,
    status,
    assignee,
  });

  io.emit("task:created", task);
  io.emit("board:updated", state);

  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const task = updateTask(req.params.id, req.body);
  if (!task) return res.status(404).json({ error: "Task not found" });

  io.emit("task:updated", task);
  io.emit("board:updated", state);

  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const ok = deleteTask(req.params.id);
  if (!ok) return res.status(404).json({ error: "Task not found" });

  io.emit("task:deleted", { id: req.params.id });
  io.emit("board:updated", state);

  res.status(204).send();
});

io.on("connection", (socket) => {
  console.log("client connected", socket.id);

  socket.emit("board:state", state);

  socket.on("task:move", ({ id, status }: { id: string; status: TaskStatus }) => {
    const task = moveTask(id, status);
    if (task) {
      io.emit("task:updated", task);
      io.emit("board:updated", state);
    }
  });

  socket.on("task:create", (payload) => {
    const task = addTask(payload);
    io.emit("task:created", task);
    io.emit("board:updated", state);
  });

  socket.on("task:update", ({ id, patch }) => {
    const task = updateTask(id, patch);
    if (task) {
      io.emit("task:updated", task);
      io.emit("board:updated", state);
    }
  });

  socket.on("task:delete", (id: string) => {
    const ok = deleteTask(id);
    if (ok) {
      io.emit("task:deleted", { id });
      io.emit("board:updated", state);
    }
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

