## `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { Task, TaskStatus } from "../types";
import { Column } from "./Column";

const statuses: { id: TaskStatus; title: string }[] = [
  { id: "todo", title: "Todo" },
  { id: "in-progress", title: "In Progress" },
  { id: "done", title: "Done" },
];

export function Board({
  tasks,
  onMoveTask,
  onEditTask,
}: {
  tasks: Task[];
  onMoveTask: (id: string, status: TaskStatus) => void;
  onEditTask: (task: Task) => void;
}) {
  const sensors = useSensors(useSensor(PointerSensor));

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const newStatus = over.id as TaskStatus;

    if (["todo", "in-progress", "done"].includes(newStatus)) {
      onMoveTask(taskId, newStatus);
    }
  }

  return (
    <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
        {statuses.map((col) => (
          <Column
            key={col.id}
            status={col.id}
            title={col.title}
            tasks={tasks.filter((t) => t.status === col.id)}
            onEditTask={onEditTask}
          />
        ))}
      </div>
    </DndContext>
  );
}
```

## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { BoardState, Task, TaskStatus } from "./types";
import { fetchBoard, createTask, updateTask } from "./api";
import { Board } from "./components/Board";
import { TaskModal } from "./components/TaskModal";

const SOCKET_URL = import.meta.env.VITE_API_URL || "http://localhost:4000";

export default function App() {
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [creating, setCreating] = useState(false);

  const socket = useMemo(() => io(SOCKET_URL), []);

  useEffect(() => {
    fetchBoard().then(setBoard).catch(console.error);

    socket.on("board:state", setBoard);
    socket.on("board:updated", setBoard);

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  const handleMoveTask = (id: string, status: TaskStatus) => {
    socket.emit("task:move", { id, status });
  };

  const handleSaveTask = async (payload: {
    title: string;
    description?: string;
    status: TaskStatus;
    assignee?: string;
  }) => {
    if (editingTask) {
      await updateTask(editingTask.id, payload);
      setEditingTask(null);
    } else {
      await createTask(payload);
      setCreating(false);
    }
  };

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif" }}>
      <header style={{ display: "flex", justifyContent: "space-between", marginBottom: 24 }}>
        <h1>Project Manager</h1>
        <button onClick={() => setCreating(true)}>New Task</button>
      </header>

      <Board
        tasks={board.tasks}
        onMoveTask={handleMoveTask}
        onEditTask={setEditingTask}
      />

      <TaskModal
        open={creating || !!editingTask}
        task={editingTask}
        onClose={() => {
          setCreating(false);
          setEditingTask(null);
        }}
        onSave={handleSaveTask}
      />
    </div>
  );
}
```

