  | { type: "task:create"; payload: Omit<Task, "id" | "updatedAt"> }
  | { type: "task:update"; payload: Task }
  | { type: "task:delete"; payload: { id: string } }
  | { type: "board:sync-request" };

export type ServerMessage =
  | { type: "board:state"; payload: BoardState }
  | { type: "task:created"; payload: Task }
  | { type: "task:updated"; payload: Task }
