```ts
import { BoardState, Task } from "./types.js";

const initialTasks: Task[] = [
  {
    id: "1",
    title: "Set up project",
    description: "Initialize repo and tooling",
    status: "todo",
    updatedAt: Date.now()
  },
  {
    id: "2",
    title: "Build task board",
    description: "Create Kanban columns",
    status: "in-progress",
    updatedAt: Date.now()
  },
  {
    id: "3",
    title: "Add collaboration",
    description: "Sync updates over WebSocket",
    status: "done",
    updatedAt: Date.now()
  }
];

let state: BoardState = {
  tasks: initialTasks
};

export function getBoardState(): BoardState {
  return state;
}

export function createTask(task: Omit<Task, "id" | "updatedAt">): Task {
  const newTask: Task = {
    ...task,
    id: crypto.randomUUID(),
    updatedAt: Date.now()
  };
  state = { tasks: [...state.tasks, newTask] };
  return newTask;
}

export function updateTask(updated: Task): Task {
  state = {
    tasks: state.tasks.map((t) => (t.id === updated.id ? { ...updated, updatedAt: Date.now() } : t))
  };
  return updated;
}

export function deleteTask(id: string): void {
  state = { tasks: state.tasks.filter((t) => t.id !== id) };
}
