## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer } from "ws";
import { createTask, deleteTask, getBoardState, updateTask } from "./boardStore.js";
import { ClientMessage, ServerMessage } from "./types.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/board", (_req, res) => {
  res.json(getBoardState());
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

function broadcast(message: ServerMessage) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === 1) client.send(data);
  }
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board:state", payload: getBoardState() } satisfies ServerMessage));
  broadcast({ type: "presence", payload: { clients: wss.clients.size } });

  ws.on("message", (raw) => {
    try {
      const message = JSON.parse(raw.toString()) as ClientMessage;

      switch (message.type) {
        case "board:sync-request":
          ws.send(JSON.stringify({ type: "board:state", payload: getBoardState() } satisfies ServerMessage));
          break;

        case "task:create": {
          const task = createTask(message.payload);
          broadcast({ type: "task:created", payload: task });
          break;
        }

        case "task:update": {
          const task = updateTask(message.payload);
          broadcast({ type: "task:updated", payload: task });
          break;
        }

        case "task:delete": {
          deleteTask(message.payload.id);
          broadcast({ type: "task:deleted", payload: { id: message.payload.id } });
          break;
        }
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });

  ws.on("close", () => {
    broadcast({ type: "presence", payload: { clients: wss.clients.size } });
  });
});

const PORT = process.env.PORT ? Number(process.env.PORT) : 3001;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

