export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assignee?: string;
  updatedAt: number;
}

export interface BoardState {
  tasks: Task[];
}

export type ClientMessage =
  | { type: "task:create"; payload: Omit<Task, "id" | "updatedAt"> }
  | { type: "task:update"; payload: Task }
  | { type: "task:delete"; payload: { id: string } }
  | { type: "board:sync-request" };

export type ServerMessage =
  | { type: "board:state"; payload: BoardState }
  | { type: "task:created"; payload: Task }
  | { type: "task:updated"; payload: Task }
  | { type: "task:deleted"; payload: { id: string } }
  | { type: "presence"; payload: { clients: number } };
