```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { Task, TaskStatus, ClientMessage, ServerMessage } from "./types";

const WS_URL = "ws://localhost:3001";

const columns: { id: TaskStatus; title: string }[] = [
  { id: "todo", title: "To Do" },
  { id: "in-progress", title: "In Progress" },
  { id: "done", title: "Done" }
];

function TaskCard({
  task,
  onDelete
}: {
  task: Task;
  onDelete?: (id: string) => void;
}) {
  return (
    <div className="task-card">
      <div className="task-card__header">
        <strong>{task.title}</strong>
        {onDelete && (
          <button className="icon-button" onClick={() => onDelete(task.id)}>
            ×
          </button>
        )}
      </div>
      {task.description && <p>{task.description}</p>}
      <small>Updated: {new Date(task.updatedAt).toLocaleTimeString()}</small>
    </div>
  );
}

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [presence, setPresence] = useState(1);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [socket, setSocket] = useState<WebSocket | null>(null);

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    const ws = new WebSocket(WS_URL);
    setSocket(ws);

    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "board:sync-request" } satisfies ClientMessage));
    };

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data) as ServerMessage;

      switch (msg.type) {
        case "board:state":
          setTasks(msg.payload.tasks);
          break;
        case "task:created":
          setTasks((prev) => [...prev.filter((t) => t.id !== msg.payload.id), msg.payload]);
          break;
        case "task:updated":
          setTasks((prev) => prev.map((t) => (t.id === msg.payload.id ? msg.payload : t)));
          break;
        case "task:deleted":
          setTasks((prev) => prev.filter((t) => t.id !== msg.payload.id));
          break;
        case "presence":
          setPresence(msg.payload.clients);
          break;
      }
    };

    return () => ws.close();
  }, []);

  const grouped = useMemo(() => {
    return columns.reduce<Record<TaskStatus, Task[]>>(
      (acc, col) => {
        acc[col.id] = tasks.filter((t) => t.status === col.id);
        return acc;
      },
      { todo: [], "in-progress": [], done: [] }
    );
  }, [tasks]);

  function send(message: ClientMessage) {
    if (socket?.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify(message));
    }
  }

  function handleCreateTask() {
    const title = prompt("Task title?");
    if (!title) return;

    send({
      type: "task:create",
      payload: {
        title,
        description: "",
        status: "todo",
        assignee: "",
        updatedAt: Date.now()
      }
    } as ClientMessage);
  }

  function handleDeleteTask(id: string) {
    send({ type: "task:delete", payload: { id } });
  }

  function onDragStart(event: any) {
    const task = tasks.find((t) => t.id === event.active.id);
    setActiveTask(task ?? null);
  }

  function onDragEnd(event: DragEndEvent) {
    setActiveTask(null);

    const taskId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId) return;

    const task = tasks.find((t) => t.id === taskId);
    if (!task) return;

    const targetStatus = columns.find((c) => c.id === overId)?.id;
    if (!targetStatus || task.status === targetStatus) return;

    send({
      type: "task:update",
      payload: { ...task, status: targetStatus, updatedAt: Date.now() }
    });
  }

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>Project Manager</h1>
          <p>{presence} collaborator(s) online</p>
        </div>
        <button onClick={handleCreateTask}>+ New Task</button>
      </header>

      <DndContext sensors={sensors} onDragStart={onDragStart} onDragEnd={onDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <div className="column" key={column.id} id={column.id}>
              <div className="column__header">
                <h2>{column.title}</h2>
                <span>{grouped[column.id].length}</span>
              </div>

              <div className="column__body" id={column.id}>
                {grouped[column.id].map((task) => (
                  <div key={task.id} data-task-id={task.id} className="draggable-wrapper">
                    <TaskCard task={task} onDelete={handleDeleteTask} />
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

