import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { api } from "./api";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [draggingTaskId, setDraggingTaskId] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    api.get("/api/board").then((res) => setBoard(res.data));

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => board?.columns || [], [board]);
  const tasks = useMemo(() => board?.tasks || {}, [board]);

  const handleDragStart = (taskId) => {
    setDraggingTaskId(taskId);
  };

  const handleDrop = async (destinationColumnId, destinationIndex) => {
    if (!draggingTaskId || !board) return;

    const sourceColumn = board.columns.find((col) =>
      col.taskIds.includes(draggingTaskId)
    );

    if (!sourceColumn) return;

    await api.post("/api/board/move", {
      taskId: draggingTaskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId,
      destinationIndex
    });

    setDraggingTaskId(null);
  };

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    await api.post("/api/tasks", {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: "todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  if (!board) return <div className="app loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
        <form className="new-task-form" onSubmit={handleAddTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            tasks={tasks}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
          />
        ))}
      </main>
    </div>
  );
}

function Column({ column, tasks, onDragStart, onDrop }) {
  return (
    <section className="column">
      <h2>{column.title}</h2>

      <div
        className="task-list"
        onDragOver={(e) => e.preventDefault()}
        onDrop={() => onDrop(column.id, column.taskIds.length)}
      >
        {column.taskIds.map((taskId, index) => (
          <div
            key={taskId}
            className="drop-zone-wrapper"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => onDrop(column.id, index)}
          >
            <TaskCard task={tasks[taskId]} onDragStart={onDragStart} />
          </div>
        ))}
      </div>
    </section>
  );
}

function TaskCard({ task, onDragStart }) {
  if (!task) return null;

  return (
    <article
      className="task-card"
      draggable
      onDragStart={() => onDragStart(task.id)}
    >
      <h3>{task.title}</h3>
      <p>{task.description}</p>
    </article>
  );
}
```

