## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { boardState, Task } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status } = req.body as Partial<Task>;

  if (!title || !status) {
    return res.status(400).json({ error: "title and status are required" });
  }

  const task: Task = {
    id: `task-${Date.now()}`,
    title,
    description,
    status,
    updatedAt: Date.now()
  };

  boardState.tasks.push(task);
  io.emit("board:update", boardState);

  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks.find((t) => t.id === id);

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, status } = req.body as Partial<Task>;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (status !== undefined) task.status = status;

  task.updatedAt = Date.now();
  io.emit("board:update", boardState);

  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const before = boardState.tasks.length;
  boardState.tasks = boardState.tasks.filter((t) => t.id !== id);

  if (boardState.tasks.length === before) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("board:update", boardState);
  res.status(204).send();
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:move", (payload: { id: string; status: Task["status"] }) => {
    const task = boardState.tasks.find((t) => t.id === payload.id);
    if (!task) return;

    task.status = payload.status;
    task.updatedAt = Date.now();

    io.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { title: string; description?: string; status: Task["status"] }) => {
    const task: Task = {
      id: `task-${Date.now()}`,
      title: payload.title,
      description: payload.description,
      status: payload.status,
      updatedAt: Date.now()
    };

    boardState.tasks.push(task);
    io.emit("board:update", boardState);
  });

  socket.on("task:update", (payload: Partial<Task> & { id: string }) => {
    const task = boardState.tasks.find((t) => t.id === payload.id);
    if (!task) return;

    if (payload.title !== undefined) task.title = payload.title;
    if (payload.description !== undefined) task.description = payload.description;
    if (payload.status !== undefined) task.status = payload.status;
    task.updatedAt = Date.now();

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (payload: { id: string }) => {
    boardState.tasks = boardState.tasks.filter((t) => t.id !== payload.id);
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

