## `client/src/components/Board.tsx`

```tsx
import { DndContext, DragEndEvent, closestCenter } from "@dnd-kit/core";
import { Column } from "./Column";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: "todo" | "inprogress" | "done";
};

type Props = {
  tasks: Task[];
  onMoveTask: (id: string, status: Task["status"]) => void;
};

const columns: { title: string; status: Task["status"] }[] = [
  { title: "To Do", status: "todo" },
  { title: "In Progress", status: "inprogress" },
  { title: "Done", status: "done" }
];

export function Board({ tasks, onMoveTask }: Props) {
  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const targetStatus = over.data.current?.status as Task["status"] | undefined;
    if (!targetStatus) return;

    onMoveTask(String(active.id), targetStatus);
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start", overflowX: "auto" }}>
        {columns.map((col) => (
          <div
            key={col.status}
            data-status={col.status}
            style={{ flex: 1, minWidth: 280 }}
          >
            <Column
              title={col.title}
              status={col.status}
              tasks={tasks.filter((t) => t.status === col.status)}
            />
          </div>
        ))}
      </div>
    </DndContext>
  );
}
```

## `client/src/App.tsx`

```tsx
import { useEffect, useState } from "react";
import { Board } from "./components/Board";
import { socket } from "./lib/socket";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: "todo" | "inprogress" | "done";
  updatedAt: number;
};

type BoardState = {
  tasks: Task[];
};

export default function App() {
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("connect", () => setConnected(true));
    socket.on("disconnect", () => setConnected(false));
    socket.on("board:update", (state: BoardState) => setBoard(state));

    return () => {
      socket.off("connect");
      socket.off("disconnect");
      socket.off("board:update");
    };
  }, []);

  const moveTask = (id: string, status: Task["status"]) => {
    socket.emit("task:move", { id, status });
  };

  const createTask = () => {
    socket.emit("task:create", {
      title: `New Task ${Date.now()}`,
      description: "Created from client",
      status: "todo"
    });
  };

  return (
    <div style={{ padding: 24, fontFamily: "Inter, system-ui, sans-serif", background: "#eef1f7", minHeight: "100vh" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0 }}>Project Board</h1>
          <p style={{ margin: "6px 0 0", color: "#666" }}>
            {connected ? "Connected" : "Disconnected"} — real-time collaboration enabled
          </p>
        </div>
        <button
          onClick={createTask}
          style={{
            background: "#111827",
            color: "white",
            border: "none",
            borderRadius: 10,
            padding: "10px 14px",
            cursor: "pointer"
          }}
        >
          Add Task
        </button>
      </header>

      <Board tasks={board.tasks} onMoveTask={moveTask} />
    </div>
  );
}
```

