### `server/index.js`
```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory state for initial implementation
let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Set up project", description: "Initialize repository and tooling" },
        { id: "t2", title: "Design UI", description: "Create initial wireframes" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build drag and drop", description: "Enable task movement between columns" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, title, description } = req.body;
  if (!boardId || !title) {
    return res.status(400).json({ error: "boardId and title are required" });
  }

  const task = {
    id: `task_${Date.now()}`,
    title,
    description: description || ""
  };

  const board = state.boards.find(b => b.id === boardId);
  if (!board) {
    return res.status(404).json({ error: "Board not found" });
  }

  board.tasks.push(task);
  io.emit("state:update", state);

  res.status(201).json(task);
});

app.post("/api/move-task", (req, res) => {
  const { taskId, fromBoardId, toBoardId, toIndex } = req.body;

  const fromBoard = state.boards.find(b => b.id === fromBoardId);
  const toBoard = state.boards.find(b => b.id === toBoardId);

  if (!fromBoard || !toBoard) {
    return res.status(404).json({ error: "Board not found" });
  }

  const taskIndex = fromBoard.tasks.findIndex(t => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromBoard.tasks.splice(taskIndex, 1);

  const insertIndex =
    typeof toIndex === "number" && toIndex >= 0 && toIndex <= toBoard.tasks.length
      ? toIndex
      : toBoard.tasks.length;

  toBoard.tasks.splice(insertIndex, 0, task);

  io.emit("state:update", state);

  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:update", state);

  socket.on("task:create", ({ boardId, title, description }) => {
    const board = state.boards.find(b => b.id === boardId);
    if (!board || !title) return;

    const task = {
      id: `task_${Date.now()}`,
      title,
      description: description || ""
    };

    board.tasks.push(task);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromBoardId, toBoardId, toIndex }) => {
    const fromBoard = state.boards.find(b => b.id === fromBoardId);
    const toBoard = state.boards.find(b => b.id === toBoardId);

    if (!fromBoard || !toBoard) return;

    const taskIndex = fromBoard.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromBoard.tasks.splice(taskIndex, 1);

    const insertIndex =
      typeof toIndex === "number" && toIndex >= 0 && toIndex <= toBoard.tasks.length
        ? toIndex
        : toBoard.tasks.length;

    toBoard.tasks.splice(insertIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
