### `client/app.js`
```js
const API_URL = "http://localhost:3001";
const socket = io(API_URL);

const boardsEl = document.getElementById("boards");
const boardSelectEl = document.getElementById("boardSelect");
const taskFormEl = document.getElementById("taskForm");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const connectionStatusEl = document.getElementById("connectionStatus");

let appState = null;
let draggedTask = null;

socket.on("connect", () => {
  connectionStatusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  connectionStatusEl.textContent = "Disconnected";
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

taskFormEl.addEventListener("submit", (e) => {
  e.preventDefault();

  const boardId = boardSelectEl.value;
  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();

  if (!boardId || !title) return;

  socket.emit("task:create", { boardId, title, description });

  taskTitleEl.value = "";
  taskDescriptionEl.value = "";
});

function render() {
  if (!appState) return;

  // Populate select
  boardSelectEl.innerHTML = appState.boards
    .map(board => `<option value="${board.id}">${board.title}</option>`)
    .join("");

  // Render boards
  boardsEl.innerHTML = appState.boards.map(board => `
    <div class="board" data-board-id="${board.id}">
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}">
        ${board.tasks.map(task => renderTask(task, board.id)).join("")}
      </div>
    </div>
  `).join("");

  attachDragEvents();
  attachDropEvents();
}

function renderTask(task, boardId) {
  return `
    <div class="task" draggable="true" data-task-id="${task.id}" data-board-id="${boardId}">
      <h3>${escapeHtml(task.title)}</h3>
      <p>${escapeHtml(task.description || "")}</p>
    </div>
  `;
}

function attachDragEvents() {
  document.querySelectorAll(".task").forEach(taskEl => {
    taskEl.addEventListener("dragstart", () => {
      draggedTask = {
        taskId: taskEl.dataset.taskId,
        fromBoardId: taskEl.dataset.boardId
      };
      setTimeout(() => taskEl.style.opacity = "0.5", 0);
    });

    taskEl.addEventListener("dragend", () => {
      taskEl.style.opacity = "1";
      draggedTask = null;
    });
  });
}

function attachDropEvents() {
  document.querySelectorAll(".task-list").forEach(listEl => {
    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drag-over");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drag-over");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const toBoardId = listEl.dataset.boardId;
      const tasksInTarget = [...listEl.querySelectorAll(".task")];
      const toIndex = tasksInTarget.length;

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromBoardId: draggedTask.fromBoardId,
        toBoardId,
        toIndex
      });
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

