### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initialState, type BoardState } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body as BoardState;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("board:update", (nextState: BoardState) => {
    boardState = nextState;
    socket.broadcast.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { columnId: string; title: string }) => {
    const id = `task-${crypto.randomUUID()}`;
    boardState.tasks[id] = { id, title: payload.title };
    boardState.columns[payload.columnId]?.taskIds.push(id);
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

