```tsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners,
  DragOverlay
} from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy, arrayMove } from "@dnd-kit/sortable";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

const socket = io("http://localhost:4000");

function findColumnId(state: BoardState, taskId: string) {
  return Object.values(state.columns).find((col) => col.taskIds.includes(taskId))?.id;
}

export default function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    socket.on("board:update", (nextBoard: BoardState) => setBoard(nextBoard));
    return () => {
      socket.off("board:update");
    };
  }, []);

  const activeTask = useMemo(() => {
    if (!board || !activeTaskId) return null;
    return board.tasks[activeTaskId];
  }, [board, activeTaskId]);

  function handleDragEnd(event: DragEndEvent) {
    if (!board) return;

    const { active, over } = event;
    setActiveTaskId(null);

    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);

    const sourceColumnId = findColumnId(board, activeId);
    const targetColumnId =
      board.columns[overId] ? overId : findColumnId(board, overId);

    if (!sourceColumnId || !targetColumnId) return;

    const next = structuredClone(board);

    if (sourceColumnId === targetColumnId) {
      const column = next.columns[sourceColumnId];
      const oldIndex = column.taskIds.indexOf(activeId);
      const newIndex = column.taskIds.indexOf(overId);

      if (oldIndex !== -1 && newIndex !== -1 && oldIndex !== newIndex) {
        column.taskIds = arrayMove(column.taskIds, oldIndex, newIndex);
      }
    } else {
      const source = next.columns[sourceColumnId];
      const target = next.columns[targetColumnId];

      source.taskIds = source.taskIds.filter((id) => id !== activeId);
      const insertIndex = target.taskIds.indexOf(overId);
      if (insertIndex >= 0) {
        target.taskIds.splice(insertIndex, 0, activeId);
      } else {
        target.taskIds.push(activeId);
      }
    }

    setBoard(next);
    socket.emit("board:update", next);
  }

  function createTask(columnId: string) {
    const title = prompt("Task title?");
    if (!title) return;
    socket.emit("task:create", { columnId, title });
  }

  if (!board) return <div className="app-shell">Loading board…</div>;

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={({ active }) => setActiveTaskId(String(active.id))}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columnOrder.map((columnId) => {
            const column = board.columns[columnId];
            return (
              <section className="column" key={column.id}>
                <div className="column-header">
                  <h2>{column.title}</h2>
                  <button onClick={() => createTask(column.id)}>+ Add</button>
                </div>

                <SortableContext
                  items={column.taskIds}
                  strategy={verticalListSortingStrategy}
                >
                  <div className="task-list" id={column.id}>
                    {column.taskIds.map((taskId) => {
                      const task = board.tasks[taskId];
                      return <TaskCard key={task.id} task={task} />;
                    })}
                  </div>
                </SortableContext>
              </section>
            );
          })}
        </div>

        <DragOverlay>
          {activeTask ? <div className="task-card dragging">{activeTask.title}</div> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useDroppable } from "@dnd-kit/core";

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`task-card ${isDragging ? "dragging" : ""}`}
      {...attributes}
      {...listeners}
    >
      {task.title}
    </div>
  );
}
```

