### `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory store for initial implementation
let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "t1", title: "Set up project", description: "Initialize app structure" },
      { id: "t2", title: "Design UI", description: "Create basic board layout" }
    ]
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [
      { id: "t3", title: "Implement drag and drop", description: "Enable moving tasks" }
    ]
  },
  {
    id: "done",
    title: "Done",
    tasks: []
  }
];

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, title, description } = req.body;

  const newTask = {
    id: `task-${Date.now()}`,
    title,
    description: description || ""
  };

  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  board.tasks.push(newTask);
  io.emit("boards:update", boards);
  res.status(201).json(newTask);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  for (const board of boards) {
    const task = board.tasks.find((t) => t.id === taskId);
    if (task) {
      task.title = title ?? task.title;
      task.description = description ?? task.description;
      io.emit("boards:update", boards);
      return res.json(task);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const board of boards) {
    const index = board.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      const [removed] = board.tasks.splice(index, 1);
      io.emit("boards:update", boards);
      return res.json(removed);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("boards:moveTask", ({ taskId, sourceBoardId, destinationBoardId, destinationIndex }) => {
    const sourceBoard = boards.find((b) => b.id === sourceBoardId);
    const destinationBoard = boards.find((b) => b.id === destinationBoardId);

    if (!sourceBoard || !destinationBoard) return;

    const taskIndex = sourceBoard.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceBoard.tasks.splice(taskIndex, 1);
    destinationBoard.tasks.splice(destinationIndex, 0, task);

    io.emit("boards:update", boards);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

