import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:3001");

export default function App() {
  const [boards, setBoards] = useState([]);
  const [newTask, setNewTask] = useState({ boardId: "todo", title: "", description: "" });
  const [draggedTask, setDraggedTask] = useState(null);

  useEffect(() => {
    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
    });

    return () => {
      socket.off("boards:update");
    };
  }, []);

  const boardMap = useMemo(() => {
    return Object.fromEntries(boards.map((b) => [b.id, b]));
  }, [boards]);

  const handleCreateTask = async (e) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    await fetch("http://localhost:3001/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newTask)
    });

    setNewTask({ boardId: "todo", title: "", description: "" });
  };

  const handleDragStart = (task, sourceBoardId) => {
    setDraggedTask({ ...task, sourceBoardId });
  };

  const handleDrop = (destinationBoardId, destinationIndex) => {
    if (!draggedTask) return;

    socket.emit("boards:moveTask", {
      taskId: draggedTask.id,
      sourceBoardId: draggedTask.sourceBoardId,
      destinationBoardId,
      destinationIndex
    });

    setDraggedTask(null);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <form className="task-form" onSubmit={handleCreateTask}>
        <select
          value={newTask.boardId}
          onChange={(e) => setNewTask((t) => ({ ...t, boardId: e.target.value }))}
        >
          <option value="todo">To Do</option>
          <option value="doing">In Progress</option>
          <option value="done">Done</option>
        </select>

        <input
          type="text"
          placeholder="Task title"
          value={newTask.title}
          onChange={(e) => setNewTask((t) => ({ ...t, title: e.target.value }))}
        />

        <input
          type="text"
          placeholder="Description"
          value={newTask.description}
          onChange={(e) => setNewTask((t) => ({ ...t, description: e.target.value }))}
        />

        <button type="submit">Add Task</button>
      </form>

      <div className="board-grid">
        {boards.map((board) => (
          <div
            key={board.id}
            className="board"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(board.id, board.tasks.length)}
          >
            <h2>{board.title}</h2>

            <div className="task-list">
              {board.tasks.map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task, board.id)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.preventDefault();
                    handleDrop(board.id, index);
                  }}
                >
                  <strong>{task.title}</strong>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
```

