## 3) Backend: `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "t1", title: "Design app layout", description: "Create initial wireframe", status: "todo" },
      { id: "t2", title: "Set up backend", description: "Initialize Express and Socket.IO", status: "todo" }
    ]
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [
      { id: "t3", title: "Build drag-and-drop", description: "Implement task movement", status: "doing" }
    ]
  },
  {
    id: "done",
    title: "Done",
    tasks: [
      { id: "t4", title: "Project scaffold", description: "Create initial folder structure", status: "done" }
    ]
  }
];

function broadcastState() {
  io.emit("boards:update", boards);
}

io.on("connection", (socket) => {
  socket.emit("boards:update", boards);

  socket.on("task:create", (task) => {
    const board = boards.find((b) => b.id === task.status);
    if (!board) return;

    const newTask = {
      id: `task-${Date.now()}`,
      title: task.title || "Untitled Task",
      description: task.description || "",
      status: task.status
    };

    board.tasks.push(newTask);
    broadcastState();
  });

  socket.on("task:update", (updatedTask) => {
    for (const board of boards) {
      const idx = board.tasks.findIndex((t) => t.id === updatedTask.id);
      if (idx !== -1) {
        board.tasks[idx] = { ...board.tasks[idx], ...updatedTask };
        break;
      }
    }
    broadcastState();
  });

  socket.on("task:move", ({ taskId, fromBoardId, toBoardId, toIndex }) => {
    const fromBoard = boards.find((b) => b.id === fromBoardId);
    const toBoard = boards.find((b) => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    const taskIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromBoard.tasks.splice(taskIndex, 1);
    task.status = toBoardId;

    const insertIndex = typeof toIndex === "number" ? toIndex : toBoard.tasks.length;
    toBoard.tasks.splice(insertIndex, 0, task);

    broadcastState();
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const board of boards) {
      const idx = board.tasks.findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        board.tasks.splice(idx, 1);
        break;
      }
    }
    broadcastState();
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

