## 6) Frontend logic: `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const cancelBtn = document.getElementById("cancelBtn");
const dialogTitle = document.getElementById("dialogTitle");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskStatusSelect = document.getElementById("taskStatus");

let currentBoards = [];
let editingTaskId = null;

socket.on("boards:update", (boards) => {
  currentBoards = boards;
  renderBoards();
});

function renderBoards() {
  boardsEl.innerHTML = "";

  currentBoards.forEach((board) => {
    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const taskListEl = boardEl.querySelector(".task-list");

    board.tasks.forEach((task) => {
      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.boardId = board.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", onDragStart);
      taskEl.querySelector(".edit-btn").addEventListener("click", () => openEditDialog(task));
      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskListEl.appendChild(taskEl);
    });

    taskListEl.addEventListener("dragover", onDragOver);
    taskListEl.addEventListener("drop", onDrop);

    boardsEl.appendChild(boardEl);
  });
}

let draggedTaskId = null;
let draggedFromBoardId = null;

function onDragStart(e) {
  draggedTaskId = e.currentTarget.dataset.taskId;
  draggedFromBoardId = e.currentTarget.dataset.boardId;
  e.dataTransfer.effectAllowed = "move";
}

function onDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = "move";
}

function onDrop(e) {
  e.preventDefault();
  const toBoardId = e.currentTarget.dataset.boardId;

  socket.emit("task:move", {
    taskId: draggedTaskId,
    fromBoardId: draggedFromBoardId,
    toBoardId,
    toIndex: currentBoards.find((b) => b.id === toBoardId)?.tasks.length ?? 0
  });

  draggedTaskId = null;
  draggedFromBoardId = null;
}

addTaskBtn.addEventListener("click", () => {
  editingTaskId = null;
  dialogTitle.textContent = "Add Task";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskStatusSelect.value = "todo";
  taskDialog.showModal();
});

cancelBtn.addEventListener("click", () => taskDialog.close());

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const payload = {
    title: taskTitleInput.value.trim(),
    description: taskDescriptionInput.value.trim(),
    status: taskStatusSelect.value
  };

  if (editingTaskId) {
    socket.emit("task:update", { id: editingTaskId, ...payload });
  } else {
    socket.emit("task:create", payload);
  }

  taskDialog.close();
});

function openEditDialog(task) {
  editingTaskId = task.id;
  dialogTitle.textContent = "Edit Task";
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskStatusSelect.value = task.status;
  taskDialog.showModal();
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
```

