### `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

// In-memory state for initial implementation
const state = {
  boards: [
    {
      id: "board-1",
      title: "Main Board",
      columns: [
        {
          id: "todo",
          title: "To Do",
          tasks: [
            { id: "task-1", title: "Design app layout", description: "Create initial UI wireframe" },
            { id: "task-2", title: "Set up backend", description: "Initialize Express and Socket.IO" }
          ]
        },
        {
          id: "doing",
          title: "In Progress",
          tasks: [
            { id: "task-3", title: "Build drag-and-drop", description: "Implement task movement" }
          ]
        },
        {
          id: "done",
          title: "Done",
          tasks: []
        }
      ]
    }
  ]
};

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

function findBoard(boardId) {
  return state.boards.find((b) => b.id === boardId);
}

function findTask(board, taskId) {
  for (const column of board.columns) {
    const taskIndex = column.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      return { column, taskIndex };
    }
  }
  return null;
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, columnId, title, description } = req.body;
  const board = findBoard(boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  const task = {
    id: `task-${Date.now()}`,
    title,
    description: description || ""
  };

  column.tasks.push(task);
  io.emit("state:update", state);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { boardId, title, description } = req.body;

  const board = findBoard(boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const result = findTask(board, taskId);
  if (!result) return res.status(404).json({ error: "Task not found" });

  const { column, taskIndex } = result;
  const task = column.tasks[taskIndex];

  task.title = title ?? task.title;
  task.description = description ?? task.description;

  io.emit("state:update", state);
  res.json(task);
});

app.post("/api/tasks/move", (req, res) => {
  const { boardId, taskId, fromColumnId, toColumnId, toIndex } = req.body;

  const board = findBoard(boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const fromColumn = board.columns.find((c) => c.id === fromColumnId);
  const toColumn = board.columns.find((c) => c.id === toColumnId);

  if (!fromColumn || !toColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = fromColumn.tasks.splice(taskIndex, 1);
  const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
  toColumn.tasks.splice(insertIndex, 0, task);

  io.emit("state:update", state);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  socket.emit("state:update", state);

  socket.on("task:create", ({ boardId, columnId, title, description }) => {
    const board = findBoard(boardId);
    if (!board) return;

    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    const task = {
      id: `task-${Date.now()}`,
      title,
      description: description || ""
    };

    column.tasks.push(task);
    io.emit("state:update", state);
  });

  socket.on("task:move", (payload) => {
    const { boardId, taskId, fromColumnId, toColumnId, toIndex } = payload;

    const board = findBoard(boardId);
    if (!board) return;

    const fromColumn = board.columns.find((c) => c.id === fromColumnId);
    const toColumn = board.columns.find((c) => c.id === toColumnId);
    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);
    const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
    toColumn.tasks.splice(insertIndex, 0, task);

    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
