### `client/app.js`

```js
const socket = io("http://localhost:3001");

const boardEl = document.getElementById("board");
const boardTitleEl = document.getElementById("boardTitle");
const connectionStatusEl = document.getElementById("connectionStatus");

const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");

let appState = null;
let activeBoardId = null;
let dragData = null;

socket.on("connect", () => {
  connectionStatusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  connectionStatusEl.textContent = "Disconnected";
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

function render() {
  if (!appState || !appState.boards.length) return;

  const board = appState.boards[0];
  activeBoardId = board.id;
  boardTitleEl.textContent = board.title;

  boardEl.innerHTML = board.columns
    .map(
      (column) => `
      <div class="column" data-column-id="${column.id}">
        <h3>${column.title}</h3>
        <div class="task-list" data-column-id="${column.id}">
          ${column.tasks
            .map(
              (task) => `
                <div class="task" draggable="true" data-task-id="${task.id}" data-column-id="${column.id}">
                  <h4>${task.title}</h4>
                  <p>${task.description || ""}</p>
                </div>
              `
            )
            .join("")}
        </div>
      </div>
    `
    )
    .join("");

  attachDnDHandlers();
}

function attachDnDHandlers() {
  document.querySelectorAll(".task").forEach((taskEl) => {
    taskEl.addEventListener("dragstart", (e) => {
      dragData = {
        taskId: taskEl.dataset.taskId,
        fromColumnId: taskEl.dataset.columnId
      };
      e.dataTransfer.effectAllowed = "move";
    });
  });

  document.querySelectorAll(".task-list").forEach((listEl) => {
    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drop-target");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drop-target");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drop-target");

      if (!dragData) return;

      const toColumnId = listEl.dataset.columnId;
      const tasks = Array.from(listEl.querySelectorAll(".task"));
      const toIndex = tasks.length;

      socket.emit("task:move", {
        boardId: activeBoardId,
        taskId: dragData.taskId,
        fromColumnId: dragData.fromColumnId,
        toColumnId,
        toIndex
      });

      dragData = null;
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  taskDialog.showModal();
});

cancelTaskBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();

  if (!title || !activeBoardId) return;

  const board = appState.boards[0];
  const columnId = board.columns[0].id;

  socket.emit("task:create", {
    boardId: activeBoardId,
    columnId,
    title,
    description
  });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskDialog.close();
});

// Initial load fallback
fetch("http://localhost:3001/api/state")
  .then((res) => res.json())
  .then((state) => {
    appState = state;
    render();
  })
  .catch(() => {
    connectionStatusEl.textContent = "Backend unavailable";
  });
```

