### `client/src/App.jsx`
```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:3001");

const initialColumns = [
  { id: "todo", title: "To Do" },
  { id: "doing", title: "In Progress" },
  { id: "done", title: "Done" }
];

function App() {
  const [board, setBoard] = useState({ todo: [], doing: [], done: [] });
  const [draggedTask, setDraggedTask] = useState(null);

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const handleDragStart = (task, fromColumn) => {
    setDraggedTask({ task, fromColumn });
  };

  const handleDrop = (toColumn) => {
    if (!draggedTask) return;

    const { task, fromColumn } = draggedTask;
    if (fromColumn === toColumn) return;

    const nextBoard = { ...board };
    nextBoard[fromColumn] = nextBoard[fromColumn].filter((t) => t.id !== task.id);
    nextBoard[toColumn] = [...nextBoard[toColumn], task];

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
    setDraggedTask(null);
  };

  const addTask = (columnId) => {
    const title = prompt("Task title?");
    if (!title) return;

    const description = prompt("Task description?") || "";
    const task = {
      id: crypto.randomUUID(),
      title,
      description
    };

    const nextBoard = {
      ...board,
      [columnId]: [...board[columnId], task]
    };

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks across columns. Updates sync in real time.</p>
      </header>

      <div className="board">
        {initialColumns.map((column) => (
          <div
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <button onClick={() => addTask(column.id)}>+ Add</button>
            </div>

            <div className="task-list">
              {board[column.id].map((task) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task, column.id)}
                >
                  <h3>{task.title}</h3>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
```

