```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { randomUUID } from "crypto";
import { state } from "./state";
import { Task, TaskStatus } from "./types";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PATCH"],
  },
});

app.get("/api/tasks", (_req, res) => {
  res.json(state.tasks);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status } = req.body as Partial<Task>;

  if (!title || !status) {
    return res.status(400).json({ error: "title and status are required" });
  }

  const task: Task = {
    id: randomUUID(),
    title,
    description,
    status: status as TaskStatus,
    updatedAt: Date.now(),
  };

  state.tasks.push(task);
  io.emit("tasks:updated", state.tasks);

  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description, status } = req.body as Partial<Task>;

  const task = state.tasks.find((t) => t.id === id);
  if (!task) return res.status(404).json({ error: "Task not found" });

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (status !== undefined) task.status = status as TaskStatus;
  task.updatedAt = Date.now();

  io.emit("tasks:updated", state.tasks);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const before = state.tasks.length;
  state.tasks = state.tasks.filter((t) => t.id !== id);

  if (state.tasks.length === before) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("tasks:updated", state.tasks);
  res.status(204).send();
});

io.on("connection", (socket) => {
  socket.emit("tasks:updated", state.tasks);

  socket.on("tasks:update", (tasks: Task[]) => {
    state.tasks = tasks.map((t) => ({ ...t, updatedAt: Date.now() }));
    io.emit("tasks:updated", state.tasks);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
