### `client/src/App.tsx`
```tsx
import { useEffect, useMemo, useState } from "react";
import { fetchTasks, createTask } from "./api";
import { socket } from "./socket";
import { Board } from "./components/Board";
import { Task, TaskStatus } from "./types";

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetchTasks().then(setTasks).catch(console.error);

    socket.on("tasks:updated", (updated: Task[]) => {
      setTasks(updated);
    });

    return () => {
      socket.off("tasks:updated");
    };
  }, []);

  const moveTask = (taskId: string, status: TaskStatus) => {
    setTasks((prev) => {
      const next = prev.map((t) => (t.id === taskId ? { ...t, status } : t));
      socket.emit("tasks:update", next);
      return next;
    });
  };

  const handleAddTask = async () => {
    if (!title.trim()) return;
    const newTask = await createTask({
      title,
      description,
      status: "todo",
    });
    setTasks((prev) => [...prev, newTask]);
    setTitle("");
    setDescription("");
  };

  const taskCount = useMemo(() => tasks.length, [tasks]);

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif", background: "#e9edf3", minHeight: "100vh" }}>
      <h1>Project Manager</h1>
      <p>{taskCount} tasks</p>

      <div style={{ display: "flex", gap: 8, marginBottom: 24 }}>
        <input
          placeholder="Task title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <input
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <button onClick={handleAddTask}>Add Task</button>
      </div>

      <Board tasks={tasks} onMoveTask={moveTask} />
    </div>
  );
}
