## 2) Backend: `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let boards = {
  todo: [
    { id: "1", title: "Set up project", description: "Initialize repo and tooling" },
    { id: "2", title: "Design UI", description: "Create board layout" },
  ],
  doing: [
    { id: "3", title: "Implement drag-and-drop", description: "Use HTML5 DnD" },
  ],
  done: [
    { id: "4", title: "Define requirements", description: "List MVP features" },
  ],
};

function findAndRemoveTask(taskId) {
  for (const column of Object.keys(boards)) {
    const index = boards[column].findIndex((task) => task.id === taskId);
    if (index !== -1) {
      return boards[column].splice(index, 1)[0];
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Send current board state to newly connected client
  socket.emit("board:update", boards);

  // Handle task movement
  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const task = findAndRemoveTask(taskId);
    if (!task) return;

    if (!boards[toColumn]) boards[toColumn] = [];
    boards[toColumn].splice(toIndex, 0, task);

    io.emit("board:update", boards);
  });

  // Handle task creation
  socket.on("task:create", ({ column, task }) => {
    if (!boards[column]) boards[column] = [];
    boards[column].unshift(task);
    io.emit("board:update", boards);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    findAndRemoveTask(taskId);
    io.emit("board:update", boards);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

