## 5) Frontend JS: `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescInput = document.getElementById("taskDesc");
const taskColumnSelect = document.getElementById("taskColumn");

let boardState = {};
let draggedTaskId = null;

function renderBoard(boards) {
  boardState = boards;

  ["todo", "doing", "done"].forEach((column) => {
    const columnEl = document.getElementById(column);
    columnEl.innerHTML = "";

    boards[column].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        draggedTaskId = task.id;
        e.dataTransfer.setData("text/plain", task.id);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      columnEl.appendChild(taskEl);
    });

    enableDropZone(columnEl, column);
  });
}

function enableDropZone(columnEl, columnName) {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    const taskId = e.dataTransfer.getData("text/plain") || draggedTaskId;
    if (!taskId) return;

    const fromColumn = findTaskColumn(taskId);
    const toColumn = columnName;

    if (!fromColumn || fromColumn === toColumn) return;

    const toIndex = boardState[toColumn].length;

    socket.emit("task:move", {
      taskId,
      fromColumn,
      toColumn,
      toIndex,
    });
  });
}

function findTaskColumn(taskId) {
  for (const column of Object.keys(boardState)) {
    if (boardState[column].some((task) => task.id === taskId)) {
      return column;
    }
  }
  return null;
}

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();
  const column = taskColumnSelect.value;

  if (!title) return;

  const task = {
    id: crypto.randomUUID(),
    title,
    description,
  };

  socket.emit("task:create", { column, task });

  taskTitleInput.value = "";
  taskDescInput.value = "";
  taskTitleInput.focus();
});

socket.on("board:update", (boards) => {
  renderBoard(boards);
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

