## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory state for initial implementation.
 * Replace with a database later.
 */
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Set up project", description: "Initialize app structure" },
        { id: "task-2", title: "Design UI", description: "Create board layout" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Implement drag and drop", description: "Use HTML5 drag events" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function findTaskAndColumn(state, taskId) {
  for (const column of state.columns) {
    const taskIndex = column.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      return { column, taskIndex, task: column.tasks[taskIndex] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board state to newly connected client
  socket.emit("board:state", boardState);

  // Handle task movement
  socket.on("task:move", ({ taskId, toColumnId, toIndex }) => {
    const found = findTaskAndColumn(boardState, taskId);
    if (!found) return;

    const { column: fromColumn, taskIndex, task } = found;
    fromColumn.tasks.splice(taskIndex, 1);

    const toColumn = boardState.columns.find((c) => c.id === toColumnId);
    if (!toColumn) return;

    const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
    toColumn.tasks.splice(insertIndex, 0, task);

    io.emit("board:state", boardState);
  });

  // Handle task creation
  socket.on("task:create", ({ columnId, title, description }) => {
    const column = boardState.columns.find((c) => c.id === columnId);
    if (!column || !title?.trim()) return;

    const newTask = {
      id: `task-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      title: title.trim(),
      description: description?.trim() || ""
    };

    column.tasks.unshift(newTask);
    io.emit("board:state", boardState);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    const found = findTaskAndColumn(boardState, taskId);
    if (!found) return;

    found.column.tasks.splice(found.taskIndex, 1);
    io.emit("board:state", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
