## 5) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const statusEl = document.getElementById("connectionStatus");
const createTaskForm = document.getElementById("createTaskForm");
const taskColumn = document.getElementById("taskColumn");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const taskTemplate = document.getElementById("taskTemplate");

let currentState = null;
let draggedTaskId = null;

socket.on("connect", () => {
  statusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
});

socket.on("board:state", (state) => {
  currentState = state;
  renderBoard(state);
});

createTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:create", {
    columnId: taskColumn.value,
    title: taskTitle.value,
    description: taskDescription.value
  });

  taskTitle.value = "";
  taskDescription.value = "";
});

function renderBoard(state) {
  boardEl.innerHTML = "";

  state.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = column.title;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drop-target");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-target");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drop-target");

      if (!draggedTaskId) return;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        toColumnId: column.id,
        toIndex: column.tasks.length
      });

      draggedTaskId = null;
    });

    column.tasks.forEach((task, index) => {
      const taskEl = createTaskElement(task, column.id, index);
      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function createTaskElement(task, columnId, index) {
  const taskNode = taskTemplate.content.cloneNode(true);
  const taskEl = taskNode.querySelector(".task");
  const titleEl = taskNode.querySelector(".task-title");
  const descEl = taskNode.querySelector(".task-description");
  const deleteBtn = taskNode.querySelector(".delete-task");

  titleEl.textContent = task.title;
  descEl.textContent = task.description || "No description";

  taskEl.dataset.taskId = task.id;
  taskEl.draggable = true;

  taskEl.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    taskEl.classList.add("dragging");
  });

  taskEl.addEventListener("dragend", () => {
    draggedTaskId = null;
    taskEl.classList.remove("dragging");
  });

  deleteBtn.addEventListener("click", () => {
    socket.emit("task:delete", { taskId: task.id });
  });

  taskEl.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  taskEl.addEventListener("drop", (e) => {
    e.preventDefault();

    if (!draggedTaskId || draggedTaskId === task.id) return;

    socket.emit("task:move", {
      taskId: draggedTaskId,
      toColumnId: columnId,
      toIndex: index
    });

    draggedTaskId = null;
  });

  return taskEl;
}
