## 3) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors({ origin: "http://localhost:5173" }));
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"]
  }
});

// In-memory data store for initial implementation
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Design app layout",
      description: "Create the initial layout and navigation."
    },
    "task-2": {
      id: "task-2",
      title: "Set up authentication",
      description: "Add login and user session handling."
    },
    "task-3": {
      id: "task-3",
      title: "Implement drag and drop",
      description: "Enable moving cards between columns."
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const id = `task-${Date.now()}`;
  const newTask = {
    id,
    title,
    description: description || ""
  };

  boardState.tasks[id] = newTask;
  const column = boardState.columns.find((c) => c.id === columnId);

  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(id);

  io.emit("board:update", boardState);

  res.status(201).json(newTask);
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  if (!taskId || !sourceColumnId || !destinationColumnId) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number"
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("board:update", boardState);

  res.json({ success: true, boardState });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("board:move-task", (payload) => {
    const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload;

    const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = boardState.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof destinationIndex === "number"
        ? destinationIndex
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
