## 7) Frontend: `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";

const socket = io("http://localhost:3001");

function TaskCard({ task }) {
  return (
    <div className="task-card">
      <h4>{task.title}</h4>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <div key={task.id} className="task-wrapper">
              <TaskCard task={task} />
            </div>
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    fetch("http://localhost:3001/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => board?.columns || [], [board]);
  const tasks = useMemo(() => board?.tasks || {}, [board]);

  const handleAddTask = async (e) => {
    e.preventDefault();

    if (!newTaskTitle.trim()) return;

    await fetch("http://localhost:3001/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDescription,
        columnId: "todo"
      })
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over) return;

    const activeTaskId = active.id;
    const overId = over.id;

    const sourceColumn = columns.find((col) => col.taskIds.includes(activeTaskId));
    const destinationColumn = columns.find((col) => col.taskIds.includes(overId)) || sourceColumn;

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(activeTaskId);
    const destinationIndex = destinationColumn.taskIds.indexOf(overId);

    const updatedColumns = columns.map((col) => ({ ...col, taskIds: [...col.taskIds] }));

    if (sourceColumn.id === destinationColumn.id) {
      const col = updatedColumns.find((c) => c.id === sourceColumn.id);
      col.taskIds = arrayMove(col.taskIds, sourceIndex, destinationIndex);
    } else {
      const sourceCol = updatedColumns.find((c) => c.id === sourceColumn.id);
      const destCol = updatedColumns.find((c) => c.id === destinationColumn.id);

      sourceCol.taskIds.splice(sourceIndex, 1);
      destCol.taskIds.splice(destinationIndex >= 0 ? destinationIndex : destCol.taskIds.length, 0, activeTaskId);
    }

    setBoard({
      ...board,
      columns: updatedColumns
    });

    socket.emit("board:move-task", {
      taskId: activeTaskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex: destinationColumn.taskIds.indexOf(overId)
    });
  };

  if (!board) return <div className="app loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>Project Board</h1>
          <p>Drag tasks between columns and collaborate in real time.</p>
        </div>

        <form className="new-task-form" onSubmit={handleAddTask}>
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <input
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
            placeholder="Description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {columns.map((column) => (
            <div key={column.id} className="column-shell">
              <Column
                column={column}
                tasks={column.taskIds.map((id) => tasks[id]).filter(Boolean)}
              />
            </div>
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

