## `server/src/store.ts`

```ts
import { BoardState, Task, TaskStatus } from "./types";

const now = () => Date.now();

export const boardState: BoardState = {
  tasks: [
    {
      id: "1",
      title: "Set up project",
      description: "Initialize repo and app structure",
      status: "todo",
      createdAt: now(),
      updatedAt: now()
    },
    {
      id: "2",
      title: "Build drag-and-drop board",
      description: "Implement task movement between columns",
      status: "inprogress",
      createdAt: now(),
      updatedAt: now()
    },
    {
      id: "3",
      title: "Add real-time sync",
      description: "Broadcast updates over Socket.IO",
      status: "done",
      createdAt: now(),
      updatedAt: now()
    }
  ]
};

export function addTask(task: Omit<Task, "id" | "createdAt" | "updatedAt">): Task {
  const newTask: Task = {
    id: crypto.randomUUID(),
    createdAt: now(),
    updatedAt: now(),
    ...task
  };
  boardState.tasks.push(newTask);
  return newTask;
}

export function updateTask(
  id: string,
  updates: Partial<Omit<Task, "id" | "createdAt">>
): Task | null {
  const task = boardState.tasks.find((t) => t.id === id);
  if (!task) return null;
  Object.assign(task, updates, { updatedAt: now() });
  return task;
}

export function moveTask(id: string, status: TaskStatus): Task | null {
  return updateTask(id, { status });
}

export function deleteTask(id: string): boolean {
  const index = boardState.tasks.findIndex((t) => t.id === id);
  if (index === -1) return false;
  boardState.tasks.splice(index, 1);
  return true;
}
```

## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { addTask, boardState, deleteTask, moveTask, updateTask } from "./store";
import { TaskStatus } from "./types";

const app = express();
app.use(cors({ origin: true }));
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status } = req.body as {
    title?: string;
    description?: string;
    status?: TaskStatus;
  };

  if (!title || !status) {
    return res.status(400).json({ error: "title and status are required" });
  }

  const task = addTask({ title, description, status });
  io.emit("board:updated", boardState);
  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = updateTask(id, req.body);
  if (!task) return res.status(404).json({ error: "Task not found" });

  io.emit("board:updated", boardState);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const ok = deleteTask(req.params.id);
  if (!ok) return res.status(404).json({ error: "Task not found" });

  io.emit("board:updated", boardState);
  res.status(204).send();
});

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: true }
});

io.on("connection", (socket) => {
  socket.emit("board:updated", boardState);

  socket.on("task:move", (payload: { id: string; status: TaskStatus }) => {
    const task = moveTask(payload.id, payload.status);
    if (task) io.emit("board:updated", boardState);
  });

  socket.on(
    "task:update",
    (payload: { id: string; title?: string; description?: string; assignee?: string }) => {
      const task = updateTask(payload.id, payload);
      if (task) io.emit("board:updated", boardState);
    }
  );

  socket.on("task:create", (payload: { title: string; description?: string; status: TaskStatus }) => {
    const task = addTask(payload);
    io.emit("board:updated", boardState);
    socket.emit("task:created", task);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

