## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type TaskStatus = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  createdAt: number;
  updatedAt: number;
  assignee?: string;
};

type BoardState = {
  tasks: Task[];
};

const socket: Socket = io("http://localhost:4000");

const columns: { key: TaskStatus; label: string }[] = [
  { key: "todo", label: "To Do" },
  { key: "inprogress", label: "In Progress" },
  { key: "done", label: "Done" }
];

export default function App() {
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [status, setStatus] = useState<TaskStatus>("todo");
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);

  useEffect(() => {
    socket.on("board:updated", (nextBoard: BoardState) => setBoard(nextBoard));
    return () => {
      socket.off("board:updated");
    };
  }, []);

  const tasksByStatus = useMemo(() => {
    return {
      todo: board.tasks.filter((t) => t.status === "todo"),
      inprogress: board.tasks.filter((t) => t.status === "inprogress"),
      done: board.tasks.filter((t) => t.status === "done")
    };
  }, [board.tasks]);

  function createTask(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;

    socket.emit("task:create", {
      title: title.trim(),
      description: description.trim() || undefined,
      status
    });

    setTitle("");
    setDescription("");
    setStatus("todo");
  }

  function onDragStart(taskId: string) {
    setDraggedTaskId(taskId);
  }

  function onDrop(targetStatus: TaskStatus) {
    if (!draggedTaskId) return;
    socket.emit("task:move", { id: draggedTaskId, status: targetStatus });
    setDraggedTaskId(null);
  }

  function deleteTask(id: string) {
    fetch(`http://localhost:4000/api/tasks/${id}`, {
      method: "DELETE"
    });
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <section className="new-task">
        <form onSubmit={createTask} className="task-form">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description"
          />
          <select value={status} onChange={(e) => setStatus(e.target.value as TaskStatus)}>
            {columns.map((col) => (
              <option key={col.key} value={col.key}>
                {col.label}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </section>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.key}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => onDrop(column.key)}
          >
            <div className="column-header">
              <h2>{column.label}</h2>
              <span>{tasksByStatus[column.key].length}</span>
            </div>

            <div className="task-list">
              {tasksByStatus[column.key].map((task) => (
                <article
                  key={task.id}
                  className={`task-card ${draggedTaskId === task.id ? "dragging" : ""}`}
                  draggable
                  onDragStart={() => onDragStart(task.id)}
                >
                  <div className="task-card-top">
                    <h3>{task.title}</h3>
                    <button onClick={() => deleteTask(task.id)}>×</button>
                  </div>
                  {task.description && <p>{task.description}</p>}
                  <small>Updated {new Date(task.updatedAt).toLocaleTimeString()}</small>
                </article>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

