# 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "task-1", title: "Set up project", description: "Initialize app structure" },
      { id: "task-2", title: "Design UI", description: "Create board layout" }
    ],
    doing: [
      { id: "task-3", title: "Implement drag-and-drop", description: "Enable task movement" }
    ],
    done: []
  }
};

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("move-task", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromTasks = state.columns[fromColumn];
    const toTasks = state.columns[toColumn];
    if (!fromTasks || !toTasks) return;

    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    toTasks.splice(toIndex, 0, task);

    io.emit("state", state);
  });

  socket.on("add-task", ({ columnId, title, description }) => {
    if (!state.columns[columnId]) return;

    const task = {
      id: `task-${Date.now()}`,
      title,
      description
    };

    state.columns[columnId].push(task);
    io.emit("state", state);
  });

  socket.on("delete-task", ({ taskId, columnId }) => {
    const column = state.columns[columnId];
    if (!column) return;

    const index = column.findIndex((t) => t.id === taskId);
    if (index === -1) return;

    column.splice(index, 1);
    io.emit("state", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

