```js
const socket = io();

let state = { columns: { todo: [], doing: [], done: [] } };
let draggedTask = null;

const taskForm = document.getElementById("taskForm");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const columnSelect = document.getElementById("column");

socket.on("state", (newState) => {
  state = newState;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.emit("add-task", { columnId, title, description });

  titleInput.value = "";
  descriptionInput.value = "";
});

function renderBoard() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    state.columns[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <button>Delete</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { taskId: task.id, fromColumn: columnId };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("delete-task", { taskId: task.id, columnId });
      });

      list.appendChild(taskEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumn = columnId;
      const toIndex = state.columns[toColumn].length;

      socket.emit("move-task", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn,
        toIndex
      });

      draggedTask = null;
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
