## 3) server.js

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", text: "Set up project", boardId: "todo" },
        { id: "t2", text: "Design UI", boardId: "todo" }
      ]
    },
    {
      id: "doing",
      title: "Doing",
      tasks: [
        { id: "t3", text: "Implement drag and drop", boardId: "doing" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function broadcast() {
  const msg = JSON.stringify({ type: "state", payload: state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "move-task") {
        const { taskId, toBoardId, toIndex } = data.payload;

        let task = null;
        for (const board of state.boards) {
          const idx = board.tasks.findIndex((t) => t.id === taskId);
          if (idx !== -1) {
            task = board.tasks.splice(idx, 1)[0];
            break;
          }
        }

        if (!task) return;

        task.boardId = toBoardId;
        const targetBoard = state.boards.find((b) => b.id === toBoardId);
        if (!targetBoard) return;

        const insertIndex = Math.max(0, Math.min(toIndex ?? targetBoard.tasks.length, targetBoard.tasks.length));
        targetBoard.tasks.splice(insertIndex, 0, task);

        broadcast();
      }

      if (data.type === "add-task") {
        const { boardId, text } = data.payload;
        const board = state.boards.find((b) => b.id === boardId);
        if (!board || !text.trim()) return;

        board.tasks.push({
          id: "t" + Date.now(),
          text: text.trim(),
          boardId
        });

        broadcast();
      }
    } catch (err) {
      console.error("Invalid message", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

