## 6) public/app.js

```js
const ws = new WebSocket(`ws://${location.host}`);
const statusEl = document.getElementById("status");
const boardsEl = document.getElementById("boards");
const boardSelect = document.getElementById("boardSelect");
const taskText = document.getElementById("taskText");
const addTaskBtn = document.getElementById("addTaskBtn");

let state = null;
let draggedTaskId = null;

ws.addEventListener("open", () => {
  statusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  statusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    state = msg.payload;
    render();
  }
});

function send(type, payload) {
  ws.send(JSON.stringify({ type, payload }));
}

function render() {
  if (!state) return;

  boardsEl.innerHTML = "";
  boardSelect.innerHTML = "";

  state.boards.forEach((board) => {
    const option = document.createElement("option");
    option.value = board.id;
    option.textContent = board.title;
    boardSelect.appendChild(option);

    const boardDiv = document.createElement("div");
    boardDiv.className = "board";
    boardDiv.dataset.boardId = board.id;

    boardDiv.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const taskList = boardDiv.querySelector(".task-list");

    board.tasks.forEach((task, index) => {
      const taskDiv = document.createElement("div");
      taskDiv.className = "task";
      taskDiv.draggable = true;
      taskDiv.dataset.taskId = task.id;
      taskDiv.dataset.index = index;
      taskDiv.textContent = task.text;

      taskDiv.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskDiv.classList.add("dragging");
      });

      taskDiv.addEventListener("dragend", () => {
        draggedTaskId = null;
        taskDiv.classList.remove("dragging");
      });

      taskList.appendChild(taskDiv);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId) return;

      const toBoardId = board.id;
      const toIndex = board.tasks.length; // minimal: drop to end
      send("move-task", { taskId: draggedTaskId, toBoardId, toIndex });
    });

    boardsEl.appendChild(boardDiv);
  });
}

addTaskBtn.addEventListener("click", () => {
  const text = taskText.value.trim();
  const boardId = boardSelect.value;
  if (!text) return;

  send("add-task", { boardId, text });
  taskText.value = "";
});

taskText.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});
```

