## 6) `public/app.js`

```js
const socket = io();

const boardEls = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

const form = document.getElementById("addTaskForm");
const taskTitleInput = document.getElementById("taskTitle");

let currentBoard = {};

function renderBoard(board) {
  currentBoard = board;
  Object.keys(boardEls).forEach((column) => {
    const el = boardEls[column];
    el.innerHTML = "";

    board[column].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.textContent = task.title;

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      el.appendChild(taskEl);
    });
  });
}

socket.on("board:update", (board) => {
  renderBoard(board);
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskTitleInput.value.trim();
  if (!title) return;
  socket.emit("task:add", { title });
  taskTitleInput.value = "";
});

document.querySelectorAll(".column").forEach((columnEl) => {
  const columnName = columnEl.dataset.column;
  const listEl = columnEl.querySelector(".task-list");

  listEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  listEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  listEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    const draggingTask = document.querySelector(".task.dragging");
    if (!draggingTask) return;

    const taskId = draggingTask.dataset.id;
    const from = draggingTask.dataset.column;
    const to = columnName;

    const tasksInTarget = Array.from(listEl.querySelectorAll(".task"));
    const index = tasksInTarget.length;

    socket.emit("task:move", { taskId, from, to, index });
  });
});
```

