## 6) `public/app.js`

```js
const socket = io();

const taskInput = document.getElementById("taskInput");
const addTaskBtn = document.getElementById("addTaskBtn");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let tasks = [];

function renderTasks() {
  Object.values(columns).forEach((col) => (col.innerHTML = ""));

  tasks.forEach((task) => {
    const card = document.createElement("div");
    card.className = "task-card";
    card.draggable = true;
    card.dataset.id = task.id;

    card.innerHTML = `
      <span>${task.title}</span>
      <button data-delete="${task.id}">×</button>
    `;

    card.addEventListener("dragstart", (e) => {
      e.dataTransfer.setData("text/plain", task.id);
    });

    card.querySelector("button").addEventListener("click", () => {
      socket.emit("deleteTask", task.id);
    });

    columns[task.status].appendChild(card);
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  if (!title) return;

  const task = {
    id: Date.now().toString(),
    title,
    status: "todo"
  };

  socket.emit("addTask", task);
  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

Object.entries(columns).forEach(([status, column]) => {
  column.parentElement.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.parentElement.classList.add("drag-over");
  });

  column.parentElement.addEventListener("dragleave", () => {
    column.parentElement.classList.remove("drag-over");
  });

  column.parentElement.addEventListener("drop", (e) => {
    e.preventDefault();
    column.parentElement.classList.remove("drag-over");

    const taskId = e.dataTransfer.getData("text/plain");
    socket.emit("moveTask", { taskId, newStatus: status });
  });
});

socket.on("init", (serverTasks) => {
  tasks = serverTasks;
  renderTasks();
});

socket.on("tasksUpdated", (serverTasks) => {
  tasks = serverTasks;
  renderTasks();
});
```

