const socket = io();

const taskForm = document.getElementById("task-form");
const taskInput = document.getElementById("task-input");

const lists = {
  todo: document.getElementById("todo-list"),
  doing: document.getElementById("doing-list"),
  done: document.getElementById("done-list")
};

let currentTasks = [];

function renderTasks(tasks) {
  currentTasks = tasks;
  Object.values(lists).forEach((list) => (list.innerHTML = ""));

  tasks.forEach((task) => {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.dataset.id = task.id;

    el.innerHTML = `
      <span>${task.title}</span>
      <button class="delete-btn" data-delete="${task.id}">X</button>
    `;

    el.addEventListener("dragstart", () => {
      el.classList.add("dragging");
      el.dataset.dragId = task.id;
    });

    el.addEventListener("dragend", () => {
      el.classList.remove("dragging");
    });

    lists[task.status].appendChild(el);
  });
}

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("add-task", {
    id: String(Date.now()),
    title,
    status: "todo"
  });

  taskInput.value = "";
});

document.addEventListener("click", (e) => {
  const id = e.target.dataset.delete;
  if (id) socket.emit("delete-task", id);
});

// Drag-and-drop support
Object.entries(lists).forEach(([status, list]) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    const dragging = document.querySelector(".task.dragging");
    if (!dragging) return;

    const id = dragging.dataset.id;
    socket.emit("move-task", { id, status });
  });
});

socket.on("init", renderTasks);
socket.on("tasks-updated", renderTasks);
