```js
const socket = io();

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

const lists = {
  todo: document.getElementById("todoList"),
  doing: document.getElementById("doingList"),
  done: document.getElementById("doneList")
};

let tasks = [];

function renderTasks() {
  Object.values(lists).forEach((list) => (list.innerHTML = ""));

  tasks.forEach((task) => {
    const taskEl = document.createElement("div");
    taskEl.className = "task";
    taskEl.draggable = true;
    taskEl.dataset.id = task.id;

    taskEl.innerHTML = `
      <span>${task.title}</span>
      <button class="delete-btn">X</button>
    `;

    taskEl.addEventListener("dragstart", (e) => {
      e.dataTransfer.setData("text/plain", task.id);
    });

    taskEl.querySelector(".delete-btn").addEventListener("click", () => {
      socket.emit("deleteTask", task.id);
    });

    lists[task.status].appendChild(taskEl);
  });
}

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskInput.value.trim();
  if (!title) return;

  const task = {
    id: Date.now().toString(),
    title,
    status: "todo"
  };

  socket.emit("addTask", task);
  taskInput.value = "";
});

Object.entries(lists).forEach(([status, list]) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("drag-over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("drag-over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("drag-over");

    const taskId = e.dataTransfer.getData("text/plain");
    socket.emit("moveTask", { taskId, newStatus: status });
  });
});

socket.on("init", (serverTasks) => {
  tasks = serverTasks;
  renderTasks();
});

socket.on("tasksUpdated", (serverTasks) => {
  tasks = serverTasks;
  renderTasks();
});
