## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "1", title: "Set up project" },
      { id: "2", title: "Create UI" }
    ],
    doing: [
      { id: "3", title: "Add drag and drop" }
    ],
    done: [
      { id: "4", title: "Initial planning" }
    ]
  }
};

function broadcast() {
  const msg = JSON.stringify({ type: "state", state });
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  });
}

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "state", state }));

  ws.on("message", message => {
    try {
      const data = JSON.parse(message);

      if (data.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = data;

        let task = null;
        state.columns[fromColumn] = state.columns[fromColumn].filter(t => {
          if (t.id === taskId) {
            task = t;
            return false;
          }
          return true;
        });

        if (task) {
          const target = state.columns[toColumn];
          const index = Math.max(0, Math.min(toIndex, target.length));
          target.splice(index, 0, task);
          broadcast();
        }
      }

      if (data.type === "add-task") {
        const { column, title } = data;
        const newTask = {
          id: String(Date.now()),
          title: title.trim()
        };
        if (newTask.title) {
          state.columns[column].push(newTask);
          broadcast();
        }
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

