## 6) `public/app.js`

```js
const board = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

const columnsMeta = [
  { id: "todo", title: "To Do" },
  { id: "doing", title: "Doing" },
  { id: "done", title: "Done" }
];

let currentState = null;
let draggedTaskId = null;
let draggedFromColumn = null;

const ws = new WebSocket(`ws://${location.host}`);

ws.addEventListener("message", event => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    currentState = msg.state;
    renderBoard();
  }
});

function send(message) {
  ws.send(JSON.stringify(message));
}

function renderBoard() {
  board.innerHTML = "";

  columnsMeta.forEach(col => {
    const columnEl = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleEl = columnEl.querySelector("h2");
    const taskListEl = columnEl.querySelector(".task-list");
    const formEl = columnEl.querySelector(".add-task-form");
    const inputEl = formEl.querySelector("input");

    titleEl.textContent = col.title;

    const tasks = currentState.columns[col.id] || [];
    tasks.forEach((task, index) => {
      const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = col.id;
      taskEl.dataset.index = index;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumn = col.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", e => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const tasksInTarget = currentState.columns[col.id] || [];
      const toIndex = tasksInTarget.length;

      send({
        type: "move-task",
        taskId: draggedTaskId,
        fromColumn: draggedFromColumn,
        toColumn: col.id,
        toIndex
      });

      draggedTaskId = null;
      draggedFromColumn = null;
    });

    formEl.addEventListener("submit", e => {
      e.preventDefault();
      const title = inputEl.value.trim();
      if (!title) return;

      send({
        type: "add-task",
        column: col.id,
        title
      });

      inputEl.value = "";
    });

    board.appendChild(columnEl);
  });
}
```

