## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project", description: "Initialize app structure" },
      { id: "t2", title: "Design UI", description: "Create board layout" }
    ],
    doing: [
      { id: "t3", title: "Build drag and drop", description: "Enable task movement" }
    ],
    done: [
      { id: "t4", title: "Create repo", description: "Repository is ready" }
    ]
  }
};

function findTask(taskId) {
  for (const columnId of Object.keys(state.columns)) {
    const index = state.columns[columnId].findIndex(task => task.id === taskId);
    if (index !== -1) {
      return { columnId, index, task: state.columns[columnId][index] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("moveTask", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const sourceIndex = state.columns[fromColumn].findIndex(t => t.id === taskId);
    if (sourceIndex === -1) return;

    const [task] = state.columns[fromColumn].splice(sourceIndex, 1);

    const targetList = state.columns[toColumn];
    const safeIndex = Math.max(0, Math.min(toIndex, targetList.length));
    targetList.splice(safeIndex, 0, task);

    io.emit("state", state);
  });

  socket.on("addTask", ({ columnId, title, description }) => {
    const task = {
      id: `t${Date.now()}`,
      title,
      description
    };
    state.columns[columnId].unshift(task);
    io.emit("state", state);
  });

  socket.on("deleteTask", ({ taskId }) => {
    const found = findTask(taskId);
    if (!found) return;
    state.columns[found.columnId].splice(found.index, 1);
    io.emit("state", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

