## 6) `public/app.js`

```js
const socket = io();

let state = null;
let draggedTaskId = null;

const board = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDesc = document.getElementById("taskDesc");
const taskColumn = document.getElementById("taskColumn");

function render() {
  if (!state) return;

  for (const columnId of Object.keys(state.columns)) {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    state.columns[columnId].forEach((task) => {
      const el = document.createElement("div");
      el.className = "task";
      el.draggable = true;
      el.dataset.taskId = task.id;

      el.innerHTML = `
        <strong>${escapeHtml(task.title)}</strong>
        <div class="meta">${escapeHtml(task.description || "")}</div>
        <button data-delete="${task.id}">Delete</button>
      `;

      el.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        el.classList.add("dragging");
      });

      el.addEventListener("dragend", () => {
        draggedTaskId = null;
        el.classList.remove("dragging");
      });

      list.appendChild(el);
    });
  }
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

socket.on("state", (newState) => {
  state = newState;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  socket.emit("addTask", {
    columnId: taskColumn.value,
    title: taskTitle.value.trim(),
    description: taskDesc.value.trim()
  });
  taskTitle.value = "";
  taskDesc.value = "";
});

document.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("over");

    if (!draggedTaskId) return;

    const toColumn = list.id;
    const tasks = Array.from(list.querySelectorAll(".task"));
    const toIndex = tasks.length;

    const fromColumn = Object.keys(state.columns).find((col) =>
      state.columns[col].some((t) => t.id === draggedTaskId)
    );

    socket.emit("moveTask", {
      taskId: draggedTaskId,
      fromColumn,
      toColumn,
      toIndex
    });
  });
});

board.addEventListener("click", (e) => {
  const taskId = e.target.getAttribute("data-delete");
  if (taskId) {
    socket.emit("deleteTask", { taskId });
  }
});
