```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Design UI" },
      { id: "t2", title: "Set up backend" }
    ],
    doing: [
      { id: "t3", title: "Build drag and drop" }
    ],
    done: [
      { id: "t4", title: "Create project scaffold" }
    ]
  }
};

io.on("connection", (socket) => {
  socket.emit("init", state);

  socket.on("move-task", ({ taskId, fromCol, toCol, toIndex }) => {
    const fromList = state.columns[fromCol];
    const toList = state.columns[toCol];
    if (!fromList || !toList) return;

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex, 0, task);

    io.emit("state-update", state);
  });

  socket.on("add-task", ({ colId, title }) => {
    if (!state.columns[colId] || !title?.trim()) return;

    const newTask = {
      id: "t" + Date.now(),
      title: title.trim()
    };

    state.columns[colId].push(newTask);
    io.emit("state-update", state);
  });

  socket.on("delete-task", ({ colId, taskId }) => {
    if (!state.columns[colId]) return;

    state.columns[colId] = state.columns[colId].filter((t) => t.id !== taskId);
    io.emit("state-update", state);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

