## 5) `public/app.js`

```js
const socket = io();

let state = null;
let draggedTask = null;

const board = document.getElementById("board");
const taskTitleInput = document.getElementById("taskTitle");
const taskColumnSelect = document.getElementById("taskColumn");
const addTaskBtn = document.getElementById("addTaskBtn");

const columnLabels = {
  todo: "To Do",
  doing: "Doing",
  done: "Done"
};

socket.on("init", (serverState) => {
  state = serverState;
  renderBoard();
});

socket.on("state-update", (serverState) => {
  state = serverState;
  renderBoard();
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const colId = taskColumnSelect.value;
  if (!title) return;

  socket.emit("add-task", { colId, title });
  taskTitleInput.value = "";
});

function renderBoard() {
  if (!state) return;

  board.innerHTML = "";

  Object.entries(state.columns).forEach(([colId, tasks]) => {
    const column = document.createElement("div");
    column.className = "column";
    column.dataset.colId = colId;

    column.innerHTML = `
      <h2>${columnLabels[colId] || colId}</h2>
      <div class="task-list" data-col-id="${colId}"></div>
    `;

    const taskList = column.querySelector(".task-list");

    tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.colId = colId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${task.title}</span>
        <button class="delete-btn" title="Delete task">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromCol: colId,
          fromIndex: index
        };
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", (e) => {
        e.stopPropagation();
        socket.emit("delete-task", { colId, taskId: task.id });
      });

      taskList.appendChild(taskEl);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTask) return;

      const toCol = colId;
      const toIndex = tasks.length;

      socket.emit("move-task", {
        taskId: draggedTask.taskId,
        fromCol: draggedTask.fromCol,
        toCol,
        toIndex
      });

      draggedTask = null;
    });

    board.appendChild(column);
  });
}
```

