## 6) `public/app.js`

```js
const socket = io();

const board = document.getElementById("board");
const taskTitle = document.getElementById("taskTitle");
const taskColumn = document.getElementById("taskColumn");
const addTaskBtn = document.getElementById("addTaskBtn");

let currentState = null;

socket.on("state", (state) => {
  currentState = state;
  renderBoard(state);
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitle.value.trim();
  const columnId = taskColumn.value;

  if (!title) return;

  socket.emit("addTask", { columnId, title });
  taskTitle.value = "";
});

function renderBoard(state) {
  board.innerHTML = "";

  const columns = [
    { id: "todo", title: "To Do" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ];

  columns.forEach((col) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h2");
    titleEl.textContent = col.title;

    const listEl = document.createElement("div");
    listEl.className = "task-list";
    listEl.dataset.columnId = col.id;

    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drag-over");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drag-over");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drag-over");

      const taskId = e.dataTransfer.getData("text/plain");
      const fromColumn = e.dataTransfer.getData("fromColumn");
      const toColumn = col.id;
      const toIndex = currentState.columns[toColumn].length;

      if (taskId && fromColumn) {
        socket.emit("moveTask", { taskId, fromColumn, toColumn, toIndex });
      }
    });

    state.columns[col.id].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", task.id);
        e.dataTransfer.setData("fromColumn", col.id);
      });

      const textEl = document.createElement("span");
      textEl.textContent = task.title;

      const delBtn = document.createElement("button");
      delBtn.textContent = "×";
      delBtn.title = "Delete task";
      delBtn.addEventListener("click", () => {
        socket.emit("deleteTask", { columnId: col.id, taskId: task.id });
      });

      taskEl.appendChild(textEl);
      taskEl.appendChild(delBtn);
      listEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(listEl);
    board.appendChild(columnEl);
  });
}
