```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let tasks = [
  { id: "1", title: "Design UI", status: "todo" },
  { id: "2", title: "Build API", status: "doing" },
  { id: "3", title: "Deploy app", status: "done" }
];

io.on("connection", (socket) => {
  // Send current state to newly connected client
  socket.emit("init", tasks);

  // Add task
  socket.on("add-task", (task) => {
    tasks.push(task);
    io.emit("task-added", task);
  });

  // Move task
  socket.on("move-task", ({ taskId, status }) => {
    const task = tasks.find((t) => t.id === taskId);
    if (task) {
      task.status = status;
      io.emit("task-moved", { taskId, status });
    }
  });

  // Optional: remove task
  socket.on("delete-task", (taskId) => {
    tasks = tasks.filter((t) => t.id !== taskId);
    io.emit("task-deleted", taskId);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

