```js
const socket = io();

const taskInput = document.getElementById("taskInput");
const addTaskBtn = document.getElementById("addTaskBtn");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let tasks = [];

function render() {
  Object.values(columns).forEach((col) => (col.innerHTML = ""));

  tasks.forEach((task) => {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.dataset.id = task.id;
    el.dataset.status = task.status;

    el.innerHTML = `
      <span>${task.title}</span>
      <button title="Delete">×</button>
    `;

    el.addEventListener("dragstart", (e) => {
      e.dataTransfer.setData("text/plain", task.id);
    });

    el.querySelector("button").addEventListener("click", () => {
      socket.emit("delete-task", task.id);
    });

    columns[task.status].appendChild(el);
  });
}

function createTask(title) {
  const task = {
    id: String(Date.now() + Math.random()),
    title,
    status: "todo"
  };
  socket.emit("add-task", task);
}

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  if (!title) return;
  createTask(title);
  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

// Drag and drop handlers
Object.entries(columns).forEach(([status, column]) => {
  column.parentElement.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.parentElement.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.parentElement.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");
    const taskId = e.dataTransfer.getData("text/plain");
    socket.emit("move-task", { taskId, status });
  });
});

// Real-time events
socket.on("init", (serverTasks) => {
  tasks = serverTasks;
  render();
});

socket.on("task-added", (task) => {
  tasks.push(task);
  render();
});

socket.on("task-moved", ({ taskId, status }) => {
  const task = tasks.find((t) => t.id === taskId);
  if (task) {
    task.status = status;
    render();
  }
});

socket.on("task-deleted", (taskId) => {
  tasks = tasks.filter((t) => t.id !== taskId);
  render();
});
