## 5) `public/app.js`

```js
const socket = io();

const statusEl = document.getElementById("status");
const boardsEl = document.getElementById("boards");
const boardSelect = document.getElementById("boardSelect");
const newTaskText = document.getElementById("newTaskText");
const addTaskBtn = document.getElementById("addTaskBtn");

const boardTemplate = document.getElementById("boardTemplate");
const taskTemplate = document.getElementById("taskTemplate");

let appState = null;
let draggedTaskId = null;

socket.on("connect", () => {
  statusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
});

socket.on("state", (state) => {
  appState = state;
  render();
});

addTaskBtn.addEventListener("click", () => {
  const text = newTaskText.value.trim();
  const boardId = boardSelect.value;
  if (!text) return;

  socket.emit("addTask", { boardId, text });
  newTaskText.value = "";
});

newTaskText.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

function render() {
  if (!appState) return;

  // Board select
  boardSelect.innerHTML = "";
  appState.boards.forEach(board => {
    const option = document.createElement("option");
    option.value = board.id;
    option.textContent = board.title;
    boardSelect.appendChild(option);
  });

  // Boards
  boardsEl.innerHTML = "";

  appState.boards.forEach(board => {
    const boardNode = boardTemplate.content.cloneNode(true);
    const section = boardNode.querySelector(".board");
    const title = boardNode.querySelector("h2");
    const taskList = boardNode.querySelector(".task-list");

    title.textContent = board.title;
    taskList.dataset.boardId = board.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const toBoardId = taskList.dataset.boardId;
      const tasks = [...taskList.querySelectorAll(".task")];
      const targetTask = e.target.closest(".task");

      let toIndex = tasks.length;
      if (targetTask) {
        toIndex = tasks.indexOf(targetTask);
        if (toIndex < 0) toIndex = tasks.length;
      }

      socket.emit("moveTask", { taskId: draggedTaskId, toBoardId, toIndex });
      draggedTaskId = null;
    });

    board.tasks.forEach(task => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const taskText = taskNode.querySelector(".task-text");
      const deleteBtn = taskNode.querySelector(".delete-btn");

      taskText.textContent = task.text;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
      });

      deleteBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        socket.emit("deleteTask", { taskId: task.id });
      });

      taskList.appendChild(taskNode);
    });

    boardsEl.appendChild(boardNode);
  });
}
```

