## 6) `public/app.js`

```js
const socket = io();

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

const columns = ["todo", "doing", "done"];
let currentBoard = {};

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("task:add", { title });
  taskInput.value = "";
});

function renderBoard() {
  columns.forEach((col) => {
    const container = document.getElementById(col);
    container.innerHTML = "";

    currentBoard[col].forEach((task, index) => {
      const div = document.createElement("div");
      div.className = "task";
      div.draggable = true;
      div.textContent = task.title;
      div.dataset.id = task.id;
      div.dataset.column = col;
      div.dataset.index = index;

      div.addEventListener("dragstart", handleDragStart);
      container.appendChild(div);
    });
  });

  setupDropZones();
}

let draggedTask = null;

function handleDragStart(e) {
  draggedTask = {
    id: e.target.dataset.id,
    from: e.target.dataset.column
  };
}

function setupDropZones() {
  document.querySelectorAll(".tasks").forEach((zone) => {
    zone.ondragover = (e) => {
      e.preventDefault();
      zone.classList.add("drag-over");
    };

    zone.ondragleave = () => {
      zone.classList.remove("drag-over");
    };

    zone.ondrop = (e) => {
      e.preventDefault();
      zone.classList.remove("drag-over");

      if (!draggedTask) return;

      const to = zone.id;
      const index = currentBoard[to].length;

      socket.emit("task:move", {
        taskId: draggedTask.id,
        from: draggedTask.from,
        to,
        index
      });

      draggedTask = null;
    };
  });
}
