const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boardState = {
  todo: [
    { id: "1", text: "Set up project", createdAt: Date.now() },
    { id: "2", text: "Build task board UI", createdAt: Date.now() }
  ],
  doing: [
    { id: "3", text: "Add drag and drop", createdAt: Date.now() }
  ],
  done: []
};

io.on("connection", (socket) => {
  socket.emit("init", boardState);

  socket.on("addTask", (task) => {
    if (!task || !task.text) return;
    const newTask = {
      id: String(Date.now()) + Math.random().toString(36).slice(2),
      text: task.text.trim(),
      createdAt: Date.now()
    };
    boardState[task.column].push(newTask);
    io.emit("stateUpdate", boardState);
  });

  socket.on("moveTask", ({ taskId, fromColumn, toColumn, toIndex }) => {
    if (!taskId || !fromColumn || !toColumn) return;

    const fromList = boardState[fromColumn];
    const toList = boardState[toColumn];
    if (!fromList || !toList) return;

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex ?? toList.length, 0, task);

    io.emit("stateUpdate", boardState);
  });

  socket.on("deleteTask", ({ taskId, column }) => {
    const list = boardState[column];
    if (!list) return;

    boardState[column] = list.filter((task) => task.id !== taskId);
    io.emit("stateUpdate", boardState);
  });
});

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
