```js
const socket = io();

let boardState = {
  todo: [],
  doing: [],
  done: []
};

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");

const lists = {
  todo: document.getElementById("todoList"),
  doing: document.getElementById("doingList"),
  done: document.getElementById("doneList")
};

let draggedTask = null;

socket.on("init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("stateUpdate", (state) => {
  boardState = state;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const text = taskInput.value.trim();
  const column = columnSelect.value;

  if (!text) return;

  socket.emit("addTask", { text, column });
  taskInput.value = "";
});

function renderBoard() {
  Object.keys(lists).forEach((column) => {
    const listEl = lists[column];
    listEl.innerHTML = "";

    boardState[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${escapeHtml(task.text)}</span>
        <button data-delete="${task.id}">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column
        };
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("deleteTask", { taskId: task.id, column });
      });

      listEl.appendChild(taskEl);
    });

    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drag-over");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drag-over");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drag-over");

      if (!draggedTask) return;

      socket.emit("moveTask", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn: column,
        toIndex: boardState[column].length
      });

      draggedTask = null;
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
