## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "1", title: "Design UI" },
      { id: "2", title: "Set up backend" }
    ],
    doing: [
      { id: "3", title: "Build drag-and-drop" }
    ],
    done: [
      { id: "4", title: "Create repo" }
    ]
  }
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", (task) => {
    const newTask = {
      id: String(Date.now()),
      title: task.title || "Untitled task"
    };
    state.columns[task.column].push(newTask);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromList = state.columns[fromColumn];
    const toList = state.columns[toColumn];

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, column }) => {
    state.columns[column] = state.columns[column].filter((t) => t.id !== taskId);
    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

