```js
const socket = io();

let boardState = null;
let draggedTask = null;

const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskColumn = document.getElementById("taskColumn");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

socket.on("state:init", (state) => {
  boardState = state;
  render();
});

socket.on("state:update", (state) => {
  boardState = state;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  socket.emit("task:add", {
    title: taskTitle.value.trim(),
    column: taskColumn.value
  });
  taskTitle.value = "";
});

function render() {
  Object.keys(columns).forEach((col) => {
    columns[col].innerHTML = "";
    boardState.columns[col].forEach((task, index) => {
      const el = document.createElement("div");
      el.className = "task";
      el.draggable = true;
      el.dataset.id = task.id;
      el.dataset.column = col;
      el.dataset.index = index;
      el.innerHTML = `
        <button class="delete" title="Delete task">×</button>
        <div>${escapeHtml(task.title)}</div>
      `;

      el.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: col
        };
      });

      el.querySelector(".delete").addEventListener("click", (ev) => {
        ev.stopPropagation();
        socket.emit("task:delete", { taskId: task.id, column: col });
      });

      columns[col].appendChild(el);
    });
  });

  setupDropZones();
}

function setupDropZones() {
  Object.entries(columns).forEach(([colName, colEl]) => {
    colEl.ondragover = (e) => {
      e.preventDefault();
      colEl.classList.add("drag-over");
    };

    colEl.ondragleave = () => {
      colEl.classList.remove("drag-over");
    };

    colEl.ondrop = (e) => {
      e.preventDefault();
      colEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const targetTasks = Array.from(colEl.querySelectorAll(".task"));
      const toIndex = targetTasks.length; // minimal: append to end

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn: colName,
        toIndex
      });

      draggedTask = null;
    };
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
