## 6) `public/app.js`

```js
const socket = io();

let boardState = {
  todo: [],
  doing: [],
  done: []
};

const columns = ["todo", "doing", "done"];
const taskLists = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

const newTaskInput = document.getElementById("newTaskInput");
const addTaskBtn = document.getElementById("addTaskBtn");

function renderBoard() {
  columns.forEach((col) => {
    taskLists[col].innerHTML = "";
    boardState[col].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = col;

      taskEl.innerHTML = `
        <span>${task.title}</span>
        <button title="Delete">×</button>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", JSON.stringify({
          taskId: task.id,
          fromColumn: col
        }));
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        deleteTask(task.id, col);
      });

      taskLists[col].appendChild(taskEl);
    });
  });
}

function moveTask(taskId, fromColumn, toColumn) {
  if (fromColumn === toColumn) return;

  const taskIndex = boardState[fromColumn].findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = boardState[fromColumn].splice(taskIndex, 1);
  boardState[toColumn].push(task);

  socket.emit("task:moved", boardState);
  renderBoard();
}

function addTask(title) {
  const trimmed = title.trim();
  if (!trimmed) return;

  const task = {
    id: String(Date.now()),
    title: trimmed
  };

  boardState.todo.push(task);
  socket.emit("task:added", boardState);
  renderBoard();
}

function deleteTask(taskId, column) {
  boardState[column] = boardState[column].filter((t) => t.id !== taskId);
  socket.emit("task:deleted", boardState);
  renderBoard();
}

addTaskBtn.addEventListener("click", () => {
  addTask(newTaskInput.value);
  newTaskInput.value = "";
});

newTaskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    addTask(newTaskInput.value);
    newTaskInput.value = "";
  }
});

columns.forEach((col) => {
  const list = taskLists[col];

  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("drag-over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("drag-over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("drag-over");

    const data = JSON.parse(e.dataTransfer.getData("text/plain"));
    moveTask(data.taskId, data.fromColumn, col);
  });
});

socket.on("board:update", (updatedBoard) => {
  boardState = updatedBoard;
  renderBoard();
});

renderBoard();
```

