```js
const socket = io();

let state = {
  boards: {
    todo: [],
    doing: [],
    done: []
  }
};

const boardEl = document.getElementById("board");
const columns = ["todo", "doing", "done"];

function render() {
  columns.forEach((col) => {
    const container = document.getElementById(col);
    container.innerHTML = "";

    state.boards[col].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = col;
      taskEl.textContent = task.title;

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      container.appendChild(taskEl);
    });
  });
}

function findTask(taskId) {
  for (const col of columns) {
    const task = state.boards[col].find((t) => t.id === taskId);
    if (task) return { task, col };
  }
  return null;
}

function moveTask(taskId, targetCol) {
  const found = findTask(taskId);
  if (!found || found.col === targetCol) return;

  state.boards[found.col] = state.boards[found.col].filter(
    (t) => t.id !== taskId
  );
  state.boards[targetCol].push(found.task);

  socket.emit("updateState", state);
  render();
}

columns.forEach((col) => {
  const list = document.getElementById(col);

  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("drag-over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("drag-over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("drag-over");

    const taskEl = document.querySelector(".task.dragging");
    if (!taskEl) return;

    moveTask(taskEl.dataset.id, col);
  });
});

socket.on("state", (newState) => {
  state = newState;
  render();
});
