## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project" },
      { id: "t2", title: "Design UI" }
    ],
    doing: [
      { id: "t3", title: "Implement board" }
    ],
    done: []
  }
};

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

wss.on("connection", (ws) => {
  // Send current state to new client
  ws.send(JSON.stringify({ type: "state", state }));

  ws.on("message", (msg) => {
    try {
      const message = JSON.parse(msg.toString());

      if (message.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = message;

        const fromTasks = state.columns[fromColumn];
        const toTasks = state.columns[toColumn];
        if (!fromTasks || !toTasks) return;

        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        toTasks.splice(toIndex, 0, task);

        broadcast({ type: "state", state });
      }

      if (message.type === "add-task") {
        const { columnId, title } = message;
        if (!state.columns[columnId]) return;

        const task = {
          id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
          title
        };

        state.columns[columnId].push(task);
        broadcast({ type: "state", state });
      }

      if (message.type === "delete-task") {
        const { taskId } = message;
        for (const columnId of Object.keys(state.columns)) {
          const idx = state.columns[columnId].findIndex((t) => t.id === taskId);
          if (idx !== -1) {
            state.columns[columnId].splice(idx, 1);
            broadcast({ type: "state", state });
            break;
          }
        }
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

