```js
const ws = new WebSocket(`ws://${location.host}`);

let state = null;
let draggedTaskId = null;
let draggedFromColumn = null;

const board = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskTitle = document.getElementById("newTaskTitle");
const newTaskColumn = document.getElementById("newTaskColumn");

function render() {
  if (!state) return;

  for (const columnId of Object.keys(state.columns)) {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    state.columns[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;

      taskEl.innerHTML = `
        <span>${task.title}</span>
        <button title="Delete task">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumn = columnId;
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        ws.send(JSON.stringify({ type: "delete-task", taskId: task.id }));
      });

      list.appendChild(taskEl);
    });
  }
}

ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);

  if (message.type === "state") {
    state = message.state;
    render();
  }
});

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitle.value.trim();
  const columnId = newTaskColumn.value;

  if (!title) return;

  ws.send(JSON.stringify({
    type: "add-task",
    columnId,
    title
  }));

  newTaskTitle.value = "";
});

document.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("drag-over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("drag-over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("drag-over");

    if (!draggedTaskId || !draggedFromColumn) return;

    const toColumn = list.id;
    const tasks = state.columns[toColumn];
    const toIndex = tasks.length;

    ws.send(JSON.stringify({
      type: "move-task",
      taskId: draggedTaskId,
      fromColumn: draggedFromColumn,
      toColumn,
      toIndex
    }));

    draggedTaskId = null;
    draggedFromColumn = null;
  });
});
