## `internal/bus/bus.go`

A simple bounded pub/sub event bus. For very high scale, you’d likely replace this with NATS, Kafka, Aeron, or a custom ring buffer.

```go
package bus

import (
	"errors"
	"sync"
)

var ErrBusFull = errors.New("event bus full")

type Event struct {
	Topic string
	Key   string
	Value any
}

type Subscriber struct {
	ch chan Event
}

func (s *Subscriber) C() <-chan Event {
	return s.ch
}

type Bus struct {
	mu   sync.RWMutex
	subs map[string][]*Subscriber
	cap  int
}

func New(capacity int) *Bus {
	return &Bus{
		subs: make(map[string][]*Subscriber),
		cap:  capacity,
	}
}

func (b *Bus) Subscribe(topic string) *Subscriber {
	b.mu.Lock()
	defer b.mu.Unlock()

	sub := &Subscriber{ch: make(chan Event, b.cap)}
	b.subs[topic] = append(b.subs[topic], sub)
	return sub
}

func (b *Bus) Publish(evt Event) error {
	b.mu.RLock()
	subs := b.subs[evt.Topic]
	b.mu.RUnlock()

	for _, sub := range subs {
		select {
		case sub.ch <- evt:
		default:
			return ErrBusFull
		}
	}
	return nil
}
```

