## `internal/risk/risk.go`

```go
package risk

import (
	"errors"
	"sync"
)

var (
	ErrLimitExceeded = errors.New("risk limit exceeded")
	ErrInvalidOrder  = errors.New("invalid order")
)

type Order struct {
	ID       string
	Symbol   string
	Side     uint8
	Qty      float64
	Price    float64
	Account  string
}

type Limits struct {
	MaxOrderQty   float64
	MaxOrderValue float64
	MaxPosition   float64
}

type Engine struct {
	mu      sync.RWMutex
	limits  Limits
	pos     map[string]float64 // keyed by account:symbol
}

func New(l Limits) *Engine {
	return &Engine{
		limits: l,
		pos:    make(map[string]float64),
	}
}

func (e *Engine) Check(o Order) error {
	if o.Qty <= 0 || o.Price <= 0 || o.Symbol == "" || o.Account == "" {
		return ErrInvalidOrder
	}
	if o.Qty > e.limits.MaxOrderQty {
		return ErrLimitExceeded
	}
	if o.Qty*o.Price > e.limits.MaxOrderValue {
		return ErrLimitExceeded
	}
	return nil
}

func (e *Engine) ApplyFill(account, symbol string, side uint8, qty float64) {
	key := account + ":" + symbol
	e.mu.Lock()
	defer e.mu.Unlock()

	if side == 0 { // buy
		e.pos[key] += qty
	} else {
		e.pos[key] -= qty
	}
}

func (e *Engine) Position(account, symbol string) float64 {
	key := account + ":" + symbol
	e.mu.RLock()
	defer e.mu.RUnlock()
	return e.pos[key]
}
```

