## `internal/oms/oms.go`

```go
package oms

import (
	"sync"
	"time"

	"trading-platform/internal/risk"
)

type Status uint8

const (
	New Status = iota
	Accepted
	Rejected
	PartiallyFilled
	Filled
	Canceled
)

type Order struct {
	ID        string
	Account   string
	Symbol    string
	Side      uint8
	Qty       float64
	Price     float64
	Status    Status
	CreatedAt time.Time
}

type Fill struct {
	OrderID string
	Qty     float64
	Price   float64
	Time    time.Time
}

type Manager struct {
	mu     sync.RWMutex
	orders map[string]*Order
	risk   *risk.Engine
}

func New(r *risk.Engine) *Manager {
	return &Manager{
		orders: make(map[string]*Order),
		risk:   r,
	}
}

func (m *Manager) Submit(o Order) (Status, error) {
	if err := m.risk.Check(risk.Order{
		ID: o.ID, Symbol: o.Symbol, Side: o.Side, Qty: o.Qty, Price: o.Price, Account: o.Account,
	}); err != nil {
		o.Status = Rejected
		m.mu.Lock()
		m.orders[o.ID] = &o
		m.mu.Unlock()
		return Rejected, err
	}

	o.Status = Accepted
	m.mu.Lock()
	m.orders[o.ID] = &o
	m.mu.Unlock()
	return Accepted, nil
}

func (m *Manager) OnFill(f Fill, account, symbol string, side uint8) {
	m.risk.ApplyFill(account, symbol, side, f.Qty)

	m.mu.Lock()
	defer m.mu.Unlock()

	if ord, ok := m.orders[f.OrderID]; ok {
		ord.Status = Filled
	}
}

func (m *Manager) Get(id string) (*Order, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	o, ok := m.orders[id]
	return o, ok
}
