## `internal/execution/router.go`

```go
package execution

import (
	"context"
	"hash/fnv"
)

type Router struct {
	venues []Venue
}

func NewRouter(venues ...Venue) *Router {
	return &Router{venues: venues}
}

func (r *Router) Route(symbol string) Venue {
	if len(r.venues) == 0 {
		return nil
	}
	h := fnv.New32a()
	_, _ = h.Write([]byte(symbol))
	idx := int(h.Sum32()) % len(r.venues)
	return r.venues[idx]
}

func (r *Router) Send(ctx context.Context, o Order) error {
	v := r.Route(o.Symbol)
	if v == nil {
		return ErrVenueDown
	}
	return v.SendOrder(ctx, o)
}
