## `internal/persistence/wal.go`

Append-only write-ahead log for recovery/replay.

```go
package persistence

import (
	"bufio"
	"encoding/json"
	"os"
	"sync"
)

type WAL struct {
	mu   sync.Mutex
	f    *os.File
	w    *bufio.Writer
}

func Open(path string) (*WAL, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil {
		return nil, err
	}
	return &WAL{
		f: f,
		w: bufio.NewWriterSize(f, 1<<20),
	}, nil
}

func (l *WAL) Append(v any) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	if _, err := l.w.Write(append(b, '\n')); err != nil {
		return err
	}
	return l.w.Flush()
}

func (l *WAL) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := l.w.Flush(); err != nil {
		return err
	}
	return l.f.Close()
}
```

