```rust
use std::sync::atomic::{AtomicU64, Ordering};

use crate::types::{Order, Side};

pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    current_notional: AtomicU64, // store as scaled integer for speed
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            current_notional: AtomicU64::new(0),
        }
    }

    pub fn validate(&self, order: &Order, market_price: f64) -> bool {
        if order.qty <= 0.0 || order.qty > self.max_order_qty {
            return false;
        }

        let notional = order.qty * market_price;
        if notional > self.max_notional {
            return false;
        }

        true
    }

    pub fn reserve_notional(&self, amount: f64) {
        let scaled = (amount * 100.0) as u64;
        self.current_notional.fetch_add(scaled, Ordering::Relaxed);
    }

    pub fn release_notional(&self, amount: f64) {
        let scaled = (amount * 100.0) as u64;
        self.current_notional.fetch_sub(scaled, Ordering::Relaxed);
    }

    #[allow(dead_code)]
    pub fn _side_adjustment(&self, side: &Side) -> i32 {
        match side {
            Side::Buy => 1,
            Side::Sell => -1,
        }
    }
}
