        let spread = tick.ask - tick.bid;

        if spread > self.threshold {
            Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 1.0,
                order_type: OrderType::Limit,
                limit_price: Some(tick.bid),
                timestamp_ns: tick.timestamp_ns,
            })
        } else {
            None
        }
    }
}
