use tracing::{info, error};
use types::Event;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = EventBus::new(1024);
    let strategy = StrategyEngine::new(0.02);
    let risk = RiskEngine::new(1000.0, 100000.0);
    let exec = execution::ExecutionGateway::new();
    let order_manager = OrderManager::new(risk, exec, bus.clone());

    let md = MarketDataFeed::new(bus.clone());

    // Market data task
    tokio::spawn(async move {
        md.run().await;
    });

    // Event loop
    let mut rx = bus.subscribe();
    loop {
        match rx.recv().await {
            Ok(Event::Tick(tick)) => {
                info!("tick: {:?}", tick);

                if let Some(order) = strategy.on_tick(&tick) {
                    let om = &order_manager;
                    if let Err(e) = om.handle_order(order, tick.ask).await {
                        error!("order handling failed: {e:?}");
                    }
                }
            }
            Ok(Event::Execution(exec)) => {
                info!("execution: {:?}", exec);
            }
            Ok(Event::Order(_)) => {}
            Err(e) => {
                error!("bus error: {e:?}");
                break;
            }
        }
    }
}
