# 6) Event bus abstraction

## `src/infra/bus.rs`

```rust
use async_trait::async_trait;
use tokio::sync::mpsc;

#[async_trait]
pub trait EventBus<T: Send + 'static>: Send + Sync {
    async fn publish(&self, event: T) -> anyhow::Result<()>;
}

pub struct InMemoryBus<T: Send + 'static> {
    sender: mpsc::Sender<T>,
}

impl<T: Send + 'static> InMemoryBus<T> {
    pub fn new(buffer: usize) -> (Self, mpsc::Receiver<T>) {
        let (tx, rx) = mpsc::channel(buffer);
        (Self { sender: tx }, rx)
    }
}

#[async_trait]
impl<T: Send + 'static> EventBus<T> for InMemoryBus<T> {
    async fn publish(&self, event: T) -> anyhow::Result<()> {
        self.sender.send(event).await?;
        Ok(())
    }
}
```

