# 7) Risk engine

## `src/engine/risk.rs`

```rust
use crate::domain::{order::{Order, OrderType}, risk::RiskLimits};

#[derive(Debug)]
pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn validate_order(&self, order: &Order, current_position: f64) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("Quantity must be positive".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!(
                "Order qty {} exceeds max_order_qty {}",
                order.qty, self.limits.max_order_qty
            ));
        }

        let projected_position = match order.side {
            crate::domain::order::Side::Buy => current_position + order.qty,
            crate::domain::order::Side::Sell => current_position - order.qty,
        };

        if projected_position.abs() > self.limits.max_position {
            return Err(format!(
                "Projected position {} exceeds max_position {}",
                projected_position, self.limits.max_position
            ));
        }

        if let OrderType::Limit { price } = order.order_type {
            let notional = price * order.qty;
            if notional > self.limits.max_notional {
                return Err(format!(
                    "Notional {} exceeds max_notional {}",
                    notional, self.limits.max_notional
                ));
            }
        }

        Ok(())
    }
}
```

