# 8) OMS / order lifecycle

## `src/engine/oms.rs`

```rust
use std::collections::HashMap;
use crate::domain::order::{Order, OrderStatus};
use uuid::Uuid;

#[derive(Debug)]
pub struct OrderManager {
    orders: HashMap<Uuid, Order>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn insert(&mut self, mut order: Order) {
        order.status = OrderStatus::Accepted;
        self.orders.insert(order.id, order);
    }

    pub fn reject(&mut self, order_id: Uuid, reason: String) {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.status = OrderStatus::Rejected { reason };
        }
    }

    pub fn mark_sent(&mut self, order_id: Uuid) {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.status = OrderStatus::Sent;
        }
    }

    pub fn mark_filled(&mut self, order_id: Uuid, qty: f64, avg_price: f64) {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.status = OrderStatus::Filled { qty, avg_price };
        }
    }

    pub fn get(&self, order_id: &Uuid) -> Option<&Order> {
        self.orders.get(order_id)
    }
}
```

