# 9) Strategy engine example

## `src/engine/strategy.rs`

```rust
use crate::domain::{market_data::Tick, order::{Order, OrderType, Side}};
use uuid::Uuid;

pub struct StrategyEngine {
    pub symbol: String,
    pub spread_threshold: f64,
}

impl StrategyEngine {
    pub fn new(symbol: impl Into<String>, spread_threshold: f64) -> Self {
        Self {
            symbol: symbol.into(),
            spread_threshold,
        }
    }

    pub fn on_tick(&self, tick: &Tick) -> Option<Order> {
        if tick.symbol != self.symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread > self.spread_threshold {
            let mid = (tick.bid + tick.ask) / 2.0;
            Some(Order {
                id: Uuid::new_v4(),
                client_order_id: format!("strat-{}", tick.ts_ns),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                order_type: OrderType::Limit { price: mid },
                qty: 1.0,
                status: crate::domain::order::OrderStatus::New,
                timestamp_ns: tick.ts_ns,
            })
        } else {
            None
        }
    }
}
```

