# 10) Main event loop

## `src/main.rs`

```rust
mod api;
mod config;
mod domain;
mod engine;
mod infra;

use crate::{
    domain::{events::Event, market_data::Tick, order::{Order, Side, OrderType}, risk::RiskLimits},
    engine::{oms::OrderManager, risk::RiskEngine, strategy::StrategyEngine},
    infra::bus::InMemoryBus,
};
use tokio::sync::mpsc;
use tracing::{info, error};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (bus, mut rx) = InMemoryBus::<Event>::new(10_000);

    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_notional: 50_000.0,
        max_position: 1_000.0,
        max_orders_per_sec: 100,
    });

    let mut oms = OrderManager::new();
    let strategy = StrategyEngine::new("AAPL", 0.05);

    // Simulated market data feed
    let bus_clone = bus;
    tokio::spawn(async move {
        let tick = Tick {
            symbol: "AAPL".to_string(),
            bid: 100.00,
            ask: 100.10,
            bid_size: 500.0,
            ask_size: 400.0,
            ts_ns: now_ns(),
        };

        if let Err(e) = bus_clone.publish(Event::MarketData(tick)).await {
            error!("publish error: {e}");
        }
    });

    while let Some(event) = rx.recv().await {
        match event {
            Event::MarketData(tick) => {
                info!("tick received: {:?}", tick);

                if let Some(order) = strategy.on_tick(&tick) {
                    handle_new_order(order, &risk, &mut oms).await;
                }
            }
            Event::NewOrder(order) => {
                handle_new_order(order, &risk, &mut oms).await;
            }
            _ => {}
        }
    }

    Ok(())
}

async fn handle_new_order(order: Order, risk: &RiskEngine, oms: &mut OrderManager) {
    let current_position = 0.0; // replace with real position service lookup

    match risk.validate_order(&order, current_position) {
        Ok(_) => {
            oms.insert(order.clone());
            tracing::info!("order accepted: {}", order.id);

            // send to execution adapter here
            oms.mark_sent(order.id);
            tracing::info!("order sent: {}", order.id);
        }
        Err(reason) => {
            tracing::warn!("order rejected: {} reason={}", order.id, reason);
            oms.reject(order.id, reason);
        }
    }
}

fn now_ns() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
