### `RingBufferEventBus.java`

```java
package com.example.trading.engine;

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReferenceArray;

public final class RingBufferEventBus<T> implements EventBus<T> {
    private final AtomicReferenceArray<T> buffer;
    private final int mask;
    private final AtomicLong writeSeq = new AtomicLong(0);
    private final AtomicLong readSeq = new AtomicLong(0);

    public RingBufferEventBus(int capacityPowerOfTwo) {
        if (Integer.bitCount(capacityPowerOfTwo) != 1) {
            throw new IllegalArgumentException("capacity must be power of two");
        }
        this.buffer = new AtomicReferenceArray<>(capacityPowerOfTwo);
        this.mask = capacityPowerOfTwo - 1;
    }

    @Override
    public boolean publish(T event) {
        long w = writeSeq.get();
        long r = readSeq.get();
        if (w - r >= buffer.length()) {
            return false;
        }
        int idx = (int) (w & mask);
        buffer.set(idx, event);
        writeSeq.lazySet(w + 1);
        return true;
    }

    @Override
    public T poll() {
        long r = readSeq.get();
        if (r >= writeSeq.get()) {
            return null;
        }
        int idx = (int) (r & mask);
        T event = buffer.get(idx);
        buffer.set(idx, null);
        readSeq.lazySet(r + 1);
        return event;
    }
}
```

> This is a simple example. For real low latency, consider **Disruptor**, **Agrona**, or a custom SPSC/MPSC design depending on topology.

