### `TradingEngine.java`

```java
package com.example.trading.engine;

import com.example.trading.config.TradingConfig;
import com.example.trading.marketdata.MarketDataEvent;
import com.example.trading.order.MockExchangeClient;
import com.example.trading.order.Order;
import com.example.trading.order.OrderRouter;
import com.example.trading.risk.RiskDecision;
import com.example.trading.risk.RiskEngine;
import com.example.trading.strategy.SimpleMomentumStrategy;
import com.example.trading.strategy.Strategy;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

public final class TradingEngine {
    private final TradingConfig config;
    private final EventBus<MarketDataEvent> marketDataBus;
    private final Strategy strategy;
    private final RiskEngine riskEngine;
    private final OrderRouter orderRouter;
    private final ExecutorService worker;
    private final AtomicBoolean running = new AtomicBoolean(false);

    public TradingEngine(TradingConfig config) {
        this.config = config;
        this.marketDataBus = new RingBufferEventBus<>(config.ringBufferSize);
        this.strategy = new SimpleMomentumStrategy();
        this.riskEngine = new RiskEngine(config);
        this.orderRouter = new OrderRouter(new MockExchangeClient());
        this.worker = Executors.newSingleThreadExecutor();
    }

    public void start() {
        if (!running.compareAndSet(false, true)) return;

        worker.submit(() -> {
            while (running.get()) {
                MarketDataEvent event = marketDataBus.poll();
                if (event == null) {
                    Thread.onSpinWait();
                    continue;
                }

                Order order = strategy.onMarketData(event);
                if (order == null) continue;

                double marketPrice = event.last;
                if (riskEngine.check(order, marketPrice) == RiskDecision.ALLOW) {
                    orderRouter.route(order);
                }
            }
        });

        // Demo feed
        new Thread(() -> {
            long ts = System.nanoTime();
            for (int i = 0; i < 1_000_000 && running.get(); i++) {
                MarketDataEvent ev = new MarketDataEvent("AAPL", ts + i, 100.0 + (i % 10) * 0.1, 100.1, 100.05 + (i % 10) * 0.1);
                while (!marketDataBus.publish(ev)) {
                    Thread.onSpinWait();
                }
            }
        }, "demo-feed").start();
    }

    public void stop() {
        running.set(false);
        worker.shutdownNow();
    }
}
```

