## 7) Strategy engine

A simple example strategy: if spread is small and price crosses a threshold, emit an order.

### `src/strategy.rs`
```rust
use crate::bus::EventBus;
use crate::types::{Event, Order, OrderType, Side, Tick};
use uuid::Uuid;

pub struct StrategyEngine {
    bus: EventBus,
    symbol: String,
    threshold: f64,
    qty: f64,
}

impl StrategyEngine {
    pub fn new(bus: EventBus, symbol: impl Into<String>, threshold: f64, qty: f64) -> Self {
        Self {
            bus,
            symbol: symbol.into(),
            threshold,
            qty,
        }
    }

    pub fn on_tick(&self, tick: Tick) {
        if tick.symbol != self.symbol {
            return;
        }

        let mid = (tick.bid + tick.ask) / 2.0;
        let spread = tick.ask - tick.bid;

        if spread <= self.threshold {
            let side = if tick.last < mid { Side::Buy } else { Side::Sell };

            let order = Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol,
                side,
                order_type: OrderType::Limit,
                qty: self.qty,
                limit_price: Some(mid),
                ts_nanos: tick.ts_nanos,
            };

            self.bus.publish(Event::Signal(order));
        }
    }
}
```

