## 8) Risk engine

Fast pre-trade checks.

### `src/risk.rs`
```rust
use crate::types::{Order, RiskLimits};

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn validate(&self, order: &Order) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!(
                "qty {} exceeds max_order_qty {}",
                order.qty, self.limits.max_order_qty
            ));
        }

        let px = order.limit_price.unwrap_or(0.0);
        let notional = px * order.qty;

        if notional > self.limits.max_notional {
            return Err(format!(
                "notional {} exceeds max_notional {}",
                notional, self.limits.max_notional
            ));
        }

        Ok(())
    }
}
```

