## 9) OMS

Tracks accepted orders and updates.

### `src/oms.rs`
```rust
use crate::types::{Order, OrderStatus, OrderUpdate};
use dashmap::DashMap;
use uuid::Uuid;

pub struct OrderManager {
    orders: DashMap<Uuid, (Order, OrderStatus)>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: DashMap::new(),
        }
    }

    pub fn accept(&self, order: Order) {
        self.orders
            .insert(order.id, (order, OrderStatus::Accepted));
    }

    pub fn reject(&self, order: Order, reason: String) {
        self.orders
            .insert(order.id, (order, OrderStatus::Rejected(reason)));
    }

    pub fn update(&self, update: OrderUpdate) {
        if let Some(mut entry) = self.orders.get_mut(&update.order_id) {
            entry.1 = update.status;
        }
    }

    pub fn get_status(&self, id: &Uuid) -> Option<OrderStatus> {
        self.orders.get(id).map(|e| e.1.clone())
    }
}
```

