use crate::bus::EventBus;
use crate::types::{Event, Order, OrderStatus, OrderUpdate};
use tokio::time::{sleep, Duration};

pub struct ExecutionGateway {
    bus: EventBus,
}

impl ExecutionGateway {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub async fn send_order(&self, order: Order) {
        // Simulate venue ack latency
        sleep(Duration::from_millis(2)).await;

        self.bus.publish(Event::OrderUpdate(OrderUpdate {
            order_id: order.id,
            status: OrderStatus::Accepted,
            ts_nanos: now_nanos(),
        }));

        // Simulate fill
        sleep(Duration::from_millis(3)).await;

        self.bus.publish(Event::OrderUpdate(OrderUpdate {
            order_id: order.id,
            status: OrderStatus::Filled {
                avg_price: order.limit_price.unwrap_or(0.0),
                filled_qty: order.qty,
            },
            ts_nanos: now_nanos(),
        }));
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
