use crate::bus::EventBus;
use crate::types::{Event, Tick};
use tokio::time::{interval, Duration};

pub struct MarketDataFeed {
    bus: EventBus,
    symbol: String,
}

impl MarketDataFeed {
    pub fn new(bus: EventBus, symbol: impl Into<String>) -> Self {
        Self {
            bus,
            symbol: symbol.into(),
        }
    }

    pub async fn run(&self) {
        let mut iv = interval(Duration::from_millis(10));
        let mut px = 100.0;

        loop {
            iv.tick().await;
            px += 0.01;

            let tick = Tick {
                symbol: self.symbol.clone(),
                bid: px - 0.01,
                ask: px + 0.01,
                last: px,
                ts_nanos: now_nanos(),
            };

            self.bus.publish(Event::Tick(tick));
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
