## 12) Main event loop

This wires everything together.

### `src/main.rs`
```rust
mod bus;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;
mod types;

use bus::EventBus;
use execution::ExecutionGateway;
use market_data::MarketDataFeed;
use oms::OrderManager;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tracing::{error, info};
use types::{Event, RiskLimits};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (bus, rx) = EventBus::new();

    let strategy = StrategyEngine::new(bus.clone(), "AAPL", 0.05, 10.0);
    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 1000.0,
        max_notional: 100000.0,
    });
    let oms = OrderManager::new();
    let exec = ExecutionGateway::new(bus.clone());
    let md = MarketDataFeed::new(bus.clone(), "AAPL");

    tokio::spawn(async move {
        md.run().await;
    });

    let event_loop_bus = bus.clone();
    tokio::spawn(async move {
        while let Ok(event) = rx.recv() {
            match event {
                Event::Tick(tick) => {
                    strategy.on_tick(tick);
                }
                Event::Signal(order) => {
                    match risk.validate(&order) {
                        Ok(_) => {
                            oms.accept(order.clone());
                            let exec2 = ExecutionGateway::new(event_loop_bus.clone());
                            tokio::spawn(async move {
                                exec2.send_order(order).await;
                            });
                        }
                        Err(reason) => {
                            oms.reject(order.clone(), reason.clone());
                            event_loop_bus.publish(Event::OrderRejected {
                                order_id: order.id,
                                reason,
                            });
                        }
                    }
                }
                Event::OrderUpdate(update) => {
                    oms.update(update.clone());
                    info!("Order update: {:?}", update);
                }
                Event::OrderAccepted(order) => {
                    info!("Order accepted: {:?}", order.id);
                }
                Event::OrderRejected { order_id, reason } => {
                    error!("Order rejected {}: {}", order_id, reason);
                }
            }
        }
    });

    // Keep process alive
    loop {
        tokio::time::sleep(std::time::Duration::from_secs(60)).await;
    }
}
```

