## 3.2 Simple low-latency ring-buffer style bus

This is a simplified single-producer/single-consumer style example. In real systems, you’d likely use **Agrona**, **Disruptor**, or a custom MPSC/MPMC queue depending on topology.

```java
package com.example.trading.bus;

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReferenceArray;

public class RingBufferEventBus<T> implements EventBus<T> {
    private final AtomicReferenceArray<T> buffer;
    private final int mask;
    private final AtomicLong writeSeq = new AtomicLong(0);
    private final AtomicLong readSeq = new AtomicLong(0);
    private volatile EventHandler<T> handler;

    public RingBufferEventBus(int capacityPowerOfTwo) {
        if (Integer.bitCount(capacityPowerOfTwo) != 1) {
            throw new IllegalArgumentException("Capacity must be a power of two");
        }
        this.buffer = new AtomicReferenceArray<>(capacityPowerOfTwo);
        this.mask = capacityPowerOfTwo - 1;
    }

    @Override
    public boolean publish(T event) {
        long currentWrite = writeSeq.get();
        long currentRead = readSeq.get();

        if (currentWrite - currentRead >= buffer.length()) {
            return false; // full
        }

        int slot = (int) (currentWrite & mask);
        buffer.set(slot, event);
        writeSeq.lazySet(currentWrite + 1);
        return true;
    }

    @Override
    public void subscribe(EventHandler<T> handler) {
        this.handler = handler;
    }

    public void drain() {
        EventHandler<T> h = this.handler;
        if (h == null) return;

        while (true) {
            long currentRead = readSeq.get();
            long currentWrite = writeSeq.get();

            if (currentRead >= currentWrite) {
                break;
            }

            int slot = (int) (currentRead & mask);
            T event = buffer.getAndSet(slot, null);
            if (event != null) {
                h.onEvent(event);
            }
            readSeq.lazySet(currentRead + 1);
        }
    }
}
```

