## 3.6 Example strategy

A simple momentum-style strategy. This is only a placeholder for a real strategy.

```java
package com.example.trading.strategy;

import com.example.trading.marketdata.MarketDataEvent;
import com.example.trading.order.*;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class MomentumStrategy implements Strategy {
    private final AtomicLong orderIdGen = new AtomicLong(1);
    private final ConcurrentHashMap<String, Double> lastMid = new ConcurrentHashMap<>();

    @Override
    public Optional<Order> onMarketData(MarketDataEvent event) {
        double mid = (event.bidPrice() + event.askPrice()) / 2.0;
        Double prev = lastMid.put(event.symbol(), mid);

        if (prev == null) {
            return Optional.empty();
        }

        // Simple example: if price rises, buy; if falls, sell
        if (mid > prev * 1.0005) {
            return Optional.of(new Order(
                    orderIdGen.getAndIncrement(),
                    event.symbol(),
                    OrderSide.BUY,
                    OrderType.LIMIT,
                    event.askPrice(),
                    100,
                    System.nanoTime()
            ));
        } else if (mid < prev * 0.9995) {
            return Optional.of(new Order(
                    orderIdGen.getAndIncrement(),
                    event.symbol(),
                    OrderSide.SELL,
                    OrderType.LIMIT,
                    event.bidPrice(),
                    100,
                    System.nanoTime()
            ));
        }

        return Optional.empty();
    }
}
```

