package com.example.trading.risk;

import com.example.trading.order.Order;
import com.example.trading.order.OrderType;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class BasicRiskEngine implements RiskEngine {
    private final long maxOrderQty;
    private final double maxPrice;
    private final Map<String, Long> symbolExposure = new ConcurrentHashMap<>();

    public BasicRiskEngine(long maxOrderQty, double maxPrice) {
        this.maxOrderQty = maxOrderQty;
        this.maxPrice = maxPrice;
    }

    @Override
    public boolean validate(Order order) {
        if (order.quantity() <= 0 || order.quantity() > maxOrderQty) {
            return false;
        }
        if (order.type() == OrderType.LIMIT && (order.price() <= 0 || order.price() > maxPrice)) {
            return false;
        }

        // Very simplified exposure check
        symbolExposure.merge(order.symbol(), order.quantity(), Long::sum);
        return true;
    }
}
