## 3.9 Order manager

```java
package com.example.trading.order;

import com.example.trading.execution.ExecutionGateway;
import com.example.trading.risk.RiskEngine;

import java.util.concurrent.ConcurrentHashMap;

public class OrderManager {
    private final RiskEngine riskEngine;
    private final ExecutionGateway executionGateway;
    private final ConcurrentHashMap<Long, OrderState> states = new ConcurrentHashMap<>();

    public OrderManager(RiskEngine riskEngine, ExecutionGateway executionGateway) {
        this.riskEngine = riskEngine;
        this.executionGateway = executionGateway;
    }

    public boolean submit(Order order) {
        states.put(order.orderId(), OrderState.NEW);

        if (!riskEngine.validate(order)) {
            states.put(order.orderId(), OrderState.REJECTED);
            return false;
        }

        states.put(order.orderId(), OrderState.VALIDATED);
        executionGateway.send(order);
        states.put(order.orderId(), OrderState.SENT);
        return true;
    }

    public OrderState getState(long orderId) {
        return states.get(orderId);
    }
}
```

