                    System.nanoTime(),
                    100.0 + (i % 100) * 0.01,
                    100.01 + (i % 100) * 0.01,
                    1000,
                    1000
            );

            while (!marketDataBus.publish(event)) {
                marketDataBus.drain(); // backpressure handling
            }

            marketDataBus.drain();
        }
    }
}
