# src/bus.rs

A simple typed event bus using bounded channels.

```rust
use tokio::sync::mpsc;

pub struct EventBus<T> {
    tx: mpsc::Sender<T>,
}

impl<T> Clone for EventBus<T> {
    fn clone(&self) -> Self {
        Self {
            tx: self.tx.clone(),
        }
    }
}

impl<T> EventBus<T> {
    pub fn new(capacity: usize) -> (Self, mpsc::Receiver<T>) {
        let (tx, rx) = mpsc::channel(capacity);
        (Self { tx }, rx)
    }

    pub async fn publish(&self, event: T) -> Result<(), mpsc::error::SendError<T>> {
        self.tx.send(event).await
    }

    pub fn try_publish(&self, event: T) -> Result<(), mpsc::error::TrySendError<T>> {
        self.tx.try_send(event)
    }
}
