# src/risk.rs

Pre-trade risk checks.

```rust
use crate::types::{NewOrder, Quantity, Side};
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Quantity,
    pub max_position: Quantity,
}

#[derive(Debug, Default)]
pub struct PositionBook {
    positions: DashMap<String, Quantity>,
}

impl PositionBook {
    pub fn get(&self, symbol: &str) -> Quantity {
        *self.positions.get(symbol).map(|v| v.value()).unwrap_or(&0.0)
    }

    pub fn update(&self, symbol: &str, delta: Quantity) {
        self.positions
            .entry(symbol.to_string())
            .and_modify(|p| *p += delta)
            .or_insert(delta);
    }
}

#[derive(Clone)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: Arc<PositionBook>,
}

#[derive(Debug)]
pub enum RiskRejectReason {
    OrderTooLarge,
    PositionLimitExceeded,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits, positions: Arc<PositionBook>) -> Self {
        Self { limits, positions }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), RiskRejectReason> {
        if order.quantity > self.limits.max_order_qty {
            return Err(RiskRejectReason::OrderTooLarge);
        }

        let current_pos = self.positions.get(&order.symbol);
        let projected = match order.side {
            Side::Buy => current_pos + order.quantity,
            Side::Sell => current_pos - order.quantity,
        };

        if projected.abs() > self.limits.max_position {
            return Err(RiskRejectReason::PositionLimitExceeded);
        }

        Ok(())
    }
}
```

