# src/strategy.rs

A simple example strategy: mean-reversion on spread.

```rust
use crate::types::{Event, NewOrder, OrderType, Side};
use std::collections::HashMap;

pub struct StrategyEngine {
    next_order_id: u64,
    last_mid: HashMap<String, f64>,
    threshold_bps: f64,
}

impl StrategyEngine {
    pub fn new(threshold_bps: f64) -> Self {
        Self {
            next_order_id: 1,
            last_mid: HashMap::new(),
            threshold_bps,
        }
    }

    fn next_id(&mut self) -> u64 {
        let id = self.next_order_id;
        self.next_order_id += 1;
        id
    }

    pub fn on_event(&mut self, event: &Event) -> Option<NewOrder> {
        match event {
            Event::MarketTick(tick) => {
                let mid = (tick.bid + tick.ask) / 2.0;
                let prev_mid = self.last_mid.insert(tick.symbol.clone(), mid);

                if let Some(prev) = prev_mid {
                    let change_bps = ((mid - prev) / prev) * 10_000.0;

                    if change_bps.abs() > self.threshold_bps {
                        let side = if change_bps > 0.0 { Side::Sell } else { Side::Buy };

                        return Some(NewOrder {
                            client_order_id: self.next_id(),
                            symbol: tick.symbol.clone(),
                            side,
                            order_type: OrderType::Limit,
                            price: Some(mid),
                            quantity: 1.0,
                            ts_ns: tick.ts_ns,
                        });
                    }
                }

                None
            }
            _ => None,
        }
    }
}
```

