use crate::types::{NewOrder, OrderStatus, OrderUpdate};
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Default)]
pub struct OrderState {
    pub status: Option<OrderStatus>,
}

#[derive(Clone)]
pub struct Oms {
    orders: Arc<DashMap<u64, OrderState>>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: Arc::new(DashMap::new()),
        }
    }

    pub fn on_new_order(&self, order: &NewOrder) {
        self.orders.insert(order.client_order_id, OrderState {
            status: Some(OrderStatus::PendingNew),
        });
    }

    pub fn on_update(&self, update: &OrderUpdate) {
        if let Some(mut entry) = self.orders.get_mut(&update.client_order_id) {
            entry.status = Some(update.status.clone());
        }
    }
}
