use crate::types::MarketTick;
use tokio::sync::mpsc::Sender;
use tokio::time::{interval, Duration};

pub async fn run_mock_feed(tx: Sender<MarketTick>) {
    let mut timer = interval(Duration::from_millis(10));
    let mut px = 100.0;

    loop {
        timer.tick().await;
        px += 0.01;

        let tick = MarketTick {
            symbol: "AAPL".to_string(),
            bid: px - 0.01,
            ask: px + 0.01,
            bid_size: 100.0,
            ask_size: 100.0,
            ts_ns: current_time_ns(),
        };

        if tx.send(tick).await.is_err() {
            break;
        }
    }
}

fn current_time_ns() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
