    let (order_tx, mut order_rx) = mpsc::channel::<NewOrder>(1024);
    let (update_tx, mut update_rx) = mpsc::channel::<OrderUpdate>(1024);

    tokio::spawn(market_data::run_mock_feed(md_tx));

    let metrics_md = metrics.clone();
    let order_tx_clone = order_tx.clone();

    tokio::spawn(async move {
        while let Some(tick) = md_rx.recv().await {
            metrics_md.inc_ticks();
            let event = Event::MarketTick(tick);

            if let Some(order) = strategy.on_event(&event) {
                metrics_md.inc_generated();
                if order_tx_clone.send(order).await.is_err() {
                    break;
                }
            }
        }
    });

    let metrics_risk = metrics.clone();
    let oms_risk = oms.clone();
    let update_tx_risk = update_tx.clone();
    let exec_risk = exec.clone();

    tokio::spawn(async move {
        while let Some(order) = order_rx.recv().await {
            match risk.check_order(&order) {
                Ok(_) => {
                    oms_risk.on_new_order(&order);
                    metrics_risk.inc_sent();
                    let update = exec_risk.send_order(order.clone()).await;
                    if update_tx_risk.send(update).await.is_err() {
                        break;
                    }
                }
                Err(reason) => {
                    metrics_risk.inc_rejected();
                    error!("Order rejected: {:?}", reason);
                }
            }
        }
    });

    let oms_updates = oms.clone();
    tokio::spawn(async move {
        while let Some(update) = update_rx.recv().await {
            oms_updates.on_update(&update);
            info!("Order update: {:?}", update);
        }
    });

    tokio::signal::ctrl_c().await.unwrap();
    info!("Shutting down");
}
