# `src/risk.rs`

```rust
use std::sync::Arc;
use dashmap::DashMap;
use uuid::Uuid;

use crate::types::{Order, OrderStatus};

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: u64,
    max_notional: f64,
    positions: Arc<DashMap<String, i64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: u64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn validate_order(&self, order: &Order, market_price: f64) -> Result<(), String> {
        if order.qty == 0 {
            return Err("qty must be > 0".into());
        }
        if order.qty > self.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", self.max_order_qty));
        }

        let notional = order.qty as f64 * market_price;
        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional: {}", self.max_notional));
        }

        Ok(())
    }

    pub fn on_fill(&self, symbol: &str, filled_qty: i64) {
        self.positions
            .entry(symbol.to_string())
            .and_modify(|v| *v += filled_qty)
            .or_insert(filled_qty);
    }

    pub fn position(&self, symbol: &str) -> i64 {
        self.positions.get(symbol).map(|v| *v).unwrap_or(0)
    }

    pub fn reject_report(order_id: Uuid, reason: String, ts_nanos: u64) -> crate::types::ExecutionReport {
        crate::types::ExecutionReport {
            order_id,
            status: OrderStatus::Rejected(reason),
            filled_qty: 0,
            avg_price: None,
            ts_nanos,
        }
    }
}
