# `src/oms.rs`

```rust
use std::sync::Arc;
use tokio::sync::Mutex;

use crate::{
    bus::{Event, EventBus},
    execution::ExecutionGateway,
    risk::RiskEngine,
    types::{ExecutionReport, Order, OrderStatus},
};

#[derive(Clone)]
pub struct OrderManagementSystem {
    bus: EventBus,
    risk: RiskEngine,
    exec: ExecutionGateway,
    last_price: Arc<Mutex<f64>>,
}

impl OrderManagementSystem {
    pub fn new(bus: EventBus, risk: RiskEngine, exec: ExecutionGateway) -> Self {
        Self {
            bus,
            risk,
            exec,
            last_price: Arc::new(Mutex::new(100.0)),
        }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        while let Ok(event) = rx.recv().await {
            match event {
                Event::Tick(tick) => {
                    let mut lp = self.last_price.lock().await;
                    *lp = tick.last;
                }
                Event::NewOrder(order) => {
                    let price = *self.last_price.lock().await;

                    match self.risk.validate_order(&order, price) {
                        Ok(_) => {
                            let accepted = ExecutionReport {
                                order_id: order.id,
                                status: OrderStatus::Accepted,
                                filled_qty: 0,
                                avg_price: None,
                                ts_nanos: now_nanos(),
                            };
                            self.bus.publish(Event::ExecReport(accepted));

                            let exec = self.exec.clone();
                            let bus = self.bus.clone();
                            tokio::spawn(async move {
                                let report = exec.send_order(order).await;
                                bus.publish(Event::ExecReport(report));
                            });
                        }
                        Err(reason) => {
                            let report = RiskEngine::reject_report(order.id, reason, now_nanos());
                            self.bus.publish(Event::ExecReport(report));
                        }
                    }
                }
                Event::ExecReport(_) => {}
            }
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

