use uuid::Uuid;

use crate::{
    bus::{Event, EventBus},
    types::{Order, OrderType, Side},
};

#[derive(Clone)]
pub struct StrategyEngine {
    bus: EventBus,
}

impl StrategyEngine {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        while let Ok(event) = rx.recv().await {
            if let Event::Tick(tick) = event {
                let spread = tick.ask - tick.bid;

                if spread < 0.05 {
                    let order = Order {
                        id: Uuid::new_v4(),
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        order_type: OrderType::Market,
                        qty: 10,
                        limit_price: None,
                        ts_nanos: tick.ts_nanos,
                    };

                    self.bus.publish(Event::NewOrder(order));
                }
            }
        }
    }
}
