## `src/risk.rs`

```rust
use crate::types::{NewOrder, Side};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_notional: u64,
    pub max_position: i64,
}

#[derive(Debug)]
pub struct RiskState {
    pub position: i64,
    pub limits: RiskLimits,
}

impl RiskState {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            position: 0,
            limits,
        }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), String> {
        if order.qty == 0 {
            return Err("qty must be > 0".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!("qty exceeds limit: {}", order.qty));
        }

        let px = order.price.unwrap_or(0);
        let notional = order.qty.saturating_mul(px);
        if notional > self.limits.max_notional {
            return Err(format!("notional exceeds limit: {}", notional));
        }

        let projected_position = match order.side {
            Side::Buy => self.position + order.qty as i64,
            Side::Sell => self.position - order.qty as i64,
        };

        if projected_position.abs() > self.limits.max_position {
            return Err(format!(
                "projected position exceeds limit: {}",
                projected_position
            ));
        }

        Ok(())
    }

    pub fn on_fill(&mut self, side: Side, qty: u64) {
        match side {
            Side::Buy => self.position += qty as i64,
            Side::Sell => self.position -= qty as i64,
        }
    }
}
