        self.orders.insert(
            order.order_id,
            OrderRecord {
                order,
                status: OrderStatus::Pending,
            },
        );
    }

    pub fn ack(&mut self, order_id: OrderId) {
        if let Some(rec) = self.orders.get_mut(&order_id) {
            rec.status = OrderStatus::Acked;
        }
    }

    pub fn reject(&mut self, order_id: OrderId) {
        if let Some(rec) = self.orders.get_mut(&order_id) {
            rec.status = OrderStatus::Rejected;
        }
    }

    pub fn fill(&mut self, order_id: OrderId) {
        if let Some(rec) = self.orders.get_mut(&order_id) {
            rec.status = OrderStatus::Filled;
        }
    }
}
