## `src/main.rs`

This wires the components together.

```rust
mod bus;
mod matching;
mod oms;
mod risk;
mod strategy;
mod types;

use crossbeam::channel::TryRecvError;
use tracing::{info, warn};

use crate::matching::MatchingEngine;
use crate::oms::Oms;
use crate::risk::{RiskLimits, RiskState};
use crate::strategy::Strategy;
use crate::types::{Event, MarketData};

fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = bus::EventBus::<Event>::new(1024);

    let mut strategy = Strategy::new();
    let mut risk = RiskState::new(RiskLimits {
        max_order_qty: 1000,
        max_notional: 1_000_000,
        max_position: 10_000,
    });
    let mut oms = Oms::new();
    let mut matching = MatchingEngine::new();

    // Simulated market data feed
    let md = MarketData {
        symbol: "AAPL",
        bid: 100,
        ask: 103,
        ts_nanos: 1,
    };

    bus.tx.send(Event::MarketData(md)).unwrap();

    loop {
        match bus.rx.try_recv() {
            Ok(event) => match event {
                Event::MarketData(md) => {
                    info!("market data: {:?}", md);

                    if let Some(order) = strategy.on_market_data(&md) {
                        match risk.check_order(&order) {
                            Ok(_) => {
                                oms.submit(order.clone());
                                let fill = matching.process_order(order.clone());
                                if let Some(fill) = fill {
                                    risk.on_fill(order.side, fill.qty);
                                    oms.fill(fill.order_id);
                                    info!("fill: {:?}", fill);
                                }
                            }
                            Err(reason) => {
                                warn!("risk reject: {}", reason);
                                oms.reject(order.order_id);
                            }
                        }
                    }
                }
                Event::NewOrder(order) => {
                    info!("new order: {:?}", order);
                }
                Event::Fill(fill) => {
                    info!("fill event: {:?}", fill);
                }
                Event::Reject { order_id, reason } => {
                    warn!("reject {}: {}", order_id, reason);
                }
            },
            Err(TryRecvError::Empty) => break,
            Err(TryRecvError::Disconnected) => break,
        }
    }

    info!("done");
}
```

