#[derive(Clone)]
pub struct EventBus<T: Send + 'static> {
    tx: Sender<T>,
}

impl<T: Send + 'static> EventBus<T> {
    pub fn new() -> (Self, Receiver<T>) {
        let (tx, rx) = unbounded();
        (Self { tx }, rx)
