# 7) Risk engine

## src/risk.rs

```rust
use crate::domain::{Order, OrderType, RiskLimits, Side};

#[derive(Debug)]
pub enum RiskDecision {
    Accept,
    Reject(String),
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check_order(&self, order: &Order, market_price: Option<f64>) -> RiskDecision {
        if order.qty <= 0.0 {
            return RiskDecision::Reject("quantity must be > 0".into());
        }

        if order.qty > self.limits.max_order_qty {
            return RiskDecision::Reject(format!(
                "qty exceeds max_order_qty: {} > {}",
                order.qty, self.limits.max_order_qty
            ));
        }

        let ref_price = match (&order.order_type, market_price) {
            (OrderType::Limit { price }, _) => *price,
            (OrderType::Market, Some(px)) => px,
            (OrderType::Market, None) => {
                return RiskDecision::Reject("no market price for market order".into())
            }
        };

        let notional = order.qty * ref_price;
        if notional > self.limits.max_notional {
            return RiskDecision::Reject(format!(
                "notional exceeds max_notional: {} > {}",
                notional, self.limits.max_notional
            ));
        }

        match order.side {
            Side::Buy | Side::Sell => RiskDecision::Accept,
        }
    }
}
```

