use std::collections::HashMap;
use uuid::Uuid;

use crate::domain::{Order, OrderEvent, OrderStatus};

pub struct OrderManager {
    orders: HashMap<Uuid, OrderStatus>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn on_new_order(&mut self, order: &Order) -> OrderEvent {
        self.orders.insert(order.id, OrderStatus::Accepted);
        OrderEvent {
            order_id: order.id,
            status: OrderStatus::Accepted,
            timestamp_ms: order.timestamp_ms,
        }
    }

    pub fn on_reject(&mut self, order: &Order, reason: String) -> OrderEvent {
        self.orders
            .insert(order.id, OrderStatus::Rejected { reason: reason.clone() });
        OrderEvent {
            order_id: order.id,
            status: OrderStatus::Rejected { reason },
            timestamp_ms: order.timestamp_ms,
        }
    }

    pub fn on_fill(&mut self, order_id: Uuid, filled_qty: f64, avg_price: f64, ts: u64) -> OrderEvent {
        self.orders
            .insert(order_id, OrderStatus::Filled { filled_qty, avg_price });
        OrderEvent {
            order_id,
            status: OrderStatus::Filled {
                filled_qty,
                avg_price,
            },
            timestamp_ms: ts,
        }
    }
}
