use uuid::Uuid;

use crate::domain::{MarketTick, Order, OrderType, Side};

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order>;
}

pub struct MeanReversionStrategy {
    pub symbol: String,
    pub buy_below: f64,
    pub sell_above: f64,
    pub order_qty: f64,
    pub client_id: String,
}

impl Strategy for MeanReversionStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        if tick.symbol != self.symbol {
            return None;
        }

        if tick.last < self.buy_below {
            Some(Order {
                id: Uuid::new_v4(),
                client_id: self.client_id.clone(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                order_type: OrderType::Market,
                timestamp_ms: tick.timestamp_ms,
            })
        } else if tick.last > self.sell_above {
            Some(Order {
                id: Uuid::new_v4(),
                client_id: self.client_id.clone(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.order_qty,
                order_type: OrderType::Market,
                timestamp_ms: tick.timestamp_ms,
            })
        } else {
            None
        }
    }
}
