use std::sync::Arc;

use crossbeam_channel::Receiver;
use tracing::{info, warn};

use crate::domain::{MarketTick, Order};
use crate::execution::ExecutionGateway;
use crate::metrics::Metrics;
use crate::oms::OrderManager;
use crate::risk::{RiskDecision, RiskEngine};
use crate::strategy::{MeanReversionStrategy, Strategy};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let metrics = Arc::new(Metrics::new());

    let risk_engine = RiskEngine::new(crate::domain::RiskLimits {
        max_order_qty: 1000.0,
        max_notional: 100_000.0,
    });

    let mut oms = OrderManager::new();
    let exec = ExecutionGateway::new();

    let strategy = MeanReversionStrategy {
        symbol: "AAPL".into(),
        buy_below: 95.0,
        sell_above: 105.0,
        order_qty: 10.0,
        client_id: "strategy-1".into(),
    };

    let ticks = vec![
        MarketTick { symbol: "AAPL".into(), bid: 99.0, ask: 99.2, last: 99.1, timestamp_ms: 1 },
        MarketTick { symbol: "AAPL".into(), bid: 94.0, ask: 94.2, last: 94.1, timestamp_ms: 2 },
        MarketTick { symbol: "AAPL".into(), bid: 106.0, ask: 106.2, last: 106.1, timestamp_ms: 3 },
    ];

    for tick in ticks {
        if let Some(order) = strategy.on_tick(&tick) {
            metrics.inc_received();

            let market_price = Some(tick.last);
            match risk_engine.check_order(&order, market_price) {
                RiskDecision::Accept => {
                    metrics.inc_accepted();
                    let _ack = oms.on_new_order(&order);

                    let fill = exec.send_order(&order).await;
                    if let crate::domain::OrderStatus::Filled { filled_qty, avg_price } = fill.status {
                        metrics.inc_filled();
                        let _evt = oms.on_fill(order.id, filled_qty, avg_price, fill.timestamp_ms);
                        info!("filled order {:?}", order.id);
                    }
                }
                RiskDecision::Reject(reason) => {
                    metrics.inc_rejected();
                    let _rej = oms.on_reject(&order, reason.clone());
                    warn!("rejected order {:?}: {}", order.id, reason);
                }
            }
        }
    }

    info!(
        received = metrics.orders_received.load(std::sync::atomic::Ordering::Relaxed),
        accepted = metrics.orders_accepted.load(std::sync::atomic::Ordering::Relaxed),
        rejected = metrics.orders_rejected.load(std::sync::atomic::Ordering::Relaxed),
        filled = metrics.orders_filled.load(std::sync::atomic::Ordering::Relaxed),
        "run complete"
    );
}
