    let execution = ExecutionGateway::new(bus.clone(), risk.clone(), order_manager.clone());
    let strategy = StrategyEngine::new(bus.clone(), risk.clone(), execution.clone());
    let market_data = MarketDataGateway::new(bus.clone());

    // Spawn components
    tokio::spawn(async move { market_data.run().await; });
    tokio::spawn(async move { strategy.run().await; });
    tokio::spawn(async move { execution.run().await; });

    // Keep process alive
    loop {
        tokio::time::sleep(std::time::Duration::from_secs(60)).await;
    }
}
