```rust
use crate::types::{OrderRequest, Side};
use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct RiskManager {
    inner: Arc<Mutex<RiskState>>,
}

#[derive(Debug)]
struct RiskState {
    max_notional: f64,
    max_position: f64,
    current_position: f64,
    current_notional: f64,
    kill_switch: bool,
}

impl RiskManager {
    pub fn new(max_notional: f64, max_position: f64) -> Self {
        Self {
            inner: Arc::new(Mutex::new(RiskState {
                max_notional,
                max_position,
                current_position: 0.0,
                current_notional: 0.0,
                kill_switch: false,
            })),
        }
    }

    pub fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        let state = self.inner.lock().unwrap();

        if state.kill_switch {
            return Err("Kill switch active".into());
        }

        let px = order.price.unwrap_or(0.0);
        let notional = px * order.qty;

        if state.current_notional + notional > state.max_notional {
            return Err("Max notional exceeded".into());
        }

        let projected_pos = match order.side {
            Side::Buy => state.current_position + order.qty,
            Side::Sell => state.current_position - order.qty,
        };

        if projected_pos.abs() > state.max_position {
            return Err("Max position exceeded".into());
        }

        Ok(())
    }

    pub fn on_fill(&self, qty: f64, price: f64, side: &Side) {
        let mut state = self.inner.lock().unwrap();
        let signed_qty = match side {
            Side::Buy => qty,
            Side::Sell => -qty,
        };
        state.current_position += signed_qty;
        state.current_notional += qty * price;
    }

    pub fn trigger_kill_switch(&self) {
        let mut state = self.inner.lock().unwrap();
        state.kill_switch = true;
    }
}
