```rust
use crate::bus::EventBus;
use crate::order_manager::OrderManager;
use crate::risk::RiskManager;
use crate::types::{Event, OrderStatus, OrderUpdate};
use std::sync::Arc;
use tokio::time::{sleep, Duration};
use tracing::{info, warn};

#[derive(Clone)]
pub struct ExecutionGateway {
    bus: EventBus,
    risk: RiskManager,
    order_manager: OrderManager,
}

impl ExecutionGateway {
    pub fn new(bus: EventBus, risk: RiskManager, order_manager: OrderManager) -> Self {
        Self { bus, risk, order_manager }
    }

    pub async fn run(self) {
        loop {
            if let Some(event) = self.bus.try_consume() {
                match event {
                    Event::OrderRequest(order) => {
                        self.order_manager.register(&order);

                        match self.risk.check_order(&order) {
                            Ok(_) => {
                                info!("Sending order to venue: {:?}", order.id);

                                // Simulated exchange ack/fill
                                let ack = OrderUpdate {
                                    order_id: order.id,
                                    status: OrderStatus::Accepted,
                                    ts_nanos: now_nanos(),
                                };
                                self.order_manager.update(ack);

                                sleep(Duration::from_millis(2)).await;

                                let fill = OrderUpdate {
                                    order_id: order.id,
                                    status: OrderStatus::Filled {
                                        qty: order.qty,
                                        avg_price: order.price.unwrap_or(0.0),
                                    },
                                    ts_nanos: now_nanos(),
                                };
                                self.order_manager.update(fill.clone());
                                let _ = self.bus.publish(Event::OrderUpdate(fill));
                            }
                            Err(reason) => {
                                warn!("Order rejected: {}", reason);
                                let rej = OrderUpdate {
                                    order_id: order.id,
                                    status: OrderStatus::Rejected(reason),
                                    ts_nanos: now_nanos(),
                                };
                                self.order_manager.update(rej.clone());
                                let _ = self.bus.publish(Event::OrderUpdate(rej));
                            }
                        }
                    }
                    _ => {}
                }
            } else {
                sleep(Duration::from_micros(50)).await;
            }
        }
    }
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
