            if let Some(event) = self.bus.try_consume() {
                if let Event::MarketTick(tick) = event {
                    self.on_tick(tick).await;
                }
            } else {
                sleep(Duration::from_micros(50)).await;
            }
        }
    }

    async fn on_tick(&self, tick: MarketTick) {
        let spread = tick.ask - tick.bid;

        if spread > 0.05 {
            let order = OrderRequest {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 10.0,
                price: Some(tick.bid),
                order_type: OrderType::Limit,
            };

            let _ = self.bus.publish(Event::OrderRequest(order));
        }
    }
