### `internal/bus/bus.go`
A simple event bus abstraction. You can later swap this with Kafka, NATS, Redis Streams, or Aeron.

```go
package bus

import (
	"context"
	"sync"
)

type Event struct {
	Topic string
	Key   string
	Value any
}

type Bus interface {
	Publish(ctx context.Context, e Event) error
	Subscribe(topic string) <-chan Event
	Close() error
}

type InMemoryBus struct {
	mu     sync.RWMutex
	subs   map[string][]chan Event
	closed bool
}

func NewInMemoryBus() *InMemoryBus {
	return &InMemoryBus{
		subs: make(map[string][]chan Event),
	}
}

func (b *InMemoryBus) Publish(ctx context.Context, e Event) error {
	b.mu.RLock()
	defer b.mu.RUnlock()

	if b.closed {
		return context.Canceled
	}

	for _, ch := range b.subs[e.Topic] {
		select {
		case ch <- e:
		default:
			// drop or route to overflow buffer depending on policy
		}
	}
	return nil
}

func (b *InMemoryBus) Subscribe(topic string) <-chan Event {
	ch := make(chan Event, 1024)

	b.mu.Lock()
	defer b.mu.Unlock()

	if b.closed {
		close(ch)
		return ch
	}

	b.subs[topic] = append(b.subs[topic], ch)
	return ch
}

func (b *InMemoryBus) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()

	if b.closed {
		return nil
	}
	b.closed = true
	for _, chans := range b.subs {
		for _, ch := range chans {
			close(ch)
		}
	}
	return nil
}
