```go
package risk

import (
	"errors"
	"sync"

	"trading-platform/internal/model"
)

var (
	ErrInvalidQty   = errors.New("invalid quantity")
	ErrInvalidPrice = errors.New("invalid price")
	ErrLimitBreached = errors.New("risk limit breached")
)

type Limits struct {
	MaxOrderQty int64
	MaxNotional int64
}

type Engine struct {
	mu     sync.RWMutex
	limits Limits
}

func NewEngine(l Limits) *Engine {
	return &Engine{limits: l}
}

func (e *Engine) Validate(o model.Order) error {
	if o.Qty <= 0 || o.Qty > e.limits.MaxOrderQty {
		return ErrInvalidQty
	}
	if o.Type == model.Limit && o.Price <= 0 {
		return ErrInvalidPrice
	}

	notional := o.Qty * o.Price
	if o.Type == model.Market {
		// market orders need a different estimate in real systems
		notional = o.Qty * 1
	}
	if e.limits.MaxNotional > 0 && notional > e.limits.MaxNotional {
		return ErrLimitBreached
	}
	return nil
}
