### `internal/matching/orderbook.go`
A deterministic in-memory order book per symbol.

```go
package matching

import (
	"container/heap"
	"time"

	"trading-platform/internal/model"
)

type orderNode struct {
	order model.Order
	index int
}

type bidHeap []*orderNode
type askHeap []*orderNode

func (h bidHeap) Len() int            { return len(h) }
func (h bidHeap) Less(i, j int) bool  { return h[i].order.Price > h[j].order.Price }
func (h bidHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i]; h[i].index, h[j].index = i, j }
func (h *bidHeap) Push(x any)         { *h = append(*h, x.(*orderNode)) }
func (h *bidHeap) Pop() any           { old := *h; n := len(old); x := old[n-1]; *h = old[:n-1]; return x }

func (h askHeap) Len() int            { return len(h) }
func (h askHeap) Less(i, j int) bool  { return h[i].order.Price < h[j].order.Price }
func (h askHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i]; h[i].index, h[j].index = i, j }
func (h *askHeap) Push(x any)         { *h = append(*h, x.(*orderNode)) }
func (h *askHeap) Pop() any           { old := *h; n := len(old); x := old[n-1]; *h = old[:n-1]; return x }

type OrderBook struct {
	Symbol string
	bids   bidHeap
	asks   askHeap
}

func NewOrderBook(symbol string) *OrderBook {
	ob := &OrderBook{Symbol: symbol}
	heap.Init(&ob.bids)
	heap.Init(&ob.asks)
	return ob
}

func (ob *OrderBook) Add(order model.Order) []model.Fill {
	node := &orderNode{order: order}
	var fills []model.Fill

	if order.Side == model.Buy {
		for ob.asks.Len() > 0 && order.Qty > 0 {
			bestAsk := ob.asks[0]
			if order.Type == model.Limit && order.Price < bestAsk.order.Price {
				break
			}
			tradeQty := min(order.Qty, bestAsk.order.Qty)
			tradePrice := bestAsk.order.Price

			fills = append(fills, model.Fill{
				TradeID:   newTradeID(),
				OrderID:   order.ID,
				Symbol:    order.Symbol,
				Side:      order.Side,
				Price:     tradePrice,
				Qty:       tradeQty,
				Timestamp: time.Now(),
			})

			order.Qty -= tradeQty
			bestAsk.order.Qty -= tradeQty

			if bestAsk.order.Qty == 0 {
				heap.Pop(&ob.asks)
			} else {
				ob.asks[0] = bestAsk
				heap.Fix(&ob.asks, 0)
			}
		}
		if order.Qty > 0 && order.Type == model.Limit {
			heap.Push(&ob.bids, &orderNode{order: order})
		}
		return fills
	}

	for ob.bids.Len() > 0 && order.Qty > 0 {
		bestBid := ob.bids[0]
		if order.Type == model.Limit && order.Price > bestBid.order.Price {
			break
		}
		tradeQty := min(order.Qty, bestBid.order.Qty)
		tradePrice := bestBid.order.Price

		fills = append(fills, model.Fill{
			TradeID:   newTradeID(),
			OrderID:   order.ID,
			Symbol:    order.Symbol,
			Side:      order.Side,
			Price:     tradePrice,
			Qty:       tradeQty,
			Timestamp: time.Now(),
		})

		order.Qty -= tradeQty
		bestBid.order.Qty -= tradeQty

		if bestBid.order.Qty == 0 {
			heap.Pop(&ob.bids)
		} else {
			ob.bids[0] = bestBid
			heap.Fix(&ob.bids, 0)
		}
	}

	if order.Qty > 0 && order.Type == model.Limit {
		heap.Push(&ob.asks, &orderNode{order: order})
	}
	return fills
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}
