### `internal/matching/engine.go`
One engine instance can manage many books. For scaling, shard by symbol.

```go
package matching

import (
	"sync"

	"trading-platform/internal/model"
)

type Engine struct {
	mu    sync.RWMutex
	books map[string]*OrderBook
}

func NewEngine() *Engine {
	return &Engine{
		books: make(map[string]*OrderBook),
	}
}

func (e *Engine) getBook(symbol string) *OrderBook {
	e.mu.RLock()
	book := e.books[symbol]
	e.mu.RUnlock()
	if book != nil {
		return book
	}

	e.mu.Lock()
	defer e.mu.Unlock()
	if book = e.books[symbol]; book == nil {
		book = NewOrderBook(symbol)
		e.books[symbol] = book
	}
	return book
}

func (e *Engine) Process(order model.Order) []model.Fill {
	book := e.getBook(order.Symbol)
	return book.Add(order)
}
