HTTP order entrypoint. In production, you may prefer FIX, gRPC, or a binary protocol.

```go
package gateway

import (
	"encoding/json"
	"net/http"
	"time"

	"trading-platform/internal/bus"
	"trading-platform/internal/model"
	"trading-platform/internal/risk"
)

type Handler struct {
	Risk *risk.Engine
	Bus  bus.Bus
}

func (h *Handler) SubmitOrder(w http.ResponseWriter, r *http.Request) {
	var o model.Order
	if err := json.NewDecoder(r.Body).Decode(&o); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	o.Timestamp = time.Now()

	if err := h.Risk.Validate(o); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	if err := h.Bus.Publish(r.Context(), bus.Event{
		Topic: "orders.new",
		Key:   o.Symbol,
		Value: o,
	}); err != nil {
		http.Error(w, "failed to publish order", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusAccepted)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status": "accepted",
		"orderId": o.ID,
	})
}
