```go
package main

import (
	"context"
	"log"

	"trading-platform/internal/bus"
	"trading-platform/internal/matching"
	"trading-platform/internal/model"
)

func main() {
	b := bus.NewInMemoryBus()
	engine := matching.NewEngine()

	orders := b.Subscribe("orders.new")

	for ev := range orders {
		order, ok := ev.Value.(model.Order)
		if !ok {
			continue
		}
		fills := engine.Process(order)
		log.Printf("processed order=%s symbol=%s fills=%d\n", order.ID, order.Symbol, len(fills))

		_ = b.Publish(context.Background(), bus.Event{
			Topic: "orders.fills",
			Key:   order.Symbol,
			Value: fills,
		})
	}
}
