```rust
use crate::types::{Order, Side};
use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct RiskEngine {
    inner: Arc<Mutex<RiskState>>,
}

struct RiskState {
    max_notional: f64,
    max_order_notional: f64,
    current_exposure: f64,
}

impl RiskEngine {
    pub fn new(max_notional: f64, max_order_notional: f64) -> Self {
        Self {
            inner: Arc::new(Mutex::new(RiskState {
                max_notional,
                max_order_notional,
                current_exposure: 0.0,
            })),
        }
    }

    pub fn check_order(&self, order: &Order, market_price: f64) -> Result<(), String> {
        let notional = order.qty * market_price.abs();

        let state = self.inner.lock().unwrap();
        if notional > state.max_order_notional {
            return Err(format!("Order notional too large: {}", notional));
        }

        let projected = match order.side {
            Side::Buy => state.current_exposure + notional,
            Side::Sell => state.current_exposure - notional,
        };

        if projected.abs() > state.max_notional {
            return Err(format!("Exposure limit exceeded: {}", projected));
        }

        Ok(())
    }

    pub fn apply_fill(&self, fill_notional: f64, side: &Side) {
        let mut state = self.inner.lock().unwrap();
        match side {
            Side::Buy => state.current_exposure += fill_notional,
            Side::Sell => state.current_exposure -= fill_notional,
        }
    }
}
