use crate::bus::EventBus;
use crate::execution::MockExecutionGateway;
use crate::risk::RiskEngine;
use crate::types::{Event, Order, OrderEvent, OrderStatus, Tick};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct OrderManager {
    risk: RiskEngine,
    execution: MockExecutionGateway,
    bus: EventBus,
    state: Arc<Mutex<HashMap<String, f64>>>,
}

impl OrderManager {
    pub fn new(risk: RiskEngine, execution: MockExecutionGateway, bus: EventBus) -> Self {
        Self {
            risk,
            execution,
            bus,
            state: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub async fn run(&self) {
        let mut rx = self.bus.subscribe();

        while let Ok(event) = rx.recv().await {
            match event {
                Event::Tick(tick) => {
                    self.on_tick(tick).await;
                }
                Event::Order(order) => {
                    self.on_order(order).await;
                }
                Event::OrderEvent(order_event) => {
                    self.on_order_event(order_event).await;
                }
            }
        }
    }

    async fn on_tick(&self, tick: Tick) {
        let mut state = self.state.lock().unwrap();
        state.insert(tick.symbol, tick.last);
    }

    async fn on_order(&self, order: Order) {
        let price = {
            let state = self.state.lock().unwrap();
            *state.get(&order.symbol).unwrap_or(&0.0)
        };

        if let Err(reason) = self.risk.check_order(&order, price) {
            self.bus.publish(Event::OrderEvent(OrderEvent {
                order_id: order.id,
                status: OrderStatus::Rejected(reason),
                ts_ns: now_ns(),
            }));
            return;
        }

        self.execution.send_order(order).await;
    }

    async fn on_order_event(&self, evt: OrderEvent) {
        if let OrderStatus::Filled(qty) = evt.status {
            let _ = qty;
        }
    }
}

fn now_ns() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
