use crate::bus::EventBus;
use crate::types::{Event, Order, OrderType, Side, Tick};
use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use uuid::Uuid;

#[derive(Clone)]
pub struct MeanReversionStrategy {
    symbol: String,
    bus: EventBus,
    window: Arc<Mutex<VecDeque<f64>>>,
    order_manager: crate::order_manager::OrderManager,
}

impl MeanReversionStrategy {
    pub fn new(symbol: String, bus: EventBus, order_manager: crate::order_manager::OrderManager) -> Self {
        Self {
            symbol,
            bus,
            window: Arc::new(Mutex::new(VecDeque::with_capacity(64))),
            order_manager,
        }
    }

    pub async fn run(&self) {
        let mut rx = self.bus.subscribe();

        while let Ok(event) = rx.recv().await {
            if let Event::Tick(tick) = event {
                if tick.symbol == self.symbol {
                    self.on_tick(tick).await;
                }
            }
        }
    }

    async fn on_tick(&self, tick: Tick) {
        let mut w = self.window.lock().unwrap();
        w.push_back(tick.last);
        if w.len() > 20 {
            w.pop_front();
        }

        if w.len() < 20 {
            return;
        }

        let avg: f64 = w.iter().sum::<f64>() / w.len() as f64;
        let deviation = (tick.last - avg) / avg;

        if deviation > 0.001 {
            let order = Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: 0.01,
                order_type: OrderType::Market,
                limit_price: None,
                ts_ns: now_ns(),
            };
            self.bus.publish(Event::Order(order));
        } else if deviation < -0.001 {
            let order = Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 0.01,
                order_type: OrderType::Market,
                limit_price: None,
                ts_ns: now_ns(),
            };
            self.bus.publish(Event::Order(order));
        }
    }
}

fn now_ns() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
