use crate::domain::order::{Order, OrderType, Side};

#[derive(Debug)]
pub enum RiskError {
    InvalidQuantity,
    InvalidPrice,
    LimitExceeded,
    UnknownAccount,
}

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_notional: i64,
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn validate(&self, order: &Order) -> Result<(), RiskError> {
        if order.quantity == 0 {
            return Err(RiskError::InvalidQuantity);
        }

        if let OrderType::Limit = order.order_type {
            if order.price.is_none() {
                return Err(RiskError::InvalidPrice);
            }
        }

        if order.quantity > self.limits.max_order_qty {
            return Err(RiskError::LimitExceeded);
        }

        Ok(())
    }
}
