```rust
use std::collections::{BTreeMap, VecDeque};

use crate::domain::order::{Order, Side};

#[derive(Debug, Clone)]
pub struct Trade {
    pub buy_order_id: u64,
    pub sell_order_id: u64,
    pub quantity: u64,
    pub price: i64,
}

pub struct OrderBook {
    bids: BTreeMap<i64, VecDeque<Order>>, // price -> FIFO queue
    asks: BTreeMap<i64, VecDeque<Order>>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) -> Vec<Trade> {
        let mut trades = Vec::new();

        match order.side {
            Side::Buy => {
                // Match against asks
                // Simplified matching logic for starter implementation
                let mut incoming = order;
                while incoming.remaining() > 0 {
                    let best_ask_price = match self.asks.keys().next().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    if let Some(limit_price) = incoming.price {
                        if best_ask_price > limit_price {
                            break;
                        }
                    }

                    let mut remove_level = false;
                    if let Some(queue) = self.asks.get_mut(&best_ask_price) {
                        while incoming.remaining() > 0 {
                            let mut resting = match queue.pop_front() {
                                Some(o) => o,
                                None => {
                                    remove_level = true;
                                    break;
                                }
                            };

                            let qty = incoming.remaining().min(resting.remaining());
                            let trade_price = best_ask_price;

                            trades.push(Trade {
                                buy_order_id: incoming.order_id,
                                sell_order_id: resting.order_id,
                                quantity: qty,
                                price: trade_price,
                            });

                            incoming.filled_quantity += qty;
                            resting.filled_quantity += qty;

                            if resting.remaining() > 0 {
                                queue.push_front(resting);
                                break;
                            }
                        }
                        if queue.is_empty() {
                            remove_level = true;
                        }
                    }

                    if remove_level {
                        self.asks.remove(&best_ask_price);
                    }

                    if incoming.remaining() == 0 {
                        break;
                    }
                }

                if incoming.remaining() > 0 {
                    let price = incoming.price.unwrap_or(i64::MAX);
                    self.bids.entry(price).or_default().push_back(incoming);
                }
            }
            Side::Sell => {
                // Match against bids
                let mut incoming = order;
                while incoming.remaining() > 0 {
                    let best_bid_price = match self.bids.keys().next_back().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    if let Some(limit_price) = incoming.price {
                        if best_bid_price < limit_price {
                            break;
                        }
                    }

                    let mut remove_level = false;
                    if let Some(queue) = self.bids.get_mut(&best_bid_price) {
                        while incoming.remaining() > 0 {
                            let mut resting = match queue.pop_front() {
                                Some(o) => o,
                                None => {
                                    remove_level = true;
                                    break;
                                }
                            };

                            let qty = incoming.remaining().min(resting.remaining());
                            let trade_price = best_bid_price;

                            trades.push(Trade {
                                buy_order_id: resting.order_id,
                                sell_order_id: incoming.order_id,
                                quantity: qty,
                                price: trade_price,
                            });

                            incoming.filled_quantity += qty;
                            resting.filled_quantity += qty;

                            if resting.remaining() > 0 {
                                queue.push_front(resting);
                                break;
                            }
                        }
                        if queue.is_empty() {
                            remove_level = true;
                        }
                    }

                    if remove_level {
                        self.bids.remove(&best_bid_price);
                    }

                    if incoming.remaining() == 0 {
                        break;
                    }
                }

                if incoming.remaining() > 0 {
                    let price = incoming.price.unwrap_or(i64::MIN);
                    self.asks.entry(price).or_default().push_back(incoming);
                }
            }
        }

        trades
    }
}
```

