use crate::domain::order::{Order, OrderStatus};
use crate::matching::book::{OrderBook, Trade};
use crate::risk::{RiskEngine, RiskError};

pub enum OrderResult {
    Accepted(Vec<Trade>),
    Rejected(String),
}

pub struct OrderManager {
    risk: RiskEngine,
    book: OrderBook,
}

impl OrderManager {
    pub fn new(risk: RiskEngine, book: OrderBook) -> Self {
        Self { risk, book }
    }

    pub fn submit(&mut self, mut order: Order) -> OrderResult {
        match self.risk.validate(&order) {
            Ok(_) => {
                order.status = OrderStatus::Accepted;
                let trades = self.book.add_order(order);
                OrderResult::Accepted(trades)
            }
            Err(e) => OrderResult::Rejected(format!("Risk rejected: {:?}", e)),
        }
    }
}
```

