```rust
use crate::domain::order::{Order, OrderType};

#[derive(Debug)]
pub enum RiskError {
    InvalidQuantity,
    MissingPriceForLimitOrder,
    PriceOutOfRange,
}

pub fn validate_order(order: &Order) -> Result<(), RiskError> {
    if order.quantity == 0 {
        return Err(RiskError::InvalidQuantity);
    }

    if matches!(order.order_type, OrderType::Limit) && order.price.is_none() {
        return Err(RiskError::MissingPriceForLimitOrder);
    }

    if let Some(price) = order.price {
        if price <= 0 {
            return Err(RiskError::PriceOutOfRange);
        }
    }

    Ok(())
}
