## `src/oms/engine.rs`

```rust
use std::collections::HashMap;
use tokio::sync::RwLock;

use crate::domain::order::{Order, OrderStatus};

pub struct OmsEngine {
    orders: RwLock<HashMap<String, Order>>,
}

impl OmsEngine {
    pub fn new() -> Self {
        Self {
            orders: RwLock::new(HashMap::new()),
        }
    }

    pub async fn submit(&self, mut order: Order) -> String {
        order.status = OrderStatus::Accepted;
        let order_id = order.order_id.clone();
        self.orders.write().await.insert(order_id.clone(), order);
        order_id
    }

    pub async fn cancel(&self, order_id: &str) -> bool {
        let mut orders = self.orders.write().await;
        if let Some(order) = orders.get_mut(order_id) {
            order.status = OrderStatus::Cancelled;
            true
        } else {
            false
        }
    }

    pub async fn get(&self, order_id: &str) -> Option<Order> {
        self.orders.read().await.get(order_id).cloned()
    }
}
