## `src/gateway/grpc.rs`

```rust
use tonic::{Request, Response, Status};
use uuid::Uuid;

use crate::domain::order::{Order, OrderStatus, OrderType, Side, TimeInForce};
use crate::oms::engine::OmsEngine;
use crate::risk::checks::validate_order;

pub mod trading {
    tonic::include_proto!("trading");
}

use trading::trading_gateway_server::TradingGateway;
use trading::{CancelRequest, CancelResponse, OrderRequest, OrderResponse};

pub struct GatewayService {
    oms: std::sync::Arc<OmsEngine>,
}

impl GatewayService {
    pub fn new(oms: std::sync::Arc<OmsEngine>) -> Self {
        Self { oms }
    }
}

#[tonic::async_trait]
impl TradingGateway for GatewayService {
    async fn submit_order(
        &self,
        request: Request<OrderRequest>,
    ) -> Result<Response<OrderResponse>, Status> {
        let req = request.into_inner();

        let side = match req.side.as_str() {
            "BUY" => Side::Buy,
            "SELL" => Side::Sell,
            _ => return Err(Status::invalid_argument("invalid side")),
        };

        let order_type = match req.order_type.as_str() {
            "MARKET" => OrderType::Market,
            "LIMIT" => OrderType::Limit,
            _ => return Err(Status::invalid_argument("invalid order_type")),
        };

        let tif = match req.tif.as_str() {
            "DAY" => TimeInForce::Day,
            "GTC" => TimeInForce::Gtc,
            "IOC" => TimeInForce::Ioc,
            "FOK" => TimeInForce::Fok,
            _ => return Err(Status::invalid_argument("invalid tif")),
        };

        let order = Order {
            order_id: Uuid::new_v4().to_string(),
            client_id: req.client_id,
            symbol: req.symbol,
            side,
            order_type,
            quantity: req.quantity,
            price: if req.price > 0 { Some(req.price) } else { None },
            time_in_force: tif,
            timestamp_ns: 0,
            status: OrderStatus::New,
        };

        validate_order(&order).map_err(|e| Status::invalid_argument(format!("{:?}", e)))?;

        let order_id = self.oms.submit(order).await;

        Ok(Response::new(OrderResponse {
            order_id,
            status: "ACCEPTED".to_string(),
            message: "order accepted".to_string(),
        }))
    }

    async fn cancel_order(
        &self,
        request: Request<CancelRequest>,
    ) -> Result<Response<CancelResponse>, Status> {
        let req = request.into_inner();

        let cancelled = self.oms.cancel(&req.order_id).await;
        if !cancelled {
            return Err(Status::not_found("order not found"));
        }

        Ok(Response::new(CancelResponse {
            order_id: req.order_id,
            status: "CANCELLED".to_string(),
            message: "order cancelled".to_string(),
        }))
    }
}
```

