```rust
mod config;
mod domain;
mod bus;
mod risk;
mod oms;
mod strategy;
mod execution;
mod market_data;
mod portfolio;
mod observability;

use tracing::info;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    observability::logging::init();

    let config = config::AppConfig::default();
    info!("Starting trading platform: {:?}", config);

    let bus = bus::event_bus::EventBus::new();

    let risk_engine = risk::risk_engine::RiskEngine::new(config.risk.clone());
    let oms = oms::oms::Oms::new();
    let portfolio = portfolio::portfolio::Portfolio::new();
    let execution_gateway = execution::execution_gateway::ExecutionGateway::new(bus.clone());

    let strategy = strategy::sample_strategy::SampleStrategy::new();
    let strategy_engine = strategy::strategy_engine::StrategyEngine::new(strategy, bus.clone());

    let market_data_gateway = market_data::market_data_gateway::MarketDataGateway::new(bus.clone());

    // Wire event consumers
    let mut rx = bus.subscribe();

    let risk_engine_task = tokio::spawn(async move {
        while let Ok(event) = rx.recv().await {
            match event {
                bus::event_bus::Event::OrderIntent(intent) => {
                    if let Err(e) = risk_engine.validate(&intent) {
                        tracing::warn!("Risk rejected order intent: {}", e);
                    }
                }
                bus::event_bus::Event::ExecutionReport(report) => {
                    // In a real system, OMS would update state here
                    tracing::info!("Execution report received: {:?}", report);
                }
                _ => {}
            }
        }
    });

    // Simulated market data feed
    let md_task = tokio::spawn(async move {
        market_data_gateway.simulate_feed().await;
    });

    let strategy_task = tokio::spawn(async move {
        strategy_engine.run().await;
    });

    let _ = tokio::join!(risk_engine_task, md_task, strategy_task);

    let _ = oms;
    let _ = portfolio;
    let _ = execution_gateway;

    Ok(())
}
```

