## `src/risk/risk_engine.rs`
```rust
use crate::config::RiskConfig;
use crate::domain::order::OrderIntent;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("order quantity exceeds limit")]
    QtyLimit,
    #[error("order notional exceeds limit")]
    NotionalLimit,
}

pub struct RiskEngine {
    config: RiskConfig,
}

impl RiskEngine {
    pub fn new(config: RiskConfig) -> Self {
        Self { config }
    }

    pub fn validate(&self, intent: &OrderIntent) -> Result<(), RiskError> {
        if intent.qty > self.config.max_order_qty {
            return Err(RiskError::QtyLimit);
        }

        if let Some(price) = intent.price {
            let notional = intent.qty * price;
            if notional > self.config.max_notional {
                return Err(RiskError::NotionalLimit);
            }
        }

        Ok(())
    }
}
