        let mut rx = self.bus.subscribe();

        while let Ok(event) = rx.recv().await {
            if let Event::MarketTick(tick) = event {
                if let Some(intent) = self.strategy.on_tick(&tick) {
                    self.bus.publish(Event::OrderIntent(intent));
                }
            }
        }
    }
}
