// crates/strategy/src/engine.rs

use crate::signals::StrategySignal;
use common::types::{MarketTick, Side};

pub struct StrategyEngine {
    pub symbol: String,
    pub threshold: f64,
}

impl StrategyEngine {
    pub fn on_tick(&self, tick: &MarketTick) -> Option<StrategySignal> {
        let spread = tick.ask - tick.bid;

        if tick.symbol != self.symbol {
            return None;
        }

        if spread > self.threshold {
            Some(StrategySignal {
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                confidence: 0.7,
            })
        } else {
            None
        }
    }
}
