## 6.4 Risk engine

```rust
// crates/risk/src/checks.rs

use common::types::{OrderRequest, OrderType};

pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

pub struct RiskEngine {
    pub limits: RiskLimits,
}

impl RiskEngine {
    pub fn approve(&self, order: &OrderRequest, mid_price: f64) -> Result<(), String> {
        if order.qty > self.limits.max_order_qty {
            return Err("order qty exceeds limit".into());
        }

        let px = match order.order_type {
            OrderType::Market => mid_price,
            OrderType::Limit { price } => price,
        };

        let notional = order.qty * px;
        if notional > self.limits.max_notional {
            return Err("order notional exceeds limit".into());
        }

        Ok(())
    }
}
```

