// apps/trading_daemon/src/main.rs

use common::{
    types::{MarketTick, OrderRequest, OrderType, Side},
    EventBus,
};
use risk::{checks::{RiskEngine, RiskLimits}};
use strategy::{engine::StrategyEngine};
use execution::gateway::ExecutionGateway;
use tokio::time::{sleep, Duration};

#[tokio::main]
async fn main() {
    let market_bus: EventBus<MarketTick> = EventBus::new(1024);

    let strategy = StrategyEngine {
        symbol: "AAPL".to_string(),
        threshold: 0.05,
    };

    let risk = RiskEngine {
        limits: RiskLimits {
            max_order_qty: 100.0,
            max_notional: 50_000.0,
        },
    };

    let exec = ExecutionGateway;

    let mut rx = market_bus.subscribe();

    tokio::spawn(async move {
        loop {
            if let Ok(tick) = rx.recv().await {
                if let Some(signal) = strategy.on_tick(&tick) {
                    let order = OrderRequest {
                        order_id: rand::random(),
                        strategy_id: 1,
                        symbol: signal.symbol.clone(),
                        side: signal.side.clone(),
                        qty: 10.0,
                        order_type: OrderType::Market,
                    };

                    let mid = (tick.bid + tick.ask) / 2.0;

                    if risk.approve(&order, mid).is_ok() {
                        let _ = exec.submit_order(&order).await;
                    }
                }
            }
        }
    });

    // Simulated market data
    loop {
        market_bus.publish(MarketTick {
            symbol: "AAPL".to_string(),
            bid: 100.0,
            ask: 100.1,
            last: 100.05,
            ts_nanos: 0,
        });

        sleep(Duration::from_millis(10)).await;
    }
}
