pub struct OrderManager;

impl OrderManager {
    pub fn new() -> Self {
        Self
    }

    pub async fn run(self, bus: EventBus) {
        info!("order manager started");
        let rx = bus.subscribe();

        loop {
            match rx.recv() {
                Ok(Event::OrderIntent(intent)) => {
                    let order = Order {
                        order_id: Uuid::new_v4(),
                        intent,
                        order_type: OrderType::Limit,
                    };

                    bus.publish(Event::Order(order.clone()));

                    let report = ExecutionReport {
                        order_id: order.order_id,
                        status: ExecutionStatus::Ack,
                        filled_qty: 0.0,
                        avg_price: None,
                        reason: None,
                        ts_nanos: current_nanos(),
                    };

                    bus.publish(Event::ExecutionReport(report));
                }
                Ok(_) => {}
                Err(_) => break,
            }
        }
    }
}

fn current_nanos() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
