# 10. Risk engine

Keep risk checks fast and deterministic.

```rust
// src/engine/risk_engine.rs
use crate::domain::{order::Order, risk::RiskLimit};

pub struct RiskEngine {
    pub limit: RiskLimit,
    pub current_position: f64,
    pub current_notional: f64,
}

impl RiskEngine {
    pub fn new(limit: RiskLimit) -> Self {
        Self {
            limit,
            current_position: 0.0,
            current_notional: 0.0,
        }
    }

    pub fn validate_order(&self, order: &Order) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.limit.max_qty {
            return Err(format!("qty exceeds max_qty {}", self.limit.max_qty));
        }

        let price = order.price.unwrap_or(0.0);
        let notional = order.qty * price;

        if notional > self.limit.max_notional {
            return Err(format!("notional exceeds max_notional {}", self.limit.max_notional));
        }

        Ok(())
    }
}
```

