# 13. Main event loop

A simple single-threaded loop is a good first step for a low-latency core.

```rust
// src/main.rs
mod domain;
mod engine;
mod storage;

use domain::{order::{Order, Side, OrderType, OrderStatus}, risk::RiskLimit};
use engine::{event_bus::{EventBus, Event}, oms::Oms, risk_engine::RiskEngine, execution_gateway::ExecutionGateway};

fn main() {
    let bus = EventBus::new();

    let risk = RiskEngine::new(RiskLimit {
        max_notional: 1_000_000.0,
        max_qty: 10_000.0,
        max_position: 50_000.0,
    });

    let mut oms = Oms::new();
    let exec = ExecutionGateway::new();

    let order = Order {
        order_id: 1,
        client_id: "client-a".into(),
        instrument_id: "AAPL".into(),
        side: Side::Buy,
        qty: 100.0,
        price: Some(200.0),
        order_type: OrderType::Limit,
        status: OrderStatus::New,
        timestamp_ns: 0,
    };

    bus.tx.send(Event::NewOrder(order)).unwrap();

    while let Ok(event) = bus.rx.recv() {
        match event {
            Event::NewOrder(order) => {
                if let Err(reason) = risk.validate_order(&order) {
                    println!("Risk rejected order {}: {}", order.order_id, reason);
                    continue;
                }

                oms.submit(order.clone());

                match exec.route_order(&order) {
                    Ok(report) => {
                        println!("Execution report: {:?}", report);
                        oms.update_status(order.order_id, OrderStatus::Acked);
                    }
                    Err(reason) => {
                        println!("Routing failed: {}", reason);
                        oms.update_status(order.order_id, OrderStatus::Rejected);
                    }
                }
            }
            Event::MarketData(tick) => {
                println!("Market tick: {:?}", tick);
            }
            Event::ExecutionReport(report) => {
                println!("Received execution report: {:?}", report);
            }
            Event::RiskRejected { order_id, reason } => {
                println!("Risk rejected {}: {}", order_id, reason);
            }
        }
    }
}
```

