use crate::domain::MarketTick;
use crossbeam_channel::Sender;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

pub fn start_market_data_feed(tx: Sender<MarketTick>) {
    thread::spawn(move || {
        let mut price: i64 = 100_00; // $100.00 in cents
        loop {
            price += 1;

            let ts_nanos = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos() as u64;

            let tick = MarketTick {
                instrument_id: 1,
                bid: price - 1,
                ask: price + 1,
                bid_size: 100,
                ask_size: 100,
                ts_nanos,
            };

            if tx.send(tick).is_err() {
                break;
            }

            thread::sleep(Duration::from_millis(10));
        }
    });
}
