```rust
use crate::domain::{MarketTick, OrderIntent, Side};
use crossbeam_channel::{Receiver, Sender};
use std::thread;

pub fn start_strategy_engine(
    rx: Receiver<MarketTick>,
    tx: Sender<OrderIntent>,
) {
    thread::spawn(move || {
        while let Ok(tick) = rx.recv() {
            let spread = tick.ask - tick.bid;

            if spread <= 2 {
                let intent = OrderIntent {
                    instrument_id: tick.instrument_id,
                    side: Side::Buy,
                    price: tick.ask,
                    quantity: 10,
                    strategy_id: "mean_reversion_v1".to_string(),
                };

                if tx.send(intent).is_err() {
                    break;
                }
            }
        }
    });
}
