## `engine/risk_engine.rs`
```rust
use crate::domain::order::Order;
use crate::domain::risk::RiskLimit;

#[derive(Debug)]
pub enum RiskDecision {
    Allow,
    Reject(String),
}

pub struct RiskEngine {
    limits: RiskLimit,
}

impl RiskEngine {
    pub fn new(limits: RiskLimit) -> Self {
        Self { limits }
    }

    pub fn check_order(&self, order: &Order) -> RiskDecision {
        if order.quantity <= 0.0 {
            return RiskDecision::Reject("quantity must be positive".into());
        }

        if order.quantity > self.limits.max_order_qty {
            return RiskDecision::Reject("order quantity exceeds limit".into());
        }

        if let Some(price) = order.price {
            let notional = price * order.quantity;
            if notional > self.limits.max_notional {
                return RiskDecision::Reject("notional exceeds limit".into());
            }
        }

        RiskDecision::Allow
    }
}
```

