        bid: 189.95,
        ask: 190.00,
        last: 189.90,
        timestamp_ns: 1_000_000,
    };

    if let Some(order) = strategy.on_tick(&tick) {
        journal.append(&format!("strategy emitted order: {:?}", order));

        match risk.check_order(&order) {
            RiskDecision::Allow => {
                oms.accept_order(order.clone());
                journal.append(&format!("order accepted: {}", order.id));

                let exec_event = execution.route_order(&order);
                journal.append(&format!("execution event: {:?}", exec_event));

                oms.update_status(&order.id, OrderStatus::Accepted);
            }
            RiskDecision::Reject(reason) => {
                journal.append(&format!("order rejected: {} reason={}", order.id, reason));
            }
        }
    }
