use crate::domain::order::{NewOrder, OrderEvent, OrderStatus};
use crate::domain::risk::RiskLimits;

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn validate(&self, order: &NewOrder, mid_price: f64) -> Result<(), String> {
        if order.qty > self.limits.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", order.qty));
        }

        let notional = order.qty * mid_price;
        if notional > self.limits.max_notional {
            return Err(format!("notional exceeds max_notional: {}", notional));
        }

        Ok(())
    }

    pub fn reject(order_id: uuid::Uuid, reason: String, ts_nanos: u64) -> OrderEvent {
        OrderEvent {
            order_id,
            status: OrderStatus::Rejected { reason },
            ts_nanos,
        }
    }
}
```

