mod bus;
mod domain;
mod engine;
mod gateway;

use bus::event_bus::EventBus;
use domain::market_data::PriceTick;
use domain::risk::RiskLimits;
use engine::order_manager::OrderManager;
use engine::risk_engine::RiskEngine;
use engine::strategy_engine::StrategyEngine;
use gateway::market_data_gateway::MarketDataGateway;
use gateway::order_gateway::OrderGateway;
use tracing::{error, info};
use tracing_subscriber::EnvFilter;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    info!("starting trading platform");

    let md_bus = EventBus::<PriceTick>::new(1024);
    let md_gateway = MarketDataGateway::new(md_bus.clone());

    let strategy = StrategyEngine::new();
    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 10.0,
        max_notional: 100_000.0,
    });
    let order_manager = OrderManager::new();
    let order_gateway = OrderGateway::new();

    let mut rx = md_bus.subscribe();

    // Simulated market data feed
    tokio::spawn(async move {
        let tick = PriceTick {
            symbol: "AAPL".to_string(),
            bid: 189.99,
            ask: 190.00,
            last: 189.995,
            ts_nanos: current_ts_nanos(),
        };
        md_gateway.publish_tick(tick);
    });

    loop {
        match rx.recv().await {
            Ok(tick) => {
                if let Some(order) = strategy.on_tick(&tick) {
                    let mid = (tick.bid + tick.ask) / 2.0;
                    match risk.validate(&order, mid) {
                        Ok(_) => {
                            order_manager.place_order(&order);
                            order_gateway.send_order(&order).await;
                            info!(order_id = %order.id, "order accepted and sent");
                        }
                        Err(reason) => {
                            let rej = RiskEngine::reject(order.id, reason, current_ts_nanos());
                            error!(order_id = %rej.order_id, "order rejected");
                        }
                    }
                }
            }
            Err(e) => {
                error!(error = %e, "market data receive error");
                break;
            }
        }
    }
}

fn current_ts_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

