use tracing::{info, error};
use crate::bus::event_bus::EventBus;
use crate::services::{
    market_data_service::MarketDataService,
    strategy_service::StrategyService,
    risk_service::RiskService,
    order_manager::OrderManager,
    exchange_adapter::ExchangeAdapter,
};
use crate::storage::event_store::InMemoryEventStore;

#[tokio::main]
async fn main() {
    observability::init_tracing();

    info!("Starting trading platform");

    let bus = EventBus::new();
    let event_store = InMemoryEventStore::new();

    let market_data = MarketDataService::new(bus.clone());
    let strategy = StrategyService::new(bus.clone());
    let risk = RiskService::new(bus.clone());
    let order_manager = OrderManager::new(bus.clone());
    let exchange = ExchangeAdapter::new(bus.clone());

    // Wire the pipeline
    let md_handle = tokio::spawn(async move { market_data.run().await });
    let strat_handle = tokio::spawn(async move { strategy.run().await });
    let risk_handle = tokio::spawn(async move { risk.run().await });
    let om_handle = tokio::spawn(async move { order_manager.run().await });
    let ex_handle = tokio::spawn(async move { exchange.run().await });

    // Event store consumer
    let store_bus = bus.clone();
    let store_handle = tokio::spawn(async move {
        store_bus.subscribe_all(|evt| {
            event_store.append(evt);
        }).await;
    });

    let results = tokio::join!(md_handle, strat_handle, risk_handle, om_handle, ex_handle, store_handle);

    for r in results {
        if let Err(e) = r {
            error!("Task failed: {:?}", e);
        }
    }
}
```

