use crate::domain::events::Event;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct EventBus {
    tx: Arc<broadcast::Sender<Event>>,
}

impl EventBus {
    pub fn new() -> Self {
        let (tx, _) = broadcast::channel(10_000);
        Self { tx: Arc::new(tx) }
    }

    pub fn publish(&self, event: Event) {
        let _ = self.tx.send(event);
    }

    pub fn subscribe(&self) -> broadcast::Receiver<Event> {
        self.tx.subscribe()
    }

    pub async fn subscribe_all<F>(&self, mut handler: F)
    where
        F: FnMut(Event) + Send + 'static,
    {
        let mut rx = self.subscribe();
        loop {
            match rx.recv().await {
                Ok(evt) => handler(evt),
                Err(_) => break,
            }
        }
    }
}
