    bus::event_bus::EventBus,
    domain::{events::Event, orders::OrderIntent},
};
use tokio::sync::broadcast::error::RecvError;

pub struct RiskService {
    bus: EventBus,
    max_qty: f64,
}

impl RiskService {
    pub fn new(bus: EventBus) -> Self {
        Self { bus, max_qty: 100.0 }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::OrderIntent(intent)) => {
                    self.handle_intent(intent).await;
                }
                Ok(_) => {}
                Err(RecvError::Closed) => break,
                Err(RecvError::Lagged(_)) => continue,
            }
        }
    }

    async fn handle_intent(&self, intent: OrderIntent) {
        if intent.qty <= self.max_qty {
            self.bus.publish(Event::RiskApproved(intent));
        } else {
            self.bus.publish(Event::RiskRejected {
                intent_id: intent.id.to_string(),
                reason: "qty exceeds limit".to_string(),
            });
        }
    }
}
```

