use anyhow::Result;
use serde::{Deserialize, Serialize};
use tokio::sync::mpsc;
use tracing::{info, warn};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MarketDataEvent {
    pub symbol: String,
    pub bid: f64,
    pub ask: f64,
    pub timestamp_ns: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NewOrderEvent {
    pub client_order_id: Uuid,
    pub symbol: String,
    pub side: Side,
    pub qty: f64,
    pub limit_price: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RiskApprovedEvent {
    pub client_order_id: Uuid,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RiskRejectedEvent {
    pub client_order_id: Uuid,
    pub reason: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderAckEvent {
    pub client_order_id: Uuid,
    pub venue_order_id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderFillEvent {
    pub client_order_id: Uuid,
    pub venue_order_id: String,
    pub fill_qty: f64,
    pub fill_price: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PlatformEvent {
    MarketData(MarketDataEvent),
    NewOrder(NewOrderEvent),
    RiskApproved(RiskApprovedEvent),
    RiskRejected(RiskRejectedEvent),
    OrderAck(OrderAckEvent),
    OrderFill(OrderFillEvent),
}

#[derive(Debug, Default)]
pub struct RiskState {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

impl RiskState {
    pub fn check(&self, order: &NewOrderEvent) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }
        if order.qty > self.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", self.max_order_qty));
        }
        let notional = order.qty * order.limit_price;
        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional: {}", self.max_notional));
        }
        Ok(())
    }
}

#[derive(Debug, Default)]
pub struct OmsState {
    pub last_internal_id: u64,
}

impl OmsState {
    pub fn next_internal_id(&mut self) -> u64 {
        self.last_internal_id += 1;
        self.last_internal_id
    }
}

pub struct ExecutionGateway;

impl ExecutionGateway {
    pub async fn send_order(order: &NewOrderEvent, internal_id: u64) -> Result<String> {
        // Replace with FIX / OUCH / exchange-specific adapter.
        let venue_order_id = format!("VENUE-{}", internal_id);
        info!(
            "sending order to venue: client_order_id={}, internal_id={}, venue_order_id={}",
            order.client_order_id, internal_id, venue_order_id
        );
        Ok(venue_order_id)
    }
}

pub struct StrategyEngine;

impl StrategyEngine {
    pub fn on_market_data(md: &MarketDataEvent) -> Option<NewOrderEvent> {
        // Very simple example strategy:
        // Buy if spread is small and ask is below a threshold.
        let spread = md.ask - md.bid;
        if spread > 0.05 {
            return None;
        }

        if md.ask < 100.0 {
            Some(NewOrderEvent {
                client_order_id: Uuid::new_v4(),
                symbol: md.symbol.clone(),
                side: Side::Buy,
                qty: 1.0,
                limit_price: md.ask,
            })
        } else {
            None
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (event_tx, mut event_rx) = mpsc::channel::<PlatformEvent>(1024);

    let risk = RiskState {
        max_order_qty: 100.0,
        max_notional: 10_000.0,
    };
    let mut oms = OmsState::default();

    // Simulated market data producer
    let producer_tx = event_tx.clone();
    tokio::spawn(async move {
        let md = MarketDataEvent {
            symbol: "AAPL".to_string(),
            bid: 99.95,
            ask: 99.97,
            timestamp_ns: 1,
        };
        let _ = producer_tx.send(PlatformEvent::MarketData(md)).await;
    });

    while let Some(event) = event_rx.recv().await {
        match event {
            PlatformEvent::MarketData(md) => {
                info!("market data: {:?}", md);

                if let Some(order) = StrategyEngine::on_market_data(&md) {
                    let tx = event_tx.clone();
                    tokio::spawn(async move {
                        let _ = tx.send(PlatformEvent::NewOrder(order)).await;
                    });
                }
            }
            PlatformEvent::NewOrder(order) => {
                info!("new order: {:?}", order);

                match risk.check(&order) {
                    Ok(_) => {
                        let _ = event_tx
                            .send(PlatformEvent::RiskApproved(RiskApprovedEvent {
                                client_order_id: order.client_order_id,
                            }))
                            .await;

                        let internal_id = oms.next_internal_id();
                        let venue_order_id = ExecutionGateway::send_order(&order, internal_id).await?;

                        let _ = event_tx
                            .send(PlatformEvent::OrderAck(OrderAckEvent {
                                client_order_id: order.client_order_id,
                                venue_order_id,
                            }))
                            .await;
                    }
                    Err(reason) => {
                        warn!("risk rejected order: {}", reason);
                        let _ = event_tx
                            .send(PlatformEvent::RiskRejected(RiskRejectedEvent {
                                client_order_id: order.client_order_id,
                                reason,
                            }))
                            .await;
                    }
                }
            }
            PlatformEvent::RiskApproved(ev) => {
                info!("risk approved: {:?}", ev);
            }
            PlatformEvent::RiskRejected(ev) => {
                warn!("risk rejected: {:?}", ev);
            }
            PlatformEvent::OrderAck(ev) => {
                info!("order ack: {:?}", ev);
            }
            PlatformEvent::OrderFill(ev) => {
                info!("order fill: {:?}", ev);
            }
        }
    }

    Ok(())
}
```

