use tokio::sync::broadcast;

use crate::domain::{MarketTick, OrderIntent, OrderRequest, OrderUpdate};

#[derive(Clone)]
pub struct EventBus {
    pub market_tx: broadcast::Sender<MarketTick>,
    pub intent_tx: broadcast::Sender<OrderIntent>,
    pub order_tx: broadcast::Sender<OrderRequest>,
    pub update_tx: broadcast::Sender<OrderUpdate>,
}

impl EventBus {
    pub fn new(buffer: usize) -> Self {
        let (market_tx, _) = broadcast::channel(buffer);
        let (intent_tx, _) = broadcast::channel(buffer);
        let (order_tx, _) = broadcast::channel(buffer);
        let (update_tx, _) = broadcast::channel(buffer);

        Self {
            market_tx,
            intent_tx,
            order_tx,
            update_tx,
        }
    }
}
