use crate::domain::{MarketTick, OrderIntent, Side};

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderIntent>;
}

pub struct SimpleSpreadStrategy {
    pub max_spread: f64,
    pub order_qty: f64,
}

impl Strategy for SimpleSpreadStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderIntent> {
        let spread = tick.ask - tick.bid;
        if spread <= self.max_spread {
            Some(OrderIntent {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: Some(tick.bid),
            })
        } else {
            None
        }
    }
}
