## `src/risk.rs`

```rust
use std::sync::Arc;
use dashmap::DashMap;

use crate::domain::{OrderIntent, RiskDecision};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_position: f64,
    positions: Arc<DashMap<String, f64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_position: f64) -> Self {
        Self {
            max_order_qty,
            max_position,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn check(&self, intent: &OrderIntent) -> RiskDecision {
        if intent.qty > self.max_order_qty {
            return RiskDecision {
                approved: false,
                reason: Some("order qty exceeds max_order_qty".into()),
            };
        }

        let current_pos = self.positions.get(&intent.symbol).map(|v| *v).unwrap_or(0.0);
        let projected = match intent.side {
            crate::domain::Side::Buy => current_pos + intent.qty,
            crate::domain::Side::Sell => current_pos - intent.qty,
        };

        if projected.abs() > self.max_position {
            return RiskDecision {
                approved: false,
                reason: Some("projected position exceeds max_position".into()),
            };
        }

        RiskDecision {
            approved: true,
            reason: None,
        }
    }

    pub fn apply_fill(&self, symbol: &str, delta_qty: f64) {
        self.positions
            .entry(symbol.to_string())
            .and_modify(|v| *v += delta_qty)
            .or_insert(delta_qty);
    }
}
