```rust
mod bus;
mod domain;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;
mod telemetry;

use std::sync::Arc;

use bus::EventBus;
use domain::{OrderRequest, OrderType};
use execution::ExecutionGateway;
use oms::Oms;
use risk::RiskEngine;
use strategy::{SimpleSpreadStrategy, Strategy};
use tracing::{info, warn};
use uuid::Uuid;

#[tokio::main]
async fn main() {
    telemetry::init();

    let bus = EventBus::new(1024);
    let strategy = Arc::new(SimpleSpreadStrategy {
        max_spread: 0.05,
        order_qty: 1.0,
    });
    let risk = Arc::new(RiskEngine::new(10.0, 100.0));
    let oms = Arc::new(Oms::new());
    let exec = Arc::new(ExecutionGateway::new());

    // Simulated market data feed
    tokio::spawn(market_data::market_data_simulator(
        "AAPL".to_string(),
        bus.market_tx.clone(),
    ));

    // Strategy loop
    {
        let mut rx = bus.market_tx.subscribe();
        let intent_tx = bus.intent_tx.clone();
        let strategy = strategy.clone();

        tokio::spawn(async move {
            while let Ok(tick) = rx.recv().await {
                if let Some(intent) = strategy.on_tick(&tick) {
                    let _ = intent_tx.send(intent);
                }
            }
        });
    }

    // Risk + order creation loop
    {
        let mut rx = bus.intent_tx.subscribe();
        let order_tx = bus.order_tx.clone();
        let risk = risk.clone();

        tokio::spawn(async move {
            while let Ok(intent) = rx.recv().await {
                let decision = risk.check(&intent);
                if !decision.approved {
                    warn!("Risk rejected intent: {:?}", decision.reason);
                    continue;
                }

                let order = OrderRequest {
                    order_id: Uuid::new_v4(),
                    symbol: intent.symbol,
                    side: intent.side,
                    qty: intent.qty,
                    order_type: OrderType::Limit,
                    price: intent.price,
                };

                let _ = order_tx.send(order);
            }
        });
    }

    // Execution loop
    {
        let mut rx = bus.order_tx.subscribe();
        let update_tx = bus.update_tx.clone();
        let oms = oms.clone();
        let exec = exec.clone();

        tokio::spawn(async move {
            while let Ok(order) = rx.recv().await {
                oms.submit(&order);
                let ack = exec.send_order(&order).await;
                oms.on_update(&ack);
                let _ = update_tx.send(ack);
                info!("Order sent and acked: {:?}", order.order_id);
            }
        });
    }

    // Update consumer
    {
        let mut rx = bus.update_tx.subscribe();
        tokio::spawn(async move {
            while let Ok(update) = rx.recv().await {
                info!("Order update: {:?}", update);
            }
        });
    }

    // Keep running
    tokio::signal::ctrl_c().await.unwrap();
    info!("Shutting down");
}
```

