use crossbeam_channel::unbounded;
use tracing::{info, error};

use crate::domain::market_data::MarketDataEvent;
use crate::domain::order::OrderRequest;
use crate::domain::execution::ExecutionReport;

fn main() {
    observability::logging::init();

    let (md_tx, md_rx) = unbounded::<MarketDataEvent>();
    let (signal_tx, signal_rx) = unbounded::<OrderRequest>();
    let (order_tx, order_rx) = unbounded::<OrderRequest>();
    let (exec_tx, exec_rx) = unbounded::<ExecutionReport>();

    let risk_engine = risk::pre_trade::PreTradeRiskEngine::new(1000.0, 10_000);
    let strategy = strategy::example_strategy::ExampleStrategy::new("BTC-USD");
    let router = execution::router::OrderRouter::new(execution::mock_gateway::MockGateway::new());

    let state = state::portfolio::PortfolioState::new();

    // Strategy thread
    {
        let signal_tx = signal_tx.clone();
        std::thread::spawn(move || {
            for md in md_rx.iter() {
                if let Some(order) = strategy.on_market_data(&md) {
                    if let Err(e) = signal_tx.send(order) {
                        error!("failed to send strategy signal: {}", e);
                        break;
                    }
                }
            }
        });
    }

    // Risk + routing thread
    {
        let order_tx = order_tx.clone();
        std::thread::spawn(move || {
            for order in signal_rx.iter() {
                if risk_engine.check_order(&order) {
                    if let Err(e) = order_tx.send(order) {
                        error!("failed to send order: {}", e);
                        break;
                    }
                } else {
                    info!("order rejected by risk: {:?}", order);
                }
            }
        });
    }

    // Execution thread
    {
        let exec_tx = exec_tx.clone();
        std::thread::spawn(move || {
            for order in order_rx.iter() {
                let report = router.route(order);
                if let Err(e) = exec_tx.send(report) {
                    error!("failed to send execution report: {}", e);
                    break;
                }
            }
        });
    }

    // State update thread
    {
        let mut state = state;
        std::thread::spawn(move || {
            for report in exec_rx.iter() {
                state.on_execution_report(&report);
                info!("updated state: {:?}", state.summary());
            }
        });
    }

    // Simulated market data feed
    for i in 0..100 {
        let md = MarketDataEvent::new("BTC-USD", 50_000.0 + i as f64, 1.0);
        md_tx.send(md).unwrap();
    }

    std::thread::sleep(std::time::Duration::from_secs(1));
}
