use crate::domain::order::OrderRequest;

pub struct PreTradeRiskEngine {
    max_order_notional: f64,
    max_order_qty: f64,
}

impl PreTradeRiskEngine {
    pub fn new(max_order_notional: f64, max_order_qty: f64) -> Self {
        Self {
            max_order_notional,
            max_order_qty,
        }
    }

    pub fn check_order(&self, order: &OrderRequest) -> bool {
        let notional = order.qty * order.price;
        if order.qty <= 0.0 {
            return false;
        }
        if order.qty > self.max_order_qty {
            return false;
        }
        if notional > self.max_order_notional {
            return false;
        }
        true
    }
}
