use std::collections::HashMap;
use crate::domain::execution::{ExecutionReport, ExecutionStatus};

#[derive(Debug, Default)]
pub struct PortfolioState {
    positions: HashMap<String, f64>,
    fills: usize,
}

impl PortfolioState {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) {
        if let ExecutionStatus::Filled | ExecutionStatus::PartiallyFilled = report.status {
            let pos = self.positions.entry(report.symbol.clone()).or_insert(0.0);
            *pos += report.filled_qty;
            self.fills += 1;
        }
    }

    pub fn summary(&self) -> String {
        format!("fills={}, positions={:?}", self.fills, self.positions)
    }
}
