## Event bus

### `EventBus.java`
```java
package com.example.trading.bus;

import java.util.function.Consumer;

public interface EventBus {
    <T> void subscribe(Class<T> eventType, Consumer<T> handler);
    void publish(Object event);
}
```

### `InMemoryEventBus.java`
```java
package com.example.trading.bus;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

public class InMemoryEventBus implements EventBus {
    private final Map<Class<?>, List<Consumer<?>>> handlers = new ConcurrentHashMap<>();

    @Override
    public <T> void subscribe(Class<T> eventType, Consumer<T> handler) {
        handlers.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>()).add(handler);
    }

    @Override
    public void publish(Object event) {
        var list = handlers.get(event.getClass());
        if (list == null) return;
        for (Consumer<?> handler : list) {
            @SuppressWarnings("unchecked")
            Consumer<Object> h = (Consumer<Object>) handler;
            h.accept(event);
        }
    }
}
```

