```java
package com.example.trading.strategy;

import com.example.trading.bus.EventBus;
import com.example.trading.events.MarketDataEvent;
import com.example.trading.events.OrderIntentEvent;
import com.example.trading.model.Order;
import com.example.trading.model.Side;

import java.util.HashMap;
import java.util.Map;

public class MeanReversionStrategy {
    private final EventBus bus;
    private final String strategyId;
    private final Map<String, Double> lastMid = new HashMap<>();

    public MeanReversionStrategy(EventBus bus, String strategyId) {
        this.bus = bus;
        this.strategyId = strategyId;
    }

    public void onMarketData(MarketDataEvent event) {
        var q = event.quote();
        double mid = (q.bid() + q.ask()) / 2.0;
        Double prev = lastMid.put(q.symbol(), mid);

        if (prev == null) return;

        // Very simple example logic:
        // If price drops > 0.2%, buy; if rises > 0.2%, sell
        double change = (mid - prev) / prev;

        if (change < -0.002) {
            Order order = Order.create(strategyId, q.symbol(), Side.BUY, 10, q.ask());
            bus.publish(new OrderIntentEvent(order));
        } else if (change > 0.002) {
            Order order = Order.create(strategyId, q.symbol(), Side.SELL, 10, q.bid());
            bus.publish(new OrderIntentEvent(order));
        }
    }
}
```

