        Order order = event.order();
        orderState.put(order.orderId(), OrderStatus.VALIDATED);
        bus.publish(new OrderSubmittedEvent(order));
    }

    public void onOrderFilled(OrderFilledEvent event) {
        orderState.put(event.order().orderId(), OrderStatus.FILLED);
    }

    public OrderStatus getStatus(String orderId) {
        return orderState.get(orderId);
    }
