## `crates/strategy/src/engine.rs`

A simple mean-reversion style placeholder strategy:

```rust
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::SystemTime;

use common::events::Event;
use common::types::{Order, OrderId, OrderType, Price, Quantity, Side};

pub struct StrategyEngine {
    next_order_id: AtomicU64,
    last_mid: Option<Price>,
}

impl StrategyEngine {
    pub fn new() -> Self {
        Self {
            next_order_id: AtomicU64::new(1),
            last_mid: None,
        }
    }

    pub fn on_event(&mut self, event: &Event) -> Option<Order> {
        match event {
            Event::MarketTick(tick) => {
                let mid = (tick.bid + tick.ask) / 2;
                let signal = match self.last_mid {
                    Some(prev_mid) if mid < prev_mid => Some(Side::Buy),
                    Some(prev_mid) if mid > prev_mid => Some(Side::Sell),
                    _ => None,
                };
                self.last_mid = Some(mid);

                signal.map(|side| self.create_order(tick.instrument_id, side, mid))
            }
            _ => None,
        }
    }

    fn create_order(&self, instrument_id: u64, side: Side, mid: Price) -> Order {
        let order_id = self.next_order_id.fetch_add(1, Ordering::Relaxed);

        Order {
            order_id,
            instrument_id,
            side,
            order_type: OrderType::Limit,
            price: Some(mid),
            quantity: 10 as Quantity,
            timestamp: SystemTime::now(),
        }
    }
}
```

