## `crates/risk/src/checks.rs`

```rust
use common::types::{Order, OrderType, Side};

pub struct RiskEngine {
    pub max_order_qty: i64,
    pub max_notional: i64,
}

impl RiskEngine {
    pub fn new(max_order_qty: i64, max_notional: i64) -> Self {
        Self {
            max_order_qty,
            max_notional,
        }
    }

    pub fn validate(&self, order: &Order) -> Result<(), String> {
        if order.quantity <= 0 {
            return Err("quantity must be positive".into());
        }

        if order.quantity > self.max_order_qty {
            return Err(format!("quantity exceeds limit: {}", order.quantity));
        }

        if matches!(order.order_type, OrderType::Limit) {
            let price = order.price.ok_or("limit order requires price")?;
            let notional = price.saturating_mul(order.quantity);

            if notional > self.max_notional {
                return Err(format!("notional exceeds limit: {}", notional));
            }
        }

        match order.side {
            Side::Buy | Side::Sell => Ok(()),
        }
    }
}
```

