    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) {
        self.orders.insert(report.order_id, report.status.clone());
    }

    pub fn status(&self, order_id: OrderId) -> Option<&OrderStatus> {
        self.orders.get(&order_id)
    }

    pub fn create_reject(order_id: OrderId, reason: String) -> ExecutionReport {
        ExecutionReport {
            order_id,
            status: OrderStatus::Rejected(reason),
            timestamp: SystemTime::now(),
        }
    }
}
