Below is a **practical high-throughput messaging system skeleton in Go** designed for:

- **millions of messages/sec** on a single node via batching + sharded routing
- **low-latency routing**
- **latency monitoring** with percentiles
- **backpressure** and bounded queues

This is not a full production broker, but it’s a solid foundation for a high-frequency in-memory router.

---

## Design summary

- **Ingress**: multiple producers call `Publish()`
- **Sharded routing**: messages are hashed to one of N shards
- **Per-shard worker**: processes batches to reduce lock contention and syscall overhead
- **Subscribers**: each topic can have multiple consumers
- **Latency tracking**: records end-to-end delivery latency and reports p50/p95/p99
- **Backpressure**: bounded channels prevent unbounded memory growth

---

## Go implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

type Subscriber struct {
	ID   string
	C    chan Message
	done chan struct{}
}

func NewSubscriber(id string, buffer int) *Subscriber {
	return &Subscriber{
		ID:   id,
		C:    make(chan Message, buffer),
		done: make(chan struct{}),
	}
}

func (s *Subscriber) Close() {
	select {
	case <-s.done:
		return
	default:
		close(s.done)
		close(s.C)
	}
}

type LatencyStats struct {
	mu       sync.Mutex
	samples  []int64 // nanoseconds
	capacity int
}

func NewLatencyStats(capacity int) *LatencyStats {
	return &LatencyStats{
		samples:  make([]int64, 0, capacity),
		capacity: capacity,
	}
}

func (l *LatencyStats) Record(d time.Duration) {
	l.mu.Lock()
	if len(l.samples) < l.capacity {
		l.samples = append(l.samples, d.Nanoseconds())
	} else {
		// reservoir-ish overwrite to keep memory bounded
		idx := time.Now().UnixNano() % int64(l.capacity)
		l.samples[idx] = d.Nanoseconds()
	}
	l.mu.Unlock()
}

func (l *LatencyStats) Snapshot() (p50, p95, p99 time.Duration, count int) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if len(l.samples) == 0 {
		return 0, 0, 0, 0
	}

	cp := make([]int64, len(l.samples))
	copy(cp, l.samples)
	sort.Slice(cp, func(i, j int) bool { return cp[i] < cp[j] })

	get := func(p float64) time.Duration {
		if len(cp) == 0 {
			return 0
		}
		idx := int(float64(len(cp)-1) * p)
		return time.Duration(cp[idx])
	}

	return get(0.50), get(0.95), get(0.99), len(cp)
}

type shard struct {
	id          int
	in          chan Message
	subsMu      sync.RWMutex
	subscribers map[string][]*Subscriber // topic -> subscribers
	latency     *LatencyStats
	processed   uint64
}

func newShard(id int, queueSize int, latencyCapacity int) *shard {
	return &shard{
		id:          id,
		in:          make(chan Message, queueSize),
		subscribers: make(map[string][]*Subscriber),
		latency:     NewLatencyStats(latencyCapacity),
	}
}

func (s *shard) addSubscriber(topic string, sub *Subscriber) {
	s.subsMu.Lock()
	s.subscribers[topic] = append(s.subscribers[topic], sub)
	s.subsMu.Unlock()
}

func (s *shard) run(ctx context.Context, batchSize int) {
	batch := make([]Message, 0, batchSize)

	flush := func() {
		if len(batch) == 0 {
			return
		}
		for _, msg := range batch {
			s.deliver(msg)
			atomic.AddUint64(&s.processed, 1)
		}
		batch = batch[:0]
	}

	for {
		select {
		case <-ctx.Done():
			flush()
			return
		case msg := <-s.in:
			batch = append(batch, msg)
			if len(batch) >= batchSize {
				flush()
			}
		default:
			// drain quickly if available
			if len(batch) > 0 {
				flush()
			}
			runtime.Gosched()
		}
	}
}

func (s *shard) deliver(msg Message) {
	s.subsMu.RLock()
	subs := s.subscribers[msg.Topic]
	s.subsMu.RUnlock()

	lat := time.Since(msg.CreatedAt)
	s.latency.Record(lat)

	for _, sub := range subs {
		// Non-blocking send to avoid stalling the shard.
		select {
		case sub.C <- msg:
		default:
			// Drop or count backpressure here if desired.
		}
	}
}

type Broker struct {
	shards       []*shard
	shardMask    uint64
	closed       chan struct{}
	wg           sync.WaitGroup
	batchSize    int
	queueSize    int
	latencyEvery time.Duration
}

func NewBroker(numShards int, queueSize int, batchSize int, latencySampleCap int) *Broker {
	// numShards should be power of two for mask optimization.
	shards := make([]*shard, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = newShard(i, queueSize, latencySampleCap)
	}

	return &Broker{
		shards:       shards,
		shardMask:    uint64(numShards - 1),
		closed:       make(chan struct{}),
		batchSize:    batchSize,
		queueSize:    queueSize,
		latencyEvery: time.Second,
	}
}

func (b *Broker) Start(ctx context.Context) {
	for _, s := range b.shards {
		b.wg.Add(1)
		go func(sh *shard) {
			defer b.wg.Done()
			sh.run(ctx, b.batchSize)
		}(s)
	}
}

func (b *Broker) Stop() {
	close(b.closed)
	b.wg.Wait()
}

func (b *Broker) shardFor(key string) *shard {
	h := fnv.New64a()
	_, _ = h.Write([]byte(key))
	idx := h.Sum64() & b.shardMask
	return b.shards[idx]
}

func (b *Broker) Publish(topic, key string, payload []byte) error {
	msg := Message{
		Topic:     topic,
		Key:       key,
		Payload:   payload,
		CreatedAt: time.Now(),
	}

	sh := b.shardFor(key)

	// Backpressure: fail fast if shard queue is full.
	select {
	case sh.in <- msg:
		return nil
	default:
		return fmt.Errorf("broker overloaded: shard queue full")
	}
}

func (b *Broker) Subscribe(topic, subscriberID string, buffer int) *Subscriber {
	sub := NewSubscriber(subscriberID, buffer)

	// Simple topic-to-shard fanout: register subscriber on all shards.
	for _, sh := range b.shards {
		sh.addSubscriber(topic, sub)
	}
	return sub
}

func (b *Broker) Stats() {
	for _, sh := range b.shards {
		p50, p95, p99, count := sh.latency.Snapshot()
		fmt.Printf(
			"shard=%d processed=%d samples=%d p50=%s p95=%s p99=%s\n",
			sh.id,
			atomic.LoadUint64(&sh.processed),
			count,
			p50,
			p95,
			p99,
		)
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Tune these based on CPU cores and workload.
	numShards := 1 << 4 // 16 shards
	queueSize := 1 << 14
	batchSize := 128
	latencySampleCap := 100_000

	broker := NewBroker(numShards, queueSize, batchSize, latencySampleCap)
	broker.Start(ctx)

	sub := broker.Subscribe("prices", "consumer-1", 1024)

	go func() {
		for msg := range sub.C {
			_ = msg
			// process message
		}
	}()

	// Simulate high-rate publishing.
	go func() {
		ticker := time.NewTicker(1 * time.Microsecond)
		defer ticker.Stop()

		i := 0
		for range ticker.C {
			err := broker.Publish("prices", fmt.Sprintf("key-%d", i%1000), []byte("hello"))
			if err != nil {
				// overloaded; drop or retry depending on policy
			}
			i++
		}
	}()

	// Periodic metrics output.
	metricsTicker := time.NewTicker(2 * time.Second)
	defer metricsTicker.Stop()

	for i := 0; i < 5; i++ {
		<-metricsTicker.C
		broker.Stats()
	}

	cancel()
	broker.Stop()
	sub.Close()
}
