## Java implementation

```java
import java.util.Arrays;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

/**
 * High-frequency messaging system skeleton:
 * - Producers publish messages into shard queues
 * - Router workers batch-drain queues and route to handlers
 * - Latency metrics collected using HDR-like fixed buckets
 */
public class HighFreqMessagingSystem {

    // ===== Message =====
    public static final class Message {
        public final long id;
        public final long createdNanos;
        public final int routeKey;
        public final byte[] payload;

        public Message(long id, int routeKey, byte[] payload) {
            this.id = id;
            this.routeKey = routeKey;
            this.payload = payload;
            this.createdNanos = System.nanoTime();
        }
    }

    // ===== Handler =====
    public interface MessageHandler {
        void onMessage(Message msg);
    }

    // ===== Latency Metrics =====
    public static final class LatencyMetrics {
        // Buckets in nanoseconds: 1us -> 10s, log-scale
        private static final long MIN_BUCKET_NS = 1_000L;
        private static final long MAX_BUCKET_NS = 10_000_000_000L;
        private static final int BUCKETS = 64;

        private final LongAdder count = new LongAdder();
        private final LongAdder totalNs = new LongAdder();
        private final LongAdder[] histogram = new LongAdder[BUCKETS];

        public LatencyMetrics() {
            for (int i = 0; i < BUCKETS; i++) histogram[i] = new LongAdder();
        }

        public void record(long latencyNs) {
            count.increment();
            totalNs.add(latencyNs);
            histogram[bucketIndex(latencyNs)].increment();
        }

        private int bucketIndex(long ns) {
            long v = Math.max(MIN_BUCKET_NS, Math.min(MAX_BUCKET_NS, ns));
            int idx = 63 - Long.numberOfLeadingZeros(v);
            return Math.min(BUCKETS - 1, Math.max(0, idx));
        }

        public Snapshot snapshot() {
            long c = count.sum();
            long t = totalNs.sum();
            long avg = c == 0 ? 0 : t / c;

            long p50 = percentile(0.50, c);
            long p95 = percentile(0.95, c);
            long p99 = percentile(0.99, c);

            return new Snapshot(c, avg, p50, p95, p99);
        }

        private long percentile(double quantile, long totalCount) {
            if (totalCount == 0) return 0;
            long target = (long) Math.ceil(totalCount * quantile);
            long cumulative = 0;

            for (int i = 0; i < BUCKETS; i++) {
                cumulative += histogram[i].sum();
                if (cumulative >= target) {
                    return bucketToLatencyNs(i);
                }
            }
            return bucketToLatencyNs(BUCKETS - 1);
        }

        private long bucketToLatencyNs(int idx) {
            // approximate bucket upper bound
            return 1L << (idx + 1);
        }

        public record Snapshot(long count, long avgNs, long p50Ns, long p95Ns, long p99Ns) {}
    }

    // ===== Router shard =====
    public static final class Shard implements Runnable {
        private final ArrayBlockingQueue<Message> queue;
        private final MessageHandler handler;
        private final LatencyMetrics metrics;
        private final int batchSize;
        private volatile boolean running = true;

        public Shard(int capacity, int batchSize, MessageHandler handler, LatencyMetrics metrics) {
            this.queue = new ArrayBlockingQueue<>(capacity);
            this.batchSize = batchSize;
            this.handler = handler;
            this.metrics = metrics;
        }

        public boolean publish(Message msg) {
            return queue.offer(msg); // non-blocking, returns false if full
        }

        public void stop() {
            running = false;
        }

        @Override
        public void run() {
            Message[] batch = new Message[batchSize];

            while (running || !queue.isEmpty()) {
                int n = queue.drainTo(Arrays.asList(batch), batchSize); // not ideal; see note below
                if (n == 0) {
                    Message msg = queue.poll();
                    if (msg == null) {
                        Thread.onSpinWait();
                        continue;
                    }
                    process(msg);
                    continue;
                }

                for (int i = 0; i < n; i++) {
                    Message msg = batch[i];
                    if (msg != null) process(msg);
                    batch[i] = null;
                }
            }
        }

        private void process(Message msg) {
            try {
                handler.onMessage(msg);
            } finally {
                metrics.record(System.nanoTime() - msg.createdNanos);
            }
        }
    }

    // ===== System =====
    public static final class RouterSystem {
        private final Shard[] shards;
        private final Thread[] workers;
        private final AtomicLong idGen = new AtomicLong();
        private final LatencyMetrics metrics = new LatencyMetrics();

        public RouterSystem(int shardCount, int queueCapacity, int batchSize, MessageHandler handler) {
            this.shards = new Shard[shardCount];
            this.workers = new Thread[shardCount];

            for (int i = 0; i < shardCount; i++) {
                shards[i] = new Shard(queueCapacity, batchSize, handler, metrics);
                workers[i] = new Thread(shards[i], "router-shard-" + i);
                workers[i].setDaemon(true);
            }
        }

        public void start() {
            for (Thread t : workers) t.start();
        }

        public boolean publish(int routeKey, byte[] payload) {
            long id = idGen.incrementAndGet();
            Message msg = new Message(id, routeKey, payload);
            int shardIdx = spread(routeKey) & (shards.length - 1);
            return shards[shardIdx].publish(msg);
        }

        public LatencyMetrics.Snapshot metrics() {
            return metrics.snapshot();
        }

        public void stop() {
            for (Shard s : shards) s.stop();
            for (Thread t : workers) {
                try {
                    t.join(1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        // Fast hash spread (power-of-two shard count recommended)
        private static int spread(int x) {
            x ^= (x >>> 16);
            x *= 0x7feb352d;
            x ^= (x >>> 15);
            x *= 0x846ca68b;
            x ^= (x >>> 16);
            return x;
        }
    }

    // ===== Demo =====
    public static void main(String[] args) throws Exception {
        int shards = 8;               // power of two
        int queueCapacity = 1 << 16;  // 65k per shard
        int batchSize = 256;

        MessageHandler handler = msg -> {
            // Simulate routing/processing work
            // Keep this extremely small in real low-latency paths
            if ((msg.id & 0xFFFF) == 0) {
                // occasional side effect
            }
        };

        RouterSystem system = new RouterSystem(shards, queueCapacity, batchSize, handler);
        system.start();

        // Producer threads
        int producers = Runtime.getRuntime().availableProcessors();
        ExecutorService pool = Executors.newFixedThreadPool(producers);

        CountDownLatch latch = new CountDownLatch(producers);
        long end = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);

        for (int p = 0; p < producers; p++) {
            final int producerId = p;
            pool.submit(() -> {
                try {
                    ThreadLocalRandom rnd = ThreadLocalRandom.current();
                    while (System.nanoTime() < end) {
                        int routeKey = rnd.nextInt(1_000_000);
                        byte[] payload = new byte[128]; // preallocate/reuse in real systems
                        payload[0] = (byte) producerId;

                        while (!system.publish(routeKey, payload)) {
                            // backpressure / retry
                            Thread.onSpinWait();
                        }
                    }
                } finally {
                    latch.countDown();
                }
            });
        }

        latch.await();
        pool.shutdownNow();
        system.stop();

        LatencyMetrics.Snapshot snap = system.metrics();
        System.out.println("Messages: " + snap.count());
        System.out.println("Avg ns:   " + snap.avgNs());
        System.out.println("p50 ns:   " + snap.p50Ns());
        System.out.println("p95 ns:   " + snap.p95Ns());
        System.out.println("p99 ns:   " + snap.p99Ns());
    }
}
```

