## Go implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"math/rand"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed event.
type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nano
	TraceID    uint64
	Partition  uint32
}

// RouteResult is returned by a handler.
type RouteResult struct {
	ProcessedAt int64
	LatencyNs   int64
	Err         error
}

// Handler processes a message.
type Handler func(ctx context.Context, msg Message) error

// LatencyStats keeps rolling latency metrics.
type LatencyStats struct {
	count uint64
	sumNs uint64

	minNs atomic.Int64
	maxNs atomic.Int64
}

func NewLatencyStats() *LatencyStats {
	s := &LatencyStats{}
	s.minNs.Store(int64(^uint64(0) >> 1)) // max int64
	return s
}

func (s *LatencyStats) Observe(latency time.Duration) {
	ns := latency.Nanoseconds()
	atomic.AddUint64(&s.count, 1)
	atomic.AddUint64(&s.sumNs, uint64(ns))

	for {
		old := s.minNs.Load()
		if ns >= old {
			break
		}
		if s.minNs.CompareAndSwap(old, ns) {
			break
		}
	}

	for {
		old := s.maxNs.Load()
		if ns <= old {
			break
		}
		if s.maxNs.CompareAndSwap(old, ns) {
			break
		}
	}
}

func (s *LatencyStats) Snapshot() (count uint64, avg time.Duration, min, max time.Duration) {
	count = atomic.LoadUint64(&s.count)
	sum := atomic.LoadUint64(&s.sumNs)
	if count > 0 {
		avg = time.Duration(sum / count)
	}
	min = time.Duration(s.minNs.Load())
	max = time.Duration(s.maxNs.Load())
	return
}

// Router routes messages to partitions/workers.
type Router struct {
	partitions int
	queues     []chan Message
	handlers   []Handler

	// metrics
	enqueued uint64
	dropped  uint64
	processed uint64
	errors   uint64

	latency *LatencyStats
}

// NewRouter creates a router with N partitions and queue capacity.
func NewRouter(partitions, queueCapacity int, handlers []Handler) *Router {
	if partitions <= 0 {
		partitions = runtime.GOMAXPROCS(0)
	}
	if queueCapacity <= 0 {
		queueCapacity = 1024
	}
	if len(handlers) == 0 {
		panic("at least one handler required")
	}

	r := &Router{
		partitions: partitions,
		queues:     make([]chan Message, partitions),
		handlers:   handlers,
		latency:    NewLatencyStats(),
	}

	for i := 0; i < partitions; i++ {
		r.queues[i] = make(chan Message, queueCapacity)
	}
	return r
}

// Start launches workers.
func (r *Router) Start(ctx context.Context) {
	for i := 0; i < r.partitions; i++ {
		go r.worker(ctx, i)
	}
}

// Stop is cooperative via context cancellation.
func (r *Router) worker(ctx context.Context, partition int) {
	q := r.queues[partition]
	handler := r.handlers[partition%len(r.handlers)]

	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-q:
			start := time.Now()
			err := handler(ctx, msg)
			latency := time.Since(time.Unix(0, msg.CreatedAt))

			r.latency.Observe(latency)
			atomic.AddUint64(&r.processed, 1)

			if err != nil {
				atomic.AddUint64(&r.errors, 1)
			}

			_ = start // reserved for additional local timing if needed
		}
	}
}

// partitionForKey hashes a key to a partition.
func (r *Router) partitionForKey(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32() % uint32(r.partitions))
}

// Publish routes a message with backpressure.
// If the queue is full, the message is dropped immediately.
func (r *Router) Publish(msg Message) bool {
	p := int(msg.Partition)
	if p < 0 || p >= r.partitions {
		p = r.partitionForKey(msg.Key)
		msg.Partition = uint32(p)
	}

	select {
	case r.queues[p] <- msg:
		atomic.AddUint64(&r.enqueued, 1)
		return true
	default:
		atomic.AddUint64(&r.dropped, 1)
		return false
	}
}

// PublishKey routes based on key.
func (r *Router) PublishKey(key string, payload []byte) bool {
	msg := Message{
		ID:       rand.Uint64(),
		Key:      key,
		Payload:  payload,
		CreatedAt: time.Now().UnixNano(),
		TraceID:  rand.Uint64(),
	}
	msg.Partition = uint32(r.partitionForKey(key))
	return r.Publish(msg)
}

// Metrics returns current counters.
func (r *Router) Metrics() (enqueued, dropped, processed, errors uint64) {
	return atomic.LoadUint64(&r.enqueued),
		atomic.LoadUint64(&r.dropped),
		atomic.LoadUint64(&r.processed),
		atomic.LoadUint64(&r.errors)
}

// Latency returns a snapshot of latency stats.
func (r *Router) Latency() (count uint64, avg, min, max time.Duration) {
	return r.latency.Snapshot()
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Example handler: simulate fast processing.
	handler := func(ctx context.Context, msg Message) error {
		// Do work here. Keep it minimal for low latency.
		if len(msg.Payload) == 0 {
			return fmt.Errorf("empty payload")
		}
		return nil
	}

	// Create router with one handler per worker group.
	router := NewRouter(
		runtime.GOMAXPROCS(0),
		8192,
		[]Handler{handler},
	)

	router.Start(ctx)

	// Producer loop
	go func() {
		ticker := time.NewTicker(1 * time.Millisecond)
		defer ticker.Stop()

		for i := 0; i < 1_000_000; i++ {
			<-ticker.C
			ok := router.PublishKey(
				fmt.Sprintf("user-%d", i%10000),
				[]byte("hello"),
			)
			if !ok {
				// drop or retry based on policy
			}
		}
		cancel()
	}()

	// Monitoring loop
	monitorTicker := time.NewTicker(2 * time.Second)
	defer monitorTicker.Stop()

	for {
		select {
		case <-ctx.Done():
			enq, drop, proc, errs := router.Metrics()
			count, avg, min, max := router.Latency()
			log.Printf("done: enqueued=%d dropped=%d processed=%d errors=%d", enq, drop, proc, errs)
			log.Printf("latency: count=%d avg=%s min=%s max=%s", count, avg, min, max)
			return

		case <-monitorTicker.C:
			enq, drop, proc, errs := router.Metrics()
			count, avg, min, max := router.Latency()
			log.Printf("metrics: enqueued=%d dropped=%d processed=%d errors=%d", enq, drop, proc, errs)
			log.Printf("latency: count=%d avg=%s min=%s max=%s", count, avg, min, max)
		}
	}
}
