## Go implementation

```go
package main

import (
	"fmt"
	"hash/fnv"
	"math"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nanos
	EnqueuedAt int64 // unix nanos
}

type Metrics struct {
	received   uint64
	routed     uint64
	processed  uint64
	dropped    uint64
	totalQueue int64
	totalProc  int64

	latencyHist [64]uint64 // log2 histogram buckets for end-to-end latency in microseconds
}

func (m *Metrics) recordLatency(ns int64) {
	us := ns / 1000
	if us < 0 {
		us = 0
	}
	bucket := 0
	if us > 0 {
		bucket = int(math.Log2(float64(us)))
	}
	if bucket < 0 {
		bucket = 0
	}
	if bucket >= len(m.latencyHist) {
		bucket = len(m.latencyHist) - 1
	}
	atomic.AddUint64(&m.latencyHist[bucket], 1)
}

func (m *Metrics) snapshot() MetricsSnapshot {
	s := MetricsSnapshot{
		Received:  atomic.LoadUint64(&m.received),
		Routed:    atomic.LoadUint64(&m.routed),
		Processed: atomic.LoadUint64(&m.processed),
		Dropped:   atomic.LoadUint64(&m.dropped),
	}

	for i := range m.latencyHist {
		s.LatencyHist[i] = atomic.LoadUint64(&m.latencyHist[i])
	}
	return s
}

type MetricsSnapshot struct {
	Received   uint64
	Routed     uint64
	Processed  uint64
	Dropped    uint64
	LatencyHist [64]uint64
}

type Worker struct {
	id      int
	ch      chan *Message
	metrics *Metrics
	stop    chan struct{}
}

func NewWorker(id int, queueSize int, metrics *Metrics) *Worker {
	return &Worker{
		id:      id,
		ch:      make(chan *Message, queueSize),
		metrics: metrics,
		stop:    make(chan struct{}),
	}
}

func (w *Worker) Start(wg *sync.WaitGroup) {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case msg := <-w.ch:
				if msg == nil {
					continue
				}
				startProc := time.Now().UnixNano()

				// Simulate processing work
				// Replace with real business logic.
				_ = len(msg.Payload)

				procDone := time.Now().UnixNano()
				queueLatency := startProc - msg.EnqueuedAt
				procLatency := procDone - startProc
				endToEndLatency := procDone - msg.CreatedAt

				atomic.AddUint64(&w.metrics.processed, 1)
				atomic.AddInt64(&w.metrics.totalQueue, queueLatency)
				atomic.AddInt64(&w.metrics.totalProc, procLatency)
				w.metrics.recordLatency(endToEndLatency)

			case <-w.stop:
				return
			}
		}
	}()
}

func (w *Worker) Stop() {
	close(w.stop)
}

func (w *Worker) TryEnqueue(msg *Message) bool {
	select {
	case w.ch <- msg:
		return true
	default:
		return false
	}
}

type Router struct {
	workers []*Worker
	metrics *Metrics
}

func NewRouter(workerCount int, queueSize int, metrics *Metrics) *Router {
	workers := make([]*Worker, workerCount)
	for i := 0; i < workerCount; i++ {
		workers[i] = NewWorker(i, queueSize, metrics)
	}
	return &Router{
		workers: workers,
		metrics: metrics,
	}
}

func (r *Router) Start(wg *sync.WaitGroup) {
	for _, w := range r.workers {
		w.Start(wg)
	}
}

func (r *Router) Stop() {
	for _, w := range r.workers {
		w.Stop()
	}
}

func (r *Router) routeIndex(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32()) % len(r.workers)
}

func (r *Router) Publish(msg *Message) bool {
	atomic.AddUint64(&r.metrics.received, 1)

	msg.EnqueuedAt = time.Now().UnixNano()
	idx := r.routeIndex(msg.Key)
	atomic.AddUint64(&r.metrics.routed, 1)

	ok := r.workers[idx].TryEnqueue(msg)
	if !ok {
		atomic.AddUint64(&r.metrics.dropped, 1)
		return false
	}
	return true
}

type Generator struct {
	nextID uint64
}

func (g *Generator) NewMessage(key string, payload []byte) *Message {
	id := atomic.AddUint64(&g.nextID, 1)
	now := time.Now().UnixNano()
	return &Message{
		ID:        id,
		Key:       key,
		Payload:   payload,
		CreatedAt: now,
		EnqueuedAt: now,
	}
}

func printMetricsLoop(metrics *Metrics, interval time.Duration, stop <-chan struct{}) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastReceived, lastProcessed, lastDropped uint64

	for {
		select {
		case <-ticker.C:
			s := metrics.snapshot()

			dr := s.Received - lastReceived
			dp := s.Processed - lastProcessed
			dd := s.Dropped - lastDropped

			lastReceived = s.Received
			lastProcessed = s.Processed
			lastDropped = s.Dropped

			fmt.Printf(
				"recv=%d (+%d/s) routed=%d processed=%d (+%d/s) dropped=%d (+%d/s)\n",
				s.Received, dr, s.Routed, s.Processed, dp, s.Dropped, dd,
			)

			fmt.Printf("latency histogram (log2 us buckets): %v\n", s.LatencyHist)

		case <-stop:
			return
		}
	}
}

func main() {
	metrics := &Metrics{}
	router := NewRouter(workerCount: 64, queueSize: 4096, metrics: metrics)

	var wg sync.WaitGroup
	router.Start(&wg)

	stopMetrics := make(chan struct{})
	go printMetricsLoop(metrics, 2*time.Second, stopMetrics)

	gen := &Generator{}

	// Example high-throughput producer loop
	// In real systems, this would be fed by network I/O, Kafka, NATS, TCP, UDP, etc.
	for i := 0; i < 1000000; i++ {
		key := fmt.Sprintf("user-%d", i%10000)
		msg := gen.NewMessage(key, []byte("hello world"))
		router.Publish(msg)
	}

	time.Sleep(3 * time.Second)

	close(stopMetrics)
	router.Stop()
	wg.Wait()

	s := metrics.snapshot()
	fmt.Printf("final: received=%d processed=%d dropped=%d\n", s.Received, s.Processed, s.Dropped)
}
