## Go code

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"math/rand"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a single routed event.
type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt  time.Time
	TraceSent  int64 // unix nano timestamp
	TraceRouted int64
}

// Metrics tracks throughput and latency observations.
type Metrics struct {
	received uint64
	routed   uint64
	dropped  uint64
	processed uint64

	latMu    sync.Mutex
	latencyN []int64 // nanoseconds, sampled
}

func (m *Metrics) IncReceived()  { atomic.AddUint64(&m.received, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.dropped, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }

func (m *Metrics) SampleLatency(d time.Duration) {
	// Sampling to reduce overhead under very high throughput.
	if rand.Intn(1000) != 0 { // 0.1% sampling
		return
	}
	m.latMu.Lock()
	m.latencyN = append(m.latencyN, int64(d))
	if len(m.latencyN) > 100000 {
		// keep memory bounded
		m.latencyN = m.latencyN[len(m.latencyN)/2:]
	}
	m.latMu.Unlock()
}

func (m *Metrics) Snapshot() (received, routed, dropped, processed uint64, p50, p95, p99 time.Duration) {
	received = atomic.LoadUint64(&m.received)
	routed = atomic.LoadUint64(&m.routed)
	dropped = atomic.LoadUint64(&m.dropped)
	processed = atomic.LoadUint64(&m.processed)

	m.latMu.Lock()
	samples := make([]int64, len(m.latencyN))
	copy(samples, m.latencyN)
	m.latMu.Unlock()

	if len(samples) == 0 {
		return
	}

	sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })
	p50 = time.Duration(samples[len(samples)/2])
	p95 = time.Duration(samples[int(float64(len(samples))*0.95)])
	p99 = time.Duration(samples[int(float64(len(samples))*0.99)])
	return
}

// Shard routes messages for a subset of keys.
type Shard struct {
	id       int
	in       chan Message
	workers  int
	metrics  *Metrics
	handlers []chan Message
}

func NewShard(id, workers, buf int, metrics *Metrics) *Shard {
	s := &Shard{
		id:       id,
		in:       make(chan Message, buf),
		workers:  workers,
		metrics:  metrics,
		handlers: make([]chan Message, workers),
	}
	for i := 0; i < workers; i++ {
		s.handlers[i] = make(chan Message, buf)
	}
	return s
}

func (s *Shard) Start(ctx context.Context, wg *sync.WaitGroup) {
	// Router goroutine for the shard.
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer func() {
			for _, ch := range s.handlers {
				close(ch)
			}
		}()

		for {
			select {
			case <-ctx.Done():
				return
			case msg, ok := <-s.in:
				if !ok {
					return
				}
				s.metrics.IncRouted()
				idx := int(fnv32(msg.Key) % uint32(s.workers))
				select {
				case s.handlers[idx] <- msg:
				default:
					// Drop if worker is overloaded to protect latency.
					s.metrics.IncDropped()
				}
			}
		}
	}()

	// Worker goroutines.
	for i := 0; i < s.workers; i++ {
		wg.Add(1)
		go func(workerID int, ch <-chan Message) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case msg, ok := <-ch:
					if !ok {
						return
					}
					// Simulate processing and latency measurement.
					now := time.Now()
					if msg.TraceSent > 0 {
						s.metrics.SampleLatency(now.Sub(time.Unix(0, msg.TraceSent)))
					}
					s.process(msg)
					s.metrics.IncProcessed()
				}
			}
		}(i, s.handlers[i])
	}
}

func (s *Shard) process(msg Message) {
	// Replace this with your real business logic.
	_ = msg
}

// Router distributes messages across shards.
type Router struct {
	shards  []*Shard
	metrics *Metrics
}

func NewRouter(numShards, workersPerShard, buf int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]*Shard, numShards),
		metrics: metrics,
	}
	for i := 0; i < numShards; i++ {
		r.shards[i] = NewShard(i, workersPerShard, buf, metrics)
	}
	return r
}

func (r *Router) Start(ctx context.Context, wg *sync.WaitGroup) {
	for _, shard := range r.shards {
		shard.Start(ctx, wg)
	}
}

func (r *Router) Publish(msg Message) bool {
	shardIdx := int(fnv32(msg.Key) % uint32(len(r.shards)))
	shard := r.shards[shardIdx]
	select {
	case shard.in <- msg:
		r.metrics.IncReceived()
		return true
	default:
		// Drop when shard queue is full to keep tail latency low.
		r.metrics.IncDropped()
		return false
	}
}

func fnv32(s string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(s))
	return h.Sum32()
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	metrics := &Metrics{}
	router := NewRouter(
		numShards:        32,
		workersPerShard:   4,
		buf:               4096,
		metrics:           metrics,
	)

	var wg sync.WaitGroup
	router.Start(ctx, &wg)

