package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

//
// Message model
//

type Message struct {
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nanos
	TraceID    uint64
	Partition  uint32
	RouteHint  uint32
}

func NewMessage(topic, key string, payload []byte) Message {
	return Message{
		Topic:    topic,
		Key:      key,
		Payload:  payload,
		CreatedAt: time.Now().UnixNano(),
	}
}

//
// Subscriber
//

type Subscriber struct {
	ID      string
	ch      chan Message
	closed  atomic.Bool
	recvCnt atomic.Uint64
}

func NewSubscriber(id string, buffer int) *Subscriber {
	return &Subscriber{
		ID: id,
		ch: make(chan Message, buffer),
	}
}

func (s *Subscriber) Channel() <-chan Message {
	return s.ch
}

func (s *Subscriber) Close() {
	if s.closed.CompareAndSwap(false, true) {
		close(s.ch)
	}
}

//
// Metrics
//

type LatencyStats struct {
	Count    uint64
	MinNanos int64
	MaxNanos int64
	P50Nanos int64
	P95Nanos int64
	P99Nanos int64
}

type Metrics struct {
	ingested   atomic.Uint64
	delivered  atomic.Uint64
	dropped    atomic.Uint64
	totalNanos atomic.Uint64

	mu       sync.Mutex
	samples  []int64
	capacity int
}

func NewMetrics(sampleCapacity int) *Metrics {
	return &Metrics{
		samples:  make([]int64, 0, sampleCapacity),
		capacity: sampleCapacity,
	}
}

func (m *Metrics) RecordLatency(d time.Duration) {
	m.totalNanos.Add(uint64(d.Nanoseconds()))

	m.mu.Lock()
	if len(m.samples) < m.capacity {
		m.samples = append(m.samples, d.Nanoseconds())
	}
	m.mu.Unlock()
}

func (m *Metrics) SnapshotAndReset() LatencyStats {
	m.mu.Lock()
	s := make([]int64, len(m.samples))
	copy(s, m.samples)
	m.samples = m.samples[:0]
	m.mu.Unlock()

	if len(s) == 0 {
		return LatencyStats{}
	}

	// Simple sort for snapshot percentiles.
	// For very high scale, replace with HDRHistogram / DDSketch / t-digest.
	sortInt64s(s)

	count := len(s)
	minV := s[0]
	maxV := s[count-1]
	p50 := s[count/2]
	p95 := s[int(float64(count)*0.95)]
	if p95 >= count {
		p95 = s[count-1]
	}
	p99 := s[int(float64(count)*0.99)]
	if p99 >= count {
		p99 = s[count-1]
	}

	return LatencyStats{
		Count:    uint64(count),
		MinNanos: minV,
		MaxNanos: maxV,
		P50Nanos: p50,
		P95Nanos: p95,
		P99Nanos: p99,
	}
}

func sortInt64s(a []int64) {
	// Insertion sort for small samples; replace with sort.Slice for simplicity if desired.
	for i := 1; i < len(a); i++ {
		x := a[i]
		j := i - 1
		for ; j >= 0 && a[j] > x; j-- {
			a[j+1] = a[j]
		}
		a[j+1] = x
	}
}

//
// Router / Dispatcher
//

type shard struct {
	id          int
	in          chan Message
	subscribers map[string][]*Subscriber
	mu          sync.RWMutex
	metrics     *Metrics
}

type Router struct {
	shards   []*shard
	shardCnt uint32
	metrics  *Metrics
}

func NewRouter(shardCount int, shardQueueSize int) *Router {
	r := &Router{
		shards:   make([]*shard, shardCount),
		shardCnt: uint32(shardCount),
		metrics:  NewMetrics(1_000_000),
	}
	for i := 0; i < shardCount; i++ {
		s := &shard{
			id:          i,
			in:          make(chan Message, shardQueueSize),
			subscribers: make(map[string][]*Subscriber),
			metrics:     NewMetrics(100_000),
		}
		r.shards[i] = s
		go s.run()
	}
	return r
}

func (r *Router) shardFor(msg Message) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(msg.Topic))
	_, _ = h.Write([]byte(msg.Key))
	idx := h.Sum32() % r.shardCnt
	return r.shards[idx]
}

func (r *Router) Publish(msg Message) bool {
	r.metrics.ingested.Add(1)
	sh := r.shardFor(msg)

	select {
	case sh.in <- msg:
		return true
	default:
		// Backpressure/dropping policy.
		r.metrics.dropped.Add(1)
		return false
	}
}

func (r *Router) Subscribe(topic string, sub *Subscriber) {
	sh := r.shardFor(Message{Topic: topic, Key: sub.ID})
	sh.mu.Lock()
	sh.subscribers[topic] = append(sh.subscribers[topic], sub)
	sh.mu.Unlock()
}

func (r *Router) Unsubscribe(topic string, subID string) {
	sh := r.shardFor(Message{Topic: topic, Key: subID})
	sh.mu.Lock()
	defer sh.mu.Unlock()

	list := sh.subscribers[topic]
	out := list[:0]
	for _, s := range list {
		if s.ID != subID {
			out = append(out, s)
		}
	}
	if len(out) == 0 {
		delete(sh.subscribers, topic)
	} else {
		sh.subscribers[topic] = out
	}
}

func (s *shard) run() {
	for msg := range s.in {
		start := time.Now()

		s.mu.RLock()
		subs := s.subscribers[msg.Topic]
		s.mu.RUnlock()

		delivered := 0
		for _, sub := range subs {
			select {
			case sub.ch <- msg:
				delivered++
			default:
				// Subscriber slow; drop or count backpressure.
			}
		}

		_ = delivered
		s.metrics.RecordLatency(time.Since(start))
	}
}

//
// Monitoring
//

func (r *Router) StartMonitoring(ctx context.Context, interval time.Duration) {
	ticker := time.NewTicker(interval)
	go func() {
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				ing := r.metrics.ingested.Load()
				del := r.metrics.delivered.Load()
				drop := r.metrics.dropped.Load()

				fmt.Printf("router: ingested=%d delivered=%d dropped=%d\n", ing, del, drop)

				for _, sh := range r.shards {
					stats := sh.metrics.SnapshotAndReset()
					if stats.Count == 0 {
						continue
					}
					fmt.Printf(
						"shard=%d count=%d p50=%s p95=%s p99=%s min=%s max=%s\n",
						sh.id,
						stats.Count,
						time.Duration(stats.P50Nanos),
						time.Duration(stats.P95Nanos),
						time.Duration(stats.P99Nanos),
						time.Duration(stats.MinNanos),
						time.Duration(stats.MaxNanos),
					)
				}
			}
		}
	}()
}

//
// Example consumers
//

func startConsumer(ctx context.Context, sub *Subscriber) {
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case msg, ok := <-sub.Channel():
				if !ok {
					return
				}
				_ = msg
				sub.recvCnt.Add(1)
			}
		}
	}()
}

//
// Main
//

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	router := NewRouter(64, 8192)
	router.StartMonitoring(ctx, 2*time.Second)

	subA := NewSubscriber("sub-a", 4096)
	subB := NewSubscriber("sub-b", 4096)

	router.Subscribe("orders", subA)
	router.Subscribe("orders", subB)

