### `LatencyStats.java`
```java
import java.util.concurrent.atomic.LongAdder;
import java.util.concurrent.atomic.AtomicLong;

public final class LatencyStats {
    private final LongAdder count = new LongAdder();
    private final LongAdder totalLatencyNanos = new LongAdder();
    private final AtomicLong minLatencyNanos = new AtomicLong(Long.MAX_VALUE);
    private final AtomicLong maxLatencyNanos = new AtomicLong(Long.MIN_VALUE);

    public void record(long latencyNanos) {
        count.increment();
        totalLatencyNanos.add(latencyNanos);

        updateMin(latencyNanos);
        updateMax(latencyNanos);
    }

    private void updateMin(long value) {
        long prev;
        do {
            prev = minLatencyNanos.get();
            if (value >= prev) return;
        } while (!minLatencyNanos.compareAndSet(prev, value));
    }

    private void updateMax(long value) {
        long prev;
        do {
            prev = maxLatencyNanos.get();
            if (value <= prev) return;
        } while (!maxLatencyNanos.compareAndSet(prev, value));
    }

    public long count() {
        return count.sum();
    }

    public double avgMicros() {
        long c = count.sum();
        if (c == 0) return 0.0;
        return (totalLatencyNanos.sum() / 1000.0) / c;
    }

    public double minMicros() {
        long v = minLatencyNanos.get();
        return v == Long.MAX_VALUE ? 0.0 : v / 1000.0;
    }

    public double maxMicros() {
        long v = maxLatencyNanos.get();
        return v == Long.MIN_VALUE ? 0.0 : v / 1000.0;
    }
}
