### `RouteWorker.java`
A dedicated worker per route minimizes lock contention and keeps latency predictable.

```java
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;

public final class RouteWorker implements Runnable {
    private final int routeId;
    private final BlockingQueue<Message> queue;
    private final MessageHandler handler;
    private final LatencyStats latencyStats;
    private volatile boolean running = true;

    public RouteWorker(int routeId, int capacity, MessageHandler handler, LatencyStats latencyStats) {
        this.routeId = routeId;
        this.queue = new ArrayBlockingQueue<>(capacity);
        this.handler = handler;
        this.latencyStats = latencyStats;
    }

    public boolean submit(Message message) {
        return queue.offer(message);
    }

    public void shutdown() {
        running = false;
    }

    @Override
    public void run() {
        final Message[] batch = new Message[1024];

        while (running || !queue.isEmpty()) {
            try {
                int n = 0;

                // Drain in batches for throughput
                Message first = queue.poll(1, TimeUnit.MILLISECONDS);
                if (first != null) {
                    batch[n++] = first;
                    n += queue.drainTo(java.util.Arrays.asList(batch).subList(1, batch.length));
                }

                for (int i = 0; i < n; i++) {
                    Message msg = batch[i];
                    if (msg == null) continue;

                    handler.handle(msg);

                    long latency = System.nanoTime() - msg.createdNanos;
                    latencyStats.record(latency);
                    batch[i] = null;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } catch (Exception ex) {
                // In production, log + dead-letter strategy
                ex.printStackTrace();
            }
        }
    }

    public int routeId() {
        return routeId;
    }
}
