### `Router.java`
Routes messages to workers by key.

```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public final class Router {
    private final ConcurrentHashMap<Integer, RouteWorker> workers = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public void registerRoute(int routeId, int capacity, MessageHandler handler, LatencyStats stats) {
        RouteWorker worker = new RouteWorker(routeId, capacity, handler, stats);
        RouteWorker existing = workers.putIfAbsent(routeId, worker);
        if (existing == null) {
            executor.submit(worker);
        }
    }

    public boolean route(Message message) {
        RouteWorker worker = workers.get(message.routeKey);
        if (worker == null) {
            return false;
        }
        return worker.submit(message);
    }

    public void shutdown() {
        workers.values().forEach(RouteWorker::shutdown);
        executor.shutdown();
    }
}
