package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed unit of work.
type Message struct {
	ID        uint64
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nano
	TraceID   uint64
}

// Handler processes messages for a topic.
type Handler func(ctx context.Context, msg Message) error

// Router routes messages to topic handlers.
type Router struct {
	handlers sync.Map // map[string]Handler
}

func (r *Router) Register(topic string, h Handler) {
	r.handlers.Store(topic, h)
}

func (r *Router) Get(topic string) (Handler, bool) {
	v, ok := r.handlers.Load(topic)
	if !ok {
		return nil, false
	}
	return v.(Handler), true
}

// Metrics stores lightweight counters and latency stats.
type Metrics struct {
	received uint64
	routed   uint64
	dropped  uint64
	errors   uint64

	latencyNanos uint64
	latencyCount  uint64
	maxLatency    uint64
}

func (m *Metrics) IncReceived() { atomic.AddUint64(&m.received, 1) }
func (m *Metrics) IncRouted()   { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncDropped()  { atomic.AddUint64(&m.dropped, 1) }
func (m *Metrics) IncErrors()   { atomic.AddUint64(&m.errors, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.latencyNanos, ns)
	atomic.AddUint64(&m.latencyCount, 1)

	for {
		old := atomic.LoadUint64(&m.maxLatency)
		if ns <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.maxLatency, old, ns) {
			return
		}
	}
}

func (m *Metrics) Snapshot() map[string]uint64 {
	count := atomic.LoadUint64(&m.latencyCount)
	sum := atomic.LoadUint64(&m.latencyNanos)

	var avg uint64
	if count > 0 {
		avg = sum / count
	}

	return map[string]uint64{
		"received":     atomic.LoadUint64(&m.received),
		"routed":       atomic.LoadUint64(&m.routed),
		"dropped":      atomic.LoadUint64(&m.dropped),
		"errors":       atomic.LoadUint64(&m.errors),
		"latency_avg_ns": avg,
		"latency_max_ns": atomic.LoadUint64(&m.maxLatency),
		"latency_count":   count,
	}
}

// Shard is a worker queue + goroutine responsible for a subset of messages.
type Shard struct {
	id       int
	queue    chan Message
	router   *Router
	metrics  *Metrics
	stopCh   chan struct{}
	wg       sync.WaitGroup
}

func NewShard(id, queueSize int, router *Router, metrics *Metrics) *Shard {
	return &Shard{
		id:      id,
		queue:   make(chan Message, queueSize),
		router:  router,
		metrics: metrics,
		stopCh:  make(chan struct{}),
	}
}

func (s *Shard) Start() {
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		for {
			select {
			case msg := <-s.queue:
				s.process(msg)
			case <-s.stopCh:
				return
			}
		}
	}()
}

func (s *Shard) Stop() {
	close(s.stopCh)
	s.wg.Wait()
}

func (s *Shard) Enqueue(msg Message) bool {
	select {
	case s.queue <- msg:
		return true
	default:
		return false
	}
}

func (s *Shard) process(msg Message) {
	handler, ok := s.router.Get(msg.Topic)
	if !ok {
		s.metrics.IncDropped()
		return
	}

	start := time.Now()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Millisecond)
	defer cancel()

	if err := handler(ctx, msg); err != nil {
		s.metrics.IncErrors()
	}

	s.metrics.IncRouted()
	s.metrics.ObserveLatency(time.Since(start))
}

// Dispatcher hashes keys to shards for stable routing.
type Dispatcher struct {
	shards  []*Shard
	metrics *Metrics
	nextID  uint64
}

func NewDispatcher(numShards, queueSize int, router *Router, metrics *Metrics) *Dispatcher {
	d := &Dispatcher{
		shards:  make([]*Shard, numShards),
		metrics: metrics,
	}

	for i := 0; i < numShards; i++ {
		d.shards[i] = NewShard(i, queueSize, router, metrics)
	}
	return d
}

func (d *Dispatcher) Start() {
	for _, s := range d.shards {
		s.Start()
	}
}

func (d *Dispatcher) Stop() {
	for _, s := range d.shards {
		s.Stop()
	}
}

func (d *Dispatcher) Dispatch(msg Message) bool {
	d.metrics.IncReceived()

	idx := d.shardIndex(msg.Key, msg.Topic)
	ok := d.shards[idx].Enqueue(msg)
	if !ok {
		d.metrics.IncDropped()
	}
	return ok
}

func (d *Dispatcher) shardIndex(key, topic string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	_, _ = h.Write([]byte(topic))
	return int(h.Sum32() % uint32(len(d.shards)))
}

// Example handlers
func fastHandler(ctx context.Context, msg Message) error {
	// Simulate minimal work
	select {
	case <-ctx.Done():
		return ctx.Err()
	default:
		return nil
	}
}

func slowHandler(ctx context.Context, msg Message) error {
	// Simulate slightly more work
	select {
	case <-time.After(50 * time.Microsecond):
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	router := &Router{}
	router.Register("fast", fastHandler)
	router.Register("slow", slowHandler)

	metrics := &Metrics{}

	numShards := runtime.NumCPU() * 4
	queueSize := 8192

	dispatcher := NewDispatcher(numShards, queueSize, router, metrics)
	dispatcher.Start()
	defer dispatcher.Stop()

	// Latency monitor
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			s := metrics.Snapshot()
			fmt.Printf(
				"received=%d routed=%d dropped=%d errors=%d avg_latency=%dns max_latency=%dns\n",
				s["received"], s["routed"], s["dropped"], s["errors"],
				s["latency_avg_ns"], s["latency_max_ns"],
			)
		}
	}()

	// Simulate high-rate ingestion
	var id uint64
	start := time.Now()
	duration := 5 * time.Second
	end := start.Add(duration)

	for time.Now().Before(end) {
		id++
		msg := Message{
			ID:       id,
			Topic:    "fast",
			Key:      fmt.Sprintf("user-%d", id%10000),
			Payload:  []byte("hello"),
			CreatedAt: time.Now().UnixNano(),
			TraceID:  id ^ 0xdeadbeef,
		}
		_ = dispatcher.Dispatch(msg)
	}

	time.Sleep(2 * time.Second)
}
