package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// =========================
// Message
// =========================

type Message struct {
	ID        uint64
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nano
	ProcessedAt int64 // unix nano
}

// =========================
// Latency metrics
// =========================

type LatencyHistogram struct {
	buckets [64]uint64 // log2 nanosecond buckets
}

func (h *LatencyHistogram) Observe(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	if ns == 0 {
		atomic.AddUint64(&h.buckets[0], 1)
		return
	}
	b := 0
	for ns > 1 && b < len(h.buckets)-1 {
		ns >>= 1
		b++
	}
	atomic.AddUint64(&h.buckets[b], 1)
}

func (h *LatencyHistogram) Snapshot() [64]uint64 {
	var out [64]uint64
	for i := 0; i < 64; i++ {
		out[i] = atomic.LoadUint64(&h.buckets[i])
	}
	return out
}

func (h *LatencyHistogram) Print() {
	s := h.Snapshot()
	var total uint64
	for _, v := range s {
		total += v
	}
	if total == 0 {
		fmt.Println("no latency samples")
		return
	}

	fmt.Printf("latency histogram (log2 ns), total=%d\n", total)
	for i, v := range s {
		if v > 0 {
			low := uint64(1) << i
			high := uint64(1) << (i + 1)
			fmt.Printf("[%d..%d) ns: %d\n", low, high, v)
		}
	}
}

// =========================
// Router
// =========================

type RouteFunc func(msg *Message)

type shard struct {
	in      chan *Message
	handler RouteFunc
	hist    *LatencyHistogram
	dropped uint64
}

type Router struct {
	shards    []*shard
	shardMask uint64
	nextID    uint64
	closed    chan struct{}
	wg        sync.WaitGroup
}

// NewRouter creates a sharded router.
// shardCount should ideally be a power of 2 for fast masking.
func NewRouter(shardCount int, queueSize int, handler RouteFunc) *Router {
	if shardCount <= 0 {
		shardCount = runtime.GOMAXPROCS(0)
	}
	// round up to power of 2
	n := 1
	for n < shardCount {
		n <<= 1
	}
	shardCount = n

	r := &Router{
		shards:    make([]*shard, shardCount),
		shardMask: uint64(shardCount - 1),
		closed:    make(chan struct{}),
	}

	for i := 0; i < shardCount; i++ {
		s := &shard{
			in:      make(chan *Message, queueSize),
			handler: handler,
			hist:    &LatencyHistogram{},
		}
		r.shards[i] = s
		r.wg.Add(1)
		go func(sh *shard) {
			defer r.wg.Done()
			for {
				select {
				case msg := <-sh.in:
					if msg == nil {
						return
					}
					start := time.Now()
					sh.handler(msg)
					msg.ProcessedAt = time.Now().UnixNano()
					sh.hist.Observe(time.Since(time.Unix(0, msg.CreatedAt)))
					_ = start
				case <-r.closed:
					return
				}
			}
		}(s)
	}

	return r
}

func (r *Router) shardFor(key string) *shard {
	h := fnv.New64a()
	_, _ = h.Write([]byte(key))
	idx := h.Sum64() & r.shardMask
	return r.shards[idx]
}

// Publish routes a message.
// Non-blocking: returns false if the shard queue is full.
func (r *Router) Publish(topic, key string, payload []byte) bool {
	id := atomic.AddUint64(&r.nextID, 1)
	msg := &Message{
		ID:       id,
		Topic:    topic,
		Key:      key,
		Payload:  payload,
		CreatedAt: time.Now().UnixNano(),
	}

	sh := r.shardFor(key)

	select {
	case sh.in <- msg:
		return true
	default:
		atomic.AddUint64(&sh.dropped, 1)
		return false
	}
}

// PublishBlocking waits until the message is queued or context is canceled.
func (r *Router) PublishBlocking(ctx context.Context, topic, key string, payload []byte) error {
	id := atomic.AddUint64(&r.nextID, 1)
	msg := &Message{
		ID:       id,
		Topic:    topic,
		Key:      key,
		Payload:  payload,
		CreatedAt: time.Now().UnixNano(),
	}

	sh := r.shardFor(key)

	select {
	case sh.in <- msg:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (r *Router) Close() {
	close(r.closed)
	for _, sh := range r.shards {
		close(sh.in)
	}
	r.wg.Wait()
}

func (r *Router) Metrics() {
	var totalDropped uint64
	for i, sh := range r.shards {
		d := atomic.LoadUint64(&sh.dropped)
		totalDropped += d
		fmt.Printf("shard %d dropped=%d\n", i, d)
		sh.hist.Print()
	}
	fmt.Printf("total dropped=%d\n", totalDropped)
}

// =========================
// Example usage
// =========================

func main() {
	handler := func(msg *Message) {
		// Simulate fast processing
		// In real systems: decode, route downstream, write to socket, etc.
		_ = msg.Payload
	}

	router := NewRouter(8, 65536, handler)
	defer router.Close()

	// High-rate publisher simulation
	for i := 0; i < 1_000_000; i++ {
		ok := router.Publish("orders", fmt.Sprintf("user-%d", i%1024), []byte("hello"))
		if !ok {
			// drop policy under load
		}
	}

	time.Sleep(2 * time.Second)
	router.Metrics()
}
