package main

import (
	"context"
	"errors"
	"fmt"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// -----------------------------
// Message
// -----------------------------

type Message struct {
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nanos
	Sequence  uint64
	Partition int
}

// -----------------------------
// Metrics
// -----------------------------

type Metrics struct {
	Enqueued      uint64
	Dequeued      uint64
	Dropped       uint64
	Processed     uint64
	TotalLatencyNs uint64
	MaxLatencyNs   uint64
}

func (m *Metrics) IncEnqueued() { atomic.AddUint64(&m.Enqueued, 1) }
func (m *Metrics) IncDequeued() { atomic.AddUint64(&m.Dequeued, 1) }
func (m *Metrics) IncDropped()  { atomic.AddUint64(&m.Dropped, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.Processed, 1) }

func (m *Metrics) ObserveLatency(ns uint64) {
	atomic.AddUint64(&m.TotalLatencyNs, ns)

	for {
		old := atomic.LoadUint64(&m.MaxLatencyNs)
		if ns <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.MaxLatencyNs, old, ns) {
			return
		}
	}
}

func (m *Metrics) Snapshot() Metrics {
	return Metrics{
		Enqueued:      atomic.LoadUint64(&m.Enqueued),
		Dequeued:      atomic.LoadUint64(&m.Dequeued),
		Dropped:       atomic.LoadUint64(&m.Dropped),
		Processed:     atomic.LoadUint64(&m.Processed),
		TotalLatencyNs: atomic.LoadUint64(&m.TotalLatencyNs),
		MaxLatencyNs:   atomic.LoadUint64(&m.MaxLatencyNs),
	}
}

// -----------------------------
// Ring buffer queue per shard
// -----------------------------

var ErrQueueFull = errors.New("queue full")

type RingQueue struct {
	buf        []Message
	head       uint64
	tail       uint64
	mask       uint64
	size       uint64
	capacity   uint64
}

func NewRingQueue(capacity int) *RingQueue {
	// capacity must be power of 2 for mask indexing
	c := 1
	for c < capacity {
		c <<= 1
	}
	return &RingQueue{
		buf:      make([]Message, c),
		mask:     uint64(c - 1),
		capacity: uint64(c),
	}
}

func (q *RingQueue) Enqueue(m Message) error {
	if q.size == q.capacity {
		return ErrQueueFull
	}
	q.buf[q.tail&q.mask] = m
	q.tail++
	q.size++
	return nil
}

func (q *RingQueue) Dequeue() (Message, bool) {
	if q.size == 0 {
		return Message{}, false
	}
	m := q.buf[q.head&q.mask]
	q.head++
	q.size--
	return m, true
}

func (q *RingQueue) Len() uint64 {
	return q.size
}

// -----------------------------
// Shard
// -----------------------------

type Shard struct {
	id       int
	queue    *RingQueue
	mu       sync.Mutex
	cond     *sync.Cond
	metrics  *Metrics
	closed   bool
}

func NewShard(id int, queueSize int, metrics *Metrics) *Shard {
	s := &Shard{
		id:      id,
		queue:   NewRingQueue(queueSize),
		metrics: metrics,
	}
	s.cond = sync.NewCond(&s.mu)
	return s
}

func (s *Shard) Enqueue(m Message) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.closed {
		return errors.New("shard closed")
	}

	if err := s.queue.Enqueue(m); err != nil {
		s.metrics.IncDropped()
		return err
	}

	s.metrics.IncEnqueued()
	s.cond.Signal()
	return nil
}

func (s *Shard) DequeueBatch(max int) []Message {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.queue.Len() == 0 {
		return nil
	}

	n := max
	if int(s.queue.Len()) < n {
		n = int(s.queue.Len())
	}

	batch := make([]Message, 0, n)
	for i := 0; i < n; i++ {
		m, ok := s.queue.Dequeue()
		if !ok {
			break
		}
		batch = append(batch, m)
		s.metrics.IncDequeued()
	}
	return batch
}

func (s *Shard) WaitForData(ctx context.Context) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	for s.queue.Len() == 0 && !s.closed {
		done := make(chan struct{})
		go func() {
			select {
			case <-ctx.Done():
				s.mu.Lock()
				s.cond.Broadcast()
				s.mu.Unlock()
			case <-done:
			}
		}()
		s.cond.Wait()
		close(done)

		if ctx.Err() != nil {
			return ctx.Err()
		}
	}
	return nil
}

func (s *Shard) Close() {
	s.mu.Lock()
	s.closed = true
	s.cond.Broadcast()
	s.mu.Unlock()
}

// -----------------------------
// Router
// -----------------------------

type Router struct {
	shards []*Shard
	metrics *Metrics
	seq     uint64
}

func NewRouter(numShards int, queueSize int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]*Shard, numShards),
		metrics: metrics,
	}
	for i := 0; i < numShards; i++ {
		r.shards[i] = NewShard(i, queueSize, metrics)
	}
	return r
}

func (r *Router) shardForKey(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) Publish(key string, payload []byte) error {
	partition := r.shardForKey(key)
	msg := Message{
		Key:       key,
		Payload:   payload,
		CreatedAt:  time.Now().UnixNano(),
		Sequence:   atomic.AddUint64(&r.seq, 1),
		Partition:  partition,
	}
	return r.shards[partition].Enqueue(msg)
}

func (r *Router) Close() {
	for _, s := range r.shards {
		s.Close()
	}
}

// -----------------------------
// Processor
// -----------------------------

type Processor struct {
	router      *Router
	metrics     *Metrics
	batchSize   int
	workersWG   sync.WaitGroup
}

func NewProcessor(router *Router, metrics *Metrics, batchSize int) *Processor {
	return &Processor{
		router:    router,
		metrics:   metrics,
		batchSize: batchSize,
	}
}

func (p *Processor) Start(ctx context.Context) {
	for _, shard := range p.router.shards {
		p.workersWG.Add(1)
		go func(s *Shard) {
			defer p.workersWG.Done()
			p.runShardWorker(ctx, s)
		}(shard)
	}
}

func (p *Processor) runShardWorker(ctx context.Context, shard *Shard) {
	for {
		if err := shard.WaitForData(ctx); err != nil {
			return
		}

		batch := shard.DequeueBatch(p.batchSize)
		if len(batch) == 0 {
			continue
		}

		// Process batch
		for _, msg := range batch {
			p.handleMessage(msg)
		}
	}
}

func (p *Processor) handleMessage(msg Message) {
	// Simulate message handling
	// Replace with business logic / IO / downstream publish
	latency := uint64(time.Now().UnixNano() - msg.CreatedAt)
	p.metrics.IncProcessed()
	p.metrics.ObserveLatency(latency)
}

func (p *Processor) Wait() {
	p.workersWG.Wait()
}

