	processor.Start(ctx)

	// Producer loop
	go func() {
		keys := []string{"user:1", "user:2", "user:3", "user:4"}
		payload := []byte("hello world")

		ticker := time.NewTicker(1 * time.Microsecond)
		defer ticker.Stop()

		for i := 0; i < 10_000_000; i++ {
			<-ticker.C
			key := keys[i%len(keys)]
			if err := router.Publish(key, payload); err != nil {
				// queue full / backpressure
			}
		}
	}()

	// Monitoring
	go func() {
		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			s := metrics.Snapshot()
			avgLatency := uint64(0)
			if s.Processed > 0 {
				avgLatency = s.TotalLatencyNs / s.Processed
			}
			fmt.Printf(
				"enq=%d deq=%d proc=%d drop=%d avg_latency=%s max_latency=%s goroutines=%d\n",
				s.Enqueued,
				s.Dequeued,
				s.Processed,
				s.Dropped,
				time.Duration(avgLatency),
				time.Duration(s.MaxLatencyNs),
				runtime.NumGoroutine(),
			)
		}
	}()

	time.Sleep(10 * time.Second)
	cancel()
	router.Close()
	processor.Wait()
}
