```go
package main

import (
	"context"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt  time.Time
	TraceID    uint64
}

type RouteResult struct {
	Delivered bool
	Err       error
}

type Handler func(msg *Message) RouteResult

// -------------------- Metrics --------------------

type LatencyHistogram struct {
	buckets []int64 // nanosecond upper bounds
	counts  []uint64
}

func NewLatencyHistogram() *LatencyHistogram {
	// Example buckets: 1us, 5us, 10us, 25us, 50us, 100us, 250us, 500us, 1ms, 5ms, 10ms, 50ms
	b := []int64{
		1_000, 5_000, 10_000, 25_000, 50_000, 100_000,
		250_000, 500_000, 1_000_000, 5_000_000, 10_000_000, 50_000_000,
	}
	return &LatencyHistogram{
		buckets: b,
		counts:  make([]uint64, len(b)+1),
	}
}

func (h *LatencyHistogram) Observe(d time.Duration) {
	ns := d.Nanoseconds()
	for i, ub := range h.buckets {
		if ns <= ub {
			atomic.AddUint64(&h.counts[i], 1)
			return
		}
	}
	atomic.AddUint64(&h.counts[len(h.counts)-1], 1)
}

func (h *LatencyHistogram) Snapshot() []uint64 {
	out := make([]uint64, len(h.counts))
	for i := range out {
		out[i] = atomic.LoadUint64(&h.counts[i])
	}
	return out
}

type Metrics struct {
	Received     uint64
	Routed       uint64
	Dropped      uint64
	Errors       uint64
	Inflight     int64
	Hist         *LatencyHistogram
}

func NewMetrics() *Metrics {
	return &Metrics{
		Hist: NewLatencyHistogram(),
	}
}

// -------------------- Router --------------------

type Router struct {
	shards   []chan *Message
	handlers map[string]Handler
	metrics  *Metrics
	rr       uint64
	stop     chan struct{}
	wg       sync.WaitGroup
}

func NewRouter(numShards int) *Router {
	if numShards <= 0 {
		numShards = runtime.GOMAXPROCS(0)
	}
	r := &Router{
		shards:   make([]chan *Message, numShards),
		handlers: make(map[string]Handler),
		metrics:  NewMetrics(),
		stop:     make(chan struct{}),
	}
	for i := range r.shards {
		r.shards[i] = make(chan *Message, 8192)
	}
	return r
}

func (r *Router) Register(topic string, h Handler) {
	r.handlers[topic] = h
}

func (r *Router) Start() {
	for i := range r.shards {
		r.wg.Add(1)
		go r.worker(i, r.shards[i])
	}
}

func (r *Router) Stop() {
	close(r.stop)
	for _, ch := range r.shards {
		close(ch)
	}
	r.wg.Wait()
}

func (r *Router) worker(idx int, ch <-chan *Message) {
	defer r.wg.Done()
	for {
		select {
		case <-r.stop:
			return
		case msg, ok := <-ch:
			if !ok {
				return
			}
			r.process(msg)
		}
	}
}

func (r *Router) process(msg *Message) {
	defer atomic.AddInt64(&r.metrics.Inflight, -1)

	handler, ok := r.handlers[msg.Topic]
	if !ok {
		atomic.AddUint64(&r.metrics.Dropped, 1)
		return
	}

	start := time.Now()
	res := handler(msg)
	lat := time.Since(start)
	r.metrics.Hist.Observe(lat)

	if res.Err != nil {
		atomic.AddUint64(&r.metrics.Errors, 1)
		return
	}
	if res.Delivered {
		atomic.AddUint64(&r.metrics.Routed, 1)
	} else {
		atomic.AddUint64(&r.metrics.Dropped, 1)
	}
}

func (r *Router) Submit(msg *Message) bool {
	atomic.AddUint64(&r.metrics.Received, 1)
	atomic.AddInt64(&r.metrics.Inflight, 1)

	// Sharded round-robin to reduce contention and balance load.
	i := atomic.AddUint64(&r.rr, 1)
	shard := int(i % uint64(len(r.shards)))

	select {
	case r.shards[shard] <- msg:
		return true
	default:
		atomic.AddUint64(&r.metrics.Dropped, 1)
		atomic.AddInt64(&r.metrics.Inflight, -1)
		return false
	}
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}

// -------------------- Example handlers --------------------

func fastHandler(msg *Message) RouteResult {
	// Simulate very low-latency processing.
	_ = len(msg.Payload)
	return RouteResult{Delivered: true}
}

func slowHandler(msg *Message) RouteResult {
	// Example of a slower path.
	time.Sleep(50 * time.Microsecond)
	return RouteResult{Delivered: true}
}

// -------------------- HTTP metrics --------------------

func metricsHandler(m *Metrics) http.HandlerFunc {
	return func(w http.ResponseWriter, _ *http.Request) {
		fmt.Fprintf(w, "received %d\n", atomic.LoadUint64(&m.Received))
		fmt.Fprintf(w, "routed %d\n", atomic.LoadUint64(&m.Routed))
		fmt.Fprintf(w, "dropped %d\n", atomic.LoadUint64(&m.Dropped))
		fmt.Fprintf(w, "errors %d\n", atomic.LoadUint64(&m.Errors))
		fmt.Fprintf(w, "inflight %d\n", atomic.LoadInt64(&m.Inflight))

		h := m.Hist.Snapshot()
		fmt.Fprintln(w, "latency_histogram_ns:")
		for i, c := range h {
			if i < len(m.Hist.buckets) {
				fmt.Fprintf(w, "  <= %d : %d\n", m.Hist.buckets[i], c)
			} else {
				fmt.Fprintf(w, "  +Inf : %d\n", c)
			}
		}
	}
}

// -------------------- Main --------------------

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	router := NewRouter(runtime.NumCPU())
	router.Register("fast", fastHandler)
	router.Register("slow", slowHandler)
	router.Start()
	defer router.Stop()

	http.HandleFunc("/metrics", metricsHandler(router.Metrics()))
	go func() {
		log.Println("metrics server on :8080")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	// Simulated high-rate producer.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		ticker := time.NewTicker(1 * time.Millisecond)
		defer ticker.Stop()

		var id uint64
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				// Burst submit to approximate high-frequency traffic.
				for i := 0; i < 5000; i++ {
					id++
					topic := "fast"
					if rand.Intn(1000) == 0 {
						topic = "slow"
					}
					msg := &Message{
						ID:       id,
						Topic:    topic,
						Payload:  []byte("hello"),
						CreatedAt: time.Now(),
						TraceID:  id ^ 0x9e3779b97f4a7c15,
					}
					router.Submit(msg)
				}
			}
		}
	}()

	select {}
}
