```rust
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};

use bytes::{Buf, BufMut, Bytes, BytesMut};
use hdrhistogram::Histogram;
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
    sync::{mpsc, RwLock},
};

const MAX_FRAME_SIZE: usize = 1024 * 1024; // 1 MB
const CHANNEL_CAPACITY: usize = 100_000;

#[derive(Debug, Clone)]
struct Message {
    topic: String,
    payload: Bytes,
    sent_at: Instant,
}

#[derive(Debug)]
struct RoutedMessage {
    topic: String,
    payload: Bytes,
    sent_at: Instant,
}

#[derive(Default)]
struct Stats {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    bytes_in: AtomicU64,
    bytes_out: AtomicU64,
}

impl Stats {
    fn snapshot(&self) -> StatsSnapshot {
        StatsSnapshot {
            received: self.received.load(Ordering::Relaxed),
            routed: self.routed.load(Ordering::Relaxed),
            dropped: self.dropped.load(Ordering::Relaxed),
            bytes_in: self.bytes_in.load(Ordering::Relaxed),
            bytes_out: self.bytes_out.load(Ordering::Relaxed),
        }
    }
}

#[derive(Debug)]
struct StatsSnapshot {
    received: u64,
    routed: u64,
    dropped: u64,
    bytes_in: u64,
    bytes_out: u64,
}

struct LatencyMonitor {
    histogram: RwLock<Histogram<u64>>,
}

impl LatencyMonitor {
    fn new() -> Self {
        Self {
            histogram: RwLock::new(Histogram::new(3).unwrap()),
        }
    }

    async fn record(&self, latency: Duration) {
        let micros = latency.as_micros() as u64;
        let mut hist = self.histogram.write().await;
        let _ = hist.record(micros);
    }

    async fn snapshot(&self) -> String {
        let hist = self.histogram.read().await;
        format!(
            "p50={}us p95={}us p99={}us max={}us count={}",
            hist.value_at_quantile(0.50),
            hist.value_at_quantile(0.95),
            hist.value_at_quantile(0.99),
            hist.max(),
            hist.len()
        )
    }
}

struct Broker {
    topics: RwLock<HashMap<String, Vec<mpsc::Sender<RoutedMessage>>>>,
    stats: Arc<Stats>,
    latency: Arc<LatencyMonitor>,
}

impl Broker {
    fn new(stats: Arc<Stats>, latency: Arc<LatencyMonitor>) -> Self {
        Self {
            topics: RwLock::new(HashMap::new()),
            stats,
            latency,
        }
    }

    async fn subscribe(&self, topic: String) -> mpsc::Receiver<RoutedMessage> {
        let (tx, rx) = mpsc::channel(CHANNEL_CAPACITY);
        let mut topics = self.topics.write().await;
        topics.entry(topic).or_default().push(tx);
        rx
    }

    async fn publish(&self, msg: RoutedMessage) {
        self.stats.received.fetch_add(1, Ordering::Relaxed);
        self.stats
            .bytes_in
            .fetch_add(msg.payload.len() as u64, Ordering::Relaxed);

        let start = msg.sent_at;
        let topic = msg.topic.clone();

        let subscribers = {
            let topics = self.topics.read().await;
            topics.get(&topic).cloned()
        };

        if let Some(subs) = subscribers {
            let mut routed_count = 0u64;

            for sub in subs {
                let cloned = RoutedMessage {
                    topic: topic.clone(),
                    payload: msg.payload.clone(),
                    sent_at: start,
                };

                match sub.try_send(cloned) {
                    Ok(_) => {
                        routed_count += 1;
                        self.stats.routed.fetch_add(1, Ordering::Relaxed);
                        self.stats
                            .bytes_out
                            .fetch_add(msg.payload.len() as u64, Ordering::Relaxed);
                    }
                    Err(_) => {
                        self.stats.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }

            let latency = Instant::now().duration_since(start);
            self.latency.record(latency).await;

            if routed_count == 0 {
                self.stats.dropped.fetch_add(1, Ordering::Relaxed);
            }
        } else {
            self.stats.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

/// Simple binary protocol:
/// [u32 topic_len][u32 payload_len][topic bytes][payload bytes]
async fn read_message(stream: &mut TcpStream) -> tokio::io::Result<Option<Message>> {
    let mut header = [0u8; 8];
    if stream.read_exact(&mut header).await.is_err() {
        return Ok(None);
    }

    let mut hdr = &header[..];
    let topic_len = hdr.get_u32() as usize;
    let payload_len = hdr.get_u32() as usize;

    if topic_len == 0 || payload_len == 0 || topic_len + payload_len > MAX_FRAME_SIZE {
        return Ok(None);
    }

    let mut topic_buf = vec![0u8; topic_len];
    let mut payload_buf = vec![0u8; payload_len];

    stream.read_exact(&mut topic_buf).await?;
    stream.read_exact(&mut payload_buf).await?;

    let topic = String::from_utf8_lossy(&topic_buf).to_string();
    let payload = Bytes::from(payload_buf);

    Ok(Some(Message {
        topic,
        payload,
        sent_at: Instant::now(),
    }))
}

async fn write_message(stream: &mut TcpStream, msg: &RoutedMessage) -> tokio::io::Result<()> {
    let topic_bytes = msg.topic.as_bytes();
    let payload = &msg.payload;

    let mut buf = BytesMut::with_capacity(8 + topic_bytes.len() + payload.len());
    buf.put_u32(topic_bytes.len() as u32);
    buf.put_u32(payload.len() as u32);
    buf.extend_from_slice(topic_bytes);
    buf.extend_from_slice(payload);

    stream.write_all(&buf).await
}

async fn handle_client(mut stream: TcpStream, broker: Arc<Broker>) -> tokio::io::Result<()> {
    loop {
        match read_message(&mut stream).await? {
            Some(msg) => {
                let routed = RoutedMessage {
                    topic: msg.topic,
                    payload: msg.payload,
                    sent_at: msg.sent_at,
                };
                broker.publish(routed).await;
            }
            None => break,
        }
    }
    Ok(())
}

async fn subscriber_task(
    mut rx: mpsc::Receiver<RoutedMessage>,
    mut stream: TcpStream,
    latency: Arc<LatencyMonitor>,
) -> tokio::io::Result<()> {
    while let Some(msg) = rx.recv().await {
        let sent = msg.sent_at;
        write_message(&mut stream, &msg).await?;
        let end_to_end = Instant::now().duration_since(sent);
        latency.record(end_to_end).await;
    }
    Ok(())
}

async fn metrics_task(stats: Arc<Stats>, latency: Arc<LatencyMonitor>) {
    loop {
        tokio::time::sleep(Duration::from_secs(5)).await;
        let snap = stats.snapshot();
        let lat = latency.snapshot().await;

        println!(
            "[metrics] received={} routed={} dropped={} bytes_in={} bytes_out={} {}",
            snap.received, snap.routed, snap.dropped, snap.bytes_in, snap.bytes_out, lat
        );
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> tokio::io::Result<()> {
    let stats = Arc::new(Stats::default());
    let latency = Arc::new(LatencyMonitor::new());
    let broker = Arc::new(Broker::new(stats.clone(), latency.clone()));

    tokio::spawn(metrics_task(stats.clone(), latency.clone()));

    let listener: TcpListener = TcpListener::bind("0.0.0.0:9000").await?;
    println!("Broker listening on 0.0.0.0:9000");

    loop {
        let (stream, addr) = listener.accept().await?;
        let broker = broker.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, broker).await {
                eprintln!("client {} error: {}", addr, e);
            }
        });
    }
}
