## 2) Initial Go implementation

This is a compact but realistic starting point.

### `main.go`
```go
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     uint32
	Payload   []byte
	CreatedAt int64 // unix nano
}

type RoutedMessage struct {
	Message
	RoutedAt int64
}

type LatencyMetrics struct {
	mu        sync.Mutex
	samplesNs []int64
	count     uint64
}

func NewLatencyMetrics(capacity int) *LatencyMetrics {
	return &LatencyMetrics{
		samplesNs: make([]int64, 0, capacity),
	}
}

func (m *LatencyMetrics) Observe(latency time.Duration) {
	m.mu.Lock()
	m.samplesNs = append(m.samplesNs, latency.Nanoseconds())
	m.count++
	m.mu.Unlock()
}

func (m *LatencyMetrics) Snapshot() (count uint64, p50, p95, p99 time.Duration) {
	m.mu.Lock()
	defer m.mu.Unlock()

	if len(m.samplesNs) == 0 {
		return m.count, 0, 0, 0
	}

	cp := make([]int64, len(m.samplesNs))
	copy(cp, m.samplesNs)
	sort.Slice(cp, func(i, j int) bool { return cp[i] < cp[j] })

	pick := func(q float64) time.Duration {
		idx := int(float64(len(cp)-1) * q)
		return time.Duration(cp[idx])
	}

	return m.count, pick(0.50), pick(0.95), pick(0.99)
}

type Router struct {
	workers int
	in      chan Message
	out     []chan RoutedMessage
	metrics *LatencyMetrics
	stop    chan struct{}
	wg      sync.WaitGroup
	seq     uint64
}

func NewRouter(workers, partitions, queueSize int, metrics *LatencyMetrics) *Router {
	r := &Router{
		workers: workers,
		in:      make(chan Message, queueSize),
		out:     make([]chan RoutedMessage, partitions),
		metrics: metrics,
		stop:    make(chan struct{}),
	}

	for i := range r.out {
		r.out[i] = make(chan RoutedMessage, queueSize)
	}
	return r
}

func (r *Router) Start() {
	// Start partition consumers
	for i := range r.out {
		r.wg.Add(1)
		go func(partition int) {
			defer r.wg.Done()
			for {
				select {
				case msg := <-r.out[partition]:
					// Simulate downstream handling
					now := time.Now().UnixNano()
					latency := time.Duration(now - msg.CreatedAt)
					r.metrics.Observe(latency)

				case <-r.stop:
					return
				}
			}
		}(i)
	}

	// Start router workers
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go func() {
			defer r.wg.Done()
			for {
				select {
				case msg := <-r.in:
					msgID := atomic.AddUint64(&r.seq, 1)
					msg.ID = msgID

					partition := int(msg.Topic % uint32(len(r.out)))
					routed := RoutedMessage{
						Message:  msg,
						RoutedAt: time.Now().UnixNano(),
					}

					select {
					case r.out[partition] <- routed:
					default:
						// Backpressure / drop policy
						// In production, consider retry, spillover, or circuit breaking
					}

				case <-r.stop:
					return
				}
			}
		}()
	}
}

func (r *Router) Stop() {
	close(r.stop)
	r.wg.Wait()
}

func (r *Router) Submit(topic uint32, payload []byte) bool {
	msg := Message{
		Topic:     topic,
		Payload:   payload,
		CreatedAt: time.Now().UnixNano(),
	}

	select {
	case r.in <- msg:
		return true
	default:
		return false
	}
}

func main() {
	metrics := NewLatencyMetrics(1_000_000)
	router := NewRouter(
		workers:   8,
		partitions: 16,
		queueSize:  4096,
		metrics:    metrics,
	)

	router.Start()
	defer router.Stop()

	// Simulate high-rate producers
	var produced, dropped uint64
	producerCount := 8
	runtime := 5 * time.Second
	end := time.Now().Add(runtime)

	var prodWG sync.WaitGroup
	for p := 0; p < producerCount; p++ {
		prodWG.Add(1)
		go func(seed int64) {
			defer prodWG.Done()
			rng := rand.New(rand.NewSource(seed))
			payload := make([]byte, 256)

			for time.Now().Before(end) {
				for i := range payload {
					payload[i] = byte(rng.Intn(256))
				}
				if router.Submit(uint32(rng.Intn(128)), payload) {
					atomic.AddUint64(&produced, 1)
				} else {
					atomic.AddUint64(&dropped, 1)
				}
			}
		}(int64(p + 1))
	}

	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	done := make(chan struct{})
	go func() {
		prodWG.Wait()
		close(done)
	}()

	for {
		select {
		case <-ticker.C:
			count, p50, p95, p99 := metrics.Snapshot()
			fmt.Printf("metrics: handled=%d p50=%s p95=%s p99=%s produced=%d dropped=%d\n",
				count, p50, p95, p99, atomic.LoadUint64(&produced), atomic.LoadUint64(&dropped))

		case <-done:
			count, p50, p95, p99 := metrics.Snapshot()
			fmt.Printf("final: handled=%d p50=%s p95=%s p99=%s produced=%d dropped=%d\n",
				count, p50, p95, p99, atomic.LoadUint64(&produced), atomic.LoadUint64(&dropped))
			return
		}
	}
}
