### `LatencyStats.java`
```java
import java.util.concurrent.atomic.LongAdder;

public final class LatencyStats {
    private final LongAdder count = new LongAdder();
    private final LongAdder totalNanos = new LongAdder();
    private final LongAdder maxNanos = new LongAdder();

    public void record(long latencyNanos) {
        count.increment();
        totalNanos.add(latencyNanos);

        // Simple max update; not strictly atomic but good enough for initial monitoring
        long currentMax = maxNanos.sum();
        if (latencyNanos > currentMax) {
            maxNanos.add(latencyNanos - currentMax);
        }
    }

    public long getCount() {
        return count.sum();
    }

    public double getAverageMicros() {
        long c = count.sum();
        return c == 0 ? 0.0 : (totalNanos.sum() / 1000.0) / c;
    }

    public double getMaxMicros() {
        return maxNanos.sum() / 1000.0;
    }
}
