### `TopicWorker.java`
```java
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.TimeUnit;

public final class TopicWorker implements Runnable {
    private final String topic;
    private final ArrayBlockingQueue<Message> queue;
    private final MessageHandler handler;
    private final LatencyStats latencyStats;
    private volatile boolean running = true;

    public TopicWorker(String topic, int capacity, MessageHandler handler, LatencyStats latencyStats) {
        this.topic = topic;
        this.queue = new ArrayBlockingQueue<>(capacity);
        this.handler = handler;
        this.latencyStats = latencyStats;
    }

    public boolean offer(Message message) {
        return queue.offer(message);
    }

    public void stop() {
        running = false;
    }

    @Override
    public void run() {
        while (running || !queue.isEmpty()) {
            try {
                Message msg = queue.poll(1, TimeUnit.MILLISECONDS);
                if (msg == null) {
                    continue;
                }

                long latency = System.nanoTime() - msg.getCreatedNanos();
                latencyStats.record(latency);

                handler.onMessage(msg);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } catch (Exception ex) {
                // In production: route to DLQ / error handling / logging
                System.err.println("Error processing message on topic " + topic + ": " + ex.getMessage());
            }
        }
    }
}
