### `MessageRouter.java`
```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public final class MessageRouter {
    private final ConcurrentHashMap<String, TopicWorker> routes = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public void registerTopic(String topic, int queueCapacity, MessageHandler handler, LatencyStats latencyStats) {
        TopicWorker worker = new TopicWorker(topic, queueCapacity, handler, latencyStats);
        TopicWorker existing = routes.putIfAbsent(topic, worker);
        if (existing == null) {
            executor.submit(worker);
        }
    }

    public boolean publish(Message message) {
        TopicWorker worker = routes.get(message.getTopic());
        if (worker == null) {
            return false;
        }
        return worker.offer(message);
    }

    public void shutdown() {
        for (TopicWorker worker : routes.values()) {
            worker.stop();
        }
        executor.shutdown();
    }
}
