### `main.go`

```go
package main

import (
	"fmt"
	"log"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt  int64 // unix nano
	SequenceID uint64
}

type Subscriber struct {
	ID      string
	Ch      chan Message
	Closed  atomic.Bool
	Latency *LatencyTracker
}

type LatencyTracker struct {
	count uint64
	sumNs uint64
	minNs uint64
	maxNs uint64
}

func NewLatencyTracker() *LatencyTracker {
	return &LatencyTracker{
		minNs: ^uint64(0),
	}
}

func (lt *LatencyTracker) Record(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&lt.count, 1)
	atomic.AddUint64(&lt.sumNs, ns)

	for {
		oldMin := atomic.LoadUint64(&lt.minNs)
		if ns >= oldMin {
			break
		}
		if atomic.CompareAndSwapUint64(&lt.minNs, oldMin, ns) {
			break
		}
	}

	for {
		oldMax := atomic.LoadUint64(&lt.maxNs)
		if ns <= oldMax {
			break
		}
		if atomic.CompareAndSwapUint64(&lt.maxNs, oldMax, ns) {
			break
		}
	}
}

func (lt *LatencyTracker) Snapshot() (count, avgNs, minNs, maxNs uint64) {
	count = atomic.LoadUint64(&lt.count)
	sum := atomic.LoadUint64(&lt.sumNs)
	minNs = atomic.LoadUint64(&lt.minNs)
	maxNs = atomic.LoadUint64(&lt.maxNs)

	if count > 0 {
		avgNs = sum / count
	}
	return
}

type TopicRouter struct {
	subscribers sync.Map // map[string]*Subscriber
	seq         atomic.Uint64
	delivered   atomic.Uint64
	dropped     atomic.Uint64
}

func NewTopicRouter() *TopicRouter {
	return &TopicRouter{}
}

func (r *TopicRouter) Subscribe(id string, buffer int, tracker *LatencyTracker) *Subscriber {
	sub := &Subscriber{
		ID:      id,
		Ch:      make(chan Message, buffer),
		Latency: tracker,
	}
	r.subscribers.Store(id, sub)
	return sub
}

func (r *TopicRouter) Unsubscribe(id string) {
	if v, ok := r.subscribers.Load(id); ok {
		sub := v.(*Subscriber)
		if sub.Closed.CompareAndSwap(false, true) {
			close(sub.Ch)
		}
		r.subscribers.Delete(id)
	}
}

func (r *TopicRouter) Publish(topic string, payload []byte) {
	msg := Message{
		Topic:     topic,
		Payload:   payload,
		CreatedAt:  time.Now().UnixNano(),
		SequenceID: r.seq.Add(1),
	}

	r.subscribers.Range(func(_, value any) bool {
		sub := value.(*Subscriber)
		if sub.Closed.Load() {
			return true
		}

		// Non-blocking send to keep latency low under load.
		select {
		case sub.Ch <- msg:
			r.delivered.Add(1)
		default:
			r.dropped.Add(1)
		}
		return true
	})
}

func (r *TopicRouter) Stats() (delivered, dropped uint64) {
	return r.delivered.Load(), r.dropped.Load()
}

func main() {
	router := NewTopicRouter()
	tracker := NewLatencyTracker()

	sub := router.Subscribe("sub-1", 1024, tracker)

	var wg sync.WaitGroup
	wg.Add(1)

	go func() {
		defer wg.Done()
		for msg := range sub.Ch {
			latency := time.Since(time.Unix(0, msg.CreatedAt))
			sub.Latency.Record(latency)

			// Simulate lightweight processing
			_ = msg.Payload
		}
	}()

	// Simulate high-rate publishing
	const total = 1_000_000
	start := time.Now()

	for i := 0; i < total; i++ {
		router.Publish("orders", []byte("hello"))
	}

	// Allow consumer to drain
	time.Sleep(500 * time.Millisecond)
	router.Unsubscribe("sub-1")
	wg.Wait()

	elapsed := time.Since(start)
	delivered, dropped := router.Stats()
	count, avgNs, minNs, maxNs := tracker.Snapshot()

	fmt.Printf("Published: %d\n", total)
	fmt.Printf("Delivered: %d\n", delivered)
	fmt.Printf("Dropped: %d\n", dropped)
	fmt.Printf("Processed: %d\n", count)
	fmt.Printf("Latency avg: %d ns, min: %d ns, max: %d ns\n", avgNs, minNs, maxNs)
	fmt.Printf("Throughput: %.2f msgs/sec\n", float64(total)/elapsed.Seconds())
}
```

