# Go implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"math/rand"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Key       string
	Payload   []byte
	CreatedAt  time.Time
	Sequence  uint64
}

type Metrics struct {
	Received        uint64
	Routed          uint64
	Processed       uint64
	Dropped         uint64
	TotalLatencyNs  uint64
}

type LatencyWindow struct {
	mu        sync.Mutex
	samplesNs  []int64
	maxSamples int
}

func NewLatencyWindow(maxSamples int) *LatencyWindow {
	return &LatencyWindow{
		samplesNs:  make([]int64, 0, maxSamples),
		maxSamples: maxSamples,
	}
}

func (lw *LatencyWindow) Add(d time.Duration) {
	lw.mu.Lock()
	defer lw.mu.Unlock()

	if len(lw.samplesNs) >= lw.maxSamples {
		// Simple ring-like behavior: drop oldest by shifting.
		// For a real system, use a circular buffer.
		copy(lw.samplesNs, lw.samplesNs[1:])
		lw.samplesNs[len(lw.samplesNs)-1] = d.Nanoseconds()
		return
	}
	lw.samplesNs = append(lw.samplesNs, d.Nanoseconds())
}

func (lw *LatencyWindow) Snapshot() (p50, p95, p99 time.Duration, avg time.Duration) {
	lw.mu.Lock()
	defer lw.mu.Unlock()

	if len(lw.samplesNs) == 0 {
		return 0, 0, 0, 0
	}

	cp := make([]int64, len(lw.samplesNs))
	copy(cp, lw.samplesNs)
	sort.Slice(cp, func(i, j int) bool { return cp[i] < cp[j] })

	sum := int64(0)
	for _, v := range cp {
		sum += v
	}

	idx := func(p float64) int {
		i := int(float64(len(cp)-1) * p)
		if i < 0 {
			i = 0
		}
		if i >= len(cp) {
			i = len(cp) - 1
		}
		return i
	}

	return time.Duration(cp[idx(0.50)]),
		time.Duration(cp[idx(0.95)]),
		time.Duration(cp[idx(0.99)]),
		time.Duration(sum / int64(len(cp)))
}

type Worker struct {
	id       int
	ch       chan Message
	metrics  *Metrics
	latency  *LatencyWindow
	stopOnce sync.Once
}

func NewWorker(id int, queueSize int, metrics *Metrics, latency *LatencyWindow) *Worker {
	return &Worker{
		id:      id,
		ch:      make(chan Message, queueSize),
		metrics: metrics,
		latency: latency,
	}
}

func (w *Worker) Start(ctx context.Context, wg *sync.WaitGroup) {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case msg := <-w.ch:
				w.process(msg)
			}
		}
	}()
}

func (w *Worker) process(msg Message) {
	// Simulate ultra-light processing.
	// Replace with actual business logic.
	atomic.AddUint64(&w.metrics.Processed, 1)

	lat := time.Since(msg.CreatedAt)
	atomic.AddUint64(&w.metrics.TotalLatencyNs, uint64(lat.Nanoseconds()))
	w.latency.Add(lat)
}

type Router struct {
	workers []*Worker
	metrics *Metrics
}

func NewRouter(workers []*Worker, metrics *Metrics) *Router {
	return &Router{
		workers: workers,
		metrics: metrics,
	}
}

func (r *Router) hashKey(key string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return h.Sum32()
}

func (r *Router) Route(msg Message) bool {
	atomic.AddUint64(&r.metrics.Received, 1)

	if len(r.workers) == 0 {
		atomic.AddUint64(&r.metrics.Dropped, 1)
		return false
	}

	idx := int(r.hashKey(msg.Key) % uint32(len(r.workers)))
	w := r.workers[idx]

	select {
	case w.ch <- msg:
		atomic.AddUint64(&r.metrics.Routed, 1)
		return true
	default:
		// Backpressure/drop policy for initial implementation.
		atomic.AddUint64(&r.metrics.Dropped, 1)
		return false
	}
}

type System struct {
	router  *Router
	workers []*Worker
	metrics *Metrics
	latency *LatencyWindow
}

func NewSystem(numWorkers int, queueSize int, latencySamples int) *System {
	metrics := &Metrics{}
	latency := NewLatencyWindow(latencySamples)

	workers := make([]*Worker, 0, numWorkers)
	for i := 0; i < numWorkers; i++ {
		workers = append(workers, NewWorker(i, queueSize, metrics, latency))
	}

	router := NewRouter(workers, metrics)

	return &System{
		router:  router,
		workers: workers,
		metrics: metrics,
		latency: latency,
	}
}

func (s *System) Start(ctx context.Context, wg *sync.WaitGroup) {
	for _, w := range s.workers {
		w.Start(ctx, wg)
	}
}

func (s *System) Submit(key string, payload []byte, seq uint64) bool {
	msg := Message{
		Key:      key,
		Payload:  payload,
		CreatedAt: time.Now(),
		Sequence: seq,
	}
	return s.router.Route(msg)
}

func (s *System) Snapshot() {
	received := atomic.LoadUint64(&s.metrics.Received)
	routed := atomic.LoadUint64(&s.metrics.Routed)
	processed := atomic.LoadUint64(&s.metrics.Processed)
	dropped := atomic.LoadUint64(&s.metrics.Dropped)

	avg := time.Duration(0)
	totalLat := atomic.LoadUint64(&s.metrics.TotalLatencyNs)
	if processed > 0 {
		avg = time.Duration(totalLat / processed)
	}

	p50, p95, p99, windowAvg := s.latency.Snapshot()

	fmt.Printf(
		"received=%d routed=%d processed=%d dropped=%d avg=%s window_avg=%s p50=%s p95=%s p99=%s\n",
		received, routed, processed, dropped, avg, windowAvg, p50, p95, p99,
	)
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	system := NewSystem(
		8,      // workers
		4096,   // queue size per worker
		10000,  // latency samples
	)

	var wg sync.WaitGroup
	system.Start(ctx, &wg)

	// Metrics reporter
	go func() {
		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()
		for {
