# Go implementation

```go
package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a high-frequency event.
// SentAt is used for latency monitoring.
type Message struct {
	Topic   string
	Key     string
	Payload []byte
	SentAt  int64 // unix nano
}

// Subscriber receives messages from a topic.
type Subscriber struct {
	ID   string
	ch   chan Message
	done chan struct{}
}

// NewSubscriber creates a bounded subscriber queue.
func NewSubscriber(id string, buffer int) *Subscriber {
	return &Subscriber{
		ID:   id,
		ch:   make(chan Message, buffer),
		done: make(chan struct{}),
	}
}

// Start begins consuming messages.
// In a real system, this would likely invoke a callback or batch processor.
func (s *Subscriber) Start(process func(Message)) {
	go func() {
		for {
			select {
			case msg := <-s.ch:
				process(msg)
			case <-s.done:
				return
			}
		}
	}()
}

// Stop terminates the subscriber.
func (s *Subscriber) Stop() {
	close(s.done)
}

// TrySend attempts to enqueue a message without blocking.
func (s *Subscriber) TrySend(msg Message) bool {
	select {
	case s.ch <- msg:
		return true
	default:
		return false
	}
}

// Metrics tracks routing and latency stats.
type Metrics struct {
	routedCount   uint64
	droppedCount   uint64
	latencyCount   uint64
	latencyTotalNs uint64
	latencyMaxNs   uint64
}

// RecordRouted increments routed count.
func (m *Metrics) RecordRouted() {
	atomic.AddUint64(&m.routedCount, 1)
}

// RecordDropped increments dropped count.
func (m *Metrics) RecordDropped() {
	atomic.AddUint64(&m.droppedCount, 1)
}

// RecordLatency updates latency stats.
func (m *Metrics) RecordLatency(ns uint64) {
	atomic.AddUint64(&m.latencyCount, 1)
	atomic.AddUint64(&m.latencyTotalNs, ns)

	for {
		current := atomic.LoadUint64(&m.latencyMaxNs)
		if ns <= current {
			break
		}
		if atomic.CompareAndSwapUint64(&m.latencyMaxNs, current, ns) {
			break
		}
	}
}

// Snapshot returns a point-in-time view of metrics.
func (m *Metrics) Snapshot() (routed, dropped, latencyCount, avgLatencyNs, maxLatencyNs uint64) {
	routed = atomic.LoadUint64(&m.routedCount)
	dropped = atomic.LoadUint64(&m.droppedCount)
	latencyCount = atomic.LoadUint64(&m.latencyCount)
	total := atomic.LoadUint64(&m.latencyTotalNs)
	maxLatencyNs = atomic.LoadUint64(&m.latencyMaxNs)

	if latencyCount > 0 {
		avgLatencyNs = total / latencyCount
	}
	return
}

// Router routes messages to subscribers by topic.
type Router struct {
	mu          sync.RWMutex
	subscribers  map[string]map[string]*Subscriber // topic -> subscriberID -> subscriber
	metrics      *Metrics
}

// NewRouter creates a router instance.
func NewRouter() *Router {
	return &Router{
		subscribers: make(map[string]map[string]*Subscriber),
		metrics:     &Metrics{},
	}
}

// Subscribe registers a subscriber to a topic.
func (r *Router) Subscribe(topic string, sub *Subscriber) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, ok := r.subscribers[topic]; !ok {
		r.subscribers[topic] = make(map[string]*Subscriber)
	}
	r.subscribers[topic][sub.ID] = sub
}

// Unsubscribe removes a subscriber from a topic.
func (r *Router) Unsubscribe(topic, subID string) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if subs, ok := r.subscribers[topic]; ok {
		delete(subs, subID)
		if len(subs) == 0 {
			delete(r.subscribers, topic)
		}
	}
}

// Publish routes a message to all subscribers of the topic.
// It is non-blocking per subscriber: if the queue is full, the message is dropped.
func (r *Router) Publish(msg Message) {
	start := time.Now()

	r.mu.RLock()
	subs := r.subscribers[msg.Topic]
	// Copy pointers to avoid holding lock during delivery.
	targets := make([]*Subscriber, 0, len(subs))
	for _, sub := range subs {
		targets = append(targets, sub)
	}
	r.mu.RUnlock()

	for _, sub := range targets {
		if sub.TrySend(msg) {
			r.metrics.RecordRouted()
		} else {
			r.metrics.RecordDropped()
		}
	}

	latency := time.Since(time.Unix(0, msg.SentAt))
	r.metrics.RecordLatency(uint64(latency.Nanoseconds()))

	_ = start
}

// Metrics returns the router metrics.
func (r *Router) Metrics() *Metrics {
	return r.metrics
}

func main() {
	router := NewRouter()

	// Create subscribers.
	sub1 := NewSubscriber("sub-1", 1024)
	sub2 := NewSubscriber("sub-2", 1024)

	// Start processing.
	sub1.Start(func(msg Message) {
		// Simulate lightweight processing.
		_ = msg
	})

	sub2.Start(func(msg Message) {
		_ = msg
	})

	// Subscribe them to a topic.
	router.Subscribe("orders", sub1)
	router.Subscribe("orders", sub2)

	// Simulate high-frequency publishing.
	const totalMessages = 100000
	for i := 0; i < totalMessages; i++ {
		router.Publish(Message{
			Topic:   "orders",
			Key:     fmt.Sprintf("order-%d", i),
			Payload: []byte("payload"),
			SentAt:  time.Now().UnixNano(),
		})
	}

	// Give consumers a moment to drain.
	time.Sleep(500 * time.Millisecond)

	routed, dropped, latencyCount, avgLatencyNs, maxLatencyNs := router.Metrics().Snapshot()
	fmt.Println("=== Metrics ===")
	fmt.Printf("Routed:       %d\n", routed)
	fmt.Printf("Dropped:      %d\n", dropped)
	fmt.Printf("LatencyCount: %d\n", latencyCount)
	fmt.Printf("AvgLatencyNs: %d\n", avgLatencyNs)
	fmt.Printf("MaxLatencyNs: %d\n", maxLatencyNs)

	sub1.Stop()
	sub2.Stop()
}
