```go
package main

import (
	"fmt"
	"hash/fnv"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

type Metrics struct {
	Ingested        atomic.Uint64
	Routed          atomic.Uint64
	Dispatched      atomic.Uint64
	Processed       atomic.Uint64
	Dropped         atomic.Uint64
	TotalLatencyNS  atomic.Uint64
	MaxLatencyNS    atomic.Uint64
	QueueDepth      atomic.Uint64
}

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	m.TotalLatencyNS.Add(ns)

	for {
		old := m.MaxLatencyNS.Load()
		if ns <= old {
			break
		}
		if m.MaxLatencyNS.CompareAndSwap(old, ns) {
			break
		}
	}
}

func (m *Metrics) AvgLatency() time.Duration {
	processed := m.Processed.Load()
	if processed == 0 {
		return 0
	}
	return time.Duration(m.TotalLatencyNS.Load() / processed)
}

type Router struct {
	shards  []chan Message
	metrics *Metrics
}

func NewRouter(numShards int, queueSize int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]chan Message, numShards),
		metrics: metrics,
	}
	for i := range r.shards {
		r.shards[i] = make(chan Message, queueSize)
	}
	return r
}

func (r *Router) shardFor(topic string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) Route(msg Message) bool {
	idx := r.shardFor(msg.Topic)
	select {
	case r.shards[idx] <- msg:
		r.metrics.Routed.Add(1)
		r.metrics.QueueDepth.Add(1)
		return true
	default:
		r.metrics.Dropped.Add(1)
		return false
	}
}

type Consumer struct {
	id      int
	in      chan Message
	metrics *Metrics
	batch   int
}

func NewConsumer(id int, in chan Message, metrics *Metrics, batch int) *Consumer {
	return &Consumer{id: id, in: in, metrics: metrics, batch: batch}
}

func (c *Consumer) Start(wg *sync.WaitGroup) {
	defer wg.Done()

	batch := make([]Message, 0, c.batch)

	for {
		msg, ok := <-c.in
		if !ok {
			return
		}
		batch = append(batch, msg)

		drain := true
		for drain && len(batch) < c.batch {
			select {
			case m, ok := <-c.in:
				if !ok {
					drain = false
					break
				}
				batch = append(batch, m)
			default:
				drain = false
			}
		}

		for _, m := range batch {
			// Simulate processing
			_ = m.Payload

			latency := time.Since(m.CreatedAt)
			c.metrics.Processed.Add(1)
			c.metrics.ObserveLatency(latency)
			c.metrics.QueueDepth.Add(^uint64(0)) // decrement by 1
		}

		c.metrics.Dispatched.Add(uint64(len(batch)))
		batch = batch[:0]
	}
}

type System struct {
	router   *Router
	metrics  *Metrics
	workers  []*Consumer
	wg       sync.WaitGroup
	stopOnce sync.Once
	stopCh   chan struct{}
}

func NewSystem(numShards, queueSize, batchSize int) *System {
	metrics := &Metrics{}
	router := NewRouter(numShards, queueSize, metrics)

	s := &System{
		router:  router,
		metrics: metrics,
		stopCh:  make(chan struct{}),
	}

	for i := 0; i < numShards; i++ {
		c := NewConsumer(i, router.shards[i], metrics, batchSize)
		s.workers = append(s.workers, c)
	}
	return s
}

func (s *System) Start() {
	for _, w := range s.workers {
		s.wg.Add(1)
		go w.Start(&s.wg)
	}
}

func (s *System) Stop() {
	s.stopOnce.Do(func() {
		close(s.stopCh)
		for _, ch := range s.router.shards {
			close(ch)
		}
	})
	s.wg.Wait()
}

func (s *System) Publish(topic string, payload []byte, id uint64) bool {
	s.metrics.Ingested.Add(1)
	msg := Message{
		ID:        id,
		Topic:     topic,
		Payload:   payload,
		CreatedAt: time.Now(),
	}
	return s.router.Route(msg)
}

func main() {
	sys := NewSystem(8, 100000, 256)
	sys.Start()

	// Simulate load
	for i := 0; i < 1000000; i++ {
		ok := sys.Publish("orders", []byte("hello"), uint64(i))
		if !ok {
			// dropped due to backpressure
		}
	}

	time.Sleep(2 * time.Second)
	sys.Stop()

	fmt.Println("Ingested:", sys.metrics.Ingested.Load())
	fmt.Println("Routed:", sys.metrics.Routed.Load())
	fmt.Println("Processed:", sys.metrics.Processed.Load())
	fmt.Println("Dropped:", sys.metrics.Dropped.Load())
	fmt.Println("Avg latency:", sys.metrics.AvgLatency())
	fmt.Println("Max latency (ns):", sys.metrics.MaxLatencyNS.Load())
}
