## Go implementation

### `main.go`

```go
package main

import (
	"context"
	"fmt"
	"log"
	"math"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nanos
}

type Subscriber struct {
	ID      string
	Ch      chan Message
	Closed  atomic.Bool
	Latency *LatencyMonitor
}

type Router struct {
	mu          sync.RWMutex
	subscribers map[string][]*Subscriber
	inbox       chan Message
	closed      atomic.Bool

	published uint64
	dropped   uint64
	routed    uint64
}

func NewRouter(inboxSize int) *Router {
	r := &Router{
		subscribers: make(map[string][]*Subscriber),
		inbox:       make(chan Message, inboxSize),
	}
	return r
}

func (r *Router) Start(ctx context.Context, workers int) {
	for i := 0; i < workers; i++ {
		go r.worker(ctx, i)
	}
}

func (r *Router) worker(ctx context.Context, id int) {
	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-r.inbox:
			r.dispatch(msg)
		}
	}
}

func (r *Router) Publish(msg Message) bool {
	if r.closed.Load() {
		return false
	}

	select {
	case r.inbox <- msg:
		atomic.AddUint64(&r.published, 1)
		return true
	default:
		atomic.AddUint64(&r.dropped, 1)
		return false
	}
}

func (r *Router) Subscribe(topic string, sub *Subscriber) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.subscribers[topic] = append(r.subscribers[topic], sub)
}

func (r *Router) Unsubscribe(topic string, subID string) {
	r.mu.Lock()
	defer r.mu.Unlock()

	subs := r.subscribers[topic]
	out := subs[:0]
	for _, s := range subs {
		if s.ID != subID {
			out = append(out, s)
		}
	}
	if len(out) == 0 {
		delete(r.subscribers, topic)
	} else {
		r.subscribers[topic] = out
	}
}

func (r *Router) dispatch(msg Message) {
	r.mu.RLock()
	subs := r.subscribers[msg.Topic]
	// Copy slice header only; underlying array is read-only here.
	r.mu.RUnlock()

	if len(subs) == 0 {
		return
	}

	for _, sub := range subs {
		if sub.Closed.Load() {
			continue
		}

		select {
		case sub.Ch <- msg:
			atomic.AddUint64(&r.routed, 1)
		default:
			// Subscriber backpressure: drop message for this subscriber
			atomic.AddUint64(&r.dropped, 1)
		}
	}
}

func (r *Router) Close() {
	r.closed.Store(true)
}

func (r *Router) Stats() (published, dropped, routed uint64) {
	return atomic.LoadUint64(&r.published),
		atomic.LoadUint64(&r.dropped),
		atomic.LoadUint64(&r.routed)
}

// LatencyMonitor tracks message latency in nanoseconds using buckets.
type LatencyMonitor struct {
	buckets [64]uint64
	count   uint64
	sum     uint64
	max     uint64
}

func NewLatencyMonitor() *LatencyMonitor {
	return &LatencyMonitor{}
}

func (lm *LatencyMonitor) Observe(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	if ns == 0 {
		ns = 1
	}

	b := bucketIndex(ns)
	atomic.AddUint64(&lm.buckets[b], 1)
	atomic.AddUint64(&lm.count, 1)
	atomic.AddUint64(&lm.sum, ns)

	for {
		old := atomic.LoadUint64(&lm.max)
		if ns <= old || atomic.CompareAndSwapUint64(&lm.max, old, ns) {
			break
		}
	}
}

func (lm *LatencyMonitor) Snapshot() (count, sum, max uint64, buckets [64]uint64) {
	count = atomic.LoadUint64(&lm.count)
	sum = atomic.LoadUint64(&lm.sum)
	max = atomic.LoadUint64(&lm.max)
	for i := range buckets {
		buckets[i] = atomic.LoadUint64(&lm.buckets[i])
	}
	return
}

func bucketIndex(ns uint64) int {
	// log2 bucketization
	return int(math.Log2(float64(ns)))
}

func startSubscriber(ctx context.Context, sub *Subscriber) {
	go func() {
		for {
			select {
			case <-ctx.Done():
				sub.Closed.Store(true)
				return
			case msg := <-sub.Ch:
				latency := time.Since(time.Unix(0, msg.CreatedAt))
				sub.Latency.Observe(latency)

				// Simulate minimal processing
				_ = msg.Payload
			}
		}
	}()
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	router := NewRouter(1 << 16)
	router.Start(ctx, runtime.NumCPU())

	latency := NewLatencyMonitor()

	// Create subscribers
	for i := 0; i < 8; i++ {
		sub := &Subscriber{
			ID:      fmt.Sprintf("sub-%d", i),
			Ch:      make(chan Message, 1<<12),
			Latency: latency,
		}
		router.Subscribe("orders", sub)
		startSubscriber(ctx, sub)
	}

	// Simulate high-rate publishers
	go func() {
		payload := []byte("hello world")
		for i := 0; i < 10_000_000; i++ {
			msg := Message{
				Topic:     "orders",
				Payload:   payload,
				CreatedAt: time.Now().UnixNano(),
			}
			router.Publish(msg)
		}
	}()

	// Periodic metrics
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		published, dropped, routed := router.Stats()
		count, sum, max, _ := latency.Snapshot()

		avg := time.Duration(0)
		if count > 0 {
			avg = time.Duration(sum / count)
		}

		log.Printf(
			"published=%d routed=%d dropped=%d latency_avg=%s latency_max=%s goroutines=%d",
			published, routed, dropped, avg, time.Duration(max), runtime.NumGoroutine(),
		)
	}
}
