## Initial implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"math"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt  int64 // unix nano
	TraceID   uint64
}

type Subscriber interface {
	Handle(msg Message)
}

type FuncSubscriber func(Message)

func (f FuncSubscriber) Handle(msg Message) { f(msg) }

type shard struct {
	incoming chan Message
	subs     map[string][]Subscriber
	mu       sync.RWMutex
}

type Router struct {
	shards []*shard
	mask   uint64

	received uint64
	dropped  uint64

	latency *LatencyMonitor
}

func NewRouter(numShards int, queueSize int, latency *LatencyMonitor) *Router {
	// Ensure power-of-two shard count for fast masking.
	n := 1
	for n < numShards {
		n <<= 1
	}

	r := &Router{
		shards:  make([]*shard, n),
		mask:    uint64(n - 1),
		latency: latency,
	}
	for i := 0; i < n; i++ {
		s := &shard{
			incoming: make(chan Message, queueSize),
			subs:     make(map[string][]Subscriber),
		}
		r.shards[i] = s
		go s.run(r.latency)
	}
	return r
}

func (r *Router) shardFor(topic string) *shard {
	h := fnv.New64a()
	_, _ = h.Write([]byte(topic))
	idx := h.Sum64() & r.mask
	return r.shards[idx]
}

func (r *Router) Publish(topic string, payload []byte, traceID uint64) bool {
	msg := Message{
		Topic:    topic,
		Payload:  payload,
		CreatedAt: time.Now().UnixNano(),
		TraceID:  traceID,
	}

	atomic.AddUint64(&r.received, 1)

	s := r.shardFor(topic)
	select {
	case s.incoming <- msg:
		return true
	default:
		atomic.AddUint64(&r.dropped, 1)
		return false
	}
}

func (r *Router) Subscribe(topic string, sub Subscriber) {
	s := r.shardFor(topic)
	s.mu.Lock()
	defer s.mu.Unlock()
	s.subs[topic] = append(s.subs[topic], sub)
}

func (s *shard) run(latency *LatencyMonitor) {
	for msg := range s.incoming {
		s.mu.RLock()
		subs := s.subs[msg.Topic]
		// Copy slice header only; subscribers are immutable after append.
		localSubs := append([]Subscriber(nil), subs...)
		s.mu.RUnlock()

		for _, sub := range localSubs {
			sub.Handle(msg)
		}

		if latency != nil {
			latency.Observe(time.Now().UnixNano() - msg.CreatedAt)
		}
	}
}

type LatencyMonitor struct {
	samples chan int64
	stop    chan struct{}

	// Aggregated stats
	count uint64
	sumNs uint64
	minNs uint64
	maxNs uint64

	mu      sync.Mutex
	hist    []int64
	closed  atomic.Bool
}

func NewLatencyMonitor(buffer int) *LatencyMonitor {
	lm := &LatencyMonitor{
		samples: make(chan int64, buffer),
		stop:    make(chan struct{}),
		minNs:   math.MaxUint64,
		hist:    make([]int64, 0, 100000),
	}
	go lm.run()
	return lm
}

func (lm *LatencyMonitor) Observe(ns int64) {
	if lm.closed.Load() {
		return
	}
	select {
	case lm.samples <- ns:
	default:
		// Drop latency samples under pressure to avoid affecting hot path.
	}
}

func (lm *LatencyMonitor) run() {
	for {
		select {
		case ns := <-lm.samples:
			atomic.AddUint64(&lm.count, 1)
			atomic.AddUint64(&lm.sumNs, uint64(ns))

			for {
				oldMin := atomic.LoadUint64(&lm.minNs)
				if uint64(ns) >= oldMin {
					break
				}
				if atomic.CompareAndSwapUint64(&lm.minNs, oldMin, uint64(ns)) {
					break
				}
			}

			for {
				oldMax := atomic.LoadUint64(&lm.maxNs)
				if uint64(ns) <= oldMax {
					break
				}
				if atomic.CompareAndSwapUint64(&lm.maxNs, oldMax, uint64(ns)) {
					break
				}
			}

			lm.mu.Lock()
			lm.hist = append(lm.hist, ns)
			lm.mu.Unlock()

		case <-lm.stop:
			return
		}
	}
}

func (lm *LatencyMonitor) Snapshot() (count uint64, avg time.Duration, min time.Duration, max time.Duration, p50 time.Duration, p95 time.Duration, p99 time.Duration) {
	count = atomic.LoadUint64(&lm.count)
	sum := atomic.LoadUint64(&lm.sumNs)
	minNs := atomic.LoadUint64(&lm.minNs)
	maxNs := atomic.LoadUint64(&lm.maxNs)

	if count > 0 {
		avg = time.Duration(sum / count)
		min = time.Duration(minNs)
		max = time.Duration(maxNs)

		lm.mu.Lock()
		samples := append([]int64(nil), lm.hist...)
		lm.mu.Unlock()

		sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })
		p50 = time.Duration(percentile(samples, 50))
		p95 = time.Duration(percentile(samples, 95))
		p99 = time.Duration(percentile(samples, 99))
	}
	return
}

func percentile(samples []int64, p float64) int64 {
	if len(samples) == 0 {
		return 0
	}
	idx := int(math.Ceil((p/100.0)*float64(len(samples)))) - 1
	if idx < 0 {
		idx = 0
	}
	if idx >= len(samples) {
		idx = len(samples) - 1
	}
	return samples[idx]
}

func (r *Router) Stats() (received uint64, dropped uint64) {
	return atomic.LoadUint64(&r.received), atomic.LoadUint64(&r.dropped)
}

func (r *Router) Close() {
	for _, s := range r.shards {
		close(s.incoming)
	}
	if r.latency != nil {
		r.latency.closed.Store(true)
		close(r.latency.stop)
	}
}

func main() {
	latency := NewLatencyMonitor(1 << 16)
	router := NewRouter(64, 1<<14, latency)

	router.Subscribe("orders", FuncSubscriber(func(msg Message) {
		// Simulate work
		_ = len(msg.Payload)
	}))

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Producer
	go func() {
		var trace uint64
		payload := make([]byte, 128)

		for {
			select {
			case <-ctx.Done():
				return
			default:
				trace++
				ok := router.Publish("orders", payload, trace)
				if !ok {
					// Backpressure/dropped message handling
				}
			}
		}
	}()

	// Periodic metrics
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	for i := 0; i < 5; i++ {
		<-ticker.C
		recv, drop := router.Stats()
		count, avg, min, max, p50, p95, p99 := latency.Snapshot()
		fmt.Printf(
			"received=%d dropped=%d latency_count=%d avg=%s min=%s max=%s p50=%s p95=%s p99=%s\n",
			recv, drop, count, avg, min, max, p50, p95, p99,
		)
	}

	cancel()
	router.Close()
}
