package main

import (
	"hash/fnv"
)

type Router struct {
	partitions int
}

func NewRouter(partitions int) *Router {
	if partitions <= 0 {
		partitions = 1
	}
	return &Router{partitions: partitions}
}

func (r *Router) Route(msg Message) int {
	// Prefer key-based routing for affinity.
	h := fnv.New32a()
	if msg.Key != "" {
		_, _ = h.Write([]byte(msg.Key))
	} else {
		_, _ = h.Write([]byte(msg.Topic))
	}
	return int(h.Sum32() % uint32(r.partitions))
}
