## `metrics.go`

```go
package main

import (
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Metrics struct {
	received   uint64
	processed  uint64
	dropped    uint64
	inflight   int64
	totalNanos uint64

	mu       sync.Mutex
	latencies []time.Duration
	capacity  int
}

func NewMetrics(capacity int) *Metrics {
	return &Metrics{
		latencies: make([]time.Duration, 0, capacity),
		capacity:  capacity,
	}
}

func (m *Metrics) IncReceived() {
	atomic.AddUint64(&m.received, 1)
	atomic.AddInt64(&m.inflight, 1)
}

func (m *Metrics) IncProcessed(latency time.Duration) {
	atomic.AddUint64(&m.processed, 1)
	atomic.AddInt64(&m.inflight, -1)
	atomic.AddUint64(&m.totalNanos, uint64(latency.Nanoseconds()))

	m.mu.Lock()
	if len(m.latencies) < m.capacity {
		m.latencies = append(m.latencies, latency)
	}
	m.mu.Unlock()
}

func (m *Metrics) IncDropped() {
	atomic.AddUint64(&m.dropped, 1)
}

func (m *Metrics) Snapshot() string {
	received := atomic.LoadUint64(&m.received)
	processed := atomic.LoadUint64(&m.processed)
	dropped := atomic.LoadUint64(&m.dropped)
	inflight := atomic.LoadInt64(&m.inflight)
	totalNanos := atomic.LoadUint64(&m.totalNanos)

	avg := time.Duration(0)
	if processed > 0 {
		avg = time.Duration(totalNanos / processed)
	}

	m.mu.Lock()
	lats := make([]time.Duration, len(m.latencies))
	copy(lats, m.latencies)
	m.mu.Unlock()

	sort.Slice(lats, func(i, j int) bool { return lats[i] < lats[j] })

	pct := func(p float64) time.Duration {
		if len(lats) == 0 {
			return 0
		}
		idx := int(float64(len(lats)-1) * p)
		return lats[idx]
	}

	return fmt.Sprintf(
		"received=%d processed=%d dropped=%d inflight=%d avg=%s p50=%s p95=%s p99=%s",
		received, processed, dropped, inflight, avg, pct(0.50), pct(0.95), pct(0.99),
	)
}
