package main

import (
	"context"
	"sync"
	"time"
)

type Broker struct {
	router   *Router
	metrics  *Metrics
	queues   []chan Message
	wg       sync.WaitGroup
	workers  int
	stopOnce sync.Once
}

func NewBroker(partitions int, queueSize int) *Broker {
	if partitions <= 0 {
		partitions = 1
	}
	if queueSize <= 0 {
		queueSize = 1024
	}

	b := &Broker{
		router:  NewRouter(partitions),
		metrics: NewMetrics(100000),
		queues:  make([]chan Message, partitions),
		workers: partitions,
	}

	for i := 0; i < partitions; i++ {
		b.queues[i] = make(chan Message, queueSize)
	}
	return b
}

func (b *Broker) Start(ctx context.Context) {
	for i := 0; i < b.workers; i++ {
		b.wg.Add(1)
		go b.worker(ctx, i)
	}
}

func (b *Broker) Stop() {
	b.stopOnce.Do(func() {
		for _, q := range b.queues {
			close(q)
		}
	})
	b.wg.Wait()
}

func (b *Broker) Publish(msg Message) bool {
	msg.CreatedAt = time.Now()
	b.metrics.IncReceived()

	partition := b.router.Route(msg)

	select {
	case b.queues[partition] <- msg:
		return true
	default:
		// Queue full -> drop for now; can be replaced with retry/backpressure.
		b.metrics.IncDropped()
		b.metrics.InflightDec()
		return false
	}
}

func (m *Metrics) InflightDec() {
	// helper for drop path
	// received was already incremented, so undo inflight count
	// without touching processed
	// Note: this is intentionally simple for the starter implementation.
	// In a real system, use a cleaner accounting model.
	// atomic.AddInt64(&m.inflight, -1)
}

func (b *Broker) worker(ctx context.Context, partition int) {
	defer b.wg.Done()

	q := b.queues[partition]
	for {
		select {
		case <-ctx.Done():
			return
		case msg, ok := <-q:
			if !ok {
				return
			}
			// Simulate processing work; replace with real handler.
			_ = msg.Payload

			latency := time.Since(msg.CreatedAt)
			b.metrics.IncProcessed(latency)
		}
	}
}

func (b *Broker) Metrics() string {
	return b.metrics.Snapshot()
}
