## 2) Latency monitor

This version records basic latency stats and can be extended to histograms.

```go
package messaging

import (
	"sync"
	"sync/atomic"
	"time"
)

type LatencyStats struct {
	Count       uint64
	TotalNanos  uint64
	MaxNanos    uint64
	MinNanos    uint64
	Dropped     uint64
}

type LatencyMonitor struct {
	count      atomic.Uint64
	totalNanos atomic.Uint64
	maxNanos   atomic.Uint64
	minNanos   atomic.Uint64
	dropped    atomic.Uint64

	mu sync.Mutex
}

func NewLatencyMonitor() *LatencyMonitor {
	lm := &LatencyMonitor{}
	lm.minNanos.Store(^uint64(0))
	return lm
}

func (lm *LatencyMonitor) Record(startNano int64) {
	lat := uint64(time.Now().UnixNano() - startNano)

	lm.count.Add(1)
	lm.totalNanos.Add(lat)

	for {
		old := lm.maxNanos.Load()
		if lat <= old || lm.maxNanos.CompareAndSwap(old, lat) {
			break
		}
	}

	for {
		old := lm.minNanos.Load()
		if lat >= old || lm.minNanos.CompareAndSwap(old, lat) {
			break
		}
	}
}

func (lm *LatencyMonitor) RecordDrop() {
	lm.dropped.Add(1)
}

func (lm *LatencyMonitor) Snapshot() LatencyStats {
	count := lm.count.Load()
	total := lm.totalNanos.Load()
	max := lm.maxNanos.Load()
	min := lm.minNanos.Load()
	if min == ^uint64(0) {
		min = 0
	}
	return LatencyStats{
		Count:      count,
		TotalNanos: total,
		MaxNanos:   max,
		MinNanos:   min,
		Dropped:    lm.dropped.Load(),
	}
}

func (s LatencyStats) AvgNanos() uint64 {
	if s.Count == 0 {
		return 0
	}
	return s.TotalNanos / s.Count
}
```

