## 3) Router

A simple topic-to-worker routing table.

```go
package messaging

import "sync"

type Handler func(*Message)

type Router struct {
	mu       sync.RWMutex
	handlers map[uint32]Handler
}

func NewRouter() *Router {
	return &Router{
		handlers: make(map[uint32]Handler),
	}
}

func (r *Router) Register(topic uint32, h Handler) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.handlers[topic] = h
}

func (r *Router) Route(msg *Message) bool {
	r.mu.RLock()
	h, ok := r.handlers[msg.Topic]
	r.mu.RUnlock()
	if !ok {
		return false
	}
	h(msg)
	return true
}
```

