## 4) Dispatcher with bounded queues

This is a simple high-throughput dispatcher using worker goroutines and bounded channels.

```go
package messaging

import (
	"errors"
	"runtime"
)

var ErrQueueFull = errors.New("message queue full")

type Dispatcher struct {
	router   *Router
	monitor  *LatencyMonitor
	queue    chan *Message
	stopCh   chan struct{}
}

func NewDispatcher(router *Router, monitor *LatencyMonitor, queueSize int) *Dispatcher {
	return &Dispatcher{
		router:  router,
		monitor: monitor,
		queue:   make(chan *Message, queueSize),
		stopCh:  make(chan struct{}),
	}
}

func (d *Dispatcher) Start(workers int) {
	for i := 0; i < workers; i++ {
		go func() {
			for {
				select {
				case msg := <-d.queue:
					if msg == nil {
						continue
					}
					d.router.Route(msg)
					d.monitor.Record(msg.CreatedAt)
				case <-d.stopCh:
					return
				}
			}
		}()
	}
}

func (d *Dispatcher) Submit(msg *Message) error {
	select {
	case d.queue <- msg:
		return nil
	default:
		d.monitor.RecordDrop()
		return ErrQueueFull
	}
}

func (d *Dispatcher) Stop() {
	close(d.stopCh)
}

func (d *Dispatcher) QueueDepth() int {
	return len(d.queue)
}

func (d *Dispatcher) GOMAXPROCS() int {
	return runtime.GOMAXPROCS(0)
}
```

