```rust
use crossbeam::channel::{bounded, Receiver, Sender, TryRecvError};
use hdrhistogram::Histogram;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy)]
struct Message {
    id: u64,
    created_ns: u64,
    topic: u32,
    payload: u64, // minimal payload
}

struct Stats {
    sent: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
}

impl Stats {
    fn new() -> Self {
        Self {
            sent: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
        }
    }
}

fn now_ns(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn route_topic(topic: u32, workers: usize) -> usize {
    (topic as usize) % workers
}

fn producer_thread(
    txs: Vec<Sender<Message>>,
    stats: Arc<Stats>,
    stop: Arc<AtomicBool>,
    start: Instant,
) {
    let mut id = 0u64;
    let workers = txs.len();
    let mut topic = 0u32;

    while !stop.load(Ordering::Relaxed) {
        let msg = Message {
            id,
            created_ns: now_ns(start),
            topic,
            payload: id ^ 0xDEADBEEF,
        };

        let shard = route_topic(topic, workers);
        match txs[shard].try_send(msg) {
            Ok(_) => {
                stats.sent.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                stats.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }

        id += 1;
        topic = topic.wrapping_add(1);
    }
}

fn worker_thread(
    rx: Receiver<Message>,
    stats: Arc<Stats>,
    stop: Arc<AtomicBool>,
    start: Instant,
) {
    let mut hist = Histogram::<u64>::new(3).unwrap();
    let mut batch = Vec::with_capacity(1024);

    while !stop.load(Ordering::Relaxed) {
        batch.clear();

        // Batch receive to reduce overhead
        for _ in 0..1024 {
            match rx.try_recv() {
                Ok(msg) => batch.push(msg),
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => return,
            }
        }

        if batch.is_empty() {
            thread::yield_now();
            continue;
        }

        for msg in &batch {
            // Simulated routing work
            let _processed = msg.id ^ msg.payload ^ (msg.topic as u64);

            let latency_ns = now_ns(start) - msg.created_ns;
            let _ = hist.record(latency_ns);

            stats.routed.fetch_add(1, Ordering::Relaxed);
        }
    }

    // Print worker-local latency summary on exit
    println!(
        "worker latency p50={}us p99={}us max={}us",
        hist.value_at_quantile(0.50) / 1000,
        hist.value_at_quantile(0.99) / 1000,
        hist.max() / 1000
    );
}

fn metrics_thread(stats: Arc<Stats>, stop: Arc<AtomicBool>) {
    let mut last_sent = 0u64;
    let mut last_routed = 0u64;
    let mut last_dropped = 0u64;
    let mut last_time = Instant::now();

    while !stop.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let now = Instant::now();
        let elapsed = now.duration_since(last_time).as_secs_f64();
        last_time = now;

        let sent = stats.sent.load(Ordering::Relaxed);
        let routed = stats.routed.load(Ordering::Relaxed);
        let dropped = stats.dropped.load(Ordering::Relaxed);

        let sent_rate = (sent - last_sent) as f64 / elapsed;
        let routed_rate = (routed - last_routed) as f64 / elapsed;
        let dropped_rate = (dropped - last_dropped) as f64 / elapsed;

        last_sent = sent;
        last_routed = routed;
        last_dropped = dropped;

        println!(
            "sent={sent} routed={routed} dropped={dropped} | \
             sent_rate={:.0}/s routed_rate={:.0}/s dropped_rate={:.0}/s",
            sent_rate, routed_rate, dropped_rate
        );
    }
}

fn main() {
    let workers = 4;
    let queue_size = 65_536;

    let stats = Arc::new(Stats::new());
    let stop = Arc::new(AtomicBool::new(false));
    let start = Instant::now();

    let mut txs = Vec::new();
    let mut rxs = Vec::new();

    for _ in 0..workers {
        let (tx, rx) = bounded::<Message>(queue_size);
        txs.push(tx);
        rxs.push(rx);
    }

    let mut handles = Vec::new();

    // Start workers
    for rx in rxs {
        let stats = stats.clone();
        let stop = stop.clone();
        let start = start.clone();
        handles.push(thread::spawn(move || worker_thread(rx, stats, stop, start)));
    }

    // Start metrics
    {
        let stats = stats.clone();
        let stop = stop.clone();
        handles.push(thread::spawn(move || metrics_thread(stats, stop)));
    }

    // Start producer
    {
        let stats = stats.clone();
        let stop = stop.clone();
        let start = start.clone();
        handles.push(thread::spawn(move || producer_thread(txs, stats, stop, start)));
    }

    // Run for 10 seconds
    thread::sleep(Duration::from_secs(10));
    stop.store(true, Ordering::Relaxed);

    for h in handles {
        let _ = h.join();
    }
}
```

