## `main.go`
```go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"log"
	"net"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID      string `json:"id"`
	Topic   string `json:"topic"`
	TsNS    int64  `json:"ts_ns"`
	Payload string `json:"payload"`
}

type Metrics struct {
	Received   uint64
	Routed     uint64
	Processed  uint64
	Dropped    uint64
	LatencySum uint64
	LatencyCnt uint64
	MaxLatency uint64
}

func (m *Metrics) recordLatency(ns uint64) {
	atomic.AddUint64(&m.LatencySum, ns)
	atomic.AddUint64(&m.LatencyCnt, 1)

	for {
		old := atomic.LoadUint64(&m.MaxLatency)
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapUint64(&m.MaxLatency, old, ns) {
			break
		}
	}
}

type Router struct {
	subscribers map[string][]chan Message
	mu          sync.RWMutex
	metrics     *Metrics
}

func NewRouter(metrics *Metrics) *Router {
	return &Router{
		subscribers: make(map[string][]chan Message),
		metrics:     metrics,
	}
}

func (r *Router) Subscribe(topic string, ch chan Message) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.subscribers[topic] = append(r.subscribers[topic], ch)
}

func (r *Router) Route(msg Message) {
	r.mu.RLock()
	subs := r.subscribers[msg.Topic]
	r.mu.RUnlock()

	if len(subs) == 0 {
		atomic.AddUint64(&r.metrics.Dropped, 1)
		return
	}

	for _, ch := range subs {
		select {
		case ch <- msg:
			atomic.AddUint64(&r.metrics.Routed, 1)
		default:
			atomic.AddUint64(&r.metrics.Dropped, 1)
		}
	}
}

func worker(id int, ch <-chan Message, metrics *Metrics) {
	for msg := range ch {
		// Simulate processing
		now := time.Now().UnixNano()
		latency := uint64(0)
		if msg.TsNS > 0 && now > msg.TsNS {
			latency = uint64(now - msg.TsNS)
		}
		metrics.recordLatency(latency)
		atomic.AddUint64(&metrics.Processed, 1)
	}
}

func handleConn(conn net.Conn, router *Router, metrics *Metrics) {
	defer conn.Close()

	scanner := bufio.NewScanner(conn)
	// Increase scanner buffer for larger messages
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	for scanner.Scan() {
		var msg Message
		if err := json.Unmarshal(scanner.Bytes(), &msg); err != nil {
			atomic.AddUint64(&metrics.Dropped, 1)
			continue
		}
		atomic.AddUint64(&metrics.Received, 1)
		router.Route(msg)
	}

	if err := scanner.Err(); err != nil {
		log.Println("conn error:", err)
	}
}

func tcpServer(addr string, router *Router, metrics *Metrics) {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatal(err)
	}
	log.Println("TCP listening on", addr)

	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go handleConn(conn, router, metrics)
	}
}

func metricsServer(addr string, metrics *Metrics) {
	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		received := atomic.LoadUint64(&metrics.Received)
		routed := atomic.LoadUint64(&metrics.Routed)
		processed := atomic.LoadUint64(&metrics.Processed)
		dropped := atomic.LoadUint64(&metrics.Dropped)
		sum := atomic.LoadUint64(&metrics.LatencySum)
		cnt := atomic.LoadUint64(&metrics.LatencyCnt)
		max := atomic.LoadUint64(&metrics.MaxLatency)

		avg := uint64(0)
		if cnt > 0 {
			avg = sum / cnt
		}

		fmt.Fprintf(w,
			"received %d\nrouted %d\nprocessed %d\ndropped %d\nlatency_avg_ns %d\nlatency_max_ns %d\n",
			received, routed, processed, dropped, avg, max)
	})

	log.Println("Metrics listening on", addr)
	log.Fatal(http.ListenAndServe(addr, nil))
}

func main() {
	metrics := &Metrics{}
	router := NewRouter(metrics)

	// Create subscribers/workers
	for i := 0; i < 4; i++ {
		ch := make(chan Message, 10000)
		router.Subscribe("orders", ch)
		go worker(i, ch, metrics)
	}

	for i := 0; i < 4; i++ {
		ch := make(chan Message, 10000)
		router.Subscribe("trades", ch)
		go worker(i+10, ch, metrics)
	}

	go tcpServer(":9000", router, metrics)
	go metricsServer(":8080", metrics)

	select {}
}
```

