## 3) Minimal implementation in Go

Go is a good fit for a minimal high-throughput prototype because it has:
- fast networking
- goroutines/channels
- decent performance with low code complexity

### `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"math/rand"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

const (
	HeaderSize   = 8 + 8 + 4
	NumWorkers   = 4
	QueueSize    = 1 << 16
	BatchSize    = 256
	ListenAddr   = ":9000"
	ReportPeriod = 1 * time.Second
)

type Message struct {
	ID       uint64
	TsNs     uint64
	RouteKey uint32
	Payload  []byte
}

func encodeMessage(msg Message) []byte {
	b := make([]byte, HeaderSize+len(msg.Payload))
	binary.BigEndian.PutUint64(b[0:8], msg.ID)
	binary.BigEndian.PutUint64(b[8:16], msg.TsNs)
	binary.BigEndian.PutUint32(b[16:20], msg.RouteKey)
	copy(b[20:], msg.Payload)
	return b
}

func decodeMessage(b []byte) Message {
	return Message{
		ID:       binary.BigEndian.Uint64(b[0:8]),
		TsNs:     binary.BigEndian.Uint64(b[8:16]),
		RouteKey: binary.BigEndian.Uint32(b[16:20]),
		Payload:  b[20:],
	}
}

type LatencyStats struct {
	count uint64
	sumNs uint64
	minNs uint64
	maxNs uint64
}

func (s *LatencyStats) Observe(latencyNs uint64) {
	atomic.AddUint64(&s.count, 1)
	atomic.AddUint64(&s.sumNs, latencyNs)

	for {
		oldMin := atomic.LoadUint64(&s.minNs)
		if oldMin != 0 && oldMin <= latencyNs {
			break
		}
		if atomic.CompareAndSwapUint64(&s.minNs, oldMin, latencyNs) {
			break
		}
	}

	for {
		oldMax := atomic.LoadUint64(&s.maxNs)
		if oldMax >= latencyNs {
			break
		}
		if atomic.CompareAndSwapUint64(&s.maxNs, oldMax, latencyNs) {
			break
		}
	}
}

func (s *LatencyStats) Snapshot() (count, avg, min, max uint64) {
	count = atomic.LoadUint64(&s.count)
	sum := atomic.LoadUint64(&s.sumNs)
	min = atomic.LoadUint64(&s.minNs)
	max = atomic.LoadUint64(&s.maxNs)
	if count > 0 {
		avg = sum / count
	}
	return
}

type Router struct {
	workers []chan Message
	stats   *LatencyStats
}

func NewRouter(numWorkers, queueSize int, stats *LatencyStats) *Router {
	workers := make([]chan Message, numWorkers)
	for i := range workers {
		workers[i] = make(chan Message, queueSize)
	}
	return &Router{workers: workers, stats: stats}
}

func (r *Router) Route(msg Message) {
	idx := int(msg.RouteKey % uint32(len(r.workers)))
	r.workers[idx] <- msg
}

func workerLoop(id int, ch <-chan Message, stats *LatencyStats, wg *sync.WaitGroup) {
	defer wg.Done()
	for msg := range ch {
		now := uint64(time.Now().UnixNano())
		latency := now - msg.TsNs
		stats.Observe(latency)

		// Simulate processing
		_ = msg.Payload
	}
}

func serverLoop(router *Router) {
	ln, err := net.Listen("tcp", ListenAddr)
	if err != nil {
		log.Fatalf("listen error: %v", err)
	}
	defer ln.Close()

	log.Printf("listening on %s", ListenAddr)

	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go handleConn(conn, router)
	}
}

func handleConn(conn net.Conn, router *Router) {
	defer conn.Close()

	buf := make([]byte, 4096)
	var pending []byte

	for {
		n, err := conn.Read(buf)
		if err != nil {
			return
		}
		pending = append(pending, buf[:n]...)

		for len(pending) >= HeaderSize {
			// In this minimal version, payload length is fixed to 0 for simplicity.
			// You can extend the header with payload length if needed.
			msgBytes := pending[:HeaderSize]
			msg := decodeMessage(msgBytes)
			router.Route(msg)
			pending = pending[HeaderSize:]
		}
	}
}

func clientLoadGenerator(n int, ratePerSec int) {
	conn, err := net.Dial("tcp", ListenAddr)
	if err != nil {
		log.Fatalf("client dial error: %v", err)
	}
	defer conn.Close()

	ticker := time.NewTicker(time.Second / time.Duration(ratePerSec))
	defer ticker.Stop()

	var id uint64
	payload := []byte("x")

	for i := 0; i < n; i++ {
		<-ticker.C
		msg := Message{
			ID:       atomic.AddUint64(&id, 1),
			TsNs:     uint64(time.Now().UnixNano()),
			RouteKey: uint32(rand.Intn(1024)),
			Payload:  payload,
		}
		_, err := conn.Write(encodeMessage(msg))
		if err != nil {
			return
		}
	}
}

func main() {
	stats := &LatencyStats{}
	router := NewRouter(NumWorkers, QueueSize, stats)

	var wg sync.WaitGroup
	for i := 0; i < NumWorkers; i++ {
		wg.Add(1)
		go workerLoop(i, router.workers[i], stats, &wg)
	}

	go serverLoop(router)

	go func() {
		for {
			time.Sleep(ReportPeriod)
			count, avg, min, max := stats.Snapshot()
			fmt.Printf("messages=%d avg=%dns min=%dns max=%dns\n", count, avg, min, max)
		}
	}()

	// Demo load generator
	time.Sleep(1 * time.Second)
	go clientLoadGenerator(100000, 50000)

	wg.Wait()
}
```

