    dropped: AtomicU64,
}

fn parse_ipv4_packet(data: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u8, usize)> {
    if data.len() < 34 {
        return None;
    }

    // Ethernet header = 14 bytes
    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &data[14..];
    let ihl = (ip[0] & 0x0f) as usize * 4;
    if ip.len() < ihl || ihl < 20 {
        return None;
    }

    let protocol = ip[9];
    let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
    let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

    Some((src, dst, protocol, ihl))
}

fn should_accept(src: Ipv4Addr, dst: Ipv4Addr, protocol: u8) -> bool {
    // Example policy:
    // - allow only traffic from 10.0.0.0/8
    // - only TCP/UDP
    let src_octets = src.octets();
    let in_private_10 = src_octets[0] == 10;
    let is_tcp_udp = protocol == 6 || protocol == 17;

    in_private_10 && is_tcp_udp && dst != Ipv4Addr::new(127, 0, 0, 1)
}

fn process_packet(pkt: Packet<'_>, counters: &Counters) {
    if let Some((src, dst, proto, _ihl)) = parse_ipv4_packet(pkt.data) {
        if should_accept(src, dst, proto) {
            counters.accepted.fetch_add(1, Ordering::Relaxed);
            // Safe action: record metadata, emit metrics, or hand off to a local analyzer.
            println!("ACCEPT src={} dst={} proto={}", src, dst, proto);
        } else {
            counters.dropped.fetch_add(1, Ordering::Relaxed);
        }
    } else {
        counters.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

fn main() {
    let counters = Arc::new(Counters::default());

    // In a real implementation, this loop would read packets from a
