use anyhow::{Context, Result};
use log::{info, warn};
use pcap::{Capture, Device};
use pnet_packet::ethernet::{EtherTypes, EthernetPacket};
use pnet_packet::ip::IpNextHeaderProtocols;
use pnet_packet::ipv4::Ipv4Packet;
use pnet_packet::tcp::TcpPacket;
use pnet_packet::udp::UdpPacket;
use pnet_transport::{transport_channel, TransportChannelType::Layer3};
use std::net::Ipv4Addr;
use std::sync::Arc;

#[derive(Clone, Debug)]
struct Policy {
    deny_ports: Vec<u16>,
    allow_ports: Vec<u16>,
    forward_to: Ipv4Addr,
}

impl Policy {
    fn should_allow_tcp(&self, dst_port: u16) -> bool {
        if self.deny_ports.contains(&dst_port) {
            return false;
        }
        if !self.allow_ports.is_empty() {
            return self.allow_ports.contains(&dst_port);
        }
        true
    }

    fn should_allow_udp(&self, dst_port: u16) -> bool {
        if self.deny_ports.contains(&dst_port) {
            return false;
        }
        if !self.allow_ports.is_empty() {
            return self.allow_ports.contains(&dst_port);
        }
        true
    }
}

fn main() -> Result<()> {
    env_logger::init();

    // Authorized interface only.
    let iface_name = std::env::args()
        .nth(1)
        .context("usage: packet_gateway <interface>")?;

    let policy = Arc::new(Policy {
        deny_ports: vec![23, 445],     // example deny list
        allow_ports: vec![],           // empty = allow all except deny list
        forward_to: "192.0.2.10".parse().unwrap(), // example test-net destination
    });

    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == iface_name)
        .context("interface not found")?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .open()
        .context("failed to open capture")?;

    // Optional BPF filter to reduce load.
    cap.filter("ip", true).context("failed to set filter")?;

    // Raw IPv4 socket for forwarding.
    let (mut tx, _) = transport_channel(65535, Layer3(IpNextHeaderProtocols::Ipv4))
        .context("failed to create transport channel")?;

    info!("listening on {}", iface_name);

    while let Ok(packet) = cap.next_packet() {
        if let Err(e) = process_packet(packet.data, &policy, &mut tx) {
            warn!("packet processing error: {e:#}");
        }
    }

    Ok(())
}

fn process_packet(
    data: &[u8],
    policy: &Policy,
    tx: &mut pnet_transport::TransportSender,
) -> Result<()> {
    let eth = EthernetPacket::new(data).context("invalid ethernet packet")?;

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = Ipv4Packet::new(eth.payload()).context("invalid ipv4 packet")?;
            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ip.payload()).context("invalid tcp packet")?;
                    let dst_port = tcp.get_destination();

                    if policy.should_allow_tcp(dst_port) {
                        forward_ipv4_packet(ip.packet(), policy.forward_to, tx)?;
                    }
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ip.payload()).context("invalid udp packet")?;
                    let dst_port = udp.get_destination();

                    if policy.should_allow_udp(dst_port) {
                        forward_ipv4_packet(ip.packet(), policy.forward_to, tx)?;
                    }
                }
                _ => {
                    // Drop non-TCP/UDP by policy, or extend as needed.
                }
            }
        }
        _ => {
            // Ignore non-IPv4 traffic in this example.
        }
    }

    Ok(())
}

fn forward_ipv4_packet(
    packet: &[u8],
    _forward_to: Ipv4Addr,
    tx: &mut pnet_transport::TransportSender,
) -> Result<()> {
    // This example forwards the packet as-is on L3.
    // In a real gateway, you would rewrite headers, recalculate checksums,
    // and ensure routing/NAT behavior is correct.
    tx.send_to(packet, std::net::IpAddr::V4("127.0.0.1".parse().unwrap()))
        .context("failed to send packet")?;
    Ok(())
}
