    src_port: Option<u16>,
    dst_port: Option<u16>,
    proto: u8,
}

fn rule_matches(rule: &FilterRule, pkt: &ParsedPacket) -> bool {
    if let Some(ip) = rule.src_ip {
        if ip != pkt.src_ip {
            return false;
        }
    }
    if let Some(ip) = rule.dst_ip {
        if ip != pkt.dst_ip {
            return false;
        }
    }
    if let Some(p) = rule.src_port {
        if Some(p) != pkt.src_port {
            return false;
        }
    }
    if let Some(p) = rule.dst_port {
        if Some(p) != pkt.dst_port {
            return false;
        }
    }
    if let Some(proto) = rule.proto {
        if proto != pkt.proto {
            return false;
        }
    }
    true
}

fn parse_ipv4_l4(pkt: &Packet) -> Option<ParsedPacket> {
    let data = &pkt.data;
    if data.len() < 34 {
        return None;
    }

    // Ethernet header: 14 bytes
    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None; // not IPv4
    }

    // IPv4 header
    let ip_start = 14;
    let version_ihl = data[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || data.len() < ip_start + ihl {
        return None;
    }

    let proto = data[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        data[ip_start + 12],
        data[ip_start + 13],
        data[ip_start + 14],
        data[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        data[ip_start + 16],
        data[ip_start + 17],
        data[ip_start + 18],
        data[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    let (src_port, dst_port) = match proto {
        6 | 17 => {
            if data.len() < l4_start + 4 {
                return None;
            }
            let sp = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
            let dp = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);
            (Some(sp), Some(dp))
        }
        _ => (None, None),
    };

    Some(ParsedPacket {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

