```rust
use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Copy, Debug)]
enum Action {
    Drop,
    Forward(u16), // output port
    Mirror(u16),   // mirror to port
    Pass,
}

#[derive(Debug)]
struct Packet<'a> {
    data: &'a [u8],
}

impl<'a> Packet<'a> {
    fn len(&self) -> usize {
        self.data.len()
    }

    fn ethertype(&self) -> Option<u16> {
        if self.data.len() < 14 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[12], self.data[13]]))
    }

    fn ipv4_header_offset(&self) -> Option<usize> {
        match self.ethertype()? {
            0x0800 => Some(14),
            _ => None,
        }
    }

    fn parse_flow_key(&self) -> Option<FlowKey> {
        let ip_off = self.ipv4_header_offset()?;
        if self.data.len() < ip_off + 20 {
            return None;
        }

        let ver_ihl = self.data[ip_off];
        let version = ver_ihl >> 4;
        let ihl = (ver_ihl & 0x0f) as usize * 4;
        if version != 4 || self.data.len() < ip_off + ihl {
            return None;
        }

        let proto = self.data[ip_off + 9];
        let src_ip = Ipv4Addr::new(
            self.data[ip_off + 12],
            self.data[ip_off + 13],
            self.data[ip_off + 14],
            self.data[ip_off + 15],
        );
        let dst_ip = Ipv4Addr::new(
            self.data[ip_off + 16],
            self.data[ip_off + 17],
            self.data[ip_off + 18],
            self.data[ip_off + 19],
        );

        // TCP/UDP ports
        if proto == 6 || proto == 17 {
            if self.data.len() < ip_off + ihl + 4 {
                return None;
            }
            let l4 = ip_off + ihl;
            let src_port = u16::from_be_bytes([self.data[l4], self.data[l4 + 1]]);
            let dst_port = u16::from_be_bytes([self.data[l4 + 2], self.data[l4 + 3]]);
            Some(FlowKey {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
            })
        } else {
            Some(FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto,
            })
        }
    }
}

struct RuleEngine {
    // Example: exact-match flow table
    flow_rules: HashMap<FlowKey, Action>,
    default_action: Action,
}

impl RuleEngine {
    fn new() -> Self {
        Self {
            flow_rules: HashMap::new(),
            default_action: Action::Drop,
        }
    }

    fn set_default(&mut self, action: Action) {
        self.default_action = action;
    }

    fn add_flow_rule(&mut self, key: FlowKey, action: Action) {
        self.flow_rules.insert(key, action);
    }

    fn classify(&self, pkt: &Packet) -> Action {
        if let Some(key) = pkt.parse_flow_key() {
            if let Some(action) = self.flow_rules.get(&key) {
                return *action;
            }
        }
        self.default_action
    }
}

trait NicRxTx: Send + Sync + 'static {
    fn recv_batch<'a>(&self, out: &mut Vec<Packet<'a>>) -> usize;
    fn send_batch<'a>(&self, port: u16, pkts: &[Packet<'a>]) -> usize;
}

/// Mock NIC backend for demonstration.
/// Replace with AF_XDP / DPDK / raw socket implementation.
struct MockNic;

impl NicRxTx for MockNic {
    fn recv_batch<'a>(&self, _out: &mut Vec<Packet<'a>>) -> usize {
        0
    }

    fn send_batch<'a>(&self, _port: u16, _pkts: &[Packet<'a>]) -> usize {
        0
    }
}

struct Forwarder<N: NicRxTx> {
    nic: Arc<N>,
    rules: Arc<Mutex<RuleEngine>>,
    running: Arc<AtomicBool>,
    batch_size: usize,
}

impl<N: NicRxTx> Forwarder<N> {
    fn new(nic: Arc<N>, rules: Arc<Mutex<RuleEngine>>) -> Self {
        Self {
            nic,
            rules,
            running: Arc::new(AtomicBool::new(true)),
            batch_size: 64,
        }
    }

    fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }

    fn run(&self) {
        let mut scratch: Vec<Vec<u8>> = Vec::with_capacity(self.batch_size);
        let mut packets: Vec<Packet> = Vec::with_capacity(self.batch_size);
        let mut forward_queues: HashMap<u16, Vec<Vec<u8>>> = HashMap::new();

        while self.running.load(Ordering::Relaxed) {
            packets.clear();
            scratch.clear();
            forward_queues.clear();

            // In a real backend, recv_batch would fill packet buffers from NIC memory.
            let rx_count = self.nic.recv_batch(&mut packets);
            if rx_count == 0 {
                thread::yield_now();
                continue;
            }

            let rules = self.rules.lock().unwrap();

            for pkt in &packets {
                match rules.classify(pkt) {
                    Action::Drop => {
                        // drop
                    }
                    Action::Pass => {
                        forward_queues.entry(0).or_default().push(pkt.data.to_vec());
                    }
                    Action::Forward(port) => {
                        forward_queues.entry(port).or_default().push(pkt.data.to_vec());
                    }
                    Action::Mirror(port) => {
                        forward_queues.entry(port).or_default().push(pkt.data.to_vec());
                        forward_queues.entry(0).or_default().push(pkt.data.to_vec());
                    }
                }
            }

            drop(rules);

            for (port, pkts) in forward_queues.iter() {
                let tx_packets: Vec<Packet> = pkts.iter().map(|b| Packet { data: b }).collect();
                let _sent = self.nic.send_batch(*port, &tx_packets);
            }
        }
    }
}

fn main() {
    let nic = Arc::new(MockNic);
    let rules = Arc::new(Mutex::new(RuleEngine::new()));

    {
        let mut r = rules.lock().unwrap();
        r.set_default(Action::Drop);

