use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;

static RX_PKTS: AtomicU64 = AtomicU64::new(0);
static TX_PKTS: AtomicU64 = AtomicU64::new(0);
static DROPPED_PKTS: AtomicU64 = AtomicU64::new(0);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Action {
    Allow,
    Drop,
    Forward(u16), // e.g. output port
}

#[derive(Debug, Clone, Copy)]
struct EthernetHeader {
    ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
enum IpAddrKind {
    V4(Ipv4Addr),
    V6(Ipv6Addr),
}

#[derive(Debug, Clone, Copy)]
struct PacketMeta {
    src: Option<IpAddrKind>,
    dst: Option<IpAddrKind>,
    proto: Option<u8>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

impl PacketMeta {
    fn empty() -> Self {
        Self {
            src: None,
            dst: None,
            proto: None,
            src_port: None,
            dst_port: None,
        }
    }
}

fn parse_ethernet(pkt: &[u8]) -> Option<(EthernetHeader, &[u8])> {
    if pkt.len() < 14 {
        return None;
    }
    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    Some((EthernetHeader { ethertype }, &pkt[14..]))
}

fn parse_ipv4(pkt: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u8, &[u8])> {
    if pkt.len() < 20 {
        return None;
    }
    let version = pkt[0] >> 4;
    let ihl = (pkt[0] & 0x0f) as usize * 4;
    if version != 4 || pkt.len() < ihl || ihl < 20 {
        return None;
    }

    let proto = pkt[9];
    let src = Ipv4Addr::new(pkt[12], pkt[13], pkt[14], pkt[15]);
    let dst = Ipv4Addr::new(pkt[16], pkt[17], pkt[18], pkt[19]);
    Some((src, dst, proto, &pkt[ihl..]))
}

fn parse_ipv6(pkt: &[u8]) -> Option<(Ipv6Addr, Ipv6Addr, u8, &[u8])> {
    if pkt.len() < 40 {
        return None;
    }
    let version = pkt[0] >> 4;
    if version != 6 {
        return None;
    }

    let next_header = pkt[6];
    let src = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[8..24]).ok()?);
    let dst = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[24..40]).ok()?);
    Some((src, dst, next_header, &pkt[40..]))
}

fn parse_l4_ports(proto: u8, pkt: &[u8]) -> (Option<u16>, Option<u16>) {
    // TCP=6, UDP=17
    if (proto == 6 || proto == 17) && pkt.len() >= 4 {
        let src = u16::from_be_bytes([pkt[0], pkt[1]]);
        let dst = u16::from_be_bytes([pkt[2], pkt[3]]);
        (Some(src), Some(dst))
    } else {
        (None, None)
    }
}

/// Example policy:
/// - drop RFC1918-to-public forwarding if not explicitly allowed
/// - allow DNS and HTTPS
/// - forward everything else to port 1
fn classify(meta: &PacketMeta) -> Action {
    if let Some(dst_port) = meta.dst_port {
        if dst_port == 53 || dst_port == 443 {
            return Action::Allow;
        }
    }

    match (meta.src, meta.dst) {
        (Some(IpAddrKind::V4(src)), Some(IpAddrKind::V4(dst))) => {
            let src_private = src.is_private();
            let dst_private = dst.is_private();

            if src_private && !dst_private {
                // Example: forward outbound traffic to port 1
                Action::Forward(1)
            } else {
                Action::Allow
            }
        }
        _ => Action::Forward(1),
    }
}

fn inspect_packet(pkt: &[u8]) -> Action {
    RX_PKTS.fetch_add(1, Ordering::Relaxed);

    let (eth, payload) = match parse_ethernet(pkt) {
        Some(v) => v,
        None => {
            DROPPED_PKTS.fetch_add(1, Ordering::Relaxed);
            return Action::Drop;
        }
    };

    let mut meta = PacketMeta::empty();

    match eth.ethertype {
        0x0800 => {
            if let Some((src, dst, proto, l4)) = parse_ipv4(payload) {
                meta.src = Some(IpAddrKind::V4(src));
                meta.dst = Some(IpAddrKind::V4(dst));
                meta.proto = Some(proto);
                let (sp, dp) = parse_l4_ports(proto, l4);
                meta.src_port = sp;
                meta.dst_port = dp;
            } else {
                DROPPED_PKTS.fetch_add(1, Ordering::Relaxed);
                return Action::Drop;
            }
        }
        0x86DD => {
            if let Some((src, dst, proto, l4)) = parse_ipv6(payload) {
                meta.src = Some(IpAddrKind::V6(src));
                meta.dst = Some(IpAddrKind::V6(dst));
                meta.proto = Some(proto);
                let (sp, dp) = parse_l4_ports(proto, l4);
                meta.src_port = sp;
                meta.dst_port = dp;
            } else {
                DROPPED_PKTS.fetch_add(1, Ordering::Relaxed);
                return Action::Drop;
            }
        }
        _ => {
            // Non-IP traffic: allow or drop based on policy
            return Action::Allow;
        }
    }

    classify(&meta)
}

/// Placeholder for a fast TX path.
/// In a real implementation this would enqueue to a NIC TX ring or XDP redirect.
fn forward_packet(_pkt: &[u8], out_port: u16) {
    let _ = out_port;
    TX_PKTS.fetch_add(1, Ordering::Relaxed);
}

fn process_packet(pkt: &[u8]) {
    match inspect_packet(pkt) {
        Action::Allow => {
            // deliver to local consumer or pass through
            TX_PKTS.fetch_add(1, Ordering::Relaxed);
        }
        Action::Drop => {
            // already counted
        }
        Action::Forward(port) => {
            forward_packet(pkt, port);
        }
    }
}

fn main() {
    let start = Instant::now();

    // Demo loop: replace with a real RX loop from DPDK/XDP/NIC driver.
    let fake_packet = vec![
        0, 1, 2, 3, 4, 5,  // dst MAC
        6, 7, 8, 9, 10, 11, // src MAC
        0x08, 0x00,         // ethertype IPv4
        0x45, 0x00, 0x00, 0x28, 0x12, 0x34, 0x40, 0x00,
        64, 6, 0, 0,        // TTL, TCP
        192, 168, 1, 10,    // src
        8, 8, 8, 8,         // dst
        0x04, 0xD2,         // src port 1234
        0x01, 0xBB,         // dst port 443
    ];

    for _ in 0..1_000 {
        process_packet(&fake_packet);
    }

    let elapsed = start.elapsed();
    println!(
        "rx={} tx={} dropped={} elapsed={:?}",
        RX_PKTS.load(Ordering::Relaxed),
        TX_PKTS.load(Ordering::Relaxed),
        DROPPED_PKTS.load(Ordering::Relaxed),
        elapsed
    );
}
