#[derive(Default)]
struct FlowStats {
    packets: AtomicU64,
    bytes: AtomicU64,
    dropped: AtomicU64,
    forwarded: AtomicU64,
}

struct Rule {
    // Very simple rule model for demonstration.
    // In production, compile rules into a fast lookup structure.
    key: Option<FlowKey>,
    action: Action,
