struct PacketProcessor {
    rules: Vec<Rule>,
    stats: Mutex<HashMap<FlowKey, Arc<FlowStats>>>,
}

impl PacketProcessor {
    fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules,
            stats: Mutex::new(HashMap::new()),
        }
    }

    fn process_batch(&self, packets: &mut [Packet]) {
        for pkt in packets.iter_mut() {
            if let Some(flow) = parse_flow_key(&pkt.data) {
                let action = self.match_rule(flow);

                let flow_stats = self.get_or_create_stats(flow);
                flow_stats.packets.fetch_add(1, Ordering::Relaxed);
                flow_stats.bytes.fetch_add(pkt.data.len() as u64, Ordering::Relaxed);

                match action {
                    Action::Allow => {
                        // In a real service, enqueue to egress port or next stage.
                        flow_stats.forwarded.fetch_add(1, Ordering::Relaxed);
                        forward_packet(pkt, None);
                    }
                    Action::Drop => {
                        flow_stats.dropped.fetch_add(1, Ordering::Relaxed);
                        drop_packet(pkt);
                    }
                    Action::Forward { port } => {
                        flow_stats.forwarded.fetch_add(1, Ordering::Relaxed);
                        forward_packet(pkt, Some(port));
                    }
                }
            } else {
                // Malformed or unsupported packet
                drop_packet(pkt);
            }
        }
    }

    fn match_rule(&self, flow: FlowKey) -> Action {
        // First-match semantics. For low latency, replace with compiled trie/hash tables.
        for rule in &self.rules {
            if rule.key.map_or(true, |k| k == flow) {
                return rule.action;
            }
        }
        Action::Drop
    }

    fn get_or_create_stats(&self, flow: FlowKey) -> Arc<FlowStats> {
        let mut map = self.stats.lock().unwrap();
        map.entry(flow)
            .or_insert_with(|| Arc::new(FlowStats::default()))
            .clone()
    }
}

fn parse_flow_key(data: &[u8]) -> Option<FlowKey> {
    // Minimal IPv4/TCP/UDP parser placeholder.
    // Assumes Ethernet + IPv4 + L4, no VLAN, no options.
    if data.len() < 34 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_start = 14;
    let version_ihl = data[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || data.len() < ip_start + ihl + 4 {
        return None;
    }

    let proto = data[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        data[ip_start + 12],
        data[ip_start + 13],
        data[ip_start + 14],
        data[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        data[ip_start + 16],
        data[ip_start + 17],
        data[ip_start + 18],
        data[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    if data.len() < l4_start + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
    let dst_port = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

