use pcap::{Capture, Device, Linktype, Packet};
use std::error::Error;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Clone, Copy, Debug)]
struct MacAddr([u8; 6]);

#[derive(Debug)]
struct EthernetFrame<'a> {
    dst: MacAddr,
    src: MacAddr,
    ethertype: u16,
    payload: &'a [u8],
}

#[derive(Debug)]
struct Ipv4Header<'a> {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    protocol: u8,
    header_len: usize,
    payload: &'a [u8],
}

fn parse_ethernet(packet: &[u8]) -> Option<EthernetFrame<'_>> {
    if packet.len() < 14 {
        return None;
    }
    let dst = MacAddr(packet[0..6].try_into().ok()?);
    let src = MacAddr(packet[6..12].try_into().ok()?);
    let ethertype = u16::from_be_bytes(packet[12..14].try_into().ok()?);
    Some(EthernetFrame {
        dst,
        src,
        ethertype,
        payload: &packet[14..],
    })
}

fn parse_ipv4(payload: &[u8]) -> Option<Ipv4Header<'_>> {
    if payload.len() < 20 {
        return None;
    }
    let version_ihl = payload[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || ihl < 20 || payload.len() < ihl {
        return None;
    }

    let protocol = payload[9];
    let src = Ipv4Addr::new(payload[12], payload[13], payload[14], payload[15]);
    let dst = Ipv4Addr::new(payload[16], payload[17], payload[18], payload[19]);

    Some(Ipv4Header {
        src,
        dst,
        protocol,
        header_len: ihl,
        payload: &payload[ihl..],
    })
}

/// Example policy:
/// - Allow only IPv4 TCP packets to a specific destination subnet
/// - Drop everything else
fn allow_packet(frame: &EthernetFrame<'_>) -> bool {
    const ETHERTYPE_IPV4: u16 = 0x0800;
    if frame.ethertype != ETHERTYPE_IPV4 {
        return false;
    }

    let ip = match parse_ipv4(frame.payload) {
        Some(ip) => ip,
        None => return false,
    };

    // Example: allow only TCP
    const IPPROTO_TCP: u8 = 6;
    if ip.protocol != IPPROTO_TCP {
        return false;
    }

    // Example destination policy: 10.0.0.0/8
    let octets = ip.dst.octets();
    octets[0] == 10
}

/// Forward packet bytes to an output pcap capture handle.
/// In a real low-latency implementation, replace this with a zero-copy TX path.
fn forward_packet(tx: &mut Capture<pcap::Active>, packet: &[u8]) -> pcap::Result<()> {
    tx.sendpacket(packet)
}

fn open_capture(dev_name: &str) -> Result<Capture<pcap::Active>, Box<dyn Error>> {
    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == dev_name)
        .ok_or_else(|| format!("Device not found: {}", dev_name))?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .timeout(1)
        .open()?;

    // Capture full packets
    cap.setnonblock()?;
    Ok(cap)
}

fn main() -> Result<(), Box<dyn Error>> {
    let in_dev = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());
    let out_dev = std::env::args().nth(2).unwrap_or_else(|| "eth1".to_string());

    let mut rx = open_capture(&in_dev)?;
    let mut tx = open_capture(&out_dev)?;

    println!("Forwarding from {} -> {}", in_dev, out_dev);

    loop {
        match rx.next_packet() {
            Ok(pkt) => {
                let data = pkt.data;

                if let Some(frame) = parse_ethernet(data) {
                    if allow_packet(&frame) {
                        if let Err(e) = forward_packet(&mut tx, data) {
                            eprintln!("TX error: {}", e);
                        }
                    }
                }
            }
            Err(pcap::Error::NoMorePackets) => {
                // nonblocking mode: avoid busy spin
                std::hint::spin_loop();
            }
            Err(e) => {
                eprintln!("RX error: {}", e);
                thread::sleep(Duration::from_micros(50));
            }
        }
    }
}
