    src_port: u16,
    dst_port: u16,
}

fn parse_eth(frame: &[u8]) -> Option<EthernetHeader> {
    if frame.len() < 14 {
        return None;
    }
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    Some(EthernetHeader { ethertype })
}

fn parse_ipv4(packet: &[u8]) -> Option<Ipv4Header> {
    if packet.len() < 20 {
        return None;
    }
    let version_ihl = packet[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || packet.len() < ihl || ihl < 20 {
        return None;
    }

    let proto = packet[9];
    let src = Ipv4Addr::new(packet[12], packet[13], packet[14], packet[15]);
    let dst = Ipv4Addr::new(packet[16], packet[17], packet[18], packet[19]);

    Some(Ipv4Header {
        src,
        dst,
        proto,
        header_len: ihl,
    })
}

fn parse_l4(packet: &[u8], ip: &Ipv4Header) -> Option<L4Header> {
    let start = ip.header_len;
    if packet.len() < start + 4 {
        return None;
    }
    let src_port = u16::from_be_bytes([packet[start], packet[start + 1]]);
    let dst_port = u16::from_be_bytes([packet[start + 2], packet[start + 3]]);
    Some(L4Header { src_port, dst_port })
}

fn rule_matches(rule: &Rule, ip: &Ipv4Header, l4: Option<&L4Header>) -> bool {
    if let Some(src) = rule.src_ip {
        if ip.src != src {
            return false;
        }
    }
    if let Some(dst) = rule.dst_ip {
        if ip.dst != dst {
            return false;
        }
    }
    if let Some(proto) = rule.proto {
        if ip.proto != proto {
            return false;
        }
    }
    if rule.src_port.is_some() || rule.dst_port.is_some() {
        let l4 = match l4 {
            Some(h) => h,
            None => return false,
        };
        if let Some(p) = rule.src_port {
            if l4.src_port != p {
                return false;
            }
        }
        if let Some(p) = rule.dst_port {
            if l4.dst_port != p {
                return false;
            }
        }
    }
    true
}

fn decide_action(rules: &[Rule], ip: &Ipv4Header, l4: Option<&L4Header>, stats: &Stats) -> Action {
    for rule in rules {
        if rule_matches(rule, ip, l4) {
            stats.matched_rules.fetch_add(1, Ordering::Relaxed);
            return rule.action;
        }
    }
    Action::Drop
}

fn forward_packet(frame: &[u8], next_hop: Ipv4Addr, out_port: u16) {
    // Placeholder for actual NIC send path.
    // In a real implementation, this would enqueue to a TX ring or send via AF_XDP/DPDK.
    let _ = (frame.len(), next_hop, out_port);
}

fn process_packet(frame: &[u8], rules: &[Rule], stats: &Stats) {
    stats.rx_packets.fetch_add(1, Ordering::Relaxed);

    let eth = match parse_eth(frame) {
        Some(h) => h,
        None => {
            stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
            return;
        }
    };

    // Only IPv4 in this example.
    if eth.ethertype != 0x0800 {
        stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
        return;
    }

    let ip = match parse_ipv4(&frame[14..]) {
        Some(h) => h,
        None => {
            stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
            return;
        }
    };

    let l4 = if ip.proto == 6 || ip.proto == 17 {
        parse_l4(&frame[14..], &ip)
    } else {
        None
    };

    match decide_action(rules, &ip, l4.as_ref(), stats) {
        Action::Drop => {
            stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
        }
        Action::Accept => {
            // Deliver to local stack / application path.
            stats.tx_packets.fetch_add(1, Ordering::Relaxed);
        }
        Action::Forward { next_hop, out_port } => {
            forward_packet(frame, next_hop, out_port);
            stats.tx_packets.fetch_add(1, Ordering::Relaxed);
        }
    }
}

