impl<'a> Packet<'a> {
    pub fn parse_ipv4(&self) -> Option<(Ipv4Addr, Ipv4Addr, u8, usize)> {
        // Minimal Ethernet + IPv4 parser
        if self.data.len() < 14 + 20 {
