        let ihl = (version_ihl & 0x0f) as usize * 4;
        if version != 4 || ip.len() < ihl + 8 {
            return None;
        }

        let proto = ip[9];
        let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
        let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);
        Some((src, dst, proto, 14 + ihl))
    }

    pub fn parse_l4_ports(&self, l4_offset: usize) -> Option<(u16, u16)> {
        if self.data.len() < l4_offset + 4 {
            return None;
        }
        let src_port = u16::from_be_bytes([self.data[l4_offset], self.data[l4_offset + 1]]);
        let dst_port = u16::from_be_bytes([self.data[l4_offset + 2], self.data[l4_offset + 3]]);
        Some((src_port, dst_port))
    }
}

pub struct Engine {
    rules: Arc<RwLock<Vec<Rule>>>,
    stats: Arc<RwLock<Stats>>,
}

