    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules: Arc::new(RwLock::new(rules)),
            stats: Arc::new(RwLock::new(Stats::default())),
        }
    }

    pub fn update_rules(&self, rules: Vec<Rule>) {
        *self.rules.write() = rules;
    }

    pub fn stats(&self) -> Stats {
        self.stats.read().clone()
    }

    pub fn process_packet(&self, pkt: &Packet) -> Action {
        self.stats.write().rx_packets += 1;

        let parsed = match pkt.parse_ipv4() {
            Some(v) => v,
            None => {
                self.stats.write().dropped_packets += 1;
                return Action::Drop;
            }
        };

        let (src_ip, dst_ip, proto, l4_offset) = parsed;
        let (src_port, dst_port) = match pkt.parse_l4_ports(l4_offset) {
            Some(v) => v,
            None => (0, 0),
        };

        let rules = self.rules.read();
        for rule in rules.iter() {
            if let Some(v) = rule.src_ip {
                if v != src_ip { continue; }
            }
            if let Some(v) = rule.dst_ip {
                if v != dst_ip { continue; }
            }
            if let Some(v) = rule.proto {
                if v != proto { continue; }
            }
            if let Some(v) = rule.src_port {
                if v != src_port { continue; }
            }
            if let Some(v) = rule.dst_port {
                if v != dst_port { continue; }
            }

            self.stats.write().matched_rules += 1;
            return rule.action.clone();
        }

        // Default policy: drop
        self.stats.write().dropped_packets += 1;
        Action::Drop
    }
