    Drop,
    Forward(u16), // egress port
    Mirror(u16),  // telemetry / monitoring port
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub ingress_port: u16,
    pub len: usize,
    pub ethertype: u16,
    pub src_ip: Option<[u8; 4]>,
    pub dst_ip: Option<[u8; 4]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

pub struct Packet {
    pub meta: PacketMeta,
    pub data: Vec<u8>, // replace with fixed-size mbuf/zero-copy buffer in real deployment
}

pub trait Filter: Send + Sync {
    fn decide(&self, pkt: &Packet) -> Action;
}

pub struct Rules {
    pub allowed_ethertypes: Vec<u16>,
    pub blocked_ports: Vec<u16>,
    pub forward_default_port: u16,
    pub mirror_port: Option<u16>,
}

impl Filter for Rules {
    fn decide(&self, pkt: &Packet) -> Action {
        if !self.allowed_ethertypes.contains(&pkt.meta.ethertype) {
            return Action::Drop;
        }

        if let Some(dst_port) = pkt.meta.dst_port {
            if self.blocked_ports.contains(&dst_port) {
                return Action::Drop;
            }
        }

        if let Some(mirror) = self.mirror_port {
            // Example: mirror only TCP/UDP packets to telemetry
            if pkt.meta.src_port.is_some() || pkt.meta.dst_port.is_some() {
                return Action::Mirror(mirror);
            }
        }

        Action::Forward(self.forward_default_port)
    }
}

