            let egress_queues = self.egress_queues.clone();

            let handle = thread::spawn(move || {
                worker_loop(core_id, ingress, egress_queues, filter, stats, running);
            });

            handles.push(handle);
        }

        handles
    }

    pub fn stop(&self) {
        self.running.store(false, Ordering::SeqCst);
    }
}

fn worker_loop<F: Filter + 'static>(
    core_id: usize,
    ingress: Arc<ArrayQueue<Packet>>,
    egress_queues: Vec<Arc<ArrayQueue<Packet>>>,
    filter: Arc<F>,
    stats: Arc<Stats>,
    running: Arc<AtomicBool>,
) {
    let mut scratch = Vec::with_capacity(64);
    let mut last_report = Instant::now();

    while running.load(Ordering::Relaxed) {
        scratch.clear();

        // Batch receive
        for _ in 0..64 {
            if let Some(pkt) = ingress.pop() {
                scratch.push(pkt);
            } else {
                break;
            }
        }

        if scratch.is_empty() {
            thread::yield_now();
            continue;
        }

        for pkt in scratch.drain(..) {
            stats.rx.fetch_add(1, Ordering::Relaxed);

            match filter.decide(&pkt) {
                Action::Drop => {
                    stats.dropped.fetch_add(1, Ordering::Relaxed);
                }
                Action::Forward(port) => {
                    if let Some(txq) = egress_queues.get(port as usize) {
                        if txq.push(pkt).is_ok() {
                            stats.tx.fetch_add(1, Ordering::Relaxed);
                        } else {
                            stats.dropped.fetch_add(1, Ordering::Relaxed);
                        }
                    } else {
                        stats.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
                Action::Mirror(port) => {
                    stats.mirrored.fetch_add(1, Ordering::Relaxed);

                    if let Some(txq) = egress_queues.get(port as usize) {
                        let _ = txq.push(Packet {
                            meta: pkt.meta.clone(),
                            data: pkt.data.clone(),
                        });
                    }

                    // Continue forwarding original packet
                    let forward_port = 0u16;
                    if let Some(txq) = egress_queues.get(forward_port as usize) {
                        if txq.push(pkt).is_ok() {
                            stats.tx.fetch_add(1, Ordering::Relaxed);
                        } else {
                            stats.dropped.fetch_add(1, Ordering::Relaxed);
                        }
                    } else {
                        stats.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
        }

        if last_report.elapsed() >= Duration::from_secs(1) {
            let rx = stats.rx.load(Ordering::Relaxed);
            let tx = stats.tx.load(Ordering::Relaxed);
            let dr = stats.dropped.load(Ordering::Relaxed);
            let mr = stats.mirrored.load(Ordering::Relaxed);
            eprintln!(
                "[core {}] rx={} tx={} dropped={} mirrored={}",
                core_id, rx, tx, dr, mr
            );
            last_report = Instant::now();
        }
    }
}

