use tokio::io::{AsyncReadExt, AsyncWriteExt, copy_bidirectional};
use tokio::net::{TcpListener, TcpStream};
use std::net::SocketAddr;
use std::sync::Arc;

#[derive(Clone)]
struct FilterConfig {
    allowed_prefixes: Vec<Vec<u8>>,
    blocked_prefixes: Vec<Vec<u8>>,
    upstream: SocketAddr,
}

impl FilterConfig {
    fn allowed(&self, buf: &[u8]) -> bool {
        if self.blocked_prefixes.iter().any(|p| buf.starts_with(p)) {
            return false;
        }
        if self.allowed_prefixes.is_empty() {
            return true;
        }
        self.allowed_prefixes.iter().any(|p| buf.starts_with(p))
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse()?;
    let upstream: SocketAddr = "127.0.0.1:9001".parse()?;

    let cfg = Arc::new(FilterConfig {
        allowed_prefixes: vec![b"GET ".to_vec(), b"POST ".to_vec()],
        blocked_prefixes: vec![b"BAD".to_vec()],
        upstream,
    });

    let listener = TcpListener::bind(listen_addr).await?;
    println!("listening on {}", listen_addr);

    loop {
        let (mut inbound, peer) = listener.accept().await?;
        let cfg = cfg.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_connection(&mut inbound, peer, cfg).await {
                eprintln!("connection {} error: {}", peer, e);
            }
        });
    }
}

async fn handle_connection(
    inbound: &mut TcpStream,
    peer: SocketAddr,
    cfg: Arc<FilterConfig>,
) -> anyhow::Result<()> {
    // Peek initial bytes for filtering without consuming them.
    let mut peek_buf = [0u8; 64];
    let n = inbound.peek(&mut peek_buf).await?;
    let initial = &peek_buf[..n];

    if !cfg.allowed(initial) {
        eprintln!("blocked connection from {} (filter match)", peer);
        return Ok(());
    }

    let mut outbound = TcpStream::connect(cfg.upstream).await?;
    outbound.set_nodelay(true)?;
    inbound.set_nodelay(true)?;

    // Bidirectional forwarding with minimal overhead.
    let (mut ri, mut wi) = inbound.split();
    let (mut ro, mut wo) = outbound.split();

    let client_to_server = async {
        tokio::io::copy(&mut ri, &mut wo).await?;
        wo.shutdown().await?;
        Ok::<_, anyhow::Error>(())
    };

    let server_to_client = async {
        tokio::io::copy(&mut ro, &mut wi).await?;
        wi.shutdown().await?;
        Ok::<_, anyhow::Error>(())
    };

    tokio::try_join!(client_to_server, server_to_client)?;
    Ok(())
}
