## Rust example: packet filter + forwarder skeleton

```rust
// Cargo.toml dependencies:
// [dependencies]
// libc = "0.2"

use libc::*;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::ptr;
use std::time::Duration;

const ETH_P_ALL: u16 = 0x0003;
const BUF_SIZE: usize = 2048;

#[repr(C)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_packet_socket(ifname: &str) -> io::Result<OwnedFd> {
    let fd = unsafe {
        socket(
            AF_PACKET,
            SOCK_RAW | SOCK_NONBLOCK,
            i32::from(htons(ETH_P_ALL)),
        )
    };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }

    let ifname_c = CString::new(ifname).unwrap();
    let ifindex = unsafe { if_nametoindex(ifname_c.as_ptr()) };
    if ifindex == 0 {
        return Err(io::Error::last_os_error());
    }

    let mut sll: sockaddr_ll = unsafe { mem::zeroed() };
    sll.sll_family = AF_PACKET as u16;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    Ok(unsafe { OwnedFd::from_raw_fd(fd) })
}

fn parse_ethhdr(buf: &[u8]) -> Option<EthHdr> {
    if buf.len() < 14 {
        return None;
    }
    let mut hdr = EthHdr {
        dst: [0; 6],
        src: [0; 6],
        ethertype: 0,
    };
    hdr.dst.copy_from_slice(&buf[0..6]);
    hdr.src.copy_from_slice(&buf[6..12]);
    hdr.ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    Some(hdr)
}

fn should_forward(pkt: &[u8]) -> bool {
    // Example policy:
    // - forward only IPv4
    // - drop ARP
    // - drop packets smaller than Ethernet header
    if let Some(eth) = parse_ethhdr(pkt) {
        match eth.ethertype {
            0x0800 => true,  // IPv4
            0x86DD => true,  // IPv6
            _ => false,      // drop others
        }
    } else {
        false
    }
}

fn rewrite_for_forwarding(pkt: &mut [u8], new_dst_mac: [u8; 6], new_src_mac: [u8; 6]) {
    if pkt.len() < 14 {
        return;
    }
    pkt[0..6].copy_from_slice(&new_dst_mac);
    pkt[6..12].copy_from_slice(&new_src_mac);
}

fn main() -> io::Result<()> {
    let in_if = "eth0";
    let out_if = "eth1";

    let in_fd = open_packet_socket(in_if)?;
    let out_fd = open_packet_socket(out_if)?;

    // Example MACs; replace with your actual next-hop / interface MACs.
    let next_hop_mac = [0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff];
    let local_mac = [0x02, 0x00, 0x00, 0x00, 0x00, 0x01];

    let mut buf = vec![0u8; BUF_SIZE];

    loop {
        let n = unsafe {
            recv(
                in_fd.as_raw_fd(),
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::WouldBlock {
                std::thread::sleep(Duration::from_micros(50));
                continue;
            }
            return Err(err);
        }

        let n = n as usize;
        let pkt = &mut buf[..n];

        if !should_forward(pkt) {
            continue;
        }

        rewrite_for_forwarding(pkt, next_hop_mac, local_mac);

        let sent = unsafe {
            send(
                out_fd.as_raw_fd(),
                pkt.as_ptr() as *const c_void,
                pkt.len(),
                0,
            )
        };

        if sent < 0 {
            let err = io::Error::last_os_error();
            eprintln!("send error: {err}");
        }
    }
}
