```rust
use std::net::SocketAddr;
use std::sync::Arc;

use tokio::net::UdpSocket;
use tokio::sync::RwLock;

#[derive(Clone, Debug)]
struct AllowRule {
    src: Option<SocketAddr>,
    dst: SocketAddr,
}

#[derive(Clone)]
struct Policy {
    rules: Arc<RwLock<Vec<AllowRule>>>,
}

impl Policy {
    async fn is_allowed(&self, src: SocketAddr, dst: SocketAddr) -> bool {
        let rules = self.rules.read().await;
        rules.iter().any(|r| {
            let src_ok = r.src.map_or(true, |s| s == src);
            let dst_ok = r.dst == dst;
            src_ok && dst_ok
        })
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse()?;
    let backend_addr: SocketAddr = "127.0.0.1:9001".parse()?;

    let socket = UdpSocket::bind(listen_addr).await?;
    let backend = UdpSocket::bind("0.0.0.0:0").await?;

    let policy = Policy {
        rules: Arc::new(RwLock::new(vec![
            AllowRule {
                src: None,
                dst: backend_addr,
            },
        ])),
    };

    let mut buf = vec![0u8; 2048];

    loop {
        let (len, src) = socket.recv_from(&mut buf).await?;
        let packet = &buf[..len];

        if policy.is_allowed(src, backend_addr).await {
            let sent = backend.send_to(packet, backend_addr).await?;
            println!("forwarded {} bytes from {} to {}", sent, src, backend_addr);
        } else {
            println!("dropped {} bytes from {}", len, src);
        }
    }
}
