```rust
use std::net::IpAddr;
use std::sync::Arc;
use std::thread;

use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::Packet;

const MAX_PACKET_SIZE: usize = 2048;

#[derive(Clone, Debug)]
struct FilterRule {
    allow_src: Option<IpAddr>,
    allow_dst: Option<IpAddr>,
    block_src: Option<IpAddr>,
    block_dst: Option<IpAddr>,
}

impl FilterRule {
    fn allow_packet(&self, eth: &EthernetPacket) -> bool {
        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                    let src = IpAddr::V4(ipv4.get_source());
                    let dst = IpAddr::V4(ipv4.get_destination());

                    if self.block_src == Some(src) || self.block_dst == Some(dst) {
                        return false;
                    }
                    if let Some(allow_src) = self.allow_src {
                        if allow_src != src {
                            return false;
                        }
                    }
                    if let Some(allow_dst) = self.allow_dst {
                        if allow_dst != dst {
                            return false;
                        }
                    }
                    true
                } else {
                    false
                }
            }
            // Non-IPv4 traffic: drop by default in this example
            _ => false,
        }
    }
}

fn find_interface(name: &str) -> NetworkInterface {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .expect("interface not found")
}

fn main() -> anyhow::Result<()> {
    let in_if = find_interface("eth0");
    let out_if = find_interface("eth1");

    let filter = Arc::new(FilterRule {
        allow_src: None,
        allow_dst: None,
        block_src: None,
        block_dst: None,
    });

    let mut cfg = Config::default();
    cfg.read_timeout = Some(std::time::Duration::from_millis(0));
    cfg.write_buffer_size = 1 << 20;
    cfg.read_buffer_size = 1 << 20;
    cfg.promiscuous = true;

    let (mut tx, mut rx) = match datalink::channel(&in_if, cfg.clone())? {
        Ethernet(tx, rx) => (tx, rx),
        _ => return Err(anyhow::anyhow!("unsupported channel type")),
    };

    let (mut out_tx, _) = match datalink::channel(&out_if, cfg)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => return Err(anyhow::anyhow!("unsupported channel type")),
    };

    let filter_clone = filter.clone();

    let handle = thread::spawn(move || {
        let mut buf = [0u8; MAX_PACKET_SIZE];

        loop {
            match rx.next() {
                Ok(packet) => {
                    let len = packet.len().min(MAX_PACKET_SIZE);
                    buf[..len].copy_from_slice(&packet[..len]);

                    if let Some(eth) = EthernetPacket::new(&buf[..len]) {
                        if filter_clone.allow_packet(&eth) {
                            // Forward packet as-is
                            if let Some(mut out_buf) = out_tx.build_and_send(1, len) {
                                out_buf.copy_from_slice(&buf[..len]);
                            }
                        }
                    }
                }
                Err(_) => {
                    // In a low-latency service, avoid busy spinning too hard if needed.
                    // Here we just continue.
                    continue;
                }
            }
        }
    });

    handle.join().unwrap();
    Ok(())
}
