    Other(u8),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Action {
    Allow,
    Drop,
    Forward(u16), // output port / next hop ID
}

#[derive(Clone)]
struct Rule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Option<Protocol>,
    action: Action,
}

impl Rule {
    fn matches(&self, p: &Packet) -> bool {
        self.src_ip.map_or(true, |ip| ip == p.src_ip)
            && self.dst_ip.map_or(true, |ip| ip == p.dst_ip)
            && self.src_port.map_or(true, |port| port == p.src_port)
            && self.dst_port.map_or(true, |port| port == p.dst_port)
            && self.protocol.map_or(true, |proto| proto == p.protocol)
    }
}

struct FilterEngine {
    rules: Vec<Rule>,
    default_action: Action,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>, default_action: Action) -> Self {
        Self { rules, default_action }
    }

    #[inline(always)]
    fn classify(&self, pkt: &Packet) -> Action {
        for rule in &self.rules {
            if rule.matches(pkt) {
                return rule.action;
            }
        }
        self.default_action
    }
}

struct Forwarder {
    engine: Arc<FilterEngine>,
}

impl Forwarder {
    fn new(engine: Arc<FilterEngine>) -> Self {
        Self { engine }
    }

    #[inline(always)]
    fn process_packet(&self, pkt: &Packet) {
        match self.engine.classify(pkt) {
            Action::Allow => {
                // Fast path: deliver to local consumer / next stage
                self.deliver(pkt);
            }
            Action::Drop => {
                // Intentionally drop
            }
            Action::Forward(port) => {
                self.forward(pkt, port);
            }
        }
    }

    #[inline(always)]
    fn deliver(&self, pkt: &Packet) {
        // Replace with actual local delivery logic
        let _ = pkt;
    }

    #[inline(always)]
    fn forward(&self, pkt: &Packet, port: u16) {
        // Replace with actual TX queue / NIC send logic
        let _ = (pkt, port);
    }
}

fn main() {
    let rules = vec![
        Rule {
            src_ip: None,
            dst_ip: Some(Ipv4Addr::new(10, 0, 0, 10)),
            src_port: None,
            dst_port: Some(443),
            protocol: Some(Protocol::Tcp),
            action: Action::Forward(1),
        },
        Rule {
            src_ip: Some(Ipv4Addr::new(192, 168, 1, 100)),
            dst_ip: None,
            src_port: None,
            dst_port: None,
            protocol: None,
            action: Action::Drop,
        },
    ];

    let engine = Arc::new(FilterEngine::new(rules, Action::Allow));
    let forwarder = Arc::new(Forwarder::new(engine));

    let worker = {
        let forwarder = forwarder.clone();
        thread::spawn(move || {
            // Simulated packet stream
            let packets = vec![
                Packet {
                    src_ip: Ipv4Addr::new(192, 168, 1, 50),
                    dst_ip: Ipv4Addr::new(10, 0, 0, 10),
                    src_port: 50000,
                    dst_port: 443,
                    protocol: Protocol::Tcp,
                    payload_len: 1200,
                },
                Packet {
                    src_ip: Ipv4Addr::new(192, 168, 1, 100),
                    dst_ip: Ipv4Addr::new(8, 8, 8, 8),
