```rust
use anyhow::{Context, Result};
use crossbeam_channel::{bounded, Receiver};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
struct FilterRule {
    allow_src: Option<Ipv4Addr>,
    allow_dst: Option<Ipv4Addr>,
    allow_tcp_port: Option<u16>,
}

impl FilterRule {
    fn matches(&self, eth: &EthernetPacket) -> bool {
        if eth.get_ethertype() != EtherTypes::Ipv4 {
            return false; // only forward IPv4 in this example
        }

        let Some(ipv4) = Ipv4Packet::new(eth.payload()) else {
            return false;
        };

        if let Some(src) = self.allow_src {
            if ipv4.get_source() != src {
                return false;
            }
        }

        if let Some(dst) = self.allow_dst {
            if ipv4.get_destination() != dst {
                return false;
            }
        }

        if let Some(port) = self.allow_tcp_port {
            if ipv4.get_next_level_protocol() != IpNextHeaderProtocols::Tcp {
                return false;
            }
            let Some(tcp) = TcpPacket::new(ipv4.payload()) else {
                return false;
            };
            if tcp.get_destination() != port && tcp.get_source() != port {
                return false;
            }
        }

        true
    }
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface not found: {name}"))
}

fn open_channel(iface: &NetworkInterface) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;

    match datalink::channel(iface, config)? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => anyhow::bail!("unsupported channel type"),
    }
}

fn capture_loop(
    mut rx: Box<dyn DataLinkReceiver>,
    tx_queue: crossbeam_channel::Sender<Vec<u8>>,
    rule: Arc<FilterRule>,
) {
    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(eth) = EthernetPacket::new(packet) {
                    if rule.matches(&eth) {
                        // Copy packet into queue for forwarding
                        let _ = tx_queue.try_send(packet.to_vec());
                    }
                }
            }
            Err(_) => {
                // ignore transient read errors/timeouts
            }
        }
    }
}

fn forward_loop(mut tx: Box<dyn DataLinkSender>, rx_queue: Receiver<Vec<u8>>) {
    while let Ok(pkt) = rx_queue.recv() {
        let _ = tx.send_to(&pkt, None);
        // In production, inspect send result and handle MTU/fragmentation.
    }
}

fn main() -> Result<()> {
    // Example usage:
    // sudo cargo run -- <input-iface> <output-iface> <src-ip-or-> <dst-ip-or-> <tcp-port-or-0>
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 6 {
        eprintln!(
            "Usage: {} <in-iface> <out-iface> <src-ip|-> <dst-ip|-> <tcp-port|0>",
            args[0]
        );
        std::process::exit(1);
    }

    let in_iface = find_interface(&args[1])?;
    let out_iface = find_interface(&args[2])?;

    let allow_src = if args[3] == "-" { None } else { Some(args[3].parse()?) };
    let allow_dst = if args[4] == "-" { None } else { Some(args[4].parse()?) };
    let allow_tcp_port = match args[5].parse::<u16>()? {
        0 => None,
        p => Some(p),
    };

    let rule = Arc::new(FilterRule {
        allow_src,
        allow_dst,
        allow_tcp_port,
    });

    let (in_tx, in_rx) = bounded::<Vec<u8>>(4096);

    let (_, in_rx_chan) = open_channel(&in_iface)?;
    let (out_tx, _) = open_channel(&out_iface)?;

    let rule_clone = rule.clone();
    let capture = thread::spawn(move || capture_loop(in_rx_chan, in_tx, rule_clone));
    let forward = thread::spawn(move || forward_loop(out_tx, in_rx));

    let _ = capture.join();
    let _ = forward.join();

    Ok(())
}
