use etherparse::{Ipv4HeaderSlice, Ipv6HeaderSlice, SlicedPacket, TransportHeader};

#[derive(Clone, Debug)]
pub enum PacketAction {
    Drop,
    Forward,
    ModifyAndForward,
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub src_ip: Option<String>,
    pub dst_ip: Option<String>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>,
}

#[derive(Clone, Debug)]
pub struct Packet {
    pub data: Vec<u8>,
    pub meta: PacketMeta,
}

impl Packet {
    pub fn parse(data: Vec<u8>) -> Self {
        let mut meta = PacketMeta {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            protocol: None,
        };

        if let Ok(sliced) = SlicedPacket::from_ethernet(&data) {
            match sliced.ip {
                Some(etherparse::InternetSlice::Ipv4(header, _)) => {
                    meta.src_ip = Some(header.source_addr().to_string());
                    meta.dst_ip = Some(header.destination_addr().to_string());
                    meta.protocol = Some(header.protocol() as u8);
                }
                Some(etherparse::InternetSlice::Ipv6(header, _)) => {
                    meta.src_ip = Some(header.source_addr().to_string());
                    meta.dst_ip = Some(header.destination_addr().to_string());
                    meta.protocol = Some(header.next_header().0);
                }
                _ => {}
            }

            if let Some(transport) = sliced.transport {
                match transport {
                    TransportHeader::Tcp(tcp) => {
                        meta.src_port = Some(tcp.source_port());
                        meta.dst_port = Some(tcp.destination_port());
                    }
                    TransportHeader::Udp(udp) => {
                        meta.src_port = Some(udp.source_port());
                        meta.dst_port = Some(udp.destination_port());
                    }
                    _ => {}
                }
            }
        }

        Self { data, meta }
    }
}
