use crate::packet::{Packet, PacketAction};

#[derive(Clone, Debug)]
pub enum FilterRule {
    DropDstPort(u16),
    DropSrcIp(String),
    AllowAll,
}

#[derive(Clone, Debug)]
pub struct FilterEngine {
    rules: Vec<FilterRule>,
}

impl FilterEngine {
    pub fn new(rules: Vec<FilterRule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, pkt: &Packet) -> PacketAction {
        for rule in &self.rules {
            match rule {
                FilterRule::DropDstPort(port) => {
                    if pkt.meta.dst_port == Some(*port) {
                        return PacketAction::Drop;
                    }
                }
                FilterRule::DropSrcIp(ip) => {
                    if pkt.meta.src_ip.as_deref() == Some(ip.as_str()) {
                        return PacketAction::Drop;
                    }
                }
                FilterRule::AllowAll => {
                    return PacketAction::Forward;
                }
            }
        }
        PacketAction::Forward
    }
}
