use crate::{
    filter::FilterEngine,
    forward::ForwardEngine,
    packet::{Packet, PacketAction},
};
use anyhow::Result;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    thread,
    time::Duration,
};

pub struct Stats {
    pub received: AtomicU64,
    pub forwarded: AtomicU64,
    pub dropped: AtomicU64,
    pub errors: AtomicU64,
}

impl Stats {
    pub fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            forwarded: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            errors: AtomicU64::new(0),
        }
    }
}

pub struct Engine {
    filter: FilterEngine,
    forwarder: ForwardEngine,
    stats: Arc<Stats>,
}

impl Engine {
    pub fn new(filter: FilterEngine, forwarder: ForwardEngine) -> Self {
        Self {
            filter,
            forwarder,
            stats: Arc::new(Stats::new()),
        }
    }

    pub fn run(&self) -> Result<()> {
        // Placeholder packet source loop.
        // In a real low-latency service, this would be:
        // - AF_XDP ring polling
        // - raw socket recv
        // - DPDK burst receive
        // - io_uring poll
        //
        // Here we simulate packet ingress.
        loop {
            let fake_packet = vec![0u8; 64];
            let pkt = Packet::parse(fake_packet);

            self.stats.received.fetch_add(1, Ordering::Relaxed);

            match self.filter.evaluate(&pkt) {
                PacketAction::Drop => {
                    self.stats.dropped.fetch_add(1, Ordering::Relaxed);
                }
                PacketAction::Forward | PacketAction::ModifyAndForward => {
                    if let Err(_e) = self.forwarder.forward(&pkt) {
                        self.stats.errors.fetch_add(1, Ordering::Relaxed);
                    } else {
                        self.stats.forwarded.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }

            // Avoid busy-spinning too aggressively in this starter version.
            // For ultra-low-latency production, replace with busy-poll tuning.
            thread::sleep(Duration::from_micros(10));
        }
    }

    pub fn stats(&self) -> Arc<Stats> {
        self.stats.clone()
    }
}
