use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    pub ethertype: u16,
    pub src_mac: [u8; 6],
    pub dst_mac: [u8; 6],
    pub ipv4_src: Option<Ipv4Addr>,
    pub ipv4_dst: Option<Ipv4Addr>,
    pub l4_proto: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub payload: &'a [u8],
}

pub fn parse_packet<'a>(data: &'a [u8]) -> Option<PacketView<'a>> {
    if data.len() < 14 {
        return None;
    }

    let mut dst_mac = [0u8; 6];
    let mut src_mac = [0u8; 6];
    dst_mac.copy_from_slice(&data[0..6]);
    src_mac.copy_from_slice(&data[6..12]);

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    let mut offset = 14;

    let mut ipv4_src = None;
    let mut ipv4_dst = None;
    let mut l4_proto = None;
    let mut src_port = None;
    let mut dst_port = None;

    if ethertype == 0x0800 {
        if data.len() < offset + 20 {
            return None;
        }

        let ihl = (data[offset] & 0x0f) as usize * 4;
        if data.len() < offset + ihl || ihl < 20 {
            return None;
        }

        let proto = data[offset + 9];
        ipv4_src = Some(Ipv4Addr::new(
            data[offset + 12],
            data[offset + 13],
            data[offset + 14],
            data[offset + 15],
        ));
        ipv4_dst = Some(Ipv4Addr::new(
            data[offset + 16],
            data[offset + 17],
            data[offset + 18],
            data[offset + 19],
        ));

        offset += ihl;

        l4_proto = Some(match proto {
            6 => L4Protocol::Tcp,
            17 => L4Protocol::Udp,
            1 => L4Protocol::Icmp,
            x => L4Protocol::Other(x),
        });

        if matches!(l4_proto, Some(L4Protocol::Tcp | L4Protocol::Udp)) {
            if data.len() < offset + 4 {
                return None;
            }
            src_port = Some(u16::from_be_bytes([data[offset], data[offset + 1]]));
            dst_port = Some(u16::from_be_bytes([data[offset + 2], data[offset + 3]]));
        }
    }

    Some(PacketView {
        ethertype,
        src_mac,
        dst_mac,
        ipv4_src,
        ipv4_dst,
        l4_proto,
        src_port,
        dst_port,
        payload: if offset <= data.len() { &data[offset..] } else { &[] },
    })
}
