use std::net::Ipv4Addr;

use crate::packet::L4Protocol;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Allow,
    Drop,
    ForwardTo(u16),
}

#[derive(Debug, Clone, Copy)]
pub struct Rule {
    pub ethertype: Option<u16>,
    pub ipv4_src: Option<Ipv4Addr>,
    pub ipv4_dst: Option<Ipv4Addr>,
    pub l4_proto: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub action: Action,
}

impl Rule {
    pub fn matches(&self, pkt: &crate::packet::PacketView<'_>) -> bool {
        if let Some(v) = self.ethertype {
            if pkt.ethertype != v {
                return false;
            }
        }
        if let Some(v) = self.ipv4_src {
            if pkt.ipv4_src != Some(v) {
                return false;
            }
        }
        if let Some(v) = self.ipv4_dst {
            if pkt.ipv4_dst != Some(v) {
                return false;
            }
        }
        if let Some(v) = self.l4_proto {
            if pkt.l4_proto != Some(v) {
                return false;
            }
        }
        if let Some(v) = self.src_port {
            if pkt.src_port != Some(v) {
                return false;
            }
        }
        if let Some(v) = self.dst_port {
            if pkt.dst_port != Some(v) {
                return false;
            }
        }
        true
    }
}

#[derive(Debug)]
pub struct RuleSet {
    rules: Vec<Rule>,
    default_action: Action,
}

impl RuleSet {
    pub fn new(default_action: Action) -> Self {
        Self {
            rules: Vec::new(),
            default_action,
        }
    }

    pub fn add_rule(&mut self, rule: Rule) {
        self.rules.push(rule);
    }

    pub fn decide(&self, pkt: &crate::packet::PacketView<'_>) -> Action {
        for rule in &self.rules {
            if rule.matches(pkt) {
                return rule.action;
            }
        }
        self.default_action
    }
}
