use crate::{
    packet::parse_packet,
    rules::{Action, RuleSet},
};

#[derive(Debug)]
pub struct Engine {
    rules: RuleSet,
    ingress_ifindex: u16,
    egress_ifindex: u16,
}

impl Engine {
    pub fn new(rules: RuleSet, ingress_ifindex: u16, egress_ifindex: u16) -> Self {
        Self {
            rules,
            ingress_ifindex,
            egress_ifindex,
        }
    }

    pub fn process_frame(&self, frame: &[u8]) -> Action {
        let _ = self.ingress_ifindex;

        let pkt = match parse_packet(frame) {
            Some(p) => p,
            None => return Action::Drop,
        };

        match self.rules.decide(&pkt) {
            Action::Allow => Action::ForwardTo(self.egress_ifindex),
            Action::Drop => Action::Drop,
            Action::ForwardTo(port) => Action::ForwardTo(port),
        }
    }
}
