## `src/filter.rs`

```rust
use crate::config::{Action, RuleConfig};
use crate::packet::Packet;
use std::net::IpAddr;

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub payload_prefix: Option<Vec<u8>>,
}

#[derive(Debug, Clone)]
pub struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    pub fn new(rule_cfgs: Vec<RuleConfig>) -> anyhow::Result<Self> {
        let mut rules = Vec::with_capacity(rule_cfgs.len());

        for r in rule_cfgs {
            let src_ip = match r.src_ip {
                Some(v) => Some(v.parse()?),
                None => None,
            };
            let dst_ip = match r.dst_ip {
                Some(v) => Some(v.parse()?),
                None => None,
            };

            let payload_prefix = match r.payload_prefix_hex {
                Some(hex) => Some(parse_hex(&hex)?),
                None => None,
            };

            rules.push(Rule {
                action: r.action,
                src_ip,
                dst_ip,
                src_port: r.src_port,
                dst_port: r.dst_port,
                payload_prefix,
            });
        }

        Ok(Self { rules })
    }

    pub fn should_forward(&self, pkt: &Packet) -> bool {
        let mut decision = true; // default allow

        for rule in &self.rules {
            if rule_matches(rule, pkt) {
                decision = matches!(rule.action, Action::Allow);
            }
        }

        decision
    }
}

fn rule_matches(rule: &Rule, pkt: &Packet) -> bool {
    if let Some(ip) = rule.src_ip {
        if pkt.src.ip() != ip {
            return false;
        }
    }
    if let Some(ip) = rule.dst_ip {
        if pkt.dst.ip() != ip {
            return false;
        }
    }
    if let Some(port) = rule.src_port {
        if pkt.src.port() != port {
            return false;
        }
    }
    if let Some(port) = rule.dst_port {
        if pkt.dst.port() != port {
            return false;
        }
    }
    if let Some(prefix) = &rule.payload_prefix {
        if pkt.payload.len() < prefix.len() {
            return false;
        }
        if &pkt.payload[..prefix.len()] != prefix.as_slice() {
            return false;
        }
    }
    true
}

fn parse_hex(s: &str) -> anyhow::Result<Vec<u8>> {
    let clean = s.trim().trim_start_matches("0x").replace('_', "");
    if clean.len() % 2 != 0 {
        anyhow::bail!("hex string must have even length");
    }

    let mut out = Vec::with_capacity(clean.len() / 2);
    for i in (0..clean.len()).step_by(2) {
        let byte = u8::from_str_radix(&clean[i..i + 2], 16)?;
        out.push(byte);
    }
    Ok(out)
}
```

