use crate::packet::Packet;
use anyhow::Context;
use std::net::SocketAddr;
use tokio::net::UdpSocket;

#[derive(Debug)]
pub struct Forwarder {
    targets: Vec<SocketAddr>,
    socket: UdpSocket,
}

impl Forwarder {
    pub async fn new(bind: SocketAddr, targets: Vec<SocketAddr>) -> anyhow::Result<Self> {
        let socket = UdpSocket::bind(bind)
            .await
            .with_context(|| format!("failed to bind forward socket on {bind}"))?;

        Ok(Self { targets, socket })
    }

    pub async fn forward(&self, pkt: &Packet) -> anyhow::Result<usize> {
        let mut sent = 0usize;
        for target in &self.targets {
            self.socket
                .send_to(&pkt.payload, target)
                .await
                .with_context(|| format!("failed to forward packet to {target}"))?;
            sent += 1;
        }
        Ok(sent)
    }
}
