```rust
mod config;
mod filter;
mod forward;
mod packet;

use anyhow::Context;
use config::Config;
use filter::FilterEngine;
use forward::Forwarder;
use packet::Packet;
use std::sync::Arc;
use tokio::net::UdpSocket;
use tracing::{info, warn};

#[derive(Debug, Default)]
struct Metrics {
    received: std::sync::atomic::AtomicU64,
    filtered: std::sync::atomic::AtomicU64,
    forwarded: std::sync::atomic::AtomicU64,
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_str = r#"
listen = "0.0.0.0:9000"
forward_targets = ["127.0.0.1:9100"]

[[rules]]
action = "deny"
src_ip = "10.0.0.1"

[[rules]]
action = "allow"
payload_prefix_hex = "deadbeef"
"#;

    let cfg = Config::from_toml_str(config_str).context("invalid config")?;
    let filter = Arc::new(FilterEngine::new(cfg.rules)?);

    let listen_socket = UdpSocket::bind(cfg.listen)
        .await
        .with_context(|| format!("failed to bind listen socket on {}", cfg.listen))?;

    let forwarder = Arc::new(
        Forwarder::new("0.0.0.0:0".parse()?, cfg.forward_targets.clone()).await?,
    );

    let metrics = Arc::new(Metrics::default());
    let mut buf = vec![0u8; 2048];

    info!("listening on {}", cfg.listen);

    loop {
        let (len, src) = listen_socket.recv_from(&mut buf).await?;
        metrics.received.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

        let payload = buf[..len].to_vec();
        let dst = listen_socket.local_addr()?;

        let pkt = Packet { src, dst, payload };

        if filter.should_forward(&pkt) {
            let fwd = forwarder.clone();
            let metrics_clone = metrics.clone();

            tokio::spawn(async move {
                match fwd.forward(&pkt).await {
                    Ok(n) => {
                        metrics_clone.forwarded.fetch_add(
                            n as u64,
                            std::sync::atomic::Ordering::Relaxed,
                        );
                    }
                    Err(e) => {
                        warn!("forwarding error: {e:#}");
                    }
                }
            });
        } else {
            metrics.filtered.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
    }
}
```

