use bytes::BytesMut;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use socket2::{Domain, Protocol, Socket, Type};
use std::io;
use std::net::{SocketAddr, UdpSocket};
use std::sync::Arc;
use std::thread;
use std::time::Instant;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Action {
    Allow,
    Drop,
    Forward(SocketAddr),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub id: u64,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub action: Action,
}

#[derive(Debug, Default)]
pub struct Metrics {
    pub packets_in: u64,
    pub packets_out: u64,
    pub packets_dropped: u64,
    pub rule_hits: u64,
}

#[derive(Clone)]
pub struct RuleEngine {
    rules: Arc<RwLock<Vec<Rule>>>,
}

impl RuleEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules: Arc::new(RwLock::new(rules)),
        }
    }

    pub fn update_rules(&self, rules: Vec<Rule>) {
        *self.rules.write() = rules;
    }

    pub fn evaluate(&self, packet: &[u8]) -> Action {
        // Minimal UDP parser for demonstration.
        // Assumes IPv4 + UDP and directly inspects ports when possible.
        // Real implementation should validate headers carefully.
        if packet.len() < 28 {
            return Action::Drop;
        }

        let ip_header_len = ((packet[0] & 0x0f) * 4) as usize;
        if packet.len() < ip_header_len + 8 {
            return Action::Drop;
        }

        let protocol = packet[9];
        if protocol != 17 {
            // UDP only in this starter implementation
            return Action::Drop;
        }

        let udp_offset = ip_header_len;
        let src_port = u16::from_be_bytes([packet[udp_offset], packet[udp_offset + 1]]);
        let dst_port = u16::from_be_bytes([packet[udp_offset + 2], packet[udp_offset + 3]]);

        let rules = self.rules.read();
        for rule in rules.iter() {
            let src_match = rule.src_port.map_or(true, |p| p == src_port);
            let dst_match = rule.dst_port.map_or(true, |p| p == dst_port);
            if src_match && dst_match {
                return rule.action.clone();
            }
        }

        Action::Allow
    }
}

pub struct PacketService {
    socket: UdpSocket,
    filter: RuleEngine,
    metrics: Arc<RwLock<Metrics>>,
}

impl PacketService {
    pub fn bind(bind_addr: SocketAddr, filter: RuleEngine) -> io::Result<Self> {
        let socket = create_udp_socket(bind_addr)?;
        socket.set_nonblocking(false)?;
        Ok(Self {
            socket,
            filter,
            metrics: Arc::new(RwLock::new(Metrics::default())),
        })
    }

    pub fn run(&self) -> io::Result<()> {
        let mut buf = [0u8; 2048];
        let mut tx_buf = BytesMut::with_capacity(2048);

        loop {
            let start = Instant::now();
            let (len, peer) = self.socket.recv_from(&mut buf)?;
            {
                let mut m = self.metrics.write();
                m.packets_in += 1;
            }

            let packet = &buf[..len];
            let action = self.filter.evaluate(packet);

            match action {
                Action::Drop => {
                    let mut m = self.metrics.write();
                    m.packets_dropped += 1;
                }
                Action::Allow => {
                    // Echo forward to sender in this starter implementation.
                    tx_buf.clear();
                    tx_buf.extend_from_slice(packet);
                    self.socket.send_to(&tx_buf, peer)?;
                    let mut m = self.metrics.write();
                    m.packets_out += 1;
                }
                Action::Forward(target) => {
                    tx_buf.clear();
                    tx_buf.extend_from_slice(packet);
                    self.socket.send_to(&tx_buf, target)?;
                    let mut m = self.metrics.write();
                    m.packets_out += 1;
                }
            }

            let elapsed = start.elapsed();
            // Hook for latency metrics if needed.
            let _ = elapsed;
        }
    }
}

fn create_udp_socket(addr: SocketAddr) -> io::Result<UdpSocket> {
    let domain = match addr {
        SocketAddr::V4(_) => Domain::IPV4,
        SocketAddr::V6(_) => Domain::IPV6,
    };

    let socket = Socket::new(domain, Type::DGRAM, Some(Protocol::UDP))?;
    socket.set_reuse_address(true)?;
    socket.bind(&addr.into())?;
    Ok(socket.into())
}

fn main() -> io::Result<()> {
    let rules = vec![
        Rule {
            id: 1,
            src_port: Some(12345),
            dst_port: Some(8080),
            action: Action::Drop,
        },
        Rule {
            id: 2,
            src_port: None,
            dst_port: Some(9000),
            action: Action::Forward("127.0.0.1:9100".parse().unwrap()),
        },
    ];

    let filter = RuleEngine::new(rules);
    let bind_addr: SocketAddr = "0.0.0.0:9000".parse().unwrap();
    let service = PacketService::bind(bind_addr, filter)?;

    println!("Packet service listening on {}", bind_addr);
    service.run()
}
