```rust
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

#[derive(Clone, Debug)]
pub enum Action {
    Drop,
    Forward { port: u16 },
    Pass,
}

#[derive(Clone, Debug)]
pub struct FilterRule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<u8>, // e.g. 6 = TCP, 17 = UDP
    pub action: Action,
}

#[derive(Default)]
pub struct Stats {
    pub rx_packets: AtomicU64,
    pub tx_packets: AtomicU64,
    pub dropped_packets: AtomicU64,
    pub filtered_packets: AtomicU64,
}

#[derive(Clone, Debug)]
pub struct Packet {
    pub data: Vec<u8>,
}

pub trait PacketSource: Send {
    fn recv_batch(&mut self, max: usize) -> Vec<Packet>;
}

pub trait PacketSink: Send {
    fn send_batch(&mut self, packets: &[Packet]);
}

pub struct Engine<S: PacketSource, T: PacketSink> {
    source: S,
    sink: T,
    rules: Vec<FilterRule>,
    stats: Arc<Stats>,
}

impl<S: PacketSource, T: PacketSink> Engine<S, T> {
    pub fn new(source: S, sink: T, rules: Vec<FilterRule>) -> Self {
        Self {
            source,
            sink,
            rules,
            stats: Arc::new(Stats::default()),
        }
    }

    pub fn stats(&self) -> Arc<Stats> {
        self.stats.clone()
    }

    pub fn run_once(&mut self) {
        let batch = self.source.recv_batch(64);
        if batch.is_empty() {
            return;
        }

        self.stats.rx_packets.fetch_add(batch.len() as u64, Ordering::Relaxed);

        let mut forwarded = Vec::with_capacity(batch.len());

        for pkt in batch {
            match self.classify_and_route(&pkt) {
                Action::Drop => {
                    self.stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                }
                Action::Pass => {
                    self.stats.filtered_packets.fetch_add(1, Ordering::Relaxed);
                    forwarded.push(pkt);
                }
                Action::Forward { .. } => {
                    self.stats.tx_packets.fetch_add(1, Ordering::Relaxed);
                    forwarded.push(pkt);
                }
            }
        }

        if !forwarded.is_empty() {
            self.sink.send_batch(&forwarded);
        }
    }

    fn classify_and_route(&self, pkt: &Packet) -> Action {
        if let Some((src_ip, dst_ip, proto, src_port, dst_port)) = parse_ipv4_packet(&pkt.data) {
            for rule in &self.rules {
                if rule_matches(rule, src_ip, dst_ip, proto, src_port, dst_port) {
                    return rule.action.clone();
                }
            }
            Action::Pass
        } else {
            Action::Drop
        }
    }
}

fn rule_matches(
    rule: &FilterRule,
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    proto: u8,
    src_port: Option<u16>,
    dst_port: Option<u16>,
) -> bool {
    if let Some(v) = rule.src_ip {
        if v != src_ip {
            return false;
        }
    }
    if let Some(v) = rule.dst_ip {
        if v != dst_ip {
            return false;
        }
    }
    if let Some(v) = rule.proto {
        if v != proto {
            return false;
        }
    }
    if let Some(v) = rule.src_port {
        if Some(v) != src_port {
            return false;
        }
    }
    if let Some(v) = rule.dst_port {
        if Some(v) != dst_port {
            return false;
        }
    }
    true
}

/// Minimal IPv4 parser:
/// Returns (src_ip, dst_ip, proto, src_port, dst_port)
fn parse_ipv4_packet(data: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u8, Option<u16>, Option<u16>)> {
    if data.len() < 34 {
        return None;
    }

    // Ethernet header: 14 bytes
    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None; // not IPv4
    }

    let ip_start = 14;
    let version_ihl = data[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || data.len() < ip_start + ihl {
        return None;
    }

    let proto = data[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        data[ip_start + 12],
        data[ip_start + 13],
        data[ip_start + 14],
        data[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        data[ip_start + 16],
        data[ip_start + 17],
        data[ip_start + 18],
        data[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    if data.len() < l4_start + 4 {
        return Some((src_ip, dst_ip, proto, None, None));
    }

    let (src_port, dst_port) = match proto {
        6 | 17 => {
            let sp = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
            let dp = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);
            (Some(sp), Some(dp))
        }
        _ => (None, None),
    };

    Some((src_ip, dst_ip, proto, src_port, dst_port))
}
