```rust
use crate::{config::FilterConfig, packet::Packet};
use std::net::IpAddr;

pub trait PacketFilter: Send + Sync {
    fn allow(&self, pkt: &Packet) -> bool;
}

#[derive(Debug, Clone)]
pub struct PrefixFilter {
    cfg: FilterConfig,
}

impl PrefixFilter {
    pub fn new(cfg: FilterConfig) -> Self {
        Self { cfg }
    }

    fn matches_prefixes(prefixes: &[String], ip: IpAddr) -> bool {
        if prefixes.is_empty() {
            return true;
        }

        let ip_s = ip.to_string();
        prefixes.iter().any(|p| ip_s.starts_with(p))
    }
}

impl PacketFilter for PrefixFilter {
    fn allow(&self, pkt: &Packet) -> bool {
        let len = pkt.len();

        if let Some(min_len) = self.cfg.min_len {
            if len < min_len {
                return false;
            }
        }

        if let Some(max_len) = self.cfg.max_len {
            if len > max_len {
                return false;
            }
        }

        let src_ok = Self::matches_prefixes(&self.cfg.allow_src_prefixes, pkt.src.ip());
        let dst_ok = Self::matches_prefixes(&self.cfg.allow_dst_prefixes, pkt.dst.ip());

        src_ok && dst_ok
    }
}
```

