```rust
use crate::{filter::PacketFilter, forward::Forwarder, packet::Packet};
use anyhow::Result;
use std::sync::Arc;
use tokio::net::UdpSocket;
use tracing::{debug, info, warn};

pub struct Service<F: PacketFilter> {
    listen: UdpSocket,
    filter: Arc<F>,
    forwarder: Arc<Forwarder>,
}

impl<F: PacketFilter + 'static> Service<F> {
    pub async fn new(listen_addr: &str, filter: F, forwarder: Forwarder) -> Result<Self> {
        let listen = UdpSocket::bind(listen_addr).await?;
        info!("service listening on {}", listen_addr);

        Ok(Self {
            listen,
            filter: Arc::new(filter),
            forwarder: Arc::new(forwarder),
        })
    }

    pub async fn run(&self) -> Result<()> {
        let mut buf = vec![0u8; 2048];

        loop {
            let (n, src) = self.listen.recv_from(&mut buf).await?;
            let dst = self.listen.local_addr()?;
            let payload = bytes::Bytes::copy_from_slice(&buf[..n]);

            let pkt = Packet { src, dst, payload };

            if self.filter.allow(&pkt) {
                debug!("packet allowed: {} -> {} ({} bytes)", pkt.src, pkt.dst, pkt.len());
                self.forwarder.forward(&pkt.payload).await?;
            } else {
                warn!("packet dropped: {} -> {} ({} bytes)", pkt.src, pkt.dst, pkt.len());
            }
        }
    }
}
```

