    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub action: Action,
}

#[derive(Default)]
pub struct RuleTable {
    rules: Vec<Rule>,
}

impl RuleTable {
    pub fn new() -> Self {
        Self { rules: Vec::new() }
    }

    pub fn add_rule(&mut self, rule: Rule) {
        self.rules.push(rule);
    }

    pub fn match_packet(&self, pkt: &PacketMeta) -> Action {
        for rule in &self.rules {
            if let Some(port) = rule.ingress_port {
                if port != pkt.ingress_port {
                    continue;
                }
            }
            if let Some(ethertype) = rule.ethertype {
                if ethertype != pkt.ethertype {
                    continue;
                }
            }
            if let Some(src_ip) = rule.src_ip {
                if Some(src_ip) != pkt.src_ip {
                    continue;
                }
            }
            if let Some(dst_ip) = rule.dst_ip {
                if Some(dst_ip) != pkt.dst_ip {
                    continue;
                }
            }
            if let Some(proto) = rule.protocol {
                if Some(proto) != pkt.protocol {
                    continue;
                }
            }
            if let Some(src_port) = rule.src_port {
                if Some(src_port) != pkt.src_port {
                    continue;
                }
            }
            if let Some(dst_port) = rule.dst_port {
                if Some(dst_port) != pkt.dst_port {
                    continue;
                }
            }
            return rule.action;
        }

        Action::Drop
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct PacketMeta {
    pub ingress_port: u16,
    pub ethertype: u16,
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub protocol: Option<u8>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

pub struct Packet<'a> {
    pub data: &'a [u8],
    pub meta: PacketMeta,
}

pub trait NicBackend: Send + Sync + 'static {
    fn poll_rx(&self, port: u16, budget: usize) -> Vec<Vec<u8>>;
    fn send_tx(&self, port: u16, packets: Vec<Vec<u8>>);
}

pub struct DummyNicBackend;

impl NicBackend for DummyNicBackend {
    fn poll_rx(&self, _port: u16, _budget: usize) -> Vec<Vec<u8>> {
        Vec::new()
    }

    fn send_tx(&self, _port: u16, _packets: Vec<Vec<u8>>) {}
}

pub struct Service<B: NicBackend> {
    backend: Arc<B>,
    rules: Arc<RwLock<RuleTable>>,
    ingress_ports: Vec<u16>,
}

impl<B: NicBackend> Service<B> {
    pub fn new(backend: B, ingress_ports: Vec<u16>) -> Self {
        Self {
            backend: Arc::new(backend),
            rules: Arc::new(RwLock::new(RuleTable::new())),
            ingress_ports,
        }
    }

    pub fn add_rule(&self, rule: Rule) {
        self.rules.write().add_rule(rule);
    }

    pub fn run(&self) {
        let mut handles = Vec::new();

        for &port in &self.ingress_ports {
            let backend = self.backend.clone();
            let rules = self.rules.clone();

            let handle = thread::spawn(move || {
                let mut tx_batch: Vec<Vec<u8>> = Vec::with_capacity(64);

                loop {
                    let packets = backend.poll_rx(port, 64);
                    if packets.is_empty() {
                        thread::yield_now();
                        continue;
                    }

                    for raw in packets {
                        let meta = parse_packet_meta(&raw, port);
                        let action = rules.read().match_packet(&meta);

                        match action {
                            Action::Drop => {
                                // drop packet
                            }
                            Action::Forward { port: out_port } => {
                                tx_batch.push(raw);
                                if tx_batch.len() >= 64 {
                                    backend.send_tx(out_port, std::mem::take(&mut tx_batch));
                                }
                            }
                        }
                    }

                    if !tx_batch.is_empty() {
                        backend.send_tx(port, std::mem::take(&mut tx_batch));
                    }
                }
            });

            handles.push(handle);
        }

        for h in handles {
            let _ = h.join();
        }
    }
}

fn parse_packet_meta(data: &[u8], ingress_port: u16) -> PacketMeta {
    let mut meta = PacketMeta {
        ingress_port,
        ..Default::default()
    };

    if data.len() < 14 {
        return meta;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    meta.ethertype = ethertype;

    // IPv4
    if ethertype == 0x0800 && data.len() >= 34 {
        let ihl = (data[14] & 0x0f) as usize * 4;
        if data.len() < 14 + ihl {
            return meta;
        }

        meta.protocol = Some(data[23]);

        let src_ip = Ipv4Addr::new(data[26], data[27], data[28], data[29]);
        let dst_ip = Ipv4Addr::new(data[30], data[31], data[32], data[33]);
        meta.src_ip = Some(src_ip);
        meta.dst_ip = Some(dst_ip);

        let l4_offset = 14 + ihl;
        if data.len() >= l4_offset + 4 {
            let src_port = u16::from_be_bytes([data[l4_offset], data[l4_offset + 1]]);
            let dst_port = u16::from_be_bytes([data[l4_offset + 2], data[l4_offset + 3]]);
            meta.src_port = Some(src_port);
            meta.dst_port = Some(dst_port);
        }
    }

    meta
}

fn main() {
    let service = Service::new(DummyNicBackend, vec![0, 1]);

    service.add_rule(Rule {
        ingress_port: Some(0),
        ethertype: Some(0x0800),
        src_ip: None,
        dst_ip: None,
        protocol: Some(17), // UDP
        src_port: None,
        dst_port: Some(53),
        action: Action::Forward { port: 1 },
    });

    service.add_rule(Rule {
        ingress_port: Some(1),
        ethertype: Some(0x0800),
        src_ip: None,
        dst_ip: None,
        protocol: Some(6), // TCP
        src_port: None,
        dst_port: Some(443),
        action: Action::Forward { port: 0 },
    });

    // In production this would run forever.
    // Here it's just the service entry point.
    thread::spawn(move || {
        service.run();
    });

    loop {
        thread::sleep(Duration::from_secs(1));
    }
}
```

