use anyhow::{Context, Result};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::time::Duration;

#[derive(Debug, Clone)]
enum Action {
    Allow,
    Drop,
    ForwardTo(String), // interface name
}

#[derive(Debug, Clone)]
struct Rule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    proto: Option<u8>, // TCP=6, UDP=17
    action: Action,
}

impl Rule {
    fn matches(&self, pkt: &ParsedPacket) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != Some(port) {
                return false;
            }
        }
        if let Some(proto) = self.proto {
            if pkt.proto != Some(proto) {
                return false;
            }
        }
        true
    }
}

#[derive(Debug, Default)]
struct ParsedPacket {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    proto: Option<u8>,
}

fn parse_packet(frame: &[u8]) -> Option<ParsedPacket> {
    let eth = EthernetPacket::new(frame)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ipv4 = Ipv4Packet::new(eth.payload())?;
    let mut parsed = ParsedPacket {
        src_ip: Some(ipv4.get_source()),
        dst_ip: Some(ipv4.get_destination()),
        proto: Some(ipv4.get_next_level_protocol().0),
        ..Default::default()
    };

    match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ipv4.payload())?;
            parsed.src_port = Some(tcp.get_source());
            parsed.dst_port = Some(tcp.get_destination());
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ipv4.payload())?;
            parsed.src_port = Some(udp.get_source());
            parsed.dst_port = Some(udp.get_destination());
        }
        _ => {}
    }

    Some(parsed)
}

fn choose_action<'a>(pkt: &ParsedPacket, rules: &'a [Rule]) -> Action {
    for rule in rules {
        if rule.matches(pkt) {
            return rule.action.clone();
        }
    }
    Action::Drop
}

fn open_interface(name: &str) -> Result<NetworkInterface> {
    let interfaces = datalink::interfaces();
    interfaces
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface not found: {name}"))
}

fn open_channel(
    iface: &NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_micros(50));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;
    config.promiscuous = true;

    match datalink::channel(iface, config)? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => anyhow::bail!("unsupported channel type"),
    }
}

fn main() -> Result<()> {
    // Example policy:
    // - allow TCP to 10.0.0.10:443
    // - forward UDP from 10.0.0.20 to another interface
    let rules = vec![
        Rule {
            src_ip: None,
            dst_ip: Some(Ipv4Addr::new(10, 0, 0, 10)),
            src_port: None,
            dst_port: Some(443),
            proto: Some(6),
            action: Action::Allow,
        },
        Rule {
            src_ip: Some(Ipv4Addr::new(10, 0, 0, 20)),
            dst_ip: None,
            src_port: None,
            dst_port: None,
            proto: Some(17),
            action: Action::ForwardTo("eth1".to_string()),
        },
    ];

    let in_iface = open_interface("eth0")?;
    let out_iface = open_interface("eth1")?;

    let (_in_tx, mut in_rx) = open_channel(&in_iface)?;
    let (mut out_tx, _out_rx) = open_channel(&out_iface)?;

    println!("listening on {}", in_iface.name);
    println!("forwarding to {}", out_iface.name);

    loop {
        match in_rx.next() {
            Ok(frame) => {
                if let Some(parsed) = parse_packet(frame) {
                    match choose_action(&parsed, &rules) {
                        Action::Allow => {
                            // In this initial version, "Allow" means keep locally.
                            // You could also forward to a default route or mirror.
                        }
                        Action::Drop => {
                            // drop silently
                        }
                        Action::ForwardTo(ref iface_name) => {
                            if iface_name == &out_iface.name {
                                let _ = out_tx.send_to(frame, None);
                            }
                        }
                    }
                }
            }
            Err(_) => {
                // timeout or transient read error
                continue;
            }
        }
    }
}
