## Initial C++ implementation

```cpp
// ultra_low_latency_service.cpp
#include <arpa/inet.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <memory>
#include <thread>
#include <vector>

namespace ull {

// -----------------------------
// Packet view
// -----------------------------
struct PacketView {
    uint8_t* data;
    size_t len;
};

// -----------------------------
// Actions
// -----------------------------
enum class ActionType : uint8_t {
    DROP = 0,
    FORWARD = 1,
    MIRROR = 2
};

struct Action {
    ActionType type;
    uint16_t out_port; // interface index or queue id depending on backend
};

// -----------------------------
// Rule matching
// -----------------------------
struct Rule {
    bool has_eth_type = false;
    uint16_t eth_type = 0;

    bool has_ip_proto = false;
    uint8_t ip_proto = 0;

    bool has_src_ip = false;
    uint32_t src_ip = 0; // network byte order

    bool has_dst_ip = false;
    uint32_t dst_ip = 0; // network byte order

    bool has_src_port = false;
    uint16_t src_port = 0; // network byte order

    bool has_dst_port = false;
    uint16_t dst_port = 0; // network byte order

    Action action{ActionType::DROP, 0};
};

class RuleTable {
public:
    void set_rules(std::shared_ptr<const std::vector<Rule>> rules) {
        rules_.store(rules, std::memory_order_release);
    }

    std::shared_ptr<const std::vector<Rule>> get_rules() const {
        return rules_.load(std::memory_order_acquire);
    }

private:
    std::atomic<std::shared_ptr<const std::vector<Rule>>> rules_{std::make_shared<const std::vector<Rule>>()};
};

// -----------------------------
// Fast packet parser
// -----------------------------
struct ParsedPacket {
    bool valid = false;
    uint16_t eth_type = 0;
    uint8_t ip_proto = 0;
    uint32_t src_ip = 0;
    uint32_t dst_ip = 0;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;
};

inline ParsedPacket parse_packet(const PacketView& pkt) {
    ParsedPacket out{};
    if (pkt.len < sizeof(ethhdr)) return out;

    const ethhdr* eth = reinterpret_cast<const ethhdr*>(pkt.data);
    out.eth_type = ntohs(eth->h_proto);

    size_t offset = sizeof(ethhdr);
    if (out.eth_type != ETH_P_IP) {
        out.valid = true;
        return out;
    }

    if (pkt.len < offset + sizeof(iphdr)) return out;
    const iphdr* ip = reinterpret_cast<const iphdr*>(pkt.data + offset);

    size_t ip_hdr_len = ip->ihl * 4;
    if (pkt.len < offset + ip_hdr_len) return out;

    out.ip_proto = ip->protocol;
    out.src_ip = ip->saddr;
    out.dst_ip = ip->daddr;

    offset += ip_hdr_len;
    if (out.ip_proto == IPPROTO_TCP) {
        if (pkt.len < offset + sizeof(tcphdr)) return out;
        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(pkt.data + offset);
        out.src_port = tcp->source;
        out.dst_port = tcp->dest;
    } else if (out.ip_proto == IPPROTO_UDP) {
        if (pkt.len < offset + sizeof(udphdr)) return out;
        const udphdr* udp = reinterpret_cast<const udphdr*>(pkt.data + offset);
        out.src_port = udp->source;
        out.dst_port = udp->dest;
    }

    out.valid = true;
    return out;
}

// -----------------------------
// Rule matching
// -----------------------------
inline bool match_rule(const Rule& r, const ParsedPacket& p) {
    if (r.has_eth_type && r.eth_type != p.eth_type) return false;
    if (r.has_ip_proto && r.ip_proto != p.ip_proto) return false;
    if (r.has_src_ip && r.src_ip != p.src_ip) return false;
    if (r.has_dst_ip && r.dst_ip != p.dst_ip) return false;
    if (r.has_src_port && r.src_port != p.src_port) return false;
    if (r.has_dst_port && r.dst_port != p.dst_port) return false;
    return true;
}

inline Action classify_packet(const ParsedPacket& p, const RuleTable& table) {
    auto rules = table.get_rules();
    for (const auto& r : *rules) {
        if (match_rule(r, p)) {
            return r.action;
        }
    }
    return Action{ActionType::DROP, 0};
}

// -----------------------------
// Backend: simple socket I/O
// -----------------------------
class SocketBackend {
public:
    bool init(const std::string& ifname) {
        ifindex_ = if_nametoindex(ifname.c_str());
        if (ifindex_ == 0) {
            perror("if_nametoindex");
            return false;
        }

        rx_fd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rx_fd_ < 0) {
            perror("socket");
            return false;
        }

        sockaddr_ll sll{};
        sll.sll_family = AF_PACKET;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex_;

        if (bind(rx_fd_, reinterpret_cast<sockaddr*>(&sll), sizeof(sll)) < 0) {
            perror("bind");
            return false;
        }

        tx_fd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (tx_fd_ < 0) {
            perror("tx socket");
            return false;
        }

        return true;
    }

    ssize_t recv_packet(uint8_t* buf, size_t cap) {
        return ::recv(rx_fd_, buf, cap, 0);
    }

    bool send_packet(const uint8_t* buf, size_t len) {
        sockaddr_ll sll{};
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = ifindex_;
        sll.sll_halen = ETH_ALEN;

        return ::sendto(tx_fd_, buf, len, 0,
                        reinterpret_cast<sockaddr*>(&sll), sizeof(sll)) >= 0;
    }

    void close_all() {
        if (rx_fd_ >= 0) ::close(rx_fd_);
        if (tx_fd_ >= 0) ::close(tx_fd_);
        rx_fd_ = tx_fd_ = -1;
    }

    ~SocketBackend() { close_all(); }

private:
    int ifindex_ = 0;
    int rx_fd_ = -1;
    int tx_fd_ = -1;
};

// -----------------------------
// Service
// -----------------------------
class Service {
public:
    explicit Service(std::string ifname) : ifname_(std::move(ifname)) {}

    bool start() {
        if (!backend_.init(ifname_)) return false;
        running_.store(true, std::memory_order_release);
        worker_ = std::thread([this] { this->run(); });
        return true;
    }

    void stop() {
        running_.store(false, std::memory_order_release);
        if (worker_.joinable()) worker_.join();
    }

    void update_rules(std::shared_ptr<const std::vector<Rule>> rules) {
        rules_.set_rules(std::move(rules));
    }

private:
    void run() {
        alignas(64) std::array<uint8_t, 2048> buf{};

        while (running_.load(std::memory_order_acquire)) {
            ssize_t n = backend_.recv_packet(buf.data(), buf.size());
            if (n <= 0) continue;

            PacketView pkt{buf.data(), static_cast<size_t>(n)};
            ParsedPacket parsed = parse_packet(pkt);
            if (!parsed.valid) continue;

            Action action = classify_packet(parsed, rules_);
            switch (action.type) {
                case ActionType::DROP:
                    break;

                case ActionType::FORWARD:
                    // In this initial version, forwarding is same-interface transmit.
                    // Replace with per-port backend mapping in production.
                    backend_.send_packet(pkt.data, pkt.len);
                    break;

                case ActionType::MIRROR:
                    backend_.send_packet(pkt.data, pkt.len);
                    break;
            }
        }
    }

    std::string ifname_;
    SocketBackend backend_;
    RuleTable rules_;
    std::atomic<bool> running_{false};
    std::thread worker_;
};

} // namespace ull

// -----------------------------
// Example usage
// -----------------------------
int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    ull::Service svc(argv[1]);

    auto rules = std::make_shared<std::vector<ull::Rule>>();

    ull::Rule allow_dns;
    allow_dns.has_eth_type = true;
    allow_dns.eth_type = ETH_P_IP;
    allow_dns.has_ip_proto = true;
    allow_dns.ip_proto = IPPROTO_UDP;
    allow_dns.has_dst_port = true;
    allow_dns.dst_port = htons(53);
    allow_dns.action = {ull::ActionType::FORWARD, 0};

    rules->push_back(allow_dns);

    ull::Rule drop_all;
    drop_all.action = {ull::ActionType::DROP, 0};
    rules->push_back(drop_all);

    svc.update_rules(rules);

    if (!svc.start()) {
        std::cerr << "Failed to start service\n";
        return 1;
    }

    std::cout << "Service running. Press Ctrl+C to stop.\n";
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    svc.stop();
    return 0;
}
