use anyhow::{Context, Result};
use bytes::BytesMut;
use log::{debug, info, warn};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
struct FilterRule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    allow: bool,
}

#[derive(Clone, Debug)]
struct Config {
    rules: Vec<FilterRule>,
    forward_ifname: String,
}

#[derive(Debug)]
struct Packet {
    data: BytesMut,
}

impl Packet {
    fn new(data: &[u8]) -> Self {
        Self {
            data: BytesMut::from(data),
        }
    }

    fn len(&self) -> usize {
        self.data.len()
    }
}

fn parse_ipv4_packet(pkt: &Packet) -> Option<(Ipv4Addr, Ipv4Addr, u8, usize)> {
    // Minimal IPv4 parser:
    // Ethernet header assumed present (14 bytes)
    if pkt.len() < 14 + 20 {
        return None;
    }

    let ethertype = u16::from_be_bytes([pkt.data[12], pkt.data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_offset = 14;
    let version_ihl = pkt.data[ip_offset];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || pkt.len() < ip_offset + ihl {
        return None;
    }

    let proto = pkt.data[ip_offset + 9];
    let src = Ipv4Addr::new(
        pkt.data[ip_offset + 12],
        pkt.data[ip_offset + 13],
        pkt.data[ip_offset + 14],
        pkt.data[ip_offset + 15],
    );
    let dst = Ipv4Addr::new(
        pkt.data[ip_offset + 16],
        pkt.data[ip_offset + 17],
        pkt.data[ip_offset + 18],
        pkt.data[ip_offset + 19],
    );

    Some((src, dst, proto, ip_offset + ihl))
}

fn parse_l4_ports(pkt: &Packet, l4_offset: usize, proto: u8) -> Option<(u16, u16)> {
    if proto != 6 && proto != 17 {
        return None;
    }
    if pkt.len() < l4_offset + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt.data[l4_offset], pkt.data[l4_offset + 1]]);
    let dst_port = u16::from_be_bytes([pkt.data[l4_offset + 2], pkt.data[l4_offset + 3]]);
    Some((src_port, dst_port))
}

fn matches_rule(pkt: &Packet, rule: &FilterRule) -> bool {
    let (src_ip, dst_ip, proto, l4_offset) = match parse_ipv4_packet(pkt) {
        Some(v) => v,
        None => return false,
    };

    if let Some(rule_src) = rule.src_ip {
        if rule_src != src_ip {
            return false;
        }
    }
    if let Some(rule_dst) = rule.dst_ip {
        if rule_dst != dst_ip {
            return false;
        }
    }

    if rule.src_port.is_some() || rule.dst_port.is_some() {
        let (src_port, dst_port) = match parse_l4_ports(pkt, l4_offset, proto) {
            Some(v) => v,
            None => return false,
        };

        if let Some(rule_src_port) = rule.src_port {
            if rule_src_port != src_port {
                return false;
            }
        }
        if let Some(rule_dst_port) = rule.dst_port {
            if rule_dst_port != dst_port {
                return false;
            }
        }
    }

    true
}

fn should_allow(pkt: &Packet, cfg: &Config) -> bool {
    for rule in &cfg.rules {
        if matches_rule(pkt, rule) {
            return rule.allow;
        }
    }
    false
}

struct FastPath {
    cfg: Arc<Config>,
}

impl FastPath {
    fn new(cfg: Arc<Config>) -> Self {
