use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub struct EthernetFrame<'a> {
    pub dst_mac: [u8; 6],
    pub src_mac: [u8; 6],
    pub ethertype: u16,
    pub payload: &'a [u8],
}

#[derive(Debug, Clone)]
pub struct Ipv4Packet<'a> {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
    pub payload: &'a [u8],
}

pub fn parse_ethernet(frame: &[u8]) -> Option<EthernetFrame<'_>> {
    if frame.len() < 14 {
        return None;
    }

    let mut dst = [0u8; 6];
    let mut src = [0u8; 6];
    dst.copy_from_slice(&frame[0..6]);
    src.copy_from_slice(&frame[6..12]);

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    Some(EthernetFrame {
        dst_mac: dst,
        src_mac: src,
        ethertype,
        payload: &frame[14..],
    })
}

pub fn parse_ipv4(payload: &[u8]) -> Option<Ipv4Packet<'_>> {
    if payload.len() < 20 {
        return None;
    }

    let version_ihl = payload[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || payload.len() < ihl || ihl < 20 {
        return None;
    }

    let protocol = payload[9];
    let src = Ipv4Addr::new(payload[12], payload[13], payload[14], payload[15]);
    let dst = Ipv4Addr::new(payload[16], payload[17], payload[18], payload[19]);

    Some(Ipv4Packet {
        src,
        dst,
        protocol,
        payload: &payload[ihl..],
    })
}
