use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Action {
    Forward,
    Drop,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FilterRule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub protocol: Option<u8>, // 6=TCP, 17=UDP
    pub action: Action,
}

#[derive(Debug, Default)]
pub struct FilterEngine {
    rules: Vec<FilterRule>,
}

impl FilterEngine {
    pub fn new() -> Self {
        Self { rules: Vec::new() }
    }

    pub fn set_rules(&mut self, rules: Vec<FilterRule>) {
        self.rules = rules;
    }

    pub fn rules(&self) -> &[FilterRule] {
        &self.rules
    }

    pub fn decide(&self, src_ip: Option<Ipv4Addr>, dst_ip: Option<Ipv4Addr>, protocol: Option<u8>) -> Action {
        for rule in &self.rules {
            if let Some(rule_src) = rule.src_ip {
                if Some(rule_src) != src_ip {
                    continue;
                }
            }
            if let Some(rule_dst) = rule.dst_ip {
                if Some(rule_dst) != dst_ip {
                    continue;
                }
            }
            if let Some(rule_proto) = rule.protocol {
                if Some(rule_proto) != protocol {
                    continue;
                }
            }
            return rule.action.clone();
        }

        Action::Drop
    }
}
