## `src/forward.rs`

```rust
use anyhow::{Context, Result};
use libc::{c_int, sockaddr_ll, AF_PACKET, ETH_P_ALL, SOCK_RAW};
use std::io;
use std::mem;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd, RawFd};

pub struct PacketSocket {
    fd: OwnedFd,
}

impl PacketSocket {
    pub fn open() -> Result<Self> {
        let proto = (ETH_P_ALL as u16).to_be() as c_int;
        let fd = unsafe {
            libc::socket(AF_PACKET, SOCK_RAW, proto)
        };
        if fd < 0 {
            return Err(io::Error::last_os_error()).context("socket(AF_PACKET) failed");
        }

        let fd = unsafe { OwnedFd::from_raw_fd(fd) };
        Ok(Self { fd })
    }

    pub fn bind_to_interface(&self, ifindex: i32) -> Result<()> {
        let mut addr: sockaddr_ll = unsafe { mem::zeroed() };
        addr.sll_family = AF_PACKET as u16;
        addr.sll_protocol = (ETH_P_ALL as u16).to_be();
        addr.sll_ifindex = ifindex;

        let ret = unsafe {
            libc::bind(
                self.fd.as_raw_fd(),
                &addr as *const sockaddr_ll as *const libc::sockaddr,
                mem::size_of::<sockaddr_ll>() as libc::socklen_t,
            )
        };
        if ret < 0 {
            return Err(io::Error::last_os_error()).context("bind(AF_PACKET) failed");
        }
        Ok(())
    }

    pub fn recv(&self, buf: &mut [u8]) -> Result<usize> {
        let n = unsafe {
            libc::recv(self.fd.as_raw_fd(), buf.as_mut_ptr() as *mut _, buf.len(), 0)
        };
        if n < 0 {
            return Err(io::Error::last_os_error()).context("recv failed");
        }
        Ok(n as usize)
    }

    pub fn send(&self, buf: &[u8]) -> Result<usize> {
        let n = unsafe {
            libc::send(self.fd.as_raw_fd(), buf.as_ptr() as *const _, buf.len(), 0)
        };
        if n < 0 {
            return Err(io::Error::last_os_error()).context("send failed");
        }
        Ok(n as usize)
    }

    pub fn fd(&self) -> RawFd {
        self.fd.as_raw_fd()
    }
}
