```rust
use crate::filter::{FilterEngine, FilterRule};
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper::server::conn::http1;
use hyper::body::Body;
use parking_lot::RwLock;
use serde_json::json;
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::TcpListener;

pub async fn run_control_server(
    addr: SocketAddr,
    filters: Arc<RwLock<FilterEngine>>,
) -> anyhow::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    loop {
        let (stream, _) = listener.accept().await?;
        let filters = filters.clone();

        tokio::spawn(async move {
            let service = service_fn(move |req| {
                let filters = filters.clone();
                async move { handle(req, filters).await }
            });

            if let Err(err) = http1::Builder::new().serve_connection(stream, service).await {
                eprintln!("control connection error: {err}");
            }
        });
    }
}

async fn handle(
    req: Request<Incoming>,
    filters: Arc<RwLock<FilterEngine>>,
) -> Result<Response<Body>, Infallible> {
    let resp = match (req.method(), req.uri().path()) {
        (&Method::GET, "/rules") => {
            let rules = filters.read().rules().to_vec();
            json_response(&rules)
        }
        (&Method::POST, "/rules") => {
            let bytes = hyper::body::to_bytes(req.into_body()).await.unwrap_or_default();
            match serde_json::from_slice::<Vec<FilterRule>>(&bytes) {
                Ok(rules) => {
                    filters.write().set_rules(rules);
                    json_response(&json!({"status": "ok"}))
                }
                Err(e) => response(StatusCode::BAD_REQUEST, format!("invalid rules: {e}")),
            }
        }
        _ => response(StatusCode::NOT_FOUND, "not found"),
    };

    Ok(resp)
}

fn json_response<T: serde::Serialize>(value: &T) -> Response<Body> {
    let body = serde_json::to_vec(value).unwrap_or_else(|_| b"{}".to_vec());
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "application/json")
        .body(Body::from(body))
        .unwrap()
}

fn response(status: StatusCode, msg: impl Into<String>) -> Response<Body> {
    Response::builder()
        .status(status)
        .body(Body::from(msg.into()))
        .unwrap()
}
