}

fn main() -> Result<()> {
    // Example initial rules:
    // Forward TCP packets from 10.0.0.10, drop everything else.
    let filters = Arc::new(RwLock::new(FilterEngine::new()));
    {
        let mut f = filters.write();
        f.set_rules(vec![
            FilterRule {
                src_ip: Some("10.0.0.10".parse().unwrap()),
                dst_ip: None,
                protocol: Some(6),
                action: Action::Forward,
            },
        ]);
    }

    let control_filters = filters.clone();
    thread::spawn(move || {
        let rt = tokio::runtime::Runtime::new().unwrap();
        rt.block_on(async move {
            let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
            if let Err(e) = control::run_control_server(addr, control_filters).await {
                eprintln!("control server error: {e}");
            }
        });
    });

    let in_if = std::env::var("IN_IF").unwrap_or_else(|_| "eth0".to_string());
    let out_if = std::env::var("OUT_IF").unwrap_or_else(|_| "eth1".to_string());

    let in_idx = interface_index(&in_if)?;
    let out_idx = interface_index(&out_if)?;

    let rx = PacketSocket::open()?;
    rx.bind_to_interface(in_idx)?;

    let tx = PacketSocket::open()?;
    tx.bind_to_interface(out_idx)?;

    let mut buf = vec![0u8; 65536];

    loop {
        let n = rx.recv(&mut buf)?;
        let frame = &buf[..n];

        if let Some(eth) = parse_ethernet(frame) {
            if eth.ethertype == 0x0800 {
                if let Some(ipv4) = parse_ipv4(eth.payload) {
                    let action = {
                        let f = filters.read();
                        f.decide(Some(ipv4.src), Some(ipv4.dst), Some(ipv4.protocol))
                    };

                    match action {
                        Action::Forward => {
                            let _ = tx.send(frame)?;
                        }
                        Action::Drop => {}
                    }
                }
            }
        }
    }
}
