use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Action {
    Allow,
    Drop,
    Forward { iface: String },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<u8>, // 6 = TCP, 17 = UDP
    pub action: Action,
}

impl Rule {
    pub fn matches(
        &self,
        src_ip: Option<Ipv4Addr>,
        dst_ip: Option<Ipv4Addr>,
        src_port: Option<u16>,
        dst_port: Option<u16>,
        proto: Option<u8>,
    ) -> bool {
        self.src_ip.map_or(true, |ip| Some(ip) == src_ip)
            && self.dst_ip.map_or(true, |ip| Some(ip) == dst_ip)
            && self.src_port.map_or(true, |p| Some(p) == src_port)
            && self.dst_port.map_or(true, |p| Some(p) == dst_port)
            && self.proto.map_or(true, |p| Some(p) == proto)
    }
}

#[derive(Debug, Clone)]
pub struct RuleSet {
    pub rules: Vec<Rule>,
}

impl RuleSet {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn decide(
        &self,
        src_ip: Option<Ipv4Addr>,
        dst_ip: Option<Ipv4Addr>,
        src_port: Option<u16>,
        dst_port: Option<u16>,
        proto: Option<u8>,
    ) -> Action {
        for rule in &self.rules {
            if rule.matches(src_ip, dst_ip, src_port, dst_port, proto) {
                return rule.action.clone();
            }
        }
        Action::Drop
    }
}
