## `src/packet.rs`

```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub struct PacketMeta {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<u8>,
}

pub fn parse_ipv4_transport(packet: &[u8]) -> Option<PacketMeta> {
    if packet.len() < 34 {
        return None;
    }

    // Ethernet type at bytes 12..14
    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only for now
    }

    let ip_start = 14;
    let version_ihl = packet[ip_start];
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if packet.len() < ip_start + ihl {
        return None;
    }

    let proto = packet[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        packet[ip_start + 12],
        packet[ip_start + 13],
        packet[ip_start + 14],
        packet[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        packet[ip_start + 16],
        packet[ip_start + 17],
        packet[ip_start + 18],
        packet[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    let (src_port, dst_port) = match proto {
        6 | 17 => {
            if packet.len() < l4_start + 4 {
                return Some(PacketMeta {
                    src_ip: Some(src_ip),
                    dst_ip: Some(dst_ip),
                    src_port: None,
                    dst_port: None,
                    proto: Some(proto),
                });
            }
            let sp = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
            let dp = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);
            (Some(sp), Some(dp))
        }
        _ => (None, None),
    };

    Some(PacketMeta {
        src_ip: Some(src_ip),
        dst_ip: Some(dst_ip),
        src_port,
        dst_port,
        proto: Some(proto),
    })
}
