use anyhow::Result;
use pnet::datalink::{self, Channel::Ethernet, DataLinkSender};

pub struct Forwarder {
    tx: Box<dyn DataLinkSender>,
}

impl Forwarder {
    pub fn new(interface_name: &str) -> Result<Self> {
        let interfaces = datalink::interfaces();
        let interface = interfaces
            .into_iter()
            .find(|iface| iface.name == interface_name)
            .ok_or_else(|| anyhow::anyhow!("interface not found: {}", interface_name))?;

        let config = datalink::Config::default();
        let (_, tx) = match datalink::channel(&interface, config)? {
            Ethernet(tx, rx) => {
                drop(rx);
                ((), tx)
            }
            _ => return Err(anyhow::anyhow!("unsupported channel type")),
        };

        Ok(Self { tx })
    }

    pub fn send(&mut self, packet: &[u8]) -> Result<()> {
        match self.tx.send_to(packet, None) {
            Some(Ok(())) => Ok(()),
            Some(Err(e)) => Err(e.into()),
            None => Err(anyhow::anyhow!("failed to send packet")),
        }
    }
}
