use anyhow::Result;
use pnet::datalink::{self, Channel::Ethernet};
use rules::{Action, Rule, RuleSet};
use stats::Stats;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn main() -> Result<()> {
    let iface_name = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == iface_name)
        .ok_or_else(|| anyhow::anyhow!("interface not found: {}", iface_name))?;

    let config = datalink::Config {
        read_timeout: Some(Duration::from_millis(10)),
        ..Default::default()
    };

    let (mut tx, mut rx) = match datalink::channel(&interface, config)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => return Err(anyhow::anyhow!("unsupported channel type")),
    };

    let rules = RuleSet::new(vec![
        Rule {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(443),
            proto: Some(6),
            action: Action::Allow,
        },
        Rule {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(53),
            proto: Some(17),
            action: Action::Allow,
        },
        Rule {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            proto: None,
            action: Action::Drop,
        },
    ]);

    let stats = Arc::new(Stats::new());
    let stats_printer = Arc::clone(&stats);

    thread::spawn(move || loop {
        let (r, a, d, f) = stats_printer.snapshot();
        eprintln!("stats: recv={} allow={} drop={} fwd={}", r, a, d, f);
        thread::sleep(Duration::from_secs(2));
    });

    loop {
        match rx.next() {
            Ok(packet) => {
                stats.received.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

                if let Some(meta) = packet::parse_ipv4_transport(packet) {
                    match rules.decide(
                        meta.src_ip,
                        meta.dst_ip,
                        meta.src_port,
                        meta.dst_port,
                        meta.proto,
                    ) {
                        Action::Allow => {
                            stats.allowed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            // Fast path: forward unchanged packet back out same interface.
                            // Replace with policy-based egress selection as needed.
                            match tx.send_to(packet, None) {
                                Some(Ok(())) => {
                                    stats.forwarded.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                }
                                _ => {
                                    stats.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                }
                            }
                        }
                        Action::Drop => {
                            stats.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                        Action::Forward { iface: _ } => {
                            // Hook for multi-interface forwarding.
                            // In a real implementation, map iface -> tx handle.
                            stats.forwarded.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                    }
                } else {
                    stats.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
            Err(_) => {
                // Timeout or transient read error
                continue;
            }
        }
    }
}
