## `main.cpp`

```cpp
#include <iostream>
#include <vector>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <unordered_map>

extern "C" {
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_udp.h>
#include <rte_tcp.h>
#include <rte_ether.h>
#include <rte_cycles.h>
}

static constexpr uint16_t BURST_SIZE = 32;
static constexpr uint16_t NB_MBUFS = 8191;
static constexpr uint16_t MBUF_CACHE_SIZE = 256;
static constexpr uint16_t RSS_QUEUE_COUNT = 1;

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    std::size_t operator()(const FlowKey& k) const {
        std::size_t h = 0;
        h ^= std::hash<uint32_t>{}(k.src_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint32_t>{}(k.dst_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.src_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.dst_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint8_t>{}(k.proto) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

enum class Action : uint8_t {
    DROP = 0,
    FORWARD = 1
};

struct Rule {
    // Very simple rule model: exact match on 5-tuple with wildcard support via bool flags
    bool match_src_ip = false;
    bool match_dst_ip = false;
    bool match_src_port = false;
    bool match_dst_port = false;
    bool match_proto = false;

    uint32_t src_ip = 0;
    uint32_t dst_ip = 0;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;
    uint8_t  proto = 0;

    Action action = Action::DROP;
    uint16_t forward_port = 0;
};

struct PortStats {
    std::atomic<uint64_t> rx_pkts{0};
    std::atomic<uint64_t> tx_pkts{0};
    std::atomic<uint64_t> dropped{0};
};

static PortStats g_stats[RTE_MAX_ETHPORTS];

static inline bool parse_ipv4_5tuple(struct rte_mbuf* m, FlowKey& key) {
    auto* eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr*);
    if (unlikely(rte_be_to_cpu_16(eth->ether_type) != RTE_ETHER_TYPE_IPV4)) {
        return false;
    }

    auto* ip = (struct rte_ipv4_hdr*)(eth + 1);
    key.src_ip = ip->src_addr;
    key.dst_ip = ip->dst_addr;
    key.proto = ip->next_proto_id;

    uint16_t ip_hdr_len = (ip->version_ihl & 0x0f) * 4;
    uint8_t* l4 = (uint8_t*)ip + ip_hdr_len;

    if (key.proto == IPPROTO_TCP) {
        auto* tcp = (struct rte_tcp_hdr*)l4;
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
        return true;
    } else if (key.proto == IPPROTO_UDP) {
        auto* udp = (struct rte_udp_hdr*)l4;
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
        return true;
    }

    key.src_port = 0;
    key.dst_port = 0;
    return true;
}

class FilterEngine {
public:
    void add_rule(const Rule& rule) {
        rules_.push_back(rule);
    }

    Action evaluate(const FlowKey& key, uint16_t& out_port) const {
        for (const auto& r : rules_) {
            if (r.match_src_ip && r.src_ip != key.src_ip) continue;
            if (r.match_dst_ip && r.dst_ip != key.dst_ip) continue;
            if (r.match_src_port && r.src_port != key.src_port) continue;
            if (r.match_dst_port && r.dst_port != key.dst_port) continue;
            if (r.match_proto && r.proto != key.proto) continue;

            out_port = r.forward_port;
            return r.action;
        }

        // Default policy: drop
        return Action::DROP;
    }

private:
    std::vector<Rule> rules_;
};

class Forwarder {
public:
    explicit Forwarder(FilterEngine& fe) : filter_(fe) {}

    void process_port(uint16_t port_id) {
        rte_mbuf* bufs[BURST_SIZE];
        const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, bufs, BURST_SIZE);
        if (nb_rx == 0) return;

        g_stats[port_id].rx_pkts.fetch_add(nb_rx, std::memory_order_relaxed);

        rte_mbuf* tx_bufs[BURST_SIZE];
        uint16_t tx_count = 0;

        for (uint16_t i = 0; i < nb_rx; ++i) {
            rte_mbuf* m = bufs[i];
            FlowKey key{};
            uint16_t out_port = 0;

            if (!parse_ipv4_5tuple(m, key)) {
                g_stats[port_id].dropped.fetch_add(1, std::memory_order_relaxed);
                rte_pktmbuf_free(m);
                continue;
            }

            Action action = filter_.evaluate(key, out_port);
            if (action == Action::FORWARD && out_port < RTE_MAX_ETHPORTS) {
                // Rewrite MACs or other headers here if needed
                tx_bufs[tx_count++] = m;

                // Flush if burst full
                if (tx_count == BURST_SIZE) {
                    send_burst(out_port, tx_bufs, tx_count);
                    tx_count = 0;
                }
            } else {
                g_stats[port_id].dropped.fetch_add(1, std::memory_order_relaxed);
                rte_pktmbuf_free(m);
            }
        }

        // Note: this simple version assumes same out_port per burst flush path.
        // A real implementation should batch per destination port.
        if (tx_count > 0) {
            // For now, forward remaining packets to the last observed port is NOT safe.
            // This is intentionally left as a placeholder for a proper per-port queue.
            for (uint16_t i = 0; i < tx_count; ++i) {
                rte_pktmbuf_free(tx_bufs[i]);
            }
        }
    }

private:
    void send_burst(uint16_t out_port, rte_mbuf** bufs, uint16_t count) {
        uint16_t nb_tx = rte_eth_tx_burst(out_port, 0, bufs, count);
        g_stats[out_port].tx_pkts.fetch_add(nb_tx, std::memory_order_relaxed);

        for (uint16_t i = nb_tx; i < count; ++i) {
            rte_pktmbuf_free(bufs[i]);
        }
    }

    FilterEngine& filter_;
};

static int init_port(uint16_t port_id, rte_mempool* mbuf_pool) {
    rte_eth_conf port_conf{};
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;

    const uint16_t rx_rings = 1;
    const uint16_t tx_rings = 1;

    int ret = rte_eth_dev_configure(port_id, rx_rings, tx_rings, &port_conf);
    if (ret < 0) return ret;

    ret = rte_eth_rx_queue_setup(port_id, 0, 1024, rte_eth_dev_socket_id(port_id), nullptr, mbuf_pool);
    if (ret < 0) return ret;

    ret = rte_eth_tx_queue_setup(port_id, 0, 1024, rte_eth_dev_socket_id(port_id), nullptr);
    if (ret < 0) return ret;

    ret = rte_eth_dev_start(port_id);
    if (ret < 0) return ret;

    rte_eth_promiscuous_enable(port_id);
    return 0;
}

int main(int argc, char* argv[]) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        std::cerr << "Failed to initialize EAL\n";
        return 1;
    }

    argc -= ret;
    argv += ret;

    rte_mempool* mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL",
        NB_MBUFS,
        MBUF_CACHE_SIZE,
        0,
        RTE_MBUF_DEFAULT_BUF_SIZE,
        rte_socket_id()
    );

    if (mbuf_pool == nullptr) {
        std::cerr << "Failed to create mbuf pool\n";
        return 1;
    }

    uint16_t nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 1) {
        std::cerr << "No available Ethernet ports\n";
        return 1;
    }

    for (uint16_t port = 0; port < nb_ports; ++port) {
        if (init_port(port, mbuf_pool) < 0) {
            std::cerr << "Failed to init port " << port << "\n";
            return 1;
        }
    }

    FilterEngine filter;

    // Example rule: forward TCP traffic to port 1 if destination port is 443
    Rule r1;
    r1.match_proto = true;
    r1.proto = IPPROTO_TCP;
    r1.match_dst_port = true;
    r1.dst_port = rte_cpu_to_be_16(443);
    r1.action = Action::FORWARD;
    r1.forward_port = (nb_ports > 1) ? 1 : 0;
    filter.add_rule(r1);

    // Example rule: drop UDP/53
    Rule r2;
    r2.match_proto = true;
    r2.proto = IPPROTO_UDP;
    r2.match_dst_port = true;
    r2.dst_port = rte_cpu_to_be_16(53);
    r2.action = Action::DROP;
    filter.add_rule(r2);

    Forwarder forwarder(filter);

    std::cout << "Starting packet processing loop...\n";

    while (true) {
        for (uint16_t port = 0; port < nb_ports; ++port) {
            forwarder.process_port(port);
        }
    }

    return 0;
}
```

