## `src/packet.rs`

```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Proto {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone)]
pub struct ParsedPacket<'a> {
    pub ethertype: u16,
    pub l4_proto: Option<L4Proto>,
    pub src_ip: Option<[u8; 16]>,
    pub dst_ip: Option<[u8; 16]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub payload: &'a [u8],
}

pub fn parse_packet(data: &[u8]) -> Option<ParsedPacket<'_>> {
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    let mut offset = 14;

    match ethertype {
        0x0800 => parse_ipv4(data, offset, ethertype),
        0x86DD => parse_ipv6(data, offset, ethertype),
        _ => Some(ParsedPacket {
            ethertype,
            l4_proto: None,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            payload: &data[offset..],
        }),
    }
}

fn parse_ipv4(data: &[u8], offset: usize, ethertype: u16) -> Option<ParsedPacket<'_>> {
    if data.len() < offset + 20 {
        return None;
    }

    let ihl = (data[offset] & 0x0f) as usize * 4;
    if ihl < 20 || data.len() < offset + ihl {
        return None;
    }

    let proto = data[offset + 9];
    let src_ip = [data[offset + 12], data[offset + 13], data[offset + 14], data[offset + 15]];
    let dst_ip = [data[offset + 16], data[offset + 17], data[offset + 18], data[offset + 19]];

    let l4_offset = offset + ihl;
    let (l4_proto, src_port, dst_port) = parse_l4(proto, data, l4_offset)?;

    Some(ParsedPacket {
        ethertype,
        l4_proto: Some(l4_proto),
        src_ip: Some(v4_to_v6(src_ip)),
        dst_ip: Some(v4_to_v6(dst_ip)),
        src_port,
        dst_port,
        payload: &data[l4_offset..],
    })
}

fn parse_ipv6(data: &[u8], offset: usize, ethertype: u16) -> Option<ParsedPacket<'_>> {
    if data.len() < offset + 40 {
        return None;
    }

    let next_header = data[offset + 6];
    let src_ip = {
        let mut a = [0u8; 16];
        a.copy_from_slice(&data[offset + 8..offset + 24]);
        a
    };
    let dst_ip = {
        let mut a = [0u8; 16];
        a.copy_from_slice(&data[offset + 24..offset + 40]);
        a
    };

    let l4_offset = offset + 40;
    let (l4_proto, src_port, dst_port) = parse_l4(next_header, data, l4_offset)?;

    Some(ParsedPacket {
        ethertype,
        l4_proto: Some(l4_proto),
        src_ip: Some(src_ip),
        dst_ip: Some(dst_ip),
        src_port,
        dst_port,
        payload: &data[l4_offset..],
    })
}

fn parse_l4(proto: u8, data: &[u8], offset: usize) -> Option<(L4Proto, Option<u16>, Option<u16>)> {
    match proto {
        6 => {
            if data.len() < offset + 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([data[offset], data[offset + 1]]);
            let dst_port = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
            Some((L4Proto::Tcp, Some(src_port), Some(dst_port)))
        }
        17 => {
            if data.len() < offset + 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([data[offset], data[offset + 1]]);
            let dst_port = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
            Some((L4Proto::Udp, Some(src_port), Some(dst_port)))
        }
        1 => Some((L4Proto::Icmp, None, None)),
        other => Some((L4Proto::Other(other), None, None)),
    }
}

fn v4_to_v6(v4: [u8; 4]) -> [u8; 16] {
    let mut out = [0u8; 16];
    out[10] = 0xff;
    out[11] = 0xff;
    out[12..16].copy_from_slice(&v4);
    out
}
