## `src/rules.rs`

```rust
use crate::config::{ActionConfig, ProtoConfig, RuleConfig};
use crate::packet::{L4Proto, ParsedPacket};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Drop,
    Forward,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub proto: Option<ProtoConfig>,
    pub src_ip: Option<[u8; 16]>,
    pub dst_ip: Option<[u8; 16]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl Rule {
    pub fn matches(&self, pkt: &ParsedPacket<'_>) -> bool {
        if let Some(proto) = &self.proto {
            if !proto_matches(proto, pkt.l4_proto) {
                return false;
            }
        }

        if let Some(src_ip) = self.src_ip {
            if pkt.src_ip != Some(src_ip) {
                return false;
            }
        }

        if let Some(dst_ip) = self.dst_ip {
            if pkt.dst_ip != Some(dst_ip) {
                return false;
            }
        }

        if let Some(src_port) = self.src_port {
            if pkt.src_port != Some(src_port) {
                return false;
            }
        }

        if let Some(dst_port) = self.dst_port {
            if pkt.dst_port != Some(dst_port) {
                return false;
            }
        }

        true
    }
}

pub fn compile_rules(configs: &[RuleConfig]) -> Vec<Rule> {
    configs
        .iter()
        .map(|r| Rule {
            action: match r.action {
                ActionConfig::Drop => Action::Drop,
                ActionConfig::Forward => Action::Forward,
            },
            proto: r.proto.clone(),
            src_ip: r.src_ip.as_deref().and_then(parse_ip),
            dst_ip: r.dst_ip.as_deref().and_then(parse_ip),
            src_port: r.src_port,
            dst_port: r.dst_port,
        })
        .collect()
}

fn proto_matches(proto_cfg: &ProtoConfig, pkt_proto: Option<L4Proto>) -> bool {
    match (proto_cfg, pkt_proto) {
        (ProtoConfig::Any, _) => true,
        (ProtoConfig::Tcp, Some(L4Proto::Tcp)) => true,
        (ProtoConfig::Udp, Some(L4Proto::Udp)) => true,
        (ProtoConfig::Icmp, Some(L4Proto::Icmp)) => true,
        _ => false,
    }
}

fn parse_ip(s: &str) -> Option<[u8; 16]> {
    if let Ok(v4) = s.parse::<std::net::Ipv4Addr>() {
        let mut out = [0u8; 16];
        out[10] = 0xff;
        out[11] = 0xff;
        out[12..16].copy_from_slice(&v4.octets());
        return Some(out);
    }

    if let Ok(v6) = s.parse::<std::net::Ipv6Addr>() {
        return Some(v6.octets());
    }

    None
}
