fn build_demo_ipv4_udp_packet() -> Vec<u8> {
    let mut p = vec![0u8; 14 + 20 + 8];

    p[12] = 0x08;
    p[13] = 0x00;

    let ip = 14;
    p[ip] = 0x45;
    p[ip + 9] = 17;
    p[ip + 12..ip + 16].copy_from_slice(&[192, 168, 1, 10]);
    p[ip + 16..ip + 20].copy_from_slice(&[8, 8, 8, 8]);

    let udp = 14 + 20;
    p[udp..udp + 2].copy_from_slice(&12345u16.to_be_bytes());
    p[udp + 2..udp + 4].copy_from_slice(&53u16.to_be_bytes());

    p
}
