```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub protocol: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

pub fn parse_packet(buf: &[u8]) -> Option<PacketMeta> {
    if buf.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    if ethertype != 0x0800 {
        return Some(PacketMeta {
            src_ip: None,
            dst_ip: None,
            protocol: None,
            src_port: None,
            dst_port: None,
        });
    }

    let ip_offset = 14;
    if buf.len() < ip_offset + 20 {
        return None;
    }

    let version_ihl = buf[ip_offset];
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if ihl < 20 || buf.len() < ip_offset + ihl {
        return None;
    }

    let protocol_num = buf[ip_offset + 9];
    let src_ip = Ipv4Addr::new(
        buf[ip_offset + 12],
        buf[ip_offset + 13],
        buf[ip_offset + 14],
        buf[ip_offset + 15],
    );
    let dst_ip = Ipv4Addr::new(
        buf[ip_offset + 16],
        buf[ip_offset + 17],
        buf[ip_offset + 18],
        buf[ip_offset + 19],
    );

    let protocol = match protocol_num {
        6 => L4Protocol::Tcp,
        17 => L4Protocol::Udp,
        1 => L4Protocol::Icmp,
        x => L4Protocol::Other(x),
    };

    let l4_offset = ip_offset + ihl;
    let (src_port, dst_port) = match protocol {
        L4Protocol::Tcp | L4Protocol::Udp => {
            if buf.len() < l4_offset + 4 {
                return None;
            }
            let sp = u16::from_be_bytes([buf[l4_offset], buf[l4_offset + 1]]);
            let dp = u16::from_be_bytes([buf[l4_offset + 2], buf[l4_offset + 3]]);
            (Some(sp), Some(dp))
        }
        _ => (None, None),
    };

    Some(PacketMeta {
        src_ip: Some(src_ip),
        dst_ip: Some(dst_ip),
        protocol: Some(protocol),
        src_port,
        dst_port,
    })
}
```

