## src/filter.rs

```rust
use std::net::Ipv4Addr;

use crate::config::{Action, Protocol, RuleConfig};
use crate::packet::{L4Protocol, PacketMeta};

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub protocol: Option<Protocol>,
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

#[derive(Debug, Clone)]
pub struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    pub fn new(rule_configs: &[RuleConfig]) -> anyhow::Result<Self> {
        let mut rules = Vec::with_capacity(rule_configs.len());

        for r in rule_configs {
            rules.push(Rule {
                action: r.action.clone(),
                protocol: r.protocol.clone(),
                src_ip: parse_ip_opt(r.src_ip.as_deref())?,
                dst_ip: parse_ip_opt(r.dst_ip.as_deref())?,
                src_port: r.src_port,
                dst_port: r.dst_port,
            });
        }

        Ok(Self { rules })
    }

    pub fn allow_packet(&self, pkt: &PacketMeta) -> bool {
        for rule in &self.rules {
            if rule_matches(rule, pkt) {
                return matches!(rule.action, Action::Allow);
            }
        }
        true
    }
}

fn rule_matches(rule: &Rule, pkt: &PacketMeta) -> bool {
    if let Some(ref p) = rule.protocol {
        let ok = match (p, pkt.protocol) {
            (Protocol::Tcp, Some(L4Protocol::Tcp)) => true,
            (Protocol::Udp, Some(L4Protocol::Udp)) => true,
            (Protocol::Icmp, Some(L4Protocol::Icmp)) => true,
            _ => false,
        };
        if !ok {
            return false;
        }
    }

    if let Some(src_ip) = rule.src_ip {
        if pkt.src_ip != Some(src_ip) {
            return false;
        }
    }

    if let Some(dst_ip) = rule.dst_ip {
        if pkt.dst_ip != Some(dst_ip) {
            return false;
        }
    }

    if let Some(src_port) = rule.src_port {
        if pkt.src_port != Some(src_port) {
            return false;
        }
    }

    if let Some(dst_port) = rule.dst_port {
        if pkt.dst_port != Some(dst_port) {
            return false;
        }
    }

    true
}

fn parse_ip_opt(s: Option<&str>) -> anyhow::Result<Option<Ipv4Addr>> {
    match s {
        Some(v) => Ok(Some(v.parse()?)),
        None => Ok(None),
    }
}
