## src/runtime.rs

```rust
use std::sync::Arc;
use std::thread;

use crate::filter::FilterEngine;
use crate::forward::{Forwarder, PacketTx};
use crate::packet::parse_packet;

pub trait PacketRx: Send + 'static {
    fn recv(&mut self, buf: &mut [u8]) -> anyhow::Result<usize>;
}

pub struct Runtime<RX, TX>
where
    RX: PacketRx,
    TX: PacketTx,
{
    rx: RX,
    forwarder: Forwarder<TX>,
    filter: Arc<FilterEngine>,
}

impl<RX, TX> Runtime<RX, TX>
where
    RX: PacketRx,
    TX: PacketTx,
{
    pub fn new(rx: RX, tx: TX, filter: FilterEngine) -> Self {
        Self {
            rx,
            forwarder: Forwarder::new(tx),
            filter: Arc::new(filter),
        }
    }

    pub fn run(mut self) -> anyhow::Result<()> {
        let filter = self.filter.clone();
        let forwarder = self.forwarder.clone();

        let handle = thread::spawn(move || -> anyhow::Result<()> {
            let mut buf = vec![0u8; 2048];

            loop {
                let n = self.rx.recv(&mut buf)?;
                if n == 0 {
                    continue;
                }

                let pkt = &buf[..n];
                if let Some(meta) = parse_packet(pkt) {
                    if filter.allow_packet(&meta) {
                        forwarder.forward(pkt)?;
                    }
                }
            }
        });

        handle.join().expect("runtime thread panicked")
    }
}
