use anyhow::{Context, Result};
use pnet::datalink::{self, Channel::Ethernet, Config};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::IpAddr;
use std::time::Instant;

#[derive(Clone, Debug)]
enum Protocol {
    Tcp,
    Udp,
    Any,
}

#[derive(Clone, Debug)]
struct Rule {
    src_ip: Option<IpAddr>,
    dst_ip: Option<IpAddr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Protocol,
    allow: bool,
}

impl Rule {
    fn matches(&self, pkt: &ParsedPacket) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != Some(port) {
                return false;
            }
        }

        match self.protocol {
            Protocol::Any => true,
            Protocol::Tcp => pkt.protocol == Some("tcp"),
            Protocol::Udp => pkt.protocol == Some("udp"),
        }
    }
}

#[derive(Debug)]
struct ParsedPacket {
    src_ip: Option<IpAddr>,
    dst_ip: Option<IpAddr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Option<&'static str>,
}

fn parse_packet(frame: &[u8]) -> Option<ParsedPacket> {
    let eth = EthernetPacket::new(frame)?;
    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ipv4 = Ipv4Packet::new(eth.payload())?;
            let src_ip = IpAddr::V4(ipv4.get_source());
            let dst_ip = IpAddr::V4(ipv4.get_destination());

            match ipv4.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ipv4.payload())?;
                    Some(ParsedPacket {
                        src_ip: Some(src_ip),
                        dst_ip: Some(dst_ip),
                        src_port: Some(tcp.get_source()),
                        dst_port: Some(tcp.get_destination()),
                        protocol: Some("tcp"),
                    })
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ipv4.payload())?;
                    Some(ParsedPacket {
                        src_ip: Some(src_ip),
                        dst_ip: Some(dst_ip),
                        src_port: Some(udp.get_source()),
                        dst_port: Some(udp.get_destination()),
                        protocol: Some("udp"),
                    })
                }
                _ => Some(ParsedPacket {
                    src_ip: Some(src_ip),
                    dst_ip: Some(dst_ip),
                    src_port: None,
                    dst_port: None,
                    protocol: Some("other"),
                }),
            }
        }
        _ => None,
    }
}

fn main() -> Result<()> {
    let interface_name = std::env::args()
        .nth(1)
        .context("usage: ultra_low_latency_net <interface>")?;

    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == interface_name)
        .context("interface not found")?;

    let mut config = Config::default();
    config.read_timeout = Some(std::time::Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;

    let (mut tx, mut rx) = match datalink::channel(&interface, config)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    let rules = vec![
        Rule {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(443),
            protocol: Protocol::Tcp,
            allow: true,
        },
        Rule {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(53),
            protocol: Protocol::Udp,
            allow: true,
        },
    ];

    let mut forwarded = 0u64;
    let mut dropped = 0u64;
    let mut parsed_fail = 0u64;
    let start = Instant::now();

    loop {
        match rx.next() {
            Ok(frame) => {
                if let Some(pkt) = parse_packet(frame) {
                    let mut decision = false;
                    for rule in &rules {
                        if rule.matches(&pkt) {
                            decision = rule.allow;
                            break;
                        }
                    }

                    if decision {
                        if let Some(Ok(_)) = tx.send_to(frame, None) {
                            forwarded += 1;
                        } else {
                            dropped += 1;
                        }
                    } else {
                        dropped += 1;
                    }
                } else {
                    parsed_fail += 1;
                }
            }
            Err(_) => {
                // timeout or transient read error; continue
            }
        }

        if (forwarded + dropped + parsed_fail) % 100_000 == 0 && (forwarded + dropped + parsed_fail) > 0 {
            let elapsed = start.elapsed().as_secs_f64();
            eprintln!(
                "pps={:.0} forwarded={} dropped={} parse_fail={}",
                (forwarded + dropped + parsed_fail) as f64 / elapsed,
                forwarded,
                dropped,
                parsed_fail
            );
        }
    }
}
```

