```rust
use etherparse::{Ipv4HeaderSlice, TcpHeaderSlice, UdpHeaderSlice};

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub src_ip: Option<std::net::Ipv4Addr>,
    pub dst_ip: Option<std::net::Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>,
    pub len: usize,
}

impl PacketMeta {
    pub fn parse(frame: &[u8]) -> Self {
        let mut meta = PacketMeta {
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            protocol: None,
            len: frame.len(),
        };

        // Very initial parsing: Ethernet header assumed to be present
        // EtherType IPv4 = 0x0800
        if frame.len() < 14 {
            return meta;
        }

        let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
        if ethertype != 0x0800 {
            return meta;
        }

        if let Ok(ipv4) = Ipv4HeaderSlice::from_slice(&frame[14..]) {
            meta.src_ip = Some(std::net::Ipv4Addr::from(ipv4.source_addr()));
            meta.dst_ip = Some(std::net::Ipv4Addr::from(ipv4.destination_addr()));
            meta.protocol = Some(ipv4.protocol());

            let ip_header_len = ipv4.slice().len();
            let payload = &frame[14 + ip_header_len..];

            match ipv4.protocol() {
                6 => {
                    if let Ok(tcp) = TcpHeaderSlice::from_slice(payload) {
                        meta.src_port = Some(tcp.source_port());
                        meta.dst_port = Some(tcp.destination_port());
                    }
                }
                17 => {
                    if let Ok(udp) = UdpHeaderSlice::from_slice(payload) {
                        meta.src_port = Some(udp.source_port());
                        meta.dst_port = Some(udp.destination_port());
                    }
                }
                _ => {}
            }
        }

        meta
    }
}
