use crate::packet::PacketMeta;

#[derive(Clone, Debug)]
pub enum Action {
    Forward,
    Drop,
}

#[derive(Clone, Debug)]
pub struct Rule {
    pub src_ip: Option<std::net::Ipv4Addr>,
    pub dst_ip: Option<std::net::Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>,
    pub action: Action,
}

impl Rule {
    pub fn matches(&self, pkt: &PacketMeta) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != Some(port) {
                return false;
            }
        }
        if let Some(proto) = self.protocol {
            if pkt.protocol != Some(proto) {
                return false;
            }
        }
        true
    }
}

#[derive(Clone)]
pub struct PacketFilter {
    rules: Vec<Rule>,
    default_action: Action,
}

impl PacketFilter {
    pub fn new(rules: Vec<Rule>, default_action: Action) -> Self {
        Self { rules, default_action }
    }

    pub fn classify(&self, pkt: &PacketMeta) -> Action {
        for rule in &self.rules {
            if rule.matches(pkt) {
                return rule.action.clone();
            }
        }
        self.default_action.clone()
    }
}
