use dashmap::DashMap;
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Default)]
pub struct FlowStats {
    pub packets: AtomicU64,
    pub bytes: AtomicU64,
    pub dropped: AtomicU64,
    pub forwarded: AtomicU64,
}

pub struct Stats {
    flows: DashMap<String, FlowStats>,
}

impl Stats {
    pub fn new() -> Self {
        Self {
            flows: DashMap::new(),
        }
    }

    fn key(src: Option<std::net::Ipv4Addr>, dst: Option<std::net::Ipv4Addr>, proto: Option<u8>, sport: Option<u16>, dport: Option<u16>) -> String {
        format!(
            "{:?}:{:?}->{:?}:{:?}/{}",
            src, sport, dst, dport, proto.unwrap_or(0)
        )
    }

    pub fn record_packet(
        &self,
        src: Option<std::net::Ipv4Addr>,
        dst: Option<std::net::Ipv4Addr>,
        proto: Option<u8>,
        sport: Option<u16>,
        dport: Option<u16>,
        len: usize,
        forwarded: bool,
    ) {
        let key = Self::key(src, dst, proto, sport, dport);
        let entry = self.flows.entry(key).or_default();
        entry.packets.fetch_add(1, Ordering::Relaxed);
        entry.bytes.fetch_add(len as u64, Ordering::Relaxed);
        if forwarded {
            entry.forwarded.fetch_add(1, Ordering::Relaxed);
        } else {
            entry.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}
