use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub dst: [u8; 6],
    pub src: [u8; 6],
    pub ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
    pub header_len: u8,
    pub total_len: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct ParsedPacket {
    pub eth: EthernetHeader,
    pub ipv4: Option<Ipv4Header>,
    pub tcp: Option<TcpHeader>,
    pub udp: Option<UdpHeader>,
}

pub fn parse_ethernet(buf: &[u8]) -> Option<EthernetHeader> {
    if buf.len() < 14 {
        return None;
    }
    let mut dst = [0u8; 6];
    let mut src = [0u8; 6];
    dst.copy_from_slice(&buf[0..6]);
    src.copy_from_slice(&buf[6..12]);
    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    Some(EthernetHeader { dst, src, ethertype })
}

pub fn parse_ipv4(buf: &[u8]) -> Option<Ipv4Header> {
    if buf.len() < 20 {
        return None;
    }
    let version_ihl = buf[0];
    let version = version_ihl >> 4;
    let ihl = version_ihl & 0x0f;
    if version != 4 || ihl < 5 {
        return None;
    }
    let header_len = ihl * 4;
    if buf.len() < header_len as usize {
        return None;
    }

    let total_len = u16::from_be_bytes([buf[2], buf[3]]);
    let protocol = buf[9];
    let src = Ipv4Addr::new(buf[12], buf[13], buf[14], buf[15]);
    let dst = Ipv4Addr::new(buf[16], buf[17], buf[18], buf[19]);

    Some(Ipv4Header {
        src,
        dst,
        protocol,
        header_len,
        total_len,
    })
}

pub fn parse_tcp(buf: &[u8]) -> Option<TcpHeader> {
    if buf.len() < 4 {
        return None;
    }
    Some(TcpHeader {
        src_port: u16::from_be_bytes([buf[0], buf[1]]),
        dst_port: u16::from_be_bytes([buf[2], buf[3]]),
    })
}

pub fn parse_udp(buf: &[u8]) -> Option<UdpHeader> {
    if buf.len() < 4 {
        return None;
    }
    Some(UdpHeader {
        src_port: u16::from_be_bytes([buf[0], buf[1]]),
        dst_port: u16::from_be_bytes([buf[2], buf[3]]),
    })
}

pub fn parse_packet(buf: &[u8]) -> Option<ParsedPacket> {
    let eth = parse_ethernet(buf)?;
    let mut ipv4 = None;
    let mut tcp = None;
    let mut udp = None;

    if eth.ethertype == 0x0800 {
        let ip_off = 14;
        let ip = parse_ipv4(&buf.get(ip_off..)?[..])?;
        let l4_off = ip_off + ip.header_len as usize;
        ipv4 = Some(ip);

        match ip.protocol {
            6 => tcp = parse_tcp(buf.get(l4_off..)?),
            17 => udp = parse_udp(buf.get(l4_off..)?),
            _ => {}
        }
    }

    Some(ParsedPacket { eth, ipv4, tcp, udp })
}
