## src/filter.rs

```rust
use std::net::Ipv4Addr;

use crate::packet::ParsedPacket;

#[derive(Debug, Clone)]
pub enum Action {
    Allow,
    Drop,
    ForwardTo([u8; 6]), // forward to a specific MAC
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>, // 6 TCP, 17 UDP
    pub action: Action,
}

#[derive(Debug, Default)]
pub struct FilterEngine {
    rules: Vec<Rule>,
    default_action: Action,
}

impl FilterEngine {
    pub fn new(default_action: Action) -> Self {
        Self {
            rules: Vec::new(),
            default_action,
        }
    }

    pub fn add_rule(&mut self, rule: Rule) {
        self.rules.push(rule);
    }

    pub fn evaluate(&self, pkt: &ParsedPacket) -> Action {
        let ip = match pkt.ipv4 {
            Some(ip) => ip,
            None => return Action::Drop,
        };

        for rule in &self.rules {
            if let Some(src) = rule.src_ip {
                if src != ip.src {
                    continue;
                }
            }
            if let Some(dst) = rule.dst_ip {
                if dst != ip.dst {
                    continue;
                }
            }
            if let Some(proto) = rule.protocol {
                if proto != ip.protocol {
                    continue;
                }
            }

            if let Some(src_port) = rule.src_port {
                let pkt_src_port = match (ip.protocol, pkt.tcp, pkt.udp) {
                    (6, Some(tcp), _) => tcp.src_port,
                    (17, _, Some(udp)) => udp.src_port,
                    _ => continue,
                };
                if src_port != pkt_src_port {
                    continue;
                }
            }

            if let Some(dst_port) = rule.dst_port {
                let pkt_dst_port = match (ip.protocol, pkt.tcp, pkt.udp) {
                    (6, Some(tcp), _) => tcp.dst_port,
                    (17, _, Some(udp)) => udp.dst_port,
                    _ => continue,
                };
                if dst_port != pkt_dst_port {
                    continue;
                }
            }

            return rule.action.clone();
        }

        self.default_action.clone()
    }
}
