```rust
use anyhow::{Context, Result};
use libc::{c_int, sockaddr_ll};
use std::ffi::CString;
use std::mem;
use std::os::unix::io::RawFd;

pub struct RawSocket {
    fd: RawFd,
    ifindex: i32,
    src_mac: [u8; 6],
}

impl RawSocket {
    pub fn open(interface: &str) -> Result<Self> {
        unsafe {
            let fd = libc::socket(libc::AF_PACKET, libc::SOCK_RAW, (libc::ETH_P_ALL as u16).to_be() as c_int);
            if fd < 0 {
                return Err(std::io::Error::last_os_error()).context("socket(AF_PACKET) failed");
            }

            let ifname = CString::new(interface)?;
            let ifindex = libc::if_nametoindex(ifname.as_ptr());
            if ifindex == 0 {
                return Err(std::io::Error::last_os_error()).context("if_nametoindex failed");
            }

            let mut sll: sockaddr_ll = mem::zeroed();
            sll.sll_family = libc::AF_PACKET as u16;
            sll.sll_protocol = (libc::ETH_P_ALL as u16).to_be();
            sll.sll_ifindex = ifindex as i32;

            let ret = libc::bind(
                fd,
                &sll as *const sockaddr_ll as *const libc::sockaddr,
                mem::size_of::<sockaddr_ll>() as u32,
            );
            if ret < 0 {
                return Err(std::io::Error::last_os_error()).context("bind(AF_PACKET) failed");
            }

            Ok(Self {
                fd,
                ifindex: ifindex as i32,
                src_mac: [0; 6],
            })
        }
    }

    pub fn recv(&self, buf: &mut [u8]) -> Result<usize> {
        let ret = unsafe {
            libc::recv(
                self.fd,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };
        if ret < 0 {
            return Err(std::io::Error::last_os_error()).context("recv failed");
        }
        Ok(ret as usize)
    }

    pub fn send(&self, buf: &[u8]) -> Result<usize> {
        let ret = unsafe {
            libc::send(
                self.fd,
                buf.as_ptr() as *const libc::c_void,
                buf.len(),
                0,
            )
        };
        if ret < 0 {
            return Err(std::io::Error::last_os_error()).context("send failed");
        }
        Ok(ret as usize)
    }

    pub fn rewrite_dst_mac(frame: &mut [u8], new_dst: [u8; 6]) {
        if frame.len() >= 6 {
            frame[0..6].copy_from_slice(&new_dst);
        }
    }
}
