```rust
mod filter;
mod forward;
mod packet;
mod stats;

use anyhow::Result;
use clap::Parser;
use filter::{Action, FilterEngine, Rule};
use forward::RawSocket;
use packet::parse_packet;
use stats::Stats;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug)]
struct Args {
    #[arg(long)]
    input_if: String,

    #[arg(long)]
    output_if: String,

    #[arg(long, default_value = "allow")]
    default_action: String,
}

fn parse_default_action(s: &str) -> Action {
    match s {
        "allow" => Action::Allow,
        "drop" => Action::Drop,
        _ => Action::Drop,
    }
}

fn main() -> Result<()> {
    env_logger::init();
    let args = Args::parse();

    let stats = Arc::new(Stats::default());

    let mut filter = FilterEngine::new(parse_default_action(&args.default_action));

    // Example rules
    filter.add_rule(Rule {
        src_ip: Some(Ipv4Addr::new(10, 0, 0, 10)),
        dst_ip: None,
        src_port: None,
        dst_port: Some(443),
        protocol: Some(6),
        action: Action::Allow,
    });

    filter.add_rule(Rule {
        src_ip: Some(Ipv4Addr::new(192, 168, 1, 100)),
        dst_ip: None,
        src_port: None,
        dst_port: None,
        protocol: None,
        action: Action::Drop,
    });

    let filter = Arc::new(filter);

    let input_sock = Arc::new(RawSocket::open(&args.input_if)?);
    let output_sock = Arc::new(RawSocket::open(&args.output_if)?);

    let worker_stats = stats.clone();
    let worker_filter = filter.clone();
    let worker_input = input_sock.clone();
    let worker_output = output_sock.clone();

    let worker = thread::spawn(move || -> Result<()> {
        let mut buf = vec![0u8; 65536];

        loop {
            let n = worker_input.recv(&mut buf)?;
            worker_stats.inc_received();

            let pkt = match parse_packet(&buf[..n]) {
                Some(p) => p,
                None => {
                    worker_stats.inc_parse_errors();
                    continue;
                }
            };

            match worker_filter.evaluate(&pkt) {
                Action::Allow => {
                    worker_output.send(&buf[..n])?;
                    worker_stats.inc_forwarded();
                }
                Action::Drop => {
                    worker_stats.inc_dropped();
                }
                Action::ForwardTo(dst_mac) => {
                    let mut frame = buf[..n].to_vec();
                    RawSocket::rewrite_dst_mac(&mut frame, dst_mac);
                    worker_output.send(&frame)?;
                    worker_stats.inc_forwarded();
                }
            }
        }
    });

    let stats_printer = {
        let stats = stats.clone();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(5));
            println!(
                "rx={} fwd={} drop={} parse_err={}",
                stats.received.load(std::sync::atomic::Ordering::Relaxed),
                stats.forwarded.load(std::sync::atomic::Ordering::Relaxed),
                stats.dropped.load(std::sync::atomic::Ordering::Relaxed),
                stats.parse_errors.load(std::sync::atomic::Ordering::Relaxed),
            );
        })
    };

    worker.join().unwrap()?;
    stats_printer.join().unwrap();
    Ok(())
}
