## Minimal C implementation

Save as `forwarder.c`:

```c
#include <pcap/pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <unistd.h>

typedef struct {
    pcap_t *tx;
    unsigned long forwarded;
    unsigned long dropped;
} ctx_t;

static int allow_packet(const u_char *pkt, int len) {
    if (len < (int)sizeof(struct ether_header)) return 0;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) {
        return 0; // only IPv4 in this minimal example
    }

    const struct ip *ip = (const struct ip *)(pkt + sizeof(struct ether_header));
    int ip_hlen = ip->ip_hl * 4;
    if (len < (int)sizeof(struct ether_header) + ip_hlen) return 0;

    // Example filter:
    // - allow TCP/UDP only
    // - block packets to destination port 23 (telnet)
    if (ip->ip_p == IPPROTO_TCP) {
        const struct tcphdr *tcp = (const struct tcphdr *)((const u_char *)ip + ip_hlen);
        if (len < (int)sizeof(struct ether_header) + ip_hlen + (int)sizeof(struct tcphdr)) return 0;
        if (ntohs(tcp->th_dport) == 23) return 0;
        return 1;
    } else if (ip->ip_p == IPPROTO_UDP) {
        const struct udphdr *udp = (const struct udphdr *)((const u_char *)ip + ip_hlen);
        if (len < (int)sizeof(struct ether_header) + ip_hlen + (int)sizeof(struct udphdr)) return 0;
        if (ntohs(udp->uh_dport) == 23) return 0;
        return 1;
    }

    return 0;
}

static void on_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    ctx_t *ctx = (ctx_t *)user;

    if (allow_packet(bytes, h->caplen)) {
        if (pcap_sendpacket(ctx->tx, bytes, h->caplen) == 0) {
            ctx->forwarded++;
        } else {
            fprintf(stderr, "pcap_sendpacket failed: %s\n", pcap_geterr(ctx->tx));
        }
    } else {
        ctx->dropped++;
    }

    if ((ctx->forwarded + ctx->dropped) % 1000 == 0) {
        fprintf(stderr, "forwarded=%lu dropped=%lu\n", ctx->forwarded, ctx->dropped);
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *rx = pcap_open_live(argv[1], 65535, 1, 1, errbuf);
    if (!rx) {
        fprintf(stderr, "pcap_open_live(rx): %s\n", errbuf);
        return 1;
    }

    pcap_t *tx = pcap_open_live(argv[2], 65535, 1, 1, errbuf);
    if (!tx) {
        fprintf(stderr, "pcap_open_live(tx): %s\n", errbuf);
        pcap_close(rx);
        return 1;
    }

    // Optional: reduce overhead by filtering at capture level too
    struct bpf_program fp;
    if (pcap_compile(rx, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        if (pcap_setfilter(rx, &fp) != 0) {
            fprintf(stderr, "pcap_setfilter: %s\n", pcap_geterr(rx));
        }
        pcap_freecode(&fp);
    }

    // Put interfaces into immediate mode if supported
#ifdef PCAP_ERROR_ACTIVATED
    pcap_set_immediate_mode(rx, 1);
    pcap_set_immediate_mode(tx, 1);
#endif

    ctx_t ctx = { .tx = tx, .forwarded = 0, .dropped = 0 };

    fprintf(stderr, "Forwarding from %s -> %s\n", argv[1], argv[2]);
    if (pcap_loop(rx, -1, on_packet, (u_char *)&ctx) < 0) {
        fprintf(stderr, "pcap_loop: %s\n", pcap_geterr(rx));
    }

    pcap_close(rx);
    pcap_close(tx);
    return 0;
}
