    let in_fd = open_packet_socket(&args.in_if)?;
    let out_fd = open_packet_socket(&args.out_if)?;

    let ethertype_filter = match args.ethertype.as_deref() {
        Some(s) => Some(parse_u16_hex(s)?),
        None => None,
    };

    let dst_mac_filter = match args.dst_mac.as_deref() {
        Some(s) => Some(parse_mac(s)?),
        None => None,
    };

    eprintln!(
        "Forwarding from {} -> {} | ethertype={:?} dst_mac={:?}",
        args.in_if, args.out_if, ethertype_filter, dst_mac_filter
    );

    let mut buf = vec![0u8; args.bufsize];

    loop {
        let n = recv(in_fd.as_raw_fd(), buf.as_mut_ptr() as *mut _, buf.len(), 0);
        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err).context("recv failed");
        }

        let n = n as usize;
        if n < 14 {
            continue;
        }

        let dst_mac = &buf[0..6];
        let ethertype = u16::from_be_bytes([buf[12], buf[13]]);

        if let Some(filter) = ethertype_filter {
            if ethertype != filter {
                continue;
            }
        }

        if let Some(filter) = dst_mac_filter {
            if dst_mac != filter.as_slice() {
                continue;
            }
        }

        let sent = send(out_fd.as_raw_fd(), buf.as_ptr() as *const _, n, 0);
        if sent < 0 {
            let err = io::Error::last_os_error();
            return Err(err).context("send failed");
        }
    }
}

fn open_packet_socket(ifname: &str) -> Result<OwnedFd> {
    let fd = unsafe {
        socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as i32)
    };
    if fd < 0 {
        return Err(io::Error::last_os_error()).context("socket(AF_PACKET) failed");
    }

    let fd = unsafe { OwnedFd::from_raw_fd(fd) };

    let ifindex = if_nametoindex_c(ifname)?;
    let mut sll: sockaddr_ll = unsafe { zeroed() };
    sll.sll_family = AF_PACKET as u16;
    sll.sll_protocol = htons(ETH_P_ALL as u16);
    sll.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd.as_raw_fd(),
            &sll as *const sockaddr_ll as *const sockaddr,
            size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error()).context("bind(AF_PACKET) failed");
    }

    Ok(fd)
}

fn if_nametoindex_c(name: &str) -> Result<u32> {
    let c = CString::new(name)?;
    let idx = unsafe { if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        return Err(io::Error::last_os_error()).context("if_nametoindex failed");
    }
    Ok(idx)
}

fn parse_u16_hex(s: &str) -> Result<u16> {
    let s = s.trim_start_matches("0x");
    Ok(u16::from_str_radix(s, 16)?)
}

fn parse_mac(s: &str) -> Result<Vec<u8>> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 6 {
        anyhow::bail!("invalid MAC format");
    }
    let mut out = Vec::with_capacity(6);
    for p in parts {
        out.push(u8::from_str_radix(p, 16)?);
    }
    Ok(out)
}
