```go
package main

import (
	"fmt"
	"log"
	"net"
	"os"
	"strconv"
	"strings"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
	"github.com/google/gopacket/afpacket"
)

type Rule struct {
	AllowTCPPorts map[uint16]bool
	AllowUDPPorts map[uint16]bool
}

func parsePortList(s string) map[uint16]bool {
	m := make(map[uint16]bool)
	if s == "" {
		return m
	}
	for _, p := range strings.Split(s, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		v, err := strconv.Atoi(p)
		if err != nil || v < 1 || v > 65535 {
			continue
		}
		m[uint16(v)] = true
	}
	return m
}

func shouldAllow(pkt gopacket.Packet, rule Rule) bool {
	if tcpLayer := pkt.Layer(layers.LayerTypeTCP); tcpLayer != nil {
		tcp := tcpLayer.(*layers.TCP)
		return rule.AllowTCPPorts[uint16(tcp.SrcPort)] || rule.AllowTCPPorts[uint16(tcp.DstPort)]
	}
	if udpLayer := pkt.Layer(layers.LayerTypeUDP); udpLayer != nil {
		udp := udpLayer.(*layers.UDP)
		return rule.AllowUDPPorts[uint16(udp.SrcPort)] || rule.AllowUDPPorts[uint16(udp.DstPort)]
	}
	return false
}

func main() {
	if len(os.Args) < 4 {
		fmt.Fprintf(os.Stderr, "usage: %s <in-iface> <out-iface> <tcp-ports> [udp-ports]\n", os.Args[0])
		fmt.Fprintf(os.Stderr, "example: %s eth0 eth1 80,443 53\n", os.Args[0])
		os.Exit(1)
	}

	inIface := os.Args[1]
	outIface := os.Args[2]
	rule := Rule{
		AllowTCPPorts: parsePortList(os.Args[3]),
		AllowUDPPorts: map[uint16]bool{},
	}
	if len(os.Args) > 4 {
		rule.AllowUDPPorts = parsePortList(os.Args[4])
	}

	inDev, err := net.InterfaceByName(inIface)
	if err != nil {
		log.Fatalf("input interface: %v", err)
	}
	outDev, err := net.InterfaceByName(outIface)
	if err != nil {
		log.Fatalf("output interface: %v", err)
	}

	snaplen := 65535
	blockSize := 1 << 20
	numBlocks := 64
	timeout := afpacket.BlockForever

	h, err := afpacket.NewTPacket(
		afpacket.OptInterface(inIface),
		afpacket.OptFrameSize(snaplen),
		afpacket.OptBlockSize(blockSize),
		afpacket.OptNumBlocks(numBlocks),
		afpacket.OptPollTimeout(timeout),
	)
	if err != nil {
		log.Fatalf("afpacket: %v", err)
	}
	defer h.Close()

	outHandle, err := net.ListenPacket("ip4:raw", "")
	if err != nil {
		log.Fatalf("raw output socket: %v", err)
	}
	defer outHandle.Close()

	fmt.Printf("filtering %s -> %s | tcp=%v udp=%v\n", inDev.Name, outDev.Name, rule.AllowTCPPorts, rule.AllowUDPPorts)

	src := gopacket.ZeroCopyPacketDataSource(h)
	packetSource := gopacket.NewPacketSource(src, layers.LayerTypeEthernet)

	for {
		data, ci, err := h.ZeroCopyReadPacketData()
		if err != nil {
			continue
		}
		_ = ci

		pkt := gopacket.NewPacket(data, layers.LayerTypeEthernet, gopacket.Default)
		if !shouldAllow(pkt, rule) {
			continue
		}

		ethLayer := pkt.Layer(layers.LayerTypeEthernet)
		if ethLayer == nil {
			continue
		}

		// Forward the raw frame as-is.
		// For real deployments, you may need L2 rewrite (MACs, VLANs, checksums, TTL, routing).
		_, err = outHandle.Write(data)
		if err != nil {
			log.Printf("forward error: %v", err)
		}
	}
}
```

