use anyhow::{Context, Result};
use libc::{bind, if_nametoindex, recv, sendto, sockaddr_ll, AF_PACKET, SOCK_RAW};
use pnet_packet::ethernet::{EtherTypes, EthernetPacket};
use pnet_packet::ip::IpNextHeaderProtocols;
use pnet_packet::ipv4::Ipv4Packet;
use pnet_packet::tcp::TcpPacket;
use pnet_packet::udp::UdpPacket;
use std::ffi::CString;
use std::mem::size_of;
use std::os::unix::io::RawFd;
use std::ptr;

const ETH_P_ALL: u16 = 0x0003;

fn open_packet_socket() -> Result<RawFd> {
    let fd = unsafe { libc::socket(AF_PACKET, SOCK_RAW, (ETH_P_ALL as i32).to_be()) };
    if fd < 0 {
        anyhow::bail!("failed to open AF_PACKET socket");
    }
    Ok(fd)
}

fn bind_to_interface(fd: RawFd, ifname: &str) -> Result<()> {
    let c_ifname = CString::new(ifname)?;
    let ifindex = unsafe { if_nametoindex(c_ifname.as_ptr()) };
    if ifindex == 0 {
        anyhow::bail!("interface not found: {}", ifname);
    }

    let mut addr: sockaddr_ll = unsafe { std::mem::zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = (ETH_P_ALL).to_be();
    addr.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &addr as *const sockaddr_ll as *const libc::sockaddr,
            size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        anyhow::bail!("failed to bind to interface {}", ifname);
    }
    Ok(())
}

fn send_packet(fd: RawFd, ifindex: i32, frame: &[u8]) -> Result<()> {
    let mut addr: sockaddr_ll = unsafe { std::mem::zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_ifindex = ifindex;
    addr.sll_halen = 6;

    let ret = unsafe {
        sendto(
            fd,
            frame.as_ptr() as *const libc::c_void,
            frame.len(),
            0,
            &addr as *const sockaddr_ll as *const libc::sockaddr,
            size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        anyhow::bail!("sendto failed");
    }
    Ok(())
}

fn allow_packet(frame: &[u8]) -> bool {
    let eth = match EthernetPacket::new(frame) {
        Some(p) => p,
        None => return false,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = match Ipv4Packet::new(eth.payload()) {
                Some(p) => p,
                None => return false,
            };

            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = match TcpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    let dport = tcp.get_destination();
                    dport == 80 || dport == 443
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = match UdpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    let dport = udp.get_destination();
                    dport == 53
                }
                _ => false,
            }
        }
        _ => false,
    }
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <in_if> <out_if>", args[0]);
        std::process::exit(1);
    }

    let in_if = &args[1];
    let out_if = &args[2];

    let in_fd = open_packet_socket().context("open input socket")?;
    let out_fd = open_packet_socket().context("open output socket")?;

    bind_to_interface(in_fd, in_if).context("bind input")?;

    let out_if_c = CString::new(out_if.as_str())?;
    let out_ifindex = unsafe { if_nametoindex(out_if_c.as_ptr()) };
    if out_ifindex == 0 {
        anyhow::bail!("output interface not found: {}", out_if);
    }

    let mut buf = vec![0u8; 2048];

    loop {
        let n = unsafe {
            recv(
                in_fd,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };
        if n < 0 {
            continue;
        }

        let frame = &buf[..n as usize];

        if allow_packet(frame) {
            let _ = send_packet(out_fd, out_ifindex as i32, frame);
        }
    }
}
