use anyhow::{Context, Result};
use pnet::datalink::{self, Channel::Ethernet, Config, DataLinkReceiver, DataLinkSender};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::Packet;
use std::env;
use std::time::Duration;

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 5 {
        eprintln!(
            "Usage: {} <in_iface> <out_iface> <tcp_port> <direction: in|out>",
            args[0]
        );
        std::process::exit(1);
    }

    let in_iface = &args[1];
    let out_iface = &args[2];
    let tcp_port: u16 = args[3].parse().context("invalid tcp_port")?;
    let _direction = &args[4]; // kept for interface symmetry; minimal example forwards all matched packets

    let interfaces = datalink::interfaces();
    let in_interface = interfaces
        .iter()
        .find(|iface| iface.name == *in_iface)
        .context("input interface not found")?;
    let out_interface = interfaces
        .iter()
        .find(|iface| iface.name == *out_iface)
        .context("output interface not found")?;

    let mut cfg = Config::default();
    cfg.read_timeout = Some(Duration::from_millis(1));
    cfg.write_buffer_size = 1 << 20;
    cfg.read_buffer_size = 1 << 20;
    cfg.promiscuous = true;

    let (_, mut rx) = match datalink::channel(in_interface, cfg.clone())
        .context("failed to open input channel")?
    {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    let (mut tx, _) = match datalink::channel(out_interface, cfg)
        .context("failed to open output channel")?
    {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    eprintln!(
        "Forwarding IPv4 TCP packets with port {} from {} to {}",
        tcp_port, in_iface, out_iface
    );

    loop {
        match rx.next() {
            Ok(frame) => {
                if should_forward(frame, tcp_port) {
                    forward_frame(&mut tx, frame);
                }
            }
            Err(_) => {
                // timeout or transient read error; keep looping for low latency
            }
        }
    }
}

fn should_forward(frame: &[u8], tcp_port: u16) -> bool {
    let eth = match EthernetPacket::new(frame) {
        Some(p) => p,
        None => return false,
    };

    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return false;
    }

    let ipv4 = match Ipv4Packet::new(eth.payload()) {
        Some(p) => p,
        None => return false,
    };

    if ipv4.get_next_level_protocol() != IpNextHeaderProtocols::Tcp {
        return false;
    }

    let tcp = match TcpPacket::new(ipv4.payload()) {
        Some(p) => p,
        None => return false,
    };

    tcp.get_source() == tcp_port || tcp.get_destination() == tcp_port
}

fn forward_frame(tx: &mut Box<dyn DataLinkSender>, frame: &[u8]) {
    let mut buf = vec![0u8; frame.len()];
    buf.copy_from_slice(frame);

    match tx.send_to(&buf, None) {
        Some(Ok(())) => {}
        Some(Err(_)) | None => {
            // drop on send failure
        }
    }
}
