        .into_iter()
        .find(|iface| iface.name == iface_name)
        .expect("interface not found");

    let mut config = datalink::Config::default();
    config.read_timeout = Some(std::time::Duration::from_millis(10));

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("unsupported channel type"),
        Err(e) => panic!("failed to open interface: {e}"),
    };

    let sock = UdpSocket::bind("0.0.0.0:0").expect("udp bind failed");
    sock.connect(forward_addr).expect("udp connect failed");

    let mut packets = 0u64;
    let mut forwarded = 0u64;
    let start = Instant::now();

    loop {
        match rx.next() {
            Ok(frame) => {
                packets += 1;

                if let Some(eth) = EthernetPacket::new(frame) {
                    if eth.get_ethertype() == EtherTypes::Ipv4 {
                        if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                            if ipv4.get_next_level_protocol() == IpNextHeaderProtocols::Tcp {
                                if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                    let dst_port = tcp.get_destination();
                                    if dst_port == allowed_dst_port {
                                        // Forward the raw frame bytes to a UDP collector
                                        // In a real system, you'd forward to another NIC or
                                        // use AF_PACKET / DPDK / AF_XDP for lower latency.
                                        let _ = sock.send(frame);
                                        forwarded += 1;
                                    }
                                }
                            }
                        }
                    }
                }

                if packets % 10000 == 0 {
                    let elapsed = start.elapsed().as_secs_f64();
                    eprintln!(
                        "packets={} forwarded={} rate={:.0} pkt/s",
                        packets,
                        forwarded,
                        packets as f64 / elapsed.max(0.001)
                    );
                }
            }
            Err(_) => {
                // timeout or transient read error
                continue;
            }
        }
    }
}
