## Code: `fast_forward.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/if.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <net/if_arp.h>
#include <net/if.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define BUF_SIZE 2048

static volatile sig_atomic_t running = 1;

static void on_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int get_if_index(int sock, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static int get_if_mac(int sock, const char *ifname, unsigned char mac[6]) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFHWADDR, &ifr) < 0) return -1;
    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
    return 0;
}

static int is_udp_port(const unsigned char *pkt, ssize_t len, uint16_t port) {
    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return 0;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return 0;

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if (ip->version != 4) return 0;
    if (ip->protocol != IPPROTO_UDP) return 0;

    int iphdr_len = ip->ihl * 4;
    if (iphdr_len < (int)sizeof(struct iphdr)) return 0;

    if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len + sizeof(struct udphdr))) return 0;

    const struct udphdr *udp = (const struct udphdr *)(pkt + sizeof(struct ethhdr) + iphdr_len);
    return ntohs(udp->dest) == port;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <in_if> <out_if> <udp_dest_port>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    uint16_t udp_port = (uint16_t)atoi(argv[3]);

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    int rx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx_sock < 0) {
        perror("socket(rx)");
        return 1;
    }

    int tx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_sock < 0) {
        perror("socket(tx)");
        close(rx_sock);
        return 1;
    }

    int in_idx = get_if_index(rx_sock, in_if);
    int out_idx = get_if_index(tx_sock, out_if);
    if (in_idx < 0 || out_idx < 0) {
        perror("ifindex");
        close(rx_sock);
        close(tx_sock);
        return 1;
    }

    unsigned char out_mac[6];
    if (get_if_mac(tx_sock, out_if, out_mac) < 0) {
        perror("ifmac");
        close(rx_sock);
        close(tx_sock);
        return 1;
    }

    struct sockaddr_ll rx_addr = {0};
    rx_addr.sll_family = AF_PACKET;
    rx_addr.sll_protocol = htons(ETH_P_ALL);
    rx_addr.sll_ifindex = in_idx;

    if (bind(rx_sock, (struct sockaddr *)&rx_addr, sizeof(rx_addr)) < 0) {
        perror("bind(rx)");
        close(rx_sock);
        close(tx_sock);
        return 1;
    }

    struct sockaddr_ll tx_addr = {0};
    tx_addr.sll_family = AF_PACKET;
    tx_addr.sll_ifindex = out_idx;
    tx_addr.sll_halen = ETH_ALEN;
    memcpy(tx_addr.sll_addr, out_mac, 6);

    unsigned char buf[BUF_SIZE];
    while (running) {
        ssize_t n = recv(rx_sock, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (!is_udp_port(buf, n, udp_port)) continue;

        struct ethhdr *eth = (struct ethhdr *)buf;
        unsigned char src_mac[6];
        memcpy(src_mac, eth->h_source, 6);
        memcpy(eth->h_source, out_mac, 6);
        memcpy(eth->h_dest, src_mac, 6);

        ssize_t sent = sendto(tx_sock, buf, n, 0,
                              (struct sockaddr *)&tx_addr, sizeof(tx_addr));
        if (sent < 0) {
            perror("sendto");
        }
    }

    close(rx_sock);
    close(tx_sock);
    return 0;
}
