// minimal_forwarder.c
#define _GNU_SOURCE
#include <pcap/pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/if_ether.h>
#include <sys/socket.h>
#include <netpacket/packet.h>
#include <net/if.h>
#include <errno.h>

static int out_sock = -1;
static int out_ifindex = -1;

static uint16_t ip_checksum(void *vdata, size_t length) {
    char *data = (char *)vdata;
    uint64_t acc = 0xffff;

    for (size_t i = 0; i + 1 < length; i += 2) {
        uint16_t word;
        memcpy(&word, data + i, 2);
        acc += ntohs(word);
        if (acc > 0xffff) acc -= 0xffff;
    }

    if (length & 1) {
        uint16_t word = 0;
        memcpy(&word, data + length - 1, 1);
        acc += ntohs(word);
        if (acc > 0xffff) acc -= 0xffff;
    }

    return htons(~acc);
}

static int allow_packet(const u_char *pkt, int len) {
    if (len < (int)(sizeof(struct ether_header) + sizeof(struct iphdr)))
        return 0;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP)
        return 0;

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ether_header));

    // Example policy: allow only TCP/UDP to/from a specific subnet
    // Replace with your own policy.
    if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP)
        return 0;

    return 1;
}

static void forward_packet(const u_char *pkt, int len) {
    ssize_t sent = sendto(out_sock, pkt, len, 0, NULL, 0);
    if (sent < 0) {
        perror("sendto");
    }
}

static void callback(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;
    if (allow_packet(bytes, h->caplen)) {
        forward_packet(bytes, h->caplen);
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    char errbuf[PCAP_ERRBUF_SIZE];

    pcap_t *handle = pcap_open_live(in_if, 65535, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
        return 1;
    }

    int out_ifidx = if_nametoindex(out_if);
    if (out_ifidx == 0) {
        perror("if_nametoindex");
        pcap_close(handle);
        return 1;
    }
    out_ifindex = out_ifidx;

    out_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (out_sock < 0) {
        perror("socket");
        pcap_close(handle);
        return 1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = out_ifindex;
    sll.sll_halen = ETH_ALEN;

    // Bind socket to output interface
    if (bind(out_sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(out_sock);
        pcap_close(handle);
        return 1;
    }

    printf("Listening on %s, forwarding allowed packets to %s\n", in_if, out_if);

    if (pcap_loop(handle, -1, callback, NULL) < 0) {
        fprintf(stderr, "pcap_loop: %s\n", pcap_geterr(handle));
    }

    close(out_sock);
    pcap_close(handle);
    return 0;
}
