```rust
use anyhow::{Context, Result};
use pnet::datalink::{self, Channel::Ethernet, Config, DataLinkReceiver, DataLinkSender};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::time::Duration;

const MAX_FRAME_SIZE: usize = 1518;

fn main() -> Result<()> {
    // Change these to match your environment
    let in_iface_name = "eth0";
    let out_iface_name = "eth1";

    let in_iface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == in_iface_name)
        .context("input interface not found")?;

    let out_iface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == out_iface_name)
        .context("output interface not found")?;

    let mut in_cfg = Config::default();
    in_cfg.read_timeout = Some(Duration::from_micros(10));
    in_cfg.write_buffer_size = 1024;
    in_cfg.read_buffer_size = 1024;

    let mut out_cfg = Config::default();
    out_cfg.write_buffer_size = 1024;

    let (_, mut rx) = match datalink::channel(&in_iface, in_cfg)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => panic!("unhandled channel type"),
    };

    let (mut tx, _) = match datalink::channel(&out_iface, out_cfg)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => panic!("unhandled channel type"),
    };

    println!("Forwarding from {} -> {}", in_iface_name, out_iface_name);

    let mut frame_buf = [0u8; MAX_FRAME_SIZE];

    loop {
        match rx.next() {
            Ok(packet) => {
                if should_forward(packet) {
                    let len = packet.len().min(MAX_FRAME_SIZE);
                    frame_buf[..len].copy_from_slice(&packet[..len]);

                    match tx.send_to(&frame_buf[..len], None) {
                        Some(Ok(())) => {}
                        Some(Err(e)) => eprintln!("send error: {e}"),
                        None => eprintln!("tx unavailable"),
                    }
                }
            }
            Err(_) => {
                // timeout or transient receive error; keep looping
            }
        }
    }
}

fn should_forward(frame: &[u8]) -> bool {
    let eth = match EthernetPacket::new(frame) {
        Some(pkt) => pkt,
        None => return false,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                let src = ipv4.get_source();
                let dst = ipv4.get_destination();

                // Example filter:
                // drop traffic from 10.0.0.1
                // forward everything else
                if src == Ipv4Addr::new(10, 0, 0, 1) {
                    return false;
                }

                // Example: only forward packets to 192.168.1.0/24
                if dst.octets()[0] == 192 && dst.octets()[1] == 168 && dst.octets()[2] == 1 {
                    return true;
                }

                false
            } else {
                false
            }
        }
        // Forward non-IPv4 frames as-is, if desired
        _ => true,
    }
}
```

