## Minimal C implementation

### `forwarder.c`
```c
#define _GNU_SOURCE
#include <pcap/pcap.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

static volatile sig_atomic_t stop = 0;

static pcap_t *in_pcap = NULL;
static pcap_t *out_pcap = NULL;

static void on_sigint(int sig) {
    (void)sig;
    stop = 1;
}

static int allow_packet(const u_char *pkt, size_t len) {
    if (len < sizeof(struct ether_header)) return 0;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    uint16_t etype = ntohs(eth->ether_type);

    // Allow only IPv4 for this minimal example
    if (etype != ETHERTYPE_IP) return 0;

    if (len < sizeof(struct ether_header) + sizeof(struct ip)) return 0;
    const struct ip *ip = (const struct ip *)(pkt + sizeof(struct ether_header));

    // Example policy:
    // - allow TCP/UDP only
    // - drop everything else
    if (ip->ip_p != IPPROTO_TCP && ip->ip_p != IPPROTO_UDP) return 0;

    // Example additional filter:
    // drop packets to/from 10.0.0.0/8
    struct in_addr src = ip->ip_src;
    struct in_addr dst = ip->ip_dst;
    uint32_t s = ntohl(src.s_addr);
    uint32_t d = ntohl(dst.s_addr);
    if ((s & 0xFF000000u) == 0x0A000000u) return 0;
    if ((d & 0xFF000000u) == 0x0A000000u) return 0;

    return 1;
}

static void handle_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    if (!allow_packet(bytes, h->caplen)) return;

    // Forward packet as-is
    if (pcap_inject(out_pcap, bytes, h->caplen) == -1) {
        fprintf(stderr, "pcap_inject failed: %s\n", pcap_geterr(out_pcap));
    }
}

static pcap_t *open_iface(const char *ifname, int promisc, int immediate) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *p = pcap_create(ifname, errbuf);
    if (!p) {
        fprintf(stderr, "pcap_create(%s): %s\n", ifname, errbuf);
        return NULL;
    }

    pcap_set_snaplen(p, 65535);
    pcap_set_promisc(p, promisc);
    pcap_set_timeout(p, 1);
#ifdef PCAP_ERROR_ACTIVATED
    (void)immediate;
#else
    if (immediate) pcap_set_immediate_mode(p, 1);
#endif

    if (pcap_activate(p) != 0) {
        fprintf(stderr, "pcap_activate(%s): %s\n", ifname, pcap_geterr(p));
        pcap_close(p);
        return NULL;
    }

    return p;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    in_pcap = open_iface(argv[1], 1, 1);
    if (!in_pcap) return 1;

    out_pcap = open_iface(argv[2], 0, 1);
    if (!out_pcap) {
        pcap_close(in_pcap);
        return 1;
    }

    // Optional: reduce overhead by using a capture filter too
    struct bpf_program fp;
    if (pcap_compile(in_pcap, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        if (pcap_setfilter(in_pcap, &fp) != 0) {
            fprintf(stderr, "pcap_setfilter: %s\n", pcap_geterr(in_pcap));
        }
        pcap_freecode(&fp);
    }

    printf("Forwarding from %s to %s. Ctrl-C to stop.\n", argv[1], argv[2]);

    while (!stop) {
        int rc = pcap_dispatch(in_pcap, 64, handle_packet, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch: %s\n", pcap_geterr(in_pcap));
            break;
        }
    }

    pcap_close(in_pcap);
    pcap_close(out_pcap);
    return 0;
}
