## C implementation

```c
/*
 * logrotated.c - memory-constrained log rotation daemon
 *
 * Features:
 *  - fixed-size static config
 *  - no heap allocation in steady state
 *  - rotates when file size exceeds threshold
 *  - keeps N rotated generations
 *  - uses rename() and reopen strategy
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -std=c11 -o logrotated logrotated.c
 *
 * Run:
 *   ./logrotated
 *
 * Notes:
 *  - This daemon assumes the target application writes to a file path
 *    that can be safely reopened after rotation.
 *  - For applications that keep file descriptors open forever, you may need
 *    copytruncate or signaling support.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_LOGS        8
#define PATH_MAX_LOCAL  512
#define CHECK_INTERVAL   5   /* seconds */

typedef struct {
    char path[PATH_MAX_LOCAL];
    size_t max_bytes;
    unsigned generations;   /* number of rotated files to keep */
} log_config_t;

static volatile sig_atomic_t g_running = 1;

static log_config_t g_logs[MAX_LOGS] = {
    { "/var/log/myapp.log", 10u * 1024u * 1024u, 5 },
    /* Add more logs here if needed */
};

static size_t g_log_count = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_one(const log_config_t *cfg) {
    char oldpath[PATH_MAX_LOCAL];
    char newpath[PATH_MAX_LOCAL];

    /* Shift generations: log.4 -> log.5, log.3 -> log.4, ... */
    for (unsigned i = cfg->generations; i > 0; --i) {
        if (i == 1) {
            if (safe_snprintf(oldpath, sizeof(oldpath), "%s", cfg->path) < 0) return -1;
        } else {
            if (safe_snprintf(oldpath, sizeof(oldpath), "%s.%u", cfg->path, i - 1) < 0) return -1;
        }

        if (safe_snprintf(newpath, sizeof(newpath), "%s.%u", cfg->path, i) < 0) return -1;

        /* Remove destination if it exists, then rename */
        (void)unlink(newpath);
        if (rename(oldpath, newpath) < 0) {
            if (errno == ENOENT) {
                continue;
            }
            return -1;
        }
    }

    /* Create a fresh empty base log file */
    int fd = open(cfg->path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int should_rotate(const log_config_t *cfg) {
    struct stat st;
    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) {
            /* Missing file: create it */
            int fd = open(cfg->path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
            if (fd < 0) return -1;
            close(fd);
            return 0;
        }
        return -1;
    }

    if ((size_t)st.st_size >= cfg->max_bytes) {
        return 1;
    }
    return 0;
}

static void daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    if (setsid() < 0) {
        perror("setsid");
        exit(EXIT_FAILURE);
    }

    pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    umask(027);
    chdir("/");

    /* Close inherited fds */
    for (int fd = (int)sysconf(_SC_OPEN_MAX); fd >= 0; --fd) {
        close(fd);
    }

    /* Reopen stdio to /dev/null */
    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd >= 0) {
        dup2(nullfd, STDIN_FILENO);
        dup2(nullfd, STDOUT_FILENO);
        dup2(nullfd, STDERR_FILENO);
        if (nullfd > STDERR_FILENO) close(nullfd);
    }
}

static int init_logs(void) {
    for (size_t i = 0; i < g_log_count; ++i) {
        int fd = open(g_logs[i].path, O_CREAT | O_WRONLY | O_APPEND, 0640);
        if (fd < 0) return -1;
        close(fd);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return EXIT_FAILURE;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return EXIT_FAILURE;

    /* Optional: daemonize */
    daemonize();

    /* Initialize log files */
    if (init_logs() < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        for (size_t i = 0; i < g_log_count; ++i) {
            int r = should_rotate(&g_logs[i]);
            if (r < 0) {
                /* In a daemon, you'd typically log this somewhere else */
                continue;
            } else if (r > 0) {
                if (rotate_one(&g_logs[i]) < 0) {
                    /* Rotation failed; keep going */
                    continue;
                }
            }
        }

        /* Sleep without allocating */
        struct timespec ts;
        ts.tv_sec = CHECK_INTERVAL;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && g_running) {
            /* retry */
        }
    }

    return EXIT_SUCCESS;
}
```

