## Code

```c
/*
 * logrotate_daemon.c
 *
 * Memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -o logrotate_daemon logrotate_daemon.c
 *
 * Usage:
 *   ./logrotate_daemon /var/log/myapp.log 10485760 5 5
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = polling interval in seconds
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <time.h>

#define PATH_BUF_SIZE 512
#define LINE_BUF_SIZE  256

static char g_log_path[PATH_BUF_SIZE];
static size_t g_max_size = 0;
static int g_keep = 0;
static int g_interval = 5;

static FILE *g_log_fp = NULL;

static void safe_sleep(int seconds) {
    struct timespec ts;
    ts.tv_sec = seconds;
    ts.tv_nsec = 0;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry */
    }
}

static int open_log_file(void) {
    g_log_fp = fopen(g_log_path, "a");
    if (!g_log_fp) {
        return -1;
    }
    return 0;
}

static void close_log_file(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_name(int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", g_log_path, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(void) {
    char old_name[PATH_BUF_SIZE];
    char new_name[PATH_BUF_SIZE];

    close_log_file();

    /* Delete oldest */
    if (g_keep > 0) {
        if (build_rotated_name(g_keep, old_name, sizeof(old_name)) == 0) {
            unlink(old_name);
        }
    }

    /* Shift rotated files */
    for (int i = g_keep - 1; i >= 1; --i) {
        if (build_rotated_name(i, old_name, sizeof(old_name)) != 0) {
            return -1;
        }
        if (build_rotated_name(i + 1, new_name, sizeof(new_name)) != 0) {
            return -1;
        }
        /* Ignore missing files */
        rename(old_name, new_name);
    }

    /* Rename current log to .1 */
    if (build_rotated_name(1, new_name, sizeof(new_name)) != 0) {
        return -1;
    }
    if (rename(g_log_path, new_name) != 0) {
        /* If rename fails because file doesn't exist, continue */
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Reopen fresh log */
    return open_log_file();
}

static void daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        _exit(1);
    }

    pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    umask(027);
    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);
}

static int write_status(const char *msg) {
    if (!g_log_fp) return -1;
    if (fprintf(g_log_fp, "%s\n", msg) < 0) return -1;
    fflush(g_log_fp);
    return 0;
}

static int should_rotate(void) {
    off_t size = 0;
    if (get_file_size(g_log_path, &size) != 0) {
        return 0;
    }
    return (size >= (off_t)g_max_size);
}

int main(int argc, char **argv) {
    if (argc < 5) {
        fprintf(stderr,
                "Usage: %s <log_path> <max_size_bytes> <keep> <interval_sec>\n",
                argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= PATH_BUF_SIZE) {
        fprintf(stderr, "Log path too long\n");
        return 1;
    }

    snprintf(g_log_path, sizeof(g_log_path), "%s", argv[1]);
    g_max_size = (size_t)strtoull(argv[2], NULL, 10);
    g_keep = atoi(argv[3]);
    g_interval = atoi(argv[4]);

    if (g_max_size == 0 || g_keep < 0 || g_interval <= 0) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    /* Optional: daemonize.
       Comment out if you want foreground execution. */
    daemonize_process();

    if (open_log_file() != 0) {
        return 1;
    }

    for (;;) {
        if (should_rotate()) {
            if (rotate_logs() != 0) {
                /* In a real daemon, log to syslog or stderr fallback */
            } else {
                write_status("log rotated");
            }
        }
        safe_sleep(g_interval);
    }

    close_log_file();
    return 0;
}
```

