## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LEN   256
#define IO_BUF_SIZE    4096
#define MAX_BACKUPS      5

typedef struct {
    char log_path[MAX_PATH_LEN];
    char rot_path[MAX_PATH_LEN];
    size_t max_size;
    unsigned interval_sec;
    unsigned max_backups;
    int compress; /* 0 = no, 1 = gzip via external command */
} config_t;

typedef struct {
    config_t cfg;
    int log_fd;
    time_t last_rotate;
    volatile sig_atomic_t stop;
} daemon_state_t;

static void safe_close(int fd) {
    if (fd >= 0) close(fd);
}

static int file_size_fd(int fd, off_t *out_size) {
    struct stat st;
    if (fstat(fd, &st) < 0) return -1;
    *out_size = st.st_size;
    return 0;
}

static int open_log_append(const char *path) {
    return open(path, O_WRONLY | O_APPEND | O_CREAT, 0644);
}

static int rename_rotate(const char *src, const char *dst) {
    if (rename(src, dst) < 0) return -1;
    return 0;
}

static int shift_backups(const config_t *cfg) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    for (unsigned i = cfg->max_backups; i >= 1; --i) {
        if (i == 1) {
            snprintf(oldp, sizeof(oldp), "%s.1", cfg->log_path);
        } else {
            snprintf(oldp, sizeof(oldp), "%s.%u", cfg->log_path, i - 1);
        }
        snprintf(newp, sizeof(newp), "%s.%u", cfg->log_path, i);

        if (access(oldp, F_OK) == 0) {
            unlink(newp); /* ignore failure */
            if (rename(oldp, newp) < 0) {
                return -1;
            }
        }

        if (i == cfg->max_backups) break;
    }
    return 0;
}

static int compress_file_external(const char *path) {
    pid_t pid = fork();
    if (pid < 0) return -1;

    if (pid == 0) {
        execlp("gzip", "gzip", "-f", path, (char *)NULL);
        _exit(127);
    }

    int status;
    if (waitpid(pid, &status, 0) < 0) return -1;
    return (WIFEXITED(status) && WEXITSTATUS(status) == 0) ? 0 : -1;
}

static int rotate_log(daemon_state_t *st) {
    char rotated[MAX_PATH_LEN];

    safe_close(st->log_fd);
    st->log_fd = -1;

    if (shift_backups(&st->cfg) < 0) {
        return -1;
    }

    snprintf(rotated, sizeof(rotated), "%s.1", st->cfg.log_path);
    if (rename_rotate(st->cfg.log_path, rotated) < 0) {
        return -1;
    }

    if (st->cfg.compress) {
        if (compress_file_external(rotated) < 0) {
            /* compression failure is non-fatal */
        }
    }

    st->log_fd = open_log_append(st->cfg.log_path);
    if (st->log_fd < 0) return -1;

    st->last_rotate = time(NULL);
    return 0;
}

static int should_rotate(const daemon_state_t *st) {
    struct stat stbuf;
    if (stat(st->cfg.log_path, &stbuf) < 0) {
        return 0; /* log may not exist yet */
    }

    if ((size_t)stbuf.st_size >= st->cfg.max_size) {
        return 1;
    }

    if (st->cfg.interval_sec > 0) {
        time_t now = time(NULL);
        if (now != (time_t)-1 && (unsigned)(now - st->last_rotate) >= st->cfg.interval_sec) {
            return 1;
        }
    }

    return 0;
}

static void on_signal(int sig) {
    (void)sig;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    if (argc < 4) {
        fprintf(stderr,
            "Usage: %s <log_path> <max_size_bytes> <interval_sec> [max_backups] [compress]\n",
            argv[0]);
        return -1;
    }

    memset(cfg, 0, sizeof(*cfg));
    strncpy(cfg->log_path, argv[1], sizeof(cfg->log_path) - 1);
    cfg->max_size = (size_t)strtoull(argv[2], NULL, 10);
    cfg->interval_sec = (unsigned)strtoul(argv[3], NULL, 10);
    cfg->max_backups = (argc >= 5) ? (unsigned)strtoul(argv[4], NULL, 10) : MAX_BACKUPS;
    cfg->compress = (argc >= 6) ? atoi(argv[5]) : 0;

    if (cfg->max_backups == 0) cfg->max_backups = 1;
    if (cfg->max_backups > MAX_BACKUPS) cfg->max_backups = MAX_BACKUPS;
    if (cfg->max_size == 0) {
        fprintf(stderr, "max_size_bytes must be > 0\n");
        return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    daemon_state_t st;
    memset(&st, 0, sizeof(st));
    st.log_fd = -1;

    if (parse_args(argc, argv, &st.cfg) < 0) {
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    st.log_fd = open_log_append(st.cfg.log_path);
    if (st.log_fd < 0) {
        perror("open log");
        return 1;
    }

    st.last_rotate = time(NULL);

    char buf[IO_BUF_SIZE];

    while (!st.stop) {
        if (should_rotate(&st)) {
            if (rotate_log(&st) < 0) {
                perror("rotate_log");
                sleep(1);
                continue;
            }
        }

        /* In a real daemon, you would tail input from stdin, socket, or pipe.
           Here we just sleep to keep the process alive with low overhead. */
        ssize_t r = read(STDIN_FILENO, buf, sizeof(buf));
        if (r > 0) {
            ssize_t off = 0;
            while (off < r) {
                ssize_t w = write(st.log_fd, buf + off, (size_t)(r - off));
                if (w < 0) {
                    if (errno == EINTR) continue;
                    perror("write");
                    break;
                }
                off += w;
            }
        } else if (r == 0) {
            /* stdin closed; idle */
            sleep(1);
        } else {
            if (errno == EINTR) continue;
            perror("read");
            sleep(1);
        }
    }

    safe_close(st.log_fd);
    return 0;
}
