#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define LOGROTATE_SLEEP_SEC 1
#define IO_BUFSZ 4096

typedef struct {
    char log_path[PATH_MAX];
    size_t max_bytes;
    int max_backups;
    int poll_interval_sec;
} config_t;

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_size(const char *path, off_t *out_size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *out_size = st.st_size;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    // Remove the oldest backup if it exists.
    if (cfg->max_backups > 0) {
        if (safe_snprintf(dst, sizeof(dst), "%s.%d", cfg->log_path, cfg->max_backups) != 0)
            return -1;
        (void)unlink(dst);
    }

    // Shift backups: N-1 -> N, ..., 1 -> 2
    for (int i = cfg->max_backups - 1; i >= 1; --i) {
        if (safe_snprintf(src, sizeof(src), "%s.%d", cfg->log_path, i) != 0)
            return -1;
        if (safe_snprintf(dst, sizeof(dst), "%s.%d", cfg->log_path, i + 1) != 0)
            return -1;
        (void)rename(src, dst); // best effort
    }

    // Move current log to .1
    if (cfg->max_backups > 0) {
        if (safe_snprintf(dst, sizeof(dst), "%s.1", cfg->log_path) != 0)
            return -1;
        if (rename(cfg->log_path, dst) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    } else {
        (void)unlink(cfg->log_path);
    }

    return 0;
}

static int reopen_log(const char *path, int *fd_out) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    *fd_out = fd;
    return 0;
}

static int write_all(int fd, const void *buf, size_t len) {
    const uint8_t *p = (const uint8_t *)buf;
    while (len > 0) {
        ssize_t n = write(fd, p, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        p += (size_t)n;
        len -= (size_t)n;
    }
    return 0;
}

static void log_message(int fd, const char *msg) {
    char buf[IO_BUFSZ];
    time_t now = time(NULL);
    struct tm tmv;

    localtime_r(&now, &tmv);
    int n = snprintf(buf, sizeof(buf),
                     "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                     tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
                     tmv.tm_hour, tmv.tm_min, tmv.tm_sec, msg);
    if (n > 0 && (size_t)n < sizeof(buf)) {
        (void)write_all(fd, buf, (size_t)n);
    }
}

static void usage(const char *argv0) {
    fprintf(stderr,
            "Usage: %s <logfile> <max_bytes> <max_backups> [poll_interval_sec]\n"
            "Example: %s /var/log/app.log 10485760 5 1\n",
            argv0, argv0);
}

int main(int argc, char **argv) {
    config_t cfg;
    int fd = -1;

    if (argc < 4) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    memset(&cfg, 0, sizeof(cfg));
    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "Log path too long\n");
        return EXIT_FAILURE;
    }

    strncpy(cfg.log_path, argv[1], sizeof(cfg.log_path) - 1);
    cfg.max_bytes = (size_t)strtoull(argv[2], NULL, 10);
    cfg.max_backups = atoi(argv[3]);
    cfg.poll_interval_sec = (argc >= 5) ? atoi(argv[4]) : LOGROTATE_SLEEP_SEC;

    if (cfg.max_backups < 0 || cfg.poll_interval_sec <= 0) {
        fprintf(stderr, "Invalid arguments\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (reopen_log(cfg.log_path, &fd) != 0) {
        die("open log");
    }

    // Demo loop: in a real daemon, this would monitor external writes.
    // Here we periodically write a line and rotate if needed.
    while (!g_stop) {
        off_t sz = 0;
        if (file_size(cfg.log_path, &sz) == 0 && (size_t)sz >= cfg.max_bytes) {
            close(fd);
            fd = -1;

            if (rotate_logs(&cfg) != 0) {
                die("rotate_logs");
            }

            if (reopen_log(cfg.log_path, &fd) != 0) {
                die("reopen_log");
            }
        }

        log_message(fd, "heartbeat");
        fsync(fd);

        sleep((unsigned int)cfg.poll_interval_sec);
    }

    if (fd >= 0) close(fd);
    return EXIT_SUCCESS;
}
