#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>
#include <time.h>

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 256
#endif

#ifndef MAX_BACKUPS
#define MAX_BACKUPS 9
#endif

#ifndef POLL_SECONDS
#define POLL_SECONDS 5
#endif

#ifndef DEFAULT_MAX_SIZE
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024) /* 10 MiB */
#endif

static int rotate_logs(const char *logfile, int backups) {
    char oldname[MAX_PATH_LEN];
    char newname[MAX_PATH_LEN];

    if (backups < 1) return -1;
    if (backups > MAX_BACKUPS) backups = MAX_BACKUPS;

    /* Remove oldest backup */
    snprintf(oldname, sizeof(oldname), "%s.%d", logfile, backups);
    unlink(oldname);

    /* Shift backups up */
    for (int i = backups - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", logfile, i);
        snprintf(newname, sizeof(newname), "%s.%d", logfile, i + 1);
        if (rename(oldname, newname) != 0 && errno != ENOENT) {
            perror("rename");
            return -1;
        }
    }

    /* Rotate current log to .1 */
    snprintf(newname, sizeof(newname), "%s.1", logfile);
    if (rename(logfile, newname) != 0) {
        perror("rename active log");
        return -1;
    }

    /* Recreate empty active log */
    FILE *f = fopen(logfile, "w");
    if (!f) {
        perror("fopen recreate");
        return -1;
    }
    fclose(f);

    return 0;
}

static off_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> [max_size_bytes] [backups]\n"
        "  logfile            Path to log file to monitor\n"
        "  max_size_bytes      Rotate when size exceeds this (default %d)\n"
        "  backups            Number of rotated copies to keep (default 3, max %d)\n",
        prog, DEFAULT_MAX_SIZE, MAX_BACKUPS);
}

int main(int argc, char **argv) {
    const char *logfile;
    long max_size = DEFAULT_MAX_SIZE;
    int backups = 3;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];
    if (argc >= 3) {
        max_size = strtol(argv[2], NULL, 10);
        if (max_size <= 0) {
            fprintf(stderr, "Invalid max_size_bytes\n");
            return 1;
        }
    }
    if (argc >= 4) {
        backups = atoi(argv[3]);
        if (backups <= 0) {
            fprintf(stderr, "Invalid backups\n");
            return 1;
        }
        if (backups > MAX_BACKUPS) backups = MAX_BACKUPS;
    }

    /* Ensure log file exists */
    FILE *f = fopen(logfile, "a");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fclose(f);

    while (1) {
        off_t size = get_file_size(logfile);
        if (size < 0) {
            perror("stat");
            sleep(POLL_SECONDS);
            continue;
        }

        if (size > max_size) {
            if (rotate_logs(logfile, backups) != 0) {
                fprintf(stderr, "Rotation failed\n");
            } else {
                fprintf(stderr, "Rotated %s\n", logfile);
            }
        }

        sleep(POLL_SECONDS);
    }

    return 0;
}
