## `logrot.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <string.h>
#include <errno.h>

#define MAX_PATH_LEN 256
#define COPY_BUF_SIZE 4096

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int copy_file(const char *src, const char *dst) {
    int in = -1, out = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    in = open(src, O_RDONLY);
    if (in < 0) return -1;

    out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) {
        close(in);
        return -1;
    }

    while ((r = read(in, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in);
                close(out);
                return -1;
            }
            off += w;
        }
    }

    close(in);
    close(out);
    return (r < 0) ? -1 : 0;
}

static int rotate_logs(const char *logpath, int keep) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];
    int i;

    if (keep < 1) return -1;

    for (i = keep - 1; i >= 1; --i) {
        snprintf(oldp, sizeof(oldp), "%s.%d", logpath, i);
        snprintf(newp, sizeof(newp), "%s.%d", logpath, i + 1);

        if (file_exists(oldp)) {
            if (rename(oldp, newp) != 0) {
                return -1;
            }
        }
    }

    snprintf(newp, sizeof(newp), "%s.1", logpath);
    if (file_exists(logpath)) {
        if (rename(logpath, newp) != 0) {
            return -1;
        }
    }

    return 0;
}

static int ensure_logfile(const char *logpath) {
    int fd = open(logpath, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> <max_bytes> <keep>\n"
        "  logfile    path to active log file\n"
        "  max_bytes   rotate when size exceeds this value\n"
        "  keep        number of rotated files to keep\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logpath;
    off_t max_bytes;
    int keep;

    if (argc != 4) {
        usage(argv[0]);
        return 1;
    }

    logpath = argv[1];
    max_bytes = (off_t)atoll(argv[2]);
    keep = atoi(argv[3]);

    if (max_bytes <= 0 || keep <= 0) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(logpath) >= MAX_PATH_LEN - 8) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    if (ensure_logfile(logpath) != 0) {
        perror("ensure_logfile");
        return 1;
    }

    for (;;) {
        off_t sz = file_size(logpath);
        if (sz < 0) {
            perror("stat");
            sleep(1);
            continue;
        }

        if (sz > max_bytes) {
            if (rotate_logs(logpath, keep) != 0) {
                perror("rotate_logs");
                sleep(1);
                continue;
            }

            if (ensure_logfile(logpath) != 0) {
                perror("recreate logfile");
                sleep(1);
                continue;
            }
        }

        sleep(1);
    }

    return 0;
}
