#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/inotify.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <limits.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_WATCHES 32
#define EVENT_BUF_SIZE (4096)
#define NAME_MAX_LEN 255

static volatile sig_atomic_t running = 1;

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    umask(027);
    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > 2) close(fd);

    return 0;
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *sz = st.st_size;
    return 0;
}

static int rotate_file(const char *path, int generations) {
    char oldpath[PATH_MAX];
    char newpath[PATH_MAX];

    for (int i = generations - 1; i >= 1; --i) {
        snprintf(oldpath, sizeof(oldpath), "%s.%d", path, i);
        snprintf(newpath, sizeof(newpath), "%s.%d", path, i + 1);
        rename(oldpath, newpath); // ignore errors if missing
    }

    snprintf(newpath, sizeof(newpath), "%s.1", path);
    if (rename(path, newpath) < 0) {
        if (errno != ENOENT) return -1;
    }

    // Recreate empty log file
    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int watch_dir_for_file(int inofd, const char *dir, const char *filename) {
    int wd = inotify_add_watch(inofd, dir, IN_CREATE | IN_MOVED_TO | IN_CLOSE_WRITE);
    if (wd < 0) return -1;
    (void)filename;
    return wd;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_WRONLY, 0640);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

int main(int argc, char **argv) {
    const char *logpath = NULL;
    off_t max_size = 1024 * 1024;   // 1 MiB default
    int generations = 5;
    int interval_sec = 5;
    char dir[PATH_MAX];
    char base[NAME_MAX_LEN + 1];

    if (argc < 2) {
        fprintf(stderr, "Usage: %s /path/to/log [max_size_bytes] [generations]\n", argv[0]);
        return 1;
    }

    logpath = argv[1];
    if (argc >= 3) max_size = atoll(argv[2]);
    if (argc >= 4) generations = atoi(argv[3]);
    if (generations < 1) generations = 1;

    const char *slash = strrchr(logpath, '/');
    if (!slash) {
        strcpy(dir, ".");
        strncpy(base, logpath, NAME_MAX_LEN);
    } else {
        size_t dlen = (size_t)(slash - logpath);
        if (dlen >= sizeof(dir)) return 1;
        memcpy(dir, logpath, dlen);
        dir[dlen] = '\0';
        strncpy(base, slash + 1, NAME_MAX_LEN);
    }
    base[NAME_MAX_LEN] = '\0';

    if (ensure_log_exists(logpath) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (daemonize() < 0) {
        perror("daemonize");
        return 1;
    }

    signal(SIGTERM, on_signal);
    signal(SIGINT, on_signal);

    int inofd = inotify_init1(IN_NONBLOCK);
    if (inofd < 0) {
        perror("inotify_init1");
        return 1;
    }

    int wd = watch_dir_for_file(inofd, dir, base);
    if (wd < 0) {
        perror("inotify_add_watch");
        close(inofd);
        return 1;
    }

    char buf[EVENT_BUF_SIZE] __attribute__((aligned(__alignof__(struct inotify_event))));
    while (running) {
        ssize_t len = read(inofd, buf, sizeof(buf));
        if (len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                sleep(interval_sec);
                off_t sz;
                if (file_size(logpath, &sz) == 0 && sz >= max_size) {
                    rotate_file(logpath, generations);
                }
                continue;
            }
            if (errno == EINTR) continue;
            break;
        }

        ssize_t i = 0;
        while (i < len) {
            struct inotify_event *ev = (struct inotify_event *)&buf[i];
            if (ev->len > 0 && strcmp(ev->name, base) == 0) {
                off_t sz;
                if (file_size(logpath, &sz) == 0 && sz >= max_size) {
                    rotate_file(logpath, generations);
                }
            }
            i += sizeof(struct inotify_event) + ev->len;
        }
    }

    close(inofd);
    return 0;
}
