## `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_PATH_LEN   256
#define POLL_INTERVAL_S 1

typedef struct {
    char log_path[MAX_PATH_LEN];
    char rotated_path[MAX_PATH_LEN];
    size_t max_size;
    int max_backups;
} config_t;

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *arg, int idx) {
    int n = snprintf(dst, dstsz, fmt, arg, idx);
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int build_rotated_name(char *out, size_t outsz, const char *base, int idx) {
    if (idx == 0) {
        int n = snprintf(out, outsz, "%s", base);
        return (n < 0 || (size_t)n >= outsz) ? -1 : 0;
    }
    int n = snprintf(out, outsz, "%s.%d", base, idx);
    return (n < 0 || (size_t)n >= outsz) ? -1 : 0;
}

static off_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rotate_logs(const config_t *cfg) {
    char src[MAX_PATH_LEN];
    char dst[MAX_PATH_LEN];

    // Remove oldest backup
    if (cfg->max_backups > 0) {
        if (build_rotated_name(dst, sizeof(dst), cfg->log_path, cfg->max_backups) != 0) {
            return -1;
        }
        unlink(dst);
    }

    // Shift backups upward: log.(n-1) -> log.n
    for (int i = cfg->max_backups - 1; i >= 1; --i) {
        if (build_rotated_name(src, sizeof(src), cfg->log_path, i) != 0) return -1;
        if (build_rotated_name(dst, sizeof(dst), cfg->log_path, i + 1) != 0) return -1;
        rename(src, dst); // ignore errors if source doesn't exist
    }

    // Rotate current log -> log.1
    if (build_rotated_name(dst, sizeof(dst), cfg->log_path, 1) != 0) return -1;
    if (rename(cfg->log_path, dst) != 0) {
        // If log doesn't exist, nothing to rotate
        if (errno == ENOENT) return 0;
        return -1;
    }

    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int parse_size(const char *s, size_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) return -1;
    if (*end == 'K' || *end == 'k') v *= 1024ULL;
    else if (*end == 'M' || *end == 'm') v *= 1024ULL * 1024ULL;
    else if (*end == 'G' || *end == 'g') v *= 1024ULL * 1024ULL * 1024ULL;
    else if (*end != '\0') return -1;
    if (v > SIZE_MAX) return -1;
    *out = (size_t)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> <max_size> <max_backups>\n"
        "  max_size examples: 1048576, 10M, 512K\n"
        "  max_backups: number of rotated copies to keep\n",
        prog);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        usage(argv[0]);
        return 1;
    }

    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    if (strlen(argv[1]) >= MAX_PATH_LEN) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }

    strncpy(cfg.log_path, argv[1], sizeof(cfg.log_path) - 1);

    if (parse_size(argv[2], &cfg.max_size) != 0) {
        fprintf(stderr, "invalid max_size\n");
        return 1;
    }

    cfg.max_backups = atoi(argv[3]);
    if (cfg.max_backups < 1 || cfg.max_backups > 1000) {
        fprintf(stderr, "invalid max_backups\n");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) != 0) {
        perror("ensure_log_exists");
        return 1;
    }

    for (;;) {
        off_t sz = get_file_size(cfg.log_path);
        if (sz < 0) {
            // file may be temporarily missing; retry
            sleep(POLL_INTERVAL_S);
            continue;
        }

        if ((size_t)sz >= cfg.max_size) {
            if (rotate_logs(&cfg) != 0) {
                perror("rotate_logs");
            }
            ensure_log_exists(cfg.log_path);
        }

        sleep(POLL_INTERVAL_S);
    }

    return 0;
}
