## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PATH 256
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)  // 10 MiB
#define DEFAULT_CHECK_MS 1000                // 1 second
#define DEFAULT_KEEP 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int rotate_logs(const char *logpath, int keep) {
    char oldpath[MAX_PATH];
    char newpath[MAX_PATH];

    // Shift: logfile.(keep-1) -> logfile.keep, ... logfile -> logfile.1
    for (int i = keep - 1; i >= 1; --i) {
        snprintf(oldpath, sizeof(oldpath), "%s.%d", logpath, i);
        snprintf(newpath, sizeof(newpath), "%s.%d", logpath, i + 1);
        rename(oldpath, newpath); // ignore errors for missing files
    }

    snprintf(newpath, sizeof(newpath), "%s.1", logpath);
    if (rename(logpath, newpath) != 0) {
        return -1;
    }

    return 0;
}

static int reopen_log(const char *logpath) {
    int fd = open(logpath, O_WRONLY | O_CREAT | O_APPEND, 0644);
    return fd;
}

int main(int argc, char **argv) {
    const char *logpath = NULL;
    unsigned long max_size = DEFAULT_MAX_SIZE;
    int keep = DEFAULT_KEEP;
    int check_ms = DEFAULT_CHECK_MS;
    rlim_t mem_limit = 16 * 1024 * 1024; // 16 MiB default
    int fd = -1;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <logfile> [max_size_bytes] [keep] [check_ms] [mem_limit_bytes]\n", argv[0]);
        return 1;
    }

    logpath = argv[1];
    if (argc > 2) max_size = strtoul(argv[2], NULL, 10);
    if (argc > 3) keep = atoi(argv[3]);
    if (argc > 4) check_ms = atoi(argv[4]);
    if (argc > 5) mem_limit = (rlim_t)strtoull(argv[5], NULL, 10);

    if (keep < 1) keep = 1;
    if (check_ms < 10) check_ms = 10;

    if (set_memory_limit(mem_limit) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        // continue anyway
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    fd = reopen_log(logpath);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    while (!g_stop) {
        struct stat st;
        struct pollfd pfd;

        if (fstat(fd, &st) != 0) {
            perror("fstat");
            break;
        }

        if ((unsigned long)st.st_size >= max_size) {
            close(fd);
            fd = -1;

            if (rotate_logs(logpath, keep) != 0) {
                perror("rotate_logs");
                // try reopening original log to continue
            }

            fd = reopen_log(logpath);
            if (fd < 0) {
                perror("reopen_log");
                break;
            }
        }

        pfd.fd = -1;
        pfd.events = 0;
        (void)poll(&pfd, 0, check_ms);
    }

    if (fd >= 0) close(fd);
    return 0;
}
