#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_PATH_LEN 256
#define BACKUP_COUNT 5
#define CHECK_INTERVAL_SEC 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    int n;
    va_start(ap, fmt);
    n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int rotate_logs(const char *logfile) {
    char oldpath[MAX_PATH_LEN];
    char newpath[MAX_PATH_LEN];

    // Remove oldest
    if (safe_snprintf(oldpath, sizeof(oldpath), "%s.%d", logfile, BACKUP_COUNT) < 0)
        return -1;
    unlink(oldpath);

    // Shift backups
    for (int i = BACKUP_COUNT - 1; i >= 1; --i) {
        if (safe_snprintf(oldpath, sizeof(oldpath), "%s.%d", logfile, i) < 0)
            return -1;
        if (safe_snprintf(newpath, sizeof(newpath), "%s.%d", logfile, i + 1) < 0)
            return -1;
        rename(oldpath, newpath); // ignore errors if missing
    }

    // Rename active log to .1
    if (safe_snprintf(newpath, sizeof(newpath), "%s.1", logfile) < 0)
        return -1;
    if (rename(logfile, newpath) < 0 && errno != ENOENT) {
        return -1;
    }

    return 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    return st.st_size;
}

static void set_strict_limits(void) {
    struct rlimit rl;

    // Limit address space to 16 MB
    rl.rlim_cur = rl.rlim_max = 16 * 1024 * 1024;
    setrlimit(RLIMIT_AS, &rl);

    // Limit file size of any process-created file to 100 MB
    rl.rlim_cur = rl.rlim_max = 100 * 1024 * 1024;
    setrlimit(RLIMIT_FSIZE, &rl);

    // Limit number of open file descriptors
    rl.rlim_cur = rl.rlim_max = 16;
    setrlimit(RLIMIT_NOFILE, &rl);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_size;
    struct sigaction sa;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <max_size_bytes>\n", argv[0]);
        return 1;
    }

    logfile = argv[1];
    max_size = (off_t)atoll(argv[2]);
    if (max_size <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    set_strict_limits();

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!g_stop) {
        off_t sz = file_size(logfile);
        if (sz > max_size) {
            if (rotate_logs(logfile) < 0) {
                fprintf(stderr, "Rotation failed: %s\n", strerror(errno));
            }
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    return 0;
}
