## `logrotate_min.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_PATH_LEN 256
#define MAX_BACKUPS 5

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *base_path) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];
    int i;

    for (i = MAX_BACKUPS - 1; i >= 1; --i) {
        int n1 = snprintf(old_path, sizeof(old_path), "%s.%d", base_path, i);
        int n2 = snprintf(new_path, sizeof(new_path), "%s.%d", base_path, i + 1);

        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(old_path) || n2 >= (int)sizeof(new_path))
            return -1;

        if (access(old_path, F_OK) == 0) {
            if (rename(old_path, new_path) != 0 && errno != ENOENT) return -1;
        }
    }

    {
        int n1 = snprintf(old_path, sizeof(old_path), "%s", base_path);
        int n2 = snprintf(new_path, sizeof(new_path), "%s.1", base_path);

        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(old_path) || n2 >= (int)sizeof(new_path))
            return -1;

        if (access(old_path, F_OK) == 0) {
            if (rename(old_path, new_path) != 0) return -1;
        }
    }

    return 0;
}

static int reopen_log(const char *path, int *fd_out) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    *fd_out = fd;
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_size;
    int fd = -1;
    struct sigaction sa;
    char buf[512];
    ssize_t r;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <max_bytes>\n", argv[0]);
        return 1;
    }

    log_path = argv[1];
    max_size = (off_t)strtoll(argv[2], NULL, 10);
    if (max_size <= 0) {
        fprintf(stderr, "Invalid max_bytes\n");
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (reopen_log(log_path, &fd) != 0) {
        perror("open");
        return 1;
    }

    while (g_running) {
        off_t sz;

        if (file_size(log_path, &sz) == 0 && sz >= max_size) {
            close(fd);
            fd = -1;

            if (rotate_logs(log_path) != 0) {
                perror("rotate");
                break;
            }

            if (reopen_log(log_path, &fd) != 0) {
                perror("reopen");
                break;
            }
        }

        r = read(STDIN_FILENO, buf, sizeof(buf));
        if (r < 0) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (r == 0) {
            usleep(100000); // idle poll
            continue;
        }

        if (write(fd, buf, (size_t)r) != r) {
            perror("write");
            break;
        }
    }

    if (fd >= 0) close(fd);
    return 0;
}
