## `logrotate_min.c`

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#ifndef MAX_PATH
#define MAX_PATH 256
#endif

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *path, int keep) {
    char oldname[MAX_PATH];
    char newname[MAX_PATH];

    // Delete oldest
    snprintf(oldname, sizeof(oldname), "%s.%d", path, keep);
    unlink(oldname);

    // Shift rotated files
    for (int i = keep - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", path, i);
        snprintf(newname, sizeof(newname), "%s.%d", path, i + 1);
        if (rename(oldname, newname) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    // Rotate current log to .1
    snprintf(newname, sizeof(newname), "%s.1", path);
    if (rename(path, newname) != 0) {
        return -1;
    }

    // Recreate empty log file
    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    if (setsid() < 0) exit(1);

    pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    umask(022);
    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main(int argc, char **argv) {
    const char *logpath;
    off_t max_bytes = 1024 * 1024;   // 1 MiB default
    int keep = 5;                    // keep 5 rotated logs
    int interval_sec = 5;            // check every 5 seconds
    int opt;

    while ((opt = getopt(argc, argv, "s:k:i:d")) != -1) {
        switch (opt) {
        case 's':
            max_bytes = atoll(optarg);
            break;
        case 'k':
            keep = atoi(optarg);
            break;
        case 'i':
            interval_sec = atoi(optarg);
            break;
        case 'd':
            // daemon mode enabled
            break;
        default:
            fprintf(stderr, "Usage: %s [-d] [-s size_bytes] [-k keep] [-i interval] logfile\n", argv[0]);
            return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Usage: %s [-d] [-s size_bytes] [-k keep] [-i interval] logfile\n", argv[0]);
        return 1;
    }

    logpath = argv[optind];

    if (keep < 1) keep = 1;
    if (interval_sec < 1) interval_sec = 1;

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (argc > 1 && memchr(argv[1], 'd', 2)) {
        daemonize();
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(logpath, &sz) == 0 && sz >= max_bytes) {
            if (rotate_logs(logpath, keep) != 0) {
                // In a real daemon, log this somewhere; here we just continue.
            }
        }
        sleep((unsigned)interval_sec);
    }

    return 0;
}
