use anyhow::{Context, Result};
use clap::Parser;
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    time::Duration,
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Parser, Debug)]
#[command(name = "resource-daemon")]
#[command(about = "High-performance OS resource monitoring daemon", long_about = None)]
struct Args {
    /// Path to configuration file
    #[arg(short, long, default_value = "/etc/resource-daemon.toml")]
    config: PathBuf,
}

#[derive(Debug, Deserialize, Clone)]
struct Config {
    /// Poll interval in seconds
    poll_interval_secs: u64,

    /// CPU usage threshold percentage
    cpu_threshold: f32,

    /// Memory usage threshold percentage
    memory_threshold: f32,

    /// Disk usage threshold percentage
    disk_threshold: f32,

    /// Optional action: log only, or attempt process cleanup
    action_mode: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_secs: 5,
            cpu_threshold: 85.0,
            memory_threshold: 90.0,
            disk_threshold: 90.0,
            action_mode: "log".to_string(),
        }
    }
}

impl Config {
    fn load(path: &PathBuf) -> Result<Self> {
        if !path.exists() {
            return Ok(Self::default());
        }

        let content = fs::read_to_string(path)
            .with_context(|| format!("failed to read config file: {}", path.display()))?;
        let cfg: Self = toml::from_str(&content)
            .with_context(|| format!("failed to parse config file: {}", path.display()))?;
        Ok(cfg)
    }
}

#[derive(Debug)]
struct Metrics {
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
}

struct ResourceMonitor {
    system: System,
}

impl ResourceMonitor {
    fn new() -> Self {
        let system = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory(MemoryRefreshKind::everything())
                .with_disks(DiskRefreshKind::everything()),
        );
        Self { system }
    }

    fn refresh(&mut self) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
    }

    fn collect(&self) -> Metrics {
        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_usage = 0.0f32;
        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - avail) / total) * 100.0;
                if used > disk_usage {
                    disk_usage = used;
                }
            }
        }

        let load = System::load_average();

        Metrics {
            cpu_usage,
            memory_usage,
            disk_usage,
            load_avg_1: load.one,
            load_avg_5: load.five,
            load_avg_15: load.fifteen,
        }
    }
}

async fn manage_resources(cfg: &Config, metrics: &Metrics) {
    if metrics.cpu_usage > cfg.cpu_threshold {
        warn!(
            cpu = metrics.cpu_usage,
            threshold = cfg.cpu_threshold,
            "CPU usage threshold exceeded"
        );
    }

    if metrics.memory_usage > cfg.memory_threshold {
        warn!(
            memory = metrics.memory_usage,
            threshold = cfg.memory_threshold,
            "Memory usage threshold exceeded"
        );
    }

    if metrics.disk_usage > cfg.disk_threshold {
        warn!(
            disk = metrics.disk_usage,
            threshold = cfg.disk_threshold,
            "Disk usage threshold exceeded"
        );
    }

    if cfg.action_mode == "cleanup" {
        // Placeholder for safe management actions.
        // In production, you might:
        // - signal low-priority processes
        // - rotate logs
        // - clear caches with strict controls
        // - notify orchestration systems
        info!("cleanup mode enabled, but no destructive action implemented");
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let args = Args::parse();
    let cfg = Config::load(&args.config)?;

    info!(?cfg, "starting resource daemon");

    let mut monitor = ResourceMonitor::new();
    let mut ticker = interval(Duration::from_secs(cfg.poll_interval_secs));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                monitor.refresh();
                let metrics = monitor.collect();

                info!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    disk = metrics.disk_usage,
                    load1 = metrics.load_avg_1,
                    load5 = metrics.load_avg_5,
                    load15 = metrics.load_avg_15,
                    "resource metrics"
                );

                manage_resources(&cfg, &metrics).await;
            }

            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}
