    pid: i32,
    name: String,
    cpu_usage: f32,
    memory: u64,
}

struct DaemonState {
    config: RwLock<Config>,
    system: RwLock<System>,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    let config = load_config(&args.config).unwrap_or_else(|e| {
        eprintln!("Failed to load config, using defaults: {e:#}");
        Config::default()
    });

    init_logging(config.log_level.as_deref().unwrap_or("info"));

    info!("Starting daemon");

    let state = Arc::new(DaemonState {
        config: RwLock::new(config),
        system: RwLock::new(System::new_all()),
    });

    let monitor_state = state.clone();
    let config_path = args.config.clone();

    tokio::spawn(async move {
        config_watcher_task(monitor_state, config_path).await;
    });

    monitor_loop(state).await
}

fn init_logging(level: &str) {
    let filter = tracing_subscriber::EnvFilter::try_new(level)
        .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info"));

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

fn load_config(path: &PathBuf) -> Result<Config> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("reading config file {}", path.display()))?;
    let cfg: Config = toml::from_str(&raw).context("parsing TOML config")?;
    Ok(cfg)
}

async fn config_watcher_task(state: Arc<DaemonState>, path: PathBuf) {
    let mut last_modified = None;

    loop {
        match fs::metadata(&path).and_then(|m| m.modified()) {
            Ok(modified) => {
                let changed = last_modified.map_or(true, |prev| prev != modified);
                if changed {
                    match load_config(&path) {
                        Ok(cfg) => {
                            info!("Reloaded config");
                            *state.config.write().await = cfg;
                            last_modified = Some(modified);
                        }
                        Err(e) => warn!("Failed to reload config: {e:#}"),
                    }
                }
            }
            Err(e) => debug!("Config watcher metadata error: {e}"),
        }

        tokio::time::sleep(Duration::from_secs(5)).await;
    }
}

async fn monitor_loop(state: Arc<DaemonState>) -> Result<()> {
    let poll_ms = {
        let cfg = state.config.read().await;
        cfg.poll_interval_ms
    };

    let mut ticker = interval(Duration::from_millis(poll_ms));

    loop {
        ticker.tick().await;

        let cfg = state.config.read().await.clone();
        let snapshot = collect_metrics(&state).await?;

        emit_metrics(&snapshot);

        if cfg.enable_actions {
            evaluate_and_act(&cfg, &snapshot).await;
        }

        // Re-read interval dynamically in case config changed
        let new_poll_ms = state.config.read().await.poll_interval_ms;
        if new_poll_ms != poll_ms {
            ticker = interval(Duration::from_millis(new_poll_ms));
        }
    }
}

async fn collect_metrics(state: &Arc<DaemonState>) -> Result<MetricsSnapshot> {
    let mut system = state.system.write().await;
    system.refresh_all();

    let cpu_usage_avg = system.global_cpu_info().cpu_usage();

    let memory_total = system.total_memory();
    let memory_used = system.used_memory();
    let memory_usage_pct = if memory_total > 0 {
        (memory_used as f32 / memory_total as f32) * 100.0
    } else {
        0.0
    };

    let disks = system.disks();
    let disk_total: u64 = disks.iter().map(|d| d.total_space()).sum();
    let disk_used: u64 = disks
        .iter()
        .map(|d| d.total_space().saturating_sub(d.available_space()))
        .sum();
    let disk_usage_pct = if disk_total > 0 {
        (disk_used as f32 / disk_total as f32) * 100.0
    } else {
        0.0
    };

    let load = System::load_average();

    let mut procs: Vec<ProcessSnapshot> = system
        .processes()
        .iter()
        .map(|(pid, p)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage: p.cpu_usage(),
            memory: p.memory(),
        })
        .collect();

    procs.sort_by(|a, b| b.cpu_usage.partial_cmp(&a.cpu_usage).unwrap_or(std::cmp::Ordering::Equal));
    procs.truncate(state.config.read().await.max_processes_to_report);

    Ok(MetricsSnapshot {
        cpu_usage_avg,
        memory_total,
        memory_used,
        memory_usage_pct,
        disk_total,
        disk_used,
        disk_usage_pct,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        top_processes: procs,
    })
}

fn emit_metrics(snapshot: &MetricsSnapshot) {
    match serde_json::to_string(snapshot) {
        Ok(json) => info!(metrics = %json, "resource snapshot"),
        Err(e) => error!("failed to serialize metrics: {e}"),
    }
}

async fn evaluate_and_act(cfg: &Config, snapshot: &MetricsSnapshot) {
    if snapshot.cpu_usage_avg > cfg.cpu_high_watermark {
        warn!(
            cpu = snapshot.cpu_usage_avg,
            threshold = cfg.cpu_high_watermark,
            "CPU usage high"
        );
        // TODO: implement policy action such as process prioritization, alerting, or throttling.
    }

    if snapshot.memory_usage_pct > cfg.mem_high_watermark {
        warn!(
            memory = snapshot.memory_usage_pct,
            threshold = cfg.mem_high_watermark,
            "Memory usage high"
        );
    }

    if snapshot.disk_usage_pct > cfg.disk_high_watermark {
        warn!(
            disk = snapshot.disk_usage_pct,
            threshold = cfg.disk_high_watermark,
            "Disk usage high"
        );
    }

    // Example Unix-specific process management hook
    #[cfg(unix)]
    {
        use nix::sys::signal::{kill, Signal};
        use nix::unistd::Pid;

        for p in &snapshot.top_processes {
            if p.cpu_usage > cfg.cpu_high_watermark + 20.0 {
                warn!(pid = p.pid, cpu = p.cpu_usage, "considering process signal");
                if false {
                    // Disabled by default: safe placeholder
                    let _ = kill(Pid::from_raw(p.pid), Signal::SIGTERM);
                }
            }
        }
    }
}
