use anyhow::Result;
use dashmap::DashMap;
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    fs,
    path::PathBuf,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, Networks, ProcessRefreshKind, RefreshKind, System};
use tokio::{signal, task, time};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    process_cpu_warn_pct: f32,
    process_mem_warn_mb: u64,
    max_history: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            process_cpu_warn_pct: 50.0,
            process_mem_warn_mb: 1024,
            max_history: 60,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_ms: u128,
    global_cpu_pct: f32,
    memory_used_pct: f32,
    swap_used_pct: f32,
    disks: Vec<DiskSnapshot>,
    processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    mount_point: String,
    used_pct: f32,
    total_bytes: u64,
    used_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_pct: f32,
    memory_mb: u64,
}

struct State {
    history: parking_lot::Mutex<VecDeque<SystemSnapshot>>,
    latest: parking_lot::Mutex<Option<SystemSnapshot>>,
    stop: AtomicBool,
    config: Config,
    alerts: DashMap<String, Instant>,
}

impl State {
    fn new(config: Config) -> Self {
        Self {
            history: parking_lot::Mutex::new(VecDeque::with_capacity(config.max_history)),
            latest: parking_lot::Mutex::new(None),
            stop: AtomicBool::new(false),
            config,
            alerts: DashMap::new(),
        }
    }

    fn push_snapshot(&self, snapshot: SystemSnapshot) {
        {
            let mut latest = self.latest.lock();
            *latest = Some(snapshot.clone());
        }

        let mut history = self.history.lock();
        if history.len() >= self.config.max_history {
            history.pop_front();
        }
        history.push_back(snapshot);
    }

    fn should_rate_limit(&self, key: &str, cooldown: Duration) -> bool {
        let now = Instant::now();
        if let Some(mut entry) = self.alerts.get_mut(key) {
            if now.duration_since(*entry) < cooldown {
                return true;
            }
            *entry = now;
            false
        } else {
            self.alerts.insert(key.to_string(), now);
            false
        }
    }
}

fn load_config() -> Config {
    let path = PathBuf::from("resource_daemon.json");
    match fs::read_to_string(&path) {
        Ok(contents) => serde_json::from_str(&contents).unwrap_or_default(),
        Err(_) => Config::default(),
    }
}

fn build_system() -> System {
    System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    )
}

fn sample_system(system: &mut System, disks: &mut Disks, _networks: &mut Networks) -> SystemSnapshot {
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_processes();
    disks.refresh();

    let timestamp_ms = Instant::now().elapsed().as_millis();

    let global_cpu_pct = system.global_cpu_usage();
    let total_mem = system.total_memory() as f32;
    let used_mem = system.used_memory() as f32;
    let memory_used_pct = if total_mem > 0.0 { used_mem * 100.0 / total_mem } else { 0.0 };

    let total_swap = system.total_swap() as f32;
    let used_swap = system.used_swap() as f32;
    let swap_used_pct = if total_swap > 0.0 { used_swap * 100.0 / total_swap } else { 0.0 };

    let disks_vec = disks
        .list()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_pct = if total > 0 {
                used as f32 * 100.0 / total as f32
            } else {
                0.0
            };

            DiskSnapshot {
                mount_point: d.mount_point().to_string_lossy().to_string(),
                used_pct,
                total_bytes: total,
                used_bytes: used,
            }
        })
        .collect::<Vec<_>>();

    let processes = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: proc_.name().to_string(),
            cpu_pct: proc_.cpu_usage(),
            memory_mb: proc_.memory() / 1024,
        })
        .collect::<Vec<_>>();

    SystemSnapshot {
        timestamp_ms,
        global_cpu_pct,
        memory_used_pct,
        swap_used_pct,
        disks: disks_vec,
        processes,
    }
}

fn evaluate_rules(state: &Arc<State>, snapshot: &SystemSnapshot) {
    let cfg = &state.config;

    if snapshot.global_cpu_pct >= cfg.cpu_warn_pct {
        if !state.should_rate_limit("cpu_warn", Duration::from_secs(10)) {
            warn!(
                cpu = snapshot.global_cpu_pct,
                threshold = cfg.cpu_warn_pct,
                "High CPU usage detected"
            );
        }
    }

    if snapshot.memory_used_pct >= cfg.mem_warn_pct {
        if !state.should_rate_limit("mem_warn", Duration::from_secs(10)) {
            warn!(
                memory = snapshot.memory_used_pct,
                threshold = cfg.mem_warn_pct,
                "High memory usage detected"
            );
        }
    }

    for disk in &snapshot.disks {
        if disk.used_pct >= cfg.disk_warn_pct {
            let key = format!("disk_warn:{}", disk.mount_point);
            if !state.should_rate_limit(&key, Duration::from_secs(30)) {
                warn!(
                    mount = %disk.mount_point,
                    used = disk.used_pct,
                    threshold = cfg.disk_warn_pct,
                    "Disk usage threshold exceeded"
                );
            }
        }
    }

    for proc_ in &snapshot.processes {
        if proc_.cpu_pct >= cfg.process_cpu_warn_pct {
            let key = format!("proc_cpu_warn:{}", proc_.pid);
            if !state.should_rate_limit(&key, Duration::from_secs(15)) {
                warn!(
                    pid = proc_.pid,
                    name = %proc_.name,
                    cpu = proc_.cpu_pct,
                    threshold = cfg.process_cpu_warn_pct,
                    "Process CPU usage high"
                );
            }
        }

        if proc_.memory_mb >= cfg.process_mem_warn_mb {
            let key = format!("proc_mem_warn:{}", proc_.pid);
            if !state.should_rate_limit(&key, Duration::from_secs(15)) {
                warn!(
                    pid = proc_.pid,
                    name = %proc_.name,
                    memory_mb = proc_.memory_mb,
                    threshold_mb = cfg.process_mem_warn_mb,
                    "Process memory usage high"
                );
            }
        }
    }
}

async fn monitor_loop(state: Arc<State>) -> Result<()> {
    let mut system = build_system();
    let mut disks = Disks::new_with_refreshed_list();
    let mut networks = Networks::new_with_refreshed_list();

    let interval = Duration::from_millis(state.config.sample_interval_ms);
    let mut ticker = time::interval(interval);
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Delay);

    loop {
        ticker.tick().await;

        if state.stop.load(Ordering::Relaxed) {
            break;
        }

        let state_clone = state.clone();
        let snapshot = task::spawn_blocking(move || {
            let mut system = system;
            let mut disks = disks;
            let mut networks = networks;
            sample_system(&mut system, &mut disks, &mut networks)
        })
        .await?;

        state.push_snapshot(snapshot.clone());
        evaluate_rules(&state_clone, &snapshot);

        debug!("sample collected");
    }

    Ok(())
}

async fn shutdown_signal() -> Result<()> {
    signal::ctrl_c().await?;
    Ok(())
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let config = load_config();
    info!(?config, "starting resource daemon");

    let state = Arc::new(State::new(config));

    let monitor = {
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = monitor_loop(state).await {
                error!(error = %e, "monitor loop failed");
            }
        })
    };

    tokio::select! {
        _ = shutdown_signal() => {
            info!("shutdown signal received");
        }
        _ = monitor => {
            warn!("monitor task exited");
        }
    }

    state.stop.store(true, Ordering::Relaxed);
    info!("resource daemon stopped");
    Ok(())
}
