```rust
use anyhow::Result;
use serde::Serialize;
use std::{
    sync::{Arc, RwLock},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
    time,
};
use tracing::{error, info};

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    timestamp: u64,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    cpu_usage_percent: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks: Vec<DiskMetric>,
    top_processes: Vec<ProcessMetric>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskMetric {
    name: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessMetric {
    pid: i32,
    name: String,
    cpu_usage: f32,
    memory_kb: u64,
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn collect_metrics(sys: &mut System) -> Metrics {
    sys.refresh_all();

    let cpu_usage_percent = sys.global_cpu_info().cpu_usage();
    let load = System::load_average();

    let disks = sys
        .disks()
        .iter()
        .map(|d| DiskMetric {
            name: d.name().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).to_string(),
        })
        .collect::<Vec<_>>();

    let mut processes = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessMetric {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage: p.cpu_usage(),
            memory_kb: p.memory(),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| b.cpu_usage.partial_cmp(&a.cpu_usage).unwrap());
    processes.truncate(10);

    Metrics {
        timestamp: now_unix(),
        total_memory_kb: sys.total_memory(),
        used_memory_kb: sys.used_memory(),
        total_swap_kb: sys.total_swap(),
        used_swap_kb: sys.used_swap(),
        cpu_usage_percent,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disks,
        top_processes: processes,
    }
}

async fn metrics_collector(state: Arc<RwLock<Metrics>>, interval: Duration) {
    let mut sys = System::new_all();
    let mut ticker = time::interval(interval);

    loop {
        ticker.tick().await;
        let metrics = collect_metrics(&mut sys);
        if let Ok(mut guard) = state.write() {
            *guard = metrics;
        }
    }
}

async fn handle_client(mut stream: TcpStream, state: Arc<RwLock<Metrics>>) -> Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;
    let req = String::from_utf8_lossy(&buf[..n]);

    // Simple protocol:
    // GET /metrics -> JSON metrics
    // GET /health  -> OK
    let response = if req.starts_with("GET /health") {
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\n\r\nOK".to_string()
    } else if req.starts_with("GET /metrics") {
        let metrics = state.read().map(|g| g.clone()).unwrap_or_default();
        let body = serde_json::to_string_pretty(&metrics)?;
        format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            body.len(),
            body
        )
    } else {
        "HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\n\r\nNot Found".to_string()
    };

    stream.write_all(response.as_bytes()).await?;
    stream.shutdown().await?;
    Ok(())
}

async fn server(state: Arc<RwLock<Metrics>>, addr: &str) -> Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("listening on {}", addr);

    loop {
        let (stream, peer) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client {} error: {}", peer, e);
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = Arc::new(RwLock::new(Metrics::default()));

    let collector_state = state.clone();
    tokio::spawn(async move {
        metrics_collector(collector_state, Duration::from_secs(1)).await;
    });

    server(state, "127.0.0.1:8080").await
}
