use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::Deserialize;
use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader};
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    interval_ms: u64,
    cpu_warn_pct: f64,
    mem_warn_pct: f64,
    disk_warn_pct: f64,
    load_warn_per_cpu: f64,

    // Optional remediation
    kill_process_name_on_critical_mem: Option<String>,
    critical_mem_pct: Option<f64>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            interval_ms: 1000,
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            load_warn_per_cpu: 1.5,
            kill_process_name_on_critical_mem: None,
            critical_mem_pct: Some(97.0),
        }
    }
}

#[derive(Debug, Clone)]
struct CpuSnapshot {
    total: u64,
    idle: u64,
}

#[derive(Debug)]
struct Stats {
    cpu_pct: f64,
    mem_pct: f64,
    disk_pct: f64,
    load1: f64,
    cpu_count: usize,
}

fn main() -> Result<()> {
    let config = load_config("sysd.toml").unwrap_or_else(|_| Config::default());

    println!("sysd starting with config: {:?}", config);

    let mut prev_cpu = read_cpu_snapshot().context("failed to read initial CPU snapshot")?;

    loop {
        let start = Instant::now();

        let curr_cpu = read_cpu_snapshot().context("failed to read CPU snapshot")?;
        let cpu_pct = compute_cpu_usage(&prev_cpu, &curr_cpu);
        prev_cpu = curr_cpu;

        let mem_pct = read_memory_usage().context("failed to read memory usage")?;
        let disk_pct = read_disk_usage("/").context("failed to read disk usage")?;
        let (load1, cpu_count) = read_loadavg_and_cpu_count().context("failed to read load average")?;

        let stats = Stats {
            cpu_pct,
            mem_pct,
            disk_pct,
            load1,
            cpu_count,
        };

        report_and_manage(&config, &stats)?;

        let elapsed = start.elapsed();
        let interval = Duration::from_millis(config.interval_ms);
        if elapsed < interval {
            thread::sleep(interval - elapsed);
        }
    }
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let data = fs::read_to_string(path)?;
    let cfg: Config = toml::from_str(&data)?;
    Ok(cfg)
}

fn read_cpu_snapshot() -> Result<CpuSnapshot> {
    let file = fs::File::open("/proc/stat")?;
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("cpu ") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            let mut vals = Vec::new();
            for p in parts.iter().skip(1) {
                vals.push(p.parse::<u64>()?);
            }

            let idle = vals.get(3).copied().unwrap_or(0) + vals.get(4).copied().unwrap_or(0);
            let total = vals.iter().sum();
            return Ok(CpuSnapshot { total, idle });
        }
    }

    anyhow::bail!("cpu line not found in /proc/stat");
}

fn compute_cpu_usage(prev: &CpuSnapshot, curr: &CpuSnapshot) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let busy = total_delta.saturating_sub(idle_delta);
    (busy as f64 / total_delta as f64) * 100.0
}

fn read_memory_usage() -> Result<f64> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut map = HashMap::<String, u64>::new();

    for line in content.lines() {
        let mut parts = line.split_whitespace();
        let key = parts.next().unwrap_or("").trim_end_matches(':').to_string();
        let val = parts.next().unwrap_or("0").parse::<u64>()?;
        map.insert(key, val);
    }

    let total = *map.get("MemTotal").context("MemTotal missing")?;
    let available = *map.get("MemAvailable").context("MemAvailable missing")?;

    let used = total.saturating_sub(available);
    Ok((used as f64 / total as f64) * 100.0)
}

fn read_disk_usage<P: AsRef<Path>>(path: P) -> Result<f64> {
    let output = Command::new("df")
        .arg("-P")
        .arg(path.as_ref())
        .output()
        .context("failed to run df")?;

    if !output.status.success() {
        anyhow::bail!("df failed");
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut lines = stdout.lines();
    lines.next(); // header
    let line = lines.next().context("df output missing data line")?;
    let fields: Vec<&str> = line.split_whitespace().collect();

    let use_pct = fields
        .get(4)
        .context("unexpected df format")?
        .trim_end_matches('%')
        .parse::<f64>()?;

    Ok(use_pct)
}

fn read_loadavg_and_cpu_count() -> Result<(f64, usize)> {
    let loadavg = fs::read_to_string("/proc/loadavg")?;
    let load1 = loadavg
        .split_whitespace()
        .next()
        .context("loadavg missing")?
        .parse::<f64>()?;

    let cpu_count = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);

    Ok((load1, cpu_count))
}

fn report_and_manage(config: &Config, stats: &Stats) -> Result<()> {
    let load_per_cpu = stats.load1 / stats.cpu_count as f64;

    println!(
        "cpu={:.1}% mem={:.1}% disk={:.1}% load1={:.2} load/cpu={:.2}",
        stats.cpu_pct, stats.mem_pct, stats.disk_pct, stats.load1, load_per_cpu
    );

    if stats.cpu_pct >= config.cpu_warn_pct {
        eprintln!("WARN: CPU usage high: {:.1}%", stats.cpu_pct);
    }

    if stats.mem_pct >= config.mem_warn_pct {
        eprintln!("WARN: Memory usage high: {:.1}%", stats.mem_pct);
    }

    if stats.disk_pct >= config.disk_warn_pct {
        eprintln!("WARN: Disk usage high: {:.1}%", stats.disk_pct);
    }

    if load_per_cpu >= config.load_warn_per_cpu {
        eprintln!(
            "WARN: Load average high: load1={:.2}, cpu_count={}, load/cpu={:.2}",
            stats.load1, stats.cpu_count, load_per_cpu
        );
    }

    if let (Some(proc_name), Some(crit_mem)) = (
        config.kill_process_name_on_critical_mem.as_ref(),
        config.critical_mem_pct,
    ) {
        if stats.mem_pct >= crit_mem {
            eprintln!(
                "CRITICAL: memory usage {:.1}% >= {:.1}%, attempting to kill process '{}'",
                stats.mem_pct, crit_mem, proc_name
            );
            kill_process_by_name(proc_name)?;
        }
    }

    Ok(())
}

fn kill_process_by_name(name: &str) -> Result<()> {
    let output = Command::new("pgrep")
        .arg("-x")
        .arg(name)
        .output()
        .context("failed to run pgrep")?;

    if !output.status.success() {
        eprintln!("No process named '{}' found", name);
        return Ok(());
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in stdout.lines() {
        if let Ok(pid_raw) = line.trim().parse::<i32>() {
            let pid = Pid::from_raw(pid_raw);
            match kill(pid, Signal::SIGTERM) {
                Ok(_) => eprintln!("Sent SIGTERM to {} (pid {})", name, pid_raw),
                Err(err) => eprintln!("Failed to kill pid {}: {}", pid_raw, err),
            }
        }
    }

    Ok(())
}
