```rust
use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, NetworkExt, NetworksExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
    net_warn_bytes_per_sec: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_warn_percent: 85.0,
            mem_warn_percent: 90.0,
            disk_warn_percent: 90.0,
            net_warn_bytes_per_sec: 50_000_000, // 50 MB/s
        }
    }
}

#[derive(Debug, Serialize)]
struct Metrics {
    cpu_usage_percent: f32,
    memory_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    disk_usage_percent: f32,
    total_disk: u64,
    used_disk: u64,
    network_rx_bytes: u64,
    network_tx_bytes: u64,
}

struct ResourceMonitor {
    sys: System,
    last_network_rx: u64,
    last_network_tx: u64,
}

impl ResourceMonitor {
    fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();

        let (rx, tx) = Self::network_totals(&sys);

        Self {
            sys,
            last_network_rx: rx,
            last_network_tx: tx,
        }
    }

    fn network_totals(sys: &System) -> (u64, u64) {
        let mut rx = 0;
        let mut tx = 0;

        for (_, data) in sys.networks() {
            rx += data.received();
            tx += data.transmitted();
        }

        (rx, tx)
    }

    fn sample(&mut self) -> Metrics {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_disks_list();
        self.sys.refresh_disks();
        self.sys.refresh_networks();

        let cpu_usage_percent = self.sys.global_cpu_info().cpu_usage();

        let total_memory = self.sys.total_memory();
        let used_memory = self.sys.used_memory();
        let memory_usage_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0;
        let mut used_disk = 0;

        for disk in self.sys.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            let used = total.saturating_sub(available);
            total_disk += total;
            used_disk += used;
        }

        let disk_usage_percent = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        let (rx, tx) = Self::network_totals(&self.sys);

        let network_rx_bytes = rx.saturating_sub(self.last_network_rx);
        let network_tx_bytes = tx.saturating_sub(self.last_network_tx);

        self.last_network_rx = rx;
        self.last_network_tx = tx;

        Metrics {
            cpu_usage_percent,
            memory_usage_percent,
            total_memory,
            used_memory,
            disk_usage_percent,
            total_disk,
            used_disk,
            network_rx_bytes,
            network_tx_bytes,
        }
    }
}

fn apply_management_policy(cfg: &Config, m: &Metrics) {
    if m.cpu_usage_percent >= cfg.cpu_warn_percent {
        warn!(
            cpu = m.cpu_usage_percent,
            threshold = cfg.cpu_warn_percent,
            "High CPU usage detected"
        );
    }

    if m.memory_usage_percent >= cfg.mem_warn_percent {
        warn!(
            memory = m.memory_usage_percent,
            threshold = cfg.mem_warn_percent,
            "High memory usage detected"
        );
    }

    if m.disk_usage_percent >= cfg.disk_warn_percent {
        warn!(
            disk = m.disk_usage_percent,
            threshold = cfg.disk_warn_percent,
            "High disk usage detected"
        );
    }

    let net_total = m.network_rx_bytes.saturating_add(m.network_tx_bytes);
    if net_total >= cfg.net_warn_bytes_per_sec {
        warn!(
            net_bytes_per_sample = net_total,
            threshold = cfg.net_warn_bytes_per_sec,
            "High network throughput detected"
        );
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = Config::default();
    info!(?cfg, "Starting resource daemon");

    let mut monitor = ResourceMonitor::new();
    let mut ticker = interval(Duration::from_millis(cfg.sample_interval_ms));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let metrics = monitor.sample();

                info!(
                    cpu = metrics.cpu_usage_percent,
                    memory = metrics.memory_usage_percent,
                    disk = metrics.disk_usage_percent,
                    rx_bytes = metrics.network_rx_bytes,
                    tx_bytes = metrics.network_tx_bytes,
                    "Resource sample"
                );

                apply_management_policy(&cfg, &metrics);
            }

            _ = signal::ctrl_c() => {
                info!("Shutdown signal received");
                break;
            }
        }
    }

    info!("Resource daemon stopped");
    Ok(())
}
