use anyhow::Result;
use serde::Serialize;
use std::time::{Duration, Instant};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Networks, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    swap_used_bytes: u64,
    swap_total_bytes: u64,
    disk_used_bytes: u64,
    disk_total_bytes: u64,
    network_received_bytes: u64,
    network_transmitted_bytes: u64,
}

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_warn: f32,
    memory_warn_ratio: f32,
    disk_warn_ratio: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_warn: 85.0,
            memory_warn_ratio: 0.90,
            disk_warn_ratio: 0.90,
        }
    }
}

struct ResourceMonitor {
    system: System,
    networks: Networks,
    start: Instant,
}

impl ResourceMonitor {
    fn new() -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything());

        let mut system = System::new_with_specifics(refresh);
        system.refresh_all();

        let networks = Networks::new_with_refreshed_list();

        Self {
            system,
            networks,
            start: Instant::now(),
        }
    }

    fn sample(&mut self) -> ResourceSnapshot {
        // Refresh only what we need for lower overhead.
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.networks.refresh();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let memory_used = self.system.used_memory() * 1024;
        let memory_total = self.system.total_memory() * 1024;

        let swap_used = self.system.used_swap() * 1024;
        let swap_total = self.system.total_swap() * 1024;

        let mut disk_used = 0u64;
        let mut disk_total = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disk_total = disk_total.saturating_add(total);
            disk_used = disk_used.saturating_add(total.saturating_sub(avail));
        }

        let mut rx = 0u64;
        let mut tx = 0u64;
        for (_name, data) in self.networks.iter() {
            rx = rx.saturating_add(data.received());
            tx = tx.saturating_add(data.transmitted());
        }

        ResourceSnapshot {
            timestamp_ms: self.start.elapsed().as_millis(),
            cpu_usage_percent: cpu_usage,
            memory_used_bytes: memory_used,
            memory_total_bytes: memory_total,
            swap_used_bytes: swap_used,
            swap_total_bytes: swap_total,
            disk_used_bytes: disk_used,
            disk_total_bytes: disk_total,
            network_received_bytes: rx,
            network_transmitted_bytes: tx,
        }
    }
}

struct ResourceManager {
    thresholds: Thresholds,
}

impl ResourceManager {
    fn new(thresholds: Thresholds) -> Self {
        Self { thresholds }
    }

    fn evaluate(&self, snap: &ResourceSnapshot) {
        let mem_ratio = if snap.memory_total_bytes > 0 {
            snap.memory_used_bytes as f32 / snap.memory_total_bytes as f32
        } else {
            0.0
        };

        let disk_ratio = if snap.disk_total_bytes > 0 {
            snap.disk_used_bytes as f32 / snap.disk_total_bytes as f32
        } else {
            0.0
        };

        if snap.cpu_usage_percent >= self.thresholds.cpu_warn {
            warn!(
                cpu = snap.cpu_usage_percent,
                "CPU usage above threshold"
            );
        }

        if mem_ratio >= self.thresholds.memory_warn_ratio {
            warn!(
                memory_used = snap.memory_used_bytes,
                memory_total = snap.memory_total_bytes,
                memory_ratio = mem_ratio,
                "Memory usage above threshold"
            );
        }

        if disk_ratio >= self.thresholds.disk_warn_ratio {
            warn!(
                disk_used = snap.disk_used_bytes,
                disk_total = snap.disk_total_bytes,
                disk_ratio = disk_ratio,
                "Disk usage above threshold"
            );
        }

        // Example management hook:
        // Here you could:
        // - lower process priority
        // - notify a supervisor
        // - trigger cgroup limits
        // - emit metrics to Prometheus/OpenTelemetry
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG").unwrap_or_else(|_| "info,resmon_daemon=debug".into()),
        )
        .init();

    info!("starting resource monitoring daemon");

    let mut monitor = ResourceMonitor::new();
    let manager = ResourceManager::new(Thresholds::default());

    let mut tick = interval(Duration::from_secs(1));

    loop {
        tokio::select! {
            _ = tick.tick() => {
                let snap = monitor.sample();

                // Fast structured logging; JSON can be enabled via subscriber config if desired.
                info!(
                    cpu = snap.cpu_usage_percent,
                    mem_used = snap.memory_used_bytes,
                    mem_total = snap.memory_total_bytes,
                    swap_used = snap.swap_used_bytes,
                    swap_total = snap.swap_total_bytes,
                    disk_used = snap.disk_used_bytes,
                    disk_total = snap.disk_total_bytes,
                    rx = snap.network_received_bytes,
                    tx = snap.network_transmitted_bytes,
                    "resource snapshot"
                );

                manager.evaluate(&snap);
            }

            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}
