use anyhow::Result;
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{Arc, RwLock},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, Networks, RefreshKind, System};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
    signal,
    time::interval,
};
use tracing::{error, info};
use tracing_subscriber::fmt::format::FmtSpan;

#[derive(Clone, Debug, Serialize)]
struct Metrics {
    timestamp_unix: u64,
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_total_bytes: u64,
    disk_used_bytes: u64,
    net_rx_bytes: u64,
    net_tx_bytes: u64,
    process_count: usize,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            timestamp_unix: 0,
            cpu_usage_percent: 0.0,
            total_memory_kib: 0,
            used_memory_kib: 0,
            total_swap_kib: 0,
            used_swap_kib: 0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            disk_total_bytes: 0,
            disk_used_bytes: 0,
            net_rx_bytes: 0,
            net_tx_bytes: 0,
            process_count: 0,
        }
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0))
        .as_secs()
}

fn gather_metrics(sys: &mut System, disks: &mut Disks, networks: &mut Networks) -> Metrics {
    sys.refresh_specifics(
        RefreshKind::nothing()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes()
    );
    disks.refresh_specifics(true, DiskRefreshKind::everything());
    networks.refresh();

    let cpu_usage = sys.global_cpu_usage();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();

    let load = System::load_average();

    let mut disk_total = 0u64;
    let mut disk_used = 0u64;
    for disk in disks.list() {
        let total = disk.total_space();
        let avail = disk.available_space();
        disk_total += total;
        disk_used += total.saturating_sub(avail);
    }

    let mut rx = 0u64;
    let mut tx = 0u64;
    for (_name, data) in networks.iter() {
        rx += data.received();
        tx += data.transmitted();
    }

    Metrics {
        timestamp_unix: now_unix(),
        cpu_usage_percent: cpu_usage,
        total_memory_kib: total_mem,
        used_memory_kib: used_mem,
        total_swap_kib: total_swap,
        used_swap_kib: used_swap,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disk_total_bytes: disk_total,
        disk_used_bytes: disk_used,
        net_rx_bytes: rx,
        net_tx_bytes: tx,
        process_count: sys.processes().len(),
    }
}

async fn handle_client(mut stream: TcpStream, state: Arc<RwLock<Metrics>>) -> Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;
    let req = String::from_utf8_lossy(&buf[..n]);

    let metrics = state.read().unwrap().clone();
    let body = serde_json::to_string_pretty(&metrics)?;

    let response = if req.starts_with("GET /health") {
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\n\r\nOK".to_string()
    } else if req.starts_with("GET /metrics") || req.starts_with("GET /") {
        format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            body.len(),
            body
        )
    } else {
        "HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\n\r\nNot Found".to_string()
    };

    stream.write_all(response.as_bytes()).await?;
    Ok(())
}

async fn run_http_server(addr: SocketAddr, state: Arc<RwLock<Metrics>>) -> Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("status server listening on {}", addr);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client error: {e}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_span_events(FmtSpan::CLOSE)
        .json()
        .init();

    let metrics_state = Arc::new(RwLock::new(Metrics::default()));
    let updater_state = metrics_state.clone();

    let mut sys = System::new_with_specifics(
        RefreshKind::nothing()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes()
    );
    let mut disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());
    let mut networks = Networks::new_with_refreshed_list();

    let http_addr: SocketAddr = "127.0.0.1:9090".parse()?;

    let updater = tokio::spawn(async move {
        let mut tick = interval(Duration::from_secs(1));
        loop {
            tick.tick().await;
            let metrics = gather_metrics(&mut sys, &mut disks, &mut networks);
            {
                let mut guard = updater_state.write().unwrap();
                *guard = metrics.clone();
            }
            info!(target: "sysmon", "{}", serde_json::to_string(&metrics).unwrap());
        }
    });

    let server = tokio::spawn(run_http_server(http_addr, metrics_state));

    info!("daemon started");

    signal::ctrl_c().await?;
    info!("shutdown signal received");

    updater.abort();
    server.abort();

    Ok(())
}
