use anyhow::Result;
use serde::Serialize;
use std::{
    sync::{Arc, RwLock},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::{io::AsyncWriteExt, net::TcpListener, time::interval};
use tracing::{info, warn};

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp_unix: u64,
    cpu_usage_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    memory_usage_percent: f32,
    swap_used_bytes: u64,
    swap_total_bytes: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_used_bytes: u64,
    disk_total_bytes: u64,
    process_count: usize,
}

impl Metrics {
    fn empty() -> Self {
        Self {
            timestamp_unix: 0,
            cpu_usage_percent: 0.0,
            memory_used_bytes: 0,
            memory_total_bytes: 0,
            memory_usage_percent: 0.0,
            swap_used_bytes: 0,
            swap_total_bytes: 0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            disk_used_bytes: 0,
            disk_total_bytes: 0,
            process_count: 0,
        }
    }
}

#[derive(Clone)]
struct Thresholds {
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn collect_metrics(sys: &mut System) -> Metrics {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();
    sys.refresh_processes();

    let cpu_usage = sys.global_cpu_info().cpu_usage();

    let total_mem = sys.total_memory() * 1024;
    let used_mem = sys.used_memory() * 1024;
    let mem_pct = if total_mem > 0 {
        (used_mem as f32 / total_mem as f32) * 100.0
    } else {
        0.0
    };

    let total_swap = sys.total_swap() * 1024;
    let used_swap = sys.used_swap() * 1024;

    let load = System::load_average();

    let mut disk_total = 0u64;
    let mut disk_used = 0u64;
    for disk in sys.disks() {
        let total = disk.total_space();
        let available = disk.available_space();
        disk_total = disk_total.saturating_add(total);
        disk_used = disk_used.saturating_add(total.saturating_sub(available));
    }

    Metrics {
        timestamp_unix: now_unix(),
        cpu_usage_percent: cpu_usage,
        memory_used_bytes: used_mem,
        memory_total_bytes: total_mem,
        memory_usage_percent: mem_pct,
        swap_used_bytes: used_swap,
        swap_total_bytes: total_swap,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disk_used_bytes: disk_used,
        disk_total_bytes: disk_total,
        process_count: sys.processes().len(),
    }
}

fn check_thresholds(m: &Metrics, t: &Thresholds) {
    if m.cpu_usage_percent >= t.cpu_percent {
        warn!("CPU threshold exceeded: {:.1}% >= {:.1}%", m.cpu_usage_percent, t.cpu_percent);
    }
    if m.memory_usage_percent >= t.memory_percent {
        warn!(
            "Memory threshold exceeded: {:.1}% >= {:.1}%",
            m.memory_usage_percent, t.memory_percent
        );
    }
    let disk_pct = if m.disk_total_bytes > 0 {
        (m.disk_used_bytes as f32 / m.disk_total_bytes as f32) * 100.0
    } else {
        0.0
    };
    if disk_pct >= t.disk_percent {
        warn!("Disk threshold exceeded: {:.1}% >= {:.1}%", disk_pct, t.disk_percent);
    }
}

async fn serve_status(shared: Arc<RwLock<Metrics>>, addr: &str) -> Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("status endpoint listening on {}", addr);

    loop {
        let (mut socket, peer) = listener.accept().await?;
        let metrics = {
            let guard = shared.read().unwrap();
            guard.clone()
        };

        let body = serde_json::to_vec(&metrics)?;
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            body.len()
        );

        info!("served status to {}", peer);
        socket.write_all(response.as_bytes()).await?;
        socket.write_all(&body).await?;
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(std::env::var("RUST_LOG").unwrap_or_else(|_| "info".into()))
        .init();

    let thresholds = Thresholds {
        cpu_percent: 85.0,
        memory_percent: 90.0,
        disk_percent: 90.0,
    };

    let shared = Arc::new(RwLock::new(Metrics::empty()));
    let shared_for_server = shared.clone();

    let server_task = tokio::spawn(async move {
        if let Err(e) = serve_status(shared_for_server, "127.0.0.1:8080").await {
            warn!("status server error: {:#}", e);
        }
    });

    let mut sys = System::new_all();
    let mut tick = interval(Duration::from_secs(2));

    info!("resource monitor daemon started");

    loop {
        tick.tick().await;

        let metrics = collect_metrics(&mut sys);
        check_thresholds(&metrics, &thresholds);

        {
            let mut guard = shared.write().unwrap();
            *guard = metrics.clone();
        }

        info!(
            "cpu={:.1}% mem={:.1}% disk_used={}B procs={}",
            metrics.cpu_usage_percent,
            metrics.memory_usage_percent,
            metrics.disk_used_bytes,
            metrics.process_count
        );
    }

    #[allow(unreachable_code)]
    {
        let _ = server_task.await;
        Ok(())
    }
}
