```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::Deserialize;
use std::fs;
use std::path::Path;
use std::time::Duration;
use sysinfo::{DiskExt, LoadAvg, ProcessExt, System, SystemExt};
use tokio::time::sleep;
use tracing::{error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    daemon: DaemonConfig,
    process: ProcessConfig,
}

#[derive(Debug, Deserialize, Clone)]
struct DaemonConfig {
    interval_secs: u64,
    cpu_threshold: f32,
    memory_threshold: f32,
    load_threshold: f64,
    disk_threshold: f32,
    action: String,
}

#[derive(Debug, Deserialize, Clone)]
struct ProcessConfig {
    top_n: usize,
    renice_value: i32,
    kill_signal: String,
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let content = fs::read_to_string(&path)
        .with_context(|| format!("failed to read config: {:?}", path.as_ref()))?;
    let cfg: Config = toml::from_str(&content).context("failed to parse TOML config")?;
    Ok(cfg)
}

fn parse_signal(name: &str) -> Signal {
    match name {
        "SIGKILL" => Signal::SIGKILL,
        "SIGTERM" => Signal::SIGTERM,
        "SIGINT" => Signal::SIGINT,
        "SIGHUP" => Signal::SIGHUP,
        _ => Signal::SIGTERM,
    }
}

fn disk_usage_percent(sys: &System) -> f32 {
    let mut total = 0u64;
    let mut used = 0u64;

    for disk in sys.disks() {
        let t = disk.total_space();
        let a = disk.available_space();
        total += t;
        used += t.saturating_sub(a);
    }

    if total == 0 {
        0.0
    } else {
        (used as f32 / total as f32) * 100.0
    }
}

fn top_processes_by_cpu(sys: &System, n: usize) -> Vec<(i32, String, f32, u64)> {
    let mut procs: Vec<_> = sys
        .processes()
        .iter()
        .map(|(pid, p)| {
            (
                pid.as_u32() as i32,
                p.name().to_string(),
                p.cpu_usage(),
                p.memory(),
            )
        })
        .collect();

    procs.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
    procs.truncate(n);
    procs
}

fn renice_process(pid: i32, nice: i32) -> Result<()> {
    let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, pid as u32, nice) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    Ok(())
}

fn kill_process(pid: i32, sig: Signal) -> Result<()> {
    kill(Pid::from_raw(pid), sig).context("failed to send signal")?;
    Ok(())
}

async fn monitor_loop(cfg: Config) -> Result<()> {
    let mut sys = System::new_all();
    let interval = Duration::from_secs(cfg.daemon.interval_secs);

    loop {
        sys.refresh_all();

        let cpu = sys.global_cpu_info().cpu_usage();
        let mem_total = sys.total_memory() as f32;
        let mem_used = sys.used_memory() as f32;
        let mem_pct = if mem_total == 0.0 {
            0.0
        } else {
            (mem_used / mem_total) * 100.0
        };
        let load = sys.load_average();
        let disk_pct = disk_usage_percent(&sys);

        info!(
            cpu = cpu,
            memory_pct = mem_pct,
            load_1 = load.one,
            disk_pct = disk_pct,
            "resource snapshot"
        );

        let overloaded = cpu > cfg.daemon.cpu_threshold
            || mem_pct > cfg.daemon.memory_threshold
            || load.one > cfg.daemon.load_threshold
            || disk_pct > cfg.daemon.disk_threshold;

        if overloaded {
            warn!("threshold exceeded; taking action={}", cfg.daemon.action);

            let offenders = top_processes_by_cpu(&sys, cfg.process.top_n);
            for (pid, name, proc_cpu, proc_mem) in offenders {
                warn!(
                    pid = pid,
                    process = %name,
                    cpu = proc_cpu,
                    memory_kb = proc_mem,
                    "top offender"
                );

                match cfg.daemon.action.as_str() {
                    "renice" => {
                        if let Err(e) = renice_process(pid, cfg.process.renice_value) {
                            error!(pid = pid, error = %e, "renice failed");
                        } else {
                            info!(pid = pid, nice = cfg.process.renice_value, "renice applied");
                        }
                    }
                    "kill" => {
                        let sig = parse_signal(&cfg.process.kill_signal);
                        if let Err(e) = kill_process(pid, sig) {
                            error!(pid = pid, error = %e, "kill failed");
                        } else {
                            info!(pid = pid, signal = ?sig, "signal sent");
                        }
                    }
                    _ => {
                        info!(pid = pid, "logging only; no action taken");
                    }
                }
            }
        }

        sleep(interval).await;
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = load_config("config.toml")?;
    info!("daemon starting");

    if let Err(e) = monitor_loop(cfg).await {
        error!(error = %e, "daemon terminated with error");
        return Err(e);
    }

    Ok(())
}
