use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};
use tokio::{signal, sync::RwLock, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    /// Poll interval in milliseconds
    poll_interval_ms: u64,

    /// CPU usage threshold above which the daemon will log a warning
    cpu_warn_threshold: f32,

    /// Memory usage threshold above which the daemon will log a warning
    memory_warn_threshold: f32,

    /// Optional path to a policy file or config file
    #[serde(default)]
    policy_name: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_warn_threshold: 85.0,
            memory_warn_threshold: 90.0,
            policy_name: None,
        }
    }
}

#[derive(Debug, Clone)]
struct Metrics {
    cpu_usage: f32,
    memory_usage: f32,
    total_memory: u64,
    used_memory: u64,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
}

#[derive(Debug)]
struct DaemonState {
    metrics: Option<Metrics>,
}

impl DaemonState {
    fn new() -> Self {
        Self { metrics: None }
    }
}

#[derive(Debug)]
enum Action {
    Warn(String),
    // Future actions:
    // ThrottleProcess { pid: i32, limit: u32 },
    // KillProcess { pid: i32 },
    // AdjustNice { pid: i32, nice: i32 },
}

struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    fn new(config: Config) -> Self {
        Self { config }
    }

    fn evaluate(&self, metrics: &Metrics) -> Vec<Action> {
        let mut actions = Vec::new();

        if metrics.cpu_usage >= self.config.cpu_warn_threshold {
            actions.push(Action::Warn(format!(
                "CPU usage high: {:.1}% >= {:.1}%",
                metrics.cpu_usage, self.config.cpu_warn_threshold
            )));
        }

        if metrics.memory_usage >= self.config.memory_warn_threshold {
            actions.push(Action::Warn(format!(
                "Memory usage high: {:.1}% >= {:.1}%",
                metrics.memory_usage, self.config.memory_warn_threshold
            )));
        }

        actions
    }
}

fn load_config(path: Option<PathBuf>) -> Result<Config> {
    match path {
        Some(p) => {
            let raw = fs::read_to_string(&p)
                .with_context(|| format!("failed to read config file: {}", p.display()))?;
            let cfg: Config = toml::from_str(&raw)
                .with_context(|| format!("failed to parse config file: {}", p.display()))?;
            Ok(cfg)
        }
        None => Ok(Config::default()),
    }
}

fn collect_metrics(system: &mut System) -> Metrics {
    system.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    let cpu_usage = system.global_cpu_usage();
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let memory_usage = if total_memory > 0 {
        (used_memory as f32 / total_memory as f32) * 100.0
    } else {
        0.0
    };

    let load = System::load_average();

    Metrics {
        cpu_usage,
        memory_usage,
        total_memory,
        used_memory,
        load_avg_1m: load.one,
        load_avg_5m: load.five,
        load_avg_15m: load.fifteen,
    }
}

async fn run_daemon(config: Config) -> Result<()> {
    let state = Arc::new(RwLock::new(DaemonState::new()));
    let policy = PolicyEngine::new(config.clone());

    let mut system = System::new();

    let poll_interval = Duration::from_millis(config.poll_interval_ms.max(100));

    info!(
        poll_interval_ms = config.poll_interval_ms,
        cpu_warn_threshold = config.cpu_warn_threshold,
        memory_warn_threshold = config.memory_warn_threshold,
        "daemon started"
    );

    loop {
        tokio::select! {
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }

            _ = time::sleep(poll_interval) => {
                let metrics = collect_metrics(&mut system);

                {
                    let mut guard = state.write().await;
                    guard.metrics = Some(metrics.clone());
                }

                debug!(
                    cpu_usage = metrics.cpu_usage,
                    memory_usage = metrics.memory_usage,
                    total_memory = metrics.total_memory,
                    used_memory = metrics.used_memory,
                    load_avg_1m = metrics.load_avg_1m,
                    load_avg_5m = metrics.load_avg_5m,
                    load_avg_15m = metrics.load_avg_15m,
                    "collected metrics"
                );

                let actions = policy.evaluate(&metrics);
                for action in actions {
                    match action {
                        Action::Warn(msg) => warn!("{}", msg),
                    }
                }
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let config_path = std::env::args().nth(1).map(PathBuf::from);
    let config = load_config(config_path)?;

    if let Err(err) = run_daemon(config).await {
        error!(error = %err, "daemon exited with error");
        return Err(err);
    }

    Ok(())
}
