use axum::{
    extract::State,
    http::StatusCode,
    routing::{get, post},
    Json, Router,
};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, NetworksExt, System, SystemExt};
use tokio::{signal, task, time};
use tracing::{error, info, warn};

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<SystemSnapshot>>,
    config: Arc<RwLock<DaemonConfig>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonConfig {
    sample_interval_ms: u64,
    cpu_alert_threshold: f32,
    memory_alert_threshold: f32,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_alert_threshold: 90.0,
            memory_alert_threshold: 90.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SystemSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    memory_total_kb: u64,
    memory_used_kb: u64,
    swap_total_kb: u64,
    swap_used_kb: u64,
    disks: Vec<DiskSnapshot>,
    networks: Vec<NetworkSnapshot>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskSnapshot {
    name: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct NetworkSnapshot {
    interface: String,
    received_bytes: u64,
    transmitted_bytes: u64,
}

impl Default for SystemSnapshot {
    fn default() -> Self {
        Self {
            timestamp_ms: 0,
            cpu_usage_percent: 0.0,
            memory_total_kb: 0,
            memory_used_kb: 0,
            swap_total_kb: 0,
            swap_used_kb: 0,
            disks: Vec::new(),
            networks: Vec::new(),
        }
    }
}

#[derive(Debug, Deserialize)]
struct UpdateConfigRequest {
    sample_interval_ms: Option<u64>,
    cpu_alert_threshold: Option<f32>,
    memory_alert_threshold: Option<f32>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState {
        metrics: Arc::new(RwLock::new(SystemSnapshot::default())),
        config: Arc::new(RwLock::new(DaemonConfig::default())),
    };

    let sampler_state = state.clone();
    task::spawn(async move {
        if let Err(e) = sampler_loop(sampler_state).await {
            error!("sampler loop error: {e:?}");
        }
    });

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(metrics))
        .route("/config", get(get_config).post(update_config))
        .route("/manage/reload", post(reload))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    info!("starting daemon on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    Ok(())
}

async fn sampler_loop(state: AppState) -> anyhow::Result<()> {
    let mut system = System::new_all();
    let mut last_sample = Instant::now();

    loop {
        let cfg = state.config.read().clone();
        let interval = Duration::from_millis(cfg.sample_interval_ms.max(100));

        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let memory_total = system.total_memory();
        let memory_used = system.used_memory();
        let swap_total = system.total_swap();
        let swap_used = system.used_swap();

        let disks = system
            .disks()
            .iter()
            .map(|d| DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                total_space: d.total_space(),
                available_space: d.available_space(),
                file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            })
            .collect::<Vec<_>>();

        let networks = system
            .networks()
            .iter()
            .map(|(name, data)| NetworkSnapshot {
                interface: name.clone(),
                received_bytes: data.received(),
                transmitted_bytes: data.transmitted(),
            })
            .collect::<Vec<_>>();

        let snapshot = SystemSnapshot {
            timestamp_ms: last_sample.elapsed().as_millis(),
            cpu_usage_percent: cpu_usage,
            memory_total_kb: memory_total,
            memory_used_kb: memory_used,
            swap_total_kb: swap_total,
            swap_used_kb: swap_used,
            disks,
            networks,
        };

        {
            let mut guard = state.metrics.write();
            *guard = snapshot;
        }

        if cpu_usage >= cfg.cpu_alert_threshold {
            warn!("CPU usage high: {:.2}%", cpu_usage);
        }
        if memory_total > 0 {
            let mem_pct = (memory_used as f32 / memory_total as f32) * 100.0;
            if mem_pct >= cfg.memory_alert_threshold {
                warn!("Memory usage high: {:.2}%", mem_pct);
            }
        }

        time::sleep(interval).await;
    }
}

async fn health() -> Json<serde_json::Value> {
    Json(serde_json::json!({
        "status": "ok"
    }))
}

async fn metrics(State(state): State<AppState>) -> Json<SystemSnapshot> {
    Json(state.metrics.read().clone())
}

async fn get_config(State(state): State<AppState>) -> Json<DaemonConfig> {
    Json(state.config.read().clone())
}

async fn update_config(
    State(state): State<AppState>,
    Json(req): Json<UpdateConfigRequest>,
) -> Result<Json<DaemonConfig>, (StatusCode, String)> {
    let mut cfg = state.config.write();

    if let Some(v) = req.sample_interval_ms {
        if v < 100 {
            return Err((StatusCode::BAD_REQUEST, "sample_interval_ms must be >= 100".into()));
        }
        cfg.sample_interval_ms = v;
    }

    if let Some(v) = req.cpu_alert_threshold {
        if !(0.0..=100.0).contains(&v) {
            return Err((StatusCode::BAD_REQUEST, "cpu_alert_threshold must be 0..=100".into()));
        }
        cfg.cpu_alert_threshold = v;
    }

    if let Some(v) = req.memory_alert_threshold {
        if !(0.0..=100.0).contains(&v) {
            return Err((StatusCode::BAD_REQUEST, "memory_alert_threshold must be 0..=100".into()));
        }
        cfg.memory_alert_threshold = v;
    }

    Ok(Json(cfg.clone()))
}

async fn reload() -> Result<StatusCode, (StatusCode, String)> {
    info!("reload requested");
    Ok(StatusCode::ACCEPTED)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(e) = signal::ctrl_c().await {
            error!("failed to install ctrl-c handler: {e}");
        }
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        match signal(SignalKind::terminate()) {
            Ok(mut sigterm) => {
                sigterm.recv().await;
            }
            Err(e) => {
                error!("failed to install SIGTERM handler: {e}");
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
