## `src/manager.rs`

```rust
use crate::types::{Alert, AlertKind, DaemonConfig, ResourceSnapshot};
use anyhow::Result;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use tracing::{info, warn};

pub struct Manager {
    cfg: DaemonConfig,
}

impl Manager {
    pub fn new(cfg: DaemonConfig) -> Self {
        Self { cfg }
    }

    pub fn evaluate(&self, snap: &ResourceSnapshot) -> Vec<Alert> {
        let mut alerts = Vec::new();

        if snap.cpu_percent >= self.cfg.thresholds.cpu_percent {
            alerts.push(Alert {
                kind: AlertKind::CpuHigh,
                message: format!("CPU usage high: {:.2}%", snap.cpu_percent),
            });
        }

        if snap.memory_percent >= self.cfg.thresholds.memory_percent {
            alerts.push(Alert {
                kind: AlertKind::MemoryHigh,
                message: format!("Memory usage high: {:.2}%", snap.memory_percent),
            });
        }

        if snap.load_avg >= self.cfg.thresholds.load_avg {
            alerts.push(Alert {
                kind: AlertKind::LoadHigh,
                message: format!("Load average high: {:.2}", snap.load_avg),
            });
        }

        alerts
    }

    pub fn handle_alerts(&self, alerts: &[Alert]) -> Result<()> {
        for alert in alerts {
            warn!(kind = ?alert.kind, "{}", alert.message);
        }
        Ok(())
    }

    pub fn remediate(&self, snap: &ResourceSnapshot) -> Result<()> {
        if self.cfg.enable_kill_on_high_cpu && snap.cpu_percent >= self.cfg.thresholds.cpu_percent {
            info!("remediation requested for high CPU, but no target selection policy is implemented yet");
        }

        if self.cfg.enable_kill_on_high_memory && snap.memory_percent >= self.cfg.thresholds.memory_percent {
            info!("remediation requested for high memory, but no target selection policy is implemented yet");
        }

        Ok(())
    }

    #[allow(dead_code)]
    pub fn kill_pid(&self, pid: i32) -> Result<()> {
        kill(Pid::from_raw(pid), Signal::SIGTERM)?;
        Ok(())
    }
}
