use crate::manager::Manager;
use crate::monitor::Monitor;
use crate::types::DaemonConfig;
use anyhow::Result;
use std::time::Duration;
use tokio::time::interval;
use tracing::{info, warn};

pub struct Daemon {
    cfg: DaemonConfig,
    monitor: Monitor,
    manager: Manager,
}

impl Daemon {
    pub fn new(cfg: DaemonConfig) -> Self {
        let monitor = Monitor::new();
        let manager = Manager::new(cfg.clone());

        Self {
            cfg,
            monitor,
            manager,
        }
    }

    pub async fn run(mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_secs(self.cfg.interval_secs));

        info!(
            interval_secs = self.cfg.interval_secs,
            "daemon started"
        );

        loop {
            ticker.tick().await;

            let snap = self.monitor.sample();
            info!(
                cpu = snap.cpu_percent,
                memory = snap.memory_percent,
                load = snap.load_avg,
                processes = snap.process_count,
                "resource snapshot"
            );

            let alerts = self.manager.evaluate(&snap);
            if !alerts.is_empty() {
                self.manager.handle_alerts(&alerts)?;
                self.manager.remediate(&snap)?;
            } else {
                warn!("no alerts triggered");
            }
        }
    }
}
