use anyhow::Result;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
    signal,
    time,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    memory_total_kib: u64,
    memory_used_kib: u64,
    swap_total_kib: u64,
    swap_used_kib: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_total_bytes: u64,
    disk_available_bytes: u64,
    process_count: usize,
}

impl ResourceSnapshot {
    fn empty() -> Self {
        Self {
            timestamp_ms: 0,
            cpu_usage_percent: 0.0,
            memory_total_kib: 0,
            memory_used_kib: 0,
            swap_total_kib: 0,
            swap_used_kib: 0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            disk_total_bytes: 0,
            disk_available_bytes: 0,
            process_count: 0,
        }
    }
}

struct SharedState {
    snapshot: RwLock<ResourceSnapshot>,
    shutdown: AtomicBool,
}

impl SharedState {
    fn new() -> Self {
        Self {
            snapshot: RwLock::new(ResourceSnapshot::empty()),
            shutdown: AtomicBool::new(false),
        }
    }
}

struct Daemon {
    system: System,
    disks: Disks,
    state: Arc<SharedState>,
    sample_interval: Duration,
}

impl Daemon {
    fn new(sample_interval: Duration) -> Self {
        let system = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory()
                .with_processes(ProcessRefreshKind::everything()),
        );

        let disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

        Self {
            system,
            disks,
            state: Arc::new(SharedState::new()),
            sample_interval,
        }
    }

    fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh_list();
        self.disks.refresh(true);

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();
        let memory_total_kib = self.system.total_memory();
        let memory_used_kib = self.system.used_memory();
        let swap_total_kib = self.system.total_swap();
        let swap_used_kib = self.system.used_swap();

        let load = System::load_average();

        let mut disk_total_bytes = 0;
        let mut disk_available_bytes = 0;
        for disk in self.disks.list() {
            disk_total_bytes += disk.total_space();
            disk_available_bytes += disk.available_space();
        }

        let process_count = self.system.processes().len();

        ResourceSnapshot {
            timestamp_ms: Instant::now().elapsed().as_millis(),
            cpu_usage_percent,
            memory_total_kib,
            memory_used_kib,
            swap_total_kib,
            swap_used_kib,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disk_total_bytes,
            disk_available_bytes,
            process_count,
        }
    }

    async fn run_sampler(self: Arc<Self>) {
        let mut interval = time::interval(self.sample_interval);
        loop {
            interval.tick().await;

            if self.state.shutdown.load(Ordering::Relaxed) {
                break;
            }

            let snapshot = {
                let mut daemon = Arc::get_mut(&mut self.clone()).unwrap_or_else(|| {
                    panic!("unexpected shared ownership in sampler");
                });
                daemon.snapshot()
            };

            {
                let mut guard = self.state.snapshot.write();
                *guard = snapshot;
            }

            self.enforce_policies().await;
        }
    }

    async fn enforce_policies(&self) {
        let snapshot = self.state.snapshot.read().clone();

        if snapshot.cpu_usage_percent > 90.0 {
            warn!("High CPU usage detected: {:.2}%", snapshot.cpu_usage_percent);
            // Placeholder: trigger throttling / alerting / remediation.
        }

        if snapshot.memory_total_kib > 0 {
            let mem_pct = (snapshot.memory_used_kib as f64 / snapshot.memory_total_kib as f64) * 100.0;
            if mem_pct > 90.0 {
                warn!("High memory usage detected: {:.2}%", mem_pct);
                // Placeholder: trigger memory pressure handling.
            }
        }
    }

    async fn serve(self: Arc<Self>, addr: SocketAddr) -> Result<()> {
        let listener = TcpListener::bind(addr).await?;
        info!("daemon listening on {}", addr);

        loop {
            tokio::select! {
                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    self.state.shutdown.store(true, Ordering::Relaxed);
                    break;
                }
                accept_res = listener.accept() => {
                    match accept_res {
                        Ok((stream, peer)) => {
                            let state = self.state.clone();
                            tokio::spawn(async move {
                                if let Err(e) = handle_client(stream, state).await {
                                    warn!("client {} error: {}", peer, e);
                                }
                            });
                        }
                        Err(e) => {
                            error!("accept error: {}", e);
                        }
                    }
                }
            }
        }

        Ok(())
    }
}

async fn handle_client(mut stream: TcpStream, state: Arc<SharedState>) -> Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;
    if n == 0 {
        return Ok(());
    }

    let req = String::from_utf8_lossy(&buf[..n]).trim().to_lowercase();

    if req == "get" || req == "snapshot" {
        let snapshot = state.snapshot.read().clone();
        let json = serde_json::to_vec(&snapshot)?;
        stream.write_all(&json).await?;
        stream.write_all(b"\n").await?;
    } else if req == "shutdown" {
        state.shutdown.store(true, Ordering::Relaxed);
        stream.write_all(b"{\"status\":\"ok\",\"action\":\"shutdown\"}\n").await?;
    } else {
        stream
            .write_all(b"{\"error\":\"unknown command; use get|snapshot|shutdown\"}\n")
            .await?;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let daemon = Arc::new(Daemon::new(Duration::from_secs(1)));

    let sampler = daemon.clone();
    tokio::spawn(async move {
        sampler.run_sampler().await;
    });

    let addr: SocketAddr = "127.0.0.1:7878".parse()?;
    daemon.serve(addr).await?;

    info!("daemon exited");
    Ok(())
}
```

