```rust
use anyhow::Result;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    convert::Infallible,
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::{signal, task, time};
use tracing::{error, info};
use warp::Filter;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonState {
    running: bool,
    last_update_ms: u128,
    snapshot: Option<ResourceSnapshot>,
}

#[derive(Debug, Clone, Deserialize)]
struct ControlRequest {
    action: String,
}

#[derive(Clone)]
struct SharedState {
    inner: Arc<RwLock<DaemonState>>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(DaemonState {
                running: true,
                last_update_ms: 0,
                snapshot: None,
            })),
        }
    }

    fn update_snapshot(&self, snapshot: ResourceSnapshot) {
        let mut state = self.inner.write();
        state.last_update_ms = snapshot.timestamp_ms;
        state.snapshot = Some(snapshot);
    }

    fn get_state(&self) -> DaemonState {
        self.inner.read().clone()
    }

    fn set_running(&self, running: bool) {
        self.inner.write().running = running;
    }
}

fn with_state(
    state: SharedState,
) -> impl Filter<Extract = (SharedState,), Error = Infallible> + Clone {
    warp::any().map(move || state.clone())
}

fn now_ms() -> u128 {
    Instant::now().elapsed().as_millis()
}

fn collect_snapshot(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let load_avg = System::load_average();

    let disks = sys
        .disks()
        .iter()
        .map(|d| DiskSnapshot {
            name: d.name().to_string_lossy().into_owned(),
            total_space: d.total_space(),
            available_space: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).into_owned(),
        })
        .collect();

    ResourceSnapshot {
        timestamp_ms: now_ms(),
        cpu_usage,
        total_memory: sys.total_memory(),
        used_memory: sys.used_memory(),
        total_swap: sys.total_swap(),
        used_swap: sys.used_swap(),
        load_avg_one: load_avg.one,
        load_avg_five: load_avg.five,
        load_avg_fifteen: load_avg.fifteen,
        disks,
    }
}

async fn metrics_loop(state: SharedState, interval: Duration) {
    let mut sys = System::new_all();
    let mut ticker = time::interval(interval);

    loop {
        ticker.tick().await;

        if !state.get_state().running {
            break;
        }

        let snapshot = task::spawn_blocking({
            let mut sys = sys.clone();
            move || collect_snapshot(&mut sys)
        })
        .await;

        match snapshot {
            Ok(snap) => {
                state.update_snapshot(snap);
            }
            Err(e) => {
                error!("failed to collect snapshot: {e}");
            }
        }
    }

    info!("metrics loop stopped");
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = SharedState::new();
    let metrics_state = state.clone();

    let metrics_task = tokio::spawn(async move {
        metrics_loop(metrics_state, Duration::from_secs(2)).await;
    });

    let status_route = warp::path!("status")
        .and(warp::get())
        .and(with_state(state.clone()))
        .and_then(|state: SharedState| async move {
            let snapshot = state.get_state();
            Ok::<_, Infallible>(warp::reply::json(&snapshot))
        });

    let control_route = warp::path!("control")
        .and(warp::post())
        .and(warp::body::json())
        .and(with_state(state.clone()))
        .and_then(|req: ControlRequest, state: SharedState| async move {
            let response = match req.action.as_str() {
                "stop" => {
                    state.set_running(false);
                    serde_json::json!({ "ok": true, "message": "daemon stopping" })
                }
                "start" => {
                    state.set_running(true);
                    serde_json::json!({ "ok": true, "message": "daemon running" })
                }
                _ => serde_json::json!({ "ok": false, "error": "unknown action" }),
            };

            Ok::<_, Infallible>(warp::reply::json(&response))
        });

    let routes = status_route.or(control_route);

    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    info!("daemon listening on http://{addr}");

    let server = warp::serve(routes).run(addr);

    tokio::select! {
        _ = server => {},
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
            state.set_running(false);
        }
    }

    if let Err(e) = metrics_task.await {
        error!("metrics task join error: {e}");
    }

    Ok(())
}
```

