```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    path::Path,
    sync::{Arc, RwLock},
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::broadcast,
    task,
    time,
};
use tracing::{debug, error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysd.sock";
const DEFAULT_POLL_INTERVAL_MS: u64 = 1000;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    poll_interval_ms: u64,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    load_warn_per_cpu: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: DEFAULT_POLL_INTERVAL_MS,
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            load_warn_per_cpu: 1.5,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_pct: f32,
    memory_total: u64,
    memory_used: u64,
    memory_usage_pct: f32,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
    process_count: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Alert {
    level: String,
    message: String,
    snapshot: ResourceSnapshot,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "data")]
enum ControlRequest {
    GetStatus,
    GetConfig,
    SetConfig(Config),
    GetMetrics,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "data")]
enum ControlResponse {
    Ok,
    Status {
        running: bool,
        uptime_ms: u128,
        last_snapshot: Option<ResourceSnapshot>,
        alerts_sent: u64,
    },
    Config(Config),
    Metrics(ResourceSnapshot),
    Error(String),
}

struct DaemonState {
    start_time: Instant,
    config: RwLock<Config>,
    last_snapshot: RwLock<Option<ResourceSnapshot>>,
    alerts_sent: RwLock<u64>,
    running: RwLock<bool>,
}

impl DaemonState {
    fn new(config: Config) -> Self {
        Self {
            start_time: Instant::now(),
            config: RwLock::new(config),
            last_snapshot: RwLock::new(None),
            alerts_sent: RwLock::new(0),
            running: RwLock::new(true),
        }
    }
}

fn read_config_file(path: &str) -> Config {
    match fs::read_to_string(path) {
        Ok(contents) => serde_json::from_str(&contents).unwrap_or_default(),
        Err(_) => Config::default(),
    }
}

fn write_config_file(path: &str, config: &Config) -> Result<()> {
    let data = serde_json::to_string_pretty(config)?;
    fs::write(path, data)?;
    Ok(())
}

fn snapshot_system(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );
    sys.refresh_processes();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_pct = if total_mem > 0 {
        (used_mem as f32 / total_mem as f32) * 100.0
    } else {
        0.0
    };

    let load = System::load_average();
    let process_count = sys.processes().len();

    ResourceSnapshot {
        timestamp_ms: Instant::now().elapsed().as_millis(),
        cpu_usage_pct: cpu_usage,
        memory_total: total_mem,
        memory_used: used_mem,
        memory_usage_pct: mem_pct,
        load_avg_1m: load.one,
        load_avg_5m: load.five,
        load_avg_15m: load.fifteen,
        process_count,
    }
}

fn evaluate_alerts(snapshot: &ResourceSnapshot, cfg: &Config) -> Vec<Alert> {
    let mut alerts = Vec::new();

    if snapshot.cpu_usage_pct >= cfg.cpu_warn_pct {
        alerts.push(Alert {
            level: "warning".into(),
            message: format!(
                "CPU usage high: {:.2}% >= {:.2}%",
                snapshot.cpu_usage_pct, cfg.cpu_warn_pct
            ),
            snapshot: snapshot.clone(),
        });
    }

    if snapshot.memory_usage_pct >= cfg.mem_warn_pct {
        alerts.push(Alert {
            level: "warning".into(),
            message: format!(
                "Memory usage high: {:.2}% >= {:.2}%",
                snapshot.memory_usage_pct, cfg.mem_warn_pct
            ),
            snapshot: snapshot.clone(),
        });
    }

    let cpu_count = num_cpus::get().max(1) as f32;
    let load_per_cpu = (snapshot.load_avg_1m as f32) / cpu_count;
    if load_per_cpu >= cfg.load_warn_per_cpu {
        alerts.push(Alert {
            level: "warning".into(),
            message: format!(
                "Load average high: {:.2} per CPU >= {:.2}",
                load_per_cpu, cfg.load_warn_per_cpu
            ),
            snapshot: snapshot.clone(),
        });
    }

    alerts
}

async fn handle_control_connection(
    stream: UnixStream,
    state: Arc<DaemonState>,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: ControlRequest = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = ControlResponse::Error(format!("invalid request: {e}"));
                writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
                writer.write_all(b"\n").await?;
                continue;
            }
        };

        let resp = match req {
            ControlRequest::GetStatus => {
                let running = *state.running.read().unwrap();
                let uptime_ms = state.start_time.elapsed().as_millis();
                let last_snapshot = state.last_snapshot.read().unwrap().clone();
                let alerts_sent = *state.alerts_sent.read().unwrap();
                ControlResponse::Status {
                    running,
                    uptime_ms,
                    last_snapshot,
                    alerts_sent,
                }
            }
            ControlRequest::GetConfig => {
                let cfg = state.config.read().unwrap().clone();
                ControlResponse::Config(cfg)
            }
            ControlRequest::SetConfig(new_cfg) => {
                {
                    let mut cfg = state.config.write().unwrap();
                    *cfg = new_cfg.clone();
                }
                if let Err(e) = write_config_file("/tmp/sysd.json", &new_cfg) {
                    warn!("failed to persist config: {e}");
                }
                ControlResponse::Ok
            }
            ControlRequest::GetMetrics => {
                let snapshot = state.last_snapshot.read().unwrap().clone();
                match snapshot {
                    Some(s) => ControlResponse::Metrics(s),
                    None => ControlResponse::Error("no metrics available yet".into()),
                }
            }
            ControlRequest::Shutdown => {
                {
                    let mut running = state.running.write().unwrap();
                    *running = false;
                }
                let _ = shutdown_tx.send(());
                ControlResponse::Ok
            }
        };

        writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).ok();
    }

    let config = read_config_file("/tmp/sysd.json");
    let state = Arc::new(DaemonState::new(config));

    let (shutdown_tx, mut shutdown_rx) = broadcast::channel::<()>(8);
    let (alert_tx, mut alert_rx) = broadcast::channel::<Alert>(64);

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind socket at {SOCKET_PATH}"))?;

    info!("sysd started");
    info!("control socket: {SOCKET_PATH}");

    let state_for_sampler = state.clone();
    let alert_tx_for_sampler = alert_tx.clone();
    let sampler_task = task::spawn(async move {
        let mut sys = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory(MemoryRefreshKind::everything()),
        );

        loop {
            let cfg = state_for_sampler.config.read().unwrap().clone();

            let snapshot = snapshot_system(&mut sys);
            {
                let mut last = state_for_sampler.last_snapshot.write().unwrap();
                *last = Some(snapshot.clone());
            }

            let alerts = evaluate_alerts(&snapshot, &cfg);
            if !alerts.is_empty() {
                let mut count = state_for_sampler.alerts_sent.write().unwrap();
                for alert in alerts {
                    *count += 1;
                    let _ = alert_tx_for_sampler.send(alert);
                }
            }

            time::sleep(Duration::from_millis(cfg.poll_interval_ms)).await;
        }
    });

    let alert_logger = task::spawn(async move {
        while let Ok(alert) = alert_rx.recv().await {
            warn!("ALERT [{}]: {}", alert.level, alert.message);
            debug!("snapshot: {:?}", alert.snapshot);
        }
    });

    let state_for_accept = state.clone();
    let shutdown_tx_for_accept = shutdown_tx.clone();
    let accept_task = task::spawn(async move {
        loop {
            tokio::select! {
                res = listener.accept() => {
                    match res {
                        Ok((stream, _addr)) => {
                            let state = state_for_accept.clone();
                            let shutdown_tx = shutdown_tx_for_accept.clone();
                            task::spawn(async move {
                                if let Err(e) = handle_control_connection(stream, state, shutdown_tx).await {
                                    error!("control connection error: {e}");
                                }
                            });
                        }
                        Err(e) => {
                            error!("accept error: {e}");
                            time::sleep(Duration::from_millis(200)).await;
                        }
                    }
                }
                _ = shutdown_rx.recv() => {
                    break;
                }
            }
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received Ctrl-C");
        }
        _ = shutdown_rx.recv() => {
            info!("shutdown requested");
        }
    }

    {
        let mut running = state.running.write().unwrap();
        *running = false;
    }

    let _ = shutdown_tx.send(());

    sampler_task.abort();
    accept_task.abort();
    alert_logger.abort();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).ok();
    }

    info!("sysd stopped");
    Ok(())
}
