use anyhow::Result;
use clap::Parser;
use serde::Serialize;
use std::{
    collections::HashMap,
    sync::{Arc, RwLock},
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{TcpListener, TcpStream},
    signal,
    sync::watch,
    task,
    time,
};
use tracing::{error, info, warn};

#[derive(Parser, Debug, Clone)]
#[command(name = "resource-daemon")]
#[command(about = "High-performance OS resource monitoring daemon")]
struct Config {
    /// Poll interval in seconds
    #[arg(long, default_value_t = 2)]
    poll_interval: u64,

    /// TCP control socket bind address
    #[arg(long, default_value = "127.0.0.1:7878")]
    bind_addr: String,

    /// CPU usage threshold for warning
    #[arg(long, default_value_t = 90.0)]
    cpu_warn: f32,

    /// Memory usage threshold for warning
    #[arg(long, default_value_t = 90.0)]
    mem_warn: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    global_cpu_usage: f32,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_usage: f32,
    memory: u64,
}

#[derive(Debug, Clone, Serialize)]
struct HealthStatus {
    cpu_warn: bool,
    memory_warn: bool,
    disk_warn: bool,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonState {
    snapshot: ResourceSnapshot,
    health: HealthStatus,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = Config::parse();
    info!(?config, "starting resource daemon");

    let state = Arc::new(RwLock::new(None::<DaemonState>));
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let monitor_state = state.clone();
    let monitor_config = config.clone();
    let monitor_shutdown = shutdown_rx.clone();

    let monitor_handle = task::spawn(async move {
        monitor_loop(monitor_config, monitor_state, monitor_shutdown).await;
    });

    let server_state = state.clone();
    let server_config = config.clone();
    let server_shutdown = shutdown_rx.clone();

    let server_handle = task::spawn(async move {
        if let Err(e) = control_server(server_config, server_state, server_shutdown).await {
            error!("control server error: {e:?}");
        }
    });

    signal::ctrl_c().await?;
    info!("shutdown signal received");
    let _ = shutdown_tx.send(true);

    let _ = monitor_handle.await;
    let _ = server_handle.await;

    info!("daemon stopped");
    Ok(())
}

async fn monitor_loop(
    config: Config,
    state: Arc<RwLock<Option<DaemonState>>>,
    mut shutdown: watch::Receiver<bool>,
) {
    let mut system = System::new_all();
    let mut interval = time::interval(Duration::from_secs(config.poll_interval));

    loop {
        tokio::select! {
            _ = interval.tick() => {
                system.refresh_all();

                let snapshot = build_snapshot(&system);
                let health = HealthStatus {
                    cpu_warn: snapshot.global_cpu_usage >= config.cpu_warn,
                    memory_warn: memory_usage_percent(&snapshot) >= config.mem_warn,
                    disk_warn: disk_usage_warn(&snapshot),
                };

                if health.cpu_warn {
                    warn!(cpu = snapshot.global_cpu_usage, "high CPU usage");
                }
                if health.memory_warn {
                    warn!(memory = memory_usage_percent(&snapshot), "high memory usage");
                }
                if health.disk_warn {
                    warn!("high disk usage detected");
                }

                let daemon_state = DaemonState { snapshot, health };
                if let Ok(mut guard) = state.write() {
                    *guard = Some(daemon_state);
                }
            }
            _ = shutdown.changed() => {
                if *shutdown.borrow() {
                    break;
                }
            }
        }
    }
}

fn build_snapshot(system: &System) -> ResourceSnapshot {
    let timestamp_unix_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();

    let mut processes: Vec<ProcessSnapshot> = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: proc_.name().to_string(),
            cpu_usage: proc_.cpu_usage(),
            memory: proc_.memory(),
        })
        .collect();

    processes.sort_by(|a, b| b.cpu_usage.partial_cmp(&a.cpu_usage).unwrap());
    processes.truncate(10);

    let disks = system
        .disks()
        .iter()
        .map(|d| DiskSnapshot {
            name: d.name().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).to_string(),
        })
        .collect();

    ResourceSnapshot {
        timestamp_unix_ms,
        total_memory: system.total_memory(),
        used_memory: system.used_memory(),
        total_swap: system.total_swap(),
        used_swap: system.used_swap(),
        global_cpu_usage: system.global_cpu_info().cpu_usage(),
        disks,
        top_processes: processes,
    }
}

fn memory_usage_percent(snapshot: &ResourceSnapshot) -> f32 {
    if snapshot.total_memory == 0 {
        0.0
    } else {
        (snapshot.used_memory as f32 / snapshot.total_memory as f32) * 100.0
    }
}

fn disk_usage_warn(snapshot: &ResourceSnapshot) -> bool {
    snapshot.disks.iter().any(|d| {
        if d.total_space == 0 {
            false
        } else {
            let used = d.total_space.saturating_sub(d.available_space);
            (used as f32 / d.total_space as f32) * 100.0 >= 90.0
        }
    })
}

async fn control_server(
    config: Config,
    state: Arc<RwLock<Option<DaemonState>>>,
    mut shutdown: watch::Receiver<bool>,
) -> Result<()> {
    let listener = TcpListener::bind(&config.bind_addr).await?;
    info!(bind_addr = %config.bind_addr, "control server listening");

    loop {
        tokio::select! {
            res = listener.accept() => {
                let (stream, addr) = res?;
                let state = state.clone();
                task::spawn(async move {
                    if let Err(e) = handle_client(stream, state).await {
                        warn!(client = %addr, "client error: {e:?}");
                    }
                });
            }
            _ = shutdown.changed() => {
                if *shutdown.borrow() {
                    break;
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: TcpStream,
    state: Arc<RwLock<Option<DaemonState>>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    writer.write_all(b"resource-daemon ready\n").await?;

    while let Some(line) = lines.next_line().await? {
        match line.trim() {
            "status" => {
                let response = {
                    let guard = state.read().ok();
                    if let Some(Some(st)) = guard.as_deref() {
                        serde_json::to_string(st)?
                    } else {
                        "{\"error\":\"no data yet\"}".to_string()
                    }
                };
                writer.write_all(response.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "health" => {
                let response = {
                    let guard = state.read().ok();
                    if let Some(Some(st)) = guard.as_deref() {
                        serde_json::to_string(&st.health)?
                    } else {
                        "{\"error\":\"no data yet\"}".to_string()
                    }
                };
                writer.write_all(response.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "quit" | "exit" => {
                writer.write_all(b"bye\n").await?;
                break;
            }
            "help" => {
                writer.write_all(b"commands: status, health, help, quit\n").await?;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}
