use anyhow::Result;
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    sync::Arc,
    time::Duration,
};
use tokio::{signal, sync::RwLock, time};
use tracing::{info, warn};
use tracing_subscriber::EnvFilter;

mod metrics;
mod policy;
mod actions;

use metrics::{Collector, ResourceSnapshot, SystemCollector};
use policy::{PolicyEngine, PolicyRule};
use actions::{ActionExecutor, SystemActionExecutor};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    sample_interval_ms: u64,
    cpu_high_threshold: f32,
    memory_high_threshold: f32,
    disk_high_threshold: f32,
    enable_actions: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_high_threshold: 85.0,
            memory_high_threshold: 90.0,
            disk_high_threshold: 90.0,
            enable_actions: false,
        }
    }
}

fn load_config(path: Option<PathBuf>) -> Result<Config> {
    if let Some(path) = path {
        let contents = fs::read_to_string(path)?;
        Ok(toml::from_str(&contents)?)
    } else {
        Ok(Config::default())
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let config = load_config(std::env::args().nth(1).map(PathBuf::from))?;
    info!("starting daemon");

    let shared_config = Arc::new(RwLock::new(config.clone()));
    let collector = SystemCollector::new();
    let policy_engine = PolicyEngine::new(vec![
        PolicyRule::cpu_high(config.cpu_high_threshold),
        PolicyRule::memory_high(config.memory_high_threshold),
        PolicyRule::disk_high(config.disk_high_threshold),
    ]);
    let executor = SystemActionExecutor::new(config.enable_actions);

    run_daemon(collector, policy_engine, executor, shared_config).await
}

async fn run_daemon<C, P, A>(
    collector: C,
    policy_engine: P,
    executor: A,
    config: Arc<RwLock<Config>>,
) -> Result<()>
where
    C: Collector + Send + Sync + 'static,
    P: PolicyEngine + Send + Sync + 'static,
    A: ActionExecutor + Send + Sync + 'static,
{
    let mut shutdown = signal::ctrl_c();
    let interval_ms = config.read().await.sample_interval_ms;
    let mut ticker = time::interval(Duration::from_millis(interval_ms));

    loop {
        tokio::select! {
            _ = &mut shutdown => {
                info!("shutdown requested");
                break;
            }
            _ = ticker.tick() => {
                match collector.collect().await {
                    Ok(snapshot) => {
                        handle_snapshot(&policy_engine, &executor, snapshot).await;
                    }
                    Err(e) => {
                        warn!("collection error: {e:?}");
                    }
                }
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}

async fn handle_snapshot<P, A>(policy_engine: &P, executor: &A, snapshot: ResourceSnapshot)
where
    P: PolicyEngine + Send + Sync,
    A: ActionExecutor + Send + Sync,
{
    let decisions = policy_engine.evaluate(&snapshot);

    for decision in decisions {
        info!(?decision, "policy decision");
        if decision.should_execute() {
            if let Err(e) = executor.execute(&decision).await {
                warn!("action failed: {e:?}");
            }
        }
    }
}
