```rust
use crate::metrics::ResourceSnapshot;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum DecisionKind {
    Alert,
    ThrottleCpu,
    CleanupMemory,
    CleanupDisk,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Decision {
    pub kind: DecisionKind,
    pub message: String,
    pub execute: bool,
}

impl Decision {
    pub fn should_execute(&self) -> bool {
        self.execute
    }
}

pub trait PolicyEngine {
    fn evaluate(&self, snapshot: &ResourceSnapshot) -> Vec<Decision>;
}

#[derive(Debug, Clone)]
pub struct PolicyRule {
    cpu_high: Option<f32>,
    memory_high: Option<f32>,
    disk_high: Option<f32>,
}

impl PolicyRule {
    pub fn cpu_high(threshold: f32) -> Self {
        Self {
            cpu_high: Some(threshold),
            memory_high: None,
            disk_high: None,
        }
    }

    pub fn memory_high(threshold: f32) -> Self {
        Self {
            cpu_high: None,
            memory_high: Some(threshold),
            disk_high: None,
        }
    }

    pub fn disk_high(threshold: f32) -> Self {
        Self {
            cpu_high: None,
            memory_high: None,
            disk_high: Some(threshold),
        }
    }
}

pub struct SimplePolicyEngine {
    rules: Vec<PolicyRule>,
}

impl SimplePolicyEngine {
    pub fn new(rules: Vec<PolicyRule>) -> Self {
        Self { rules }
    }
}

impl PolicyEngine for SimplePolicyEngine {
    fn evaluate(&self, snapshot: &ResourceSnapshot) -> Vec<Decision> {
        let mut decisions = Vec::new();

        for rule in &self.rules {
            if let Some(threshold) = rule.cpu_high {
                if snapshot.cpu_usage >= threshold {
                    decisions.push(Decision {
                        kind: DecisionKind::ThrottleCpu,
                        message: format!("CPU usage high: {:.1}%", snapshot.cpu_usage),
                        execute: true,
                    });
                }
            }

            if let Some(threshold) = rule.memory_high {
                if snapshot.memory_used_percent >= threshold {
                    decisions.push(Decision {
                        kind: DecisionKind::CleanupMemory,
                        message: format!("Memory usage high: {:.1}%", snapshot.memory_used_percent),
                        execute: true,
                    });
                }
            }

            if let Some(threshold) = rule.disk_high {
                if snapshot.disk_used_percent >= threshold {
                    decisions.push(Decision {
                        kind: DecisionKind::CleanupDisk,
                        message: format!("Disk usage high: {:.1}%", snapshot.disk_used_percent),
                        execute: true,
                    });
                }
            }
        }

        if decisions.is_empty() {
            decisions.push(Decision {
                kind: DecisionKind::Alert,
                message: "System within normal limits".to_string(),
                execute: false,
            });
        }

        decisions
    }
}

pub use SimplePolicyEngine as PolicyEngineImpl;
