```rust
use crate::state::SystemSnapshot;
use sysinfo::{DiskExt, ProcessExt, System, SystemExt};

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn sample(&mut self) -> SystemSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();

        let mem_usage_pct = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let disk_usage_pct = self
            .system
            .disks()
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                if total > 0 {
                    ((total - avail) as f32 / total as f32) * 100.0
                } else {
                    0.0
                }
            })
            .fold(0.0_f32, f32::max);

        SystemSnapshot::new(
            cpu_usage,
            mem_usage_pct,
            disk_usage_pct,
            total_memory,
            used_memory,
            total_swap,
            used_swap,
        )
    }

    pub fn top_processes_by_memory(&mut self, limit: usize) -> Vec<(i32, String, u64)> {
        self.system.refresh_processes();
        let mut procs: Vec<_> = self
            .system
            .processes()
            .iter()
            .map(|(pid, p)| (pid.as_u32() as i32, p.name().to_string(), p.memory()))
            .collect();

        procs.sort_by(|a, b| b.2.cmp(&a.2));
        procs.truncate(limit);
        procs
    }
}
