use anyhow::Result;
use config::Config;
use monitor::Monitor;
use tokio::time::{interval, Duration};
use tracing::{info, warn};

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let cfg = Config::load("sysd.toml")?;
    info!(?cfg, "Configuration loaded");

    let mut monitor = Monitor::new();
    let mut ticker = interval(Duration::from_millis(cfg.interval_ms));

    info!("System daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = monitor.sample();

                info!(
                    cpu_usage = snapshot.cpu_usage,
                    mem_usage_pct = snapshot.mem_usage_pct,
                    disk_usage_pct = snapshot.disk_usage_pct,
                    total_memory = snapshot.total_memory,
                    used_memory = snapshot.used_memory,
                    total_swap = snapshot.total_swap,
                    used_swap = snapshot.used_swap,
                    "System snapshot"
                );

                actions::handle_cpu_pressure(snapshot.cpu_usage, cfg.cpu_warn_pct);
                actions::handle_memory_pressure(snapshot.mem_usage_pct, cfg.mem_warn_pct);
                actions::handle_disk_pressure(snapshot.disk_usage_pct, cfg.disk_warn_pct);

                let top = monitor.top_processes_by_memory(cfg.process_scan_limit);
                for (pid, name, mem) in top {
                    warn!(pid = pid, process = %name, memory_kib = mem, "Top memory process");
                }
            }

            _ = tokio::signal::ctrl_c() => {
                info!("Shutdown signal received");
                break;
            }
        }
    }

    info!("System daemon stopped");
