use anyhow::Result;
use serde::Serialize;
use std::time::{Duration, Instant};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    memory_used_mb: u64,
    memory_total_mb: u64,
    swap_used_mb: u64,
    swap_total_mb: u64,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
    process_count: usize,
    disk_used_gb: u64,
    disk_total_gb: u64,
}

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_warning: f32,
    memory_warning_ratio: f32,
    load_warning_1: f64,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_warning: 85.0,
            memory_warning_ratio: 0.90,
            load_warning_1: 4.0,
        }
    }
}

struct ResourceMonitor {
    system: System,
    start: Instant,
}

impl ResourceMonitor {
    fn new() -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::new())
            .with_memory()
            .with_processes()
            .with_disks(DiskRefreshKind::new());

        let mut system = System::new_with_specifics(refresh);
        system.refresh_all();

        Self {
            system,
            start: Instant::now(),
        }
    }

    fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();
        let memory_used_mb = self.system.used_memory() / 1024;
        let memory_total_mb = self.system.total_memory() / 1024;
        let swap_used_mb = self.system.used_swap() / 1024;
        let swap_total_mb = self.system.total_swap() / 1024;

        let load = System::load_average();
        let process_count = self.system.processes().len();

        let (disk_used_gb, disk_total_gb) = self.disk_usage_gb();

        ResourceSnapshot {
            timestamp_ms: self.start.elapsed().as_millis(),
            cpu_usage_percent,
            memory_used_mb,
            memory_total_mb,
            swap_used_mb,
            swap_total_mb,
            load_avg_1: load.one,
            load_avg_5: load.five,
            load_avg_15: load.fifteen,
            process_count,
            disk_used_gb,
            disk_total_gb,
        }
    }

    fn disk_usage_gb(&self) -> (u64, u64) {
        let mut total_bytes = 0u64;
        let mut used_bytes = 0u64;

        for disk in self.system.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            total_bytes += total;
            used_bytes += total.saturating_sub(available);
        }

        (used_bytes / 1024 / 1024 / 1024, total_bytes / 1024 / 1024 / 1024)
    }
}

struct PolicyEngine {
    thresholds: Thresholds,
}

impl PolicyEngine {
    fn new(thresholds: Thresholds) -> Self {
        Self { thresholds }
    }

    fn evaluate(&self, snapshot: &ResourceSnapshot) -> Vec<String> {
        let mut actions = Vec::new();

        let memory_ratio = if snapshot.memory_total_mb > 0 {
            snapshot.memory_used_mb as f32 / snapshot.memory_total_mb as f32
        } else {
            0.0
        };

        if snapshot.cpu_usage_percent >= self.thresholds.cpu_warning {
            actions.push(format!(
                "CPU high: {:.1}% >= {:.1}%",
                snapshot.cpu_usage_percent, self.thresholds.cpu_warning
            ));
        }

        if memory_ratio >= self.thresholds.memory_warning_ratio {
            actions.push(format!(
                "Memory high: {:.1}% >= {:.1}%",
                memory_ratio * 100.0,
                self.thresholds.memory_warning_ratio * 100.0
            ));
        }

        if snapshot.load_avg_1 >= self.thresholds.load_warning_1 {
            actions.push(format!(
                "Load average high: {:.2} >= {:.2}",
                snapshot.load_avg_1, self.thresholds.load_warning_1
            ));
        }

        actions
    }
}

async fn run_daemon() -> Result<()> {
    let mut monitor = ResourceMonitor::new();
    let policy = PolicyEngine::new(Thresholds::default());

    let mut ticker = interval(Duration::from_secs(2));

    info!("resource daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = monitor.snapshot();
                let alerts = policy.evaluate(&snapshot);

                match serde_json::to_string(&snapshot) {
                    Ok(json) => info!(snapshot = %json, "resource snapshot"),
                    Err(e) => error!(error = %e, "failed to serialize snapshot"),
                }

                if !alerts.is_empty() {
                    for alert in alerts {
                        warn!(%alert, "policy alert");
                    }
                } else {
                    debug!("resource usage within thresholds");
                }
            }

            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .with_target(false)
        .compact()
        .init();

    if let Err(e) = run_daemon().await {
        error!(error = %e, "daemon exited with error");
        return Err(e);
    }

    Ok(())
}
```

