use anyhow::Result;
use clap::Parser;
use serde::Serialize;
use std::sync::Arc;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::sync::RwLock;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Parser, Debug, Clone)]
#[command(name = "sysd", version, about = "High-performance OS resource monitoring daemon")]
struct Args {
    /// Polling interval in seconds
    #[arg(long, default_value_t = 2)]
    interval_secs: u64,

    /// CPU usage threshold percentage
    #[arg(long, default_value_t = 85.0)]
    cpu_threshold: f32,

    /// Memory usage threshold percentage
    #[arg(long, default_value_t = 85.0)]
    memory_threshold: f32,

    /// Disk usage threshold percentage
    #[arg(long, default_value_t = 90.0)]
    disk_threshold: f32,

    /// Enable JSON event output
    #[arg(long, default_value_t = false)]
    json: bool,
}

#[derive(Debug, Clone)]
struct Config {
    interval: Duration,
    cpu_threshold: f32,
    memory_threshold: f32,
    disk_threshold: f32,
    json: bool,
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_used_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    disk_used_percent: f32,
    disk_used_bytes: u64,
    disk_total_bytes: u64,
    top_processes: Vec<ProcessStat>,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessStat {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
}

#[derive(Debug, Clone)]
struct DaemonState {
    last_snapshot: Option<ResourceSnapshot>,
}

impl DaemonState {
    fn new() -> Self {
        Self { last_snapshot: None }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let args = Args::parse();
    let config = Config {
        interval: Duration::from_secs(args.interval_secs),
        cpu_threshold: args.cpu_threshold,
        memory_threshold: args.memory_threshold,
        disk_threshold: args.disk_threshold,
        json: args.json,
    };

    info!("starting sysd daemon");

    let state = Arc::new(RwLock::new(DaemonState::new()));
    let monitor_state = Arc::clone(&state);
    let monitor_config = config.clone();

    let monitor_task = tokio::spawn(async move {
        run_monitor_loop(monitor_state, monitor_config).await;
    });

    tokio::select! {
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = monitor_task => {
            if let Err(e) = res {
                error!("monitor task failed: {}", e);
            }
        }
    }

    info!("sysd daemon stopped");
    Ok(())
}

async fn run_monitor_loop(state: Arc<RwLock<DaemonState>>, config: Config) {
    let mut ticker = interval(config.interval);

    // Build a system object with only the refreshes we need.
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    loop {
        ticker.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks_list();
        system.refresh_disks();
        system.refresh_processes();

        let snapshot = collect_snapshot(&system);
        {
            let mut guard = state.write().await;
            guard.last_snapshot = Some(snapshot.clone());
        }

        emit_snapshot(&snapshot, config.json);

        manage_resources(&snapshot, &config).await;
    }
}

fn collect_snapshot(system: &System) -> ResourceSnapshot {
    let timestamp_unix_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);

    let cpu_usage_percent = system.global_cpu_info().cpu_usage();
    let memory_total_bytes = system.total_memory() * 1024;
    let memory_used_bytes = system.used_memory() * 1024;
    let memory_used_percent = if memory_total_bytes > 0 {
        (memory_used_bytes as f32 / memory_total_bytes as f32) * 100.0
    } else {
        0.0
    };

    let disk_total_bytes: u64 = system.disks().iter().map(|d| d.total_space()).sum();
    let disk_available_bytes: u64 = system.disks().iter().map(|d| d.available_space()).sum();
    let disk_used_bytes = disk_total_bytes.saturating_sub(disk_available_bytes);
    let disk_used_percent = if disk_total_bytes > 0 {
        (disk_used_bytes as f32 / disk_total_bytes as f32) * 100.0
    } else {
        0.0
    };

    let mut processes: Vec<ProcessStat> = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessStat {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let top_processes = processes.into_iter().take(10).collect();

    ResourceSnapshot {
        timestamp_unix_ms,
        cpu_usage_percent,
        memory_used_percent,
        memory_used_bytes,
        memory_total_bytes,
        disk_used_percent,
        disk_used_bytes,
        disk_total_bytes,
        top_processes,
    }
}

fn emit_snapshot(snapshot: &ResourceSnapshot, json: bool) {
    if json {
        match serde_json::to_string(snapshot) {
            Ok(line) => info!("{}", line),
            Err(e) => warn!("failed to serialize snapshot as JSON: {}", e),
        }
    } else {
        info!(
            "cpu={:.1}% mem={:.1}% ({}/{}) disk={:.1}% ({}/{}) top_proc={}",
            snapshot.cpu_usage_percent,
            snapshot.memory_used_percent,
            snapshot.memory_used_bytes,
            snapshot.memory_total_bytes,
            snapshot.disk_used_percent,
            snapshot.disk_used_bytes,
            snapshot.disk_total_bytes,
            snapshot
                .top_processes
                .first()
                .map(|p| format!("{}:{} {:.1}%", p.pid, p.name, p.cpu_percent))
                .unwrap_or_else(|| "none".to_string())
        );
    }
}

async fn manage_resources(snapshot: &ResourceSnapshot, config: &Config) {
    if snapshot.cpu_usage_percent >= config.cpu_threshold {
        warn!(
            "high CPU usage detected: {:.1}% >= {:.1}%",
            snapshot.cpu_usage_percent, config.cpu_threshold
        );
        // Placeholder for remediation:
        // - lower priority of offending processes
        // - notify external controller
        // - trigger autoscaling
    }

    if snapshot.memory_used_percent >= config.memory_threshold {
        warn!(
            "high memory usage detected: {:.1}% >= {:.1}%",
            snapshot.memory_used_percent, config.memory_threshold
        );
        // Placeholder for remediation:
        // - reclaim caches
        // - identify memory-hungry processes
        // - request cleanup from managed services
    }

    if snapshot.disk_used_percent >= config.disk_threshold {
        warn!(
            "high disk usage detected: {:.1}% >= {:.1}%",
            snapshot.disk_used_percent, config.disk_threshold
        );
        // Placeholder for remediation:
        // - rotate logs
        // - delete temporary files
        // - alert administrator
    }
}
