use sysinfo::{CpuExt, DiskExt, System, SystemExt};

#[derive(Debug, Clone)]
pub struct Metrics {
    pub cpu_usage: f32,
    pub memory_used_percent: f32,
    pub disk_used_percent: f32,
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_used_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0.0f32;
        let mut used_disk = 0.0f32;

        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let available = disk.available_space() as f32;
            total_disk += total;
            used_disk += total - available;
        }

        let disk_used_percent = if total_disk > 0.0 {
            (used_disk / total_disk) * 100.0
        } else {
            0.0
        };

        Metrics {
            cpu_usage,
            memory_used_percent,
            disk_used_percent,
        }
    }
}
