## `src/policy.rs`

```rust
use crate::{config::Config, metrics::Metrics};
use tracing::{warn, info};

#[derive(Debug)]
pub enum Action {
    LogWarning(String),
    Noop,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &Metrics) -> Vec<Action> {
        let mut actions = Vec::new();

        if metrics.cpu_usage > self.config.cpu_alert_threshold {
            actions.push(Action::LogWarning(format!(
                "CPU usage high: {:.2}%",
                metrics.cpu_usage
            )));
        }

        if metrics.memory_used_percent > self.config.memory_alert_threshold {
            actions.push(Action::LogWarning(format!(
                "Memory usage high: {:.2}%",
                metrics.memory_used_percent
            )));
        }

        if metrics.disk_used_percent > self.config.disk_alert_threshold {
            actions.push(Action::LogWarning(format!(
                "Disk usage high: {:.2}%",
                metrics.disk_used_percent
            )));
        }

        if actions.is_empty() {
            actions.push(Action::Noop);
        }

        actions
    }

    pub fn execute(&self, actions: Vec<Action>) {
        for action in actions {
            match action {
                Action::LogWarning(msg) => warn!("{msg}"),
                Action::Noop => info!("All resource metrics within thresholds"),
            }
        }
    }
}
