use crate::{config::Config, metrics::MetricsCollector, policy::PolicyEngine};
use tokio::time::{interval, Duration};
use tracing::info;

pub struct Daemon {
    config: Config,
    collector: MetricsCollector,
    policy: PolicyEngine,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        let collector = MetricsCollector::new();
        let policy = PolicyEngine::new(config.clone());

        Self {
            config,
            collector,
            policy,
        }
    }

    pub async fn run(mut self) -> anyhow::Result<()> {
        let mut ticker = interval(Duration::from_secs(self.config.sample_interval_secs));

        info!(
            "daemon started with sample interval={}s",
            self.config.sample_interval_secs
        );

        loop {
            ticker.tick().await;

            let metrics = self.collector.collect();
            info!(
                "metrics: cpu={:.2}% mem={:.2}% disk={:.2}%",
                metrics.cpu_usage, metrics.memory_used_percent, metrics.disk_used_percent
            );

            let actions = self.policy.evaluate(&metrics);
            self.policy.execute(actions);
        }
    }
}
