```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    path::Path,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, NetworkRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
    signal,
    time,
};
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

const SOCKET_PATH: &str = "/tmp/sysd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    memory_total_kib: u64,
    memory_used_kib: u64,
    swap_total_kib: u64,
    swap_used_kib: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks_total_bytes: u64,
    disks_available_bytes: u64,
    network_received_bytes: u64,
    network_transmitted_bytes: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonStatus {
    uptime_secs: u64,
    last_snapshot: Option<ResourceSnapshot>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Status,
    Ping,
    SetInterval { millis: u64 },
    Shutdown,
}

#[derive(Debug, Serialize, Deserialize)]
struct Response {
    ok: bool,
    message: String,
    status: Option<DaemonStatus>,
}

struct SharedState {
    started_at: Instant,
    last_snapshot: Option<ResourceSnapshot>,
    sample_interval: Duration,
    shutdown: bool,
}

impl SharedState {
    fn new() -> Self {
        Self {
            started_at: Instant::now(),
            last_snapshot: None,
            sample_interval: SAMPLE_INTERVAL,
            shutdown: false,
        }
    }
}

fn collect_snapshot(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything())
            .with_networks(NetworkRefreshKind::everything()),
    );

    let load = System::load_average();

    let (disks_total_bytes, disks_available_bytes) = sys.disks().iter().fold((0, 0), |acc, d| {
        (acc.0 + d.total_space(), acc.1 + d.available_space())
    });

    let (network_received_bytes, network_transmitted_bytes) =
        sys.networks().iter().fold((0, 0), |acc, (_name, data)| {
            (acc.0 + data.received(), acc.1 + data.transmitted())
        });

    ResourceSnapshot {
        timestamp_ms: Instant::now().elapsed().as_millis(),
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        memory_total_kib: sys.total_memory(),
        memory_used_kib: sys.used_memory(),
        swap_total_kib: sys.total_swap(),
        swap_used_kib: sys.used_swap(),
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disks_total_bytes,
        disks_available_bytes,
        network_received_bytes,
        network_transmitted_bytes,
    }
}

fn status_from_state(state: &SharedState) -> DaemonStatus {
    DaemonStatus {
        uptime_secs: state.started_at.elapsed().as_secs(),
        last_snapshot: state.last_snapshot.clone(),
    }
}

async fn handle_client(mut stream: UnixStream, state: Arc<Mutex<SharedState>>) -> Result<()> {
    let mut buf = vec![0u8; 4096];
    let n = stream.read(&mut buf).await.context("read request")?;
    if n == 0 {
        return Ok(());
    }

    let req: Request = serde_json::from_slice(&buf[..n]).context("parse request")?;
    let mut state_guard = state.lock().unwrap();

    let resp = match req {
        Request::Ping => Response {
            ok: true,
            message: "pong".into(),
            status: None,
        },
        Request::Status => Response {
            ok: true,
            message: "status".into(),
            status: Some(status_from_state(&state_guard)),
        },
        Request::SetInterval { millis } => {
            let clamped = millis.clamp(250, 60_000);
            state_guard.sample_interval = Duration::from_millis(clamped);
            Response {
                ok: true,
                message: format!("sample interval set to {} ms", clamped),
                status: Some(status_from_state(&state_guard)),
            }
        }
        Request::Shutdown => {
            state_guard.shutdown = true;
            Response {
                ok: true,
                message: "shutdown requested".into(),
                status: Some(status_from_state(&state_guard)),
            }
        }
    };

    drop(state_guard);

    let data = serde_json::to_vec(&resp).context("serialize response")?;
    stream.write_all(&data).await.context("write response")?;
    stream.shutdown().await.ok();
    Ok(())
}

async fn monitor_loop(state: Arc<Mutex<SharedState>>) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything())
            .with_networks(NetworkRefreshKind::everything()),
    );

    loop {
        let interval = {
            let guard = state.lock().unwrap();
            if guard.shutdown {
                break;
            }
            guard.sample_interval
        };

        let snapshot = collect_snapshot(&mut sys);

        {
            let mut guard = state.lock().unwrap();
            guard.last_snapshot = Some(snapshot);
        }

        time::sleep(interval).await;
    }

    Ok(())
}

async fn serve_socket(state: Arc<Mutex<SharedState>>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).ok();
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("bind unix socket at {}", SOCKET_PATH))?;

    info!("listening on {}", SOCKET_PATH);

    loop {
        {
            let guard = state.lock().unwrap();
            if guard.shutdown {
                break;
            }
        }

        let (stream, _) = match listener.accept().await {
            Ok(v) => v,
            Err(e) => {
                warn!("accept error: {e}");
                continue;
            }
        };

        let state_cloned = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state_cloned).await {
                error!("client error: {e:#}");
            }
        });
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse().unwrap()))
        .init();

    let state = Arc::new(Mutex::new(SharedState::new()));

    let monitor_state = state.clone();
    let socket_state = state.clone();

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let socket_task = tokio::spawn(async move {
        if let Err(e) = serve_socket(socket_state).await {
            error!("socket server failed: {e:#}");
        }
    });

    info!("daemon started");

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received termination signal");
        }
        _ = async {
            loop {
                {
                    let guard = state.lock().unwrap();
                    if guard.shutdown {
                        break;
                    }
                }
                time::sleep(Duration::from_millis(250)).await;
            }
        } => {
            info!("shutdown requested via control socket");
        }
    }

    {
        let mut guard = state.lock().unwrap();
        guard.shutdown = true;
    }

    let _ = monitor_task.await;
    let _ = socket_task.await;

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).ok();
    }

    info!("daemon stopped");
    Ok(())
}
```

