## `src/monitor.rs`

```rust
use crate::types::SystemSnapshot;
use sysinfo::{Disks, System};

pub struct Monitor {
    system: System,
    disks: Disks,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh(true);

        Self { system, disks }
    }

    pub fn sample(&mut self) -> SystemSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh(true);

        let cpu_percent = self.system.global_cpu_usage();

        let total_memory_kib = self.system.total_memory();
        let used_memory_kib = self.system.used_memory();
        let total_swap_kib = self.system.total_swap();
        let used_swap_kib = self.system.used_swap();

        let memory_percent = if total_memory_kib > 0 {
            (used_memory_kib as f32 / total_memory_kib as f32) * 100.0
        } else {
            0.0
        };

        let disk_percent = self
            .disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                if total == 0 {
                    0.0
                } else {
                    ((total - avail) as f32 / total as f32) * 100.0
                }
            })
            .fold(0.0, f32::max);

        SystemSnapshot {
            cpu_percent,
            memory_percent,
            disk_percent,
            total_memory_kib,
            used_memory_kib,
            total_swap_kib,
            used_swap_kib,
        }
    }
}
```

