use crate::types::{DaemonConfig, SystemSnapshot};
use tracing::{info, warn};

pub fn evaluate_and_act(snapshot: &SystemSnapshot, cfg: &DaemonConfig) {
    if snapshot.cpu_percent >= cfg.thresholds.cpu_percent {
        warn!(
            cpu = snapshot.cpu_percent,
            threshold = cfg.thresholds.cpu_percent,
            "CPU usage threshold exceeded"
        );
        if cfg.enable_actions {
            info!("Action hook: would trigger CPU mitigation policy");
        }
    }

    if snapshot.memory_percent >= cfg.thresholds.memory_percent {
        warn!(
            memory = snapshot.memory_percent,
            threshold = cfg.thresholds.memory_percent,
            "Memory usage threshold exceeded"
        );
        if cfg.enable_actions {
            info!("Action hook: would trigger memory reclamation policy");
        }
    }

    if snapshot.disk_percent >= cfg.thresholds.disk_percent {
        warn!(
            disk = snapshot.disk_percent,
            threshold = cfg.thresholds.disk_percent,
            "Disk usage threshold exceeded"
        );
        if cfg.enable_actions {
            info!("Action hook: would trigger disk cleanup policy");
        }
    }
}
