## `src/daemon.rs`

```rust
use crate::{actions::evaluate_and_act, monitor::Monitor, types::DaemonConfig};
use std::time::Duration;
use tokio::time;
use tracing::info;

pub async fn run_daemon(cfg: DaemonConfig) -> anyhow::Result<()> {
    let mut monitor = Monitor::new();
    let interval = Duration::from_millis(cfg.sample_interval_ms);

    info!(
        sample_interval_ms = cfg.sample_interval_ms,
        enable_actions = cfg.enable_actions,
        "daemon started"
    );

    let mut ticker = time::interval(interval);

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = monitor.sample();

                info!(
                    cpu = snapshot.cpu_percent,
                    memory = snapshot.memory_percent,
                    disk = snapshot.disk_percent,
                    used_mem_kib = snapshot.used_memory_kib,
                    total_mem_kib = snapshot.total_memory_kib,
                    used_swap_kib = snapshot.used_swap_kib,
                    total_swap_kib = snapshot.total_swap_kib,
                    "system snapshot"
                );

                evaluate_and_act(&snapshot, &cfg);
            }

            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}
