use anyhow::{Context, Result};
use clap::Parser;
use serde::{Deserialize, Serialize};
use std::{
    path::PathBuf,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
};
use sysinfo::{CpuRefreshKind, DiskExt, Disks, LoadAvg, RefreshKind, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{broadcast, Mutex},
    time::{self, Duration},
};
use tracing::{error, info, warn};

#[derive(Parser, Debug)]
#[command(name = "sysd", version, about = "High-performance OS resource daemon")]
struct Args {
    /// Unix socket path for control commands
    #[arg(long, default_value = "/tmp/sysd.sock")]
    socket: String,

    /// Sampling interval in milliseconds
    #[arg(long, default_value_t = 1000)]
    interval_ms: u64,

    /// Log level filter
    #[arg(long, default_value = "info")]
    log_level: String,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    load_one: f64,
    load_five: f64,
    load_fifteen: f64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Status,
    Shutdown,
    SetInterval { interval_ms: u64 },
}

#[derive(Debug, Serialize)]
struct Response {
    ok: bool,
    message: String,
    snapshot: Option<MetricsSnapshot>,
    interval_ms: Option<u64>,
}

struct DaemonState {
    system: Mutex<System>,
    disks: Mutex<Disks>,
    interval_ms: AtomicU64,
}

impl DaemonState {
    fn new(interval_ms: u64) -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::new())
            .with_memory()
            .with_disks_list()
            .with_disks();

        let mut system = System::new_with_specifics(refresh);
        system.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self {
            system: Mutex::new(system),
            disks: Mutex::new(disks),
            interval_ms: AtomicU64::new(interval_ms),
        }
    }

    async fn snapshot(&self) -> MetricsSnapshot {
        let mut system = self.system.lock().await;
        let mut disks = self.disks.lock().await;

        system.refresh_cpu();
        system.refresh_memory();
        disks.refresh();

        let load = System::load_average();

        let disk_snapshots = disks
            .iter()
            .map(|d| DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: d.total_space(),
                available_space: d.available_space(),
                file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            })
            .collect();

        MetricsSnapshot {
            cpu_usage_percent: system.global_cpu_info().cpu_usage(),
            total_memory_kib: system.total_memory(),
            used_memory_kib: system.used_memory(),
            total_swap_kib: system.total_swap(),
            used_swap_kib: system.used_swap(),
            load_one: load.one,
            load_five: load.five,
            load_fifteen: load.fifteen,
            disks: disk_snapshots,
        }
    }

    fn interval_ms(&self) -> u64 {
        self.interval_ms.load(Ordering::Relaxed)
    }

    fn set_interval_ms(&self, ms: u64) {
        self.interval_ms.store(ms, Ordering::Relaxed);
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    tracing_subscriber::fmt()
        .with_env_filter(args.log_level)
        .with_target(false)
        .compact()
        .init();

    let socket_path = PathBuf::from(&args.socket);
    if socket_path.exists() {
        std::fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove existing socket {}", socket_path.display()))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket {}", socket_path.display()))?;

    info!("sysd starting");
    info!("control socket: {}", socket_path.display());

    let state = Arc::new(DaemonState::new(args.interval_ms));
    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let sampler_state = state.clone();
    let sampler_shutdown = shutdown_tx.subscribe();
    tokio::spawn(async move {
        run_sampler(sampler_state, sampler_shutdown).await;
    });

    let accept_state = state.clone();
    let accept_shutdown = shutdown_tx.subscribe();
    let accept_task = tokio::spawn(async move {
        run_accept_loop(listener, accept_state, accept_shutdown).await;
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown requested via signal");
        }
        res = accept_task => {
            if let Err(e) = res {
                error!("accept loop failed: {}", e);
            }
        }
    }

    let _ = shutdown_tx.send(());
    time::sleep(Duration::from_millis(200)).await;

    if socket_path.exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    info!("sysd stopped");
    Ok(())
}

async fn run_sampler(state: Arc<DaemonState>, mut shutdown: broadcast::Receiver<()>) {
    loop {
        let interval = state.interval_ms();
        let mut ticker = time::interval(Duration::from_millis(interval.max(100)));

        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = state.snapshot().await;
                info!(
                    cpu = snapshot.cpu_usage_percent,
                    mem_used_kib = snapshot.used_memory_kib,
                    mem_total_kib = snapshot.total_memory_kib,
                    swap_used_kib = snapshot.used_swap_kib,
                    load1 = snapshot.load_one,
                    load5 = snapshot.load_five,
                    load15 = snapshot.load_fifteen,
                    "resource snapshot"
                );
            }
            _ = shutdown.recv() => {
                info!("sampler shutting down");
                break;
            }
        }
    }
}

async fn run_accept_loop(
    listener: UnixListener,
    state: Arc<DaemonState>,
    mut shutdown: broadcast::Receiver<()>,
) {
    loop {
        tokio::select! {
            res = listener.accept() => {
                match res {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state).await {
                                warn!("client error: {}", e);
                            }
                        });
                    }
                    Err(e) => {
                        error!("accept error: {}", e);
                        break;
                    }
                }
            }
            _ = shutdown.recv() => {
                info!("accept loop shutting down");
                break;
            }
        }
    }
}

async fn handle_client(stream: UnixStream, state: Arc<DaemonState>) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: Command = serde_json::from_str(line.trim())
        .context("failed to parse command JSON")?;

    let response = match cmd {
        Command::Status => {
            let snapshot = state.snapshot().await;
            Response {
                ok: true,
                message: "ok".to_string(),
                snapshot: Some(snapshot),
                interval_ms: Some(state.interval_ms()),
            }
        }
        Command::Shutdown => {
            Response {
                ok: true,
                message: "shutdown requested".to_string(),
                snapshot: None,
                interval_ms: Some(state.interval_ms()),
            }
        }
        Command::SetInterval { interval_ms } => {
            if interval_ms < 100 {
                Response {
                    ok: false,
                    message: "interval_ms must be >= 100".to_string(),
                    snapshot: None,
                    interval_ms: Some(state.interval_ms()),
                }
            } else {
                state.set_interval_ms(interval_ms);
                Response {
                    ok: true,
                    message: format!("interval set to {} ms", interval_ms),
                    snapshot: None,
                    interval_ms: Some(interval_ms),
                }
            }
        }
    };

    let json = serde_json::to_string(&response)?;
    write_half.write_all(json.as_bytes()).await?;
    write_half.write_all(b"\n").await?;
    Ok(())
}
