```rust
use crate::config::Config;
use crate::error::DaemonError;
use crate::metrics::{ProcessMetric, Snapshot, SystemMetrics};
use sysinfo::{CpuExt, DiskExt, PidExt, ProcessExt, System, SystemExt};

pub struct Monitor {
    sys: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();
        Self { sys }
    }

    pub fn collect(&mut self, cfg: &Config) -> Result<Snapshot, DaemonError> {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_disks_list();
        self.sys.refresh_disks();

        if cfg.process_scan_enabled {
            self.sys.refresh_processes();
        }

        let cpu_usage_pct = self.sys.global_cpu_info().cpu_usage();

        let total_mem_mb = self.sys.total_memory() / 1024;
        let used_mem_mb = self.sys.used_memory() / 1024;
        let memory_used_pct = if total_mem_mb > 0 {
            (used_mem_mb as f32 / total_mem_mb as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total_mb = 0u64;
        let mut disk_used_mb = 0u64;
        for disk in self.sys.disks() {
            let total = disk.total_space() / 1024 / 1024;
            let available = disk.available_space() / 1024 / 1024;
            let used = total.saturating_sub(available);
            disk_total_mb += total;
            disk_used_mb += used;
        }

        let disk_used_pct = if disk_total_mb > 0 {
            (disk_used_mb as f32 / disk_total_mb as f32) * 100.0
        } else {
            0.0
        };

        let mut top_processes = Vec::new();
        if cfg.process_scan_enabled {
            let mut procs: Vec<_> = self
                .sys
                .processes()
                .iter()
                .map(|(pid, p)| ProcessMetric {
                    pid: pid.as_u32(),
                    name: p.name().to_string(),
                    cpu_usage_pct: p.cpu_usage(),
                    memory_used_mb: p.memory() / 1024,
                })
                .collect();

            procs.sort_by(|a, b| {
                b.cpu_usage_pct
                    .partial_cmp(&a.cpu_usage_pct)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });

            top_processes = procs.into_iter().take(10).collect();
        }

        Ok(Snapshot {
            system: SystemMetrics {
                cpu_usage_pct,
                memory_used_pct,
                memory_used_mb: used_mem_mb,
                memory_total_mb: total_mem_mb,
                disk_used_pct,
                disk_used_mb,
                disk_total_mb,
            },
            top_processes,
        })
    }
}
