```rust
use crate::config::Config;
use crate::metrics::Snapshot;
use serde::Serialize;

#[derive(Debug, Clone, Serialize)]
pub enum AlertLevel {
    Info,
    Warning,
    Critical,
}

#[derive(Debug, Clone, Serialize)]
pub enum AlertKind {
    CpuHigh,
    MemoryHigh,
    DiskHigh,
    ProcessHighCpu,
    ProcessHighMemory,
}

#[derive(Debug, Clone, Serialize)]
pub struct Alert {
    pub level: AlertLevel,
    pub kind: AlertKind,
    pub message: String,
    pub pid: Option<u32>,
    pub process_name: Option<String>,
}

pub struct PolicyEngine;

impl PolicyEngine {
    pub fn evaluate(cfg: &Config, snapshot: &Snapshot) -> Vec<Alert> {
        let mut alerts = Vec::new();

        if snapshot.system.cpu_usage_pct >= cfg.cpu_threshold_pct {
            alerts.push(Alert {
                level: AlertLevel::Warning,
                kind: AlertKind::CpuHigh,
                message: format!("CPU usage high: {:.1}%", snapshot.system.cpu_usage_pct),
                pid: None,
                process_name: None,
            });
        }

        if snapshot.system.memory_used_pct >= cfg.memory_threshold_pct {
            alerts.push(Alert {
                level: AlertLevel::Warning,
                kind: AlertKind::MemoryHigh,
                message: format!("Memory usage high: {:.1}%", snapshot.system.memory_used_pct),
                pid: None,
                process_name: None,
            });
        }

        if snapshot.system.disk_used_pct >= cfg.disk_threshold_pct {
            alerts.push(Alert {
                level: AlertLevel::Critical,
                kind: AlertKind::DiskHigh,
                message: format!("Disk usage high: {:.1}%", snapshot.system.disk_used_pct),
                pid: None,
                process_name: None,
            });
        }

        for p in &snapshot.top_processes {
            if p.cpu_usage_pct >= cfg.process_cpu_threshold_pct {
                alerts.push(Alert {
                    level: AlertLevel::Warning,
                    kind: AlertKind::ProcessHighCpu,
                    message: format!("Process {} high CPU: {:.1}%", p.name, p.cpu_usage_pct),
                    pid: Some(p.pid),
                    process_name: Some(p.name.clone()),
                });
            }

            if p.memory_used_mb >= cfg.process_memory_threshold_mb {
                alerts.push(Alert {
                    level: AlertLevel::Warning,
                    kind: AlertKind::ProcessHighMemory,
                    message: format!("Process {} high memory: {} MB", p.name, p.memory_used_mb),
                    pid: Some(p.pid),
                    process_name: Some(p.name.clone()),
                });
            }
        }

        alerts
    }
}
