use crate::error::DaemonError;
use crate::policy::{Alert, AlertKind};
use tracing::{info, warn};

pub struct ActionManager;

impl ActionManager {
    pub fn new() -> Self {
        Self
    }

    pub fn handle_alert(&self, alert: &Alert) -> Result<(), DaemonError> {
        match alert.kind {
            AlertKind::CpuHigh => {
                warn!(message = %alert.message, "CPU alert");
            }
            AlertKind::MemoryHigh => {
                warn!(message = %alert.message, "Memory alert");
            }
            AlertKind::DiskHigh => {
                warn!(message = %alert.message, "Disk alert");
            }
            AlertKind::ProcessHighCpu | AlertKind::ProcessHighMemory => {
                warn!(
                    message = %alert.message,
                    pid = ?alert.pid,
                    process = ?alert.process_name,
                    "Process alert"
                );
            }
        }

        info!("Alert handled");
        Ok(())
    }
}
