## `src/daemon.rs`

```rust
use crate::actions::ActionManager;
use crate::config::Config;
use crate::monitor::Monitor;
use crate::policy::PolicyEngine;
use std::time::Duration;
use tokio::signal;
use tracing::{error, info};

pub struct Daemon {
    cfg: Config,
    monitor: Monitor,
    actions: ActionManager,
}

impl Daemon {
    pub fn new(cfg: Config) -> Self {
        Self {
            cfg,
            monitor: Monitor::new(),
            actions: ActionManager::new(),
        }
    }

    pub async fn run(&mut self) -> anyhow::Result<()> {
        info!("daemon starting");

        let mut interval = tokio::time::interval(Duration::from_millis(self.cfg.interval_ms));

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    match self.monitor.collect(&self.cfg) {
                        Ok(snapshot) => {
                            let alerts = PolicyEngine::evaluate(&self.cfg, &snapshot);

                            tracing::info!(
                                cpu = snapshot.system.cpu_usage_pct,
                                memory = snapshot.system.memory_used_pct,
                                disk = snapshot.system.disk_used_pct,
                                alerts = alerts.len(),
                                "snapshot collected"
                            );

                            if self.cfg.enable_actions {
                                for alert in alerts {
                                    if let Err(e) = self.actions.handle_alert(&alert) {
                                        error!(error = %e, "failed to handle alert");
                                    }
                                }
                            } else {
                                for alert in alerts {
                                    info!(kind = ?alert.kind, message = %alert.message, "alert");
                                }
                            }
                        }
                        Err(e) => {
                            error!(error = %e, "monitor collection failed");
                        }
                    }
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}
