## `src/metrics.rs`

```rust
use serde::{Deserialize, Serialize};
use sysinfo::{CpuExt, DiskExt, NetworkExt, System, SystemExt};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MetricsSnapshot {
    pub cpu_usage_percent: f32,
    pub memory_used_percent: f32,
    pub disk_used_percent: f32,
    pub network_rx_bytes: u64,
    pub network_tx_bytes: u64,
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> MetricsSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_networks_list();
        self.system.refresh_networks();

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_used_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_used_percent = 0.0;
        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let available = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - available) / total) * 100.0;
                if used > disk_used_percent {
                    disk_used_percent = used;
                }
            }
        }

        let mut network_rx_bytes = 0;
        let mut network_tx_bytes = 0;
        for (_name, data) in self.system.networks() {
            network_rx_bytes += data.received();
            network_tx_bytes += data.transmitted();
        }

        MetricsSnapshot {
            cpu_usage_percent,
            memory_used_percent,
            disk_used_percent,
            network_rx_bytes,
            network_tx_bytes,
        }
    }
}
