## `src/actions.rs`

```rust
use crate::config::Config;
use crate::metrics::MetricsSnapshot;
use tracing::{info, warn};

#[derive(Debug, Clone)]
pub enum Action {
    LogWarning(String),
    RecommendScaleUp(String),
    ThrottleNonCriticalWork(String),
}

pub fn evaluate_actions(metrics: &MetricsSnapshot, config: &Config) -> Vec<Action> {
    let mut actions = Vec::new();

    if metrics.cpu_usage_percent >= config.cpu_warn_threshold {
        actions.push(Action::LogWarning(format!(
            "High CPU usage: {:.2}%",
            metrics.cpu_usage_percent
        )));
        actions.push(Action::ThrottleNonCriticalWork(
            "CPU threshold exceeded".to_string(),
        ));
    }

    if metrics.memory_used_percent >= config.mem_warn_threshold {
        actions.push(Action::LogWarning(format!(
            "High memory usage: {:.2}%",
            metrics.memory_used_percent
        )));
        actions.push(Action::RecommendScaleUp(
            "Memory threshold exceeded".to_string(),
        ));
    }

    if metrics.disk_used_percent >= config.disk_warn_threshold {
        actions.push(Action::LogWarning(format!(
            "High disk usage: {:.2}%",
            metrics.disk_used_percent
        )));
    }

    actions
}

pub fn execute_actions(actions: &[Action]) {
    for action in actions {
        match action {
            Action::LogWarning(msg) => warn!("{}", msg),
            Action::RecommendScaleUp(msg) => info!("Recommendation: {}", msg),
            Action::ThrottleNonCriticalWork(msg) => info!("Action: {}", msg),
        }
    }
}
```

