## `src/control.rs`

```rust
use crate::config::Config;
use crate::metrics::MetricsSnapshot;
use anyhow::Result;
use serde_json::json;
use std::sync::{Arc, RwLock};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;
use tracing::{error, info};

pub async fn run_control_server(
    bind_addr: String,
    config: Arc<RwLock<Config>>,
    latest_metrics: Arc<RwLock<Option<MetricsSnapshot>>>,
) -> Result<()> {
    let listener = TcpListener::bind(&bind_addr).await?;
    info!("Control server listening on {}", bind_addr);

    loop {
        let (mut socket, peer) = listener.accept().await?;
        let config = Arc::clone(&config);
        let latest_metrics = Arc::clone(&latest_metrics);

        tokio::spawn(async move {
            let mut buf = vec![0u8; 1024];
            match socket.read(&mut buf).await {
                Ok(n) if n > 0 => {
                    let request = String::from_utf8_lossy(&buf[..n]).trim().to_string();

                    let response = match request.as_str() {
                        "status" => {
                            let metrics = latest_metrics.read().ok().and_then(|m| m.clone());
                            json!({
                                "ok": true,
                                "metrics": metrics
                            })
                            .to_string()
                        }
                        "config" => {
                            let cfg = config.read().map(|c| c.clone()).unwrap_or_default();
                            json!({
                                "ok": true,
                                "config": cfg
                            })
                            .to_string()
                        }
                        _ => json!({
                            "ok": false,
                            "error": "unknown command; use status|config"
                        })
                        .to_string(),
                    };

                    if let Err(e) = socket.write_all(response.as_bytes()).await {
                        error!("Failed to write response to {}: {}", peer, e);
                    }
                }
                Ok(_) => {}
                Err(e) => error!("Read error from {}: {}", peer, e),
            }
        });
    }
}
```

