## `src/daemon.rs`

```rust
use crate::actions::{evaluate_actions, execute_actions};
use crate::config::Config;
use crate::metrics::{MetricsCollector, MetricsSnapshot};
use anyhow::Result;
use std::sync::{Arc, RwLock};
use tokio::time::{sleep, Duration};
use tracing::info;

pub async fn run_daemon(
    config: Arc<RwLock<Config>>,
    latest_metrics: Arc<RwLock<Option<MetricsSnapshot>>>,
) -> Result<()> {
    let mut collector = MetricsCollector::new();

    loop {
        let cfg = config.read().map(|c| c.clone()).unwrap_or_default();
        let metrics = collector.collect();

        if let Ok(mut slot) = latest_metrics.write() {
            *slot = Some(metrics.clone());
        }

        info!(
            cpu = metrics.cpu_usage_percent,
            mem = metrics.memory_used_percent,
            disk = metrics.disk_used_percent,
            rx = metrics.network_rx_bytes,
            tx = metrics.network_tx_bytes,
            "metrics collected"
        );

        let actions = evaluate_actions(&metrics, &cfg);
        execute_actions(&actions);

        sleep(Duration::from_secs(cfg.sample_interval_secs)).await;
    }
}
```

