# `src/policy.rs`

```rust
use crate::{config::ThresholdConfig, metrics::Metrics};

#[derive(Debug, Clone)]
pub enum PolicyDecision {
    Healthy,
    Warn(Vec<String>),
    Critical(Vec<String>),
}

pub struct PolicyEngine {
    thresholds: ThresholdConfig,
}

impl PolicyEngine {
    pub fn new(thresholds: ThresholdConfig) -> Self {
        Self { thresholds }
    }

    pub fn evaluate(&self, metrics: &Metrics) -> PolicyDecision {
        let mut warnings = Vec::new();
        let mut critical = Vec::new();

        if metrics.cpu_percent >= self.thresholds.cpu_percent {
            critical.push(format!(
                "CPU usage high: {:.1}% >= {:.1}%",
                metrics.cpu_percent, self.thresholds.cpu_percent
            ));
        }

        if metrics.memory_percent >= self.thresholds.memory_percent {
            critical.push(format!(
                "Memory usage high: {:.1}% >= {:.1}%",
                metrics.memory_percent, self.thresholds.memory_percent
            ));
        }

        if metrics.load_avg_1m >= self.thresholds.load_avg_1m {
            warnings.push(format!(
                "Load average high: {:.2} >= {:.2}",
                metrics.load_avg_1m, self.thresholds.load_avg_1m
            ));
        }

        if metrics.process_count >= self.thresholds.process_count {
            warnings.push(format!(
                "Process count high: {} >= {}",
                metrics.process_count, self.thresholds.process_count
            ));
        }

        if !critical.is_empty() {
            PolicyDecision::Critical(critical)
        } else if !warnings.is_empty() {
            PolicyDecision::Warn(warnings)
        } else {
            PolicyDecision::Healthy
        }
    }
}
