# `src/daemon.rs`

```rust
use crate::{config::Config, manager::ResourceManager, metrics::MetricsCollector, policy::PolicyEngine};
use tokio::time::{interval, Duration};
use tracing::info;

pub async fn run_daemon(config: Config) -> anyhow::Result<()> {
    let mut collector = MetricsCollector::new();
    let policy = PolicyEngine::new(config.thresholds.clone());
    let manager = ResourceManager::new(config.actions.clone());

    let mut ticker = interval(Duration::from_millis(config.daemon.interval_ms));

    info!("daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let metrics = collector.collect();
                let decision = policy.evaluate(&metrics);
                manager.handle_decision(decision, &metrics).await;
            }
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}
