use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, ProcessesToUpdate, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
    process_scan_enabled: bool,
    max_processes_to_log: usize,
    pid_file: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_warn_percent: 85.0,
            mem_warn_percent: 90.0,
            disk_warn_percent: 90.0,
            process_scan_enabled: true,
            max_processes_to_log: 10,
            pid_file: Some("/var/run/sysd.pid".to_string()),
        }
    }
}

impl Config {
    fn load(path: Option<&str>) -> Result<Self> {
        if let Some(path) = path {
            let content = fs::read_to_string(path)
                .with_context(|| format!("failed to read config file: {path}"))?;
            let cfg: Self = toml::from_str(&content)
                .with_context(|| format!("failed to parse config file: {path}"))?;
            Ok(cfg)
        } else {
            Ok(Self::default())
        }
    }
}

struct Daemon {
    cfg: Config,
    system: System,
    disks: Disks,
}

impl Daemon {
    fn new(cfg: Config) -> Self {
        let system = System::new_with_specifics(
            RefreshKind::nothing()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory()
                .with_processes(sysinfo::ProcessRefreshKind::everything()),
        );

        let disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

        Self { cfg, system, disks }
    }

    fn refresh(&mut self) {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.system.refresh_processes(ProcessesToUpdate::All, true);
        self.disks.refresh(true);
    }

    fn cpu_usage_percent(&self) -> f32 {
        self.system.global_cpu_usage()
    }

    fn memory_usage_percent(&self) -> f32 {
        let total = self.system.total_memory() as f32;
        let used = self.system.used_memory() as f32;
        if total <= 0.0 {
            0.0
        } else {
            (used / total) * 100.0
        }
    }

    fn disk_usage_percent(&self) -> f32 {
        let mut total = 0u128;
        let mut used = 0u128;

        for disk in self.disks.list() {
            let space_total = disk.total_space() as u128;
            let space_avail = disk.available_space() as u128;
            total += space_total;
            used += space_total.saturating_sub(space_avail);
        }

        if total == 0 {
            0.0
        } else {
            (used as f32 / total as f32) * 100.0
        }
    }

    fn log_top_processes(&self) {
        if !self.cfg.process_scan_enabled {
            return;
        }

        let mut procs: Vec<_> = self.system.processes().values().collect();
        procs.sort_by(|a, b| {
            b.cpu_usage()
                .partial_cmp(&a.cpu_usage())
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        for p in procs.into_iter().take(self.cfg.max_processes_to_log) {
            debug!(
                pid = ?p.pid(),
                name = %p.name().to_string_lossy(),
                cpu = p.cpu_usage(),
                mem = p.memory(),
                "process snapshot"
            );
        }
    }

    fn enforce_policies(&self, cpu: f32, mem: f32, disk: f32) {
        if cpu >= self.cfg.cpu_warn_percent {
            warn!(cpu, threshold = self.cfg.cpu_warn_percent, "high CPU usage detected");
        }

        if mem >= self.cfg.mem_warn_percent {
            warn!(mem, threshold = self.cfg.mem_warn_percent, "high memory usage detected");
        }

        if disk >= self.cfg.disk_warn_percent {
            warn!(disk, threshold = self.cfg.disk_warn_percent, "high disk usage detected");
        }

        // Placeholder for future actions:
        // - send signal to offending process
        // - adjust cgroup limits
        // - trigger cleanup jobs
        // - notify external controller
    }

    fn write_pid_file(&self) -> Result<()> {
        if let Some(ref pid_path) = self.cfg.pid_file {
            let pid = std::process::id();
            fs::write(pid_path, pid.to_string())
                .with_context(|| format!("failed to write pid file: {pid_path}"))?;
        }
        Ok(())
    }

    fn remove_pid_file(&self) {
        if let Some(ref pid_path) = self.cfg.pid_file {
            let _ = fs::remove_file(pid_path);
        }
    }

    async fn run(mut self) -> Result<()> {
        self.write_pid_file()?;

        let mut ticker = interval(Duration::from_millis(self.cfg.sample_interval_ms));
        let start = Instant::now();

        info!("daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let cycle_start = Instant::now();

                    self.refresh();

                    let cpu = self.cpu_usage_percent();
                    let mem = self.memory_usage_percent();
                    let disk = self.disk_usage_percent();

                    info!(
                        uptime_secs = start.elapsed().as_secs(),
                        cpu,
                        mem,
                        disk,
                        "resource snapshot"
                    );

                    self.enforce_policies(cpu, mem, disk);
                    self.log_top_processes();

                    let elapsed = cycle_start.elapsed();
                    debug!(ms = elapsed.as_millis(), "sampling cycle complete");
                }

                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        self.remove_pid_file();
        info!("daemon stopped");
        Ok(())
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info".to_string()),
        )
        .init();

    let config_path = std::env::args().nth(1);
    let cfg = Config::load(config_path.as_deref())?;

    info!(?cfg, "loaded configuration");

    let daemon = Daemon::new(cfg);
    daemon.run().await
}
