```rust
use crate::{config::Config, metrics::Metrics};
use sysinfo::{CpuRefreshKind, DiskExt, Disks, ProcessExt, RefreshKind, System, SystemExt};

pub struct Monitor {
    system: System,
    disks: Disks,
}

impl Monitor {
    pub fn new() -> Self {
        let system = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory()
                .with_processes()
                .with_disks_list()
                .with_disks(),
        );
        let disks = Disks::new_with_refreshed_list();

        Self { system, disks }
    }

    pub fn sample(&mut self, _cfg: &Config) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh_list();
        self.disks.refresh();

        let cpu = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let memory_usage = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0u64;
        let mut used_disk = 0u64;

        for disk in self.disks.list() {
            let total = disk.total_space();
            let available = disk.available_space();
            total_disk += total;
            used_disk += total.saturating_sub(available);
        }

        let disk_usage = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        Metrics {
            cpu_usage_percent: cpu,
            memory_usage_percent: memory_usage,
            disk_usage_percent: disk_usage,
            total_memory,
            used_memory,
            total_disk,
            used_disk,
        }
    }

    pub fn top_processes(&mut self, limit: usize) -> Vec<(String, f32)> {
        let mut procs: Vec<(String, f32)> = self
            .system
            .processes()
            .iter()
            .map(|(_, p)| (p.name().to_string(), p.cpu_usage()))
            .collect();

        procs.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        procs.truncate(limit);
        procs
    }
}
```

