## `src/daemon.rs`

```rust
use crate::{actions::ActionEngine, config::Config, monitor::Monitor};
use tokio::time::{interval, Duration};
use tracing::{info, warn};

pub struct Daemon {
    cfg: Config,
    monitor: Monitor,
    actions: ActionEngine,
}

impl Daemon {
    pub fn new(cfg: Config) -> Self {
        let actions = ActionEngine::new(cfg.enable_actions);
        Self {
            cfg,
            monitor: Monitor::new(),
            actions,
        }
    }

    pub async fn run(&mut self) -> anyhow::Result<()> {
        let mut ticker = interval(Duration::from_secs(self.cfg.sample_interval_secs));

        info!("system daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let metrics = self.monitor.sample(&self.cfg);

                    info!(
                        cpu = metrics.cpu_usage_percent,
                        memory = metrics.memory_usage_percent,
                        disk = metrics.disk_usage_percent,
                        "resource snapshot"
                    );

                    if metrics.cpu_usage_percent > self.cfg.cpu_warn_percent {
                        warn!("CPU warning threshold exceeded: {:.2}%", metrics.cpu_usage_percent);
                    }
                    if metrics.memory_usage_percent > self.cfg.memory_warn_percent {
                        warn!("Memory warning threshold exceeded: {:.2}%", metrics.memory_usage_percent);
                    }
                    if metrics.disk_usage_percent > self.cfg.disk_warn_percent {
                        warn!("Disk warning threshold exceeded: {:.2}%", metrics.disk_usage_percent);
                    }

                    let top = self.monitor.top_processes(self.cfg.process_scan_limit);
                    for (name, cpu) in top.iter().take(5) {
                        info!(process = %name, cpu = cpu, "top process");
                    }

                    self.actions.evaluate(&metrics);
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}
