use daemonize::Daemonize;
use log::{error, info, warn};
use simplelog::{Config, LevelFilter, WriteLogger};
use std::fs::File;
use std::thread;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};

const LOG_FILE: &str = "/tmp/resourced.log";
const INTERVAL_SECS: u64 = 5;

// Example thresholds
const HIGH_CPU_THRESHOLD: f32 = 85.0;
const HIGH_MEM_THRESHOLD: f32 = 90.0;
const HIGH_DISK_THRESHOLD: f32 = 90.0;

fn main() {
    // Setup logging
    let log_file = File::create(LOG_FILE).expect("failed to create log file");
    WriteLogger::init(LevelFilter::Info, Config::default(), log_file)
        .expect("failed to initialize logger");

    // Detach into background
    let daemonize = Daemonize::new()
        .working_directory("/")
        .umask(0o027);

    match daemonize.start() {
        Ok(_) => info!("resourced daemon started"),
        Err(e) => {
            eprintln!("Failed to daemonize: {}", e);
            return;
        }
    }

    let mut system = System::new_all();

    loop {
        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_memory = system.total_memory() as f32;
        let used_memory = system.used_memory() as f32;
        let mem_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_usage = 0.0;
        for disk in system.disks() {
            let total = disk.total_space() as f32;
            let available = disk.available_space() as f32;
            if total > 0.0 {
                let used = total - available;
                let usage = (used / total) * 100.0;
                if usage > disk_usage {
                    disk_usage = usage;
                }
            }
        }

        info!(
            "CPU: {:.1}%, MEM: {:.1}%, DISK: {:.1}%",
            cpu_usage, mem_usage, disk_usage
        );

        if cpu_usage > HIGH_CPU_THRESHOLD {
            warn!("High CPU usage detected: {:.1}%", cpu_usage);
        }

        if mem_usage > HIGH_MEM_THRESHOLD {
            warn!("High memory usage detected: {:.1}%", mem_usage);
        }

        if disk_usage > HIGH_DISK_THRESHOLD {
            warn!("High disk usage detected: {:.1}%", disk_usage);
        }

        // Minimal management action hook:
        // In a real daemon, this could trigger cleanup, throttling, alerts, etc.
        if cpu_usage > HIGH_CPU_THRESHOLD || mem_usage > HIGH_MEM_THRESHOLD || disk_usage > HIGH_DISK_THRESHOLD {
            info!("Resource threshold exceeded; management hook invoked");
        }

        thread::sleep(Duration::from_secs(INTERVAL_SECS));
    }
}
