```rust
use anyhow::Result;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use std::time::Duration;
use sysinfo::{Disks, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Clone, Debug)]
struct Config {
    sample_period: Duration,
    memory_warn_threshold_percent: f32,
    pid_to_manage: Option<i32>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_period: Duration::from_secs(2),
            memory_warn_threshold_percent: 85.0,
            pid_to_manage: None,
        }
    }
}

struct Daemon {
    cfg: Config,
    system: System,
    disks: Disks,
}

impl Daemon {
    fn new(cfg: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh(true);

        Self { cfg, system, disks }
    }

    fn sample(&mut self) {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh(true);

        let cpu = self.system.global_cpu_usage();
        let total_mem = self.system.total_memory() as f32;
        let used_mem = self.system.used_memory() as f32;
        let mem_pct = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;

        for disk in self.disks.list() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(avail);
        }

        let disk_pct = if disk_total > 0 {
            (disk_used as f64 / disk_total as f64) * 100.0
        } else {
            0.0
        };

        info!(
            cpu_percent = cpu,
            memory_percent = mem_pct,
            disk_percent = disk_pct,
            "resource sample"
        );

        if mem_pct >= self.cfg.memory_warn_threshold_percent {
            warn!(
                memory_percent = mem_pct,
                threshold = self.cfg.memory_warn_threshold_percent,
                "memory usage threshold exceeded"
            );

            if let Some(pid) = self.cfg.pid_to_manage {
                let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
                warn!(pid = pid, "sent SIGTERM to managed process");
            }
        }
    }

    async fn run(mut self) -> Result<()> {
        let mut ticker = interval(self.cfg.sample_period);

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    self.sample();
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown requested");
                    break;
                }
            }
        }

        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = Config::default();
    let daemon = Daemon::new(cfg);

    info!("daemon starting");
    daemon.run().await?;
    info!("daemon stopped");

    Ok(())
}
```

