use anyhow::Result;
use serde::Deserialize;
use std::fs;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::time::interval;

#[derive(Debug, Deserialize, Clone)]
struct Config {
    poll_interval_ms: u64,
    cpu_threshold: f32,
    memory_threshold: f32,
    disk_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_threshold: 85.0,
            memory_threshold: 90.0,
            disk_threshold: 90.0,
        }
    }
}

fn load_config() -> Config {
    let path = "resmon.toml";
    match fs::read_to_string(path) {
        Ok(contents) => toml::from_str(&contents).unwrap_or_default(),
        Err(_) => Config::default(),
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = load_config();
    let mut system = System::new_all();
    let mut ticker = interval(Duration::from_millis(config.poll_interval_ms));

    println!("resmon-daemon started");

    loop {
        ticker.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks_list();
        system.refresh_disks();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_memory = system.total_memory() as f32;
        let used_memory = system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut max_disk_usage = 0.0_f32;
        for disk in system.disks() {
            let total = disk.total_space() as f32;
            let available = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - available) / total) * 100.0;
                if used > max_disk_usage {
                    max_disk_usage = used;
                }
            }
        }

        println!(
            "CPU: {:>5.1}% | MEM: {:>5.1}% | DISK: {:>5.1}%",
            cpu_usage, memory_usage, max_disk_usage
        );

        if cpu_usage > config.cpu_threshold {
            eprintln!("warning: CPU usage above threshold: {:.1}%", cpu_usage);
        }
        if memory_usage > config.memory_threshold {
            eprintln!("warning: memory usage above threshold: {:.1}%", memory_usage);
        }
        if max_disk_usage > config.disk_threshold {
            eprintln!("warning: disk usage above threshold: {:.1}%", max_disk_usage);
        }
    }
}
