    // Redirect daemon output to files.
    let stdout = File::create("/tmp/resource-daemon.out").unwrap();
    let stderr = File::create("/tmp/resource-daemon.err").unwrap();

    let daemonize = Daemonize::new()
        .pid_file("/tmp/resource-daemon.pid")
        .working_directory("/")
        .stdout(stdout)
        .stderr(stderr);

    match daemonize.start() {
