#[derive(Parser, Debug)]
#[command(name = "resourced")]
#[command(about = "Minimal OS resource monitoring daemon")]
struct Args {
    /// Poll interval in seconds
    #[arg(short, long, default_value_t = 2)]
    interval: u64,

    /// Memory usage threshold percentage to trigger action
    #[arg(short, long, default_value_t = 90.0)]
    mem_threshold: f32,

    /// Optional PID to signal when threshold is exceeded
    #[arg(long)]
    target_pid: Option<i32>,
}

fn main() -> Result<()> {
    env_logger::init();
    let args = Args::parse();

    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    info!("resourced started");
    info!(
        "interval={}s mem_threshold={}%",
        args.interval, args.mem_threshold
    );

    loop {
        system.refresh_cpu();
        system.refresh_memory();

        let total_mem = system.total_memory() as f32;
        let used_mem = system.used_memory() as f32;
        let mem_pct = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let cpu_usage: f32 = system.global_cpu_info().cpu_usage();
        let load_avg = System::load_average();

        info!(
            "cpu={:.1}% mem={:.1}% used={}MB total={}MB loadavg=({:.2}, {:.2}, {:.2})",
            cpu_usage,
            mem_pct,
            used_mem / 1024,
            total_mem / 1024,
            load_avg.one,
            load_avg.five,
            load_avg.fifteen
        );

        if mem_pct >= args.mem_threshold {
            warn!(
                "memory threshold exceeded: {:.1}% >= {:.1}%",
                mem_pct, args.mem_threshold
            );

            if let Some(pid) = args.target_pid {
                warn!("sending SIGTERM to pid {}", pid);
                let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
            }
        }

        thread::sleep(Duration::from_secs(args.interval));
    }
}
