use anyhow::{Context, Result};
use serde::Deserialize;
use std::{fs, path::Path, time::Duration};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    poll_interval_ms: u64,
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
    top_processes: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_warn_percent: 80.0,
            mem_warn_percent: 80.0,
            disk_warn_percent: 90.0,
            top_processes: 5,
        }
    }
}

fn load_config() -> Result<Config> {
    let path = Path::new("resmon.toml");
    if path.exists() {
        let data = fs::read_to_string(path).context("failed to read resmon.toml")?;
        let cfg: Config = toml::from_str(&data).context("failed to parse resmon.toml")?;
        Ok(cfg)
    } else {
        Ok(Config::default())
    }
}

fn percent_used(total: u64, used: u64) -> f32 {
    if total == 0 {
        0.0
    } else {
        (used as f32 / total as f32) * 100.0
    }
}

fn disk_usage_percent(sys: &System) -> f32 {
    let total: u64 = sys.disks().iter().map(|d| d.total_space()).sum();
    let avail: u64 = sys.disks().iter().map(|d| d.available_space()).sum();
    let used = total.saturating_sub(avail);
    percent_used(total, used)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = load_config()?;
    info!("starting resmon-daemon with config: {:?}", cfg);

    let mut sys = System::new_all();
    let mut tick = interval(Duration::from_millis(cfg.poll_interval_ms));

    loop {
        tokio::select! {
            _ = tick.tick() => {
                sys.refresh_all();

                let cpu = sys.global_cpu_info().cpu_usage();
                let total_mem = sys.total_memory();
                let used_mem = sys.used_memory();
                let mem = percent_used(total_mem, used_mem);
                let disk = disk_usage_percent(&sys);

                info!(
                    "cpu={:.1}% mem={:.1}% disk={:.1}% procs={}",
                    cpu,
                    mem,
                    disk,
                    sys.processes().len()
                );

                if cpu >= cfg.cpu_warn_percent {
                    warn!("high CPU usage detected: {:.1}%", cpu);
                }
                if mem >= cfg.mem_warn_percent {
                    warn!("high memory usage detected: {:.1}%", mem);
                }
                if disk >= cfg.disk_warn_percent {
                    warn!("high disk usage detected: {:.1}%", disk);
                }

                // Print top processes by CPU usage
                let mut procs: Vec<_> = sys.processes().values().collect();
                procs.sort_by(|a, b| b.cpu_usage().partial_cmp(&a.cpu_usage()).unwrap());

                for p in procs.into_iter().take(cfg.top_processes) {
                    info!(
                        "top-proc pid={} name={} cpu={:.1}% mem={} KB",
                        p.pid(),
                        p.name(),
                        p.cpu_usage(),
                        p.memory()
                    );
                }
            }
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    Ok(())
}
