```rust
use daemonize::Daemonize;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::process;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};

const SOCKET_PATH: &str = "/tmp/sysmon-daemon.sock";
const PID_FILE: &str = "/tmp/sysmon-daemon.pid";
const LOG_FILE: &str = "/tmp/sysmon-daemon.log";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const MEMORY_ALERT_THRESHOLD: f32 = 90.0;

#[derive(Clone, Debug, Default)]
struct Metrics {
    cpu_usage: f32,
    mem_used_percent: f32,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() > 1 {
        match args[1].as_str() {
            "stop" => {
                stop_daemon();
                return;
            }
            "status" => {
                query_status();
                return;
            }
            _ => {}
        }
    }

    run_daemon();
}

fn run_daemon() {
    cleanup_stale_files();

    let stdout = File::create(LOG_FILE).expect("failed to open log file");
    let stderr = stdout.try_clone().expect("failed to clone log file");

    let daemonize = Daemonize::new()
        .pid_file(PID_FILE)
        .working_directory("/")
        .stdout(stdout)
        .stderr(stderr);

    match daemonize.start() {
        Ok(_) => {}
        Err(e) => {
            eprintln!("daemonization failed: {}", e);
            process::exit(1);
        }
    }

    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Mutex::new(Metrics::default()));

    let listener = UnixListener::bind(SOCKET_PATH).expect("failed to bind unix socket");
    listener
        .set_nonblocking(true)
        .expect("failed to set nonblocking");

    let running_socket = running.clone();
    let metrics_socket = metrics.clone();

    // Control socket thread
    thread::spawn(move || {
        while running_socket.load(Ordering::Relaxed) {
            match listener.accept() {
                Ok((stream, _)) => {
                    handle_client(stream, &running_socket, &metrics_socket);
                }
                Err(_) => {
                    thread::sleep(Duration::from_millis(100));
                }
            }
        }
    });

    // Monitoring loop
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    log_line("sysmon-daemon started");

    while running.load(Ordering::Relaxed) {
        let start = Instant::now();

        system.refresh_cpu();
        system.refresh_memory();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_memory = system.total_memory() as f32;
        let used_memory = system.used_memory() as f32;
        let mem_used_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let load = System::load_average();

        let current = Metrics {
            cpu_usage,
            mem_used_percent,
            load_avg_1: load.one,
            load_avg_5: load.five,
            load_avg_15: load.fifteen,
        };

        {
            let mut guard = metrics.lock().unwrap();
            *guard = current.clone();
        }

        log_line(&format!(
            "cpu={:.1}% mem={:.1}% load={:.2},{:.2},{:.2}",
            current.cpu_usage,
            current.mem_used_percent,
            current.load_avg_1,
            current.load_avg_5,
            current.load_avg_15
        ));

        if current.mem_used_percent >= MEMORY_ALERT_THRESHOLD {
            log_line(&format!(
                "ALERT: memory usage high ({:.1}%)",
                current.mem_used_percent
            ));
        }

        let elapsed = start.elapsed();
        if elapsed < SAMPLE_INTERVAL {
            thread::sleep(SAMPLE_INTERVAL - elapsed);
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    let _ = fs::remove_file(PID_FILE);
    log_line("sysmon-daemon stopped");
}

fn handle_client(mut stream: UnixStream, running: &Arc<AtomicBool>, metrics: &Arc<Mutex<Metrics>>) {
    let mut buf = String::new();
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let _ = reader.read_line(&mut buf);

    let cmd = buf.trim();

    match cmd {
        "status" => {
            let m = metrics.lock().unwrap().clone();
            let response = format!(
                "cpu={:.1}% mem={:.1}% load={:.2},{:.2},{:.2}\n",
                m.cpu_usage, m.mem_used_percent, m.load_avg_1, m.load_avg_5, m.load_avg_15
            );
            let _ = stream.write_all(response.as_bytes());
        }
        "quit" => {
            running.store(false, Ordering::Relaxed);
            let _ = stream.write_all(b"shutting down\n");
        }
        _ => {
            let _ = stream.write_all(b"unknown command\n");
        }
    }
}

fn stop_daemon() {
    if let Ok(mut stream) = UnixStream::connect(SOCKET_PATH) {
        let _ = stream.write_all(b"quit\n");
        let mut resp = String::new();
        let _ = stream.read_to_string(&mut resp);
        println!("{}", resp.trim());
        return;
    }

    if let Ok(pid_str) = fs::read_to_string(PID_FILE) {
        if let Ok(pid) = pid_str.trim().parse::<i32>() {
            let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
            println!("sent SIGTERM to daemon");
            return;
        }
    }

    println!("daemon not running");
}

fn query_status() {
    if let Ok(mut stream) = UnixStream::connect(SOCKET_PATH) {
        let _ = stream.write_all(b"status\n");
        let mut resp = String::new();
        let _ = stream.read_to_string(&mut resp);
        println!("{}", resp.trim());
    } else {
        println!("daemon not running");
    }
}

fn cleanup_stale_files() {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }
    if Path::new(PID_FILE).exists() {
        let _ = fs::remove_file(PID_FILE);
    }
}

fn log_line(msg: &str) {
    let line = format!("[{}] {}\n", chrono_like_timestamp(), msg);
    let _ = std::io::stdout().write_all(line.as_bytes());
    let _ = std::io::stdout().flush();
}

fn chrono_like_timestamp() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    format!("{}", now.as_secs())
}
```

