use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};

const POLL_INTERVAL_SECS: u64 = 2;
const CPU_WARN_THRESHOLD: f32 = 80.0;
const MEM_WARN_THRESHOLD: u64 = 80; // percent

fn main() -> Result<()> {
    env_logger::init();

    // Daemonize the process
    let stdout = File::create("/tmp/resource-daemon.out")?;
    let stderr = File::create("/tmp/resource-daemon.err")?;

    let daemonize = Daemonize::new()
        .pid_file("/tmp/resource-daemon.pid")
        .working_directory("/")
        .umask(0o027)
        .stdout(stdout)
        .stderr(stderr);

    match daemonize.start() {
        Ok(_) => info!("Daemon started"),
        Err(e) => {
            eprintln!("Failed to daemonize: {e}");
            return Err(e.into());
        }
    }

    // Configure sysinfo for lightweight refreshes
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    // Initial refresh to establish baseline
    system.refresh_cpu();
    system.refresh_memory();

    loop {
        system.refresh_cpu();
        system.refresh_memory();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_memory = system.total_memory();
        let used_memory = system.used_memory();
        let mem_usage_pct = if total_memory > 0 {
            ((used_memory as f64 / total_memory as f64) * 100.0) as u64
        } else {
            0
        };

        info!(
            "CPU usage: {:.1}%, Memory usage: {}% ({} / {} KiB)",
            cpu_usage, mem_usage_pct, used_memory, total_memory
        );

        if cpu_usage > CPU_WARN_THRESHOLD {
            warn!("High CPU usage detected: {:.1}%", cpu_usage);
            // Hook: add mitigation logic here
            // e.g., send alert, lower priority, throttle worker threads
        }

        if mem_usage_pct > MEM_WARN_THRESHOLD {
            warn!("High memory usage detected: {}%", mem_usage_pct);
            // Hook: add mitigation logic here
            // e.g., free caches, restart noncritical workers
        }

        thread::sleep(Duration::from_secs(POLL_INTERVAL_SECS));
    }
}
