## C++20 implementation

```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <vector>
#include <chrono>
#include <thread>
#include <optional>
#include <algorithm>
#include <iostream>

#if defined(__GNUC__) || defined(__clang__)
#define likely(x)   __builtin_expect(!!(x), 1)
#define unlikely(x) __builtin_expect(!!(x), 0)
#else
#define likely(x)   (x)
#define unlikely(x) (x)
#endif

// -----------------------------
// Packet / protocol structures
// -----------------------------
#pragma pack(push, 1)
struct EthHdr {
    uint8_t  dst[6];
    uint8_t  src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t  ver_ihl;
    uint8_t  dscp_ecn;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_frag;
    uint8_t  ttl;
    uint8_t  protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t  data_offset_reserved;
    uint8_t  flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

// -----------------------------
// Utilities
// -----------------------------
static inline uint16_t bswap16(uint16_t x) {
    return (x >> 8) | (x << 8);
}

static inline uint32_t bswap32(uint32_t x) {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8)  |
           ((x & 0x00FF0000u) >> 8)  |
           ((x & 0xFF000000u) >> 24);
}

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) { return x; }
static inline uint32_t ntoh32(uint32_t x) { return x; }
#endif

static inline uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()
    ).count();
}

// -----------------------------
// Flow key and stats
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  pad[3];

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

static inline uint64_t flow_hash(const FlowKey& k) noexcept {
    // Fast mix for 5-tuple
    uint64_t x = (uint64_t)k.src_ip << 32 | k.dst_ip;
    uint64_t y = (uint64_t)k.src_port << 48 | (uint64_t)k.dst_port << 32 | (uint64_t)k.protocol;
    uint64_t z = x ^ (y + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2));
    z ^= z >> 33;
    z *= 0xff51afd7ed558ccdULL;
    z ^= z >> 33;
    z *= 0xc4ceb9fe1a85ec53ULL;
    z ^= z >> 33;
    return z;
}

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey  key{};
    FlowStats stats{};
    uint64_t  hash = 0;
    uint32_t  epoch = 0;
    bool      occupied = false;
};

// -----------------------------
// Sharded flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2 = 1 << 20)
        : capacity_(round_up_pow2(capacity_pow2)),
          mask_(capacity_ - 1),
          entries_(capacity_) {}

    FlowStats* find_or_insert(const FlowKey& key, uint64_t ts_ns) {
        const uint64_t h = flow_hash(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < kMaxProbe; ++probe) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.hash = h;
                e.key = key;
                e.stats = {};
                e.stats.first_seen_ns = ts_ns;
                e.stats.last_seen_ns = ts_ns;
                e.epoch = current_epoch_;
                ++size_;
                return &e.stats;
            }
            if (e.hash == h && e.key == key) {
                e.epoch = current_epoch_;
                return &e.stats;
            }
            idx = (idx + 1) & mask_;
        }

        // Simple fallback: evict current slot
        FlowEntry& e = entries_[idx];
        e.occupied = true;
        e.hash = h;
        e.key = key;
        e.stats = {};
        e.stats.first_seen_ns = ts_ns;
        e.stats.last_seen_ns = ts_ns;
        e.epoch = current_epoch_;
        return &e.stats;
    }

    void age_and_evict(uint64_t cutoff_ns) {
        for (auto& e : entries_) {
            if (e.occupied && e.stats.last_seen_ns < cutoff_ns) {
                e.occupied = false;
                e.stats = {};
                e.hash = 0;
            }
        }
    }

    void next_epoch() { ++current_epoch_; }

    size_t size() const noexcept { return size_; }

private:
    static constexpr size_t kMaxProbe = 8;

    static size_t round_up_pow2(size_t x) {
        if (x < 2) return 2;
        --x;
        for (size_t i = 1; i < sizeof(size_t) * 8; i <<= 1) x |= x >> i;
        return x + 1;
    }

    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    size_t size_ = 0;
    uint32_t current_epoch_ = 0;
};

// -----------------------------
// Sharded analyzer
// -----------------------------
class NetworkFlowAnalyzer {
public:
    explicit NetworkFlowAnalyzer(size_t shards = std::thread::hardware_concurrency(),
                                 size_t table_capacity_per_shard = 1 << 18)
        : shard_count_(std::max<size_t>(1, shards)) {
        shards_.reserve(shard_count_);
        for (size_t i = 0; i < shard_count_; ++i) {
            shards_.emplace_back(table_capacity_per_shard);
        }
    }

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        if (unlikely(len < sizeof(EthHdr))) return;

        const EthHdr* eth = reinterpret_cast<const EthHdr*>(data);
        uint16_t ethertype = ntoh16(eth->ethertype);

        // IPv4 only in this skeleton
        if (unlikely(ethertype != 0x0800)) return;

        size_t off = sizeof(EthHdr);
        if (unlikely(len < off + sizeof(Ipv4Hdr))) return;

        const Ipv4Hdr* ip = reinterpret_cast<const Ipv4Hdr*>(data + off);
        uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
        if (unlikely(ihl < 20 || len < off + ihl)) return;

        uint8_t proto = ip->protocol;
        uint32_t src_ip = ntoh32(ip->src);
        uint32_t dst_ip = ntoh32(ip->dst);

        off += ihl;

        FlowKey key{};
        key.src_ip = src_ip;
        key.dst_ip = dst_ip;
        key.protocol = proto;

        if (proto == 6) { // TCP
            if (unlikely(len < off + sizeof(TcpHdr))) return;
            const TcpHdr* tcp = reinterpret_cast<const TcpHdr*>(data + off);
            key.src_port = ntoh16(tcp->src_port);
            key.dst_port = ntoh16(tcp->dst_port);
        } else if (proto == 17) { // UDP
            if (unlikely(len < off + sizeof(UdpHdr))) return;
            const UdpHdr* udp = reinterpret_cast<const UdpHdr*>(data + off);
            key.src_port = ntoh16(udp->src_port);
            key.dst_port = ntoh16(udp->dst_port);
        } else {
            key.src_port = 0;
            key.dst_port = 0;
        }

        auto& shard = shards_[flow_shard(key)];
        FlowStats* s = shard.find_or_insert(key, ts_ns);
        ++s->packets;
        s->bytes += len;
        s->last_seen_ns = ts_ns;
    }

    void age(uint64_t idle_timeout_ns) {
        const uint64_t cutoff = now_ns() - idle_timeout_ns;
        for (auto& shard : shards_) {
            shard.age_and_evict(cutoff);
            shard.next_epoch();
        }
    }

    void print_summary() const {
        uint64_t total_packets = 0;
        uint64_t total_bytes = 0;

        for (const auto& shard : shards_) {
            // In a production build, expose iterators for live entries.
            // This skeleton keeps the hot path simple.
            (void)shard;
        }

        std::cout << "Analyzer running with " << shard_count_ << " shards\n";
        std::cout << "Summary collection omitted in skeleton for performance.\n";
    }

private:
    size_t flow_shard(const FlowKey& key) const noexcept {
        return static_cast<size_t>(flow_hash(key)) % shard_count_;
    }

    size_t shard_count_;
    std::vector<FlowTable> shards_;
};

// -----------------------------
// Example packet ingest loop
// -----------------------------
int main() {
    NetworkFlowAnalyzer analyzer(
        std::max(1u, std::thread::hardware_concurrency()),
        1 << 18
    );

    // Example: fake packet buffer
    std::array<uint8_t, 128> packet{};
    auto* eth = reinterpret_cast<EthHdr*>(packet.data());
    eth->ethertype = ntoh16(0x0800);

    auto* ip = reinterpret_cast<Ipv4Hdr*>(packet.data() + sizeof(EthHdr));
    ip->ver_ihl = 0x45;
    ip->protocol = 6;
    ip->src = ntoh32(0x0A000001);
    ip->dst = ntoh32(0x0A000002);

    auto* tcp = reinterpret_cast<TcpHdr*>(packet.data() + sizeof(EthHdr) + sizeof(Ipv4Hdr));
    tcp->src_port = ntoh16(12345);
    tcp->dst_port = ntoh16(443);

    analyzer.process_packet(packet.data(), packet.size(), now_ns());
    analyzer.age(30ULL * 1000000000ULL); // 30s idle timeout
    analyzer.print_summary();

    return 0;
}
