// =========================
// Packet / protocol structs
// =========================

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_frag;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct IPv6Header {
    uint32_t ver_tc_fl;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src_ip[16];
    uint8_t dst_ip[16];
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

// =========================
// Utility
// =========================

static inline uint16_t bswap16(uint16_t x) {
    return (x >> 8) | (x << 8);
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

static inline uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()
    ).count();
}

// =========================
// Flow key
// =========================

struct FlowKey {
    uint64_t a;   // packed addresses / family / proto
    uint32_t b;   // ports or extra bits
    uint32_t c;   // reserved / extension

    bool operator==(const FlowKey& o) const noexcept {
        return a == o.a && b == o.b && c == o.c;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast mix
        uint64_t x = k.a;
        x ^= (uint64_t)k.b + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
        x ^= (uint64_t)k.c + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

// =========================
// Flow record
// =========================

struct FlowRecord {
    FlowKey key{};
    uint64_t first_seen_ns{0};
    uint64_t last_seen_ns{0};
    uint64_t packets{0};
    uint64_t bytes{0};

    uint32_t tcp_syn{0};
    uint32_t tcp_fin{0};
    uint32_t tcp_rst{0};

    bool active{false};
};

// =========================
// Sharded flow table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t shards = 64, size_t per_shard_capacity = 1 << 20)
        : shards_(shards), tables_(shards), mutexes_(shards) {
        for (size_t i = 0; i < shards_; ++i) {
            tables_[i].reserve(per_shard_capacity / shards_ + 1024);
        }
    }

    FlowRecord& upsert(const FlowKey& key, uint64_t ts_ns, uint32_t bytes,
                       bool syn = false, bool fin = false, bool rst = false) {
        auto idx = shard_for(key);
        std::unique_lock<std::shared_mutex> lock(mutexes_[idx]);

        auto& table = tables_[idx];
        auto it = table.find(key);
        if (it == table.end()) {
            FlowRecord rec;
            rec.key = key;
            rec.first_seen_ns = ts_ns;
            rec.last_seen_ns = ts_ns;
            rec.packets = 1;
            rec.bytes = bytes;
            rec.tcp_syn = syn ? 1 : 0;
            rec.tcp_fin = fin ? 1 : 0;
            rec.tcp_rst = rst ? 1 : 0;
            rec.active = true;
            auto [inserted_it, _] = table.emplace(key, std::move(rec));
            return inserted_it->second;
        } else {
            auto& rec = it->second;
            rec.last_seen_ns = ts_ns;
            rec.packets++;
            rec.bytes += bytes;
            if (syn) rec.tcp_syn++;
            if (fin) rec.tcp_fin++;
            if (rst) rec.tcp_rst++;
            return rec;
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) const {
        for (size_t i = 0; i < shards_; ++i) {
            std::shared_lock<std::shared_mutex> lock(mutexes_[i]);
            for (const auto& kv : tables_[i]) {
                fn(kv.second);
            }
        }
    }

    template <typename Fn>
    void expire(uint64_t cutoff_ns, Fn&& on_expire) {
        for (size_t i = 0; i < shards_; ++i) {
            std::unique_lock<std::shared_mutex> lock(mutexes_[i]);
            auto& table = tables_[i];
            for (auto it = table.begin(); it != table.end(); ) {
                if (it->second.last_seen_ns < cutoff_ns) {
                    on_expire(it->second);
                    it = table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

private:
    size_t shard_for(const FlowKey& key) const noexcept {
        return FlowKeyHash{}(key) % shards_;
    }

    size_t shards_;
    std::vector<std::unordered_map<FlowKey, FlowRecord, FlowKeyHash>> tables_;
    std::vector<std::shared_mutex> mutexes_;
};

// =========================
// Packet parser
// =========================

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_bytes{0};
    uint8_t ip_proto{0};
    bool syn{false};
    bool fin{false};
    bool rst{false};
    bool valid{false};
};

class PacketParser {
public:
    static ParsedPacket parse(const uint8_t* data, size_t len) {
        ParsedPacket out{};
        if (len < sizeof(EthernetHeader)) return out;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(data);
        uint16_t ethertype = ntoh16(eth->ethertype);

        size_t offset = sizeof(EthernetHeader);

        if (ethertype == 0x0800) { // IPv4
            if (len < offset + sizeof(IPv4Header)) return out;
            const auto* ip = reinterpret_cast<const IPv4Header*>(data + offset);
            uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
            if (ihl < 20 || len < offset + ihl) return out;

            uint32_t src = ntoh32(ip->src_ip);
            uint32_t dst = ntoh32(ip->dst_ip);
            uint8_t proto = ip->protocol;
            offset += ihl;

            uint16_t sport = 0, dport = 0;
            uint32_t l4_bytes = 0;

            if (proto == 6) { // TCP
                if (len < offset + sizeof(TCPHeader)) return out;
                const auto* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
                sport = ntoh16(tcp->src_port);
                dport = ntoh16(tcp->dst_port);
                uint8_t doff = ((tcp->data_offset_reserved >> 4) & 0x0F) * 4;
                if (doff < 20 || len < offset + doff) return out;
                l4_bytes = (uint32_t)(len - offset);
                out.syn = tcp->flags & 0x02;
                out.fin = tcp->flags & 0x01;
                out.rst = tcp->flags & 0x04;
            } else if (proto == 17) { // UDP
                if (len < offset + sizeof(UDPHeader)) return out;
                const auto* udp = reinterpret_cast<const UDPHeader*>(data + offset);
                sport = ntoh16(udp->src_port);
                dport = ntoh16(udp->dst_port);
                l4_bytes = (uint32_t)(len - offset);
            } else {
                return out;
            }

            out.key = make_ipv4_key(src, dst, sport, dport, proto);
            out.payload_bytes = l4_bytes;
            out.ip_proto = proto;
            out.valid = true;
            return out;
        }

        return out;
    }

private:
    static FlowKey make_ipv4_key(uint32_t src, uint32_t dst,
                                 uint16_t sport, uint16_t dport,
                                 uint8_t proto) {
        FlowKey k{};
        // Canonicalize direction for bidirectional flow aggregation
        bool swap = (src > dst) || (src == dst && sport > dport);
        uint32_t a1 = swap ? dst : src;
        uint32_t a2 = swap ? src : dst;
        uint16_t p1 = swap ? dport : sport;
        uint16_t p2 = swap ? sport : dport;

        k.a = ((uint64_t)a1 << 32) | a2;
        k.b = ((uint32_t)p1 << 16) | p2;
        k.c = proto;
        return k;
    }
};

// =========================
// Analyzer
// =========================

class FlowAnalyzer {
public:
    FlowAnalyzer(size_t shards = 64, size_t capacity = 1 << 20)
        : table_(shards, capacity) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        auto pkt = PacketParser::parse(data, len);
        if (!pkt.valid) return;

        table_.upsert(pkt.key, ts_ns, pkt.payload_bytes, pkt.syn, pkt.fin, pkt.rst);
    }

    void expire_idle(uint64_t idle_timeout_ns) {
        uint64_t cutoff = now_ns() - idle_timeout_ns;
        table_.expire(cutoff, [](const FlowRecord& rec) {
            // Replace with export to Kafka/PCAP/JSON/Prometheus/etc.
            std::cout << "Expired flow: packets=" << rec.packets
                      << " bytes=" << rec.bytes << "\n";
        });
    }

    void dump_top_flows(size_t n = 10) const {
        std::vector<FlowRecord> all;
        all.reserve(1024 * 1024);

        table_.for_each([&](const FlowRecord& rec) {
            all.push_back(rec);
        });

        std::partial_sort(all.begin(),
                          all.begin() + std::min(n, all.size()),
                          all.end(),
                          [](const FlowRecord& a, const FlowRecord& b) {
                              return a.bytes > b.bytes;
                          });

        size_t limit = std::min(n, all.size());
        for (size_t i = 0; i < limit; ++i) {
            std::cout << "#" << i + 1
                      << " packets=" << all[i].packets
                      << " bytes=" << all[i].bytes
                      << " first_ns=" << all[i].first_seen_ns
                      << " last_ns=" << all[i].last_seen_ns
                      << "\n";
        }
    }

private:
    FlowTable table_;
};

