    FlowKey key{};
    FlowStats stats{};
};

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of 2");
        }
    }

    FlowEntry* find_or_insert(const FlowKey& key, uint64_t now_ns) {
        const uint64_t h = hash_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowEntry& e = table_[idx];
            uint8_t expected = e.state.load(std::memory_order_acquire);

            if (expected == 0) {
                // Try to claim the slot
                if (e.state.compare_exchange_strong(expected, 1, std::memory_order_acq_rel)) {
                    e.key = key;
                    e.stats.packets = 0;
                    e.stats.bytes = 0;
                    e.stats.first_seen_ns = now_ns;
                    e.stats.last_seen_ns = now_ns;
                    return &e;
                }
            } else if (e.key == key) {
                return &e;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // Table full
    }

    template <typename ExportFn>
    void age_and_export(uint64_t now_ns, uint64_t idle_timeout_ns, ExportFn&& export_fn) {
        for (auto& e : table_) {
            if (e.state.load(std::memory_order_acquire) == 1) {
                if (now_ns - e.stats.last_seen_ns > idle_timeout_ns) {
                    export_fn(e.key, e.stats);
                    e.state.store(0, std::memory_order_release);
                }
            }
        }
    }

private:
    static uint64_t hash_key(const FlowKey& k) noexcept {
        uint64_t x = 0;
        x ^= hash64(static_cast<uint64_t>(k.src_ip));
        x ^= hash64(static_cast<uint64_t>(k.dst_ip) << 1);
        x ^= hash64(static_cast<uint64_t>(k.src_port) << 2);
        x ^= hash64(static_cast<uint64_t>(k.dst_port) << 3);
        x ^= hash64(static_cast<uint64_t>(k.protocol) << 4);
        return x;
    }

    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> table_;
};

struct ParsedPacket {
    FlowKey key{};
    size_t payload_len = 0;
    bool valid = false;
};

static inline uint16_t read_be16(const void* p) {
    uint16_t v;
    std::memcpy(&v, p, sizeof(v));
    return ntohs(v);
}

static inline uint32_t read_be32(const void* p) {
    uint32_t v;
    std::memcpy(&v, p, sizeof(v));
    return ntohl(v);
}

ParsedPacket parse_packet(const uint8_t* data, size_t len) {
    ParsedPacket out;

    if (len < sizeof(EthHdr)) return out;
    const auto* eth = reinterpret_cast<const EthHdr*>(data);
    uint16_t ethertype = ntohs(eth->ethertype);

    if (ethertype != 0x0800) return out; // IPv4 only

    size_t offset = sizeof(EthHdr);
    if (len < offset + sizeof(Ipv4Hdr)) return out;

    const auto* ip = reinterpret_cast<const Ipv4Hdr*>(data + offset);
    uint8_t ihl = ip->ver_ihl & 0x0F;
    uint8_t version = ip->ver_ihl >> 4;
    if (version != 4 || ihl < 5) return out;

    size_t ip_hdr_len = ihl * 4;
    if (len < offset + ip_hdr_len) return out;

    uint8_t proto = ip->protocol;
    uint32_t src_ip = ntohl(ip->src);
    uint32_t dst_ip = ntohl(ip->dst);

    offset += ip_hdr_len;

    if (proto == 6) { // TCP
        if (len < offset + sizeof(TcpHdr)) return out;
        const auto* tcp = reinterpret_cast<const TcpHdr*>(data + offset);
        uint8_t doff = (tcp->data_offset_reserved >> 4) & 0x0F;
        size_t tcp_hdr_len = doff * 4;
        if (doff < 5 || len < offset + tcp_hdr_len) return out;

        out.key = FlowKey{
            src_ip,
            dst_ip,
            ntohs(tcp->src_port),
            ntohs(tcp->dst_port),
            proto
        };
        out.payload_len = len - (offset + tcp_hdr_len);
        out.valid = true;
        return out;
    }

    if (proto == 17) { // UDP
        if (len < offset + sizeof(UdpHdr)) return out;
        const auto* udp = reinterpret_cast<const UdpHdr*>(data + offset);

        out.key = FlowKey{
            src_ip,
            dst_ip,
            ntohs(udp->src_port),
            ntohs(udp->dst_port),
            proto
        };
        out.payload_len = len - (offset + sizeof(UdpHdr));
        out.valid = true;
        return out;
    }

    return out;
}

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2),
          idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t now_ns) {
        ParsedPacket pkt = parse_packet(data, len);
        if (!pkt.valid) return;

        FlowEntry* entry = table_.find_or_insert(pkt.key, now_ns);
        if (!entry) return; // table full; consider metrics/drop counter

        // Hot path update: keep it simple and predictable
        entry->stats.packets += 1;
        entry->stats.bytes += len;
        entry->stats.last_seen_ns = now_ns;
        if (entry->stats.first_seen_ns == 0) {
            entry->stats.first_seen_ns = now_ns;
        }
    }

    template <typename ExportFn>
    void age(uint64_t now_ns, ExportFn&& export_fn) {
        table_.age_and_export(now_ns, idle_timeout_ns_, std::forward<ExportFn>(export_fn));
    }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
};

// Example exporter
static void export_flow(const FlowKey& k, const FlowStats& s) {
    auto ip_to_str = [](uint32_t ip) {
        std::array<char, 16> buf{};
        std::snprintf(buf.data(), buf.size(), "%u.%u.%u.%u",
                      (ip >> 24) & 0xFF, (ip >> 16) & 0xFF,
                      (ip >> 8) & 0xFF, ip & 0xFF);
        return std::string(buf.data());
    };

    std::cout << ip_to_str(k.src_ip) << ":" << k.src_port
              << " -> " << ip_to_str(k.dst_ip) << ":" << k.dst_port
              << " proto=" << static_cast<int>(k.protocol)
              << " packets=" << s.packets
              << " bytes=" << s.bytes
              << "\n";
}

