    const uint8_t* data;
    uint32_t len;
    uint64_t ts_ns;
};

// ============================
// Flow key / stats
// ============================

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// ============================
// Flow table: open addressing
// ============================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of 2");
        }
    }

    FlowStats* get_or_create(const FlowKey& key, uint64_t ts_ns) {
        const uint64_t h = hash_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (;;) {
            auto& e = table_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.hash = h;
                e.key = key;
                e.stats.first_seen_ns = ts_ns;
                e.stats.last_seen_ns = ts_ns;
                ++size_;
                return &e.stats;
            }
            if (e.hash == h && e.key == key) {
                e.stats.last_seen_ns = ts_ns;
                return &e.stats;
            }
            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& e : table_) {
            if (e.occupied) fn(e);
        }
    }

    void clear() {
        for (auto& e : table_) {
            e.occupied = false;
            e.hash = 0;
            e.stats = {};
        }
        size_ = 0;
    }

    size_t size() const noexcept { return size_; }

private:
    static uint64_t hash_key(const FlowKey& k) noexcept {
        uint64_t a = (uint64_t(k.src_ip) << 32) | k.dst_ip;
        uint64_t b = (uint64_t(k.src_port) << 48) | (uint64_t(k.dst_port) << 32) | (uint64_t(k.protocol) << 24);
        return mix_key(a, b, 0x12345678abcdefULL);
    }

    size_t mask_;
    std::vector<FlowEntry> table_;
    size_t size_ = 0;
};

// ============================
// Parser
// ============================

class PacketParser {
public:
    static std::optional<std::pair<FlowKey, uint32_t>> parse_ipv4_l4(const PacketView& p) {
        if (p.len < sizeof(EthernetHeader) + sizeof(IPv4Header)) return std::nullopt;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(p.data);
        uint16_t ethertype = ntohs16(eth->ethertype);
        if (ethertype != 0x0800) return std::nullopt; // IPv4 only

        const auto* ip = reinterpret_cast<const IPv4Header*>(p.data + sizeof(EthernetHeader));
        uint8_t ihl = ip->ver_ihl & 0x0F;
        uint8_t version = ip->ver_ihl >> 4;
        if (version != 4 || ihl < 5) return std::nullopt;

        uint32_t ip_hdr_len = ihl * 4;
        if (p.len < sizeof(EthernetHeader) + ip_hdr_len) return std::nullopt;

        uint16_t total_len = ntohs16(ip->total_len);
        if (total_len < ip_hdr_len) return std::nullopt;

        const uint8_t* l4 = p.data + sizeof(EthernetHeader) + ip_hdr_len;
        uint32_t l4_len = total_len - ip_hdr_len;

        FlowKey key{};
        key.src_ip = ntohl32(ip->src);
        key.dst_ip = ntohl32(ip->dst);
        key.protocol = ip->protocol;

        if (ip->protocol == 6) { // TCP
            if (l4_len < sizeof(TCPHeader)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TCPHeader*>(l4);
            key.src_port = ntohs16(tcp->src_port);
            key.dst_port = ntohs16(tcp->dst_port);
        } else if (ip->protocol == 17) { // UDP
            if (l4_len < sizeof(UDPHeader)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UDPHeader*>(l4);
            key.src_port = ntohs16(udp->src_port);
            key.dst_port = ntohs16(udp->dst_port);
        } else {
            return std::nullopt;
        }

        return std::make_pair(key, total_len + sizeof(EthernetHeader));
    }

private:
    static inline uint16_t ntohs16(uint16_t x) noexcept {
        return (x >> 8) | (x << 8);
    }
    static inline uint32_t ntohl32(uint32_t x) noexcept {
        return ((x & 0x000000FFU) << 24) |
               ((x & 0x0000FF00U) << 8)  |
               ((x & 0x00FF0000U) >> 8)  |
               ((x & 0xFF000000U) >> 24);
    }
};

// ============================
// Analyzer
// ============================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t flow_timeout_ns)
        : table_(table_capacity_pow2), flow_timeout_ns_(flow_timeout_ns) {}

    void ingest_batch(const PacketView* packets, size_t count) {
        for (size_t i = 0; i < count; ++i) {
            ingest_one(packets[i]);
        }
    }

    void ingest_one(const PacketView& p) {
        auto parsed = PacketParser::parse_ipv4_l4(p);
        if (!parsed) return;

        const auto& [key, frame_len] = *parsed;
        FlowStats* stats = table_.get_or_create(key, p.ts_ns);
        stats->packets++;
        stats->bytes += frame_len;
    }

    template <typename ExportFn>
    void age_and_export(uint64_t now_ns, ExportFn&& export_fn) {
        std::vector<FlowEntry> expired;
        expired.reserve(1024);

        table_.for_each([&](FlowEntry& e) {
            if (now_ns - e.stats.last_seen_ns >= flow_timeout_ns_) {
                expired.push_back(e);
            }
        });

        for (const auto& e : expired) {
            export_fn(e.key, e.stats);
        }

        // Rebuild table without expired flows
        if (!expired.empty()) {
            FlowTable new_table(table_capacity_pow2());
            table_.for_each([&](FlowEntry& e) {
                if (now_ns - e.stats.last_seen_ns < flow_timeout_ns_) {
                    FlowStats* s = new_table.get_or_create(e.key, e.stats.last_seen_ns);
                    *s = e.stats;
                }
            });
            table_ = std::move(new_table);
        }
    }

    size_t flow_count() const noexcept { return table_.size(); }

private:
    size_t table_capacity_pow2() const noexcept { return 1ull << 20; } // 1,048,576 entries
    FlowTable table_;
    uint64_t flow_timeout_ns_;
};

