// Example usage
// ============================

int main() {
    FlowAnalyzer analyzer(1ull << 20, 30ull * 1000 * 1000 * 1000); // 30s timeout

    // Example packets would normally come from AF_XDP / DPDK / libpcap
    std::vector<PacketView> batch;
    batch.reserve(1024);

    // Feed packets here...
    analyzer.ingest_batch(batch.data(), batch.size());

    analyzer.age_and_export(rdtsc_fallback_ns(), [](const FlowKey& key, const FlowStats& stats) {
        std::cout << "Expired flow: "
                  << key.src_ip << ":" << key.src_port
                  << " -> " << key.dst_ip << ":" << key.dst_port
                  << " proto=" << int(key.protocol)
                  << " packets=" << stats.packets
                  << " bytes=" << stats.bytes << "\n";
    });

    std::cout << "Active flows: " << analyzer.flow_count() << "\n";
    return 0;
}
