struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
    uint8_t pad[3];

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        return static_cast<size_t>(
            hash_combine64(k.src_ip, k.dst_ip, k.src_port, k.dst_port, k.proto)
        );
    }
};

// -----------------------------
// Flow statistics
// -----------------------------
struct alignas(64) FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;

    uint32_t tcp_syn = 0;
    uint32_t tcp_fin = 0;
    uint32_t tcp_rst = 0;

    uint32_t flags = 0;
    uint32_t pad = 0;

    void update(uint32_t len, uint8_t tcp_flags, uint64_t now_ns) noexcept {
        if (packets == 0) first_seen_ns = now_ns;
        last_seen_ns = now_ns;
        ++packets;
        bytes += len;

        if (tcp_flags & 0x02) ++tcp_syn;
        if (tcp_flags & 0x01) ++tcp_fin;
        if (tcp_flags & 0x04) ++tcp_rst;
    }
};

// -----------------------------
// Packet metadata
// -----------------------------
struct PacketView {
    FlowKey key;
    uint32_t length;
    uint8_t tcp_flags;
    uint64_t timestamp_ns;
};

// -----------------------------
// Sharded flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t shards = 64)
        : shards_(shards), tables_(shards) {}

    void reserve(size_t expected_flows_per_shard) {
        for (auto& shard : tables_) {
            std::unique_lock lock(shard.mtx);
            shard.map.reserve(expected_flows_per_shard);
        }
    }

    inline void ingest(const PacketView& pkt) {
        auto& shard = shard_for(pkt.key);
        std::unique_lock lock(shard.mtx);

        auto it = shard.map.find(pkt.key);
        if (it == shard.map.end()) {
            FlowStats stats;
            stats.update(pkt.length, pkt.tcp_flags, pkt.timestamp_ns);
            shard.map.emplace(pkt.key, stats);
        } else {
            it->second.update(pkt.length, pkt.tcp_flags, pkt.timestamp_ns);
        }
    }

    inline void ingest_batch(const PacketView* begin, const PacketView* end) {
        for (auto p = begin; p != end; ++p) {
            ingest(*p);
        }
    }

    template <typename Fn>
    void for_each_flow(Fn&& fn) {
        for (auto& shard : tables_) {
            std::unique_lock lock(shard.mtx);
            for (auto& [k, v] : shard.map) {
                fn(k, v);
            }
        }
    }

    // Remove flows idle longer than idle_timeout_ns
    template <typename Fn>
    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_evict) {
        for (auto& shard : tables_) {
            std::unique_lock lock(shard.mtx);
            for (auto it = shard.map.begin(); it != shard.map.end(); ) {
                if (now_ns - it->second.last_seen_ns > idle_timeout_ns) {
                    on_evict(it->first, it->second);
                    it = shard.map.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

private:
    struct Shard {
        std::mutex mtx;
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> map;
    };

    std::vector<Shard> tables_;
    size_t shards_;

    Shard& shard_for(const FlowKey& key) noexcept {
        size_t h = FlowKeyHash{}(key);
        return tables_[h % shards_];
    }
};

