class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t shards = 64)
        : table_(shards) {}

    void reserve(size_t expected_total_flows) {
        table_.reserve(expected_total_flows / shards_hint());
    }

    void process_packets(const ParsedPacket* packets, size_t count, uint64_t ts_ns) {
        batch_.clear();
        batch_.reserve(count);

        for (size_t i = 0; i < count; ++i) {
            batch_.push_back(make_packet_view(packets[i], ts_ns));
        }

        table_.ingest_batch(batch_.data(), batch_.data() + batch_.size());
    }

    void periodic_age(uint64_t now_ns, uint64_t idle_timeout_ns) {
        table_.age_out(now_ns, idle_timeout_ns,
            [](const FlowKey&, const FlowStats&) {
                // Export/serialize flow here
            });
