// =====================
// Packet / Flow types
// =====================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

struct PacketMeta {
    uint32_t src_ip;     // network-order or host-order, but be consistent
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    L4Proto proto;
    uint32_t bytes;
    uint64_t ts_ns;      // timestamp in nanoseconds
};

struct FlowKey {
    uint32_t a_ip;
    uint32_t b_ip;
    uint16_t a_port;
    uint16_t b_port;
    uint8_t proto;

    // Canonicalize direction so both directions map to same flow
    static FlowKey canonical(uint32_t src_ip, uint32_t dst_ip,
                             uint16_t src_port, uint16_t dst_port,
                             L4Proto proto) {
        FlowKey k{};
        k.proto = static_cast<uint8_t>(proto);

        // Sort by 5-tuple-ish order to make bidirectional flow canonical
        if (src_ip < dst_ip || (src_ip == dst_ip && src_port <= dst_port)) {
            k.a_ip = src_ip;
            k.b_ip = dst_ip;
            k.a_port = src_port;
            k.b_port = dst_port;
        } else {
            k.a_ip = dst_ip;
            k.b_ip = src_ip;
            k.a_port = dst_port;
            k.b_port = src_port;
        }
        return k;
    }

    bool operator==(const FlowKey& other) const noexcept {
        return a_ip == other.a_ip &&
               b_ip == other.b_ip &&
               a_port == other.a_port &&
               b_port == other.b_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast 64-bit mix; good enough for sharded hash tables
        uint64_t x = 0xcbf29ce484222325ULL;
        auto mix = [&](uint64_t v) {
            x ^= v;
            x *= 0x100000001b3ULL;
        };

        mix(k.a_ip);
        mix(k.b_ip);
        mix((uint64_t(k.a_port) << 16) | k.b_port);
        mix(k.proto);

        // Final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return static_cast<size_t>(x);
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns = 0;

    void update(uint32_t pkt_bytes, uint64_t ts_ns) noexcept {
        if (packets == 0) {
            first_ts_ns = ts_ns;
        }
        ++packets;
        bytes += pkt_bytes;
        last_ts_ns = ts_ns;
    }
};

// =====================
// Sharded flow table
// =====================

class FlowTable {
public:
    explicit FlowTable(size_t shards = 64, size_t reserve_per_shard = 1 << 14)
        : shards_(normalize_shards(shards)), tables_(shards_), mutexes_(shards_) {
        for (auto& t : tables_) {
            t.reserve(reserve_per_shard);
        }
    }

    void ingest(const PacketMeta& p) {
        FlowKey key = FlowKey::canonical(p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.proto);
        auto idx = shard_index(key);

        // Shard lock: practical and fast under moderate/high concurrency
        std::lock_guard<std::mutex> lock(mutexes_[idx]);

        auto& table = tables_[idx];
        auto it = table.find(key);
        if (it == table.end()) {
            FlowStats s;
            s.update(p.bytes, p.ts_ns);
            table.emplace(std::move(key), s);
        } else {
            it->second.update(p.bytes, p.ts_ns);
        }
    }

    // Aging: remove flows idle for more than idle_timeout_ns
    size_t expire_idle(uint64_t now_ns, uint64_t idle_timeout_ns) {
        size_t removed = 0;
        for (size_t i = 0; i < shards_; ++i) {
            std::lock_guard<std::mutex> lock(mutexes_[i]);
            auto& table = tables_[i];

            for (auto it = table.begin(); it != table.end(); ) {
                if (now_ns > it->second.last_ts_ns &&
                    (now_ns - it->second.last_ts_ns) > idle_timeout_ns) {
                    it = table.erase(it);
                    ++removed;
                } else {
                    ++it;
                }
            }
        }
        return removed;
    }

    // Snapshot current flows for reporting/export
    std::vector<std::pair<FlowKey, FlowStats>> snapshot() const {
        std::vector<std::pair<FlowKey, FlowStats>> out;
        for (size_t i = 0; i < shards_; ++i) {
            std::lock_guard<std::mutex> lock(mutexes_[i]);
            const auto& table = tables_[i];
            out.reserve(out.size() + table.size());
            for (const auto& kv : table) {
                out.push_back(kv);
            }
        }
        return out;
    }

    size_t size() const {
        size_t total = 0;
        for (size_t i = 0; i < shards_; ++i) {
            std::lock_guard<std::mutex> lock(mutexes_[i]);
            total += tables_[i].size();
        }
        return total;
    }

private:
    using Table = std::unordered_map<FlowKey, FlowStats, FlowKeyHash>;

    static size_t normalize_shards(size_t s) {
        // round up to power of two for fast masking
        if (s < 1) return 1;
        size_t p = 1;
        while (p < s) p <<= 1;
        return p;
    }

    size_t shard_index(const FlowKey& k) const noexcept {
        return FlowKeyHash{}(k) & (shards_ - 1);
    }

    size_t shards_;
    std::vector<Table> tables_;
    mutable std::vector<std::mutex> mutexes_;
};

// =====================
// Example analyzer loop
// =====================

class Analyzer {
public:
    Analyzer(size_t shards = 64, size_t reserve_per_shard = 1 << 14)
        : flows_(shards, reserve_per_shard) {}

    void on_packet(const PacketMeta& p) {
        flows_.ingest(p);
    }

    void maintenance(uint64_t now_ns) {
        // Example: expire flows idle for > 60 seconds
        constexpr uint64_t idle_timeout_ns = 60ULL * 1000ULL * 1000ULL * 1000ULL;
        size_t expired = flows_.expire_idle(now_ns, idle_timeout_ns);
        if (expired) {
            std::cout << "Expired " << expired << " idle flows\n";
        }
    }

    void report_top_flows(size_t n = 10) {
        auto snap = flows_.snapshot();
        std::sort(snap.begin(), snap.end(),
                  [](const auto& a, const auto& b) {
                      return a.second.bytes > b.second.bytes;
                  });

        std::cout << "Top " << n << " flows by bytes:\n";
        for (size_t i = 0; i < std::min(n, snap.size()); ++i) {
            const auto& [k, s] = snap[i];
            std::cout << i + 1
                      << " bytes=" << s.bytes
                      << " packets=" << s.packets
                      << " proto=" << unsigned(k.proto)
                      << " first_ts=" << s.first_ts_ns
                      << " last_ts=" << s.last_ts_ns
                      << "\n";
        }
    }

private:
    FlowTable flows_;
};

// =====================
// Demo main
// =====================

int main() {
    Analyzer analyzer(128, 1 << 15);

    // Simulated packets
    for (uint64_t i = 0; i < 1'000'000; ++i) {
        PacketMeta p{};
        p.src_ip = 0x0A000001 + (i % 1024); // 10.0.0.x
        p.dst_ip = 0x0A000100 + (i % 256);  // 10.0.1.x
        p.src_port = 10000 + (i % 5000);
        p.dst_port = 443;
        p.proto = L4Proto::TCP;
        p.bytes = 64 + (i % 1400);
        p.ts_ns = i * 1000;

        analyzer.on_packet(p);

        if ((i % 200000) == 0 && i != 0) {
            analyzer.maintenance(p.ts_ns);
        }
    }

    analyzer.report_top_flows(10);
    return 0;
}
