// ============================
// Packet header definitions
// ============================

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct VlanHdr {
    uint16_t tci;
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct Ipv6Hdr {
    uint32_t ver_tc_fl;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src[16];
    uint8_t dst[16];
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static_assert(sizeof(EthHdr) == 14);
static_assert(sizeof(VlanHdr) == 4);

// ============================
// Helpers
// ============================

static inline uint16_t bswap16(uint16_t x) { return __builtin_bswap16(x); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) { return x; }
static inline uint32_t ntoh32(uint32_t x) { return x; }
#endif

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

// Fast 64-bit mix
static inline uint64_t mix64(uint64_t x) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

// ============================
// Flow key / record
// ============================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    OTHER = 255
};

struct FlowKey {
    uint8_t ip_version;   // 4 or 6
    uint8_t proto;        // L4Proto
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t src_v4;
    uint32_t dst_v4;
    std::array<uint8_t, 16> src_v6{};
    std::array<uint8_t, 16> dst_v6{};

    bool operator==(const FlowKey& o) const {
        if (ip_version != o.ip_version || proto != o.proto ||
            src_port != o.src_port || dst_port != o.dst_port) {
            return false;
        }
        if (ip_version == 4) {
            return src_v4 == o.src_v4 && dst_v4 == o.dst_v4;
        }
        return src_v6 == o.src_v6 && dst_v6 == o.dst_v6;
    }
};

struct FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool occupied = false;
    bool tombstone = false;
};

// ============================
// Hashing
// ============================

static inline uint64_t hash_flow_key(const FlowKey& k) {
    uint64_t h = 0xcbf29ce484222325ULL;

    auto mix_bytes = [&](const void* data, size_t len) {
        const uint8_t* p = static_cast<const uint8_t*>(data);
        for (size_t i = 0; i < len; ++i) {
            h ^= p[i];
            h *= 0x100000001b3ULL;
        }
    };

    mix_bytes(&k.ip_version, sizeof(k.ip_version));
    mix_bytes(&k.proto, sizeof(k.proto));
    mix_bytes(&k.src_port, sizeof(k.src_port));
    mix_bytes(&k.dst_port, sizeof(k.dst_port));

    if (k.ip_version == 4) {
        mix_bytes(&k.src_v4, sizeof(k.src_v4));
        mix_bytes(&k.dst_v4, sizeof(k.dst_v4));
    } else {
        mix_bytes(k.src_v6.data(), k.src_v6.size());
        mix_bytes(k.dst_v6.data(), k.dst_v6.size());
    }

    return mix64(h);
}

// ============================
// Sharded open-addressing flow table
// ============================

class FlowShard {
public:
    explicit FlowShard(size_t capacity_pow2)
        : capacity_(capacity_pow2), mask_(capacity_pow2 - 1), table_(capacity_pow2) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t ts_ns, size_t& probes) {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;
        size_t first_tombstone = capacity_;

        for (size_t i = 0; i < capacity_; ++i) {
            ++probes;
            FlowRecord& slot = table_[idx];

            if (!slot.occupied) {
                if (!slot.tombstone) {
                    size_t target = (first_tombstone != capacity_) ? first_tombstone : idx;
                    FlowRecord& dst = table_[target];
                    dst.key = key;
                    dst.packets = 0;
                    dst.bytes = 0;
                    dst.first_seen_ns = ts_ns;
                    dst.last_seen_ns = ts_ns;
                    dst.occupied = true;
                    dst.tombstone = false;
                    ++size_;
                    return &dst;
                } else if (first_tombstone == capacity_) {
                    first_tombstone = idx;
                }
            } else if (slot.key == key) {
                return &slot;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    template <typename Fn>
    void age_out(uint64_t cutoff_ns, Fn&& fn) {
        for (auto& slot : table_) {
            if (slot.occupied && slot.last_seen_ns < cutoff_ns) {
                fn(slot);
                slot.occupied = false;
                slot.tombstone = true;
                --size_;
            }
        }
    }

    size_t size() const { return size_; }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> table_;
    size_t size_ = 0;
};

class FlowTable {
public:
    explicit FlowTable(size_t shard_count_pow2, size_t shard_capacity_pow2)
        : shard_mask_(shard_count_pow2 - 1) {
        shards_.reserve(shard_count_pow2);
        for (size_t i = 0; i < shard_count_pow2; ++i) {
            shards_.emplace_back(shard_capacity_pow2);
        }
    }

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t ts_ns, size_t& probes) {
        uint64_t h = hash_flow_key(key);
        return shards_[static_cast<size_t>(h) & shard_mask_].find_or_insert(key, ts_ns, probes);
    }

    template <typename Fn>
    void age_out(uint64_t cutoff_ns, Fn&& fn) {
        for (auto& shard : shards_) {
            shard.age_out(cutoff_ns, fn);
        }
    }

private:
    size_t shard_mask_;
    std::vector<FlowShard> shards_;
};

// ============================
// Packet parsing
// ============================

struct ParsedPacket {
    FlowKey key{};
    uint32_t l3_len = 0;
    uint32_t l4_len = 0;
    uint8_t proto = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(std::span<const uint8_t> pkt) {
    ParsedPacket out{};
    if (pkt.size() < sizeof(EthHdr)) return out;

    const uint8_t* p = pkt.data();
    size_t len = pkt.size();

    auto eth = reinterpret_cast<const EthHdr*>(p);
    uint16_t ethertype = ntoh16(eth->ethertype);
    size_t off = sizeof(EthHdr);

    // VLAN support
    if (ethertype == 0x8100 || ethertype == 0x88A8) {
        if (len < off + sizeof(VlanHdr)) return out;
        auto vlan = reinterpret_cast<const VlanHdr*>(p + off);
        ethertype = ntoh16(vlan->ethertype);
        off += sizeof(VlanHdr);
    }

    if (ethertype == 0x0800) { // IPv4
        if (len < off + sizeof(Ipv4Hdr)) return out;
        auto ip = reinterpret_cast<const Ipv4Hdr*>(p + off);
        uint8_t ihl = ip->ver_ihl & 0x0F;
        uint8_t ver = ip->ver_ihl >> 4;
        if (ver != 4 || ihl < 5) return out;

        size_t ip_hdr_len = ihl * 4;
        if (len < off + ip_hdr_len) return out;

        out.key.ip_version = 4;
        out.key.proto = ip->protocol;
        out.key.src_v4 = ntoh32(ip->src);
        out.key.dst_v4 = ntoh32(ip->dst);

        off += ip_hdr_len;

        if (ip->protocol == 6) { // TCP
            if (len < off + sizeof(TcpHdr)) return out;
            auto tcp = reinterpret_cast<const TcpHdr*>(p + off);
            out.key.src_port = ntoh16(tcp->src_port);
            out.key.dst_port = ntoh16(tcp->dst_port);
            out.proto = 6;
        } else if (ip->protocol == 17) { // UDP
            if (len < off + sizeof(UdpHdr)) return out;
            auto udp = reinterpret_cast<const UdpHdr*>(p + off);
            out.key.src_port = ntoh16(udp->src_port);
            out.key.dst_port = ntoh16(udp->dst_port);
            out.proto = 17;
        } else {
            return out;
        }

        out.valid = true;
        return out;
    }

    if (ethertype == 0x86DD) { // IPv6
        if (len < off + sizeof(Ipv6Hdr)) return out;
        auto ip6 = reinterpret_cast<const Ipv6Hdr*>(p + off);

        out.key.ip_version = 6;
        out.key.proto = ip6->next_header;
        std::memcpy(out.key.src_v6.data(), ip6->src, 16);
        std::memcpy(out.key.dst_v6.data(), ip6->dst, 16);

        off += sizeof(Ipv6Hdr);

        if (ip6->next_header == 6) {
            if (len < off + sizeof(TcpHdr)) return out;
            auto tcp = reinterpret_cast<const TcpHdr*>(p + off);
            out.key.src_port = ntoh16(tcp->src_port);
            out.key.dst_port = ntoh16(tcp->dst_port);
            out.proto = 6;
        } else if (ip6->next_header == 17) {
            if (len < off + sizeof(UdpHdr)) return out;
            auto udp = reinterpret_cast<const UdpHdr*>(p + off);
            out.key.src_port = ntoh16(udp->src_port);
            out.key.dst_port = ntoh16(udp->dst_port);
            out.proto = 17;
        } else {
            return out;
        }

        out.valid = true;
        return out;
    }

    return out;
}

// ============================
// Analyzer
// ============================

class FlowAnalyzer {
public:
    FlowAnalyzer(size_t shards_pow2 = 64, size_t shard_capacity_pow2 = 1 << 16)
        : table_(shards_pow2, shard_capacity_pow2) {}

    void process_packet(std::span<const uint8_t> pkt, uint64_t ts_ns) {
        ParsedPacket parsed = parse_packet(pkt);
        if (!parsed.valid) return;

        size_t probes = 0;
        FlowRecord* rec = table_.find_or_insert(parsed.key, ts_ns, probes);
        if (!rec) {
            dropped_++;
            return;
        }

        rec->packets++;
        rec->bytes += pkt.size();
        rec->last_seen_ns = ts_ns;

        total_packets_++;
        total_bytes_ += pkt.size();
        total_probes_ += probes;
    }

    template <typename Fn>
    void age_out(uint64_t idle_timeout_ns, Fn&& fn) {
        uint64_t cutoff = now_ns() - idle_timeout_ns;
        table_.age_out(cutoff, std::forward<Fn>(fn));
    }

    void stats() const {
        std::cout << "packets=" << total_packets_.load()
                  << " bytes=" << total_bytes_.load()
                  << " dropped=" << dropped_.load()
                  << " probes=" << total_probes_.load()
                  << "\n";
    }

private:
    FlowTable table_;
    std::atomic<uint64_t> total_packets_{0};
    std::atomic<uint64_t> total_bytes_{0};
    std::atomic<uint64_t> dropped_{0};
    std::atomic<uint64_t> total_probes_{0};
};

// ============================
// Example usage
// ============================

int main() {
    FlowAnalyzer analyzer;

    // Example packet buffer would come from capture backend
    std::vector<uint8_t> dummy_packet(64, 0);

    // NOTE: This dummy packet is not a valid Ethernet/IP packet.
    // Replace with real capture data from DPDK/AF_XDP/libpcap.
    analyzer.process_packet(dummy_packet, now_ns());

    analyzer.stats();
    return 0;
}
