#include <array>
#include <atomic>
#include <bit>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <memory>
#include <span>
#include <thread>
#include <vector>
#include <chrono>

// -----------------------------
// Packet parsing
// -----------------------------

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_frag;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct IPv6Header {
    uint32_t ver_tc_fl;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src[16];
    uint8_t dst[16];
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) {
    return __builtin_bswap16(x);
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

// -----------------------------
// Flow key / flow state
// -----------------------------

enum class L4Proto : uint8_t {
    Unknown = 0,
    TCP = 6,
    UDP = 17,
    ICMP = 1
};

struct FlowKey {
    uint8_t ip_version;   // 4 or 6
    uint8_t protocol;     // L4 protocol
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4 uses lower 32 bits of src/dst, IPv6 uses full 128 bits
    std::array<uint8_t, 16> src_ip{};
    std::array<uint8_t, 16> dst_ip{};

    bool operator==(const FlowKey& other) const noexcept {
        return ip_version == other.ip_version &&
               protocol == other.protocol &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               src_ip == other.src_ip &&
               dst_ip == other.dst_ip;
    }
};

struct FlowKeyHash {
    static inline uint64_t mix64(uint64_t x) noexcept {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return x;
    }

    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0xcbf29ce484222325ULL;
        auto add = [&](const void* data, size_t len) {
            const uint8_t* p = static_cast<const uint8_t*>(data);
            for (size_t i = 0; i < len; ++i) {
                h ^= p[i];
                h *= 0x100000001b3ULL;
            }
        };

        add(&k.ip_version, sizeof(k.ip_version));
        add(&k.protocol, sizeof(k.protocol));
        add(&k.src_port, sizeof(k.src_port));
        add(&k.dst_port, sizeof(k.dst_port));
        add(k.src_ip.data(), k.src_ip.size());
        add(k.dst_ip.data(), k.dst_ip.size());

        return static_cast<size_t>(mix64(h));
    }
};

struct FlowState {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint32_t tcp_flags_or = 0;
    uint32_t tcp_flags_and = 0xFF;
};

// -----------------------------
// Fast fixed-capacity hash table
// Open addressing with linear probing
// -----------------------------

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          keys_(capacity_),
          states_(capacity_),
          occupied_(capacity_) {
        if ((capacity_ & (capacity_ - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowState& get_or_create(const FlowKey& key, uint64_t now_ns) {
        const size_t idx0 = hasher_(key) & mask_;
        size_t idx = idx0;

        for (;;) {
            if (!occupied_[idx].load(std::memory_order_acquire)) {
                // Try to claim slot
                bool expected = false;
                if (occupied_[idx].compare_exchange_strong(
                        expected, true, std::memory_order_acq_rel)) {
                    keys_[idx] = key;
                    auto& st = states_[idx];
                    st.first_seen_ns = now_ns;
                    st.last_seen_ns = now_ns;
                    return st;
                }
            } else if (keys_[idx] == key) {
                auto& st = states_[idx];
                st.last_seen_ns = now_ns;
                return st;
            }

            idx = (idx + 1) & mask_;
            if (idx == idx0) {
                throw std::runtime_error("flow table full");
            }
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (size_t i = 0; i < capacity_; ++i) {
            if (occupied_[i].load(std::memory_order_acquire)) {
                fn(keys_[i], states_[i]);
            }
        }
    }

    template <typename Fn>
    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        for (size_t i = 0; i < capacity_; ++i) {
            if (occupied_[i].load(std::memory_order_acquire)) {
                if (now_ns - states_[i].last_seen_ns >= idle_timeout_ns) {
                    on_expire(keys_[i], states_[i]);
                    occupied_[i].store(false, std::memory_order_release);
                }
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    FlowKeyHash hasher_;
    std::vector<FlowKey> keys_;
    std::vector<FlowState> states_;
    std::vector<std::atomic<bool>> occupied_;
};

// -----------------------------
// Packet parser
// -----------------------------

struct ParsedPacket {
    FlowKey key{};
    uint32_t packet_len = 0;
    uint8_t l4_proto = 0;
    uint8_t tcp_flags = 0;
    bool valid = false;
};

class PacketParser {
public:
    static ParsedPacket parse(std::span<const uint8_t> pkt) {
        ParsedPacket out{};
        out.packet_len = static_cast<uint32_t>(pkt.size());

        if (pkt.size() < sizeof(EthernetHeader)) return out;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(pkt.data());
        uint16_t ethertype = ntoh16(eth->ethertype);

        size_t offset = sizeof(EthernetHeader);

        if (ethertype == 0x0800) { // IPv4
            if (pkt.size() < offset + sizeof(IPv4Header)) return out;
            const auto* ip = reinterpret_cast<const IPv4Header*>(pkt.data() + offset);

            uint8_t ihl = ip->ver_ihl & 0x0F;
            uint8_t ver = ip->ver_ihl >> 4;
            if (ver != 4 || ihl < 5) return out;

            size_t ip_hdr_len = ihl * 4;
            if (pkt.size() < offset + ip_hdr_len) return out;

            out.key.ip_version = 4;
            out.key.protocol = ip->protocol;
            out.key.src_ip.fill(0);
            out.key.dst_ip.fill(0);

            uint32_t src = ntoh32(ip->src);
            uint32_t dst = ntoh32(ip->dst);
            std::memcpy(out.key.src_ip.data(), &src, sizeof(src));
            std::memcpy(out.key.dst_ip.data(), &dst, sizeof(dst));

            offset += ip_hdr_len;

            if (ip->protocol == static_cast<uint8_t>(L4Proto::TCP)) {
                if (pkt.size() < offset + sizeof(TCPHeader)) return out;
                const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
                out.key.src_port = ntoh16(tcp->src_port);
                out.key.dst_port = ntoh16(tcp->dst_port);
                out.tcp_flags = tcp->flags;
            } else if (ip->protocol == static_cast<uint8_t>(L4Proto::UDP)) {
                if (pkt.size() < offset + sizeof(UDPHeader)) return out;
                const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
                out.key.src_port = ntoh16(udp->src_port);
                out.key.dst_port = ntoh16(udp->dst_port);
            } else {
                out.key.src_port = 0;
                out.key.dst_port = 0;
            }

            out.valid = true;
            return out;
        }

        if (ethertype == 0x86DD) { // IPv6
            if (pkt.size() < offset + sizeof(IPv6Header)) return out;
            const auto* ip6 = reinterpret_cast<const IPv6Header*>(pkt.data() + offset);

            uint32_t ver = ntoh32(ip6->ver_tc_fl) >> 28;
            if (ver != 6) return out;

            out.key.ip_version = 6;
            out.key.protocol = ip6->next_header;
            std::memcpy(out.key.src_ip.data(), ip6->src, 16);
            std::memcpy(out.key.dst_ip.data(), ip6->dst, 16);

            offset += sizeof(IPv6Header);

            if (ip6->next_header == static_cast<uint8_t>(L4Proto::TCP)) {
                if (pkt.size() < offset + sizeof(TCPHeader)) return out;
                const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
                out.key.src_port = ntoh16(tcp->src_port);
                out.key.dst_port = ntoh16(tcp->dst_port);
                out.tcp_flags = tcp->flags;
            } else if (ip6->next_header == static_cast<uint8_t>(L4Proto::UDP)) {
                if (pkt.size() < offset + sizeof(UDPHeader)) return out;
                const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
                out.key.src_port = ntoh16(udp->src_port);
                out.key.dst_port = ntoh16(udp->dst_port);
            } else {
                out.key.src_port = 0;
                out.key.dst_port = 0;
            }

            out.valid = true;
            return out;
        }

        return out;
    }
};

// -----------------------------
// Analyzer
// -----------------------------

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2 = 20)
        : table_(table_pow2) {}

    void ingest_packet(std::span<const uint8_t> pkt, uint64_t now_ns) {
        ParsedPacket p = PacketParser::parse(pkt);
        if (!p.valid) return;

        FlowState& st = table_.get_or_create(p.key, now_ns);
        st.packets++;
        st.bytes += p.packet_len;
        st.last_seen_ns = now_ns;
        if (st.first_seen_ns == 0) st.first_seen_ns = now_ns;
        st.tcp_flags_or |= p.tcp_flags;
        st.tcp_flags_and &= p.tcp_flags;
    }

    template <typename Fn>
    void export_flows(Fn&& fn) {
        table_.for_each(std::forward<Fn>(fn));
    }

    template <typename Fn>
    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        table_.age_out(now_ns, idle_timeout_ns, std::forward<Fn>(on_expire));
    }

private:
    FlowTable table_;
};

