// Example usage
// -----------------------------

static uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
}

int main() {
    FlowAnalyzer analyzer(20); // ~1M slots

    // Example packet buffer (placeholder, not a real packet)
    std::vector<uint8_t> packet(64, 0);

    // In a real system, this would come from AF_PACKET/DPDK/etc.
    analyzer.ingest_packet(packet, now_ns());

    analyzer.export_flows([](const FlowKey& key, const FlowState& st) {
        std::cout << "Flow packets=" << st.packets
                  << " bytes=" << st.bytes
                  << " first=" << st.first_seen_ns
                  << " last=" << st.last_seen_ns
                  << "\n";
    });

    analyzer.age_out(now_ns(), 60ULL * 1'000'000'000ULL, [](const FlowKey&, const FlowState&) {
        // export expired flow
    });

    return 0;
}
