#include <bit>
#include <limits>

// ==============================
// Utilities
// ==============================

static inline uint64_t rdtsc_fallback_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint32_t rotl32(uint32_t x, int r) {
    return (x << r) | (x >> (32 - r));
}

// Fast-ish 64-bit mix (splitmix64 style)
static inline uint64_t mix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

// ==============================
// Packet / Flow key
// ==============================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

struct PacketView {
    uint32_t src_ip;   // host order
    uint32_t dst_ip;   // host order
    uint16_t src_port; // host order
    uint16_t dst_port; // host order
    L4Proto proto;
    uint32_t length;   // bytes
    uint64_t ts_ns;    // timestamp in ns
};

struct FlowKey {
    uint32_t a_ip;
    uint32_t b_ip;
    uint16_t a_port;
    uint16_t b_port;
    uint8_t  proto;

    // Canonicalized direction-independent key
    static FlowKey canonical(uint32_t src_ip, uint32_t dst_ip,
                             uint16_t src_port, uint16_t dst_port,
                             L4Proto proto) {
        FlowKey k{};
        k.proto = static_cast<uint8_t>(proto);

        // Canonical order: lexicographic tuple
        if (src_ip < dst_ip ||
            (src_ip == dst_ip && src_port <= dst_port)) {
            k.a_ip = src_ip;
            k.b_ip = dst_ip;
            k.a_port = src_port;
            k.b_port = dst_port;
        } else {
            k.a_ip = dst_ip;
            k.b_ip = src_ip;
            k.a_port = dst_port;
            k.b_port = src_port;
        }
        return k;
    }

    bool operator==(const FlowKey& other) const noexcept {
        return a_ip == other.a_ip &&
               b_ip == other.b_ip &&
               a_port == other.a_port &&
               b_port == other.b_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t x = 0;
        x ^= mix64((uint64_t)k.a_ip);
        x ^= mix64((uint64_t)k.b_ip << 1);
        x ^= mix64((uint64_t)k.a_port << 32 | k.b_port);
        x ^= mix64((uint64_t)k.proto << 48);
        return (size_t)mix64(x);
    }
};

// ==============================
// Flow record
// ==============================

struct FlowRecord {
    FlowKey key{};
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns  = 0;
    uint64_t packets       = 0;
    uint64_t bytes         = 0;
    uint32_t tcp_flags     = 0; // optional aggregation
    bool     in_use        = false;
};

// ==============================
// High-performance open-addressing flow table
// - fixed capacity
// - linear probing
// - no per-flow heap allocations
// ==============================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : cap_(next_pow2(capacity_pow2)),
          mask_(cap_ - 1),
          entries_(cap_) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t ts_ns) {
        size_t idx = FlowKeyHash{}(key) & mask_;

        for (size_t probe = 0; probe < cap_; ++probe) {
            FlowRecord& e = entries_[idx];
            if (!e.in_use) {
                e.in_use = true;
                e.key = key;
                e.first_seen_ns = ts_ns;
                e.last_seen_ns = ts_ns;
                e.packets = 0;
                e.bytes = 0;
                e.tcp_flags = 0;
                return &e;
            }
            if (e.key == key) {
                return &e;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        for (auto& e : entries_) {
            if (e.in_use && now_ns - e.last_seen_ns >= idle_timeout_ns) {
                on_expire(e);
                e.in_use = false;
            }
        }
    }

    size_t capacity() const { return cap_; }

private:
    static size_t next_pow2(size_t x) {
        if (x < 2) return 2;
        --x;
        for (size_t i = 1; i < sizeof(size_t) * 8; i <<= 1) x |= x >> i;
        return x + 1;
    }

    size_t cap_;
    size_t mask_;
    std::vector<FlowRecord> entries_;
};

// ==============================
// Analyzer
// ==============================

class FlowAnalyzer {
public:
    struct Stats {
        uint64_t packets = 0;
        uint64_t bytes = 0;
        uint64_t dropped_table_full = 0;
        uint64_t expired_flows = 0;
    };

    explicit FlowAnalyzer(size_t flow_capacity_pow2,
                          uint64_t idle_timeout_ns)
        : table_(flow_capacity_pow2),
          idle_timeout_ns_(idle_timeout_ns) {}

    inline void process_packet(const PacketView& p) {
        ++stats_.packets;
        stats_.bytes += p.length;

        FlowKey key = FlowKey::canonical(p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.proto);
        FlowRecord* flow = table_.find_or_insert(key, p.ts_ns);

        if (!flow) {
            ++stats_.dropped_table_full;
            return;
        }

        if (flow->packets == 0) {
            flow->first_seen_ns = p.ts_ns;
        }
        flow->last_seen_ns = p.ts_ns;
        ++flow->packets;
        flow->bytes += p.length;
    }

    template <typename PacketRange>
    void process_batch(const PacketRange& packets) {
        for (const auto& p : packets) {
            process_packet(p);
        }
    }

    void expire(uint64_t now_ns) {
        table_.expire(now_ns, idle_timeout_ns_, [&](const FlowRecord&) {
            ++stats_.expired_flows;
        });
    }

    const Stats& stats() const { return stats_; }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
    Stats stats_;
};

// ==============================
// Example usage
// ==============================

int main() {
    // Example: 1M flow table, 30s idle timeout
    FlowAnalyzer analyzer(1u << 20, 30ULL * 1000 * 1000 * 1000);

    std::vector<PacketView> batch;
    batch.reserve(3);

    uint64_t now = rdtsc_fallback_ns();

    batch.push_back({0x0a000001, 0x0a000002, 12345, 80, L4Proto::TCP, 1500, now});
    batch.push_back({0x0a000002, 0x0a000001, 80, 12345, L4Proto::TCP, 1500, now + 1000});
    batch.push_back({0x0a000001, 0x0a000003, 54321, 53, L4Proto::UDP, 128, now + 2000});

    analyzer.process_batch(batch);
    analyzer.expire(now + 31ULL * 1000 * 1000 * 1000);

    const auto& s = analyzer.stats();
    std::cout << "Packets: " << s.packets << "\n";
    std::cout << "Bytes: " << s.bytes << "\n";
    std::cout << "Dropped (table full): " << s.dropped_table_full << "\n";
    std::cout << "Expired flows: " << s.expired_flows << "\n";

    return 0;
}
