#include <algorithm>

// ==========================
// Fast hashing
// ==========================
static inline uint64_t mix64(uint64_t x) {
    // SplitMix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

// ==========================
// Flow key
// ==========================
struct FlowKey {
    uint8_t  ip_version;   // 4 or 6
    uint8_t  protocol;     // TCP/UDP/ICMP...
    uint16_t src_port;
    uint16_t dst_port;

    union {
        struct {
            uint32_t src_ip;
            uint32_t dst_ip;
        } v4;
        struct {
            uint64_t src_hi, src_lo;
            uint64_t dst_hi, dst_lo;
        } v6;
    } addr;

    bool operator==(const FlowKey& other) const noexcept {
        if (ip_version != other.ip_version ||
            protocol   != other.protocol   ||
            src_port   != other.src_port   ||
            dst_port   != other.dst_port) {
            return false;
        }

        if (ip_version == 4) {
            return addr.v4.src_ip == other.addr.v4.src_ip &&
                   addr.v4.dst_ip == other.addr.v4.dst_ip;
        } else {
            return addr.v6.src_hi == other.addr.v6.src_hi &&
                   addr.v6.src_lo == other.addr.v6.src_lo &&
                   addr.v6.dst_hi == other.addr.v6.dst_hi &&
                   addr.v6.dst_lo == other.addr.v6.dst_lo;
        }
    }
};

struct FlowKeyHasher {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0;
        h ^= mix64(k.ip_version);
        h ^= mix64(k.protocol);
        h ^= mix64(k.src_port);
        h ^= mix64(k.dst_port);

        if (k.ip_version == 4) {
            h ^= mix64(k.addr.v4.src_ip);
            h ^= mix64(k.addr.v4.dst_ip);
        } else {
            h ^= mix64(k.addr.v6.src_hi);
            h ^= mix64(k.addr.v6.src_lo);
            h ^= mix64(k.addr.v6.dst_hi);
            h ^= mix64(k.addr.v6.dst_lo);
        }
        return static_cast<size_t>(h);
    }
};

// ==========================
// Flow record
// ==========================
struct FlowRecord {
    FlowKey key;
    uint64_t packets = 0;
    uint64_t bytes   = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns  = 0;
    bool     active = false;
};

// ==========================
// High-performance open-addressing flow table
// ==========================
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          table_(capacity_) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        size_t idx = FlowKeyHasher{}(key) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowRecord& slot = table_[idx];

            if (!slot.active) {
                slot.key = key;
                slot.packets = 0;
                slot.bytes = 0;
                slot.first_seen_ns = now_ns;
                slot.last_seen_ns = now_ns;
                slot.active = true;
                ++size_;
                return &slot;
            }

            if (slot.key == key) {
                slot.last_seen_ns = now_ns;
                return &slot;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        for (auto& slot : table_) {
            if (slot.active && (now_ns - slot.last_seen_ns) > idle_timeout_ns) {
                slot.active = false;
                --size_;
            }
        }
    }

    size_t size() const noexcept { return size_; }
    size_t capacity() const noexcept { return capacity_; }

    const std::vector<FlowRecord>& raw() const noexcept { return table_; }

private:
    size_t capacity_;
    size_t mask_;
    size_t size_ = 0;
    std::vector<FlowRecord> table_;
};

// ==========================
// Packet metadata
// ==========================
struct PacketView {
    FlowKey key;
    uint32_t payload_bytes;
    uint64_t timestamp_ns;
};

// ==========================
// Analyzer
// ==========================
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2,
                          uint64_t idle_timeout_ns = 30ULL * 1000 * 1000 * 1000)
        : table_(table_pow2),
          idle_timeout_ns_(idle_timeout_ns) {}

    inline void process_packet(const PacketView& pkt) noexcept {
        FlowRecord* rec = table_.find_or_insert(pkt.key, pkt.timestamp_ns);
        if (!rec) {
            // Table full: in production you might evict, sample, or spill.
            dropped_++;
            return;
        }

        rec->packets += 1;
        rec->bytes += pkt.payload_bytes;
    }

    void periodic_maintenance(uint64_t now_ns) noexcept {
        table_.age_out(now_ns, idle_timeout_ns_);
    }

    void print_summary() const {
        std::cout << "Active flows: " << table_.size() << "\n";
        std::cout << "Dropped packets due to full table: " << dropped_ << "\n";
    }

    const FlowTable& table() const noexcept { return table_; }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
    uint64_t dropped_ = 0;
};

// ==========================
// Example usage
// ==========================
static inline uint64_t now_ns() {
    using clock = std::chrono::steady_clock;
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        clock::now().time_since_epoch()
    ).count();
}

