// -----------------------------
// Packet / Flow definitions
// -----------------------------

struct PacketView {
    // 5-tuple
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    // L2/L3/L4 metadata
    uint32_t bytes;
    uint64_t timestamp_ns;
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes   = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns  = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
    bool tombstone = false;
};

// -----------------------------
// Fast hash
// -----------------------------

static inline uint64_t mix64(uint64_t x) noexcept {
    // SplitMix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t a = (uint64_t(k.src_ip) << 32) ^ uint64_t(k.dst_ip);
    uint64_t b = (uint64_t(k.src_port) << 48) ^ (uint64_t(k.dst_port) << 32) ^ uint64_t(k.protocol);
    return mix64(a ^ mix64(b));
}

// -----------------------------
// Flow table: open addressing
// -----------------------------

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1),
          entries_(capacity_pow2) {
        // capacity_pow2 must be a power of two
    }

    FlowEntry* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        const uint64_t h = hash_flow_key(key);
        size_t idx = size_t(h) & mask_;
        size_t first_tombstone = npos;

        for (size_t probe = 0; probe < entries_.size(); ++probe) {
            FlowEntry& e = entries_[idx];

            if (!e.occupied) {
                if (!e.tombstone) {
                    // Empty slot, use tombstone if seen
                    FlowEntry& target = (first_tombstone != npos)
                        ? entries_[first_tombstone]
                        : e;

                    target.key = key;
                    target.hash = h;
                    target.occupied = true;
                    target.tombstone = false;
                    target.stats = {};
                    target.stats.first_seen_ns = now_ns;
                    target.stats.last_seen_ns  = now_ns;
                    return &target;
                } else if (first_tombstone == npos) {
                    first_tombstone = idx;
                }
            } else if (e.hash == h && e.key == key) {
                return &e;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    void expire_idle(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        for (auto& e : entries_) {
            if (e.occupied && (now_ns - e.stats.last_seen_ns) > idle_timeout_ns) {
                e.occupied = false;
                e.tombstone = true;
            }
        }
    }

    size_t size() const noexcept {
        size_t count = 0;
        for (const auto& e : entries_) {
            if (e.occupied) ++count;
        }
        return count;
    }

private:
    static constexpr size_t npos = static_cast<size_t>(-1);
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// -----------------------------
// Sharded analyser
// -----------------------------

class FlowAnalyzer {
public:
    struct Config {
        size_t shards = 16;
        size_t table_capacity_pow2 = 1 << 20; // per shard
        uint64_t idle_timeout_ns = 30ULL * 1'000'000'000ULL;
    };

    explicit FlowAnalyzer(Config cfg)
        : cfg_(cfg) {
        if ((cfg_.shards == 0) || (cfg_.shards & (cfg_.shards - 1)) != 0) {
            throw std::runtime_error("shards must be a power of two");
        }
        if ((cfg_.table_capacity_pow2 == 0) || (cfg_.table_capacity_pow2 & (cfg_.table_capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("table_capacity_pow2 must be a power of two");
        }

        shards_.reserve(cfg_.shards);
        for (size_t i = 0; i < cfg_.shards; ++i) {
            shards_.emplace_back(cfg_.table_capacity_pow2);
        }
    }

    void ingest(const PacketView& pkt) noexcept {
        FlowKey key{pkt.src_ip, pkt.dst_ip, pkt.src_port, pkt.dst_port, pkt.protocol};
        const uint64_t h = hash_flow_key(key);
        FlowTable& table = shards_[h & (cfg_.shards - 1)];

        FlowEntry* e = table.find_or_insert(key, pkt.timestamp_ns);
        if (!e) {
            // Table full: drop or count overflow here
            return;
        }

        e->stats.packets += 1;
        e->stats.bytes   += pkt.bytes;
        e->stats.last_seen_ns = pkt.timestamp_ns;
    }

    void expire_all(uint64_t now_ns) noexcept {
        for (auto& shard : shards_) {
            shard.expire_idle(now_ns, cfg_.idle_timeout_ns);
        }
    }

    size_t active_flows() const noexcept {
        size_t total = 0;
        for (const auto& shard : shards_) {
            total += shard.size();
        }
        return total;
    }

private:
    Config cfg_;
    std::vector<FlowTable> shards_;
};

// -----------------------------
// Example usage
// -----------------------------

int main() {
    FlowAnalyzer::Config cfg;
    cfg.shards = 16;
    cfg.table_capacity_pow2 = 1 << 18; // 262,144 entries per shard
    cfg.idle_timeout_ns = 10ULL * 1'000'000'000ULL;

    FlowAnalyzer analyser(cfg);

    auto now_ns = []() -> uint64_t {
        using namespace std::chrono;
        return duration_cast<nanoseconds>(
            steady_clock::now().time_since_epoch()
        ).count();
    };

    // Simulated packets
    for (int i = 0; i < 1'000'000; ++i) {
        PacketView p;
        p.src_ip = 0x0A000001 + (i % 1024);
        p.dst_ip = 0x0A000100 + (i % 256);
        p.src_port = uint16_t(10000 + (i % 1000));
        p.dst_port = 443;
        p.protocol = 6; // TCP
        p.bytes = 1500;
        p.timestamp_ns = now_ns();

        analyser.ingest(p);

        if ((i % 100000) == 0) {
            analyser.expire_all(now_ns());
            std::cout << "Active flows: " << analyser.active_flows() << "\n";
        }
    }

    std::cout << "Final active flows: " << analyser.active_flows() << "\n";
    return 0;
}
