#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <vector>
#include <chrono>
#include <iostream>
#include <optional>
#include <thread>
#include <algorithm>

#if defined(__GNUC__) || defined(__clang__)
#define ALWAYS_INLINE __attribute__((always_inline)) inline
#define LIKELY(x)   __builtin_expect(!!(x), 1)
#define UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define ALWAYS_INLINE inline
#define LIKELY(x)   (x)
#define UNLIKELY(x)   (x)
#endif

// -----------------------------
// Packet capture abstraction
// -----------------------------
struct PacketView {
    const uint8_t* data;
    uint32_t len;
    uint64_t ts_ns;
};

// -----------------------------
// Flow key: IPv4 5-tuple
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    ALWAYS_INLINE bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

// -----------------------------
// Fast hash for flow keys
// -----------------------------
ALWAYS_INLINE static uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

ALWAYS_INLINE static uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t x = 0;
    x ^= uint64_t(k.src_ip) * 0x9e3779b185ebca87ULL;
    x ^= uint64_t(k.dst_ip) * 0xc2b2ae3d27d4eb4fULL;
    x ^= uint64_t(k.src_port) << 16;
    x ^= uint64_t(k.dst_port) << 32;
    x ^= uint64_t(k.proto) << 48;
    return mix64(x);
}

// -----------------------------
// Flow record
// -----------------------------
struct alignas(64) FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool occupied = false;
};

// -----------------------------
// Fixed-size open-addressing flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be a power of two");
        }
    }

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t ts_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = size_t(h) & mask_;

        for (size_t probe = 0; probe < table_.size(); ++probe) {
            FlowRecord& slot = table_[idx];
            if (!slot.occupied) {
                slot.key = key;
                slot.packets = 0;
                slot.bytes = 0;
                slot.first_seen_ns = ts_ns;
                slot.last_seen_ns = ts_ns;
                slot.occupied = true;
                return &slot;
            }
            if (slot.key == key) {
                return &slot;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // Table full
    }

    template <typename Fn>
    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        for (auto& slot : table_) {
            if (slot.occupied && (now_ns - slot.last_seen_ns > idle_timeout_ns)) {
                on_expire(slot);
                slot = FlowRecord{};
            }
        }
    }

private:
    size_t mask_;
    std::vector<FlowRecord> table_;
};

// -----------------------------
// Packet parsing helpers
// -----------------------------
ALWAYS_INLINE static uint16_t read_be16(const uint8_t* p) noexcept {
    return (uint16_t(p[0]) << 8) | uint16_t(p[1]);
}

ALWAYS_INLINE static uint32_t read_be32(const uint8_t* p) noexcept {
    return (uint32_t(p[0]) << 24) | (uint32_t(p[1]) << 16) |
           (uint32_t(p[2]) << 8) | uint32_t(p[3]);
}

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

ALWAYS_INLINE static ParsedPacket parse_ipv4_tcp_udp(const PacketView& pkt) noexcept {
    ParsedPacket out{};

    // Ethernet header: 14 bytes
    if (pkt.len < 14) return out;
    const uint8_t* p = pkt.data;

    uint16_t ethertype = read_be16(p + 12);
    if (ethertype != 0x0800) return out; // IPv4 only for this fast path

    // IPv4 header
    const uint8_t* ip = p + 14;
    if (pkt.len < 14 + 20) return out;

    uint8_t ver_ihl = ip[0];
    uint8_t version = ver_ihl >> 4;
    uint8_t ihl = ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) return out;

    uint32_t ip_hdr_len = uint32_t(ihl) * 4;
    if (pkt.len < 14 + ip_hdr_len) return out;

    uint8_t proto = ip[9];
    uint32_t src_ip = read_be32(ip + 12);
    uint32_t dst_ip = read_be32(ip + 16);

    const uint8_t* l4 = ip + ip_hdr_len;
    uint32_t l4_len = pkt.len - 14 - ip_hdr_len;

    if (proto == 6) { // TCP
        if (l4_len < 20) return out;
        uint16_t src_port = read_be16(l4 + 0);
        uint16_t dst_port = read_be16(l4 + 2);
        uint8_t data_offset = (l4[12] >> 4) & 0x0F;
        uint32_t tcp_hdr_len = uint32_t(data_offset) * 4;
        if (l4_len < tcp_hdr_len) return out;

        out.key = FlowKey{src_ip, dst_ip, src_port, dst_port, proto};
        out.payload_len = l4_len - tcp_hdr_len;
        out.valid = true;
        return out;
    } else if (proto == 17) { // UDP
        if (l4_len < 8) return out;
        uint16_t src_port = read_be16(l4 + 0);
        uint16_t dst_port = read_be16(l4 + 2);
        uint16_t udp_len = read_be16(l4 + 4);
        if (udp_len < 8 || udp_len > l4_len) return out;

        out.key = FlowKey{src_ip, dst_ip, src_port, dst_port, proto};
        out.payload_len = udp_len - 8;
        out.valid = true;
        return out;
    }

    return out;
}

// -----------------------------
// Flow analyser
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    ALWAYS_INLINE void ingest(const PacketView& pkt) noexcept {
        ParsedPacket parsed = parse_ipv4_tcp_udp(pkt);
        if (UNLIKELY(!parsed.valid)) return;

        FlowRecord* rec = table_.find_or_insert(parsed.key, pkt.ts_ns);
        if (UNLIKELY(!rec)) {
            dropped_++;
            return;
        }

        rec->packets++;
        rec->bytes += parsed.payload_len;
        rec->last_seen_ns = pkt.ts_ns;
    }

    template <typename Fn>
    void expire(uint64_t now_ns, Fn&& on_expire) {
        table_.age_out(now_ns, idle_timeout_ns_, std::forward<Fn>(on_expire));
    }

    uint64_t dropped() const noexcept { return dropped_.load(std::memory_order_relaxed); }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
    std::atomic<uint64_t> dropped_{0};
};

// -----------------------------
// Example usage
// -----------------------------
static void on_flow_expire(const FlowRecord& r) {
    std::cout << "Expired flow: "
              << "pkts=" << r.packets
              << " bytes=" << r.bytes
              << " first=" << r.first_seen_ns
              << " last=" << r.last_seen_ns
              << "\n";
}

int main() {
    // 1M slots, idle timeout 30s
    FlowAnalyzer analyzer(1u << 20, 30ULL * 1'000'000'000ULL);

    // Example packet buffer placeholder
    std::array<uint8_t, 64> pktbuf{};
    PacketView pkt{pktbuf.data(), uint32_t(pktbuf.size()), 1'000'000'000ULL};

    // In real use, fill pktbuf from AF_PACKET, DPDK, netmap, PF_RING, etc.
    analyzer.ingest(pkt);

    analyzer.expire(2'000'000'000ULL, on_flow_expire);

    std::cout << "Dropped: " << analyzer.dropped() << "\n";
    return 0;
}
