#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <mutex>
#include <optional>
#include <thread>
#include <unordered_map>
#include <vector>

// -------------------------
// Fast flow key
// -------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  pad[3]{}; // align to 16 bytes

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // 64-bit mix, reasonably fast
        uint64_t x = 0;
        x ^= (uint64_t)k.src_ip * 0x9e3779b185ebca87ULL;
        x ^= (uint64_t)k.dst_ip * 0xc2b2ae3d27d4eb4fULL;
        x ^= (uint64_t)k.src_port << 48;
        x ^= (uint64_t)k.dst_port << 32;
        x ^= (uint64_t)k.protocol << 24;

        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return static_cast<size_t>(x);
    }
};

// -------------------------
// Flow statistics
// -------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// -------------------------
// Packet representation
// In real deployments this would be filled from a capture backend.
// -------------------------
struct Packet {
    FlowKey key;
    uint32_t length;
    uint64_t timestamp_ns;
};

// -------------------------
// Sharded flow table
// -------------------------
class FlowTable {
public:
    explicit FlowTable(size_t shard_count = 64, size_t reserve_per_shard = 1 << 16)
        : shards_(shard_count) {
        for (auto& shard : shards_) {
            shard.map.reserve(reserve_per_shard);
        }
    }

    void add_packet(const Packet& pkt) {
        auto& shard = shards_[shard_index(pkt.key)];
        std::lock_guard<std::mutex> lock(shard.mutex);

        auto it = shard.map.find(pkt.key);
        if (it == shard.map.end()) {
            FlowStats stats;
            stats.packets = 1;
            stats.bytes = pkt.length;
            stats.first_seen_ns = pkt.timestamp_ns;
            stats.last_seen_ns = pkt.timestamp_ns;
            shard.map.emplace(pkt.key, stats);
        } else {
            FlowStats& stats = it->second;
            ++stats.packets;
            stats.bytes += pkt.length;
            stats.last_seen_ns = pkt.timestamp_ns;
        }
    }

    // Expire flows inactive for longer than timeout_ns.
    // Returns number of expired flows.
    size_t expire(uint64_t now_ns, uint64_t timeout_ns) {
        size_t expired = 0;
        for (auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mutex);

            for (auto it = shard.map.begin(); it != shard.map.end(); ) {
                if (now_ns - it->second.last_seen_ns > timeout_ns) {
                    it = shard.map.erase(it);
                    ++expired;
                } else {
                    ++it;
                }
            }
        }
        return expired;
    }

    // Snapshot for reporting
    std::vector<std::pair<FlowKey, FlowStats>> snapshot() const {
        std::vector<std::pair<FlowKey, FlowStats>> out;
        for (const auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mutex);
            out.reserve(out.size() + shard.map.size());
            for (const auto& kv : shard.map) {
                out.push_back(kv);
            }
        }
        return out;
    }

private:
    struct Shard {
        mutable std::mutex mutex;
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> map;
    };

    std::vector<Shard> shards_;

    size_t shard_index(const FlowKey& key) const noexcept {
        return FlowKeyHash{}(key) % shards_.size();
    }
};

// -------------------------
// Analyzer
// -------------------------
class NetworkFlowAnalyzer {
public:
    NetworkFlowAnalyzer(size_t shard_count = 64,
                        size_t reserve_per_shard = 1 << 16,
                        uint64_t flow_timeout_ns = 30ULL * 1'000'000'000ULL)
        : table_(shard_count, reserve_per_shard),
          flow_timeout_ns_(flow_timeout_ns) {}

    void process_batch(const Packet* packets, size_t count) {
        // Hot path: minimal work per packet
        for (size_t i = 0; i < count; ++i) {
            table_.add_packet(packets[i]);
        }
    }

    void maintenance(uint64_t now_ns) {
        size_t expired = table_.expire(now_ns, flow_timeout_ns_);
        if (expired > 0) {
            std::cout << "Expired flows: " << expired << "\n";
        }
    }

    void report_top_flows(size_t top_n = 10) {
        auto flows = table_.snapshot();
        std::sort(flows.begin(), flows.end(),
                  [](const auto& a, const auto& b) {
                      return a.second.bytes > b.second.bytes;
                  });

        std::cout << "Top " << top_n << " flows by bytes:\n";
        for (size_t i = 0; i < std::min(top_n, flows.size()); ++i) {
            const auto& [k, s] = flows[i];
            std::cout << i + 1 << ": "
                      << ip_to_string(k.src_ip) << ":" << k.src_port
                      << " -> "
                      << ip_to_string(k.dst_ip) << ":" << k.dst_port
                      << " proto=" << unsigned(k.protocol)
                      << " packets=" << s.packets
                      << " bytes=" << s.bytes
                      << "\n";
        }
    }

private:
    FlowTable table_;
    uint64_t flow_timeout_ns_;

    static std::string ip_to_string(uint32_t ip_be) {
        uint8_t b1 = (ip_be >> 24) & 0xFF;
        uint8_t b2 = (ip_be >> 16) & 0xFF;
        uint8_t b3 = (ip_be >> 8) & 0xFF;
        uint8_t b4 = ip_be & 0xFF;
        return std::to_string(b1) + "." + std::to_string(b2) + "." +
               std::to_string(b3) + "." + std::to_string(b4);
    }
};

// -------------------------
// Example usage
// -------------------------
int main() {
    NetworkFlowAnalyzer analyzer(64, 1 << 14, 30ULL * 1'000'000'000ULL);

    std::vector<Packet> batch;
    batch.reserve(1024);

    // Simulated traffic
    uint64_t now_ns = 1'000'000'000ULL;
    for (int i = 0; i < 100000; ++i) {
        Packet p;
        p.key.src_ip = 0x0A000001 + (i % 256); // 10.0.0.x
        p.key.dst_ip = 0x0A000100 + (i % 64);  // 10.0.1.x
        p.key.src_port = 10000 + (i % 1000);
        p.key.dst_port = 80;
        p.key.protocol = 6; // TCP
        p.length = 64 + (i % 1400);
        p.timestamp_ns = now_ns + i * 1000;

        batch.push_back(p);

        if (batch.size() == 1024) {
            analyzer.process_batch(batch.data(), batch.size());
            batch.clear();
        }
    }

    if (!batch.empty()) {
        analyzer.process_batch(batch.data(), batch.size());
    }

    analyzer.maintenance(now_ns + 40ULL * 1'000'000'000ULL);
    analyzer.report_top_flows(10);

    return 0;
}
