```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <vector>
#include <thread>
#include <iostream>
#include <optional>
#include <algorithm>
#include <shared_mutex>

// ============================================================
// Configuration
// ============================================================

static constexpr size_t FLOW_TABLE_SIZE = 1 << 20;   // 1,048,576 slots
static constexpr size_t FLOW_TABLE_MASK = FLOW_TABLE_SIZE - 1;
static constexpr uint64_t FLOW_IDLE_TIMEOUT_NS = 30ULL * 1000ULL * 1000ULL * 1000ULL; // 30s
static constexpr size_t EXPORT_BATCH_SIZE = 4096;

// ============================================================
// Packet / Flow definitions
// ============================================================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    OTHER = 255
};

struct PacketView {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    L4Proto proto;
    uint32_t bytes;
    uint64_t timestamp_ns;
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    // Fast 64-bit mix (splitmix-like)
    uint64_t x = 0;
    x ^= (uint64_t)k.src_ip + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= (uint64_t)k.dst_ip + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= (uint64_t)k.src_port + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= (uint64_t)k.dst_port + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= (uint64_t)k.proto + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);

    // Final avalanche
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

// ============================================================
// Flow state
// ============================================================

struct alignas(64) FlowEntry {
    std::atomic<uint64_t> state; // 0 = empty, 1 = occupied
    FlowKey key;

    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    uint64_t packets;
    uint64_t bytes;

    // Optional TCP flags, directionality, etc.
    uint32_t flags;

    FlowEntry() : state(0), key{}, first_seen_ns(0), last_seen_ns(0), packets(0), bytes(0), flags(0) {}
};

struct FlowSummary {
    FlowKey key;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    uint64_t packets;
    uint64_t bytes;
};

// ============================================================
// Flow table
// Open addressing with linear probing.
// Hot path: update existing or insert new.
// ============================================================

class FlowTable {
public:
    FlowTable() = default;

    void process_packet(const PacketView& pkt) noexcept {
        FlowKey key{
            pkt.src_ip,
            pkt.dst_ip,
            pkt.src_port,
            pkt.dst_port,
            static_cast<uint8_t>(pkt.proto)
        };

        const uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & FLOW_TABLE_MASK;

        for (size_t probe = 0; probe < FLOW_TABLE_SIZE; ++probe) {
            FlowEntry& e = table_[idx];

            uint64_t s = e.state.load(std::memory_order_acquire);

            if (s == 0) {
                // Try to claim empty slot
                uint64_t expected = 0;
                if (e.state.compare_exchange_strong(expected, 1, std::memory_order_acq_rel)) {
                    // We own it now
                    e.key = key;
                    e.first_seen_ns = pkt.timestamp_ns;
                    e.last_seen_ns = pkt.timestamp_ns;
                    e.packets = 1;
                    e.bytes = pkt.bytes;
                    e.flags = 0;
                    return;
                }
                // Lost race, retry same slot
            } else {
                // Check match
                if (e.key == key) {
                    // Single-writer assumption preferred for best performance.
                    // If multi-writer, replace with atomics or sharded ownership.
                    e.last_seen_ns = pkt.timestamp_ns;
                    ++e.packets;
                    e.bytes += pkt.bytes;
                    return;
                }
            }

            idx = (idx + 1) & FLOW_TABLE_MASK;
        }

        // Table full / pathological collision
        dropped_packets_.fetch_add(1, std::memory_order_relaxed);
    }

    std::vector<FlowSummary> expire_and_collect(uint64_t now_ns) {
        std::vector<FlowSummary> out;
        out.reserve(EXPORT_BATCH_SIZE);

        for (size_t i = 0; i < FLOW_TABLE_SIZE; ++i) {
            FlowEntry& e = table_[i];
            if (e.state.load(std::memory_order_acquire) == 1) {
                if (now_ns > e.last_seen_ns && (now_ns - e.last_seen_ns) > FLOW_IDLE_TIMEOUT_NS) {
                    FlowSummary s{
                        e.key,
                        e.first_seen_ns,
                        e.last_seen_ns,
                        e.packets,
                        e.bytes
                    };
                    out.push_back(s);

                    // Clear slot
                    e.packets = 0;
                    e.bytes = 0;
                    e.first_seen_ns = 0;
                    e.last_seen_ns = 0;
                    e.flags = 0;
                    e.state.store(0, std::memory_order_release);

                    if (out.size() >= EXPORT_BATCH_SIZE) {
                        break;
                    }
                }
            }
        }

        return out;
    }

    uint64_t dropped_packets() const noexcept {
        return dropped_packets_.load(std::memory_order_relaxed);
    }

private:
    std::array<FlowEntry, FLOW_TABLE_SIZE> table_{};
    std::atomic<uint64_t> dropped_packets_{0};
};

