// ============================================================
// Main loop skeleton
// ============================================================

int main() {
    FlowTable flow_table;

    // Simulated packet loop
    auto start = std::chrono::steady_clock::now();
    uint64_t start_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
        start.time_since_epoch()).count();

    for (uint64_t i = 0; i < 10'000'000; ++i) {
        uint8_t dummy[64] = {};
        auto now = std::chrono::steady_clock::now();
        uint64_t ts_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
            now.time_since_epoch()).count();

        auto pkt = parse_packet_stub(dummy, sizeof(dummy), ts_ns);
        if (pkt) {
            flow_table.process_packet(*pkt);
        }

        if ((i % 1'000'000) == 0) {
            auto expired = flow_table.expire_and_collect(ts_ns);
            std::cout << "Expired flows: " << expired.size()
                      << ", dropped: " << flow_table.dropped_packets() << "\n";
        }
    }

    auto end = std::chrono::steady_clock::now();
    uint64_t end_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
        end.time_since_epoch()).count();

    auto final_expired = flow_table.expire_and_collect(end_ns);
    std::cout << "Final expired: " << final_expired.size() << "\n";
    std::cout << "Done.\n";

    return 0;
}
