```cpp
// flow_analyzer.cpp
// C++20
#include <array>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <optional>
#include <span>
#include <thread>
#include <vector>
#include <chrono>
#include <algorithm>

#if defined(__GNUC__) || defined(__clang__)
#define ALWAYS_INLINE __attribute__((always_inline)) inline
#define LIKELY(x)   __builtin_expect(!!(x), 1)
#define UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define ALWAYS_INLINE inline
#define LIKELY(x)   (x)
#define UNLIKELY(x) (x)
#endif

// -----------------------------
// Packet header structures
// -----------------------------
#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct VlanHdr {
    uint16_t tci;
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct Ipv6Hdr {
    uint32_t ver_tc_fl;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src[16];
    uint8_t dst[16];
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static_assert(sizeof(EthHdr) == 14);
static_assert(sizeof(VlanHdr) == 4);

// -----------------------------
// Flow key / stats
// -----------------------------
struct FlowKey {
    uint8_t ip_version;   // 4 or 6
    uint8_t protocol;     // TCP/UDP/other
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4 or IPv6 address storage
    union {
        struct {
            uint32_t src;
            uint32_t dst;
        } v4;
        struct {
            std::array<uint8_t, 16> src;
            std::array<uint8_t, 16> dst;
        } v6;
    } ip;

    bool operator==(const FlowKey& other) const noexcept {
        if (ip_version != other.ip_version ||
            protocol != other.protocol ||
            src_port != other.src_port ||
            dst_port != other.dst_port) {
            return false;
        }
        if (ip_version == 4) {
            return ip.v4.src == other.ip.v4.src && ip.v4.dst == other.ip.v4.dst;
        }
        return ip.v6.src == other.ip.v6.src && ip.v6.dst == other.ip.v6.dst;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// -----------------------------
// Fast hash
// -----------------------------
static ALWAYS_INLINE uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static ALWAYS_INLINE uint64_t hash_bytes(const uint8_t* data, size_t len) noexcept {
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < len; ++i) {
        h ^= data[i];
        h *= 1099511628211ULL;
    }
    return mix64(h);
}

static ALWAYS_INLINE uint64_t flow_hash(const FlowKey& k) noexcept {
    uint64_t h = 0xcbf29ce484222325ULL;
    h ^= k.ip_version; h *= 0x100000001b3ULL;
    h ^= k.protocol;    h *= 0x100000001b3ULL;
    h ^= k.src_port;    h *= 0x100000001b3ULL;
    h ^= k.dst_port;    h *= 0x100000001b3ULL;

    if (k.ip_version == 4) {
        h ^= k.ip.v4.src; h *= 0x100000001b3ULL;
        h ^= k.ip.v4.dst; h *= 0x100000001b3ULL;
    } else {
        h ^= hash_bytes(k.ip.v6.src.data(), k.ip.v6.src.size());
        h ^= hash_bytes(k.ip.v6.dst.data(), k.ip.v6.dst.size());
    }
    return mix64(h);
}

// -----------------------------
// Fixed-size open addressing table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : cap_(1ULL << capacity_pow2), mask_(cap_ - 1), entries_(cap_) {}

    FlowStats* upsert(const FlowKey& key, uint64_t now_ns, uint64_t pkt_len) noexcept {
        const uint64_t h = flow_hash(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < cap_; ++probe) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.hash = h;
                e.key = key;
                e.stats.packets = 1;
                e.stats.bytes = pkt_len;
                e.stats.first_seen_ns = now_ns;
                e.stats.last_seen_ns = now_ns;
                return &e.stats;
            }
            if (e.hash == h && e.key == key) {
                e.stats.packets++;
                e.stats.bytes += pkt_len;
                e.stats.last_seen_ns = now_ns;
                return &e.stats;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void expire_inactive(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& e : entries_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_seen_ns > idle_timeout_ns) {
                fn(e.key, e.stats);
                e.occupied = false;
            }
        }
    }

private:
    size_t cap_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// -----------------------------
// Packet parsing
// -----------------------------
struct ParsedFlow {
    FlowKey key{};
    uint16_t packet_len = 0;
};

static ALWAYS_INLINE std::optional<ParsedFlow> parse_packet(std::span<const uint8_t> pkt) noexcept {
    if (pkt.size() < sizeof(EthHdr)) return std::nullopt;

    const auto* eth = reinterpret_cast<const EthHdr*>(pkt.data());
    uint16_t ethertype = __builtin_bswap16(eth->ethertype);
    size_t off = sizeof(EthHdr);

    // VLAN handling
    if (ethertype == 0x8100 || ethertype == 0x88A8) {
        if (pkt.size() < off + sizeof(VlanHdr)) return std::nullopt;
        const auto* vlan = reinterpret_cast<const VlanHdr*>(pkt.data() + off);
        ethertype = __builtin_bswap16(vlan->ethertype);
        off += sizeof(VlanHdr);
    }

    ParsedFlow out{};
    out.packet_len = static_cast<uint16_t>(pkt.size());

    if (ethertype == 0x0800) { // IPv4
        if (pkt.size() < off + sizeof(Ipv4Hdr)) return std::nullopt;
        const auto* ip = reinterpret_cast<const Ipv4Hdr*>(pkt.data() + off);
        const uint8_t ihl = ip->ver_ihl & 0x0F;
        const size_t ip_hlen = static_cast<size_t>(ihl) * 4;
        if (ihl < 5 || pkt.size() < off + ip_hlen) return std::nullopt;

        out.key.ip_version = 4;
        out.key.protocol = ip->protocol;
        out.key.ip.v4.src = ip->src;
        out.key.ip.v4.dst = ip->dst;

        off += ip_hlen;

        if (ip->protocol == 6) { // TCP
            if (pkt.size() < off + sizeof(TcpHdr)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(pkt.data() + off);
            out.key.src_port = tcp->src_port;
            out.key.dst_port = tcp->dst_port;
        } else if (ip->protocol == 17) { // UDP
            if (pkt.size() < off + sizeof(UdpHdr)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UdpHdr*>(pkt.data() + off);
            out.key.src_port = udp->src_port;
            out.key.dst_port = udp->dst_port;
        } else {
            out.key.src_port = 0;
            out.key.dst_port = 0;
        }
        return out;
    }

    if (ethertype == 0x86DD) { // IPv6
        if (pkt.size() < off + sizeof(Ipv6Hdr)) return std::nullopt;
        const auto* ip6 = reinterpret_cast<const Ipv6Hdr*>(pkt.data() + off);

        out.key.ip_version = 6;
        out.key.protocol = ip6->next_header;
        std::memcpy(out.key.ip.v6.src.data(), ip6->src, 16);
        std::memcpy(out.key.ip.v6.dst.data(), ip6->dst, 16);

        off += sizeof(Ipv6Hdr);

        if (ip6->next_header == 6) {
            if (pkt.size() < off + sizeof(TcpHdr)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(pkt.data() + off);
            out.key.src_port = tcp->src_port;
            out.key.dst_port = tcp->dst_port;
        } else if (ip6->next_header == 17) {
            if (pkt.size() < off + sizeof(UdpHdr)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UdpHdr*>(pkt.data() + off);
            out.key.src_port = udp->src_port;
            out.key.dst_port = udp->dst_port;
        } else {
            out.key.src_port = 0;
            out.key.dst_port = 0;
        }
        return out;
    }

    return std::nullopt;
}

// -----------------------------
// Sharded analyzer
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t shards_pow2, size_t table_pow2)
        : shard_mask_((1ULL << shards_pow2) - 1) {
        shards_.reserve(1ULL << shards_pow2);
        for (size_t i = 0; i < (1ULL << shards_pow2); ++i) {
            shards_.emplace_back(table_pow2);
        }
    }

    void process_packet(std::span<const uint8_t> pkt, uint64_t now_ns) noexcept {
        auto parsed = parse_packet(pkt);
        if (!parsed) return;

        const uint64_t h = flow_hash(parsed->key);
        FlowTable& t = shards_[static_cast<size_t>(h) & shard_mask_];
        (void)t.upsert(parsed->key, now_ns, parsed->packet_len);
    }

    template <typename Fn>
    void expire_all(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& shard : shards_) {
            shard.expire_inactive(now_ns, idle_timeout_ns, fn);
        }
    }

private:
    size_t shard_mask_;
    std::vector<FlowTable> shards_;
};

// -----------------------------
// Demo main
// -----------------------------
static uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()
    ).count();
}

int main() {
