#include <array>
#include <atomic>
#include <bit>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <memory>
#include <span>
#include <string_view>
#include <thread>
#include <vector>
#include <chrono>
#include <optional>

// =========================
// Utilities
// =========================

static inline uint64_t rdtsc_fallback() {
    return std::chrono::steady_clock::now().time_since_epoch().count();
}

static inline uint64_t mix64(uint64_t x) {
    // SplitMix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static inline uint16_t bswap16(uint16_t x) { return __builtin_bswap16(x); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) { return x; }
static inline uint32_t ntoh32(uint32_t x) { return x; }
#endif

// =========================
// Packet parsing structures
// =========================

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct VlanHdr {
    uint16_t tci;
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct Ipv6Hdr {
    uint32_t ver_tc_flow;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src[16];
    uint8_t dst[16];
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

enum class L4Proto : uint8_t { Other = 0, TCP = 6, UDP = 17 };

struct PacketView {
    const uint8_t* data = nullptr;
    size_t len = 0;

    // Parsed fields
    bool ipv6 = false;
    L4Proto l4 = L4Proto::Other;

    uint8_t ip_protocol = 0;
    uint32_t src_v4 = 0, dst_v4 = 0;
    std::array<uint8_t, 16> src_v6{}, dst_v6{};
    uint16_t src_port = 0, dst_port = 0;
    uint8_t ttl_or_hlim = 0;
    size_t l3_offset = 0;
    size_t l4_offset = 0;
};

// =========================
// Flow key
// =========================

struct FlowKey {
    bool ipv6 = false;
    L4Proto proto = L4Proto::Other;

    std::array<uint8_t, 16> a{};
    std::array<uint8_t, 16> b{};
    uint16_t port_a = 0;
    uint16_t port_b = 0;

    bool operator==(const FlowKey& other) const noexcept {
        return ipv6 == other.ipv6 &&
               proto == other.proto &&
               port_a == other.port_a &&
               port_b == other.port_b &&
               a == other.a &&
               b == other.b;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0xcbf29ce484222325ULL;
        auto fnv = [&](const uint8_t* p, size_t n) {
            for (size_t i = 0; i < n; ++i) {
                h ^= p[i];
                h *= 0x100000001b3ULL;
            }
        };
        fnv(reinterpret_cast<const uint8_t*>(&k.ipv6), sizeof(k.ipv6));
        fnv(reinterpret_cast<const uint8_t*>(&k.proto), sizeof(k.proto));
        fnv(k.a.data(), k.a.size());
        fnv(k.b.data(), k.b.size());
        fnv(reinterpret_cast<const uint8_t*>(&k.port_a), sizeof(k.port_a));
        fnv(reinterpret_cast<const uint8_t*>(&k.port_b), sizeof(k.port_b));
        return static_cast<size_t>(mix64(h));
    }
};

// Normalize direction so bidirectional traffic maps to same key
static inline FlowKey make_flow_key(const PacketView& p) {
    FlowKey k;
    k.ipv6 = p.ipv6;
    k.proto = p.l4;

    if (!p.ipv6) {
        uint32_t s = p.src_v4, d = p.dst_v4;
        uint16_t sp = p.src_port, dp = p.dst_port;
        if (s < d || (s == d && sp <= dp)) {
            std::memcpy(k.a.data(), &s, sizeof(s));
            std::memcpy(k.b.data(), &d, sizeof(d));
            k.port_a = sp; k.port_b = dp;
        } else {
            std::memcpy(k.a.data(), &d, sizeof(d));
            std::memcpy(k.b.data(), &s, sizeof(s));
            k.port_a = dp; k.port_b = sp;
        }
    } else {
        int cmp = std::memcmp(p.src_v6.data(), p.dst_v6.data(), 16);
        if (cmp < 0 || (cmp == 0 && p.src_port <= p.dst_port)) {
            k.a = p.src_v6; k.b = p.dst_v6;
            k.port_a = p.src_port; k.port_b = p.dst_port;
        } else {
            k.a = p.dst_v6; k.b = p.src_v6;
            k.port_a = p.dst_port; k.port_b = p.src_port;
        }
    }
    return k;
}

// =========================
// Flow record
// =========================

struct alignas(64) FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint8_t tcp_flags = 0;
    uint8_t ttl_min = 255;
    uint8_t ttl_max = 0;
    uint8_t _pad = 0;
};

// =========================
// Fixed-size open-addressing flow table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), slots_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) {
        size_t idx = FlowKeyHash{}(key) & mask_;
        for (size_t probe = 0; probe < slots_.size(); ++probe) {
            auto& s = slots_[(idx + probe) & mask_];
            if (!s.occupied) {
                s.occupied = true;
                s.rec.key = key;
                s.rec.first_seen_ns = now_ns;
                s.rec.last_seen_ns = now_ns;
                return &s.rec;
            }
            if (s.rec.key == key) {
                return &s.rec;
            }
        }
        // Simple fallback eviction: overwrite current slot
        auto& s = slots_[idx];
        s.occupied = true;
        s.rec = FlowRecord{};
        s.rec.key = key;
        s.rec.first_seen_ns = now_ns;
        s.rec.last_seen_ns = now_ns;
        return &s.rec;
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& s : slots_) {
            if (s.occupied) fn(s.rec);
        }
    }

private:
    struct Slot {
        bool occupied = false;
        FlowRecord rec{};
    };

    size_t mask_;
    std::vector<Slot> slots_;
};

// =========================
// Packet parser
// =========================

class PacketParser {
public:
    static std::optional<PacketView> parse(const uint8_t* data, size_t len) {
        if (len < sizeof(EthHdr)) return std::nullopt;

        PacketView p;
        p.data = data;
        p.len = len;

        const auto* eth = reinterpret_cast<const EthHdr*>(data);
        uint16_t ethertype = ntoh16(eth->ethertype);
        size_t off = sizeof(EthHdr);

        // VLAN stacking support
        while (ethertype == 0x8100 || ethertype == 0x88a8) {
            if (len < off + sizeof(VlanHdr)) return std::nullopt;
            const auto* vlan = reinterpret_cast<const VlanHdr*>(data + off);
            ethertype = ntoh16(vlan->ethertype);
            off += sizeof(VlanHdr);
        }

        p.l3_offset = off;

        if (ethertype == 0x0800) { // IPv4
            if (len < off + sizeof(Ipv4Hdr)) return std::nullopt;
            const auto* ip = reinterpret_cast<const Ipv4Hdr*>(data + off);
            uint8_t ihl = ip->ver_ihl & 0x0F;
            size_t ip_hlen = static_cast<size_t>(ihl) * 4;
            if (ihl < 5 || len < off + ip_hlen) return std::nullopt;

            p.ipv6 = false;
            p.ip_protocol = ip->protocol;
            p.src_v4 = ntoh32(ip->src);
            p.dst_v4 = ntoh32(ip->dst);
            p.ttl_or_hlim = ip->ttl;
            p.l4_offset = off + ip_hlen;

            if (ip->protocol == 6) p.l4 = L4Proto::TCP;
            else if (ip->protocol == 17) p.l4 = L4Proto::UDP;
            else p.l4 = L4Proto::Other;

        } else if (ethertype == 0x86DD) { // IPv6
            if (len < off + sizeof(Ipv6Hdr)) return std::nullopt;
            const auto* ip6 = reinterpret_cast<const Ipv6Hdr*>(data + off);

            p.ipv6 = true;
            p.ip_protocol = ip6->next_header;
            std::memcpy(p.src_v6.data(), ip6->src, 16);
            std::memcpy(p.dst_v6.data(), ip6->dst, 16);
            p.ttl_or_hlim = ip6->hop_limit;
            p.l4_offset = off + sizeof(Ipv6Hdr);

            if (ip6->next_header == 6) p.l4 = L4Proto::TCP;
            else if (ip6->next_header == 17) p.l4 = L4Proto::UDP;
            else p.l4 = L4Proto::Other;
        } else {
            return std::nullopt;
        }

        if (p.l4 == L4Proto::TCP) {
            if (len < p.l4_offset + sizeof(TcpHdr)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(data + p.l4_offset);
            p.src_port = ntoh16(tcp->src_port);
            p.dst_port = ntoh16(tcp->dst_port);
        } else if (p.l4 == L4Proto::UDP) {
            if (len < p.l4_offset + sizeof(UdpHdr)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UdpHdr*>(data + p.l4_offset);
            p.src_port = ntoh16(udp->src_port);
            p.dst_port = ntoh16(udp->dst_port);
        } else {
            return p; // non-TCP/UDP still parse L3
        }

        return p;
    }
};

// =========================
// Flow analyser
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2 = 1 << 20)
        : table_(table_pow2) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t now_ns) {
        auto parsed = PacketParser::parse(data, len);
        if (!parsed) return;

        const PacketView& p = *parsed;
        if (p.l4 != L4Proto::TCP && p.l4 != L4Proto::UDP) return;

        FlowKey key = make_flow_key(p);
        FlowRecord* rec = table_.find_or_insert(key, now_ns);
        if (!rec) return;

        rec->packets++;
        rec->bytes += len;
        rec->last_seen_ns = now_ns;
        rec->ttl_min = std::min(rec->ttl_min, p.ttl_or_hlim);
        rec->ttl_max = std::max(rec->ttl_max, p.ttl_or_hlim);
    }

    template <typename Fn>
    void for_each_flow(Fn&& fn) {
        table_.for_each(std::forward<Fn>(fn));
    }

private:
    FlowTable table_;
};

// =========================
// Example usage
// =========================

int main() {
    FlowAnalyzer analyzer(1 << 18); // 262k slots

    // Example packet buffer would come from NIC/pcap/AF_XDP/etc.
    std::vector<uint8_t> fake_packet(64, 0);

    // NOTE: This is just a placeholder; real traffic should be fed here.
    for (int i = 0; i < 1000; ++i) {
        analyzer.process_packet(fake_packet.data(), fake_packet.size(), rdtsc_fallback());
    }

    analyzer.for_each_flow([](const FlowRecord& r) {
        std::cout << "packets=" << r.packets
                  << " bytes=" << r.bytes
                  << " first=" << r.first_seen_ns
                  << " last=" << r.last_seen_ns
                  << "\n";
    });

    return 0;
}
