#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <thread>
#include <vector>
#include <optional>
#include <iostream>
#include <bit>
#include <algorithm>

// ==========================
// Utilities
// ==========================

static inline uint64_t rdtsc_fallback_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint64_t mix64(uint64_t x) {
    // SplitMix64 finalizer
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t bswap16(uint16_t x) {
    return __builtin_bswap16(x);
}

// ==========================
// Packet / Flow definitions
// ==========================

enum class L4Proto : uint8_t { TCP = 6, UDP = 17, OTHER = 255 };

struct PacketView {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    L4Proto proto;
    uint32_t bytes;
    uint64_t ts_ns;
    uint8_t tcp_flags; // if TCP
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t x = 0;
        x ^= (uint64_t)k.src_ip * 0x9e3779b185ebca87ULL;
        x ^= (uint64_t)k.dst_ip * 0xc2b2ae3d27d4eb4fULL;
        x ^= (uint64_t)k.src_port << 48;
        x ^= (uint64_t)k.dst_port << 32;
        x ^= (uint64_t)k.proto << 24;
        return (size_t)mix64(x);
    }
};

struct FlowEntry {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint8_t tcp_flags_or = 0;
    bool occupied = false;
};

// ==========================
// Bounded MPSC ring queue
// ==========================

template <typename T, size_t CapacityPow2>
class MPSCQueue {
    static_assert((CapacityPow2 & (CapacityPow2 - 1)) == 0, "Capacity must be power of two");

public:
    bool try_push(const T& item) {
        auto tail = tail_.fetch_add(1, std::memory_order_relaxed);
        auto head = head_.load(std::memory_order_acquire);
        if (tail - head >= CapacityPow2) {
            // queue full, rollback not trivial; in production use a better bounded MPSC design
            dropped_.fetch_add(1, std::memory_order_relaxed);
            return false;
        }
        buffer_[tail & (CapacityPow2 - 1)] = item;
        return true;
    }

    bool try_pop(T& out) {
        auto head = head_.load(std::memory_order_relaxed);
        if (head >= tail_.load(std::memory_order_acquire)) return false;
        out = buffer_[head & (CapacityPow2 - 1)];
        head_.store(head + 1, std::memory_order_release);
        return true;
    }

    uint64_t dropped() const { return dropped_.load(std::memory_order_relaxed); }

private:
    std::array<T, CapacityPow2> buffer_{};
    std::atomic<size_t> head_{0};
    std::atomic<size_t> tail_{0};
    std::atomic<uint64_t> dropped_{0};
};

// ==========================
// Flow table: open addressing
// ==========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), entries_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("FlowTable capacity must be power of 2");
        }
    }

    FlowEntry& get_or_create(const FlowKey& key, uint64_t now_ns) {
        size_t idx = FlowKeyHash{}(key) & mask_;
        for (;;) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.key = key;
                e.packets = 0;
                e.bytes = 0;
                e.first_seen_ns = now_ns;
                e.last_seen_ns = now_ns;
                e.tcp_flags_or = 0;
                e.occupied = true;
                return e;
            }
            if (e.key == key) {
                return e;
            }
            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& e : entries_) {
            if (e.occupied) fn(e);
        }
    }

    void expire_older_than(uint64_t cutoff_ns) {
        for (auto& e : entries_) {
            if (e.occupied && e.last_seen_ns < cutoff_ns) {
                e.occupied = false;
            }
        }
    }

private:
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// ==========================
// Packet parsing (IPv4 + TCP/UDP)
// ==========================

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urg_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline std::optional<PacketView> parse_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
    if (len < sizeof(EthHdr)) return std::nullopt;

    const EthHdr* eth = reinterpret_cast<const EthHdr*>(data);
    uint16_t ethertype = bswap16(eth->ethertype);
    if (ethertype != 0x0800) return std::nullopt; // IPv4 only

    size_t off = sizeof(EthHdr);
    if (len < off + sizeof(Ipv4Hdr)) return std::nullopt;

    const Ipv4Hdr* ip = reinterpret_cast<const Ipv4Hdr*>(data + off);
    uint8_t ihl = ip->ver_ihl & 0x0F;
    size_t ip_hlen = ihl * 4;
    if (ihl < 5 || len < off + ip_hlen) return std::nullopt;

    uint8_t proto = ip->protocol;
    uint32_t src_ip = bswap32(ip->src);
    uint32_t dst_ip = bswap32(ip->dst);

    off += ip_hlen;
    PacketView pv{};
    pv.src_ip = src_ip;
    pv.dst_ip = dst_ip;
    pv.ts_ns = ts_ns;
    pv.tcp_flags = 0;

    if (proto == 6) {
        if (len < off + sizeof(TcpHdr)) return std::nullopt;
        const TcpHdr* tcp = reinterpret_cast<const TcpHdr*>(data + off);
        pv.src_port = bswap16(tcp->src_port);
        pv.dst_port = bswap16(tcp->dst_port);
        pv.proto = L4Proto::TCP;
        pv.tcp_flags = tcp->flags;
    } else if (proto == 17) {
        if (len < off + sizeof(UdpHdr)) return std::nullopt;
        const UdpHdr* udp = reinterpret_cast<const UdpHdr*>(data + off);
        pv.src_port = bswap16(udp->src_port);
        pv.dst_port = bswap16(udp->dst_port);
        pv.proto = L4Proto::UDP;
    } else {
        return std::nullopt;
    }

    pv.bytes = static_cast<uint32_t>(len);
    return pv;
}

// ==========================
// Analyzer
// ==========================

class FlowAnalyzer {
public:
    FlowAnalyzer(size_t flow_capacity_pow2, size_t queue_capacity_pow2)
        : flows_(flow_capacity_pow2), queue_() {
        (void)queue_capacity_pow2;
    }

    bool ingest_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        auto parsed = parse_packet(data, len, ts_ns);
        if (!parsed) return false;
        return queue_.try_push(*parsed);
    }

    void run_once() {
        PacketView pv;
        while (queue_.try_pop(pv)) {
            FlowKey key{
                pv.src_ip, pv.dst_ip, pv.src_port, pv.dst_port, static_cast<uint8_t>(pv.proto)
            };
            FlowEntry& e = flows_.get_or_create(key, pv.ts_ns);
            e.packets++;
            e.bytes += pv.bytes;
            e.last_seen_ns = pv.ts_ns;
            e.tcp_flags_or |= pv.tcp_flags;
        }
    }

    void expire(uint64_t idle_timeout_ns) {
        uint64_t now = rdtsc_fallback_ns();
        flows_.expire_older_than(now - idle_timeout_ns);
    }

    void dump_top(std::ostream& os, size_t limit = 20) {
        struct Item { FlowEntry* e; };
        std::vector<FlowEntry*> all;
        flows_.for_each([&](FlowEntry& e) { all.push_back(&e); });

        std::sort(all.begin(), all.end(), [](const FlowEntry* a, const FlowEntry* b) {
            return a->bytes > b->bytes;
        });

        size_t n = std::min(limit, all.size());
        for (size_t i = 0; i < n; ++i) {
            const auto* e = all[i];
            os << "flow " << i
               << " packets=" << e->packets
               << " bytes=" << e->bytes
               << " proto=" << int(e->key.proto)
               << " src_port=" << e->key.src_port
               << " dst_port=" << e->key.dst_port
               << "\n";
        }
    }

    uint64_t dropped_packets() const { return queue_.dropped(); }

private:
    FlowTable flows_;
    MPSCQueue<PacketView, 1 << 20> queue_; // 1M entries
};

// ==========================
// Example main loop
// ==========================

int main() {
    FlowAnalyzer analyzer(1 << 20, 1 << 20);

    // In production, replace this with a capture loop from DPDK/AF_XDP/etc.
    // Here we just show the processing loop structure.
    while (true) {
        analyzer.run_once();

        // Periodic maintenance
        static uint64_t last_expire = 0;
        uint64_t now = rdtsc_fallback_ns();
        if (now - last_expire > 1'000'000'000ULL) { // 1s
            analyzer.expire(30'000'000'000ULL); // 30s idle timeout
            last_expire = now;
        }

        // Sleep a bit in this demo; remove in real hot path
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    return 0;
}
