// ==========================
// Fast packet/flow structures
// ==========================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

#pragma pack(push, 1)
struct IPv4Header {
