    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

struct PacketView {
    const uint8_t* data;
    size_t len;
    uint64_t ts_ns;
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3]; // align to 16 bytes

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    std::atomic<uint8_t> state{0}; // 0=empty, 1=occupied, 2=tombstone
};

// ==========================
// Hashing
// ==========================

static inline uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t a = (uint64_t(k.src_ip) << 32) ^ k.dst_ip;
    uint64_t b = (uint64_t(k.src_port) << 48) ^ (uint64_t(k.dst_port) << 32) ^ k.proto;
    return mix64(a ^ mix64(b));
}

// ==========================
// Flow table: open addressing
// ==========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          entries_(capacity_) {
        if ((capacity_ & (capacity_ - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowEntry* find_or_insert(const FlowKey& key) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;
        size_t first_tombstone = capacity_;

        for (;;) {
            FlowEntry& e = entries_[idx];
            uint8_t s = e.state.load(std::memory_order_relaxed);

            if (s == 0) {
                size_t target = (first_tombstone != capacity_) ? first_tombstone : idx;
                FlowEntry& slot = entries_[target];
                slot.key = key;
                slot.stats = {};
                slot.state.store(1, std::memory_order_relaxed);
                return &slot;
            }

            if (s == 1 && e.key == key) {
                return &e;
            }

            if (s == 2 && first_tombstone == capacity_) {
                first_tombstone = idx;
            }

            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& e : entries_) {
            if (e.state.load(std::memory_order_relaxed) == 1) {
                fn(e);
            }
        }
    }

    void erase_expired(uint64_t now_ns, uint64_t idle_timeout_ns) {
        for (auto& e : entries_) {
            if (e.state.load(std::memory_order_relaxed) == 1) {
                if (now_ns - e.stats.last_ts_ns > idle_timeout_ns) {
                    e.state.store(2, std::memory_order_relaxed); // tombstone
                }
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// ==========================
// Packet parsing helpers
// ==========================

static inline uint16_t ntoh16(uint16_t x) noexcept {
    if constexpr (std::endian::native == std::endian::little) {
        return __builtin_bswap16(x);
    } else {
        return x;
    }
}

static inline uint32_t ntoh32(uint32_t x) noexcept {
    if constexpr (std::endian::native == std::endian::little) {
        return __builtin_bswap32(x);
    } else {
        return x;
    }
}

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

static inline ParsedPacket parse_ipv4_packet(const PacketView& p) noexcept {
    ParsedPacket out{};
    if (p.len < sizeof(IPv4Header)) return out;

    const auto* ip = reinterpret_cast<const IPv4Header*>(p.data);
    const uint8_t version = ip->ver_ihl >> 4;
    const uint8_t ihl = ip->ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) return out;

    const size_t ip_hdr_len = size_t(ihl) * 4;
    if (p.len < ip_hdr_len) return out;

    uint8_t proto = ip->protocol;
    size_t l4_off = ip_hdr_len;

    FlowKey key{};
    key.src_ip = ntoh32(ip->src);
    key.dst_ip = ntoh32(ip->dst);
    key.proto = proto;

    if (proto == static_cast<uint8_t>(L4Proto::TCP)) {
        if (p.len < l4_off + sizeof(TCPHeader)) return out;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(p.data + l4_off);
        key.src_port = ntoh16(tcp->src_port);
        key.dst_port = ntoh16(tcp->dst_port);
        uint8_t doff = tcp->data_offset_reserved >> 4;
        if (doff < 5) return out;
        size_t tcp_hdr_len = size_t(doff) * 4;
        if (p.len < l4_off + tcp_hdr_len) return out;
        out.payload_len = static_cast<uint32_t>(p.len - (l4_off + tcp_hdr_len));
    } else if (proto == static_cast<uint8_t>(L4Proto::UDP)) {
        if (p.len < l4_off + sizeof(UDPHeader)) return out;
        const auto* udp = reinterpret_cast<const UDPHeader*>(p.data + l4_off);
        key.src_port = ntoh16(udp->src_port);
        key.dst_port = ntoh16(udp->dst_port);
        out.payload_len = static_cast<uint32_t>(p.len - (l4_off + sizeof(UDPHeader)));
    } else {
        key.src_port = 0;
        key.dst_port = 0;
        out.payload_len = static_cast<uint32_t>(p.len - l4_off);
    }

    out.key = key;
    out.valid = true;
    return out;
}

// ==========================
// Analyzer
// ==========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2 = 20, uint64_t idle_timeout_ns = 60ULL * 1'000'000'000ULL)
        : table_(table_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const PacketView& pkt) noexcept {
        ParsedPacket parsed = parse_ipv4_packet(pkt);
        if (!parsed.valid) return;

        FlowEntry* e = table_.find_or_insert(parsed.key);
        if (e->stats.packets == 0) {
            e->stats.first_ts_ns = pkt.ts_ns;
        }
        e->stats.packets++;
        e->stats.bytes += pkt.len;
        e->stats.last_ts_ns = pkt.ts_ns;
    }

    void age(uint64_t now_ns) {
        table_.erase_expired(now_ns, idle_timeout_ns_);
    }

    template <typename Fn>
    void export_flows(Fn&& fn) {
        table_.for_each([&](FlowEntry& e) {
            fn(e.key, e.stats);
        });
    }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
};

// ==========================
// Example usage
// ==========================

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

int main() {
    FlowAnalyzer analyzer(20); // ~1M slots

    // Example packet buffer would come from capture engine
    std::array<uint8_t, 64> fake_pkt{};
    // Populate fake IPv4/TCP packet minimally for demo
    auto* ip = reinterpret_cast<IPv4Header*>(fake_pkt.data());
    ip->ver_ihl = (4 << 4) | 5;
    ip->protocol = static_cast<uint8_t>(L4Proto::TCP);
    ip->src = __builtin_bswap32(0x0A000001); // 10.0.0.1
    ip->dst = __builtin_bswap32(0x0A000002); // 10.0.0.2

    auto* tcp = reinterpret_cast<TCPHeader*>(fake_pkt.data() + sizeof(IPv4Header));
    tcp->src_port = __builtin_bswap16(12345);
    tcp->dst_port = __builtin_bswap16(443);
    tcp->data_offset_reserved = (5 << 4);

    PacketView pkt{fake_pkt.data(), fake_pkt.size(), now_ns()};
