```go
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"sync"
	"sync/atomic"
	"time"
)

const (
	NumShards      = 256
	FlowIdleTimeout = 30 * time.Second
	SweepInterval   = 5 * time.Second
	MaxPacketSize   = 2048
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	IPVer   uint8
	_       [2]byte // padding for alignment
}

type FlowStats struct {
	Packets   uint64
	Bytes     uint64
	FirstSeen int64
	LastSeen  int64
}

type FlowEntry struct {
	Key   FlowKey
	Stats FlowStats
}

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*FlowEntry
}

type FlowTable struct {
	shards [NumShards]shard
}

func NewFlowTable() *FlowTable {
	ft := &FlowTable{}
	for i := 0; i < NumShards; i++ {
		ft.shards[i].flows = make(map[FlowKey]*FlowEntry, 1024)
	}
	return ft
}

func (ft *FlowTable) getShard(key FlowKey) *shard {
	h := flowHash(key)
	return &ft.shards[h%NumShards]
}

func flowHash(k FlowKey) uint64 {
	// Fast-ish FNV-1a style hash
	var h uint64 = 1469598103934665603
	mix := func(b byte) {
		h ^= uint64(b)
		h *= 1099511628211
	}

	for _, b := range k.SrcIP {
		mix(b)
	}
	for _, b := range k.DstIP {
		mix(b)
	}
	mix(byte(k.SrcPort))
	mix(byte(k.SrcPort >> 8))
	mix(byte(k.DstPort))
	mix(byte(k.DstPort >> 8))
	mix(k.Proto)
	mix(k.IPVer)
	return h
}

func (ft *FlowTable) Update(key FlowKey, pktLen int, ts time.Time) {
	sh := ft.getShard(key)
	now := ts.UnixNano()

	sh.mu.Lock()
	defer sh.mu.Unlock()

	entry, ok := sh.flows[key]
	if !ok {
		entry = &FlowEntry{
			Key: key,
			Stats: FlowStats{
				Packets:   1,
				Bytes:     uint64(pktLen),
				FirstSeen: now,
				LastSeen:  now,
			},
		}
		sh.flows[key] = entry
		return
	}

	entry.Stats.Packets++
	entry.Stats.Bytes += uint64(pktLen)
	entry.Stats.LastSeen = now
}

func (ft *FlowTable) Sweep(expireBefore time.Time, emit func(FlowEntry)) {
	cutoff := expireBefore.UnixNano()

	for i := 0; i < NumShards; i++ {
		sh := &ft.shards[i]

		sh.mu.Lock()
		for k, entry := range sh.flows {
			if entry.Stats.LastSeen < cutoff {
				emit(*entry)
				delete(sh.flows, k)
			}
		}
		sh.mu.Unlock()
	}
}

type Packet struct {
	Data []byte
	Len  int
	TS   time.Time
}

type Parser struct{}

func (p *Parser) Parse(pkt []byte) (FlowKey, bool) {
	if len(pkt) < 14 {
		return FlowKey{}, false
	}

	ethType := binary.BigEndian.Uint16(pkt[12:14])
	offset := 14

	// VLAN tag support
	if ethType == 0x8100 || ethType == 0x88a8 {
		if len(pkt) < 18 {
			return FlowKey{}, false
		}
		ethType = binary.BigEndian.Uint16(pkt[16:18])
		offset = 18
	}

	var key FlowKey

	switch ethType {
	case 0x0800: // IPv4
		if len(pkt) < offset+20 {
			return FlowKey{}, false
		}
		ihl := int(pkt[offset]&0x0F) * 4
		if len(pkt) < offset+ihl {
			return FlowKey{}, false
		}
		key.IPVer = 4
		key.Proto = pkt[offset+9]
		copy(key.SrcIP[:4], pkt[offset+12:offset+16])
		copy(key.DstIP[:4], pkt[offset+16:offset+20])

		l4 := offset + ihl
		if key.Proto == 6 || key.Proto == 17 || key.Proto == 132 { // TCP/UDP/SCTP
			if len(pkt) < l4+4 {
				return FlowKey{}, false
			}
			key.SrcPort = binary.BigEndian.Uint16(pkt[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(pkt[l4+2 : l4+4])
		}
		return key, true

	case 0x86DD: // IPv6
		if len(pkt) < offset+40 {
			return FlowKey{}, false
		}
		key.IPVer = 6
		nextHeader := pkt[offset+6]
		key.Proto = nextHeader
		copy(key.SrcIP[:16], pkt[offset+8:offset+24])
		copy(key.DstIP[:16], pkt[offset+24:offset+40])

		l4 := offset + 40
		if key.Proto == 6 || key.Proto == 17 || key.Proto == 132 {
			if len(pkt) < l4+4 {
				return FlowKey{}, false
			}
			key.SrcPort = binary.BigEndian.Uint16(pkt[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(pkt[l4+2 : l4+4])
		}
		return key, true
	default:
		return FlowKey{}, false
	}
}

type Analyzer struct {
	table   *FlowTable
	parser  *Parser
	ingest  chan Packet
	closed  chan struct{}
	wg      sync.WaitGroup
	exports chan FlowEntry
}

func NewAnalyzer(workerCount int) *Analyzer {
	a := &Analyzer{
		table:   NewFlowTable(),
		parser:  &Parser{},
		ingest:  make(chan Packet, 8192),
		closed:  make(chan struct{}),
		exports: make(chan FlowEntry, 8192),
	}

	for i := 0; i < workerCount; i++ {
		a.wg.Add(1)
		go func() {
			defer a.wg.Done()
			for pkt := range a.ingest {
				key, ok := a.parser.Parse(pkt.Data)
				if !ok {
					continue
				}
				a.table.Update(key, pkt.Len, pkt.TS)
			}
		}()
	}

	a.wg.Add(1)
	go func() {
		defer a.wg.Done()
		ticker := time.NewTicker(SweepInterval)
		defer ticker.Stop()

		for {
			select {
			case <-ticker.C:
				a.table.Sweep(time.Now().Add(-FlowIdleTimeout), func(fe FlowEntry) {
					select {
					case a.exports <- fe:
					default:
						// drop if exporter is congested
					}
				})
			case <-a.closed:
				return
			}
		}
	}()

	return a
}

func (a *Analyzer) Submit(pkt Packet) {
	a.ingest <- pkt
}

func (a *Analyzer) Close() {
	close(a.closed)
	close(a.ingest)
	a.wg.Wait()
	close(a.exports)
}

func main() {
	workerCount := 4
	if len(os.Args) > 1 {
		// simplistic override
		workerCount = 8
	}

	analyzer := NewAnalyzer(workerCount)

	// Example packet injection loop with synthetic data
	go func() {
		defer analyzer.Close()
		for i := 0; i < 100000; i++ {
			pkt := Packet{
				Data: buildSyntheticIPv4TCPPacket(),
				Len:  74,
				TS:   time.Now(),
			}
			analyzer.Submit(pkt)
		}
	}()

	for flow := range analyzer.exports {
		fmt.Printf("flow: %+v\n", flow)
	}
}

func buildSyntheticIPv4TCPPacket() []byte {
	pkt := make([]byte, 74)

	// Ethernet
	pkt[12] = 0x08
	pkt[13] = 0x00

	// IPv4 header
	pkt[14] = 0x45
	pkt[23] = 6 // TCP
	copy(pkt[26:30], net.IPv4(10, 0, 0, 1).To4())
	copy(pkt[30:34], net.IPv4(10, 0, 0, 2).To4())

	// TCP
	binary.BigEndian.PutUint16(pkt[34:36], 12345)
	binary.BigEndian.PutUint16(pkt[36:38], 80)

	return pkt
}
