package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
	"github.com/google/gopacket/pcap"
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	_       [5]byte // padding for alignment
}

type FlowStats struct {
	Packets    uint64    `json:"packets"`
	Bytes      uint64    `json:"bytes"`
	FirstSeen  int64     `json:"first_seen_unix_nano"`
	LastSeen   int64     `json:"last_seen_unix_nano"`
	TCPFlags   uint8     `json:"tcp_flags"`
	Direction  uint8     `json:"direction"`
	_          [6]byte   // padding
}

type FlowEntry struct {
	Key   FlowKey
	Stats FlowStats
}

type Shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*FlowStats
}

type Analyzer struct {
	shards     []Shard
	shardMask  uint32
	exportCh    chan FlowEntry
	stopCh     chan struct{}
	wg         sync.WaitGroup
	flushEvery  time.Duration
	ttl         time.Duration
}

func NewAnalyzer(numShards int, flushEvery, ttl time.Duration) *Analyzer {
	// Ensure power of two for fast masking
	n := 1
	for n < numShards {
		n <<= 1
	}
	shards := make([]Shard, n)
	for i := range shards {
		shards[i].flows = make(map[FlowKey]*FlowStats, 1<<16)
	}
	return &Analyzer{
		shards:    shards,
		shardMask: uint32(n - 1),
		exportCh:  make(chan FlowEntry, 1<<14),
		stopCh:    make(chan struct{}),
		flushEvery: flushEvery,
		ttl:        ttl,
	}
}

func (a *Analyzer) shardFor(key FlowKey) *Shard {
	h := fnv1a64(key)
	return &a.shards[uint32(h)&a.shardMask]
}

func fnv1a64(k FlowKey) uint64 {
	const (
		offset64 = 1469598103934665603
		prime64  = 1099511628211
	)
	h := uint64(offset64)
	b := (*[32]byte)(unsafePointer(&k))
	for i := 0; i < 32; i++ {
		h ^= uint64(b[i])
		h *= prime64
	}
	return h
}

// unsafePointer avoids reflection/allocations for hashing.
// Keep isolated to minimize risk.
func unsafePointer(v interface{}) unsafe.Pointer {
	return *(*unsafe.Pointer)(unsafe.Pointer(&v))
}

func (a *Analyzer) Update(key FlowKey, packetLen int, tcpFlags uint8, now time.Time) {
	s := a.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()

	stats, ok := s.flows[key]
	if !ok {
		stats = &FlowStats{
			Packets:   0,
			Bytes:     0,
			FirstSeen: now.UnixNano(),
			LastSeen:  now.UnixNano(),
			TCPFlags:  tcpFlags,
		}
		s.flows[key] = stats
	}
	stats.Packets++
	stats.Bytes += uint64(packetLen)
	stats.LastSeen = now.UnixNano()
	stats.TCPFlags |= tcpFlags
}

func (a *Analyzer) StartExporter() {
	a.wg.Add(1)
	go func() {
		defer a.wg.Done()
		ticker := time.NewTicker(a.flushEvery)
		defer ticker.Stop()

		for {
			select {
			case <-ticker.C:
				a.flushExpired()
			case <-a.stopCh:
				a.flushAll()
				return
			}
		}
	}()
}

func (a *Analyzer) flushExpired() {
	now := time.Now().UnixNano()
	expireBefore := now - a.ttl.Nanoseconds()

	for i := range a.shards {
		s := &a.shards[i]
		s.mu.Lock()
		for k, v := range s.flows {
			if v.LastSeen < expireBefore {
				select {
				case a.exportCh <- FlowEntry{Key: k, Stats: *v}:
				default:
					// Drop on backpressure to preserve capture path
				}
				delete(s.flows, k)
			}
		}
		s.mu.Unlock()
	}
}

func (a *Analyzer) flushAll() {
	for i := range a.shards {
		s := &a.shards[i]
		s.mu.Lock()
		for k, v := range s.flows {
			select {
			case a.exportCh <- FlowEntry{Key: k, Stats: *v}:
			default:
			}
			delete(s.flows, k)
		}
		s.mu.Unlock()
	}
}

func (a *Analyzer) Stop() {
	close(a.stopCh)
	a.wg.Wait()
	close(a.exportCh)
}

func (a *Analyzer) ExportLoop() {
	a.wg.Add(1)
	go func() {
		defer a.wg.Done()
		enc := json.NewEncoder(os.Stdout)
		for entry := range a.exportCh {
			_ = enc.Encode(entry)
		}
	}()
}

func buildFlowKey(netFlow gopacket.Flow, transportFlow gopacket.Flow, proto uint8) FlowKey {
	var key FlowKey

	srcIP := netFlow.Src().Raw()
	dstIP := netFlow.Dst().Raw()
	copy(key.SrcIP[:], srcIP)
	copy(key.DstIP[:], dstIP)

	if transportFlow != gopacket.Flow{} {
		if sp, err := parsePort(transportFlow.Src().String()); err == nil {
			key.SrcPort = sp
		}
		if dp, err := parsePort(transportFlow.Dst().String()); err == nil {
			key.DstPort = dp
		}
	}

	key.Proto = proto
	return key
}

func parsePort(s string) (uint16, error) {
	var p int
	_, err := fmt.Sscanf(s, "%d", &p)
	if err != nil {
		return 0, err
	}
	if p < 0 || p > 65535 {
		return 0, fmt.Errorf("invalid port")
	}
	return uint16(p), nil
}

func handlePacket(an *Analyzer, packet gopacket.Packet) {
	now := time.Now()

	ipLayer := packet.Layer(layers.LayerTypeIPv4)
	var proto uint8
	var netFlow gopacket.Flow
	var transportFlow gopacket.Flow

	if ipLayer != nil {
		ip4 := ipLayer.(*layers.IPv4)
		proto = uint8(ip4.Protocol)
		netFlow = ip4.NetworkFlow()
	} else if ipv6Layer := packet.Layer(layers.LayerTypeIPv6); ipv6Layer != nil {
		ip6 := ipv6Layer.(*layers.IPv6)
		proto = uint8(ip6.NextHeader)
		netFlow = ip6.NetworkFlow()
	} else {
		return
	}

	if tcpLayer := packet.Layer(layers.LayerTypeTCP); tcpLayer != nil {
		tcp := tcpLayer.(*layers.TCP)
		transportFlow = tcp.TransportFlow()
		an.Update(buildFlowKey(netFlow, transportFlow, proto), len(packet.Data()), uint8(tcp.Flags), now)
		return
	}

	if udpLayer := packet.Layer(layers.LayerTypeUDP); udpLayer != nil {
		udp := udpLayer.(*layers.UDP)
		transportFlow = udp.TransportFlow()
		an.Update(buildFlowKey(netFlow, transportFlow, proto), len(packet.Data()), 0, now)
		return
	}

	an.Update(buildFlowKey(netFlow, gopacket.Flow{}, proto), len(packet.Data()), 0, now)
}

func main() {
	var (
		iface    = flag.String("i", "eth0", "interface to capture on")
		snaplen  = flag.Int("snaplen", 65535, "pcap snaplen")
		promisc  = flag.Bool("promisc", true, "promiscuous mode")
		workers  = flag.Int("workers", 4, "number of packet workers")
		shards   = flag.Int("shards", 64, "number of flow shards")
		flushDur = flag.Duration("flush", 5*time.Second, "flush interval")
		ttl      = flag.Duration("ttl", 30*time.Second, "flow TTL")
		filter   = flag.String("filter", "ip", "BPF filter")
	)
	flag.Parse()

	handle, err := pcap.OpenLive(*iface, int32(*snaplen), *promisc, pcap.BlockForever)
	if err != nil {
		log.Fatalf("pcap open: %v", err)
	}
	defer handle.Close()

	if err := handle.SetBPFFilter(*filter); err != nil {
		log.Fatalf("bpf filter: %v", err)
	}

	an := NewAnalyzer(*shards, *flushDur, *ttl)
	an.StartExporter()
	an.ExportLoop()

	packetSource := gopacket.NewPacketSource(handle, handle.LinkType())
	packets := packetSource.Packets()

	var wg sync.WaitGroup
	packetCh := make(chan gopacket.Packet, 1<<14)

	for i := 0; i < *workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for pkt := range packetCh {
				handlePacket(an, pkt)
			}
		}()
	}

	go func() {
		for pkt := range packets {
			packetCh <- pkt
		}
		close(packetCh)
	}()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	an.Stop()
	wg.Wait()
}
