use anyhow::Result;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use log::{info, warn};
use parking_lot::Mutex;
use std::collections::VecDeque;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum FlowKey {
    V4 {
        src: Ipv4Addr,
        dst: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
    V6 {
        src: Ipv6Addr,
        dst: Ipv6Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u64,
    tcp_fin: u64,
    tcp_rst: u64,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, len: usize, now: Instant, tcp_flags: Option<u16>) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = now;

        if let Some(flags) = tcp_flags {
            if flags & 0x02 != 0 {
                self.tcp_syn += 1;
            }
            if flags & 0x01 != 0 {
                self.tcp_fin += 1;
            }
            if flags & 0x04 != 0 {
                self.tcp_rst += 1;
            }
        }
    }
}

struct FlowTable {
    flows: DashMap<FlowKey, FlowStats>,
    inactive_timeout: Duration,
}

impl FlowTable {
    fn new(inactive_timeout: Duration) -> Self {
        Self {
            flows: DashMap::new(),
            inactive_timeout,
        }
    }

    fn process_packet(&self, packet: &[u8], now: Instant) {
        let sliced = match SlicedPacket::from_ethernet(packet) {
            Ok(s) => s,
            Err(_) => return,
        };

        let (src_ip, dst_ip, proto) = match sliced.ip {
            Some(InternetSlice::Ipv4(header, _)) => (
                IpAddr::V4(Ipv4Addr::from(header.source())),
                IpAddr::V4(Ipv4Addr::from(header.destination())),
                header.protocol(),
            ),
            Some(InternetSlice::Ipv6(header, _)) => (
                IpAddr::V6(Ipv6Addr::from(header.source())),
                IpAddr::V6(Ipv6Addr::from(header.destination())),
                header.next_header(),
            ),
            _ => return,
        };

        let (src_port, dst_port, tcp_flags) = match sliced.transport {
            Some(TransportSlice::Tcp(tcp)) => (
                tcp.source_port(),
                tcp.destination_port(),
                Some(tcp.flags()),
            ),
            Some(TransportSlice::Udp(udp)) => (
                udp.source_port(),
                udp.destination_port(),
                None,
            ),
            _ => return,
        };

        let key = match (src_ip, dst_ip) {
            (IpAddr::V4(src), IpAddr::V4(dst)) => FlowKey::V4 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            },
            (IpAddr::V6(src), IpAddr::V6(dst)) => FlowKey::V6 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            },
            _ => return,
        };

        let mut entry = self.flows.entry(key).or_insert_with(|| FlowStats::new(now));
        entry.update(packet.len(), now, tcp_flags);
    }

    fn evict_inactive(&self) -> Vec<(FlowKey, FlowStats)> {
        let cutoff = Instant::now() - self.inactive_timeout;
        let mut expired = Vec::new();

        let keys: Vec<FlowKey> = self
            .flows
            .iter()
            .filter_map(|entry| {
                if entry.value().last_seen < cutoff {
                    Some(*entry.key())
                } else {
                    None
                }
            })
            .collect();

        for key in keys {
            if let Some((k, v)) = self.flows.remove(&key) {
                expired.push((k, v));
            }
        }

        expired
    }

    fn len(&self) -> usize {
        self.flows.len()
    }
}

#[derive(Debug)]
struct PacketBatch {
    packets: Vec<Vec<u8>>,
}

impl PacketBatch {
    fn new() -> Self {
        Self { packets: Vec::new() }
    }
}

fn analyzer_worker(rx: Receiver<PacketBatch>, table: Arc<FlowTable>) {
    while let Ok(batch) = rx.recv() {
        let now = Instant::now();
        for packet in batch.packets {
            table.process_packet(&packet, now);
        }
    }
}

fn eviction_worker(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(5));
        let expired = table.evict_inactive();
        if !expired.is_empty() {
            info!("Evicted {} inactive flows", expired.len());
        }
    }
}

fn synthetic_packet_ipv4_tcp() -> Vec<u8> {
    // Placeholder synthetic packet bytes; in production this would come from AF_PACKET,
    // DPDK, pcap, or an equivalent capture path.
    vec![
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, // dst MAC
        0x00, 0x11, 0x22, 0x33, 0x44, 0x55, // src MAC
        0x08, 0x00, // ethertype IPv4
        // IPv4 header + TCP payload omitted for brevity
    ]
}

fn packet_producer(tx: Sender<PacketBatch>) {
    loop {
        let mut batch = PacketBatch::new();
        for _ in 0..1024 {
            batch.packets.push(synthetic_packet_ipv4_tcp());
        }

        if tx.send(batch).is_err() {
            break;
        }
    }
}

fn main() -> Result<()> {
    env_logger::init();

    let table = Arc::new(FlowTable::new(Duration::from_secs(60)));
    let (tx, rx) = bounded::<PacketBatch>(64);

    {
        let table = Arc::clone(&table);
        thread::spawn(move || analyzer_worker(rx, table));
    }

    {
        let table = Arc::clone(&table);
        thread::spawn(move || eviction_worker(table));
    }

    {
        let tx = tx.clone();
        thread::spawn(move || packet_producer(tx));
    }

    info!("Flow analyser started");

    loop {
        thread::sleep(Duration::from_secs(10));
        info!("Active flows: {}", table.len());
    }
}
