use anyhow::Result;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, len: usize) -> Self {
        Self {
            packets: 1,
            bytes: len as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, len: usize) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct CompletedFlow {
    key: FlowKey,
    stats: FlowStats,
}

struct FlowTable {
    map: DashMap<FlowKey, FlowStats>,
    tx: Sender<CompletedFlow>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(tx: Sender<CompletedFlow>, idle_timeout: Duration) -> Self {
        Self {
            map: DashMap::new(),
            tx,
            idle_timeout,
        }
    }

    fn update_flow(&self, key: FlowKey, packet_len: usize) {
        let now = Instant::now();
        use dashmap::mapref::entry::Entry;

        match self.map.entry(key) {
            Entry::Occupied(mut entry) => {
                entry.get_mut().update(now, packet_len);
            }
            Entry::Vacant(entry) => {
                entry.insert(FlowStats::new(now, packet_len));
            }
        }
    }

    fn expire_stale(&self) {
        let now = Instant::now();
        let timeout = self.idle_timeout;

        let mut expired = Vec::new();

        for item in self.map.iter() {
            let key = *item.key();
            let stats = item.value().clone();

            if now.duration_since(stats.last_seen) >= timeout {
                expired.push((key, stats));
            }
        }

        for (key, stats) in expired {
            if self.map.remove(&key).is_some() {
                let _ = self.tx.send(CompletedFlow { key, stats });
            }
        }
    }
}

fn parse_flow_key(packet: &[u8]) -> Option<(FlowKey, usize)> {
    let sliced = SlicedPacket::from_ethernet(packet).ok()?;

    let (src_ip, dst_ip) = match sliced.ip? {
        InternetSlice::Ipv4(header, _) => {
            let src = Ipv4Addr::from(header.source());
            let dst = Ipv4Addr::from(header.destination());
            (src, dst)
        }
        _ => return None,
    };

    let (src_port, dst_port, proto) = match sliced.transport? {
        TransportSlice::Tcp(tcp) => (tcp.source_port(), tcp.destination_port(), 6),
        TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port(), 17),
        _ => return None,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Some((key, packet.len()))
}

fn export_loop(rx: Receiver<CompletedFlow>) {
    while let Ok(flow) = rx.recv() {
        println!(
            "FLOW {:?} packets={} bytes={} duration_ms={}",
            flow.key,
            flow.stats.packets,
            flow.stats.bytes,
            flow.stats
                .last_seen
                .duration_since(flow.stats.first_seen)
                .as_millis()
        );
    }
}

fn main() -> Result<()> {
    let device = Device::lookup()?;
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .snaplen(65535)
        .timeout(10)
        .open()?;

    let (tx, rx) = bounded::<CompletedFlow>(100_000);
    let flow_table = Arc::new(FlowTable::new(tx, Duration::from_secs(30)));

    let exporter_handle = {
        thread::spawn(move || export_loop(rx))
    };

    let expirer_table = Arc::clone(&flow_table);
    let expirer_handle = thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(5));
        expirer_table.expire_stale();
    });

    println!("Starting capture...");

    while let Ok(packet) = cap.next_packet() {
        if let Some((key, len)) = parse_flow_key(packet.data) {
            flow_table.update_flow(key, len);
        }
    }

    let _ = exporter_handle.join();
    let _ = expirer_handle.join();

    Ok(())
}
```

