use std::{
    hash::{Hash, Hasher},
    net::{Ipv4Addr, Ipv6Addr},
    sync::Arc,
    thread,
    time::{Duration, Instant},
};

use bytes::Bytes;
use clap::Parser;
use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use parking_lot::Mutex;

#[derive(Parser, Debug)]
struct Args {
    /// Number of worker threads
    #[arg(long, default_value_t = 1)]
    workers: usize,

    /// Flow idle timeout in seconds
    #[arg(long, default_value_t = 60)]
    idle_timeout_secs: u64,

    /// Channel capacity for packet buffering
    #[arg(long, default_value_t = 8192)]
    channel_capacity: usize,
}

#[derive(Clone, Copy, Debug, Eq)]
enum IpAddrKind {
    V4(u32),
    V6([u8; 16]),
}

impl PartialEq for IpAddrKind {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (IpAddrKind::V4(a), IpAddrKind::V4(b)) => a == b,
            (IpAddrKind::V6(a), IpAddrKind::V6(b)) => a == b,
            _ => false,
        }
    }
}

impl Hash for IpAddrKind {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            IpAddrKind::V4(v) => {
                4u8.hash(state);
                v.hash(state);
            }
            IpAddrKind::V6(v) => {
                6u8.hash(state);
                v.hash(state);
            }
        }
    }
}

impl From<Ipv4Addr> for IpAddrKind {
    fn from(ip: Ipv4Addr) -> Self {
        IpAddrKind::V4(u32::from(ip))
    }
}

impl From<Ipv6Addr> for IpAddrKind {
    fn from(ip: Ipv6Addr) -> Self {
        IpAddrKind::V6(ip.octets())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: IpAddrKind,
    dst_ip: IpAddrKind,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct Packet {
    data: Bytes,
    timestamp: Instant,
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity(1 << 20),
            idle_timeout,
        }
    }

    fn process_packet(&mut self, pkt: &Packet) {
        if let Some(key) = parse_flow_key(&pkt.data) {
            let entry = self.flows.entry(key);
            match entry {
                hashbrown::hash_map::Entry::Occupied(mut e) => {
                    e.get_mut().update(pkt.timestamp, pkt.data.len());
                }
                hashbrown::hash_map::Entry::Vacant(e) => {
                    e.insert(FlowStats::new(pkt.timestamp, pkt.data.len()));
                }
            }
        }
    }

    fn expire_old_flows(&mut self) -> Vec<(FlowKey, FlowStats)> {
        let now = Instant::now();
        let timeout = self.idle_timeout;

        let mut expired = Vec::new();
        self.flows.retain(|k, v| {
            if now.duration_since(v.last_seen) > timeout {
                expired.push((*k, v.clone()));
                false
            } else {
                true
            }
        });
        expired
    }
}

fn parse_flow_key(packet: &[u8]) -> Option<FlowKey> {
    let sliced = SlicedPacket::from_ethernet(packet).ok()?;

    let (src_ip, dst_ip) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = IpAddrKind::from(Ipv4Addr::from(header.source()));
            let dst = IpAddrKind::from(Ipv4Addr::from(header.destination()));
            (src, dst)
        }
        Some(InternetSlice::Ipv6(header, _)) => {
            let src = IpAddrKind::from(Ipv6Addr::from(header.source()));
            let dst = IpAddrKind::from(Ipv6Addr::from(header.destination()));
            (src, dst)
        }
        _ => return None,
    };

    let (src_port, dst_port, proto) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port(), 6),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port(), 17),
        Some(TransportSlice::Icmpv4(_)) => (0, 0, 1),
        Some(TransportSlice::Icmpv6(_)) => (0, 0, 58),
        _ => return None,
    };

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

fn worker_loop(rx: Receiver<Packet>, table: Arc<Mutex<FlowTable>>) {
    while let Ok(pkt) = rx.recv() {
        let mut guard = table.lock();
        guard.process_packet(&pkt);
    }
}

fn expiration_loop(table: Arc<Mutex<FlowTable>>) {
    loop {
        thread::sleep(Duration::from_secs(5));
        let mut guard = table.lock();
        let expired = guard.expire_old_flows();
        if !expired.is_empty() {
            println!("Expired {} flows", expired.len());
        }
    }
}

fn packet_generator(tx: Sender<Packet>) {
    // Placeholder synthetic traffic generator.
    // Replace with real capture backend (pcap/AF_XDP/DPDK/etc).
    loop {
        let dummy = Bytes::from_static(&[
            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, // eth dst
            0x00, 0x11, 0x22, 0x33, 0x44, 0x55, // eth src
            0x08, 0x00, // IPv4
            0x45, 0x00, 0x00, 0x28, 0x00, 0x00, 0x40, 0x00,
            0x40, 0x06, 0x00, 0x00, // TCP
            0xc0, 0xa8, 0x00, 0x01, // 192.168.0.1
            0xc0, 0xa8, 0x00, 0x02, // 192.168.0.2
