use anyhow::Result;
use crossbeam_channel::{bounded, Receiver, Sender};
use hashbrown::HashMap;
use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: [u8; 16],
    dst_ip: [u8; 16],
    src_port: u16,
    dst_port: u16,
    proto: u8,
    is_ipv6: bool,
}

impl FlowKey {
    fn from_ipv4(src: Ipv4Addr, dst: Ipv4Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        let mut src_ip = [0u8; 16];
        let mut dst_ip = [0u8; 16];
        src_ip[..4].copy_from_slice(&src.octets());
        dst_ip[..4].copy_from_slice(&dst.octets());

        Self {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
            is_ipv6: false,
        }
    }

    fn from_ipv6(src: Ipv6Addr, dst: Ipv6Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        Self {
            src_ip: src.octets(),
            dst_ip: dst.octets(),
            src_port,
            dst_port,
            proto,
            is_ipv6: true,
        }
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct FlowRecord {
    key: FlowKey,
    stats: FlowStats,
}

#[derive(Debug)]
enum Packet {
    IPv4 {
        src: Ipv4Addr,
        dst: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        len: usize,
    },
    IPv6 {
        src: Ipv6Addr,
        dst: Ipv6Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        len: usize,
    },
    Unsupported,
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowStats>,
    max_flows: usize,
    idle_timeout: Duration,
}

impl FlowTable {
    fn with_capacity(max_flows: usize, idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity(max_flows),
            max_flows,
            idle_timeout,
        }
    }

    fn ingest(&mut self, pkt: Packet, now: Instant) {
        match pkt {
            Packet::IPv4 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
                len,
            } => {
                let key = FlowKey::from_ipv4(src, dst, src_port, dst_port, proto);
                self.update_flow(key, now, len);
            }
            Packet::IPv6 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
                len,
            } => {
                let key = FlowKey::from_ipv6(src, dst, src_port, dst_port, proto);
                self.update_flow(key, now, len);
            }
            Packet::Unsupported => {}
        }
    }

    fn update_flow(&mut self, key: FlowKey, now: Instant, len: usize) {
        if let Some(stats) = self.flows.get_mut(&key) {
            stats.update(now, len);
        } else {
            if self.flows.len() >= self.max_flows {
                self.evict_expired(now);
                if self.flows.len() >= self.max_flows {
                    self.evict_one();
                }
            }
            self.flows.insert(key, FlowStats::new(now, len));
        }
    }

    fn evict_expired(&mut self, now: Instant) {
        let timeout = self.idle_timeout;
        self.flows.retain(|_, stats| now.duration_since(stats.last_seen) <= timeout);
    }

    fn evict_one(&mut self) {
        if let Some(victim_key) = self
            .flows
            .iter()
            .min_by_key(|(_, stats)| stats.last_seen)
            .map(|(k, _)| *k)
        {
            self.flows.remove(&victim_key);
        }
    }

    fn drain_expired(&mut self, now: Instant) -> Vec<FlowRecord> {
        let timeout = self.idle_timeout;
        let mut expired = Vec::new();
        self.flows.retain(|key, stats| {
            let keep = now.duration_since(stats.last_seen) <= timeout;
            if !keep {
                expired.push(FlowRecord {
                    key: *key,
                    stats: stats.clone(),
                });
            }
            keep
        });
        expired
    }
}

fn parse_mock_packet(line: &str) -> Packet {
    // Simple mock parser for initial implementation.
    // Format:
    // ipv4 src_ip dst_ip src_port dst_port proto len
    // ipv6 src_ip dst_ip src_port dst_port proto len
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() != 7 {
        return Packet::Unsupported;
    }

    match parts[0] {
        "ipv4" => {
            let src: Ipv4Addr = parts[1].parse().ok().unwrap_or(Ipv4Addr::UNSPECIFIED);
            let dst: Ipv4Addr = parts[2].parse().ok().unwrap_or(Ipv4Addr::UNSPECIFIED);
            let src_port = parts[3].parse().ok().unwrap_or(0);
            let dst_port = parts[4].parse().ok().unwrap_or(0);
            let proto = parts[5].parse().ok().unwrap_or(0);
            let len = parts[6].parse().ok().unwrap_or(0);

            Packet::IPv4 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
                len,
            }
        }
        "ipv6" => {
            let src: Ipv6Addr = parts[1].parse().ok().unwrap_or(Ipv6Addr::UNSPECIFIED);
            let dst: Ipv6Addr = parts[2].parse().ok().unwrap_or(Ipv6Addr::UNSPECIFIED);
            let src_port = parts[3].parse().ok().unwrap_or(0);
            let dst_port = parts[4].parse().ok().unwrap_or(0);
            let proto = parts[5].parse().ok().unwrap_or(0);
            let len = parts[6].parse().ok().unwrap_or(0);

            Packet::IPv6 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
                len,
            }
        }
        _ => Packet::Unsupported,
    }
}

fn producer(tx: Sender<Packet>) {
    let samples = vec![
        "ipv4 10.0.0.1 10.0.0.2 12345 80 6 1500",
        "ipv4 10.0.0.1 10.0.0.2 12345 80 6 1500",
        "ipv4 10.0.0.3 10.0.0.4 54321 443 6 900",
        "ipv6 2001:db8::1 2001:db8::2 1111 2222 17 1280",
    ];

    for line in samples {
        let pkt = parse_mock_packet(line);
        if tx.send(pkt).is_err() {
            break;
        }
    }
}

fn consumer(rx: Receiver<Packet>) {
    let mut table = FlowTable::with_capacity(1_000_000, Duration::from_secs(30));
    let mut last_flush = Instant::now();

    while let Ok(pkt) = rx.recv() {
        let now = Instant::now();
        table.ingest(pkt, now);

        if now.duration_since(last_flush) >= Duration::from_secs(5) {
            let expired = table.drain_expired(now);
            for flow in expired {
                println!(
                    "expired flow: packets={} bytes={} proto={} tcp/udp={} -> {}",
                    flow.stats.packets,
                    flow.stats.bytes,
                    flow.key.proto,
                    flow.key.src_port,
                    flow.key.dst_port
                );
            }
            last_flush = now;
        }
    }

    let expired = table.drain_expired(Instant::now());
    for flow in expired {
        println!(
            "final expired flow: packets={} bytes={}",
            flow.stats.packets, flow.stats.bytes
        );
    }
}

fn main() -> Result<()> {
    env_logger::init();

    let (tx, rx) = bounded::<Packet>(100_000);

    let producer_handle = std::thread::spawn(move || producer(tx));
    let consumer_handle = std::thread::spawn(move || consumer(rx));

    producer_handle.join().unwrap();
    consumer_handle.join().unwrap();

    Ok(())
}
