use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT_SECS: u64 = 30;
const FLOW_MAX_LIFETIME_SECS: u64 = 300;

/// Fast, simple hasher for flow keys.
/// For production, consider a stronger/faster hash (e.g. ahash, fxhash, wyhash),
/// but this keeps the example self-contained.
#[derive(Default)]
struct Fnv1a64 {
    hash: u64,
}

impl Hasher for Fnv1a64 {
    fn write(&mut self, bytes: &[u8]) {
        let mut hash = if self.hash == 0 {
            0xcbf29ce484222325
        } else {
            self.hash
        };
        for b in bytes {
            hash ^= *b as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        self.hash = hash;
    }

    fn finish(&self) -> u64 {
        if self.hash == 0 {
            0xcbf29ce484222325
        } else {
            self.hash
        }
    }
}

type FastBuildHasher = BuildHasherDefault<Fnv1a64>;

#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct FlowRecord {
    pub key: FlowKey,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub packets: u64,
    pub bytes: u64,
}

impl FlowRecord {
    pub fn new(key: FlowKey, now: Instant, len: usize) -> Self {
        Self {
            key,
            first_seen: now,
            last_seen: now,
            packets: 1,
            bytes: len as u64,
        }
    }

    pub fn update(&mut self, now: Instant, len: usize) {
        self.last_seen = now;
        self.packets += 1;
        self.bytes += len as u64;
    }

    pub fn is_expired(&self, now: Instant) -> bool {
        let idle = now.duration_since(self.last_seen);
        let lifetime = now.duration_since(self.first_seen);

        idle >= Duration::from_secs(FLOW_IDLE_TIMEOUT_SECS)
            || lifetime >= Duration::from_secs(FLOW_MAX_LIFETIME_SECS)
    }
}

pub struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowRecord, FastBuildHasher>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::with_hasher(FastBuildHasher::default())),
        }
    }

    fn update_flow(&self, key: FlowKey, now: Instant, len: usize) {
        let mut guard = self.map.lock().unwrap();
        if let Some(flow) = guard.get_mut(&key) {
            flow.update(now, len);
        } else {
            guard.insert(key, FlowRecord::new(key, now, len));
        }
    }

    fn expire_flows(&self, now: Instant) -> Vec<FlowRecord> {
        let mut guard = self.map.lock().unwrap();
        let mut expired = Vec::new();

        guard.retain(|_, flow| {
            if flow.is_expired(now) {
                expired.push(flow.clone());
                false
            } else {
                true
            }
        });

        expired
    }

    fn len(&self) -> usize {
        let guard = self.map.lock().unwrap();
        guard.len()
    }
}

pub struct FlowAnalyzer {
    shards: Vec<Arc<FlowShard>>,
}

impl FlowAnalyzer {
    pub fn new() -> Self {
        let mut shards = Vec::with_capacity(SHARDS);
        for _ in 0..SHARDS {
            shards.push(Arc::new(FlowShard::new()));
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(key: &FlowKey) -> usize {
        use std::collections::hash_map::DefaultHasher;
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & (SHARDS - 1)
    }

    pub fn process_packet(
        &self,
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        protocol: u8,
        packet_len: usize,
    ) {
        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            protocol,
        };

        let idx = Self::shard_index(&key);
        let shard = &self.shards[idx];
        shard.update_flow(key, Instant::now(), packet_len);
    }

    pub fn expire_all(&self) -> Vec<FlowRecord> {
        let now = Instant::now();
        let mut expired = Vec::new();

        for shard in &self.shards {
            expired.extend(shard.expire_flows(now));
        }

        expired
    }

    pub fn total_flows(&self) -> usize {
        self.shards.iter().map(|s| s.len()).sum()
    }
}
