use hashbrown::HashMap;
use parking_lot::Mutex;
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum FlowAddr {
    V4(Ipv4Addr),
    V6(Ipv6Addr),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: FlowAddr,
    dst: FlowAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct FlowTable {
    map: HashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            map: HashMap::with_capacity(1 << 20),
            idle_timeout,
        }
    }

    fn observe(&mut self, key: FlowKey, now: Instant, bytes: usize) {
        use hashbrown::hash_map::Entry;

        match self.map.entry(key) {
            Entry::Occupied(mut e) => {
                e.get_mut().update(now, bytes);
            }
            Entry::Vacant(e) => {
                e.insert(FlowStats::new(now, bytes));
            }
        }
    }

    fn expire(&mut self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let timeout = self.idle_timeout;
        let mut expired = Vec::new();

        self.map.retain(|k, v| {
            let should_expire = now.duration_since(v.last_seen) >= timeout;
            if should_expire {
                expired.push((*k, v.clone()));
                false
            } else {
                true
            }
        });

        expired
    }
}

#[derive(Debug)]
struct ParsedPacket<'a> {
    proto: u8,
    src: FlowAddr,
    dst: FlowAddr,
    src_port: u16,
    dst_port: u16,
    payload: &'a [u8],
}

fn parse_packet(packet: &[u8]) -> Option<ParsedPacket<'_>> {
    if packet.len() < 14 {
        return None;
    }

    // Ethernet header
    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    let mut offset = 14;

    match ethertype {
        0x0800 => parse_ipv4(packet, offset),
        0x86DD => parse_ipv6(packet, offset),
        _ => None,
    }
}

fn parse_ipv4(packet: &[u8], offset: usize) -> Option<ParsedPacket<'_>> {
    if packet.len() < offset + 20 {
        return None;
    }

    let ihl = (packet[offset] & 0x0F) as usize * 4;
    if ihl < 20 || packet.len() < offset + ihl {
        return None;
    }

    let proto = packet[offset + 9];
    let src = Ipv4Addr::new(
        packet[offset + 12],
        packet[offset + 13],
        packet[offset + 14],
        packet[offset + 15],
    );
    let dst = Ipv4Addr::new(
        packet[offset + 16],
        packet[offset + 17],
        packet[offset + 18],
        packet[offset + 19],
    );

    let l4 = offset + ihl;
    parse_l4(packet, l4, proto, FlowAddr::V4(src), FlowAddr::V4(dst))
}

fn parse_ipv6(packet: &[u8], offset: usize) -> Option<ParsedPacket<'_>> {
    if packet.len() < offset + 40 {
        return None;
    }

    let proto = packet[offset + 6];
    let src = Ipv6Addr::from(<[u8; 16]>::try_from(&packet[offset + 8..offset + 24]).ok()?);
    let dst = Ipv6Addr::from(<[u8; 16]>::try_from(&packet[offset + 24..offset + 40]).ok()?);

    let l4 = offset + 40;
    parse_l4(packet, l4, proto, FlowAddr::V6(src), FlowAddr::V6(dst))
}

fn parse_l4(
    packet: &[u8],
    offset: usize,
    proto: u8,
    src: FlowAddr,
    dst: FlowAddr,
) -> Option<ParsedPacket<'_>> {
    match proto {
        6 => {
            // TCP
            if packet.len() < offset + 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([packet[offset], packet[offset + 1]]);
            let dst_port = u16::from_be_bytes([packet[offset + 2], packet[offset + 3]]);
            let data_offset = ((packet[offset + 12] >> 4) as usize) * 4;
            if data_offset < 20 || packet.len() < offset + data_offset {
                return None;
            }
            Some(ParsedPacket {
                proto,
                src,
                dst,
                src_port,
                dst_port,
                payload: &packet[offset + data_offset..],
            })
        }
        17 => {
            // UDP
            if packet.len() < offset + 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([packet[offset], packet[offset + 1]]);
            let dst_port = u16::from_be_bytes([packet[offset + 2], packet[offset + 3]]);
            Some(ParsedPacket {
                proto,
                src,
                dst,
                src_port,
                dst_port,
                payload: &packet[offset + 8..],
            })
        }
        _ => None,
    }
}

fn process_packet(flow_table: &mut FlowTable, packet: &[u8], now: Instant) {
    if let Some(parsed) = parse_packet(packet) {
        let key = FlowKey {
            src: parsed.src,
            dst: parsed.dst,
            src_port: parsed.src_port,
            dst_port: parsed.dst_port,
            proto: parsed.proto,
        };

        flow_table.observe(key, now, packet.len());
    }
}

fn main() {
    let mut flow_table = FlowTable::new(Duration::from_secs(30));

