use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

const DEFAULT_SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);

#[derive(Clone, Copy, Debug, Eq)]
pub enum FlowKey {
    V4 {
        src: u32,
        dst: u32,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
    V6 {
        src: [u8; 16],
        dst: [u8; 16],
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        use FlowKey::*;
        match (self, other) {
            (
                V4 {
                    src: a1,
                    dst: a2,
                    src_port: a3,
                    dst_port: a4,
                    proto: a5,
                },
                V4 {
                    src: b1,
                    dst: b2,
                    src_port: b3,
                    dst_port: b4,
                    proto: b5,
                },
            ) => a1 == b1 && a2 == b2 && a3 == b3 && a4 == b4 && a5 == b5,
            (
                V6 {
                    src: a1,
                    dst: a2,
                    src_port: a3,
                    dst_port: a4,
                    proto: a5,
                },
                V6 {
                    src: b1,
                    dst: b2,
                    src_port: b3,
                    dst_port: b4,
                    proto: b5,
                },
            ) => a1 == b1 && a2 == b2 && a3 == b3 && a4 == b4 && a5 == b5,
            _ => false,
        }
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            FlowKey::V4 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            } => {
                4u8.hash(state);
                src.hash(state);
                dst.hash(state);
                src_port.hash(state);
                dst_port.hash(state);
                proto.hash(state);
            }
            FlowKey::V6 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            } => {
                6u8.hash(state);
                src.hash(state);
                dst.hash(state);
                src_port.hash(state);
                dst_port.hash(state);
                proto.hash(state);
            }
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    pub fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    pub fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

pub struct FlowRecord {
    pub key: FlowKey,
    pub stats: FlowStats,
}

struct Shard {
    map: RwLock<HashMap<FlowKey, FlowStats>>,
}

impl Shard {
    fn new(capacity: usize) -> Self {
        Self {
            map: RwLock::new(HashMap::with_capacity(capacity)),
        }
    }
}

pub struct FlowAnalyzer {
    shards: Vec<Shard>,
    shard_mask: usize,
    idle_timeout: Duration,
}

impl FlowAnalyzer {
    pub fn new(shards: usize, expected_flows: usize, idle_timeout: Duration) -> Self {
        assert!(shards.is_power_of_two(), "shards must be a power of two");

        let per_shard = (expected_flows / shards).max(1);
        let mut shard_vec = Vec::with_capacity(shards);
        for _ in 0..shards {
            shard_vec.push(Shard::new(per_shard));
        }

        Self {
            shards: shard_vec,
            shard_mask: shards - 1,
            idle_timeout,
        }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        use std::collections::hash_map::DefaultHasher;
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & self.shard_mask
    }

    #[inline]
    pub fn observe_packet(&self, key: FlowKey, packet_len: usize, now: Instant) {
        let idx = self.shard_index(&key);
        let shard = &self.shards[idx];

        // Hot path: write lock per shard
        let mut map = shard.map.write().unwrap();
        match map.get_mut(&key) {
            Some(stats) => stats.update(now, packet_len),
            None => {
                map.insert(key, FlowStats::new(now, packet_len));
            }
        }
    }

    pub fn expire_idle_flows(&self, now: Instant) -> Vec<FlowRecord> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.write().unwrap();
            let timeout = self.idle_timeout;

            let mut to_remove = Vec::new();
            for (k, v) in map.iter() {
                if now.duration_since(v.last_seen) >= timeout {
                    to_remove.push(*k);
                }
            }

            for key in to_remove {
                if let Some(stats) = map.remove(&key) {
                    expired.push(FlowRecord { key, stats });
                }
            }
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<FlowRecord> {
        let mut out = Vec::new();
        for shard in &self.shards {
            let map = shard.map.read().unwrap();
            out.extend(map.iter().map(|(k, v)| FlowRecord {
                key: *k,
                stats: v.clone(),
            }));
        }
        out
    }
}

// --- Packet parsing helpers ---

#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    pub src: IpAddr,
    pub dst: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub len: usize,
    pub payload: &'a [u8],
}

impl<'a> PacketView<'a> {
    pub fn to_flow_key(&self) -> Option<FlowKey> {
        match (self.src, self.dst) {
            (IpAddr::V4(s), IpAddr::V4(d)) => Some(FlowKey::V4 {
                src: u32::from_be_bytes(s.octets()),
                dst: u32::from_be_bytes(d.octets()),
                src_port: self.src_port,
                dst_port: self.dst_port,
                proto: self.proto,
            }),
            (IpAddr::V6(s), IpAddr::V6(d)) => Some(FlowKey::V6 {
                src: s.octets(),
                dst: d.octets(),
                src_port: self.src_port,
                dst_port: self.dst_port,
                proto: self.proto,
            }),
            _ => None,
        }
    }
}

// --- Example usage ---

fn main() {
    let analyzer = Arc::new(FlowAnalyzer::new(
        DEFAULT_SHARDS,
        1_000_000,
        FLOW_IDLE_TIMEOUT,
    ));

    let now = Instant::now();

    // Simulated packets
    let packets = vec![
        PacketView {
            src: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
            dst: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
            src_port: 12345,
            dst_port: 443,
            proto: 6,
            len: 1500,
            payload: &[],
        },
        PacketView {
            src: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
            dst: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
            src_port: 12345,
            dst_port: 443,
            proto: 6,
            len: 1500,
            payload: &[],
        },
    ];

    for pkt in packets {
        if let Some(flow_key) = pkt.to_flow_key() {
            analyzer.observe_packet(flow_key, pkt.len, now);
        }
    }

    let snapshot = analyzer.snapshot();
    for rec in snapshot {
        println!("{:?} => packets={}, bytes={}", rec.key, rec.stats.packets, rec.stats.bytes);
    }

    let expired = analyzer.expire_idle_flows(now + Duration::from_secs(31));
    println!("expired flows: {}", expired.len());
}
