## Initial implementation

### `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const (
	ethHeaderLen = 14
	ipv4MinLen   = 20
	tcpMinLen    = 20
	udpLen       = 8

	numShards = 256
)

type FlowKey struct {
	SrcIP   uint32
	DstIP   uint32
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	_       uint8 // padding
}

type FlowStats struct {
	Packets    uint64
	Bytes      uint64
	FirstSeen  int64
	LastSeen   int64
	TCPFlags   uint8
	_          [7]byte
}

type flowEntry struct {
	key   FlowKey
	stats FlowStats
}

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*flowEntry
}

type Analyzer struct {
	shards [numShards]shard

	totalPackets uint64
	totalBytes   uint64
	dropped      uint64
}

func NewAnalyzer() *Analyzer {
	a := &Analyzer{}
	for i := range a.shards {
		a.shards[i].flows = make(map[FlowKey]*flowEntry, 1024)
	}
	return a
}

func shardIndex(k FlowKey) uint32 {
	// Simple multiplicative hash on key fields.
	h := uint32(k.SrcIP) ^ uint32(k.DstIP<<1) ^ uint32(k.SrcPort)<<16 ^ uint32(k.DstPort) ^ uint32(k.Proto)
	h ^= h >> 16
	h *= 0x7feb352d
	h ^= h >> 15
	h *= 0x846ca68b
	h ^= h >> 16
	return h % numShards
}

func (a *Analyzer) ProcessPacket(pkt []byte, now time.Time) {
	atomic.AddUint64(&a.totalPackets, 1)

	// Parse Ethernet
	if len(pkt) < ethHeaderLen {
		atomic.AddUint64(&a.dropped, 1)
		return
	}

	ethType := binary.BigEndian.Uint16(pkt[12:14])
	if ethType != 0x0800 { // IPv4 only
		return
	}

	ip := pkt[ethHeaderLen:]
	if len(ip) < ipv4MinLen {
		atomic.AddUint64(&a.dropped, 1)
		return
	}

	verIHL := ip[0]
	version := verIHL >> 4
	ihl := int(verIHL&0x0F) * 4
	if version != 4 || ihl < ipv4MinLen || len(ip) < ihl {
		atomic.AddUint64(&a.dropped, 1)
		return
	}

	totalLen := int(binary.BigEndian.Uint16(ip[2:4]))
	if totalLen < ihl || len(ip) < totalLen {
		atomic.AddUint64(&a.dropped, 1)
		return
	}

	proto := ip[9]
	srcIP := binary.BigEndian.Uint32(ip[12:16])
	dstIP := binary.BigEndian.Uint32(ip[16:20])

	l4 := ip[ihl:totalLen]

	var srcPort, dstPort uint16
	var flags uint8

	switch proto {
	case 6: // TCP
		if len(l4) < tcpMinLen {
			atomic.AddUint64(&a.dropped, 1)
			return
		}
		srcPort = binary.BigEndian.Uint16(l4[0:2])
		dstPort = binary.BigEndian.Uint16(l4[2:4])
		flags = l4[13]
	case 17: // UDP
		if len(l4) < udpLen {
			atomic.AddUint64(&a.dropped, 1)
			return
		}
		srcPort = binary.BigEndian.Uint16(l4[0:2])
		dstPort = binary.BigEndian.Uint16(l4[2:4])
	default:
		// Track only TCP/UDP for now
		return
	}

	key := FlowKey{
		SrcIP:   srcIP,
		DstIP:   dstIP,
		SrcPort: srcPort,
		DstPort: dstPort,
		Proto:   proto,
	}

	idx := shardIndex(key)
	s := &a.shards[idx]

	s.mu.Lock()
	entry, ok := s.flows[key]
	if !ok {
		entry = &flowEntry{
			key: key,
			stats: FlowStats{
				FirstSeen: now.UnixNano(),
				LastSeen:  now.UnixNano(),
				TCPFlags:  flags,
			},
		}
		s.flows[key] = entry
	}
	entry.stats.Packets++
	entry.stats.Bytes += uint64(totalLen + ethHeaderLen)
	entry.stats.LastSeen = now.UnixNano()
	entry.stats.TCPFlags |= flags
	s.mu.Unlock()

	atomic.AddUint64(&a.totalBytes, uint64(totalLen+ethHeaderLen))
}

func (a *Analyzer) Snapshot() []flowEntry {
	var out []flowEntry
	for i := range a.shards {
		s := &a.shards[i]
		s.mu.RLock()
		for _, e := range s.flows {
			out = append(out, *e)
		}
		s.mu.RUnlock()
	}
	return out
}

func (a *Analyzer) ExpireFlows(idleTimeout time.Duration) {
	cutoff := time.Now().Add(-idleTimeout).UnixNano()
	for i := range a.shards {
		s := &a.shards[i]
		s.mu.Lock()
		for k, e := range s.flows {
			if e.stats.LastSeen < cutoff {
				delete(s.flows, k)
			}
		}
		s.mu.Unlock()
	}
}

func ipToString(ip uint32) string {
	b := []byte{
		byte(ip >> 24),
		byte(ip >> 16),
		byte(ip >> 8),
		byte(ip),
	}
	return net.IP(b).String()
}

func protoName(p uint8) string {
	switch p {
	case 6:
		return "TCP"
	case 17:
		return "UDP"
	default:
		return fmt.Sprintf("%d", p)
	}
}

