		for range ticker.C {
			flows := analyzer.Snapshot()
			fmt.Printf("flows=%d totalPackets=%d totalBytes=%d dropped=%d\n",
				len(flows),
				atomic.LoadUint64(&analyzer.totalPackets),
				atomic.LoadUint64(&analyzer.totalBytes),
				atomic.LoadUint64(&analyzer.dropped),
			)

			// Print top few flows by bytes
			for i, f := range flows {
				if i >= 10 {
					break
				}
				fmt.Printf("%s %s:%d -> %s:%d packets=%d bytes=%d first=%s last=%s flags=0x%02x\n",
					protoName(f.key.Proto),
					ipToString(f.key.SrcIP), f.key.SrcPort,
					ipToString(f.key.DstIP), f.key.DstPort,
					f.stats.Packets,
					f.stats.Bytes,
					time.Unix(0, f.stats.FirstSeen).Format(time.RFC3339Nano),
					time.Unix(0, f.stats.LastSeen).Format(time.RFC3339Nano),
					f.stats.TCPFlags,
				)
			}
		}
	}()

	// Idle flow expiration
	go func() {
		ticker := time.NewTicker(30 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			analyzer.ExpireFlows(2 * time.Minute)
		}
	}()

	// Graceful shutdown
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh
	log.Println("shutting down")
}
