use ahash::AHasher;
use bytes::BytesMut;
use crossbeam::queue::ArrayQueue;
use hashbrown::HashMap;
use parking_lot::Mutex;
use std::hash::{Hash, Hasher};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::time::{Duration, Instant};

const SHARDS: usize = 64;
const FLOW_TIMEOUT_SECS: u64 = 60;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum IpAddrKind {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: IpAddrKind,
    dst: IpAddrKind,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
}

impl FlowStats {
    fn new(now_ns: u64, packet_len: usize) -> Self {
        Self {
            packets: 1,
            bytes: packet_len as u64,
            first_seen_ns: now_ns,
            last_seen_ns: now_ns,
        }
    }

    fn update(&mut self, now_ns: u64, packet_len: usize) {
        self.packets += 1;
        self.bytes += packet_len as u64;
        self.last_seen_ns = now_ns;
    }
}

struct Shard {
    table: Mutex<HashMap<FlowKey, FlowStats>>,
}

impl Shard {
    fn new() -> Self {
        Self {
            table: Mutex::new(HashMap::with_capacity(4096)),
        }
    }
}

struct FlowTable {
    shards: Vec<Shard>,
}

impl FlowTable {
    fn new() -> Self {
        let mut shards = Vec::with_capacity(SHARDS);
        for _ in 0..SHARDS {
            shards.push(Shard::new());
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & (SHARDS - 1)
    }

    fn ingest(&self, key: FlowKey, now_ns: u64, packet_len: usize) {
        let idx = Self::shard_index(&key);
        let mut guard = self.shards[idx].table.lock();

        match guard.get_mut(&key) {
            Some(stats) => stats.update(now_ns, packet_len),
            None => {
                guard.insert(key, FlowStats::new(now_ns, packet_len));
            }
        }
    }

    fn expire(&self, now_ns: u64, timeout_ns: u64) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut guard = shard.table.lock();
            let keys_to_remove: Vec<FlowKey> = guard
                .iter()
                .filter_map(|(k, v)| {
                    if now_ns.saturating_sub(v.last_seen_ns) > timeout_ns {
                        Some(*k)
                    } else {
                        None
                    }
                })
                .collect();

            for key in keys_to_remove {
                if let Some(stats) = guard.remove(&key) {
                    expired.push((key, stats));
                }
            }
        }

        expired
    }
}

#[derive(Debug)]
struct ParsedPacket {
    flow: FlowKey,
    len: usize,
}

#[inline]
fn now_ns() -> u64 {
    // Monotonic time in ns
    Instant::now().elapsed().as_nanos() as u64
}

/// Parse Ethernet + IPv4/IPv6 + TCP/UDP.
/// Returns None for unsupported/invalid frames.
fn parse_packet(frame: &[u8]) -> Option<ParsedPacket> {
    if frame.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    let payload = &frame[14..];

    match ethertype {
        0x0800 => parse_ipv4(payload, frame.len()),
        0x86DD => parse_ipv6(payload, frame.len()),
        _ => None,
    }
}

fn parse_ipv4(payload: &[u8], frame_len: usize) -> Option<ParsedPacket> {
    if payload.len() < 20 {
        return None;
    }

    let ihl = (payload[0] & 0x0F) as usize * 4;
    if payload.len() < ihl || ihl < 20 {
        return None;
    }

    let proto = payload[9];
    let src = [payload[12], payload[13], payload[14], payload[15]];
    let dst = [payload[16], payload[17], payload[18], payload[19]];

    let l4 = &payload[ihl..];
    match proto {
        6 | 17 => {
            if l4.len() < 4 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

            Some(ParsedPacket {
                flow: FlowKey {
                    src: IpAddrKind::V4(src),
                    dst: IpAddrKind::V4(dst),
                    src_port,
                    dst_port,
                    proto,
                },
                len: frame_len,
            })
        }
        _ => None,
    }
}

fn parse_ipv6(payload: &[u8], frame_len: usize) -> Option<ParsedPacket> {
    if payload.len() < 40 {
        return None;
    }

    let next_header = payload[6];
    let src: [u8; 16] = payload[8..24].try_into().ok()?;
    let dst: [u8; 16] = payload[24..40].try_into().ok()?;

    let l4 = &payload[40..];
    match next_header {
        6 | 17 => {
            if l4.len() < 4 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

            Some(ParsedPacket {
                flow: FlowKey {
                    src: IpAddrKind::V6(src),
                    dst: IpAddrKind::V6(dst),
                    src_port,
                    dst_port,
                    proto: next_header,
                },
                len: frame_len,
            })
        }
        _ => None,
    }
}

struct Analyzer {
    flows: Arc<FlowTable>,
    expired_sink: ArrayQueue<(FlowKey, FlowStats)>,
}

impl Analyzer {
    fn new() -> Self {
        Self {
            flows: Arc::new(FlowTable::new()),
            expired_sink: ArrayQueue::new(1 << 16),
        }
    }

    fn process_frame(&self, frame: &[u8]) {
        if let Some(pkt) = parse_packet(frame) {
            let now = now_ns();
            self.flows.ingest(pkt.flow, now, pkt.len);
        }
    }

    fn run_expiry_loop(&self) {
        let timeout_ns = Duration::from_secs(FLOW_TIMEOUT_SECS).as_nanos() as u64;

        loop {
            std::thread::sleep(Duration::from_secs(1));
            let now = now_ns();
            let expired = self.flows.expire(now, timeout_ns);

            for item in expired {
                let _ = self.expired_sink.push(item);
            }

            // In a real system, drain expired_sink to an exporter here.
        }
    }
}

fn main() {
    let analyzer = Analyzer::new();

