use ahash::AHasher;
use bytes::BytesMut;
use crossbeam::channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct CanonicalFlowKey {
    a_ip: Ipv4Addr,
    b_ip: Ipv4Addr,
    a_port: u16,
    b_port: u16,
    protocol: u8,
}

impl CanonicalFlowKey {
    fn new(src_ip: Ipv4Addr, dst_ip: Ipv4Addr, src_port: u16, dst_port: u16, protocol: u8) -> Self {
        // Bidirectional canonical ordering
        let left = (u32::from(src_ip), src_port);
        let right = (u32::from(dst_ip), dst_port);

        if left <= right {
            Self {
                a_ip: src_ip,
                b_ip: dst_ip,
                a_port: src_port,
                b_port: dst_port,
                protocol,
            }
        } else {
            Self {
                a_ip: dst_ip,
                b_ip: src_ip,
                a_port: dst_port,
                b_port: src_port,
                protocol,
            }
        }
    }
}

#[derive(Debug, Clone)]
struct FlowRecord {
    key: CanonicalFlowKey,
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u64,
    tcp_fin: u64,
    tcp_rst: u64,
    tcp_psh: u64,
    tcp_ack: u64,
}

impl FlowRecord {
    fn new(key: CanonicalFlowKey, now: Instant) -> Self {
        Self {
            key,
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
            tcp_psh: 0,
            tcp_ack: 0,
        }
    }

    fn update(&mut self, packet_len: usize, now: Instant, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += packet_len as u64;
        self.last_seen = now;

        if let Some(flags) = tcp_flags {
            if flags & 0x02 != 0 {
                self.tcp_syn += 1;
            }
            if flags & 0x01 != 0 {
                self.tcp_fin += 1;
            }
            if flags & 0x04 != 0 {
                self.tcp_rst += 1;
            }
            if flags & 0x08 != 0 {
                self.tcp_psh += 1;
            }
            if flags & 0x10 != 0 {
                self.tcp_ack += 1;
            }
        }
    }
}

struct Shard {
    flows: Mutex<HashMap<CanonicalFlowKey, FlowRecord>>,
}

impl Shard {
    fn new() -> Self {
        Self {
            flows: Mutex::new(HashMap::with_capacity(4096)),
        }
    }
}

struct FlowTable {
    shards: Vec<Shard>,
}

impl FlowTable {
    fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(Shard::new());
        }
        Self { shards }
    }

    fn shard_for(key: &CanonicalFlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % NUM_SHARDS
    }

    fn update_flow(
        &self,
        key: CanonicalFlowKey,
        packet_len: usize,
        now: Instant,
        tcp_flags: Option<u8>,
    ) {
        let idx = Self::shard_for(&key);
        let mut shard = self.shards[idx].flows.lock();

        let entry = shard.entry(key).or_insert_with(|| FlowRecord::new(key, now));
        entry.update(packet_len, now, tcp_flags);
    }

    fn export_idle(&self, idle_timeout: Duration) -> Vec<FlowRecord> {
        let now = Instant::now();
        let mut exported = Vec::new();

        for shard in &self.shards {
            let mut map = shard.flows.lock();
            let idle_keys: Vec<_> = map
                .iter()
                .filter_map(|(k, v)| {
                    if now.duration_since(v.last_seen) >= idle_timeout {
                        Some(*k)
                    } else {
                        None
                    }
                })
                .collect();

            for key in idle_keys {
                if let Some(record) = map.remove(&key) {
                    exported.push(record);
                }
            }
        }

        exported
    }

    fn export_all(&self) -> Vec<FlowRecord> {
        let mut exported = Vec::new();
        for shard in &self.shards {
            let mut map = shard.flows.lock();
            exported.extend(map.drain().map(|(_, v)| v));
        }
        exported
    }
}

#[derive(Debug)]
struct ParsedPacket {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
    tcp_flags: Option<u8>,
    packet_len: usize,
}

fn parse_ethernet_ipv4(packet: &[u8]) -> Option<ParsedPacket> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only for now
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || ip.len() < ihl {
        return None;
    }

    let protocol = ip[9];
    let src_ip = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
    let dst_ip = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

    let transport = &ip[ihl..];
    match protocol {
        6 => {
            // TCP
            if transport.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([transport[0], transport[1]]);
            let dst_port = u16::from_be_bytes([transport[2], transport[3]]);
            let data_offset = ((transport[12] >> 4) as usize) * 4;
            if transport.len() < data_offset || data_offset < 20 {
                return None;
            }
            let flags = transport[13];

            Some(ParsedPacket {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                protocol,
                tcp_flags: Some(flags),
                packet_len: packet.len(),
            })
        }
        17 => {
            // UDP
            if transport.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([transport[0], transport[1]]);
            let dst_port = u16::from_be_bytes([transport[2], transport[3]]);

            Some(ParsedPacket {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                protocol,
                tcp_flags: None,
                packet_len: packet.len(),
            })
        }
        _ => None,
    }
}

trait PacketSource: Send {
    fn recv_packet(&mut self, buf: &mut BytesMut) -> Option<usize>;
}

struct DummyPacketSource {
    packets: Vec<Vec<u8>>,
    idx: usize,
}

impl DummyPacketSource {
    fn new(packets: Vec<Vec<u8>>) -> Self {
        Self { packets, idx: 0 }
    }
}

impl PacketSource for DummyPacketSource {
    fn recv_packet(&mut self, buf: &mut BytesMut) -> Option<usize> {
        if self.idx >= self.packets.len() {
            return None;
        }
        let pkt = &self.packets[self.idx];
        self.idx += 1;

        buf.clear();
        buf.extend_from_slice(pkt);
        Some(pkt.len())
    }
}

fn packet_worker(mut source: Box<dyn PacketSource>, tx: Sender<BytesMut>) {
    loop {
        let mut buf = BytesMut::with_capacity(2048);
        match source.recv_packet(&mut buf) {
            Some(_) => {
                if tx.send(buf).is_err() {
                    break;
                }
            }
            None => break,
        }
    }
}

fn analyser_worker(rx: Receiver<BytesMut>, flow_table: Arc<FlowTable>) {
    while let Ok(packet) = rx.recv() {
        if let Some(parsed) = parse_ethernet_ipv4(&packet) {
            let key = CanonicalFlowKey::new(
                parsed.src_ip,
                parsed.dst_ip,
                parsed.src_port,
                parsed.dst_port,
                parsed.protocol,
            );
            flow_table.update_flow(key, parsed.packet_len, Instant::now(), parsed.tcp_flags);
        }
    }
}

fn exporter_worker(flow_table: Arc<FlowTable>) {
    loop {
        thread::sleep(EXPORT_INTERVAL);
        let expired = flow_table.export_idle(FLOW_IDLE_TIMEOUT);

        if !expired.is_empty() {
            for flow in expired {
                println!(
                    "EXPIRED flow {:?} packets={} bytes={} first_seen={:?} last_seen={:?}",
                    flow.key, flow.packets, flow.bytes, flow.first_seen, flow.last_seen
                );
            }
        }
    }
}

fn build_dummy_ipv4_tcp_packet() -> Vec<u8> {
    // Minimal Ethernet + IPv4 + TCP packet
    let mut pkt = vec![0u8; 14 + 20 + 20];

    // Ethernet type IPv4
    pkt[12] = 0x08;
    pkt[13] = 0x00;

    // IPv4 header
    pkt[14] = 0x45; // version=4, ihl=5
    pkt[23] = 6; // TCP
    pkt[26..30].copy_from_slice(&[192, 168, 1, 10]);
    pkt[30..34].copy_from_slice(&[192, 168, 1, 20]);

    // TCP header
    pkt[34..36].copy_from_slice(&12345u16.to_be_bytes());
    pkt[36..38].copy_from_slice(&80u16.to_be_bytes());
    pkt[46] = 0x50; // data offset=5
    pkt[47] = 0x18; // PSH+ACK

    pkt
}

fn main() {
    let flow_table = Arc::new(FlowTable::new());

    let (tx, rx) = bounded::<BytesMut>(8192);

    let dummy_packets = vec![
        build_dummy_ipv4_tcp_packet(),
        build_dummy_ipv4_tcp_packet(),
        build_dummy_ipv4_tcp_packet(),
    ];

    let source = Box::new(DummyPacketSource::new(dummy_packets));

    let ft1 = flow_table.clone();
    let analyser_handle = thread::spawn(move || analyser_worker(rx, ft1));

    let tx1 = tx.clone();
    let packet_handle = thread::spawn(move || packet_worker(source, tx1));

    let ft2 = flow_table.clone();
    let exporter_handle = thread::spawn(move || exporter_worker(ft2));

    drop(tx);

    let _ = packet_handle.join();
    let _ = analyser_handle.join();

    // Final export
    let remaining = flow_table.export_all();
    for flow in remaining {
        println!(
            "FINAL flow {:?} packets={} bytes={}",
            flow.key, flow.packets, flow.bytes
        );
    }

    // exporter thread is infinite in this demo; in a real system use shutdown signal
    let _ = exporter_handle;
}
