```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use ahash::RandomState;
use crossbeam_utils::CachePadded;

const DEFAULT_SHARDS: usize = 64;
const DEFAULT_FLOW_TIMEOUT: Duration = Duration::from_secs(60);

#[derive(Clone, Copy, Debug, Eq)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub flow: FlowKey,
    pub bytes: usize,
    pub timestamp: Instant,
    pub tcp_syn: bool,
    pub tcp_fin: bool,
    pub tcp_rst: bool,
}

#[derive(Debug, Default, Clone)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub tcp_syn_count: u64,
    pub tcp_fin_count: u64,
    pub tcp_rst_count: u64,
}

impl FlowStats {
    pub fn new(ts: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: ts,
            last_seen: ts,
            tcp_syn_count: 0,
            tcp_fin_count: 0,
            tcp_rst_count: 0,
        }
    }

    pub fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.bytes as u64;
        self.last_seen = pkt.timestamp;

        if pkt.tcp_syn {
            self.tcp_syn_count += 1;
        }
        if pkt.tcp_fin {
            self.tcp_fin_count += 1;
        }
        if pkt.tcp_rst {
            self.tcp_rst_count += 1;
        }
    }
}

pub struct FlowTable {
    shards: Vec<CachePadded<Mutex<HashMap<FlowKey, FlowStats, RandomState>>>>,
    shard_mask: usize,
    timeout: Duration,
}

impl FlowTable {
    pub fn new(shards: usize, timeout: Duration) -> Self {
        assert!(shards.is_power_of_two(), "shards must be a power of two");

        let mut vec = Vec::with_capacity(shards);
        for _ in 0..shards {
            vec.push(CachePadded::new(Mutex::new(HashMap::with_hasher(
                RandomState::new(),
            ))));
        }

        Self {
            shards: vec,
            shard_mask: shards - 1,
            timeout,
        }
    }

    fn shard_for(&self, key: &FlowKey) -> usize {
        let mut hasher = ahash::AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & self.shard_mask
    }

    pub fn ingest(&self, pkt: PacketMeta) {
        let shard_idx = self.shard_for(&pkt.flow);
        let mut shard = self.shards[shard_idx].lock().unwrap();

        shard
            .entry(pkt.flow)
            .and_modify(|stats| stats.update(&pkt))
            .or_insert_with(|| {
                let mut stats = FlowStats::new(pkt.timestamp);
                stats.update(&pkt);
                stats
            });
    }

    pub fn expire(&self, now: Instant) -> usize {
        let mut expired = 0;

        for shard in &self.shards {
            let mut guard = shard.lock().unwrap();
            let timeout = self.timeout;

            guard.retain(|_, stats| {
                let alive = now.duration_since(stats.last_seen) <= timeout;
                if !alive {
                    expired += 1;
                }
                alive
            });
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut out = Vec::new();

        for shard in &self.shards {
            let guard = shard.lock().unwrap();
            out.extend(guard.iter().map(|(k, v)| (*k, v.clone())));
        }

        out
    }
}

fn main() {
    let table = Arc::new(FlowTable::new(DEFAULT_SHARDS, DEFAULT_FLOW_TIMEOUT));

    let now = Instant::now();

    let packets = vec![
        PacketMeta {
            flow: FlowKey {
                src_ip: "10.0.0.1".parse().unwrap(),
                dst_ip: "10.0.0.2".parse().unwrap(),
                src_port: 12345,
                dst_port: 443,
                proto: 6,
            },
            bytes: 1500,
            timestamp: now,
            tcp_syn: true,
            tcp_fin: false,
            tcp_rst: false,
        },
        PacketMeta {
            flow: FlowKey {
                src_ip: "10.0.0.1".parse().unwrap(),
                dst_ip: "10.0.0.2".parse().unwrap(),
                src_port: 12345,
                dst_port: 443,
                proto: 6,
            },
            bytes: 900,
            timestamp: now + Duration::from_millis(1),
            tcp_syn: false,
            tcp_fin: false,
            tcp_rst: false,
        },
    ];

    for pkt in packets {
        table.ingest(pkt);
    }

    let expired = table.expire(Instant::now() + Duration::from_secs(120));
    println!("expired flows: {}", expired);

    for (key, stats) in table.snapshot() {
        println!("{:?} => {:?}", key, stats);
    }
}
