#include <arpa/inet.h>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <atomic>
#include <thread>
#include <mutex>

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t header_checksum;
    uint32_t src_addr;
    uint32_t dst_addr;
};

struct IPv6Header {
    uint32_t ver_tc_fl;
    uint16_t payload_len;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src_addr[16];
    uint8_t dst_addr[16];
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

enum class L3Type : uint8_t {
    IPv4,
    IPv6,
    Unknown
};

struct FlowKey {
    L3Type l3;
    uint8_t proto; // TCP/UDP/other
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4 or IPv6 endpoints
    uint8_t src_ip[16];
    uint8_t dst_ip[16];

    bool operator==(const FlowKey& other) const noexcept {
        return l3 == other.l3 &&
               proto == other.proto &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               std::memcmp(src_ip, other.src_ip, 16) == 0 &&
               std::memcmp(dst_ip, other.dst_ip, 16) == 0;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast-ish hash for initial implementation
        size_t h = 1469598103934665603ULL;
        auto mix = [&](const void* data, size_t len) {
            const uint8_t* p = static_cast<const uint8_t*>(data);
            for (size_t i = 0; i < len; ++i) {
                h ^= p[i];
                h *= 1099511628211ULL;
            }
        };
        mix(&k.l3, sizeof(k.l3));
        mix(&k.proto, sizeof(k.proto));
        mix(&k.src_port, sizeof(k.src_port));
        mix(&k.dst_port, sizeof(k.dst_port));
        mix(k.src_ip, 16);
        mix(k.dst_ip, 16);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(uint64_t flow_timeout_ns = 60ULL * 1000 * 1000 * 1000)
        : flow_timeout_ns_(flow_timeout_ns) {
        flows_.reserve(1 << 20); // reserve for scale; tune for deployment
    }

    void process_packet(const uint8_t* data, size_t len, uint64_t now_ns) {
        if (len < sizeof(EthernetHeader)) return;

        const EthernetHeader* eth = reinterpret_cast<const EthernetHeader*>(data);
        uint16_t ethertype = ntohs(eth->ethertype);

        size_t offset = sizeof(EthernetHeader);

        if (ethertype == 0x8100) { // VLAN
            if (len < offset + 4) return;
            ethertype = ntohs(*reinterpret_cast<const uint16_t*>(data + offset + 2));
            offset += 4;
        }

        FlowKey key{};
        key.l3 = L3Type::Unknown;

        if (ethertype == 0x0800) {
            if (len < offset + sizeof(IPv4Header)) return;
            const IPv4Header* ip = reinterpret_cast<const IPv4Header*>(data + offset);
            uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
            if (ihl < 20 || len < offset + ihl) return;

            key.l3 = L3Type::IPv4;
            std::memset(key.src_ip, 0, 16);
            std::memset(key.dst_ip, 0, 16);
            std::memcpy(key.src_ip, &ip->src_addr, 4);
            std::memcpy(key.dst_ip, &ip->dst_addr, 4);
            key.proto = ip->protocol;

            offset += ihl;
            if (key.proto == 6) { // TCP
                if (len < offset + sizeof(TCPHeader)) return;
                const TCPHeader* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
                key.src_port = ntohs(tcp->src_port);
                key.dst_port = ntohs(tcp->dst_port);
            } else if (key.proto == 17) { // UDP
                if (len < offset + sizeof(UDPHeader)) return;
                const UDPHeader* udp = reinterpret_cast<const UDPHeader*>(data + offset);
                key.src_port = ntohs(udp->src_port);
                key.dst_port = ntohs(udp->dst_port);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }
        } else if (ethertype == 0x86DD) {
            if (len < offset + sizeof(IPv6Header)) return;
            const IPv6Header* ip6 = reinterpret_cast<const IPv6Header*>(data + offset);

            key.l3 = L3Type::IPv6;
            std::memcpy(key.src_ip, ip6->src_addr, 16);
            std::memcpy(key.dst_ip, ip6->dst_addr, 16);
            key.proto = ip6->next_header;

            offset += sizeof(IPv6Header);
            if (key.proto == 6) {
                if (len < offset + sizeof(TCPHeader)) return;
                const TCPHeader* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
                key.src_port = ntohs(tcp->src_port);
                key.dst_port = ntohs(tcp->dst_port);
            } else if (key.proto == 17) {
                if (len < offset + sizeof(UDPHeader)) return;
                const UDPHeader* udp = reinterpret_cast<const UDPHeader*>(data + offset);
                key.src_port = ntohs(udp->src_port);
                key.dst_port = ntohs(udp->dst_port);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }
        } else {
            return;
        }

        // Normalize flow direction for bidirectional aggregation
        normalize_key(key);

        auto it = flows_.find(key);
        if (it == flows_.end()) {
            FlowStats stats;
            stats.packets = 1;
            stats.bytes = len;
            stats.first_seen_ns = now_ns;
            stats.last_seen_ns = now_ns;
            flows_.emplace(std::move(key), stats);
        } else {
            it->second.packets++;
            it->second.bytes += len;
            it->second.last_seen_ns = now_ns;
        }

        if ((packet_counter_++ & 0xFFFF) == 0) {
            expire_flows(now_ns);
        }
    }

    void export_flows() const {
        for (const auto& [key, stats] : flows_) {
            std::cout << flow_to_string(key) << " packets=" << stats.packets
                      << " bytes=" << stats.bytes << "\n";
        }
    }

private:
    void normalize_key(FlowKey& key) const noexcept {
        // Canonical ordering to merge A->B and B->A
        if (compare_endpoints(key.dst_ip, key.src_ip, key.dst_port, key.src_port) < 0) {
            std::swap(key.src_ip, key.dst_ip);
            std::swap(key.src_port, key.dst_port);
        }
    }

    static int compare_endpoints(const uint8_t* ip1, const uint8_t* ip2,
                                 uint16_t p1, uint16_t p2) noexcept {
        int cmp = std::memcmp(ip1, ip2, 16);
        if (cmp != 0) return cmp;
        return (p1 < p2) ? -1 : (p1 > p2 ? 1 : 0);
    }

    void expire_flows(uint64_t now_ns) {
        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_ns - it->second.last_seen_ns > flow_timeout_ns_) {
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
    }

    static std::string flow_to_string(const FlowKey& key) {
        char src[INET6_ADDRSTRLEN] = {0};
        char dst[INET6_ADDRSTRLEN] = {0};

        if (key.l3 == L3Type::IPv4) {
            inet_ntop(AF_INET, key.src_ip, src, sizeof(src));
            inet_ntop(AF_INET, key.dst_ip, dst, sizeof(dst));
        } else if (key.l3 == L3Type::IPv6) {
            inet_ntop(AF_INET6, key.src_ip, src, sizeof(src));
            inet_ntop(AF_INET6, key.dst_ip, dst, sizeof(dst));
        } else {
            std::snprintf(src, sizeof(src), "unknown");
            std::snprintf(dst, sizeof(dst), "unknown");
        }

        return std::string(src) + ":" + std::to_string(key.src_port) +
               " <-> " + dst + ":" + std::to_string(key.dst_port) +
               " proto=" + std::to_string(key.proto);
    }

private:
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
    uint64_t flow_timeout_ns_;
    std::atomic<uint64_t> packet_counter_{0};
};
```

