use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const FLOW_TIMEOUT: Duration = Duration::from_secs(60);

#[derive(Clone, Copy, Debug, Eq)]
pub enum FlowKey {
    V4 {
        src: Ipv4Addr,
        dst: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
    V6 {
        src: Ipv6Addr,
        dst: Ipv6Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (
                FlowKey::V4 {
                    src: a1,
                    dst: a2,
                    src_port: a3,
                    dst_port: a4,
                    proto: a5,
                },
                FlowKey::V4 {
                    src: b1,
                    dst: b2,
                    src_port: b3,
                    dst_port: b4,
                    proto: b5,
                },
            ) => a1 == b1 && a2 == b2 && a3 == b3 && a4 == b4 && a5 == b5,
            (
                FlowKey::V6 {
                    src: a1,
                    dst: a2,
                    src_port: a3,
                    dst_port: a4,
                    proto: a5,
                },
                FlowKey::V6 {
                    src: b1,
                    dst: b2,
                    src_port: b3,
                    dst_port: b4,
                    proto: b5,
                },
            ) => a1 == b1 && a2 == b2 && a3 == b3 && a4 == b4 && a5 == b5,
            _ => false,
        }
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            FlowKey::V4 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            } => {
                4u8.hash(state);
                src.hash(state);
                dst.hash(state);
                src_port.hash(state);
                dst_port.hash(state);
                proto.hash(state);
            }
            FlowKey::V6 {
                src,
                dst,
                src_port,
                dst_port,
                proto,
            } => {
                6u8.hash(state);
                src.hash(state);
                dst.hash(state);
                src_port.hash(state);
                dst_port.hash(state);
                proto.hash(state);
            }
        }
    }
}

#[derive(Debug, Clone)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    pub fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    pub fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

pub struct FlowShard {
    table: Mutex<HashMap<FlowKey, FlowStats>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            table: Mutex::new(HashMap::with_capacity(16_384)),
        }
    }
}

pub struct FlowAnalyzer {
    shards: Vec<FlowShard>,
    flow_timeout: Duration,
}

impl FlowAnalyzer {
    pub fn new() -> Arc<Self> {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(FlowShard::new());
        }

        Arc::new(Self {
            shards,
            flow_timeout: FLOW_TIMEOUT,
        })
    }

    #[inline]
    fn shard_index(key: &FlowKey) -> usize {
        use std::collections::hash_map::DefaultHasher;
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & (NUM_SHARDS - 1)
    }

    pub fn ingest_packet(&self, packet: &[u8], now: Instant) {
        if let Some((key, payload_len)) = parse_packet(packet) {
            let shard_idx = Self::shard_index(&key);
            let shard = &self.shards[shard_idx];

            let mut table = shard.table.lock().unwrap();
            match table.get_mut(&key) {
                Some(stats) => stats.update(now, payload_len),
                None => {
                    table.insert(key, FlowStats::new(now, payload_len));
                }
            }
        }
    }

    pub fn expire_flows(&self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut table = shard.table.lock().unwrap();
            let timeout = self.flow_timeout;

            let mut to_remove = Vec::new();
            for (key, stats) in table.iter() {
                if now.duration_since(stats.last_seen) >= timeout {
                    to_remove.push(*key);
                }
            }

            for key in to_remove {
                if let Some(stats) = table.remove(&key) {
                    expired.push((key, stats));
                }
            }
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let table = shard.table.lock().unwrap();
            all.extend(table.iter().map(|(k, v)| (*k, v.clone())));
        }
        all
    }
}

/// Very minimal packet parser:
/// Assumes Ethernet + IPv4/IPv6 + TCP/UDP.
/// Returns (flow key, packet length).
///
/// NOTE: This is intentionally initial/simplified and should be replaced
/// with a zero-copy parser for production.
fn parse_packet(packet: &[u8]) -> Option<(FlowKey, usize)> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    let mut offset = 14;

    match ethertype {
        0x0800 => parse_ipv4(packet, offset),
        0x86DD => parse_ipv6(packet, offset),
        _ => None,
    }
}

fn parse_ipv4(packet: &[u8], offset: usize) -> Option<(FlowKey, usize)> {
    if packet.len() < offset + 20 {
        return None;
    }

    let version_ihl = packet[offset];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0F) as usize * 4;
    if version != 4 || packet.len() < offset + ihl {
        return None;
    }

    let proto = packet[offset + 9];
    let src = Ipv4Addr::new(
        packet[offset + 12],
        packet[offset + 13],
        packet[offset + 14],
        packet[offset + 15],
    );
    let dst = Ipv4Addr::new(
        packet[offset + 16],
        packet[offset + 17],
        packet[offset + 18],
        packet[offset + 19],
    );

    let l4_offset = offset + ihl;
    if packet.len() < l4_offset + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);

    Some((
        FlowKey::V4 {
            src,
            dst,
            src_port,
            dst_port,
            proto,
        },
        packet.len(),
    ))
}

fn parse_ipv6(packet: &[u8], offset: usize) -> Option<(FlowKey, usize)> {
    if packet.len() < offset + 40 {
        return None;
    }

    let next_header = packet[offset + 6];
    let src = Ipv6Addr::from([
        packet[offset + 8],
        packet[offset + 9],
        packet[offset + 10],
        packet[offset + 11],
        packet[offset + 12],
        packet[offset + 13],
        packet[offset + 14],
        packet[offset + 15],
        packet[offset + 16],
        packet[offset + 17],
        packet[offset + 18],
        packet[offset + 19],
        packet[offset + 20],
        packet[offset + 21],
        packet[offset + 22],
        packet[offset + 23],
    ]);
    let dst = Ipv6Addr::from([
        packet[offset + 24],
        packet[offset + 25],
        packet[offset + 26],
        packet[offset + 27],
        packet[offset + 28],
        packet[offset + 29],
        packet[offset + 30],
        packet[offset + 31],
        packet[offset + 32],
        packet[offset + 33],
        packet[offset + 34],
        packet[offset + 35],
        packet[offset + 36],
        packet[offset + 37],
        packet[offset + 38],
        packet[offset + 39],
    ]);

    let l4_offset = offset + 40;
    if packet.len() < l4_offset + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);

    Some((
        FlowKey::V6 {
            src,
            dst,
            src_port,
            dst_port,
            proto: next_header,
        },
        packet.len(),
    ))
}
