use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::env;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn canonical_flow_key(
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
) -> FlowKey {
    // Bidirectional normalization: smaller endpoint first
    let a = (src_ip.octets(), src_port);
    let b = (dst_ip.octets(), dst_port);

    if a <= b {
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        }
    } else {
        FlowKey {
            src_ip: dst_ip,
            dst_ip: src_ip,
            src_port: dst_port,
            dst_port: src_port,
            proto,
        }
    }
}

fn parse_packet(data: &[u8]) -> Option<(FlowKey, usize)> {
    // Ethernet header: 14 bytes
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only
    }

    let ip = &data[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([ip[2], ip[3]]) as usize;
    if total_len < ihl || ip.len() < total_len {
        return None;
    }

    let proto = ip[9];
    let src_ip = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
    let dst_ip = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

    let l4 = &ip[ihl..];
    let (src_port, dst_port) = match proto {
        6 | 17 => {
            if l4.len() < 4 {
                return None;
            }
            (
                u16::from_be_bytes([l4[0], l4[1]]),
                u16::from_be_bytes([l4[2], l4[3]]),
            )
        }
        _ => return None,
    };

    let key = canonical_flow_key(src_ip, dst_ip, src_port, dst_port, proto);
    Some((key, total_len + 14))
}

fn main() -> anyhow::Result<()> {
    let iface = env::args().nth(1).unwrap_or_else(|| {
        eprintln!("Usage: flow_analyzer <interface>");
        std::process::exit(1);
    });

    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == iface)
        .expect("Interface not found");

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .open()?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let expire_after = Duration::from_secs(30);
    let mut last_cleanup = Instant::now();

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();

                if let Some((key, bytes)) = parse_packet(packet.data) {
                    let entry = flows.entry(key).or_insert(FlowStats {
                        packets: 0,
                        bytes: 0,
                        first_seen: now,
                        last_seen: now,
                    });

                    entry.packets += 1;
                    entry.bytes += bytes as u64;
                    entry.last_seen = now;
                }

                if last_cleanup.elapsed() >= Duration::from_secs(5) {
                    let cutoff = Instant::now() - expire_after;
                    flows.retain(|key, stat| {
                        if stat.last_seen < cutoff {
                            println!(
                                "FLOW {:?} packets={} bytes={} duration_ms={}",
                                key,
                                stat.packets,
                                stat.bytes,
                                stat.last_seen.duration_since(stat.first_seen).as_millis()
                            );
                            false
                        } else {
                            true
                        }
                    });
                    last_cleanup = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => return Err(e.into()),
        }
    }
}
