use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn parse_packet(pkt: &[u8]) -> Option<(FlowKey, usize)> {
    // Ethernet header = 14 bytes
    if pkt.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only
    }

    let ip = &pkt[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    // TCP/UDP ports
    if proto != 6 && proto != 17 {
        return None;
    }

    if ip.len() < ihl + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([ip[ihl], ip[ihl + 1]]);
    let dst_port = u16::from_be_bytes([ip[ihl + 2], ip[ihl + 3]]);

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Some((key, pkt.len()))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let device = Device::lookup()?
        .ok_or("No default capture device found")?;

    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .open()?;

    // Optional BPF filter to reduce load
    cap.filter("tcp or udp", true)?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let mut last_report = Instant::now();

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();

                if let Some((key, len)) = parse_packet(packet.data) {
                    flows
                        .entry(key)
                        .and_modify(|f| {
                            f.packets += 1;
                            f.bytes += len as u64;
                            f.last_seen = now;
                        })
                        .or_insert(FlowStats {
                            packets: 1,
                            bytes: len as u64,
                            first_seen: now,
                            last_seen: now,
                        });
                }

                if last_report.elapsed() >= Duration::from_secs(1) {
                    report(&flows);
                    last_report = Instant::now();
                }
            }
            Err(e) => {
                eprintln!("Capture error: {e}");
            }
        }
    }
}

fn report(flows: &HashMap<FlowKey, FlowStats>) {
    println!("--- active flows: {} ---", flows.len());

    for (k, v) in flows.iter().take(20) {
        let src = Ipv4Addr::from(k.src_ip);
        let dst = Ipv4Addr::from(k.dst_ip);
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} age_ms={}",
            src,
            k.src_port,
            dst,
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes,
            v.last_seen.duration_since(v.first_seen).as_millis()
        );
    }
}
