## 2) Minimal C implementation

### `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <netinet/in.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>

#ifndef TPACKET_V3
#define TPACKET_V3 3
#endif

#define MAX_FLOWS       (1 << 20)   // 1M entries
#define HASH_SIZE       (1 << 20)   // must be power of two
#define BATCH_TIMEOUT_MS 100
#define PRINT_INTERVAL_S 5

typedef struct {
    uint32_t saddr;
    uint32_t daddr;
    uint16_t sport;
    uint16_t dport;
    uint8_t  proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ns;
    uint64_t last_ns;
    uint8_t used;
} flow_entry_t;

static flow_entry_t *flows;
static volatile sig_atomic_t running = 1;

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    // Fast-ish 32-bit mix
    uint32_t h = k->saddr ^ (k->daddr * 0x9e3779b1u);
    h ^= ((uint32_t)k->sport << 16) | k->dport;
    h ^= (uint32_t)k->proto * 0x85ebca6bu;
    h ^= h >> 16;
    h *= 0x7feb352du;
    h ^= h >> 15;
    h *= 0x846ca68bu;
    h ^= h >> 16;
    return h;
}

static inline int flow_key_eq(const flow_key_t *a, const flow_key_t *b) {
    return a->saddr == b->saddr &&
           a->daddr == b->daddr &&
           a->sport == b->sport &&
           a->dport == b->dport &&
           a->proto == b->proto;
}

static flow_entry_t *flow_get_or_create(const flow_key_t *k, uint64_t ts_ns) {
    uint32_t idx = hash_flow(k) & (HASH_SIZE - 1);

    for (uint32_t n = 0; n < HASH_SIZE; n++) {
        flow_entry_t *e = &flows[idx];
        if (!e->used) {
            e->used = 1;
            e->key = *k;
            e->packets = 0;
            e->bytes = 0;
            e->first_ns = ts_ns;
            e->last_ns = ts_ns;
            return e;
        }
        if (flow_key_eq(&e->key, k)) {
            return e;
        }
        idx = (idx + 1) & (HASH_SIZE - 1);
    }
    return NULL; // table full
}

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

static int get_ifindex_and_mtu(const char *ifname, int *ifindex, int *mtu) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        close(fd);
        return -1;
    }
    *ifindex = ifr.ifr_ifindex;

    if (ioctl(fd, SIOCGIFMTU, &ifr) < 0) {
        close(fd);
        return -1;
    }
    *mtu = ifr.ifr_mtu;

    close(fd);
    return 0;
}

static void print_top_flows(void) {
    // Minimal: print flows with highest packet counts
    // O(N) scan; acceptable for a minimal version.
    typedef struct {
        flow_entry_t *e;
    } ref_t;

    ref_t *top = calloc(10, sizeof(ref_t));
    if (!top) return;

    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = &flows[i];
        if (!e->used) continue;

        for (int j = 0; j < 10; j++) {
            if (!top[j].e || e->packets > top[j].e->packets) {
                for (int k = 9; k > j; k--) top[k] = top[k - 1];
                top[j].e = e;
                break;
            }
        }
    }

    printf("\n=== Top flows ===\n");
    for (int i = 0; i < 10; i++) {
        if (!top[i].e) break;
        flow_entry_t *e = top[i].e;

        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        struct in_addr sa = { .s_addr = e->key.saddr };
        struct in_addr da = { .s_addr = e->key.daddr };

        inet_ntop(AF_INET, &sa, src, sizeof(src));
        inet_ntop(AF_INET, &da, dst, sizeof(dst));

        printf("%2d) %s:%u -> %s:%u proto=%u packets=%lu bytes=%lu\n",
               i + 1,
               src, ntohs(e->key.sport),
               dst, ntohs(e->key.dport),
               e->key.proto,
               (unsigned long)e->packets,
               (unsigned long)e->bytes);
    }

    free(top);
}

static void process_packet(const uint8_t *pkt, size_t len, uint64_t ts_ns) {
    if (len < sizeof(struct ethhdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    uint16_t eth_type = ntohs(eth->h_proto);

    if (eth_type != ETH_P_IP) return;

    const uint8_t *p = pkt + sizeof(struct ethhdr);
    size_t remain = len - sizeof(struct ethhdr);

    if (remain < sizeof(struct iphdr)) return;
    const struct iphdr *ip = (const struct iphdr *)p;

    if (ip->version != 4) return;
    size_t ip_hl = ip->ihl * 4;
    if (remain < ip_hl) return;

    uint8_t proto = ip->protocol;
    uint32_t saddr = ip->saddr;
    uint32_t daddr = ip->daddr;

    uint16_t sport = 0, dport = 0;
    const uint8_t *l4 = p + ip_hl;
    size_t l4_len = remain - ip_hl;

    if (proto == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        sport = tcp->source;
        dport = tcp->dest;
    } else if (proto == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        sport = udp->source;
        dport = udp->dest;
    } else {
        // For non-TCP/UDP, use ports 0
    }

    flow_key_t key = {
        .saddr = saddr,
        .daddr = daddr,
        .sport = sport,
        .dport = dport,
        .proto = proto
    };

    flow_entry_t *e = flow_get_or_create(&key, ts_ns);
    if (!e) return;

    e->packets++;
    e->bytes += len;
    e->last_ns = ts_ns;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <iface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    const char *ifname = argv[1];
    int ifindex, mtu;
    if (get_ifindex_and_mtu(ifname, &ifindex, &mtu) < 0) {
        perror("interface lookup");
        return 1;
    }

    flows = aligned_alloc(64, sizeof(flow_entry_t) * HASH_SIZE);
    if (!flows) {
        perror("alloc flows");
        return 1;
    }
    memset(flows, 0, sizeof(flow_entry_t) * HASH_SIZE);

    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    int ver = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &ver, sizeof(ver)) < 0) {
        perror("PACKET_VERSION");
        return 1;
    }

    int fanout = 0;
    if (setsockopt(fd, SOL_PACKET, PACKET_FANOUT, &fanout, sizeof(fanout)) < 0) {
        // optional; ignore if not needed
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;
    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return 1;
    }

    // Ring buffer setup
    size_t frame_size = 2048;
    size_t block_size = 1 << 20; // 1 MiB
    size_t block_nr = 64;        // 64 MiB total ring
    size_t frame_nr = (block_size * block_nr) / frame_size;

    struct tpacket_req3 req = {0};
    req.tp_block_size = block_size;
    req.tp_block_nr = block_nr;
    req.tp_frame_size = frame_size;
    req.tp_frame_nr = frame_nr;
    req.tp_retire_blk_tov = BATCH_TIMEOUT_MS;
    req.tp_feature_req_word = TP_FT_REQ_FILL_RXHASH;

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("PACKET_RX_RING");
        return 1;
    }

    size_t ring_size = req.tp_block_size * req.tp_block_nr;
    uint8_t *ring = mmap(NULL, ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (ring == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    struct pollfd pfd = { .fd = fd, .events = POLLIN };
    uint64_t last_print = now_ns();
    uint64_t print_interval_ns = PRINT_INTERVAL_S * 1000000000ULL;

    while (running) {
        int rc = poll(&pfd, 1, 100);
        if (rc < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }

        // Walk blocks
        for (size_t b = 0; b < req.tp_block_nr; b++) {
            struct tpacket_block_desc *bd = (struct tpacket_block_desc *)(ring + b * req.tp_block_size);
            if (!(bd->hdr.bh1.block_status & TP_STATUS_USER)) continue;

            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)bd + bd->hdr.bh1.offset_to_first_pkt);
            for (uint32_t i = 0; i < bd->hdr.bh1.num_pkts; i++) {
                uint8_t *pkt = (uint8_t *)ppd + ppd->tp_mac;
                size_t len = ppd->tp_snaplen;
                uint64_t ts_ns = (uint64_t)ppd->tp_sec * 1000000000ULL + ppd->tp_nsec;
                process_packet(pkt, len, ts_ns);

                ppd = (struct tpacket3_hdr *)((uint8_t *)ppd + ppd->tp_next_offset);
            }

            bd->hdr.bh1.block_status = TP_STATUS_KERNEL;
        }

        uint64_t t = now_ns();
        if (t - last_print >= print_interval_ns) {
            print_top_flows();
            last_print = t;
        }
    }

    munmap(ring, ring_size);
    close(fd);
    free(flows);
    return 0;
}
```

