### `src/main.rs`
```rust
use std::{
    collections::hash_map::DefaultHasher,
    hash::{Hash, Hasher},
    net::{IpAddr, Ipv4Addr, Ipv6Addr},
    sync::Arc,
    thread,
    time::{Duration, Instant},
};

use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use parking_lot::RwLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum FlowAddr {
    V4(Ipv4Addr),
    V6(Ipv6Addr),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src: FlowAddr,
    dst: FlowAddr,
    proto: u8,
    src_port: u16,
    dst_port: u16,
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u128,
    last_seen_ns: u128,
    tcp_syn: u64,
    tcp_fin: u64,
    tcp_rst: u64,
}

impl FlowStats {
    fn update(&mut self, pkt_len: usize, now_ns: u128, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += pkt_len as u64;
        if self.first_seen_ns == 0 {
            self.first_seen_ns = now_ns;
        }
        self.last_seen_ns = now_ns;

        if let Some(flags) = tcp_flags {
            if flags & 0x02 != 0 { self.tcp_syn += 1; }
            if flags & 0x01 != 0 { self.tcp_fin += 1; }
            if flags & 0x04 != 0 { self.tcp_rst += 1; }
        }
    }
}

type FlowTable = Arc<RwLock<HashMap<FlowKey, FlowStats>>>;

#[derive(Debug)]
struct PacketEvent {
    key: FlowKey,
    len: usize,
    now_ns: u128,
    tcp_flags: Option<u8>,
}

fn now_ns() -> u128 {
    Instant::now().elapsed().as_nanos()
}

fn parse_packet(data: &[u8]) -> Option<PacketEvent> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    let (src, dst, proto, src_port, dst_port, tcp_flags) = match (sliced.ip, sliced.transport) {
        (Some(InternetSlice::Ipv4(h, _)), Some(TransportSlice::Tcp(tcp))) => {
            let src = FlowAddr::V4(Ipv4Addr::from(h.source()));
            let dst = FlowAddr::V4(Ipv4Addr::from(h.destination()));
            (src, dst, 6u8, tcp.source_port(), tcp.destination_port(), Some(tcp.flags()))
        }
        (Some(InternetSlice::Ipv4(h, _)), Some(TransportSlice::Udp(udp))) => {
            let src = FlowAddr::V4(Ipv4Addr::from(h.source()));
            let dst = FlowAddr::V4(Ipv4Addr::from(h.destination()));
            (src, dst, 17u8, udp.source_port(), udp.destination_port(), None)
        }
        (Some(InternetSlice::Ipv6(h, _)), Some(TransportSlice::Tcp(tcp))) => {
            let src = FlowAddr::V6(Ipv6Addr::from(h.source()));
            let dst = FlowAddr::V6(Ipv6Addr::from(h.destination()));
            (src, dst, 6u8, tcp.source_port(), tcp.destination_port(), Some(tcp.flags()))
        }
        (Some(InternetSlice::Ipv6(h, _)), Some(TransportSlice::Udp(udp))) => {
            let src = FlowAddr::V6(Ipv6Addr::from(h.source()));
            let dst = FlowAddr::V6(Ipv6Addr::from(h.destination()));
            (src, dst, 17u8, udp.source_port(), udp.destination_port(), None)
        }
        _ => return None,
    };

    Some(PacketEvent {
        key: FlowKey {
            src,
            dst,
            proto,
            src_port,
            dst_port,
        },
        len: data.len(),
        now_ns: now_ns(),
        tcp_flags,
    })
}

fn worker(rx: Receiver<PacketEvent>, flows: FlowTable) {
    while let Ok(pkt) = rx.recv() {
        let mut table = flows.write();
        let entry = table.entry(pkt.key).or_default();
        entry.update(pkt.len, pkt.now_ns, pkt.tcp_flags);
    }
}

fn exporter(flows: FlowTable, interval: Duration) {
    loop {
        thread::sleep(interval);

        let snapshot = {
            let table = flows.read();
            table.iter().map(|(k, v)| (*k, v.clone())).collect::<Vec<_>>()
        };

        if snapshot.is_empty() {
            println!("No active flows");
            continue;
        }

        let mut top = snapshot;
        top.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));

        println!("\n=== Flow summary: {} active flows ===", top.len());
        for (key, stats) in top.iter().take(10) {
            println!(
                "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} syn={} fin={} rst={}",
                key.src,
                key.src_port,
                key.dst,
                key.dst_port,
                key.proto,
                stats.packets,
                stats.bytes,
                stats.tcp_syn,
                stats.tcp_fin,
                stats.tcp_rst
            );
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let iface = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());

    let flows: FlowTable = Arc::new(RwLock::new(HashMap::with_capacity(1 << 20)));
    let (tx, rx): (Sender<PacketEvent>, Receiver<PacketEvent>) = bounded(100_000);

    // Worker thread
    {
        let flows = flows.clone();
        thread::spawn(move || worker(rx, flows));
    }

    // Exporter thread
    {
        let flows = flows.clone();
        thread::spawn(move || exporter(flows, Duration::from_secs(5)));
    }

    // Capture loop
    let mut cap = pcap::Capture::from_device(iface.as_str())?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(2048)
        .open()?;

    println!("Capturing on interface: {}", iface);

    while let Ok(packet) = cap.next_packet() {
        if let Some(evt) = parse_packet(packet.data) {
            // Drop packets if overloaded rather than blocking capture
            let _ = tx.try_send(evt);
        }
    }

    Ok(())
}
```

