## 2) Minimal working C++17 implementation

This example uses **libpcap** for portability.  
For real gigabit-scale deployment, swap capture backend with **PF_RING**, **DPDK**, or **AF_PACKET/TPACKET_V3**.

### `flow_analyzer.cpp`
```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <cstdint>
#include <cstring>
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <atomic>

#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast hash mix
        uint64_t x = ((uint64_t)k.src_ip << 32) ^ k.dst_ip;
        x ^= ((uint64_t)k.src_port << 16) ^ k.dst_port;
        x ^= (uint64_t)k.proto << 56;
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_us = 0;
    uint64_t last_seen_us = 0;
};
#pragma pack(pop)

using FlowTable = std::unordered_map<FlowKey, FlowStats, FlowKeyHash>;

static inline uint64_t now_us() {
    using namespace std::chrono;
    return duration_cast<microseconds>(
        steady_clock::now().time_since_epoch()
    ).count();
}

static inline bool parse_packet(const u_char* pkt, int len, FlowKey& key, uint32_t& payload_len) {
    if (len < (int)sizeof(ether_header)) return false;

    const ether_header* eth = reinterpret_cast<const ether_header*>(pkt);
    uint16_t eth_type = ntohs(eth->ether_type);

    // Only IPv4 for minimal version
    if (eth_type != ETHERTYPE_IP) return false;

    const u_char* ip_ptr = pkt + sizeof(ether_header);
    if (len < (int)(sizeof(ether_header) + sizeof(iphdr))) return false;

    const iphdr* ip = reinterpret_cast<const iphdr*>(ip_ptr);
    if (ip->version != 4) return false;

    int ip_header_len = ip->ihl * 4;
    if (ip_header_len < 20) return false;
    if (len < (int)(sizeof(ether_header) + ip_header_len)) return false;

    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;
    key.src_port = 0;
    key.dst_port = 0;

    const u_char* l4 = ip_ptr + ip_header_len;
    int l4_len = len - (sizeof(ether_header) + ip_header_len);

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < (int)sizeof(tcphdr)) return false;
        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4);
        key.src_port = ntohs(tcp->source);
        key.dst_port = ntohs(tcp->dest);
        payload_len = ntohs(ip->tot_len) - ip_header_len - tcp->doff * 4;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < (int)sizeof(udphdr)) return false;
        const udphdr* udp = reinterpret_cast<const udphdr*>(l4);
        key.src_port = ntohs(udp->source);
        key.dst_port = ntohs(udp->dest);
        payload_len = ntohs(udp->len) - sizeof(udphdr);
    } else {
        payload_len = ntohs(ip->tot_len) - ip_header_len;
    }

    return true;
}

static void expire_flows(FlowTable& table, uint64_t idle_timeout_us) {
    const uint64_t t = now_us();
    for (auto it = table.begin(); it != table.end(); ) {
        if (t - it->second.last_seen_us > idle_timeout_us) {
            // Minimal export: print and erase
            const auto& k = it->first;
            const auto& s = it->second;
            std::cout
                << inet_ntoa(*(in_addr*)&k.src_ip) << ":" << k.src_port
                << " -> "
                << inet_ntoa(*(in_addr*)&k.dst_ip) << ":" << k.dst_port
                << " proto=" << (int)k.proto
                << " packets=" << s.packets
                << " bytes=" << s.bytes
                << "\n";
            it = table.erase(it);
        } else {
            ++it;
        }
    }
}

static void packet_handler(u_char* user, const struct pcap_pkthdr* h, const u_char* bytes) {
    FlowTable* table = reinterpret_cast<FlowTable*>(user);

    FlowKey key{};
    uint32_t payload_len = 0;

    if (!parse_packet(bytes, h->caplen, key, payload_len)) return;

    uint64_t ts_us = (uint64_t)h->ts.tv_sec * 1000000ULL + (uint64_t)h->ts.tv_usec;

    auto& flow = (*table)[key];
    if (flow.packets == 0) {
        flow.first_seen_us = ts_us;
    }
    flow.packets++;
    flow.bytes += h->len;
    flow.last_seen_us = ts_us;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    const char* dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];

    pcap_t* handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Optional: reduce overhead
    pcap_set_immediate_mode(handle, 1);

    FlowTable flows;
    flows.reserve(1 << 20); // reserve for scale

    std::atomic<bool> running{true};

    // Simple aging thread
    std::thread aging([&]() {
        while (running.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            expire_flows(flows, 30ULL * 1000000ULL); // 30s idle timeout
        }
    });

    std::cout << "Starting capture on " << dev << "\n";
    if (pcap_loop(handle, -1, packet_handler, reinterpret_cast<u_char*>(&flows)) < 0) {
        std::cerr << "pcap_loop error: " << pcap_geterr(handle) << "\n";
    }

    running.store(false);
    aging.join();
    pcap_close(handle);
    return 0;
}
```

