use std::hash::{Hash, Hasher};
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::unix::io::RawFd;
use std::time::{Duration, Instant};

const ETH_P_ALL: u16 = 0x0003;
const ETH_HDR_LEN: usize = 14;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    dscp_ecn: u8,
    total_len: u16,
    id: u16,
    flags_frag: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: [u8; 4],
    dst: [u8; 4],
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    data_offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct UdpHdr {
    src_port: u16,
    dst_port: u16,
    len: u16,
    checksum: u16,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src: u32,
    dst: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn ntohs(v: u16) -> u16 {
    u16::from_be(v)
}

fn ntohl(v: u32) -> u32 {
    u32::from_be(v)
}

fn open_raw_socket(iface: &str) -> io::Result<RawFd> {
    unsafe {
        let fd = libc::socket(libc::AF_PACKET, libc::SOCK_RAW, i32::from(htons(ETH_P_ALL)));
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let ifname = std::ffi::CString::new(iface).unwrap();
        let ifindex = libc::if_nametoindex(ifname.as_ptr());
        if ifindex == 0 {
            return Err(io::Error::last_os_error());
        }

        let mut sll: libc::sockaddr_ll = mem::zeroed();
        sll.sll_family = libc::AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex as i32;

        let ret = libc::bind(
            fd,
            &sll as *const _ as *const libc::sockaddr,
            mem::size_of::<libc::sockaddr_ll>() as u32,
        );
        if ret < 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(fd)
    }
}

fn parse_ipv4(packet: &[u8]) -> Option<(FlowKey, usize)> {
    if packet.len() < ETH_HDR_LEN + 20 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &packet[ETH_HDR_LEN..];
    let ver_ihl = ip[0];
    let version = ver_ihl >> 4;
    let ihl = (ver_ihl & 0x0f) as usize * 4;
    if version != 4 || ihl < 20 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..];
    match proto {
        6 => {
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port,
                    dst_port,
                    proto,
                },
                packet.len(),
            ))
        }
        17 => {
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port,
                    dst_port,
                    proto,
                },
                packet.len(),
            ))
        }
        _ => None,
    }
}

fn print_flow(key: &FlowKey, stats: &FlowStats) {
    let src = Ipv4Addr::from(key.src);
    let dst = Ipv4Addr::from(key.dst);
    println!(
        "{}:{} -> {}:{} proto={} packets={} bytes={} age_ms={}",
        src,
        key.src_port,
        dst,
        key.dst_port,
        key.proto,
        stats.packets,
        stats.bytes,
        stats.last_seen.duration_since(stats.first_seen).as_millis()
    );
}

fn main() -> io::Result<()> {
    let iface = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());
    let fd = open_raw_socket(&iface)?;

    let mut buf = vec![0u8; 65536];
    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);

    let mut last_report = Instant::now();
    let report_interval = Duration::from_secs(5);

    loop {
        let n = unsafe {
            libc::recv(
                fd,
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0 as c_int,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }

        let packet = &buf[..n as usize];
        let now = Instant::now();

        if let Some((key, bytes)) = parse_ipv4(packet) {
            flows
                .entry(key)
                .and_modify(|s| s.update(now, bytes))
                .or_insert_with(|| FlowStats::new(now, bytes));
        }

        if last_report.elapsed() >= report_interval {
            println!("--- flow table size: {} ---", flows.len());
            for (k, v) in flows.iter().take(20) {
                print_flow(k, v);
            }
            last_report = Instant::now();
        }
    }
}
