## C implementation

### `flow_analyzer.c`
```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE 1048576   // 1M buckets
#define MAX_FLOWS  2000000

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_seen;
    struct timeval last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];
static volatile sig_atomic_t running = 1;

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = k->src_ip ^ (k->dst_ip * 16777619u);
    h ^= ((uint32_t)k->src_port << 16) | k->dst_port;
    h ^= (uint32_t)k->proto * 2654435761u;
    return h & (HASH_SIZE - 1);
}

static inline int key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static flow_entry_t *lookup_or_create(const flow_key_t *key, const struct timeval *ts) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (key_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_seen = *ts;
    e->last_seen = *ts;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_ip(uint32_t ip) {
    struct in_addr a;
    a.s_addr = ip;
    printf("%s", inet_ntoa(a));
}

static void dump_flows(void) {
    printf("\n=== Flow snapshot ===\n");
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            printf("%u.%u.%u.%u:%u -> %u.%u.%u.%u:%u proto=%u packets=%llu bytes=%llu\n",
                   (ntohl(e->key.src_ip) >> 24) & 0xff,
                   (ntohl(e->key.src_ip) >> 16) & 0xff,
                   (ntohl(e->key.src_ip) >> 8) & 0xff,
                   ntohl(e->key.src_ip) & 0xff,
                   ntohs(e->key.src_port),
                   (ntohl(e->key.dst_ip) >> 24) & 0xff,
                   (ntohl(e->key.dst_ip) >> 16) & 0xff,
                   (ntohl(e->key.dst_ip) >> 8) & 0xff,
                   ntohl(e->key.dst_ip) & 0xff,
                   ntohs(e->key.dst_port),
                   e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes);
            e = e->next;
        }
    }
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    const struct ether_header {
        uint8_t dst[6];
        uint8_t src[6];
        uint16_t type;
    } *eth = (const void *)bytes;

    if (ntohs(eth->type) != 0x0800) return; // IPv4 only

    const struct ip *ip = (const struct ip *)(bytes + sizeof(*eth));
    int ip_hl = ip->ip_hl * 4;
    if (ip->ip_v != 4 || ip_hl < 20) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto  = ip->ip_p;

    const u_char *l4 = (const u_char *)ip + ip_hl;

    if (ip->ip_p == IPPROTO_TCP) {
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (ip->ip_p == IPPROTO_UDP) {
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return; // only TCP/UDP in this minimal version
    }

    flow_entry_t *e = lookup_or_create(&key, &h->ts);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    e->last_seen = h->ts;
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *dev = NULL;
    char filter_exp[] = "ip";
    pcap_t *handle;
    struct bpf_program fp;
    bpf_u_int32 net = 0, mask = 0;

    signal(SIGINT, handle_sigint);

    if (argc > 1) dev = argv[1];
    else dev = pcap_lookupdev(errbuf);

    if (!dev) {
        fprintf(stderr, "No capture device found: %s\n", errbuf);
        return 1;
    }

    handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1 ||
        pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap filter setup failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    printf("Capturing on %s...\n", dev);

    time_t last_dump = time(NULL);

    while (running) {
        int rc = pcap_dispatch(handle, 1024, packet_handler, NULL);
        if (rc < 0) break;

        time_t now = time(NULL);
        if (now - last_dump >= 5) {
            dump_flows();
            last_dump = now;
        }
    }

    dump_flows();
    pcap_close(handle);
    return 0;
}
