## 2) Minimal working C implementation

### `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <netinet/ip6.h>
#include <time.h>
#include <signal.h>

#define HASH_SIZE 1048576   // 1M buckets, power of two
#define SNAPLEN    96       // enough for headers, keep capture cheap
#define TIMEOUT_MS  1000

typedef struct flow_key {
    uint8_t  ip_version;   // 4 or 6
    uint8_t  protocol;
    uint16_t src_port;
    uint16_t dst_port;
    union {
        struct in_addr  v4;
        struct in6_addr v6;
    } src_ip, dst_ip;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ts_ns;
    uint64_t last_ts_ns;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];
static volatile sig_atomic_t running = 1;

static inline uint64_t ts_to_ns(const struct timeval *tv) {
    return (uint64_t)tv->tv_sec * 1000000000ULL + (uint64_t)tv->tv_usec * 1000ULL;
}

static inline uint32_t hash_u32(uint32_t x) {
    x ^= x >> 16;
    x *= 0x7feb352d;
    x ^= x >> 15;
    x *= 0x846ca68b;
    x ^= x >> 16;
    return x;
}

static inline uint32_t hash_bytes(const void *data, size_t len) {
    const uint8_t *p = (const uint8_t *)data;
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < len; i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h;
}

static uint32_t flow_hash(const flow_key_t *k) {
    uint32_t h = 0;
    h ^= hash_u32(k->ip_version);
    h ^= hash_u32(k->protocol);
    h ^= hash_u32(k->src_port);
    h ^= hash_u32(k->dst_port);

    if (k->ip_version == 4) {
        h ^= hash_bytes(&k->src_ip.v4, sizeof(struct in_addr));
        h ^= hash_bytes(&k->dst_ip.v4, sizeof(struct in_addr));
    } else {
        h ^= hash_bytes(&k->src_ip.v6, sizeof(struct in6_addr));
        h ^= hash_bytes(&k->dst_ip.v6, sizeof(struct in6_addr));
    }
    return h & (HASH_SIZE - 1);
}

static int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    if (a->ip_version != b->ip_version ||
        a->protocol   != b->protocol   ||
        a->src_port   != b->src_port   ||
        a->dst_port   != b->dst_port) {
        return 0;
    }
    if (a->ip_version == 4) {
        return memcmp(&a->src_ip.v4, &b->src_ip.v4, sizeof(struct in_addr)) == 0 &&
               memcmp(&a->dst_ip.v4, &b->dst_ip.v4, sizeof(struct in_addr)) == 0;
    } else {
        return memcmp(&a->src_ip.v6, &b->src_ip.v6, sizeof(struct in6_addr)) == 0 &&
               memcmp(&a->dst_ip.v6, &b->dst_ip.v6, sizeof(struct in6_addr)) == 0;
    }
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, uint64_t ts_ns) {
    uint32_t idx = flow_hash(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_ts_ns = ts_ns;
    e->last_ts_ns = ts_ns;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_flow(const flow_entry_t *e) {
    char src[INET6_ADDRSTRLEN], dst[INET6_ADDRSTRLEN];

    if (e->key.ip_version == 4) {
        inet_ntop(AF_INET, &e->key.src_ip.v4, src, sizeof(src));
        inet_ntop(AF_INET, &e->key.dst_ip.v4, dst, sizeof(dst));
    } else {
        inet_ntop(AF_INET6, &e->key.src_ip.v6, src, sizeof(src));
        inet_ntop(AF_INET6, &e->key.dst_ip.v6, dst, sizeof(dst));
    }

    printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu first=%llu last=%llu\n",
           src, ntohs(e->key.src_port),
           dst, ntohs(e->key.dst_port),
           e->key.protocol,
           (unsigned long long)e->packets,
           (unsigned long long)e->bytes,
           (unsigned long long)e->first_ts_ns,
           (unsigned long long)e->last_ts_ns);
}

static void dump_flows(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        for (flow_entry_t *e = flow_table[i]; e; e = e->next) {
            if (e->packets > 0) print_flow(e);
        }
    }
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static void process_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    if (h->caplen < 14) return; // Ethernet header minimum

    const uint8_t *ptr = bytes;
    uint16_t ethertype = ntohs(*(uint16_t *)(ptr + 12));
    size_t offset = 14;

    flow_key_t key;
    memset(&key, 0, sizeof(key));

    if (ethertype == 0x8100 && h->caplen >= 18) { // VLAN
        ethertype = ntohs(*(uint16_t *)(ptr + 16));
        offset += 4;
    }

    if (ethertype == 0x0800) {
        if (h->caplen < offset + sizeof(struct ip)) return;
        const struct ip *ip = (const struct ip *)(ptr + offset);

        size_t ip_hl = ip->ip_hl * 4;
        if (h->caplen < offset + ip_hl) return;

        key.ip_version = 4;
        key.protocol = ip->ip_p;
        key.src_ip.v4 = ip->ip_src;
        key.dst_ip.v4 = ip->ip_dst;

        const uint8_t *l4 = ptr + offset + ip_hl;
        size_t l4_len = h->caplen - (offset + ip_hl);

        if (ip->ip_p == IPPROTO_TCP && l4_len >= sizeof(struct tcphdr)) {
            const struct tcphdr *tcp = (const struct tcphdr *)l4;
            key.src_port = tcp->source;
            key.dst_port = tcp->dest;
        } else if (ip->ip_p == IPPROTO_UDP && l4_len >= sizeof(struct udphdr)) {
            const struct udphdr *udp = (const struct udphdr *)l4;
            key.src_port = udp->uh_sport;
            key.dst_port = udp->uh_dport;
        } else {
            key.src_port = 0;
            key.dst_port = 0;
        }

    } else if (ethertype == 0x86DD) {
        if (h->caplen < offset + sizeof(struct ip6_hdr)) return;
        const struct ip6_hdr *ip6 = (const struct ip6_hdr *)(ptr + offset);

        key.ip_version = 6;
        key.protocol = ip6->ip6_nxt;
        key.src_ip.v6 = ip6->ip6_src;
        key.dst_ip.v6 = ip6->ip6_dst;

        const uint8_t *l4 = ptr + offset + sizeof(struct ip6_hdr);
        size_t l4_len = h->caplen - (offset + sizeof(struct ip6_hdr));

        if (key.protocol == IPPROTO_TCP && l4_len >= sizeof(struct tcphdr)) {
            const struct tcphdr *tcp = (const struct tcphdr *)l4;
            key.src_port = tcp->source;
            key.dst_port = tcp->dest;
        } else if (key.protocol == IPPROTO_UDP && l4_len >= sizeof(struct udphdr)) {
            const struct udphdr *udp = (const struct udphdr *)l4;
            key.src_port = udp->uh_sport;
            key.dst_port = udp->uh_dport;
        } else {
            key.src_port = 0;
            key.dst_port = 0;
        }
    } else {
        return; // unsupported ethertype
    }

    uint64_t ts_ns = ts_to_ns(&h->ts);
    flow_entry_t *e = flow_lookup_or_create(&key, ts_ns);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    if (ts_ns < e->first_ts_ns) e->first_ts_ns = ts_ns;
    if (ts_ns > e->last_ts_ns)  e->last_ts_ns = ts_ns;
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *dev = (argc > 1) ? argv[1] : NULL;

    signal(SIGINT, handle_sigint);

    if (!dev) {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            fprintf(stderr, "pcap_lookupdev failed: %s\n", errbuf);
            return 1;
        }
    }

    pcap_t *handle = pcap_open_live(dev, SNAPLEN, 1, TIMEOUT_MS, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    // Optional: reduce user-space load with a capture filter
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip or ip6", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    printf("Listening on %s... Press Ctrl-C to stop.\n", dev);

    while (running) {
        int rc = pcap_dispatch(handle, 1024, process_packet, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(handle));
            break;
        }
    }

    printf("\n=== Flow summary ===\n");
    dump_flows();

    pcap_close(handle);
    return 0;
}
