## Minimal implementation in C

### `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <time.h>
#include <unistd.h>

#define FLOW_TABLE_SIZE (1 << 20)   // 1,048,576 buckets
#define FLOW_TIMEOUT_SEC 30
#define SNAPLEN 96

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h & (FLOW_TABLE_SIZE - 1);
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, uint64_t ts_ns) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_seen_ns = ts_ns;
    e->last_seen_ns = ts_ns;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void expire_flows(uint64_t now) {
    uint64_t timeout_ns = (uint64_t)FLOW_TIMEOUT_SEC * 1000000000ULL;

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if (now - e->last_seen_ns > timeout_ns) {
                printf("EXPIRE %u.%u.%u.%u:%u -> %u.%u.%u.%u:%u proto=%u pkts=%lu bytes=%lu age=%.3f\n",
                       (e->key.src_ip >> 24) & 0xff, (e->key.src_ip >> 16) & 0xff,
                       (e->key.src_ip >> 8) & 0xff, e->key.src_ip & 0xff,
                       ntohs(e->key.src_port),
                       (e->key.dst_ip >> 24) & 0xff, (e->key.dst_ip >> 16) & 0xff,
                       (e->key.dst_ip >> 8) & 0xff, e->key.dst_ip & 0xff,
                       ntohs(e->key.dst_port), e->key.proto,
                       e->packets, e->bytes,
                       (double)(e->last_seen_ns - e->first_seen_ns) / 1e9);

                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void handle_packet(const u_char *packet, const struct pcap_pkthdr *hdr) {
    if (hdr->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = packet + sizeof(struct ether_header);
    if (hdr->caplen < sizeof(struct ether_header) + sizeof(struct ip)) return;

    const struct ip *ip = (const struct ip *)ip_ptr;
    size_t ip_hlen = ip->ip_hl * 4;
    if (ip_hlen < sizeof(struct ip)) return;
    if (hdr->caplen < sizeof(struct ether_header) + ip_hlen) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ntohl(ip->ip_src.s_addr);
    key.dst_ip = ntohl(ip->ip_dst.s_addr);
    key.proto = ip->ip_p;

    const u_char *l4 = ip_ptr + ip_hlen;
    size_t l4_len = hdr->caplen - sizeof(struct ether_header) - ip_hlen;

    if (ip->ip_p == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->ip_p == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    uint64_t ts_ns = (uint64_t)hdr->ts.tv_sec * 1000000000ULL + hdr->ts.tv_usec * 1000ULL;
    flow_entry_t *flow = flow_lookup_or_create(&key, ts_ns);
    if (!flow) return;

    flow->packets++;
    flow->bytes += hdr->len;
    flow->last_seen_ns = ts_ns;
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *hdr, const u_char *packet) {
    (void)user;
    handle_packet(packet, hdr);
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *iface = (argc > 1) ? argv[1] : "eth0";

    pcap_t *pcap = pcap_create(iface, errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_create failed: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(pcap, SNAPLEN);
    pcap_set_promisc(pcap, 1);
    pcap_set_timeout(pcap, 1);
    pcap_set_immediate_mode(pcap, 1);

    if (pcap_activate(pcap) != 0) {
        fprintf(stderr, "pcap_activate failed: %s\n", pcap_geterr(pcap));
        pcap_close(pcap);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(pcap, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(pcap));
        pcap_close(pcap);
        return 1;
    }
    if (pcap_setfilter(pcap, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(pcap));
        pcap_freecode(&fp);
        pcap_close(pcap);
        return 1;
    }
    pcap_freecode(&fp);

    printf("Listening on %s...\n", iface);

    uint64_t last_expire = now_ns();

    while (1) {
        int rc = pcap_dispatch(pcap, 1024, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(pcap));
            break;
        }

        uint64_t now = now_ns();
        if (now - last_expire > 1000000000ULL) {
            expire_flows(now);
            last_expire = now;
        }
    }

    pcap_close(pcap);
    return 0;
}
