# C implementation

```c
// flow_analyzer.c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE 1048576   // 1M buckets
#define FLOW_TIMEOUT_SEC 30

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_seen;
    struct timeval last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t **flow_table = NULL;
static volatile sig_atomic_t running = 1;

static inline uint64_t tv_to_us(struct timeval tv) {
    return (uint64_t)tv.tv_sec * 1000000ULL + (uint64_t)tv.tv_usec;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    // Simple fast hash (good enough for minimal working version)
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h;
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, const struct timeval *ts) {
    uint32_t idx = hash_flow(key) % HASH_SIZE;
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_seen = *ts;
    e->last_seen = *ts;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_ip(uint32_t ip) {
    struct in_addr a;
    a.s_addr = ip;
    printf("%s", inet_ntoa(a));
}

static void print_flows(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            printf("FLOW ");
            print_ip(e->key.src_ip);
            printf(":%u -> ", ntohs(e->key.src_port));
            print_ip(e->key.dst_ip);
            printf(":%u proto=%u packets=%llu bytes=%llu age=%llu us\n",
                   ntohs(e->key.dst_port),
                   e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes,
                   (unsigned long long)(tv_to_us(e->last_seen) - tv_to_us(e->first_seen)));
            e = e->next;
        }
    }
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    // Ethernet header
    if (h->caplen < 14) return;
    const uint8_t *ptr = bytes;
    uint16_t ethertype = ntohs(*(uint16_t *)(ptr + 12));
    if (ethertype != 0x0800) return; // IPv4 only

    // IP header
    const struct ip *iph = (const struct ip *)(ptr + 14);
    int ip_header_len = iph->ip_hl * 4;
    if (ip_header_len < 20) return;
    if (h->caplen < 14 + (size_t)ip_header_len) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const uint8_t *l4 = ptr + 14 + ip_header_len;

    if (iph->ip_p == IPPROTO_TCP) {
        if (h->caplen < 14 + (size_t)ip_header_len + sizeof(struct tcphdr)) return;
        const struct tcphdr *th = (const struct tcphdr *)l4;
        key.src_port = th->source;
        key.dst_port = th->dest;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (h->caplen < 14 + (size_t)ip_header_len + sizeof(struct udphdr)) return;
        const struct udphdr *uh = (const struct udphdr *)l4;
        key.src_port = uh->source;
        key.dst_port = uh->dest;
    } else {
        // For non-TCP/UDP, ports remain 0
    }

    flow_entry_t *e = flow_lookup_or_create(&key, &h->ts);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    e->last_seen = h->ts;
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *dev = NULL;
    pcap_t *handle = NULL;
    struct bpf_program fp;
    char filter_exp[] = "ip";
    bpf_u_int32 net = 0, mask = 0;

    if (argc > 1) {
        dev = argv[1];
    } else {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            fprintf(stderr, "pcap_lookupdev failed: %s\n", errbuf);
            return 1;
        }
    }

    if (pcap_lookupnet(dev, &net, &mask, errbuf) == -1) {
        net = 0;
        mask = 0;
    }

    handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_compile(handle, &fp, filter_exp, 0, mask) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }

    pcap_freecode(&fp);

    flow_table = (flow_entry_t **)calloc(HASH_SIZE, sizeof(flow_entry_t *));
    if (!flow_table) {
        fprintf(stderr, "failed to allocate flow table\n");
        pcap_close(handle);
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    printf("Listening on %s...\n", dev);

    while (running) {
        int rc = pcap_dispatch(handle, 1024, packet_handler, NULL);
        if (rc == -1) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(handle));
            break;
        }
    }

    printf("\nFinal flow table:\n");
    print_flows();

    pcap_close(handle);
    return 0;
}
