## src/main.rs

```rust
use hashbrown::HashMap;
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::{
    ethernet::{EtherTypes, EthernetPacket},
    ip::IpNextHeaderProtocols,
    ipv4::Ipv4Packet,
    ipv6::Ipv6Packet,
    tcp::TcpPacket,
    udp::UdpPacket,
    Packet,
};
use std::{
    net::{IpAddr, Ipv4Addr, Ipv6Addr},
    time::{Duration, Instant},
};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

fn main() {
    let iface_name = std::env::args().nth(1).expect("usage: flow-analyzer <iface>");
    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == iface_name)
        .expect("interface not found");

    let mut config = datalink::Config::default();
    config.read_timeout = Some(Duration::from_millis(10));
    config.promiscuous = true;

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(_, rx)) => ((), rx),
        Ok(_) => panic!("unhandled channel type"),
        Err(e) => panic!("failed to open interface: {e}"),
    };

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let expiry = Duration::from_secs(30);
    let mut last_expiry = Instant::now();

    loop {
        match rx.next() {
            Ok(packet) => {
                let now = Instant::now();
                if let Some((key, len)) = parse_packet(packet) {
                    flows
                        .entry(key)
                        .and_modify(|s| s.update(now, len))
                        .or_insert_with(|| FlowStats::new(now, len));
                }

                if last_expiry.elapsed() >= Duration::from_secs(1) {
                    expire_flows(&mut flows, expiry);
                    last_expiry = now;
                    print_top_flows(&flows);
                }
            }
            Err(_) => {
                // Timeout or transient capture error; continue.
            }
        }
    }
}

fn parse_packet(packet: &[u8]) -> Option<(FlowKey, usize)> {
    let eth = EthernetPacket::new(packet)?;
    match eth.get_ethertype() {
        EtherTypes::Ipv4 => parse_ipv4(eth.payload()),
        EtherTypes::Ipv6 => parse_ipv6(eth.payload()),
        _ => None,
    }
}

fn parse_ipv4(payload: &[u8]) -> Option<(FlowKey, usize)> {
    let ip = Ipv4Packet::new(payload)?;
    let src = IpAddr::V4(Ipv4Addr::from(ip.get_source()));
    let dst = IpAddr::V4(Ipv4Addr::from(ip.get_destination()));
    let proto = ip.get_next_level_protocol();

    match proto {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ip.payload())?;
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: 6,
                },
                ip.packet().len(),
            ))
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ip.payload())?;
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: 17,
                },
                ip.packet().len(),
            ))
        }
        _ => None,
    }
}

fn parse_ipv6(payload: &[u8]) -> Option<(FlowKey, usize)> {
    let ip = Ipv6Packet::new(payload)?;
    let src = IpAddr::V6(Ipv6Addr::from(ip.get_source()));
    let dst = IpAddr::V6(Ipv6Addr::from(ip.get_destination()));
    let proto = ip.get_next_header();

    match proto {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ip.payload())?;
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: 6,
                },
                ip.packet().len(),
            ))
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ip.payload())?;
            Some((
                FlowKey {
                    src,
                    dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: 17,
                },
                ip.packet().len(),
            ))
        }
        _ => None,
    }
}

fn expire_flows(flows: &mut HashMap<FlowKey, FlowStats>, expiry: Duration) {
    let now = Instant::now();
    flows.retain(|_, stats| now.duration_since(stats.last_seen) <= expiry);
}

fn print_top_flows(flows: &HashMap<FlowKey, FlowStats>) {
    let mut top: Vec<_> = flows.iter().collect();
    top.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("--- top flows ---");
    for (key, stats) in top.into_iter().take(10) {
        println!(
            "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={}",
            key.src,
            key.src_port,
            key.dst,
            key.dst_port,
            key.proto,
            stats.packets,
            stats.bytes
        );
    }
}
