## `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <time.h>

#define FLOW_TABLE_SIZE (1u << 20)   // 1,048,576 entries
#define FLOW_TABLE_MASK (FLOW_TABLE_SIZE - 1)
#define SNAP_LEN 96                  // enough for L2 + L3 + L4 headers

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ts_ns;
    uint64_t last_ts_ns;
    uint8_t used;
} flow_entry_t;

static flow_entry_t flow_table[FLOW_TABLE_SIZE];
static volatile sig_atomic_t stop_flag = 0;
static pcap_t *handle = NULL;

static inline uint64_t ts_to_ns(const struct timeval *tv) {
    return (uint64_t)tv->tv_sec * 1000000000ull + (uint64_t)tv->tv_usec * 1000ull;
}

static inline uint64_t hash_flow(const flow_key_t *k) {
    // Simple fast mix
    uint64_t x = ((uint64_t)k->src_ip << 32) ^ k->dst_ip;
    x ^= ((uint64_t)k->src_port << 16) ^ k->dst_port;
    x ^= (uint64_t)k->proto * 0x9e3779b97f4a7c15ull;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdull;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ull;
    x ^= x >> 33;
    return x;
}

static inline int key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static inline flow_entry_t* flow_lookup_or_insert(const flow_key_t *key) {
    uint64_t h = hash_flow(key);
    uint32_t idx = (uint32_t)h & FLOW_TABLE_MASK;

    for (uint32_t probe = 0; probe < FLOW_TABLE_SIZE; probe++) {
        flow_entry_t *e = &flow_table[idx];
        if (!e->used) {
            e->used = 1;
            e->key = *key;
            e->packets = 0;
            e->bytes = 0;
            e->first_ts_ns = 0;
            e->last_ts_ns = 0;
            return e;
        }
        if (key_equal(&e->key, key)) {
            return e;
        }
        idx = (idx + 1) & FLOW_TABLE_MASK;
    }
    return NULL; // table full
}

static void print_ip(uint32_t ip_net_order) {
    struct in_addr a;
    a.s_addr = ip_net_order;
    printf("%s", inet_ntoa(a));
}

static void export_flows(void) {
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flow_table[i];
        if (!e->used || e->packets == 0) continue;

        printf("%u.%u.%u.%u:%u -> %u.%u.%u.%u:%u proto=%u packets=%lu bytes=%lu first_ns=%lu last_ns=%lu\n",
               (ntohl(e->key.src_ip) >> 24) & 0xff,
               (ntohl(e->key.src_ip) >> 16) & 0xff,
               (ntohl(e->key.src_ip) >> 8) & 0xff,
               ntohl(e->key.src_ip) & 0xff,
               ntohs(e->key.src_port),
               (ntohl(e->key.dst_ip) >> 24) & 0xff,
               (ntohl(e->key.dst_ip) >> 16) & 0xff,
               (ntohl(e->key.dst_ip) >> 8) & 0xff,
               ntohl(e->key.dst_ip) & 0xff,
               ntohs(e->key.dst_port),
               e->key.proto,
               (unsigned long)e->packets,
               (unsigned long)e->bytes,
               (unsigned long)e->first_ts_ns,
               (unsigned long)e->last_ts_ns);
    }
}

static void on_signal(int sig) {
    (void)sig;
    stop_flag = 1;
    if (handle) pcap_breakloop(handle);
}

static void packet_cb(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    // Minimal Ethernet parsing
    if (h->caplen < 14) return;
    uint16_t ethertype = (bytes[12] << 8) | bytes[13];
    if (ethertype != 0x0800) return; // IPv4 only

    const u_char *p = bytes + 14;
    if (h->caplen < 14 + sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)p;
    if (iph->ip_v != 4) return;
    uint32_t ip_hl = iph->ip_hl * 4;
    if (ip_hl < 20) return;
    if (h->caplen < 14 + ip_hl) return;

    if (iph->ip_p != IPPROTO_TCP && iph->ip_p != IPPROTO_UDP) return;

    flow_key_t key;
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const u_char *l4 = p + ip_hl;
    if (iph->ip_p == IPPROTO_TCP) {
        if (h->caplen < 14 + ip_hl + sizeof(struct tcphdr)) return;
        const struct tcphdr *th = (const struct tcphdr *)l4;
        key.src_port = th->source;
        key.dst_port = th->dest;
    } else {
        if (h->caplen < 14 + ip_hl + sizeof(struct udphdr)) return;
        const struct udphdr *uh = (const struct udphdr *)l4;
        key.src_port = uh->uh_sport;
        key.dst_port = uh->uh_dport;
    }

    flow_entry_t *e = flow_lookup_or_insert(&key);
    if (!e) return;

    uint64_t ts = ts_to_ns(&h->ts);
    if (e->packets == 0) e->first_ts_ns = ts;
    e->last_ts_ns = ts;
    e->packets++;
    e->bytes += h->len;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    handle = pcap_open_live(argv[1], SNAP_LEN, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    // Reduce overhead
    if (pcap_set_immediate_mode(handle, 1) != 0) {
        fprintf(stderr, "Warning: immediate mode not supported\n");
    }

    struct bpf_program fp;
    const char *filter = "ip and (tcp or udp)";
    if (pcap_compile(handle, &fp, filter, 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        return 1;
    }
    pcap_freecode(&fp);

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    fprintf(stderr, "Capturing on %s...\n", argv[1]);

    int ret = pcap_loop(handle, -1, packet_cb, NULL);
    if (ret == -1) {
        fprintf(stderr, "pcap_loop error: %s\n", pcap_geterr(handle));
    }

    fprintf(stderr, "\nExporting flows...\n");
    export_flows();

    pcap_close(handle);
    return 0;
}
```

