## Example firmware structure

```c
#include <stdint.h>
#include <stdbool.h>

/* =========================
   Configuration
   ========================= */
#define SENSOR_SAMPLE_INTERVAL_MS   100
#define FILTER_WINDOW_SIZE          8
#define THRESHOLD_HIGH              3000
#define THRESHOLD_LOW               1000

/* =========================
   Hardware abstraction stubs
   Replace these with your MCU HAL
   ========================= */
void System_Init(void);
void UART_Init(void);
void Sensor_Init(void);
uint16_t Sensor_ReadRaw(void);
void UART_SendString(const char *s);
uint32_t millis(void);
void delay_ms(uint32_t ms);

/* =========================
   Simple moving average filter
   ========================= */
typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    uint32_t sum;
} MovingAverageFilter;

void Filter_Init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

uint16_t Filter_Update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
    }

    f->buffer[f->index] = sample;
    f->sum += sample;

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    return (uint16_t)(f->sum / f->count);
}

/* =========================
   Event detection
   ========================= */
typedef enum {
    SENSOR_STATE_NORMAL = 0,
    SENSOR_STATE_HIGH,
    SENSOR_STATE_LOW
} SensorState;

SensorState ProcessSensorValue(uint16_t value) {
    if (value > THRESHOLD_HIGH) {
        return SENSOR_STATE_HIGH;
    } else if (value < THRESHOLD_LOW) {
        return SENSOR_STATE_LOW;
    } else {
        return SENSOR_STATE_NORMAL;
    }
}

const char* StateToString(SensorState state) {
    switch (state) {
        case SENSOR_STATE_HIGH:   return "HIGH";
        case SENSOR_STATE_LOW:    return "LOW";
        default:                  return "NORMAL";
    }
}

/* =========================
   Main firmware
   ========================= */
int main(void) {
    System_Init();
    UART_Init();
    Sensor_Init();

    MovingAverageFilter filter;
    Filter_Init(&filter);

    uint32_t last_sample_time = 0;
    uint16_t raw_value = 0;
    uint16_t filtered_value = 0;
    SensorState state = SENSOR_STATE_NORMAL;

    UART_SendString("Firmware started\r\n");

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_INTERVAL_MS) {
            last_sample_time = now;

            raw_value = Sensor_ReadRaw();
            filtered_value = Filter_Update(&filter, raw_value);
            state = ProcessSensorValue(filtered_value);

            char msg[128];
            // Simple formatting without sprintf to reduce dependencies
