typedef struct {
    int32_t buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} MovingAverageFilter;

static void Filter_Init(MovingAverageFilter *f)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
    f->index = 0;
    f->count = 0;
    f->sum = 0;
}

static int32_t Filter_Update(MovingAverageFilter *f, int32_t sample)
{
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;
    return f->sum / f->count;
}

