static uint16_t ema_filter(uint16_t input)
{
    static uint32_t filtered = 0;
    const uint8_t alpha = 8; // 1/8 smoothing

    if (filtered == 0) {
        filtered = input << 8;
    } else {
        filtered = filtered - (filtered >> alpha) + (input << (8 - alpha));
    }

    return (uint16_t)(filtered >> 8);
}
```

