static uint16_t average_samples(const uint16_t *buf, uint8_t len)
{
    uint32_t sum = 0;
    for (uint8_t i = 0; i < len; i++) {
        sum += buf[i];
    }
    return (uint16_t)(sum / len);
}

static void process_sensor_value(uint16_t value)
