    SystemInit();
    GPIO_Init();
    ADC_Init();
    UART_Init();

    UART_SendString("Firmware start\r\n");

    /* Prime the buffer with initial readings */
    for (uint8_t i = 0; i < SAMPLE_COUNT; i++) {
        sample_buffer[i] = ADC_ReadChannel(SENSOR_ADC_CHANNEL);
        DelayMs(10);
