        uint16_t raw = ADC_ReadChannel(SENSOR_ADC_CHANNEL);

        /* Store in circular buffer */
        sample_buffer[sample_index] = raw;
        sample_index = (sample_index + 1) % SAMPLE_COUNT;

        /* Process filtered data */
        uint16_t filtered = average_samples(sample_buffer, SAMPLE_COUNT);
        process_sensor_value(filtered);

        DelayMs(100);
    }

    return 0;
