static void uart_write_int(const char *prefix, int32_t value)
{
    char buf[64];
    int n = 0;

    // simple itoa-like conversion
    int32_t v = value;
    char tmp[16];
    int i = 0;
    bool negative = false;

    if (v < 0) {
        negative = true;
        v = -v;
    }

    do {
        tmp[i++] = '0' + (v % 10);
        v /= 10;
    } while (v > 0 && i < (int)sizeof(tmp));

    if (negative) {
