    }

    // build output string
    while (prefix && *prefix && n < (int)sizeof(buf) - 1) {
        buf[n++] = *prefix++;
    }

    while (i > 0 && n < (int)sizeof(buf) - 1) {
        buf[n++] = tmp[--i];
