        f->y = f->alpha * sample->y + (1.0f - f->alpha) * f->y;
        f->z = f->alpha * sample->z + (1.0f - f->alpha) * f->z;
        f->temp = f->alpha * sample->temp + (1.0f - f->alpha) * f->temp;
