## Simple Moving Average Filter

### `filter.h`
```c
#ifndef FILTER_H
#define FILTER_H

#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int32_t buffer[16];
    uint8_t size;
    uint8_t index;
    uint8_t count;
    int64_t sum;
} MovingAvg_t;

void Filter_Init(MovingAvg_t *f, uint8_t window_size);
int32_t Filter_Update(MovingAvg_t *f, int32_t sample);

#endif
```

### `filter.c`
```c
#include "filter.h"

void Filter_Init(MovingAvg_t *f, uint8_t window_size)
{
    if (f == NULL) return;

    if (window_size > 16) {
        window_size = 16;
    }

    f->size = window_size;
    f->index = 0;
    f->count = 0;
    f->sum = 0;

    for (uint8_t i = 0; i < 16; i++) {
        f->buffer[i] = 0;
    }
}

int32_t Filter_Update(MovingAvg_t *f, int32_t sample)
{
    if (f == NULL || f->size == 0) {
        return sample;
    }

    if (f->count < f->size) {
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
    }

    f->buffer[f->index] = sample;
    f->sum += sample;
    f->index = (f->index + 1) % f->size;

    return (int32_t)(f->sum / f->count);
}
```

