typedef struct {
    float alpha;
    bool initialized;
    float last_x;
    float last_y;
    float last_z;
} LowPassFilter_t;

/* =========================
 * Global State
 * ========================= */
static SensorData_t g_sensorData;
static LowPassFilter_t g_filter;

/* =========================
 * Utility Functions
 * ========================= */
static float absf(float v) {
    return (v < 0.0f) ? -v : v;
}

static float sqrt_approx(float x) {
    if (x <= 0.0f) return 0.0f;

    float guess = x > 1.0f ? x : 1.0f;
    for (int i = 0; i < 8; i++) {
        guess = 0.5f * (guess + x / guess);
    }
    return guess;
}

/* =========================
 * Filter Functions
 * ========================= */
static void LowPassFilter_Init(LowPassFilter_t *f, float alpha) {
    if (!f) return;
    f->alpha = alpha;
    f->initialized = false;
    f->last_x = 0.0f;
    f->last_y = 0.0f;
    f->last_z = 0.0f;
}

static void LowPassFilter_Apply(LowPassFilter_t *f, float x, float y, float z,
                                float *out_x, float *out_y, float *out_z) {
    if (!f || !out_x || !out_y || !out_z) return;

    if (!f->initialized) {
        f->last_x = x;
        f->last_y = y;
        f->last_z = z;
        f->initialized = true;
    } else {
        f->last_x = f->alpha * x + (1.0f - f->alpha) * f->last_x;
        f->last_y = f->alpha * y + (1.0f - f->alpha) * f->last_y;
        f->last_z = f->alpha * z + (1.0f - f->alpha) * f->last_z;
    }

    *out_x = f->last_x;
    *out_y = f->last_y;
    *out_z = f->last_z;
}

/* =========================
 * Processing Functions
 * ========================= */
static float ComputeMagnitude(float x, float y, float z) {
    return sqrt_approx((x * x) + (y * y) + (z * z));
}

static void ProcessSensorData(SensorData_t *data) {
    if (!data || !data->valid) return;

    data->magnitude = ComputeMagnitude(data->filtered_x,
                                       data->filtered_y,
