### `filter.c`
```c
#include "filter.h"

void Filter_Init(MovingAverageFilter *f)
{
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;

    for (uint8_t i = 0; i < 8; i++) {
        f->buffer[i] = 0.0f;
    }
}

float Filter_Update(MovingAverageFilter *f, float sample)
{
    if (f->count < 8) {
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
    }

    f->buffer[f->index] = sample;
    f->sum += sample;

    f->index = (f->index + 1) % 8;

    return f->sum / (float)f->count;
}
```

