#include "sensor.h"
#include "config.h"

// Platform-specific function to read ADC
extern uint16_t Platform_ADC_Read(void);

static MovingAverageFilter g_filter;

void Sensor_Init(void)
{
    Filter_Init(&g_filter);
}

bool Sensor_ReadRaw(uint16_t *adc_value)
{
    if (adc_value == 0) {
        return false;
    }

    *adc_value = Platform_ADC_Read();
    return true;
}

float Sensor_ConvertToVoltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
}

float Sensor_Process(float voltage)
{
    float adjusted = voltage - SENSOR_OFFSET_VOLTAGE;
    if (adjusted < 0.0f) {
        adjusted = 0.0f;
    }

    return adjusted * SENSOR_SCALE_FACTOR;
}

void Sensor_Update(SensorData *data)
{
    if (data == 0) {
        return;
    }

    uint16_t adc;
    if (!Sensor_ReadRaw(&adc)) {
        data->valid = false;
        return;
    }

    data->raw_voltage = Sensor_ConvertToVoltage(adc);
    data->filtered_voltage = Filter_Update(&g_filter, data->raw_voltage);
    data->processed_value = Sensor_Process(data->filtered_voltage);
    data->valid = true;
}
