    Timer_Init(SENSOR_SAMPLE_PERIOD_MS);

    UART_SendString("Firmware startup complete\r\n");

    g_lastSampleTime = millis();

    while (1) {
        uint32_t now = millis();

        if ((now - g_lastSampleTime) >= SENSOR_SAMPLE_PERIOD_MS) {
            g_lastSampleTime = now;

            /* Read raw sensor value */
            uint16_t raw_adc = ADC_ReadRaw();
            g_sensor.raw = (float)raw_adc;

            /* Validate reading */
            g_sensor.valid = is_sensor_value_valid(g_sensor.raw);

            /* Filter only valid samples */
            if (g_sensor.valid) {
                g_sensor.filtered = apply_low_pass_filter(
                    g_sensor.raw,
                    g_sensor.filtered,
                    FILTER_ALPHA
                );
            }

            /* Process the reading */
            process_sensor_data(&g_sensor);
        }

        /* Optional: sleep / idle to save power */
        DelayMs(1);
    }

    /* Unreachable */
    return 0;
