static uint16_t MovingAverage_Update(MovingAverageFilter_t *f, uint16_t sample)
{
    if (f->count < SENSOR_BUFFER_SIZE) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

