### `processing.c`
```c
#include "processing.h"
#include "config.h"

void processing_init(processing_state_t *state)
{
    if (!state) return;

    state->filtered_value = 0.0f;
    state->average_value = 0.0f;
    state->min_value = 0.0f;
    state->max_value = 0.0f;
    state->last_value = 0.0f;
    state->sample_count = 0;
}

float processing_apply_filter(processing_state_t *state, float input)
{
    if (!state) return input;

    if (state->sample_count == 0) {
        state->filtered_value = input;
    } else {
        state->filtered_value =
            (FILTER_ALPHA * input) + ((1.0f - FILTER_ALPHA) * state->filtered_value);
    }

    state->last_value = input;
    state->sample_count++;
    return state->filtered_value;
}

void processing_update_stats(processing_state_t *state, float input)
{
    if (!state) return;

    if (state->sample_count == 1) {
        state->min_value = input;
        state->max_value = input;
        state->average_value = input;
    } else {
        if (input < state->min_value) state->min_value = input;
        if (input > state->max_value) state->max_value = input;

        // Running average
        state->average_value =
            ((state->average_value * (state->sample_count - 1)) + input) /
            (float)state->sample_count;
    }
}
