#include "filter.h"

#define FILTER_WINDOW_SIZE 8

static float window[FILTER_WINDOW_SIZE];
static uint8_t index = 0;
static uint8_t count = 0;
static float sum = 0.0f;

void Filter_Init(void)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        window[i] = 0.0f;
    }

    index = 0;
    count = 0;
    sum = 0.0f;
}

float Filter_Update(float input)
{
    // Remove oldest value from sum
    sum -= window[index];

    // Store new value
    window[index] = input;
    sum += input;

    // Advance index
    index++;
    if (index >= FILTER_WINDOW_SIZE) {
        index = 0;
    }

    // Increase sample count until full
    if (count < FILTER_WINDOW_SIZE) {
        count++;
    }

    // Return average
    if (count == 0) {
        return input;
    }

    return sum / (float)count;
}
```

