 * Utility functions
 * ----------------------------- */
static void add_sample(uint16_t sample)
{
    sample_buffer[sample_index++] = sample;

    if (sample_index >= SAMPLE_WINDOW_SIZE) {
        sample_index = 0;
        buffer_full = true;
    }
}

static uint16_t calculate_average(void)
{
    uint32_t sum = 0;
    uint8_t count = buffer_full ? SAMPLE_WINDOW_SIZE : sample_index;

    if (count == 0) {
        return 0;
    }

    for (uint8_t i = 0; i < count; i++) {
        sum += sample_buffer[i];
    }

    return (uint16_t)(sum / count);
}

