    /* Simple threshold with hysteresis */
    if (!alarm_state && value > SENSOR_THRESHOLD) {
        alarm_state = true;
        UART_SendString("ALARM: Sensor value exceeded threshold\r\n");
    } else if (alarm_state && value < (SENSOR_THRESHOLD - SENSOR_HYSTERESIS)) {
        alarm_state = false;
        UART_SendString("ALARM CLEARED\r\n");
    }

    /* Optional formatted output */
    (void)msg; // Placeholder if you later add snprintf support
}

