} sensor_calibration_t;

typedef struct {
    int16_t buffer[SENSOR_FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} moving_average_filter_t;

/* =========================
 * Globals
 * ========================= */
static sensor_calibration_t g_cal = {
    .offset = 0,
    .gain = 1.0f
};

static moving_average_filter_t g_filter = {0};
static uint32_t g_last_sample_time_ms = 0;
static uint32_t g_last_valid_sample_time_ms = 0;

/* =========================
 * Hardware Abstraction Layer
 * Replace these with MCU-specific implementations
 * ========================= */
uint32_t HAL_GetTick(void);
void HAL_Delay(uint32_t ms);

bool Sensor_HW_Init(void);
bool Sensor_HW_ReadRaw(int16_t *value);

void System_Init(void);
void UART_Print(const char *msg);

/* =========================
 * Utility Functions
 * ========================= */
static void filter_init(moving_average_filter_t *f)
{
    memset(f, 0, sizeof(*f));
}

static int16_t filter_apply(moving_average_filter_t *f, int16_t sample)
{
    if (f->count < SENSOR_FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % SENSOR_FILTER_WINDOW;

    return (int16_t)(f->sum / (int32_t)f->count);
}

static int16_t apply_calibration(int16_t raw)
{
    float corrected = ((float)raw - (float)g_cal.offset) * g_cal.gain;
    return (int16_t)corrected;
}

static void process_sample(sensor_sample_t *sample)
{
    sample->calibrated = apply_calibration(sample->raw);
    sample->filtered = filter_apply(&g_filter, sample->calibrated);
    sample->valid = true;
}

static void handle_sensor_event(const sensor_sample_t *sample)
{
    if (sample->filtered > SENSOR_THRESHOLD_HIGH) {
        UART_Print("Event: sensor above high threshold\r\n");
    } else if (sample->filtered < SENSOR_THRESHOLD_LOW) {
        UART_Print("Event: sensor below low threshold\r\n");
    }
}

static bool read_sensor_with_retry(int16_t *value)
{
    for (uint8_t attempt = 0; attempt < SENSOR_MAX_RETRIES; attempt++) {
        if (Sensor_HW_ReadRaw(value)) {
            return true;
        }
        HAL_Delay(5);
    }
    return false;
}

/* =========================
 * Main Firmware Logic
 * ========================= */
static void sensor_task(void)
{
    uint32_t now = HAL_GetTick();

    if ((now - g_last_sample_time_ms) < SENSOR_SAMPLE_PERIOD_MS) {
        return;
    }
    g_last_sample_time_ms = now;

    int16_t raw_value = 0;
    sensor_sample_t sample = {0};

    if (read_sensor_with_retry(&raw_value)) {
        sample.raw = raw_value;
        process_sample(&sample);
        g_last_valid_sample_time_ms = now;

        UART_Print("Sensor sample processed\r\n");
        handle_sensor_event(&sample);
    } else {
        UART_Print("Error: sensor read failed\r\n");
    }

    if ((now - g_last_valid_sample_time_ms) > SENSOR_FAULT_TIMEOUT_MS) {
        UART_Print("Fault: sensor timeout\r\n");
        // Optional: trigger reset, reinit sensor, or enter safe mode
    }
}

