{
    System_Init();
    UART_Print("Firmware boot\r\n");

    filter_init(&g_filter);

    if (!Sensor_HW_Init()) {
        UART_Print("Error: sensor init failed\r\n");
        while (1) {
            // Safe halt or retry init
        }
    }

    UART_Print("Sensor init OK\r\n");

    while (1) {
        sensor_task();

        // Optional low-power sleep until next tick/interrupt
        // MCU_Sleep();
    }

