#include "processing.h"
#include "config.h"

static float filtered_value = 0.0f;
static uint8_t filter_initialized = 0;

float low_pass_filter(float input)
{
    if (!filter_initialized) {
        filtered_value = input;
        filter_initialized = 1;
        return filtered_value;
    }

    filtered_value = FILTER_ALPHA * input + (1.0f - FILTER_ALPHA) * filtered_value;
    return filtered_value;
}

float compute_sensor_metric(float voltage)
{
    // Example conversion:
    // If sensor outputs 0.5V at minimum and 2.5V at maximum,
    // map voltage to a normalized value.
    const float min_v = 0.5f;
    const float max_v = 2.5f;

    if (voltage < min_v) voltage = min_v;
    if (voltage > max_v) voltage = max_v;

    return (voltage - min_v) / (max_v - min_v);
}
```

