int samples[WINDOW_SIZE];
int sampleIndex = 0;
long sampleSum = 0;

void setup() {
  Serial.begin(115200);
  pinMode(SENSOR_PIN, INPUT);

  for (int i = 0; i < WINDOW_SIZE; i++) {
    samples[i] = 0;
  }

  Serial.println("Sensor firmware started");
