#include <stdio.h>
#include <string.h>

#define FILTER_SIZE 8

UART_HandleTypeDef huart2;
ADC_HandleTypeDef hadc1;

static uint16_t adc_buffer[FILTER_SIZE];
static uint32_t adc_sum = 0;
static uint8_t adc_index = 0;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_USART2_UART_Init(void);
static void MX_ADC1_Init(void);

static uint16_t Read_Sensor_ADC(void);
static uint16_t Moving_Average(uint16_t new_value);
static void Process_Sensor_Data(uint16_t value);
static void UART_Print(const char *msg);

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_USART2_UART_Init();
    MX_ADC1_Init();

    memset(adc_buffer, 0, sizeof(adc_buffer));

    char msg[64];

    while (1)
    {
        uint16_t raw = Read_Sensor_ADC();
        uint16_t filtered = Moving_Average(raw);

        Process_Sensor_Data(filtered);

        snprintf(msg, sizeof(msg), "Raw=%u Filtered=%u\r\n", raw, filtered);
        UART_Print(msg);

        HAL_Delay(100);
    }
}

static uint16_t Read_Sensor_ADC(void)
{
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
    uint16_t value = (uint16_t)HAL_ADC_GetValue(&hadc1);
    HAL_ADC_Stop(&hadc1);
    return value;
}

static uint16_t Moving_Average(uint16_t new_value)
{
    adc_sum -= adc_buffer[adc_index];
    adc_buffer[adc_index] = new_value;
    adc_sum += new_value;

    adc_index++;
    if (adc_index >= FILTER_SIZE)
        adc_index = 0;

    return (uint16_t)(adc_sum / FILTER_SIZE);
}

static void Process_Sensor_Data(uint16_t value)
{
    // Example processing:
    // turn LED on if sensor value exceeds threshold
    if (value > 2000)
        HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);
    else
        HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);
}

static void UART_Print(const char *msg)
{
    HAL_UART_Transmit(&huart2, (uint8_t *)msg, strlen(msg), HAL_MAX_DELAY);
}
