// Minimal sensor-processing firmware
// Reads analog sensor data, averages samples, and applies a threshold.

const int SENSOR_PIN = A0;      // Analog input pin
const int LED_PIN = 13;         // Status LED
const int THRESHOLD = 512;      // Example threshold for 10-bit ADC

const int NUM_SAMPLES = 8;
int samples[NUM_SAMPLES];
int sampleIndex = 0;
long sampleSum = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);

  // Initialize sample buffer
  for (int i = 0; i < NUM_SAMPLES; i++) {
    samples[i] = 0;
  }
}

int readFilteredSensor() {
  // Remove oldest sample from sum
  sampleSum -= samples[sampleIndex];

  // Read new sample
  int raw = analogRead(SENSOR_PIN);
  samples[sampleIndex] = raw;

  // Add new sample to sum
  sampleSum += raw;

  // Advance circular buffer index
  sampleIndex = (sampleIndex + 1) % NUM_SAMPLES;

  // Return average
  return sampleSum / NUM_SAMPLES;
}

void loop() {
  int filteredValue = readFilteredSensor();

  // Simple processing: threshold detection
  bool active = (filteredValue > THRESHOLD);

  // Control LED based on processed sensor value
  digitalWrite(LED_PIN, active ? HIGH : LOW);

  // Print raw processed value
  Serial.print("Filtered sensor value: ");
  Serial.print(filteredValue);
  Serial.print(" | State: ");
  Serial.println(active ? "ACTIVE" : "INACTIVE");

  delay(50); // 20 Hz update rate
}
```

