#include "stm32f4xx.h"

#define FILTER_SIZE 8
#define THRESHOLD   2000

static uint16_t filter_buffer[FILTER_SIZE];
static uint8_t filter_index = 0;
static uint32_t filter_sum = 0;

void delay(volatile uint32_t count) {
    while (count--) {
        __NOP();
    }
}

void gpio_init(void) {
    // Enable GPIOA clock
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;

    // PA5 as output (LED on many STM32 Nucleo boards)
    GPIOA->MODER &= ~(3U << (5 * 2));
    GPIOA->MODER |=  (1U << (5 * 2));
}

void adc_init(void) {
    // Enable ADC1 clock
    RCC->APB2ENR |= RCC_APB2ENR_ADC1EN;

    // Configure ADC1 for single conversion on channel 0 (PA0)
    ADC1->SQR3 = 0;                 // Channel 0
    ADC1->SQR1 = 0;                 // 1 conversion
    ADC1->CR2 |= ADC_CR2_ADON;      // Enable ADC
}

uint16_t adc_read(void) {
    ADC1->CR2 |= ADC_CR2_SWSTART;   // Start conversion
    while (!(ADC1->SR & ADC_SR_EOC));
    return (uint16_t)ADC1->DR;
}

uint16_t moving_average(uint16_t sample) {
    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = sample;
    filter_sum += sample;

    filter_index = (filter_index + 1) % FILTER_SIZE;
    return (uint16_t)(filter_sum / FILTER_SIZE);
}

void process_sensor(uint16_t value) {
    if (value > THRESHOLD) {
        GPIOA->BSRR = GPIO_BSRR_BS5;   // LED on
    } else {
        GPIOA->BSRR = GPIO_BSRR_BR5;   // LED off
    }
}

int main(void) {
    gpio_init();
    adc_init();

    // Initialize filter buffer
    for (int i = 0; i < FILTER_SIZE; i++) {
        filter_buffer[i] = 0;
    }

    while (1) {
        uint16_t raw = adc_read();
        uint16_t filtered = moving_average(raw);
        process_sensor(filtered);

        delay(100000);
    }
}
