## `main.c`

```c
#include "main.h"

ADC_HandleTypeDef hadc1;
UART_HandleTypeDef huart2;

#define FILTER_SIZE 8
#define THRESHOLD   2000

static uint16_t filter_buffer[FILTER_SIZE];
static uint8_t filter_index = 0;
static uint32_t filter_sum = 0;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_ADC1_Init(void);
static void MX_USART2_UART_Init(void);

static uint16_t Read_Sensor_ADC(void);
static uint16_t Moving_Average(uint16_t new_value);
static void Process_Sensor_Value(uint16_t value);

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_ADC1_Init();
    MX_USART2_UART_Init();

    // Initialize filter buffer
    for (int i = 0; i < FILTER_SIZE; i++) {
        filter_buffer[i] = 0;
    }

    while (1)
    {
        uint16_t raw = Read_Sensor_ADC();
        uint16_t filtered = Moving_Average(raw);

        Process_Sensor_Value(filtered);

        HAL_Delay(100); // 10 Hz sampling
    }
}

static uint16_t Read_Sensor_ADC(void)
{
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
    uint16_t value = (uint16_t)HAL_ADC_GetValue(&hadc1);
    HAL_ADC_Stop(&hadc1);
    return value;
}

static uint16_t Moving_Average(uint16_t new_value)
{
    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = new_value;
    filter_sum += new_value;

    filter_index = (filter_index + 1) % FILTER_SIZE;

    return (uint16_t)(filter_sum / FILTER_SIZE);
}

static void Process_Sensor_Value(uint16_t value)
{
    char msg[64];

    if (value > THRESHOLD) {
        HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);   // LED ON
    } else {
        HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET); // LED OFF
    }

    int len = snprintf(msg, sizeof(msg), "Sensor: %u\r\n", value);
    HAL_UART_Transmit(&huart2, (uint8_t*)msg, len, HAL_MAX_DELAY);
}

/* --- Peripheral init functions --- */

static void MX_ADC1_Init(void)
{
    ADC_ChannelConfTypeDef sConfig = {0};

    hadc1.Instance = ADC1;
    hadc1.Init.ScanConvMode = ADC_SCAN_DISABLE;
    hadc1.Init.ContinuousConvMode = DISABLE;
    hadc1.Init.DiscontinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConv = ADC_SOFTWARE_START;
    hadc1.Init.DataAlign = ADC_DATAALIGN_RIGHT;
    hadc1.Init.NbrOfConversion = 1;

    HAL_ADC_Init(&hadc1);

    sConfig.Channel = ADC_CHANNEL_0;   // Sensor input pin
    sConfig.Rank = ADC_REGULAR_RANK_1;
    sConfig.SamplingTime = ADC_SAMPLETIME_71CYCLES_5;

    HAL_ADC_ConfigChannel(&hadc1, &sConfig);
}

static void MX_USART2_UART_Init(void)
{
    huart2.Instance = USART2;
    huart2.Init.BaudRate = 115200;
    huart2.Init.WordLength = UART_WORDLENGTH_8B;
    huart2.Init.StopBits = UART_STOPBITS_1;
    huart2.Init.Parity = UART_PARITY_NONE;
    huart2.Init.Mode = UART_MODE_TX_RX;
    huart2.Init.HwFlowCtl = UART_HWCONTROL_NONE;
    huart2.Init.OverSampling = UART_OVERSAMPLING_16;

    HAL_UART_Init(&huart2);
}

static void MX_GPIO_Init(void)
{
    __HAL_RCC_GPIOC_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();

    GPIO_InitTypeDef GPIO_InitStruct = {0};

    // LED pin
    GPIO_InitStruct.Pin = GPIO_PIN_13;
    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOC, &GPIO_InitStruct);

    // ADC input pin
    GPIO_InitStruct.Pin = GPIO_PIN_0;
    GPIO_InitStruct.Mode = GPIO_MODE_ANALOG;
    HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);
}

