struct State {
    double x{0};       // position
    double y{0};
    double theta{0};   // heading
    double v{0};       // linear velocity
    double omega{0};   // angular velocity
};

// ============================
// PID Controller
// ============================
class PID {
public:
    PID(double kp, double ki, double kd, double out_min, double out_max)
        : kp_(kp), ki_(ki), kd_(kd), out_min_(out_min), out_max_(out_max) {}

    double update(double setpoint, double measurement, double dt) {
        if (dt <= 0.0) return 0.0;

        double error = setpoint - measurement;
        integral_ += error * dt;

        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, out_min_, out_max_);
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double out_min_, out_max_;
    double integral_{0.0};
    double prev_error_{0.0};
};

// ============================
// Simple EKF-like State Estimator
// (Lightweight placeholder for real sensor fusion)
// ============================
class StateEstimator {
public:
    StateEstimator() = default;

    State predict(const IMUData& imu, double dt) {
        // Very simplified motion model:
        // Use gyro z for heading rate, and forward accel projected onto heading.
        // In a real robot, use full EKF matrices and covariance propagation.

        double yaw_rate = imu.gz;
        state_.theta += yaw_rate * dt;

        // Approximate forward acceleration from body frame ax
        state_.v += imu.ax * dt;
        state_.x += state_.v * std::cos(state_.theta) * dt;
        state_.y += state_.v * std::sin(state_.theta) * dt;
        state_.omega = yaw_rate;

        return state_;
    }

    State correctWithEncoders(const EncoderData& enc, double dt) {
        // Convert encoder ticks to velocity estimate.
        // Replace with your wheel radius, ticks per rev, wheelbase, etc.
        constexpr double ticks_per_meter = 1000.0;

        int64_t delta_left = enc.ticks_left - prev_ticks_left_;
        int64_t delta_right = enc.ticks_right - prev_ticks_right_;
        prev_ticks_left_ = enc.ticks_left;
        prev_ticks_right_ = enc.ticks_right;

        double v_enc = ((delta_left + delta_right) * 0.5) / ticks_per_meter / dt;

        // Fuse with predicted velocity using a simple complementary blend.
        // Real EKF would use Kalman gain.
        constexpr double alpha = 0.85;
        state_.v = alpha * state_.v + (1.0 - alpha) * v_enc;

        return state_;
    }

    const State& getState() const { return state_; }

private:
    State state_;
    int64_t prev_ticks_left_{0};
    int64_t prev_ticks_right_{0};
};

// ============================
