// ============================
class MotorDriver {
public:
    void setMotorCommands(double left, double right) {
        // Replace with actual PWM / CAN / serial / GPIO commands.
        std::lock_guard<std::mutex> lock(mutex_);
        left_cmd_ = clamp(left, -1.0, 1.0);
        right_cmd_ = clamp(right, -1.0, 1.0);

