        SensorBundle s;
        s.imu = readIMU();
        s.enc = readEncoders();
        return s;
    }

private:
    IMUData readIMU() {
        IMUData imu;
        imu.ax = 0.02;   // mock values
        imu.ay = 0.00;
        imu.az = 9.81;
        imu.gz = 0.01;
        imu.timestamp = Clock::now();
        return imu;
    }

    EncoderData readEncoders() {
        EncoderData enc;
        static int64_t left = 0;
        static int64_t right = 0;
        left += 10;
        right += 10;
        enc.ticks_left = left;
        enc.ticks_right = right;
        enc.timestamp = Clock::now();
        return enc;
    }
};

// ============================
// Main Control Loop
// ============================
int main() {
    constexpr double loop_hz = 100.0;
    constexpr auto loop_period = std::chrono::duration<double>(1.0 / loop_hz);

    SensorReader sensor_reader;
    StateEstimator estimator;
    MotorDriver motors;

    PID linear_pid(1.2, 0.0, 0.05, -1.0, 1.0);
    PID angular_pid(2.0, 0.0, 0.08, -1.0, 1.0);

    // Desired target
    double target_v = 0.5;      // m/s
    double target_theta = 0.0;  // rad

    TimePoint next_tick = Clock::now();

    while (true) {
        auto loop_start = Clock::now();

        // 1) Read sensors
        SensorBundle sensors = sensor_reader.readSensors();

        // 2) Compute dt
        static TimePoint prev_time = loop_start;
        double dt = std::chrono::duration<double>(loop_start - prev_time).count();
        prev_time = loop_start;
        if (dt <= 0.0) dt = 1.0 / loop_hz;

        // 3) Sensor fusion / state estimation
        estimator.predict(sensors.imu, dt);
        State state = estimator.correctWithEncoders(sensors.enc, dt);

        // 4) Control law
        double v_cmd = linear_pid.update(target_v, state.v, dt);
        double theta_cmd = angular_pid.update(target_theta, state.theta, dt);

        // 5) Mix into left/right motor commands
        // Differential drive mixing
        double left = v_cmd - theta_cmd;
        double right = v_cmd + theta_cmd;

        // 6) Send to motors
        motors.setMotorCommands(left, right);

        // 7) Diagnostics
        std::cout << "State => x: " << state.x
                  << " y: " << state.y
                  << " theta: " << state.theta
                  << " v: " << state.v << "\n";

        // 8) Maintain fixed rate
        next_tick += std::chrono::duration_cast<Clock::duration>(loop_period);
        std::this_thread::sleep_until(next_tick);
    }

    return 0;
}
