#include <iostream>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>
#include <cmath>
#include <array>

// -----------------------------
// Utility
// -----------------------------
using Clock = std::chrono::steady_clock;
using namespace std::chrono;

template <typename T>
T clamp(T v, T lo, T hi) {
    return std::max(lo, std::min(v, hi));
}

// -----------------------------
// Sensor Data
// -----------------------------
struct IMUData {
    double accel_x = 0.0;   // m/s^2
    double accel_y = 0.0;
    double accel_z = 0.0;
    double gyro_x  = 0.0;   // rad/s
    double gyro_y  = 0.0;
    double gyro_z  = 0.0;
    Clock::time_point timestamp;
};

struct EncoderData {
    double left_ticks = 0.0;
    double right_ticks = 0.0;
    Clock::time_point timestamp;
};

struct RobotState {
    double roll = 0.0;      // rad
    double pitch = 0.0;     // rad
    double yaw = 0.0;       // rad
    double vel_left = 0.0;  // m/s
    double vel_right = 0.0;
};

// -----------------------------
// PID Controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double out_min, double out_max)
        : kp_(kp), ki_(ki), kd_(kd), out_min_(out_min), out_max_(out_max) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;

        // Anti-windup
        integral_ = clamp(integral_, -integral_limit_, integral_limit_);

        double derivative = (dt > 1e-9) ? (error - prev_error_) / dt : 0.0;
        prev_error_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        return clamp(output, out_min_, out_max_);
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

    void setIntegralLimit(double limit) { integral_limit_ = std::abs(limit); }

private:
    double kp_, ki_, kd_;
    double out_min_, out_max_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
    double integral_limit_ = 100.0;
};

// -----------------------------
// Complementary Filter
// -----------------------------
class ComplementaryFilter {
public:
    // alpha close to 1.0 means trust gyro more
    ComplementaryFilter(double alpha = 0.98) : alpha_(alpha) {}

    void update(const IMUData& imu, double dt, RobotState& state) {
        // Estimate roll and pitch from accelerometer
        double accel_roll  = std::atan2(imu.accel_y, imu.accel_z);
        double accel_pitch = std::atan2(-imu.accel_x,
                                        std::sqrt(imu.accel_y * imu.accel_y + imu.accel_z * imu.accel_z));

        // Integrate gyro
        state.roll  = alpha_ * (state.roll  + imu.gyro_x * dt) + (1.0 - alpha_) * accel_roll;
        state.pitch = alpha_ * (state.pitch + imu.gyro_y * dt) + (1.0 - alpha_) * accel_pitch;
        state.yaw   = state.yaw + imu.gyro_z * dt; // no magnetometer here
    }

private:
    double alpha_;
};

