        std::cout << "Motor PWM -> Left: " << left << " Right: " << right << "\n";
    }
};

// -----------------------------
// Sensor Fusion + Control System
// -----------------------------
class RobotController {
public:
    RobotController()
        : pitch_pid_(2.0, 0.5, 0.05, -255.0, 255.0),
          left_speed_pid_(1.0, 0.2, 0.01, -255.0, 255.0),
          right_speed_pid_(1.0, 0.2, 0.01, -255.0, 255.0) {}

    void updateSensors() {
        std::lock_guard<std::mutex> lock(sensor_mutex_);
        latest_imu_ = hw_.readIMU();
        latest_enc_ = hw_.readEncoders();
        new_sensor_data_ = true;
    }

    void controlLoop(double dt) {
        IMUData imu;
        EncoderData enc;

        {
            std::lock_guard<std::mutex> lock(sensor_mutex_);
            imu = latest_imu_;
            enc = latest_enc_;
            new_sensor_data_ = false;
        }

        // Update state estimate
        fusion_.update(imu, dt, state_);

        // Convert encoder ticks to velocity (placeholder)
        double measured_left_speed  = enc.left_ticks * 0.001;
        double measured_right_speed = enc.right_ticks * 0.001;

        state_.vel_left = measured_left_speed;
        state_.vel_right = measured_right_speed;

        // Example control objective:
        // - keep robot upright using pitch PID
        // - match wheel speeds to a target
        double target_pitch = 0.0; // upright
        double balance_correction = pitch_pid_.update(target_pitch, state_.pitch, dt);

        double target_speed_left = 0.5;   // m/s
        double target_speed_right = 0.5;  // m/s

        double speed_correction_left = left_speed_pid_.update(target_speed_left, measured_left_speed, dt);
        double speed_correction_right = right_speed_pid_.update(target_speed_right, measured_right_speed, dt);

        double motor_left = balance_correction + speed_correction_left;
        double motor_right = balance_correction + speed_correction_right;

        motor_left = clamp(motor_left, -255.0, 255.0);
        motor_right = clamp(motor_right, -255.0, 255.0);

        hw_.setMotorPWM(motor_left, motor_right);
    }

    void run() {
        constexpr double control_hz = 200.0;
        const auto cycle = duration<double>(1.0 / control_hz);

        auto next_time = Clock::now();

        while (running_) {
            // Sensor update can run in same thread or separate thread
            updateSensors();

            auto start = Clock::now();

            if (new_sensor_data_) {
                controlLoop(1.0 / control_hz);
            }

            next_time += duration_cast<Clock::duration>(cycle);
            std::this_thread::sleep_until(next_time);

            auto elapsed = duration<double>(Clock::now() - start).count();
            if (elapsed > (1.0 / control_hz)) {
                std::cerr << "Warning: control loop overran by "
                          << (elapsed - 1.0 / control_hz) * 1000.0 << " ms\n";
            }
        }
    }

    void stop() {
        running_ = false;
    }

private:
    HardwareInterface hw_;
    ComplementaryFilter fusion_{0.98};

    RobotState state_;

    PID pitch_pid_;
    PID left_speed_pid_;
    PID right_speed_pid_;

    std::mutex sensor_mutex_;
    IMUData latest_imu_;
    EncoderData latest_enc_;
    bool new_sensor_data_ = false;

    std::atomic<bool> running_{true};
};

// -----------------------------
// Main
// -----------------------------
int main() {
    RobotController controller;

    std::thread control_thread([&]() {
        controller.run();
    });

    // Run for some time in this demo
    std::this_thread::sleep_for(std::chrono::seconds(5));
    controller.stop();

    control_thread.join();
    return 0;
}
