#define WINDOW_SIZE         32      // rolling statistics window
#define HPF_ALPHA           0.95f   // closer to 1.0 = lower cutoff
#define ANOMALY_Z_THRESHOLD 3.5f    // z-score threshold
#define MIN_STDDEV          0.05f   // avoid divide-by-zero / tiny variance

/* =========================
 * Types
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    // High-pass filter state
    float prev_in_x, prev_in_y, prev_in_z;
    float prev_out_x, prev_out_y, prev_out_z;

    // Rolling magnitude buffer
    float mag_buf[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // Rolling statistics
    float sum;
    float sum_sq;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float vector_magnitude(float x, float y, float z) {
    return fast_sqrtf(x * x + y * y + z * z);
}

/* =========================
 * Initialization
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *d) {
    d->prev_in_x = d->prev_in_y = d->prev_in_z = 0.0f;
    d->prev_out_x = d->prev_out_y = d->prev_out_z = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_buf[i] = 0.0f;
    }

    d->idx = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->sum_sq = 0.0f;
}

/* =========================
 * High-pass filter
 * Simple one-pole HPF:
 * y[n] = alpha * (y[n-1] + x[n] - x[n-1])
 * ========================= */
static inline float hpf_step(float x, float *prev_in, float *prev_out) {
    float y = HPF_ALPHA * (*prev_out + x - *prev_in);
    *prev_in = x;
    *prev_out = y;
    return y;
}

static void high_pass_filter(const accel_sample_t *in, accel_sample_t *out, anomaly_detector_t *d) {
    out->x = hpf_step(in->x, &d->prev_in_x, &d->prev_out_x);
    out->y = hpf_step(in->y, &d->prev_in_y, &d->prev_out_y);
    out->z = hpf_step(in->z, &d->prev_in_z, &d->prev_out_z);
}

/* =========================
 * Rolling statistics update
 * ========================= */
static void rolling_stats_update(anomaly_detector_t *d, float new_val) {
    if (d->count < WINDOW_SIZE) {
        d->mag_buf[d->idx] = new_val;
        d->sum += new_val;
        d->sum_sq += new_val * new_val;
        d->count++;
        d->idx = (d->idx + 1) % WINDOW_SIZE;
    } else {
        float old_val = d->mag_buf[d->idx];
        d->sum -= old_val;
        d->sum_sq -= old_val * old_val;

        d->mag_buf[d->idx] = new_val;
        d->sum += new_val;
        d->sum_sq += new_val * new_val;

        d->idx = (d->idx + 1) % WINDOW_SIZE;
    }
}

static void rolling_stats_get(const anomaly_detector_t *d, float *mean, float *stddev) {
    if (d->count == 0) {
        *mean = 0.0f;
        *stddev = MIN_STDDEV;
        return;
    }

    *mean = d->sum / (float)d->count;

    float var = (d->sum_sq / (float)d->count) - (*mean * *mean);
    if (var < 0.0f) var = 0.0f;

    *stddev = fast_sqrtf(var);
    if (*stddev < MIN_STDDEV) {
        *stddev = MIN_STDDEV;
    }
}

/* =========================
 * Main processing function
 * Returns true if anomaly detected
 * ========================= */
bool anomaly_detector_process(anomaly_detector_t *d,
                              const accel_sample_t *raw,
                              float *out_score,
                              float *out_baseline_mean,
                              float *out_baseline_stddev)
{
    // 1) Filter
    accel_sample_t filtered;
    high_pass_filter(raw, &filtered, d);

    // 2) Feature extraction: magnitude of filtered signal
    float mag = vector_magnitude(filtered.x, filtered.y, filtered.z);

    // 3) Update baseline stats
    rolling_stats_update(d, mag);

    // 4) Compute baseline mean/stddev
    float mean, stddev;
    rolling_stats_get(d, &mean, &stddev);

    // 5) Z-score anomaly score
    float z = fabsf(mag - mean) / stddev;

    if (out_score) *out_score = z;
    if (out_baseline_mean) *out_baseline_mean = mean;
    if (out_baseline_stddev) *out_baseline_stddev = stddev;

    return (d->count >= WINDOW_SIZE) && (z > ANOMALY_Z_THRESHOLD);
}

