/*
 * Embedded accelerometer anomaly detector
 * - Fixed-size, allocation-free
 * - Designed for MCU use
 * - Computes a simple high-pass magnitude feature and running statistics
 * - Flags anomalies when z-score exceeds threshold
 *
 * Assumptions:
 * - Called at a fixed sample rate
 * - Input accelerometer data is in raw units or mg, but consistent
 * - You can tune thresholds and filter constants for your sensor
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef SAMPLE_RATE_HZ
#define SAMPLE_RATE_HZ 100
#endif

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef ANOMALY_Z_THRESHOLD
#define ANOMALY_Z_THRESHOLD 4.0f
#endif

#ifndef MIN_STD_EPS
#define MIN_STD_EPS 1e-3f
#endif

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // High-pass / baseline tracking
    float baseline_mag;
    float hp_alpha;   // 0..1, closer to 1 = slower baseline

    // Running window statistics over feature
    float window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
    float sum_sq;

    // State
    bool initialized;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void anomaly_detector_init(anomaly_detector_t *det, float baseline_alpha) {
    if (!det) return;

    det->baseline_mag = 0.0f;
    det->hp_alpha = baseline_alpha;
    det->idx = 0;
    det->count = 0;
    det->sum = 0.0f;
    det->sum_sq = 0.0f;
    det->initialized = false;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        det->window[i] = 0.0f;
    }
}

static void window_push(anomaly_detector_t *det, float v) {
    if (det->count < WINDOW_SIZE) {
        det->window[det->idx] = v;
        det->sum += v;
        det->sum_sq += v * v;
        det->idx = (det->idx + 1) % WINDOW_SIZE;
        det->count++;
    } else {
        float old = det->window[det->idx];
        det->sum -= old;
        det->sum_sq -= old * old;

        det->window[det->idx] = v;
        det->sum += v;
        det->sum_sq += v * v;
        det->idx = (det->idx + 1) % WINDOW_SIZE;
    }
}

static void window_stats(const anomaly_detector_t *det, float *mean, float *stddev) {
    if (det->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float n = (float)det->count;
    float m = det->sum / n;
    float var = (det->sum_sq / n) - (m * m);
    if (var < 0.0f) var = 0.0f;

    *mean = m;
    *stddev = fast_sqrtf(var);
}

/*
 * Process one accelerometer sample.
 *
 * Returns true if anomaly detected.
 * out_score: optional z-score-like value
 * out_feature: optional filtered feature used for detection
 */
bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              float *out_score,
                              float *out_feature)
{
    if (!det || !sample) return false;

    float mag = compute_magnitude(sample);

    if (!det->initialized) {
        det->baseline_mag = mag;
        det->initialized = true;
    }

    // Exponential moving baseline to remove gravity / slow drift
    det->baseline_mag = det->hp_alpha * det->baseline_mag + (1.0f - det->hp_alpha) * mag;

    // High-pass feature: deviation from baseline
    float feature = mag - det->baseline_mag;
    if (feature < 0.0f) feature = -feature;

    // Update stats window
    window_push(det, feature);

    float mean, stddev;
    window_stats(det, &mean, &stddev);

    float denom = (stddev > MIN_STD_EPS) ? stddev : MIN_STD_EPS;
    float z = (feature - mean) / denom;
    if (z < 0.0f) z = -z;

    if (out_score)   *out_score = z;
    if (out_feature) *out_feature = feature;

    // Require a few samples before trusting detection
    if (det->count < (WINDOW_SIZE / 2)) {
        return false;
    }

    return (z > ANOMALY_Z_THRESHOLD);
}

