/*
 * Embedded accelerometer anomaly detector
 *
 * Pipeline:
 *   1) Read raw accelerometer samples
 *   2) Convert to g
 *   3) Low-pass filter
 *   4) Compute magnitude
 *   5) Maintain rolling baseline (mean / variance)
 *   6) Flag anomaly when deviation exceeds threshold for N consecutive samples
 *
 * Designed for small MCUs:
 *   - No dynamic allocation
 *   - Fixed-size rolling window
 *   - O(1) update per sample
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define ACC_WINDOW_SIZE        32
#define ANOMALY_Z_THRESHOLD    3.5f
#define ANOMALY_CONSECUTIVE    3
#define LPF_ALPHA              0.15f   /* 0..1, higher = less smoothing */

/* Sensor scale example: ±2g, 16-bit signed raw output */
#define ACC_RAW_TO_G           (2.0f / 32768.0f)

/* ---------------- Data Types ---------------- */

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_raw_t;

typedef struct {
    float x;
    float y;
    float z;
} accel_f_t;

typedef struct {
    float buf[ACC_WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum;
    float sumsq;
} rolling_stats_t;

typedef struct {
    accel_f_t lpf_state;
    rolling_stats_t mag_stats;
    uint8_t anomaly_streak;
    bool initialized;
} anomaly_detector_t;

/* ---------------- Rolling Stats ---------------- */

static void rolling_stats_init(rolling_stats_t *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (uint8_t i = 0; i < ACC_WINDOW_SIZE; i++) {
        s->buf[i] = 0.0f;
    }
}

static void rolling_stats_update(rolling_stats_t *s, float x) {
    if (s->count < ACC_WINDOW_SIZE) {
        s->buf[s->idx] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->count++;
        s->idx = (s->idx + 1) % ACC_WINDOW_SIZE;
    } else {
        float old = s->buf[s->idx];
        s->buf[s->idx] = x;
        s->sum += x - old;
        s->sumsq += (x * x) - (old * old);
        s->idx = (s->idx + 1) % ACC_WINDOW_SIZE;
    }
}

static float rolling_stats_mean(const rolling_stats_t *s) {
    if (s->count == 0) return 0.0f;
    return s->sum / (float)s->count;
}

static float rolling_stats_variance(const rolling_stats_t *s) {
    if (s->count < 2) return 0.0f;
    float n = (float)s->count;
    float mean = s->sum / n;
    float var = (s->sumsq / n) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

/* ---------------- Detector ---------------- */

static void anomaly_detector_init(anomaly_detector_t *d) {
    d->lpf_state.x = 0.0f;
    d->lpf_state.y = 0.0f;
    d->lpf_state.z = 0.0f;
    rolling_stats_init(&d->mag_stats);
    d->anomaly_streak = 0;
    d->initialized = false;
}

static accel_f_t raw_to_g(accel_raw_t r) {
    accel_f_t g;
    g.x = (float)r.x * ACC_RAW_TO_G;
    g.y = (float)r.y * ACC_RAW_TO_G;
    g.z = (float)r.z * ACC_RAW_TO_G;
    return g;
}

static accel_f_t low_pass_filter(anomaly_detector_t *d, accel_f_t in) {
    if (!d->initialized) {
        d->lpf_state = in;
        d->initialized = true;
        return in;
    }

    d->lpf_state.x = LPF_ALPHA * in.x + (1.0f - LPF_ALPHA) * d->lpf_state.x;
    d->lpf_state.y = LPF_ALPHA * in.y + (1.0f - LPF_ALPHA) * d->lpf_state.y;
    d->lpf_state.z = LPF_ALPHA * in.z + (1.0f - LPF_ALPHA) * d->lpf_state.z;

    return d->lpf_state;
}

static float accel_magnitude(accel_f_t a) {
    return sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}

/*
 * Returns true if anomaly detected on this sample.
 * Strategy:
 *   - Use rolling mean/std of filtered magnitude
 *   - Compute z-score
 *   - Require consecutive threshold crossings
 */
bool anomaly_detector_process(anomaly_detector_t *d, accel_raw_t sample) {
    accel_f_t g = raw_to_g(sample);
    accel_f_t filtered = low_pass_filter(d, g);
    float mag = accel_magnitude(filtered);

    /* Update stats after computing current deviation,
       so current sample doesn't bias its own threshold too much */
    float mean = rolling_stats_mean(&d->mag_stats);
    float var = rolling_stats_variance(&d->mag_stats);
    float stddev = sqrtf(var);

    bool anomaly_now = false;

    if (d->mag_stats.count >= 8 && stddev > 1e-6f) {
        float z = fabsf(mag - mean) / stddev;
        if (z > ANOMALY_Z_THRESHOLD) {
            d->anomaly_streak++;
            if (d->anomaly_streak >= ANOMALY_CONSECUTIVE) {
                anomaly_now = true;
            }
        } else {
            d->anomaly_streak = 0;
        }
    }

    rolling_stats_update(&d->mag_stats, mag);
    return anomaly_now;
}

/* ---------------- Example Hook ----------------
 *
 * Replace these with your platform-specific sensor read / event handling.
 */

extern bool accel_read_raw(accel_raw_t *out_sample);
extern void report_anomaly(float magnitude);

void sensor_task_loop(void) {
    static anomaly_detector_t detector;
    static bool inited = false;

    if (!inited) {
        anomaly_detector_init(&detector);
        inited = true;
    }

    accel_raw_t sample;
    if (accel_read_raw(&sample)) {
        bool anomaly = anomaly_detector_process(&detector, sample);
        if (anomaly) {
            accel_f_t g = raw_to_g(sample);
            float mag = accel_magnitude(g);
            report_anomaly(mag);
        }
    }
}
