Below is a compact C implementation for an embedded accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples,
- applies a simple low-pass filter,
- computes signal magnitude,
- maintains a rolling baseline and variance,
- flags anomalies when the magnitude deviates significantly from the baseline.

This is designed to be lightweight enough for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define ALPHA           0.1f      // Low-pass filter coefficient
#define ANOMALY_Z       3.0f      // Threshold in standard deviations
#define MIN_VARIANCE    1e-4f

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float lp_x, lp_y, lp_z;
    float baseline_mean;
    float baseline_m2;
    uint32_t count;
    float window[WINDOW_SIZE];
    uint8_t window_idx;
    bool window_full;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    // For embedded targets without full libm, replace with a platform-specific fast sqrt.
    return sqrtf(x);
}

void detector_init(anomaly_detector_t *d) {
    d->lp_x = d->lp_y = d->lp_z = 0.0f;
    d->baseline_mean = 0.0f;
    d->baseline_m2 = 0.0f;
    d->count = 0;
    d->window_idx = 0;
    d->window_full = false;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->window[i] = 0.0f;
    }
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

bool detector_process_sample(anomaly_detector_t *d, const accel_sample_t *raw, float *out_score) {
    // 1) Low-pass filter each axis
    d->lp_x += ALPHA * (raw->x - d->lp_x);
    d->lp_y += ALPHA * (raw->y - d->lp_y);
    d->lp_z += ALPHA * (raw->z - d->lp_z);

    accel_sample_t filtered = { d->lp_x, d->lp_y, d->lp_z };

    // 2) Compute magnitude
    float mag = compute_magnitude(&filtered);

    // 3) Update rolling window
    d->window[d->window_idx] = mag;
    d->window_idx = (d->window_idx + 1) % WINDOW_SIZE;
    if (d->window_idx == 0) {
        d->window_full = true;
    }

    // 4) Compute baseline mean/variance from window
    uint32_t n = d->window_full ? WINDOW_SIZE : d->window_idx;
    if (n < 2) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    float sum = 0.0f;
    for (uint32_t i = 0; i < n; i++) {
        sum += d->window[i];
    }
    float mean = sum / (float)n;

    float var_sum = 0.0f;
    for (uint32_t i = 0; i < n; i++) {
        float diff = d->window[i] - mean;
        var_sum += diff * diff;
    }
    float variance = var_sum / (float)(n - 1);
    if (variance < MIN_VARIANCE) variance = MIN_VARIANCE;

    float stddev = fast_sqrtf(variance);

    // 5) Anomaly score = z-score of current magnitude vs baseline
    float z = (mag - mean) / stddev;
    if (out_score) *out_score = z;

    // 6) Detect anomaly
    return (fabsf(z) > ANOMALY_Z);
}
