    float y;
    float z;
} accel_g_t;

typedef struct {
    float mean_x;
    float mean_y;
    float mean_z;

    float prev_mag;
    uint16_t cooldown;

    float mag_window[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
} anomaly_detector_t;

typedef struct {
    bool anomaly;
    float peak;
    float rms;
    float jerk;
} anomaly_result_t;

/* ---------------- Hardware-specific hook ----------------
 * Replace this with your I2C/SPI/ADC read function.
 */
extern bool accel_read_raw(accel_raw_t *out);

/* Convert raw counts to g; adjust scale for your sensor. */
static inline accel_g_t accel_convert_to_g(const accel_raw_t *r)
{
    const float scale = 0.000061f; // example: 16-bit sensor, +/-2g
    accel_g_t a;
    a.x = (float)r->x_raw * scale;
    a.y = (float)r->y_raw * scale;
    a.z = (float)r->z_raw * scale;
    return a;
}

static inline float fast_sqrtf(float x)
{
    return sqrtf(x);
}

/* ---------------- Detector API ---------------- */

void anomaly_detector_init(anomaly_detector_t *d)
{
    d->mean_x = 0.0f;
    d->mean_y = 0.0f;
    d->mean_z = 0.0f;
    d->prev_mag = 0.0f;
    d->cooldown = 0;

    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
    d->idx = 0;
    d->count = 0;
}

static anomaly_result_t anomaly_detector_update(anomaly_detector_t *d, accel_raw_t raw)
{
    anomaly_result_t res = {0};

    accel_g_t a = accel_convert_to_g(&raw);

    /* Running mean removal (simple high-pass approximation) */
    d->mean_x += (a.x - d->mean_x) / (float)(1u << MEAN_ALPHA_SHIFT);
    d->mean_y += (a.y - d->mean_y) / (float)(1u << MEAN_ALPHA_SHIFT);
    d->mean_z += (a.z - d->mean_z) / (float)(1u << MEAN_ALPHA_SHIFT);

    float dx = a.x - d->mean_x;
    float dy = a.y - d->mean_y;
    float dz = a.z - d->mean_z;

    /* Magnitude after detrending */
    float mag = fast_sqrtf(dx * dx + dy * dy + dz * dz);

    /* Update window */
    d->mag_window[d->idx] = mag;
    d->idx = (uint8_t)((d->idx + 1u) % WINDOW_SIZE);
    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    /* Compute peak and RMS over window */
    float sum_sq = 0.0f;
    float peak = 0.0f;
    for (uint8_t i = 0; i < d->count; i++) {
        float v = d->mag_window[i];
        sum_sq += v * v;
        if (v > peak) peak = v;
    }
    float rms = (d->count > 0) ? fast_sqrtf(sum_sq / (float)d->count) : 0.0f;

    /* Jerk estimate: magnitude derivative */
    float jerk = (mag - d->prev_mag) * (float)SAMPLE_RATE_HZ;
    d->prev_mag = mag;
    if (jerk < 0.0f) jerk = -jerk;

    /* Decision logic */
    bool over_threshold =
        (peak > PEAK_THRESHOLD_G) ||
        (rms > RMS_THRESHOLD_G) ||
        (jerk > JERK_THRESHOLD_GS);

    if (d->cooldown > 0) {
        d->cooldown--;
    } else if (over_threshold && d->count == WINDOW_SIZE) {
        res.anomaly = true;
        d->cooldown = ANOMALY_COOLDOWN;
    }

    res.peak = peak;
    res.rms = rms;
    res.jerk = jerk;
    return res;
}

/* ---------------- Example main loop ----------------
 * Call this from your RTOS task or bare-metal polling loop.
 */
void sensor_pipeline_task(void)
{
    static anomaly_detector_t detector;
    static bool initialized = false;

    if (!initialized) {
        anomaly_detector_init(&detector);
        initialized = true;
    }

    accel_raw_t raw;
    if (accel_read_raw(&raw)) {
        anomaly_result_t r = anomaly_detector_update(&detector, raw);

        if (r.anomaly) {
            /* TODO: log event, raise interrupt, send packet, etc. */
            // e.g., set a GPIO, store timestamp, or notify a host.
        }
    }
}
