Below is a compact embedded-friendly C example of an accelerometer anomaly-detection pipeline. It:

- reads raw accelerometer samples
- applies a simple low-pass filter
- computes a rolling magnitude-based feature
- maintains a baseline mean/variance with Welford’s algorithm
- flags anomalies using a z-score threshold

It is designed to be lightweight for microcontrollers and easy to adapt.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define BASELINE_MIN_SAMPLES 64
#define Z_THRESHOLD         3.5f
#define ALPHA               0.1f   // low-pass filter coefficient

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Low-pass filtered values
    float fx, fy, fz;

    // Rolling window of magnitudes
    float mag_window[WINDOW_SIZE];
    uint8_t win_idx;
    uint8_t win_count;
    float win_sum;

    // Baseline statistics on windowed magnitude
    uint32_t baseline_n;
    float baseline_mean;
    float baseline_m2;

    // State
    bool initialized;
} AnomalyDetector;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float accel_magnitude(const AccelSample *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* =========================
 * Initialization
 * ========================= */
void detector_init(AnomalyDetector *d) {
    d->fx = d->fy = d->fz = 0.0f;
    d->win_idx = 0;
    d->win_count = 0;
    d->win_sum = 0.0f;
    d->baseline_n = 0;
    d->baseline_mean = 0.0f;
    d->baseline_m2 = 0.0f;
    d->initialized = true;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
}

/* =========================
 * Baseline update (Welford)
 * ========================= */
static void baseline_update(AnomalyDetector *d, float value) {
    d->baseline_n++;
    float delta = value - d->baseline_mean;
    d->baseline_mean += delta / (float)d->baseline_n;
    float delta2 = value - d->baseline_mean;
    d->baseline_m2 += delta * delta2;
}

static float baseline_stddev(const AnomalyDetector *d) {
    if (d->baseline_n < 2) return 0.0f;
    return fast_sqrtf(d->baseline_m2 / (float)(d->baseline_n - 1));
}

/* =========================
 * Rolling window update
 * ========================= */
static float window_update(AnomalyDetector *d, float new_mag) {
    if (d->win_count < WINDOW_SIZE) {
        d->mag_window[d->win_idx] = new_mag;
        d->win_sum += new_mag;
        d->win_count++;
    } else {
        float old = d->mag_window[d->win_idx];
        d->win_window[d->win_idx] = new_mag; // <-- typo fixed below
    }

    d->win_idx = (d->win_idx + 1) % WINDOW_SIZE;

    // Return current window mean
    return d->win_sum / (float)d->win_count;
}

/* Corrected rolling window update */
static float window_update_fixed(AnomalyDetector *d, float new_mag) {
    if (d->win_count < WINDOW_SIZE) {
        d->mag_window[d->win_idx] = new_mag;
        d->win_sum += new_mag;
        d->win_count++;
    } else {
        float old = d->mag_window[d->win_idx];
        d->win_sum -= old;
        d->mag_window[d->win_idx] = new_mag;
        d->win_sum += new_mag;
    }

    d->win_idx = (d->win_idx + 1) % WINDOW_SIZE;
    return d->win_sum / (float)d->win_count;
}

/* =========================
 * Main processing step
 * Returns true if anomaly detected
 * ========================= */
bool detector_process(AnomalyDetector *d, const AccelSample *raw_sample) {
    if (!d->initialized) {
        detector_init(d);
    }

    // 1) Low-pass filter
    d->fx = ALPHA * raw_sample->x + (1.0f - ALPHA) * d->fx;
    d->fy = ALPHA * raw_sample->y + (1.0f - ALPHA) * d->fy;
    d->fz = ALPHA * raw_sample->z + (1.0f - ALPHA) * d->fz;

    AccelSample filtered = { d->fx, d->fy, d->fz };

    // 2) Feature extraction: magnitude
    float mag = accel_magnitude(&filtered);

    // 3) Rolling mean of magnitude
    float win_mean = window_update_fixed(d, mag);

    // 4) Build baseline during startup
    if (d->baseline_n < BASELINE_MIN_SAMPLES) {
        baseline_update(d, win_mean);
        return false; // do not flag anomalies during baseline learning
    }

    // 5) Compute z-score against baseline
    float stddev = baseline_stddev(d);
    if (stddev < 1e-6f) {
        return false;
    }

    float z = (win_mean - d->baseline_mean) / stddev;
    if (z < 0.0f) z = -z;

    // 6) Optional slow adaptation of baseline when not anomalous
    if (z < Z_THRESHOLD) {
        // gentle update to track slow drift
        baseline_update(d, win_mean);
    }

    // 7) Anomaly decision
    return (z >= Z_THRESHOLD);
}
