Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis samples
- applies a simple high-pass filter to reduce gravity/DC offset
- computes signal magnitude
- tracks a rolling baseline and variance with an exponential moving average
- flags anomalies when the magnitude deviates too far from the baseline

This is designed to be lightweight for microcontrollers and easy to adapt.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define ALPHA_BASELINE   0.01f   // baseline adaptation rate
#define ALPHA_VAR        0.01f   // variance adaptation rate
#define HPF_ALPHA        0.95f   // high-pass filter coefficient
#define ANOMALY_Z_THRESH 3.0f    // anomaly threshold in std devs
#define MIN_STD_DEV      0.05f   // avoid division by very small values

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float hpf_x, hpf_y, hpf_z;
    float prev_x, prev_y, prev_z;

    float baseline;
    float variance;
    bool initialized;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

/* =========================
 * Initialization
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det) {
    det->hpf_x = det->hpf_y = det->hpf_z = 0.0f;
    det->prev_x = det->prev_y = det->prev_z = 0.0f;
    det->baseline = 0.0f;
    det->variance = 1.0f;
    det->initialized = false;
}

/* =========================
 * High-pass filter
 * Removes slow-changing components (e.g., gravity bias)
 * ========================= */
static void high_pass_filter(anomaly_detector_t *det,
                             const accel_sample_t *in,
                             accel_sample_t *out) {
    det->hpf_x = HPF_ALPHA * (det->hpf_x + in->x - det->prev_x);
    det->hpf_y = HPF_ALPHA * (det->hpf_y + in->y - det->prev_y);
    det->hpf_z = HPF_ALPHA * (det->hpf_z + in->z - det->prev_z);

    det->prev_x = in->x;
    det->prev_y = in->y;
    det->prev_z = in->z;

    out->x = det->hpf_x;
    out->y = det->hpf_y;
    out->z = det->hpf_z;
}

/* =========================
 * Process one sample
 * Returns true if anomaly detected
 * ========================= */
bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              float *out_score) {
    accel_sample_t filtered;
    high_pass_filter(det, sample, &filtered);

    // Signal magnitude
    float mag = fast_sqrtf(filtered.x * filtered.x +
                           filtered.y * filtered.y +
                           filtered.z * filtered.z);

    if (!det->initialized) {
        det->baseline = mag;
        det->variance = 1.0f;
        det->initialized = true;
        if (out_score) *out_score = 0.0f;
        return false;
    }

    // Update baseline and variance using EMA
    float diff = mag - det->baseline;
    det->baseline += ALPHA_BASELINE * diff;

    // Variance estimate around baseline
    float var_diff = (diff * diff) - det->variance;
    det->variance += ALPHA_VAR * var_diff;

    float stddev = fast_sqrtf(det->variance);
    if (stddev < MIN_STD_DEV) stddev = MIN_STD_DEV;

    float z = fabsf(mag - det->baseline) / stddev;
    if (out_score) *out_score = z;

    return (z > ANOMALY_Z_THRESH);
}
