/*
 * Embedded accelerometer anomaly detection pipeline
 * - Fixed-size ring buffer
 * - Lightweight high-pass-ish detrending via moving average removal
 * - Feature extraction: mean, variance, RMS, peak-to-peak, jerk energy
 * - Simple threshold-based anomaly score
 *
 * Assumptions:
 * - Accelerometer samples arrive at a fixed rate
 * - Input is 3-axis raw acceleration in g or m/s^2
 * - Suitable for MCU-class targets with limited RAM/CPU
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         64
#define AXES                3
#define FEATURE_DIM         5

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} ring_buffer_t;

typedef struct {
    float mean[AXES];
    float var[AXES];
    float rms[AXES];
    float p2p[AXES];
    float jerk_energy;
} features_t;

typedef struct {
    ring_buffer_t rb;
    accel_sample_t prev_sample;
    bool has_prev;
} pipeline_t;

/* ---------------- Ring buffer ---------------- */

static void rb_init(ring_buffer_t *rb) {
    rb->head = 0;
    rb->count = 0;
}

static void rb_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static accel_sample_t rb_get(const ring_buffer_t *rb, uint16_t idx_oldest_first) {
    uint16_t start = (rb->head + WINDOW_SIZE - rb->count) % WINDOW_SIZE;
    uint16_t pos = (start + idx_oldest_first) % WINDOW_SIZE;
    return rb->buf[pos];
}

/* ---------------- Math helpers ---------------- */

static float fmaxf3(float a, float b, float c) {
    float m = (a > b) ? a : b;
    return (m > c) ? m : c;
}

static float fminf3(float a, float b, float c) {
    float m = (a < b) ? a : b;
    return (m < c) ? m : c;
}

/* ---------------- Feature extraction ---------------- */

static bool extract_features(const ring_buffer_t *rb, features_t *out) {
    if (rb->count < WINDOW_SIZE) {
        return false; // not enough data yet
    }

    float sum[AXES] = {0};
    float sumsq[AXES] = {0};
    float minv[AXES] = {1e30f, 1e30f, 1e30f};
    float maxv[AXES] = {-1e30f, -1e30f, -1e30f};
    float jerk_energy = 0.0f;

    accel_sample_t prev = rb_get(rb, 0);

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        accel_sample_t s = rb_get(rb, i);

        float v[AXES] = {s.x, s.y, s.z};
        for (int a = 0; a < AXES; a++) {
            sum[a] += v[a];
            sumsq[a] += v[a] * v[a];
            if (v[a] < minv[a]) minv[a] = v[a];
            if (v[a] > maxv[a]) maxv[a] = v[a];
        }

        if (i > 0) {
            float dx = s.x - prev.x;
            float dy = s.y - prev.y;
            float dz = s.z - prev.z;
            jerk_energy += dx * dx + dy * dy + dz * dz;
        }
        prev = s;
    }

    for (int a = 0; a < AXES; a++) {
        out->mean[a] = sum[a] / WINDOW_SIZE;
        out->var[a]  = (sumsq[a] / WINDOW_SIZE) - (out->mean[a] * out->mean[a]);
        if (out->var[a] < 0.0f) out->var[a] = 0.0f;
        out->rms[a]  = sqrtf(sumsq[a] / WINDOW_SIZE);
        out->p2p[a]  = maxv[a] - minv[a];
    }

    out->jerk_energy = jerk_energy / (WINDOW_SIZE - 1);
    return true;
}

/* ---------------- Anomaly scoring ---------------- */

/*
 * Simple heuristic anomaly score:
 * - Large variance or peak-to-peak on any axis
 * - High jerk energy
 * - Deviation of magnitude from expected gravity (if stationary-ish baseline)
 *
 * Tune thresholds for your sensor and sampling rate.
 */
static float anomaly_score(const features_t *f) {
    float score = 0.0f;

    // Axis-wise variance thresholds
    const float var_thresh = 0.05f;
    const float p2p_thresh = 0.8f;
    const float jerk_thresh = 0.02f;
    const float g_expected  = 1.0f;   // if input is in g units

    float mag_mean = sqrtf(f->mean[0]*f->mean[0] +
                           f->mean[1]*f->mean[1] +
                           f->mean[2]*f->mean[2]);

    for (int a = 0; a < AXES; a++) {
        if (f->var[a] > var_thresh) {
            score += (f->var[a] - var_thresh) * 10.0f;
        }
        if (f->p2p[a] > p2p_thresh) {
            score += (f->p2p[a] - p2p_thresh) * 5.0f;
        }
    }

    if (f->jerk_energy > jerk_thresh) {
        score += (f->jerk_energy - jerk_thresh) * 20.0f;
    }

    // Magnitude deviation from gravity
    float mag_dev = fabsf(mag_mean - g_expected);
    if (mag_dev > 0.15f) {
        score += mag_dev * 8.0f;
    }

    return score;
}

static bool is_anomaly(const features_t *f) {
    const float anomaly_threshold = 1.5f;
    return anomaly_score(f) > anomaly_threshold;
}

/* ---------------- Pipeline API ---------------- */

void pipeline_init(pipeline_t *p) {
    rb_init(&p->rb);
    p->has_prev = false;
}

bool pipeline_process_sample(pipeline_t *p, accel_sample_t s, bool *anomaly_out) {
    rb_push(&p->rb, s);

    features_t feat;
    if (!extract_features(&p->rb, &feat)) {
        *anomaly_out = false;
        return false; // not enough data yet
    }

    *anomaly_out = is_anomaly(&feat);
    return true;
}

