    return sqrtf(x);
}

static inline float vec_mag(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

void anomaly_detector_init(anomaly_detector_t *d) {
    d->head = 0;
    d->count = 0;

    d->base_x = 0.0f;
    d->base_y = 0.0f;
    d->base_z = 0.0f;

    d->prev_fx = 0.0f;
    d->prev_fy = 0.0f;
    d->prev_fz = 0.0f;

    d->jerk_x = 0.0f;
    d->jerk_y = 0.0f;
    d->jerk_z = 0.0f;

    d->mean_mag = 0.0f;
    d->var_mag = 0.0f;

    d->anomaly_streak = 0;
    d->anomaly_flag = false;
}

static void update_stats(anomaly_detector_t *d, float mag) {
    // Exponential moving mean/variance
    float delta = mag - d->mean_mag;
    d->mean_mag += VAR_ALPHA * delta;
    float delta2 = mag - d->mean_mag;
    d->var_mag = (1.0f - VAR_ALPHA) * d->var_mag + VAR_ALPHA * (delta * delta2);
}

static bool compute_anomaly(anomaly_detector_t *d, float mag, float jerk_mag) {
    // Normalize features by their running stats / thresholds
    float energy_score = mag / (d->mean_mag + 1e-3f);
    float var_score    = d->var_mag / (VAR_THRESH + 1e-3f);
    float jerk_score   = jerk_mag / (JERK_THRESH + 1e-3f);

    bool hit = (energy_score > ENERGY_THRESH) ||
               (var_score > 1.0f) ||
               (jerk_score > 1.0f);

    if (hit) {
        if (d->anomaly_streak < 255) d->anomaly_streak++;
    } else {
        d->anomaly_streak = 0;
    }

    d->anomaly_flag = (d->anomaly_streak >= ANOMALY_HYST);
    return d->anomaly_flag;
}

/*
 * Feed one accelerometer sample.
 * Returns true if anomaly is detected.
 */
bool anomaly_detector_update(anomaly_detector_t *d, accel_sample_t s) {
    // Update baseline with slow EMA
    d->base_x += EMA_ALPHA * (s.x - d->base_x);
    d->base_y += EMA_ALPHA * (s.y - d->base_y);
    d->base_z += EMA_ALPHA * (s.z - d->base_z);

    // Remove baseline
    float fx = s.x - d->base_x;
    float fy = s.y - d->base_y;
    float fz = s.z - d->base_z;

    // Jerk estimate (smoothed derivative)
    float dx = fx - d->prev_fx;
    float dy = fy - d->prev_fy;
    float dz = fz - d->prev_fz;

    d->jerk_x += JERK_ALPHA * (dx - d->jerk_x);
    d->jerk_y += JERK_ALPHA * (dy - d->jerk_y);
    d->jerk_z += JERK_ALPHA * (dz - d->jerk_z);

    d->prev_fx = fx;
    d->prev_fy = fy;
    d->prev_fz = fz;

    float mag = vec_mag(fx, fy, fz);
    float jerk_mag = vec_mag(d->jerk_x, d->jerk_y, d->jerk_z);

    // Update running stats once we have enough samples
    if (d->count < WINDOW_SIZE) {
        d->buf[d->head] = s;
        d->head = (d->head + 1) % WINDOW_SIZE;
        d->count++;

        // Warm-up: establish stats but don't trigger anomalies yet
        update_stats(d, mag);
        return false;
    }

    d->buf[d->head] = s;
    d->head = (d->head + 1) % WINDOW_SIZE;

    update_stats(d, mag);
    return compute_anomaly(d, mag, jerk_mag);
}

