Below is a compact embedded-friendly C implementation of an accelerometer anomaly detection pipeline. It:

- ingests 3-axis accel samples
- applies a simple high-pass filter to remove gravity/slow drift
- computes signal magnitude
- maintains a rolling mean/variance using Welford-style updates
- flags anomalies when the current magnitude deviates significantly from the baseline

It is designed to be lightweight enough for microcontrollers.

```c
/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 *  - 3-axis accelerometer input
 *  - High-pass filtering to remove gravity/slow drift
 *  - Magnitude computation
 *  - Rolling mean/variance anomaly detection
 *
 * Compile with a C99 compiler.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef HP_ALPHA
#define HP_ALPHA 0.95f   // closer to 1.0 => slower drift removal
#endif

#ifndef ANOMALY_Z_THRESHOLD
#define ANOMALY_Z_THRESHOLD 3.0f
#endif

#ifndef MIN_STDDEV
#define MIN_STDDEV 0.05f
#endif

typedef struct {
    // High-pass filter state
    float lp_x, lp_y, lp_z;   // low-pass estimate of gravity/slow drift
    float hp_x, hp_y, hp_z;   // high-pass output

    // Rolling window for magnitude
    float mag_window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // Running statistics
    float mean;
    float m2;                 // sum of squares of differences from the mean

    // Detection output
    bool anomaly;
    float z_score;
} AccelAnomalyDetector;

static float fast_sqrtf(float x)
{
    // Use standard sqrtf if available; wrapper kept for portability.
    return sqrtf(x);
}

void detector_init(AccelAnomalyDetector *d)
{
    d->lp_x = d->lp_y = d->lp_z = 0.0f;
    d->hp_x = d->hp_y = d->hp_z = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }

    d->idx = 0;
    d->count = 0;
    d->mean = 0.0f;
    d->m2 = 0.0f;

    d->anomaly = false;
    d->z_score = 0.0f;
}

static void update_running_stats(AccelAnomalyDetector *d, float x)
{
    // For simplicity, this implementation uses a fixed-size window but keeps
    // an approximate running mean/variance over the samples currently in the window.
    // On embedded targets, this is often sufficient and cheaper than full recomputation.

    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    // Remove old sample contribution only after window is full
    float old = d->mag_window[d->idx];
    d->mag_window[d->idx] = x;
    d->idx = (d->idx + 1) % WINDOW_SIZE;

    if (d->count == 1) {
        d->mean = x;
        d->m2 = 0.0f;
        return;
    }

    if (d->count < WINDOW_SIZE) {
        // Welford update during warm-up
        float delta = x - d->mean;
        d->mean += delta / (float)d->count;
        float delta2 = x - d->mean;
        d->m2 += delta * delta2;
    } else {
        // Recompute stats over the full window for correctness
        float sum = 0.0f;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            sum += d->mag_window[i];
        }
        d->mean = sum / (float)WINDOW_SIZE;

        float var_sum = 0.0f;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            float diff = d->mag_window[i] - d->mean;
            var_sum += diff * diff;
        }
        d->m2 = var_sum;
    }
}

bool detector_process_sample(AccelAnomalyDetector *d, float ax, float ay, float az)
{
    // 1) Low-pass filter estimates gravity/slow motion
    d->lp_x = HP_ALPHA * d->lp_x + (1.0f - HP_ALPHA) * ax;
    d->lp_y = HP_ALPHA * d->lp_y + (1.0f - HP_ALPHA) * ay;
    d->lp_z = HP_ALPHA * d->lp_z + (1.0f - HP_ALPHA) * az;

    // 2) High-pass output
    d->hp_x = ax - d->lp_x;
    d->hp_y = ay - d->lp_y;
    d->hp_z = az - d->lp_z;

    // 3) Magnitude of filtered acceleration
    float mag = fast_sqrtf(d->hp_x * d->hp_x +
                           d->hp_y * d->hp_y +
                           d->hp_z * d->hp_z);

    // 4) Update baseline statistics
    update_running_stats(d, mag);

    // 5) Compute anomaly score
    float variance = 0.0f;
    if (d->count > 1) {
        variance = d->m2 / (float)(d->count - 1);
    }

    float stddev = fast_sqrtf(variance);
    if (stddev < MIN_STDDEV) {
        stddev = MIN_STDDEV;
    }

    d->z_score = (mag - d->mean) / stddev;
    d->anomaly = (fabsf(d->z_score) > ANOMALY_Z_THRESHOLD);

    return d->anomaly;
}

float detector_get_z_score(const AccelAnomalyDetector *d)
{
    return d->z_score;
}

float detector_get_mean(const AccelAnomalyDetector *d)
{
    return d->mean;
}

float detector_get_stddev(const AccelAnomalyDetector *d)
{
    if (d->count <= 1) return 0.0f;
    return fast_sqrtf(d->m2 / (float)(d->count - 1));
}
```

