Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline.

It does:
1. **Input buffering**
2. **High-pass filtering** to remove gravity / slow drift
3. **Feature extraction** over a sliding window
4. **Simple anomaly scoring** using energy and spike metrics
5. **Threshold-based detection** with hysteresis

This is designed for microcontrollers: no heap use, fixed-size buffers, small CPU cost.

---

## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
   Configuration
   ========================= */

#define AXIS_COUNT              3
#define WINDOW_SIZE             32      // samples per feature window
#define HP_ALPHA                0.95f   // high-pass filter coefficient
#define ENERGY_THRESHOLD        2.50f   // tune for your sensor scale
#define SPIKE_THRESHOLD         3.00f   // tune for your sensor scale
#define ANOMALY_HYSTERESIS      3       // consecutive windows before flagging
#define CLEAR_HYSTERESIS        5       // consecutive normal windows before clearing

/* =========================
   Data structures
   ========================= */

typedef struct {
    float hp_prev_input[AXIS_COUNT];
    float hp_prev_output[AXIS_COUNT];
} HighPassFilterState;

typedef struct {
    float samples[WINDOW_SIZE][AXIS_COUNT];
    uint16_t index;
    uint16_t count;
} WindowBuffer;

typedef struct {
    HighPassFilterState hp;
    WindowBuffer window;

    uint8_t anomaly_count;
    uint8_t normal_count;
    bool anomaly_active;
} SensorPipeline;

/* =========================
   Utility functions
   ========================= */

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

/* =========================
   High-pass filter
   y[n] = alpha * (y[n-1] + x[n] - x[n-1])
   ========================= */

static float high_pass_filter(float x, float *prev_x, float *prev_y) {
    float y = HP_ALPHA * (*prev_y + x - *prev_x);
    *prev_x = x;
    *prev_y = y;
    return y;
}

/* =========================
   Pipeline initialization
   ========================= */

void sensor_pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < AXIS_COUNT; i++) {
        p->hp.hp_prev_input[i] = 0.0f;
        p->hp.hp_prev_output[i] = 0.0f;
    }

    p->window.index = 0;
    p->window.count = 0;

    p->anomaly_count = 0;
    p->normal_count = 0;
    p->anomaly_active = false;
}

/* =========================
   Push one accelerometer sample
   accel: raw accelerometer reading in g or m/s^2
   Returns true when a window is ready for processing
   ========================= */

static bool window_push(WindowBuffer *w, const float accel[AXIS_COUNT]) {
    for (int i = 0; i < AXIS_COUNT; i++) {
        w->samples[w->index][i] = accel[i];
    }

    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }

    return (w->count == WINDOW_SIZE);
}

/* =========================
   Feature extraction
   Computes:
   - mean magnitude
   - RMS energy
   - max absolute deviation
   ========================= */

typedef struct {
    float mean_mag;
    float rms_energy;
    float max_abs;
} WindowFeatures;

static WindowFeatures extract_features(const WindowBuffer *w) {
    WindowFeatures f = {0};

    float sum_mag = 0.0f;
    float sum_sq = 0.0f;
    float max_abs = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        float x = w->samples[i][0];
        float y = w->samples[i][1];
        float z = w->samples[i][2];

        float mag = sqrtf(x * x + y * y + z * z);
        sum_mag += mag;

        float sample_energy = x * x + y * y + z * z;
        sum_sq += sample_energy;

        float ax = fast_absf(x);
        float ay = fast_absf(y);
        float az = fast_absf(z);

        if (ax > max_abs) max_abs = ax;
        if (ay > max_abs) max_abs = ay;
        if (az > max_abs) max_abs = az;
    }

    f.mean_mag = sum_mag / (float)WINDOW_SIZE;
    f.rms_energy = sqrtf(sum_sq / (float)WINDOW_SIZE);
    f.max_abs = max_abs;

    return f;
}

/* =========================
   Anomaly scoring
   Simple rule-based detector:
   - high RMS energy
   - large spike on any axis
   ========================= */

static bool detect_anomaly(const WindowFeatures *f) {
    bool energy_anomaly = (f->rms_energy > ENERGY_THRESHOLD);
    bool spike_anomaly  = (f->max_abs > SPIKE_THRESHOLD);

    return energy_anomaly || spike_anomaly;
}

/* =========================
   Process one sample
   accel_raw: raw sample
   Returns current anomaly state after processing
   ========================= */

bool sensor_pipeline_process(SensorPipeline *p, const float accel_raw[AXIS_COUNT]) {
    float filtered[AXIS_COUNT];

    // High-pass filter each axis
    for (int i = 0; i < AXIS_COUNT; i++) {
        filtered[i] = high_pass_filter(
            accel_raw[i],
            &p->hp.hp_prev_input[i],
            &p->hp.hp_prev_output[i]
        );
    }

    // Push filtered sample into window
    bool ready = window_push(&p->window, filtered);

    if (!ready) {
        return p->anomaly_active;
    }

    // Extract features and classify
    WindowFeatures features = extract_features(&p->window);
    bool anomaly = detect_anomaly(&features);

    // Hysteresis / debouncing
    if (anomaly) {
        p->anomaly_count++;
        p->normal_count = 0;

        if (p->anomaly_count >= ANOMALY_HYSTERESIS) {
            p->anomaly_active = true;
        }
    } else {
        p->normal_count++;
        p->anomaly_count = 0;

        if (p->normal_count >= CLEAR_HYSTERESIS) {
            p->anomaly_active = false;
        }
    }

    return p->anomaly_active;
}

/* =========================
   Example usage
   ========================= */

