        // Replace with actual sensor read
        sample[0] = 0.02f;
        sample[1] = -0.01f;
        sample[2] = 1.00f;

        bool anomaly = sensor_pipeline_process(&pipeline, sample);

        if (anomaly) {
            printf("Anomaly detected!\n");
        }
    }

    return 0;
}
