Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes signal magnitude
- maintains a rolling mean/variance using Welford-style updates
- flags anomalies when the current magnitude deviates beyond a threshold
- is designed to be lightweight for MCU/RTOS use

You can adapt the sampling rate, window size, and threshold for your sensor and application.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 * - 3-axis input in g-units or raw scaled units
 * - low-pass filtering
 * - magnitude computation
 * - rolling statistics
 * - anomaly detection via z-score threshold
 */

#define WINDOW_SIZE        32
#define LPF_ALPHA          0.2f
#define ZSCORE_THRESHOLD    3.0f

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    // Low-pass filtered state
    float fx, fy, fz;
    bool initialized;

    // Rolling window
    float mag_window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // Running stats
    float mean;
    float m2;
} anomaly_detector_t;

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void detector_init(anomaly_detector_t *d)
{
    d->fx = d->fy = d->fz = 0.0f;
    d->initialized = false;
    d->idx = 0;
    d->count = 0;
    d->mean = 0.0f;
    d->m2 = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
}

static void running_stats_recompute(anomaly_detector_t *d)
{
    d->mean = 0.0f;
    d->m2 = 0.0f;

    if (d->count == 0) return;

    for (uint16_t i = 0; i < d->count; i++) {
        float x = d->mag_window[i];
        float delta = x - d->mean;
        d->mean += delta / (float)(i + 1);
        float delta2 = x - d->mean;
        d->m2 += delta * delta2;
    }
}

static void running_stats_add(anomaly_detector_t *d, float value)
{
    if (d->count < WINDOW_SIZE) {
        d->mag_window[d->count++] = value;
    } else {
        d->mag_window[d->idx] = value;
        d->idx = (d->idx + 1) % WINDOW_SIZE;
    }
    running_stats_recompute(d);
}

static void low_pass_filter(anomaly_detector_t *d, const accel_sample_t *in, accel_sample_t *out)
{
    if (!d->initialized) {
        d->fx = in->x;
        d->fy = in->y;
        d->fz = in->z;
        d->initialized = true;
    } else {
        d->fx = LPF_ALPHA * in->x + (1.0f - LPF_ALPHA) * d->fx;
        d->fy = LPF_ALPHA * in->y + (1.0f - LPF_ALPHA) * d->fy;
        d->fz = LPF_ALPHA * in->z + (1.0f - LPF_ALPHA) * d->fz;
    }

    out->x = d->fx;
    out->y = d->fy;
    out->z = d->fz;
}

/*
 * Process one sample.
 * Returns true if anomaly detected.
 */
bool detector_process(anomaly_detector_t *d, const accel_sample_t *raw)
{
    accel_sample_t filtered;
    low_pass_filter(d, raw, &filtered);

    float mag = accel_magnitude(&filtered);

    // Need enough samples before detection is meaningful
    running_stats_add(d, mag);
    if (d->count < WINDOW_SIZE / 2) {
        return false;
    }

    // Compute standard deviation
    float variance = (d->count > 1) ? (d->m2 / (float)(d->count - 1)) : 0.0f;
    float stddev = sqrtf(variance);

    if (stddev < 1e-6f) {
        return false;
    }

    float z = fabsf(mag - d->mean) / stddev;
    return (z > ZSCORE_THRESHOLD);
}

/* Example usage */
#ifdef DEMO_MAIN
#include <stdio.h>

int main(void)
{
    anomaly_detector_t detector;
    detector_init(&detector);

    // Example stream
    accel_sample_t stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.02f, 0.01f, 0.99f},
        {0.00f, 0.03f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {2.50f, 0.10f, 1.80f}, // anomaly
    };

    for (unsigned i = 0; i < sizeof(stream)/sizeof(stream[0]); i++) {
        bool anomaly = detector_process(&detector, &stream[i]);
        printf("Sample %u: anomaly=%s\n", i, anomaly ? "true" : "false");
    }

    return 0;
}
#endif
```

### Notes for embedded deployment
- If your MCU lacks an FPU, consider using fixed-point arithmetic.
- `sqrtf()` can be expensive; you can compare squared z-scores instead if needed.
- The current implementation recomputes statistics over the whole window for simplicity. For higher performance, use a true O(1) rolling mean/variance update.
- If you want to detect motion anomalies rather than absolute magnitude anomalies, you can subtract gravity first or use high-pass filtering.

### Common improvements
- Add a high-pass filter to remove gravity drift.
- Use axis-wise anomaly scoring instead of magnitude only.
- Add a refractory period to avoid repeated triggers.
- Combine with an IMU state machine for “idle / moving / impact” classification.

