- computes a rolling magnitude-based feature
- maintains running mean/variance with Welford’s algorithm
- flags anomalies when the current feature deviates too far from the learned baseline

This is designed to be lightweight and suitable for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define WARMUP_SAMPLES      128
#define ANOMALY_Z_THRESHOLD 3.5f
#define HPF_ALPHA           0.95f   // closer to 1.0 => slower DC removal

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    // High-pass filter state
    float prev_input_x, prev_input_y, prev_input_z;
    float prev_output_x, prev_output_y, prev_output_z;

    // Rolling window for magnitude feature
    float mag_window[WINDOW_SIZE];
    uint16_t win_idx;
    uint16_t win_count;
    float win_sum;

    // Baseline statistics (Welford)
    uint32_t n;
    float mean;
    float m2;

    // Warmup / training
    uint32_t sample_count;
    bool baseline_ready;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* =========================
 * High-pass filter
 * Simple first-order HPF:
 * y[n] = alpha * (y[n-1] + x[n] - x[n-1])
 * Applied per axis.
 * ========================= */
static accel_sample_t hpf_update(anomaly_detector_t *d, const accel_sample_t *in) {
    accel_sample_t out;

    out.x = HPF_ALPHA * (d->prev_output_x + in->x - d->prev_input_x);
    out.y = HPF_ALPHA * (d->prev_output_y + in->y - d->prev_input_y);
    out.z = HPF_ALPHA * (d->prev_output_z + in->z - d->prev_input_z);

    d->prev_input_x = in->x;
    d->prev_input_y = in->y;
    d->prev_input_z = in->z;

    d->prev_output_x = out.x;
    d->prev_output_y = out.y;
    d->prev_output_z = out.z;

    return out;
}

/* =========================
 * Rolling window update
 * Maintains sum for O(1) mean calculation.
 * ========================= */
static float rolling_window_update(anomaly_detector_t *d, float value) {
    if (d->win_count < WINDOW_SIZE) {
        d->mag_window[d->win_idx] = value;
        d->win_sum += value;
        d->win_count++;
        d->win_idx = (d->win_idx + 1) % WINDOW_SIZE;
    } else {
        float old = d->mag_window[d->win_idx];
        d->win_window[d->win_idx] = value; // NOTE: see corrected line below
    }

    return d->win_sum / (float)d->win_count;
}
