```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define WARMUP_SAMPLES      128
#define ANOMALY_Z_THRESHOLD 3.5f
#define HPF_ALPHA           0.95f

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float prev_input_x, prev_input_y, prev_input_z;
    float prev_output_x, prev_output_y, prev_output_z;

    float mag_window[WINDOW_SIZE];
    uint16_t win_idx;
    uint16_t win_count;
    float win_sum;

    uint32_t n;
    float mean;
    float m2;

    uint32_t sample_count;
    bool baseline_ready;
} anomaly_detector_t;

static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static accel_sample_t hpf_update(anomaly_detector_t *d, const accel_sample_t *in) {
    accel_sample_t out;

    out.x = HPF_ALPHA * (d->prev_output_x + in->x - d->prev_input_x);
    out.y = HPF_ALPHA * (d->prev_output_y + in->y - d->prev_input_y);
    out.z = HPF_ALPHA * (d->prev_output_z + in->z - d->prev_input_z);

    d->prev_input_x = in->x;
    d->prev_input_y = in->y;
    d->prev_input_z = in->z;

    d->prev_output_x = out.x;
    d->prev_output_y = out.y;
    d->prev_output_z = out.z;

    return out;
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static float rolling_window_update(anomaly_detector_t *d, float value) {
    if (d->win_count < WINDOW_SIZE) {
        d->mag_window[d->win_idx] = value;
        d->win_sum += value;
        d->win_count++;
        d->win_idx = (d->win_idx + 1) % WINDOW_SIZE;
    } else {
        float old = d->mag_window[d->win_idx];
        d->win_sum -= old;
        d->mag_window[d->win_idx] = value;
        d->win_sum += value;
        d->win_idx = (d->win_idx + 1) % WINDOW_SIZE;
    }

    return d->win_sum / (float)d->win_count;
}

static void welford_update(anomaly_detector_t *d, float x) {
    d->n++;
    float delta = x - d->mean;
    d->mean += delta / (float)d->n;
    float delta2 = x - d->mean;
    d->m2 += delta * delta2;
}

static float welford_stddev(const anomaly_detector_t *d) {
    if (d->n < 2) return 0.0f;
    return fast_sqrtf(d->m2 / (float)(d->n - 1));
}

void anomaly_detector_init(anomaly_detector_t *d) {
    d->prev_input_x = d->prev_input_y = d->prev_input_z = 0.0f;
    d->prev_output_x = d->prev_output_y = d->prev_output_z = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
    d->win_idx = 0;
    d->win_count = 0;
    d->win_sum = 0.0f;

    d->n = 0;
    d->mean = 0.0f;
    d->m2 = 0.0f;

    d->sample_count = 0;
    d->baseline_ready = false;
}

/*
 * Process one accelerometer sample.
 * Returns true if anomaly detected.
 *
 * During warmup, the detector learns baseline statistics and does not flag anomalies.
 */
bool anomaly_detector_process(anomaly_detector_t *d, const accel_sample_t *raw) {
    d->sample_count++;

    // 1) Filter
    accel_sample_t filtered = hpf_update(d, raw);

    // 2) Feature extraction: magnitude of filtered signal
    float mag = accel_magnitude(&filtered);

    // 3) Rolling smoothing
    float feature = rolling_window_update(d, mag);

    // 4) Warmup / baseline learning
    if (!d->baseline_ready) {
        welford_update(d, feature);
        if (d->sample_count >= WARMUP_SAMPLES) {
            d->baseline_ready = true;
        }
        return false;
    }

    // 5) Compute anomaly score
    float stddev = welford_stddev(d);
    if (stddev < 1e-6f) {
        stddev = 1e-6f;
    }

    float z = (feature - d->mean) / stddev;
    bool anomaly = (fabsf(z) > ANOMALY_Z_THRESHOLD);

    // 6) Optionally adapt baseline slowly when not anomalous
    if (!anomaly) {
        // Small learning rate to follow slow drift
        const float lr = 0.01f;
        d->mean = (1.0f - lr) * d->mean + lr * feature;
        // Approximate variance adaptation
        float err = feature - d->mean;
        d->m2 = (1.0f - lr) * d->m2 + lr * (err * err);
        if (d->m2 < 0.0f) d->m2 = 0.0f;
        d->n++;
    }

    return anomaly;
}
