Below is a compact embedded-friendly C example for an accelerometer anomaly-detection pipeline. It uses:

- a sliding window
- simple feature extraction: mean, RMS, variance, peak-to-peak
- a lightweight z-score based anomaly score
- optional exponential smoothing for stability

It is designed to be easy to port to bare-metal or RTOS environments.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE      32
#define AXES             3
#define ANOMALY_THRESH   3.5f   // tune for your sensor/noise
#define EPS              1e-6f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
} ring_buffer_t;

typedef struct {
    float mean;
    float rms;
    float variance;
    float peak_to_peak;
} features_t;

typedef struct {
    ring_buffer_t rb;
    float baseline_mean;
    float baseline_std;
    float ema_score;
    bool initialized;
} anomaly_detector_t;

static float fmax3(float a, float b, float c) {
    float m = (a > b) ? a : b;
    return (m > c) ? m : c;
}

static float fmin3(float a, float b, float c) {
    float m = (a < b) ? a : b;
    return (m < c) ? m : c;
}

static void ring_init(ring_buffer_t *rb) {
    rb->index = 0;
    rb->count = 0;
}

static void ring_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->index] = s;
    rb->index = (rb->index + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static bool ring_full(const ring_buffer_t *rb) {
    return rb->count == WINDOW_SIZE;
}

static features_t extract_features(const ring_buffer_t *rb) {
    features_t f = {0};

    if (rb->count == 0) return f;

    float sum_mag = 0.0f;
    float sum_sq_mag = 0.0f;
    float min_mag = 1e30f;
    float max_mag = -1e30f;

    for (uint16_t i = 0; i < rb->count; i++) {
        accel_sample_t s = rb->buf[i];
        float mag = sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);

        sum_mag += mag;
        sum_sq_mag += mag * mag;

        if (mag < min_mag) min_mag = mag;
        if (mag > max_mag) max_mag = mag;
    }

    f.mean = sum_mag / (float)rb->count;
    f.rms = sqrtf(sum_sq_mag / (float)rb->count);
    f.variance = (sum_sq_mag / (float)rb->count) - (f.mean * f.mean);
    if (f.variance < 0.0f) f.variance = 0.0f;
    f.peak_to_peak = max_mag - min_mag;

    return f;
}

static float compute_score(const features_t *f, float baseline_mean, float baseline_std) {
    // Normalize deviation of RMS from baseline
    float z = fabsf(f->rms - baseline_mean) / (baseline_std + EPS);

    // Add some sensitivity to variance and peak-to-peak
    float score = z
                + 0.5f * f->variance
                + 0.25f * f->peak_to_peak;

    return score;
}

void anomaly_detector_init(anomaly_detector_t *det) {
    ring_init(&det->rb);
    det->baseline_mean = 0.0f;
    det->baseline_std = 1.0f;
    det->ema_score = 0.0f;
    det->initialized = false;
}

// Call this with a known "normal" calibration segment first
void anomaly_detector_calibrate(anomaly_detector_t *det) {
    if (!ring_full(&det->rb)) return;

    features_t f = extract_features(&det->rb);

    det->baseline_mean = f.rms;
    det->baseline_std = sqrtf(f.variance + EPS);
    if (det->baseline_std < 0.05f) det->baseline_std = 0.05f;

    det->initialized = true;
}

// Feed one sample at a time; returns true if anomaly detected
bool anomaly_detector_update(anomaly_detector_t *det, accel_sample_t sample) {
    ring_push(&det->rb, sample);

    if (!det->initialized) {
        // Wait until we have enough data to calibrate
        if (ring_full(&det->rb)) {
            anomaly_detector_calibrate(det);
        }
        return false;
    }

    if (!ring_full(&det->rb)) {
        return false;
    }

    features_t f = extract_features(&det->rb);
    float score = compute_score(&f, det->baseline_mean, det->baseline_std);

    // Exponential smoothing to reduce false positives
    det->ema_score = 0.8f * det->ema_score + 0.2f * score;

    return (det->ema_score > ANOMALY_THRESH);
}
