/*
 * Embedded accelerometer anomaly detector
 * - Fixed-point friendly, low memory
 * - Computes magnitude, high-pass filters baseline, tracks energy/variance
 * - Flags anomaly when short-term motion departs from baseline
 *
 * Assumptions:
 * - Called at a fixed sample rate
 * - Input accelerometer units are in mg or raw counts already scaled
 * - Suitable for Cortex-M / bare-metal style integration
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define WINDOW_SIZE         32      // short-term window
#define BASELINE_ALPHA      0.01f    // baseline adaptation rate
#define HPF_ALPHA           0.95f    // high-pass filter coefficient
#define ENERGY_THRESHOLD    4.0f     // tune per device/use case
#define ZSCORE_THRESHOLD    3.0f     // tune per device/use case
#define MIN_SAMPLES         64       // allow startup settling

/* ---------------- Data Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mean;
    float var;
    uint16_t count;
} running_stats_t;

typedef struct {
    // Baseline magnitude estimate
    float baseline_mag;

    // High-pass filter state
    float prev_mag;
    float prev_hpf;

    // Short-term statistics
    float window[WINDOW_SIZE];
    uint8_t idx;
    uint8_t filled;

    // Running stats of HPF output
    running_stats_t stats;

    // Sample counter
    uint32_t sample_count;
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float vector_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* Welford update for mean/variance */
static void running_stats_update(running_stats_t *st, float x) {
    st->count++;
    float delta = x - st->mean;
    st->mean += delta / (float)st->count;
    float delta2 = x - st->mean;
    st->var += delta * delta2;
}

static float running_stats_variance(const running_stats_t *st) {
    return (st->count > 1) ? (st->var / (float)(st->count - 1)) : 0.0f;
}

/* ---------------- API ---------------- */

void anomaly_detector_init(anomaly_detector_t *det) {
    det->baseline_mag = 0.0f;
    det->prev_mag = 0.0f;
    det->prev_hpf = 0.0f;
    det->idx = 0;
    det->filled = 0;
    det->stats.mean = 0.0f;
    det->stats.var = 0.0f;
    det->stats.count = 0;
    det->sample_count = 0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->window[i] = 0.0f;
    }
}

/*
 * Process one accelerometer sample.
 * Returns true if anomaly detected.
 */
bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *s) {
    det->sample_count++;

    // 1) Magnitude
    float mag = vector_magnitude(s);

    // 2) Baseline tracking (slow moving average)
    if (det->sample_count == 1) {
        det->baseline_mag = mag;
    } else {
        det->baseline_mag = (1.0f - BASELINE_ALPHA) * det->baseline_mag +
                            BASELINE_ALPHA * mag;
    }

    // 3) High-pass filter to remove gravity / slow drift
    float hpf = HPF_ALPHA * (det->prev_hpf + mag - det->prev_mag);
    det->prev_mag = mag;
    det->prev_hpf = hpf;

    // 4) Update short-term window
    det->window[det->idx] = hpf;
    det->idx = (det->idx + 1) % WINDOW_SIZE;
    if (det->filled < WINDOW_SIZE) det->filled++;

    // 5) Update running stats on HPF output
    running_stats_update(&det->stats, hpf);

    // 6) Compute short-term energy
    float energy = 0.0f;
    for (uint8_t i = 0; i < det->filled; i++) {
        energy += det->window[i] * det->window[i];
    }
    energy /= (float)det->filled;

    // 7) Compute z-score relative to running stats
    float variance = running_stats_variance(&det->stats);
    float stddev = fast_sqrtf(variance);
    float zscore = 0.0f;
    if (stddev > 1e-6f) {
        zscore = fabsf(hpf - det->stats.mean) / stddev;
    }

    // 8) Anomaly decision
    bool settled = (det->sample_count >= MIN_SAMPLES);
    bool energy_anomaly = (energy > ENERGY_THRESHOLD);
    bool zscore_anomaly = (zscore > ZSCORE_THRESHOLD);

    return settled && (energy_anomaly || zscore_anomaly);
}

