Below is a compact embedded-style C implementation for an accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples,
- applies a simple low-pass filter,
- computes magnitude,
- maintains a rolling baseline,
- flags anomalies when the current signal deviates too far from baseline.

It is designed to be lightweight and suitable for MCU firmware.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ===================== Configuration ===================== */

#define WINDOW_SIZE         32      // Rolling baseline window
#define LPF_ALPHA           0.2f     // Low-pass filter coefficient
#define ANOMALY_Z_THRESHOLD 3.0f     // Threshold in standard deviations
#define MIN_VARIANCE        1e-6f    // Prevent divide-by-zero
#define ANOMALY_COUNT_LIMIT  3       // Require N consecutive anomalies

/* ===================== Data Types ===================== */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float lpf_x;
    float lpf_y;
    float lpf_z;

    float magnitude_history[WINDOW_SIZE];
    uint8_t hist_idx;
    uint8_t hist_count;

    uint8_t anomaly_streak;
    bool initialized;
} anomaly_detector_t;

/* ===================== Utility ===================== */

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static float mean_of_window(const float *buf, uint8_t n)
{
    float sum = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        sum += buf[i];
    }
    return (n > 0) ? (sum / (float)n) : 0.0f;
}

static float variance_of_window(const float *buf, uint8_t n, float mean)
{
    float sum = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        float d = buf[i] - mean;
        sum += d * d;
    }
    return (n > 1) ? (sum / (float)(n - 1)) : 0.0f;
}

/* ===================== API ===================== */

void anomaly_detector_init(anomaly_detector_t *det)
{
    det->lpf_x = 0.0f;
    det->lpf_y = 0.0f;
    det->lpf_z = 0.0f;
    det->hist_idx = 0;
    det->hist_count = 0;
    det->anomaly_streak = 0;
    det->initialized = false;

    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        det->magnitude_history[i] = 0.0f;
    }
}

/*
 * Process one accelerometer sample.
 * Returns true if anomaly is detected.
 */
bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *raw)
{
    /* Initialize LPF on first sample */
    if (!det->initialized) {
        det->lpf_x = raw->x;
        det->lpf_y = raw->y;
        det->lpf_z = raw->z;
        det->initialized = true;
    } else {
        det->lpf_x = LPF_ALPHA * raw->x + (1.0f - LPF_ALPHA) * det->lpf_x;
        det->lpf_y = LPF_ALPHA * raw->y + (1.0f - LPF_ALPHA) * det->lpf_y;
        det->lpf_z = LPF_ALPHA * raw->z + (1.0f - LPF_ALPHA) * det->lpf_z;
    }

    accel_sample_t filtered = {
        .x = det->lpf_x,
        .y = det->lpf_y,
        .z = det->lpf_z
    };

    float mag = accel_magnitude(&filtered);

    /* Update rolling history */
    det->magnitude_history[det->hist_idx] = mag;
    det->hist_idx = (det->hist_idx + 1) % WINDOW_SIZE;
    if (det->hist_count < WINDOW_SIZE) {
        det->hist_count++;
    }

    /* Need enough history before detecting anomalies */
    if (det->hist_count < WINDOW_SIZE) {
        return false;
    }

    float mean = mean_of_window(det->magnitude_history, WINDOW_SIZE);
    float var  = variance_of_window(det->magnitude_history, WINDOW_SIZE, mean);
    if (var < MIN_VARIANCE) {
        var = MIN_VARIANCE;
    }

    float stddev = sqrtf(var);
    float z = fabsf(mag - mean) / stddev;

    bool is_anomaly = (z > ANOMALY_Z_THRESHOLD);

    /* Require consecutive anomalies to reduce false positives */
    if (is_anomaly) {
        if (det->anomaly_streak < 255) {
            det->anomaly_streak++;
        }
    } else {
        det->anomaly_streak = 0;
    }

    return (det->anomaly_streak >= ANOMALY_COUNT_LIMIT);
}
