Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples,
- computes a smoothed magnitude,
- maintains a running baseline and variance,
- flags anomalies when the signal deviates too far from normal,
- is designed to avoid dynamic allocation and heavy math.

You can adapt it to an MCU ISR or a periodic task.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 *
 * Assumptions:
 * - Input samples are in raw units or mg; the algorithm works either way
 *   as long as thresholds are tuned accordingly.
 * - Called at a fixed sample rate.
 * - No dynamic memory.
 */

typedef struct {
    // EMA smoothing for magnitude
    float mag_ema;
    float ema_alpha;     // 0..1, higher = less smoothing

    // Baseline and variance tracking
    float mean;
    float var;
    float mean_alpha;    // baseline update rate
    float var_alpha;     // variance update rate

    // Detection thresholds
    float z_thresh;      // e.g. 3.0f
    float min_var;       // floor to avoid divide-by-zero

    // Optional high-pass style drift rejection
    float gravity_est;   // if you want to track slow gravity changes
    float gravity_alpha; // e.g. 0.01f

    // State
    bool initialized;
    uint32_t sample_count;
    uint32_t anomaly_count;
} AnomalyDetector;

static inline float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static inline float fast_sqrtf(float x) {
    // Use sqrtf if available; replace with a platform-specific fast sqrt if needed.
    return sqrtf(x);
}

void anomaly_detector_init(AnomalyDetector *d) {
    d->mag_ema = 0.0f;
    d->ema_alpha = 0.2f;

    d->mean = 0.0f;
    d->var = 1.0f;
    d->mean_alpha = 0.01f;
    d->var_alpha = 0.01f;

    d->z_thresh = 3.0f;
    d->min_var = 1e-6f;

    d->gravity_est = 0.0f;
    d->gravity_alpha = 0.01f;

    d->initialized = false;
    d->sample_count = 0;
    d->anomaly_count = 0;
}

/*
 * Process one accelerometer sample.
 * ax, ay, az: accelerometer axes
 * returns true if anomaly detected
 */
bool anomaly_detector_process(AnomalyDetector *d, float ax, float ay, float az) {
    // Compute magnitude
    float mag = fast_sqrtf(ax * ax + ay * ay + az * az);

    // Optional slow gravity/drift estimate
    if (!d->initialized) {
        d->gravity_est = mag;
        d->mag_ema = mag;
        d->mean = mag;
        d->var = 1.0f;
        d->initialized = true;
        d->sample_count = 1;
        return false;
    }

    d->gravity_est += d->gravity_alpha * (mag - d->gravity_est);

    // Remove slow drift if desired
    float detrended = mag - d->gravity_est;

    // Smooth the detrended magnitude
    d->mag_ema += d->ema_alpha * (detrended - d->mag_ema);

    // Update running mean/variance using EMA
    float err = d->mag_ema - d->mean;
    d->mean += d->mean_alpha * err;

    // Exponentially weighted variance update
    float dev = d->mag_ema - d->mean;
    d->var += d->var_alpha * ((dev * dev) - d->var);
    if (d->var < d->min_var) {
        d->var = d->min_var;
    }

    // Z-score based anomaly detection
    float stddev = fast_sqrtf(d->var);
    float z = fast_absf(d->mag_ema - d->mean) / stddev;

    d->sample_count++;

    if (z > d->z_thresh) {
        d->anomaly_count++;
        return true;
    }

    return false;
}
