Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline. It includes:

- sample ingestion
- simple filtering
- windowed feature extraction
- baseline adaptation
- anomaly scoring
- event reporting

It is designed to be easy to port to a microcontroller.

```c
/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 *  - 3-axis accelerometer input
 *  - High-pass-ish detrending using exponential moving average
 *  - Magnitude-based window features
 *  - Adaptive baseline and threshold
 *  - Anomaly flagging
 *
 * Assumptions:
 *  - Called once per sample at fixed sample rate
 *  - Accelerometer values are in g or m/s^2 consistently
 *  - Suitable for small MCUs: no dynamic allocation
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.01f
#endif

#ifndef FILTER_ALPHA
#define FILTER_ALPHA 0.05f
#endif

#ifndef THRESHOLD_MULTIPLIER
#define THRESHOLD_MULTIPLIER 3.0f
#endif

#ifndef MIN_ANOMALY_SCORE
#define MIN_ANOMALY_SCORE 1.5f
#endif

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mag_mean;
    float mag_var;
    float mag_peak;
    float energy;
} feature_vector_t;

typedef struct {
    float ema_x;
    float ema_y;
    float ema_z;

    float window_mag[WINDOW_SIZE];
    uint16_t window_index;
    uint16_t window_count;

    float baseline_mean;
    float baseline_var;

    uint32_t sample_count;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    det->ema_x = 0.0f;
    det->ema_y = 0.0f;
    det->ema_z = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        det->window_mag[i] = 0.0f;
    }

    det->window_index = 0;
    det->window_count = 0;

    det->baseline_mean = 0.0f;
    det->baseline_var = 1.0f;

    det->sample_count = 0;
}

static float compute_magnitude(float x, float y, float z) {
    return fast_sqrtf(x * x + y * y + z * z);
}

static feature_vector_t extract_features(anomaly_detector_t *det) {
    feature_vector_t f = {0};

    if (det->window_count == 0) {
        return f;
    }

    float sum = 0.0f;
    float sumsq = 0.0f;
    float peak = 0.0f;

    for (uint16_t i = 0; i < det->window_count; i++) {
        float v = det->window_mag[i];
        sum += v;
        sumsq += v * v;
        if (v > peak) peak = v;
    }

    f.mag_mean = sum / (float)det->window_count;
    f.mag_var = (sumsq / (float)det->window_count) - (f.mag_mean * f.mag_mean);
    if (f.mag_var < 0.0f) f.mag_var = 0.0f;
    f.mag_peak = peak;
    f.energy = sumsq;

    return f;
}

/*
 * Update detector with one accelerometer sample.
 * Returns true if anomaly detected.
 */
bool anomaly_detector_update(anomaly_detector_t *det, accel_sample_t sample, float *out_score) {
    det->sample_count++;

    /*
     * Low-pass estimate of slow motion / bias.
     * Detrended signal = raw - EMA
     */
    det->ema_x = (1.0f - FILTER_ALPHA) * det->ema_x + FILTER_ALPHA * sample.x;
    det->ema_y = (1.0f - FILTER_ALPHA) * det->ema_y + FILTER_ALPHA * sample.y;
    det->ema_z = (1.0f - FILTER_ALPHA) * det->ema_z + FILTER_ALPHA * sample.z;

    float dx = sample.x - det->ema_x;
    float dy = sample.y - det->ema_y;
    float dz = sample.z - det->ema_z;

    float mag = compute_magnitude(dx, dy, dz);

    det->window_mag[det->window_index] = mag;
    det->window_index = (det->window_index + 1) % WINDOW_SIZE;
    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    if (det->window_count < WINDOW_SIZE) {
        if (out_score) *out_score = 0.0f;
        return false; // need full window before scoring
    }

    feature_vector_t feat = extract_features(det);

    /*
     * Simple anomaly score:
     *  - deviation from baseline mean
     *  - boosted by high variance / peak / energy
     */
    float mean_dev = fabsf(feat.mag_mean - det->baseline_mean);
    float var_dev  = fabsf(feat.mag_var - det->baseline_var);

    float score = mean_dev + 0.5f * var_dev + 0.1f * feat.mag_peak + 0.01f * feat.energy;

    if (out_score) *out_score = score;

    float threshold = det->baseline_mean + THRESHOLD_MULTIPLIER * fast_sqrtf(det->baseline_var + 1e-6f);

    bool anomaly = (score > threshold) && (score > MIN_ANOMALY_SCORE);

    /*
     * Adapt baseline only when not anomalous.
     * This prevents the model from learning the anomaly itself.
     */
    if (!anomaly) {
        det->baseline_mean = (1.0f - BASELINE_ALPHA) * det->baseline_mean + BASELINE_ALPHA * feat.mag_mean;

        float diff = feat.mag_mean - det->baseline_mean;
        det->baseline_var = (1.0f - BASELINE_ALPHA) * det->baseline_var + BASELINE_ALPHA * (diff * diff);

        if (det->baseline_var < 1e-6f) {
            det->baseline_var = 1e-6f;
        }
    }

    return anomaly;
}
