```c
/*
 * Embedded accelerometer anomaly detection pipeline
 * - Fixed-size ring buffer
 * - Simple preprocessing: DC removal via running mean
 * - Feature extraction: RMS, peak-to-peak, variance, jerk
 * - Lightweight anomaly score with thresholding
 *
 * Intended for Cortex-M / bare-metal style systems.
 * Replace the "read_accel_sample()" stub with your sensor driver.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define AXES                    3
#define WINDOW_SIZE             64      // must be power of 2 for fast modulo if desired
#define SAMPLE_RATE_HZ          100
#define ANOMALY_THRESHOLD       3.5f
#define WARMUP_WINDOWS          4

/* Feature weights for a simple score */
#define W_RMS                   1.0f
#define W_P2P                   0.8f
#define W_VAR                   0.6f
#define W_JERK                  0.9f

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float rms;
    float p2p;
    float variance;
    float jerk;
} features_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} ring_buffer_t;

typedef struct {
    float mean[AXES];
    float m2[AXES];
    uint32_t n;
} running_stats_t;

/* =========================
 * Utility
 * ========================= */
static inline float f_absf(float x) { return (x < 0.0f) ? -x : x; }
static inline float f_maxf(float a, float b) { return (a > b) ? a : b; }
static inline float f_minf(float a, float b) { return (a < b) ? a : b; }

/* =========================
 * Ring buffer
 * ========================= */
static void rb_init(ring_buffer_t *rb) {
    rb->head = 0;
    rb->count = 0;
}

static void rb_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static accel_sample_t rb_get(const ring_buffer_t *rb, uint16_t idx_from_oldest) {
    uint16_t start = (rb->head + WINDOW_SIZE - rb->count) % WINDOW_SIZE;
    uint16_t idx = (start + idx_from_oldest) % WINDOW_SIZE;
    return rb->buf[idx];
}

/* =========================
 * Running stats (Welford)
 * ========================= */
static void stats_init(running_stats_t *s) {
    s->mean[0] = s->mean[1] = s->mean[2] = 0.0f;
    s->m2[0] = s->m2[1] = s->m2[2] = 0.0f;
    s->n = 0;
}

static void stats_update(running_stats_t *s, accel_sample_t x) {
    float v[AXES] = { x.x, x.y, x.z };
    s->n++;
    for (int i = 0; i < AXES; i++) {
        float delta = v[i] - s->mean[i];
        s->mean[i] += delta / (float)s->n;
        float delta2 = v[i] - s->mean[i];
        s->m2[i] += delta * delta2;
    }
}

static accel_sample_t stats_mean(const running_stats_t *s) {
    accel_sample_t m = { s->mean[0], s->mean[1], s->mean[2] };
    return m;
}

/* =========================
 * Preprocessing
 * ========================= */
static accel_sample_t remove_dc(accel_sample_t s, accel_sample_t mean) {
    accel_sample_t o = { s.x - mean.x, s.y - mean.y, s.z - mean.z };
    return o;
}

/* Magnitude */
static float accel_mag(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* =========================
 * Feature extraction
 * ========================= */
static features_t extract_features(const ring_buffer_t *rb, accel_sample_t dc_mean) {
    features_t f = {0};

    if (rb->count == 0) return f;

    float sum_sq = 0.0f;
    float min_m = 1e9f;
    float max_m = -1e9f;
    float sum_m = 0.0f;
    float sum_m2 = 0.0f;

    // Jerk: average absolute difference in magnitude between consecutive samples
    float jerk_sum = 0.0f;
    uint16_t jerk_n = 0;

    float prev_mag = 0.0f;
    bool has_prev = false;

    for (uint16_t i = 0; i < rb->count; i++) {
        accel_sample_t s = remove_dc(rb_get(rb, i), dc_mean);
        float m = accel_mag(s);

        sum_sq += m * m;
        sum_m += m;
        sum_m2 += m * m;

        min_m = f_minf(min_m, m);
        max_m = f_maxf(max_m, m);

        if (has_prev) {
            jerk_sum += f_absf(m - prev_mag);
            jerk_n++;
        } else {
            has_prev = true;
        }
        prev_mag = m;
    }

    float n = (float)rb->count;
    f.rms = sqrtf(sum_sq / n);
    f.p2p = max_m - min_m;
    f.variance = (sum_m2 / n) - ((sum_m / n) * (sum_m / n));
    f.jerk = (jerk_n > 0) ? (jerk_sum / (float)jerk_n) : 0.0f;

    return f;
}

/* =========================
 * Anomaly scoring
 * =========================
 * For embedded use, we compare features against a baseline learned during normal operation.
 * Score is a normalized deviation from baseline.
 */
typedef struct {
    features_t mean;
    features_t stddev;
    bool ready;
} baseline_t;

static void baseline_init(baseline_t *b) {
    b->mean.rms = b->mean.p2p = b->mean.variance = b->mean.jerk = 0.0f;
    b->stddev.rms = b->stddev.p2p = b->stddev.variance = b->stddev.jerk = 1.0f;
    b->ready = false;
}

static float norm_dev(float x, float mean, float stddev) {
    float d = f_absf(x - mean) / (stddev + 1e-6f);
    return d;
}

static float anomaly_score(features_t f, const baseline_t *b) {
    float s = 0.0f;
    s += W_RMS  * norm_dev(f.rms,      b->mean.rms,      b->stddev.rms);
    s += W_P2P  * norm_dev(f.p2p,      b->mean.p2p,      b->stddev.p2p);
    s += W_VAR  * norm_dev(f.variance, b->mean.variance, b->stddev.variance);
    s += W_JERK * norm_dev(f.jerk,     b->mean.jerk,     b->stddev.jerk);
    return s;
}

/* =========================
 * Baseline learning
 * ========================= */
#define BASELINE_SAMPLES  8

typedef struct {
    features_t samples[BASELINE_SAMPLES];
    uint8_t count;
} baseline_learner_t;

static void learner_init(baseline_learner_t *l) {
    l->count = 0;
}

static void learner_add(baseline_learner_t *l, features_t f) {
    if (l->count < BASELINE_SAMPLES) {
        l->samples[l->count++] = f;
    }
}

static void learner_finalize(const baseline_learner_t *l, baseline_t *b) {
    if (l->count == 0) return;

    float sum_rms = 0, sum_p2p = 0, sum_var = 0, sum_jerk = 0;
    for (uint8_t i = 0; i < l->count; i++) {
        sum_rms  += l->samples[i].rms;
        sum_p2p  += l->samples[i].p2p;
        sum_var  += l->samples[i].variance;
        sum_jerk += l->samples[i].jerk;
    }

    float n = (float)l->count;
    b->mean.rms      = sum_rms / n;
    b->mean.p2p      = sum_p2p / n;
    b->mean.variance = sum_var / n;
    b->mean.jerk     = sum_jerk / n;

    float var_rms = 0, var_p2p = 0, var_var = 0, var_jerk = 0;
    for (uint8_t i = 0; i < l->count; i++) {
        var_rms  += (l->samples[i].rms      - b->mean.rms)      * (l->samples[i].rms      - b->mean.rms);
        var_p2p  += (l->samples[i].p2p      - b->mean.p2p)      * (l->samples[i].p2p      - b->mean.p2p);
        var_var  += (l->samples[i].variance - b->mean.variance) * (l->samples[i].variance - b->mean.variance);
        var_jerk += (l->samples[i].jerk     - b->mean.jerk)     * (l->samples[i].jerk     - b->mean.jerk);
    }

    b->stddev.rms      = sqrtf(var_rms / n) + 1e-3f;
    b->stddev.p2p      = sqrtf(var_p2p / n) + 1e-3f;
    b->stddev.variance = sqrtf(var_var / n) + 1e-3f;
    b->stddev.jerk     = sqrtf(var_jerk / n) + 1e-3f;
    b->ready = true;
}

/* =========================
 * Sensor I/O stub
 * ========================= */
static bool read_accel_sample(accel_sample_t *out) {
    // TODO: Replace with actual sensor read.
    // Return true when a new sample is available.
