/* =========================
 * Application pipeline
 * ========================= */
typedef struct {
    ring_buffer_t rb;
    running_stats_t dc_stats;
    baseline_t baseline;
    baseline_learner_t learner;
    uint32_t window_counter;
    uint32_t anomaly_count;
} pipeline_t;

static void pipeline_init(pipeline_t *p) {
    rb_init(&p->rb);
    stats_init(&p->dc_stats);
    baseline_init(&p->baseline);
    learner_init(&p->learner);
    p->window_counter = 0;
    p->anomaly_count = 0;
}

static void pipeline_process_sample(pipeline_t *p, accel_sample_t s) {
    // Update running DC estimate
    stats_update(&p->dc_stats, s);

    // Store raw sample
    rb_push(&p->rb, s);

    // Process when window is full
    if (p->rb.count == WINDOW_SIZE) {
        p->window_counter++;

        accel_sample_t mean = stats_mean(&p->dc_stats);
        features_t f = extract_features(&p->rb, mean);

        if (!p->baseline.ready) {
            learner_add(&p->learner, f);
            if (p->learner.count >= BASELINE_SAMPLES) {
                learner_finalize(&p->learner, &p->baseline);
            }
            return;
        }

        float score = anomaly_score(f, &p->baseline);
        bool anomaly = (score > ANOMALY_THRESHOLD);

        if (anomaly) {
            p->anomaly_count++;
            // TODO: trigger alert / log / transmit event
            // Example: toggle GPIO, enqueue message, etc.
        }

        // Optional: slow adaptation of baseline during confirmed normal operation
        // (not implemented here to keep behavior stable)
        (void)score;
    }
}

/* =========================
 * Main loop
 * ========================= */
