```c
/*
 * Embedded accelerometer anomaly detector
 * - Fixed-size, streaming-friendly
 * - Uses a rolling mean/std over magnitude
 * - Flags anomaly when z-score exceeds threshold for N consecutive samples
 *
 * Assumptions:
 * - 3-axis accelerometer samples arrive at a fixed rate
 * - int16_t raw units are from sensor LSBs
 * - This code is MCU-friendly and avoids dynamic allocation
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE        32
#define CONSECUTIVE_LIMIT   3
#define ZSCORE_THRESHOLD    3.5f
#define MIN_STD_EPS         1e-3f

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_sample_t;

typedef struct {
    float buf[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum;
    float sumsq;
    uint8_t consecutive;
    bool anomaly;
} anomaly_detector_t;

static float accel_magnitude(const accel_sample_t *s)
{
    /* If your platform lacks sqrtf, replace with an approximation. */
    float fx = (float)s->x;
    float fy = (float)s->y;
    float fz = (float)s->z;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

void anomaly_detector_init(anomaly_detector_t *d)
{
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        d->buf[i] = 0.0f;
    }
    d->idx = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->sumsq = 0.0f;
    d->consecutive = 0;
    d->anomaly = false;
}

static void rolling_stats_update(anomaly_detector_t *d, float sample)
{
    if (d->count < WINDOW_SIZE) {
        d->buf[d->idx] = sample;
        d->sum += sample;
        d->sumsq += sample * sample;
        d->idx = (d->idx + 1) % WINDOW_SIZE;
        d->count++;
    } else {
        float old = d->buf[d->idx];
        d->buf[d->idx] = sample;
        d->sum += sample - old;
        d->sumsq += (sample * sample) - (old * old);
        d->idx = (d->idx + 1) % WINDOW_SIZE;
    }
}

static void rolling_stats_compute(const anomaly_detector_t *d, float *mean, float *stddev)
{
    if (d->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float n = (float)d->count;
    float m = d->sum / n;
    float var = (d->sumsq / n) - (m * m);
    if (var < 0.0f) var = 0.0f;

    *mean = m;
    *stddev = sqrtf(var);
}

bool anomaly_detector_process(anomaly_detector_t *d, const accel_sample_t *sample)
{
    float mag = accel_magnitude(sample);

    /* Warm-up phase: fill window before making decisions */
    if (d->count < WINDOW_SIZE) {
        rolling_stats_update(d, mag);
        d->anomaly = false;
        d->consecutive = 0;
        return false;
    }

    /* Compute stats from current window before adding new sample */
    float mean, stddev;
    rolling_stats_compute(d, &mean, &stddev);

    float denom = (stddev < MIN_STD_EPS) ? MIN_STD_EPS : stddev;
    float z = (mag - mean) / denom;
    float az = (z < 0.0f) ? -z : z;

    bool is_outlier = (az > ZSCORE_THRESHOLD);

    if (is_outlier) {
        if (d->consecutive < 255) d->consecutive++;
    } else {
        d->consecutive = 0;
    }

    d->anomaly = (d->consecutive >= CONSECUTIVE_LIMIT);

    /* Update rolling window after decision */
    rolling_stats_update(d, mag);

    return d->anomaly;
}

