## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef ANOMALY_THRESHOLD
#define ANOMALY_THRESHOLD 3.5f
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.01f
#endif

#ifndef VAR_ALPHA
#define VAR_ALPHA 0.01f
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float mean;
    float var;
    bool initialized;
} running_stats_t;

typedef struct {
    accel_sample_t window[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    running_stats_t mag_stats;
    float baseline_mag;

    bool anomaly_detected;
    float anomaly_score;
} sensor_pipeline_t;

static float vector_magnitude(const accel_sample_t *s) {
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

static void running_stats_init(running_stats_t *stats) {
    stats->mean = 0.0f;
    stats->var = 0.0f;
    stats->initialized = false;
}

static void running_stats_update(running_stats_t *stats, float x, float alpha) {
    if (!stats->initialized) {
        stats->mean = x;
        stats->var = 0.0f;
        stats->initialized = true;
        return;
    }

    float diff = x - stats->mean;
    stats->mean += alpha * diff;
    stats->var = (1.0f - alpha) * (stats->var + alpha * diff * diff);
}

void sensor_pipeline_init(sensor_pipeline_t *p) {
    memset(p, 0, sizeof(*p));
    running_stats_init(&p->mag_stats);
    p->baseline_mag = 0.0f;
    p->anomaly_detected = false;
    p->anomaly_score = 0.0f;
}

static float compute_window_energy(const sensor_pipeline_t *p) {
    if (p->count == 0) return 0.0f;

    float sum = 0.0f;
    for (uint16_t i = 0; i < p->count; i++) {
        float mag = vector_magnitude(&p->window[i]);
        float centered = mag - p->baseline_mag;
        sum += centered * centered;
    }
    return sum / (float)p->count;
}

static float compute_peak_deviation(const sensor_pipeline_t *p) {
    float peak = 0.0f;
    for (uint16_t i = 0; i < p->count; i++) {
        float mag = vector_magnitude(&p->window[i]);
        float dev = fabsf(mag - p->baseline_mag);
        if (dev > peak) peak = dev;
    }
    return peak;
}

bool sensor_pipeline_process(sensor_pipeline_t *p, const accel_sample_t *sample) {
    // Store sample in ring buffer
    p->window[p->index] = *sample;
    p->index = (p->index + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }

    // Estimate magnitude and update baseline slowly
    float mag = vector_magnitude(sample);

    if (p->baseline_mag == 0.0f) {
        p->baseline_mag = mag;
    } else {
        p->baseline_mag += BASELINE_ALPHA * (mag - p->baseline_mag);
    }

    // Update running stats for magnitude
    running_stats_update(&p->mag_stats, mag, VAR_ALPHA);

    // Need enough samples before detection
    if (p->count < WINDOW_SIZE / 2) {
        p->anomaly_detected = false;
        p->anomaly_score = 0.0f;
        return false;
    }

    // Feature extraction
    float energy = compute_window_energy(p);
    float peak_dev = compute_peak_deviation(p);

    // Normalize by estimated variance to create a simple score
    float stddev = sqrtf(p->mag_stats.var + 1e-6f);
    float normalized_peak = peak_dev / stddev;
    float normalized_energy = energy / (p->mag_stats.var + 1e-6f);

    // Simple anomaly score
    float score = 0.6f * normalized_peak + 0.4f * normalized_energy;
    p->anomaly_score = score;

    // Decision
    p->anomaly_detected = (score > ANOMALY_THRESHOLD);
    return p->anomaly_detected;
}

bool sensor_pipeline_is_anomaly(const sensor_pipeline_t *p) {
    return p->anomaly_detected;
}

float sensor_pipeline_get_score(const sensor_pipeline_t *p) {
    return p->anomaly_score;
}
