## 2) C implementation

This is written in a style suitable for embedded C.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE         32
#define BASELINE_ALPHA      0.05f   // slow adaptation
#define ANOMALY_THRESHOLD   3.0f    // tune this
#define MIN_BASELINE_READY   8

typedef struct {
    float mean_mag;
    float var_mag;
    float peak_to_peak;
    float energy;
} FeatureSet;

typedef struct {
    float baseline_mean;
    float baseline_var;
    float baseline_energy;
    uint32_t samples_seen;
    bool initialized;
} BaselineModel;

typedef struct {
    float mag_buffer[WINDOW_SIZE];
    uint16_t write_idx;
    uint16_t count;
    BaselineModel baseline;
} SensorPipeline;

typedef struct {
    bool anomaly_detected;
    float score;
    FeatureSet features;
} AnomalyResult;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

void sensor_pipeline_init(SensorPipeline *p) {
    memset(p, 0, sizeof(*p));
    p->baseline.initialized = false;
}

static float compute_magnitude(float ax, float ay, float az) {
    return fast_sqrtf(ax * ax + ay * ay + az * az);
}

static void push_sample(SensorPipeline *p, float mag) {
    p->mag_buffer[p->write_idx] = mag;
    p->write_idx = (p->write_idx + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }
}

static bool window_full(const SensorPipeline *p) {
    return p->count == WINDOW_SIZE;
}

static void extract_features(const SensorPipeline *p, FeatureSet *out) {
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = p->mag_buffer[0];
    float max_v = p->mag_buffer[0];

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        float v = p->mag_buffer[i];
        sum += v;
        sum_sq += v * v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }

    out->mean_mag = sum / WINDOW_SIZE;
    out->var_mag = (sum_sq / WINDOW_SIZE) - (out->mean_mag * out->mean_mag);
    if (out->var_mag < 0.0f) out->var_mag = 0.0f;
    out->peak_to_peak = max_v - min_v;
    out->energy = sum_sq;
}

static float compute_anomaly_score(const SensorPipeline *p, const FeatureSet *f) {
    if (!p->baseline.initialized || p->baseline.samples_seen < MIN_BASELINE_READY) {
        return 0.0f;
    }

    float mean_diff = fabsf(f->mean_mag - p->baseline.baseline_mean);
    float var_diff = fabsf(f->var_mag - p->baseline.baseline_var);
    float energy_diff = fabsf(f->energy - p->baseline.baseline_energy);

    // Normalize with simple scaling factors; tune for your hardware/data
    float score =
        (mean_diff / (p->baseline.baseline_mean + 1e-3f)) +
        0.5f * (var_diff / (p->baseline.baseline_var + 1e-3f)) +
        0.25f * (energy_diff / (p->baseline.baseline_energy + 1e-3f));

    return score;
}

static void update_baseline(BaselineModel *b, const FeatureSet *f) {
    if (!b->initialized) {
        b->baseline_mean = f->mean_mag;
        b->baseline_var = f->var_mag;
        b->baseline_energy = f->energy;
        b->samples_seen = 1;
        b->initialized = true;
        return;
    }

    b->baseline_mean =
        (1.0f - BASELINE_ALPHA) * b->baseline_mean + BASELINE_ALPHA * f->mean_mag;
    b->baseline_var =
        (1.0f - BASELINE_ALPHA) * b->baseline_var + BASELINE_ALPHA * f->var_mag;
    b->baseline_energy =
        (1.0f - BASELINE_ALPHA) * b->baseline_energy + BASELINE_ALPHA * f->energy;

    b->samples_seen++;
}

AnomalyResult sensor_pipeline_process_sample(SensorPipeline *p,
                                             float ax, float ay, float az) {
    AnomalyResult result;
    memset(&result, 0, sizeof(result));

    float mag = compute_magnitude(ax, ay, az);
    push_sample(p, mag);

    if (!window_full(p)) {
        return result;
    }

    FeatureSet f;
    extract_features(p, &f);

    float score = compute_anomaly_score(p, &f);
    bool anomaly = (score >= ANOMALY_THRESHOLD);

    result.anomaly_detected = anomaly;
    result.score = score;
    result.features = f;

    // Only update baseline if not anomalous
    if (!anomaly) {
        update_baseline(&p->baseline, &f);
    }

    return result;
}
