## Embedded C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define ACC_WINDOW_SIZE        32
#define ACC_FILTER_ALPHA       0.2f
#define ACC_SPIKE_THRESHOLD    2.5f   // g-units, tune for your sensor
#define ACC_VAR_THRESHOLD      0.8f   // tune based on normal motion
#define ACC_JERK_THRESHOLD     1.8f   // tune based on expected dynamics

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mag;
    float filtered_mag;
    float jerk;
} AccelFeatures;

typedef struct {
    AccelSample samples[ACC_WINDOW_SIZE];
    float mags[ACC_WINDOW_SIZE];
    float filtered_mags[ACC_WINDOW_SIZE];
    float jerks[ACC_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    float prev_filtered_mag;
    bool has_prev;

    // Optional baseline statistics
    float baseline_mean;
    float baseline_var;
    bool baseline_ready;
} AccelPipeline;

typedef struct {
    bool anomaly_detected;
    float score;
    float mean_mag;
    float var_mag;
    float max_mag;
    float max_jerk;
} AnomalyResult;

static float compute_magnitude(AccelSample s) {
    return sqrtf((s.x * s.x) + (s.y * s.y) + (s.z * s.z));
}

static float compute_mean(const float *data, uint16_t n) {
    if (n == 0) return 0.0f;
    float sum = 0.0f;
    for (uint16_t i = 0; i < n; i++) {
        sum += data[i];
    }
    return sum / (float)n;
}

static float compute_variance(const float *data, uint16_t n, float mean) {
    if (n == 0) return 0.0f;
    float sum = 0.0f;
    for (uint16_t i = 0; i < n; i++) {
        float d = data[i] - mean;
        sum += d * d;
    }
    return sum / (float)n;
}

static float compute_max(const float *data, uint16_t n) {
    if (n == 0) return 0.0f;
    float m = data[0];
    for (uint16_t i = 1; i < n; i++) {
        if (data[i] > m) m = data[i];
    }
    return m;
}

void AccelPipeline_Init(AccelPipeline *p) {
    memset(p, 0, sizeof(*p));
    p->baseline_ready = false;
}

static void update_baseline(AccelPipeline *p, float mag) {
    // Simple exponential moving average baseline
    if (!p->baseline_ready) {
        p->baseline_mean = mag;
        p->baseline_var = 0.0f;
        p->baseline_ready = true;
        return;
    }

    const float beta = 0.01f; // slow baseline adaptation
    float diff = mag - p->baseline_mean;
    p->baseline_mean += beta * diff;
    p->baseline_var = (1.0f - beta) * p->baseline_var + beta * (diff * diff);
}

static float compute_jerk(float current_filtered_mag, float prev_filtered_mag) {
    return fabsf(current_filtered_mag - prev_filtered_mag);
}

static AnomalyResult evaluate_window(AccelPipeline *p) {
    AnomalyResult result;
    memset(&result, 0, sizeof(result));

    uint16_t n = p->count;
    if (n == 0) {
        return result;
    }

    float mean_mag = compute_mean(p->filtered_mags, n);
    float var_mag  = compute_variance(p->filtered_mags, n, mean_mag);
    float max_mag   = compute_max(p->mags, n);
    float max_jerk  = compute_max(p->jerks, n);

    result.mean_mag = mean_mag;
    result.var_mag = var_mag;
    result.max_mag = max_mag;
    result.max_jerk = max_jerk;

    // Simple anomaly score
    float score = 0.0f;

    if (max_mag > ACC_SPIKE_THRESHOLD) {
        score += 1.0f;
    }
    if (var_mag > ACC_VAR_THRESHOLD) {
        score += 1.0f;
    }
    if (max_jerk > ACC_JERK_THRESHOLD) {
        score += 1.0f;
    }

    // Optional baseline comparison
    if (p->baseline_ready) {
        float baseline_deviation = fabsf(mean_mag - p->baseline_mean);
        if (baseline_deviation > 0.5f) {
            score += 0.5f;
        }
    }

    result.score = score;
    result.anomaly_detected = (score >= 2.0f);

    return result;
}

// Returns true when a full window has been processed and result is valid.
bool AccelPipeline_ProcessSample(AccelPipeline *p, AccelSample sample, AnomalyResult *out_result) {
    float mag = compute_magnitude(sample);

    // Simple low-pass filter on magnitude
    float filtered_mag;
    if (!p->has_prev) {
        filtered_mag = mag;
        p->has_prev = true;
    } else {
        filtered_mag = ACC_FILTER_ALPHA * mag + (1.0f - ACC_FILTER_ALPHA) * p->prev_filtered_mag;
    }

    float jerk = 0.0f;
    if (p->count > 0) {
        jerk = compute_jerk(filtered_mag, p->prev_filtered_mag);
    }

    p->prev_filtered_mag = filtered_mag;

    // Store into ring buffer
    p->samples[p->index] = sample;
    p->mags[p->index] = mag;
    p->filtered_mags[p->index] = filtered_mag;
    p->jerks[p->index] = jerk;

    p->index = (p->index + 1) % ACC_WINDOW_SIZE;
    if (p->count < ACC_WINDOW_SIZE) {
        p->count++;
    }

    // Update baseline continuously
    update_baseline(p, mag);

    if (p->count < ACC_WINDOW_SIZE) {
        return false; // not enough data yet
    }

    AnomalyResult result = evaluate_window(p);

    if (out_result) {
        *out_result = result;
    }

    return true;
}
