### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float sp_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float sp_sqrtf_safe(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float sp_compute_mag(const sp_accel_sample_t *s) {
    return sp_sqrtf_safe(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

static void sp_compute_features(const sp_pipeline_t *p, sp_features_t *f) {
    uint8_t n = p->count;
    if (n == 0) {
        f->mean_mag = 0.0f;
        f->var_mag = 0.0f;
        f->max_mag = 0.0f;
        f->mean_jerk = 0.0f;
        return;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float max_mag = p->magnitudes[0];

    for (uint8_t i = 0; i < n; i++) {
        float m = p->magnitudes[i];
        sum += m;
        sum_sq += m * m;
        if (m > max_mag) max_mag = m;
    }

    float mean = sum / (float)n;
    float var = (sum_sq / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    float jerk_sum = 0.0f;
    if (n > 1) {
        for (uint8_t i = 1; i < n; i++) {
            jerk_sum += sp_absf(p->magnitudes[i] - p->magnitudes[i - 1]);
        }
        jerk_sum /= (float)(n - 1);
    }

    f->mean_mag = mean;
    f->var_mag = var;
    f->max_mag = max_mag;
    f->mean_jerk = jerk_sum;
}

static bool sp_detect_anomaly(const sp_pipeline_t *p, const sp_features_t *f) {
    bool hit = false;

    if (f->max_mag > p->cfg.mag_threshold) {
        hit = true;
    }
    if (f->var_mag > p->cfg.var_threshold) {
        hit = true;
    }
    if (f->mean_jerk > p->cfg.jerk_threshold) {
        hit = true;
    }

    return hit;
}

void sp_init(sp_pipeline_t *p, const sp_config_t *cfg) {
    memset(p, 0, sizeof(*p));
    p->cfg = *cfg;
}

bool sp_push_sample(sp_pipeline_t *p, const sp_accel_sample_t *s, bool *anomaly_out, sp_features_t *features_out) {
    float mag = sp_compute_mag(s);

    p->samples[p->idx] = *s;
    p->magnitudes[p->idx] = mag;

    p->idx = (uint8_t)((p->idx + 1) % SP_WINDOW_SIZE);
    if (p->count < SP_WINDOW_SIZE) {
        p->count++;
    }

    p->sample_counter++;

    bool anomaly = false;

    if (p->count == SP_WINDOW_SIZE) {
        sp_features_t f;
        sp_compute_features(p, &f);

        if (features_out) {
            *features_out = f;
        }

        if (sp_detect_anomaly(p, &f)) {
            if (p->anomaly_streak < 255) p->anomaly_streak++;
        } else {
            p->anomaly_streak = 0;
        }

        anomaly = (p->anomaly_streak >= p->cfg.consecutive_hits);
    }

    if (anomaly_out) {
        *anomaly_out = anomaly;
    }

    return (p->count == SP_WINDOW_SIZE);
}
```

