#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define ANOMALY_COUNT_LIMIT 3
#define MAG_THRESHOLD       1.8f   // g units, tune for your application
#define VAR_THRESHOLD       0.25f  // tune as needed

typedef struct {
    float x_buf[WINDOW_SIZE];
    float y_buf[WINDOW_SIZE];
    float z_buf[WINDOW_SIZE];
    float mag_buf[WINDOW_SIZE];

    uint16_t idx;
    uint16_t count;

    float sum_x;
    float sum_y;
    float sum_z;
    float sum_mag;

    float sumsq_mag;

    uint8_t anomaly_streak;
    bool anomaly_detected;
} SensorPipeline;

typedef struct {
    float ax;
    float ay;
    float az;
    float mag;
    float mag_mean;
    float mag_var;
    bool anomaly;
} PipelineResult;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->x_buf[i] = 0.0f;
        p->y_buf[i] = 0.0f;
        p->z_buf[i] = 0.0f;
        p->mag_buf[i] = 0.0f;
    }

    p->idx = 0;
    p->count = 0;
    p->sum_x = 0.0f;
    p->sum_y = 0.0f;
    p->sum_z = 0.0f;
    p->sum_mag = 0.0f;
    p->sumsq_mag = 0.0f;
    p->anomaly_streak = 0;
    p->anomaly_detected = false;
}

static void update_ring(float *buf, float *sum, float new_val, uint16_t idx, uint16_t count) {
    if (count == WINDOW_SIZE) {
        *sum -= buf[idx];
    }
    buf[idx] = new_val;
    *sum += new_val;
}

PipelineResult pipeline_process(SensorPipeline *p, float ax, float ay, float az) {
    PipelineResult result = {0};

    // Update ring buffers
    update_ring(p->x_buf, &p->sum_x, ax, p->idx, p->count);
    update_ring(p->y_buf, &p->sum_y, ay, p->idx, p->count);
    update_ring(p->z_buf, &p->sum_z, az, p->idx, p->count);

    // Compute moving average for DC removal
    float denom = (p->count < WINDOW_SIZE) ? (float)(p->count + 1) : (float)WINDOW_SIZE;
    float mean_x = p->sum_x / denom;
    float mean_y = p->sum_y / denom;
    float mean_z = p->sum_z / denom;

    float dx = ax - mean_x;
    float dy = ay - mean_y;
    float dz = az - mean_z;

    // Magnitude of detrended signal
    float mag = fast_sqrtf(dx * dx + dy * dy + dz * dz);

    // Update magnitude buffer / stats
    if (p->count == WINDOW_SIZE) {
        p->sum_mag -= p->mag_buf[p->idx];
        p->sumsq_mag -= p->mag_buf[p->idx] * p->mag_buf[p->idx];
    }
    p->mag_buf[p->idx] = mag;
    p->sum_mag += mag;
    p->sumsq_mag += mag * mag;

    float mag_mean = p->sum_mag / denom;
    float mag_var = (p->sumsq_mag / denom) - (mag_mean * mag_mean);
    if (mag_var < 0.0f) mag_var = 0.0f;

    // Simple anomaly decision
    bool is_anomaly_now = (mag > MAG_THRESHOLD) || (mag_var > VAR_THRESHOLD);

    if (is_anomaly_now) {
        if (p->anomaly_streak < 255) p->anomaly_streak++;
    } else {
        p->anomaly_streak = 0;
    }

    p->anomaly_detected = (p->anomaly_streak >= ANOMALY_COUNT_LIMIT);

    // Advance ring index
    p->idx = (p->idx + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) p->count++;

    result.ax = dx;
    result.ay = dy;
    result.az = dz;
    result.mag = mag;
    result.mag_mean = mag_mean;
    result.mag_var = mag_var;
    result.anomaly = p->anomaly_detected;

    return result;
}
```

