### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

void pipeline_init(anomaly_detector_t *detector) {
    detector->baseline_mean = 0.0f;
    detector->baseline_std = 0.0f;
    detector->anomaly_threshold = 3.0f;   // z-score threshold
    detector->warmup_windows = 8;
    detector->processed_windows = 0;
}

bool pipeline_push_sample(anomaly_detector_t *detector, sample_window_t *window, const accel_sample_t *sample) {
    (void)detector;

    window->window[window->index] = *sample;
    window->index = (window->index + 1) % WINDOW_SIZE;

    if (window->count < WINDOW_SIZE) {
        window->count++;
    }

    return (window->count == WINDOW_SIZE);
}

static void compute_features(const sample_window_t *window, feature_vector_t *features) {
    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = 1e9f;
    float max_v = -1e9f;
    float jerk_sum = 0.0f;

    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        uint32_t idx = (window->index + i) % WINDOW_SIZE;
        mags[i] = accel_magnitude(&window->window[idx]);
        sum += mags[i];
        sum_sq += mags[i] * mags[i];

        if (mags[i] < min_v) min_v = mags[i];
        if (mags[i] > max_v) max_v = mags[i];

        if (i > 0) {
            jerk_sum += fabsf(mags[i] - mags[i - 1]);
        }
    }

    float mean = sum / WINDOW_SIZE;
    float var = (sum_sq / WINDOW_SIZE) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    features->mean_mag = mean;
    features->std_mag = sqrtf(var);
    features->peak_to_peak = max_v - min_v;
    features->energy = sum_sq / WINDOW_SIZE;
    features->jerk_mean = jerk_sum / (WINDOW_SIZE - 1);
}

static float compute_anomaly_score(const anomaly_detector_t *detector, const feature_vector_t *f) {
    // Simple score based on deviation from baseline mean/std
    float denom = detector->baseline_std;
    if (denom < 1e-3f) denom = 1e-3f;

    float z_mean = fabsf(f->mean_mag - detector->baseline_mean) / denom;
    float z_std  = f->std_mag / denom;

    // Weighted combination
    return 0.7f * z_mean + 0.3f * z_std;
}

bool pipeline_process_window(anomaly_detector_t *detector, const sample_window_t *window, feature_vector_t *features, bool *is_anomaly) {
    compute_features(window, features);

    detector->processed_windows++;

    // Warmup: establish baseline
    if (detector->processed_windows <= detector->warmup_windows) {
        if (detector->processed_windows == 1) {
            detector->baseline_mean = features->mean_mag;
            detector->baseline_std = features->std_mag;
        } else {
            // simple running average
            float n = (float)detector->processed_windows;
            detector->baseline_mean = ((detector->baseline_mean * (n - 1.0f)) + features->mean_mag) / n;
            detector->baseline_std  = ((detector->baseline_std  * (n - 1.0f)) + features->std_mag) / n;
        }
        *is_anomaly = false;
        return true;
    }

    float score = compute_anomaly_score(detector, features);
    *is_anomaly = (score > detector->anomaly_threshold);

    // Slowly adapt baseline when not anomalous
    if (!*is_anomaly) {
        const float alpha = 0.02f;
        detector->baseline_mean = (1.0f - alpha) * detector->baseline_mean + alpha * features->mean_mag;
        detector->baseline_std  = (1.0f - alpha) * detector->baseline_std  + alpha * features->std_mag;
    }

    return true;
}
