### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float accel_magnitude(accel_sample_t s)
{
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static accel_sample_t low_pass_filter(sensor_pipeline_t *p, accel_sample_t in)
{
    // Simple exponential moving average
    const float alpha = 0.2f;

    if (!p->has_filter_state) {
        p->lp_x = in.x;
        p->lp_y = in.y;
        p->lp_z = in.z;
        p->has_filter_state = true;
    } else {
        p->lp_x = alpha * in.x + (1.0f - alpha) * p->lp_x;
        p->lp_y = alpha * in.y + (1.0f - alpha) * p->lp_y;
        p->lp_z = alpha * in.z + (1.0f - alpha) * p->lp_z;
    }

    accel_sample_t out = { p->lp_x, p->lp_y, p->lp_z };
    return out;
}

void sensor_pipeline_init(sensor_pipeline_t *p)
{
    memset(p, 0, sizeof(*p));
}

static void update_window(sensor_pipeline_t *p, accel_sample_t sample, float mag)
{
    if (p->count < PIPELINE_WINDOW_SIZE) {
        p->window[p->index] = sample;
        p->mag_window[p->index] = mag;
        p->mag_sum += mag;
        p->mag_sq_sum += mag * mag;
        p->count++;
    } else {
        float old_mag = p->mag_window[p->index];
        p->mag_sum -= old_mag;
        p->mag_sq_sum -= old_mag * old_mag;

        p->window[p->index] = sample;
        p->mag_window[p->index] = mag;
        p->mag_sum += mag;
        p->mag_sq_sum += mag * mag;
    }

    p->index = (p->index + 1) % PIPELINE_WINDOW_SIZE;
}

static feature_set_t compute_features(sensor_pipeline_t *p, float current_mag)
{
    feature_set_t f;
    memset(&f, 0, sizeof(f));

    f.magnitude = current_mag;
    f.sample_count = p->count;

    if (p->count > 0) {
        f.mean_mag = p->mag_sum / (float)p->count;
        float mean_sq = p->mag_sq_sum / (float)p->count;
        float variance = mean_sq - (f.mean_mag * f.mean_mag);
        if (variance < 0.0f) variance = 0.0f;
        f.stddev_mag = sqrtf(variance);
    }

    float max_delta = 0.0f;
    if (p->has_prev) {
        float dx = fabsf(p->prev_sample.x - p->window[(p->index + PIPELINE_WINDOW_SIZE - 1) % PIPELINE_WINDOW_SIZE].x);
        float dy = fabsf(p->prev_sample.y - p->window[(p->index + PIPELINE_WINDOW_SIZE - 1) % PIPELINE_WINDOW_SIZE].y);
        float dz = fabsf(p->prev_sample.z - p->window[(p->index + PIPELINE_WINDOW_SIZE - 1) % PIPELINE_WINDOW_SIZE].z);
        max_delta = fmaxf(dx, fmaxf(dy, dz));
    }
    f.max_delta = max_delta;

    return f;
}

static anomaly_result_t score_anomaly(feature_set_t f)
{
    anomaly_result_t r;
    memset(&r, 0, sizeof(r));
    r.features = f;

    // Basic rule-based scoring
    float score = 0.0f;

    // Spike: sudden large deviation from gravity and/or large delta
    float grav_dev = fabsf(f.magnitude - PIPELINE_GRAVITY_G);
    if (grav_dev > 0.8f) score += 0.6f;
    if (f.max_delta > PIPELINE_SPIKE_THRESH) score += 0.6f;

    // Vibration: high variance over the window
    if (f.stddev_mag > PIPELINE_MIN_STDDEV) score += 0.4f;
    if (f.stddev_mag > 0.35f) score += 0.4f;

    // Drop / impact-like event: magnitude near zero or very low
    if (f.magnitude < 0.2f) score += 0.8f;

    r.score = score;

    if (score >= 0.8f) {
        r.is_anomaly = true;

        if (f.magnitude < 0.2f) {
            r.type = ANOMALY_DROP;
        } else if (f.max_delta > PIPELINE_SPIKE_THRESH) {
            r.type = ANOMALY_SPIKE;
        } else {
            r.type = ANOMALY_VIBRATION;
        }
    } else {
        r.type = ANOMALY_NONE;
    }

    return r;
}

anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t sample)
{
    p->total_samples++;

    // 1) Filter
    accel_sample_t filtered = low_pass_filter(p, sample);

    // 2) Feature extraction
    float mag = accel_magnitude(filtered);
    update_window(p, filtered, mag);

    // 3) Compute features
    feature_set_t f = compute_features(p, mag);

    // 4) Score anomaly
    anomaly_result_t result = score_anomaly(f);

    // 5) Save previous sample
    p->prev_sample = filtered;
    p->has_prev = true;

    return result;
}
```

