Below is a solid **initial embedded C implementation** for an accelerometer anomaly-detection pipeline. It is designed to be:

- **lightweight**
- **streaming / sample-by-sample**
- **fixed-size and embedded-friendly**
- easy to extend later with more advanced features

It uses a simple pipeline:

1. **Acquire accelerometer sample**
2. **High-pass / baseline removal** via running mean
3. **Compute magnitude**
4. **Maintain rolling statistics**
5. **Flag anomaly** when magnitude deviates too much from normal behavior

---

## Assumptions

- 3-axis accelerometer input: `ax, ay, az`
- Sample rate is known and roughly stable
- You want a first-pass anomaly detector, not a trained ML model
- Embedded target may not have an FPU, so the code can be adapted to fixed-point later

---

## C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define BASELINE_ALPHA_NUM   1   // baseline = baseline + alpha * (x - baseline)
#define BASELINE_ALPHA_DEN   32
#define ANOMALY_THRESHOLD    3.0f
#define MIN_SAMPLES_FOR_DET  32

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float baseline_x;
    float baseline_y;
    float baseline_z;

    float mag_window[WINDOW_SIZE];
    uint16_t window_index;
    uint16_t window_count;

    float mag_sum;
    float mag_sum_sq;

    uint32_t sample_count;
} anomaly_detector_t;

typedef struct {
    bool anomaly;
    float magnitude;
    float mean;
    float stddev;
    float z_score;
} anomaly_result_t;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    det->baseline_x = 0.0f;
    det->baseline_y = 0.0f;
    det->baseline_z = 0.0f;
    det->window_index = 0;
    det->window_count = 0;
    det->mag_sum = 0.0f;
    det->mag_sum_sq = 0.0f;
    det->sample_count = 0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

static void update_baseline(float *baseline, float sample) {
    // Simple IIR low-pass estimate of gravity / bias
    *baseline += (sample - *baseline) / (float)BASELINE_ALPHA_DEN;
}

static void window_push(anomaly_detector_t *det, float mag) {
    if (det->window_count < WINDOW_SIZE) {
        det->mag_window[det->window_index] = mag;
        det->mag_sum += mag;
        det->mag_sum_sq += mag * mag;
        det->window_count++;
    } else {
        float old = det->mag_window[det->window_index];
        det->mag_window[det->window_index] = mag;
        det->mag_sum += mag - old;
        det->mag_sum_sq += (mag * mag) - (old * old);
    }

    det->window_index = (det->window_index + 1) % WINDOW_SIZE;
}

static void compute_stats(const anomaly_detector_t *det, float *mean, float *stddev) {
    if (det->window_count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = det->mag_sum / (float)det->window_count;

    float variance = (det->mag_sum_sq / (float)det->window_count) - (*mean * *mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    *stddev = fast_sqrtf(variance);
}

anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, accel_sample_t s) {
    anomaly_result_t result = {0};

    // Update baseline estimates
    update_baseline(&det->baseline_x, s.ax);
    update_baseline(&det->baseline_y, s.ay);
    update_baseline(&det->baseline_z, s.az);

    // Remove baseline
    float hx = s.ax - det->baseline_x;
    float hy = s.ay - det->baseline_y;
    float hz = s.az - det->baseline_z;

    // Magnitude of dynamic acceleration
    float mag = fast_sqrtf(hx * hx + hy * hy + hz * hz);

    // Update rolling window
    window_push(det, mag);
    det->sample_count++;

    // Compute statistics
    float mean = 0.0f;
    float stddev = 0.0f;
    compute_stats(det, &mean, &stddev);

    result.magnitude = mag;
    result.mean = mean;
    result.stddev = stddev;

    if (det->sample_count >= MIN_SAMPLES_FOR_DET && det->window_count >= MIN_SAMPLES_FOR_DET) {
        float epsilon = 0.0001f;
        float z = (mag - mean) / (stddev + epsilon);
        result.z_score = z;

        if (fabsf(z) > ANOMALY_THRESHOLD) {
            result.anomaly = true;
        }
    }

    return result;
}
```

