Below is a solid **initial embedded C implementation** of a sensor-processing pipeline for **accelerometer anomaly detection**. It is designed to be:

- **streaming-friendly**
- **low memory**
- **fixed-size / embedded-safe**
- easy to adapt for bare-metal or RTOS use

It uses a simple pipeline:

1. **Acquire samples**
2. **Calibrate / bias-correct**
3. **Compute magnitude**
4. **Low-pass filter**
5. **Extract features over a sliding window**
6. **Detect anomalies using threshold-based scoring**

---

## 1) Design overview

### Assumptions
- Accelerometer data arrives as `x, y, z` samples.
- Sampling rate is fixed or approximately fixed.
- Anomalies are events like:
  - sudden shocks
  - excessive vibration
  - sustained motion outside expected range
  - sensor glitches / spikes

### Detection strategy
For an initial implementation, a practical embedded approach is:

- Compute acceleration magnitude:  
  `mag = sqrt(x² + y² + z²)`
- Remove gravity/bias using a simple baseline estimate or high-pass approximation.
- Maintain a sliding window of recent filtered magnitudes.
- Compute:
  - mean
  - variance / standard deviation
  - peak deviation
- Trigger anomaly if:
  - peak exceeds threshold, or
  - window variance is too high, or
  - sustained deviation persists

This is simple, fast, and easy to tune.

---

## 2) C implementation

### `sensor_pipeline.h`
```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#define PIPELINE_WINDOW_SIZE   32
#define PIPELINE_ALPHA         0.90f   // low-pass filter coefficient
#define PIPELINE_BASELINE_BETA  0.01f   // baseline adaptation rate

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float filtered_mag;
    float baseline_mag;
    float window[PIPELINE_WINDOW_SIZE];
    uint16_t window_index;
    uint16_t window_count;
    float sum;
    float sum_sq;
} sensor_pipeline_t;

typedef struct {
    bool anomaly;
    float score;
    float mean;
    float stddev;
    float peak;
} anomaly_result_t;

void sensor_pipeline_init(sensor_pipeline_t *p);
anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t sample);

#endif
```

---

### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>

static float clampf(float v, float min_v, float max_v)
{
    if (v < min_v) return min_v;
    if (v > max_v) return max_v;
    return v;
}

void sensor_pipeline_init(sensor_pipeline_t *p)
{
    if (!p) return;

    p->filtered_mag = 0.0f;
    p->baseline_mag = 0.0f;
    p->window_index = 0;
    p->window_count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;

    for (uint16_t i = 0; i < PIPELINE_WINDOW_SIZE; i++) {
        p->window[i] = 0.0f;
    }
}

anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t sample)
{
    anomaly_result_t result = {0};

    if (!p) {
        return result;
    }

    // 1) Compute magnitude
    float mag = sqrtf(sample.x * sample.x +
                      sample.y * sample.y +
                      sample.z * sample.z);

    // 2) Update baseline slowly (approx gravity / long-term offset)
    if (p->baseline_mag == 0.0f) {
        p->baseline_mag = mag;
    } else {
        p->baseline_mag = (1.0f - PIPELINE_BASELINE_BETA) * p->baseline_mag +
                           PIPELINE_BASELINE_BETA * mag;
    }

    // 3) Remove baseline and low-pass filter the deviation
    float deviation = mag - p->baseline_mag;
    p->filtered_mag = PIPELINE_ALPHA * p->filtered_mag +
                      (1.0f - PIPELINE_ALPHA) * deviation;

    // 4) Update sliding window statistics
    float old = p->window[p->window_index];

    if (p->window_count < PIPELINE_WINDOW_SIZE) {
        p->window_count++;
    } else {
        p->sum -= old;
        p->sum_sq -= old * old;
    }

    p->window[p->window_index] = p->filtered_mag;
    p->window_index = (p->window_index + 1) % PIPELINE_WINDOW_SIZE;

    p->sum += p->filtered_mag;
    p->sum_sq += p->filtered_mag * p->filtered_mag;

    // 5) Compute features
    float mean = 0.0f;
    float variance = 0.0f;
    float stddev = 0.0f;
    float peak = 0.0f;

    if (p->window_count > 0) {
        mean = p->sum / (float)p->window_count;
        variance = (p->sum_sq / (float)p->window_count) - (mean * mean);
        variance = clampf(variance, 0.0f, 1e9f);
        stddev = sqrtf(variance);

        for (uint16_t i = 0; i < p->window_count; i++) {
            float v = fabsf(p->window[i] - mean);
            if (v > peak) {
                peak = v;
            }
        }
    }

    // 6) Simple anomaly score
    // Tune these thresholds for your application.
    const float PEAK_THRESHOLD = 1.5f;
    const float STDDEV_THRESHOLD = 0.5f;
    const float SCORE_THRESHOLD = 1.0f;

    float score = 0.0f;
    if (peak > PEAK_THRESHOLD) {
        score += (peak - PEAK_THRESHOLD);
    }
    if (stddev > STDDEV_THRESHOLD) {
        score += (stddev - STDDEV_THRESHOLD);
    }

    result.mean = mean;
    result.stddev = stddev;
    result.peak = peak;
    result.score = score;
    result.anomaly = (score > SCORE_THRESHOLD);

    return result;
}
```

