## Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE         64
#define BASELINE_SAMPLES     256
#define ANOMALY_SCORE_LIMIT  3

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mean_mag;
    float rms_mag;
    float var_mag;
    float p2p_mag;
} accel_features_t;

typedef struct {
    accel_sample_t window[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} sample_buffer_t;

typedef struct {
    float mean_mag;
    float std_mag;
    float mean_rms;
    float std_rms;
    float mean_var;
    float std_var;
    float mean_p2p;
    float std_p2p;
    bool trained;
} anomaly_model_t;

typedef struct {
    sample_buffer_t buffer;
    anomaly_model_t model;
    uint32_t baseline_count;
    float baseline_mag_sum;
    float baseline_mag_sq_sum;
    float baseline_rms_sum;
    float baseline_rms_sq_sum;
    float baseline_var_sum;
    float baseline_var_sq_sum;
    float baseline_p2p_sum;
    float baseline_p2p_sq_sum;
} sensor_pipeline_t;

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static void buffer_init(sample_buffer_t *buf)
{
    memset(buf, 0, sizeof(*buf));
}

static void buffer_push(sample_buffer_t *buf, accel_sample_t sample)
{
    buf->window[buf->head] = sample;
    buf->head = (buf->head + 1) % WINDOW_SIZE;
    if (buf->count < WINDOW_SIZE) {
        buf->count++;
    }
}

static bool buffer_full(const sample_buffer_t *buf)
{
    return buf->count == WINDOW_SIZE;
}

static void compute_features(const sample_buffer_t *buf, accel_features_t *out)
{
    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_mag = 1e30f;
    float max_mag = -1e30f;

    for (uint16_t i = 0; i < buf->count; i++) {
        uint16_t idx = (buf->head + WINDOW_SIZE - buf->count + i) % WINDOW_SIZE;
        mags[i] = accel_magnitude(&buf->window[idx]);
        sum += mags[i];
        sum_sq += mags[i] * mags[i];
        if (mags[i] < min_mag) min_mag = mags[i];
        if (mags[i] > max_mag) max_mag = mags[i];
    }

    float n = (float)buf->count;
    float mean = sum / n;
    float rms = sqrtf(sum_sq / n);

    float var = 0.0f;
    for (uint16_t i = 0; i < buf->count; i++) {
        float d = mags[i] - mean;
        var += d * d;
    }
    var /= n;

    out->mean_mag = mean;
    out->rms_mag = rms;
    out->var_mag = var;
    out->p2p_mag = max_mag - min_mag;
}

static void pipeline_init(sensor_pipeline_t *p)
{
    memset(p, 0, sizeof(*p));
    buffer_init(&p->buffer);
}

static void baseline_accumulate(sensor_pipeline_t *p, const accel_features_t *f)
{
    p->baseline_count++;

    p->baseline_mag_sum += f->mean_mag;
    p->baseline_mag_sq_sum += f->mean_mag * f->mean_mag;

    p->baseline_rms_sum += f->rms_mag;
    p->baseline_rms_sq_sum += f->rms_mag * f->rms_mag;

    p->baseline_var_sum += f->var_mag;
    p->baseline_var_sq_sum += f->var_mag * f->var_mag;

    p->baseline_p2p_sum += f->p2p_mag;
    p->baseline_p2p_sq_sum += f->p2p_mag * f->p2p_mag;
}

static float std_from_sums(float sum, float sq_sum, uint32_t n)
{
    if (n < 2) return 0.0f;
    float mean = sum / (float)n;
    float var = (sq_sum / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

static void train_model(sensor_pipeline_t *p)
{
    uint32_t n = p->baseline_count;
    if (n == 0) return;

    p->model.mean_mag = p->baseline_mag_sum / (float)n;
    p->model.std_mag  = std_from_sums(p->baseline_mag_sum, p->baseline_mag_sq_sum, n);

    p->model.mean_rms = p->baseline_rms_sum / (float)n;
    p->model.std_rms  = std_from_sums(p->baseline_rms_sum, p->baseline_rms_sq_sum, n);

    p->model.mean_var = p->baseline_var_sum / (float)n;
    p->model.std_var  = std_from_sums(p->baseline_var_sum, p->baseline_var_sq_sum, n);

    p->model.mean_p2p = p->baseline_p2p_sum / (float)n;
    p->model.std_p2p  = std_from_sums(p->baseline_p2p_sum, p->baseline_p2p_sq_sum, n);

    p->model.trained = true;
}

static int anomaly_score(const sensor_pipeline_t *p, const accel_features_t *f)
{
    if (!p->model.trained) return 0;

    int score = 0;

    if (fabsf(f->mean_mag - p->model.mean_mag) > 3.0f * p->model.std_mag) score++;
    if (fabsf(f->rms_mag  - p->model.mean_rms) > 3.0f * p->model.std_rms) score++;
    if (fabsf(f->var_mag  - p->model.mean_var) > 3.0f * p->model.std_var) score++;
    if (fabsf(f->p2p_mag  - p->model.mean_p2p) > 3.0f * p->model.std_p2p) score++;

    return score;
}

/*
 * Returns true if anomaly detected.
 * During startup, this function collects baseline data and trains the model.
 */
bool sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t sample)
{
    buffer_push(&p->buffer, sample);

    if (!buffer_full(&p->buffer)) {
        return false;
    }

    accel_features_t features;
    compute_features(&p->buffer, &features);

    if (!p->model.trained) {
        baseline_accumulate(p, &features);

        if (p->baseline_count >= BASELINE_SAMPLES) {
            train_model(p);
        }
        return false;
    }

    int score = anomaly_score(p, &features);
    return (score >= ANOMALY_SCORE_LIMIT);
}
