## Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

// -----------------------------
// Configuration
// -----------------------------
#define PIPELINE_WINDOW_SIZE     32
#define PIPELINE_ANOMALY_ZTHRESH 3.0f
#define PIPELINE_LPF_ALPHA       0.10f   // 0..1, higher = more responsive

// -----------------------------
// Data types
// -----------------------------
typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float filtered_mag;
    float baseline_mean;
    float baseline_var;
    bool  anomaly;
    float anomaly_score;
} pipeline_result_t;

typedef struct {
    // Low-pass filter state
    float lpf_mag;
    bool  lpf_initialized;

    // Rolling statistics over filtered magnitude
    float window[PIPELINE_WINDOW_SIZE];
    uint32_t window_index;
    uint32_t window_count;
    float sum;
    float sum_sq;

    // Detection state
    float baseline_mean;
    float baseline_var;
} sensor_pipeline_t;

// -----------------------------
// API
// -----------------------------
void sensor_pipeline_init(sensor_pipeline_t *p);
pipeline_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t s);

#endif // SENSOR_PIPELINE_H

// -----------------------------
// Implementation
// -----------------------------

static float compute_magnitude(accel_sample_t s)
{
    return sqrtf((s.ax * s.ax) + (s.ay * s.ay) + (s.az * s.az));
}

void sensor_pipeline_init(sensor_pipeline_t *p)
{
    if (!p) return;

    p->lpf_mag = 0.0f;
    p->lpf_initialized = false;

    for (uint32_t i = 0; i < PIPELINE_WINDOW_SIZE; i++) {
        p->window[i] = 0.0f;
    }

    p->window_index = 0;
    p->window_count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;

    p->baseline_mean = 0.0f;
    p->baseline_var = 0.0f;
}

static void update_rolling_stats(sensor_pipeline_t *p, float x)
{
    // Remove old sample if window full
    if (p->window_count == PIPELINE_WINDOW_SIZE) {
        float old = p->window[p->window_index];
        p->sum    -= old;
        p->sum_sq -= old * old;
    } else {
        p->window_count++;
    }

    // Add new sample
    p->window[p->window_index] = x;
    p->sum    += x;
    p->sum_sq += x * x;

    p->window_index = (p->window_index + 1) % PIPELINE_WINDOW_SIZE;

    // Compute mean and variance
    if (p->window_count > 0) {
        p->baseline_mean = p->sum / (float)p->window_count;

        float mean_sq = p->baseline_mean * p->baseline_mean;
        float avg_sq   = p->sum_sq / (float)p->window_count;
        float var      = avg_sq - mean_sq;

        // Clamp numerical noise
        p->baseline_var = (var > 0.0f) ? var : 0.0f;
    }
}

pipeline_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t s)
{
    pipeline_result_t result = {0};

    if (!p) {
        return result;
    }

    // 1) Magnitude
    float mag = compute_magnitude(s);

    // 2) Low-pass filter
    if (!p->lpf_initialized) {
        p->lpf_mag = mag;
        p->lpf_initialized = true;
    } else {
        p->lpf_mag = (PIPELINE_LPF_ALPHA * mag) +
                     ((1.0f - PIPELINE_LPF_ALPHA) * p->lpf_mag);
    }

    // 3) Update baseline statistics
    update_rolling_stats(p, p->lpf_mag);

    // 4) Anomaly detection using z-score-like threshold
    float stddev = sqrtf(p->baseline_var);
    float score = 0.0f;
    bool anomaly = false;

    if (stddev > 1e-6f) {
        score = fabsf(p->lpf_mag - p->baseline_mean) / stddev;
        anomaly = (score > PIPELINE_ANOMALY_ZTHRESH);
    }

    result.filtered_mag  = p->lpf_mag;
    result.baseline_mean = p->baseline_mean;
    result.baseline_var  = p->baseline_var;
    result.anomaly_score = score;
    result.anomaly       = anomaly;

    return result;
}
```

