```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define ACC_WINDOW_SIZE     32
#define ACC_BASELINE_ALPHA  0.01f
#define ACC_ANOMALY_THRESH  3.0f   // tune this
#define ACC_JERK_THRESH     1.5f   // tune this

typedef struct {
    float ax;
    float ay;
    float az;
    float mag;
} AccSample;

typedef struct {
    float mean;
    float stddev;
    float min;
    float max;
    float rms;
    float jerk_mean;
} AccFeatures;

typedef struct {
    AccSample window[ACC_WINDOW_SIZE];
    uint8_t head;
    uint8_t count;

    // simple baseline model
    float baseline_mean;
    float baseline_stddev;
    float baseline_rms;
    float baseline_jerk;

    bool baseline_initialized;
} AccPipeline;

typedef struct {
    bool anomaly;
    float score;
    AccFeatures features;
} AccResult;

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

static void acc_pipeline_init(AccPipeline *p) {
    memset(p, 0, sizeof(*p));
}

static void acc_pipeline_push(AccPipeline *p, float ax, float ay, float az) {
    AccSample s;
    s.ax = ax;
    s.ay = ay;
    s.az = az;
    s.mag = compute_magnitude(ax, ay, az);

    p->window[p->head] = s;
    p->head = (uint8_t)((p->head + 1) % ACC_WINDOW_SIZE);
    if (p->count < ACC_WINDOW_SIZE) {
        p->count++;
    }
}

static void compute_features(const AccPipeline *p, AccFeatures *f) {
    memset(f, 0, sizeof(*f));

    if (p->count == 0) return;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = p->window[0].mag;
    float max_v = p->window[0].mag;
    float jerk_sum = 0.0f;
    uint8_t jerk_n = 0;

    uint8_t start = (p->head + ACC_WINDOW_SIZE - p->count) % ACC_WINDOW_SIZE;

    float prev = p->window[start].mag;
    for (uint8_t i = 0; i < p->count; i++) {
        uint8_t idx = (uint8_t)((start + i) % ACC_WINDOW_SIZE);
        float v = p->window[idx].mag;

        sum += v;
        sum_sq += v * v;

        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;

        if (i > 0) {
            jerk_sum += fast_absf(v - prev);
            jerk_n++;
        }
        prev = v;
    }

    float n = (float)p->count;
    float mean = sum / n;
    float variance = (sum_sq / n) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;

    f->mean = mean;
    f->stddev = sqrtf(variance);
    f->min = min_v;
    f->max = max_v;
    f->rms = sqrtf(sum_sq / n);
    f->jerk_mean = (jerk_n > 0) ? (jerk_sum / (float)jerk_n) : 0.0f;
}

static void update_baseline(AccPipeline *p, const AccFeatures *f) {
    if (!p->baseline_initialized) {
        p->baseline_mean = f->mean;
        p->baseline_stddev = f->stddev;
        p->baseline_rms = f->rms;
        p->baseline_jerk = f->jerk_mean;
        p->baseline_initialized = true;
        return;
    }

    const float a = ACC_BASELINE_ALPHA;
    p->baseline_mean   = (1.0f - a) * p->baseline_mean   + a * f->mean;
    p->baseline_stddev = (1.0f - a) * p->baseline_stddev + a * f->stddev;
    p->baseline_rms    = (1.0f - a) * p->baseline_rms    + a * f->rms;
    p->baseline_jerk   = (1.0f - a) * p->baseline_jerk   + a * f->jerk_mean;
}

static float anomaly_score(const AccPipeline *p, const AccFeatures *f) {
    if (!p->baseline_initialized) return 0.0f;

    // normalized deviations
    float d_mean = fast_absf(f->mean - p->baseline_mean);
    float d_std  = fast_absf(f->stddev - p->baseline_stddev);
    float d_rms  = fast_absf(f->rms - p->baseline_rms);
    float d_jerk = fast_absf(f->jerk_mean - p->baseline_jerk);

    // weighted sum, tune weights as needed
    float score = 0.0f;
    score += 1.0f * d_mean;
    score += 1.5f * d_std;
    score += 1.0f * d_rms;
    score += 2.0f * d_jerk;

    return score;
}

static AccResult acc_pipeline_process(AccPipeline *p, float ax, float ay, float az) {
    AccResult r;
    memset(&r, 0, sizeof(r));

    acc_pipeline_push(p, ax, ay, az);

    // Need a full window for meaningful detection
    if (p->count < ACC_WINDOW_SIZE) {
        return r;
    }

    AccFeatures f;
    compute_features(p, &f);
    r.features = f;

    if (!p->baseline_initialized) {
        update_baseline(p, &f);
        return r;
    }

    r.score = anomaly_score(p, &f);
    r.anomaly = (r.score > ACC_ANOMALY_THRESH) || (f.jerk_mean > ACC_JERK_THRESH);

    // Update baseline only when not anomalous
    if (!r.anomaly) {
        update_baseline(p, &f);
    }

    return r;
}
```

