Below is a compact initial implementation for an embedded sensor-processing pipeline that reads accelerometer samples, filters them, computes a simple motion feature, and flags anomalies when the signal deviates from a running baseline.

I’ll assume:
- C/C++-style embedded environment
- 3-axis accelerometer
- fixed sample rate
- limited RAM/CPU
- no ML model yet, just lightweight anomaly detection

---

## Design overview

Pipeline stages:

1. **Acquire samples**
   - Read `ax, ay, az` from the sensor.
2. **Preprocess**
   - Optional offset removal / calibration
   - Low-pass filter to reduce noise
3. **Feature extraction**
   - Compute magnitude: `sqrt(ax² + ay² + az²)`
   - Or use squared magnitude to avoid `sqrt`
4. **Baseline tracking**
   - Maintain running mean and variance using Welford’s algorithm or EMA
5. **Anomaly detection**
   - Flag anomaly if current feature is outside `mean ± k * stddev`
6. **Event handling**
   - Emit anomaly event, log, or trigger actuator

---

## Initial C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define FILTER_ALPHA         0.2f
#define BASELINE_ALPHA       0.01f
#define ANOMALY_Z_THRESHOLD  3.0f
#define MIN_BASELINE_SAMPLES  50

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float x;
    float y;
    float z;
} AccelState;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} RunningStats;

typedef struct {
    AccelState lp_state;
    RunningStats stats;
    bool initialized;
} SensorPipeline;

static float low_pass(float input, float prev, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

static float magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static void running_stats_init(RunningStats *rs) {
    rs->mean = 0.0f;
    rs->m2 = 0.0f;
    rs->count = 0;
}

static void running_stats_update(RunningStats *rs, float value) {
    rs->count++;
    float delta = value - rs->mean;
    rs->mean += delta / (float)rs->count;
    float delta2 = value - rs->mean;
    rs->m2 += delta * delta2;
}

static float running_stats_variance(const RunningStats *rs) {
    if (rs->count < 2) return 0.0f;
    return rs->m2 / (float)(rs->count - 1);
}

static void pipeline_init(SensorPipeline *p) {
    p->lp_state.x = 0.0f;
    p->lp_state.y = 0.0f;
    p->lp_state.z = 0.0f;
    running_stats_init(&p->stats);
    p->initialized = true;
}

typedef struct {
    bool anomaly;
    float feature;
    float mean;
    float stddev;
} PipelineResult;

PipelineResult pipeline_process(SensorPipeline *p, AccelSample raw) {
    if (!p->initialized) {
        pipeline_init(p);
    }

    // Low-pass filter each axis
    p->lp_state.x = low_pass(raw.x, p->lp_state.x, FILTER_ALPHA);
    p->lp_state.y = low_pass(raw.y, p->lp_state.y, FILTER_ALPHA);
    p->lp_state.z = low_pass(raw.z, p->lp_state.z, FILTER_ALPHA);

    AccelSample filtered = {
        .x = p->lp_state.x,
        .y = p->lp_state.y,
        .z = p->lp_state.z
    };

    float feature = magnitude(&filtered);

    // Warm-up period: collect baseline only
    if (p->stats.count < MIN_BASELINE_SAMPLES) {
        running_stats_update(&p->stats, feature);
        return (PipelineResult){
            .anomaly = false,
            .feature = feature,
            .mean = p->stats.mean,
            .stddev = 0.0f
        };
    }

    float variance = running_stats_variance(&p->stats);
    float stddev = sqrtf(variance);

    bool anomaly = false;
    if (stddev > 1e-6f) {
        float z = fabsf(feature - p->stats.mean) / stddev;
        anomaly = (z > ANOMALY_Z_THRESHOLD);
    }

    // Update baseline slowly to adapt to gradual changes
    // Optionally skip baseline update on anomaly
    if (!anomaly) {
        // EMA-style baseline tracking
        p->stats.mean = (1.0f - BASELINE_ALPHA) * p->stats.mean + BASELINE_ALPHA * feature;
        // Approximate variance update
        float diff = feature - p->stats.mean;
        p->stats.m2 = (1.0f - BASELINE_ALPHA) * p->stats.m2 + BASELINE_ALPHA * (diff * diff);
        p->stats.count++;
    }

    return (PipelineResult){
        .anomaly = anomaly,
        .feature = feature,
        .mean = p->stats.mean,
        .stddev = stddev
    };
}
```

