Below is a solid **initial implementation** of an embedded-friendly accelerometer anomaly-detection pipeline. It is designed to be simple, low-memory, and easy to port to a microcontroller.

## What it does
- Reads 3-axis accelerometer samples
- Computes signal magnitude
- Applies a lightweight moving average filter
- Maintains a rolling baseline
- Detects anomalies when the signal deviates significantly from baseline
- Uses a small state machine to reduce false positives

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         16
#define BASELINE_SIZE        64
#define ANOMALY_THRESHOLD    2.5f   // Tune based on sensor/noise characteristics
#define MIN_ANOMALY_COUNT    3      // Require consecutive outliers
#define RECOVERY_COUNT       8

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float window[WINDOW_SIZE];
    uint8_t window_idx;
    uint8_t window_count;

    float baseline[BASELINE_SIZE];
    uint8_t baseline_idx;
    uint8_t baseline_count;

    float filtered_value;
    float baseline_mean;
    float baseline_stddev;

    uint8_t anomaly_count;
    uint8_t recovery_count;
    bool anomaly_active;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static float moving_average_update(anomaly_detector_t *detector, float value) {
    detector->window[detector->window_idx] = value;
    detector->window_idx = (detector->window_idx + 1) % WINDOW_SIZE;

    if (detector->window_count < WINDOW_SIZE) {
        detector->window_count++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < detector->window_count; i++) {
        sum += detector->window[i];
    }
    return sum / (float)detector->window_count;
}

static void baseline_update(anomaly_detector_t *detector, float value) {
    detector->baseline[detector->baseline_idx] = value;
    detector->baseline_idx = (detector->baseline_idx + 1) % BASELINE_SIZE;

    if (detector->baseline_count < BASELINE_SIZE) {
        detector->baseline_count++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < detector->baseline_count; i++) {
        sum += detector->baseline[i];
    }
    detector->baseline_mean = sum / (float)detector->baseline_count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < detector->baseline_count; i++) {
        float d = detector->baseline[i] - detector->baseline_mean;
        var_sum += d * d;
    }
    detector->baseline_stddev = fast_sqrtf(var_sum / (float)detector->baseline_count);
}

void anomaly_detector_init(anomaly_detector_t *detector) {
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        detector->window[i] = 0.0f;
    }
    for (uint8_t i = 0; i < BASELINE_SIZE; i++) {
        detector->baseline[i] = 0.0f;
    }

    detector->window_idx = 0;
    detector->window_count = 0;
    detector->baseline_idx = 0;
    detector->baseline_count = 0;
    detector->filtered_value = 0.0f;
    detector->baseline_mean = 0.0f;
    detector->baseline_stddev = 0.0f;
    detector->anomaly_count = 0;
    detector->recovery_count = 0;
    detector->anomaly_active = false;
}

/*
 * Returns true if an anomaly is currently active.
 * Call this once per new accelerometer sample.
 */
bool anomaly_detector_process(anomaly_detector_t *detector, const accel_sample_t *sample) {
    float mag = compute_magnitude(sample);
    float filtered = moving_average_update(detector, mag);
    detector->filtered_value = filtered;

    // Build baseline during startup
    if (detector->baseline_count < BASELINE_SIZE) {
        baseline_update(detector, filtered);
        return false;
    }

    // Simple z-score-like deviation check
    float deviation = fabsf(filtered - detector->baseline_mean);
    float threshold = ANOMALY_THRESHOLD * (detector->baseline_stddev + 0.001f);

    bool outlier = (deviation > threshold);

    if (outlier) {
        if (detector->anomaly_count < 255) detector->anomaly_count++;
        detector->recovery_count = 0;
    } else {
        detector->anomaly_count = 0;
        if (detector->recovery_count < 255) detector->recovery_count++;
    }

    if (!detector->anomaly_active) {
        if (detector->anomaly_count >= MIN_ANOMALY_COUNT) {
            detector->anomaly_active = true;
            detector->recovery_count = 0;
        }
    } else {
        // Update baseline only when not anomalous
        if (!outlier) {
            baseline_update(detector, filtered);
        }

        if (detector->recovery_count >= RECOVERY_COUNT) {
            detector->anomaly_active = false;
            detector->anomaly_count = 0;
        }
    }

    return detector->anomaly_active;
}
```

