Below is a **minimal working embedded-style sensor-processing pipeline** for **anomaly detection from accelerometer data**. It is designed to be simple enough to run on a microcontroller, while still reflecting a realistic pipeline:

1. **Acquire accelerometer samples**
2. **Filter / smooth**
3. **Extract a small feature**
4. **Compare against a baseline**
5. **Flag anomalies**

---

## 1) Minimal pipeline concept

A practical low-cost anomaly detector for embedded systems is:

- Read 3-axis accelerometer samples: `(ax, ay, az)`
- Compute acceleration magnitude:
  \[
  m = \sqrt{ax^2 + ay^2 + az^2}
  \]
- Apply a simple moving average to reduce noise
- Maintain a rolling baseline mean and standard deviation
- Flag anomaly if the current value deviates too much from baseline

This works well as a **baseline detector** for sudden shocks, drops, vibration changes, or motion events.

---

## 2) Minimal C implementation

This version is written in plain C and should be easy to adapt to bare-metal or RTOS firmware.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 8
#define BASELINE_SIZE 32
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float x[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
} MovingAverage;

typedef struct {
    float buf[BASELINE_SIZE];
    int idx;
    int count;
} BaselineBuffer;

static void ma_init(MovingAverage *ma) {
    ma->idx = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) ma->x[i] = 0.0f;
}

static float ma_update(MovingAverage *ma, float sample) {
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    } else {
        ma->sum -= ma->x[ma->idx];
    }

    ma->x[ma->idx] = sample;
    ma->sum += sample;
    ma->idx = (ma->idx + 1) % WINDOW_SIZE;

    return ma->sum / (float)ma->count;
}

static void baseline_init(BaselineBuffer *b) {
    b->idx = 0;
    b->count = 0;
    for (int i = 0; i < BASELINE_SIZE; i++) b->buf[i] = 0.0f;
}

static void baseline_update(BaselineBuffer *b, float sample) {
    b->buf[b->idx] = sample;
    b->idx = (b->idx + 1) % BASELINE_SIZE;
    if (b->count < BASELINE_SIZE) b->count++;
}

static void baseline_stats(const BaselineBuffer *b, float *mean, float *stddev) {
    if (b->count == 0) {
        *mean = 0.0f;
        *stddev = 1.0f;
        return;
    }

    float sum = 0.0f;
    for (int i = 0; i < b->count; i++) {
        sum += b->buf[i];
    }
    *mean = sum / (float)b->count;

    float var = 0.0f;
    for (int i = 0; i < b->count; i++) {
        float d = b->buf[i] - *mean;
        var += d * d;
    }
    var /= (float)b->count;

    *stddev = sqrtf(var);
    if (*stddev < 1e-6f) *stddev = 1e-6f;
}

typedef struct {
    MovingAverage ma;
    BaselineBuffer baseline;
    bool baseline_ready;
} SensorPipeline;

void pipeline_init(SensorPipeline *p) {
    ma_init(&p->ma);
    baseline_init(&p->baseline);
    p->baseline_ready = false;
}

static float accel_magnitude(int16_t ax, int16_t ay, int16_t az) {
    float fx = (float)ax;
    float fy = (float)ay;
    float fz = (float)az;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

// Returns true if anomaly detected
bool pipeline_process_sample(SensorPipeline *p, int16_t ax, int16_t ay, int16_t az) {
    // 1) Feature extraction
    float mag = accel_magnitude(ax, ay, az);

    // 2) Smoothing
    float smooth_mag = ma_update(&p->ma, mag);

    // 3) Build baseline until enough samples are collected
    if (!p->baseline_ready) {
        baseline_update(&p->baseline, smooth_mag);
        if (p->baseline.count >= BASELINE_SIZE) {
            p->baseline_ready = true;
        }
        return false;
    }

    // 4) Compare to baseline
    float mean, stddev;
    baseline_stats(&p->baseline, &mean, &stddev);

    float z = (smooth_mag - mean) / stddev;
    bool anomaly = (z > ANOMALY_Z_THRESHOLD) || (z < -ANOMALY_Z_THRESHOLD);

    // 5) Update baseline only if not anomalous
    if (!anomaly) {
        baseline_update(&p->baseline, smooth_mag);
    }

    return anomaly;
}
```

