Below is a minimal working embedded-style pipeline for anomaly detection from accelerometer data. It is intentionally simple and suitable as a starting point for a microcontroller project.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple feature per window: RMS magnitude
3. Compares against a baseline
4. Flags an anomaly when deviation is too large

---

## Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#define WINDOW_SIZE 32
#define ANOMALY_THRESHOLD 0.35f   // tune for your sensor / application

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float samples[WINDOW_SIZE];
    uint8_t idx;
    bool full;
} window_t;

static void window_init(window_t *w) {
    w->idx = 0;
    w->full = false;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->samples[i] = 0.0f;
    }
}

static void window_push(window_t *w, float value) {
    w->samples[w->idx++] = value;
    if (w->idx >= WINDOW_SIZE) {
        w->idx = 0;
        w->full = true;
    }
}

static float compute_rms(const window_t *w) {
    float sum = 0.0f;
    int count = w->full ? WINDOW_SIZE : w->idx;
    if (count == 0) return 0.0f;

    for (int i = 0; i < count; i++) {
        sum += w->samples[i] * w->samples[i];
    }
    return sqrtf(sum / count);
}

// Placeholder: replace with your actual sensor read function
static accel_sample_t read_accelerometer(void) {
    accel_sample_t s = {0.0f, 0.0f, 1.0f}; // stationary example
    return s;
}

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

int main(void) {
    window_t mag_window;
    window_init(&mag_window);

    // Baseline learned from initial stationary period
    float baseline_rms = 1.0f;

    while (1) {
        accel_sample_t sample = read_accelerometer();
        float mag = accel_magnitude(&sample);

        window_push(&mag_window, mag);

        if (mag_window.full) {
            float rms = compute_rms(&mag_window);
            float deviation = fabsf(rms - baseline_rms);

            if (deviation > ANOMALY_THRESHOLD) {
                printf("Anomaly detected! RMS=%.3f baseline=%.3f dev=%.3f\n",
                       rms, baseline_rms, deviation);
            } else {
                printf("Normal. RMS=%.3f\n", rms);
            }
        }

        // Add your platform delay here, e.g. 10 ms
    }

    return 0;
}
```

