Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from accelerometer data. It’s designed to be simple enough to run on a microcontroller or be adapted to one.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple magnitude-based feature
3. Maintains a rolling baseline
4. Flags an anomaly when the current magnitude deviates too much from the baseline

---

## Minimal pipeline logic

### Detection idea
For each sample `(ax, ay, az)`:

- Compute acceleration magnitude:
  \[
  m = \sqrt{ax^2 + ay^2 + az^2}
  \]
- Update a rolling mean and variance over a small window
- If the current magnitude is far from the rolling mean, mark it as anomalous

A simple threshold rule:
\[
|m - \mu| > k \cdot \sigma
\]
where:
- `μ` = rolling mean
- `σ` = rolling standard deviation
- `k` = sensitivity factor, e.g. `3.0`

---

## C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define ANOMALY_K 3.0f

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sum_sq;
} RollingStats;

void rolling_stats_init(RollingStats *rs) {
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sum_sq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rs->buffer[i] = 0.0f;
    }
}

void rolling_stats_update(RollingStats *rs, float value) {
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index++] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->count++;
        if (rs->index >= WINDOW_SIZE) rs->index = 0;
    } else {
        float old = rs->buffer[rs->index];
        rs->buffer[rs->index] = value;
        rs->sum += value - old;
        rs->sum_sq += value * value - old * old;
        rs->index = (rs->index + 1) % WINDOW_SIZE;
    }
}

void rolling_stats_get(const RollingStats *rs, float *mean, float *stddev) {
    if (rs->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = rs->sum / rs->count;
    float variance = (rs->sum_sq / rs->count) - (*mean * *mean);
    if (variance < 0.0f) variance = 0.0f;
    *stddev = sqrtf(variance);
}

typedef struct {
    RollingStats stats;
    float anomaly_k;
} AnomalyDetector;

void detector_init(AnomalyDetector *detector) {
    rolling_stats_init(&detector->stats);
    detector->anomaly_k = ANOMALY_K;
}

bool detector_process_sample(AnomalyDetector *detector, float ax, float ay, float az) {
    float magnitude = sqrtf(ax * ax + ay * ay + az * az);

    float mean, stddev;
    rolling_stats_get(&detector->stats, &mean, &stddev);

    bool anomaly = false;
    if (detector->stats.count >= WINDOW_SIZE / 2) {
        float threshold = detector->anomaly_k * (stddev + 0.001f); // avoid zero threshold
        if (fabsf(magnitude - mean) > threshold) {
            anomaly = true;
        }
    }

    rolling_stats_update(&detector->stats, magnitude);
    return anomaly;
}
```

