Below is a **minimal working embedded-style sensor-processing pipeline** for **anomaly detection from accelerometer data**. It is intentionally simple so it can run on a microcontroller or be adapted easily.

## What it does
- Reads 3-axis accelerometer samples
- Computes a few lightweight features over a sliding window
- Uses a simple threshold-based anomaly detector
- Emits an anomaly flag when motion looks unusual

---

## Minimal pipeline design

### 1) Input
Accelerometer samples:
```c
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;
```

### 2) Windowed feature extraction
For each window of `N` samples:
- mean magnitude
- variance of magnitude
- peak magnitude

### 3) Detection rule
Flag anomaly if:
- variance is too high, or
- peak magnitude exceeds a threshold

This is not a full ML model, but it is a practical embedded baseline.

---

# C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define MAG_THRESHOLD 2.5f
#define VAR_THRESHOLD 0.20f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float magnitudes[WINDOW_SIZE];
    int index;
    int count;
} SensorWindow;

static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static void window_init(SensorWindow *w) {
    w->index = 0;
    w->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->magnitudes[i] = 0.0f;
    }
}

static void window_add(SensorWindow *w, float mag) {
    w->magnitudes[w->index] = mag;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static void compute_features(const SensorWindow *w, float *mean, float *var, float *peak) {
    float sum = 0.0f;
    float maxv = 0.0f;

    for (int i = 0; i < w->count; i++) {
        float v = w->magnitudes[i];
        sum += v;
        if (v > maxv) maxv = v;
    }

    *mean = sum / (float)w->count;

    float var_sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        float d = w->magnitudes[i] - *mean;
        var_sum += d * d;
    }
    *var = var_sum / (float)w->count;
    *peak = maxv;
}

static bool detect_anomaly(const SensorWindow *w) {
    if (w->count < WINDOW_SIZE) {
        return false; // not enough data yet
    }

    float mean, var, peak;
    compute_features(w, &mean, &var, &peak);

    // Simple baseline rules
    if (peak > MAG_THRESHOLD) return true;
    if (var > VAR_THRESHOLD) return true;

    return false;
}

int main(void) {
    SensorWindow window;
    window_init(&window);

    // Example data stream: mostly stable, then a spike
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.00f},
        {0.01f, 0.00f, 0.98f},
        {0.02f, 0.01f, 1.00f},
        {0.00f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.00f},
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 0.99f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.00f},
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 1.00f},

        // anomaly
        {2.00f, 1.50f, 3.00f}
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = magnitude(stream[i]);
        window_add(&window, mag);

        bool anomaly = detect_anomaly(&window);

        printf("Sample %2d: mag=%.3f  anomaly=%s\n",
               i, mag, anomaly ? "YES" : "NO");
    }

    return 0;
}
```

