Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or be adapted to one.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple magnitude-based feature
- Maintains a short rolling window
- Flags an anomaly when the signal deviates too much from the recent baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define THRESHOLD_MULTIPLIER 3.0f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float values[WINDOW_SIZE];
    int index;
    int count;
} RingBuffer;

void rb_init(RingBuffer *rb) {
    rb->index = 0;
    rb->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rb->values[i] = 0.0f;
    }
}

void rb_push(RingBuffer *rb, float value) {
    rb->values[rb->index] = value;
    rb->index = (rb->index + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

float rb_mean(const RingBuffer *rb) {
    if (rb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < rb->count; i++) {
        sum += rb->values[i];
    }
    return sum / rb->count;
}

float rb_stddev(const RingBuffer *rb, float mean) {
    if (rb->count < 2) return 0.0f;
    float sum_sq = 0.0f;
    for (int i = 0; i < rb->count; i++) {
        float d = rb->values[i] - mean;
        sum_sq += d * d;
    }
    return sqrtf(sum_sq / (rb->count - 1));
}

float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

bool detect_anomaly(RingBuffer *rb, float feature) {
    float mean = rb_mean(rb);
    float stddev = rb_stddev(rb, mean);

    // Need enough history before deciding
    if (rb->count < WINDOW_SIZE) {
        rb_push(rb, feature);
        return false;
    }

    float diff = fabsf(feature - mean);
    bool anomaly = (stddev > 0.0f) && (diff > THRESHOLD_MULTIPLIER * stddev);

    rb_push(rb, feature);
    return anomaly;
}

int main(void) {
    RingBuffer buffer;
    rb_init(&buffer);

    // Example stream of accelerometer samples
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.50f, 0.80f, 1.90f}, // likely anomaly
        {0.01f, 0.01f, 1.00f},
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(&stream[i]);
        bool anomaly = detect_anomaly(&buffer, mag);

        printf("Sample %d: mag=%.3f -> %s\n",
               i, mag, anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

