Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It is designed to be simple enough to run on a microcontroller or as a starting point for embedded firmware.

## What it does
- Reads 3-axis accelerometer samples
- Applies a simple low-pass filter
- Computes a rolling magnitude-based feature
- Flags an anomaly when the signal deviates too much from a baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ALPHA 0.2f
#define ANOMALY_THRESHOLD 2.5f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;
    float baseline_mean;
    float baseline_var;
    float window[WINDOW_SIZE];
    int window_index;
    int window_count;
} SensorPipeline;

void pipeline_init(SensorPipeline *p) {
    p->filtered_x = 0.0f;
    p->filtered_y = 0.0f;
    p->filtered_z = 0.0f;
    p->baseline_mean = 0.0f;
    p->baseline_var = 1.0f;
    p->window_index = 0;
    p->window_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->window[i] = 0.0f;
    }
}

static float low_pass(float prev, float current) {
    return ALPHA * current + (1.0f - ALPHA) * prev;
}

static float magnitude(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}

bool pipeline_process(SensorPipeline *p, AccelSample s) {
    // 1) Filter raw data
    p->filtered_x = low_pass(p->filtered_x, s.x);
    p->filtered_y = low_pass(p->filtered_y, s.y);
    p->filtered_z = low_pass(p->filtered_z, s.z);

    // 2) Compute feature: acceleration magnitude
    float mag = magnitude(p->filtered_x, p->filtered_y, p->filtered_z);

    // 3) Update rolling window
    p->window[p->window_index] = mag;
    p->window_index = (p->window_index + 1) % WINDOW_SIZE;
    if (p->window_count < WINDOW_SIZE) {
        p->window_count++;
    }

    // 4) Compute baseline mean and variance over window
    float sum = 0.0f;
    for (int i = 0; i < p->window_count; i++) {
        sum += p->window[i];
    }
    p->baseline_mean = sum / p->window_count;

    float var_sum = 0.0f;
    for (int i = 0; i < p->window_count; i++) {
        float d = p->window[i] - p->baseline_mean;
        var_sum += d * d;
    }
    p->baseline_var = (p->window_count > 1) ? (var_sum / (p->window_count - 1)) : 1.0f;

    // 5) Detect anomaly using z-score-like deviation
    float stddev = sqrtf(p->baseline_var);
    float z = (stddev > 1e-6f) ? fabsf(mag - p->baseline_mean) / stddev : 0.0f;

    return (z > ANOMALY_THRESHOLD);
}
```

