Below is a minimal working embedded-style sensor-processing pipeline for anomaly detection from accelerometer data. It is designed to be simple enough to run on a microcontroller, but the structure is realistic:

- sample accelerometer
- maintain a small sliding window
- compute lightweight features
- compare against a baseline
- flag anomalies

## Assumptions

- 3-axis accelerometer: `ax, ay, az`
- fixed sample rate, e.g. 50 Hz
- anomaly = motion pattern that deviates strongly from recent normal behavior
- no ML model, just a compact statistical detector

---

## Pipeline overview

1. **Acquire samples**
2. **Preprocess**
   - optional high-pass / gravity removal
   - compute magnitude
3. **Windowing**
   - keep last `N` samples
4. **Feature extraction**
   - mean magnitude
   - variance / energy
   - peak-to-peak
5. **Baseline tracking**
   - running mean and variance of features
6. **Anomaly decision**
   - z-score or threshold on deviation

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define BASELINE_ALPHA 0.05f   // smoothing for baseline update
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    float mag_window[WINDOW_SIZE];
    int index;
    int count;
} SlidingWindow;

typedef struct {
    float mean_mag;
    float var_mag;
} Features;

typedef struct {
    float baseline_mean;
    float baseline_var;
    bool initialized;
} Baseline;

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void window_init(SlidingWindow *w) {
    w->index = 0;
    w->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->mag_window[i] = 0.0f;
    }
}

static void window_push(SlidingWindow *w, float value) {
    w->mag_window[w->index] = value;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static Features compute_features(const SlidingWindow *w) {
    Features f = {0};

    if (w->count == 0) return f;

    float sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        sum += w->mag_window[i];
    }
    f.mean_mag = sum / w->count;

    float var_sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        float d = w->mag_window[i] - f.mean_mag;
        var_sum += d * d;
    }
    f.var_mag = var_sum / w->count;

    return f;
}

static void baseline_init(Baseline *b) {
    b->baseline_mean = 0.0f;
    b->baseline_var = 1.0f;   // avoid divide-by-zero
    b->initialized = false;
}

static void baseline_update(Baseline *b, Features f) {
    if (!b->initialized) {
        b->baseline_mean = f.mean_mag;
        b->baseline_var = f.var_mag > 1e-6f ? f.var_mag : 1.0f;
        b->initialized = true;
        return;
    }

    // Exponential moving average
    b->baseline_mean = (1.0f - BASELINE_ALPHA) * b->baseline_mean + BASELINE_ALPHA * f.mean_mag;
    b->baseline_var  = (1.0f - BASELINE_ALPHA) * b->baseline_var + BASELINE_ALPHA * f.var_mag;

    if (b->baseline_var < 1e-6f) {
        b->baseline_var = 1e-6f;
    }
}

static bool detect_anomaly(const Baseline *b, Features f) {
    float std = sqrtf(b->baseline_var);
    float z = fabsf(f.mean_mag - b->baseline_mean) / std;

    return z > ANOMALY_Z_THRESHOLD;
}

// Replace this with real sensor read
static AccelSample read_accelerometer_mock(int t) {
    AccelSample s;

    // Normal motion
    s.ax = 0.02f * sinf(0.1f * t);
    s.ay = 0.03f * cosf(0.07f * t);
    s.az = 1.0f + 0.01f * sinf(0.05f * t);

    // Inject anomaly
    if (t > 200 && t < 220) {
        s.ax += 2.5f;
        s.ay += 2.0f;
        s.az += 1.5f;
    }

    return s;
}

int main(void) {
    SlidingWindow window;
    Baseline baseline;

    window_init(&window);
    baseline_init(&baseline);

    for (int t = 0; t < 400; t++) {
        AccelSample sample = read_accelerometer_mock(t);
        float mag = accel_magnitude(sample);

        window_push(&window, mag);

        if (window.count < WINDOW_SIZE) {
            continue; // wait until window is full
        }

        Features f = compute_features(&window);

        // Update baseline only when not anomalous
        bool anomaly = false;
        if (baseline.initialized) {
            anomaly = detect_anomaly(&baseline, f);
        }

        if (!anomaly) {
            baseline_update(&baseline, f);
        } else {
            printf("Anomaly detected at t=%d: mean=%.3f var=%.3f baseline=%.3f\n",
                   t, f.mean_mag, f.var_mag, baseline.baseline_mean);
        }
    }

    return 0;
}
```

