Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or in a bare-metal C environment.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple motion feature: **magnitude**
- Maintains a **rolling baseline**
- Flags an anomaly when the current magnitude deviates too much from the baseline

This is not a full ML model—it's a lightweight threshold-based detector suitable for embedded systems.

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f   // tune this for your sensor/noise level

typedef struct {
    float buf[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} RollingWindow;

typedef struct {
    RollingWindow window;
} AnomalyDetector;

static void window_init(RollingWindow *w) {
    w->index = 0;
    w->count = 0;
    w->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buf[i] = 0.0f;
    }
}

static void window_add(RollingWindow *w, float value) {
    if (w->count < WINDOW_SIZE) {
        w->buf[w->index] = value;
        w->sum += value;
        w->count++;
    } else {
        w->sum -= w->buf[w->index];
        w->buf[w->index] = value;
        w->sum += value;
    }
    w->index = (w->index + 1) % WINDOW_SIZE;
}

static float window_mean(const RollingWindow *w) {
    if (w->count == 0) return 0.0f;
    return w->sum / (float)w->count;
}

static void detector_init(AnomalyDetector *d) {
    window_init(&d->window);
}

static float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

// Returns 1 if anomaly detected, 0 otherwise
static int detector_update(AnomalyDetector *d, float ax, float ay, float az) {
    float mag = accel_magnitude(ax, ay, az);
    float mean = window_mean(&d->window);

    // If enough history exists, compare against baseline
    int anomaly = 0;
    if (d->window.count >= WINDOW_SIZE / 2) {
        float diff = fabsf(mag - mean);
        if (diff > ANOMALY_THRESHOLD) {
            anomaly = 1;
        }
    }

    window_add(&d->window, mag);
    return anomaly;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector);

    // Example stream: mostly stable, then a spike
    float samples[][3] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.98f},
        {2.50f, 1.80f, 3.20f},   // anomaly
        {0.01f, 0.02f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);
    for (int i = 0; i < n; i++) {
        int anomaly = detector_update(
            &detector,
            samples[i][0],
            samples[i][1],
            samples[i][2]
        );

        printf("Sample %d: ax=%.2f ay=%.2f az=%.2f -> %s\n",
               i,
               samples[i][0], samples[i][1], samples[i][2],
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
