## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define BASELINE_SAMPLES 200
#define ANOMALY_THRESHOLD 3.0f

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    float samples[WINDOW_SIZE];
    int index;
    int count;
} SlidingWindow;

typedef struct {
    float mean;
    float variance;
} Features;

static void window_init(SlidingWindow *w) {
    w->index = 0;
    w->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->samples[i] = 0.0f;
    }
}

static void window_add(SlidingWindow *w, float value) {
    w->samples[w->index] = value;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static float compute_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static Features compute_features(const SlidingWindow *w) {
    Features f = {0};

    if (w->count == 0) return f;

    float sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        sum += w->samples[i];
    }
    f.mean = sum / w->count;

    float var_sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        float d = w->samples[i] - f.mean;
        var_sum += d * d;
    }
    f.variance = var_sum / w->count;

    return f;
}

static bool is_anomaly(const Features *f, float baseline_mean, float baseline_std) {
    float z = fabsf(f->mean - baseline_mean) / (baseline_std + 1e-6f);
    return (z > ANOMALY_THRESHOLD) || (f->variance > 2.0f * baseline_std * baseline_std);
}

int main(void) {
    SlidingWindow window;
    window_init(&window);

    // Simulated baseline training phase
    float baseline_sum = 0.0f;
    float baseline_sq_sum = 0.0f;
    int baseline_count = 0;

    // Replace this with real sensor reads
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.00f},
        {0.03f, 0.01f, 1.02f},
        {0.02f, 0.00f, 1.00f},
        {0.01f, 0.02f, 1.01f},
        // anomaly
        {2.50f, 1.80f, 0.20f},
        {2.40f, 1.70f, 0.10f},
        {0.01f, 0.01f, 1.00f}
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = compute_magnitude(stream[i]);
        window_add(&window, mag);

        // Build baseline from first samples
        if (baseline_count < BASELINE_SAMPLES && window.count == WINDOW_SIZE) {
            Features f = compute_features(&window);
            baseline_sum += f.mean;
            baseline_sq_sum += f.mean * f.mean;
            baseline_count++;
            continue;
        }

        if (baseline_count < WINDOW_SIZE) {
            continue;
        }

        float baseline_mean = baseline_sum / baseline_count;
        float baseline_var = (baseline_sq_sum / baseline_count) - (baseline_mean * baseline_mean);
        if (baseline_var < 1e-6f) baseline_var = 1e-6f;
        float baseline_std = sqrtf(baseline_var);

        Features f = compute_features(&window);

        if (is_anomaly(&f, baseline_mean, baseline_std)) {
            printf("Anomaly detected at sample %d: mean=%.3f var=%.3f\n",
                   i, f.mean, f.variance);
        } else {
            printf("Normal at sample %d: mean=%.3f var=%.3f\n",
                   i, f.mean, f.variance);
        }
    }

    return 0;
}
```

