## 2) Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define THRESHOLD_Z 3.0f

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sum_sq;
} RollingStats;

void stats_init(RollingStats *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sum_sq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buffer[i] = 0.0f;
    }
}

void stats_update(RollingStats *s, float x) {
    if (s->count < WINDOW_SIZE) {
        s->buffer[s->index] = x;
        s->sum += x;
        s->sum_sq += x * x;
        s->count++;
    } else {
        float old = s->buffer[s->index];
        s->buffer[s->index] = x;
        s->sum += x - old;
        s->sum_sq += x * x - old * old;
    }

    s->index = (s->index + 1) % WINDOW_SIZE;
}

float stats_mean(const RollingStats *s) {
    return (s->count > 0) ? (s->sum / s->count) : 0.0f;
}

float stats_stddev(const RollingStats *s) {
    if (s->count < 2) return 0.0f;

    float mean = stats_mean(s);
    float var = (s->sum_sq / s->count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

bool detect_anomaly(RollingStats *stats, float sample) {
    if (stats->count < WINDOW_SIZE) {
        stats_update(stats, sample);
        return false;  // warm-up phase
    }

    float mean = stats_mean(stats);
    float stddev = stats_stddev(stats);
    float z = (stddev > 1e-6f) ? fabsf(sample - mean) / stddev : 0.0f;

    bool anomaly = (z > THRESHOLD_Z);

    // Update after detection so current sample doesn't bias baseline too much
    stats_update(stats, sample);

    return anomaly;
}

int main(void) {
    RollingStats stats;
    stats_init(&stats);

    // Example stream: mostly stable, then one spike
    float samples[][3] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.00f},
        {0.02f, 0.00f, 0.99f},
        {0.01f, 0.02f, 1.01f},
        {0.00f, 0.01f, 1.00f},
        {0.50f, 0.40f, 2.20f},  // anomaly
        {0.01f, 0.02f, 0.99f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float ax = samples[i][0];
        float ay = samples[i][1];
        float az = samples[i][2];

        float mag = accel_magnitude(ax, ay, az);
        bool anomaly = detect_anomaly(&stats, mag);

        printf("sample %d: mag=%.3f anomaly=%s\n",
               i, mag, anomaly ? "YES" : "NO");
    }

    return 0;
}
```

