Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It is intentionally simple so it can run on a microcontroller or be adapted to one.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple motion magnitude
3. Maintains a rolling baseline
4. Flags an anomaly when the signal deviates too much from the baseline

---

## Minimal design

### Pipeline
- **Input:** `ax, ay, az`
- **Feature:** `magnitude = sqrt(ax² + ay² + az²)`
- **Baseline:** moving average over a small window
- **Anomaly rule:** if `abs(magnitude - baseline) > threshold`, raise anomaly

---

## C-like embedded implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define THRESHOLD   2.5f   // tune for your sensor units

typedef struct {
    float buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverage;

typedef struct {
    MovingAverage ma;
    float threshold;
} AnomalyDetector;

static void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

static float ma_update(MovingAverage *ma, float x) {
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
    }

    ma->buffer[ma->index] = x;
    ma->sum += x;
    ma->index = (ma->index + 1) % WINDOW_SIZE;

    return ma->sum / ma->count;
}

static void detector_init(AnomalyDetector *d, float threshold) {
    ma_init(&d->ma);
    d->threshold = threshold;
}

static bool detector_process(AnomalyDetector *d, float ax, float ay, float az) {
    float magnitude = sqrtf(ax * ax + ay * ay + az * az);
    float baseline = ma_update(&d->ma, magnitude);
    float deviation = fabsf(magnitude - baseline);

    // Don't trigger too early while the baseline is still warming up
    if (d->ma.count < WINDOW_SIZE) {
        return false;
    }

    return deviation > d->threshold;
}
```

