## What it does
- Reads 3-axis accelerometer samples
- Computes a simple magnitude-based feature
- Applies a moving average / variance estimate
- Flags an anomaly when the signal deviates too much from the recent baseline

## Assumptions
- You have a function to read the accelerometer: `read_accel(&x, &y, &z)`
- Samples arrive at a fixed rate
- You want a lightweight, no-ML baseline detector

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
   Configuration
   ========================= */
#define WINDOW_SIZE     32
#define ANOMALY_ZTHRESH  3.0f   // anomaly if |x - mean| > 3*stddev
#define EPSILON         1e-6f

/* =========================
   Sensor sample type
   ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

/* =========================
   Ring buffer state
   ========================= */
typedef struct {
    float buf[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum;
    float sumsq;
} stats_window_t;

static void stats_window_init(stats_window_t *w) {
    w->idx = 0;
    w->count = 0;
    w->sum = 0.0f;
    w->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buf[i] = 0.0f;
    }
}

static void stats_window_push(stats_window_t *w, float v) {
    if (w->count < WINDOW_SIZE) {
        w->buf[w->idx] = v;
        w->sum += v;
        w->sumsq += v * v;
        w->count++;
        w->idx = (w->idx + 1) % WINDOW_SIZE;
    } else {
        float old = w->buf[w->idx];
        w->sum -= old;
        w->sumsq -= old * old;

        w->buf[w->idx] = v;
        w->sum += v;
        w->sumsq += v * v;

        w->idx = (w->idx + 1) % WINDOW_SIZE;
    }
}

static void stats_window_get_mean_std(const stats_window_t *w, float *mean, float *stddev) {
    if (w->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float n = (float)w->count;
    float m = w->sum / n;
    float var = (w->sumsq / n) - (m * m);
    if (var < 0.0f) var = 0.0f;

    *mean = m;
    *stddev = sqrtf(var);
}

/* =========================
   Anomaly detector
   ========================= */
typedef struct {
    stats_window_t window;
    bool initialized;
} anomaly_detector_t;

static void anomaly_detector_init(anomaly_detector_t *d) {
    stats_window_init(&d->window);
    d->initialized = false;
}

/* Feature: acceleration magnitude */
static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* Returns true if anomaly detected */
static bool anomaly_detector_update(anomaly_detector_t *d, const accel_sample_t *sample) {
    float mag = accel_magnitude(sample);

    /* Warm-up phase: collect baseline first */
    if (d->window.count < WINDOW_SIZE) {
        stats_window_push(&d->window, mag);
        return false;
    }

    float mean, stddev;
    stats_window_get_mean_std(&d->window, &mean, &stddev);

    bool anomaly = false;
    float threshold = ANOMALY_ZTHRESH * (stddev + EPSILON);

    if (fabsf(mag - mean) > threshold) {
        anomaly = true;
    }

    /* Update baseline after decision */
    stats_window_push(&d->window, mag);

    return anomaly;
}

/* =========================
   Hardware abstraction stub
   Replace with real sensor driver
   ========================= */
bool read_accel(accel_sample_t *out) {
    /* TODO: Replace with real accelerometer read */
    /* Example dummy data */
    static int i = 0;
    i++;

    out->x = 0.01f;
    out->y = 0.02f;
    out->z = 1.00f;

    /* Inject a fake anomaly every 200 samples */
    if (i % 200 == 0) {
        out->x = 2.5f;
        out->y = 2.0f;
        out->z = 3.0f;
    }

    return true;
}

/* =========================
   Main processing loop
   ========================= */
int main(void) {
    anomaly_detector_t detector;
    anomaly_detector_init(&detector);

    while (1) {
        accel_sample_t sample;

        if (read_accel(&sample)) {
            bool anomaly = anomaly_detector_update(&detector, &sample);

            if (anomaly) {
                /* Handle anomaly:
                   - raise event
                   - log sample
                   - trigger alert
                */
                // e.g. gpio_set(ALERT_PIN, 1);
            }
        }

        /* TODO: delay to match sample rate, e.g. 50Hz or 100Hz */
    }

    return 0;
}
