Below is a **minimal working embedded-style sensor-processing pipeline** for **anomaly detection from accelerometer data**. It is intentionally simple so it can run on small devices.

## What it does
- Reads 3-axis accelerometer samples `(ax, ay, az)`
- Maintains a small sliding window
- Computes a few lightweight features:
  - mean magnitude
  - variance of magnitude
  - peak-to-peak range
- Flags an anomaly if the features exceed simple thresholds

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    AccelSample buffer[WINDOW_SIZE];
    int index;
    int count;
} SampleWindow;

typedef struct {
    float mean_mag;
    float var_mag;
    float peak_to_peak;
} Features;

void window_init(SampleWindow *w) {
    w->index = 0;
    w->count = 0;
}

void window_push(SampleWindow *w, AccelSample s) {
    w->buffer[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static float magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

Features extract_features(SampleWindow *w) {
    Features f = {0};

    if (w->count == 0) return f;

    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float minv = 1e9f, maxv = -1e9f;

    for (int i = 0; i < w->count; i++) {
        mags[i] = magnitude(w->buffer[i]);
        sum += mags[i];
        if (mags[i] < minv) minv = mags[i];
        if (mags[i] > maxv) maxv = mags[i];
    }

    f.mean_mag = sum / w->count;

    float var_sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        float d = mags[i] - f.mean_mag;
        var_sum += d * d;
    }
    f.var_mag = var_sum / w->count;
    f.peak_to_peak = maxv - minv;

    return f;
}

int detect_anomaly(Features f) {
    // Simple heuristic thresholds; tune for your device/use case
    if (f.mean_mag > 2.0f) return 1;
    if (f.var_mag > 0.5f) return 1;
    if (f.peak_to_peak > 1.5f) return 1;
    return 0;
}

int main(void) {
    SampleWindow window;
    window_init(&window);

    // Example stream of accelerometer samples
    AccelSample data[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.50f, 0.40f, 1.80f}, // possible anomaly
        {0.60f, 0.50f, 1.90f},
        {0.02f, 0.01f, 1.00f},
    };

    int n = sizeof(data) / sizeof(data[0]);

    for (int i = 0; i < n; i++) {
        window_push(&window, data[i]);

        if (window.count >= WINDOW_SIZE / 2) {
            Features f = extract_features(&window);
            int anomaly = detect_anomaly(f);

            printf("Sample %d: mean=%.3f var=%.3f p2p=%.3f -> %s\n",
                   i, f.mean_mag, f.var_mag, f.peak_to_peak,
                   anomaly ? "ANOMALY" : "normal");
        }
    }

    return 0;
}
