Below is a **minimal working embedded-style sensor-processing pipeline** for **anomaly detection from accelerometer data**. It is designed to be simple enough to run on a microcontroller or in a small firmware loop.

## What it does
- Reads 3-axis accelerometer samples
- Maintains a small sliding window
- Computes a few lightweight features
- Compares them to a baseline
- Flags anomalies when values deviate too much

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define AXES 3

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    AccelSample samples[WINDOW_SIZE];
    int index;
    int count;
    float baseline_mag;
    float baseline_var;
} SensorPipeline;

static float vector_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static float mean_magnitude(SensorPipeline *p) {
    float sum = 0.0f;
    for (int i = 0; i < p->count; i++) {
        sum += vector_magnitude(p->samples[i]);
    }
    return (p->count > 0) ? (sum / p->count) : 0.0f;
}

static float variance_magnitude(SensorPipeline *p, float mean) {
    float sum = 0.0f;
    for (int i = 0; i < p->count; i++) {
        float m = vector_magnitude(p->samples[i]);
        float d = m - mean;
        sum += d * d;
    }
    return (p->count > 1) ? (sum / (p->count - 1)) : 0.0f;
}

void pipeline_init(SensorPipeline *p) {
    p->index = 0;
    p->count = 0;
    p->baseline_mag = 0.0f;
    p->baseline_var = 0.0f;
}

void pipeline_update_baseline(SensorPipeline *p) {
    float mean = mean_magnitude(p);
    float var = variance_magnitude(p, mean);
    p->baseline_mag = mean;
    p->baseline_var = var;
}

int pipeline_detect_anomaly(SensorPipeline *p, AccelSample s) {
    float mag = vector_magnitude(s);

    // Simple threshold based on baseline
    float mag_diff = fabsf(mag - p->baseline_mag);
    float stddev = sqrtf(p->baseline_var + 1e-6f);

    // Tune these thresholds for your sensor/application
    if (mag_diff > 3.0f * stddev) {
        return 1; // anomaly
    }
    return 0;
}

void pipeline_add_sample(SensorPipeline *p, AccelSample s) {
    p->samples[p->index] = s;
    p->index = (p->index + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }
}

int main(void) {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    // Example: collect baseline samples
    AccelSample baseline_data[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, -0.01f, 1.01f},
        {0.01f, 0.00f, 1.00f},
        {0.00f, 0.02f, 1.00f},
        {0.01f, -0.02f, 0.98f},
        {0.00f, 0.01f, 1.02f},
        {0.02f, 0.00f, 1.00f},
    };

    int baseline_n = sizeof(baseline_data) / sizeof(baseline_data[0]);
    for (int i = 0; i < baseline_n; i++) {
        pipeline_add_sample(&pipeline, baseline_data[i]);
    }

    pipeline_update_baseline(&pipeline);

    printf("Baseline magnitude: %.4f\n", pipeline.baseline_mag);
    printf("Baseline variance:   %.6f\n", pipeline.baseline_var);

    // Incoming stream
    AccelSample stream[] = {
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.01f},
        {0.50f, 0.40f, 1.80f}, // anomaly
        {0.00f, 0.01f, 1.00f},
        {0.02f, -0.01f, 0.99f},
    };

    int stream_n = sizeof(stream) / sizeof(stream[0]);
    for (int i = 0; i < stream_n; i++) {
        int anomaly = pipeline_detect_anomaly(&pipeline, stream[i]);
        printf("Sample %d: (%.2f, %.2f, %.2f) -> %s\n",
               i,
               stream[i].x, stream[i].y, stream[i].z,
               anomaly ? "ANOMALY" : "normal");

        pipeline_add_sample(&pipeline, stream[i]);
    }

    return 0;
}
```

---

## How it works
1. **Baseline phase**
   - Collect a few normal samples.
   - Compute average magnitude and variance.

2. **Detection phase**
   - For each new sample, compute its magnitude.
   - Compare it against the baseline.
   - If the difference is greater than `3 × stddev`, flag an anomaly.

---

## Why this is embedded-friendly
- No dynamic memory
- Small fixed-size buffer
- O(N) per update with tiny N
- Uses only basic math

