Below is a minimal working embedded-style sensor-processing pipeline for accelerometer anomaly detection. It is designed to be simple enough to run on a microcontroller or in a small embedded C project.

## What it does
- Reads 3-axis accelerometer samples
- Computes signal magnitude
- Maintains a short moving average
- Flags an anomaly when the current magnitude deviates too much from the baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f   // tune for your sensor/noise level

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} moving_avg_t;

static void moving_avg_init(moving_avg_t *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

static float moving_avg_update(moving_avg_t *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / (float)ma->count;
}

static float accel_magnitude(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static bool is_anomaly(float magnitude, float baseline) {
    return fabsf(magnitude - baseline) > ANOMALY_THRESHOLD;
}

int main(void) {
    moving_avg_t baseline_filter;
    moving_avg_init(&baseline_filter);

    // Example stream of accelerometer samples
    accel_sample_t samples[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.03f, 0.01f, 1.00f},
        {3.00f, 2.50f, 4.00f},   // anomaly
        {0.01f, 0.02f, 1.00f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(samples[i]);
        float baseline = moving_avg_update(&baseline_filter, mag);

        bool anomaly = false;

        // Avoid false detection during initial warm-up
        if (baseline_filter.count >= WINDOW_SIZE / 2) {
            anomaly = is_anomaly(mag, baseline);
        }

        printf("Sample %d: mag=%.3f baseline=%.3f %s\n",
               i, mag, baseline, anomaly ? "ANOMALY" : "OK");
    }

    return 0;
}
```

---

## How it works
1. **Magnitude calculation**  
   Converts 3-axis acceleration into a single scalar:
   \[
   \sqrt{x^2 + y^2 + z^2}
   \]

2. **Moving average baseline**  
   Tracks the recent “normal” acceleration level.

3. **Anomaly detection**  
   If the current magnitude differs from the baseline by more than `ANOMALY_THRESHOLD`, it is flagged.

---

