Below is a minimal working embedded-style pipeline for detecting anomalies from accelerometer data. It is designed to be simple enough to run on a microcontroller or in a small firmware task.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple magnitude-based feature
- Maintains a rolling baseline
- Flags an anomaly when the current sample deviates too much from the baseline

---

## Minimal pipeline

### 1) Data model
```c
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;
```

### 2) Feature extraction
Use acceleration magnitude:
```c
#include <math.h>

static inline float accel_magnitude(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}
```

### 3) Rolling baseline and anomaly detector
This version uses a moving average and moving variance over a small window.

```c
#include <stdbool.h>
#include <string.h>

#define WINDOW_SIZE 16
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float window[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sumsq;
} detector_t;

void detector_init(detector_t *d) {
    memset(d, 0, sizeof(*d));
}

static void detector_push(detector_t *d, float value) {
    if (d->count < WINDOW_SIZE) {
        d->window[d->index] = value;
        d->sum += value;
        d->sumsq += value * value;
        d->count++;
    } else {
        float old = d->window[d->index];
        d->window[d->index] = value;
        d->sum += value - old;
        d->sumsq += value * value - old * old;
    }

    d->index = (d->index + 1) % WINDOW_SIZE;
}

static void detector_stats(detector_t *d, float *mean, float *stddev) {
    if (d->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = d->sum / d->count;
    float var = (d->sumsq / d->count) - (*mean * *mean);
    if (var < 0.0f) var = 0.0f;
    *stddev = sqrtf(var);
}

bool detector_update(detector_t *d, accel_sample_t sample) {
    float mag = accel_magnitude(sample);

    float mean, stddev;
    detector_stats(d, &mean, &stddev);

    bool anomaly = false;
    if (d->count >= WINDOW_SIZE / 2 && stddev > 0.0001f) {
        float z = fabsf(mag - mean) / stddev;
        anomaly = (z > ANOMALY_Z_THRESHOLD);
    }

    detector_push(d, mag);
    return anomaly;
}
