}

static void write_actuator(uint8_t state) {
    // TODO: set GPIO / PWM / relay / valve
    (void)state;
}

/* Optional: simple validity check */
static bool sensor_value_valid(uint16_t v) {
    return (v >= SENSOR_MIN_VALID && v <= SENSOR_MAX_VALID);
}

/* ---------------- Filtering ---------------- */

/*
 * Exponential moving average:
 *   filtered = filtered + (raw - filtered) / 2^FILTER_SHIFT
 *
 * Very cheap for embedded CPUs: uses only shifts and integer math.
 */
static uint16_t ema_filter(uint16_t raw, uint16_t prev_filtered) {
    int32_t delta = (int32_t)raw - (int32_t)prev_filtered;
    return (uint16_t)(prev_filtered + (delta >> FILTER_SHIFT));
}

/* ---------------- Control Logic ---------------- */

/*
 * Hysteresis prevents actuator chatter:
 * - turn ON when filtered >= THRESHOLD_HIGH
 * - turn OFF when filtered <= THRESHOLD_LOW
 */
static bool decide_actuator(uint16_t filtered, bool current_state) {
    if (!current_state && filtered >= THRESHOLD_HIGH) {
        return true;
    }
    if (current_state && filtered <= THRESHOLD_LOW) {
        return false;
    }
    return current_state;
}

/* ---------------- Main Processing Step ---------------- */

void edge_control_init(EdgeControlState *st) {
    if (!st) return;
    st->filtered = 0;
    st->actuator_on = false;
    write_actuator(ACTUATOR_OFF);
}

/*
 * Call this periodically, e.g. every 10 ms / 100 ms from a timer tick.
 */
void edge_control_step(EdgeControlState *st) {
    if (!st) return;

    uint16_t raw = read_sensor_raw();

    if (!sensor_value_valid(raw)) {
        // Fail-safe behavior: keep previous filtered value,
        // optionally turn actuator off on invalid input.
        write_actuator(st->actuator_on ? ACTUATOR_ON : ACTUATOR_OFF);
        return;
    }

    if (st->filtered == 0) {
        // Initialize filter on first sample to avoid startup lag
        st->filtered = raw;
    } else {
        st->filtered = ema_filter(raw, st->filtered);
    }

    st->actuator_on = decide_actuator(st->filtered, st->actuator_on);
    write_actuator(st->actuator_on ? ACTUATOR_ON : ACTUATOR_OFF);
}

