    return (uint16_t)(prev_filtered + (diff >> EMA_SHIFT));
}

/* ---------------- Control Logic ---------------- */

static actuator_state_t update_actuator_state(uint16_t filtered,
                                              actuator_state_t current)
{
    /*
     * Hysteresis:
     * - Turn ON only when above HIGH_THRESHOLD
     * - Turn OFF only when below LOW_THRESHOLD
     * This prevents rapid toggling near the threshold.
     */
    if (current == ACTUATOR_OFF) {
        if (filtered >= HIGH_THRESHOLD) {
            return ACTUATOR_ON;
        }
    } else {
        if (filtered <= LOW_THRESHOLD) {
            return ACTUATOR_OFF;
        }
    }
    return current;
}

/* ---------------- Main Loop ---------------- */

int main(void)
{
    uint16_t raw = 0;
    uint16_t filtered = 0;
    actuator_state_t actuator = ACTUATOR_OFF;

    /* Optional: initialize hardware here */
    // init_adc();
