        raw = read_sensor_raw();

        /* Clamp raw input if needed */
        if (raw > MAX_SENSOR_VALUE) {
            raw = MAX_SENSOR_VALUE;
        }

        /* Filter sensor reading */
        filtered = ema_filter(raw, filtered);

        /* Update actuator state */
        actuator = update_actuator_state(filtered, actuator);

        /* Apply actuator output */
        set_actuator(actuator == ACTUATOR_ON);

        /* Optional: sleep or wait for next sampling tick */
