- reads sensor data,
- filters it with a lightweight exponential moving average,
- applies basic threshold logic with hysteresis,
- drives actuators safely,
- avoids dynamic allocation,
- uses fixed-size buffers and simple state.

You can adapt the I/O functions to your hardware platform.

```c
#include <stdint.h>
#include <stdbool.h>

/* ---------------- Configuration ---------------- */

#define SENSOR_COUNT        4
#define ACTUATOR_COUNT      2

#define EMA_ALPHA_NUM       1   // alpha = 1/8
#define EMA_ALPHA_DEN       8

#define TEMP_HIGH_ON        750  // example: 75.0 C if scaled by 10
#define TEMP_HIGH_OFF       700
#define HUMID_LOW_ON        300
#define HUMID_LOW_OFF       350

#define ACTUATOR_COOLDOWN_MS 500

/* ---------------- Hardware abstraction ----------------
   Replace these with platform-specific implementations.
*/

extern uint16_t hw_read_sensor(uint8_t id);
extern void     hw_set_actuator(uint8_t id, bool on);
extern uint32_t hw_millis(void);

/* ---------------- State ---------------- */

typedef struct {
    uint16_t filtered;
    bool initialized;
} EmaFilter;

typedef struct {
    bool on;
    uint32_t last_change_ms;
} ActuatorState;

static EmaFilter sensor_filters[SENSOR_COUNT];
static ActuatorState actuators[ACTUATOR_COUNT];

/* ---------------- Filtering ---------------- */

static uint16_t ema_update(EmaFilter *f, uint16_t sample)
{
    if (!f->initialized) {
        f->filtered = sample;
        f->initialized = true;
        return sample;
    }

    // filtered = filtered + alpha * (sample - filtered)
    // alpha = 1/8 implemented with shift for low CPU cost
    int32_t diff = (int32_t)sample - (int32_t)f->filtered;
    f->filtered = (uint16_t)(f->filtered + (diff * EMA_ALPHA_NUM) / EMA_ALPHA_DEN);
    return f->filtered;
}

/* ---------------- Actuator control ---------------- */

static void set_actuator_safe(uint8_t id, bool on)
{
    if (id >= ACTUATOR_COUNT) return;

    uint32_t now = hw_millis();
    ActuatorState *a = &actuators[id];

    // Enforce cooldown to reduce chatter and wear
    if ((now - a->last_change_ms) < ACTUATOR_COOLDOWN_MS && a->on != on) {
        return;
    }

    if (a->on != on) {
        a->on = on;
        a->last_change_ms = now;
        hw_set_actuator(id, on);
    }
}

/* ---------------- Control logic ---------------- */

static void process_sensors_and_actuators(void)
{
    // Example mapping:
    // sensor 0 -> temperature control actuator 0
    // sensor 1 -> humidity control actuator 1

    uint16_t temp  = ema_update(&sensor_filters[0], hw_read_sensor(0));
    uint16_t humid = ema_update(&sensor_filters[1], hw_read_sensor(1));

    // Temperature hysteresis
    if (!actuators[0].on && temp >= TEMP_HIGH_ON) {
        set_actuator_safe(0, true);
    } else if (actuators[0].on && temp <= TEMP_HIGH_OFF) {
        set_actuator_safe(0, false);
    }

    // Humidity hysteresis
    if (!actuators[1].on && humid <= HUMID_LOW_ON) {
        set_actuator_safe(1, true);
    } else if (actuators[1].on && humid >= HUMID_LOW_OFF) {
        set_actuator_safe(1, false);
    }
}

/* ---------------- Initialization ---------------- */

static void system_init(void)
{
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensor_filters[i].initialized = false;
        sensor_filters[i].filtered = 0;
    }

    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        actuators[i].on = false;
        actuators[i].last_change_ms = 0;
        hw_set_actuator(i, false);
    }
}

/* ---------------- Main loop ---------------- */

int main(void)
{
    system_init();

    while (1) {
        process_sensors_and_actuators();

        // Optional: insert low-power sleep / wait-for-interrupt here
        // platform_sleep_ms(50);
    }

    return 0;
}
```

