    // Replace with actual ADC read
    static float x = 25.0f;
    x += 0.7f; // dummy changing value
    return x;
}

float moving_average(float new_value) {
    static float buffer[WINDOW_SIZE] = {0};
    static int index = 0;
    static int count = 0;
    static float sum = 0;

    sum -= buffer[index];
    buffer[index] = new_value;
    sum += new_value;

    index = (index + 1) % WINDOW_SIZE;
    if (count < WINDOW_SIZE) count++;

    return sum / count;
}

void actuator_on(void) {
