```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    #info {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div id="info">
    Controls: ← → move, Space / ↑ jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
      if (["ArrowUp", "Space"].includes(e.code)) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    // --- World ---
    const world = {
      width: 3200,
      height: 900
    };

    const gravity = 0.7;

    const platforms = [
      { x: 0, y: 820, w: 3200, h: 80 },     // ground
      { x: 250, y: 700, w: 180, h: 20 },
      { x: 520, y: 620, w: 180, h: 20 },
      { x: 820, y: 560, w: 220, h: 20 },
      { x: 1180, y: 650, w: 220, h: 20 },
      { x: 1500, y: 580, w: 180, h: 20 },
      { x: 1800, y: 500, w: 220, h: 20 },
      { x: 2140, y: 620, w: 220, h: 20 },
      { x: 2500, y: 560, w: 220, h: 20 },
      { x: 2850, y: 650, w: 180, h: 20 }
    ];

    // --- Generate simple sprite sheet for animation ---
    function createSpriteSheet() {
      const sheet = document.createElement("canvas");
      sheet.width = 256;
      sheet.height = 64;
      const sctx = sheet.getContext("2d");

      // 4 frames, 64x64 each
      for (let i = 0; i < 4; i++) {
        const x = i * 64;
        // body
        sctx.fillStyle = "#ffcc66";
        sctx.fillRect(x + 22, 18, 20, 26);
        // head
        sctx.fillStyle = "#f2c29b";
        sctx.fillRect(x + 20, 6, 24, 18);
        // eyes
        sctx.fillStyle = "#222";
        sctx.fillRect(x + 26, 12, 3, 3);
        sctx.fillRect(x + 35, 12, 3, 3);

        // arms / legs animation
        sctx.strokeStyle = "#333";
        sctx.lineWidth = 4;
        sctx.lineCap = "round";

        // arms
        sctx.beginPath();
        sctx.moveTo(x + 22, 25);
        sctx.lineTo(x + 12, 34 + (i % 2 === 0 ? 2 : -2));
        sctx.stroke();

        sctx.beginPath();
        sctx.moveTo(x + 42, 25);
        sctx.lineTo(x + 52, 34 + (i % 2 === 0 ? -2 : 2));
        sctx.stroke();

        // legs
        sctx.beginPath();
        sctx.moveTo(x + 26, 44);
        sctx.lineTo(x + 18 + (i % 2 === 0 ? 2 : -2), 58);
        sctx.stroke();

        sctx.beginPath();
        sctx.moveTo(x + 38, 44);
        sctx.lineTo(x + 46 + (i % 2 === 0 ? -2 : 2), 58);
        sctx.stroke();
      }
      return sheet;
    }

    const spriteSheet = createSpriteSheet();

    // --- Player ---
    const player = {
      x: 100,
      y: 700,
      w: 40,
      h: 58,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 6,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0
    };

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // X movement
      entity.x += entity.vx;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vx > 0) {
            entity.x = p.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Y movement
      entity.y += entity.vy;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Game Loop ---
    let lastTime = 0;

    function update(dt) {
      // Horizontal input
      if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["ArrowRight"] || keys["KeyD"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Friction
      player.vx *= player.onGround ? 0.82 : 0.95;

      // Clamp speed
      player.vx = Math.max(-player.maxSpeed, Math.min(player.maxSpeed, player.vx));

      // Jump
      if ((keys["Space"] || keys["ArrowUp"] || keys["KeyW"]) && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += gravity;
      if (player.vy > 18) player.vy = 18;

      // Collisions
      resolveCollisions(player, platforms);

      // Keep within world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 700;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.frameTimer += dt;
        if (player.frameTimer > 0.12) {
          player.frame = (player.frame + 1) % 4;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
        player.frameTimer = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b3f2f";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
      ctx.fillStyle = "#6b5a45";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawPlayer() {
      const sx = player.frame * 64;
      const sy = 0;
      const dx = player.x - camera.x;
      const dy = player.y - camera.y;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteSheet, sx, sy, 64, 64, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(spriteSheet, sx, sy, 64, 64, dx, dy, player.w, player.h);
      }
      ctx.restore();
    }

    function drawBackground() {
      // Simple parallax hills
      ctx.fillStyle = "#8fd18f";
      for (let i = 0; i < 12; i++) {
        const hillX = (i * 300 - camera.x * 0.3) % (canvas.width + 300) - 150;
        ctx.beginPath();
        ctx.arc(hillX, canvas.height - 40, 120, 0, Math.PI * 2);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 8; i++) {
        const cx = (i * 420 - camera.x * 0.15) % (canvas.width + 420) - 100;
        const cy = 80 + (i % 3) * 40;
        ctx.beginPath();
        ctx.arc(cx, cy, 24, 0, Math.PI * 2);
        ctx.arc(cx + 26, cy + 8, 30, 0, Math.PI * 2);
        ctx.arc(cx + 52, cy, 22, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Player
      drawPlayer();

      // Debug-ish HUD
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.fillRect(10, canvas.height - 50, 260, 34);
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(0)} y: ${player.y.toFixed(0)} vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 18, canvas.height - 28);
    }

    function loop(timestamp) {
      const dt = Math.min(0.033, (timestamp - lastTime) / 1000 || 0);
      lastTime = timestamp;

      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
