## Full code

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      left: 12px;
      top: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud" id="hud">Coins: 0</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const hud = document.getElementById("hud");

    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    window.addEventListener("resize", () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    });

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // -----------------------------
    // Game constants
    // -----------------------------
    const TILE = 48;
    const GRAVITY = 0.7;
    const MOVE_SPEED = 0.6;
    const MAX_SPEED_X = 6;
    const JUMP_SPEED = -14;
    const FRICTION = 0.82;

    // -----------------------------
    // Level map
    // # = solid block
    // C = coin
    // G = goal
    // P = player spawn
    // -----------------------------
    const levelMap = [
      "................................................................",
      "................................................................",
      "................................................................",
      "................................................................",
      "....................C...........................................",
      "..............###.................C.............................",
      "......................................................###.......G",
      "...........C..................#######...........................#",
      "......#######...................................................#",
      "...........................................C....................#",
      "....................###.........................................#",
      "....P.............................................####..........#",
      "##############################..##################################",
    ];

    const world = {
      tiles: [],
      coins: [],
      goal: null,
      width: levelMap[0].length * TILE,
      height: levelMap.length * TILE,
    };

    let playerSpawn = { x: 100, y: 100 };

    // Build world
    for (let y = 0; y < levelMap.length; y++) {
      for (let x = 0; x < levelMap[y].length; x++) {
        const ch = levelMap[y][x];
        const px = x * TILE;
        const py = y * TILE;

        if (ch === "#") {
          world.tiles.push({ x: px, y: py, w: TILE, h: TILE });
        } else if (ch === "C") {
          world.coins.push({
            x: px + TILE / 2,
            y: py + TILE / 2,
            r: 12,
            collected: false,
            anim: 0
          });
        } else if (ch === "G") {
          world.goal = { x: px, y: py, w: TILE, h: TILE * 2 };
        } else if (ch === "P") {
          playerSpawn = { x: px, y: py - 20 };
        }
      }
    }

    // -----------------------------
    // Player
    // -----------------------------
    const player = {
      x: playerSpawn.x,
      y: playerSpawn.y,
      w: 34,
      h: 44,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0,
      coins: 0,
      won: false
    };

    // -----------------------------
    // Collision helpers
    // -----------------------------
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveTileCollision(entity, tile) {
      const overlapX = Math.min(entity.x + entity.w - tile.x, tile.x + tile.w - entity.x);
      const overlapY = Math.min(entity.y + entity.h - tile.y, tile.y + tile.h - entity.y);

      if (overlapX < overlapY) {
        // Resolve horizontally
        if (entity.x < tile.x) entity.x = tile.x - entity.w;
        else entity.x = tile.x + tile.w;

        entity.vx = 0;
      } else {
        // Resolve vertically
        if (entity.y < tile.y) {
          entity.y = tile.y - entity.h;
          entity.vy = 0;
          entity.onGround = true;
        } else {
          entity.y = tile.y + tile.h;
          entity.vy = 0;
        }
      }
    }

    function getNearbyTiles(entity) {
      const tiles = [];
      const left = Math.floor(entity.x / TILE) - 1;
      const right = Math.floor((entity.x + entity.w) / TILE) + 1;
      const top = Math.floor(entity.y / TILE) - 1;
      const bottom = Math.floor((entity.y + entity.h) / TILE) + 1;

      for (const tile of world.tiles) {
        const tx = tile.x / TILE;
        const ty = tile.y / TILE;
        if (tx >= left && tx <= right && ty >= top && ty <= bottom) {
          tiles.push(tile);
        }
      }
      return tiles;
    }

    // -----------------------------
    // Game loop
    // -----------------------------
    let camera = { x: 0, y: 0 };

    function update() {
      if (!player.won) {
        // Input
        let moving = false;

        if (keys["a"] || keys["arrowleft"]) {
          player.vx -= MOVE_SPEED;
          player.facing = -1;
          moving = true;
        }
        if (keys["d"] || keys["arrowright"]) {
          player.vx += MOVE_SPEED;
          player.facing = 1;
          moving = true;
        }

        // Clamp horizontal velocity
        player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

        // Jump
        if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
          player.vy = JUMP_SPEED;
          player.onGround = false;
        }

        // Physics
        player.vy += GRAVITY;

        // Apply friction when on ground and no movement input
        if (player.onGround && !moving) {
          player.vx *= FRICTION;
          if (Math.abs(player.vx) < 0.05) player.vx = 0;
        }

        // Move X and collide
        player.x += player.vx;
        for (const tile of getNearbyTiles(player)) {
          if (rectsOverlap(player, tile)) {
            resolveTileCollision(player, tile);
          }
        }

        // Move Y and collide
        player.y += player.vy;
        player.onGround = false;
        for (const tile of getNearbyTiles(player)) {
          if (rectsOverlap(player, tile)) {
            resolveTileCollision(player, tile);
          }
        }

        // Keep player in bounds
        if (player.x < 0) player.x = 0;
        if (player.x + player.w > world.width) player.x = world.width - player.w;
        if (player.y > world.height + 300) {
          // reset if fallen off map
          player.x = playerSpawn.x;
          player.y = playerSpawn.y;
          player.vx = 0;
          player.vy = 0;
        }

        // Coin collection
        for (const coin of world.coins) {
          if (!coin.collected) {
            const coinBox = { x: coin.x - coin.r, y: coin.y - coin.r, w: coin.r * 2, h: coin.r * 2 };
            if (rectsOverlap(player, coinBox)) {
              coin.collected = true;
              player.coins++;
              hud.textContent = `Coins: ${player.coins}`;
            }
            coin.anim += 0.12;
          }
        }

        // Goal
        if (world.goal && rectsOverlap(player, world.goal)) {
          player.won = true;
        }

        // Animation
        if (Math.abs(player.vx) > 0.5 && player.onGround) {
          player.frameTimer++;
          if (player.frameTimer > 8) {
            player.frame = (player.frame + 1) % 4;
            player.frameTimer = 0;
          }
        } else {
          player.frame = 0;
          player.frameTimer = 0;
        }
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    // -----------------------------
    // Drawing
    // -----------------------------
    function drawBackground() {
      // Parallax-like clouds
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let i = 0; i < 8; i++) {
        const x = ((i * 260) - camera.x * 0.2) % (canvas.width + 300) - 150;
        const y = 60 + (i % 3) * 70;
        drawCloud(x, y, 1 + (i % 2) * 0.3);
      }
    }

    function drawCloud(x, y, scale) {
      ctx.save();
      ctx.globalAlpha = 0.45;
      ctx.fillStyle = "white";
      ctx.beginPath();
      ctx.arc(x, y, 22 * scale, 0, Math.PI * 2);
      ctx.arc(x + 25 * scale, y - 10 * scale, 28 * scale, 0, Math.PI * 2);
      ctx.arc(x + 55 * scale, y, 22 * scale, 0, Math.PI * 2);
      ctx.arc(x + 30 * scale, y + 10 * scale, 24 * scale, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function drawTile(tile) {
      ctx.fillStyle = "#5b3a29";
      ctx.fillRect(tile.x - camera.x, tile.y - camera.y, tile.w, tile.h);

      ctx.fillStyle = "#7d5a4f";
      ctx.fillRect(tile.x - camera.x + 4, tile.y - camera.y + 4, tile.w - 8, tile.h - 8);
    }

    function drawCoin(coin) {
      if (coin.collected) return;
      const bob = Math.sin(coin.anim) * 4;
      const scale = 1 + Math.sin(coin.anim * 2) * 0.08;

      ctx.save();
      ctx.translate(coin.x - camera.x, coin.y - camera.y + bob);
      ctx.scale(scale, 1);

      ctx.fillStyle = "#ffd700";
      ctx.beginPath();
      ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#c99a00";
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.fillStyle = "#fff3a0";
      ctx.beginPath();
      ctx.arc(-4, -4, 4, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawGoal(goal) {
      if (!goal) return;
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(goal.x - camera.x, goal.y - camera.y, goal.w, goal.h);

      ctx.fillStyle = "#1f8f4d";
      ctx.fillRect(goal.x - camera.x + 8, goal.y - camera.y + 8, goal.w - 16, goal.h - 16);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Body animation colors
      const colors = ["#ff5c5c", "#ff7a7a", "#ff9a9a", "#ff7a7a"];
      const bodyColor = colors[player.frame];

      ctx.save();

      // Flip horizontally if facing left
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-(x + player.w / 2), -(y + player.h / 2));

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 4, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Head
      ctx.fillStyle = "#ffd2b3";
      ctx.fillRect(x + 8, y + 4, 18, 14);

      // Body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(x + 6, y + 18, 22, 18);

      // Legs
      ctx.fillStyle = "#2d2d2d";
      ctx.fillRect(x + 8, y + 36, 7, 8);
      ctx.fillRect(x + 19, y + 36, 7, 8);

      // Eye
      ctx.fillStyle = "#222";
      ctx.fillRect(x + 20, y + 9, 3, 3);

      // Outline
      ctx.strokeStyle = "#000";
      ctx.lineWidth = 2;
      ctx.strokeRect(x + 6, y + 18, 22, 18);
      ctx.strokeRect(x + 8, y + 4, 18, 14);

      ctx.restore();
    }

    function drawWinScreen() {
      ctx.save();
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.font = "bold 48px sans-serif";
      ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2 - 20);

      ctx.font = "24px sans-serif";
      ctx.fillText(`Coins collected: ${player.coins}`, canvas.width / 2, canvas.height / 2 + 25);
      ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 60);
      ctx.restore();
    }

    function render() {
      drawBackground();

      // Draw tiles
      for (const tile of world.tiles) drawTile(tile);

      // Draw coins
      for (const coin of world.coins) drawCoin(coin);

      // Draw goal
      drawGoal(world.goal);

      // Draw player
      drawPlayer();

      if (player.won) drawWinScreen();
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

