```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud" id="hud">Coins: 0</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const hud = document.getElementById("hud");

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const world = {
      gravity: 0.55,
      friction: 0.82,
      airFriction: 0.98,
      width: 3000,
      height: 540
    };

    const player = {
      x: 100,
      y: 300,
      w: 40,
      h: 52,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12.5,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      coins: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 3000, h: 40 },
      { x: 200, y: 410, w: 180, h: 20 },
      { x: 460, y: 360, w: 180, h: 20 },
      { x: 720, y: 300, w: 180, h: 20 },
      { x: 980, y: 250, w: 180, h: 20 },
      { x: 1280, y: 340, w: 220, h: 20 },
      { x: 1600, y: 280, w: 220, h: 20 },
      { x: 1950, y: 220, w: 220, h: 20 },
      { x: 2280, y: 320, w: 220, h: 20 },
      { x: 2600, y: 260, w: 200, h: 20 }
    ];

    const coins = [
      { x: 250, y: 370, r: 10, collected: false },
      { x: 510, y: 320, r: 10, collected: false },
      { x: 770, y: 260, r: 10, collected: false },
      { x: 1030, y: 210, r: 10, collected: false },
      { x: 1350, y: 300, r: 10, collected: false },
      { x: 1680, y: 240, r: 10, collected: false },
      { x: 2030, y: 180, r: 10, collected: false },
      { x: 2360, y: 280, r: 10, collected: false },
      { x: 2680, y: 220, r: 10, collected: false }
    ];

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (player.onGround) {
        player.vx *= world.friction;
      } else {
        player.vx *= world.airFriction;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += world.gravity;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > world.width) player.x = world.width - player.w;
      if (player.y > world.height - player.h) {
        player.y = world.height - player.h;
        player.vy = 0;
        player.onGround = true;
      }

      // Coins
      for (const c of coins) {
        if (!c.collected && circleRectCollision(c, player)) {
          c.collected = true;
          player.coins++;
        }
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += 1;
        if (player.animTime > 8) {
          player.animTime = 0;
          player.frame = (player.frame + 1) % 4;
        }
      } else {
        player.frame = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
    }

    function drawBackground() {
      // Parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, 0);

      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 12; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 300 + 150, 470, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = p.y >= 490 ? "#5b3a29" : "#7a5c3d";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        // top highlight
        ctx.fillStyle = "#9b7a54";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 4);
      }
    }

    function drawCoins() {
      for (const c of coins) {
        if (c.collected) continue;
        const x = c.x - camera.x;
        const y = c.y - camera.y;

        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(0, 0, c.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#c89b00";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, c.r - 3, 0, Math.PI * 2);
        ctx.stroke();

        ctx.restore();
      }
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Simple sprite animation using drawn frames
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // body bounce based on frame
      const bob = player.onGround ? Math.sin(player.frame * 1.5) * 2 : 0;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // legs
      ctx.fillStyle = "#2d3e50";
      const legOffset = [0, 2, 0, -2][player.frame];
      ctx.fillRect(-10, 10 + bob, 8, 18);
      ctx.fillRect(2, 10 - bob, 8, 18);

      // torso
      ctx.fillStyle = "#ff4d4d";
      ctx.fillRect(-14, -10 + bob, 28, 24);

      // arms
      ctx.fillStyle = "#f1c27d";
      ctx.fillRect(-20, -6 + bob, 8, 16);
      ctx.fillRect(12, -6 - bob, 8, 16);

      // head
      ctx.fillStyle = "#f1c27d";
      ctx.beginPath();
      ctx.arc(0, -26 + bob, 14, 0, Math.PI * 2);
      ctx.fill();

      // eyes
      ctx.fillStyle = "#222";
      ctx.beginPath();
      ctx.arc(-5, -28 + bob, 2, 0, Math.PI * 2);
      ctx.arc(5, -28 + bob, 2, 0, Math.PI * 2);
      ctx.fill();

      // hat
      ctx.fillStyle = "#333";
      ctx.fillRect(-16, -40 + bob, 32, 8);
      ctx.fillRect(-10, -48 + bob, 20, 10);

      ctx.restore();
    }

    function drawHUD() {
      hud.textContent = `Coins: ${player.coins} / ${coins.length}`;
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // Ground haze
      const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
      gradient.addColorStop(0, "rgba(255,255,255,0.15)");
      gradient.addColorStop(1, "rgba(255,255,255,0)");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      drawPlatforms();
      drawCoins();
      drawPlayer();

      // Debug-ish horizon line
      ctx.strokeStyle = "rgba(255,255,255,0.15)";
      ctx.beginPath();
      ctx.moveTo(0, 500 - camera.y);
      ctx.lineTo(canvas.width, 500 - camera.y);
      ctx.stroke();
    }

    function gameLoop() {
      updatePlayer();
      render();
      drawHUD();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
