## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    #hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 14px;
      text-shadow: 0 1px 2px black;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="hud">Arrows / A-D to move, Space / W / Up to jump</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- World / Level ---
    const TILE_SIZE = 48;

    const level = [
      "..................................................",
      "..................................................",
      "..................................................",
      "..................................................",
      "..................................................",
      "..................................................",
      "....................####..........................",
      "..............###..................................",
      ".............................................###..",
      "...........####.....................###............",
      "..................................................",
      "......###...................####..................",
      "..................................................",
      "####################....##########################",
    ];

    const solids = new Set(["#"]);

    function tileAt(tx, ty) {
      if (ty < 0 || ty >= level.length || tx < 0 || tx >= level[0].length) return "#";
      return level[ty][tx];
    }

    function rectVsTile(x, y, w, h) {
      const left = Math.floor(x / TILE_SIZE);
      const right = Math.floor((x + w - 1) / TILE_SIZE);
      const top = Math.floor(y / TILE_SIZE);
      const bottom = Math.floor((y + h - 1) / TILE_SIZE);

      for (let ty = top; ty <= bottom; ty++) {
        for (let tx = left; tx <= right; tx++) {
          if (solids.has(tileAt(tx, ty))) {
            return true;
          }
        }
      }
      return false;
    }

    // --- Animation helper ---
    class Animation {
      constructor(frames, frameDuration) {
        this.frames = frames;
        this.frameDuration = frameDuration;
        this.time = 0;
      }

      update(dt) {
        this.time += dt;
      }

      getFrame() {
        const index = Math.floor(this.time / this.frameDuration) % this.frames.length;
        return this.frames[index];
      }
    }

    // --- Player ---
    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 44,
      vx: 0,
      vy: 0,
      speed: 260,
      jumpPower: 620,
      gravity: 1800,
      friction: 0.82,
      onGround: false,
      facing: 1,
      animState: "idle",
      animations: {
        idle: new Animation([0, 1], 0.35),
        run: new Animation([0, 1, 2, 3], 0.1),
        jump: new Animation([0], 0.2),
      }
    };

    let jumpPressedLast = false;

    function updatePlayer(dt) {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      // Horizontal movement
      if (left) {
        player.vx = Math.max(player.vx - player.speed * dt * 6, -player.speed);
        player.facing = -1;
      } else if (right) {
        player.vx = Math.min(player.vx + player.speed * dt * 6, player.speed);
        player.facing = 1;
      } else {
        player.vx *= Math.pow(player.friction, dt * 60);
        if (Math.abs(player.vx) < 1) player.vx = 0;
      }

      // Jump
      if (jump && !jumpPressedLast && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      jumpPressedLast = jump;

      // Gravity
      player.vy += player.gravity * dt;
      if (player.vy > 1200) player.vy = 1200;

      // Move X + resolve collisions
      player.x += player.vx * dt;
      if (rectVsTile(player.x, player.y, player.w, player.h)) {
        if (player.vx > 0) {
          player.x = Math.floor((player.x + player.w) / TILE_SIZE) * TILE_SIZE - player.w - 0.01;
        } else if (player.vx < 0) {
          player.x = Math.floor(player.x / TILE_SIZE + 1) * TILE_SIZE + 0.01;
        }
        player.vx = 0;
      }

      // Move Y + resolve collisions
      player.y += player.vy * dt;
      player.onGround = false;

      if (rectVsTile(player.x, player.y, player.w, player.h)) {
        if (player.vy > 0) {
          player.y = Math.floor((player.y + player.h) / TILE_SIZE) * TILE_SIZE - player.h - 0.01;
          player.onGround = true;
        } else if (player.vy < 0) {
          player.y = Math.floor(player.y / TILE_SIZE + 1) * TILE_SIZE + 0.01;
        }
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.animState = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.animState = "run";
      } else {
        player.animState = "idle";
      }

      player.animations[player.animState].update(dt);
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      const maxX = level[0].length * TILE_SIZE - canvas.width;
      const maxY = level.length * TILE_SIZE - canvas.height;

      camera.x = Math.max(0, Math.min(camera.x, Math.max(0, maxX)));
      camera.y = Math.max(0, Math.min(camera.y, Math.max(0, maxY)));
    }

    // --- Rendering ---
    function drawLevel() {
      const startX = Math.floor(camera.x / TILE_SIZE);
      const endX = Math.ceil((camera.x + canvas.width) / TILE_SIZE);
      const startY = Math.floor(camera.y / TILE_SIZE);
      const endY = Math.ceil((camera.y + canvas.height) / TILE_SIZE);

      for (let y = startY; y < endY; y++) {
        for (let x = startX; x < endX; x++) {
          const tile = tileAt(x, y);
          if (tile === "#") {
            ctx.fillStyle = "#4b2e1f";
            ctx.fillRect(
              x * TILE_SIZE - camera.x,
              y * TILE_SIZE - camera.y,
              TILE_SIZE,
              TILE_SIZE
            );

            // simple top highlight
            ctx.fillStyle = "#6b4430";
            ctx.fillRect(
              x * TILE_SIZE - camera.x,
              y * TILE_SIZE - camera.y,
              TILE_SIZE,
              8
            );
          }
        }
      }
    }

    function drawPlayer() {
      const frame = player.animations[player.animState].getFrame();

      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Body
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(player.w / 2, player.h + 4, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Legs / body animation
      ctx.fillStyle = "#2b6cb0";
      ctx.fillRect(6, 16, 20, 22);

      ctx.fillStyle = "#f6c9a2";
      ctx.fillRect(8, 4, 16, 14);

      // Eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(12 + frame * 0.5, 9, 2, 2);
      ctx.fillRect(17 + frame * 0.5, 9, 2, 2);

      // Arms
      ctx.fillStyle = "#d97706";
      if (player.animState === "run") {
        ctx.fillRect(2, 18, 6, 4);
        ctx.fillRect(24, 18, 6, 4);
      } else {
        ctx.fillRect(3, 18, 5, 4);
        ctx.fillRect(24, 18, 5, 4);
      }

      // Feet
      ctx.fillStyle = "#111";
      ctx.fillRect(7, 37, 8, 4);
      ctx.fillRect(17, 37, 8, 4);

      ctx.restore();
    }

    function drawBackground() {
      // parallax clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 8; i++) {
        const cx = ((i * 260) - (camera.x * 0.25)) % (canvas.width + 300) - 150;
        const cy = 60 + (i % 3) * 40;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 40, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 30, cy + 5, 50, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(cx - 30, cy + 8, 35, 16, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // --- Game loop ---
    let lastTime = 0;
    function loop(time) {
      const dt = Math.min((time - lastTime) / 1000, 0.033);
      lastTime = time;

      updatePlayer(dt);
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawLevel();
      drawPlayer();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

