```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1b1f2a;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .help {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="help">
    Move: A/D or Arrow Keys<br>
    Jump: Space / W / Arrow Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // World settings
    const GRAVITY = 2200;
    const FRICTION = 0.82;
    const MOVE_ACCEL = 2200;
    const MAX_SPEED = 420;
    const JUMP_VEL = 820;

    const world = {
      width: 3200,
      height: 1200
    };

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") {
        keys.jump = true;
      }
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") {
        keys.jump = false;
      }
    });

    // Platforms
    const platforms = [
      { x: 0, y: 1120, w: 3200, h: 80 },     // ground
      { x: 200, y: 950, w: 220, h: 30 },
      { x: 520, y: 850, w: 240, h: 30 },
      { x: 860, y: 760, w: 220, h: 30 },
      { x: 1200, y: 680, w: 260, h: 30 },
      { x: 1550, y: 780, w: 220, h: 30 },
      { x: 1880, y: 900, w: 260, h: 30 },
      { x: 2240, y: 820, w: 220, h: 30 },
      { x: 2550, y: 720, w: 260, h: 30 },
      { x: 2900, y: 600, w: 180, h: 30 }
    ];

    // Player
    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    // Simple generated sprite sheet (4 frames, 2 rows: idle/run)
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 256;
    spriteCanvas.height = 128;
    const sctx = spriteCanvas.getContext("2d");

    function drawSpriteFrame(frame, row) {
      const x = frame * 64;
      const y = row * 64;
      sctx.clearRect(x, y, 64, 64);

      // body
      sctx.fillStyle = "#2b2d42";
      sctx.fillRect(x + 24, y + 22, 16, 22);

      // head
      sctx.fillStyle = "#ffd6a5";
      sctx.fillRect(x + 22, y + 8, 20, 16);

      // legs animation
      sctx.fillStyle = "#4361ee";
      if (row === 1) {
        // run frames
        const legOffset = [0, 4, -2, 3][frame];
        sctx.fillRect(x + 20, y + 44, 10, 14);
        sctx.fillRect(x + 34, y + 44, 10, 14);
        sctx.fillRect(x + 18 + legOffset, y + 46, 8, 12);
        sctx.fillRect(x + 38 - legOffset, y + 46, 8, 12);
      } else {
        // idle
        sctx.fillRect(x + 20, y + 44, 10, 14);
        sctx.fillRect(x + 34, y + 44, 10, 14);
      }

      // arms
      sctx.fillStyle = "#ffd6a5";
      sctx.fillRect(x + 14, y + 24, 10, 6);
      sctx.fillRect(x + 40, y + 24, 10, 6);

      // eye
      sctx.fillStyle = "#111";
      sctx.fillRect(x + 30, y + 14, 3, 3);
    }

    for (let row = 0; row < 2; row++) {
      for (let frame = 0; frame < 4; frame++) {
        drawSpriteFrame(frame, row);
      }
    }

    const sprite = new Image();
    sprite.src = spriteCanvas.toDataURL();

    function aabbIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, dx, dy) {
      // Move X and resolve
      entity.x += dx;
      for (const p of platforms) {
        if (aabbIntersect(entity, p)) {
          if (dx > 0) {
            entity.x = p.x - entity.w;
          } else if (dx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Move Y and resolve
      entity.y += dy;
      entity.onGround = false;
      for (const p of platforms) {
        if (aabbIntersect(entity, p)) {
          if (dy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (dy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    let lastTime = performance.now();
    const camera = { x: 0, y: 0 };

    function update(dt) {
      // Horizontal movement
      if (keys.left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (keys.right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      // Clamp speed
      player.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, player.vx));

      // Friction
      if (!keys.left && !keys.right && player.onGround) {
        player.vx *= Math.pow(FRICTION, dt * 60);
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Jump
      if (keys.jump && player.onGround) {
        player.vy = -JUMP_VEL;
        player.onGround = false;
      }

      // Move and collide
      resolveCollisions(player, player.vx * dt, player.vy * dt);

      // Animation
      player.animTime += dt;
      if (player.onGround) {
        if (Math.abs(player.vx) > 20) {
          player.frame = Math.floor(player.animTime * 12) % 4; // run
        } else {
          player.frame = 0; // idle
        }
      } else {
        player.frame = 1; // jump frame
      }

      // Camera follows player
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b5563";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#6b7280";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const sx = player.frame * 64;
      const sy = player.onGround && Math.abs(player.vx) > 20 ? 64 : 0;

      ctx.save();
      ctx.translate(player.x - camera.x + player.w / 2, player.y - camera.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.drawImage(
        sprite,
        sx, sy, 64, 64,
        -player.w / 2, -player.h / 2,
        player.w, player.h
      );
      ctx.restore();
    }

    function drawBackground() {
      // simple parallax hills
      ctx.fillStyle = "#9bd1ff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const hillOffset = camera.x * 0.3;
      ctx.fillStyle = "#7cc37c";
      for (let i = -1; i < 8; i++) {
        const hx = i * 500 - (hillOffset % 500);
        ctx.beginPath();
        ctx.ellipse(hx + 250, canvas.height - 120, 220, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      const cloudOffset = camera.x * 0.15;
      for (let i = 0; i < 6; i++) {
        const cx = (i * 420 - (cloudOffset % 420)) + 100;
        const cy = 80 + (i % 3) * 50;
        ctx.beginPath();
        ctx.arc(cx, cy, 28, 0, Math.PI * 2);
        ctx.arc(cx + 30, cy - 10, 36, 0, Math.PI * 2);
        ctx.arc(cx + 65, cy, 26, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function loop(now) {
      const dt = Math.min(0.033, (now - lastTime) / 1000);
      lastTime = now;

      update(dt);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // Draw platforms
      for (const p of platforms) drawPlatform(p);

      // Draw player
      drawPlayer();

      // HUD
      ctx.fillStyle = "rgba(0,0,0,0.4)";
      ctx.fillRect(10, canvas.height - 40, 220, 28);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(0)}  y: ${player.y.toFixed(0)}`, 20, canvas.height - 21);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
