```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1b1f2a;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#7ec8ff, #cfefff);
      image-rendering: pixelated;
    }
    #ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      user-select: none;
    }
  </style>
</head>
<body>
  <div id="ui">Coins: <span id="coins">0</span> | <span id="message">Reach the flag!</span></div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinText = document.getElementById("coins");
    const messageText = document.getElementById("message");

    const TILE = 48;
    const GRAVITY = 2200;
    const MOVE_SPEED = 420;
    const JUMP_SPEED = 860;
    const FRICTION = 0.82;
    const MAX_FALL = 1400;

    const keys = {};
    addEventListener("keydown", e => keys[e.code] = true);
    addEventListener("keyup", e => keys[e.code] = false);

    // Level map:
    // # = solid
    // C = coin
    // E = enemy
    // P = player spawn
    // F = flag (goal)
    const level = [
      "................................................................................",
      "................................................................................",
      "................................................................................",
      "....................................................C...........................",
      "............................C...................................................",
      "....................####.......................................................F",
      ".............................................####...............................#",
      ".............C.................................................................#",
      "...........#####......................C........................................#",
      "....................................#####......................................#",
      "....................E.........................................................#",
      ".............####.........................#####.....................C.........#",
      "..............................................................#####............#",
      ".....P..................................................C......................#",
      "##############################....###############################....############"
    ];

    const world = {
      width: level[0].length * TILE,
      height: level.length * TILE
    };

    const solids = [];
    const coins = [];
    const enemies = [];
    let flag = null;
    let player = null;

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function parseLevel() {
      solids.length = 0;
      coins.length = 0;
      enemies.length = 0;
      flag = null;
      player = null;

      for (let y = 0; y < level.length; y++) {
        for (let x = 0; x < level[y].length; x++) {
          const ch = level[y][x];
          const px = x * TILE;
          const py = y * TILE;

          if (ch === "#") {
            solids.push({ x: px, y: py, w: TILE, h: TILE });
          } else if (ch === "C") {
            coins.push({ x: px + 12, y: py + 12, w: 24, h: 24, collected: false, t: 0 });
          } else if (ch === "E") {
            enemies.push({
              x: px + 8,
              y: py + 8,
              w: 32,
              h: 40,
              vx: -80,
              vy: 0,
              dir: -1,
              onGround: false,
              alive: true
            });
          } else if (ch === "P") {
            player = {
              x: px + 8,
              y: py + 8,
              w: 32,
              h: 40,
              vx: 0,
              vy: 0,
              onGround: false,
              facing: 1,
              alive: true,
              win: false,
              animTime: 0,
              animFrame: 0
            };
          } else if (ch === "F") {
            flag = { x: px + 12, y: py - 48, w: 24, h: 96 };
          }
        }
      }
    }

    // Generate a tiny sprite sheet on an offscreen canvas
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 128;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawSpriteSheet() {
      sctx.clearRect(0, 0, spriteCanvas.width, spriteCanvas.height);

      // Player frames (4 frames, 32x40 each)
      const frames = [
        { leg: 28, arm: 18, color: "#ffcc66" },
        { leg: 30, arm: 14, color: "#ffd27f" },
        { leg: 28, arm: 18, color: "#ffcc66" },
        { leg: 30, arm: 14, color: "#ffd27f" }
      ];

      frames.forEach((f, i) => {
        const x = i * 32;
        const y = 0;

        // body
        sctx.fillStyle = "#2d5bff";
        sctx.fillRect(x + 10, y + 18, 12, 14);

        // head
        sctx.fillStyle = f.color;
        sctx.fillRect(x + 11, y + 6, 10, 10);

        // legs
        sctx.fillStyle = "#1d2a57";
        sctx.fillRect(x + 8, y + f.leg, 6, 10);
        sctx.fillRect(x + 18, y + f.leg, 6, 10);

        // arms
        sctx.fillStyle = "#ff9966";
        sctx.fillRect(x + 6, y + f.arm, 5, 12);
        sctx.fillRect(x + 21, y + f.arm, 5, 12);

        // eyes
        sctx.fillStyle = "#000";
        sctx.fillRect(x + 13, y + 9, 2, 2);
        sctx.fillRect(x + 17, y + 9, 2, 2);
      });

      // Enemy frame (32x40)
      sctx.fillStyle = "#7c3f00";
      sctx.fillRect(0, 40, 32, 20);
      sctx.fillStyle = "#ffdd55";
      sctx.fillRect(8, 46, 16, 10);
      sctx.fillStyle = "#000";
      sctx.fillRect(10, 48, 4, 4);
      sctx.fillRect(18, 48, 4, 4);
      sctx.fillStyle = "#5a2d00";
      sctx.fillRect(6, 58, 6, 6);
      sctx.fillRect(20, 58, 6, 6);
    }
    drawSpriteSheet();

    function moveAndCollide(entity, dt) {
      entity.vy += GRAVITY * dt;
      if (entity.vy > MAX_FALL) entity.vy = MAX_FALL;

      // X axis
      entity.x += entity.vx * dt;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      entity.onGround = false;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    function updatePlayer(dt) {
      if (!player.alive || player.win) return;

      const left = keys["ArrowLeft"] || keys["KeyA"];
      const right = keys["ArrowRight"] || keys["KeyD"];
      const jump = keys["Space"] || keys["ArrowUp"] || keys["KeyW"];

      if (left) {
        player.vx -= MOVE_SPEED * dt * 2.2;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_SPEED * dt * 2.2;
        player.facing = 1;
      }

      if (!left && !right) {
        player.vx *= Math.pow(FRICTION, dt * 60);
      }

      player.vx = Math.max(-MOVE_SPEED, Math.min(MOVE_SPEED, player.vx));

      if (jump && player.onGround && !player._jumpHeld) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }
      player._jumpHeld = jump;

      moveAndCollide(player, dt);

      // Collect coins
      for (const c of coins) {
        if (!c.collected && rectsOverlap(player, c)) {
          c.collected = true;
          coinText.textContent = String(Number(coinText.textContent) + 1);
        }
      }

      // Goal
      if (flag && rectsOverlap(player, flag)) {
        player.win = true;
        messageText.textContent = "You win!";
      }

      // Fall off map
      if (player.y > world.height + 200) {
        player.alive = false;
        messageText.textContent = "You fell!";
      }

      // Animation
      player.animTime += dt;
      if (Math.abs(player.vx) > 20 && player.onGround) {
        player.animFrame = Math.floor(player.animTime * 12) % 4;
      } else {
        player.animFrame = 0;
      }
    }

    function updateEnemies(dt) {
      for (const e of enemies) {
        if (!e.alive) continue;

        e.vx = e.dir * 90;
        moveAndCollide(e, dt);

        // turn around at edges or walls
        if (e.onGround) {
          const frontX = e.dir > 0 ? e.x + e.w + 2 : e.x - 2;
          const footY = e.y + e.h + 2;
          const aheadSolid = solids.some(s => frontX >= s.x && frontX <= s.x + s.w && footY >= s.y && footY <= s.y + s.h);
          if (!aheadSolid) e.dir *= -1;
        }

        // player collision
        if (player.alive && !player.win && rectsOverlap(player, e)) {
          // stomp if falling
          if (player.vy > 0 && player.y + player.h - 10 < e.y + 12) {
            e.alive = false;
            player.vy = -JUMP_SPEED * 0.55;
          } else {
            player.alive = false;
            messageText.textContent = "Game over!";
          }
        }
      }
    }

    function drawBackground(cameraX, cameraY) {
      // distant hills
      ctx.save();
      ctx.translate(-cameraX * 0.3, -cameraY * 0.1);
      ctx.fillStyle = "rgba(70, 160, 90, 0.25)";
      for (let i = 0; i < 12; i++) {
        ctx.beginPath();
        ctx.arc(i * 260 + 100, 420, 120, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x + player.w / 2 - canvas.width / 2));
      const cameraY = Math.max(0, Math.min(world.height - canvas.height, player.y + player.h / 2 - canvas.height / 2));

      drawBackground(cameraX, cameraY);

      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      // Draw solids
      for (const s of solids) {
        ctx.fillStyle = "#4b3b2a";
        ctx.fillRect(s.x, s.y, s.w, s.h);
        ctx.fillStyle = "#6f5a3b";
        ctx.fillRect(s.x, s.y, s.w, 8);
      }

      // Draw coins
      for (const c of coins) {
        if (c.collected) continue;
        c.t += 0.08;
        const bob = Math.sin(c.t) * 4;
        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(c.x + 12, c.y + 12 + bob, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#fff4a3";
        ctx.beginPath();
        ctx.arc(c.x + 8, c.y + 9 + bob, 3, 0, Math.PI * 2);
        ctx.fill();
      }

      // Draw flag
      if (flag) {
        ctx.fillStyle = "#8b5a2b";
        ctx.fillRect(flag.x + 10, flag.y, 4, flag.h);
        ctx.fillStyle = "#ff4d4d";
        ctx.fillRect(flag.x + 14, flag.y + 10, 28, 18);
      }

      // Draw enemies
      for (const e of enemies) {
        if (!e.alive) continue;
        ctx.save();
        ctx.translate(e.x, e.y);
        if (e.dir < 0) {
          ctx.scale(-1, 1);
          ctx.translate(-e.w, 0);
        }
        ctx.drawImage(spriteCanvas, 0, 40, 32, 40, 0, 0, e.w, e.h);
        ctx.restore();
      }

      // Draw player
      if (player) {
        ctx.save();
        ctx.translate(player.x, player.y);
        if (player.facing < 0) {
          ctx.scale(-1, 1);
          ctx.translate(-player.w, 0);
        }
        ctx.drawImage(
          spriteCanvas,
          player.animFrame * 32, 0, 32, 40,
          0, 0, player.w, player.h
        );
        ctx.restore();
      }

      ctx.restore();

      // UI
      coinText.textContent = coins.filter(c => c.collected).length.toString();
    }

    let last = 0;
    function loop(ts) {
      const dt = Math.min(0.033, (ts - last) / 1000 || 0);
      last = ts;

      updatePlayer(dt);
      updateEnemies(dt);
      draw();

      requestAnimationFrame(loop);
    }

    parseLevel();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
