## Code

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      font-size: 16px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: W/Space/↑ | Restart: R
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
      if (e.code === "KeyR") resetGame();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    // -----------------------------
    // World / Physics constants
    // -----------------------------
    const GRAVITY = 2200;
    const MOVE_ACCEL = 2500;
    const MAX_SPEED = 420;
    const FRICTION = 1800;
    const JUMP_VELOCITY = 820;
    const AIR_CONTROL = 0.75;

    const world = {
      width: 3000,
      height: 1200
    };

    // -----------------------------
    // Utility
    // -----------------------------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    // -----------------------------
    // Level data
    // -----------------------------
    const platforms = [
      { x: 0, y: 1100, w: 3000, h: 100, color: "#4b3f2f" },
      { x: 200, y: 950, w: 250, h: 30, color: "#6b5845" },
      { x: 550, y: 850, w: 220, h: 30, color: "#6b5845" },
      { x: 900, y: 760, w: 220, h: 30, color: "#6b5845" },
      { x: 1250, y: 680, w: 240, h: 30, color: "#6b5845" },
      { x: 1650, y: 760, w: 240, h: 30, color: "#6b5845" },
      { x: 2050, y: 860, w: 260, h: 30, color: "#6b5845" },
      { x: 2450, y: 940, w: 220, h: 30, color: "#6b5845" },
      { x: 700, y: 1020, w: 140, h: 20, color: "#7a6650" },
      { x: 1500, y: 980, w: 160, h: 20, color: "#7a6650" },
      { x: 2250, y: 1020, w: 160, h: 20, color: "#7a6650" },
    ];

    const coins = [
      { x: 300, y: 900, r: 12, collected: false },
      { x: 620, y: 800, r: 12, collected: false },
      { x: 970, y: 710, r: 12, collected: false },
      { x: 1320, y: 630, r: 12, collected: false },
      { x: 1720, y: 710, r: 12, collected: false },
      { x: 2140, y: 810, r: 12, collected: false },
      { x: 2520, y: 890, r: 12, collected: false },
    ];

    // -----------------------------
    // Player
    // -----------------------------
    const playerStart = { x: 100, y: 900 };

    const player = {
      x: playerStart.x,
      y: playerStart.y,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      facing: 1,
      onGround: false,
      score: 0,
      animTime: 0,
      state: "idle"
    };

    // -----------------------------
    // Camera
    // -----------------------------
    const camera = {
      x: 0,
      y: 0
    };

    // -----------------------------
    // Reset
    // -----------------------------
    function resetGame() {
      player.x = playerStart.x;
      player.y = playerStart.y;
      player.vx = 0;
      player.vy = 0;
      player.facing = 1;
      player.onGround = false;
      player.score = 0;
      player.animTime = 0;
      player.state = "idle";
      coins.forEach(c => c.collected = false);
    }

    // -----------------------------
    // Physics / Collision
    // -----------------------------
    function moveAndCollide(dt) {
      // Horizontal movement
      player.x += player.vx * dt;
      let box = { x: player.x, y: player.y, w: player.w, h: player.h };

      for (const p of platforms) {
        if (rectsOverlap(box, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
          box.x = player.x;
        }
      }

      // Vertical movement
      player.y += player.vy * dt;
      player.onGround = false;
      box = { x: player.x, y: player.y, w: player.w, h: player.h };

      for (const p of platforms) {
        if (rectsOverlap(box, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          box.y = player.y;
        }
      }

      // World bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height + 200) {
        resetGame();
      }
    }

    // -----------------------------
    // Animation
    // -----------------------------
    function updateAnimation(dt) {
      const speed = Math.abs(player.vx);
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (speed > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }
      player.animTime += dt;
    }

    function drawPlayer(x, y) {
      const t = player.animTime;
      const facing = player.facing;
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(facing, 1);

      // Simple animated character made from shapes.
      // Replace with sprite sheet rendering if desired.
      let bob = 0;
      if (player.state === "run") bob = Math.sin(t * 14) * 2;
      if (player.state === "idle") bob = Math.sin(t * 4) * 1;
      if (player.state === "jump") bob = -2;
      if (player.state === "fall") bob = 2;

      ctx.translate(0, bob);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 - 2, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#ffcc66";
      roundRect(-18, -18, 36, 34, 8);
      ctx.fill();

      // Head
      ctx.fillStyle = "#ffdca8";
      ctx.beginPath();
      ctx.arc(0, -28, 14, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#222";
      ctx.beginPath();
      ctx.arc(-5, -30, 2.2, 0, Math.PI * 2);
      ctx.arc(5, -30, 2.2, 0, Math.PI * 2);
      ctx.fill();

      // Legs animation
      ctx.strokeStyle = "#3b2f2f";
      ctx.lineWidth = 5;
      ctx.lineCap = "round";

      const legSwing = player.state === "run" ? Math.sin(t * 14) * 10 : 0;
      const legSwing2 = player.state === "run" ? Math.sin(t * 14 + Math.PI) * 10 : 0;

      ctx.beginPath();
      ctx.moveTo(-8, 15);
      ctx.lineTo(-12 + legSwing * 0.05, 28);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 15);
      ctx.lineTo(12 + legSwing2 * 0.05, 28);
      ctx.stroke();

      // Arms
      ctx.strokeStyle = "#5a4636";
      ctx.lineWidth = 4;
      const armSwing = player.state === "run" ? Math.sin(t * 14 + Math.PI) * 8 : 0;

      ctx.beginPath();
      ctx.moveTo(-16, -8);
      ctx.lineTo(-24, 2 + armSwing * 0.05);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(16, -8);
      ctx.lineTo(24, 2 - armSwing * 0.05);
      ctx.stroke();

      ctx.restore();
    }

    function roundRect(x, y, w, h, r) {
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r);
      ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r);
      ctx.closePath();
    }

    // -----------------------------
    // Update
    // -----------------------------
    function update(dt) {
      const left = keys["ArrowLeft"] || keys["KeyA"];
      const right = keys["ArrowRight"] || keys["KeyD"];
      const jump = keys["ArrowUp"] || keys["KeyW"] || keys["Space"];

      let accel = MOVE_ACCEL * (player.onGround ? 1 : AIR_CONTROL);

      if (left) {
        player.vx -= accel * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += accel * dt;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        // friction
        if (player.vx > 0) {
          player.vx = Math.max(0, player.vx - FRICTION * dt);
        } else if (player.vx < 0) {
          player.vx = Math.min(0, player.vx + FRICTION * dt);
        }
      }

      player.vx = clamp(player.vx, -MAX_SPEED, MAX_SPEED);

      if (jump && player.onGround && !update.jumpLock) {
        player.vy = -JUMP_VELOCITY;
        player.onGround = false;
        update.jumpLock = true;
      }
      if (!jump) update.jumpLock = false;

      // Gravity
      player.vy += GRAVITY * dt;
      player.vy = Math.min(player.vy, 1600);

      moveAndCollide(dt);
      updateAnimation(dt);

      // Collect coins
      for (const c of coins) {
        if (c.collected) continue;
        const px = player.x + player.w / 2;
        const py = player.y + player.h / 2;
        const dx = px - c.x;
        const dy = py - c.y;
        if (Math.hypot(dx, dy) < c.r + 22) {
          c.collected = true;
          player.score++;
        }
      }

      // Camera follow
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;
      camera.x += (targetX - camera.x) * Math.min(1, dt * 6);
      camera.y += (targetY - camera.y) * Math.min(1, dt * 6);

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    // -----------------------------
    // Draw
    // -----------------------------
    function drawBackground() {
      // Parallax clouds / hills could go here
      ctx.fillStyle = "rgba(255,255,255,0.35)";
      for (let i = 0; i < 8; i++) {
        const x = ((i * 420 - camera.x * 0.2) % (world.width + 500)) - 200;
        const y = 80 + (i % 3) * 40;
        drawCloud(x, y, 1 + (i % 2) * 0.2);
      }
    }

    function drawCloud(x, y, s) {
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(s, s);
      ctx.beginPath();
      ctx.arc(0, 0, 24, 0, Math.PI * 2);
      ctx.arc(24, -10, 30, 0, Math.PI * 2);
      ctx.arc(54, 0, 22, 0, Math.PI * 2);
      ctx.arc(26, 10, 28, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Camera transform
      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      drawBackground();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x, p.y, p.w, p.h);

        // top highlight
        ctx.fillStyle = "rgba(255,255,255,0.12)";
        ctx.fillRect(p.x, p.y, p.w, 4);
      }

      // Coins
      for (const c of coins) {
        if (c.collected) continue;
        ctx.save();
        ctx.translate(c.x, c.y);
        const pulse = 1 + Math.sin(performance.now() * 0.01) * 0.08;
        ctx.scale(pulse, pulse);

        ctx.fillStyle = "#ffd84d";
        ctx.beginPath();
        ctx.arc(0, 0, c.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#b8860b";
        ctx.lineWidth = 3;
        ctx.stroke();

        ctx.fillStyle = "rgba(255,255,255,0.35)";
        ctx.beginPath();
        ctx.arc(-4, -4, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      // Player
      drawPlayer(player.x, player.y);

      ctx.restore();

      // HUD
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Coins: ${player.score}/${coins.length}`, 20, 50);
      ctx.fillText(`State: ${player.state}`, 20, 78);
    }

    // -----------------------------
    // Game loop
    // -----------------------------
    let last = performance.now();
    function loop(now) {
      const dt = Math.min(1 / 30, (now - last) / 1000);
      last = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
