```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 1px 2px black;
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">Move: A/D or ←/→ | Jump: Space / W / ↑</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // Input
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // World
    const TILE = 48;
    const world = {
      width: 50,
      height: 20,
      tiles: []
    };

    // Build a simple level
    for (let y = 0; y < world.height; y++) {
      world.tiles[y] = [];
      for (let x = 0; x < world.width; x++) {
        world.tiles[y][x] = 0;
      }
    }

    // Ground
    for (let x = 0; x < world.width; x++) {
      world.tiles[18][x] = 1;
      world.tiles[19][x] = 1;
    }

    // Platforms
    for (let x = 5; x < 10; x++) world.tiles[14][x] = 1;
    for (let x = 14; x < 20; x++) world.tiles[11][x] = 1;
    for (let x = 24; x < 30; x++) world.tiles[8][x] = 1;
    for (let x = 34; x < 42; x++) world.tiles[13][x] = 1;

    // Player
    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 44,
      vx: 0,
      vy: 0,
      speed: 0.6,
      jumpPower: 13,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const physics = {
      gravity: 0.55,
      friction: 0.82,
      airFriction: 0.95,
      maxSpeed: 6,
      terminalVelocity: 16
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function getTileAtPixel(px, py) {
      const tx = Math.floor(px / TILE);
      const ty = Math.floor(py / TILE);
      if (ty < 0 || ty >= world.height || tx < 0 || tx >= world.width) return 0;
      return world.tiles[ty][tx];
    }

    function isSolidAt(px, py) {
      return getTileAtPixel(px, py) === 1;
    }

    function moveAndCollide(entity) {
      // Horizontal movement
      entity.x += entity.vx;
      let left = entity.x;
      let right = entity.x + entity.w;
      let top = entity.y;
      let bottom = entity.y + entity.h;

      if (entity.vx > 0) {
        const checkX = right;
        for (let y = Math.floor(top / TILE); y <= Math.floor((bottom - 1) / TILE); y++) {
          if (isSolidAt(checkX, y * TILE) || isSolidAt(checkX, y * TILE + TILE - 1)) {
            entity.x = Math.floor(checkX / TILE) * TILE - entity.w - 0.01;
            entity.vx = 0;
            break;
          }
        }
      } else if (entity.vx < 0) {
        const checkX = left;
        for (let y = Math.floor(top / TILE); y <= Math.floor((bottom - 1) / TILE); y++) {
          if (isSolidAt(checkX, y * TILE) || isSolidAt(checkX, y * TILE + TILE - 1)) {
            entity.x = Math.floor(checkX / TILE + 1) * TILE + 0.01;
            entity.vx = 0;
            break;
          }
        }
      }

      // Vertical movement
      entity.y += entity.vy;
      left = entity.x;
      right = entity.x + entity.w;
      top = entity.y;
      bottom = entity.y + entity.h;
      entity.onGround = false;

      if (entity.vy > 0) {
        const checkY = bottom;
        for (let x = Math.floor(left / TILE); x <= Math.floor((right - 1) / TILE); x++) {
          if (isSolidAt(x * TILE, checkY) || isSolidAt(x * TILE + TILE - 1, checkY)) {
            entity.y = Math.floor(checkY / TILE) * TILE - entity.h - 0.01;
            entity.vy = 0;
            entity.onGround = true;
            break;
          }
        }
      } else if (entity.vy < 0) {
        const checkY = top;
        for (let x = Math.floor(left / TILE); x <= Math.floor((right - 1) / TILE); x++) {
          if (isSolidAt(x * TILE, checkY) || isSolidAt(x * TILE + TILE - 1, checkY)) {
            entity.y = Math.floor(checkY / TILE + 1) * TILE + 0.01;
            entity.vy = 0;
            break;
          }
        }
      }
    }

    function updatePlayer(dt) {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      player.vx = Math.max(-physics.maxSpeed, Math.min(physics.maxSpeed, player.vx));

      if (player.onGround) {
        player.vx *= physics.friction;
      } else {
        player.vx *= physics.airFriction;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += physics.gravity;
      player.vy = Math.min(player.vy, physics.terminalVelocity);

      moveAndCollide(player);

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += dt;
        player.frame = Math.floor(player.animTime / 0.12) % 4;
      } else {
        player.frame = 0;
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      const maxX = world.width * TILE - canvas.width;
      const maxY = world.height * TILE - canvas.height;

      camera.x = Math.max(0, Math.min(maxX, camera.x));
      camera.y = Math.max(0, Math.min(maxY, camera.y));
    }

    function drawWorld() {
      const startX = Math.floor(camera.x / TILE);
      const endX = Math.ceil((camera.x + canvas.width) / TILE);
      const startY = Math.floor(camera.y / TILE);
      const endY = Math.ceil((camera.y + canvas.height) / TILE);

      for (let y = startY; y < endY; y++) {
        for (let x = startX; x < endX; x++) {
          if (y < 0 || y >= world.height || x < 0 || x >= world.width) continue;
          if (world.tiles[y][x] === 1) {
            ctx.fillStyle = "#4b5563";
            ctx.fillRect(x * TILE - camera.x, y * TILE - camera.y, TILE, TILE);
            ctx.fillStyle = "#6b7280";
            ctx.fillRect(x * TILE - camera.x + 4, y * TILE - camera.y + 4, TILE - 8, TILE - 8);
          }
        }
      }
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body animation frames
      const bob = player.onGround && Math.abs(player.vx) > 0.5 ? Math.sin(player.animTime * 20) * 2 : 0;
      const bodyW = player.w;
      const bodyH = player.h;

      // Simple "sprite" made from shapes
      ctx.save();
      ctx.translate(x + bodyW / 2, y + bodyH / 2 + bob);
      ctx.scale(player.facing, 1);

      // Legs
      ctx.fillStyle = "#2d3748";
      const legOffset = player.onGround && Math.abs(player.vx) > 0.5 ? (player.frame % 2 === 0 ? 3 : -3) : 0;
      ctx.fillRect(-10, 16, 8, 14);
      ctx.fillRect(2, 16, 8, 14);

      // Torso
      ctx.fillStyle = "#ef4444";
      ctx.fillRect(-14, -6, 28, 24);

      // Arms
      ctx.fillStyle = "#f59e0b";
      ctx.fillRect(-18, 0 + legOffset, 6, 16);
      ctx.fillRect(12, 0 - legOffset, 6, 16);

      // Head
      ctx.fillStyle = "#fcd34d";
      ctx.beginPath();
      ctx.arc(0, -18, 12, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#111827";
      ctx.fillRect(-5, -20, 3, 3);
      ctx.fillRect(2, -20, 3, 3);

      // Hat
      ctx.fillStyle = "#1f2937";
      ctx.fillRect(-14, -30, 28, 6);
      ctx.fillRect(-10, -38, 20, 8);

      ctx.restore();
    }

    function drawBackground() {
      // Parallax hills
      ctx.fillStyle = "#a7f3d0";
      for (let i = 0; i < 8; i++) {
        const hx = (i * 240 - (camera.x * 0.3) % 240) - 40;
        const hy = canvas.height - 120;
        ctx.beginPath();
        ctx.arc(hx, hy, 90, Math.PI, 0);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      const cloudPositions = [
        [120, 90], [420, 60], [760, 120], [1100, 80], [1450, 100]
      ];
      for (const [cx, cy] of cloudPositions) {
        const x = cx - (camera.x * 0.15);
        const y = cy;
        ctx.beginPath();
        ctx.arc(x, y, 24, 0, Math.PI * 2);
        ctx.arc(x + 24, y - 10, 30, 0, Math.PI * 2);
        ctx.arc(x + 52, y, 22, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    let lastTime = 0;
    function gameLoop(time) {
      const dt = Math.min(0.033, (time - lastTime) / 1000 || 0.016);
      lastTime = time;

      updatePlayer(dt);
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();

      requestAnimationFrame(gameLoop);
    }

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

