</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: W/Space/↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- World ---
    const gravity = 0.7;
    const friction = 0.85;

    const world = {
      width: 3000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 700, w: 3000, h: 80 },   // ground
      { x: 200, y: 560, w: 220, h: 25 },
      { x: 520, y: 470, w: 220, h: 25 },
      { x: 860, y: 390, w: 220, h: 25 },
      { x: 1200, y: 520, w: 260, h: 25 },
      { x: 1600, y: 430, w: 220, h: 25 },
      { x: 1900, y: 350, w: 220, h: 25 },
      { x: 2250, y: 500, w: 250, h: 25 },
      { x: 2600, y: 420, w: 220, h: 25 },
    ];

    // --- Player ---
    const player = {
      x: 100,
      y: 100,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 0.8,
      jumpPower: 15,
      grounded: false,
      facing: 1, // 1 = right, -1 = left
      animFrame: 0,
      animTimer: 0
    };

    // --- Sprite Animation ---
    // Using a simple programmatic sprite sheet-like animation:
    // We'll draw the player differently per frame.
    const playerFrames = [
      { body: "#ffcc66", shirt: "#2b6cff", eye: "#222" },
      { body: "#ffd27f", shirt: "#2457d6", eye: "#222" },
      { body: "#ffcc66", shirt: "#2b6cff", eye: "#222" },
      { body: "#ffd27f", shirt: "#2457d6", eye: "#222" }
    ];

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Horizontal movement
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Jump
      if ((keys["w"] || keys[" "] || keys["arrowup"]) && player.grounded) {
        player.vy = -player.jumpPower;
        player.grounded = false;
      }

      // Apply gravity
      player.vy += gravity;

      // Apply friction
      player.vx *= friction;

      // Limit speeds
      player.vx = clamp(player.vx, -8, 8);
      player.vy = clamp(player.vy, -20, 20);

      // Move X and resolve collisions
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Move Y and resolve collisions
      player.y += player.vy;
      player.grounded = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.grounded = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep player in world bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      player.y = clamp(player.y, -200, world.height - player.h);

      // Animate based on movement
      const moving = Math.abs(player.vx) > 0.5;

      if (moving) {
        player.animTimer++;
        if (player.animTimer > 8) {
          player.animTimer = 0;
          player.animFrame = (player.animFrame + 1) % playerFrames.length;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }

      // Camera follows player
      camera.x = clamp(player.x + player.w / 2 - canvas.width / 2, 0, world.width - canvas.width);
      camera.y = clamp(player.y + player.h / 2 - canvas.height / 2, 0, world.height - canvas.height);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b4636";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      // top highlight
      ctx.fillStyle = "#7a5c45";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const frame = playerFrames[player.animFrame];
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(player.w / 2, player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Legs
      ctx.fillStyle = "#444";
      ctx.fillRect(14, 44, 8, 18);
      ctx.fillRect(26, 44, 8, 18);

      // Body
      ctx.fillStyle = frame.shirt;
      ctx.fillRect(10, 18, 28, 28);

      // Head
      ctx.fillStyle = frame.body;
      ctx.fillRect(12, 0, 24, 22);

      // Eyes
      ctx.fillStyle = frame.eye;
      ctx.fillRect(18, 8, 3, 3);
      ctx.fillRect(26, 8, 3, 3);

      // Arms
      ctx.fillStyle = frame.body;
      ctx.fillRect(4, 20, 6, 18);
      ctx.fillRect(38, 20, 6, 18);

      // Shoes
      ctx.fillStyle = "#111";
      ctx.fillRect(12, 58, 10, 4);
      ctx.fillRect(26, 58, 10, 4);

      ctx.restore();
    }

    function drawBackground() {
      // Parallax hills / clouds
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Clouds
      const cloudOffset = camera.x * 0.3;
      drawCloud(150 - cloudOffset, 100);
      drawCloud(500 - cloudOffset * 0.8, 160);
      drawCloud(900 - cloudOffset * 0.6, 80);
      drawCloud(1400 - cloudOffset * 0.4, 130);

      // Distant mountains
      ctx.fillStyle = "#7da57a";
      for (let i = 0; i < 8; i++) {
        const mx = i * 400 - (camera.x * 0.2 % 400);
        ctx.beginPath();
        ctx.moveTo(mx, canvas.height - 120);
        ctx.lineTo(mx + 100, canvas.height - 260);
        ctx.lineTo(mx + 200, canvas.height - 120);
        ctx.fill();
      }
    }

    function drawCloud(x, y) {
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      ctx.beginPath();
      ctx.arc(x, y, 24, 0, Math.PI * 2);
      ctx.arc(x + 28, y - 10, 30, 0, Math.PI * 2);
      ctx.arc(x + 58, y, 22, 0, Math.PI * 2);
      ctx.arc(x + 30, y + 10, 26, 0, Math.PI * 2);
      ctx.fill();
    }

    function render() {
      drawBackground();

      // Platforms
      for (const p of platforms) {
        drawPlatform(p);
      }

      // Player
      drawPlayer();

      // Debug-ish info
      ctx.fillStyle = "black";
      ctx.font = "16px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 20);
    }

    function gameLoop() {
      update();
      render();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
