> Note: This uses simple colored rectangles for the player animation frames so it runs without external assets. You can replace the drawing logic with real sprite images later.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="ui" id="ui">Coins: 0</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const ui = document.getElementById("ui");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const TILE = 48;
    const GRAVITY = 2200;
    const MOVE_ACCEL = 2400;
    const MAX_SPEED = 420;
    const FRICTION = 1800;
    const JUMP_SPEED = 820;

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    // Level map:
    // # = solid block
    // C = coin
    // G = goal
    // P = player start
    const level = [
      "................................................................................",
      "................................................................................",
      "................................................................................",
      "................................................................................",
      "..............................................C.................................",
      ".....................###........................................................",
      "............................................................###.................",
      "...............C...............................................................G",
      "..........##########....................C..................................######",
      ".......................................................#####....................",
      "..............................................................C.................",
      ".....P............................#####..........................................",
      "####################....###########################....##########################",
    ];

    const world = {
      solids: [],
      coins: [],
      goal: null,
      width: level[0].length * TILE,
      height: level.length * TILE
    };

    let player = null;

    function buildLevel() {
      world.solids = [];
      world.coins = [];
      world.goal = null;
      player = null;

      for (let y = 0; y < level.length; y++) {
        for (let x = 0; x < level[y].length; x++) {
          const ch = level[y][x];
          const px = x * TILE;
          const py = y * TILE;

          if (ch === "#") {
            world.solids.push({ x: px, y: py, w: TILE, h: TILE });
          } else if (ch === "C") {
            world.coins.push({
              x: px + TILE / 2,
              y: py + TILE / 2,
              r: 12,
              collected: false
            });
          } else if (ch === "G") {
            world.goal = { x: px, y: py, w: TILE, h: TILE * 2 };
          } else if (ch === "P") {
            player = createPlayer(px, py);
          }
        }
      }
    }

    function createPlayer(x, y) {
      return {
        x, y,
        w: 34,
        h: 44,
        vx: 0,
        vy: 0,
        onGround: false,
        facing: 1,
        animTime: 0,
        animFrame: 0,
        coins: 0,
        won: false
      };
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids, dt) {
      // Horizontal
      entity.x += entity.vx * dt;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Vertical
      entity.y += entity.vy * dt;
      entity.onGround = false;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    function updatePlayer(dt) {
      if (player.won) return;

      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys["arrowup"] || keys[" "];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      if (!left && !right) {
        // friction
        if (player.vx > 0) {
          player.vx = Math.max(0, player.vx - FRICTION * dt);
        } else if (player.vx < 0) {
          player.vx = Math.min(0, player.vx + FRICTION * dt);
        }
      }

      player.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, player.vx));

      // gravity
      player.vy += GRAVITY * dt;

      // jump
      if (jump && player.onGround && !player.jumpLock) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
        player.jumpLock = true;
      }
      if (!jump) player.jumpLock = false;

      resolveCollisions(player, world.solids, dt);

      // fall reset
      if (player.y > world.height + 300) {
        buildLevel();
        return;
      }

      // coin pickup
      for (const coin of world.coins) {
        if (!coin.collected) {
          const dx = (player.x + player.w / 2) - coin.x;
          const dy = (player.y + player.h / 2) - coin.y;
          if (Math.hypot(dx, dy) < 28) {
            coin.collected = true;
            player.coins++;
            ui.textContent = `Coins: ${player.coins}`;
          }
        }
      }

      // goal
      if (world.goal && rectsOverlap(player, world.goal) && player.coins >= 2) {
        player.won = true;
      }

      // animation
      const moving = Math.abs(player.vx) > 20;
      if (player.onGround && moving) {
        player.animTime += dt;
        if (player.animTime > 0.12) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
      }
    }

    function drawWorld(cameraX, cameraY) {
      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      // background hills
      ctx.fillStyle = "rgba(120, 200, 120, 0.25)";
      for (let i = 0; i < 20; i++) {
        const x = i * 300 + (cameraX * 0.3) % 300;
        ctx.beginPath();
        ctx.arc(x, world.height - 40, 90, 0, Math.PI * 2);
        ctx.fill();
      }

      // solids
      for (const s of world.solids) {
        ctx.fillStyle = "#5b4b8a";
        ctx.fillRect(s.x, s.y, s.w, s.h);
        ctx.strokeStyle = "#3f3463";
        ctx.strokeRect(s.x, s.y, s.w, s.h);
      }

      // coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        ctx.save();
        ctx.translate(coin.x, coin.y);
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c89b00";
        ctx.stroke();
        ctx.restore();
      }

      // goal
      if (world.goal) {
        ctx.fillStyle = "#2ecc71";
        ctx.fillRect(world.goal.x, world.goal.y, world.goal.w, world.goal.h);
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(world.goal.x + 10, world.goal.y + 10, 18, 18);
      }

      // player
      if (player) drawPlayer(player);

      ctx.restore();
    }

    function drawPlayer(p) {
      ctx.save();
      ctx.translate(p.x + p.w / 2, p.y + p.h / 2);
      ctx.scale(p.facing, 1);

      // body
      const bob = p.onGround && Math.abs(p.vx) > 20 ? Math.sin(performance.now() * 0.02) * 2 : 0;
      ctx.translate(0, bob);

      // animation frames: simple stylized character
      const frame = p.animFrame;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.18)";
      ctx.beginPath();
      ctx.ellipse(0, p.h / 2 - 2, 16, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // legs
      ctx.fillStyle = "#2c3e50";
      if (frame === 0) {
        ctx.fillRect(-10, 8, 8, 18);
        ctx.fillRect(2, 8, 8, 18);
      } else if (frame === 1) {
        ctx.fillRect(-11, 8, 8, 18);
        ctx.fillRect(3, 8, 8, 18);
      } else if (frame === 2) {
        ctx.fillRect(-9, 8, 8, 18);
        ctx.fillRect(1, 8, 8, 18);
      } else {
        ctx.fillRect(-10, 8, 8, 18);
        ctx.fillRect(2, 8, 8, 18);
      }

      // torso
      ctx.fillStyle = "#e74c3c";
      ctx.fillRect(-14, -10, 28, 22);

      // head
      ctx.fillStyle = "#f1c27d";
      ctx.beginPath();
      ctx.arc(0, -22, 12, 0, Math.PI * 2);
      ctx.fill();

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(4, -25, 3, 3);
      ctx.fillRect(-7, -25, 3, 3);

      // arms
      ctx.strokeStyle = "#f1c27d";
      ctx.lineWidth = 4;
      ctx.beginPath();
      if (frame === 1) {
        ctx.moveTo(-14, -2); ctx.lineTo(-22, 8);
        ctx.moveTo(14, -2); ctx.lineTo(22, 8);
      } else if (frame === 2) {
        ctx.moveTo(-14, -2); ctx.lineTo(-20, 14);
        ctx.moveTo(14, -2); ctx.lineTo(18, 10);
      } else {
        ctx.moveTo(-14, -2); ctx.lineTo(-18, 10);
        ctx.moveTo(14, -2); ctx.lineTo(20, 14);
      }
      ctx.stroke();

      ctx.restore();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      if (player) updatePlayer(dt);

      // camera
      let cameraX = 0;
      let cameraY = 0;
      if (player) {
        cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x + player.w / 2 - canvas.width / 2));
        cameraY = Math.max(0, Math.min(world.height - canvas.height, player.y + player.h / 2 - canvas.height / 2));
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawWorld(cameraX, cameraY);

      // win text
      if (player && player.won) {
        ctx.save();
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "24px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 40);
        ctx.restore();
      }

      requestAnimationFrame(loop);
    }

    buildLevel();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
