<script>
(() => {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");

  const W = canvas.width;
  const H = canvas.height;

  const keys = {};
  addEventListener("keydown", e => {
    keys[e.key.toLowerCase()] = true;
    if (e.key.toLowerCase() === "r") resetGame();
  });
  addEventListener("keyup", e => {
    keys[e.key.toLowerCase()] = false;
  });

  // --- World ---
  const world = {
    gravity: 1800,
    friction: 0.82,
    airDrag: 0.99,
    cameraX: 0,
    cameraY: 0,
    width: 3200,
    height: 1200
  };

  const platforms = [
    { x: 0, y: 500, w: 900, h: 40 },
    { x: 980, y: 430, w: 220, h: 30 },
    { x: 1280, y: 360, w: 220, h: 30 },
    { x: 1600, y: 300, w: 260, h: 30 },
    { x: 1960, y: 420, w: 260, h: 30 },
    { x: 2300, y: 350, w: 180, h: 30 },
    { x: 2600, y: 280, w: 220, h: 30 },
    { x: 2900, y: 420, w: 260, h: 30 },

    // ground segments
    { x: 900, y: 500, w: 120, h: 40 },
    { x: 1200, y: 500, w: 80, h: 40 },
    { x: 1500, y: 500, w: 100, h: 40 },
    { x: 1860, y: 500, w: 100, h: 40 },
    { x: 2220, y: 500, w: 80, h: 40 },
    { x: 2480, y: 500, w: 120, h: 40 },
    { x: 2820, y: 500, w: 140, h: 40 },
    { x: 3060, y: 500, w: 140, h: 40 }
  ];

  const coins = [
    { x: 150, y: 450, collected: false },
    { x: 260, y: 450, collected: false },
    { x: 1030, y: 390, collected: false },
    { x: 1320, y: 320, collected: false },
    { x: 1640, y: 260, collected: false },
    { x: 2000, y: 380, collected: false },
    { x: 2340, y: 310, collected: false },
    { x: 2640, y: 240, collected: false },
    { x: 2940, y: 380, collected: false }
  ];

  const enemies = [
    { x: 1080, y: 400, w: 28, h: 28, vx: 70, minX: 1000, maxX: 1180, alive: true },
    { x: 2050, y: 390, w: 28, h: 28, vx: 90, minX: 1980, maxX: 2200, alive: true },
    { x: 2680, y: 250, w: 28, h: 28, vx: 100, minX: 2600, maxX: 2790, alive: true }
  ];

  const player = {
    x: 50,
    y: 420,
    w: 28,
    h: 40,
    vx: 0,
    vy: 0,
    speed: 420,
    jumpPower: 720,
    onGround: false,
    facing: 1,
    animTime: 0,
    dead: false,
    score: 0
  };

  let gameOver = false;
  let win = false;

  function resetGame() {
    player.x = 50;
    player.y = 420;
    player.vx = 0;
    player.vy = 0;
    player.onGround = false;
    player.facing = 1;
    player.animTime = 0;
    player.dead = false;
    player.score = 0;

    coins.forEach(c => c.collected = false);
    enemies.forEach(e => e.alive = true);

    gameOver = false;
    win = false;
  }

  // --- Collision helpers ---
  function rectsIntersect(a, b) {
    return (
      a.x < b.x + b.w &&
      a.x + a.w > b.x &&
      a.y < b.y + b.h &&
      a.y + a.h > b.y
    );
  }

  function resolvePlatformCollision(entity, platform) {
    const prevX = entity.prevX;
    const prevY = entity.prevY;

    const wasAbove = prevY + entity.h <= platform.y;
    const wasBelow = prevY >= platform.y + platform.h;
    const wasLeft = prevX + entity.w <= platform.x;
    const wasRight = prevX >= platform.x + platform.w;

    if (!rectsIntersect(entity, platform)) return;

    // Determine collision side by previous position
    if (wasAbove) {
      entity.y = platform.y - entity.h;
      entity.vy = 0;
      entity.onGround = true;
    } else if (wasBelow) {
      entity.y = platform.y + platform.h;
      entity.vy = 0;
    } else if (wasLeft) {
      entity.x = platform.x - entity.w;
      entity.vx = 0;
    } else if (wasRight) {
      entity.x = platform.x + platform.w;
      entity.vx = 0;
    } else {
      // fallback: push out vertically
      const overlapLeft = (entity.x + entity.w) - platform.x;
      const overlapRight = (platform.x + platform.w) - entity.x;
      const overlapTop = (entity.y + entity.h) - platform.y;
      const overlapBottom = (platform.y + platform.h) - entity.y;
      const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

      if (minOverlap === overlapTop) {
        entity.y = platform.y - entity.h;
        entity.vy = 0;
        entity.onGround = true;
      } else if (minOverlap === overlapBottom) {
        entity.y = platform.y + platform.h;
        entity.vy = 0;
      } else if (minOverlap === overlapLeft) {
        entity.x = platform.x - entity.w;
        entity.vx = 0;
      } else {
        entity.x = platform.x + platform.w;
        entity.vx = 0;
      }
    }
  }

  // --- Sprite sheet generation ---
  // Creates a simple animated character sheet procedurally.
  const spriteCanvas = document.createElement("canvas");
  spriteCanvas.width = 128;
  spriteCanvas.height = 64;
  const sctx = spriteCanvas.getContext("2d");

  function drawFrame(frame, flip = false) {
    sctx.clearRect(0, 0, spriteCanvas.width, spriteCanvas.height);
    sctx.save();
    if (flip) {
      sctx.translate(64, 0);
      sctx.scale(-1, 1);
    }

    const x = frame * 32;
    const bob = frame === 1 ? 2 : 0;

    // body
    sctx.fillStyle = "#2b2f3a";
    sctx.fillRect(x + 10, 16 + bob, 12, 16);

    // head
    sctx.fillStyle = "#ffd6b0";
    sctx.fillRect(x + 11, 6 + bob, 10, 10);

    // eyes
    sctx.fillStyle = "#222";
    sctx.fillRect(x + 13, 9 + bob, 2, 2);
    sctx.fillRect(x + 17, 9 + bob, 2, 2);

    // legs
    sctx.fillStyle = "#3d4b7a";
    if (frame === 1) {
      sctx.fillRect(x + 10, 32 + bob, 5, 8);
      sctx.fillRect(x + 17, 30 + bob, 5, 10);
    } else if (frame === 2) {
      sctx.fillRect(x + 9, 30 + bob, 5, 10);
      sctx.fillRect(x + 18, 32 + bob, 5, 8);
    } else {
      sctx.fillRect(x + 10, 31 + bob, 5, 9);
      sctx.fillRect(x + 17, 31 + bob, 5, 9);
    }

    // arms
    sctx.fillStyle = "#2b2f3a";
    if (frame === 1) {
      sctx.fillRect(x + 5, 18 + bob, 5, 4);
      sctx.fillRect(x + 22, 20 + bob, 5, 4);
    } else if (frame === 2) {
      sctx.fillRect(x + 5, 20 + bob, 5, 4);
      sctx.fillRect(x + 22, 18 + bob, 5, 4);
    } else {
      sctx.fillRect(x + 5, 19 + bob, 5, 4);
      sctx.fillRect(x + 22, 19 + bob, 5, 4);
    }

    sctx.restore();
  }

  // --- Update ---
  let lastTime = performance.now();

  function update(dt) {
    if (gameOver || win) return;

    // Input
    const left = keys["a"] || keys["arrowleft"];
    const right = keys["d"] || keys["arrowright"];
    const jump = keys[" "] || keys["w"] || keys["arrowup"];

    if (left) {
      player.vx = Math.max(player.vx - player.speed * dt, -player.speed);
      player.facing = -1;
    }
    if (right) {
      player.vx = Math.min(player.vx + player.speed * dt, player.speed);
      player.facing = 1;
    }

    if (!left && !right) {
      player.vx *= player.onGround ? world.friction : world.airDrag;
      if (Math.abs(player.vx) < 1) player.vx = 0;
    }

    if (jump && player.onGround) {
      player.vy = -player.jumpPower;
      player.onGround = false;
    }

    // Save previous position for collision resolution
    player.prevX = player.x;
    player.prevY = player.y;

    // Physics
    player.vy += world.gravity * dt;
    player.x += player.vx * dt;
    player.y += player.vy * dt;

    // World bounds
    player.x = Math.max(0, Math.min(world.width - player.w, player.x));
    if (player.y > world.height) {
      gameOver = true;
      return;
    }

    // Platform collisions
    player.onGround = false;
    for (const p of platforms) resolvePlatformCollision(player, p);

    // Coins
    for (const c of coins) {
      if (!c.collected) {
        const coinBox = { x: c.x - 10, y: c.y - 10, w: 20, h: 20 };
        if (rectsIntersect(player, coinBox)) {
          c.collected = true;
          player.score += 1;
        }
      }
    }

    // Enemies
    for (const e of enemies) {
      if (!e.alive) continue;

      e.prevX = e.x;
      e.prevY = e.y;
      e.x += e.vx * dt;

      if (e.x < e.minX) {
        e.x = e.minX;
        e.vx *= -1;
      }
      if (e.x > e.maxX) {
        e.x = e.maxX;
        e.vx *= -1;
      }

      // Keep enemies on platforms
      e.vy = (e.vy || 0) + world.gravity * dt;
      e.y += e.vy * dt;
      e.onGround = false;
      for (const p of platforms) resolvePlatformCollision(e, p);

      // Player/enemy interaction
      if (rectsIntersect(player, e)) {
        const playerBottomPrev = player.prevY + player.h;
        const enemyTop = e.y;
        if (playerBottomPrev <= enemyTop + 4 && player.vy > 0) {
          // stomp
          e.alive = false;
          player.vy = -player.jumpPower * 0.55;
        } else {
          gameOver = true;
        }
      }
    }

    // Win condition
    if (player.score === coins.length) {
      win = true;
    }

    // Animation
    if (Math.abs(player.vx) > 5 && player.onGround) {
      player.animTime += dt * 12;
    } else {
      player.animTime += dt * 4;
    }

    // Camera
    world.cameraX = player.x + player.w / 2 - W / 2;
    world.cameraX = Math.max(0, Math.min(world.width - W, world.cameraX));
  }

  // --- Draw ---
  function drawBackground() {
    // Parallax hills
    const cam = world.cameraX;
    ctx.save();

    // clouds
    ctx.fillStyle = "rgba(255,255,255,0.6)";
    for (let i = 0; i < 8; i++) {
      const cx = ((i * 260) - cam * 0.25) % (world.width + 400) - 200;
      const cy = 70 + (i % 3) * 30;
      ctx.beginPath();
      ctx.arc(cx, cy, 24, 0, Math.PI * 2);
      ctx.arc(cx + 22, cy + 8, 20, 0, Math.PI * 2);
      ctx.arc(cx - 22, cy + 10, 18, 0, Math.PI * 2);
      ctx.fill();
    }

    // distant mountains
    ctx.fillStyle = "#6bb26f";
    for (let i = 0; i < 6; i++) {
      const mx = i * 520 - (cam * 0.35 % 520);
      ctx.beginPath();
      ctx.moveTo(mx, 420);
      ctx.lineTo(mx + 140, 240);
      ctx.lineTo(mx + 280, 420);
      ctx.fill();
    }

    ctx.restore();
  }

  function drawPlatform(p) {
    const x = p.x - world.cameraX;
    const y = p.y - world.cameraY;
    ctx.fillStyle = "#4b3b2a";
    ctx.fillRect(x, y, p.w, p.h);
    ctx.fillStyle = "#6b4f31";
    ctx.fillRect(x, y, p.w, 8);
  }

  function drawCoin(c) {
    if (c.collected) return;
    const x = c.x - world.cameraX;
    const y = c.y - world.cameraY;
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = "#ffd54a";
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#ffb300";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.restore();
  }

  function drawEnemy(e) {
    if (!e.alive) return;
    const x = e.x - world.cameraX;
    const y = e.y - world.cameraY;
    ctx.fillStyle = "#d94b4b";
    ctx.fillRect(x, y, e.w, e.h);
    ctx.fillStyle = "#fff";
    ctx.fillRect(x + 6, y + 8, 4, 4);
    ctx.fillRect(x + 18, y + 8, 4, 4);
    ctx.fillStyle = "#222";
    ctx.fillRect(x + 8, y + 10, 2, 2);
    ctx.fillRect(x + 20, y + 10, 2, 2);
  }

  function drawPlayer() {
    const frame = player.onGround
      ? (Math.floor(player.animTime) % 3)
      : 1;

    drawFrame(frame, player.facing < 0);

    const sx = player.facing < 0 ? 32 : 0;
    const dx = Math.floor(player.x - world.cameraX);
    const dy = Math.floor(player.y - world.cameraY);

    ctx.save();
    if (player.facing < 0) {
      ctx.translate(dx + player.w, dy);
      ctx.scale(-1, 1);
      ctx.drawImage(spriteCanvas, sx, 0, 32, 64, 0, -12, 32, 64);
    } else {
      ctx.drawImage(spriteCanvas, sx, 0, 32, 64, dx - 2, dy - 12, 32, 64);
    }
    ctx.restore();
  }

  function drawHUD() {
    ctx.fillStyle = "rgba(0,0,0,0.35)";
    ctx.fillRect(12, H - 52, 160, 36);
    ctx.fillStyle = "white";
    ctx.font = "20px sans-serif";
    ctx.fillText(`Coins: ${player.score}/${coins.length}`, 22, H - 28);

    if (gameOver || win) {
      ctx.fillStyle = "rgba(0,0,0,0.65)";
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.font = "bold 54px sans-serif";
      ctx.fillText(win ? "YOU WIN!" : "GAME OVER", W / 2, H / 2 - 20);
      ctx.font = "24px sans-serif";
      ctx.fillText("Press R to restart", W / 2, H / 2 + 24);
      ctx.textAlign = "left";
    }
  }

  function render() {
    ctx.clearRect(0, 0, W, H);
    drawBackground();

    // Platforms
    for (const p of platforms) drawPlatform(p);

    // Coins
    for (const c of coins) drawCoin(c);

    // Enemies
    for (const e of enemies) drawEnemy(e);

    // Player
    drawPlayer();

    // Simple ground haze
    const grad = ctx.createLinearGradient(0, H - 80, 0, H);
    grad.addColorStop(0, "rgba(0,0,0,0)");
    grad.addColorStop(1, "rgba(0,0,0,0.18)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, H - 80, W, 80);

    drawHUD();
  }

  function loop(now) {
    const dt = Math.min(0.033, (now - lastTime) / 1000);
    lastTime = now;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  resetGame();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
