      { x: 900, y: 430, r: 14, collected: false },
      { x: 1540, y: 350, r: 14, collected: false },
      { x: 2140, y: 290, r: 14, collected: false },
      { x: 2950, y: 390, r: 14, collected: false },
      { x: 3740, y: 320, r: 14, collected: false },
      { x: 4500, y: 650, r: 14, collected: false }
    ];

    const goal = {
      x: 4750,
      y: 620,
      w: 40,
      h: 80
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function update(dt) {
      // Input
      let moving = false;
      if (keys["a"] || keys["arrowleft"]) {
        player.vx = -MOVE_SPEED;
        player.facing = -1;
        moving = true;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx = MOVE_SPEED;
        player.facing = 1;
        moving = true;
      }

      if (!moving) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      if ((keys["w"] || keys[" "] || keys["arrowup"]) && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Horizontal movement + collision
      player.x += player.vx * dt;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement + collision
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep player in world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        // reset if fall off
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Collect coins
      for (const c of coins) {
        if (!c.collected && circleRectCollision(c, player)) {
          c.collected = true;
          player.coins++;
        }
      }

      // Goal check
      if (rectsOverlap(player, goal)) {
        alert(`You win! Coins collected: ${player.coins}`);
        resetGame();
      }

      // Animation timer
      if (Math.abs(player.vx) > 10 && player.onGround) {
        player.animTime += dt * 12;
      } else {
        player.animTime += dt * 4;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      hud.textContent = `Coins: ${player.coins}`;
    }

    function resetGame() {
      player.x = 100;
      player.y = 200;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      player.coins = 0;
      player.animTime = 0;
      coins = coins.map(c => ({ ...c, collected: false }));
    }

    // --- Procedural sprite animation ---
    function drawPlayer(x, y) {
      const frame = Math.floor(player.animTime) % 4;
      const flip = player.facing === -1;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(flip ? -1 : 1, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.fillRect(10, 54, 28, 8);

      // head
      ctx.fillStyle = "#ffd6b0";
      ctx.beginPath();
      ctx.arc(24, 16, 12, 0, Math.PI * 2);
      ctx.fill();

      // hair
      ctx.fillStyle = "#3b2f2f";
      ctx.beginPath();
      ctx.arc(24, 12, 12, Math.PI, 0);
      ctx.fill();

      // torso
      ctx.fillStyle = "#4b7bec";
      ctx.fillRect(14, 26, 20, 22);

      // arms
      ctx.strokeStyle = "#ffd6b0";
      ctx.lineWidth = 5;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(14, 30);
      ctx.lineTo(6, 40 + (frame === 1 ? 3 : 0));
      ctx.moveTo(34, 30);
      ctx.lineTo(42, 40 + (frame === 2 ? 3 : 0));
      ctx.stroke();

      // legs animation
      ctx.strokeStyle = "#2d3436";
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(20, 48);
      ctx.lineTo(16 + (frame === 0 ? -3 : frame === 2 ? 3 : 0), 62);
      ctx.moveTo(28, 48);
      ctx.lineTo(32 + (frame === 1 ? 3 : frame === 3 ? -3 : 0), 62);
      ctx.stroke();

      // shoes
      ctx.fillStyle = "#111";
      ctx.fillRect(12 + (frame === 0 ? -3 : frame === 2 ? 3 : 0), 60, 10, 4);
      ctx.fillRect(28 + (frame === 1 ? 3 : frame === 3 ? -3 : 0), 60, 10, 4);

      ctx.restore();
    }

    function drawCoin(c) {
      if (c.collected) return;
      const t = performance.now() * 0.005;
      const scale = 0.8 + 0.2 * Math.sin(t + c.x * 0.01);

      ctx.save();
      ctx.translate(c.x, c.y);
      ctx.scale(scale, 1);

      ctx.fillStyle = "#f1c40f";
      ctx.beginPath();
      ctx.arc(0, 0, c.r, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#d4ac0d";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, c.r - 3, 0, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = "rgba(255,255,255,0.35)";
      ctx.beginPath();
      ctx.arc(-4, -4, 4, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6c5ce7";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "rgba(255,255,255,0.15)";
      ctx.fillRect(p.x, p.y, p.w, 6);
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.fillRect(p.x, p.y + p.h - 6, p.w, 6);
    }

    function drawGoal(g) {
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(g.x, g.y, g.w, g.h);
      ctx.fillStyle = "#27ae60";
      ctx.fillRect(g.x + 8, g.y + 8, g.w - 16, g.h - 16);
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.moveTo(g.x + g.w, g.y + 10);
      ctx.lineTo(g.x + g.w + 40, g.y + 20);
      ctx.lineTo(g.x + g.w, g.y + 30);
      ctx.closePath();
      ctx.fill();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, -camera.y * 0.2);
      ctx.fillStyle = "#8fd694";
      for (let i = 0; i < 20; i++) {
        ctx.beginPath();
        ctx.arc(i * 350 + 100, 760, 180, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // World transform
      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Coins
      for (const c of coins) drawCoin(c);

      // Goal
      drawGoal(goal);

      // Player
      drawPlayer(player.x, player.y);

      ctx.restore();

      // Instructions
      ctx.fillStyle = "white";
      ctx.font = "16px Arial";
      ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Space / Arrow Up", 12, canvas.height - 18);
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

