```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#7ec8ff, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      padding: 8px 12px;
      background: rgba(0,0,0,0.35);
      border-radius: 8px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: W/Space/↑ | Restart: R
    <div id="status"></div>
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
      if (["arrowup", "arrowleft", "arrowright", " "].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
      if (e.key.toLowerCase() === "r") resetGame();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- World ---
    const gravity = 2200;
    const moveSpeed = 360;
    const jumpSpeed = 820;
    const friction = 0.82;

    const world = {
      width: 3200,
      height: 1400
    };

    const platforms = [
      { x: 0, y: 1320, w: 3200, h: 80 },
      { x: 200, y: 1180, w: 220, h: 30 },
      { x: 520, y: 1080, w: 250, h: 30 },
      { x: 900, y: 980, w: 260, h: 30 },
      { x: 1250, y: 900, w: 240, h: 30 },
      { x: 1600, y: 1030, w: 300, h: 30 },
      { x: 2050, y: 930, w: 220, h: 30 },
      { x: 2400, y: 820, w: 270, h: 30 },
      { x: 2800, y: 700, w: 220, h: 30 }
    ];

    const coins = [
      { x: 290, y: 1120, r: 12, collected: false },
      { x: 610, y: 1020, r: 12, collected: false },
      { x: 980, y: 920, r: 12, collected: false },
      { x: 1340, y: 840, r: 12, collected: false },
      { x: 1710, y: 970, r: 12, collected: false },
      { x: 2140, y: 870, r: 12, collected: false },
      { x: 2520, y: 760, r: 12, collected: false },
      { x: 2890, y: 640, r: 12, collected: false }
    ];

    const enemies = [
      { x: 700, y: 1040, w: 40, h: 40, vx: 120, minX: 560, maxX: 740 },
      { x: 1700, y: 990, w: 40, h: 40, vx: 140, minX: 1600, maxX: 1860 },
      { x: 2550, y: 780, w: 40, h: 40, vx: 160, minX: 2430, maxX: 2650 }
    ];

    const player = {
      x: 80,
      y: 1200,
      w: 44,
      h: 60,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle", // idle, run, jump, fall
      lives: 3,
      score: 0
    };

    let camera = { x: 0, y: 0 };
    let gameOver = false;

    // --- Generate a simple sprite sheet on an offscreen canvas ---
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 256;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frameIndex) {
      const x = frameIndex * 64;
      sctx.clearRect(x, 0, 64, 64);

      // body
      sctx.fillStyle = "#2d2dff";
      sctx.fillRect(x + 22, 24, 20, 24);

      // head
      sctx.fillStyle = "#ffd39b";
      sctx.beginPath();
      sctx.arc(x + 32, 16, 12, 0, Math.PI * 2);
      sctx.fill();

      // legs/arms vary slightly per frame
      sctx.strokeStyle = "#111";
      sctx.lineWidth = 4;
      sctx.lineCap = "round";

      // arms
      sctx.beginPath();
      sctx.moveTo(x + 22, 30);
      sctx.lineTo(x + 12 + (frameIndex % 2 ? 2 : -2), 38);
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(x + 42, 30);
      sctx.lineTo(x + 52 + (frameIndex % 2 ? -2 : 2), 38);
      sctx.stroke();

      // legs
      sctx.beginPath();
      sctx.moveTo(x + 26, 48);
      sctx.lineTo(x + 20 + (frameIndex % 2 ? 3 : -3), 60);
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(x + 38, 48);
      sctx.lineTo(x + 44 + (frameIndex % 2 ? -3 : 3), 60);
      sctx.stroke();
    }

    for (let i = 0; i < 4; i++) drawFrame(i);

    // --- Utility ---
    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function resetGame() {
      player.x = 80;
      player.y = 1200;
      player.vx = 0;
      player.vy = 0;
      player.lives = 3;
      player.score = 0;
      player.onGround = false;
      gameOver = false;

      coins.forEach(c => c.collected = false);
      enemies[0].x = 700;
      enemies[1].x = 1700;
      enemies[2].x = 2550;
    }

    // --- Physics & Collision ---
    function moveAndCollide(entity, dt) {
      // X axis
      entity.x += entity.vx * dt;
      for (const p of platforms) {
        if (rectsIntersect(entity, p)) {
          if (entity.vx > 0) entity.x = p.x - entity.w;
          else if (entity.vx < 0) entity.x = p.x + p.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      entity.onGround = false;

      for (const p of platforms) {
        if (rectsIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    function updatePlayer(dt) {
      if (gameOver) return;

      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys["arrowup"] || keys[" "];

      if (left) {
        player.vx = Math.max(player.vx - 2200 * dt, -moveSpeed);
        player.facing = -1;
      } else if (right) {
        player.vx = Math.min(player.vx + 2200 * dt, moveSpeed);
        player.facing = 1;
      } else {
        player.vx *= Math.pow(friction, dt * 60);
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = -jumpSpeed;
        player.onGround = false;
      }

      player.vy += gravity * dt;
      if (player.vy > 1400) player.vy = 1400;

      moveAndCollide(player, dt);

      // Determine animation state
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;

      // Collect coins
      for (const coin of coins) {
        if (!coin.collected && circleRectCollision(coin, player)) {
          coin.collected = true;
          player.score += 10;
        }
      }

      // Enemy collisions
      for (const enemy of enemies) {
        if (rectsIntersect(player, enemy)) {
          const playerBottomBefore = player.y + player.h - player.vy * dt;
          const enemyTop = enemy.y;
          if (playerBottomBefore <= enemyTop + 10 && player.vy > 0) {
            // Stomp enemy
            player.vy = -550;
            enemy.x = enemy.minX;
            player.score += 25;
          } else {
            player.lives -= 1;
            player.x = 80;
            player.y = 1200;
            player.vx = 0;
            player.vy = 0;
            if (player.lives <= 0) gameOver = true;
          }
        }
      }

      // Fall off map
      if (player.y > world.height + 200) {
        player.lives -= 1;
        player.x = 80;
        player.y = 1200;
        player.vx = 0;
        player.vy = 0;
        if (player.lives <= 0) gameOver = true;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function updateEnemies(dt) {
      for (const enemy of enemies) {
        enemy.x += enemy.vx * dt;
        if (enemy.x < enemy.minX) {
          enemy.x = enemy.minX;
          enemy.vx *= -1;
        }
        if (enemy.x > enemy.maxX) {
          enemy.x = enemy.maxX;
          enemy.vx *= -1;
        }
      }
    }

    // --- Rendering ---
    function drawBackground() {
      // Parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.2, 0);
      ctx.fillStyle = "#8fd18f";
      for (let i = 0; i < 12; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 300 + 150, canvas.height - 120, 180, 70, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // Clouds
      ctx.save();
      ctx.translate(-camera.x * 0.5, -camera.y * 0.2);
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      for (let i = 0; i < 10; i++) {
        const x = i * 380 + 40;
        const y = 80 + (i % 3) * 60;
        ctx.beginPath();
        ctx.arc(x, y, 26, 0, Math.PI * 2);
        ctx.arc(x + 26, y - 10, 34, 0, Math.PI * 2);
        ctx.arc(x + 58, y, 24, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawCoins() {
      for (const coin of coins) {
        if (coin.collected) continue;
        ctx.save();
        ctx.translate(coin.x - camera.x, coin.y - camera.y);
        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#fff3a0";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, coin.r - 4, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }
    }

    function drawEnemies() {
      for (const enemy of enemies) {
        ctx.fillStyle = "#c0392b";
        ctx.fillRect(enemy.x - camera.x, enemy.y - camera.y, enemy.w, enemy.h);
        ctx.fillStyle = "#fff";
        ctx.fillRect(enemy.x - camera.x + 10, enemy.y - camera.y + 10, 6, 6);
        ctx.fillRect(enemy.x - camera.x + 24, enemy.y - camera.y + 10, 6, 6);
        ctx.fillStyle = "#111";
        ctx.fillRect(enemy.x - camera.x + 12, enemy.y - camera.y + 28, 16, 4);
      }
    }

    function drawPlayer() {
      let frame = 0;
      if (player.state === "idle") frame = 0;
      if (player.state === "run") frame = 1 + (Math.floor(player.animTime * 12) % 2);
      if (player.state === "jump") frame = 3;
      if (player.state === "fall") frame = 2;

      ctx.save();
      ctx.translate(player.x - camera.x + player.w / 2, player.y - camera.y);
      if (player.facing === -1) ctx.scale(-1, 1);

      ctx.drawImage(
        spriteCanvas,
        frame * 64, 0, 64, 64,
        -32, 0, 64, 64
      );
      ctx.restore();
    }

    function drawUI() {
      statusEl.textContent = `Score: ${player.score} | Lives: ${player.lives}${gameOver ? " | GAME OVER - Press R" : ""}`;
      if (gameOver) {
        ctx.save();
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.textAlign = "center";
        ctx.font = "bold 56px sans-serif";
        ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 20);
        ctx.font = "24px sans-serif";
        ctx.fillText("Press R to restart", canvas.width / 2, canvas.height / 2 + 30);
        ctx.restore();
      }
    }

    // --- Main loop ---
    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      updatePlayer(dt);
      updateEnemies(dt);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawEnemies();
      drawPlayer();
      drawUI();

      requestAnimationFrame(loop);
    }

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

