```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: Space / W / ↑
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const WORLD = {
      width: 3200,
      height: 1200
    };

    const GRAVITY = 2200;
    const MOVE_SPEED = 420;
    const JUMP_SPEED = 820;
    const FRICTION = 0.82;

    const player = {
      x: 100,
      y: 200,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    const platforms = [
      { x: 0, y: 500, w: 900, h: 40 },
      { x: 980, y: 430, w: 220, h: 30 },
      { x: 1280, y: 360, w: 260, h: 30 },
      { x: 1650, y: 460, w: 260, h: 30 },
      { x: 2000, y: 390, w: 220, h: 30 },
      { x: 2300, y: 320, w: 220, h: 30 },
      { x: 2600, y: 450, w: 500, h: 40 },
      { x: 700, y: 620, w: 260, h: 30 },
      { x: 1100, y: 700, w: 260, h: 30 },
      { x: 1500, y: 760, w: 260, h: 30 },
      { x: 1900, y: 820, w: 260, h: 30 },
      { x: 2400, y: 880, w: 260, h: 30 }
    ];

    const coins = [
      { x: 1040, y: 380, r: 10, collected: false },
      { x: 1350, y: 310, r: 10, collected: false },
      { x: 1710, y: 410, r: 10, collected: false },
      { x: 2050, y: 340, r: 10, collected: false },
      { x: 2350, y: 270, r: 10, collected: false }
    ];

    let score = 0;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = clamp(circle.x, rect.x, rect.x + rect.w);
      const cy = clamp(circle.y, rect.y, rect.y + rect.h);
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    // Simple animated player drawing
    function drawPlayer(ctx, p, t) {
      const walkFrame = Math.floor(t * 12) % 4;
      const idleBob = Math.sin(t * 6) * 2;

      ctx.save();
      ctx.translate(p.x + p.w / 2, p.y + p.h / 2 + idleBob);
      ctx.scale(p.facing, 1);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, p.h / 2 - 2, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(-16, -18, 32, 28);

      // Head
      ctx.fillStyle = "#ffd9b3";
      ctx.beginPath();
      ctx.arc(0, -30, 14, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(4, -33, 3, 3);
      ctx.fillRect(-7, -33, 3, 3);

      // Legs animation
      ctx.strokeStyle = "#333";
      ctx.lineWidth = 5;
      ctx.lineCap = "round";

      if (p.onGround && p.state === "run") {
        const legSwing = [0.8, -0.8, 0.8, -0.8][walkFrame];
        ctx.beginPath();
        ctx.moveTo(-8, 10);
        ctx.lineTo(-12, 24 + legSwing * 4);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(8, 10);
        ctx.lineTo(12, 24 - legSwing * 4);
        ctx.stroke();
      } else {
        ctx.beginPath();
        ctx.moveTo(-8, 10);
        ctx.lineTo(-10, 24);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(8, 10);
        ctx.lineTo(10, 24);
        ctx.stroke();
      }

      // Arms
      ctx.beginPath();
      ctx.moveTo(-16, -5);
      ctx.lineTo(-26, 4);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(16, -5);
      ctx.lineTo(26, 4);
      ctx.stroke();

      ctx.restore();
    }

    function update(dt) {
      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      if (move !== 0) {
        player.vx = move * MOVE_SPEED;
        player.facing = move;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 8) player.vx = 0;
      }

      // Jump
      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Physics
      player.vy += GRAVITY * dt;

      let nextX = player.x + player.vx * dt;
      let nextY = player.y + player.vy * dt;

      // Horizontal collision
      let temp = { x: nextX, y: player.y, w: player.w, h: player.h };
      for (const platform of platforms) {
        if (rectsOverlap(temp, platform)) {
          if (player.vx > 0) nextX = platform.x - player.w;
          else if (player.vx < 0) nextX = platform.x + platform.w;
          player.vx = 0;
          temp.x = nextX;
        }
      }

      // Vertical collision
      player.onGround = false;
      temp = { x: nextX, y: nextY, w: player.w, h: player.h };
      for (const platform of platforms) {
        if (rectsOverlap(temp, platform)) {
          if (player.vy > 0) {
            nextY = platform.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            nextY = platform.y + platform.h;
            player.vy = 0;
          }
          temp.y = nextY;
        }
      }

      player.x = nextX;
      player.y = nextY;

      // World bounds
      player.x = clamp(player.x, 0, WORLD.width - player.w);
      if (player.y > WORLD.height) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Coins
      for (const coin of coins) {
        if (!coin.collected && circleRectCollision(coin, player)) {
          coin.collected = true;
          score += 1;
        }
      }

      // Animation state
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;
    }

    function drawBackground(cameraX, cameraY) {
      // Parallax hills
      ctx.fillStyle = "#6cc06c";
      for (let i = 0; i < 12; i++) {
        const x = (i * 300 - cameraX * 0.3) % (WORLD.width + 300) - 300;
        ctx.beginPath();
        ctx.ellipse(x + 150, 420, 180, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      for (let i = 0; i < 7; i++) {
        const x = (i * 500 - cameraX * 0.15) % (WORLD.width + 500) - 500;
        const y = 70 + (i % 3) * 40;
        ctx.beginPath();
        ctx.ellipse(x + 60, y, 40, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 95, y + 5, 55, 28, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 130, y, 40, 22, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const cameraX = clamp(player.x + player.w / 2 - canvas.width / 2, 0, WORLD.width - canvas.width);
      const cameraY = clamp(player.y + player.h / 2 - canvas.height / 2, 0, WORLD.height - canvas.height);

      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      drawBackground(cameraX, cameraY);

      // Platforms
      for (const platform of platforms) {
        ctx.fillStyle = "#4b3f72";
        ctx.fillRect(platform.x, platform.y, platform.w, platform.h);
        ctx.fillStyle = "#6f5aa8";
        ctx.fillRect(platform.x, platform.y, platform.w, 8);
      }

      // Coins
      for (const coin of coins) {
        if (coin.collected) continue;
        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(coin.x, coin.y, coin.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#ffef9a";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(coin.x, coin.y, coin.r - 3, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Player
      drawPlayer(ctx, player, player.animTime);

      ctx.restore();

      // HUD
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Score: ${score}/${coins.length}`, 20, 50);

      if (score === coins.length) {
        ctx.fillStyle = "rgba(0,0,0,0.65)";
        ctx.fillRect(canvas.width / 2 - 180, 90, 360, 70);
        ctx.fillStyle = "#fff";
        ctx.font = "24px sans-serif";
        ctx.fillText("You collected all coins!", canvas.width / 2 - 145, 132);
      }
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      update(dt);
      draw();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
