<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
