<body>
  <div class="hud">
    Move: A/D or ←/→<br/>
    Jump: Space / W / ↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    // --- World / Physics constants ---
    const GRAVITY = 1800;
    const MOVE_SPEED = 320;
    const JUMP_VELOCITY = 720;
    const FRICTION = 0.82;

    const TILE = 48;

    // --- Level data (simple tile map) ---
    // # = solid block, . = empty
    const level = [
      "........................................",
      "........................................",
      "........................................",
      "........................................",
      ".......................###..............",
      "..............###.......................",
      "........................................",
      "....###................................#",
      "........................................",
      "....................####................",
      "........................................",
      "###########......................########",
    ];

    const solids = [];
    for (let y = 0; y < level.length; y++) {
      for (let x = 0; x < level[y].length; x++) {
        if (level[y][x] === "#") {
          solids.push({
            x: x * TILE,
            y: y * TILE,
            w: TILE,
            h: TILE
          });
        }
      }
    }

    // --- Player ---
    const player = {
      x: 100,
      y: 100,
      w: 34,
      h: 42,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0
    };

    // --- Simple sprite animation frames ---
    // We'll draw a stylized character using canvas shapes.
    function drawPlayer(ctx, p) {
      const frame = p.animFrame;
      const bob = p.onGround && Math.abs(p.vx) > 10 ? Math.sin(p.animTime * 18) * 2 : 0;

      ctx.save();
      ctx.translate(p.x - camera.x, p.y - camera.y + bob);

      // Flip horizontally based on facing
      ctx.scale(p.facing, 1);
      ctx.translate(-p.w / 2, 0);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(p.w / 2, p.h + 3, 14, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(8, 14, 18, 18);

      // Head
      ctx.fillStyle = "#ffd8a8";
      ctx.fillRect(9, 2, 16, 14);

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(13, 7, 2, 2);
      ctx.fillRect(19, 7, 2, 2);

      // Legs animation
      if (p.onGround && Math.abs(p.vx) > 10) {
        const legSwing = Math.sin(p.animTime * 18) * 4;
        ctx.fillStyle = "#444";
        ctx.fillRect(10, 31, 5, 10 + legSwing * 0.2);
        ctx.fillRect(20, 31, 5, 10 - legSwing * 0.2);
      } else {
        ctx.fillStyle = "#444";
        ctx.fillRect(10, 31, 5, 10);
        ctx.fillRect(20, 31, 5, 10);
      }

      // Arms
      ctx.fillStyle = "#d98";
      ctx.fillRect(4, 16, 4, 12);
      ctx.fillRect(26, 16, 4, 12);

      // Small animation detail: blink / motion frame
      if (frame === 1) {
        ctx.fillStyle = "#fff";
        ctx.fillRect(13, 7, 2, 1);
        ctx.fillRect(19, 7, 2, 1);
      }

      ctx.restore();
    }

    // --- Collision helpers ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisionsX(entity, solids) {
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) {
            entity.x = s.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = s.x + s.w;
          }
          entity.vx = 0;
        }
      }
    }

    function resolveCollisionsY(entity, solids) {
      entity.onGround = false;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // Clamp camera to level bounds
      const levelWidth = level[0].length * TILE;
      const levelHeight = level.length * TILE;

      camera.x = Math.max(0, Math.min(camera.x, levelWidth - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, levelHeight - canvas.height));
    }

    // --- Game loop ---
    let lastTime = 0;

    function update(dt) {
      // Input
      const left = keys["ArrowLeft"] || keys["KeyA"];
      const right = keys["ArrowRight"] || keys["KeyD"];
      const jump = keys["Space"] || keys["ArrowUp"] || keys["KeyW"];

      if (left) {
        player.vx = -MOVE_SPEED;
        player.facing = -1;
      } else if (right) {
        player.vx = MOVE_SPEED;
        player.facing = 1;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 1) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = -JUMP_VELOCITY;
        player.onGround = false;
      }

      // Physics
      player.vy += GRAVITY * dt;

      // Move and collide X
      player.x += player.vx * dt;
      resolveCollisionsX(player, solids);

      // Move and collide Y
      player.y += player.vy * dt;
      resolveCollisionsY(player, solids);

      // Animation
      player.animTime += dt;
      if (player.onGround && Math.abs(player.vx) > 10) {
        player.animFrame = Math.floor(player.animTime * 10) % 2;
      } else {
        player.animFrame = 0;
      }

      updateCamera();

      // Reset if falling out of world
      const levelHeight = level.length * TILE;
      if (player.y > levelHeight + 300) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawBackground() {
      // Sky gradient already on canvas background; draw distant clouds/hills
      ctx.save();
      ctx.translate(-camera.x * 0.2, -camera.y * 0.2);

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      for (let i = 0; i < 8; i++) {
        const x = 150 + i * 320;
        const y = 80 + (i % 3) * 40;
        ctx.beginPath();
        ctx.ellipse(x, y, 40, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 30, y + 2, 50, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(x - 25, y + 4, 30, 14, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // Hills
      ctx.fillStyle = "#88c070";
      for (let i = 0; i < 6; i++) {
        const x = i * 500;
        ctx.beginPath();
        ctx.arc(x + 200, canvas.height - 20, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawWorld() {
      // Tiles
      for (const s of solids) {
        const x = s.x - camera.x;
        const y = s.y - camera.y;

        ctx.fillStyle = "#4b5563";
        ctx.fillRect(x, y, s.w, s.h);

        ctx.fillStyle = "#6b7280";
        ctx.fillRect(x + 4, y + 4, s.w - 8, s.h - 8);

        // Top highlight
        ctx.fillStyle = "#9ca3af";
        ctx.fillRect(x, y, s.w, 6);
      }

      drawPlayer(ctx, player);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
    }

    function loop(timestamp) {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
      lastTime = timestamp;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    // Start the game
    requestAnimationFrame(loop);
  </script>
</body>
</html>
