## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Controls: A/D or Arrow Keys = Move, Space/W/Up = Jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    // World settings
    const GRAVITY = 2200;
    const FRICTION = 0.82;
    const MOVE_SPEED = 520;
    const JUMP_VELOCITY = 820;
    const MAX_FALL_SPEED = 1400;

    const world = {
      width: 4000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 1100, w: 4000, h: 100 },  // ground
      { x: 250, y: 900, w: 250, h: 30 },
      { x: 620, y: 780, w: 220, h: 30 },
      { x: 980, y: 680, w: 260, h: 30 },
      { x: 1400, y: 820, w: 300, h: 30 },
      { x: 1850, y: 720, w: 220, h: 30 },
      { x: 2250, y: 600, w: 260, h: 30 },
      { x: 2700, y: 760, w: 280, h: 30 },
      { x: 3200, y: 650, w: 250, h: 30 }
    ];

    // Simple sprite sheet-like animation using colored frames
    // In a real game, replace this with an actual image sprite sheet.
    const animations = {
      idle: {
        frames: [0, 1, 2, 1],
        fps: 4
      },
      run: {
        frames: [0, 1, 2, 3, 4, 5],
        fps: 12
      },
      jump: {
        frames: [0],
        fps: 1
      }
    };

    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: MOVE_SPEED,
      jumpPower: JUMP_VELOCITY,
      onGround: false,
      facing: 1,
      state: "idle",
      animTime: 0,
      frameIndex: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer(dt) {
      // Horizontal movement input
      if (keys.left) {
        player.vx = -player.speed;
        player.facing = -1;
      } else if (keys.right) {
        player.vx = player.speed;
        player.facing = 1;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 10) player.vx = 0;
      }

      // Jump
      if (keys.jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Apply gravity
      player.vy += GRAVITY * dt;
      if (player.vy > MAX_FALL_SPEED) player.vy = MAX_FALL_SPEED;

      // Move horizontally
      player.x += player.vx * dt;
      resolveCollisions("x");

      // Move vertically
      player.y += player.vy * dt;
      player.onGround = false;
      resolveCollisions("y");

      // Clamp to world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      player.y = Math.min(world.height - player.h, player.y);

      // State selection
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      // Animation update
      const anim = animations[player.state];
      player.animTime += dt;
      const frameCount = anim.frames.length;
      const frameDuration = 1 / anim.fps;
      player.frameIndex = Math.floor(player.animTime / frameDuration) % frameCount;
    }

    function resolveCollisions(axis) {
      for (const p of platforms) {
        if (!rectsOverlap(player, p)) continue;

        if (axis === "x") {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }

        if (axis === "y") {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6b4f2a";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      // top highlight
      ctx.fillStyle = "#8b6a3a";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Body animation colors (placeholder sprite frames)
      const runColors = ["#ff5f5f", "#ff8a5f", "#ffd15f", "#8aff5f", "#5fffd6", "#5f8aff"];
      const idleColors = ["#ff5f5f", "#ff6f6f", "#ff5f5f", "#ff6f6f"];
      const jumpColor = "#c75fff";

      let color = "#ff5f5f";
      if (player.state === "run") {
        color = runColors[animations.run.frames[player.frameIndex]];
      } else if (player.state === "idle") {
        color = idleColors[animations.idle.frames[player.frameIndex]];
      } else if (player.state === "jump") {
        color = jumpColor;
      }

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 10, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = color;
      ctx.fillRect(x, y, player.w, player.h);

      // Face direction marker
      ctx.fillStyle = "#fff";
      const eyeX = player.facing === 1 ? x + 32 : x + 10;
      ctx.fillRect(eyeX, y + 18, 6, 6);

      // Legs/feet hint for animation feel
      ctx.fillStyle = "#333";
      if (player.state === "run") {
        const step = animations.run.frames[player.frameIndex] % 2;
        ctx.fillRect(x + 10, y + 58, 10, step ? 4 : 8);
        ctx.fillRect(x + 28, y + 58, 10, step ? 8 : 4);
      } else {
        ctx.fillRect(x + 10, y + 58, 10, 8);
        ctx.fillRect(x + 28, y + 58, 10, 8);
      }
    }

    function drawBackground() {
      // Simple parallax-ish clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      for (let i = 0; i < 8; i++) {
        const cx = ((i * 520) - (camera.x * 0.3)) % (world.width + 600) - 200;
        const cy = 90 + (i % 3) * 60;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 60, 25, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 40, cy + 10, 75, 30, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 85, cy, 55, 22, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Player
      drawPlayer();

      // Debug info
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 80, 280, 60);
      ctx.fillStyle = "#fff";
      ctx.font = "14px monospace";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 55);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 35);
      ctx.fillText(`state: ${player.state} grounded: ${player.onGround}`, 20, canvas.height - 15);
    }

    let lastTime = performance.now();
    function gameLoop(now) {
      const dt = Math.min(0.033, (now - lastTime) / 1000);
      lastTime = now;

      updatePlayer(dt);
      updateCamera();
      draw();

      requestAnimationFrame(gameLoop);
    }

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

