## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const WIDTH = canvas.width;
const HEIGHT = canvas.height;

const keys = {};
window.addEventListener("keydown", (e) => (keys[e.code] = true));
window.addEventListener("keyup", (e) => (keys[e.code] = false));

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

class SpriteAnimation {
  constructor(frames, frameDuration = 0.12, loop = true) {
    this.frames = frames; // array of Image objects
    this.frameDuration = frameDuration;
    this.loop = loop;
    this.time = 0;
    this.index = 0;
  }

  update(dt) {
    if (this.frames.length <= 1) return;
    this.time += dt;
    while (this.time >= this.frameDuration) {
      this.time -= this.frameDuration;
      this.index++;
      if (this.index >= this.frames.length) {
        this.index = this.loop ? 0 : this.frames.length - 1;
      }
    }
  }

  getFrame() {
    return this.frames[this.index];
  }

  reset() {
    this.time = 0;
    this.index = 0;
  }
}

function loadImage(src) {
  const img = new Image();
  img.src = src;
  return img;
}

const assets = {
  idle: loadImage("assets/player_idle.png"),
  run0: loadImage("assets/player_run_0.png"),
  run1: loadImage("assets/player_run_1.png"),
  jump: loadImage("assets/player_jump.png"),
};

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 40;
    this.h = 56;

    this.vx = 0;
    this.vy = 0;

    this.speed = 320;
    this.jumpStrength = 640;
    this.gravity = 1800;
    this.maxFallSpeed = 1200;
    this.friction = 0.82;
    this.airControl = 0.75;

    this.onGround = false;
    this.facing = 1;

    this.animIdle = new SpriteAnimation([assets.idle], 0.2, true);
    this.animRun = new SpriteAnimation([assets.run0, assets.run1], 0.12, true);
    this.animJump = new SpriteAnimation([assets.jump], 0.2, true);

    this.currentAnimation = this.animIdle;
  }

  update(dt, platforms) {
    const left = keys["ArrowLeft"] || keys["KeyA"];
    const right = keys["ArrowRight"] || keys["KeyD"];
    const jump = keys["Space"] || keys["ArrowUp"] || keys["KeyW"];

    // Horizontal movement
    let move = 0;
    if (left) move -= 1;
    if (right) move += 1;

    if (move !== 0) {
      this.facing = move;
      const accel = this.onGround ? this.speed : this.speed * this.airControl;
      this.vx += move * accel * dt;
    } else if (this.onGround) {
      this.vx *= this.friction;
      if (Math.abs(this.vx) < 5) this.vx = 0;
    }

    this.vx = clamp(this.vx, -this.speed, this.speed);

    // Jump
    if (jump && this.onGround && !this.jumpHeld) {
      this.vy = -this.jumpStrength;
      this.onGround = false;
    }
    this.jumpHeld = jump;

    // Gravity
    this.vy += this.gravity * dt;
    this.vy = clamp(this.vy, -9999, this.maxFallSpeed);

    // Move and collide
    this.x += this.vx * dt;
    this.resolveHorizontal(platforms);

    this.y += this.vy * dt;
    this.resolveVertical(platforms);

    // Animation selection
    if (!this.onGround) {
      this.currentAnimation = this.animJump;
    } else if (Math.abs(this.vx) > 20) {
      this.currentAnimation = this.animRun;
    } else {
      this.currentAnimation = this.animIdle;
    }

    this.currentAnimation.update(dt);
  }

  resolveHorizontal(platforms) {
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vx > 0) {
          this.x = p.x - this.w;
        } else if (this.vx < 0) {
          this.x = p.x + p.w;
        }
        this.vx = 0;
      }
    }
  }

  resolveVertical(platforms) {
    this.onGround = false;
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }
  }

  intersects(rect) {
    return (
      this.x < rect.x + rect.w &&
      this.x + this.w > rect.x &&
      this.y < rect.y + rect.h &&
      this.y + this.h > rect.y
    );
  }

  draw(ctx) {
    const frame = this.currentAnimation.getFrame();

    // If images are loaded, draw sprite; otherwise draw placeholder rectangle.
    if (frame && frame.complete && frame.naturalWidth > 0) {
      ctx.save();
      if (this.facing < 0) {
        ctx.translate(this.x + this.w, this.y);
        ctx.scale(-1, 1);
        ctx.drawImage(frame, 0, 0, this.w, this.h);
      } else {
        ctx.drawImage(frame, this.x, this.y, this.w, this.h);
      }
      ctx.restore();
    } else {
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(this.x, this.y, this.w, this.h);
    }
  }
}

class Platform {
  constructor(x, y, w, h, color = "#3c5a40") {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.color = color;
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.w, this.h);
  }
}

// Example level
const platforms = [
  new Platform(0, 500, 960, 40, "#2f3e46"),     // ground
  new Platform(120, 410, 180, 24, "#4e7a5a"),
  new Platform(360, 350, 180, 24, "#4e7a5a"),
  new Platform(620, 290, 180, 24, "#4e7a5a"),
  new Platform(780, 430, 120, 24, "#4e7a5a"),
];

const player = new Player(80, 300);

let lastTime = 0;
function gameLoop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
  lastTime = timestamp;

  update(dt);
  render();

  requestAnimationFrame(gameLoop);
}

function update(dt) {
  player.update(dt, platforms);
}

function render() {
  ctx.clearRect(0, 0, WIDTH, HEIGHT);

  // Background decorations
  drawBackground();

  // Platforms
  for (const p of platforms) p.draw(ctx);

  // Player
  player.draw(ctx);

  // HUD
  ctx.fillStyle = "#000";
  ctx.font = "18px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);
}

function drawBackground() {
  // simple clouds
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  drawCloud(120, 80);
  drawCloud(420, 60);
  drawCloud(760, 100);

  // distant hills
  ctx.fillStyle = "#9bd18f";
  ctx.beginPath();
  ctx.arc(180, 540, 180, Math.PI, 0, false);
  ctx.arc(520, 540, 220, Math.PI, 0, false);
  ctx.arc(850, 540, 160, Math.PI, 0, false);
  ctx.fill();
}

function drawCloud(x, y) {
  ctx.beginPath();
  ctx.arc(x, y, 20, 0, Math.PI * 2);
  ctx.arc(x + 20, y - 10, 25, 0, Math.PI * 2);
  ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
  ctx.arc(x + 20, y + 10, 22, 0, Math.PI * 2);
  ctx.fill();
}

requestAnimationFrame(gameLoop);
```

