      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Controls: A/D or Arrow Keys = Move, Space/W/Up = Jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // ----------------------------
    // Input
    // ----------------------------
    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    // ----------------------------
    // World / Physics Constants
    // ----------------------------
    const GRAVITY = 2200;
    const MOVE_ACCEL = 1800;
    const MAX_SPEED = 380;
    const FRICTION = 2200;
    const JUMP_SPEED = 780;
    const TERMINAL_VELOCITY = 1600;

    const world = {
      width: 3200,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 1100, w: 3200, h: 100 },   // ground
      { x: 200, y: 920,  w: 220,  h: 30 },
      { x: 520, y: 820,  w: 220,  h: 30 },
      { x: 860, y: 740,  w: 240,  h: 30 },
      { x: 1220, y: 650, w: 220,  h: 30 },
      { x: 1560, y: 760, w: 300,  h: 30 },
      { x: 1960, y: 860, w: 260,  h: 30 },
      { x: 2320, y: 760, w: 260,  h: 30 },
      { x: 2700, y: 640, w: 240,  h: 30 }
    ];

    // ----------------------------
    // Player
    // ----------------------------
    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1, // 1 = right, -1 = left
      animTime: 0,
      animState: "idle"
    };

    // Simple sprite sheet-like animation using drawn frames.
    // In a real game, replace this with image assets.
    const anim = {
      idle: [
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: 0 },
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: 1 }
      ],
      run: [
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: -3 },
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: 3 },
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: -1 },
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: 1 }
      ],
      jump: [
        { body: "#f4c27a", shirt: "#4a90e2", pants: "#2c3e50", legOffset: 0 }
      ]
    };

    // ----------------------------
    // Collision Helpers
    // ----------------------------
    function aabbIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      for (const s of solids) {
        if (!aabbIntersect(entity, s)) continue;

        const prevX = entity.prevX;
        const prevY = entity.prevY;

        const prevRight = prevX + entity.w;
        const prevBottom = prevY + entity.h;
        const currRight = entity.x + entity.w;
        const currBottom = entity.y + entity.h;

        const wasAbove = prevBottom <= s.y;
        const wasBelow = prevY >= s.y + s.h;
        const wasLeft = prevRight <= s.x;
        const wasRight = prevX >= s.x + s.w;

        if (wasAbove) {
          entity.y = s.y - entity.h;
          entity.vy = 0;
          entity.onGround = true;
        } else if (wasBelow) {
          entity.y = s.y + s.h;
          entity.vy = 0;
        } else if (wasLeft) {
          entity.x = s.x - entity.w;
          entity.vx = 0;
        } else if (wasRight) {
          entity.x = s.x + s.w;
          entity.vx = 0;
        } else {
          // Fallback: separate by smallest overlap
          const overlapLeft = currRight - s.x;
          const overlapRight = s.x + s.w - entity.x;
          const overlapTop = currBottom - s.y;
          const overlapBottom = s.y + s.h - entity.y;

          const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

          if (minOverlap === overlapTop) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (minOverlap === overlapBottom) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          } else if (minOverlap === overlapLeft) {
            entity.x = s.x - entity.w;
            entity.vx = 0;
          } else {
            entity.x = s.x + s.w;
            entity.vx = 0;
          }
        }
      }
    }

    // ----------------------------
    // Game Loop
    // ----------------------------
    let last = performance.now();
    let cameraX = 0;
    let cameraY = 0;

    function update(dt) {
      player.prevX = player.x;
      player.prevY = player.y;

      // Horizontal movement
      let moveDir = 0;
      if (keys.left) moveDir -= 1;
      if (keys.right) moveDir += 1;

      if (moveDir !== 0) {
        player.vx += moveDir * MOVE_ACCEL * dt;
        player.facing = moveDir;
      } else {
        // friction
        if (player.vx > 0) {
          player.vx = Math.max(0, player.vx - FRICTION * dt);
        } else if (player.vx < 0) {
          player.vx = Math.min(0, player.vx + FRICTION * dt);
        }
      }

      player.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, player.vx));

      // Jump
      if (keys.jump && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;
      player.vy = Math.min(player.vy, TERMINAL_VELOCITY);

      // Integrate
      player.x += player.vx * dt;
      player.y += player.vy * dt;

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }
      if (player.y > world.height) {
        player.y = 200;
        player.vy = 0;
      }

      resolveCollisions(player, platforms);

      // Animation state
      if (!player.onGround) {
        player.animState = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.animState = "run";
      } else {
        player.animState = "idle";
      }

      player.animTime += dt;

      // Camera follow
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;
      cameraX += (targetX - cameraX) * Math.min(1, 8 * dt);
      cameraY += (targetY - cameraY) * Math.min(1, 8 * dt);

      cameraX = Math.max(0, Math.min(world.width - canvas.width, cameraX));
      cameraY = Math.max(0, Math.min(world.height - canvas.height, cameraY));
    }

    function drawBackground() {
      // sky
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // distant hills
      ctx.save();
      ctx.translate(-cameraX * 0.2, -cameraY * 0.1);
      ctx.fillStyle = "#7fc97f";
      for (let i = 0; i < 8; i++) {
        ctx.beginPath();
        ctx.ellipse(250 + i * 420, 980, 220, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawPlatforms() {
      ctx.fillStyle = "#5c4b3a";
      for (const p of platforms) {
        ctx.fillRect(
          Math.round(p.x - cameraX),
          Math.round(p.y - cameraY),
          p.w,
          p.h
        );

        // top highlight
        ctx.fillStyle = "#7a624d";
        ctx.fillRect(
          Math.round(p.x - cameraX),
          Math.round(p.y - cameraY),
          p.w,
          6
        );
        ctx.fillStyle = "#5c4b3a";
      }
    }

    function drawPlayer() {
      const frameSet = anim[player.animState];
      const frame = frameSet[Math.floor(player.animTime * 10) % frameSet.length];

      const x = Math.round(player.x - cameraX);
      const y = Math.round(player.y - cameraY);

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(player.w / 2, player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // legs
      ctx.fillStyle = frame.pants;
      ctx.fillRect(14, 38 + frame.legOffset, 8, 20);
      ctx.fillRect(26, 38 - frame.legOffset, 8, 20);

      // body
      ctx.fillStyle = frame.shirt;
      ctx.fillRect(12, 18, 24, 24);

      // head
      ctx.fillStyle = frame.body;
      ctx.beginPath();
      ctx.arc(24, 14, 12, 0, Math.PI * 2);
      ctx.fill();

      // eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(19, 12, 2, 2);
      ctx.fillRect(27, 12, 2, 2);

      // arms
      ctx.fillStyle = frame.shirt;
      ctx.fillRect(6, 20, 8, 6);
      ctx.fillRect(34, 20, 8, 6);

      ctx.restore();
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.lineWidth = 4;
      ctx.strokeRect(-cameraX, -cameraY, world.width, world.height);
    }

    function render() {
      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawWorldBounds();
    }

    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

