## Full example

Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Initial Implementation</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
  </style>
</head>
<body>
<canvas id="game"></canvas>

<script>
(() => {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");

  const TILE_SIZE = 32;
  const GRAVITY = 1800;
  const MOVE_SPEED = 260;
  const JUMP_SPEED = 650;
  const FRICTION = 0.85;
  const MAX_FALL_SPEED = 1200;

  let width = window.innerWidth;
  let height = window.innerHeight;
  canvas.width = width;
  canvas.height = height;

  window.addEventListener("resize", () => {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;
  });

  const keys = new Set();
  window.addEventListener("keydown", (e) => keys.add(e.code));
  window.addEventListener("keyup", (e) => keys.delete(e.code));

  // Simple level map:
  // # = solid block
  // . = empty
  const level = [
    "................................................................",
    "................................................................",
    "................................................................",
    "................................................................",
    "................................................................",
    "....................###.........................................",
    "..............###...............................................",
    "..............................................###...............",
    "...............................###..............................",
    "####################....##############################....######",
  ];

  const world = {
    width: level[0].length * TILE_SIZE,
    height: level.length * TILE_SIZE,
    tiles: []
  };

  for (let y = 0; y < level.length; y++) {
    for (let x = 0; x < level[y].length; x++) {
      if (level[y][x] === "#") {
        world.tiles.push({
          x: x * TILE_SIZE,
          y: y * TILE_SIZE,
          w: TILE_SIZE,
          h: TILE_SIZE
        });
      }
    }
  }

  const player = {
    x: 100,
    y: 100,
    w: 28,
    h: 40,
    vx: 0,
    vy: 0,
    onGround: false,
    facing: 1,
    animTime: 0,
    state: "idle"
  };

  const camera = {
    x: 0,
    y: 0
  };

  // --- Sprite animation setup ---
  // Using simple generated sprite frames (placeholder art).
  // Replace with real sprite sheets later if desired.
  const sprite = {
    frameWidth: 32,
    frameHeight: 48,
    idle: [],
    run: [],
    jump: []
  };

  function makeFrame(color1, color2, accent) {
    const c = document.createElement("canvas");
    c.width = 32;
    c.height = 48;
    const g = c.getContext("2d");

    // body
    g.fillStyle = color1;
    g.fillRect(10, 16, 12, 18);

    // head
    g.fillStyle = color2;
    g.fillRect(9, 4, 14, 12);

    // legs
    g.fillStyle = accent;
    g.fillRect(9, 34, 5, 10);
    g.fillRect(18, 34, 5, 10);

    // eyes
    g.fillStyle = "#000";
    g.fillRect(12, 8, 2, 2);
    g.fillRect(18, 8, 2, 2);

    return c;
  }

  // Idle frames
  sprite.idle.push(makeFrame("#4c8bf5", "#ffd7b5", "#2d5bd1"));
  sprite.idle.push(makeFrame("#4c8bf5", "#ffd7b5", "#2d5bd1"));

  // Run frames
  sprite.run.push(makeFrame("#4c8bf5", "#ffd7b5", "#2d5bd1"));
  sprite.run.push(makeFrame("#3f7ae0", "#ffd7b5", "#2d5bd1"));
  sprite.run.push(makeFrame("#4c8bf5", "#ffd7b5", "#2d5bd1"));
  sprite.run.push(makeFrame("#3f7ae0", "#ffd7b5", "#2d5bd1"));

  // Jump frames
  sprite.jump.push(makeFrame("#6b9cff", "#ffd7b5", "#2d5bd1"));

  function rectsIntersect(a, b) {
    return (
      a.x < b.x + b.w &&
      a.x + a.w > b.x &&
      a.y < b.y + b.h &&
      a.y + a.h > b.y
    );
  }

  function update(dt) {
    // Input
    let move = 0;
    if (keys.has("ArrowLeft") || keys.has("KeyA")) move -= 1;
    if (keys.has("ArrowRight") || keys.has("KeyD")) move += 1;

    if (move !== 0) {
      player.vx = move * MOVE_SPEED;
      player.facing = Math.sign(move);
    } else {
      player.vx *= FRICTION;
      if (Math.abs(player.vx) < 5) player.vx = 0;
    }

    // Jump
    if ((keys.has("Space") || keys.has("ArrowUp") || keys.has("KeyW")) && player.onGround) {
      player.vy = -JUMP_SPEED;
      player.onGround = false;
    }

    // Gravity
    player.vy += GRAVITY * dt;
    if (player.vy > MAX_FALL_SPEED) player.vy = MAX_FALL_SPEED;

    // Horizontal movement + collision
    player.x += player.vx * dt;
    let playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };
    for (const tile of world.tiles) {
      if (rectsIntersect(playerBox, tile)) {
        if (player.vx > 0) {
          player.x = tile.x - player.w;
        } else if (player.vx < 0) {
          player.x = tile.x + tile.w;
        }
        player.vx = 0;
        playerBox.x = player.x;
      }
    }

    // Vertical movement + collision
    player.y += player.vy * dt;
    player.onGround = false;
    playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };
    for (const tile of world.tiles) {
      if (rectsIntersect(playerBox, tile)) {
        if (player.vy > 0) {
          player.y = tile.y - player.h;
          player.vy = 0;
          player.onGround = true;
        } else if (player.vy < 0) {
          player.y = tile.y + tile.h;
          player.vy = 0;
        }
        playerBox.y = player.y;
      }
    }

    // Determine animation state
    if (!player.onGround) {
      player.state = "jump";
    } else if (Math.abs(player.vx) > 20) {
      player.state = "run";
    } else {
      player.state = "idle";
    }

    player.animTime += dt;

    // Camera follow
    camera.x = player.x + player.w / 2 - width / 2;
    camera.y = player.y + player.h / 2 - height / 2;

    camera.x = Math.max(0, Math.min(camera.x, world.width - width));
    camera.y = Math.max(0, Math.min(camera.y, world.height - height));
  }

  function drawBackground() {
    // Simple parallax-ish sky + clouds
    ctx.fillStyle = "#87ceeb";
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = "rgba(255,255,255,0.7)";
    for (let i = 0; i < 8; i++) {
      const x = (i * 220 - camera.x * 0.2) % (width + 200) - 100;
      const y = 60 + (i % 3) * 50;
      ctx.beginPath();
      ctx.ellipse(x, y, 40, 20, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 25, y + 5, 35, 18, 0, 0, Math.PI * 2);
      ctx.ellipse(x - 25, y + 5, 30, 16, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function drawWorld() {
    ctx.fillStyle = "#3b2f2f";
    for (const tile of world.tiles) {
      const sx = tile.x - camera.x;
      const sy = tile.y - camera.y;
      ctx.fillStyle = "#6b4f2a";
      ctx.fillRect(sx, sy, tile.w, tile.h);
      ctx.fillStyle = "#8b6b3f";
      ctx.fillRect(sx + 2, sy + 2, tile.w - 4, tile.h - 4);
    }
  }

  function drawPlayer() {
    let frames;
    if (player.state === "run") frames = sprite.run;
    else if (player.state === "jump") frames = sprite.jump;
    else frames = sprite.idle;

    const frameIndex = Math.floor(player.animTime * 10) % frames.length;
    const frame = frames[frameIndex];

    const drawX = player.x - camera.x;
    const drawY = player.y - camera.y;

    ctx.save();
    ctx.translate(drawX + player.w / 2, drawY + player.h / 2);
    ctx.scale(player.facing, 1);
    ctx.translate(-(drawX + player.w / 2), -(drawY + player.h / 2));

    // Draw sprite centered in collision box
    ctx.drawImage(frame, drawX - 2, drawY - 4, 32, 48);

    ctx.restore();
  }

  function drawUI() {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(10, 10, 260, 70);

    ctx.fillStyle = "#fff";
    ctx.font = "16px sans-serif";
    ctx.fillText("Controls:", 20, 32);
    ctx.fillText("A/D or Arrow Keys = Move", 20, 52);
    ctx.fillText("Space / W / Up = Jump", 20, 72);
  }

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 1 / 30);
    last = now;

    update(dt);

    drawBackground();
    drawWorld();
    drawPlayer();
    drawUI();

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
