## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// ----------------------------
// Input
// ----------------------------
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// ----------------------------
// Utility
// ----------------------------
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

// ----------------------------
// Assets
// ----------------------------
const assets = {
  idle: new Image(),
  run1: new Image(),
  run2: new Image(),
  jump: new Image(),
};

assets.idle.src = "assets/player_idle.png";
assets.run1.src = "assets/player_run_1.png";
assets.run2.src = "assets/player_run_2.png";
assets.jump.src = "assets/player_jump.png";

// ----------------------------
// World / Level
// ----------------------------
const world = {
  gravity: 1800,
  platforms: [
    { x: 0, y: 700, w: 2000, h: 80 },     // ground
    { x: 250, y: 560, w: 220, h: 30 },
    { x: 560, y: 480, w: 220, h: 30 },
    { x: 900, y: 410, w: 220, h: 30 },
    { x: 1250, y: 520, w: 240, h: 30 },
    { x: 1600, y: 620, w: 180, h: 30 },
  ],
};

// ----------------------------
// Player
// ----------------------------
const player = {
  x: 100,
  y: 500,
  w: 48,
  h: 64,
  vx: 0,
  vy: 0,
  speed: 420,
  jumpForce: 720,
  onGround: false,
  facing: 1,
  animTime: 0,
  currentFrame: "idle",
};

// ----------------------------
// Camera
// ----------------------------
const camera = {
  x: 0,
  y: 0,
};

// ----------------------------
// Physics / Collision
// ----------------------------
function moveAndCollide(entity, dt) {
  // Horizontal movement
  entity.x += entity.vx * dt;
  for (const p of world.platforms) {
    if (rectsOverlap(entity, p)) {
      if (entity.vx > 0) {
        entity.x = p.x - entity.w;
      } else if (entity.vx < 0) {
        entity.x = p.x + p.w;
      }
      entity.vx = 0;
    }
  }

  // Vertical movement
  entity.y += entity.vy * dt;
  entity.onGround = false;

  for (const p of world.platforms) {
    if (rectsOverlap(entity, p)) {
      if (entity.vy > 0) {
        entity.y = p.y - entity.h;
        entity.vy = 0;
        entity.onGround = true;
      } else if (entity.vy < 0) {
        entity.y = p.y + p.h;
        entity.vy = 0;
      }
    }
  }
}

// ----------------------------
// Update
// ----------------------------
let lastTime = performance.now();

function update(now) {
  const dt = Math.min((now - lastTime) / 1000, 0.033);
  lastTime = now;

  // Input -> velocity
  const moveLeft = keys.left;
  const moveRight = keys.right;

  if (moveLeft && !moveRight) {
    player.vx = -player.speed;
    player.facing = -1;
  } else if (moveRight && !moveLeft) {
    player.vx = player.speed;
    player.facing = 1;
  } else {
    // friction
    player.vx *= player.onGround ? 0.82 : 0.95;
    if (Math.abs(player.vx) < 5) player.vx = 0;
  }

  // Jump
  if (keys.jump && player.onGround) {
    player.vy = -player.jumpForce;
    player.onGround = false;
  }

  // Gravity
  player.vy += world.gravity * dt;
  player.vy = clamp(player.vy, -2000, 2200);

  // Physics
  moveAndCollide(player, dt);

  // Animation state
  player.animTime += dt;

  if (!player.onGround) {
    player.currentFrame = "jump";
  } else if (Math.abs(player.vx) > 20) {
    player.currentFrame = (Math.floor(player.animTime * 10) % 2 === 0) ? "run1" : "run2";
  } else {
    player.currentFrame = "idle";
  }

  // Camera follow
  camera.x = clamp(player.x + player.w / 2 - canvas.width / 2, 0, 2000 - canvas.width);
  camera.y = 0;

  render();
  requestAnimationFrame(update);
}

// ----------------------------
// Render
// ----------------------------
function drawPlatform(p) {
  ctx.fillStyle = "#4b5563";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

  ctx.fillStyle = "#6b7280";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
}

function drawPlayer() {
  const screenX = player.x - camera.x;
  const screenY = player.y - camera.y;

  const img = assets[player.currentFrame];
  if (img.complete && img.naturalWidth > 0) {
    ctx.save();
    if (player.facing === -1) {
      ctx.translate(screenX + player.w, screenY);
      ctx.scale(-1, 1);
      ctx.drawImage(img, 0, 0, player.w, player.h);
    } else {
      ctx.drawImage(img, screenX, screenY, player.w, player.h);
    }
    ctx.restore();
  } else {
    // fallback placeholder if images are missing
    ctx.fillStyle = "#ffcc00";
    ctx.fillRect(screenX, screenY, player.w, player.h);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // background parallax-ish layer
  ctx.fillStyle = "rgba(255,255,255,0.25)";
  for (let i = 0; i < 20; i++) {
    const x = ((i * 300) - (camera.x * 0.3)) % (canvas.width + 300) - 150;
    const y = 80 + (i % 4) * 40;
    ctx.beginPath();
    ctx.arc(x, y, 30, 0, Math.PI * 2);
    ctx.fill();
  }

  // platforms
  for (const p of world.platforms) {
    drawPlatform(p);
  }

  // player
  drawPlayer();

  // HUD
  ctx.fillStyle = "#111827";
  ctx.font = "18px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);
}

// Start
requestAnimationFrame(update);
```

