## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Starter</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }

    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 14px;
      text-shadow: 0 1px 2px rgba(0,0,0,0.5);
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys | Jump: Space / W / Up
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const GRAVITY = 2200;
    const MOVE_ACCEL = 2200;
    const MAX_SPEED = 360;
    const FRICTION = 1800;
    const JUMP_SPEED = 780;

    const keys = {
      left: false,
      right: false,
      jump: false,
      jumpPressed: false
    };

    const world = {
      width: 3000,
      height: 1200
    };

    const camera = {
      x: 0,
      y: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 3000, h: 40 },
      { x: 200, y: 420, w: 180, h: 20 },
      { x: 500, y: 360, w: 180, h: 20 },
      { x: 820, y: 300, w: 180, h: 20 },
      { x: 1150, y: 380, w: 220, h: 20 },
      { x: 1500, y: 320, w: 220, h: 20 },
      { x: 1850, y: 260, w: 220, h: 20 },
      { x: 2200, y: 360, w: 220, h: 20 },
      { x: 2550, y: 300, w: 220, h: 20 }
    ];

    const player = {
      x: 80,
      y: 200,
      w: 42,
      h: 56,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      state: "idle",
      animTime: 0
    };

    // Simple sprite sheet placeholder using colored frames
    // In a real game, replace with image assets.
    const sprite = {
      frameWidth: 42,
      frameHeight: 56,
      frameCount: {
        idle: 4,
        run: 6,
        jump: 1,
        fall: 1
      }
    };

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayerState(dt) {
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;
    }

    function handleInput(dt) {
      let ax = 0;

      if (keys.left) ax -= MOVE_ACCEL;
      if (keys.right) ax += MOVE_ACCEL;

      if (ax !== 0) {
        player.vx += ax * dt;
        player.facing = ax > 0 ? 1 : -1;
      } else if (player.onGround) {
        // friction
        const frictionStep = FRICTION * dt;
        if (Math.abs(player.vx) <= frictionStep) {
          player.vx = 0;
        } else {
          player.vx -= Math.sign(player.vx) * frictionStep;
        }
      }

      player.vx = clamp(player.vx, -MAX_SPEED, MAX_SPEED);

      if (keys.jumpPressed && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      keys.jumpPressed = false;
    }

    function applyPhysics(dt) {
      player.vy += GRAVITY * dt;

      // Horizontal move + collisions
      player.x += player.vx * dt;
      resolveCollisions("x");

      // Vertical move + collisions
      player.y += player.vy * dt;
      player.onGround = false;
      resolveCollisions("y");

      // Keep inside world bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height) {
        player.x = 80;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function resolveCollisions(axis) {
      for (const p of platforms) {
        if (!rectsOverlap(player, p)) continue;

        if (axis === "x") {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        } else {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }
    }

    function updateCamera() {
      camera.x = clamp(
        player.x + player.w / 2 - canvas.width / 2,
        0,
        world.width - canvas.width
      );
      camera.y = 0;
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#3a5f3a";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#5d8c5d";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Animation frame selection
      let frameIndex = 0;
      const frameDuration = 0.12;

      if (player.state === "idle") {
        frameIndex = Math.floor(player.animTime / frameDuration) % sprite.frameCount.idle;
      } else if (player.state === "run") {
        frameIndex = Math.floor(player.animTime / frameDuration) % sprite.frameCount.run;
      } else if (player.state === "jump") {
        frameIndex = 0;
      } else if (player.state === "fall") {
        frameIndex = 0;
      }

      // Placeholder animated character using simple shapes
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // body color changes by state/frame for visual feedback
      let bodyColor = "#ffcc66";
      if (player.state === "run") bodyColor = ["#ffcc66", "#ffd98a", "#ffe2a8"][frameIndex % 3];
      if (player.state === "jump") bodyColor = "#66ccff";
      if (player.state === "fall") bodyColor = "#ff6666";

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 - 2, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // head
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-14, -20, 28, 22);

      // torso
      ctx.fillRect(-16, 2, 32, 24);

      // legs
      ctx.fillStyle = "#2b2b3a";
      const legSwing = player.state === "run" ? Math.sin(player.animTime * 18) * 5 : 0;
      ctx.fillRect(-14, 26, 10, 22 + legSwing);
      ctx.fillRect(4, 26, 10, 22 - legSwing);

      // eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(6, -12, 4, 4);
      ctx.fillRect(-10, -12, 4, 4);

      ctx.restore();
    }

    function drawBackground() {
      // simple parallax hills
      const hillOffset = camera.x * 0.3;

      ctx.fillStyle = "#7cc47c";
      for (let i = -1; i < 8; i++) {
        const x = i * 300 - (hillOffset % 300);
        ctx.beginPath();
        ctx.ellipse(x + 150, 500, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      const cloudOffset = camera.x * 0.15;
      for (let i = -1; i < 6; i++) {
        const x = i * 260 - (cloudOffset % 260) + 40;
        const y = 70 + (i % 3) * 35;
        ctx.beginPath();
        ctx.ellipse(x, y, 45, 20, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 30, y - 10, 35, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 60, y, 40, 20, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // platforms
      for (const p of platforms) drawPlatform(p);

      drawPlayer();

      // debug text
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 60, 240, 50);
      ctx.fillStyle = "white";
      ctx.font = "14px monospace";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 38);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 20);
    }

    let lastTime = performance.now();

    function gameLoop(now) {
      const dt = Math.min((now - lastTime) / 1000, 1 / 30);
      lastTime = now;

      handleInput(dt);
      applyPhysics(dt);
      updatePlayerState(dt);
      updateCamera();
      render();

      requestAnimationFrame(gameLoop);
    }

    // Input handling
    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") {
        if (!keys.jump) keys.jumpPressed = true;
        keys.jump = true;
      }
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
