        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update(dt) {
      // Horizontal movement
      if (keys.left) {
        player.vx = -player.speed;
        player.facing = -1;
      } else if (keys.right) {
        player.vx = player.speed;
        player.facing = 1;
      } else {
        player.vx *= world.friction;
        if (Math.abs(player.vx) < 10) player.vx = 0;
      }

      // Jump
      if (keys.jump && player.onGround) {
        player.vy = -player.jumpStrength;
        player.onGround = false;
      }

      // Gravity
      player.vy += world.gravity * dt;

      // Move X and resolve collisions
      player.x += player.vx * dt;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Move Y and resolve collisions
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Animation
      const moving = Math.abs(player.vx) > 5;
      if (player.onGround && moving) {
        player.animTime += dt;
        if (player.animTime > 0.12) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
        player.animTime = 0;
      }

      // Camera follows player
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b3f72";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      // top highlight
      ctx.fillStyle = "#6c5ea0";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 20, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      const colors = ["#ffcc66", "#ffb84d", "#ffa31a", "#ffb84d"];
      const bodyColor = player.onGround && Math.abs(player.vx) > 5
        ? colors[player.animFrame]
        : "#ffcc66";

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(x + player.w / 2, y + player.h / 2);
        ctx.scale(-1, 1);
        ctx.translate(-(x + player.w / 2), -(y + player.h / 2));
      }

      // Head
      ctx.fillStyle = "#ffd9b3";
      ctx.fillRect(x + 12, y + 6, 24, 22);

      // Body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(x + 10, y + 26, 28, 24);

      // Legs
      ctx.fillStyle = "#2b2b2b";
      if (player.onGround && Math.abs(player.vx) > 5) {
        const legOffset = player.animFrame % 2 === 0 ? 4 : -4;
        ctx.fillRect(x + 12, y + 50, 8, 14 + legOffset);
        ctx.fillRect(x + 28, y + 50, 8, 14 - legOffset);
      } else {
        ctx.fillRect(x + 12, y + 50, 8, 14);
        ctx.fillRect(x + 28, y + 50, 8, 14);
      }

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(x + 17, y + 14, 4, 4);
      ctx.fillRect(x + 27, y + 14, 4, 4);

      ctx.restore();
    }

    function drawBackground() {
      // Simple parallax-ish hills
      const offset = camera.x * 0.2;
      ctx.fillStyle = "#b7e4c7";
      for (let i = -1; i < 6; i++) {
        ctx.beginPath();
        ctx.arc(i * 300 - (offset % 300), canvas.height - 80, 160, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      for (const p of platforms) drawPlatform(p);
      drawPlayer();

      // Debug ground line
      ctx.strokeStyle = "rgba(255,255,255,0.15)";
      ctx.beginPath();
      ctx.moveTo(-camera.x, 560 - camera.y);
      ctx.lineTo(2000 - camera.x, 560 - camera.y);
      ctx.stroke();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

