```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

canvas.width = 960;
canvas.height = 540;

// -----------------------------
// Input handling
// -----------------------------
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// -----------------------------
// Utility
// -----------------------------
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

// -----------------------------
// Platform class
// -----------------------------
class Platform {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
  }

  draw(ctx) {
    ctx.fillStyle = "#4b5563";
    ctx.fillRect(this.x, this.y, this.w, this.h);
    ctx.fillStyle = "#374151";
    ctx.fillRect(this.x, this.y, this.w, 6);
  }
}

// -----------------------------
// Sprite animation helper
// -----------------------------
class SpriteAnimator {
  constructor(image, frameWidth, frameHeight, frameCount, frameSpeed = 8) {
    this.image = image;
    this.frameWidth = frameWidth;
    this.frameHeight = frameHeight;
    this.frameCount = frameCount;
    this.frameSpeed = frameSpeed;
    this.currentFrame = 0;
    this.frameTimer = 0;
  }

  update() {
    this.frameTimer++;
    if (this.frameTimer >= this.frameSpeed) {
      this.frameTimer = 0;
      this.currentFrame = (this.currentFrame + 1) % this.frameCount;
    }
  }

  draw(ctx, x, y, w, h, flip = false) {
    const sx = this.currentFrame * this.frameWidth;

    ctx.save();
    if (flip) {
      ctx.translate(x + w, y);
      ctx.scale(-1, 1);
      ctx.drawImage(
        this.image,
        sx, 0, this.frameWidth, this.frameHeight,
        0, 0, w, h
      );
    } else {
      ctx.drawImage(
        this.image,
        sx, 0, this.frameWidth, this.frameHeight,
        x, y, w, h
      );
    }
    ctx.restore();
  }
}

// -----------------------------
// Player class
// -----------------------------
class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 48;
    this.h = 64;

    this.vx = 0;
    this.vy = 0;

    this.speed = 0.6;
    this.maxSpeed = 6;
    this.jumpPower = 14;
    this.gravity = 0.7;
    this.friction = 0.85;

    this.onGround = false;
    this.facingRight = true;

    // Placeholder sprite sheets
    this.idleImage = new Image();
    this.runImage = new Image();
    this.jumpImage = new Image();

    // Replace these with your actual sprite sheet paths
    this.idleImage.src = "assets/player_idle.png";
    this.runImage.src = "assets/player_run.png";
    this.jumpImage.src = "assets/player_jump.png";

    // Default animators
    this.idleAnim = new SpriteAnimator(this.idleImage, 48, 64, 4, 10);
    this.runAnim = new SpriteAnimator(this.runImage, 48, 64, 6, 6);
    this.jumpAnim = new SpriteAnimator(this.jumpImage, 48, 64, 2, 12);
  }

  update(platforms) {
    // Horizontal movement
    if (keys.left) {
      this.vx -= this.speed;
      this.facingRight = false;
    }
    if (keys.right) {
      this.vx += this.speed;
      this.facingRight = true;
    }

    this.vx = clamp(this.vx, -this.maxSpeed, this.maxSpeed);

    // Jump
    if (keys.jump && this.onGround) {
      this.vy = -this.jumpPower;
      this.onGround = false;
    }

    // Gravity
    this.vy += this.gravity;

    // Apply friction if grounded
    if (this.onGround) {
      this.vx *= this.friction;
      if (Math.abs(this.vx) < 0.1) this.vx = 0;
    }

    // Move X and resolve collisions
    this.x += this.vx;
    this.resolveCollisions(platforms, "x");

    // Move Y and resolve collisions
    this.y += this.vy;
    this.onGround = false;
    this.resolveCollisions(platforms, "y");

    // Update animation
    if (!this.onGround) {
      this.jumpAnim.update();
    } else if (Math.abs(this.vx) > 0.5) {
      this.runAnim.update();
    } else {
      this.idleAnim.update();
    }

    // Keep player in bounds
    this.x = clamp(this.x, 0, canvas.width - this.w);
    this.y = clamp(this.y, 0, canvas.height - this.h);
  }

  resolveCollisions(platforms, axis) {
    for (const p of platforms) {
      if (
        this.x < p.x + p.w &&
        this.x + this.w > p.x &&
        this.y < p.y + p.h &&
        this.y + this.h > p.y
      ) {
        if (axis === "x") {
          if (this.vx > 0) {
            this.x = p.x - this.w;
          } else if (this.vx < 0) {
            this.x = p.x + p.w;
          }
          this.vx = 0;
        } else if (axis === "y") {
          if (this.vy > 0) {
            this.y = p.y - this.h;
            this.vy = 0;
            this.onGround = true;
          } else if (this.vy < 0) {
            this.y = p.y + p.h;
            this.vy = 0;
          }
        }
      }
    }
  }

  draw(ctx) {
    // If images aren't loaded yet, draw a placeholder
    const usePlaceholder =
      !this.idleImage.complete || !this.runImage.complete || !this.jumpImage.complete;

    if (usePlaceholder) {
      ctx.fillStyle = this.onGround ? "#f59e0b" : "#ef4444";
      ctx.fillRect(this.x, this.y, this.w, this.h);
      return;
    }

    if (!this.onGround) {
      this.jumpAnim.draw(ctx, this.x, this.y, this.w, this.h, !this.facingRight);
    } else if (Math.abs(this.vx) > 0.5) {
      this.runAnim.draw(ctx, this.x, this.y, this.w, this.h, !this.facingRight);
    } else {
      this.idleAnim.draw(ctx, this.x, this.y, this.w, this.h, !this.facingRight);
    }
  }
}

// -----------------------------
// World setup
// -----------------------------
const platforms = [
  new Platform(0, 500, 960, 40),      // ground
  new Platform(120, 420, 160, 20),
  new Platform(340, 360, 180, 20),
  new Platform(620, 300, 160, 20),
  new Platform(760, 420, 120, 20),
];

const player = new Player(100, 300);

// Camera (simple follow)
const camera = {
  x: 0,
  y: 0,
};

// -----------------------------
// Game loop
// -----------------------------
function update() {
  player.update(platforms);

  // Simple camera follow
  camera.x = clamp(player.x - canvas.width / 2 + player.w / 2, 0, 0);
  camera.y = 0;
}

function drawBackground() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Clouds / parallax-like simple background
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  ctx.beginPath();
  ctx.arc(150, 100, 30, 0, Math.PI * 2);
  ctx.arc(180, 90, 40, 0, Math.PI * 2);
  ctx.arc(220, 105, 28, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.arc(700, 80, 25, 0, Math.PI * 2);
  ctx.arc(730, 70, 35, 0, Math.PI * 2);
  ctx.arc(770, 85, 22, 0, Math.PI * 2);
  ctx.fill();
}

function draw() {
  drawBackground();

  // Draw platforms
  for (const p of platforms) {
    p.draw(ctx);
  }

  // Draw player
  player.draw(ctx);

  // Debug info
  ctx.fillStyle = "#111827";
  ctx.font = "16px sans-serif";
  ctx.fillText(`X: ${player.x.toFixed(1)} Y: ${player.y.toFixed(1)}`, 20, 25);
  ctx.fillText(`VX: ${player.vx.toFixed(1)} VY: ${player.vy.toFixed(1)}`, 20, 45);
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();
```

