  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // =========================
    // Input
    // =========================
    const keys = {
      left: false,
      right: false,
      jump: false,
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    // =========================
    // World / Level
    // =========================
    const TILE_SIZE = 48;

    // 0 = empty, 1 = solid
    const level = [
      "................................................",
      "................................................",
      "................................................",
      "................................................",
      ".................###............................",
      "................................................",
      ".............###................................",
      "................................................",
      "....###.........................................",
      "................................................",
      ".......................####.....................",
      "................................................",
      "..............###...............................",
      "................................................",
      "###########################.....................",
      "................................................",
      "................................................",
      "................................................",
      "................................................",
      "################################################",
    ];

    const world = {
      width: level[0].length * TILE_SIZE,
      height: level.length * TILE_SIZE,
      solids: []
    };

    for (let y = 0; y < level.length; y++) {
      for (let x = 0; x < level[y].length; x++) {
        if (level[y][x] === "#") {
          world.solids.push({
            x: x * TILE_SIZE,
            y: y * TILE_SIZE,
            w: TILE_SIZE,
            h: TILE_SIZE
          });
        }
      }
    }

    // =========================
    // Player
    // =========================
    const player = {
      x: 100,
      y: 100,
      w: 34,
      h: 44,
      vx: 0,
      vy: 0,
      speed: 320,
      jumpForce: 760,
      grounded: false,
      facing: 1,
      state: "idle",
      animTime: 0,
      color: "#ffcc66",
    };

    const physics = {
      gravity: 1800,
      friction: 0.82,
      airFriction: 0.96,
      maxFallSpeed: 1200,
    };

    // =========================
    // Animation frames
    // =========================
    // Initial implementation uses simple procedural sprite animation.
    // You can replace this later with actual sprite sheet rendering.
    const animations = {
      idle: { frames: 4, frameDuration: 0.18 },
      run: { frames: 6, frameDuration: 0.10 },
      jump: { frames: 2, frameDuration: 0.14 },
      fall: { frames: 2, frameDuration: 0.14 },
    };

    function getAnimationState() {
      if (!player.grounded) {
        return player.vy < 0 ? "jump" : "fall";
      }
      if (Math.abs(player.vx) > 20) return "run";
      return "idle";
    }

    // =========================
    // Collision helpers
    // =========================
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      // X axis
      entity.x += entity.vx * dt;
      let box = { x: entity.x, y: entity.y, w: entity.w, h: entity.h };

      for (const s of solids) {
        if (!rectsOverlap(box, s)) continue;

        if (entity.vx > 0) {
          entity.x = s.x - entity.w;
        } else if (entity.vx < 0) {
          entity.x = s.x + s.w;
        }
        entity.vx = 0;
        box.x = entity.x;
      }

      // Y axis
      entity.y += entity.vy * dt;
      box.y = entity.y;
      entity.grounded = false;

      for (const s of solids) {
        if (!rectsOverlap(box, s)) continue;

        if (entity.vy > 0) {
          entity.y = s.y - entity.h;
          entity.grounded = true;
        } else if (entity.vy < 0) {
          entity.y = s.y + s.h;
        }
        entity.vy = 0;
        box.y = entity.y;
      }
    }

    function getNearbySolids(entity) {
      // Simple broad-phase: only check solids near the player
      const padding = 200;
      return world.solids.filter(s =>
        s.x + s.w > entity.x - padding &&
        s.x < entity.x + entity.w + padding &&
        s.y + s.h > entity.y - padding &&
        s.y < entity.y + entity.h + padding
      );
    }

    // =========================
    // Camera
    // =========================
    const camera = {
      x: 0,
      y: 0,
      smooth: 0.08,
    };

    function updateCamera() {
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;

      camera.x += (targetX - camera.x) * camera.smooth;
      camera.y += (targetY - camera.y) * camera.smooth;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    // =========================
    // Game loop
    // =========================
    let lastTime = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Input -> movement
      let move = 0;
      if (keys.left) move -= 1;
      if (keys.right) move += 1;

      if (move !== 0) {
        player.vx = move * player.speed;
        player.facing = move;
      } else {
        const friction = player.grounded ? physics.friction : physics.airFriction;
        player.vx *= friction;
        if (Math.abs(player.vx) < 1) player.vx = 0;
      }

      // Jump
      if (keys.jump && player.grounded) {
        player.vy = -player.jumpForce;
        player.grounded = false;
      }

      // Gravity
      player.vy += physics.gravity * dt;
      player.vy = Math.min(player.vy, physics.maxFallSpeed);

      // Collisions
      const nearby = getNearbySolids(player);
      resolveCollisions(player, nearby);

      // Keep player within world bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }

      // Update animation
      player.state = getAnimationState();
      player.animTime += dt;
      updateCamera();
    }

    function drawBackground() {
      // Sky gradient already on canvas background, but we can add parallax clouds
      const cloudOffset = camera.x * 0.2;

      ctx.save();
      ctx.translate(-cloudOffset, 0);
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      for (let i = 0; i < 12; i++) {
        const x = i * 420 + 80;
        const y = 60 + (i % 3) * 55;
        ctx.beginPath();
        ctx.arc(x, y, 28, 0, Math.PI * 2);
        ctx.arc(x + 24, y + 8, 34, 0, Math.PI * 2);
        ctx.arc(x + 52, y, 26, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawLevel() {
      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      for (const s of world.solids) {
        // Draw ground tiles
        ctx.fillStyle = "#3d3f52";
        ctx.fillRect(s.x, s.y, s.w, s.h);

        ctx.fillStyle = "#5a5d78";
        ctx.fillRect(s.x + 4, s.y + 4, s.w - 8, s.h - 8);

        // Simple top highlight
        ctx.fillStyle = "#7d80a3";
        ctx.fillRect(s.x + 4, s.y + 4, s.w - 8, 6);
      }

      ctx.restore();
    }

    function drawPlayer() {
      const anim = animations[player.state];
      const frame = Math.floor(player.animTime / anim.frameDuration) % anim.frames;

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Flip horizontally based on facing
      const cx = player.x + player.w / 2;
      const cy = player.y + player.h / 2;

      ctx.translate(cx, cy);
      ctx.scale(player.facing, 1);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 + 8, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      const bob = player.state === "run" ? Math.sin(frame * 0.8) * 2 : 0;

      // Head
      ctx.fillStyle = player.color;
      ctx.beginPath();
      ctx.roundRect(-14, -22 + bob, 28, 28, 8);
      ctx.fill();

      // Body
      ctx.fillStyle = "#ff9f43";
      ctx.beginPath();
      ctx.roundRect(-15, 2 + bob, 30, 26, 8);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#1d1f27";
      ctx.beginPath();
      ctx.arc(6, -10 + bob, 2.5, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(-2, -10 + bob, 2.5, 0, Math.PI * 2);
      ctx.fill();

      // Legs / feet animation
      ctx.strokeStyle = "#2b2d3a";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      const legSwing = player.state === "run" ? Math.sin(frame * 1.2) * 8 : 0;
      ctx.beginPath();
      ctx.moveTo(-8, 28 + bob);
      ctx.lineTo(-10 - legSwing * 0.2, 38 + bob);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 28 + bob);
      ctx.lineTo(10 + legSwing * 0.2, 38 + bob);
      ctx.stroke();

      ctx.restore();
    }

    function drawDebug() {
      ctx.save();
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(12, canvas.height - 92, 260, 80);
      ctx.fillStyle = "white";
      ctx.font = "14px monospace";
      ctx.fillText(`x: ${player.x.toFixed(1)}  y: ${player.y.toFixed(1)}`, 22, canvas.height - 62);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 22, canvas.height - 42);
      ctx.fillText(`state: ${player.state} grounded: ${player.grounded}`, 22, canvas.height - 22);
      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawLevel();
      drawPlayer();
      drawDebug();
    }

    function loop(now) {
      const delta = Math.min((now - lastTime) / 1000, 1 / 30);
      lastTime = now;

      update(delta);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

