## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

canvas.width = 960;
canvas.height = 540;

const TILE_SIZE = 48;
const GRAVITY = 2200;
const MOVE_SPEED = 420;
const JUMP_SPEED = 850;
const FRICTION = 0.85;
const AIR_FRICTION = 0.98;
const MAX_FALL_SPEED = 1800;

const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// Simple tile map: # = solid, . = empty
const level = [
  "................................................",
  "................................................",
  "................................................",
  "................................................",
  "................................................",
  "......................###.......................",
  "................................................",
  ".............###................................",
  "................................................",
  "....###.........................................",
  "................................................",
  "###########################.......##############",
];

const world = {
  width: level[0].length * TILE_SIZE,
  height: level.length * TILE_SIZE,
};

const playerImage = new Image();
playerImage.src = "assets/player_run.png"; // placeholder sprite sheet

const player = {
  x: 100,
  y: 100,
  w: 36,
  h: 44,
  vx: 0,
  vy: 0,
  onGround: false,
  facing: 1,
  state: "idle",
  animTime: 0,
  frame: 0,
};

const camera = {
  x: 0,
  y: 0,
};

function isSolidTile(tx, ty) {
  if (ty < 0 || ty >= level.length || tx < 0 || tx >= level[0].length) return false;
  return level[ty][tx] === "#";
}

function rectVsTile(x, y, w, h, tx, ty) {
  const tileX = tx * TILE_SIZE;
  const tileY = ty * TILE_SIZE;
  return (
    x < tileX + TILE_SIZE &&
    x + w > tileX &&
    y < tileY + TILE_SIZE &&
    y + h > tileY
  );
}

function resolveCollisions(entity) {
  entity.onGround = false;

  // Horizontal
  entity.x += entity.vx * dt;
  let left = Math.floor(entity.x / TILE_SIZE);
  let right = Math.floor((entity.x + entity.w) / TILE_SIZE);
  let top = Math.floor(entity.y / TILE_SIZE);
  let bottom = Math.floor((entity.y + entity.h - 1) / TILE_SIZE);

  for (let ty = top; ty <= bottom; ty++) {
    if (entity.vx > 0) {
      if (isSolidTile(right, ty) && rectVsTile(entity.x, entity.y, entity.w, entity.h, right, ty)) {
        entity.x = right * TILE_SIZE - entity.w - 0.01;
        entity.vx = 0;
        break;
      }
    } else if (entity.vx < 0) {
      if (isSolidTile(left, ty) && rectVsTile(entity.x, entity.y, entity.w, entity.h, left, ty)) {
        entity.x = (left + 1) * TILE_SIZE + 0.01;
        entity.vx = 0;
        break;
      }
    }
  }

  // Vertical
  entity.y += entity.vy * dt;
  left = Math.floor(entity.x / TILE_SIZE);
  right = Math.floor((entity.x + entity.w - 1) / TILE_SIZE);
  top = Math.floor(entity.y / TILE_SIZE);
  bottom = Math.floor((entity.y + entity.h) / TILE_SIZE);

  for (let tx = left; tx <= right; tx++) {
    if (entity.vy > 0) {
      if (isSolidTile(tx, bottom) && rectVsTile(entity.x, entity.y, entity.w, entity.h, tx, bottom)) {
        entity.y = bottom * TILE_SIZE - entity.h - 0.01;
        entity.vy = 0;
        entity.onGround = true;
        break;
      }
    } else if (entity.vy < 0) {
      if (isSolidTile(tx, top) && rectVsTile(entity.x, entity.y, entity.w, entity.h, tx, top)) {
        entity.y = (top + 1) * TILE_SIZE + 0.01;
        entity.vy = 0;
        break;
      }
    }
  }
}

function updatePlayer(dt) {
  const moveLeft = keys.left;
  const moveRight = keys.right;
  const wantsJump = keys.jump;

  // Horizontal movement
  if (moveLeft) {
    player.vx -= 2600 * dt;
    player.facing = -1;
  }
  if (moveRight) {
    player.vx += 2600 * dt;
    player.facing = 1;
  }

  // Clamp speed
  if (player.vx > MOVE_SPEED) player.vx = MOVE_SPEED;
  if (player.vx < -MOVE_SPEED) player.vx = -MOVE_SPEED;

  // Friction
  if (player.onGround) {
    player.vx *= FRICTION;
    if (Math.abs(player.vx) < 5) player.vx = 0;
  } else {
    player.vx *= AIR_FRICTION;
  }

  // Jump
  if (wantsJump && player.onGround) {
    player.vy = -JUMP_SPEED;
    player.onGround = false;
  }

  // Gravity
  player.vy += GRAVITY * dt;
  if (player.vy > MAX_FALL_SPEED) player.vy = MAX_FALL_SPEED;

  // Collision
  resolveCollisions(player);

  // Animation state
  if (!player.onGround) {
    player.state = "jump";
  } else if (Math.abs(player.vx) > 20) {
    player.state = "run";
  } else {
    player.state = "idle";
  }

  player.animTime += dt;
  if (player.state === "run") {
    player.frame = Math.floor(player.animTime * 12) % 6;
  } else if (player.state === "jump") {
    player.frame = 0;
  } else {
    player.frame = Math.floor(player.animTime * 4) % 4;
  }
}

function updateCamera() {
  camera.x = player.x + player.w / 2 - canvas.width / 2;
  camera.y = player.y + player.h / 2 - canvas.height / 2;

  camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
  camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
}

function drawLevel() {
  const startX = Math.floor(camera.x / TILE_SIZE);
  const endX = Math.ceil((camera.x + canvas.width) / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endY = Math.ceil((camera.y + canvas.height) / TILE_SIZE);

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (isSolidTile(x, y)) {
        ctx.fillStyle = "#4a4a5e";
        ctx.fillRect(
          x * TILE_SIZE - camera.x,
          y * TILE_SIZE - camera.y,
          TILE_SIZE,
          TILE_SIZE
        );
        ctx.fillStyle = "#5f5f78";
        ctx.fillRect(
          x * TILE_SIZE - camera.x + 4,
          y * TILE_SIZE - camera.y + 4,
          TILE_SIZE - 8,
          TILE_SIZE - 8
        );
      }
    }
  }
}

function drawPlayer() {
  const screenX = player.x - camera.x;
  const screenY = player.y - camera.y;

  // Fallback rectangle if sprite isn't loaded yet
  if (!playerImage.complete || playerImage.naturalWidth === 0) {
    ctx.fillStyle = "#ffcc66";
    ctx.fillRect(screenX, screenY, player.w, player.h);
    return;
  }

  // Basic sprite sheet animation assumptions:
  // - run: 6 frames in a row
  // - idle: 4 frames in a row
  // - jump: 1 frame
  let sx = 0, sy = 0, sw = 0, sh = 0;

  if (player.state === "run") {
    sw = playerImage.width / 6;
    sh = playerImage.height;
    sx = sw * player.frame;
    sy = 0;
  } else if (player.state === "idle") {
    sw = playerImage.width / 4;
    sh = playerImage.height;
    sx = sw * player.frame;
    sy = 0;
  } else {
    sw = playerImage.width;
    sh = playerImage.height;
    sx = 0;
    sy = 0;
  }

  ctx.save();
  if (player.facing === -1) {
    ctx.translate(screenX + player.w, screenY);
    ctx.scale(-1, 1);
    ctx.drawImage(playerImage, sx, sy, sw, sh, 0, 0, player.w, player.h);
  } else {
    ctx.drawImage(playerImage, sx, sy, sw, sh, screenX, screenY, player.w, player.h);
  }
  ctx.restore();
}

function drawUI() {
  ctx.fillStyle = "rgba(0,0,0,0.4)";
  ctx.fillRect(12, 12, 290, 70);
  ctx.fillStyle = "#fff";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys", 24, 38);
  ctx.fillText("Jump: W / Up / Space", 24, 60);
}

let lastTime = performance.now();
let dt = 0;

function gameLoop(now) {
  dt = Math.min((now - lastTime) / 1000, 0.033);
  lastTime = now;

  updatePlayer(dt);
  updateCamera();

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawLevel();
  drawPlayer();
  drawUI();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
```

