    if (keys.right) move += 1;

    if (move !== 0) {
      player.vx += move * MOVE_SPEED * dt;
      player.facing = move;
    } else {
      player.vx *= player.onGround ? FRICTION : AIR_FRICTION;
    }

    // Clamp horizontal speed
    player.vx = Math.max(-MOVE_SPEED, Math.min(MOVE_SPEED, player.vx));

    // Jump
    if (keys.jumpPressed && player.onGround) {
      player.vy = -JUMP_SPEED;
      player.onGround = false;
    }
    keys.jumpPressed = false;

    // Gravity
    player.vy += GRAVITY * dt;
    if (player.vy > MAX_FALL_SPEED) player.vy = MAX_FALL_SPEED;

    // Move X and resolve collisions
    player.x += player.vx * dt;
    rectVsTiles(player, (tx, ty) => {
      const tileRect = { x: tx * TILE, y: ty * TILE, w: TILE, h: TILE };
      if (
        player.x < tileRect.x + tileRect.w &&
        player.x + player.w > tileRect.x &&
        player.y < tileRect.y + tileRect.h &&
        player.y + player.h > tileRect.y
      ) {
        if (player.vx > 0) {
          player.x = tileRect.x - player.w;
        } else if (player.vx < 0) {
          player.x = tileRect.x + tileRect.w;
        }
        player.vx = 0;
      }
    });

    // Move Y and resolve collisions
    player.y += player.vy * dt;
    player.onGround = false;
    rectVsTiles(player, (tx, ty) => {
      const tileRect = { x: tx * TILE, y: ty * TILE, w: TILE, h: TILE };
      if (
        player.x < tileRect.x + tileRect.w &&
        player.x + player.w > tileRect.x &&
        player.y < tileRect.y + tileRect.h &&
        player.y + player.h > tileRect.y
      ) {
        if (player.vy > 0) {
          player.y = tileRect.y - player.h;
          player.vy = 0;
          player.onGround = true;
        } else if (player.vy < 0) {
          player.y = tileRect.y + tileRect.h;
          player.vy = 0;
        }
      }
    });

    // Keep inside world bounds
    player.x = Math.max(0, Math.min(world.width - player.w, player.x));
    player.y = Math.max(0, Math.min(world.height - player.h, player.y));

    // Animation
    const speed = Math.abs(player.vx);
    if (player.onGround && speed > 10) {
      player.animTime += dt;
      if (player.animTime > 0.12) {
        player.animTime = 0;
        player.animFrame = (player.animFrame + 1) % 4;
      }
    } else {
      player.animFrame = player.onGround ? 0 : 3; // idle or jump frame
    }
  }

  function updateCamera() {
    camera.x = player.x + player.w / 2 - WIDTH / 2;
    camera.y = player.y + player.h / 2 - HEIGHT / 2;

    camera.x = Math.max(0, Math.min(world.width - WIDTH, camera.x));
    camera.y = Math.max(0, Math.min(world.height - HEIGHT, camera.y));
  }

  function drawLevel() {
    const startX = Math.floor(camera.x / TILE);
    const endX = Math.ceil((camera.x + WIDTH) / TILE);
    const startY = Math.floor(camera.y / TILE);
    const endY = Math.ceil((camera.y + HEIGHT) / TILE);

    for (let y = startY; y <= endY; y++) {
      for (let x = startX; x <= endX; x++) {
        if (isSolidTile(x, y)) {
          const px = x * TILE - camera.x;
          const py = y * TILE - camera.y;

          // simple block styling
          ctx.fillStyle = "#4b5563";
          ctx.fillRect(px, py, TILE, TILE);

          ctx.fillStyle = "#6b7280";
          ctx.fillRect(px + 4, py + 4, TILE - 8, TILE - 8);

          ctx.strokeStyle = "rgba(255,255,255,0.08)";
          ctx.strokeRect(px + 0.5, py + 0.5, TILE - 1, TILE - 1);
        }
      }
    }
  }

  function drawPlayer() {
    const x = Math.floor(player.x - camera.x);
    const y = Math.floor(player.y - camera.y);

    // Shadow
    ctx.fillStyle = "rgba(0,0,0,0.2)";
    ctx.beginPath();
    ctx.ellipse(x + player.w / 2, y + player.h + 6, 18, 6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Sprite animation placeholder: draw a stylized character with frame variation
    const frameColors = ["#ffcc66", "#ffd98a", "#ffbf4d", "#ffe6b3"];
    const bodyColor = frameColors[player.animFrame];

    // Body
    ctx.fillStyle = bodyColor;
    ctx.fillRect(x, y, player.w, player.h);

    // Head
    ctx.fillStyle = "#f2c9a0";
    ctx.fillRect(x + 6, y + 4, player.w - 12, 14);

    // Eyes
    ctx.fillStyle = "#222";
    const eyeX = player.facing === 1 ? x + 20 : x + 10;
    ctx.fillRect(eyeX, y + 10, 3, 3);
    ctx.fillRect(eyeX + 6, y + 10, 3, 3);

    // Legs / motion hint
    ctx.fillStyle = "#333";
    if (player.onGround && Math.abs(player.vx) > 10) {
      ctx.fillRect(x + 6, y + 38, 8, 6);
      ctx.fillRect(x + 20, y + 38, 8, 6);
    } else {
      ctx.fillRect(x + 8, y + 38, 6, 6);
      ctx.fillRect(x + 20, y + 38, 6, 6);
    }

    // Facing direction indicator
    ctx.fillStyle = "#ff4d4d";
    if (player.facing === 1) {
      ctx.fillRect(x + player.w - 4, y + 18, 4, 8);
    } else {
      ctx.fillRect(x, y + 18, 4, 8);
    }
  }

  function drawBackground() {
    // parallax-ish clouds
    ctx.fillStyle = "#ffffff66";
    for (let i = 0; i < 8; i++) {
      const cx = ((i * 220 - camera.x * 0.2) % (WIDTH + 300)) - 150;
      const cy = 60 + (i % 3) * 40;
      ctx.beginPath();
      ctx.ellipse(cx, cy, 40, 16, 0, 0, Math.PI * 2);
      ctx.ellipse(cx + 28, cy + 4, 30, 14, 0, 0, Math.PI * 2);
      ctx.ellipse(cx - 28, cy + 4, 28, 12, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = Math.min(1 / 30, (now - last) / 1000);
    last = now;

    updatePlayer(dt);
    updateCamera();

    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    drawBackground();
    drawLevel();
    drawPlayer();

    // HUD
    ctx.fillStyle = "#00000088";
    ctx.fillRect(12, 12, 220, 54);
    ctx.fillStyle = "#fff";
    ctx.font = "16px sans-serif";
    ctx.fillText("Move: A/D or ←/→", 22, 34);
    ctx.fillText("Jump: W / Space / ↑", 22, 54);

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

