## 3) `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

canvas.width = 960;
canvas.height = 540;

// -----------------------------
// Input
// -----------------------------
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// -----------------------------
// Utility
// -----------------------------
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

// -----------------------------
// Game objects
// -----------------------------
const world = {
  gravity: 0.6,
  friction: 0.82,
  platforms: [
    { x: 0, y: 500, w: 2000, h: 40 },     // ground
    { x: 250, y: 400, w: 200, h: 20 },
    { x: 550, y: 330, w: 180, h: 20 },
    { x: 820, y: 280, w: 220, h: 20 },
    { x: 1200, y: 420, w: 250, h: 20 },
    { x: 1550, y: 360, w: 180, h: 20 },
  ],
};

const player = {
  x: 100,
  y: 300,
  w: 48,
  h: 64,
  vx: 0,
  vy: 0,
  speed: 0.8,
  jumpPower: 12.5,
  grounded: false,
  facing: 1, // 1 = right, -1 = left
  state: "idle", // idle, run, jump
  animFrame: 0,
  animTimer: 0,
};

// -----------------------------
// Sprite animation setup
// -----------------------------
// Replace these with real sprite sheets if available.
const sprites = {
  idle: null,
  run: null,
  jump: null,
};

function loadImage(src) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.src = src;
  });
}

async function loadSprites() {
  try {
    sprites.idle = await loadImage("assets/player_idle.png");
    sprites.run = await loadImage("assets/player_run.png");
    sprites.jump = await loadImage("assets/player_jump.png");
  } catch (e) {
    console.warn("Sprite loading failed; using placeholder rendering.");
  }
}

// -----------------------------
// Physics and collisions
// -----------------------------
function moveAndCollide(entity, platforms) {
  // Horizontal movement
  entity.x += entity.vx;
  for (const p of platforms) {
    if (rectsIntersect(entity, p)) {
      if (entity.vx > 0) {
        entity.x = p.x - entity.w;
      } else if (entity.vx < 0) {
        entity.x = p.x + p.w;
      }
      entity.vx = 0;
    }
  }

  // Vertical movement
  entity.y += entity.vy;
  entity.grounded = false;
  for (const p of platforms) {
    if (rectsIntersect(entity, p)) {
      if (entity.vy > 0) {
        entity.y = p.y - entity.h;
        entity.vy = 0;
        entity.grounded = true;
      } else if (entity.vy < 0) {
        entity.y = p.y + p.h;
        entity.vy = 0;
      }
    }
  }
}

// -----------------------------
// Update
// -----------------------------
function update(dt) {
  // Movement input
  if (keys.left) {
    player.vx -= player.speed;
    player.facing = -1;
  }
  if (keys.right) {
    player.vx += player.speed;
    player.facing = 1;
  }

  // Clamp horizontal speed
  player.vx = clamp(player.vx, -5, 5);

  // Jump
  if (keys.jump && player.grounded) {
    player.vy = -player.jumpPower;
    player.grounded = false;
  }

  // Gravity
  player.vy += world.gravity;
  player.vy = clamp(player.vy, -20, 16);

  // Friction
  if (player.grounded) {
    player.vx *= world.friction;
    if (Math.abs(player.vx) < 0.05) player.vx = 0;
  }

  // Move and collide
  moveAndCollide(player, world.platforms);

  // Determine state
  if (!player.grounded) {
    player.state = "jump";
  } else if (Math.abs(player.vx) > 0.2) {
    player.state = "run";
  } else {
    player.state = "idle";
  }

  // Animation timer
  player.animTimer += dt;
  const frameDuration = player.state === "run" ? 0.08 : 0.18;
  if (player.animTimer >= frameDuration) {
    player.animTimer = 0;
    player.animFrame = (player.animFrame + 1) % 4; // assume 4 frames
  }
}

// -----------------------------
// Camera
// -----------------------------
const camera = {
  x: 0,
  y: 0,
  follow(target) {
    this.x = target.x + target.w / 2 - canvas.width / 2;
    this.y = target.y + target.h / 2 - canvas.height / 2;
    this.x = clamp(this.x, 0, 2000 - canvas.width);
    this.y = clamp(this.y, 0, 0); // keep fixed vertically for now
  },
};

// -----------------------------
// Rendering
// -----------------------------
function drawPlatform(p) {
  ctx.fillStyle = "#3c2f2f";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

  ctx.fillStyle = "#5c4638";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
}

function drawPlayer() {
  const screenX = player.x - camera.x;
  const screenY = player.y - camera.y;

  const img =
    player.state === "jump" ? sprites.jump :
    player.state === "run" ? sprites.run :
    sprites.idle;

  if (img) {
    // Basic sprite sheet rendering:
    // assumes 4 horizontal frames in each sheet
    const frameCount = 4;
    const frameWidth = img.width / frameCount;
    const frameHeight = img.height;

    ctx.save();
    if (player.facing === -1) {
      ctx.translate(screenX + player.w / 2, screenY + player.h / 2);
      ctx.scale(-1, 1);
      ctx.translate(-(screenX + player.w / 2), -(screenY + player.h / 2));
    }

    ctx.drawImage(
      img,
      frameWidth * player.animFrame, 0, frameWidth, frameHeight,
      screenX, screenY, player.w, player.h
    );
    ctx.restore();
  } else {
    // Placeholder rectangle if sprites are missing
    ctx.fillStyle = player.state === "jump" ? "#ffcc00" : player.state === "run" ? "#00cc88" : "#ff6699";
    ctx.fillRect(screenX, screenY, player.w, player.h);
  }
}

function drawBackground() {
  // simple parallax-ish sky
  ctx.fillStyle = "#87ceeb";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.55)";
  for (let i = 0; i < 5; i++) {
    const x = (i * 260 - camera.x * 0.2) % (canvas.width + 300) - 100;
    const y = 60 + (i % 3) * 40;
    ctx.beginPath();
    ctx.arc(x, y, 25, 0, Math.PI * 2);
    ctx.arc(x + 25, y - 10, 30, 0, Math.PI * 2);
    ctx.arc(x + 55, y, 22, 0, Math.PI * 2);
    ctx.fill();
  }
}

// -----------------------------
// Main loop
// -----------------------------
let lastTime = 0;

function loop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
  lastTime = timestamp;

  update(dt);
  camera.follow(player);

  drawBackground();
  for (const p of world.platforms) drawPlatform(p);
  drawPlayer();

  requestAnimationFrame(loop);
}

// Start
loadSprites().then(() => {
  requestAnimationFrame(loop);
});
```

