    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 16, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // body
      const colors = ["#ff6b6b", "#ff8f6b", "#ffd56b", "#ffb56b"];
      const color = colors[player.animFrame];

      ctx.fillStyle = color;
      ctx.fillRect(x, y, player.w, player.h);

      // face / direction indicator
      ctx.fillStyle = "#1e1e2e";
      const eyeX = player.facing === 1 ? x + 20 : x + 8;
      ctx.fillRect(eyeX, y + 14, 4, 4);

      // legs animation
      ctx.strokeStyle = "#1e1e2e";
      ctx.lineWidth = 3;
      ctx.beginPath();
      if (player.animFrame % 2 === 0 && Math.abs(player.vx) > 0.2 && player.grounded) {
        ctx.moveTo(x + 8, y + player.h);
        ctx.lineTo(x + 6, y + player.h + 8);
        ctx.moveTo(x + 24, y + player.h);
        ctx.lineTo(x + 26, y + player.h + 2);
      } else {
        ctx.moveTo(x + 8, y + player.h);
        ctx.lineTo(x + 8, y + player.h + 8);
        ctx.moveTo(x + 24, y + player.h);
        ctx.lineTo(x + 24, y + player.h + 8);
      }
      ctx.stroke();
    }

    function drawBackground() {
      // simple parallax-like hills
      ctx.fillStyle = "#b6e3a8";
      for (let i = -1; i < 6; i++) {
        const baseX = i * 300 - (camera.x * 0.2) % 300;
        ctx.beginPath();
        ctx.arc(baseX + 100, canvas.height - 80, 80, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      for (const p of platforms) drawPlatform(p);
      drawPlayer();

      // debug text
      ctx.fillStyle = "#000";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 10, canvas.height - 20);
    }

    function loop() {
      updatePlayer();
      updateCamera();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
