<body>
  <div class="hint">Move: A/D or Arrow Keys | Jump: Space / W / Up</div>
  <canvas id="game" width="800" height="450"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 0.5;
    const MOVE_SPEED = 3.2;
    const JUMP_SPEED = 10.5;

    const player = {
      x: 50,
      y: 300,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      won: false
    };

    const platforms = [
      { x: 0, y: 410, w: 800, h: 40 },   // ground
      { x: 120, y: 330, w: 120, h: 20 },
      { x: 280, y: 280, w: 120, h: 20 },
      { x: 460, y: 230, w: 120, h: 20 },
      { x: 620, y: 180, w: 120, h: 20 }
    ];

    const goal = { x: 730, y: 130, w: 24, h: 50 };

    function aabb(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      if (player.won) return;

      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * MOVE_SPEED;
      if (move !== 0) player.facing = move;

      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Physics
      player.vy += GRAVITY;

      // Horizontal move + collision
      player.x += player.vx;
      for (const p of platforms) {
        if (aabb(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Vertical move + collision
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (aabb(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep inside screen
      player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
      if (player.y > canvas.height) {
        player.x = 50;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Win condition
      if (aabb(player, goal)) {
        player.won = true;
      }

      // Simple animation
      if (Math.abs(player.vx) > 0.1 && player.onGround) {
        player.animTime += 1;
        if (player.animTime % 10 === 0) {
          player.frame = (player.frame + 1) % 4;
        }
      } else {
        player.frame = 0;
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b4636";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#7c5c43";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawPlayer() {
      // Placeholder sprite animation using simple frame colors
      const frames = ["#ff5d5d", "#ff8a5d", "#ffd15d", "#ff8a5d"];
      const color = frames[player.frame];

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w / 2, 0);
        ctx.scale(-1, 1);
        ctx.translate(-(player.x + player.w / 2), 0);
      }

      // body
      ctx.fillStyle = color;
      ctx.fillRect(player.x, player.y, player.w, player.h);

      // face/eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(player.x + 8, player.y + 14, 4, 4);
      ctx.fillRect(player.x + 20, player.y + 14, 4, 4);

      // legs animation
      ctx.fillStyle = "#333";
      const legOffset = player.frame % 2 === 0 ? 0 : 4;
      ctx.fillRect(player.x + 6, player.y + 40, 6, 8 - legOffset);
      ctx.fillRect(player.x + 20, player.y + 40, 6, 8 - (4 - legOffset));

      ctx.restore();
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd700";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(goal.x + 6, goal.y + 8, 12, 12);
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // background hills
      ctx.fillStyle = "rgba(255,255,255,0.25)";
      ctx.beginPath();
      ctx.arc(120, 400, 90, 0, Math.PI * 2);
      ctx.arc(260, 390, 120, 0, Math.PI * 2);
      ctx.arc(520, 405, 100, 0, Math.PI * 2);
      ctx.fill();

      platforms.forEach(drawPlatform);
      drawGoal();
      drawPlayer();

      if (player.won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
