  ctx.beginPath();
  ctx.arc(150, 520, 120, 0, Math.PI * 2);
  ctx.arc(420, 530, 160, 0, Math.PI * 2);
  ctx.arc(720, 520, 140, 0, Math.PI * 2);
  ctx.fill();

  // platforms
  ctx.fillStyle = "#6b4f2a";
  for (const p of platforms) {
    ctx.fillRect(p.x, p.y, p.w, p.h);
  }

  // goal
  ctx.fillStyle = "#ffd700";
  ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
  ctx.fillStyle = "#333";
  ctx.fillText("Goal", goal.x - 2, goal.y - 6);

  drawPlayer();

  // UI
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 12, 24);
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
