    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Horizontal movement
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Jump
      if ((keys["w"] || keys[" "] || keys["arrowup"]) && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Apply physics
      player.vy += gravity;
      player.vx *= friction;

      // Move X and resolve collisions
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Move Y and resolve collisions
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
