      } else {
        ctx.fillRect(6, 40, 8, 8);
        ctx.fillRect(18, 40, 8, 8);
      }

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.beginPath();
      ctx.arc(120, 80, 20, 0, Math.PI * 2);
