  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const TILE = 40;
    const gravity = 0.6;
    const friction = 0.85;

    // 1 = solid block, 0 = empty
    const level = [
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000000000000000000",
      "00000111000001110000",
      "00000000000000000000",
      "00000000001100000000",
      "00000000000000000000",
      "00001110000000001110",
      "00000000000000000000",
      "00000000000000000000",
      "11111111111111111111",
      "11111111111111111111",
      "11111111111111111111"
    ];

    const world = [];
    for (let y = 0; y < level.length; y++) {
      for (let x = 0; x < level[y].length; x++) {
        if (level[y][x] === "1") {
          world.push({ x: x * TILE, y: y * TILE, w: TILE, h: TILE });
        }
      }
    }

    const player = {
      x: 80,
      y: 100,
      w: 28,
      h: 36,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTick: 0
    };

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal
      entity.x += entity.vx;
      for (const s of solids) {
        if (rectsIntersect(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Vertical
      entity.y += entity.vy;
      for (const s of solids) {
        if (rectsIntersect(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      player.vx *= friction;
      player.vy += gravity;

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      resolveCollisions(player, world);

      // Simple animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.animTick++;
        if (player.animTick > 8) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTick = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTick = 0;
      }

      // Keep player in bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height + 200) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawWorld() {
      ctx.fillStyle = "#4b3f2f";
      for (const s of world) {
        ctx.fillRect(s.x, s.y, s.w, s.h);
        ctx.strokeStyle = "rgba(0,0,0,0.2)";
        ctx.strokeRect(s.x, s.y, s.w, s.h);
      }
    }

    function drawPlayer() {
      // "Sprite animation" via simple frame colors
      const frames = ["#ff4d4d", "#ff7a4d", "#ffd24d", "#7dff4d"];
      const color = frames[player.animFrame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, player.w, player.h);

      // eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(8, 10, 4, 4);
      ctx.fillRect(16, 10, 4, 4);

      // legs/feet animation
      ctx.fillStyle = "#222";
      if (player.animFrame % 2 === 0 && player.onGround) {
        ctx.fillRect(6, 30, 6, 6);
        ctx.fillRect(16, 30, 6, 6);
      } else {
        ctx.fillRect(8, 30, 4, 6);
        ctx.fillRect(18, 30, 4, 6);
      }

      ctx.restore();
    }

    function drawBackground() {
      // simple clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      ctx.beginPath();
      ctx.arc(120, 80, 20, 0, Math.PI * 2);
      ctx.arc(145, 70, 28, 0, Math.PI * 2);
      ctx.arc(175, 82, 22, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(600, 100, 18, 0, Math.PI * 2);
      ctx.arc(625, 90, 26, 0, Math.PI * 2);
      ctx.arc(655, 102, 20, 0, Math.PI * 2);
      ctx.fill();
    }

    function loop() {
      updatePlayer();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
