    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.82,
      width: 3000,
      height: 1200
    };

    const player = {
      x: 100,
      y: 100,
      w: 40,
      h: 56,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animTime: 0
    };

    const platforms = [
      { x: 0, y: 700, w: 900, h: 40 },
      { x: 980, y: 620, w: 220, h: 30 },
      { x: 1280, y: 540, w: 240, h: 30 },
      { x: 1650, y: 650, w: 260, h: 30 },
      { x: 2000, y: 580, w: 220, h: 30 },
      { x: 2350, y: 500, w: 240, h: 30 },
      { x: 2700, y: 650, w: 300, h: 40 },
      { x: 0, y: 1100, w: 3000, h: 100 } // ground
    ];

    const camera = { x: 0, y: 0 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      // Move X and resolve collisions
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Move Y and resolve collisions
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep inside world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      player.y = Math.min(world.height - player.h, player.y);

      // Animation timer
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.animTime += 0.15;
      } else {
        player.animTime += 0.05;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b5563";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      // top highlight
      ctx.fillStyle = "#6b7280";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Simple sprite-like animation using shapes
      const frame = Math.floor(player.animTime * 8) % 4;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

