      ctx.fillRect(x + 16 + eyeOffset, y + 10, 3, 3);
      ctx.fillRect(x + 24 + eyeOffset, y + 10, 3, 3);

      // legs animation
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      const legSwing = player.onGround ? (frame % 2 === 0 ? 4 : -4) : 0;

      ctx.beginPath();
      ctx.moveTo(x + 14, y + 44);
      ctx.lineTo(x + 10 + legSwing, y + 54);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(x + 26, y + 44);
      ctx.lineTo(x + 30 - legSwing, y + 54);
      ctx.stroke();

      // arms
      ctx.beginPath();
      ctx.moveTo(x + 8, y + 22);
      ctx.lineTo(x + 2, y + 30);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(x + 32, y + 22);
      ctx.lineTo(x + 38, y + 30);
      ctx.stroke();
    }

    function drawBackground() {
      // simple parallax-ish clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      for (let i = 0; i < 8; i++) {
        const cx = (i * 420 - camera.x * 0.3) % (canvas.width + 500) - 100;
        const cy = 80 + (i % 3) * 60;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 40, 20, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 30, cy + 5, 50, 25, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 65, cy, 35, 18, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // platforms
      for (const p of platforms) drawPlatform(p);

      drawPlayer();
    }

    function loop() {
      updatePlayer();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
