  }

  // Sprite animation
  if (player.onGround && Math.abs(player.vx) > 0) {
    player.animTimer++;
    if (player.animTimer > 8) {
      player.animFrame = (player.animFrame + 1) % 4;
      player.animTimer = 0;
    }
