  const y = player.y - camera.y;

  // Simple animated "sprite" made of rectangles
  const colors = ["#ff6b6b", "#ff8fab", "#ffd166", "#06d6a0"];
  const bodyColor = colors[player.animFrame];

  // Shadow
  ctx.fillStyle = "rgba(0,0,0,0.2)";
  ctx.beginPath();
  ctx.ellipse(x + player.w/2, y + player.h + 4, 16, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  ctx.fillStyle = bodyColor;
  ctx.fillRect(x, y, player.w, player.h);

  // Face/eye to show facing direction
  ctx.fillStyle = "#111";
  const eyeX = player.facing === 1 ? x + 22 : x + 8;
  ctx.fillRect(eyeX, y + 14, 4, 4);

  // Legs animation
  ctx.fillStyle = "#333";
  const legOffset = player.animFrame % 2 === 0 ? 0 : 4;
  ctx.fillRect(x + 6, y + 42, 6, 6 + legOffset);
  ctx.fillRect(x + 20, y + 42, 6, 6 + (4 - legOffset));
}

function drawBackground() {
  // simple parallax hills
  ctx.fillStyle = "#b7e4c7";
  for (let i = -1; i < 10; i++) {
