    ctx.arc(hillX + 110, canvas.height - 40, 90, 0, Math.PI * 2);
    ctx.fill();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBackground();

  for (const p of platforms) drawPlatform(p);
  drawPlayer();

  // UI
  ctx.fillStyle = "#111";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 16, 28);
}

function loop() {
  updatePlayer();
  draw();
  requestAnimationFrame(loop);
}

loop();
