      { x: 780, y: 240, w: 140, h: 20 },
      { x: 980, y: 180, w: 140, h: 20 },
      { x: 1180, y: 260, w: 180, h: 20 },
      { x: 1440, y: 330, w: 160, h: 20 },
      { x: 1700, y: 400, w: 180, h: 20 }
    ];

    const goal = { x: 1880, y: 340, w: 40, h: 160 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      player.vx = 0;
      if (left) {
        player.vx = -MOVE_SPEED;
        player.facing = -1;
      }
      if (right) {
        player.vx = MOVE_SPEED;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      player.vy += GRAVITY;

      // Horizontal movement + collision
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Vertical movement + collision
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep inside world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height + 200) {
        player.x = 100;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Simple animation
      if (Math.abs(player.vx) > 0.1 && player.onGround) {
        player.animTime += 1;
        if (player.animTime % 10 === 0) {
          player.frame = (player.frame + 1) % 4;
        }
      } else {
        player.frame = 0;
      }

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You reached the goal!");
        player.x = 100;
        player.y = 300;
        player.vy = 0;
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5c3b1e";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#7a4b24";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd700";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(goal.x + 10, goal.y + 20, 20, 20);
    }

    function drawPlayer() {
      const colors = ["#ff4d4d", "#ff7a7a", "#ffb84d", "#ff4d4d"];
      const color = colors[player.frame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // Body
