      ctx.fillRect(4, 8, 24, 32);

      // Head
      ctx.fillStyle = "#ffe0bd";
      ctx.fillRect(8, 0, 16, 12);

      // Eyes
      ctx.fillStyle = "#000";
      ctx.fillRect(11, 4, 3, 3);
      ctx.fillRect(18, 4, 3, 3);

      // Legs animation
      ctx.fillStyle = "#333";
      if (player.onGround && Math.abs(player.vx) > 0.1) {
        if (player.frame % 2 === 0) {
          ctx.fillRect(6, 40, 8, 8);
          ctx.fillRect(18, 38, 8, 10);
        } else {
          ctx.fillRect(6, 38, 8, 10);
          ctx.fillRect(18, 40, 8, 8);
        }
      } else {
        ctx.fillRect(6, 39, 8, 9);
        ctx.fillRect(18, 39, 8, 9);
      }

      ctx.restore();
    }

    function drawBackground() {
      // Simple parallax-ish hills
      ctx.fillStyle = "#7ec850";
      ctx.fillRect(0, 470, canvas.width, 70);

      ctx.fillStyle = "#6ab04c";
      for (let i = 0; i < 10; i++) {
        const x = (i * 220 - cameraX * 0.4) % (canvas.width + 220) - 100;
        ctx.beginPath();
        ctx.arc(x, 500, 80, Math.PI, 0);
        ctx.fill();
      }
    }

    let cameraX = 0;

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x - canvas.width / 2));
      ctx.save();
      ctx.translate(-cameraX, 0);

      drawBackground();
      for (const p of platforms) drawPlatform(p);
      drawGoal();
      drawPlayer();

      ctx.restore();

      // HUD
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, 40, 190, 26);
      ctx.fillStyle = "white";
      ctx.fillText(`X: ${Math.floor(player.x)} Y: ${Math.floor(player.y)}`, 18, 58);
    }

    function loop() {
      updatePlayer();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
