<body>
  <div class="hint">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.82
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 160, h: 20 },
      { x: 760, y: 240, w: 140, h: 20 },
      { x: 420, y: 460, w: 120, h: 20 },
      { x: 220, y: 300, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 190, w: 24, h: 50 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left  = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump  = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.x += player.vx;
      player.y += player.vy;

      // Horizontal bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;

      // Platform collisions
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevY = player.y - player.vy;
          const prevX = player.x - player.vx;

          // Landing on top
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting from below
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Side collisions
          else if (prevX + player.w <= p.x) {
            player.x = p.x - player.w;
            player.vx = 0;
          } else if (prevX >= p.x + p.w) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

