      const moving = Math.abs(player.vx) > 0.2;
      if (moving && player.onGround) {
        player.animTimer++;
        if (player.animTimer > 8) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }

      // Friction
      if (player.onGround) {
        player.vx *= world.friction;
      } else {
        player.vx *= 0.99;
      }

      requestAnimationFrame(update);
      draw();
    }

    function drawPlayer() {
      const x = player.x;
      const y = player.y;
      const f = player.animFrame;
      const dir = player.facing;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(dir, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // Body
      ctx.fillStyle = "#2d6cdf";
      ctx.fillRect(6, 14, 20, 22);

      // Head
      ctx.fillStyle = "#ffd7b5";
      ctx.fillRect(8, 0, 16, 16);

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(12, 6, 2, 2);
      ctx.fillRect(16, 6, 2, 2);

      // Legs animation
      ctx.fillStyle = "#1f3f7a";
      if (player.onGround && Math.abs(player.vx) > 0.2) {
