          ctx.fillRect(19, 34, 6, 12);
        } else if (f === 1) {
          ctx.fillRect(7, 34, 6, 12);
          ctx.fillRect(19, 36, 6, 10);
        } else if (f === 2) {
          ctx.fillRect(7, 36, 6, 10);
          ctx.fillRect(19, 34, 6, 12);
        } else {
          ctx.fillRect(7, 34, 6, 12);
          ctx.fillRect(19, 36, 6, 10);
        }
      } else {
        ctx.fillRect(7, 35, 6, 11);
        ctx.fillRect(19, 35, 6, 11);
      }

      // Arms
      ctx.fillStyle = "#ffd7b5";
      ctx.fillRect(2, 16, 5, 14);
      ctx.fillRect(25, 16, 5, 14);

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      ctx.beginPath(); ctx.arc(120, 90, 24, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(150, 80, 30, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(180, 92, 22, 0, Math.PI * 2); ctx.fill();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5e4b3c";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7f6a55";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      // Goal
      ctx.fillStyle = "#ffcc00";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#333";
      ctx.fillRect(goal.x + 6, goal.y + 8, 12, 12);

      // Player
      drawPlayer();

      // Ground shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.fillRect(0, 500, canvas.width, 40);
    }

    function reset() {
      player.x = 80;
      player.y = 100;
      player.vx = 0;
      player.vy = 0;
    }

    update();
  </script>
