    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.6,
      friction: 0.85,
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },   // ground
      { x: 120, y: 410, w: 160, h: 20 },
      { x: 340, y: 350, w: 180, h: 20 },
      { x: 600, y: 290, w: 160, h: 20 },
      { x: 790, y: 220, w: 120, h: 20 },
      { x: 500, y: 450, w: 120, h: 16 },
    ];

    const goal = { x: 860, y: 170, w: 24, h: 50 };

    const player = {
      x: 40,
      y: 420,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.8,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      won: false
    };

    // Simple generated sprite frames (4-frame walk cycle)
    function makeSpriteFrame(frameIndex) {
      const c = document.createElement("canvas");
      c.width = 32;
      c.height = 48;
      const g = c.getContext("2d");

      // Colors
      const skin = "#f2c29b";
      const shirt = "#4a90e2";
      const pants = "#2d3e50";
      const shoe = "#222";
      const outline = "#111";

      // Clear
      g.clearRect(0, 0, c.width, c.height);

      // Body
      g.fillStyle = shirt;
      g.fillRect(10, 18, 12, 14);

      // Head
      g.fillStyle = skin;
      g.fillRect(11, 6, 10, 10);

      // Eyes
      g.fillStyle = outline;
      g.fillRect(14, 10, 1, 1);
      g.fillRect(17, 10, 1, 1);

      // Arms
      g.fillStyle = shirt;
      g.fillRect(8, 19, 2, 8);
      g.fillRect(22, 19, 2, 8);

      // Legs animate
      g.fillStyle = pants;
      if (frameIndex === 0) {
        g.fillRect(11, 32, 4, 10);
        g.fillRect(17, 32, 4, 10);
      } else if (frameIndex === 1) {
        g.fillRect(10, 32, 4, 10);
        g.fillRect(18, 32, 4, 10);
      } else if (frameIndex === 2) {
        g.fillRect(11, 32, 4, 10);
        g.fillRect(17, 32, 4, 10);
      } else {
        g.fillRect(12, 32, 4, 10);
        g.fillRect(16, 32, 4, 10);
      }

      // Shoes
      g.fillStyle = shoe;
      g.fillRect(10, 41, 5, 2);
      g.fillRect(17, 41, 5, 2);

      return c;
    }

    const sprites = [
      makeSpriteFrame(0),
      makeSpriteFrame(1),
      makeSpriteFrame(2),
      makeSpriteFrame(3),
    ];

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      if (player.won) return;

      // Horizontal movement
      let moving = false;
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = -1;
        moving = true;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = 1;
        moving = true;
      }

      // Jump
      const jumpPressed = keys["w"] || keys[" "] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Apply physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      // Move and collide X
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Move and collide Y
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep in bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height + 100) {
        player.x = 40;
        player.y = 420;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (moving && player.onGround) {
        player.animTime += 1;
        player.frame = Math.floor(player.animTime / 8) % sprites.length;
      } else {
        player.frame = 0;
      }

      // Win condition
      if (rectsIntersect(player, goal)) {
        player.won = true;
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b4b5f";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#6c6c85";
      ctx.fillRect(p.x, p.y, p.w, 4);
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd54a";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff2a8";
      ctx.fillRect(goal.x + 6, goal.y + 8, 12, 12);
    }

    function drawPlayer() {
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(sprites[player.frame], 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(sprites[player.frame], player.x, player.y, player.w, player.h);
      }
      ctx.restore();
    }

    function drawBackground() {
      // simple clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.beginPath();
      ctx.arc(120, 90, 22, 0, Math.PI * 2);
      ctx.arc(145, 82, 28, 0, Math.PI * 2);
      ctx.arc(175, 92, 20, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(620, 70, 18, 0, Math.PI * 2);
      ctx.arc(640, 62, 26, 0, Math.PI * 2);
      ctx.arc(668, 72, 18, 0, Math.PI * 2);
      ctx.fill();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // platforms
      platforms.forEach(drawPlatform);

      // goal
      drawGoal();

      // player
      drawPlayer();

      if (player.won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
      }
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
