      { x: 820, y: 240, w: 160,  h: 20 },
      { x: 1100,y: 380, w: 200,  h: 20 },
      { x: 1400,y: 320, w: 140,  h: 20 },
      { x: 1600,y: 260, w: 180,  h: 20 },
      { x: 1900,y: 420, w: 180,  h: 20 }
    ];

    let cameraX = 0;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
