    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#5b3a1e";
        ctx.fillRect(p.x - cameraX, p.y, p.w, p.h);
        ctx.fillStyle = "#3d8f3d";
        ctx.fillRect(p.x - cameraX, p.y, p.w, 6);
      }
    }

    function drawPlayer() {
      const x = player.x - cameraX;
      const y = player.y;

      // Simple "sprite animation" frames using colors/shapes
      const colors = ["#ffcc66", "#ffb347", "#ff9933", "#ffb347"];
      const legShift = [0, 2, 4, 2][player.frame];

      // body
      ctx.fillStyle = colors[player.frame];
      ctx.fillRect(x, y, player.w, player.h);

      // face
      ctx.fillStyle = "#000";
      const eyeX = player.facing === 1 ? x + 20 : x + 8;
      ctx.fillRect(eyeX, y + 14, 4, 4);

      // legs animation
      ctx.fillStyle = "#333";
      ctx.fillRect(x + 8, y + 40, 6, 8);
      ctx.fillRect(x + 18, y + 40 + legShift, 6, 8);

      // outline
      ctx.strokeStyle = "#222";
      ctx.strokeRect(x, y, player.w, player.h);
    }

    function drawHUD() {
      ctx.fillStyle = "#000";
      ctx.font = "16px sans-serif";
      ctx.fillText(`x: ${Math.floor(player.x)} y: ${Math.floor(player.y)}`, 12, 30);
    }

    function loop() {
      update();
      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawHUD();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
