    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      width: 2000,
      height: 540,
      gravity: 0.6
    };

    const platforms = [
      { x: 0, y: 500, w: 2000, h: 40 },
      { x: 180, y: 420, w: 120, h: 20 },
      { x: 360, y: 360, w: 120, h: 20 },
      { x: 540, y: 300, w: 120, h: 20 },
      { x: 760, y: 340, w: 160, h: 20 },
      { x: 980, y: 280, w: 140, h: 20 },
      { x: 1180, y: 400, w: 160, h: 20 },
      { x: 1400, y: 330, w: 140, h: 20 },
      { x: 1600, y: 260, w: 140, h: 20 }
    ];

    const goal = { x: 1840, y: 210, w: 30, h: 80 };

    const player = {
      x: 40,
      y: 400,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 3.2,
      jumpPower: 12.5,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    let cameraX = 0;
    let won = false;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      if (!won) {
        const left = keys["a"] || keys["arrowleft"];
        const right = keys["d"] || keys["arrowright"];
        const jump = keys[" "] || keys["w"] || keys["arrowup"];

        player.vx = 0;
        if (left) {
          player.vx = -player.speed;
          player.facing = -1;
        }
        if (right) {
          player.vx = player.speed;
          player.facing = 1;
        }

        if (jump && player.onGround) {
          player.vy = -player.jumpPower;
          player.onGround = false;
        }

        // Physics
        player.vy += world.gravity;

        // Horizontal movement
        player.x += player.vx;
        for (const p of platforms) {
          if (rectsOverlap(player, p)) {
            if (player.vx > 0) player.x = p.x - player.w;
            if (player.vx < 0) player.x = p.x + p.w;
          }
        }

        // Vertical movement
        player.y += player.vy;
        player.onGround = false;
        for (const p of platforms) {
          if (rectsOverlap(player, p)) {
            if (player.vy > 0) {
              player.y = p.y - player.h;
              player.vy = 0;
              player.onGround = true;
            } else if (player.vy < 0) {
              player.y = p.y + p.h;
              player.vy = 0;
            }
          }
        }

        // Keep in world
        player.x = Math.max(0, Math.min(world.width - player.w, player.x));
        if (player.y > world.height) {
          player.x = 40;
          player.y = 400;
          player.vx = 0;
          player.vy = 0;
        }

        // Win condition
        if (rectsOverlap(player, goal)) {
          won = true;
        }

        // Animation
        if (Math.abs(player.vx) > 0.1 && player.onGround) {
          player.animTime += 1;
          if (player.animTime > 8) {
            player.frame = (player.frame + 1) % 4;
            player.animTime = 0;
          }
        } else {
          player.frame = 0;
          player.animTime = 0;
        }
      }

      cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x - canvas.width / 2));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5c4b3b";
      ctx.fillRect(p.x - cameraX, p.y, p.w, p.h);
      ctx.fillStyle = "#7d6a55";
      ctx.fillRect(p.x - cameraX, p.y, p.w, 6);
    }

    function drawPlayer() {
      const x = player.x - cameraX;
      const y = player.y;

      // Simple animated sprite made from rectangles
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(x + player.w / 2, 0);
        ctx.scale(-1, 1);
        ctx.translate(-(x + player.w / 2), 0);
      }

      // body
      ctx.fillStyle = "#2b2d42";
      ctx.fillRect(x + 8, y + 12, 16, 24);

      // head
      ctx.fillStyle = "#f2c6a0";
      ctx.fillRect(x + 9, y + 2, 14, 12);

      // legs animation
      ctx.fillStyle = "#3a86ff";
      if (player.frame === 0) {
        ctx.fillRect(x + 8, y + 36, 6, 10);
        ctx.fillRect(x + 18, y + 36, 6, 10);
      } else if (player.frame === 1) {
        ctx.fillRect(x + 7, y + 36, 6, 10);
        ctx.fillRect(x + 19, y + 36, 6, 10);
      } else if (player.frame === 2) {
        ctx.fillRect(x + 8, y + 36, 6, 10);
        ctx.fillRect(x + 18, y + 36, 6, 10);
      } else {
        ctx.fillRect(x + 9, y + 36, 6, 10);
        ctx.fillRect(x + 17, y + 36, 6, 10);
      }

      // eye
      ctx.fillStyle = "#000";
      ctx.fillRect(x + 18, y + 6, 2, 2);

      ctx.restore();
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd166";
      ctx.fillRect(goal.x - cameraX, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#ef476f";
      ctx.fillRect(goal.x - cameraX + 8, goal.y + 10, 14, 14);
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background hills
      ctx.fillStyle = "rgba(255,255,255,0.2)";
      ctx.beginPath();
      ctx.arc(200 - cameraX * 0.2, 470, 120, 0, Math.PI * 2);
      ctx.arc(520 - cameraX * 0.2, 470, 150, 0, Math.PI * 2);
      ctx.arc(900 - cameraX * 0.2, 470, 100, 0, Math.PI * 2);
      ctx.fill();

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Goal
      drawGoal();

      // Player
      drawPlayer();

      // UI
      ctx.fillStyle = "black";
      ctx.font = "20px sans-serif";
      ctx.fillText(won ? "You Win!" : "Reach the flag!", 20, 30);

      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.font = "48px sans-serif";
        ctx.fillText("You Win!", canvas.width / 2 - 90, canvas.height / 2);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
