  ctx.fillStyle = "#111";
  if (player.facing === 1) {
    ctx.fillRect(x + 18, y + 7, 2, 2);
  } else {
    ctx.fillRect(x + 12, y + 7, 2, 2);
  }

  // Arms
  ctx.fillStyle = "#ffd9b3";
  if (player.animFrame % 2 === 0 && Math.abs(player.vx) > 0) {
    ctx.fillRect(x + 2, y + 16, 6, 4);
    ctx.fillRect(x + 24, y + 16, 6, 4);
  } else {
    ctx.fillRect(x + 2, y + 18, 6, 4);
    ctx.fillRect(x + 24, y + 18, 6, 4);
  }
}

function drawBackground() {
  // simple parallax hills
  ctx.fillStyle = "#9cd67b";
  for (let i = -1; i < 6; i++) {
    const hx = i * 300 - (camera.x * 0.2 % 300);
    ctx.beginPath();
    ctx.arc(hx + 150, canvas.height - 80, 120, 0, Math.PI * 2);
    ctx.fill();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();

  for (const p of platforms) drawPlatform(p);
  drawPlayer();

  // UI
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 20, 30);
}

function loop() {
  updatePlayer();
  draw();
  requestAnimationFrame(loop);
}
loop();
</script>
</body>
</html>
```

