## 2) `main.js`

```js
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js';

const container = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  antialias: true,
  alpha: false,
  powerPreference: 'high-performance'
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
container.appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.FogExp2(0x05070d, 0.03);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x8899ff, 0.35);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(5, 8, 3);
scene.add(dirLight);

const pointLight1 = new THREE.PointLight(0x44aaff, 60, 20, 2);
pointLight1.position.set(-3, 2, 0);
scene.add(pointLight1);

const pointLight2 = new THREE.PointLight(0xff4466, 60, 20, 2);
pointLight2.position.set(3, 2, 0);
scene.add(pointLight2);

// Helpers
const grid = new THREE.GridHelper(20, 20, 0x223355, 0x112233);
grid.position.y = 0;
scene.add(grid);

// ---------- Shader Ground ----------
const groundGeometry = new THREE.PlaneGeometry(40, 40, 128, 128);

const groundMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x0a1020) },
    uColorB: { value: new THREE.Color(0x1d4ed8) },
    uColorC: { value: new THREE.Color(0x7c3aed) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.x * 0.8 + uTime * 1.5) * 0.08
                 + cos(pos.y * 0.7 + uTime * 1.2) * 0.08;
      pos.z += wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uColorC;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      float stripes = sin((vUv.x + vUv.y * 0.5) * 20.0 + uTime * 2.0);
      float glow = smoothstep(0.2, 1.0, abs(stripes));

      vec3 base = mix(uColorA, uColorB, vUv.y);
      base = mix(base, uColorC, 0.5 + 0.5 * sin(uTime + vUv.x * 6.0));

      float vignette = smoothstep(0.9, 0.2, distance(vUv, vec2(0.5)));
      vec3 color = base + glow * 0.12 + vWave * 1.5;

      // subtle emissive pulse
      color += 0.08 * sin(uTime * 3.0 + vUv.x * 10.0) * vignette;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  side: THREE.DoubleSide
});

const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.position.y = 0;
scene.add(ground);

// ---------- Main Objects ----------
const objects = new THREE.Group();
scene.add(objects);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 200, 32),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    metalness: 0.85,
    roughness: 0.18,
    emissive: 0x111122,
    emissiveIntensity: 0.4
  })
);
torus.position.set(0, 1.6, 0);
objects.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.6, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0x66ccff,
    metalness: 0.2,
    roughness: 0.05,
    emissive: 0x113355,
    emissiveIntensity: 0.6
  })
);
sphere.position.set(-2.2, 1.0, 0.5);
objects.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xff6699,
    metalness: 0.6,
    roughness: 0.25
  })
);
box.position.set(2.2, 0.8, -0.5);
objects.add(box);

// ---------- Postprocessing ----------
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.9,   // strength
  0.6,   // radius
  0.15   // threshold
);
composer.addPass(bloomPass);

// ---------- Animation Loop ----------
const clock = new THREE.Clock();

function animate() {
  const t = clock.getElapsedTime();
  const dt = clock.getDelta();

  controls.update();

  // Object motion
  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.8;

  sphere.position.y = 1.0 + Math.sin(t * 2.0) * 0.25;
  sphere.rotation.y = t * 1.2;

  box.rotation.x = t * 0.7;
  box.rotation.y = t * 1.1;
  box.position.y = 0.8 + Math.cos(t * 1.8) * 0.15;

  // Dynamic lights
  dirLight.position.x = Math.cos(t * 0.7) * 6.0;
  dirLight.position.z = Math.sin(t * 0.7) * 6.0;
  dirLight.position.y = 6.0 + Math.sin(t * 1.1) * 1.5;

  pointLight1.position.x = Math.cos(t * 1.5) * 3.5;
  pointLight1.position.z = Math.sin(t * 1.5) * 3.5;
  pointLight1.position.y = 1.8 + Math.sin(t * 2.1) * 0.6;

  pointLight2.position.x = Math.cos(t * 1.2 + Math.PI) * 3.5;
  pointLight2.position.z = Math.sin(t * 1.2 + Math.PI) * 3.5;
  pointLight2.position.y = 1.8 + Math.cos(t * 1.7) * 0.6;

  // Shader uniforms
  groundMaterial.uniforms.uTime.value = t;

  // Slight exposure breathing
  renderer.toneMappingExposure = 1.05 + Math.sin(t * 0.4) * 0.08;

  composer.render();
  requestAnimationFrame(animate);
}

animate();

// Resize
window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;

  camera.aspect = w / h;
  camera.updateProjectionMatrix();

  renderer.setSize(w, h);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  composer.setSize(w, h);
});
```

