    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    scene.add(floor);

    // Subtle grid helper
    const grid = new THREE.GridHelper(30, 30, 0x335577, 0x112233);
    grid.position.y = 0.001;
    scene.add(grid);

    // --- Animated particles ---
    const particlesCount = 400;
    const particleGeo = new THREE.BufferGeometry();
    const particlePos = new Float32Array(particlesCount * 3);

    for (let i = 0; i < particlesCount; i++) {
      particlePos[i * 3 + 0] = (Math.random() - 0.5) * 20;
      particlePos[i * 3 + 1] = Math.random() * 8 + 0.5;
      particlePos[i * 3 + 2] = (Math.random() - 0.5) * 20;
    }

    particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePos, 3));

    const particleMat = new THREE.PointsMaterial({
      color: 0x88ccff,
      size: 0.04,
      transparent: true,
      opacity: 0.9
    });

    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // --- Animation loop ---
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      object.rotation.y = t * 0.35;
      object.rotation.x = Math.sin(t * 0.4) * 0.15;

      pointLight.position.x = Math.sin(t * 1.2) * 4.0;
      pointLight.position.z = Math.cos(t * 1.2) * 4.0;

      rimLight.position.x = Math.cos(t * 0.9) * 4.0;
      rimLight.position.z = Math.sin(t * 0.9) * 4.0;

      particles.rotation.y = t * 0.05;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // --- Resize handling ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
```

