      const s = new THREE.Mesh(sphereGeo, sphereMat.clone());
      s.position.set(Math.cos(i) * 2.8, 1.2 + (i % 2) * 0.4, Math.sin(i) * 2.8);
      scene.add(s);
      orbitSpheres.push(s);
