    addObject(new THREE.IcosahedronGeometry(1, 2), shaderMaterial.clone(), -2.5, 1.2, 0);
    addObject(new THREE.TorusKnotGeometry(0.9, 0.3, 120, 16), shaderMaterial.clone(), 0, 1.4, 0);
    addObject(new THREE.SphereGeometry(1, 64, 64), shaderMaterial.clone(), 2.5, 1.1, 0);

    // Extra standard material objects for lighting contrast
    const metalMat = new THREE.MeshStandardMaterial({
      color: 0xbfc7d5,
      metalness: 1.0,
      roughness: 0.15
    });

    addObject(new THREE.BoxGeometry(1.2, 1.2, 1.2), metalMat, -1.2, 0.6, -3);
    addObject(new THREE.CylinderGeometry(0.7, 0.7, 1.6, 32), metalMat, 1.4, 0.8, -3);

    // Small helper spheres for lights
    const lightMarkerGeo = new THREE.SphereGeometry(0.12, 16, 16);
    const lightMarkerMat1 = new THREE.MeshBasicMaterial({ color: 0x00aaff });
    const lightMarkerMat2 = new THREE.MeshBasicMaterial({ color: 0xff3355 });
    const lightMarker1 = new THREE.Mesh(lightMarkerGeo, lightMarkerMat1);
    const lightMarker2 = new THREE.Mesh(lightMarkerGeo, lightMarkerMat2);
    scene.add(lightMarker1, lightMarker2);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate lights
      pointLight1.position.set(Math.sin(t * 1.2) * 4.5, 2.5 + Math.sin(t * 2.0) * 0.8, Math.cos(t * 1.2) * 4.5);
      pointLight2.position.set(Math.cos(t * 0.9) * 4.0, 2.0 + Math.cos(t * 1.7) * 0.7, Math.sin(t * 0.9) * 4.0);

      lightMarker1.position.copy(pointLight1.position);
      lightMarker2.position.copy(pointLight2.position);

      // Animate shader uniforms + object transforms
      for (let i = 0; i < objects.length; i++) {
        const obj = objects[i];
        obj.rotation.y += 0.003 + i * 0.0008;
        obj.rotation.x += 0.0015;
        if (obj.material.uniforms?.uTime) {
          obj.material.uniforms.uTime.value = t;
        }
      }

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
