        100
      );
      camera.position.set(0, 3, 8);

      // Renderer
      renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.1;
      document.body.appendChild(renderer.domElement);

      // Controls
      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.06;
      controls.target.set(0, 1, 0);

      // Clock
      clock = new THREE.Clock();

      // Lights
      const ambient = new THREE.AmbientLight(0x223344, 0.6);
      scene.add(ambient);

      const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
      dirLight.position.set(5, 8, 3);
      scene.add(dirLight);

      // Animated point lights
      const colors = [0xff4d6d, 0x4dd7ff, 0x7cff4d];
      for (let i = 0; i < 3; i++) {
        const light = new THREE.PointLight(colors[i], 2.5, 20, 2);
        light.position.set(Math.cos(i * 2.1) * 4, 2 + i, Math.sin(i * 2.1) * 4);
        scene.add(light);
        animatedLights.push(light);

        // Visible light helper sphere
        const helper = new THREE.Mesh(
          new THREE.SphereGeometry(0.08, 16, 16),
          new THREE.MeshBasicMaterial({ color: colors[i] })
        );
        light.add(helper);
      }

      // Ground
      const ground = new THREE.Mesh(
        new THREE.PlaneGeometry(50, 50),
        new THREE.MeshStandardMaterial({
          color: 0x111722,
          metalness: 0.1,
          roughness: 0.95,
        })
      );
      ground.rotation.x = -Math.PI / 2;
      ground.receiveShadow = true;
      scene.add(ground);

      // Custom shader material
      const shaderMaterial = new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0.0 },
          uColorA: { value: new THREE.Color(0x4dd7ff) },
          uColorB: { value: new THREE.Color(0xff4d6d) },
        },
        vertexShader: `
          uniform float uTime;
          varying vec3 vNormal;
          varying vec3 vPosition;

          void main() {
            vNormal = normalMatrix * normal;
            vPosition = position;

            vec3 pos = position;
            float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.08;
            wave += cos(pos.y * 4.0 + uTime * 1.7) * 0.08;
            wave += sin(pos.z * 5.0 + uTime * 1.3) * 0.08;
            pos += normal * wave;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;
          varying vec3 vNormal;
          varying vec3 vPosition;

          void main() {
            vec3 n = normalize(vNormal);
            float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.5);

            float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 4.0);
            vec3 base = mix(uColorA, uColorB, pulse);

            vec3 color = base * (0.35 + fresnel * 1.4);
            gl_FragColor = vec4(color, 1.0);
          }
        `,
      });

      // Main shader object
      shaderMesh = new THREE.Mesh(
        new THREE.IcosahedronGeometry(1.4, 5),
        shaderMaterial
      );
      shaderMesh.position.set(0, 1.8, 0);
      scene.add(shaderMesh);

      // Surrounding objects
      const torus = new THREE.Mesh(
        new THREE.TorusKnotGeometry(0.9, 0.28, 180, 24),
        new THREE.MeshStandardMaterial({
          color: 0xffffff,
          metalness: 0.8,
          roughness: 0.2,
        })
      );
      torus.position.set(-2.8, 1.6, 0);
      scene.add(torus);

      const sphere = new THREE.Mesh(
        new THREE.SphereGeometry(0.8, 64, 64),
        new THREE.MeshStandardMaterial({
          color: 0xddddff,
          metalness: 0.2,
          roughness: 0.1,
          emissive: 0x111122,
          emissiveIntensity: 0.3,
        })
      );
      sphere.position.set(2.8, 1.2, 0);
      scene.add(sphere);

      // Post-processing
      composer = new EffectComposer(renderer);
      composer.addPass(new RenderPass(scene, camera));

      const bloomPass = new UnrealBloomPass(
        new THREE.Vector2(window.innerWidth, window.innerHeight),
        0.9,   // strength
        0.5,   // radius
        0.2    // threshold
      );
      composer.addPass(bloomPass);

      // Resize
      window.addEventListener("resize", onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
    }

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Update shader uniforms
      shaderMesh.material.uniforms.uTime.value = t;

      // Animate main object
      shaderMesh.rotation.y = t * 0.45;
      shaderMesh.rotation.x = Math.sin(t * 0.6) * 0.2;

      // Animate lights in circular paths
      animatedLights.forEach((light, i) => {
        const radius = 4.0 + i * 0.7;
        const speed = 0.6 + i * 0.25;
        light.position.x = Math.cos(t * speed + i * 2.0) * radius;
        light.position.z = Math.sin(t * speed + i * 2.0) * radius;
        light.position.y = 2.0 + Math.sin(t * 1.2 + i) * 1.0;
      });

      controls.update();
      composer.render();
    }
  </script>
</body>
</html>
