```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";

// Basic setup
const app = document.getElementById("app");
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050816);
scene.fog = new THREE.Fog(0x050816, 10, 40);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
app.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.35);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.2);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x00ffff, 30, 30, 2);
pointLight.position.set(-3, 2, 0);
scene.add(pointLight);

const pointLight2 = new THREE.PointLight(0xff00ff, 20, 30, 2);
pointLight2.position.set(3, 2, 0);
scene.add(pointLight2);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.MeshStandardMaterial({ color: 0x0b1020, roughness: 1, metalness: 0 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff3df2) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vNormal;

    void main() {
      vUv = uv;
      vNormal = normal;

      vec3 p = position;
      float wave = sin(p.y * 6.0 + uTime * 2.0) * 0.08;
      p += normal * wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vUv.x * 8.0 + vUv.y * 6.0);
      vec3 color = mix(uColorA, uColorB, pulse);

      // Simple fresnel-like edge glow
      vec3 n = normalize(vNormal);
      float fresnel = pow(1.0 - abs(n.z), 2.0);

      color += fresnel * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.85, 0.28, 180, 32),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 1.0,
    roughness: 0.15,
    emissive: 0x111122,
    emissiveIntensity: 0.4
  })
);
torus.position.set(1.8, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 1.2),
  new THREE.MeshStandardMaterial({
    color: 0x99ccff,
    metalness: 0.6,
    roughness: 0.3
  })
);
box.position.set(0, 0.8, -2.5);
scene.add(box);

// Particles
const particlesCount = 1200;
const positions = new Float32Array(particlesCount * 3);

for (let i = 0; i < particlesCount; i++) {
  const r = 15 * Math.random();
  const theta = Math.random() * Math.PI * 2;
  const y = (Math.random() - 0.5) * 10;

  positions[i * 3 + 0] = Math.cos(theta) * r;
  positions[i * 3 + 1] = y;
  positions[i * 3 + 2] = Math.sin(theta) * r;
}

const particleGeometry = new THREE.BufferGeometry();
particleGeometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particleMaterial = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.04,
  transparent: true,
  opacity: 0.9
});

const particles = new THREE.Points(particleGeometry, particleMaterial);
scene.add(particles);

// Post-processing
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  1.0,  // strength
  0.6,  // radius
  0.15  // threshold
);
composer.addPass(bloomPass);

// Animation
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  sphere.rotation.y = t * 0.4;
  sphere.rotation.x = Math.sin(t * 0.5) * 0.15;

  torus.rotation.x = t * 0.7;
  torus.rotation.y = t * 0.5;

  box.rotation.x = t * 0.6;
  box.rotation.y = t * 0.3;

  pointLight.position.x = Math.sin(t * 1.2) * 4;
  pointLight.position.z = Math.cos(t * 1.2) * 4;

  pointLight2.position.x = Math.cos(t * 1.0) * 4;
  pointLight2.position.z = Math.sin(t * 1.0) * 4;

  particles.rotation.y = t * 0.03;

  controls.update();
  composer.render();
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
});
