          float fres = pow(1.0 - max(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

          vec3 base = mix(uColorA, uColorB, wave);
          base += fres * 0.35;

          // subtle animated glow
          float glow = 0.15 + 0.15 * sin(uTime * 3.0 + vWorldPos.y * 2.0);
          base += glow;

          gl_FragColor = vec4(base, 1.0);
        }
      `
    });

