## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: sans-serif;
    }

    #info {
      position: absolute;
      top: 12px;
      left: 12px;
      color: white;
      z-index: 10;
      padding: 8px 12px;
      background: rgba(0, 0, 0, 0.35);
      border-radius: 8px;
      font-size: 14px;
      user-select: none;
    }

    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">Drag to orbit • Scroll to zoom • Dynamic lighting + shader effects</div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070d);
    scene.fog = new THREE.Fog(0x05070d, 10, 40);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 2.5, 7);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.target.set(0, 1, 0);

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambientLight);

    const hemisphereLight = new THREE.HemisphereLight(0x88aaff, 0x110011, 0.6);
    scene.add(hemisphereLight);

    const pointLight = new THREE.PointLight(0x00ffff, 2.5, 30, 2);
    pointLight.position.set(3, 3, 3);
    scene.add(pointLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
    directionalLight.position.set(-3, 5, 2);
    scene.add(directionalLight);

    // Floor
    const floorGeo = new THREE.PlaneGeometry(80, 80, 1, 1);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x111111,
      roughness: 0.95,
      metalness: 0.05
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1;
    floor.receiveShadow = true;
    scene.add(floor);

    // Shader material
    const shaderMat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0x7c3cff) }
      },
      vertexShader: `
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          vPosition = position;
          vNormal = normal;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          float wave = sin(vPosition.y * 4.0 + uTime * 2.0) * 0.5 + 0.5;
          float pulse = sin(uTime + length(vPosition.xy) * 3.0) * 0.5 + 0.5;
          float mixFactor = clamp(wave * 0.7 + pulse * 0.3, 0.0, 1.0);

          vec3 color = mix(uColorA, uColorB, mixFactor);

          // simple fake lighting
          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));
          float diffuse = max(dot(normalize(vNormal), lightDir), 0.0);
          diffuse = diffuse * 0.8 + 0.2;

          gl_FragColor = vec4(color * diffuse, 1.0);
        }
      `
    });

    // Objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 200, 32),
      shaderMat
    );
    torus.position.y = 1.2;
    scene.add(torus);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.7, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.9,
        roughness: 0.15,
        emissive: 0x111122,
        emissiveIntensity: 0.6
      })
    );
    sphere.position.set(-2.5, 0.2, 0);
    scene.add(sphere);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0x2222ff,
        metalness: 0.4,
        roughness: 0.3
      })
    );
    box.position.set(2.5, 0, 0);
    scene.add(box);

    // Particles
    const particleCount = 1200;
    const particleGeo = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      const r = 12 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);

      positions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
      positions[i * 3 + 1] = r * Math.cos(phi) * 0.6 + 1.5;
      positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
    }

    particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

    const particleMat = new THREE.PointsMaterial({
      color: 0x88ccff,
      size: 0.04,
      transparent: true,
      opacity: 0.8,
      depthWrite: false
    });

    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMat.uniforms.uTime.value = t;

      // Dynamic lighting motion
      pointLight.position.x = Math.sin(t * 1.3) * 4.0;
      pointLight.position.z = Math.cos(t * 1.3) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

      directionalLight.position.x = Math.cos(t * 0.4) * 5.0;
      directionalLight.position.z = Math.sin(t * 0.4) * 5.0;

      // Object motion
      torus.rotation.x = t * 0.4;
      torus.rotation.y = t * 0.7;

      sphere.rotation.y = t * 0.9;
      sphere.position.y = 0.2 + Math.sin(t * 2.2) * 0.25;

      box.rotation.x = t * 0.6;
      box.rotation.y = t * 0.8;

      particles.rotation.y = t * 0.03;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
