  </style>
</head>
<body>
  <div id="info">
    <strong>3D Scene Viewer</strong><br />
    Drag to orbit · Scroll to zoom
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
    import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
    import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
    import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";

    // Scene / Camera / Renderer
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 10, 40);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 8);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lighting
    const ambient = new THREE.AmbientLight(0x223355, 0.8);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(5, 8, 3);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x00aaff, 3, 30, 2);
    pointLight.position.set(0, 3, 0);
    scene.add(pointLight);

    const pointLight2 = new THREE.PointLight(0xff3366, 2.5, 30, 2);
    pointLight2.position.set(0, -2, 0);
    scene.add(pointLight2);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(50, 50);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x0b1020,
      roughness: 1,
      metalness: 0
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Custom shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff3d81) }
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vUv = uv;
          vNormal = normalize(normalMatrix * normal);
          vec4 worldPos = modelMatrix * vec4(position, 1.0);
          vWorldPos = worldPos.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          float wave = sin(vUv.y * 12.0 + uTime * 2.0) * 0.5 + 0.5;
          float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 3.0);
          vec3 base = mix(uColorA, uColorB, wave);
          vec3 color = base + fresnel * 0.8;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Main object
    const sphere = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.25, 5),
      shaderMaterial
    );
    sphere.position.y = 0.7;
    scene.add(sphere);

    // Floating ring
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(2.2, 0.08, 16, 100),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 1,
        roughness: 0.15,
        emissive: 0x112244,
        emissiveIntensity: 0.8
      })
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.7;
    scene.add(ring);

    // Small orbiting particles
    const particleGeo = new THREE.SphereGeometry(0.06, 16, 16);
    const particleMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x66ccff,
      emissiveIntensity: 2,
      metalness: 0.2,
      roughness: 0.2
    });

    const particles = [];
    for (let i = 0; i < 20; i++) {
      const p = new THREE.Mesh(particleGeo, particleMat);
      const angle = (i / 20) * Math.PI * 2;
      p.position.set(Math.cos(angle) * 3, 0.4 + Math.sin(i) * 0.5, Math.sin(angle) * 3);
      scene.add(p);
      particles.push({ mesh: p, angle, radius: 3, speed: 0.3 + Math.random() * 0.5 });
    }

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.2,  // strength
      0.4,  // radius
      0.85  // threshold
    );
    composer.addPass(bloomPass);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      controls.update();

      // Dynamic lighting movement
      pointLight.position.x = Math.sin(t * 1.2) * 4;
      pointLight.position.z = Math.cos(t * 1.2) * 4;
      pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 1.0;

      pointLight2.position.x = Math.cos(t * 0.9) * 5;
      pointLight2.position.z = Math.sin(t * 0.9) * 5;
      pointLight2.position.y = 1.0 + Math.cos(t * 1.5) * 1.2;

      // Animate objects
      sphere.rotation.y = t * 0.35;
      sphere.rotation.x = Math.sin(t * 0.5) * 0.15;
      ring.rotation.z = t * 0.6;

      shaderMaterial.uniforms.uTime.value = t;

      particles.forEach((p, i) => {
        p.angle += 0.01 * p.speed;
        p.mesh.position.x = Math.cos(p.angle) * p.radius;
        p.mesh.position.z = Math.sin(p.angle) * p.radius;
        p.mesh.position.y = 0.5 + Math.sin(t * 2 + i) * 0.5;
      });

      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
```

