<body>
  <div id="info">
    <strong>3D Scene Viewer</strong><br/>
    Drag: rotate | Scroll: zoom | Right-drag: pan
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
    import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
    import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
    import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 10, 40);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 7);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1, 0);

    // Lights
    const ambient = new THREE.AmbientLight(0x7aa7ff, 0.25);
    scene.add(ambient);

    const hemi = new THREE.HemisphereLight(0x88aaff, 0x111122, 0.6);
    scene.add(hemi);

    const pointLight = new THREE.PointLight(0xff66cc, 2.5, 30, 2);
    pointLight.position.set(3, 3, 3);
    scene.add(pointLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(-3, 5, 2);
    scene.add(dirLight);

    // Floor
    const floorGeo = new THREE.PlaneGeometry(50, 50);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x0b1020,
      metalness: 0.2,
      roughness: 0.9
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1;
    floor.receiveShadow = true;
    scene.add(floor);

    // Shader material for the main object
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff4fd8) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vUv = uv;
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position;
          float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.08
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.08
                     + sin(pos.z * 5.0 + uTime * 2.5) * 0.08;
          pos += normal * wave;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPos = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
          float diff = max(dot(n, lightDir), 0.0);

          float fresnel = pow(1.0 - max(dot(n, normalize(-vWorldPos)), 0.0), 3.0);

          float stripes = 0.5 + 0.5 * sin((vUv.y * 20.0) + uTime * 3.0);
          vec3 base = mix(uColorA, uColorB, stripes);

          vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.8;
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Main object
    const geometry = new THREE.IcosahedronGeometry(1.5, 5);
    const objectMesh = new THREE.Mesh(geometry, shaderMaterial);
    objectMesh.position.y = 1.2;
    scene.add(objectMesh);

    // Decorative ring
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(2.5, 0.06, 16, 200),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        emissive: 0x2244ff,
        emissiveIntensity: 1.5,
        metalness: 0.8,
        roughness: 0.2
      })
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 1.2;
    scene.add(ring);

    // Particles
    const particleCount = 1200;
    const particlePositions = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      const r = 12 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      particlePositions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
      particlePositions[i * 3 + 1] = r * Math.cos(phi) * 0.6;
      particlePositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
    }

    const particlesGeo = new THREE.BufferGeometry();
    particlesGeo.setAttribute("position", new THREE.BufferAttribute(particlePositions, 3));
    const particlesMat = new THREE.PointsMaterial({
      color: 0x88ccff,
      size: 0.03,
      transparent: true,
      opacity: 0.8
    });
    const particles = new THREE.Points(particlesGeo, particlesMat);
    scene.add(particles);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.1,   // strength
      0.5,   // radius
      0.2    // threshold
    );
    composer.addPass(bloomPass);

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
    });

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      objectMesh.rotation.y = t * 0.35;
      objectMesh.rotation.x = Math.sin(t * 0.25) * 0.15;

      ring.rotation.z = t * 0.35;

      pointLight.position.x = Math.sin(t * 1.2) * 4.0;
      pointLight.position.z = Math.cos(t * 1.2) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.7;

      particles.rotation.y = t * 0.03;
      controls.update();

      composer.render();
    }

    animate();
  </script>
