      positions[i * 3 + 2] = Math.sin(theta) * r;
    }
    particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    const particleMat = new THREE.PointsMaterial({
      color: 0x88aaff,
      size: 0.05,
      transparent: true,
      opacity: 0.7,
      depthWrite: false
    });

    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.2,   // strength
      0.4,   // radius
      0.85   // threshold
    );
    composer.addPass(bloomPass);

    // Animate
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Update shader uniforms
      glowMaterial.uniforms.uTime.value = t;

      // Animate lights
      pointLight.position.x = Math.sin(t * 1.2) * 3.5;
      pointLight.position.z = Math.cos(t * 1.2) * 3.5;
      pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.5;

      movingLight.position.x = Math.cos(t * 0.8) * 6.0;
      movingLight.position.z = Math.sin(t * 0.8) * 6.0;
      movingLight.position.y = 1.5 + Math.sin(t * 1.7) * 1.2;

      // Animate objects
      sphere.rotation.y = t * 0.6;
      sphere.position.y = 1.2 + Math.sin(t * 2.2) * 0.25;

      torus.rotation.x = t * 0.4;
      torus.rotation.y = t * 0.7;

      cubes.forEach((cube, i) => {
        cube.userData.angle += 0.003 + i * 0.0002;
        const a = cube.userData.angle;
        const r = cube.userData.radius;
        cube.position.x = Math.cos(a) * r;
        cube.position.z = Math.sin(a) * r;
        cube.position.y = 0.5 + Math.sin(t * 2 + i) * 0.25;
        cube.rotation.x = t + i;
        cube.rotation.y = t * 0.7 + i * 0.3;
      });

      particles.rotation.y = t * 0.03;

      controls.update();
      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```

