## 5) `main.js`

```js
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

// --- Renderer ---
const container = document.getElementById('app');

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  powerPreference: 'high-performance'
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
container.appendChild(renderer.domElement);

// --- Scene ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 40);

// Environment for better lighting response
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

// --- Camera ---
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 8);

// --- Controls ---
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// --- Lights ---
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
dirLight.position.set(5, 8, 4);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66aaff, 20, 20, 2);
pointLight.position.set(0, 2.5, 0);
scene.add(pointLight);

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x10131a,
  roughness: 0.95,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// --- Custom shader material (dynamic effect) ---
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00d4ff) },
  uColorB: { value: new THREE.Color(0x7c3aed) }
};

const shaderMat = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

      float diff = max(dot(n, lightDir), 0.0);
      float fresnel = pow(1.0 - max(dot(n, normalize(cameraPosition - vWorldPos)), 0.0), 3.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 4.0);
      vec3 base = mix(uColorA, uColorB, wave);

      vec3 color = base * (0.2 + diff * 0.9) + fresnel * 0.8;
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// --- Objects ---
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMat
);
sphere.position.set(-1.5, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.85,
    roughness: 0.15,
    emissive: 0x111122,
    emissiveIntensity: 0.5
  })
);
torus.position.set(1.8, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    metalness: 0.2,
    roughness: 0.35
  })
);
box.position.set(0, 0.5, -2.5);
scene.add(box);

// --- Small moving light marker ---
const lightMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x66aaff })
);
scene.add(lightMarker);

// --- Animation loop ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  shaderUniforms.uTime.value = t;

  // Dynamic light motion
  pointLight.position.x = Math.sin(t * 1.2) * 3.5;
  pointLight.position.z = Math.cos(t * 1.2) * 3.5;
  pointLight.position.y = 2.2 + Math.sin(t * 2.0) * 0.6;

  lightMarker.position.copy(pointLight.position);

  // Object motion
  sphere.rotation.y = t * 0.7;
  sphere.rotation.x = Math.sin(t * 0.5) * 0.2;

  torus.rotation.x = t * 0.6;
  torus.rotation.y = t * 0.9;

  box.rotation.x = t * 0.8;
  box.rotation.y = t * 0.5;
  box.position.y = 0.5 + Math.sin(t * 1.5) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize handling ---
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

