## 4) `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

let scene, camera, renderer, controls;
let clock;
let shaderMesh, floor, pointLight, dirLight;

init();
animate();

function init() {
  const container = document.getElementById("app");

  // Scene
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x05060a);
  scene.fog = new THREE.Fog(0x05060a, 10, 40);

  // Camera
  camera = new THREE.PerspectiveCamera(
    60,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(4, 3, 8);

  // Renderer
  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.2;
  container.appendChild(renderer.domElement);

  // Controls
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.05;
  controls.target.set(0, 1, 0);

  // Lights
  const ambient = new THREE.AmbientLight(0xffffff, 0.25);
  scene.add(ambient);

  dirLight = new THREE.DirectionalLight(0x88aaff, 1.5);
  dirLight.position.set(5, 8, 4);
  scene.add(dirLight);

  pointLight = new THREE.PointLight(0xff66cc, 30, 20, 2);
  pointLight.position.set(-2, 2, 2);
  scene.add(pointLight);

  const pointLight2 = new THREE.PointLight(0x66ffff, 20, 20, 2);
  pointLight2.position.set(2, 3, -2);
  scene.add(pointLight2);

  // Floor
  const floorGeo = new THREE.PlaneGeometry(30, 30, 1, 1);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x111318,
    roughness: 0.95,
    metalness: 0.0,
  });
  floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.01;
  scene.add(floor);

  // Main object with custom shader
  const geometry = new THREE.IcosahedronGeometry(1.2, 4);

  const uniforms = {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x6a5cff) },
    uColorB: { value: new THREE.Color(0x00d4ff) },
    uLightPos: { value: new THREE.Vector3() },
  };

  const vertexShader = `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `;

  const fragmentShader = `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 4.0 + vWorldPos.x * 2.0);
      vec3 base = mix(uColorA, uColorB, wave);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      vec3 color = base * (0.18 + diff * 1.2) + spec * vec3(1.0);
      color += fresnel * 0.8 * vec3(0.8, 0.95, 1.0);

      // subtle animated glow bands
      float bands = smoothstep(0.45, 0.55, sin(vWorldPos.y * 8.0 + uTime * 3.0) * 0.5 + 0.5);
      color += bands * 0.15 * vec3(1.0, 0.4, 0.9);

      gl_FragColor = vec4(color, 1.0);
    }
  `;

  const shaderMat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader,
  });

  shaderMesh = new THREE.Mesh(geometry, shaderMat);
  shaderMesh.position.y = 1.4;
  scene.add(shaderMesh);

  // Supporting objects
  const torus = new THREE.Mesh(
    new THREE.TorusKnotGeometry(0.55, 0.18, 180, 24),
    new THREE.MeshStandardMaterial({
      color: 0xddddff,
      metalness: 0.8,
      roughness: 0.2,
      emissive: 0x111122,
      emissiveIntensity: 0.4,
    })
  );
  torus.position.set(-2.2, 1.1, 0);
  scene.add(torus);

  const sphere = new THREE.Mesh(
    new THREE.SphereGeometry(0.55, 48, 48),
    new THREE.MeshStandardMaterial({
      color: 0x66ccff,
      metalness: 0.4,
      roughness: 0.15,
      emissive: 0x003344,
      emissiveIntensity: 0.5,
    })
  );
  sphere.position.set(2.2, 0.8, 0.5);
  scene.add(sphere);

  // Simple environment-like glow plane behind
  const backdrop = new THREE.Mesh(
    new THREE.SphereGeometry(25, 32, 32),
    new THREE.MeshBasicMaterial({
      color: 0x08101f,
      side: THREE.BackSide,
    })
  );
  scene.add(backdrop);

  clock = new THREE.Clock();

  window.addEventListener("resize", onWindowResize);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate dynamic lighting
  pointLight.position.x = Math.sin(elapsed * 1.2) * 3.5;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 3.5;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.5;

  dirLight.position.x = Math.cos(elapsed * 0.4) * 6.0;
  dirLight.position.z = Math.sin(elapsed * 0.4) * 6.0;

  // Animate shader object
  shaderMesh.rotation.y = elapsed * 0.35;
  shaderMesh.rotation.x = Math.sin(elapsed * 0.5) * 0.15;
  shaderMesh.material.uniforms.uTime.value = elapsed;
  shaderMesh.material.uniforms.uLightPos.value.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}
```

