import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("scene-canvas");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070c);
scene.fog = new THREE.Fog(0x05070c, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 3, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.5);
directionalLight.position.set(5, 10, 4);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x66aaff, 2.5, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4f46e5) },
    uColorB: { value: new THREE.Color(0x22d3ee) },
    uLightPos: { value: pointLight.position },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 lightDir = normalize(uLightPos - vWorldPos);
      float diff = max(dot(normalize(vNormal), lightDir), 0.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 3.0 + vWorldPos.x * 2.0);
      vec3 baseColor = mix(uColorA, uColorB, wave);

      vec3 ambient = 0.18 * baseColor;
      vec3 diffuse = diff * baseColor * 1.4;

      float rim = pow(1.0 - max(dot(normalize(vNormal), normalize(-vWorldPos)), 0.0), 2.0);
      vec3 rimColor = rim * vec3(0.6, 0.8, 1.0);

      vec3 finalColor = ambient + diffuse + rimColor;
      gl_FragColor = vec4(finalColor, 1.0);
    }
  `,
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 160, 32),
  new THREE.MeshStandardMaterial({
    color: 0xff6b6b,
    metalness: 0.7,
    roughness: 0.25,
  })
);
torus.position.set(2.2, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 1.2),
  new THREE.MeshStandardMaterial({
    color: 0x7cfc98,
    metalness: 0.2,
    roughness: 0.5,
  })
);
box.position.set(0, 1.2, -2.2);
scene.add(box);

// Subtle particle-like stars
const starsGeo = new THREE.BufferGeometry();
const starCount = 500;
const starPositions = new Float32Array(starCount * 3);

for (let i = 0; i < starCount; i++) {
  starPositions[i * 3 + 0] = (Math.random() - 0.5) * 80;
  starPositions[i * 3 + 1] = Math.random() * 30 + 2;
  starPositions[i * 3 + 2] = (Math.random() - 0.5) * 80;
}
starsGeo.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));

const starsMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.08,
  transparent: true,
  opacity: 0.7,
});
const stars = new THREE.Points(starsGeo, starsMat);
scene.add(stars);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  // Dynamic light motion
  pointLight.position.x = Math.sin(t * 1.2) * 4.0;
  pointLight.position.z = Math.cos(t * 1.2) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

  // Object animation
  sphere.rotation.y = t * 0.8;
  sphere.rotation.x = Math.sin(t * 0.5) * 0.2;

  torus.rotation.x = t * 0.6;
  torus.rotation.y = t * 0.9;

  box.rotation.x = t * 0.5;
  box.rotation.y = t * 0.7;

  stars.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

