## `main.js`

```javascript
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("sceneCanvas");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0x88ccff, 2.0);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xff8844, 1.0);
fillLight.position.set(-4, 2, -3);
scene.add(fillLight);

const pointLight = new THREE.PointLight(0x66ffcc, 20, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.95,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = 0;
ground.receiveShadow = false;
scene.add(ground);

// Shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0.0 },
    uBaseColor: { value: new THREE.Color(0x4cc9f0) },
    uLightPos: { value: pointLight.position.clone() }
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;
      float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.08
                 + cos(pos.y * 5.0 + uTime * 1.5) * 0.08;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uBaseColor;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 3.0);
      vec3 color = uBaseColor * (0.15 + diff * 0.85);
      color += vec3(1.0) * spec * 0.8;
      color += vec3(0.2, 0.8, 1.0) * fresnel * (0.2 + pulse * 0.2);

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  wireframe: false
});

// Main object
const geo = new THREE.IcosahedronGeometry(1.2, 5);
const object = new THREE.Mesh(geo, shaderMaterial);
object.position.y = 1.8;
scene.add(object);

// Decorative orbiting spheres
const spheres = [];
const sphereGeo = new THREE.SphereGeometry(0.15, 24, 24);
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  emissive: 0x223344,
  metalness: 0.8,
  roughness: 0.2
});

for (let i = 0; i < 8; i++) {
  const s = new THREE.Mesh(sphereGeo, sphereMat.clone());
  s.material.color = new THREE.Color().setHSL(i / 8, 0.8, 0.6);
  scene.add(s);
  spheres.push(s);
}

// Grid helper for depth reference
const grid = new THREE.GridHelper(50, 50, 0x223344, 0x111827);
grid.position.y = 0.001;
scene.add(grid);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader uniforms
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

  // Animate object
  object.rotation.y = t * 0.45;
  object.rotation.x = Math.sin(t * 0.3) * 0.2;

  // Animate dynamic light
  pointLight.position.x = Math.sin(t * 1.2) * 3.5;
  pointLight.position.z = Math.cos(t * 1.2) * 3.5;
  pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.6;

  // Orbiting spheres
  spheres.forEach((s, i) => {
    const a = t * 0.8 + (i / spheres.length) * Math.PI * 2;
    const r = 2.8 + (i % 3) * 0.4;
    s.position.set(
      Math.cos(a) * r,
      1.2 + Math.sin(t * 2.0 + i) * 0.3,
      Math.sin(a) * r
    );
    s.scale.setScalar(0.8 + 0.3 * Math.sin(t * 3.0 + i));
  });

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

