## `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 8, 28);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(4, 8, 5);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66ccff, 20, 20, 2);
pointLight.position.set(-3, 2, 0);
scene.add(pointLight);

const movingLight = new THREE.PointLight(0xff8844, 18, 18, 2);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111622,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper for depth reference
const grid = new THREE.GridHelper(40, 40, 0x2a3550, 0x1a2233);
grid.position.y = 0.001;
scene.add(grid);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0xf72585) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      // Simple animated displacement
      float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.08;
      wave += cos(pos.y * 4.0 + uTime * 1.5) * 0.05;
      pos += normal * wave;

      vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
      float diffuse = max(dot(n, lightDir), 0.0);

      float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 3.0);
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 4.0);

      vec3 base = mix(uColorA, uColorB, pulse);
      vec3 color = base * (0.25 + diffuse * 0.85) + fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 5),
  shaderMaterial
);
sphere.position.set(0, 1.4, 0);
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.25, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    metalness: 0.7,
    roughness: 0.2,
  })
);
torus.position.set(-2.5, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xffcc66,
    metalness: 0.1,
    roughness: 0.5,
  })
);
box.position.set(2.5, 1, 0);
scene.add(box);

// Simple particles
const particlesCount = 500;
const positions = new Float32Array(particlesCount * 3);
for (let i = 0; i < particlesCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = Math.random() * 10;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
const particlesGeo = new THREE.BufferGeometry();
particlesGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.04,
  transparent: true,
  opacity: 0.8,
});
const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader
  shaderMaterial.uniforms.uTime.value = t;

  // Animate objects
  sphere.rotation.y = t * 0.4;
  sphere.rotation.x = Math.sin(t * 0.2) * 0.15;

  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.3;

  box.rotation.x = t * 0.7;
  box.rotation.y = t * 0.4;

  // Move dynamic lights
  movingLight.position.x = Math.sin(t * 1.2) * 4.0;
  movingLight.position.z = Math.cos(t * 1.2) * 4.0;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.5;

  pointLight.position.x = Math.cos(t * 0.8) * 3.0;
  pointLight.position.z = Math.sin(t * 0.8) * 3.0;

  // Subtle particle drift
  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();
```

