  <div id="app"></div>
  <div class="overlay">
    <div><strong>3D Scene Viewer</strong></div>
    <div>Drag to orbit • Scroll to zoom</div>
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.physicallyCorrectLights = true;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.getElementById("app").appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070c);
    scene.fog = new THREE.Fog(0x05070c, 10, 40);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 7);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.target.set(0, 1, 0);

    // Lights
    const ambient = new THREE.AmbientLight(0x335577, 0.35);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 3.0);
    dirLight.position.set(5, 8, 4);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x66aaff, 20, 25, 2);
    pointLight.position.set(-4, 2, 3);
    scene.add(pointLight);

    const pointLight2 = new THREE.PointLight(0xff6699, 15, 20, 2);
    pointLight2.position.set(3, 1.5, -2);
    scene.add(pointLight2);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x11151d,
        roughness: 0.95,
        metalness: 0.0
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.01;
    ground.receiveShadow = true;
    scene.add(ground);

    // Shader material for the main object
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x4cc9f0) },
        uColorB: { value: new THREE.Color(0x7209b7) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vUv = uv;
          vNormal = normalMatrix * normal;
          vPosition = position;

          vec3 pos = position;

          // Simple animated displacement
          float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
          pos += normal * wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 0.8, 0.6));

          float diffuse = max(dot(n, lightDir), 0.0);
          float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

          float stripes = 0.5 + 0.5 * sin((vUv.y * 20.0) - uTime * 4.0);
          vec3 baseColor = mix(uColorA, uColorB, vUv.y);
          vec3 color = baseColor * (0.3 + 0.7 * diffuse);
          color += fresnel * 0.8;
          color *= mix(0.75, 1.15, stripes);

          gl_FragColor = vec4(color, 1.0);
        }
      `,
      transparent: false
    });

    // Main object
    const object = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 256, 32),
      shaderMaterial
    );
    object.position.y = 1.5;
    scene.add(object);

    // Secondary object for depth
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.75, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.2,
        metalness: 0.8
      })
    );
    sphere.position.set(-2.5, 1.0, -1.5);
    scene.add(sphere);

    // Subtle star-like background points
    const starCount = 500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);

    for (let i = 0; i < starCount; i++) {
      const r = 25 + Math.random() * 25;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);

      starPositions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = r * Math.cos(phi);
      starPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
    }

    starGeometry.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
    const stars = new THREE.Points(
      starGeometry,
      new THREE.PointsMaterial({ color: 0x88aaff, size: 0.08, sizeAttenuation: true })
    );
    scene.add(stars);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = elapsed;

      object.rotation.y = elapsed * 0.6;
      object.rotation.x = Math.sin(elapsed * 0.4) * 0.2;

      sphere.position.y = 1.0 + Math.sin(elapsed * 1.5) * 0.25;
      sphere.rotation.y = elapsed * 0.9;

      pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
      pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;

      pointLight2.position.x = Math.cos(elapsed * 0.8) * 3.5;
      pointLight2.position.y = 1.5 + Math.sin(elapsed * 1.1) * 0.8;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
