import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x6b7cff, 0.35);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(4, 8, 5);
scene.add(directional);

const pointLight = new THREE.PointLight(0x00d5ff, 8, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0b1020,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1;
ground.receiveShadow = false;
scene.add(ground);

// Shader material for a central object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d5ff) },
    uColorB: { value: new THREE.Color(0x7c4dff) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vUv = uv;
      vNormal = normalMatrix * normal;

      vec3 pos = position;

      // Subtle animated displacement
      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.08;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.4, 0.8, 0.2));
      float diff = max(dot(N, L), 0.0);

      float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 3.0);

      float stripe = 0.5 + 0.5 * sin(vUv.y * 18.0 + uTime * 4.0);
      vec3 base = mix(uColorA, uColorB, stripe);

      vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.8;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphereGeo = new THREE.SphereGeometry(1.2, 64, 64);
const sphere = new THREE.Mesh(sphereGeo, shaderMaterial);
sphere.position.set(0, 1.2, 0);
scene.add(sphere);

// Additional objects for depth
const torusGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 180, 24);
const torusMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  metalness: 0.8,
  roughness: 0.25,
});
const torus = new THREE.Mesh(torusGeo, torusMat);
torus.position.set(-2.2, 1.1, 0);
scene.add(torus);

const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const boxMat = new THREE.MeshStandardMaterial({
  color: 0x8fd3ff,
  metalness: 0.2,
  roughness: 0.4,
});
const box = new THREE.Mesh(boxGeo, boxMat);
box.position.set(2.2, 0.0, -0.5);
scene.add(box);

// Decorative particles
const particleCount = 400;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const i3 = i * 3;
  particlePositions[i3 + 0] = (Math.random() - 0.5) * 30;
  particlePositions[i3 + 1] = Math.random() * 10;
  particlePositions[i3 + 2] = (Math.random() - 0.5) * 30;
}

particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0x9ad7ff,
  size: 0.04,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  sphere.rotation.y = t * 0.5;
  sphere.rotation.x = Math.sin(t * 0.3) * 0.2;

  torus.rotation.x = t * 0.4;
  torus.rotation.y = t * 0.7;

  box.rotation.x = t * 0.6;
  box.rotation.y = t * 0.3;

  pointLight.position.x = Math.sin(t * 1.2) * 3.0;
  pointLight.position.z = Math.cos(t * 1.2) * 3.0;
  pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.5;

  particles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
