      pos.z += cos(pos.y * 3.0 + uTime * 1.5) * 0.05;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.5 + vUv.y * 10.0);
      vec3 color = mix(uColorA, uColorB, vUv.y);
      color += pulse * 0.15;

      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 3.0);
      color += fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  transparent: false
});

// Objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1.2, 0.35, 200, 32),
  shaderMaterial
);
torus.position.set(-2, 1.5, 0);
scene.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.15,
    metalness: 0.9,
    emissive: 0x112244,
    emissiveIntensity: 0.6
  })
);
sphere.position.set(2.5, 1.2, 0);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xccccff,
    roughness: 0.35,
    metalness: 0.7
  })
);
box.position.set(0, 0.75, -2.5);
scene.add(box);

// Floating particles
const particleCount = 500;
const particlesGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const i3 = i * 3;
  positions[i3 + 0] = (Math.random() - 0.5) * 30;
  positions[i3 + 1] = Math.random() * 12;
  positions[i3 + 2] = (Math.random() - 0.5) * 30;
}

particlesGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  torus.rotation.x = t * 0.35;
  torus.rotation.y = t * 0.6;

  sphere.position.y = 1.2 + Math.sin(t * 2.0) * 0.35;
  sphere.rotation.y = t * 0.8;

  box.rotation.x = t * 0.5;
  box.rotation.y = t * 0.35;

  fillLight.position.x = Math.sin(t * 1.2) * 5;
  fillLight.position.z = Math.cos(t * 1.2) * 5;

  rimLight.position.x = Math.cos(t * 0.9) * 6;
  rimLight.position.z = Math.sin(t * 0.9) * 6;

  particles.rotation.y = t * 0.02;
  particles.position.y = Math.sin(t * 0.5) * 0.2;

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
