## 4) `main.js`

```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("webgl");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.22);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0x9cc7ff, 1.8);
dirLight.position.set(5, 8, 3);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xff7b54, 30, 20, 2);
pointLight.position.set(-2, 2, 2);
scene.add(pointLight);

// Helpers: subtle grid/floor
const floorGeo = new THREE.PlaneGeometry(30, 30, 1, 1);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  metalness: 0.15,
  roughness: 0.9,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = 0;
scene.add(floor);

// Custom shader material for animated object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4fd1ff) },
    uColorB: { value: new THREE.Color(0x7c3aed) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 pos = position;

      // Subtle vertex displacement for a living/shader effect
      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.05;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vWorldPos = worldPos.xyz;
      vNormal = normalize(mat3(modelMatrix) * normal);

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.4, 1.0, 0.2));
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      float stripe = 0.5 + 0.5 * sin(vWorldPos.y * 8.0 + uTime * 4.0);
      vec3 base = mix(uColorA, uColorB, stripe);

      vec3 color = base * (0.18 + diff * 0.9) + spec * vec3(1.0) * 0.9;
      color += fresnel * vec3(0.4, 0.6, 1.0);

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const cube = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 1.2, 32, 32, 32),
  shaderMaterial
);
cube.position.set(-1.5, 1.0, 0);
scene.add(cube);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.8, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0xd1d5db,
    metalness: 0.7,
    roughness: 0.2,
  })
);
sphere.position.set(1.6, 0.8, 0);
scene.add(sphere);

// Accent torus
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.6, 0.18, 160, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffb86b,
    metalness: 0.9,
    roughness: 0.15,
  })
);
torus.position.set(0, 1.4, -1.8);
scene.add(torus);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const t = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = t;

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 1.2) * 3.0;
  pointLight.position.z = Math.cos(t * 1.2) * 3.0;
  pointLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.5;

  dirLight.position.x = Math.cos(t * 0.4) * 6.0;
  dirLight.position.z = Math.sin(t * 0.4) * 6.0;

  // Object motion
  cube.rotation.x = t * 0.7;
  cube.rotation.y = t * 1.1;

  sphere.rotation.y = -t * 0.4;
  sphere.position.y = 0.8 + Math.sin(t * 2.2) * 0.15;

  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.8;

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

