```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lighting
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0x88aaff, 2.5);
directionalLight.position.set(5, 8, 4);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0xff66cc, 2.0, 25, 2);
pointLight.position.set(-3, 2, 2);
scene.add(pointLight);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(30, 30);
const groundMaterial = new THREE.MeshStandardMaterial({
  color: 0x10131a,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(30, 30, 0x223344, 0x111822);
grid.position.y = 0;
scene.add(grid);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff4fd8) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      vPosition = position;
      vNormal = normal;

      vec3 pos = position;
      pos += normal * sin(uTime + position.y * 6.0) * 0.08;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 8.0);
      vec3 color = mix(uColorA, uColorB, wave);

      // Simple lighting response
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.6));
      float diffuse = max(dot(normalize(vNormal), lightDir), 0.0);
      float rim = pow(1.0 - max(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

      vec3 finalColor = color * (0.35 + 0.85 * diffuse) + rim * 0.35;
      gl_FragColor = vec4(finalColor, 1.0);
    }
  `,
});

// Objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 180, 24),
  shaderMaterial
);
torus.position.set(-1.6, 1.4, 0);
scene.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.8, 48, 48),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    roughness: 0.15,
    metalness: 0.85,
  })
);
sphere.position.set(1.8, 1.0, 0.2);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.1, 1.1, 1.1),
  new THREE.MeshStandardMaterial({
    color: 0x88ffcc,
    roughness: 0.25,
    metalness: 0.6,
  })
);
box.position.set(0, 0.8, -1.8);
scene.add(box);

// Accent particles
const particleCount = 250;
const particlePositions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  particlePositions[i * 3 + 1] = Math.random() * 8;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}

const particlesGeometry = new THREE.BufferGeometry();
particlesGeometry.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particlesMaterial = new THREE.PointsMaterial({
  color: 0x66ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
  depthWrite: false,
});

const particles = new THREE.Points(particlesGeometry, particlesMaterial);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = elapsed;

  torus.rotation.y = elapsed * 0.7;
  torus.rotation.x = elapsed * 0.35;

  sphere.rotation.y = elapsed * 0.5;
  box.rotation.x = elapsed * 0.6;
  box.rotation.y = elapsed * 0.4;

  pointLight.position.x = Math.sin(elapsed * 1.2) * 4;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4;

  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);

  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
