## 4) `main.js`

```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.15);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 3.0);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0x00aaff, 20, 30);
fillLight.position.set(-4, 2, 2);
scene.add(fillLight);

const movingLight = new THREE.PointLight(0xff5500, 30, 40);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111822,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Main object with shader effect
const geometry = new THREE.TorusKnotGeometry(1.2, 0.42, 220, 32);

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff4d8d) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vPosition = position;

      vec3 pos = position;
      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
      pos += normal * wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      float fresnel = pow(1.0 - abs(n.z), 2.5);

      float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vPosition.x * 2.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 color = base + fresnel * vec3(0.8, 0.9, 1.0);
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

const object = new THREE.Mesh(geometry, shaderMaterial);
object.position.y = 1.8;
scene.add(object);

// Secondary objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.5, 32, 32),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.15,
    metalness: 0.8,
  })
);
sphere.position.set(-2.2, 1, 0);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(0.8, 0.8, 0.8),
  new THREE.MeshStandardMaterial({
    color: 0x7c5cff,
    roughness: 0.35,
    metalness: 0.5,
  })
);
box.position.set(2.2, 0.8, -0.5);
scene.add(box);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Shader animation
  shaderMaterial.uniforms.uTime.value = t;

  // Dynamic lighting motion
  movingLight.position.x = Math.sin(t * 1.2) * 4.0;
  movingLight.position.z = Math.cos(t * 1.2) * 4.0;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

  fillLight.intensity = 15 + Math.sin(t * 1.5) * 5;

  // Object motion
  object.rotation.y = t * 0.5;
  object.rotation.x = Math.sin(t * 0.3) * 0.2;

  sphere.position.y = 1 + Math.sin(t * 2.0) * 0.25;
  sphere.rotation.y = t * 1.2;

  box.rotation.x = t * 0.7;
  box.rotation.y = t * 0.9;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

