import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas / Renderer
const canvas = document.getElementById("scene-canvas");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene / Camera
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 40);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0x88aaff, 2.0);
directional.position.set(5, 8, 4);
scene.add(directional);

const pointLight = new THREE.PointLight(0xff66cc, 25, 30, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

const movingLight = new THREE.PointLight(0x66ffff, 15, 20, 2);
movingLight.position.set(-4, 2, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = false;
scene.add(ground);

// Custom shader material for effect
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x6a5cff) },
    uColorB: { value: new THREE.Color(0x00d4ff) },
  },
  vertexShader: `
    varying vec3 vPosition;
    varying vec3 vNormal;
    varying vec2 vUv;
    uniform float uTime;

    void main() {
      vUv = uv;
      vNormal = normal;
      vPosition = position;

      vec3 pos = position;
      pos += normal * sin(uTime + position.y * 4.0) * 0.08;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    precision highp float;

    varying vec3 vPosition;
    varying vec3 vNormal;
    varying vec2 vUv;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    void main() {
      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 8.0 + vUv.y * 4.0);
      vec3 color = mix(uColorA, uColorB, wave);

      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 3.0);
      color += fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
const sphere = new THREE.Mesh(sphereGeo, shaderMaterial);
sphere.position.set(0, 1.5, 0);
scene.add(sphere);

// Secondary objects
const torusGeo = new THREE.TorusKnotGeometry(0.7, 0.25, 160, 24);
const torusMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  metalness: 0.8,
  roughness: 0.2,
});
const torus = new THREE.Mesh(torusGeo, torusMat);
torus.position.set(-2.2, 1.4, 0);
scene.add(torus);

const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const boxMat = new THREE.MeshStandardMaterial({
  color: 0x88ffcc,
  metalness: 0.2,
  roughness: 0.35,
});
const box = new THREE.Mesh(boxGeo, boxMat);
box.position.set(2.2, 1.0, 0);
scene.add(box);

// Simple background stars
const starsGeo = new THREE.BufferGeometry();
const starCount = 1000;
const starPositions = new Float32Array(starCount * 3);

for (let i = 0; i < starCount; i++) {
  const i3 = i * 3;
  starPositions[i3 + 0] = (Math.random() - 0.5) * 100;
  starPositions[i3 + 1] = Math.random() * 40 + 5;
  starPositions[i3 + 2] = (Math.random() - 0.5) * 100;
}

starsGeo.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
const starsMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
});
const stars = new THREE.Points(starsGeo, starsMat);
scene.add(stars);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  sphere.rotation.y = t * 0.6;
  sphere.rotation.x = Math.sin(t * 0.4) * 0.2;

  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.7;

  box.rotation.x = t * 0.8;
  box.rotation.y = t * 0.4;

  pointLight.position.x = Math.sin(t * 1.2) * 3.0;
  pointLight.position.z = Math.cos(t * 1.2) * 3.0;

  movingLight.position.x = Math.cos(t * 0.9) * 4.0;
  movingLight.position.z = Math.sin(t * 0.9) * 4.0;
  movingLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.8;

  stars.rotation.y = t * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

