    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.4, 0.8, 0.2));
      float diff = max(dot(N, L), 0.0);

      float fresnel = pow(1.0 - max(dot(N, normalize(-vPosition)), 0.0), 3.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 2.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 color = base * (0.15 + diff * 0.85) + fresnel * 0.8;
      color += 0.05 * sin(uTime + vPosition.xyx * 3.0).xyz;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const geometry = new THREE.IcosahedronGeometry(1.2, 5);
const objectMesh = new THREE.Mesh(geometry, shaderMaterial);
objectMesh.position.y = 1.2;
scene.add(objectMesh);

// Secondary objects for depth
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 180, 32),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.8,
    roughness: 0.25,
    emissive: 0x111122,
  })
);
torus.position.set(-2.3, 1.0, 0.5);
scene.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.6, 48, 48),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    metalness: 0.3,
    roughness: 0.15,
    emissive: 0x000011,
  })
);
sphere.position.set(2.2, 0.2, -1.0);
scene.add(sphere);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader uniforms
  shaderMaterial.uniforms.uTime.value = t;

  // Animate lights
  movingLight.position.x = Math.sin(t * 1.2) * 4.0;
  movingLight.position.z = Math.cos(t * 1.2) * 4.0;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

  fillLight.intensity = 20 + Math.sin(t * 3.0) * 5.0;
  keyLight.intensity = 2.2 + Math.cos(t * 1.5) * 0.3;

  // Animate objects
  objectMesh.rotation.y = t * 0.4;
  objectMesh.rotation.x = Math.sin(t * 0.5) * 0.2;

  torus.rotation.x = t * 0.35;
  torus.rotation.y = t * 0.55;

  sphere.position.y = 0.2 + Math.sin(t * 1.8) * 0.25;
  sphere.rotation.y = t * 0.6;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
