## 4) `main.js`

```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070c);
scene.fog = new THREE.Fog(0x05070c, 12, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(5, 3.5, 7);

// Controls
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0x9fd3ff, 2.2);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xff8a65, 1.0);
fillLight.position.set(-4, 2, -3);
scene.add(fillLight);

const pointLight = new THREE.PointLight(0x6cf0ff, 25, 30, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11161f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.5;
ground.receiveShadow = true;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5de5) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vPos;
    varying vec3 vNormal;

    void main() {
      vPos = position;
      vNormal = normal;

      vec3 p = position;
      float wave = sin(p.x * 3.0 + uTime * 2.0) * 0.08;
      wave += cos(p.y * 4.0 + uTime * 1.5) * 0.06;
      p += normal * wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vPos;
    varying vec3 vNormal;

    void main() {
      vec3 n = normalize(vNormal);
      float fresnel = pow(1.0 - abs(n.z), 2.5);
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPos.y * 4.0);

      vec3 color = mix(uColorA, uColorB, pulse);
      color += fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const objects = [];

function addObject(mesh, x, y, z) {
  mesh.position.set(x, y, z);
  scene.add(mesh);
  objects.push(mesh);
  return mesh;
}

// Central shader object
const shaderSphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.1, 5),
  shaderMaterial
);
addObject(shaderSphere, 0, 1.2, 0);

// Surrounding objects
const boxMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  roughness: 0.28,
  metalness: 0.85,
});

const torusMat = new THREE.MeshStandardMaterial({
  color: 0x7dd3fc,
  roughness: 0.2,
  metalness: 0.9,
});

for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const radius = 3.5;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;
  const y = 0.5 + (i % 2) * 0.4;

  const geom = i % 2 === 0
    ? new THREE.BoxGeometry(0.55, 0.55, 0.55)
    : new THREE.TorusGeometry(0.35, 0.12, 16, 48);

  const mat = i % 2 === 0 ? boxMat : torusMat;
  const mesh = new THREE.Mesh(geom, mat);
  addObject(mesh, x, y, z);
}

// Decorative particles
const particleCount = 300;
const particlePositions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  const r = 10 + Math.random() * 10;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);

  particlePositions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
  particlePositions[i * 3 + 1] = r * Math.cos(phi) * 0.6;
  particlePositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}

const particlesGeo = new THREE.BufferGeometry();
particlesGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particlesMat = new THREE.PointsMaterial({
  color: 0x8fd3ff,
  size: 0.035,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader
  shaderMaterial.uniforms.uTime.value = t;

  // Animate lights
  pointLight.position.x = Math.sin(t * 1.2) * 3.5;
  pointLight.position.z = Math.cos(t * 1.2) * 3.5;
  pointLight.position.y = 2.2 + Math.sin(t * 2.0) * 0.8;

  keyLight.intensity = 2.0 + Math.sin(t * 1.5) * 0.25;
  fillLight.intensity = 0.85 + Math.cos(t * 1.1) * 0.2;

  // Rotate objects
  shaderSphere.rotation.y = t * 0.5;
  shaderSphere.rotation.x = Math.sin(t * 0.4) * 0.2;

  objects.forEach((obj, idx) => {
    if (obj === shaderSphere) return;
    obj.rotation.x = t * 0.3 + idx * 0.1;
    obj.rotation.y = t * 0.5 + idx * 0.08;
    obj.position.y = 0.5 + Math.sin(t * 1.5 + idx) * 0.15;
  });

  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

