```js
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

// -----------------------------
// Basic setup
// -----------------------------
const canvas = document.getElementById('app');

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
  powerPreference: 'high-performance',
});

renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 45);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  200
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);
controls.minDistance = 3;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI * 0.49;

// -----------------------------
// Lighting
// -----------------------------
const ambient = new THREE.AmbientLight(0x9bbcff, 0.25);
scene.add(ambient);

const hemi = new THREE.HemisphereLight(0x88aaff, 0x111122, 0.5);
scene.add(hemi);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.2);
dirLight.position.set(5, 8, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 30;
dirLight.shadow.camera.left = -10;
dirLight.shadow.camera.right = 10;
dirLight.shadow.camera.top = 10;
dirLight.shadow.camera.bottom = -10;
scene.add(dirLight);

// Moving point light for dynamic lighting
const pointLight = new THREE.PointLight(0x66ccff, 18, 25, 2);
pointLight.castShadow = true;
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Soft fill light
const pointLight2 = new THREE.PointLight(0xff66aa, 8, 25, 2);
pointLight2.position.set(-4, 2, -3);
scene.add(pointLight2);

// -----------------------------
// Floor
// -----------------------------
const floorGeo = new THREE.PlaneGeometry(50, 50, 1, 1);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x10131b,
  roughness: 0.95,
  metalness: 0.0,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// Grid helper for depth cues
const grid = new THREE.GridHelper(50, 50, 0x2d3957, 0x1a2235);
grid.position.y = 0.001;
scene.add(grid);

// -----------------------------
// Shader effect material
// -----------------------------
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x2aa7ff) },
    uColorB: { value: new THREE.Color(0xff4fd8) },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.3));
      float diffuse = max(dot(n, lightDir), 0.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 3.0 + vWorldPos.x * 2.0);
      vec3 base = mix(uColorA, uColorB, wave);

      float rim = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

      vec3 color = base * (0.25 + diffuse * 0.9) + rim * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// -----------------------------
// Scene objects
// -----------------------------
const objects = [];

// Central shader sphere
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.1, 64, 64),
  shaderMaterial
);
sphere.position.set(0, 1.5, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);
objects.push(sphere);

// Surrounding standard meshes
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 160, 24),
  new THREE.MeshStandardMaterial({
    color: 0xe8f1ff,
    metalness: 0.8,
    roughness: 0.2,
  })
);
torus.position.set(-2.5, 1.4, 0);
torus.castShadow = true;
scene.add(torus);
objects.push(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0x7cffc6,
    metalness: 0.2,
    roughness: 0.35,
  })
);
box.position.set(2.5, 0.7, -0.5);
box.castShadow = true;
scene.add(box);
objects.push(box);

// Floating emissive ring
const ring = new THREE.Mesh(
  new THREE.TorusGeometry(2.6, 0.05, 16, 120),
  new THREE.MeshStandardMaterial({
    color: 0x223355,
    emissive: 0x3b7cff,
    emissiveIntensity: 1.8,
    metalness: 0.3,
    roughness: 0.4,
  })
);
ring.rotation.x = Math.PI / 2;
ring.position.y = 2.2;
scene.add(ring);

// Particles for atmosphere
const particleCount = 500;
const particleGeo = new THREE.BufferGeometry();
const particlePos = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const i3 = i * 3;
  particlePos[i3 + 0] = (Math.random() - 0.5) * 30;
  particlePos[i3 + 1] = Math.random() * 12;
  particlePos[i3 + 2] = (Math.random() - 0.5) * 30;
}

particleGeo.setAttribute(
  'position',
  new THREE.BufferAttribute(particlePos, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0xaaccff,
  size: 0.04,
  transparent: true,
  opacity: 0.8,
  depthWrite: false,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// -----------------------------
// Animation loop
// -----------------------------
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();
  const delta = clock.getDelta();

  controls.update();

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(elapsed * 0.9) * 4.5;
  pointLight.position.z = Math.cos(elapsed * 0.9) * 4.5;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 1.7) * 0.8;

  pointLight2.position.x = Math.cos(elapsed * 0.6) * 5.5;
  pointLight2.position.z = Math.sin(elapsed * 0.6) * 5.5;

  // Shader uniform update
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Object motion
  sphere.rotation.y += delta * 0.35;
  torus.rotation.x += delta * 0.8;
  torus.rotation.y += delta * 0.5;
  box.rotation.x += delta * 0.6;
  box.rotation.y += delta * 0.9;
  ring.rotation.z = Math.sin(elapsed * 0.5) * 0.2;

  // Subtle particle drift
  particles.rotation.y = elapsed * 0.03;

  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// -----------------------------
// Resize handling
// -----------------------------
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
