      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070f);
    scene.fog = new THREE.Fog(0x05070f, 10, 30);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 5);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lights
    const ambient = new THREE.AmbientLight(0x404060, 0.8);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight.position.set(3, 5, 2);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x00ffff, 2.5, 20);
    pointLight.position.set(-2, 1, 2);
    scene.add(pointLight);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(1, 0.35, 200, 32);

    // Custom shader material with animated color effect
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uLightPos: { value: new THREE.Vector3() }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vNormal = normalize(normalMatrix * normal);
          vec4 worldPos = modelMatrix * vec4(position, 1.0);
          vWorldPos = worldPos.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uLightPos;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPos);

          // Diffuse lighting
          float diff = max(dot(normal, lightDir), 0.0);

          // Animated shader effect
          float wave = sin(vWorldPos.y * 8.0 + uTime * 3.0) * 0.5 + 0.5;
          vec3 baseColor = mix(vec3(0.1, 0.3, 1.0), vec3(0.9, 0.2, 1.0), wave);

          // Simple specular highlight
          vec3 viewDir = normalize(cameraPosition - vWorldPos);
          vec3 reflectDir = reflect(-lightDir, normal);
          float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

          vec3 color = baseColor * (0.25 + diff) + spec * vec3(1.0);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      material.uniforms.uTime.value = t;
      material.uniforms.uLightPos.value.copy(pointLight.position);

      mesh.rotation.y = t * 0.4;
      mesh.rotation.x = t * 0.2;

      pointLight.position.x = Math.sin(t) * 3.0;
      pointLight.position.z = Math.cos(t) * 3.0;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();
  </script>
</body>
</html>
