### `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
    #info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      font-family: sans-serif;
      background: rgba(0,0,0,0.4);
      padding: 8px 10px;
      border-radius: 6px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="info">Drag to orbit • Scroll to zoom</div>

  <script type="module">
    import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 10, 35);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2, 7);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0x66aaff, 2.0, 30);
    pointLight.position.set(3, 4, 3);
    scene.add(pointLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
    directionalLight.position.set(-2, 5, 2);
    scene.add(directionalLight);

    // Floor
    const floorGeo = new THREE.PlaneGeometry(30, 30);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x111111,
      metalness: 0.2,
      roughness: 0.9
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1.2;
    scene.add(floor);

    // Custom shader material for the sphere
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vPosition = position;

          vec3 pos = position;
          pos += normal * sin(uTime + position.y * 4.0) * 0.15;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.8));
          float diff = max(dot(normalize(vNormal), lightDir), 0.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.x * 3.0);
          vec3 baseColor = mix(vec3(0.1, 0.4, 1.0), vec3(1.0, 0.2, 0.6), pulse);

          vec3 color = baseColor * (0.2 + diff * 0.8);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Main object
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 64, 64),
      shaderMaterial
    );
    scene.add(sphere);

    // Additional objects
    const cube = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0x44ffaa,
        metalness: 0.7,
        roughness: 0.2
      })
    );
    cube.position.set(-2.5, -0.2, 0);
    scene.add(cube);

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.7, 0.25, 128, 16),
      new THREE.MeshStandardMaterial({
        color: 0xffaa44,
        metalness: 0.5,
        roughness: 0.35
      })
    );
    torus.position.set(2.5, 0, 0);
    scene.add(torus);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      sphere.rotation.y = t * 0.4;
      cube.rotation.x = t * 0.7;
      cube.rotation.y = t * 0.5;
      torus.rotation.x = t * 0.4;
      torus.rotation.y = t * 0.8;

      pointLight.position.x = Math.sin(t) * 4;
      pointLight.position.z = Math.cos(t) * 4;
      pointLight.position.y = 2 + Math.sin(t * 1.5);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
