        void main() {
          float wave = sin(vUv.y * 12.0 + uTime * 3.0) * 0.5 + 0.5;
          float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);

          vec3 base = mix(uColor1, uColor2, wave);
          vec3 color = base + fresnel * 0.6;

          gl_FragColor = vec4(color, 1.0);
