    camera.position.set(0, 1.5, 4);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 160, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff4d8d) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 pos = position;

          // Subtle vertex wave
          pos += normal * sin(uTime + position.y * 4.0) * 0.05;

          vNormal = normalMatrix * normal;
          vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 N = normalize(vNormal);
          vec3 L = normalize(vec3(0.6, 1.0, 0.8)); // fake directional light
          float diff = max(dot(N, L), 0.0);

          // Animated gradient based on position
          float t = 0.5 + 0.5 * sin(uTime + vPosition.y * 2.0);
          vec3 baseColor = mix(uColorA, uColorB, t);

          // Simple fresnel glow
          vec3 V = normalize(-vPosition);
          float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

          vec3 color = baseColor * (0.25 + 0.75 * diff) + fresnel * vec3(1.0, 0.9, 1.0) * 0.8;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Dynamic light
    const pointLight = new THREE.PointLight(0xffffff, 40, 20);
    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.06, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0xffffff })
    );
    scene.add(lightSphere);

    // Ambient light for fill
    scene.add(new THREE.AmbientLight(0x223344, 0.6));

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      material.uniforms.uTime.value = t;

      // Rotate object
      mesh.rotation.y = t * 0.6;
      mesh.rotation.x = t * 0.25;

      // Move light in a circle
      pointLight.position.set(
        Math.sin(t * 1.2) * 2.5,
        Math.cos(t * 0.9) * 1.5 + 1.5,
        Math.cos(t * 1.2) * 2.5
      );
      lightSphere.position.copy(pointLight.position);

      renderer.render(scene, camera);
    }

    animate();
  </script>
