          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(sphereGeo, sphereMat);
    sphere.position.y = 0.5;
    scene.add(sphere);

    // Secondary object for depth
    const torusGeo = new THREE.TorusKnotGeometry(0.6, 0.2, 128, 16);
    const torusMat = new THREE.MeshStandardMaterial({
      color: 0xffc857,
      metalness: 0.8,
      roughness: 0.25,
      emissive: 0x221100,
      emissiveIntensity: 0.5
    });
    const torus = new THREE.Mesh(torusGeo, torusMat);
    torus.position.set(2, 0.5, 0);
    scene.add(torus);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      const t = clock.getElapsedTime();

      sphere.material.uniforms.uTime.value = t;
      sphere.rotation.y = t * 0.4;

      torus.rotation.x = t * 0.6;
      torus.rotation.y = t * 0.9;

      pointLight.position.x = Math.sin(t) * 4;
      pointLight.position.z = Math.cos(t) * 4;
      pointLight.intensity = 2.0 + Math.sin(t * 2.0) * 0.5;

      controls.update();
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
