// PhysicsWorld.cpp
#include "PhysicsWorld.h"

void PhysicsWorld::SetGravity(const Vec3& g)
{
    gravity = g;
}

PhysicsBody* PhysicsWorld::CreateBody(const PhysicsBody& body)
{
    bodies.push_back(body);
    return &bodies.back();
}

void PhysicsWorld::DestroyBody(PhysicsBody* body)
{
    // Simple placeholder removal logic
    for (auto it = bodies.begin(); it != bodies.end(); ++it)
    {
        if (&(*it) == body)
        {
            bodies.erase(it);
            return;
        }
    }
}

void PhysicsWorld::Step(float deltaTime)
{
    for (auto& body : bodies)
    {
        if (body.isStatic) continue;

        Vec3 acceleration{
            gravity.x + body.force.x / body.mass,
            gravity.y + body.force.y / body.mass,
            gravity.z + body.force.z / body.mass
        };

        body.velocity.x += acceleration.x * deltaTime;
        body.velocity.y += acceleration.y * deltaTime;
        body.velocity.z += acceleration.z * deltaTime;

        body.position.x += body.velocity.x * deltaTime;
        body.position.y += body.velocity.y * deltaTime;
        body.position.z += body.velocity.z * deltaTime;

        body.force = {0.0f, 0.0f, 0.0f};
    }
}
