class PhysicsBody {
public:
    PhysicsBody(float mass, const Vec3& position, const Quat& rotation)
        : mass_(mass), position_(position), rotation_(rotation) {}

    void SetLinearVelocity(const Vec3& v) { linearVelocity_ = v; }
    Vec3 GetLinearVelocity() const { return linearVelocity_; }

    void SetPosition(const Vec3& p) { position_ = p; }
    Vec3 GetPosition() const { return position_; }

    void SetRotation(const Quat& q) { rotation_ = q; }
    Quat GetRotation() const { return rotation_; }

