    void Integrate(float dt) {
        position_.x += linearVelocity_.x * dt;
        position_.y += linearVelocity_.y * dt;
        position_.z += linearVelocity_.z * dt;
    }

private:
    float mass_;
    Vec3 position_{0,0,0};
    Quat rotation_{0,0,0,1};
    Vec3 linearVelocity_{0,0,0};
};
