```cpp
#include "PhysicsWorld.h"
#include <algorithm>

PhysicsBody* PhysicsWorld::CreateBody(float mass, const Vec3& position, const Quat& rotation) {
    bodies_.push_back(std::make_unique<PhysicsBody>(mass, position, rotation));
    return bodies_.back().get();
}

void PhysicsWorld::DestroyBody(PhysicsBody* body) {
    bodies_.erase(
        std::remove_if(bodies_.begin(), bodies_.end(),
            [body](const std::unique_ptr<PhysicsBody>& ptr) {
                return ptr.get() == body;
            }),
        bodies_.end()
    );
}

void PhysicsWorld::StepSimulation(float dt) {
    for (auto& body : bodies_) {
        Vec3 v = body->GetLinearVelocity();
        v.x += gravity_.x * dt;
        v.y += gravity_.y * dt;
        v.z += gravity_.z * dt;
        body->SetLinearVelocity(v);

        body->Integrate(dt);
    }
}
