## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(EntityId id, BodyType type)
        : m_entityId(id), m_type(type)
    {
        if (type == BodyType::Static)
        {
            m_mass = 0.0f;
            m_inverseMass = 0.0f;
        }
    }

    void RigidBody::SetPosition(const Vec3& position)
    {
        m_position = position;
    }

    void RigidBody::SetVelocity(const Vec3& velocity)
    {
        m_velocity = velocity;
    }

    void RigidBody::SetMass(float mass)
    {
        if (m_type == BodyType::Static || mass <= 0.0f)
        {
            m_mass = 0.0f;
            m_inverseMass = 0.0f;
            return;
        }

        m_mass = mass;
        m_inverseMass = 1.0f / mass;
    }

    void RigidBody::SetUseGravity(bool enabled)
    {
        m_useGravity = enabled;
    }

    void RigidBody::ApplyForce(const Vec3& force)
    {
        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vec3::Zero();
    }

    void RigidBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic || m_inverseMass <= 0.0f)
            return;

        Vec3 totalForce = m_accumulatedForce;
        if (m_useGravity)
            totalForce += gravity * m_mass;

        Vec3 acceleration = totalForce * m_inverseMass;
        m_velocity += acceleration * dt;
        m_position += m_velocity * dt;

        ClearForces();
    }
}
