    void PhysicsWorld::Step(float deltaTime)
    {
        m_accumulator += deltaTime;

        while (m_accumulator >= m_settings.fixedTimeStep)
        {
            IntegrateBodies(m_settings.fixedTimeStep);
            ResolveCollisionsPlaceholder();
            m_accumulator -= m_settings.fixedTimeStep;
        }
    }

    void PhysicsWorld::IntegrateBodies(float dt)
    {
        for (auto& [id, body] : m_bodies)
        {
            if (body)
                body->Integrate(dt, m_gravity);
        }
    }

