    void PhysicsPlugin::Shutdown()
    {
        if (!m_initialized)
            return;

        m_world.reset();
        m_initialized = false;

        std::cout << "[CustomPhysics] Plugin shutdown\n";
    }

    void PhysicsPlugin::Update(float deltaTime)
    {
        if (!m_initialized || !m_world)
            return;

        m_world->Step(deltaTime);
        m_world->DebugDraw();
    }

    std::shared_ptr<PhysicsWorld> PhysicsPlugin::GetWorld() const
    {
        return m_world ? std::shared_ptr<PhysicsWorld>(m_world.get(), [](PhysicsWorld*) {}) : nullptr;
    }
