#pragma once

#include <vector>
#include <functional>
#include <cstdint>

namespace CustomPhysics
{
    using BodyId = uint32_t;

    struct Vec3
    {
        float x = 0.0f;
        float y = 0.0f;
        float z = 0.0f;

        Vec3() = default;
        Vec3(float px, float py, float pz) : x(px), y(py), z(pz) {}

        Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
        Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
        Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }

        Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    };

    inline Vec3 operator*(float s, const Vec3& v) { return v * s; }

    struct Transform
    {
        Vec3 position;
        Vec3 rotationEuler; // placeholder; replace with quaternion later
    };

    struct RigidBodyDesc
    {
        Transform transform;
        float mass = 1.0f;
        bool isStatic = false;
        bool useGravity = true;
    };

    struct CollisionEvent
    {
        BodyId bodyA = 0;
        BodyId bodyB = 0;
    };

    class IPhysicsWorld
    {
    public:
        virtual ~IPhysicsWorld() = default;

        virtual BodyId CreateBody(const RigidBodyDesc& desc) = 0;
        virtual void DestroyBody(BodyId id) = 0;

        virtual void ApplyForce(BodyId id, const Vec3& force) = 0;
        virtual void ApplyImpulse(BodyId id, const Vec3& impulse) = 0;

        virtual Transform GetTransform(BodyId id) const = 0;
        virtual void SetTransform(BodyId id, const Transform& t) = 0;

        virtual void SetGravity(const Vec3& gravity) = 0;
        virtual void StepSimulation(float dt) = 0;

        virtual void SetCollisionCallback(std::function<void(const CollisionEvent&)> callback) = 0;
    };
}
