        void ApplyImpulse(BodyId id, const Vec3& impulse) override;

        Transform GetTransform(BodyId id) const override;
        void SetTransform(BodyId id, const Transform& t) override;

        void SetGravity(const Vec3& gravity) override;
        void StepSimulation(float dt) override;

        void SetCollisionCallback(std::function<void(const CollisionEvent&)> callback) override;

    private:
        Body* FindBody(BodyId id);
        const Body* FindBody(BodyId id) const;

        void IntegrateBody(Body& body, float dt);
        void ClearForces(Body& body);

    private:
        std::unordered_map<BodyId, Body> m_bodies;
        BodyId m_nextId = 1;
        Vec3 m_gravity = Vec3(0.0f, -9.81f, 0.0f);
