### `PhysicsWorld.cpp`
```cpp
#include "PhysicsWorld.h"

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld() = default;

    BodyId PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
    {
        Body body;
        body.id = m_nextId++;
        body.transform = desc.transform;
        body.mass = desc.mass > 0.0f ? desc.mass : 1.0f;
        body.invMass = desc.isStatic ? 0.0f : 1.0f / body.mass;
        body.isStatic = desc.isStatic;
        body.useGravity = desc.useGravity;

        m_bodies.emplace(body.id, body);
        return body.id;
    }

    void PhysicsWorld::DestroyBody(BodyId id)
    {
        m_bodies.erase(id);
    }

    void PhysicsWorld::ApplyForce(BodyId id, const Vec3& force)
    {
        Body* body = FindBody(id);
        if (!body || body->isStatic) return;
        body->forceAccum += force;
    }

    void PhysicsWorld::ApplyImpulse(BodyId id, const Vec3& impulse)
    {
        Body* body = FindBody(id);
        if (!body || body->isStatic) return;
        body->velocity += impulse * body->invMass;
    }

    Transform PhysicsWorld::GetTransform(BodyId id) const
    {
        const Body* body = FindBody(id);
        if (!body) return {};
        return body->transform;
    }

    void PhysicsWorld::SetTransform(BodyId id, const Transform& t)
    {
        Body* body = FindBody(id);
        if (!body) return;
        body->transform = t;
    }

    void PhysicsWorld::SetGravity(const Vec3& gravity)
    {
        m_gravity = gravity;
    }

    void PhysicsWorld::StepSimulation(float dt)
    {
        if (dt <= 0.0f) return;

        for (auto& [id, body] : m_bodies)
        {
            IntegrateBody(body, dt);
        }

        // Placeholder collision pass:
        // Replace with broadphase + narrowphase later.
        // For now, this is where collision events would be generated.
    }

    void PhysicsWorld::SetCollisionCallback(std::function<void(const CollisionEvent&)> callback)
    {
        m_collisionCallback = std::move(callback);
    }

    Body* PhysicsWorld::FindBody(BodyId id)
    {
        auto it = m_bodies.find(id);
        return it != m_bodies.end() ? &it->second : nullptr;
    }

    const Body* PhysicsWorld::FindBody(BodyId id) const
    {
        auto it = m_bodies.find(id);
        return it != m_bodies.end() ? &it->second : nullptr;
    }

    void PhysicsWorld::IntegrateBody(Body& body, float dt)
    {
        if (body.isStatic) return;

        Vec3 totalForce = body.forceAccum;
        if (body.useGravity)
            totalForce += m_gravity * body.mass;

        Vec3 acceleration = totalForce * body.invMass;

        body.velocity += acceleration * dt;
        body.transform.position += body.velocity * dt;

        ClearForces(body);
    }

    void PhysicsWorld::ClearForces(Body& body)
    {
        body.forceAccum = Vec3{};
    }
}
