```cpp
#pragma once

#include <cstdint>

struct Vec3
{
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    Vec3() = default;
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
    Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }

    Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    Vec3& operator-=(const Vec3& rhs) { x -= rhs.x; y -= rhs.y; z -= rhs.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

inline float Dot(const Vec3& a, const Vec3& b)
{
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

inline float LengthSq(const Vec3& v)
{
    return Dot(v, v);
}

enum class EBodyType : uint8_t
{
    Static,
    Dynamic,
    Kinematic
};

struct Transform
{
    Vec3 position;
    Vec3 rotationEuler; // initial implementation: Euler angles only
};

class CollisionShape;

class RigidBody
{
public:
    EBodyType BodyType = EBodyType::Dynamic;

    Transform WorldTransform;
    Vec3 LinearVelocity;
    Vec3 AngularVelocity;

    Vec3 AccumulatedForce;
    Vec3 AccumulatedTorque;

    float Mass = 1.0f;
    float InvMass = 1.0f;

    float Restitution = 0.2f;
    float Friction = 0.8f;

    CollisionShape* Shape = nullptr;

    bool IsAwake = true;

public:
    void SetMass(float InMass);
    void AddForce(const Vec3& Force);
    void AddImpulse(const Vec3& Impulse);
    void Integrate(float DeltaTime, const Vec3& Gravity);
    void ClearAccumulators();
};
```

### `RigidBody.cpp`

```cpp
#include "RigidBody.h"
#include "CollisionShape.h"

void RigidBody::SetMass(float InMass)
{
    Mass = InMass;
    InvMass = (InMass > 0.0f) ? 1.0f / InMass : 0.0f;

    if (BodyType == EBodyType::Static)
    {
        InvMass = 0.0f;
    }
}

void RigidBody::AddForce(const Vec3& Force)
{
    AccumulatedForce += Force;
    IsAwake = true;
}

void RigidBody::AddImpulse(const Vec3& Impulse)
{
    if (InvMass <= 0.0f) return;
    LinearVelocity += Impulse * InvMass;
    IsAwake = true;
}

void RigidBody::Integrate(float DeltaTime, const Vec3& Gravity)
{
    if (!IsAwake || BodyType == EBodyType::Static)
        return;

    if (BodyType == EBodyType::Dynamic)
    {
        Vec3 acceleration = Gravity + (AccumulatedForce * InvMass);
        LinearVelocity += acceleration * DeltaTime;
        WorldTransform.position += LinearVelocity * DeltaTime;
    }
    else if (BodyType == EBodyType::Kinematic)
    {
        // Kinematic bodies are moved externally by the engine/game code.
    }

    ClearAccumulators();
}

void RigidBody::ClearAccumulators()
{
    AccumulatedForce = {};
    AccumulatedTorque = {};
}
