```cpp
#include "BroadPhase.h"
#include "CollisionShape.h"

static bool SphereSphereTest(RigidBody* A, RigidBody* B, CollisionManifold& OutManifold)
{
    auto* SA = static_cast<SphereShape*>(A->Shape);
    auto* SB = static_cast<SphereShape*>(B->Shape);

    Vec3 delta = B->WorldTransform.position - A->WorldTransform.position;
    float distSq = LengthSq(delta);
    float radius = SA->Radius + SB->Radius;

    if (distSq > radius * radius)
        return false;

    float dist = std::sqrt(distSq);
    OutManifold.HasCollision = true;
    OutManifold.A = A;
    OutManifold.B = B;
    OutManifold.Penetration = radius - dist;
    OutManifold.Normal = (dist > 0.0001f) ? delta * (1.0f / dist) : Vec3{1.0f, 0.0f, 0.0f};
    OutManifold.ContactPoint = A->WorldTransform.position + OutManifold.Normal * SA->Radius;
    return true;
}

void BroadPhase::ComputePairs(const std::vector<RigidBody*>& Bodies, std::vector<CollisionManifold>& OutPairs)
{
    OutPairs.clear();

    for (size_t i = 0; i < Bodies.size(); ++i)
    {
        for (size_t j = i + 1; j < Bodies.size(); ++j)
        {
            RigidBody* A = Bodies[i];
            RigidBody* B = Bodies[j];

            if (!A || !B || !A->Shape || !B->Shape)
                continue;

            if (A->Shape->GetType() == EShapeType::Sphere &&
                B->Shape->GetType() == EShapeType::Sphere)
            {
                CollisionManifold M;
                if (SphereSphereTest(A, B, M))
                    OutPairs.push_back(M);
            }
        }
    }
}
