```cpp
#include "PhysicsWorld.h"
#include <algorithm>

void PhysicsWorld::AddBody(RigidBody* Body)
{
    if (!Body) return;
    Bodies.push_back(Body);
}

void PhysicsWorld::RemoveBody(RigidBody* Body)
{
    Bodies.erase(std::remove(Bodies.begin(), Bodies.end(), Body), Bodies.end());
}

void PhysicsWorld::Step(float DeltaTime)
{
    for (RigidBody* Body : Bodies)
    {
        if (Body)
            Body->Integrate(DeltaTime, Gravity);
    }

    BroadPhase Broad;
    std::vector<CollisionManifold> Contacts;
    Broad.ComputePairs(Bodies, Contacts);

    for (auto& Contact : Contacts)
    {
        ResolveCollision(Contact);
    }
}

void PhysicsWorld::ResolveCollision(CollisionManifold& Manifold)
{
    if (!Manifold.HasCollision || !Manifold.A || !Manifold.B)
        return;

    RigidBody* A = Manifold.A;
    RigidBody* B = Manifold.B;

    float InvMassSum = A->InvMass + B->InvMass;
    if (InvMassSum <= 0.0f)
        return;

    // Positional correction
    const float Percent = 0.8f;
    const float Slop = 0.01f;
    float CorrectionMag = std::max(Manifold.Penetration - Slop, 0.0f) / InvMassSum * Percent;
    Vec3 Correction = Manifold.Normal * CorrectionMag;

    if (A->BodyType == EBodyType::Dynamic)
        A->WorldTransform.position -= Correction * A->InvMass;
    if (B->BodyType == EBodyType::Dynamic)
        B->WorldTransform.position += Correction * B->InvMass;

    // Velocity impulse
    Vec3 RelativeVelocity = B->LinearVelocity - A->LinearVelocity;
    float VelAlongNormal = Dot(RelativeVelocity, Manifold.Normal);

    if (VelAlongNormal > 0.0f)
        return;

    float Restitution = std::min(A->Restitution, B->Restitution);
    float J = -(1.0f + Restitution) * VelAlongNormal;
    J /= InvMassSum;

    Vec3 Impulse = Manifold.Normal * J;

    if (A->BodyType == EBodyType::Dynamic)
        A->LinearVelocity -= Impulse * A->InvMass;
    if (B->BodyType == EBodyType::Dynamic)
        B->LinearVelocity += Impulse * B->InvMass;
}
