## 7) Basic collision detection and response

This is intentionally simple: sphere-sphere and sphere-box, with static/dynamic resolution.

### Add to `PhysicsWorld.cpp`
```cpp
static bool IntersectSphereSphere(
    const Vec3& P0, float R0,
    const Vec3& P1, float R1,
    Vec3& OutNormal, float& OutPenetration)
{
    Vec3 Delta = P1 - P0;
    float DistSq = LengthSq(Delta);
    float R = R0 + R1;

    if (DistSq >= R * R)
        return false;

    float Dist = std::sqrt(std::max(DistSq, 0.000001f));
    OutPenetration = R - Dist;
    OutNormal = Delta * (1.0f / Dist);
    return true;
}

static bool IntersectSphereBox(
    const Vec3& SpherePos, float Radius,
    const Vec3& BoxPos, const Vec3& HalfExtents,
    Vec3& OutNormal, float& OutPenetration)
{
    Vec3 Closest(
        std::clamp(SpherePos.x, BoxPos.x - HalfExtents.x, BoxPos.x + HalfExtents.x),
        std::clamp(SpherePos.y, BoxPos.y - HalfExtents.y, BoxPos.y + HalfExtents.y),
        std::clamp(SpherePos.z, BoxPos.z - HalfExtents.z, BoxPos.z + HalfExtents.z));

    Vec3 Delta = SpherePos - Closest;
    float DistSq = LengthSq(Delta);

    if (DistSq >= Radius * Radius)
        return false;

    float Dist = std::sqrt(std::max(DistSq, 0.000001f));
    OutPenetration = Radius - Dist;
    OutNormal = Delta * (1.0f / Dist);
    return true;
}

static void ResolvePair(PhysicsActor& A, PhysicsActor& B, const Vec3& Normal, float Penetration)
{
    auto& BA = A.Body;
    auto& BB = B.Body;

    float InvMassSum = BA.InvMass + BB.InvMass;
    if (InvMassSum <= 0.0f)
        return;

    // Positional correction
    Vec3 Correction = Normal * (Penetration / InvMassSum);
    if (BA.Type == EBodyType::Dynamic)
        BA.Position -= Correction * BA.InvMass;
    if (BB.Type == EBodyType::Dynamic)
        BB.Position += Correction * BB.InvMass;

    // Relative velocity
    Vec3 RV = BB.Velocity - BA.Velocity;
    float VelAlongNormal = Dot(RV, Normal);

    if (VelAlongNormal > 0.0f)
        return;

    float Restitution = std::min(BA.Restitution, BB.Restitution);
    float J = -(1.0f + Restitution) * VelAlongNormal;
    J /= InvMassSum;

    Vec3 Impulse = Normal * J;
    if (BA.Type == EBodyType::Dynamic)
        BA.Velocity -= Impulse * BA.InvMass;
    if (BB.Type == EBodyType::Dynamic)
        BB.Velocity += Impulse * BB.InvMass;
}

void PhysicsWorld::DetectAndResolveCollisions()
{
    for (size_t i = 0; i < Actors.size(); ++i)
    {
        for (size_t j = i + 1; j < Actors.size(); ++j)
        {
            auto& A = Actors[i];
            auto& B = Actors[j];

            Vec3 Normal;
            float Penetration = 0.0f;
            bool bHit = false;

            if (A.Collider.Type == EColliderType::Sphere && B.Collider.Type == EColliderType::Sphere)
            {
                bHit = IntersectSphereSphere(
                    A.Body.Position, A.Collider.Radius,
                    B.Body.Position, B.Collider.Radius,
                    Normal, Penetration);
            }
            else if (A.Collider.Type == EColliderType::Sphere && B.Collider.Type == EColliderType::Box)
            {
                bHit = IntersectSphereBox(
                    A.Body.Position, A.Collider.Radius,
                    B.Body.Position, B.Collider.HalfExtents,
                    Normal, Penetration);
            }
            else if (A.Collider.Type == EColliderType::Box && B.Collider.Type == EColliderType::Sphere)
            {
                bHit = IntersectSphereBox(
                    B.Body.Position, B.Collider.Radius,
                    A.Body.Position, A.Collider.HalfExtents,
                    Normal, Penetration);
                Normal = Normal * -1.0f;
            }

            if (bHit)
            {
                ResolvePair(A, B, Normal, Penetration);
            }
        }
    }
}
```

