            body->Integrate(dt, gravity);
    }

    // Naive pairwise collision pass
    for (size_t i = 0; i < bodies.size(); ++i)
    {
        for (size_t j = i + 1; j < bodies.size(); ++j)
        {
            PhysicsBody* a = bodies[i];
            PhysicsBody* b = bodies[j];
            if (!a || !b) continue;

            // Placeholder: sphere radius fixed at 1.0
            CollisionManifold m = PhysicsCollision::TestSphereSphere(*a, 1.0f, *b, 1.0f);
            if (m.hasCollision)
            {
                ResolveCollision(*a, *b, m);
            }
        }
    }
}

void PhysicsWorld::ResolveCollision(PhysicsBody& a, PhysicsBody& b, const CollisionManifold& m)
{
    // Initial placeholder resolution:
    // In a real implementation, separate bodies and apply impulse based on relative velocity.
    if (a.GetBodyType() == EPhysicsBodyType::Dynamic)
    {
        Vec3 pos = a.GetPosition();
        pos.y += m.penetration * 0.5f;
        a.SetPosition(pos);
    }

    if (b.GetBodyType() == EPhysicsBodyType::Dynamic)
    {
        Vec3 pos = b.GetPosition();
        pos.y -= m.penetration * 0.5f;
        b.SetPosition(pos);
    }
}
