## `PhysicsBody.cpp`
```cpp
#include "PhysicsBody.h"

namespace CustomPhysics
{
    void PhysicsBody::SetMass(float mass)
    {
        m_mass = (mass <= 0.0f) ? 1.0f : mass;
    }

    void PhysicsBody::AddForce(const Vector3& force)
    {
        if (m_type == BodyType::Dynamic)
        {
            m_accumulatedForce += force;
        }
    }

    void PhysicsBody::Integrate(float deltaTime, const Vector3& gravity)
    {
        if (m_type != BodyType::Dynamic || deltaTime <= 0.0f)
            return;

        Vector3 acceleration = {0.0f, 0.0f, 0.0f};

        if (m_gravityEnabled)
        {
            acceleration += gravity;
        }

        acceleration += m_accumulatedForce * (1.0f / m_mass);

        m_velocity += acceleration * deltaTime;
        m_transform.position += m_velocity * deltaTime;

        // Clear forces after integration
        m_accumulatedForce = {0.0f, 0.0f, 0.0f};
    }
}
