## 3) Example initial implementation

This is a simple fixed-step loop with a stub world:

```cpp
#include <memory>
#include <vector>
#include <cmath>

struct Vec3
{
    float x, y, z;
};

class PhysicsBody
{
public:
    Vec3 position{0, 0, 0};
    Vec3 velocity{0, 0, 0};
    float mass = 1.0f;
    bool isStatic = false;
};

class PhysicsWorld : public IPhysicsWorld
{
public:
    void Initialize() override
    {
        bodies_.clear();
    }

    void Shutdown() override
    {
        bodies_.clear();
    }

    void Step(float deltaTime) override
    {
        const Vec3 gravity{0.0f, -9.81f, 0.0f};

        for (auto& body : bodies_)
        {
            if (body.isStatic) continue;

            body.velocity.x += gravity.x * deltaTime;
            body.velocity.y += gravity.y * deltaTime;
            body.velocity.z += gravity.z * deltaTime;

            body.position.x += body.velocity.x * deltaTime;
            body.position.y += body.velocity.y * deltaTime;
            body.position.z += body.velocity.z * deltaTime;

            // Simple ground plane at y = 0
            if (body.position.y < 0.0f)
            {
                body.position.y = 0.0f;
                if (body.velocity.y < 0.0f)
                    body.velocity.y *= -0.5f; // restitution
            }
        }
    }

    PhysicsBody& CreateBody(const Vec3& pos, float mass, bool isStatic)
    {
        bodies_.push_back(PhysicsBody{pos, {0,0,0}, mass, isStatic});
        return bodies_.back();
    }

private:
    std::vector<PhysicsBody> bodies_;
};

class PhysicsPlugin
{
public:
    bool OnLoad()
    {
        world_ = std::make_unique<PhysicsWorld>();
        world_->Initialize();

        // Example body
        auto* concreteWorld = static_cast<PhysicsWorld*>(world_.get());
        concreteWorld->CreateBody({0.0f, 10.0f, 0.0f}, 1.0f, false);

        return true;
    }

    void OnUnload()
    {
        if (world_)
        {
            world_->Shutdown();
            world_.reset();
        }
    }

    void OnUpdate(float deltaTime)
    {
        accumulator_ += deltaTime;

        while (accumulator_ >= fixedTimeStep_)
        {
            world_->Step(fixedTimeStep_);
            accumulator_ -= fixedTimeStep_;
        }
    }

private:
    std::unique_ptr<IPhysicsWorld> world_;
    float accumulator_ = 0.0f;
    const float fixedTimeStep_ = 1.0f / 60.0f;
};
```

