## 4) Rigid body implementation

### `src/RigidBody.cpp`
```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody()
        : m_position(0, 0, 0),
          m_velocity(0, 0, 0),
          m_accumulatedForce(0, 0, 0),
          m_mass(1.0f),
          m_inverseMass(1.0f),
          m_restitution(0.2f),
          m_friction(0.5f),
          m_static(false)
    {
    }

    void RigidBody::SetPosition(const Vec3& position) { m_position = position; }
    void RigidBody::SetVelocity(const Vec3& velocity) { m_velocity = velocity; }

    void RigidBody::SetMass(float mass)
    {
        m_mass = (mass <= 0.0f) ? 1.0f : mass;
        m_inverseMass = 1.0f / m_mass;
        if (m_static)
        {
            m_inverseMass = 0.0f;
        }
    }

    void RigidBody::SetRestitution(float restitution) { m_restitution = restitution; }
    void RigidBody::SetFriction(float friction) { m_friction = friction; }

    void RigidBody::SetStatic(bool isStatic)
    {
        m_static = isStatic;
        m_inverseMass = m_static ? 0.0f : (1.0f / m_mass);
    }

    const Vec3& RigidBody::GetPosition() const { return m_position; }
    const Vec3& RigidBody::GetVelocity() const { return m_velocity; }
    float RigidBody::GetMass() const { return m_mass; }
    float RigidBody::GetInverseMass() const { return m_inverseMass; }
    float RigidBody::GetRestitution() const { return m_restitution; }
    float RigidBody::GetFriction() const { return m_friction; }
    bool RigidBody::IsStatic() const { return m_static; }

    void RigidBody::AddForce(const Vec3& force)
    {
        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vec3(0, 0, 0);
    }

    void RigidBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_static || dt <= 0.0f)
            return;

        Vec3 acceleration = gravity + (m_accumulatedForce * m_inverseMass);

        // Semi-implicit Euler
        m_velocity += acceleration * dt;
        m_position += m_velocity * dt;

        ClearForces();
    }
}
