## 6) Physics world implementation

### `src/PhysicsWorld.cpp`
```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
    {
    }

    void PhysicsWorld::SetGravity(const Vec3& gravity) { m_gravity = gravity; }
    const Vec3& PhysicsWorld::GetGravity() const { return m_gravity; }

    RigidBody* PhysicsWorld::CreateRigidBody()
    {
        m_bodies.push_back(std::make_unique<RigidBody>());
        return m_bodies.back().get();
    }

    void PhysicsWorld::DestroyRigidBody(RigidBody* body)
    {
        auto it = std::remove_if(m_bodies.begin(), m_bodies.end(),
            [body](const std::unique_ptr<RigidBody>& ptr)
            {
                return ptr.get() == body;
            });

        m_bodies.erase(it, m_bodies.end());
    }

    void PhysicsWorld::AddGroundPlane(const Plane& plane)
    {
        m_planes.push_back(plane);
    }

    void PhysicsWorld::Step(float dt)
    {
        if (dt <= 0.0f)
            return;

        for (auto& body : m_bodies)
        {
            body->Integrate(dt, m_gravity);

            for (const auto& plane : m_planes)
            {
                ResolvePlaneCollision(*body, plane);
            }
        }
    }

    void PhysicsWorld::ResolvePlaneCollision(RigidBody& body, const Plane& plane)
    {
        if (body.IsStatic())
            return;

        const Vec3& pos = body.GetPosition();
        float signedDistance = pos.x * plane.normal.x +
                               pos.y * plane.normal.y +
                               pos.z * plane.normal.z +
                               plane.distance;

        if (signedDistance < 0.0f)
        {
            // Push body out of plane
            Vec3 correction = plane.normal * (-signedDistance);
            body.SetPosition(pos + correction);

            // Reflect velocity
            Vec3 vel = body.GetVelocity();
            float vn = vel.x * plane.normal.x + vel.y * plane.normal.y + vel.z * plane.normal.z;

            if (vn < 0.0f)
            {
                Vec3 normalComponent = plane.normal * vn;
                Vec3 tangentComponent = vel - normalComponent;

                float restitution = body.GetRestitution();
                float friction = body.GetFriction();

                Vec3 newNormal = normalComponent * (-restitution);
                Vec3 newTangent = tangentComponent * std::max(0.0f, 1.0f - friction);

                body.SetVelocity(newNormal + newTangent);
            }
        }
    }

    const std::vector<std::unique_ptr<RigidBody>>& PhysicsWorld::GetBodies() const
    {
        return m_bodies;
    }
}
