        c.radius = r;
        c.halfExtents = Vec3(0,0,0);
        return c;
    }

    static Collider MakeBox(const Vec3& halfExtents)
    {
        Collider c;
        c.type = ColliderType::Box;
        c.halfExtents = halfExtents;
        c.radius = 0.0f;
        return c;
    }
};

struct PhysicsMaterial
{
    float restitution = 0.2f;
    float friction = 0.5f;
};

class PhysicsBody
{
public:
    BodyType type = BodyType::Dynamic;
    Transform transform;
    Vec3 velocity = Vec3(0,0,0);
    Vec3 forceAccum = Vec3(0,0,0);
    float mass = 1.0f;
    float invMass = 1.0f;
    Collider collider;
    PhysicsMaterial material;

    void SetMass(float m)
    {
        mass = m;
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f;
    }

    void AddForce(const Vec3& force)
    {
        if (type == BodyType::Dynamic)
            forceAccum += force;
    }

    void ClearForces()
    {
        forceAccum = Vec3(0,0,0);
    }
};
