## `PhysicsWorld.cpp`
```cpp
#include "PhysicsWorld.h"
#include <algorithm>

void PhysicsWorld::AddBody(PhysicsBody* body)
{
    bodies.push_back(body);
}

void PhysicsWorld::RemoveBody(PhysicsBody* body)
{
    bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
}

void PhysicsWorld::Step(float dt)
{
    for (PhysicsBody* body : bodies)
    {
        IntegrateBody(body, dt);
    }

    DetectAndResolveCollisions();

    for (PhysicsBody* body : bodies)
    {
        body->ClearForces();
    }
}

void PhysicsWorld::IntegrateBody(PhysicsBody* body, float dt)
{
    if (!body || body->type != BodyType::Dynamic || body->invMass <= 0.0f)
        return;

    Vec3 acceleration = gravity + body->forceAccum * body->invMass;
    body->velocity += acceleration * dt;
    body->transform.position += body->velocity * dt;
}

bool PhysicsWorld::Intersect(const PhysicsBody& a, const PhysicsBody& b, Contact& outContact)
{
    // Sphere-Sphere
    if (a.collider.type == ColliderType::Sphere && b.collider.type == ColliderType::Sphere)
    {
        Vec3 delta = b.transform.position - a.transform.position;
        float distSq = LengthSq(delta);
        float r = a.collider.radius + b.collider.radius;

        if (distSq < r * r)
        {
            float dist = std::sqrt(std::max(distSq, 1e-6f));
            outContact.normal = (dist > 0.0f) ? (delta / dist) : Vec3(0,1,0);
            outContact.penetration = r - dist;
            return true;
        }
    }

    // AABB-AABB
    if (a.collider.type == ColliderType::Box && b.collider.type == ColliderType::Box)
    {
        Vec3 ap = a.transform.position;
        Vec3 bp = b.transform.position;
        Vec3 ah = a.collider.halfExtents;
        Vec3 bh = b.collider.halfExtents;

        bool overlapX = std::abs(ap.x - bp.x) <= (ah.x + bh.x);
        bool overlapY = std::abs(ap.y - bp.y) <= (ah.y + bh.y);
        bool overlapZ = std::abs(ap.z - bp.z) <= (ah.z + bh.z);

        if (overlapX && overlapY && overlapZ)
        {
            Vec3 diff = bp - ap;
            float px = (ah.x + bh.x) - std::abs(diff.x);
            float py = (ah.y + bh.y) - std::abs(diff.y);
            float pz = (ah.z + bh.z) - std::abs(diff.z);

            outContact.penetration = std::min({px, py, pz});

            if (outContact.penetration == px)
                outContact.normal = Vec3((diff.x < 0) ? -1.0f : 1.0f, 0, 0);
            else if (outContact.penetration == py)
                outContact.normal = Vec3(0, (diff.y < 0) ? -1.0f : 1.0f, 0);
            else
                outContact.normal = Vec3(0, 0, (diff.z < 0) ? -1.0f : 1.0f);

            return true;
        }
    }

    return false;
}

void PhysicsWorld::DetectAndResolveCollisions()
{
    for (size_t i = 0; i < bodies.size(); ++i)
    {
        for (size_t j = i + 1; j < bodies.size(); ++j)
        {
            PhysicsBody* a = bodies[i];
            PhysicsBody* b = bodies[j];

            if (!a || !b) continue;
            if (a->type == BodyType::Static && b->type == BodyType::Static) continue;

            Contact contact;
            contact.a = a;
            contact.b = b;

            if (Intersect(*a, *b, contact))
            {
                ResolveContact(contact);
            }
        }
    }
}

void PhysicsWorld::ResolveContact(const Contact& contact)
{
    PhysicsBody* a = contact.a;
    PhysicsBody* b = contact.b;

    float invMassA = (a->type == BodyType::Dynamic) ? a->invMass : 0.0f;
    float invMassB = (b->type == BodyType::Dynamic) ? b->invMass : 0.0f;

    float invMassSum = invMassA + invMassB;
    if (invMassSum <= 0.0f) return;

    // Positional correction
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(contact.penetration - slop, 0.0f) / invMassSum * percent;
    Vec3 correction = contact.normal * correctionMag;

    if (a->type == BodyType::Dynamic)
        a->transform.position -= correction * invMassA;
    if (b->type == BodyType::Dynamic)
        b->transform.position += correction * invMassB;

    // Relative velocity
    Vec3 rv = b->velocity - a->velocity;
    float velAlongNormal = Dot(rv, contact.normal);

    if (velAlongNormal > 0.0f)
        return;

    float e = std::min(a->material.restitution, b->material.restitution);
    float j = -(1.0f + e) * velAlongNormal;
    j /= invMassSum;

    Vec3 impulse = contact.normal * j;

    if (a->type == BodyType::Dynamic)
        a->velocity -= impulse * invMassA;
    if (b->type == BodyType::Dynamic)
        b->velocity += impulse * invMassB;
}
