    void SetGravity(const Vec3& InGravity) { Gravity = InGravity; }

    RigidBody* CreateBody(const RigidBodyDesc& Desc)
    {
        Bodies.emplace_back(Desc);
        return &Bodies.back();
    }

    void Step(float DeltaTime)
    {
        for (auto& Body : Bodies)
        {
            if (!Body.IsDynamic())
                continue;

            if (Body.Desc.bUseGravity)
            {
                Body.LinearVelocity.x += Gravity.x * DeltaTime;
                Body.LinearVelocity.y += Gravity.y * DeltaTime;
                Body.LinearVelocity.z += Gravity.z * DeltaTime;
            }

            Body.Position.x += Body.LinearVelocity.x * DeltaTime;
            Body.Position.y += Body.LinearVelocity.y * DeltaTime;
            Body.Position.z += Body.LinearVelocity.z * DeltaTime;

            // Placeholder: collision resolution goes here
        }
    }

    const std::vector<RigidBody>& GetBodies() const { return Bodies; }

private:
    Vec3 Gravity {0.0f, -980.0f, 0.0f};
    std::vector<RigidBody> Bodies;
};
