## 4) Physics world implementation

```cpp
// PhysicsWorld.cpp
#include "PhysicsWorld.h"

PhysicsWorld::PhysicsWorld()
    : gravity(0.0f, -9.81f, 0.0f) {}

PhysicsBody* PhysicsWorld::CreateBody(const PhysicsBody& body) {
    storage.push_back(body);
    bodies.push_back(&storage.back());
    return &storage.back();
}

void PhysicsWorld::RemoveBody(PhysicsBody* body) {
    for (size_t i = 0; i < bodies.size(); ++i) {
        if (bodies[i] == body) {
            bodies.erase(bodies.begin() + i);
            break;
        }
    }
}

void PhysicsWorld::Step(float dt) {
    for (auto* body : bodies) {
        if (!body->IsDynamic()) continue;
        IntegrateForces(*body, dt);
    }

    SolveCollisions();

    for (auto* body : bodies) {
        if (!body->IsDynamic()) continue;
        IntegrateVelocity(*body, dt);
        body->ClearForces();
    }
}

void PhysicsWorld::IntegrateForces(PhysicsBody& body, float dt) {
    Vec3 acceleration = gravity + body.accumulatedForce * body.inverseMass;
    body.velocity += acceleration * dt;
}

void PhysicsWorld::IntegrateVelocity(PhysicsBody& body, float dt) {
    body.position += body.velocity * dt;
}

void PhysicsWorld::SolveCollisions() {
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            Contact c;
            if (SphereSphere(*bodies[i], *bodies[j], c)) {
                ResolveContact(c);
            }
        }
    }
}

bool PhysicsWorld::SphereSphere(PhysicsBody& a, PhysicsBody& b, Contact& outContact) {
    Vec3 delta = b.position - a.position;
    float distSq = delta.LengthSq();
    float radiusSum = a.radius + b.radius;

    if (distSq >= radiusSum * radiusSum) return false;

    float dist = std::sqrt(distSq);
    outContact.a = &a;
    outContact.b = &b;
    outContact.normal = (dist > 1e-6f) ? (delta / dist) : Vec3(0, 1, 0);
    outContact.penetration = radiusSum - dist;
    return true;
}

void PhysicsWorld::ResolveContact(const Contact& c) {
    PhysicsBody* a = c.a;
    PhysicsBody* b = c.b;

    float invMassA = a->IsDynamic() ? a->inverseMass : 0.0f;
    float invMassB = b->IsDynamic() ? b->inverseMass : 0.0f;
    float totalInvMass = invMassA + invMassB;
    if (totalInvMass <= 0.0f) return;

    // Positional correction
    Vec3 correction = c.normal * (c.penetration / totalInvMass);
    if (a->IsDynamic()) a->position -= correction * invMassA;
    if (b->IsDynamic()) b->position += correction * invMassB;

    // Relative velocity
    Vec3 rv = b->velocity - a->velocity;
    float velAlongNormal = Vec3::Dot(rv, c.normal);
    if (velAlongNormal > 0.0f) return;

    float e = (a->restitution < b->restitution) ? a->restitution : b->restitution;
    float j = -(1.0f + e) * velAlongNormal;
    j /= totalInvMass;

    Vec3 impulse = c.normal * j;
    if (a->IsDynamic()) a->velocity -= impulse * invMassA;
    if (b->IsDynamic()) b->velocity += impulse * invMassB;
}
```

