#pragma once

#include "PhysicsTypes.h"

enum class EBodyType
{
    Static,
    Dynamic
};

struct RigidBodyDesc
{
    EBodyType Type = EBodyType::Dynamic;
    float Mass = 1.0f;
    Vec3 Position = Vec3(0, 0, 0);
    Vec3 Velocity = Vec3(0, 0, 0);
    Vec3 AccumulatedForce = Vec3(0, 0, 0);
    float Restitution = 0.2f;
    float LinearDamping = 0.01f;
};

class RigidBody
{
public:
    explicit RigidBody(const RigidBodyDesc& desc);

    void AddForce(const Vec3& force);
    void ClearForces();

    void Integrate(float dt, const Vec3& gravity);

    const Vec3& GetPosition() const { return m_position; }
    const Vec3& GetVelocity() const { return m_velocity; }
    void SetPosition(const Vec3& p) { m_position = p; }
    void SetVelocity(const Vec3& v) { m_velocity = v; }

    EBodyType GetType() const { return m_type; }
    float GetMass() const { return m_mass; }
    float GetInvMass() const { return m_invMass; }

private:
    EBodyType m_type = EBodyType::Dynamic;
    float m_mass = 1.0f;
    float m_invMass = 1.0f;

    Vec3 m_position;
    Vec3 m_velocity;
    Vec3 m_forceAccum;

    float m_restitution = 0.2f;
    float m_linearDamping = 0.01f;
};
```

### `RigidBody.cpp`
```cpp
#include "RigidBody.h"

RigidBody::RigidBody(const RigidBodyDesc& desc)
    : m_type(desc.Type)
    , m_mass(desc.Mass)
    , m_position(desc.Position)
    , m_velocity(desc.Velocity)
    , m_forceAccum(desc.AccumulatedForce)
    , m_restitution(desc.Restitution)
    , m_linearDamping(desc.LinearDamping)
{
    if (m_type == EBodyType::Static || m_mass <= 0.0f)
    {
        m_mass = 0.0f;
        m_invMass = 0.0f;
    }
    else
    {
        m_invMass = 1.0f / m_mass;
    }
}

void RigidBody::AddForce(const Vec3& force)
{
    if (m_type == EBodyType::Dynamic)
    {
        m_forceAccum += force;
    }
}

void RigidBody::ClearForces()
{
    m_forceAccum = Vec3(0, 0, 0);
}

void RigidBody::Integrate(float dt, const Vec3& gravity)
{
    if (m_type == EBodyType::Static || m_invMass <= 0.0f)
        return;

    // Acceleration from force and gravity
    Vec3 acceleration = gravity + (m_forceAccum * m_invMass);

    // Semi-implicit Euler
    m_velocity += acceleration * dt;
    m_velocity *= (1.0f - m_linearDamping);

    m_position += m_velocity * dt;

    ClearForces();
}
```

