#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld() = default;

void PhysicsWorld::SetGravity(const Vec3& gravity)
{
    m_gravity = gravity;
}

RigidBody* PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
{
    m_bodies.push_back(std::make_unique<RigidBody>(desc));
    return m_bodies.back().get();
}

void PhysicsWorld::DestroyBody(RigidBody* body)
{
    auto it = std::remove_if(m_bodies.begin(), m_bodies.end(),
        [body](const std::unique_ptr<RigidBody>& b)
        {
            return b.get() == body;
        });

    m_bodies.erase(it, m_bodies.end());
}

void PhysicsWorld::Step(float dt)
{
    // Basic simulation step
    for (auto& body : m_bodies)
    {
        body->Integrate(dt, m_gravity);
        ResolveGroundPlane(*body);
    }
}

void PhysicsWorld::ResolveGroundPlane(RigidBody& body)
{
    // Temporary placeholder collision: infinite ground plane at y = 0
    if (body.GetType() == EBodyType::Static)
        return;

    Vec3 pos = body.GetPosition();
    Vec3 vel = body.GetVelocity();

    if (pos.y < 0.0f)
    {
        pos.y = 0.0f;

        if (vel.y < 0.0f)
        {
            vel.y = -vel.y * 0.2f; // simple restitution
            vel.x *= 0.98f;        // friction-ish damping
            vel.z *= 0.98f;
        }

        body.SetPosition(pos);
        body.SetVelocity(vel);
    }
}
