## `PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"
#include <algorithm>

namespace CustomPhysics
{
    FPhysicsBody::FPhysicsBody(const FPhysicsBodyDesc& Desc)
        : Type(Desc.Type)
        , Position(Desc.Position)
        , Velocity(Desc.Velocity)
        , AccumulatedForce(0, 0, 0)
        , Mass(Desc.Mass > 0.0f ? Desc.Mass : 1.0f)
        , InvMass(Desc.Type == EBodyType::Dynamic ? 1.0f / (Desc.Mass > 0.0f ? Desc.Mass : 1.0f) : 0.0f)
        , Restitution(std::clamp(Desc.Restitution, 0.0f, 1.0f))
        , Radius(std::max(0.0f, Desc.Radius))
    {
    }

    void FPhysicsBody::AddForce(const Vec3& Force)
    {
        if (Type == EBodyType::Dynamic)
        {
            AccumulatedForce += Force;
        }
    }

    void FPhysicsBody::Integrate(float DeltaTime, const Vec3& Gravity)
    {
        if (Type == EBodyType::Static || DeltaTime <= 0.0f)
        {
            AccumulatedForce = Vec3(0, 0, 0);
            return;
        }

        Vec3 Acceleration = Gravity + (AccumulatedForce * InvMass);
        Velocity += Acceleration * DeltaTime;
        Position += Velocity * DeltaTime;

        AccumulatedForce = Vec3(0, 0, 0);
    }

    void FPhysicsBody::ResolveGroundCollision(float GroundY)
    {
        if (Type == EBodyType::Static)
            return;

        float Bottom = Position.y - Radius;
        if (Bottom < GroundY)
        {
            Position.y = GroundY + Radius;

            if (Velocity.y < 0.0f)
            {
                Velocity.y = -Velocity.y * Restitution;

                // simple friction approximation
                Velocity.x *= 0.98f;
                Velocity.z *= 0.98f;

                if (std::abs(Velocity.y) < 0.01f)
                {
                    Velocity.y = 0.0f;
                }
            }
        }
    }
}
