### `physics_plugin.cpp`
```cpp
#include "physics_plugin.h"
#include <algorithm>

void PhysicsPlugin::Initialize() {
    bodies.clear();
}

void PhysicsPlugin::Shutdown() {
    bodies.clear();
}

void PhysicsPlugin::AddBody(RigidBody* body) {
    if (!body) return;
    bodies.push_back(body);
}

void PhysicsPlugin::RemoveBody(RigidBody* body) {
    bodies.erase(
        std::remove(bodies.begin(), bodies.end(), body),
        bodies.end()
    );
}

void PhysicsPlugin::Step(float deltaTime) {
    for (RigidBody* body : bodies) {
        if (!body || body->isStatic) continue;
        Integrate(*body, deltaTime);
        ResolveGroundCollision(*body);
    }
}

void PhysicsPlugin::Integrate(RigidBody& body, float dt) {
    body.velocity.x += gravity.x * dt;
    body.velocity.y += gravity.y * dt;
    body.velocity.z += gravity.z * dt;

    body.position.x += body.velocity.x * dt;
    body.position.y += body.velocity.y * dt;
    body.position.z += body.velocity.z * dt;
}

void PhysicsPlugin::ResolveGroundCollision(RigidBody& body) {
    if (body.position.y < 0.0f) {
        body.position.y = 0.0f;
        if (body.velocity.y < 0.0f) {
            body.velocity.y = -body.velocity.y * body.restitution;
            if (std::abs(body.velocity.y) < 0.05f) {
                body.velocity.y = 0.0f;
            }
        }
    }
}
