void PhysicsPlugin::Step(float dt) {
    for (auto* body : bodies) {
        if (!body || body->isStatic) continue;

        Vec3 acceleration = gravity;
        if (body->mass > 0.0f) {
            acceleration = acceleration + (body->force * (1.0f / body->mass));
