```cpp
// MinimalPhysics.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position{};
    Vec3 velocity{};
    Vec3 force{};
    float mass = 1.0f;
    bool isStatic = false;
};

class PhysicsWorld {
public:
    void AddBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void Step(float dt) {
        for (auto* body : bodies) {
            if (body->isStatic || body->mass <= 0.0f) continue;

            // Gravity
            body->force.y += -9.81f * body->mass;

            // Integrate
            Vec3 accel{
                body->force.x / body->mass,
                body->force.y / body->mass,
                body->force.z / body->mass
            };

            body->velocity.x += accel.x * dt;
            body->velocity.y += accel.y * dt;
            body->velocity.z += accel.z * dt;

            body->position.x += body->velocity.x * dt;
            body->position.y += body->velocity.y * dt;
            body->position.z += body->velocity.z * dt;

            // Clear forces
            body->force = {0, 0, 0};

            // Ground collision
            if (body->position.y < 0.0f) {
                body->position.y = 0.0f;
                if (body->velocity.y < 0.0f) {
                    body->velocity.y *= -0.5f; // restitution
                }
            }
        }
    }

private:
    std::vector<RigidBody*> bodies;
};
```

