## Example: engine-agnostic C++ plugin structure

### `PhysicsPlugin.h`
```cpp
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position{};
    Vec3 velocity{};
    Vec3 force{};
    float mass = 1.0f;
    bool isStatic = false;
};

class PhysicsWorld {
public:
    void AddBody(const RigidBody& body);
    void Step(float dt);

    std::vector<RigidBody>& GetBodies();

private:
    std::vector<RigidBody> bodies_;
};

class PhysicsPlugin {
public:
    bool Initialize();
    void Shutdown();
    void Tick(float deltaTime);

    PhysicsWorld& GetWorld();

private:
    PhysicsWorld world_;
    bool initialized_ = false;
};
```

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"

static Vec3 operator+(const Vec3& a, const Vec3& b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 operator-(const Vec3& a, const Vec3& b) {
    return {a.x - b.x, a.y - b.y, a.z - b.z};
}

static Vec3 operator*(const Vec3& v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

void PhysicsWorld::AddBody(const RigidBody& body) {
    bodies_.push_back(body);
}

std::vector<RigidBody>& PhysicsWorld::GetBodies() {
    return bodies_;
}

void PhysicsWorld::Step(float dt) {
    const Vec3 gravity{0.0f, -9.81f, 0.0f};

    for (auto& body : bodies_) {
        if (body.isStatic) continue;

        // Integrate forces
        Vec3 acceleration{
            gravity.x + body.force.x / body.mass,
            gravity.y + body.force.y / body.mass,
            gravity.z + body.force.z / body.mass
        };

        body.velocity = body.velocity + acceleration * dt;
        body.position = body.position + body.velocity * dt;

        // Clear force accumulator
        body.force = {0.0f, 0.0f, 0.0f};

        // Very simple ground collision
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) {
                body.velocity.y *= -0.5f; // restitution
            }
        }
    }
}

bool PhysicsPlugin::Initialize() {
    initialized_ = true;
    return true;
}

void PhysicsPlugin::Shutdown() {
    initialized_ = false;
}

void PhysicsPlugin::Tick(float deltaTime) {
    if (!initialized_) return;
    world_.Step(deltaTime);
}

PhysicsWorld& PhysicsPlugin::GetWorld() {
    return world_;
}
```

