```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"

static Vec3 add(Vec3 a, Vec3 b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 mul(Vec3 a, float s) {
    return {a.x * s, a.y * s, a.z * s};
}

bool PhysicsPlugin::initialize() {
    bodyCount = 0;
    return true;
}

void PhysicsPlugin::shutdown() {
    bodyCount = 0;
}

void PhysicsPlugin::addBody(RigidBody* body) {
    if (bodyCount < 128) {
        bodies[bodyCount++] = body;
    }
}

void PhysicsPlugin::update(float dt) {
    const Vec3 gravity = {0.0f, -9.81f, 0.0f};

    for (int i = 0; i < bodyCount; ++i) {
        RigidBody* b = bodies[i];
        if (!b || b->isStatic) continue;

        Vec3 accel = add(gravity, mul(b->force, 1.0f / b->mass));
        b->velocity = add(b->velocity, mul(accel, dt));
        b->position = add(b->position, mul(b->velocity, dt));

        // Clear force after integration
        b->force = {0.0f, 0.0f, 0.0f};
    }
}
