```cpp
// SimplePhysicsPlugin.cpp
#include "IPhysicsPlugin.h"
#include <vector>
#include <algorithm>

class SimplePhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {}
    void Shutdown() override { bodies.clear(); }

    void AddBody(RigidBody* body) override {
        bodies.push_back(body);
    }

    void RemoveBody(RigidBody* body) override {
        bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
    }

    void Step(float dt) override {
        const Vec3 gravity{0.0f, -9.81f, 0.0f};

        for (auto* body : bodies) {
            if (!body || body->isStatic) continue;

            body->velocity.x += gravity.x * dt;
            body->velocity.y += gravity.y * dt;
            body->velocity.z += gravity.z * dt;

            body->position.x += body->velocity.x * dt;
            body->position.y += body->velocity.y * dt;
            body->position.z += body->velocity.z * dt;
        }
    }

private:
    std::vector<RigidBody*> bodies;
};
