## 4) `PhysicsPlugin.cpp`

```cpp
#include "PhysicsPlugin.h"

PhysicsPlugin::PhysicsPlugin()
    : initialized(false), gravity(0.0f, -9.81f, 0.0f)
{
}

void PhysicsPlugin::Initialize()
{
    initialized = true;
}

void PhysicsPlugin::Shutdown()
{
    bodies.clear();
    initialized = false;
}

int PhysicsPlugin::CreateBody(const Vec3& position, float mass, bool isStatic)
{
    PhysicsBody body;
    body.position = position;
    body.mass = mass > 0.0f ? mass : 1.0f;
    body.isStatic = isStatic;

    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

PhysicsBody& PhysicsPlugin::GetBody(int id)
{
    return bodies[id];
}

void PhysicsPlugin::AddForce(int id, const Vec3& force)
{
    if (id < 0 || id >= static_cast<int>(bodies.size()))
        return;

    bodies[id].force += force;
}

void PhysicsPlugin::Update(float deltaTime)
{
    if (!initialized)
        return;

    for (auto& body : bodies)
    {
        if (body.isStatic)
            continue;

        // Apply gravity
        body.force += gravity * body.mass;

        // Integrate acceleration -> velocity -> position
        Vec3 acceleration = body.force * (1.0f / body.mass);
        body.velocity += acceleration * deltaTime;
        body.position += body.velocity * deltaTime;

        // Simple ground collision at y = 0
        if (body.position.y < 0.0f)
        {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f)
                body.velocity.y = 0.0f;
        }

        // Clear forces
        body.force = Vec3(0.0f, 0.0f, 0.0f);
    }
}
```

