```cpp
// SimplePhysicsPlugin.cpp
#include "SimplePhysicsPlugin.h"

bool SimplePhysicsPlugin::Initialize() {
    bodies_.clear();
    return true;
}

void SimplePhysicsPlugin::Shutdown() {
    bodies_.clear();
}

int SimplePhysicsPlugin::CreateRigidBody(const RigidBodyDesc& desc) {
    Body body;
    body.active = true;
    body.position = desc.position;
    body.velocity = desc.velocity;
    body.mass = desc.mass > 0.0f ? desc.mass : 1.0f;

    for (int i = 0; i < static_cast<int>(bodies_.size()); ++i) {
        if (!bodies_[i].active) {
            bodies_[i] = body;
            return i;
        }
    }

    bodies_.push_back(body);
    return static_cast<int>(bodies_.size()) - 1;
}

void SimplePhysicsPlugin::DestroyRigidBody(int id) {
    if (id >= 0 && id < static_cast<int>(bodies_.size())) {
        bodies_[id].active = false;
    }
}

void SimplePhysicsPlugin::StepSimulation(float dt) {
    for (auto& body : bodies_) {
        if (!body.active) continue;

        body.velocity.x += gravity_.x * dt;
        body.velocity.y += gravity_.y * dt;
        body.velocity.z += gravity_.z * dt;

        body.position.x += body.velocity.x * dt;
        body.position.y += body.velocity.y * dt;
        body.position.z += body.velocity.z * dt;

        // Simple ground plane at y = 0
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) {
                body.velocity.y *= -0.5f; // restitution
            }
        }
    }
}

void SimplePhysicsPlugin::GetRigidBodyState(int id, Vec3& outPosition, Vec3& outVelocity) const {
    if (id >= 0 && id < static_cast<int>(bodies_.size()) && bodies_[id].active) {
        outPosition = bodies_[id].position;
        outVelocity = bodies_[id].velocity;
    }
}
