### `PhysicsPlugin.h`
```cpp
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;

    RigidBody()
        : position(), velocity(), force(), mass(1.0f), isStatic(false) {}
};

class PhysicsWorld {
public:
    void AddBody(const RigidBody& body);
    void Step(float dt);

    std::vector<RigidBody>& GetBodies() { return bodies; }

private:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void Update(float dt) = 0;
    virtual PhysicsWorld* GetWorld() = 0;
};

// Factory function your engine can call
extern "C" {
    IPhysicsPlugin* CreatePhysicsPlugin();
    void DestroyPhysicsPlugin(IPhysicsPlugin* plugin);
}
```

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"

void PhysicsWorld::AddBody(const RigidBody& body) {
    bodies.push_back(body);
}

void PhysicsWorld::Step(float dt) {
    for (auto& body : bodies) {
        if (body.isStatic) continue;

        Vec3 acceleration = gravity;
        if (body.mass > 0.0f) {
            acceleration += body.force * (1.0f / body.mass);
        }

        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;

        body.force = Vec3(0.0f, 0.0f, 0.0f);
    }
}

class PhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {}
    void Shutdown() override {}
    void Update(float dt) override { world.Step(dt); }
    PhysicsWorld* GetWorld() override { return &world; }

private:
    PhysicsWorld world;
};

extern "C" IPhysicsPlugin* CreatePhysicsPlugin() {
    return new PhysicsPlugin();
}

extern "C" void DestroyPhysicsPlugin(IPhysicsPlugin* plugin) {
    delete plugin;
}
```

