```cpp
#include "CustomPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "Components/PrimitiveComponent.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bEnabled)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    UPrimitiveComponent* Prim = Cast<UPrimitiveComponent>(Owner->GetRootComponent());
    if (!Prim || !Prim->IsSimulatingPhysics())
    {
        return;
    }

    const FVector CurrentLocation = Prim->GetComponentLocation();
    const FVector Direction = (TargetPoint - CurrentLocation).GetSafeNormal();

    if (Direction.IsNearlyZero())
    {
        return;
    }

    const FVector Force = Direction * ForceStrength;
    Prim->AddForce(Force);
}
```

