### `CustomPhysicsPlugin.cpp`
```cpp
#include "CustomPhysicsPlugin.h"
#include <stdexcept>

bool CustomPhysicsPlugin::Initialize() {
    bodies.clear();
    return true;
}

void CustomPhysicsPlugin::Shutdown() {
    bodies.clear();
}

void CustomPhysicsPlugin::Update(float deltaTime) {
    for (auto& body : bodies) {
        if (body.isStatic) continue;

        // Basic Euler integration
        body.velocity.x += gravity.x * deltaTime;
        body.velocity.y += gravity.y * deltaTime;
        body.velocity.z += gravity.z * deltaTime;

        body.position.x += body.velocity.x * deltaTime;
        body.position.y += body.velocity.y * deltaTime;
        body.position.z += body.velocity.z * deltaTime;
    }
}

int CustomPhysicsPlugin::AddRigidBody(const RigidBody& body) {
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void CustomPhysicsPlugin::RemoveRigidBody(int id) {
    if (id < 0 || id >= static_cast<int>(bodies.size())) return;
    bodies[id] = bodies.back();
    bodies.pop_back();
}

const RigidBody& CustomPhysicsPlugin::GetRigidBody(int id) const {
    if (id < 0 || id >= static_cast<int>(bodies.size()))
        throw std::out_of_range("Rigid body id out of range");
    return bodies[id];
}

RigidBody& CustomPhysicsPlugin::GetRigidBody(int id) {
    if (id < 0 || id >= static_cast<int>(bodies.size()))
        throw std::out_of_range("Rigid body id out of range");
    return bodies[id];
}
