## Minimal C++-style plugin skeleton

```cpp
// PhysicsPlugin.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position{};
    Vec3 velocity{};
    Vec3 force{};
    float mass = 1.0f;
    bool isStatic = false;
};

class PhysicsWorld {
public:
    void SetGravity(const Vec3& g);
    int CreateBody(const RigidBody& body);
    RigidBody& GetBody(int id);
    void Step(float dt);

private:
    Vec3 gravity_{0.0f, -9.81f, 0.0f};
    std::vector<RigidBody> bodies_;
};
```

```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"

void PhysicsWorld::SetGravity(const Vec3& g) {
    gravity_ = g;
}

int PhysicsWorld::CreateBody(const RigidBody& body) {
    bodies_.push_back(body);
    return static_cast<int>(bodies_.size() - 1);
}

RigidBody& PhysicsWorld::GetBody(int id) {
    return bodies_[id];
}

void PhysicsWorld::Step(float dt) {
    for (auto& body : bodies_) {
        if (body.isStatic) continue;

        // Acceleration = gravity + force / mass
        Vec3 accel;
        accel.x = gravity_.x + body.force.x / body.mass;
        accel.y = gravity_.y + body.force.y / body.mass;
        accel.z = gravity_.z + body.force.z / body.mass;

        // Semi-implicit Euler integration
        body.velocity.x += accel.x * dt;
        body.velocity.y += accel.y * dt;
        body.velocity.z += accel.z * dt;

        body.position.x += body.velocity.x * dt;
        body.position.y += body.velocity.y * dt;
        body.position.z += body.velocity.z * dt;

        // Very simple ground collision at y = 0
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) {
                body.velocity.y *= -0.5f; // restitution
            }
        }

        // Clear forces each frame
        body.force = {0.0f, 0.0f, 0.0f};
    }
}
```

