## C++ Example

```cpp
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

// -----------------------------
// Basic math
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return {x + b.x, y + b.y, z + b.z}; }
    Vec3 operator-(const Vec3& b) const { return {x - b.x, y - b.y, z - b.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline Vec3 cross(const Vec3& a, const Vec3& b) {
    return {
        a.y*b.z - a.z*b.y,
        a.z*b.x - a.x*b.z,
        a.x*b.y - a.y*b.x
    };
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-8f) return {0, 0, 0};
    return v / len;
}

// -----------------------------
// Quaternion
// -----------------------------
struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& b) const {
        return {
            w*b.w - x*b.x - y*b.y - z*b.z,
            w*b.x + x*b.w + y*b.z - z*b.y,
            w*b.y - x*b.z + y*b.w + z*b.x,
            w*b.z + x*b.y - y*b.x + z*b.w
        };
    }

    Quat operator*(float s) const { return {w*s, x*s, y*s, z*s}; }
    Quat operator+(const Quat& b) const { return {w+b.w, x+b.x, y+b.y, z+b.z}; }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len > 1e-8f) {
            w /= len; x /= len; y /= len; z /= len;
        }
    }
};

static inline Quat quatFromAngularVelocity(const Vec3& omega) {
    return {0.0f, omega.x, omega.y, omega.z};
}

// -----------------------------
// Rigid body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    Quat orientation;
    Vec3 angularVelocity;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    // For simplicity, use a sphere collider
    float radius;

    // Physical properties
    float restitution; // bounciness [0..1]
    float friction;    // [0..1]

    RigidBody(float m, float r)
        : position(0,0,0), velocity(0,0,0), forceAccum(0,0,0),
          orientation(), angularVelocity(0,0,0), torqueAccum(0,0,0),
          mass(m), radius(r), restitution(0.5f), friction(0.5f) {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }

    void applyForce(const Vec3& f) {
        forceAccum += f;
    }

    void applyImpulse(const Vec3& impulse) {
        velocity += impulse * invMass;
    }

    void clearAccumulators() {
        forceAccum = {0,0,0};
        torqueAccum = {0,0,0};
    }

    void integrate(float dt) {
        if (invMass == 0.0f) return; // static body

        // Linear motion
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt; // semi-implicit Euler

        // Angular motion (simplified: no inertia tensor for sphere)
        Vec3 angularAcc = torqueAccum * invMass;
        angularVelocity += angularAcc * dt;

        Quat qdot = quatFromAngularVelocity(angularVelocity) * orientation;
        orientation = orientation + qdot * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

// -----------------------------
// Physics world
// -----------------------------
struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0f, -9.81f, 0.0f};

    // Ground plane at y = 0
    void step(float dt) {
        // Apply forces
        for (auto& b : bodies) {
            if (b.invMass == 0.0f) continue;
            b.applyForce(gravity * b.mass);
        }

        // Integrate
        for (auto& b : bodies) {
            b.integrate(dt);
        }

        // Collisions with ground
        for (auto& b : bodies) {
            resolveGroundCollision(b);
        }
    }

    void resolveGroundCollision(RigidBody& b) {
        float minY = b.radius;
        if (b.position.y < minY) {
            // Position correction
            b.position.y = minY;

            // Velocity response
            if (b.velocity.y < 0.0f) {
                float vn = b.velocity.y;
                b.velocity.y = -vn * b.restitution;

                // Simple friction on tangential velocity
                b.velocity.x *= (1.0f - b.friction);
                b.velocity.z *= (1.0f - b.friction);

                // Sleep threshold to avoid tiny jitter
                if (std::fabs(b.velocity.y) < 0.05f) b.velocity.y = 0.0f;
            }
        }
    }
};

// -----------------------------
// Frame-rate constrained main loop
// -----------------------------
int main() {
    PhysicsWorld world;

    // Create a falling rigid body
    RigidBody ball(1.0f, 0.5f);
    ball.position = {0.0f, 5.0f, 0.0f};
    ball.velocity = {2.0f, 0.0f, 0.0f};
    ball.restitution = 0.7f;
    ball.friction = 0.2f;
    world.bodies.push_back(ball);

    // Fixed timestep physics
    const float fixedDt = 1.0f / 120.0f; // 120 Hz physics
    const float maxFrameTime = 0.25f;     // avoid spiral of death
    float accumulator = 0.0f;

    // Mock real-time loop
    // Replace this with your platform's timer / render loop.
    double lastTime = 0.0;
    double currentTime = 0.0;

    for (int frame = 0; frame < 1000; ++frame) {
        // Simulate variable frame time (example only)
        currentTime += 1.0 / 60.0; // pretend render runs at ~60 FPS
        float frameTime = static_cast<float>(currentTime - lastTime);
        lastTime = currentTime;

        frameTime = std::min(frameTime, maxFrameTime);
        accumulator += frameTime;

        // Step physics at fixed rate
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Interpolation factor for rendering
        float alpha = accumulator / fixedDt;

        // Render/debug output
        const auto& b = world.bodies[0];
        std::cout << "Frame " << frame
                  << " pos=(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                  << " vel=(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                  << " alpha=" << alpha
                  << "\n";
    }

    return 0;
}
```

