    Quat orientation;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    // Simplified inertia for a box-like body
    Vec3 inertia;      // diagonal inertia tensor in local space
    Vec3 invInertia;

    float restitution = 0.4f;
    float friction = 0.5f;

    Vec3 halfExtents;  // box shape

    RigidBody(float m, const Vec3& halfSize)
        : position(), velocity(), orientation(), angularVelocity(),
          forceAccum(), torqueAccum(),
          mass(m), halfExtents(halfSize)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;

        // Box inertia tensor diagonal:
        // Ixx = (1/12)m(hy^2 + hz^2) etc, using full extents = 2*halfExtents
        float x = halfExtents.x * 2.0f;
        float y = halfExtents.y * 2.0f;
        float z = halfExtents.z * 2.0f;

        inertia = {
            (1.0f/12.0f) * mass * (y*y + z*z),
            (1.0f/12.0f) * mass * (x*x + z*z),
            (1.0f/12.0f) * mass * (x*x + y*y)
        };

        invInertia = {
            inertia.x > 0 ? 1.0f / inertia.x : 0.0f,
            inertia.y > 0 ? 1.0f / inertia.y : 0.0f,
            inertia.z > 0 ? 1.0f / inertia.z : 0.0f
        };
    }

    void addForce(const Vec3& f) { forceAccum += f; }

    void clearAccumulators() {
        forceAccum = {0,0,0};
        torqueAccum = {0,0,0};
    }

    void integrate(float dt) {
        if (invMass <= 0.0f) return; // static body

        // Linear motion
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        // Angular motion (simplified)
        Vec3 angularAccel = {
            torqueAccum.x * invInertia.x,
            torqueAccum.y * invInertia.y,
            torqueAccum.z * invInertia.z
        };
        angularVelocity += angularAccel * dt;

        // Quaternion update
        Quat omega(0.0f, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat qdot = orientation * omega;
        qdot = qdot * 0.5f;
        orientation += qdot * dt;
        orientation = normalize(orientation);

        clearAccumulators();
    }
};

// -----------------------------
// Collision with ground plane
// -----------------------------

struct Contact {
    RigidBody* body;
    Vec3 normal;
    float penetration;
    Vec3 contactPoint;
};

void resolveContact(Contact& c) {
    RigidBody* b = c.body;
    if (!b || b->invMass <= 0.0f) return;

    // Positional correction
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(c.penetration - slop, 0.0f) * percent / b->invMass;
    b->position += c.normal * (correctionMag * b->invMass);

    // Relative velocity along normal
    float velAlongNormal = dot(b->velocity, c.normal);
    if (velAlongNormal > 0.0f) return;

    float e = b->restitution;
    float j = -(1.0f + e) * velAlongNormal;
    j /= b->invMass;

    Vec3 impulse = c.normal * j;
    b->velocity += impulse * b->invMass;

    // Simple friction
    Vec3 tangent = b->velocity - c.normal * dot(b->velocity, c.normal);
    float tLen = length(tangent);
    if (tLen > 1e-6f) {
        tangent = tangent / tLen;
        float jt = -dot(b->velocity, tangent);
        jt /= b->invMass;

        float mu = b->friction;
        jt = std::clamp(jt, -j * mu, j * mu);

        b->velocity += tangent * (jt * b->invMass);
    }
}

void groundCollision(RigidBody& b, std::vector<Contact>& contacts) {
    // Treat body as axis-aligned in world for this simple example.
    // For full OBB collision, transform box corners by orientation.
    float bottom = b.position.y - b.halfExtents.y;
    if (bottom < 0.0f) {
        Contact c;
        c.body = &b;
        c.normal = {0, 1, 0};
        c.penetration = -bottom;
        c.contactPoint = {b.position.x, 0.0f, b.position.z};
        contacts.push_back(c);
    }
}

// -----------------------------
// Physics world
// -----------------------------

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0f, -9.81f, 0.0f};

    void step(float dt) {
        // Apply forces
        for (auto& b : bodies) {
            if (b.invMass > 0.0f) {
                b.addForce(gravity * b.mass);
            }
        }

        // Integrate
        for (auto& b : bodies) {
            b.integrate(dt);
        }

        // Collision detection
        std::vector<Contact> contacts;
        for (auto& b : bodies) {
            groundCollision(b, contacts);
        }

        // Resolve contacts
        for (auto& c : contacts) {
            resolveContact(c);
        }
    }
};

// -----------------------------
// Real-time loop with frame-rate constraints
// -----------------------------

int main() {
    PhysicsWorld world;

    // Dynamic box
    world.bodies.emplace_back(1.0f, Vec3(0.5f, 0.5f, 0.5f));
    world.bodies.back().position = {0.0f, 5.0f, 0.0f};
    world.bodies.back().velocity = {2.0f, 0.0f, 0.0f};

    // Simulation settings
    const float fixedDt = 1.0f / 120.0f;   // 120 Hz physics
    const float maxFrameTime = 0.25f;      // clamp long frames
    const int maxSubsteps = 8;             // avoid spiral of death

    float accumulator = 0.0f;
    float lastTime = 0.0f;

    // Replace this with your real timer/render loop.
    // Here we simulate a few seconds with a fake frame delta.
    for (int frame = 0; frame < 600; ++frame) {
        float frameDt = 1.0f / 60.0f; // pretend rendering at 60 FPS
        frameDt = std::min(frameDt, maxFrameTime);

        accumulator += frameDt;

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            ++substeps;
        }

        // If too much time accumulated, drop excess to maintain real-time responsiveness
        if (substeps == maxSubsteps) {
            accumulator = 0.0f;
        }

        // Output state
        const auto& b = world.bodies[0];
        std::cout << "Frame " << frame
                  << " pos=(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                  << " vel=(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
    }

    return 0;
}
```

---

## Key design points

### 1. Fixed timestep
Physics is updated using a constant `fixedDt` instead of the render frame delta. This makes simulation stable and deterministic across different frame rates.

### 2. Accumulator loop
The render loop accumulates elapsed time and runs as many physics substeps as needed:

```cpp
while (accumulator >= fixedDt) {
    world.step(fixedDt);
    accumulator -= fixedDt;
}
```

### 3. Frame-rate constraints
To avoid a “spiral of death” when the machine falls behind:

- clamp max frame time
- cap max substeps per frame
- optionally drop excess accumulated time

### 4. Semi-implicit Euler
This is better than plain Euler for real-time physics:

```cpp
velocity += acceleration * dt;
position += velocity * dt;
```

### 5. Rigid body extension
This example includes:
- linear velocity
- angular velocity
- quaternion orientation
- torque accumulation

For a full rigid body engine, you’d also need:
- world-space inertia tensor
- proper rotation of inertia tensor
- narrow-phase collision detection
- contact manifolds
- iterative constraint solver
- sleep states
- broad-phase acceleration structures

