// ---------------------------
// Basic math types
// ---------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
    Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    Vec3& operator-=(const Vec3& rhs) { x -= rhs.x; y -= rhs.y; z -= rhs.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline Vec3 cross(const Vec3& a, const Vec3& b) {
    return {
        a.y*b.z - a.z*b.y,
        a.z*b.x - a.x*b.z,
        a.x*b.y - a.y*b.x
    };
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-8f) return {0, 0, 0};
    return v / len;
}

// ---------------------------
// Quaternion for orientation
// ---------------------------
struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& rhs) const {
        return {
            w*rhs.w - x*rhs.x - y*rhs.y - z*rhs.z,
            w*rhs.x + x*rhs.w + y*rhs.z - z*rhs.y,
            w*rhs.y - x*rhs.z + y*rhs.w + z*rhs.x,
            w*rhs.z + x*rhs.y - y*rhs.x + z*rhs.w
        };
    }

    Quat operator*(float s) const { return {w*s, x*s, y*s, z*s}; }

    Quat& operator+=(const Quat& rhs) {
        w += rhs.w; x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }
};

static inline Quat normalize(const Quat& q) {
    float len = std::sqrt(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    if (len <= 1e-8f) return Quat();
    return {q.w/len, q.x/len, q.y/len, q.z/len};
}

// Angular velocity to quaternion derivative
static inline Quat quatDerivative(const Quat& q, const Vec3& omega) {
    Quat wq(0, omega.x, omega.y, omega.z);
    return q * wq * 0.5f;
}

// ---------------------------
// Rigid body
// ---------------------------
struct RigidBody {
    Vec3 position;
    Vec3 velocity;

    Quat orientation;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    // Simplified inertia tensor for a box in local space
    Vec3 localInertia;
    Vec3 invLocalInertia;

    float restitution = 0.4f;
    float friction = 0.5f;

    bool isStatic = false;

    RigidBody(float m, const Vec3& pos)
        : position(pos), velocity(), orientation(), angularVelocity(),
          forceAccum(), torqueAccum(), mass(m)
    {
        if (m <= 0.0f) {
            invMass = 0.0f;
            isStatic = true;
        } else {
            invMass = 1.0f / m;
        }
        localInertia = {1, 1, 1};
        invLocalInertia = {1, 1, 1};
    }

    void addForce(const Vec3& f) {
        if (!isStatic) forceAccum += f;
    }

    void addTorque(const Vec3& t) {
        if (!isStatic) torqueAccum += t;
    }

    void clearAccumulators() {
        forceAccum = {0,0,0};
        torqueAccum = {0,0,0};
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Linear motion
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        // Angular motion (simplified, assumes diagonal inertia in world approximation)
        Vec3 angularAccel = {
            torqueAccum.x * invLocalInertia.x,
            torqueAccum.y * invLocalInertia.y,
            torqueAccum.z * invLocalInertia.z
        };
        angularVelocity += angularAccel * dt;

        // Orientation update
        Quat dq = quatDerivative(orientation, angularVelocity);
        orientation += dq * dt;
        orientation = normalize(orientation);

        clearAccumulators();
    }
};

// ---------------------------
// Collision with ground plane y = 0
// ---------------------------
void resolveGroundCollision(RigidBody& body) {
    if (body.isStatic) return;

    // Simple sphere-like contact point using position.y as height
    if (body.position.y < 0.0f) {
        Vec3 normal = {0, 1, 0};

        // Positional correction
        body.position.y = 0.0f;

        // Relative velocity along normal
        float velAlongNormal = dot(body.velocity, normal);

        // Only resolve if moving into the plane
        if (velAlongNormal < 0.0f) {
            float e = body.restitution;
            float j = -(1.0f + e) * velAlongNormal;
            j /= body.invMass > 0.0f ? body.invMass : 1.0f;

            Vec3 impulse = normal * j;
            body.velocity += impulse * body.invMass;

            // Friction
            Vec3 tangent = body.velocity - normal * dot(body.velocity, normal);
            float tangentLen = length(tangent);
            if (tangentLen > 1e-6f) {
                tangent = tangent / tangentLen;
                float vt = dot(body.velocity, tangent);
                float frictionImpulseMag = -vt * body.friction;
                body.velocity += tangent * frictionImpulseMag;
            }
        }
    }
}

// ---------------------------
// Physics world
// ---------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0f, -9.81f, 0.0f};

    void step(float dt) {
        // Apply forces
        for (auto& b : bodies) {
            if (!b.isStatic) {
                b.addForce(gravity * b.mass);
            }
        }

        // Integrate
        for (auto& b : bodies) {
            b.integrate(dt);
        }

        // Collision resolution
        for (auto& b : bodies) {
            resolveGroundCollision(b);
        }
    }
};

// ---------------------------
// Real-time loop with fixed timestep
// ---------------------------
int main() {
    PhysicsWorld world;

    // Dynamic body
    world.bodies.emplace_back(1.0f, Vec3{0.0f, 10.0f, 0.0f});
    world.bodies.back().velocity = {2.0f, 0.0f, 0.0f};
    world.bodies.back().restitution = 0.6f;
    world.bodies.back().friction = 0.2f;

    // Static ground proxy (optional)
    world.bodies.emplace_back(0.0f, Vec3{0.0f, 0.0f, 0.0f});

    const float fixedDt = 1.0f / 120.0f;   // physics at 120 Hz
    const float maxFrameTime = 0.25f;       // prevent spiral of death
    float accumulator = 0.0f;

    auto lastTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> frameTime = now - lastTime;
        lastTime = now;

        float dt = std::min(frameTime.count(), maxFrameTime);
        accumulator += dt;

        // Run physics in fixed steps
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render/interpolate here in a real engine
