struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& v) const { return {x + v.x, y + v.y, z + v.z}; }
    Vec3 operator-(const Vec3& v) const { return {x - v.x, y - v.y, z - v.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& v) { x += v.x; y += v.y; z += v.z; return *this; }
    Vec3& operator-=(const Vec3& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline Vec3 cross(const Vec3& a, const Vec3& b) {
    return {
        a.y*b.z - a.z*b.y,
        a.z*b.x - a.x*b.z,
        a.x*b.y - a.y*b.x
    };
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len < 1e-8f) return {0, 0, 0};
    return v / len;
}

struct Quaternion {
    float w, x, y, z;

    Quaternion() : w(1), x(0), y(0), z(0) {}
    Quaternion(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quaternion operator+(const Quaternion& q) const {
        return {w + q.w, x + q.x, y + q.y, z + q.z};
    }

    Quaternion operator*(float s) const {
        return {w * s, x * s, y * s, z * s};
    }

    Quaternion operator*(const Quaternion& q) const {
        return {
            w*q.w - x*q.x - y*q.y - z*q.z,
            w*q.x + x*q.w + y*q.z - z*q.y,
            w*q.y - x*q.z + y*q.w + z*q.x,
            w*q.z + x*q.y - y*q.x + z*q.w
        };
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    static Quaternion fromAngularVelocity(const Vec3& omega) {
        return {0, omega.x, omega.y, omega.z};
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    Quaternion orientation;
    Vec3 angularVelocity;
    Vec3 torque;

    float mass;
    float invMass;
    float radius;

    float restitution;
    float friction;

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos), velocity(), force(),
          orientation(), angularVelocity(), torque(),
          mass(m), radius(r), restitution(0.6f), friction(0.4f)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }

    void applyForce(const Vec3& f) {
        force += f;
    }

    void applyImpulse(const Vec3& impulse) {
        velocity += impulse * invMass;
    }

    void integrate(float dt) {
        if (invMass == 0.0f) return;

        // Linear motion
        Vec3 acceleration = force * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        // Angular motion (simplified)
        Quaternion qdot = orientation * Quaternion::fromAngularVelocity(angularVelocity);
        orientation = orientation + qdot * (0.5f * dt);
        orientation.normalize();

        // Clear accumulators
        force = {0, 0, 0};
        torque = {0, 0, 0};
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0f, -9.81f, 0.0f};

    float groundY = 0.0f;

    void step(float dt) {
        // Apply gravity
        for (auto& b : bodies) {
            if (b.invMass > 0.0f) {
                b.applyForce(gravity * b.mass);
            }
        }

        // Integrate
        for (auto& b : bodies) {
            b.integrate(dt);
        }

        // Collisions
        solveSphereSphereCollisions();
        solveGroundCollisions();
    }

    void solveSphereSphereCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                Vec3 delta = b.position - a.position;
                float dist = length(delta);
                float penetration = (a.radius + b.radius) - dist;

                if (penetration > 0.0f) {
                    Vec3 normal = (dist > 1e-6f) ? (delta / dist) : Vec3{0, 1, 0};

                    // Positional correction
                    float totalInvMass = a.invMass + b.invMass;
                    if (totalInvMass > 0.0f) {
                        Vec3 correction = normal * (penetration / totalInvMass * 0.8f);
                        a.position -= correction * a.invMass;
                        b.position += correction * b.invMass;
                    }

                    // Relative velocity
                    Vec3 relVel = b.velocity - a.velocity;
                    float velAlongNormal = dot(relVel, normal);

                    // Only resolve if bodies are moving toward each other
                    if (velAlongNormal < 0.0f) {
                        float e = std::min(a.restitution, b.restitution);
                        float j = -(1.0f + e) * velAlongNormal;
                        j /= (a.invMass + b.invMass);

                        Vec3 impulse = normal * j;
                        a.velocity -= impulse * a.invMass;
                        b.velocity += impulse * b.invMass;
                    }
                }
            }
        }
    }

    void solveGroundCollisions() {
        for (auto& b : bodies) {
            float minY = groundY + b.radius;
            if (b.position.y < minY) {
                b.position.y = minY;

                if (b.velocity.y < 0.0f) {
                    b.velocity.y = -b.velocity.y * b.restitution;

                    // Simple friction
                    b.velocity.x *= (1.0f - b.friction * 0.1f);
                    b.velocity.z *= (1.0f - b.friction * 0.1f);
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    world.bodies.emplace_back(1.0f, 0.5f, Vec3{-1.0f, 5.0f, 0.0f});
    world.bodies.emplace_back(1.0f, 0.5f, Vec3{ 1.0f, 8.0f, 0.0f});
    world.bodies.emplace_back(2.0f, 0.75f, Vec3{ 0.0f, 12.0f, 0.0f});

    // Frame-rate constrained loop
    const float fixedDt = 1.0f / 120.0f;   // physics at 120 Hz
    const float maxFrameTime = 0.25f;      // avoid spiral of death
    const int targetFPS = 60;
    const auto frameDuration = std::chrono::milliseconds(1000 / targetFPS);

    double accumulator = 0.0;
    auto lastTime = std::chrono::high_resolution_clock::now();

    for (int frame = 0; frame < 600; ++frame) { // run for a while
        auto now = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> elapsed = now - lastTime;
        lastTime = now;

        double frameTime = std::min(elapsed.count(), (double)maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // "Render" placeholder: print body positions
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " pos=(" << b.position.x << ", "
                                   << b.position.y << ", "
                                   << b.position.z << ")\n";
        }

        // Frame-rate constraint / pacing
        std::this_thread::sleep_for(frameDuration);
    }

    return 0;
}
```

