## Single-file HTML example

Save this as `index.html` and open it in a browser:

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Minimal Rigid Body Physics</title>
  <style>
    html, body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
<canvas id="c"></canvas>
<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// ----------------------------
// Physics constants
// ----------------------------
const FIXED_DT = 1 / 60;      // physics step (60 Hz)
const MAX_FRAME_DT = 0.25;    // clamp huge frame spikes
const GRAVITY = 1200;         // px/s^2
const RESTITUTION = 0.4;      // bounciness
const FRICTION = 0.8;

// ----------------------------
// Rigid body definition
// ----------------------------
class Body {
  constructor(x, y, w, h, mass = 1) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.angularVelocity = 0;
    this.mass = mass;
    this.invMass = mass > 0 ? 1 / mass : 0;
    this.isStatic = mass === 0;
  }

  integrate(dt) {
    if (this.isStatic) return;

    // Gravity
    this.vy += GRAVITY * dt;

    // Integrate position
    this.x += this.vx * dt;
    this.y += this.vy * dt;

    // Integrate rotation (kept minimal; not used in collision response here)
    this.angle += this.angularVelocity * dt;
  }
}

// ----------------------------
// World setup
// ----------------------------
const bodies = [];

// Ground as a static body
const ground = new Body(0, canvas.height - 50, canvas.width, 50, 0);
bodies.push(ground);

// Some dynamic boxes
for (let i = 0; i < 8; i++) {
  const b = new Body(100 + i * 60, 50 + i * 10, 40, 40, 1);
  b.vx = (Math.random() - 0.5) * 100;
  bodies.push(b);
}

// ----------------------------
// Collision resolution
// ----------------------------
function resolveGroundCollision(body, ground) {
  if (body.isStatic) return;

  const bodyBottom = body.y + body.h;
  const groundTop = ground.y;

  if (bodyBottom > groundTop) {
    // Push body out of the ground
    body.y = groundTop - body.h;

    // Bounce
    if (body.vy > 0) {
      body.vy = -body.vy * RESTITUTION;

      // Simple friction on impact
      body.vx *= FRICTION;

      // Stop tiny jitter
      if (Math.abs(body.vy) < 20) body.vy = 0;
      if (Math.abs(body.vx) < 5) body.vx = 0;
    }
  }
}

// ----------------------------
// Physics step
// ----------------------------
function stepPhysics(dt) {
  for (const body of bodies) {
    body.integrate(dt);
  }

  // Ground collision only for minimal demo
  for (const body of bodies) {
    resolveGroundCollision(body, ground);
  }
}

// ----------------------------
// Render
// ----------------------------
function drawBody(body, color = "#4af") {
  ctx.save();
  ctx.translate(body.x + body.w / 2, body.y + body.h / 2);
  ctx.rotate(body.angle);
  ctx.fillStyle = color;
  ctx.fillRect(-body.w / 2, -body.h / 2, body.w, body.h);
  ctx.restore();
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Ground
  ctx.fillStyle = "#444";
  ctx.fillRect(ground.x, ground.y, ground.w, ground.h);

  // Bodies
  for (let i = 1; i < bodies.length; i++) {
    drawBody(bodies[i]);
  }
}

// ----------------------------
// Main loop with fixed timestep
// ----------------------------
let lastTime = performance.now();
let accumulator = 0;

function loop(now) {
  let frameDt = (now - lastTime) / 1000;
  lastTime = now;

  // Frame-rate constraint handling
  frameDt = Math.min(frameDt, MAX_FRAME_DT);
  accumulator += frameDt;

  // Fixed physics updates
  while (accumulator >= FIXED_DT) {
    stepPhysics(FIXED_DT);
    accumulator -= FIXED_DT;
  }

  render();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
</body>
</html>
```

