## 8) Corporate system adapter: `src/infrastructure/corporate/corporateClient.ts`

```ts
import axios, { AxiosInstance } from "axios";
import { CorporateIntegrationError } from "../../domain/errors.js";

export interface CorporateEmployeeRecord {
  corporateId: string;
  status: "ACTIVE" | "INACTIVE";
  departmentCode: string;
}

export interface CorporateClient {
  getEmployeeRecord(corporateId: string): Promise<CorporateEmployeeRecord>;
}

export class HttpCorporateClient implements CorporateClient {
  private readonly client: AxiosInstance;

  constructor(baseURL: string, token: string) {
    this.client = axios.create({
      baseURL,
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      timeout: 5000
    });
  }

  async getEmployeeRecord(corporateId: string): Promise<CorporateEmployeeRecord> {
    try {
      const response = await this.client.get(`/employees/${encodeURIComponent(corporateId)}`);
      const data = response.data as CorporateEmployeeRecord;

      if (!data?.corporateId || !data?.status || !data?.departmentCode) {
        throw new CorporateIntegrationError("Invalid corporate response shape");
      }

      return data;
    } catch (error) {
      throw new CorporateIntegrationError(
        error instanceof Error ? `Corporate lookup failed: ${error.message}` : "Corporate lookup failed"
      );
    }
  }
}
```

