## 10) Application service: `src/application/userService.ts`

```ts
import { randomUUID } from "node:crypto";
import { CorporateClient } from "../infrastructure/corporate/corporateClient.js";
import { UserRepository } from "../infrastructure/persistence/userRepository.js";
import { CreateUserInput, User } from "../domain/types.js";
import { err, ok, Result } from "../shared/result.js";
import { CorporateIntegrationError, ValidationError } from "../domain/errors.js";

export type CreateUserError =
  | { type: "VALIDATION_ERROR"; message: string }
  | { type: "CONFLICT"; message: string }
  | { type: "CORPORATE_ERROR"; message: string };

export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly corporateClient: CorporateClient
  ) {}

  async createUser(input: CreateUserInput): Promise<Result<User, CreateUserError>> {
    if (!input.email.includes("@")) {
      return err({ type: "VALIDATION_ERROR", message: "Invalid email address" });
    }

    const existing = await this.userRepository.findByEmail(input.email);
    if (existing) {
      return err({ type: "CONFLICT", message: "User already exists" });
    }

    let corporateRecord;
    try {
      corporateRecord = await this.corporateClient.getEmployeeRecord(input.corporateId);
    } catch (e) {
      const message = e instanceof Error ? e.message : "Unknown corporate error";
      return err({ type: "CORPORATE_ERROR", message });
    }

    if (corporateRecord.status !== "ACTIVE") {
      return err({ type: "VALIDATION_ERROR", message: "Employee is not active in corporate system" });
    }

    const now = new Date().toISOString();
    const user: User = {
      id: randomUUID(),
      email: input.email.toLowerCase(),
      fullName: input.fullName,
      corporateId: input.corporateId,
      createdAt: now,
      updatedAt: now
    };

    const saved = await this.userRepository.save(user);
    return ok(saved);
  }
}
```

