## 12) HTTP handlers: `src/interfaces/http/handlers.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { UserService } from "../../application/userService.js";
import { CreateUserRequestSchema } from "./schemas.js";

export function createUserHandler(userService: UserService) {
  return async function handler(
    request: FastifyRequest,
    reply: FastifyReply
  ) {
    const parsed = CreateUserRequestSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        details: parsed.error.flatten()
      });
    }

    const result = await userService.createUser(parsed.data);

    if (!result.ok) {
      switch (result.error.type) {
        case "VALIDATION_ERROR":
          return reply.status(400).send({ error: result.error.type, message: result.error.message });
        case "CONFLICT":
          return reply.status(409).send({ error: result.error.type, message: result.error.message });
        case "CORPORATE_ERROR":
          return reply.status(502).send({ error: result.error.type, message: result.error.message });
      }
    }

    return reply.status(201).send(result.value);
  };
}
```

