import Fastify from "fastify";
import { logger } from "./shared/logger.js";
import { registerRoutes } from "./interfaces/http/routes.js";
import { UserService } from "./application/userService.js";
import { InMemoryUserRepository } from "./infrastructure/persistence/userRepository.js";
import { HttpCorporateClient } from "./infrastructure/corporate/corporateClient.js";
import { loadEnv } from "./config/env.js";

export function buildApp() {
  const env = loadEnv();

  const app = Fastify({ logger });

  const userRepository = new InMemoryUserRepository();
  const corporateClient = new HttpCorporateClient(
    env.CORPORATE_API_BASE_URL,
    env.CORPORATE_API_TOKEN
  );
  const userService = new UserService(userRepository, corporateClient);

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Unhandled error");
    reply.status(500).send({ error: "INTERNAL_SERVER_ERROR" });
  });

  void registerRoutes(app, userService);

  return app;
}
