## `src/infrastructure/customerRepository.ts`

```ts
import { PrismaClient } from "@prisma/client";
import type { Customer } from "../domain/customer.js";

export class CustomerRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async findById(id: string): Promise<Customer | null> {
    const row = await this.prisma.customer.findUnique({ where: { id } });
    return row
      ? {
          id: row.id,
          firstName: row.firstName,
          lastName: row.lastName,
          email: row.email,
          crmStatus: row.crmStatus as Customer["crmStatus"]
        }
      : null;
  }

  async upsert(customer: Customer): Promise<Customer> {
    const row = await this.prisma.customer.upsert({
      where: { id: customer.id },
      create: {
        id: customer.id,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        crmStatus: customer.crmStatus
      },
      update: {
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        crmStatus: customer.crmStatus
      }
    });

    return {
      id: row.id,
      firstName: row.firstName,
      lastName: row.lastName,
      email: row.email,
      crmStatus: row.crmStatus as Customer["crmStatus"]
    };
  }
}
