## `src/infrastructure/crmClient.ts`

```ts
import axios, { AxiosInstance } from "axios";
import { z } from "zod";
import { CustomerSchema, type CustomerId } from "../domain/customer.js";
import { ExternalServiceError } from "../utils/errors.js";

const CrmCustomerResponseSchema = CustomerSchema;

export class CrmClient {
  private readonly client: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.client = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      }
    });
  }

  async fetchCustomer(id: CustomerId) {
    try {
      const response = await this.client.get(`/customers/${encodeURIComponent(id)}`);
      return CrmCustomerResponseSchema.parse(response.data);
    } catch (error) {
      if (axios.isAxiosError(error)) {
        throw new ExternalServiceError(
          `CRM request failed: ${error.message}`,
          error.response?.status
        );
      }
      if (error instanceof z.ZodError) {
        throw new ExternalServiceError(`CRM returned invalid payload: ${error.message}`);
      }
      throw error;
    }
  }
}
```

