## `src/services/customerService.ts`

```ts
import type { CustomerId } from "../domain/customer.js";
import { NotFoundError } from "../utils/errors.js";
import type { CustomerRepository } from "../infrastructure/customerRepository.js";
import type { CrmClient } from "../infrastructure/crmClient.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CrmClient
  ) {}

  async getCustomer(id: CustomerId) {
    const cached = await this.repository.findById(id);
    if (cached) return cached;

    const fromCrm = await this.crmClient.fetchCustomer(id);
    return this.repository.upsert(fromCrm);
  }

  async getCustomerOrThrow(id: CustomerId) {
    try {
      return await this.getCustomer(id);
    } catch (error) {
      if (error instanceof NotFoundError) {
        throw error;
      }
      throw error;
    }
  }
}
```

