## `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerIdSchema, CustomerSchema } from "../domain/customer.js";
import { ExternalServiceError, NotFoundError } from "../utils/errors.js";
import type { CustomerService } from "../services/customerService.js";

const ParamsSchema = z.object({
  id: CustomerIdSchema
});

export async function customerRoutes(
  app: FastifyInstance,
  service: CustomerService
) {
  app.get("/customers/:id", async (request, reply) => {
    const params = ParamsSchema.parse(request.params);

    try {
      const customer = await service.getCustomer(params.id);
      return reply.send(CustomerSchema.parse(customer));
    } catch (error) {
      if (error instanceof NotFoundError) {
        return reply.status(404).send({ error: "Customer not found" });
      }
      if (error instanceof ExternalServiceError) {
        return reply.status(502).send({
          error: "Upstream CRM unavailable",
          details: error.message
        });
      }
      throw error;
    }
  });
}
```

