## `src/app.ts`

```ts
import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import { env } from "./config/env.js";
import { logger } from "./infrastructure/logger.js";
import { CustomerRepository } from "./infrastructure/customerRepository.js";
import { CrmClient } from "./infrastructure/crmClient.js";
import { CustomerService } from "./services/customerService.js";
import { customerRoutes } from "./routes/customerRoutes.js";
import { healthRoutes } from "./routes/healthRoutes.js";

export async function buildApp() {
  const app = Fastify({ logger });

  const prisma = new PrismaClient();
  const repository = new CustomerRepository(prisma);
  const crmClient = new CrmClient(env.CRM_BASE_URL, env.CRM_API_KEY);
  const customerService = new CustomerService(repository, crmClient);

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await customerRoutes(instance, customerService);
  });

  app.setErrorHandler((error, _, reply) => {
    app.log.error({ err: error }, "Unhandled error");
    return reply.status(500).send({ error: "Internal Server Error" });
  });

  return app;
}
```

