## Corporate client service

### src/modules/corporate/corporate-client.service.ts

```ts
import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { DomainError } from '@/common/errors/domain-error';
import type { CorporateCustomerDto } from './dto/corporate-customer.dto';

@Injectable()
export class CorporateClientService {
  private readonly logger = new Logger(CorporateClientService.name);

  constructor(private readonly http: HttpService) {}

  async fetchCustomerByExternalId(externalId: string): Promise<CorporateCustomerDto> {
    try {
      const response = await firstValueFrom(
        this.http.get<CorporateCustomerDto>(`/customers/${encodeURIComponent(externalId)}`)
      );

      return response.data;
    } catch (error) {
      this.logger.error(`Failed to fetch customer ${externalId}`, error as Error);
      throw new DomainError('Failed to retrieve customer from corporate system', 'CORPORATE_FETCH_FAILED', 502);
    }
  }

  async createOrUpdateCustomer(payload: CorporateCustomerDto): Promise<CorporateCustomerDto> {
    try {
      const response = await firstValueFrom(
        this.http.put<CorporateCustomerDto>(`/customers/${encodeURIComponent(payload.externalId)}`, payload)
      );

      return response.data;
    } catch (error) {
      this.logger.error(`Failed to upsert customer ${payload.externalId}`, error as Error);
      throw new DomainError('Failed to sync customer to corporate system', 'CORPORATE_SYNC_FAILED', 502);
    }
  }
}
```

