## Customer service

### src/modules/customer/customer.service.ts

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { CorporateClientService } from '@/modules/corporate/corporate-client.service';
import { DomainError } from '@/common/errors/domain-error';
import { Ok, Err, type Result } from '@/common/types/result';
import type { Customer } from './models/customer.model';
import type { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomerService {
  constructor(private readonly corporateClient: CorporateClientService) {}

  async createCustomer(dto: CreateCustomerDto): Promise<Result<Customer, 'VALIDATION_ERROR' | 'SYNC_FAILED'>> {
    if (!dto.externalId.trim()) {
      return Err('VALIDATION_ERROR');
    }

    const now = new Date().toISOString();

    const customer: Customer = {
      id: randomUUID(),
      externalId: dto.externalId,
      fullName: dto.fullName,
      email: dto.email,
      active: true,
      createdAt: now,
      updatedAt: now
    };

    try {
      await this.corporateClient.createOrUpdateCustomer({
        externalId: customer.externalId,
        fullName: customer.fullName,
        emailAddress: customer.email,
        status: 'ACTIVE'
      });

      return Ok(customer);
    } catch (error) {
      if (error instanceof DomainError) {
        return Err('SYNC_FAILED');
      }
      return Err('SYNC_FAILED');
    }
  }
}
```

