import { randomUUID } from "node:crypto";
import type { CorporateClient } from "../../integrations/corporateClient.js";
import type { CreateCustomerRequest, Customer } from "./customer.types.js";

export class CustomerService {
  constructor(private readonly corporateClient: CorporateClient) {}

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const existing = await this.corporateClient.getEmployeeByEmail(input.email);

    if (!existing) {
      throw new Error("Customer email is not registered in corporate directory");
    }

    return {
      id: randomUUID(),
      email: input.email,
      fullName: input.fullName,
      department: input.department,
      createdAt: new Date().toISOString()
    };
