## `src/modules/customer/customer.routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { CreateCustomerSchema } from "./customer.types.js";
import type { CustomerService } from "./customer.service.js";

export async function customerRoutes(
  app: FastifyInstance,
  service: CustomerService
): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    try {
      const customer = await service.createCustomer(parsed.data);
      return reply.status(201).send(customer);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Unknown error";
      if (message.includes("not registered")) {
        return reply.status(409).send({ error: message });
      }
      request.log.error({ err }, "Failed to create customer");
      return reply.status(500).send({ error: "Internal server error" });
    }
  });
}
```

