export async function buildApp() {
  const env = loadEnv();

  const app = Fastify({
    logger: true
  });

  await app.register(loggerPlugin);

  app.get("/health", async () => ({
    status: "ok",
    timestamp: new Date().toISOString()
  }));

  const corporateClient = new CorporateClient(env);
  const customerService = new CustomerService(corporateClient);

  await customerRoutes(app, customerService);

  return app;
}
