Example in-memory implementation for tests/dev:

```ts
// src/modules/employee/employee.repository.memory.ts
import { randomUUID } from 'crypto';
import type { EmployeeRepository } from './employee.repository';
import type { Employee, EmployeeId } from './employee.types';

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly items = new Map<string, Employee>();

  async create(employee: Omit<Employee, 'createdAt'> & { createdAt?: Date }): Promise<Employee> {
    const created: Employee = {
      ...employee,
      id: (employee.id ?? randomUUID()) as EmployeeId,
      createdAt: employee.createdAt ?? new Date(),
    };
    this.items.set(created.id, created);
    return created;
  }

  async findByEmail(email: string): Promise<Employee | null> {
    for (const item of this.items.values()) {
      if (item.email === email) return item;
    }
    return null;
  }

  async findById(id: EmployeeId): Promise<Employee | null> {
    return this.items.get(id) ?? null;
  }
}
```

