# 6) Service layer

```ts
// src/modules/employee/employee.service.ts
import { randomUUID } from 'crypto';
import { AppError } from '../../common/errors/app-error';
import type { EmployeeRepository } from './employee.repository';
import type { Employee } from './employee.types';
import type { CreateEmployeeInput } from './employee.schema';
import type { HRSystemClient } from '../../integrations/hr-system/hr-system.client';

export class EmployeeService {
  constructor(
    private readonly repo: EmployeeRepository,
    private readonly hrClient: HRSystemClient,
  ) {}

  async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const existing = await this.repo.findByEmail(input.email);
    if (existing) {
      throw new AppError('EMPLOYEE_ALREADY_EXISTS', 'Employee already exists', 409, {
        email: input.email,
      });
    }

    const employee: Employee = {
      id: randomUUID() as Employee['id'],
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      departmentCode: input.departmentCode,
      createdAt: new Date(),
    };

    const saved = await this.repo.create(employee);

    try {
      await this.hrClient.syncEmployee({
        employeeId: saved.id,
        firstName: saved.firstName,
        lastName: saved.lastName,
        email: saved.email,
        departmentCode: saved.departmentCode,
      });
    } catch (err) {
      // Depending on business rules, you may want to:
      // - fail the request
      // - queue a retry
      // - mark the record as pending sync
      throw new AppError('HR_SYNC_FAILED', 'Employee created but HR sync failed', 502, {
        cause: err,
      });
    }

    return saved;
  }

  async getEmployee(id: string): Promise<Employee> {
    const employee = await this.repo.findById(id as Employee['id']);
    if (!employee) {
      throw new AppError('EMPLOYEE_NOT_FOUND', 'Employee not found', 404, { id });
    }
    return employee;
  }
}
```

