```ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CorporateErpClient } from '../integrations/corporate-erp/corporate-erp.client';
import { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly erpClient: CorporateErpClient
  ) {}

  async createCustomer(dto: CreateCustomerDto) {
    const erpResult = await this.erpClient.createCustomer({
      name: dto.name,
      email: dto.email
    });

    const customer = await this.prisma.customer.create({
      data: {
        name: dto.name,
        email: dto.email,
        externalId: erpResult.externalId
      }
    });

    return {
      id: customer.id,
      name: customer.name,
      email: customer.email,
      externalId: customer.externalId
    };
  }

  async getCustomerById(id: string) {
    return this.prisma.customer.findUnique({
      where: { id }
    });
  }
}
