## 9) Typed corporate client: `src/integrations/corporate-system.client.ts`

```ts
import axios, { AxiosInstance } from 'axios';
import { Injectable, Logger } from '@nestjs/common';
import type { CorporateEmployeeRecord, CorporateSyncResponse } from './corporate-system.types';
import { DomainError } from '../common/errors/domain-error';

@Injectable()
export class CorporateSystemClient {
  private readonly logger = new Logger(CorporateSystemClient.name);
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: process.env.CORPORATE_API_BASE_URL,
      timeout: 10_000,
      headers: {
        Authorization: `Bearer ${process.env.CORPORATE_API_TOKEN}`,
        'Content-Type': 'application/json'
      }
    });
  }

  async syncEmployee(record: CorporateEmployeeRecord): Promise<CorporateSyncResponse> {
    try {
      const response = await this.http.post<CorporateSyncResponse>('/employees/sync', record);
      return response.data;
    } catch (error) {
      this.logger.error(`Corporate sync failed for employeeId=${record.employeeId}`, error as Error);

      throw new DomainError(
        'Failed to sync employee with corporate system',
        'CORPORATE_SYNC_FAILED',
        {
          employeeId: record.employeeId
        }
      );
    }
  }
}
```

