## 13) Service layer: `src/employees/employees.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { EmployeesRepository } from './employees.repository';
import type { Employee } from './employees.types';
import { CorporateSystemClient } from '../integrations/corporate-system.client';
import { DomainError } from '../common/errors/domain-error';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly repository: EmployeesRepository,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async syncEmployee(employee: Employee): Promise<{ employee: Employee; correlationId: string }> {
    const saved = await this.repository.upsert(employee);

    const corporateResponse = await this.corporateClient.syncEmployee({
      employeeId: saved.employeeId,
      firstName: saved.firstName,
      lastName: saved.lastName,
      email: saved.email,
      departmentCode: saved.departmentCode,
      active: saved.active
    });

    if (!corporateResponse.success) {
      throw new DomainError(
        'Corporate system rejected employee sync',
        'CORPORATE_REJECTED_SYNC',
        {
          employeeId: saved.employeeId,
          message: corporateResponse.message
        }
      );
    }

    return {
      employee: saved,
      correlationId: corporateResponse.correlationId
    };
  }
}
```

