```ts
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { CorporateCrmCreateCustomerRequest, CorporateCrmCreateCustomerResponse } from './corporate-crm.types';

@Injectable()
export class CorporateCrmClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      timeout: 5000
    });
  }

  async createCustomer(
    baseUrl: string,
    apiKey: string,
    payload: CorporateCrmCreateCustomerRequest
  ): Promise<CorporateCrmCreateCustomerResponse> {
    try {
      const response = await this.http.post<CorporateCrmCreateCustomerResponse>(
        `${baseUrl}/customers`,
        payload,
        {
          headers: {
            Authorization: `Bearer ${apiKey}`,
            'Content-Type': 'application/json'
          }
        }
      );

      if (!response.data?.referenceId) {
        throw new Error('Invalid CRM response: missing referenceId');
      }

      return response.data;
    } catch (error) {
      throw new HttpException(
        `Failed to create customer in corporate CRM`,
        HttpStatus.BAD_GATEWAY
      );
    }
  }
}
```

