## Service

### `src/modules/customer/customer.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { ConfigService } from '@nestjs/config';
import { AppConfig } from '../../config/configuration';
import { CorporateCrmClient } from '../../integrations/corporate-crm/corporate-crm.client';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerRecord, CustomerRepository } from './customer.repository';
import { CustomerResponseDto } from './dto/customer-response.dto';

@Injectable()
export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient,
    private readonly configService: ConfigService<AppConfig, true>
  ) {}

  async createCustomer(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const id = randomUUID();

    const config = this.configService.getOrThrow('corporateCrmBaseUrl');
    const apiKey = this.configService.getOrThrow('corporateCrmApiKey');

    const crmResult = await this.crmClient.createCustomer(config, apiKey, {
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email
    });

    const record: CustomerRecord = {
      id,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      crmReferenceId: crmResult.referenceId
    };

    await this.repository.save(record);

    return record;
  }

  async getCustomer(id: string): Promise<CustomerResponseDto | null> {
    return this.repository.findById(id);
  }
}
```

