    this.http = axios.create({
      baseURL: config.ERP_BASE_URL,
      timeout: 5000,
      headers: {
        "X-API-Key": config.ERP_API_KEY,
        "Content-Type": "application/json"
      }
    });
  }

  async getCustomerByExternalId(externalId: string): Promise<ErpCustomerRecord | null> {
    try {
