import { randomUUID } from "crypto";
import { Customer } from "./customer.types";

export class CustomerRepository {
  private readonly store = new Map<string, Customer>();

  async save(customer: Omit<Customer, "id" | "createdAt">): Promise<Customer> {
    const record: Customer = {
      id: randomUUID(),
      createdAt: new Date().toISOString(),
      ...customer
    };

    this.store.set(record.id, record);
    return record;
  }

  async findByExternalId(externalId: string): Promise<Customer | null> {
    for (const customer of this.store.values()) {
      if (customer.externalId === externalId) return customer;
    }
    return null;
  }
}
