## `src/modules/customer/customer.service.ts`

```ts
import { Injectable } from "@nestjs/common";
import { DomainError } from "../../common/errors";
import { ErpClient } from "../../integrations/erp/erp.client";
import { CreateCustomerInput } from "./customer.schema";
import { CustomerRepository } from "./customer.client";
import { Customer } from "./customer.types";

@Injectable()
export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly erpClient: ErpClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repo.findByExternalId(input.externalId);
    if (existing) {
      throw new DomainError("Customer already exists", "CUSTOMER_EXISTS", 409);
    }

    const erpRecord = await this.erpClient.getCustomerByExternalId(input.externalId);
    if (!erpRecord) {
      throw new DomainError("Customer not found in ERP", "ERP_CUSTOMER_NOT_FOUND", 404);
    }

    return this.repo.save({
      externalId: input.externalId,
      name: input.name
    });
  }
}
```

