## 12) Service layer

### `src/employees/employees.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../common/errors/domain-error';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { EmployeeResponseDto } from './dto/employee-response.dto';
import { EmployeesRepository } from './employees.repository';
import { Employee } from './employees.types';
import { CorporateHrClient } from './integrations/corporate-hr.types';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly repository: EmployeesRepository,
    private readonly corporateHrClient: CorporateHrClient
  ) {}

  async create(dto: CreateEmployeeDto): Promise<EmployeeResponseDto> {
    const existing = await this.repository.findByEmail(dto.email);
    if (existing !== null) {
      throw new DomainError(
        'EMPLOYEE_ALREADY_EXISTS',
        `Employee with email ${dto.email} already exists`,
        409
      );
    }

    const employee: Employee = {
      id: randomUUID(),
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      departmentCode: dto.departmentCode,
      createdAt: new Date()
    };

    const saved = await this.repository.save(employee);

    await this.corporateHrClient.syncEmployee({
      employeeId: saved.id,
      fullName: `${saved.firstName} ${saved.lastName}`,
      email: saved.email,
      departmentCode: saved.departmentCode
    });

    return {
      id: saved.id,
      firstName: saved.firstName,
      lastName: saved.lastName,
      email: saved.email,
      departmentCode: saved.departmentCode,
      createdAt: saved.createdAt.toISOString()
    };
  }
}
```

