import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CorpSystemClient } from '../integrations/corp-system/corp-system.client';
import { CreateEmployeeDto } from './dto/create-employee.dto';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly corpSystemClient: CorpSystemClient
  ) {}

  async create(dto: CreateEmployeeDto) {
    const existing = await this.prisma.employee.findFirst({
      where: {
        OR: [{ employeeNo: dto.employeeNo }, { email: dto.email }]
      }
    });

    if (existing) {
      throw new ConflictException('Employee already exists');
    }

    const employee = await this.prisma.employee.create({
      data: dto
    });

    await this.corpSystemClient.syncEmployee({
      employeeNo: employee.employeeNo,
      fullName: `${employee.firstName} ${employee.lastName}`,
      email: employee.email
    });

    return employee;
  }

  async findById(id: string) {
    const employee = await this.prisma.employee.findUnique({ where: { id } });
    if (!employee) {
      throw new NotFoundException('Employee not found');
    }
    return employee;
  }
}
