import axios, { type AxiosInstance } from 'axios';
import { Injectable } from '@nestjs/common';
import { DomainError } from '../../common/errors/domain-error';
import type {
  CrmCreateCustomerRequest,
  CrmCreateCustomerResponse
} from './crm.types';

@Injectable()
export class CrmClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.CRM_BASE_URL,
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': process.env.CRM_API_KEY
      }
    });
  }

  async createCustomer(
    input: CrmCreateCustomerRequest
  ): Promise<CrmCreateCustomerResponse> {
    try {
      const res = await this.client.post<CrmCreateCustomerResponse>('/customers', input);
      if (!res.data.externalCustomerId) {
        throw new DomainError('CRM response missing externalCustomerId', 'CRM_INVALID_RESPONSE', 502);
      }
      return res.data;
    } catch (err) {
      throw new DomainError('Failed to create customer in CRM', 'CRM_CREATE_FAILED', 502);
    }
  }
}
