# 9) Repository implementation

## `src/customers/infrastructure/customer.repository.memory.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CustomerEntity } from '../domain/customer.entity';
import type { CustomerRepository } from '../domain/customer.repository';

@Injectable()
export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly items = new Map<string, CustomerEntity>();

  async save(customer: CustomerEntity): Promise<CustomerEntity> {
    this.items.set(customer.id, customer);
    return customer;
  }

  async findById(id: string): Promise<CustomerEntity | null> {
    return this.items.get(id) ?? null;
  }

  async findByEmail(email: string): Promise<CustomerEntity | null> {
    for (const customer of this.items.values()) {
      if (customer.email.toLowerCase() === email.toLowerCase()) {
        return customer;
      }
    }
    return null;
  }
}
