# 10) Service layer

## `src/customers/customers.service.ts`

```ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../common/errors/domain-error';
import { AppLogger } from '../common/logging/logger.service';
import { CrmClient } from '../integrations/crm/crm.client';
import { CustomerEntity } from './domain/customer.entity';
import {
  CUSTOMER_REPOSITORY,
  type CustomerRepository
} from './domain/customer.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomersService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY) private readonly repo: CustomerRepository,
    private readonly crmClient: CrmClient,
    private readonly logger: AppLogger
  ) {}

  async createCustomer(dto: CreateCustomerDto): Promise<CustomerEntity> {
    const existing = await this.repo.findByEmail(dto.email);
    if (existing) {
      throw new DomainError('Customer already exists', 'CUSTOMER_ALREADY_EXISTS', 409);
    }

    const customer = CustomerEntity.create({
      id: randomUUID(),
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email.toLowerCase(),
      status: 'ACTIVE'
    });

    const crmResult = await this.crmClient.createCustomer({
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      phoneNumber: dto.phoneNumber
    });

    const saved = await this.repo.save(customer.withExternalId(crmResult.externalCustomerId));

    this.logger.log(`Customer created: ${saved.id}`, CustomersService.name);
    return saved;
  }

  async getCustomer(id: string): Promise<CustomerEntity> {
    const customer = await this.repo.findById(id);
    if (!customer) {
      throw new DomainError('Customer not found', 'CUSTOMER_NOT_FOUND', 404);
    }
    return customer;
  }
}
```

