## 9) Corporate CRM integration client

### `src/customers/integrations/crm.client.ts`

```ts
import axios, { AxiosInstance } from "axios";
import { ExternalSystemError } from "../../common/errors";

export interface CrmCreateCustomerRequest {
  firstName: string;
  lastName: string;
  email: string;
}

export interface CrmCreateCustomerResponse {
  crmId: string;
}

export class CrmClient {
  private readonly client: AxiosInstance;

  constructor(
    baseURL: string,
    apiKey: string
  ) {
    this.client = axios.create({
      baseURL,
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      },
      timeout: 5000
    });
  }

  async createCustomer(
    payload: CrmCreateCustomerRequest
  ): Promise<CrmCreateCustomerResponse> {
    try {
      const response = await this.client.post<CrmCreateCustomerResponse>(
        "/customers",
        payload
      );

      return response.data;
    } catch (err: unknown) {
      if (axios.isAxiosError(err)) {
        throw new ExternalSystemError(
          `CRM request failed: ${err.message}`,
          "CRM",
          err.response?.status
        );
      }
      throw new ExternalSystemError("Unknown CRM error", "CRM");
    }
  }
}
```

