## 10) Service layer

### `src/customers/customers.service.ts`

```ts
import { Injectable } from "@nestjs/common";
import { randomUUID } from "crypto";
import { DomainError } from "../common/errors";
import { Logger } from "../common/logger";
import { Customer } from "./domain/customer";
import { CreateCustomerDto } from "./dto/create-customer.dto";
import { CrmClient } from "./integrations/crm.client";
import { CustomerRepository } from "./repository/customer.repository";

@Injectable()
export class CustomersService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CrmClient,
    private readonly logger: Logger
  ) {}

  async createCustomer(dto: CreateCustomerDto): Promise<Customer> {
    const existing = await this.repository.findByEmail(dto.email);
    if (existing) {
      throw new DomainError("Customer already exists", "CUSTOMER_EXISTS");
    }

    const createdAt = new Date();
    const customer: Customer = {
      id: randomUUID(),
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email.toLowerCase(),
      createdAt
    };

    const crmResult = await this.crmClient.createCustomer({
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email
    });

    const enrichedCustomer: Customer = {
      ...customer,
      externalCrmId: crmResult.crmId
    };

    const saved = await this.repository.save(enrichedCustomer);

    this.logger.info("Customer created", {
      customerId: saved.id,
      crmId: saved.externalCrmId
    });

    return saved;
  }
}
```

