## 12) Module wiring

### `src/customers/customers.module.ts`

```ts
import { Module } from "@nestjs/common";
import { ConsoleLogger } from "../common/logger";
import { CustomersController } from "./customers.controller";
import { CustomersService } from "./customers.service";
import { CrmClient } from "./integrations/crm.client";
import { InMemoryCustomerRepository } from "./repository/in-memory-customer.repository";

@Module({
  controllers: [CustomersController],
  providers: [
    {
      provide: "CustomerRepository",
      useClass: InMemoryCustomerRepository
    },
    {
      provide: "Logger",
      useClass: ConsoleLogger
    },
    {
      provide: "CrmClient",
      useFactory: () => {
        const baseURL = process.env.CRM_BASE_URL;
        const apiKey = process.env.CRM_API_KEY;

        if (!baseURL || !apiKey) {
          throw new Error("Missing CRM_BASE_URL or CRM_API_KEY");
        }

        return new CrmClient(baseURL, apiKey);
      }
    },
    {
      provide: CustomersService,
      useFactory: (repo: InMemoryCustomerRepository, crm: CrmClient, logger: ConsoleLogger) =>
        new CustomersService(repo, crm, logger),
      inject: ["CustomerRepository", "CrmClient", "Logger"]
    }
  ],
  exports: [CustomersService]
})
export class CustomersModule {}
```

