import axios, { AxiosInstance } from "axios";
import type { Env } from "../config/env.js";
import type { Customer, CreateCustomerInput } from "../types/customer.js";

export class CorporateClient {
  private readonly client: AxiosInstance;

  constructor(env: Env) {
    this.client = axios.create({
      baseURL: env.CORPORATE_API_BASE_URL,
      timeout: env.REQUEST_TIMEOUT_MS,
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const response = await this.client.post("/customers", input);
    return response.data as Customer;
  }

  async getCustomerById(id: string): Promise<Customer | null> {
    try {
      const response = await this.client.get(`/customers/${id}`);
      return response.data as Customer;
    } catch (err: unknown) {
      if (axios.isAxiosError(err) && err.response?.status === 404) {
        return null;
      }
      throw err;
    }
  }
}
