## `src/routes/customers.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerSchema, CreateCustomerInputSchema } from "../types/customer.js";
import type { CustomerService } from "../services/customerService.js";

const ParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  const { customerService } = deps;

  app.post(
    "/customers",
    {
      schema: {
        body: {
          type: "object",
          required: ["firstName", "lastName", "email"],
          properties: {
            firstName: { type: "string", minLength: 1 },
            lastName: { type: "string", minLength: 1 },
            email: { type: "string", format: "email" }
          }
        },
        response: {
          201: {
            type: "object"
          }
        }
      }
    },
    async (request, reply) => {
      const input = CreateCustomerInputSchema.parse(request.body);
      const created = await customerService.createCustomer(input);
      const validated = CustomerSchema.parse(created);
      return reply.code(201).send(validated);
    }
  );

  app.get(
    "/customers/:id",
    {
      schema: {
        params: {
          type: "object",
          required: ["id"],
          properties: {
            id: { type: "string", format: "uuid" }
          }
        }
      }
    },
    async (request, reply) => {
      const { id } = ParamsSchema.parse(request.params);
      const customer = await customerService.getCustomer(id);

      if (!customer) {
        return reply.code(404).send({ message: "Customer not found" });
      }

      return reply.send(CustomerSchema.parse(customer));
    }
  );
}
```

