## `src/app.ts`

```ts
import Fastify from "fastify";
import type { Env } from "./config/env.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { CorporateClient } from "./integrations/corporateClient.js";
import { CustomerService } from "./services/customerService.js";

export async function buildApp(env: Env) {
  const app = Fastify({
    logger: {
      level: env.NODE_ENV === "production" ? "info" : "debug"
    }
  });

  const corporateClient = new CorporateClient(env);
  const customerService = new CustomerService(corporateClient);

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Unhandled error");

    if (error instanceof Error && "validation" in error) {
      return reply.code(400).send({
        message: "Validation failed"
      });
    }

    return reply.code(500).send({
      message: "Internal server error"
    });
  });

  return app;
}
```

