import { randomUUID } from "node:crypto";
import { CorporateSystemClient } from "../integrations/corporateSystem.client.js";
import { Customer } from "../types/customer.js";

export interface CreateCustomerInput {
  firstName: string;
  lastName: string;
  email: string;
}

export class CustomerService {
  constructor(private readonly corporateClient: CorporateSystemClient) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const id = randomUUID();

    const fullName = `${input.firstName} ${input.lastName}`;

    const corporateResult = await this.corporateClient.syncCustomer({
      externalId: id,
      fullName,
      email: input.email
    });

    return {
      id,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      corporateId: corporateResult.corporateId
    };
  }
}
