## `src/app.ts`

```ts
import Fastify from "fastify";
import { CorporateSystemClient } from "./integrations/corporateSystem.client.js";
import { CustomerService } from "./services/customer.service.js";
import { CustomerController } from "./controllers/customer.controller.js";
import { customerRoutes } from "./routes/customer.routes.js";
import { healthRoutes } from "./routes/health.routes.js";

declare module "fastify" {
  interface FastifyInstance {
    diContainer: {
      customerController: CustomerController;
    };
  }
}

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  const corporateClient = new CorporateSystemClient();
  const customerService = new CustomerService(corporateClient);
  const customerController = new CustomerController(customerService);

  app.decorate("diContainer", {
    customerController
  });

  await app.register(healthRoutes);
  await app.register(customerRoutes);

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ error }, "Unhandled error");
    reply.status(500).send({
      error: "Internal Server Error"
    });
  });

  return app;
}
```

