## 3) Environment validation with Zod

### `src/config/env.ts`

```ts
import { z } from 'zod';

export const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),

  DATABASE_URL: z.string().url(),

  KAFKA_BROKERS: z.string().min(1), // comma-separated
  KAFKA_CLIENT_ID: z.string().min(1),
  KAFKA_TOPIC_CUSTOMER_CREATED: z.string().min(1),

  CRM_BASE_URL: z.string().url(),
  CRM_API_KEY: z.string().min(1)
});

export type Env = z.infer<typeof EnvSchema>;

export function parseEnv(rawEnv: Record<string, unknown>): Env {
  const parsed = EnvSchema.safeParse(rawEnv);
  if (!parsed.success) {
    const message = parsed.error.issues
      .map((issue) => `${issue.path.join('.')}: ${issue.message}`)
      .join('; ');
    throw new Error(`Invalid environment configuration: ${message}`);
  }
  return parsed.data;
}
```

