## 10) Kafka producer

### `src/messaging/kafka.producer.ts`

```ts
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { Kafka, Producer } from 'kafkajs';

@Injectable()
export class KafkaProducer implements OnModuleInit, OnModuleDestroy {
  private readonly producer: Producer;

  constructor() {
    const brokers = (process.env.KAFKA_BROKERS ?? '').split(',').map((b) => b.trim()).filter(Boolean);

    const kafka = new Kafka({
      clientId: process.env.KAFKA_CLIENT_ID ?? 'enterprise-microservice',
      brokers
    });

    this.producer = kafka.producer();
  }

  async onModuleInit(): Promise<void> {
    await this.producer.connect();
  }

  async onModuleDestroy(): Promise<void> {
    await this.producer.disconnect();
  }

  async publishCustomerCreated(event: {
    customerId: string;
    name: string;
    email: string;
    externalReference: string;
    crmId: string;
  }): Promise<void> {
    const topic = process.env.KAFKA_TOPIC_CUSTOMER_CREATED ?? 'customer.created';

    await this.producer.send({
      topic,
      messages: [
        {
          key: event.customerId,
          value: JSON.stringify(event)
        }
      ]
    });
  }
}
```

