## 11) Customer service

### `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CorporateCrmClient } from './clients/corporate-crm.client';
import { KafkaProducer } from '../messaging/kafka.producer';
import { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly crmClient: CorporateCrmClient,
    private readonly kafkaProducer: KafkaProducer
  ) {}

  async createCustomer(dto: CreateCustomerDto): Promise<{
    id: string;
    name: string;
    email: string;
    externalReference: string;
    crmId: string;
  }> {
    const crmResult = await this.crmClient.createCustomer({
      name: dto.name,
      email: dto.email,
      externalReference: dto.externalReference
    });

    const customer = await this.prisma.customer.create({
      data: {
        name: dto.name,
        email: dto.email,
        externalReference: dto.externalReference,
        crmId: crmResult.crmId
      }
    });

    await this.kafkaProducer.publishCustomerCreated({
      customerId: customer.id,
      name: customer.name,
      email: customer.email,
      externalReference: customer.externalReference,
      crmId: customer.crmId
    });

    return customer;
  }
}
```

