```ts
import { AppError } from "../utils/errors.js";
import type { CreateCustomerInput, Customer } from "../domain/customer.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { CorporateIntegrationService } from "./corporate-integration.service.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly integration: CorporateIntegrationService
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByExternalId(input.externalId);
    if (existing) {
      throw new AppError("Customer already exists", 409, "CUSTOMER_EXISTS");
    }

    const customer = await this.repository.create(input);

    try {
      await this.integration.syncCustomer(input);
    } catch (cause) {
      throw new AppError(
        "Customer created but corporate sync failed",
        502,
        "CORPORATE_SYNC_FAILED",
        cause
      );
    }

    return customer;
  }
}
```

