```ts
import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import { env } from "./config/env.js";
import loggerPlugin from "./plugins/logger.plugin.js";
import errorPlugin from "./plugins/error.plugin.js";
import authPlugin from "./plugins/auth.plugin.js";
import { CustomerRepository } from "./repositories/customer.repository.js";
import { CorporateApiClient } from "./clients/corporate-api.client.js";
import { CorporateIntegrationService } from "./services/corporate-integration.service.js";
import { CustomerService } from "./services/customer.service.js";
import { customerRoutes } from "./routes/customer.routes.js";

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  const prisma = new PrismaClient();
  const corporateApi = new CorporateApiClient(
    env.CORPORATE_API_BASE_URL,
    env.CORPORATE_API_TOKEN
  );

  const repository = new CustomerRepository(prisma);
  const integration = new CorporateIntegrationService(corporateApi);
  const customerService = new CustomerService(repository, integration);

  await app.register(loggerPlugin);
  await app.register(errorPlugin);
  await app.register(authPlugin);

  app.get("/health/live", async () => ({ status: "ok" }));
  app.get("/health/ready", async () => {
    await prisma.$queryRaw`SELECT 1`;
    return { status: "ready" };
  });

  await customerRoutes(app, customerService);

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

