## 9) Service: `src/modules/orders/orders.service.ts`

```ts
import { Injectable, BadRequestException, ServiceUnavailableException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { CreateOrderDto } from './dto/create-order.dto';
import { Order } from './models/order.model';
import { ErpClient } from '@/integrations/erp/erp.client';

@Injectable()
export class OrdersService {
  private readonly orders = new Map<string, Order>();

  constructor(private readonly erpClient: ErpClient) {}

  async create(dto: CreateOrderDto): Promise<Order> {
    if (dto.amountCents > 10_000_000) {
      throw new BadRequestException('Order amount exceeds enterprise limit');
    }

    const order: Order = {
      id: randomUUID(),
      customerId: dto.customerId,
      amountCents: dto.amountCents,
      currency: dto.currency,
      status: 'PENDING',
      createdAt: new Date()
    };

    this.orders.set(order.id, order);

    try {
      const erpResult = await this.erpClient.createOrder({
        customerId: order.customerId,
        amountCents: order.amountCents,
        currency: order.currency
      });

      if (!erpResult.accepted) {
        order.status = 'REJECTED';
        this.orders.set(order.id, order);
        return order;
      }

      order.status = 'CONFIRMED';
      this.orders.set(order.id, order);
      return order;
    } catch {
      order.status = 'REJECTED';
      this.orders.set(order.id, order);
      throw new ServiceUnavailableException('ERP integration unavailable');
    }
  }

  findById(id: string): Order | undefined {
    return this.orders.get(id);
  }
}
```

