## 9) Repository layer: `src/modules/customer/customer.repository.ts`

This example uses an in-memory store, but the interface is designed so you can swap in a database implementation later.

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { Customer, CreateCustomerInput, UpdateCustomerInput } from './customer.types';

@Injectable()
export class CustomerRepository {
  private readonly customers = new Map<string, Customer>();

  async create(input: CreateCustomerInput): Promise<Customer> {
    const now = new Date();
    const customer: Customer = {
      id: randomUUID(),
      externalId: `CUST-${randomUUID()}`,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: now,
      updatedAt: now,
    };

    this.customers.set(customer.id, customer);
    return customer;
  }

  async findById(id: string): Promise<Customer | null> {
    return this.customers.get(id) ?? null;
  }

  async update(id: string, input: UpdateCustomerInput): Promise<Customer | null> {
    const existing = this.customers.get(id);
    if (!existing) return null;

    const updated: Customer = {
      ...existing,
      ...input,
      updatedAt: new Date(),
    };

    this.customers.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<boolean> {
    return this.customers.delete(id);
  }
}
```

