import { HttpService } from '@nestjs/axios';
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';
import { CorporateCustomerSyncRequest, CorporateCustomerSyncResponse } from './corporate-client.types';

@Injectable()
export class CorporateClientService {
  constructor(private readonly http: HttpService) {}

  async syncCustomer(payload: CorporateCustomerSyncRequest): Promise<CorporateCustomerSyncResponse> {
    try {
      const baseUrl = process.env.CORPORATE_API_BASE_URL;
      const token = process.env.CORPORATE_API_TOKEN;

      if (!baseUrl || !token) {
        throw new Error('Missing corporate API configuration');
      }

      const response = await firstValueFrom(
        this.http.post<CorporateCustomerSyncResponse>(
          `${baseUrl}/customers/sync`,
          payload,
          {
            headers: {
              Authorization: `Bearer ${token}`,
              'Content-Type': 'application/json',
            },
            timeout: 5000,
          },
        ),
      );

      return response.data;
    } catch (error) {
      throw new InternalServerErrorException('Failed to sync customer with corporate system');
    }
  }
}
