import { Injectable, NotFoundException } from '@nestjs/common';
import { CustomerRepository } from './customer.repository';
import { CorporateClientService } from '../corporate/corporate-client.service';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { Customer } from './customer.types';

@Injectable()
export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateClient: CorporateClientService,
  ) {}

  async create(dto: CreateCustomerDto): Promise<Customer> {
    const customer = await this.repository.create(dto);

    await this.corporateClient.syncCustomer({
      externalId: customer.externalId,
      email: customer.email,
      fullName: `${customer.firstName} ${customer.lastName}`,
    });

    return customer;
  }

  async getById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundException(`Customer ${id} not found`);
    }
    return customer;
  }

  async update(id: string, dto: UpdateCustomerDto): Promise<Customer> {
    const updated = await this.repository.update(id, dto);
    if (!updated) {
      throw new NotFoundException(`Customer ${id} not found`);
    }
    return updated;
  }

  async delete(id: string): Promise<void> {
    const deleted = await this.repository.delete(id);
    if (!deleted) {
      throw new NotFoundException(`Customer ${id} not found`);
    }
  }
}
```

