# 7) Application service

## `src/application/customer-service.ts`

```ts
import type { Customer, CustomerId } from "../domain/customer.js";
import { NotFoundError, ValidationError } from "../domain/errors.js";
import type { CrmPort, ErpPort, CustomerRepository } from "./ports.js";

export interface UpdateCustomerInput {
  firstName?: string;
  lastName?: string;
  email?: string;
  status?: "ACTIVE" | "INACTIVE";
}

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly crm: CrmPort,
    private readonly erp: ErpPort
  ) {}

  async getCustomer(id: CustomerId): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) throw new NotFoundError(`Customer ${id} not found`);
    return customer;
  }

  async updateCustomer(id: CustomerId, input: UpdateCustomerInput): Promise<Customer> {
    const existing = await this.repo.findById(id);
    if (!existing) throw new NotFoundError(`Customer ${id} not found`);

    if (input.email !== undefined && !input.email.includes("@")) {
      throw new ValidationError("Invalid email format");
    }

    const updated: Customer = {
      ...existing,
      ...input
    };

    await this.repo.save(updated);

    // Enterprise integration points; can be made async/event-driven later
    await Promise.all([
      this.crm.syncCustomer(updated),
      this.erp.syncCustomer(updated)
    ]);

    return updated;
  }
}
```

