import type { Customer, CustomerId } from "../domain/customer.js";
import type { CustomerRepository } from "../application/ports.js";

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly data = new Map<CustomerId, Customer>();

  constructor(seed: Customer[] = []) {
    for (const customer of seed) {
      this.data.set(customer.id, customer);
    }
  }

  async findById(id: CustomerId): Promise<Customer | null> {
    return this.data.get(id) ?? null;
  }

  async save(customer: Customer): Promise<void> {
    this.data.set(customer.id, customer);
  }
}
