# 10) HTTP schemas and routes

## `src/infrastructure/http/schemas.ts`

```ts
import { z } from "zod";

export const customerIdSchema = z.string().min(1);

export const updateCustomerSchema = z.object({
  firstName: z.string().min(1).optional(),
  lastName: z.string().min(1).optional(),
  email: z.string().email().optional(),
  status: z.enum(["ACTIVE", "INACTIVE"]).optional()
});

export type UpdateCustomerBody = z.infer<typeof updateCustomerSchema>;
```

## `src/infrastructure/http/routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { customerIdSchema, updateCustomerSchema } from "./schemas.js";
import { NotFoundError, ValidationError } from "../../domain/errors.js";
import type { CustomerService } from "../../application/customer-service.js";

export async function registerRoutes(app: FastifyInstance, customerService: CustomerService) {
  app.get("/health", async () => ({ status: "ok" }));

  app.get("/customers/:id", async (request, reply) => {
    const parsed = customerIdSchema.safeParse(request.params && (request.params as { id?: unknown }).id);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Invalid customer id" });
    }

    try {
      const customer = await customerService.getCustomer(parsed.data);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      throw err;
    }
  });

  app.put("/customers/:id", async (request, reply) => {
    const idParsed = customerIdSchema.safeParse((request.params as { id?: unknown }).id);
    const bodyParsed = updateCustomerSchema.safeParse(request.body);

    if (!idParsed.success) {
      return reply.code(400).send({ error: "Invalid customer id" });
    }
    if (!bodyParsed.success) {
      return reply.code(400).send({ error: "Invalid request body", details: bodyParsed.error.flatten() });
    }

    try {
      const updated = await customerService.updateCustomer(idParsed.data, bodyParsed.data);
      return reply.send(updated);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      if (err instanceof ValidationError) {
        return reply.code(400).send({ error: err.message });
      }
      throw err;
    }
  });
}
```

