import { CustomerProps } from './customer.types';

export class Customer {
  private constructor(private readonly props: CustomerProps) {}

  static create(input: Omit<CustomerProps, 'createdAt' | 'updatedAt'>): Customer {
    const now = new Date();
    return new Customer({
      ...input,
      createdAt: now,
      updatedAt: now,
    });
  }

  static rehydrate(props: CustomerProps): Customer {
    return new Customer(props);
  }

  get id(): string {
    return this.props.id;
  }

  get firstName(): string {
    return this.props.firstName;
