```ts
import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'uuid';
import { Customer } from './customer.entity';
import { CustomerRepository } from './customer.repository';
import { CorporateIdentityClient } from '@infra/integrations/corporate-identity.client';
import { AuditClient } from '@infra/integrations/audit.client';
import { ErpSyncClient } from '@infra/integrations/erp-sync.client';

export interface CreateCustomerCommand {
  firstName: string;
  lastName: string;
  email: string;
}

@Injectable()
export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly identityClient: CorporateIdentityClient,
    private readonly erpSyncClient: ErpSyncClient,
    private readonly auditClient: AuditClient,
  ) {}

  async createCustomer(command: CreateCustomerCommand): Promise<Customer> {
    const existing = await this.repository.findByEmail(command.email);
    if (existing) {
      throw new ConflictException(`Customer with email ${command.email} already exists`);
    }

    const employeeId = await this.identityClient.provisionIdentity({
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName,
    });

    const customer = Customer.create({
      id: randomUUID(),
      firstName: command.firstName,
      lastName: command.lastName,
      email: command.email,
      corporateEmployeeId: employeeId,
    });

    const saved = await this.repository.save(customer);

    await this.erpSyncClient.syncCustomer(saved);
    await this.auditClient.record({
      action: 'CUSTOMER_CREATED',
      entityId: saved.id,
      payload: saved.toJSON(),
    });

    return saved;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundException(`Customer ${id} not found`);
    }
    return customer;
  }
}
