## 7.2 Use case: `CreateCustomer`

### `src/application/use-cases/CreateCustomer.ts`

```ts
import { randomUUID } from "node:crypto";
import { Customer } from "../../domain/entities/Customer.js";
import { CustomerRepository } from "../ports/CustomerRepository.js";
import { CorporateDirectoryClient } from "../ports/CorporateDirectoryClient.js";
import { AuditLogger } from "../ports/AuditLogger.js";
import { ok, err, Result } from "../../domain/types/Result.js";

export interface CreateCustomerInput {
  employeeId: string;
}

export type CreateCustomerError =
  | { type: "PROFILE_NOT_FOUND"; message: string }
  | { type: "ALREADY_EXISTS"; message: string }
  | { type: "INTEGRATION_ERROR"; message: string };

export class CreateCustomer {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient,
    private readonly auditLogger: AuditLogger
  ) {}

  async execute(input: CreateCustomerInput): Promise<Result<Customer, CreateCustomerError>> {
    try {
      const existing = await this.customerRepository.findByExternalId(input.employeeId);
      if (existing) {
        return err({ type: "ALREADY_EXISTS", message: "Customer already exists" });
      }

      const profile = await this.corporateDirectoryClient.getProfileByEmployeeId(input.employeeId);
      if (!profile) {
        return err({ type: "PROFILE_NOT_FOUND", message: "Employee profile not found" });
      }

      const customer: Customer = {
        id: randomUUID(),
        externalId: profile.employeeId,
        fullName: profile.fullName,
        email: profile.email,
        createdAt: new Date()
      };

      await this.customerRepository.save(customer);

      await this.auditLogger.record({
        action: "CUSTOMER_CREATED",
        actor: profile.employeeId,
        subject: customer.id,
        metadata: {
          email: customer.email
        }
      });

      return ok(customer);
    } catch {
      return err({ type: "INTEGRATION_ERROR", message: "Unexpected integration failure" });
    }
  }
}
```

