# 8) Infrastructure layer

## 8.1 Corporate directory client

### `src/infrastructure/corporate/CorporateDirectoryHttpClient.ts`

```ts
import { request } from "undici";
import { CorporateDirectoryClient, CorporateDirectoryProfile } from "../../application/ports/CorporateDirectoryClient.js";

export class CorporateDirectoryHttpClient implements CorporateDirectoryClient {
  constructor(private readonly baseUrl: string, private readonly token: string) {}

  async getProfileByEmployeeId(employeeId: string): Promise<CorporateDirectoryProfile | null> {
    const res = await request(`${this.baseUrl}/employees/${encodeURIComponent(employeeId)}`, {
      method: "GET",
      headers: {
        authorization: `Bearer ${this.token}`
      }
    });

    if (res.statusCode === 404) return null;
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new Error(`Corporate directory returned status ${res.statusCode}`);
    }

    const body = (await res.body.json()) as unknown;

    if (
      typeof body !== "object" ||
      body === null ||
      typeof (body as { employeeId?: unknown }).employeeId !== "string" ||
      typeof (body as { fullName?: unknown }).fullName !== "string" ||
      typeof (body as { email?: unknown }).email !== "string"
    ) {
      throw new Error("Invalid corporate directory response");
    }

    return {
      employeeId: body.employeeId,
      fullName: body.fullName,
      email: body.email
    };
  }
}
```

