## 9.2 Route handler

### `src/infrastructure/http/routes/customerRoutes.ts`

```ts
import { FastifyInstance } from "fastify";
import { createCustomerBodySchema } from "../schemas/customerSchemas.js";
import { CreateCustomer } from "../../../application/use-cases/CreateCustomer.js";

export async function customerRoutes(app: FastifyInstance, deps: { createCustomer: CreateCustomer }) {
  app.post("/customers", async (request, reply) => {
    const parsed = createCustomerBodySchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        details: parsed.error.flatten()
      });
    }

    const result = await deps.createCustomer.execute(parsed.data);

    if (!result.ok) {
      switch (result.error.type) {
        case "PROFILE_NOT_FOUND":
          return reply.status(404).send({ error: result.error.type, message: result.error.message });
        case "ALREADY_EXISTS":
          return reply.status(409).send({ error: result.error.type, message: result.error.message });
        case "INTEGRATION_ERROR":
          return reply.status(502).send({ error: result.error.type, message: result.error.message });
      }
    }

    return reply.status(201).send({
      id: result.value.id,
      externalId: result.value.externalId,
      fullName: result.value.fullName,
      email: result.value.email,
      createdAt: result.value.createdAt.toISOString()
    });
  });
}
```

