## 3) Core type-safety patterns

### Branded types
Use branded types to avoid mixing IDs and raw strings.

```ts
// src/common/types/branded-types.ts
export type Brand<T, B extends string> = T & { readonly __brand: B };

export type EmployeeId = Brand<string, 'EmployeeId'>;
export type CorporateUserId = Brand<string, 'CorporateUserId'>;

export const EmployeeId = (value: string): EmployeeId => value as EmployeeId;
export const CorporateUserId = (value: string): CorporateUserId => value as CorporateUserId;
```

