## 4) Domain layer

### Employee entity

```ts
// src/domain/employee/employee.entity.ts
import { EmployeeId, CorporateUserId } from '../../common/types/branded-types';

export interface EmployeeProps {
  id: EmployeeId;
  corporateUserId: CorporateUserId;
  firstName: string;
  lastName: string;
  email: string;
  department?: string;
  title?: string;
  createdAt: Date;
  updatedAt: Date;
}

export class Employee {
  private constructor(private readonly props: EmployeeProps) {}

  static create(props: Omit<EmployeeProps, 'createdAt' | 'updatedAt'> & { createdAt?: Date; updatedAt?: Date }): Employee {
    if (!props.firstName.trim()) throw new Error('firstName is required');
    if (!props.lastName.trim()) throw new Error('lastName is required');
    if (!props.email.includes('@')) throw new Error('email is invalid');

    return new Employee({
      ...props,
      createdAt: props.createdAt ?? new Date(),
      updatedAt: props.updatedAt ?? new Date(),
    });
  }

  get id(): EmployeeId {
    return this.props.id;
  }

  get corporateUserId(): CorporateUserId {
    return this.props.corporateUserId;
  }

  get email(): string {
    return this.props.email;
  }

  updateProfile(input: { firstName?: string; lastName?: string; department?: string; title?: string }): Employee {
    return Employee.create({
      ...this.props,
      firstName: input.firstName ?? this.props.firstName,
      lastName: input.lastName ?? this.props.lastName,
      department: input.department ?? this.props.department,
      title: input.title ?? this.props.title,
      updatedAt: new Date(),
    });
  }

  toJSON(): EmployeeProps {
    return { ...this.props };
  }
}
```

