  async execute(input: {
    corporateUserId: string;
    firstName: string;
    lastName: string;
    email: string;
    department?: string;
    title?: string;
  }): Promise<Employee> {
    const employee = Employee.create({
      id: EmployeeId(crypto.randomUUID()),
      corporateUserId: CorporateUserId(input.corporateUserId),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      department: input.department,
      title: input.title,
    });

    await this.repository.save(employee);

    await this.eventPublisher.publish('employee.created', {
      employeeId: employee.id,
      corporateUserId: employee.corporateUserId,
      email: employee.email,
    });

    return employee;
  }
}
