### Repository implementation

```ts
// src/infrastructure/persistence/prisma-employee.repository.ts
import { Injectable } from '@nestjs/common';
import { EmployeeRepository } from '../../domain/employee/employee.repository';
import { Employee } from '../../domain/employee/employee.entity';
import { EmployeeId, CorporateUserId } from '../../common/types/branded-types';
import { PrismaService } from './prisma.service';

@Injectable()
export class PrismaEmployeeRepository implements EmployeeRepository {
  constructor(private readonly prisma: PrismaService) {}

  async findById(id: EmployeeId): Promise<Employee | null> {
    const row = await this.prisma.employee.findUnique({ where: { id } });
    return row ? this.toDomain(row) : null;
  }

  async findByCorporateUserId(corporateUserId: CorporateUserId): Promise<Employee | null> {
    const row = await this.prisma.employee.findUnique({ where: { corporateUserId } });
    return row ? this.toDomain(row) : null;
  }

  async save(employee: Employee): Promise<void> {
    const e = employee.toJSON();
    await this.prisma.employee.upsert({
      where: { id: e.id },
      create: {
        id: e.id,
        corporateUserId: e.corporateUserId,
        firstName: e.firstName,
        lastName: e.lastName,
        email: e.email,
        department: e.department,
        title: e.title,
        createdAt: e.createdAt,
        updatedAt: e.updatedAt,
      },
      update: {
        corporateUserId: e.corporateUserId,
        firstName: e.firstName,
        lastName: e.lastName,
        email: e.email,
        department: e.department,
        title: e.title,
        updatedAt: e.updatedAt,
      },
    });
  }

  private toDomain(row: {
    id: string;
    corporateUserId: string;
    firstName: string;
    lastName: string;
    email: string;
    department: string | null;
    title: string | null;
    createdAt: Date;
    updatedAt: Date;
  }): Employee {
    return Employee.create({
      id: EmployeeId(row.id),
      corporateUserId: CorporateUserId(row.corporateUserId),
      firstName: row.firstName,
      lastName: row.lastName,
      email: row.email,
      department: row.department ?? undefined,
      title: row.title ?? undefined,
      createdAt: row.createdAt,
      updatedAt: row.updatedAt,
    });
  }
}
```

