## 4. Strict environment validation

Use `zod` so startup fails fast if config is invalid.

### `src/config/env.schema.ts`

```ts
import { z } from 'zod';

export const envSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'staging', 'production']),
  PORT: z.coerce.number().int().positive().default(3000),

  DATABASE_URL: z.string().min(1),

  IDP_BASE_URL: z.string().url(),
  IDP_CLIENT_ID: z.string().min(1),
  IDP_CLIENT_SECRET: z.string().min(1),

  CORPORATE_API_BASE_URL: z.string().url(),
  CORPORATE_API_TIMEOUT_MS: z.coerce.number().int().positive().default(5000),

  KAFKA_BROKERS: z.string().min(1),
  KAFKA_CLIENT_ID: z.string().min(1),
  KAFKA_TOPIC_AUDIT: z.string().min(1)
});

export type EnvSchema = z.infer<typeof envSchema>;
```

### `src/config/configuration.ts`

```ts
import { envSchema } from './env.schema';

export function validateEnv(config: Record<string, unknown>) {
  const parsed = envSchema.safeParse(config);
  if (!parsed.success) {
    throw new Error(`Invalid environment configuration: ${parsed.error.message}`);
  }
  return parsed.data;
}
```

