## 8) Application service

### `src/application/customerService.ts`

```ts
import { Customer } from '../domain/customer.js';
import { NotFoundError } from '../domain/errors.js';
import { CrmClient } from '../integrations/crmClient.js';
import { IdentityClient } from '../integrations/identityClient.js';

export class CustomerService {
  constructor(
    private readonly crmClient: CrmClient,
    private readonly identityClient: IdentityClient
  ) {}

  async getCustomerProfile(customerId: string): Promise<Customer> {
    const crmRecord = await this.crmClient.getCustomerRecord(customerId);

    if (!crmRecord) {
      throw new NotFoundError(`Customer ${customerId} not found`);
    }

    const identity = await this.identityClient.getUserByEmail(
      `${customerId}@example.com`
    );

    return {
      id: customerId,
      firstName: 'John',
      lastName: 'Doe',
      email: identity?.email ?? `${customerId}@example.com`,
      status: 'ACTIVE',
      externalCrmId: crmRecord.crmId
    };
  }
}
```

