## 12) Routes

### `src/routes/customerRoutes.ts`

```ts
import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { CustomerService } from '../application/customerService.js';

const paramsSchema = z.object({
  customerId: z.string().min(1)
});

export async function customerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
) {
  app.get('/customers/:customerId', async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: 'VALIDATION_ERROR',
        message: 'Invalid customerId'
      });
    }

    const customer = await customerService.getCustomerProfile(parsed.data.customerId);
    return reply.status(200).send(customer);
  });
}
```

