## 13) App bootstrap

### `src/app.ts`

```ts
import Fastify from 'fastify';
import { env } from './config/env.js';
import { errorHandler } from './middleware/errorHandler.js';
import { requestContext } from './middleware/requestContext.js';
import { CrmClient } from './integrations/crmClient.js';
import { IdentityClient } from './integrations/identityClient.js';
import { CustomerService } from './application/customerService.js';
import { customerRoutes } from './routes/customerRoutes.js';

export async function buildApp() {
  const app = Fastify({
    logger: {
      level: env.LOG_LEVEL
    }
  });

  app.addHook('onRequest', requestContext);
  app.setErrorHandler(errorHandler);

  const crmClient = new CrmClient(env.CRM_BASE_URL);
  const identityClient = new IdentityClient(env.IDENTITY_BASE_URL);
  const customerService = new CustomerService(crmClient, identityClient);

  await customerRoutes(app, customerService);

  app.get('/health', async () => ({
    status: 'ok',
    service: 'customer-profile-service'
  }));

  return app;
}
```

