```ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../../common/errors/domain-error';
import { Customer } from './domain/customer';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerRepositoryPort } from './ports/customer-repository.port';
import { CorporateCrmPort } from './ports/corporate-crm.port';

export const CUSTOMER_REPOSITORY = Symbol('CUSTOMER_REPOSITORY');
export const CORPORATE_CRM = Symbol('CORPORATE_CRM');

@Injectable()
export class CustomerService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepositoryPort,
    @Inject(CORPORATE_CRM)
    private readonly corporateCrm: CorporateCrmPort
  ) {}

  async createCustomer(input: CreateCustomerDto): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new DomainError('Customer already exists', 'CUSTOMER_EXISTS', 409, {
        email: input.email
      });
    }

    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date()
    };

    const crmResult = await this.corporateCrm.createCustomer(customer);
    customer.externalId = crmResult.externalId;

    return this.customerRepository.save(customer);
  }
}
```

