import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { CrmCreateCustomerRequest, CrmCreateCustomerResponse } from './crm.types';

@Injectable()
export class CrmClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.CRM_BASE_URL,
      headers: {
        Authorization: `Bearer ${process.env.CRM_API_KEY}`,
        'Content-Type': 'application/json'
      },
      timeout: 5000
    });
  }

  async createCustomer(
    request: CrmCreateCustomerRequest
  ): Promise<CrmCreateCustomerResponse> {
    const response = await this.client.post<CrmCreateCustomerResponse>('/customers', request);
    return response.data;
  }
}
