```ts
import { Injectable } from '@nestjs/common';
import { Customer } from '../../customer/domain/customer';
import { CorporateCrmPort } from '../../customer/ports/corporate-crm.port';
import { CrmClient } from './crm.client';

@Injectable()
export class CrmAdapter implements CorporateCrmPort {
  constructor(private readonly crmClient: CrmClient) {}

  async createCustomer(customer: Customer): Promise<{ externalId: string }> {
    const result = await this.crmClient.createCustomer({
      first_name: customer.firstName,
      last_name: customer.lastName,
      email_address: customer.email
