## 5) Corporate system integration client

This is where you connect to internal ERP/CRM/mainframe services.

### `src/integrations/corporate-system/corporate-system.types.ts`

```ts
export interface CorporateCustomerRecord {
  corporateId: string;
  fullName: string;
  email: string;
  status: 'ACTIVE' | 'INACTIVE';
}
```

### `src/integrations/corporate-system/corporate-system.client.ts`

```ts
import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { AppError } from '../../common/errors/app-error';
import { CorporateCustomerRecord } from './corporate-system.types';

@Injectable()
export class CorporateSystemClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      timeout: 5000
    });
  }

  async createCustomer(input: {
    fullName: string;
    email: string;
  }): Promise<CorporateCustomerRecord> {
    const baseUrl = process.env.CORPORATE_SYSTEM_BASE_URL!;
    const apiKey = process.env.CORPORATE_SYSTEM_API_KEY!;

    try {
      const response = await this.http.post<CorporateCustomerRecord>(
        `${baseUrl}/customers`,
        input,
        {
          headers: {
            'X-API-Key': apiKey,
            'Content-Type': 'application/json'
          }
        }
      );

      return response.data;
    } catch (error) {
      throw new AppError(
        'CORPORATE_SYSTEM_UNAVAILABLE',
        'Failed to create customer in corporate system',
        502,
        error
      );
    }
  }
}
```

