# 8) Application service

## `src/application/employeeService.ts`

```ts
import type { EmployeeRepository, CorporateHrSystemClient, Clock } from "./ports.js";
import type { EmployeeProfile, EmployeeId } from "../domain/employee.js";
import { EmployeeNotFoundError } from "../domain/errors.js";
import { ok, err, type Result } from "../utils/result.js";

export interface UpdateEmployeeInput {
  firstName?: string;
  lastName?: string;
  email?: string;
  department?: string;
  active?: boolean;
}

export class EmployeeService {
  constructor(
    private readonly repo: EmployeeRepository,
    private readonly hrClient: CorporateHrSystemClient,
    private readonly clock: Clock
  ) {}

  async getEmployeeById(id: EmployeeId): Promise<Result<EmployeeProfile, EmployeeNotFoundError>> {
    const employee = await this.repo.findById(id);
    if (!employee) return err(new EmployeeNotFoundError(id));
    return ok(employee);
  }

  async updateEmployee(
    id: EmployeeId,
    input: UpdateEmployeeInput
  ): Promise<Result<EmployeeProfile, EmployeeNotFoundError>> {
    const existing = await this.repo.findById(id);
    if (!existing) return err(new EmployeeNotFoundError(id));

    const updated: EmployeeProfile = {
      ...existing,
      ...input,
      updatedAt: this.clock.now()
    };

    await this.repo.save(updated);
    await this.hrClient.syncEmployee(updated);

    return ok(updated);
  }
}
```

