```ts
import type { FastifyInstance } from "fastify";
import { EmployeeIdParamsSchema, UpdateEmployeeBodySchema } from "./schemas.js";
import type { EmployeeService } from "../application/employeeService.js";

export async function registerRoutes(app: FastifyInstance, employeeService: EmployeeService) {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/employees/:id", async (request, reply) => {
    const params = EmployeeIdParamsSchema.parse(request.params);
    const result = await employeeService.getEmployeeById(params.id);

    if (!result.ok) {
      return reply.status(404).send({
        error: result.error.code,
        message: result.error.message
      });
    }

    return reply.send(result.value);
  });

  app.put("/employees/:id", async (request, reply) => {
    const params = EmployeeIdParamsSchema.parse(request.params);
    const body = UpdateEmployeeBodySchema.parse(request.body);

    const result = await employeeService.updateEmployee(params.id, body);

    if (!result.ok) {
      return reply.status(404).send({
        error: result.error.code,
        message: result.error.message
      });
    }

    return reply.send(result.value);
  });
}
```

