import { EmployeeService } from "./application/employeeService.js";

export async function buildApp() {
  const env = loadEnv();
  const logger = createLogger(env);

  const app = Fastify({
    logger
  });

  app.setErrorHandler(errorHandler);

  const repo = new InMemoryEmployeeRepository();
  const hrClient = new CorporateHrAdapter();
  const clock = { now: () => new Date() };

  const employeeService = new EmployeeService(repo, hrClient, clock);

  // Seed sample data for initial implementation
  repo.seed({
    id: "emp_1001",
    employeeNumber: "E1001",
    firstName: "Ava",
    lastName: "Patel",
    email: "ava.patel@corp.example",
    department: "Finance",
    active: true,
    createdAt: new Date("2025-01-01T00:00:00.000Z"),
    updatedAt: new Date("2025-01-01T00:00:00.000Z")
  });

  await registerRoutes(app, employeeService);

  return { app, env };
}
