```ts
import { Injectable } from '@nestjs/common';
import { PrismaClient, Employee } from '@prisma/client';

@Injectable()
export class EmployeesRepository {
  private readonly prisma = new PrismaClient();

  async create(data: {
    employeeNo: string;
    firstName: string;
    lastName: string;
    email: string;
    department: string;
    title?: string;
  }): Promise<Employee> {
    return this.prisma.employee.create({ data });
  }

  async findById(id: string): Promise<Employee | null> {
    return this.prisma.employee.findUnique({ where: { id } });
  }

  async findByEmail(email: string): Promise<Employee | null> {
    return this.prisma.employee.findUnique({ where: { email } });
  }

  async list(): Promise<Employee[]> {
    return this.prisma.employee.findMany({ orderBy: { createdAt: 'desc' } });
  }
}
```

> In a production implementation, the Prisma client should be wrapped in a shared provider rather than instantiated directly in the repository. This is just an initial implementation.

