# 6. Corporate integration pattern

For enterprise systems, avoid coupling your domain directly to external APIs. Use adapters.

## Example adapter interface
```ts
export interface CorporateCrmClient {
  getCustomerById(id: string): Promise<{
    id: string;
    name: string;
    status: 'ACTIVE' | 'INACTIVE';
  }>;
}
```

## Example implementation
```ts
import { Injectable } from '@nestjs/common';
import axios from 'axios';

@Injectable()
export class HttpCorporateCrmClient {
  async getCustomerById(id: string) {
    const response = await axios.get(`https://crm.internal/api/customers/${id}`, {
      timeout: 5000,
      headers: {
        'X-Correlation-Id': crypto.randomUUID()
      }
    });

    return response.data;
  }
}
```

