## 12) Service layer

### `src/services/employee.service.ts`

```ts
import { ConflictError, NotFoundError } from "../domain/errors.js";
import { EmployeeRepository } from "../repositories/employee.repository.js";
import type { CreateEmployeeInput, UpdateEmployeeInput } from "../schemas/employee.schemas.js";
import { MessageBusClient } from "../integrations/message-bus-client.js";

export class EmployeeService {
  constructor(
    private readonly repo = new EmployeeRepository(),
    private readonly eventBus = new MessageBusClient()
  ) {}

  async create(input: CreateEmployeeInput) {
    const existing = await this.repo.findByEmail(input.email);
    if (existing) throw new ConflictError("Employee with this email already exists");

    const employee = await this.repo.create(input);

    await this.eventBus.publish({
      type: "employee.created",
      occurredAt: new Date().toISOString(),
      payload: employee
    });

    return employee;
  }

  async getById(id: string) {
    const employee = await this.repo.findById(id);
    if (!employee) throw new NotFoundError("Employee not found");
    return employee;
  }

  async update(id: string, input: UpdateEmployeeInput) {
    await this.getById(id);
    const employee = await this.repo.update(id, input);

    await this.eventBus.publish({
      type: "employee.updated",
      occurredAt: new Date().toISOString(),
      payload: employee
    });

    return employee;
  }

  async delete(id: string) {
    await this.getById(id);
    await this.repo.delete(id);

    await this.eventBus.publish({
      type: "employee.deleted",
      occurredAt: new Date().toISOString(),
      payload: { id }
    });
  }
}
```

