import type { FastifyInstance } from "fastify";
import { CreateEmployeeSchema, UpdateEmployeeSchema, EmployeeIdSchema } from "../schemas/employee.schemas.js";
import { EmployeeService } from "../services/employee.service.js";

export async function employeeRoutes(app: FastifyInstance) {
  const service = new EmployeeService();

  app.post("/", async (request, reply) => {
    const body = CreateEmployeeSchema.parse(request.body);
    const employee = await service.create(body);
    return reply.code(201).send(employee);
  });

  app.get("/:id", async (request) => {
    const { id } = EmployeeIdSchema.parse(request.params);
    return service.getById(id);
  });

  app.patch("/:id", async (request) => {
    const { id } = EmployeeIdSchema.parse(request.params);
    const body = UpdateEmployeeSchema.parse(request.body);
    return service.update(id, body);
  });

  app.delete("/:id", async (request, reply) => {
    const { id } = EmployeeIdSchema.parse(request.params);
    await service.delete(id);
    return reply.code(204).send();
  });
}
