# 8) Repository layer: `src/modules/employee/employee.repository.ts`

This is an in-memory initial implementation, but the interface is ready for a real DB.

```ts
import type { CreateEmployeeInput, Employee } from "./employee.types.js";

export interface EmployeeRepository {
  create(input: CreateEmployeeInput): Promise<Employee>;
  findById(id: string): Promise<Employee | null>;
  findByEmployeeNumber(employeeNumber: string): Promise<Employee | null>;
}

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly employees = new Map<string, Employee>();

  async create(input: CreateEmployeeInput): Promise<Employee> {
    const now = new Date().toISOString();
    const employee: Employee = {
      id: crypto.randomUUID(),
      ...input,
      createdAt: now,
      updatedAt: now
    };

    this.employees.set(employee.id, employee);
    return employee;
  }

  async findById(id: string): Promise<Employee | null> {
    return this.employees.get(id) ?? null;
  }

  async findByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    for (const employee of this.employees.values()) {
      if (employee.employeeNumber === employeeNumber) return employee;
    }
    return null;
  }
}
```

