# 12) Service layer: `src/modules/employee/employee.service.ts`

```ts
import { AppError, NotFoundError } from "../../shared/errors.js";
import type { AuditClient } from "../../integrations/audit/audit.client.js";
import type { CorporateApiClient } from "../../integrations/corporate-api/corporate-api.client.js";
import type { EmployeeRepository } from "./employee.repository.js";
import type { CreateEmployeeInput, Employee } from "./employee.types.js";

export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly corporateApi: CorporateApiClient,
    private readonly auditClient: AuditClient
  ) {}

  async createEmployee(input: CreateEmployeeInput, actor?: string): Promise<Employee> {
    const existing = await this.repository.findByEmployeeNumber(input.employeeNumber);
    if (existing) {
      throw new AppError("Employee number already exists", 409, "CONFLICT");
    }

    const corporateRecord = await this.corporateApi.getEmployeeRecord(input.employeeNumber);
    if (corporateRecord && corporateRecord.status !== "ACTIVE") {
      throw new AppError("Employee is inactive in corporate system", 409, "INACTIVE_CORPORATE_EMPLOYEE");
    }

    const employee = await this.repository.create(input);

    await this.auditClient.emit({
      action: "employee.created",
      actor,
      entityType: "employee",
      entityId: employee.id,
      timestamp: new Date().toISOString(),
      metadata: {
        employeeNumber: employee.employeeNumber,
        department: employee.department
      }
    });

    return employee;
  }

  async getEmployeeById(id: string): Promise<Employee> {
    const employee = await this.repository.findById(id);
    if (!employee) {
      throw new NotFoundError("Employee not found");
    }
    return employee;
  }
}
