```ts
import type { FastifyInstance } from "fastify";
import { CreateEmployeeSchema, EmployeeIdParamsSchema } from "./employee.schema.js";
import { authMiddleware } from "../../integrations/auth/auth.middleware.js";
import { ValidationError } from "../../shared/errors.js";
import type { EmployeeService } from "./employee.service.js";

export async function employeeRoutes(
  app: FastifyInstance,
  service: EmployeeService
): Promise<void> {
  app.post(
    "/employees",
    { preHandler: authMiddleware },
    async (request, reply) => {
      const parsed = CreateEmployeeSchema.safeParse(request.body);
      if (!parsed.success) {
        throw new ValidationError(parsed.error.message);
      }

      const employee = await service.createEmployee(parsed.data, request.user?.subject);
      return reply.code(201).send(employee);
    }
  );

  app.get(
    "/employees/:id",
    { preHandler: authMiddleware },
    async (request) => {
      const paramsResult = EmployeeIdParamsSchema.safeParse(request.params);
      if (!paramsResult.success) {
        throw new ValidationError(paramsResult.error.message);
      }

      return service.getEmployeeById(paramsResult.data.id);
    }
  );
}
