```ts
import { FastifyInstance } from 'fastify';
import fp from 'fastify-plugin';
import fastifyEnv from '@fastify/env';
import { z } from 'zod';

const envSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace']).default('info'),
  CORPORATE_API_BASE_URL: z.string().url(),
  CORPORATE_API_TOKEN: z.string().min(1)
});

export type AppEnv = z.infer<typeof envSchema>;

declare module 'fastify' {
  interface FastifyInstance {
    config: AppEnv;
  }
}

export default fp(async (app: FastifyInstance) => {
  await app.register(fastifyEnv, {
    schema: {
      type: 'object',
      required: ['NODE_ENV', 'PORT', 'LOG_LEVEL', 'CORPORATE_API_BASE_URL', 'CORPORATE_API_TOKEN'],
      properties: {
        NODE_ENV: { type: 'string' },
        PORT: { type: 'number' },
        LOG_LEVEL: { type: 'string' },
        CORPORATE_API_BASE_URL: { type: 'string' },
        CORPORATE_API_TOKEN: { type: 'string' }
      }
    },
    dotenv: true,
    data: process.env
  });

  const parsed = envSchema.parse(app.config);
  app.decorate('config', parsed);
});
```

