## 6) Corporate integration client abstraction

### `src/integrations/corporateClient.ts`

This is where you integrate with existing corporate systems (ERP, CRM, IAM, ESB, etc.). The interface keeps the rest of the app strongly typed and isolated from vendor-specific details.

```ts
export interface CorporateUserRecord {
  id: string;
  email: string;
  displayName: string;
  department?: string;
}

export interface CorporateClient {
  getUserByEmail(email: string): Promise<CorporateUserRecord | null>;
}

export class HttpCorporateClient implements CorporateClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async getUserByEmail(email: string): Promise<CorporateUserRecord | null> {
    const url = new URL('/users', this.baseUrl);
    url.searchParams.set('email', email);

    const res = await fetch(url, {
      headers: {
        Authorization: `Bearer ${this.token}`,
        Accept: 'application/json'
      }
    });

    if (res.status === 404) return null;
    if (!res.ok) {
      throw new Error(`Corporate API error: ${res.status} ${res.statusText}`);
    }

    const data: unknown = await res.json();

    // Minimal runtime validation; can be replaced with zod schema
    if (
      typeof data === 'object' &&
      data !== null &&
      'id' in data &&
      'email' in data &&
      'displayName' in data
    ) {
      const record = data as Record<string, unknown>;
      return {
        id: String(record.id),
        email: String(record.email),
        displayName: String(record.displayName),
        department: typeof record.department === 'string' ? record.department : undefined
      };
    }

    throw new Error('Invalid corporate user payload');
  }
}
```

