## 10) Routes: `src/modules/users/user.routes.ts`

```ts
import { FastifyInstance } from 'fastify';
import { GetUserByEmailParamsSchema } from './user.schemas.js';
import { UserService } from './user.service.js';

export async function userRoutes(app: FastifyInstance) {
  const userService = new UserService(app.corporateClient);

  app.get('/users/:email', {
    schema: {
      params: {
        type: 'object',
        required: ['email'],
        properties: {
          email: { type: 'string', format: 'email' }
        }
      }
    }
  }, async (request, reply) => {
    const parsed = GetUserByEmailParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.badRequest('Invalid email parameter');
    }

    const user = await userService.getUserByEmail(parsed.data.email);

    if (!user) {
      return reply.notFound('User not found');
    }

    return reply.send(user);
  });
}
```

