```ts
import Fastify from 'fastify';
import sensible from '@fastify/sensible';
import envPlugin from './config/env.js';
import { logger } from './config/logger.js';
import { healthPlugin } from './plugins/health.js';
import { userRoutes } from './modules/users/user.routes.js';
import { HttpCorporateClient } from './integrations/corporateClient.js';

export async function buildApp() {
  const app = Fastify({
    logger
  });

  await app.register(sensible);
  await app.register(envPlugin);

  app.decorate('corporateClient', new HttpCorporateClient(
    app.config.CORPORATE_API_BASE_URL,
    app.config.CORPORATE_API_TOKEN
  ));

  await app.register(healthPlugin);
  await app.register(userRoutes);

  return app;
}

declare module 'fastify' {
  interface FastifyInstance {
    corporateClient: HttpCorporateClient;
  }
}
