## `src/integrations/corporate-crm.client.ts`

Example typed integration client with basic error mapping.

```ts
import { AppError } from "../errors/app-error.js";
import type {
  CorporateCrmCreateCustomerRequest,
  CorporateCrmCreateCustomerResponse
} from "./corporate-crm.types.js";

export interface CorporateCrmClient {
  createCustomer(
    input: CorporateCrmCreateCustomerRequest
  ): Promise<CorporateCrmCreateCustomerResponse>;
}

export class HttpCorporateCrmClient implements CorporateCrmClient {
  constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  async createCustomer(
    input: CorporateCrmCreateCustomerRequest
  ): Promise<CorporateCrmCreateCustomerResponse> {
    const res = await fetch(`${this.baseUrl}/customers`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.apiKey}`
      },
      body: JSON.stringify(input)
    });

    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new AppError(
        "CRM_INTEGRATION_FAILED",
        `Corporate CRM request failed with status ${res.status}`,
        502,
        { body }
      );
    }

    const json = (await res.json()) as unknown;

    if (
      typeof json !== "object" ||
      json === null ||
      !("externalId" in json) ||
      typeof (json as { externalId: unknown }).externalId !== "string"
    ) {
      throw new AppError(
        "CRM_INVALID_RESPONSE",
        "Corporate CRM returned an invalid response",
        502,
        json
      );
    }

    return { externalId: (json as { externalId: string }).externalId };
  }
}
```

