## `src/services/customer.service.ts`

Business logic lives here.

```ts
import { randomUUID } from "node:crypto";
import { AppError } from "../errors/app-error.js";
import type { Customer } from "../domain/customer.js";
import type { CorporateCrmClient } from "../integrations/corporate-crm.client.js";
import type { CreateCustomerRequest } from "../dto/customer.dto.js";

export interface CustomerRepository {
  save(customer: Customer): Promise<Customer>;
  findByEmail(email: string): Promise<Customer | null>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly customers = new Map<string, Customer>();

  async save(customer: Customer): Promise<Customer> {
    this.customers.set(customer.id, customer);
    return customer;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    for (const customer of this.customers.values()) {
      if (customer.email === email) return customer;
    }
    return null;
  }
}

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new AppError(
        "CUSTOMER_ALREADY_EXISTS",
        "A customer with this email already exists",
        409
      );
    }

    const crmResult = await this.crmClient.createCustomer({
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email
    });

    const customer: Customer = {
      id: randomUUID(),
      externalId: crmResult.externalId,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date()
    };

    return this.repository.save(customer);
  }
}
```

