        body: {
          type: "object",
          required: ["firstName", "lastName", "email"],
          properties: {
            firstName: { type: "string", minLength: 1, maxLength: 100 },
            lastName: { type: "string", minLength: 1, maxLength: 100 },
            email: { type: "string", format: "email", maxLength: 254 }
          }
        }
      }
    },
    async (request, reply) => {
      const parsed = createCustomerRequestSchema.safeParse(request.body);
      if (!parsed.success) {
        throw new AppError("VALIDATION_ERROR", "Invalid request body", 400, parsed.error.flatten());
      }

      const customer = await deps.customerService.createCustomer(parsed.data);

      return reply.code(201).send({
        id: customer.id,
        externalId: customer.externalId,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        createdAt: customer.createdAt.toISOString()
      });
    }
  );
}
