```ts
import Fastify from "fastify";
import { env } from "./config/env.js";
import { AppError } from "./errors/app-error.js";
import { HttpCorporateCrmClient } from "./integrations/corporate-crm.client.js";
import { customerRoutes } from "./routes/customer.routes.js";
import {
  CustomerService,
  InMemoryCustomerRepository
} from "./services/customer.service.js";
import { logger } from "./utils/logger.js";

export function buildApp() {
  const app = Fastify({ logger });

  const crmClient = new HttpCorporateCrmClient(
    env.CORP_CRM_BASE_URL,
    env.CORP_CRM_API_KEY
  );
  const repository = new InMemoryCustomerRepository();
  const customerService = new CustomerService(repository, crmClient);

  app.get("/health", async () => ({ status: "ok" }));

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message,
        details: error.details
      });
    }

    app.log.error(error);
    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
