## Service

### `src/modules/customers/customers.service.ts`

```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { CustomersRepository } from './customers.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerEntity } from './entities/customer.entity';
import { CrmClient } from '../integration/crm.client';
import { EventPublisher } from '../integration/event-publisher';

@Injectable()
export class CustomersService {
  constructor(
    private readonly repo: CustomersRepository,
    private readonly crmClient: CrmClient,
    private readonly eventPublisher: EventPublisher
  ) {}

  async create(dto: CreateCustomerDto): Promise<CustomerEntity> {
    const existing = await this.repo.findByEmail(dto.email);
    if (existing) {
      throw new ConflictException('Customer already exists for this email');
    }

    const created = await this.repo.createAndSave({
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email.toLowerCase(),
      corporateId: dto.corporateId ?? null,
      metadata: dto.metadata ?? null
    });

    await this.eventPublisher.publishCustomerCreated(created);

    // Optional synchronous integration with corporate CRM
    await this.crmClient.upsertCustomer(created);

    return created;
  }

  async getById(id: string): Promise<CustomerEntity> {
    const customer = await this.repo.findById(id);
    if (!customer) {
      throw new NotFoundException('Customer not found');
    }
    return customer;
  }
}
```

