## `src/modules/integration/crm.client.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ConfigService } from '@nestjs/config';
import { CustomerEntity } from '../customers/entities/customer.entity';

@Injectable()
export class CrmClient {
  private readonly logger = new Logger(CrmClient.name);
  private readonly client: AxiosInstance;

  constructor(private readonly config: ConfigService) {
    this.client = axios.create({
      baseURL: this.config.get<string>('crmBaseUrl'),
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        ...(this.config.get<string>('crmApiKey')
          ? { Authorization: `Bearer ${this.config.get<string>('crmApiKey')}` }
          : {})
      }
    });
  }

  async upsertCustomer(customer: CustomerEntity): Promise<void> {
    try {
      await this.client.post('/customers/upsert', {
        id: customer.id,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        corporateId: customer.corporateId,
        metadata: customer.metadata
      });
    } catch (error) {
      this.logger.error(`CRM upsert failed for customer ${customer.id}`, error as Error);
      // In a real enterprise setup:
      // - retry with backoff
      // - publish to dead-letter queue
      // - mark integration status in DB
      // - avoid failing the whole request if CRM is non-critical
    }
  }
}
```

