### `src/application/createCustomer.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Customer } from "../domain/customer.js";
import { ValidationError } from "../domain/errors.js";
import type { AuditClient, CrmClient, CustomerRepository } from "./ports.js";

export interface CreateCustomerInput {
  firstName: string;
  lastName: string;
  email: string;
  actorId?: string;
}

export interface CreateCustomerUseCase {
  execute(input: CreateCustomerInput): Promise<Customer>;
}

export function createCreateCustomerUseCase(deps: {
  repo: CustomerRepository;
  crm: CrmClient;
  audit: AuditClient;
}): CreateCustomerUseCase {
  return {
    async execute(input) {
      if (!input.firstName.trim() || !input.lastName.trim()) {
        throw new ValidationError("firstName and lastName are required");
      }
      if (!input.email.includes("@")) {
        throw new ValidationError("email must be valid");
      }

      const now = new Date();
      const customer: Customer = {
        id: randomUUID(),
        firstName: input.firstName.trim(),
        lastName: input.lastName.trim(),
        email: input.email.trim().toLowerCase(),
        createdAt: now,
        updatedAt: now
      };

      const saved = await deps.repo.create(customer);
      await deps.crm.syncCustomer(saved);
      await deps.audit.recordEvent({
        action: "CUSTOMER_CREATED",
        actorId: input.actorId,
        entityType: "Customer",
        entityId: saved.id,
        timestamp: new Date().toISOString(),
        metadata: { email: saved.email }
      });

      return saved;
    }
  };
}
```

### `src/application/getCustomer.ts`

```ts
import type { Customer } from "../domain/customer.js";
import { CustomerNotFoundError } from "../domain/errors.js";
import type { CustomerRepository } from "./ports.js";

export interface GetCustomerUseCase {
  execute(id: string): Promise<Customer>;
}

export function createGetCustomerUseCase(deps: {
  repo: CustomerRepository;
}): GetCustomerUseCase {
  return {
    async execute(id) {
      const customer = await deps.repo.findById(id);
      if (!customer) throw new CustomerNotFoundError(id);
      return customer;
    }
  };
}
