### `src/interfaces/http/handlers.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import type { CreateCustomerUseCase } from "../../application/createCustomer.js";
import type { GetCustomerUseCase } from "../../application/getCustomer.js";
import { createCustomerBodySchema, customerParamsSchema } from "./schemas.js";

export function buildHandlers(deps: {
  createCustomer: CreateCustomerUseCase;
  getCustomer: GetCustomerUseCase;
}) {
  return {
    async createCustomer(req: FastifyRequest, reply: FastifyReply) {
      const body = createCustomerBodySchema.parse(req.body);
      const actorId = req.user?.sub;

      const customer = await deps.createCustomer.execute({
        ...body,
        actorId
      });

      return reply.code(201).send(customer);
    },

    async getCustomer(req: FastifyRequest, reply: FastifyReply) {
      const params = customerParamsSchema.parse(req.params);
      const customer = await deps.getCustomer.execute(params.id);
      return reply.send(customer);
    }
  };
}
```

