## 12) App bootstrap

### `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { authPlugin } from "./infrastructure/auth/authPlugin.js";
import { registerRoutes } from "./interfaces/http/routes.js";
import { prismaCustomerRepository } from "./infrastructure/db/customerRepository.js";
import { crmClient } from "./infrastructure/corporate/crmClient.js";
import { auditClient } from "./infrastructure/corporate/auditClient.js";
import { createCreateCustomerUseCase } from "./application/createCustomer.js";
import { createGetCustomerUseCase } from "./application/getCustomer.js";

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  await app.register(sensible);
  await app.register(authPlugin);

  const createCustomer = createCreateCustomerUseCase({
    repo: prismaCustomerRepository,
    crm: crmClient,
    audit: auditClient
  });

  const getCustomer = createGetCustomerUseCase({
    repo: prismaCustomerRepository
  });

  await registerRoutes(app, {
    createCustomer,
    getCustomer
  });

  app.get("/health", async () => ({ status: "ok" }));

  return app;
}
```

