## 7) Service layer

### `src/services/entityService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { CreateEntityInput, EntityOutput } from "../schemas/entitySchemas.js";
import { CorporateSystemClient } from "../integrations/corporateSystemClient.js";

export class EntityService {
  constructor(private readonly corporateClient: CorporateSystemClient) {}

  async createEntity(input: CreateEntityInput): Promise<EntityOutput> {
    const now = new Date().toISOString();
    const corporateRecord = await this.corporateClient.createEntity(input.name);

    return {
      id: randomUUID(),
      name: corporateRecord.displayName,
      status: corporateRecord.lifecycleState,
      createdAt: now,
      updatedAt: now
    };
  }

  async getEntity(id: string): Promise<EntityOutput | null> {
    const record = await this.corporateClient.fetchEntityById(id);
    if (!record) return null;

    const now = new Date().toISOString();
    return {
      id: record.externalId,
      name: record.displayName,
      status: record.lifecycleState,
      createdAt: now,
