## 8) Controller layer

### `src/controllers/entityController.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { CreateEntitySchema } from "../schemas/entitySchemas.js";
import { EntityService } from "../services/entityService.js";

export class EntityController {
  constructor(private readonly service: EntityService) {}

  create = async (
    request: FastifyRequest<{ Body: unknown }>,
    reply: FastifyReply
  ) => {
    const parsed = CreateEntitySchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        details: parsed.error.flatten()
      });
    }

    const entity = await this.service.createEntity(parsed.data);
    return reply.status(201).send(entity);
  };

  getById = async (
    request: FastifyRequest<{ Params: { id: string } }>,
    reply: FastifyReply
  ) => {
    const entity = await this.service.getEntity(request.params.id);
    if (!entity) {
      return reply.status(404).send({ error: "NOT_FOUND" });
    }

    return reply.send(entity);
  };
}
```

