## 10) App bootstrap and dependency wiring

### `src/app.ts`

```ts
import Fastify from "fastify";
import helmet from "@fastify/helmet";
import cors from "@fastify/cors";
import { env } from "./config/env.js";
import { healthRoutes } from "./routes/health.js";
import { entityRoutes } from "./routes/entities.js";
import { CorporateSystemClient } from "./integrations/corporateSystemClient.js";
import { EntityService } from "./services/entityService.js";
import { EntityController } from "./controllers/entityController.js";

export async function buildApp() {
  const app = Fastify({
    logger: {
      level: env.LOG_LEVEL
    }
  });

  await app.register(helmet);
  await app.register(cors, { origin: true });

  const corporateClient = new CorporateSystemClient();
  const entityService = new EntityService(corporateClient);
  const entityController = new EntityController(entityService);

  app.decorate("diContainer", {
    entityController
  });

  await app.register(healthRoutes);
  await app.register(entityRoutes);

  app.setErrorHandler((error, _request, reply) => {
    app.log.error({ error }, "Unhandled error");
    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR"
    });
  });

  return app;
}
```

