Minimal corporate auth integration using JWT verification hook.

```ts
import type { FastifyInstance, FastifyRequest } from "fastify";

export async function registerCorporateAuth(app: FastifyInstance): Promise<void> {
  app.addHook("preHandler", async (request: FastifyRequest) => {
    if (request.url === "/health") return;

    try {
      await request.jwtVerify();
    } catch {
      throw app.httpErrors.unauthorized("Invalid or missing corporate token");
    }
  });
}
```

> This assumes JWTs are issued by your corporate identity platform.  
> In a real enterprise setup, you would validate issuer, audience, and possibly JWKS keys.

