## 9) `src/routes/health.ts`

```ts
import type { FastifyInstance } from "fastify";
import type { AppConfig, HealthResponse } from "../types/index.js";
import { CorporateClient } from "../services/corporateClient.js";

export async function healthRoutes(
  app: FastifyInstance,
  config: AppConfig
): Promise<void> {
  const corporateClient = new CorporateClient(config);

  app.get("/health", async (): Promise<HealthResponse> => {
    return {
      status: "ok",
      service: config.serviceName,
      timestamp: new Date().toISOString()
    };
  });

  app.get("/ready", async () => {
    const corporateStatus = await corporateClient.checkConnectivity();

    return {
      status: corporateStatus.reachable ? "ready" : "degraded",
      corporate: corporateStatus
    };
  });
}
