import { config } from "../config.js";
import { CustomerSchema, type Customer } from "../types/customer.js";

export class CorporateSystemClient {
  async getCustomerById(id: string): Promise<Customer | null> {
    const response = await fetch(`${config.CORPORATE_API_BASE_URL}/customers/${id}`, {
      headers: {
        Authorization: `Bearer ${config.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });

    if (response.status === 404) return null;
    if (!response.ok) {
      throw new Error(`Corporate API error: ${response.status}`);
    }

    const data: unknown = await response.json();
    return CustomerSchema.parse(data);
  }
}
```

