# 8) `src/routes/customers.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { pool } from "../db.js";
import { NotFoundError } from "../errors.js";

const CreateCustomerBodySchema = z.object({
  externalId: z.string().min(1),
  name: z.string().min(1),
  email: z.string().email()
});

const CustomerParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(app: FastifyInstance) {
  app.post(
    "/customers",
    {
      schema: {
        body: {
          type: "object",
          required: ["externalId", "name", "email"],
          properties: {
            externalId: { type: "string" },
            name: { type: "string" },
            email: { type: "string", format: "email" }
          },
          additionalProperties: false
        }
      }
    },
    async (request, reply) => {
      const body = CreateCustomerBodySchema.parse(request.body);

      const result = await pool.query(
        `INSERT INTO customers (external_id, name, email)
         VALUES ($1, $2, $3)
         RETURNING id, external_id, name, email, created_at`,
        [body.externalId, body.name, body.email]
      );

      const row = result.rows[0];
      return reply.code(201).send({
        id: row.id,
        externalId: row.external_id,
        name: row.name,
        email: row.email,
        createdAt: row.created_at.toISOString()
      });
    }
  );

  app.get(
    "/customers/:id",
    {
      schema: {
        params: {
          type: "object",
          required: ["id"],
          properties: {
            id: { type: "string", format: "uuid" }
          },
          additionalProperties: false
        }
      }
    },
    async (request, reply) => {
      const params = CustomerParamsSchema.parse(request.params);

      const result = await pool.query(
        `SELECT id, external_id, name, email, created_at
         FROM customers
         WHERE id = $1`,
        [params.id]
      );

      const row = result.rows[0];
      if (!row) throw new NotFoundError("Customer not found");

      return reply.send({
        id: row.id,
        externalId: row.external_id,
        name: row.name,
        email: row.email,
        createdAt: row.created_at.toISOString()
      });
    }
  );
}
```

