import { HttpCorporateSystemClient } from "../integrations/corporateSystem.js";

const service = new CustomerService(new HttpCorporateSystemClient());

export async function customerRoutes(app: FastifyInstance) {
  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const customer = await service.createCustomer(parsed.data);

    return reply.status(201).send({
      id: customer.id,
      externalId: customer.externalId,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  });

  app.get("/customers/:id", async (request, reply) => {
    const { id } = request.params as { id: string };
    const customer = await service.getCustomerById(id);

    if (!customer) {
      return reply.status(404).send({ error: "NotFound" });
    }

    return {
      id: customer.id,
      externalId: customer.externalId,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  });
}
