## 9) PostgreSQL implementation — `src/repositories/postgres.employee.repository.ts`

```ts
import type { Pool } from "pg";
import type { Employee, EmployeeId } from "../types.js";
import type { CreateEmployeeInput } from "../schemas/employee.schema.js";
import type { EmployeeRepository } from "./employee.repository.js";

export class PostgresEmployeeRepository implements EmployeeRepository {
  constructor(private readonly pool: Pool) {}

  async create(input: CreateEmployeeInput): Promise<Employee> {
    const now = new Date().toISOString();
    const id = crypto.randomUUID();

    await this.pool.query(
      `INSERT INTO employees (id, first_name, last_name, email, department, active, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
      [id, input.firstName, input.lastName, input.email, input.department, true, now, now]
    );

    return {
      id,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      department: input.department,
      active: true,
      createdAt: now,
      updatedAt: now
    };
  }

  async findById(id: EmployeeId): Promise<Employee | null> {
    const result = await this.pool.query(
      `SELECT id, first_name, last_name, email, department, active, created_at, updated_at
       FROM employees
       WHERE id = $1`,
      [id]
    );

    if (result.rowCount === 0) return null;

    const row = result.rows[0];
    return {
      id: row.id,
      firstName: row.first_name,
      lastName: row.last_name,
      email: row.email,
      department: row.department,
      active: row.active,
      createdAt: row.created_at.toISOString?.() ?? row.created_at,
      updatedAt: row.updated_at.toISOString?.() ?? row.updated_at
    };
  }
}
```

