export class HttpIdentityClient implements IdentityClient {
  constructor(private readonly baseUrl: string) {}

  async validateToken(token: string): Promise<{ subject: string; roles: string[] }> {
    const res = await fetch(`${this.baseUrl}/validate`, {
      headers: { Authorization: `Bearer ${token}` }
    });

    if (!res.ok) {
      throw new Error("Invalid corporate identity token");
    }

    return res.json() as Promise<{ subject: string; roles: string[] }>;
  }
}
