```ts
import { config } from "../config.js";
import { CustomerSchema, type Customer } from "../schemas/customer.js";
import { ExternalSystemError } from "../types/errors.js";

export class CorporateSystemClient {
  async getCustomerById(id: string): Promise<Customer | null> {
    const res = await fetch(`${config.CORPORATE_SYSTEM_BASE_URL}/customers/${encodeURIComponent(id)}`, {
      headers: {
        "Authorization": `Bearer ${config.CORPORATE_SYSTEM_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (res.status === 404) return null;
    if (!res.ok) {
      throw new ExternalSystemError(`Corporate system returned ${res.status}`);
    }

    const data = await res.json();
    return CustomerSchema.parse(data);
  }

  async syncCustomer(id: string): Promise<void> {
    const res = await fetch(`${config.CORPORATE_SYSTEM_BASE_URL}/customers/${encodeURIComponent(id)}/sync`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${config.CORPORATE_SYSTEM_API_KEY}`,
        "Content-Type": "application/json"
      }
    });

    if (!res.ok) {
      throw new ExternalSystemError(`Sync failed with status ${res.status}`);
    }
  }
}
```

