## 12) src/routes/customers.ts

```ts
import type { FastifyInstance } from "fastify";
import { CustomerIdSchema, SyncRequestSchema } from "../schemas/customer.js";
import { NotFoundError } from "../types/errors.js";

export async function customerRoutes(app: FastifyInstance) {
  app.get("/customers/:id", async (request, reply) => {
    const params = CustomerIdSchema.safeParse(request.params?.id);
    if (!params.success) {
      return reply.code(400).send({ error: "Invalid customer id" });
    }

    try {
      const customer = await app.customerService.getCustomer(params.data);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      throw err;
    }
  });

  app.post("/customers/sync", async (request, reply) => {
    const body = SyncRequestSchema.safeParse(request.body);
    if (!body.success) {
      return reply.code(400).send({ error: "Invalid request body", details: body.error.flatten() });
    }

    await app.customerService.syncCustomer(body.data.customerId);
    return reply.code(202).send({ status: "SYNC_REQUESTED", customerId: body.data.customerId });
  });
}
```

