export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  const client = new CorporateSystemClient();
  app.decorate("customerService", new CustomerService(client));

  app.setErrorHandler((err, _request, reply) => {
    if (err instanceof ExternalSystemError) {
      return reply.code(502).send({ error: "Upstream corporate system error" });
    }

    app.log.error(err);
    return reply.code(500).send({ error: "Internal server error" });
  });

  await app.register(healthRoutes);
  await app.register(customerRoutes);

  return app;
}
