# 11) src/middleware/auth.ts

JWT auth middleware with corporate IdP integration via JWKS.

```ts
import fp from "fastify-plugin";
import { createRemoteJWKSet, jwtVerify } from "jose";
import type { FastifyPluginAsync, FastifyRequest } from "fastify";
import { config } from "../config.js";
import type { UserClaims } from "../types.js";

declare module "fastify" {
  interface FastifyRequest {
    user?: UserClaims;
  }
}

const authPlugin: FastifyPluginAsync = async (fastify) => {
  const jwks = createRemoteJWKSet(new URL(config.JWT_JWKS_URL));

  fastify.decorateRequest("user", null);

  fastify.addHook("preHandler", async (request: FastifyRequest) => {
    if (request.url === "/health") return;

    const auth = request.headers.authorization;
    if (!auth?.startsWith("Bearer ")) {
      throw fastify.httpErrors.unauthorized("Missing Bearer token");
    }

    const token = auth.slice("Bearer ".length);

    const { payload } = await jwtVerify(token, jwks, {
      issuer: config.JWT_ISSUER,
      audience: config.JWT_AUDIENCE
    });

    request.user = {
      sub: String(payload.sub ?? ""),
      email: typeof payload.email === "string" ? payload.email : undefined,
      roles: Array.isArray(payload.roles) ? payload.roles.map(String) : undefined
    };

    if (!request.user.sub) {
      throw fastify.httpErrors.unauthorized("Invalid token subject");
    }
  });
};

export default fp(authPlugin);
```

