import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerSchema } from "../types.js";
import { CustomerService } from "../services/customerService.js";

const CreateCustomerRequestSchema = CustomerSchema;

export async function customerRoutes(app: FastifyInstance) {
  const service = new CustomerService(app.corporateClient);

  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerRequestSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    const customer = await service.createCustomer(parsed.data);
    return reply.status(201).send(customer);
  });

  app.get("/customers/health", async () => {
    return { status: "ok" };
  });
}
