```ts
import type { HealthResponse } from "../types/health.js";
import type { CorporateClient } from "../clients/corporateClient.js";

export class HealthService {
  constructor(
    private readonly serviceName: string,
    private readonly corporateClient: CorporateClient
  ) {}

  async getHealth(): Promise<HealthResponse> {
    let corporateStatus: "up" | "down" = "down";

    try {
      const ping = await this.corporateClient.ping();
      corporateStatus = ping.ok ? "up" : "down";
    } catch {
      corporateStatus = "down";
    }

    return {
      status: "ok",
      service: this.serviceName,
      timestamp: new Date().toISOString(),
      dependencies: {
        corporateSystem: corporateStatus
      }
    };
  }
}
```

