### `src/routes/employee.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CorporateHrClient } from "../integrations/corporateHrClient.js";
import { EmployeeService } from "../services/employeeService.js";
import { NotFoundError } from "../utils/errors.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function employeeRoutes(app: FastifyInstance) {
  const service = new EmployeeService(new CorporateHrClient());

  app.get("/employees/:id", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request parameters",
        details: parsed.error.flatten()
      });
    }

    try {
      const employee = await service.getEmployee(parsed.data.id);
      return reply.send(employee);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.status(404).send({ error: err.message });
      }
      throw err;
    }
  });
}
```

