## 7) `src/services/corporateClient.ts`

This is the integration layer for an existing corporate system.

```ts
import { request } from "undici";
import type { CorporateStatusResponse } from "../types/index.js";

export class CorporateClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async checkStatus(): Promise<CorporateStatusResponse> {
    try {
      const res = await request(`${this.baseUrl}/status`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${this.token}`,
          "Content-Type": "application/json"
        }
      });

      if (res.statusCode >= 200 && res.statusCode < 300) {
        return {
          system: "corporate-system",
          reachable: true,
          message: "Corporate system reachable"
        };
      }

      return {
        system: "corporate-system",
        reachable: false,
        message: `Corporate system returned HTTP ${res.statusCode}`
      };
    } catch (error) {
      return {
        system: "corporate-system",
        reachable: false,
        message: error instanceof Error ? error.message : "Unknown error"
      };
    }
  }
}
```

