## 9) `src/server.ts`

```ts
import Fastify from "fastify";
import { loadConfig } from "./config.js";
import { healthRoutes } from "./routes/health.js";
import { CorporateClient } from "./services/corporateClient.js";

const config = loadConfig();

declare module "fastify" {
  interface FastifyInstance {
    config: typeof config;
    corporateClient: CorporateClient;
  }
}

async function main() {
  const app = Fastify({
    logger: true
  });

  app.decorate("config", config);
  app.decorate(
    "corporateClient",
    new CorporateClient(config.CORPORATE_API_BASE_URL, config.CORPORATE_API_TOKEN)
  );

  await app.register(healthRoutes);

  app.get("/integration-check", async () => {
    return app.corporateClient.checkStatus();
  });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ error }, "Unhandled error");
    reply.status(500).send({
      error: "Internal Server Error"
    });
  });

  const port = config.PORT;
  await app.listen({ port, host: "0.0.0.0" });

  app.log.info(`Service started on port ${port}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

