import type { Employee, EmployeeId, CreateEmployeeInput } from "../types.js";

export interface EmployeeRepository {
  findById(id: EmployeeId): Promise<Employee | null>;
  create(input: CreateEmployeeInput): Promise<Employee>;
}

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly data = new Map<EmployeeId, Employee>();

  async findById(id: EmployeeId): Promise<Employee | null> {
    return this.data.get(id) ?? null;
  }

  async create(input: CreateEmployeeInput): Promise<Employee> {
    const id = crypto.randomUUID();
    const employee: Employee = {
      id,
      ...input,
      createdAt: new Date().toISOString()
    };
    this.data.set(id, employee);
    return employee;
  }
}
