```ts
import type { CreateEmployeeInput, Employee, EmployeeId } from "../types.js";
import type { EmployeeRepository } from "../repositories/employee.repository.js";
import type { IdentityService } from "./identity.service.js";
import type { AuditService } from "./audit.service.js";

export class EmployeeService {
  constructor(
    private readonly repo: EmployeeRepository,
    private readonly identity: IdentityService,
    private readonly audit: AuditService
  ) {}

  async getEmployee(id: EmployeeId): Promise<Employee | null> {
    return this.repo.findById(id);
  }

  async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const allowed = await this.identity.canCreateEmployee(input.email);
    if (!allowed) {
      throw new Error("Employee creation not allowed by identity policy");
    }

    const employee = await this.repo.create(input);

    await this.audit.log("employee.created", {
      employeeId: employee.id,
      email: employee.email,
      department: employee.department
    });

    return employee;
  }
}
