## 12) src/routes/employee.routes.ts

Uses Zod for strict request validation.

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { EmployeeService } from "../services/employee.service.js";

const createEmployeeSchema = z.object({
  firstName: z.string().min(1),
  lastName: z.string().min(1),
  email: z.string().email(),
  department: z.string().min(1)
});

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function employeeRoutes(app: FastifyInstance, service: EmployeeService) {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/employees/:id", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({ error: "Invalid employee id" });
    }

    const employee = await service.getEmployee(parsed.data.id);
    if (!employee) {
      return reply.status(404).send({ error: "Employee not found" });
    }

    return employee;
  });

  app.post("/employees", async (request, reply) => {
    const parsed = createEmployeeSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    try {
      const employee = await service.createEmployee(parsed.data);
      return reply.status(201).send(employee);
    } catch (err) {
      return reply.status(403).send({
        error: err instanceof Error ? err.message : "Forbidden"
      });
    }
  });
}
```

