import { request } from "undici";
import { env } from "../config/env.js";
import { CorporateCustomerResponseSchema } from "../schemas/customer.js";

export async function fetchCustomerFromCorporateSystem(customerId: string) {
  const url = new URL(`/customers/${encodeURIComponent(customerId)}`, env.CORPORATE_API_BASE_URL);

  const res = await request(url, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
      Accept: "application/json"
    }
  });

  if (res.statusCode === 404) {
    return null;
  }

  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw new Error(`Corporate system returned HTTP ${res.statusCode}`);
  }

  const body = (await res.body.json()) as unknown;
  return CorporateCustomerResponseSchema.parse(body);
}
```

