## 7) `Services/CustomerService.cs`
```csharp
using EnterpriseBackend.Data;
using EnterpriseBackend.DTOs;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _db;

    public CustomerService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<CustomerDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .OrderByDescending(c => c.CreatedUtc)
            .Select(c => new CustomerDto(c.Id, c.Name, c.Email, c.PhoneNumber, c.CreatedUtc, c.UpdatedUtc))
            .ToListAsync(cancellationToken);
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .Where(c => c.Id == id)
            .Select(c => new CustomerDto(c.Id, c.Name, c.Email, c.PhoneNumber, c.CreatedUtc, c.UpdatedUtc))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<CustomerDto> CreateAsync(string name, string email, string? phoneNumber, CancellationToken cancellationToken = default)
    {
        var entity = new Customer
        {
            Id = Guid.NewGuid(),
            Name = name.Trim(),
            Email = email.Trim(),
            PhoneNumber = phoneNumber?.Trim(),
            CreatedUtc = DateTime.UtcNow
        };

        _db.Customers.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        return new CustomerDto(entity.Id, entity.Name, entity.Email, entity.PhoneNumber, entity.CreatedUtc, entity.UpdatedUtc);
    }

    public async Task<bool> UpdateAsync(Guid id, string name, string email, string? phoneNumber, CancellationToken cancellationToken = default)
    {
        var entity = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
        if (entity is null) return false;

        entity.Name = name.Trim();
        entity.Email = email.Trim();
        entity.PhoneNumber = phoneNumber?.Trim();
        entity.UpdatedUtc = DateTime.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var entity = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
        if (entity is null) return false;

        _db.Customers.Remove(entity);
        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }
}
```

