using Enterprise.Backend.Api.Data;
using Enterprise.Backend.Api.Data.Entities;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Api.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<Employee> CreateAsync(Employee employee, CancellationToken cancellationToken)
    {
        employee.CreatedAt = DateTimeOffset.UtcNow;
        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);
        return employee;
    }

    public async Task<Employee?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        return await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<Employee>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await _db.Employees
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync(cancellationToken);
    }
}
