            return BadRequest("OrderNumber is required.");

        if (string.IsNullOrWhiteSpace(request.CustomerName))
            return BadRequest("CustomerName is required.");

        var created = await _orderService.CreateAsync(request, cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerName}", created.Id, created.CustomerName);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
