```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<EmployeeResponse> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken)
    {
        var exists = await _db.Employees.AnyAsync(e => e.Email == request.Email, cancellationToken);
        if (exists)
            throw new InvalidOperationException("An employee with this email already exists.");

        var entity = new Employee
        {
            FirstName = request.FirstName.Trim(),
            LastName = request.LastName.Trim(),
            Email = request.Email.Trim().ToLowerInvariant()
        };

        _db.Employees.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        return Map(entity);
    }

    public async Task<EmployeeResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var entity = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        return entity is null ? null : Map(entity);
    }

    public async Task<IReadOnlyList<EmployeeResponse>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await _db.Employees
            .OrderByDescending(e => e.CreatedUtc)
            .Select(e => new EmployeeResponse
            {
                Id = e.Id,
                FullName = e.FirstName + " " + e.LastName,
                Email = e.Email,
                CreatedUtc = e.CreatedUtc
            })
            .ToListAsync(cancellationToken);
    }

    private static EmployeeResponse Map(Employee entity) => new()
    {
        Id = entity.Id,
        FullName = $"{entity.FirstName} {entity.LastName}",
        Email = entity.Email,
        CreatedUtc = entity.CreatedUtc
    };
}
