# 6) `Controllers/EmployeesController.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class EmployeesController : ControllerBase
{
    private readonly AppDbContext _db;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(AppDbContext db, ILogger<EmployeesController> logger)
    {
        _db = db;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Employee>>> GetAll()
    {
        var employees = await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync();

        return Ok(employees);
    }

    [HttpGet("{id:int}")]
    public async Task<ActionResult<Employee>> GetById(int id)
    {
        var employee = await _db.Employees.FindAsync(id);

        if (employee is null)
            return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public async Task<ActionResult<Employee>> Create([FromBody] Employee employee)
    {
        if (string.IsNullOrWhiteSpace(employee.Email))
            return BadRequest("Email is required.");

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync();

        _logger.LogInformation("Created employee {EmployeeId}", employee.Id);

        return CreatedAtAction(nameof(GetById), new { id = employee.Id }, employee);
    }

    [HttpPut("{id:int}")]
    public async Task<IActionResult> Update(int id, [FromBody] Employee updated)
    {
        var employee = await _db.Employees.FindAsync(id);
        if (employee is null)
            return NotFound();

        employee.FirstName = updated.FirstName;
        employee.LastName = updated.LastName;
        employee.Email = updated.Email;

        await _db.SaveChangesAsync();

        _logger.LogInformation("Updated employee {EmployeeId}", id);

        return NoContent();
    }

    [HttpDelete("{id:int}")]
    public async Task<IActionResult> Delete(int id)
    {
        var employee = await _db.Employees.FindAsync(id);
        if (employee is null)
            return NotFound();

        _db.Employees.Remove(employee);
        await _db.SaveChangesAsync();

        _logger.LogInformation("Deleted employee {EmployeeId}", id);

        return NoContent();
    }
}
