using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly EnterpriseDbContext _db;

    public CustomerService(EnterpriseDbContext db)
    {
        _db = db;
    }

    public async Task<Customer> CreateAsync(string name, string email, CancellationToken ct = default)
    {
        var customer = new Customer
        {
            Name = name.Trim(),
            Email = email.Trim().ToLowerInvariant()
        };

        _db.Customers.Add(customer);
        await _db.SaveChangesAsync(ct);

        return customer;
    }

