## 5) Application service

### `Enterprise.Backend.Application/Services/EmployeeService.cs`
```csharp
using Enterprise.Backend.Api.Models;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;

namespace Enterprise.Backend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly IEmployeeRepository _repository;

    public EmployeeService(IEmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        return employee is null ? null : Map(employee);
    }

    public async Task<List<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _repository.GetAllAsync(cancellationToken);
        return employees.Select(Map).ToList();
    }

    public async Task<EmployeeDto> CreateAsync(EmployeeDto dto, CancellationToken cancellationToken = default)
    {
        var employee = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = dto.EmployeeNumber,
            FirstName = dto.FirstName,
            LastName = dto.LastName,
            Email = dto.Email,
            CreatedAt = DateTimeOffset.UtcNow
        };

        var created = await _repository.AddAsync(employee, cancellationToken);
        return Map(created);
    }

    public async Task<bool> UpdateAsync(Guid id, EmployeeDto dto, CancellationToken cancellationToken = default)
    {
        var existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null) return false;

        existing.EmployeeNumber = dto.EmployeeNumber;
        existing.FirstName = dto.FirstName;
        existing.LastName = dto.LastName;
        existing.Email = dto.Email;
        existing.UpdatedAt = DateTimeOffset.UtcNow;

        await _repository.UpdateAsync(existing, cancellationToken);
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null) return false;

        await _repository.DeleteAsync(existing, cancellationToken);
        return true;
    }

    private static EmployeeDto Map(Employee employee) => new()
    {
        Id = employee.Id,
        EmployeeNumber = employee.EmployeeNumber,
        FirstName = employee.FirstName,
        LastName = employee.LastName,
        Email = employee.Email
    };
}
