        => _db.Employees.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

    public Task<List<Employee>> GetAllAsync(CancellationToken cancellationToken = default)
        => _db.Employees.AsNoTracking().OrderBy(x => x.LastName).ToListAsync(cancellationToken);

    public async Task<Employee> AddAsync(Employee employee, CancellationToken cancellationToken = default)
    {
        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);
        return employee;
    }

    public async Task UpdateAsync(Employee employee, CancellationToken cancellationToken = default)
    {
        _db.Employees.Update(employee);
        await _db.SaveChangesAsync(cancellationToken);
    }

    public async Task DeleteAsync(Employee employee, CancellationToken cancellationToken = default)
    {
        _db.Employees.Remove(employee);
        await _db.SaveChangesAsync(cancellationToken);
    }
}
