## 4.4 Application service implementation

**`src/EnterpriseBackend.Application/WorkItems/WorkItemService.cs`**
```csharp
using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Domain.Entities;

namespace EnterpriseBackend.Application.WorkItems;

public class WorkItemService : IWorkItemService
{
    private readonly IWorkItemRepository _repository;

    public WorkItemService(IWorkItemRepository repository)
    {
        _repository = repository;
    }

    public async Task<WorkItemDto> CreateAsync(CreateWorkItemRequest request, CancellationToken cancellationToken)
    {
        var item = new WorkItem(request.Title, request.Description);

        await _repository.AddAsync(item, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return ToDto(item);
    }

    public async Task<WorkItemDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        return item is null ? null : ToDto(item);
    }

    public async Task<IReadOnlyList<WorkItemDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        var items = await _repository.GetAllAsync(cancellationToken);
        return items.Select(ToDto).ToList();
    }

    public async Task<bool> CompleteAsync(Guid id, CancellationToken cancellationToken)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        if (item is null) return false;

        item.MarkComplete();
        await _repository.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static WorkItemDto ToDto(WorkItem item) =>
        new(item.Id, item.Title, item.Description, item.IsCompleted, item.CreatedUtc, item.CompletedUtc);
}
```

