using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Persistence;

public class WorkItemRepository : IWorkItemRepository
{
    private readonly AppDbContext _db;

    public WorkItemRepository(AppDbContext db)
    {
        _db = db;
    }

    public async Task<WorkItem?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<WorkItem>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems.OrderByDescending(x => x.CreatedAt).ToListAsync(cancellationToken);
    }

    public async Task AddAsync(WorkItem workItem, CancellationToken cancellationToken = default)
    {
        await _db.WorkItems.AddAsync(workItem, cancellationToken);
        await _db.SaveChangesAsync(cancellationToken);
    }

    public async Task UpdateAsync(WorkItem workItem, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Update(workItem);
        await _db.SaveChangesAsync(cancellationToken);
    }

    public async Task DeleteAsync(WorkItem workItem, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Remove(workItem);
        await _db.SaveChangesAsync(cancellationToken);
    }
}
