## 4.3 Service implementation

### `EnterpriseBackend.Application/WorkItems/WorkItemService.cs`

```csharp
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.WorkItems;

public class WorkItemService : IWorkItemService
{
    private readonly AppDbContext _db;

    public WorkItemService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<WorkItemDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await Task.FromResult(_db.WorkItems.Select(MapToDto).AsEnumerable());
    }

    public async Task<WorkItemDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _db.WorkItems.FindAsync([id], cancellationToken);
        return item is null ? null : MapToDto(item);
    }

    public async Task<WorkItemDto> CreateAsync(CreateWorkItemRequest request, CancellationToken cancellationToken = default)
    {
        var entity = new WorkItem
        {
            Title = request.Title,
            Description = request.Description
        };

        _db.WorkItems.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        return MapToDto(entity);
    }

    public async Task<bool> MarkCompletedAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _db.WorkItems.FindAsync([id], cancellationToken);
        if (item is null) return false;

        item.IsCompleted = true;
        item.CompletedAt = DateTimeOffset.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static WorkItemDto MapToDto(WorkItem item) => new()
    {
        Id = item.Id,
        Title = item.Title,
        Description = item.Description,
        IsCompleted = item.IsCompleted,
        CreatedAt = item.CreatedAt,
        CompletedAt = item.CompletedAt
    };
}
```

