## `Application/Employees/EmployeeService.cs`
```csharp
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.Employees;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _db.Employees.FindAsync([id], cancellationToken);
        return employee is null
            ? null
            : new EmployeeDto(employee.Id, employee.EmployeeNumber, employee.DisplayName, employee.Email);
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .Select(e => new EmployeeDto(e.Id, e.EmployeeNumber, e.DisplayName, e.Email))
            .ToListAsync(cancellationToken);
    }

    public async Task<EmployeeDto> CreateAsync(string employeeNumber, string displayName, string email, CancellationToken cancellationToken = default)
    {
        var employee = new Employee
        {
            EmployeeNumber = employeeNumber,
            DisplayName = displayName,
            Email = email
        };

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);

        return new EmployeeDto(employee.Id, employee.EmployeeNumber, employee.DisplayName, employee.Email);
    }
}
