## `Application/Services/WorkItemService.cs`
```csharp
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Contracts.WorkItems;
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Persistence;

namespace Enterprise.Backend.Application.Services;

public class WorkItemService : IWorkItemService
{
    private readonly AppDbContext _db;

    public WorkItemService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<WorkItemResponse> CreateAsync(CreateWorkItemRequest request, CancellationToken ct = default)
    {
        var entity = new WorkItem
        {
            Title = request.Title,
            Description = request.Description
        };

        _db.WorkItems.Add(entity);
        await _db.SaveChangesAsync(ct);

        return Map(entity);
    }

    public async Task<WorkItemResponse?> GetByIdAsync(Guid id, CancellationToken ct = default)
    {
        var entity = await _db.WorkItems.FindAsync([id], ct);
        return entity is null ? null : Map(entity);
    }

    public async Task<IEnumerable<WorkItemResponse>> GetAllAsync(CancellationToken ct = default)
    {
        var items = await _db.WorkItems
            .OrderByDescending(x => x.CreatedUtc)
            .ToListAsync(ct);

        return items.Select(Map);
    }

    private static WorkItemResponse Map(WorkItem entity) => new()
    {
        Id = entity.Id,
        Title = entity.Title,
        Description = entity.Description,
        Status = entity.Status,
        CreatedUtc = entity.CreatedUtc,
        UpdatedUtc = entity.UpdatedUtc
    };
}
```

