```csharp
using Enterprise.Backend.Application.DTOs;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeDto dto, CancellationToken cancellationToken = default)
    {
        var employee = new Employee
        {
            FirstName = dto.FirstName.Trim(),
            LastName = dto.LastName.Trim(),
            Email = dto.Email.Trim().ToLowerInvariant()
        };

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);

        return new EmployeeDto(employee.Id, employee.FirstName, employee.LastName, employee.Email, employee.IsActive);
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _db.Employees
            .AsNoTracking()
            .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

        return employee is null
            ? null
            : new EmployeeDto(employee.Id, employee.FirstName, employee.LastName, employee.Email, employee.IsActive);
    }

    public async Task<IEnumerable<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .Select(e => new EmployeeDto(e.Id, e.FirstName, e.LastName, e.Email, e.IsActive))
            .ToListAsync(cancellationToken);
    }
}
