public class TicketService : ITicketService
{
    private readonly ITicketRepository _repository;

    public TicketService(ITicketRepository repository)
    {
        _repository = repository;
    }

    public async Task<TicketResponse> CreateAsync(CreateTicketRequest request, CancellationToken cancellationToken = default)
    {
        var ticket = new Ticket
        {
            Title = request.Title,
            Description = request.Description
        };

        await _repository.AddAsync(ticket, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return new TicketResponse(ticket.Id, ticket.Title, ticket.Description, ticket.Status, ticket.CreatedAt);
    }

    public async Task<TicketResponse?> GetAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var ticket = await _repository.GetByIdAsync(id, cancellationToken);
        if (ticket is null) return null;

        return new TicketResponse(ticket.Id, ticket.Title, ticket.Description, ticket.Status, ticket.CreatedAt);
    }
}
