## `Services/EmployeeService.cs`

```csharp
using Enterprise.BackendService.Data;
using Enterprise.BackendService.Data.Entities;
using Enterprise.BackendService.Models;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.BackendService.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.FullName)
            .Select(e => new EmployeeDto
            {
                Id = e.Id,
                EmployeeNumber = e.EmployeeNumber,
                FullName = e.FullName,
                Department = e.Department,
                CreatedAt = e.CreatedAt
            })
            .ToListAsync(cancellationToken);
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .Where(e => e.Id == id)
            .Select(e => new EmployeeDto
            {
                Id = e.Id,
                EmployeeNumber = e.EmployeeNumber,
                FullName = e.FullName,
                Department = e.Department,
                CreatedAt = e.CreatedAt
            })
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        var entity = new Employee
        {
            EmployeeNumber = request.EmployeeNumber,
            FullName = request.FullName,
            Department = request.Department
        };

        _db.Employees.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        return new EmployeeDto
        {
            Id = entity.Id,
            EmployeeNumber = entity.EmployeeNumber,
            FullName = entity.FullName,
            Department = entity.Department,
            CreatedAt = entity.CreatedAt
        };
    }
}
```

