using Microsoft.EntityFrameworkCore;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<Employee?> GetByIdAsync(Guid id)
        => await _db.Employees.FirstOrDefaultAsync(e => e.Id == id);

    public async Task<IEnumerable<Employee>> GetAllAsync()
        => await _db.Employees.OrderBy(e => e.LastName).ToListAsync();

    public async Task<Employee> CreateAsync(Employee employee)
    {
        employee.Id = Guid.NewGuid();
        employee.CreatedUtc = DateTime.UtcNow;

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync();

        return employee;
    }
}
```

