### Service implementation

```csharp
using Enterprise.Backend.Application.DTOs;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Repositories;

namespace Enterprise.Backend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly ICustomerRepository _repository;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(ICustomerRepository repository, ILogger<CustomerService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var customer = await _repository.GetByIdAsync(id, cancellationToken);
        return customer is null ? null : new CustomerDto(customer.Id, customer.Name, customer.Email);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerDto request, CancellationToken cancellationToken)
    {
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            Name = request.Name,
            Email = request.Email
        };

        await _repository.AddAsync(customer, cancellationToken);

        _logger.LogInformation("Created customer {CustomerId}", customer.Id);

        return new CustomerDto(customer.Id, customer.Name, customer.Email);
    }
}
```

