# 8) Controller: `Controllers/ItemsController.cs`

```csharp
using EnterpriseBackend.Api.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class ItemsController : ControllerBase
{
    private readonly IItemService _service;
    private readonly ILogger<ItemsController> _logger;

    public ItemsController(IItemService service, ILogger<ItemsController> logger)
    {
        _service = service;
        _logger = logger;
    }

    [HttpGet]
    public IActionResult GetAll()
    {
        _logger.LogInformation("Fetching all items");
        return Ok(_service.GetAll());
    }

    [HttpGet("{id:guid}")]
    public IActionResult GetById(Guid id)
    {
        var item = _service.GetById(id);
        return item is null ? NotFound() : Ok(item);
    }

    [HttpPost]
    public IActionResult Create([FromBody] CreateItemRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name))
            return BadRequest("Name is required.");

        var item = _service.Create(request.Name);
        _logger.LogInformation("Created item {ItemId}", item.Id);

        return CreatedAtAction(nameof(GetById), new { id = item.Id }, item);
    }

    public record CreateItemRequest(string Name);
}
```

