Below is a solid high-performance **Node.js** web server example using **Fastify** (fast, low overhead, good concurrency handling). It includes:

- async request handling
- connection keep-alive
- graceful shutdown
- basic health endpoint
- optional clustering to use multiple CPU cores

## Install
```bash
npm init -y
npm install fastify
```

## `server.js`
```js
'use strict';

const cluster = require('cluster');
const os = require('os');
const fastifyFactory = require('fastify');

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const WORKERS = process.env.WORKERS ? Number(process.env.WORKERS) : os.cpus().length;

function buildServer() {
  const fastify = fastifyFactory({
    logger: false,
    trustProxy: true,
    connectionTimeout: 10_000,
    keepAliveTimeout: 72_000,
    bodyLimit: 1_048_576, // 1 MB
  });

  fastify.get('/health', async () => {
    return { status: 'ok', ts: Date.now() };
  });

  fastify.get('/', async (request, reply) => {
    reply.header('content-type', 'application/json');
    return {
      message: 'Hello, world!',
      worker: process.pid,
    };
  });

  fastify.post('/echo', async (request, reply) => {
    return {
      worker: process.pid,
      received: request.body,
    };
  });

  fastify.get('/compute', async (request, reply) => {
    const n = Number(request.query.n || 100000);
    let sum = 0;
    for (let i = 0; i < n; i++) sum += i;
    return { n, sum, worker: process.pid };
  });

  async function start() {
    try {
      await fastify.listen({ port: PORT, host: HOST });
      console.log(`Worker ${process.pid} listening on http://${HOST}:${PORT}`);
    } catch (err) {
      console.error(err);
      process.exit(1);
    }
  }

  async function shutdown(signal) {
    console.log(`Worker ${process.pid} received ${signal}, shutting down...`);
    try {
      await fastify.close();
      process.exit(0);
    } catch (err) {
      console.error('Shutdown error:', err);
      process.exit(1);
    }
  }

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));

  start();
}

if (cluster.isPrimary) {
  console.log(`Primary ${process.pid} starting ${WORKERS} workers...`);

  for (let i = 0; i < WORKERS; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} exited (${signal || code}). Restarting...`);
    cluster.fork();
  });

  process.on('SIGINT', () => {
    console.log('Primary shutting down...');
    for (const id in cluster.workers) {
      cluster.workers[id].kill('SIGTERM');
    }
    setTimeout(() => process.exit(0), 5000).unref();
  });

  process.on('SIGTERM', () => {
    console.log('Primary shutting down...');
    for (const id in cluster.workers) {
      cluster.workers[id].kill('SIGTERM');
    }
    setTimeout(() => process.exit(0), 5000).unref();
  });
} else {
  buildServer();
}
```

