Below is a solid **high-performance async web server** example in **Rust** using **Tokio**. It’s designed to handle many concurrent connections efficiently with non-blocking I/O, connection limits, timeouts, and keep-alive support.

## `Cargo.toml`
```toml
[package]
name = "high_perf_web_server"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1", features = ["full"] }
bytes = "1"
httparse = "1"
```

## `src/main.rs`
```rust
use bytes::BytesMut;
use httparse::Request;
use std::{
    io,
    net::SocketAddr,
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    },
    time::Duration,
};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
    sync::Semaphore,
    time::timeout,
};

const MAX_CONNECTIONS: usize = 100_000;
const READ_TIMEOUT_SECS: u64 = 5;
const WRITE_TIMEOUT_SECS: u64 = 5;
const MAX_REQUEST_SIZE: usize = 16 * 1024;

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> io::Result<()> {
    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    let listener = TcpListener::bind(addr).await?;
    println!("Listening on http://{}", addr);

    let semaphore = Arc::new(Semaphore::new(MAX_CONNECTIONS));
    let active_connections = Arc::new(AtomicUsize::new(0));

    loop {
        let (socket, peer) = listener.accept().await?;
        let permit = match semaphore.clone().try_acquire_owned() {
            Ok(p) => p,
            Err(_) => {
                // Too many concurrent connections; drop new ones quickly.
                eprintln!("Rejecting connection from {}: server overloaded", peer);
                continue;
            }
        };

        let active_connections = active_connections.clone();
        active_connections.fetch_add(1, Ordering::Relaxed);

        tokio::spawn(async move {
            let _permit = permit; // released when task ends
            if let Err(e) = handle_connection(socket).await {
                eprintln!("Connection error from {}: {}", peer, e);
            }
            active_connections.fetch_sub(1, Ordering::Relaxed);
        });
    }
}

async fn handle_connection(mut stream: TcpStream) -> io::Result<()> {
    stream.set_nodelay(true)?;

    let mut buf = BytesMut::with_capacity(8 * 1024);

    loop {
        // Read request with timeout
        let n = match timeout(
            Duration::from_secs(READ_TIMEOUT_SECS),
            stream.read_buf(&mut buf),
        )
        .await
        {
            Ok(Ok(0)) => return Ok(()), // client closed
            Ok(Ok(n)) => n,
            Ok(Err(e)) => return Err(e),
            Err(_) => return Err(io::Error::new(io::ErrorKind::TimedOut, "read timeout")),
        };

        if n == 0 {
            return Ok(());
        }

        if buf.len() > MAX_REQUEST_SIZE {
            write_response(&mut stream, 413, "Payload Too Large", "Request too large").await?;
            return Ok(());
        }

        // Parse HTTP request
        let mut headers = [httparse::EMPTY_HEADER; 32];
        let mut req = Request::new(&mut headers);

        match req.parse(&buf) {
            Ok(httparse::Status::Complete(body_start)) => {
                let method = req.method.unwrap_or("");
                let path = req.path.unwrap_or("/");

                let (status, status_text, body) = route(method, path);

                write_response(&mut stream, status, status_text, body).await?;

                // Remove consumed bytes and continue for keep-alive requests
                buf.advance(body_start);

                // Very simple keep-alive handling:
                // close after one response for simplicity in this example.
                return Ok(());
            }
            Ok(httparse::Status::Partial) => {
                // Need more data
                if buf.len() == buf.capacity() {
                    buf.reserve(8 * 1024);
                }
                continue;
            }
            Err(_) => {
                write_response(&mut stream, 400, "Bad Request", "Invalid HTTP request").await?;
                return Ok(());
            }
        }
    }
}

fn route(method: &str, path: &str) -> (u16, &'static str, &'static str) {
    match (method, path) {
        ("GET", "/") => (200, "OK", "Hello from a high-performance Rust server!\n"),
        ("GET", "/health") => (200, "OK", "ok\n"),
        ("GET", "/metrics") => (200, "OK", "requests_total 1\n"),
        _ => (404, "Not Found", "404 page not found\n"),
    }
}

async fn write_response(
    stream: &mut TcpStream,
    status: u16,
    status_text: &str,
    body: &str,
) -> io::Result<()> {
    let response = format!(
        "HTTP/1.1 {} {}\r\n\
         Content-Type: text/plain; charset=utf-8\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\
         \r\n\
         {}",
        status,
        status_text,
        body.len(),
        body
    );

    timeout(
        Duration::from_secs(WRITE_TIMEOUT_SECS),
        stream.write_all(response.as_bytes()),
    )
    .await
    .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "write timeout"))??;

    Ok(())
}
```

## Notes on performance
- **Tokio async runtime**: handles many concurrent sockets efficiently.
- **Semaphore**: caps concurrent connections to avoid overload.
- **Timeouts**: protects against slow clients.
- **`set_nodelay(true)`**: reduces latency for small responses.
- **Minimal allocations**: uses `BytesMut` for buffered reads.

