use std::{convert::Infallible, net::SocketAddr, time::Instant};

use bytes::Bytes;
use http_body_util::Full;
use hyper::{
    body::Incoming,
    service::service_fn,
    Request, Response, StatusCode,
};
use hyper_util::{
    rt::TokioIo,
    server::conn::auto::Builder as AutoBuilder,
};
use tokio::net::TcpListener;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    let listener = TcpListener::bind(addr).await.unwrap();

    println!("Listening on http://{addr}");

    loop {
        let (stream, peer_addr) = match listener.accept().await {
            Ok(v) => v,
            Err(e) => {
                eprintln!("accept error: {e}");
                continue;
            }
        };

        tokio::spawn(async move {
            let io = TokioIo::new(stream);

            let service = service_fn(move |req: Request<Incoming>| async move {
                handle_request(req, peer_addr).await
            });

            let builder = AutoBuilder::new(hyper_util::rt::TokioExecutor::new());

            if let Err(err) = builder.serve_connection_with_upgrades(io, service).await {
                eprintln!("connection error from {peer_addr}: {err}");
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let start = Instant::now();

    let response = match req.uri().path() {
        "/" => Response::new(Full::new(Bytes::from_static(b"Hello, world!"))),

        "/health" => Response::new(Full::new(Bytes::from_static(b"OK"))),

        "/echo" => {
            let msg = format!("You hit /echo from {peer_addr}\n");
            Response::new(Full::new(Bytes::from(msg)))
        }

        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    let elapsed = start.elapsed();
    println!(
        "{} {} from {} in {:?}",
        req.method(),
        req.uri().path(),
        peer_addr,
        elapsed
    );

    Ok(response)
}
