use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::TokioExecutor;
use hyper_util::server::conn::auto::Builder as AutoBuilder;
use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::net::TcpListener;
use tokio::signal;
use tokio::time::{sleep, Duration};

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
        println!("Shutdown signal received");
    };

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            _ = &mut shutdown => {
                break;
            }
            accept_result = listener.accept() => {
                let (stream, peer_addr) = match accept_result {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("accept error: {}", e);
                        continue;
                    }
                };

                tokio::spawn(async move {
                    let service = service_fn(move |req: Request<Incoming>| {
                        handle_request(req, peer_addr)
                    });

                    let io = hyper_util::rt::TokioIo::new(stream);
                    let builder = AutoBuilder::new(TokioExecutor::new());

                    if let Err(e) = builder.serve_connection(io, service).await {
                        eprintln!("connection error ({}): {}", peer_addr, e);
                    }
                });
            }
        }
    }

    println!("Server shut down cleanly");
    Ok(())
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let path = req.uri().path();

    let response = match path {
        "/" => text_response("Hello from a high-performance Rust server!\n"),
        "/health" => text_response("OK\n"),
        "/slow" => {
            // Example of a non-blocking delay; doesn't block the runtime thread.
            sleep(Duration::from_millis(100)).await;
            text_response("Slow endpoint complete\n")
        }
        _ => not_found_response(),
    };

    println!("{} -> {} {}", peer_addr, req.method(), path);
    Ok(response)
}

fn text_response(body: &str) -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(body.to_owned())))
        .unwrap()
}

fn not_found_response() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from("404 Not Found\n")))
        .unwrap()
}
```

