	jobs    chan Job
	results chan Result
	wg      sync.WaitGroup
}

func NewWorkerPool(workerCount int, queueSize int) *WorkerPool {
	wp := &WorkerPool{
		jobs:    make(chan Job, queueSize),
		results: make(chan Result, queueSize),
	}
	wp.wg.Add(workerCount)

	for i := 0; i < workerCount; i++ {
		go func(workerID int) {
			defer wp.wg.Done()
			for job := range wp.jobs {
				// Simulate CPU-bound or expensive work
				time.Sleep(10 * time.Millisecond)

				wp.results <- Result{
					JobID: job.ID,
					Value: fmt.Sprintf("worker=%d processed=%s", workerID, job.Data),
				}
			}
		}(i)
	}

	// Close results when workers exit
	go func() {
		wp.wg.Wait()
		close(wp.results)
	}()

	return wp
}

func (wp *WorkerPool) Submit(job Job) {
	wp.jobs <- job
}

func (wp *WorkerPool) Close() {
	close(wp.jobs)
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s %v", r.RemoteAddr, r.Method, r.URL.Path, time.Since(start))
	})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(`{"status":"ok"}`))
}

func workHandler(pool *WorkerPool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Simple request ID
		jobID := int(time.Now().UnixNano())

		data := r.URL.Query().Get("data")
		if data == "" {
			data = "default"
		}

		select {
		case pool.jobs <- Job{ID: jobID, Data: data}:
			// Wait for a result from the shared results channel.
			// In a real system, use per-request response channels to avoid cross-talk.
			select {
			case res := <-pool.results:
				w.Header().Set("Content-Type", "application/json")
				_, _ = fmt.Fprintf(w, `{"job_id":%d,"result":%q}`, res.JobID, res.Value)
			case <-r.Context().Done():
				http.Error(w, "request canceled", http.StatusRequestTimeout)
			case <-time.After(2 * time.Second):
				http.Error(w, "timeout", http.StatusGatewayTimeout)
			}

		default:
			http.Error(w, "server busy", http.StatusServiceUnavailable)
		}
	}
}

func main() {
	// Tune runtime for available CPUs
	runtime.GOMAXPROCS(runtime.NumCPU())

	port := 8080
	if p := os.Getenv("PORT"); p != "" {
		if v, err := strconv.Atoi(p); err == nil {
			port = v
		}
	}

	workerCount := runtime.NumCPU() * 4
	queueSize := 10000

	pool := NewWorkerPool(workerCount, queueSize)
	defer pool.Close()

	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/work", workHandler(pool))

	server := &http.Server{
		Addr:              fmt.Sprintf(":%d", port),
		Handler:           loggingMiddleware(mux),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20, // 1 MB
	}

	// Start server
	go func() {
		log.Printf("listening on :%d with %d workers", port, workerCount)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("server error: %v", err)
		}
	}()

	// Graceful shutdown on SIGINT/SIGTERM
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	log.Println("shutting down...")

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Printf("shutdown error: %v", err)
	}

	log.Println("server stopped")
}
