use std::{convert::Infallible, net::SocketAddr, sync::Arc};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::TokioExecutor;
use hyper_util::server::conn::auto::Builder as AutoBuilder;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;
    println!("Listening on http://{}", addr);

    let builder = Arc::new(AutoBuilder::new(TokioExecutor::new()));

    loop {
        tokio::select! {
            biased;

            _ = shutdown_signal() => {
                println!("Shutdown signal received.");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, peer_addr) = match accept_result {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("Accept error: {}", e);
                        continue;
                    }
                };

                let builder = builder.clone();

                tokio::spawn(async move {
                    let service = service_fn(move |req: Request<Incoming>| async move {
                        handle_request(req, peer_addr).await
                    });

                    if let Err(err) = builder.serve_connection_with_upgrades(stream, service).await {
                        eprintln!("Connection error ({}): {}", peer_addr, err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&hyper::Method::GET, "/") => Response::new(Full::new(Bytes::from_static(
            b"Hello from a high-performance Rust server!",
        ))),

        (&hyper::Method::GET, "/health") => Response::new(Full::new(Bytes::from_static(b"OK"))),

        (&hyper::Method::GET, "/info") => {
            let body = format!("peer={peer_addr}, path={}", req.uri().path());
            Response::new(Full::new(Bytes::from(body)))
        }

        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
```

