type Server struct {
	logger *log.Logger
	mux    *http.ServeMux
}

func NewServer(logger *log.Logger) *Server {
	mux := http.NewServeMux()

	s := &Server{
		logger: logger,
		mux:    mux,
	}

	// Routes
	mux.HandleFunc("/health", s.withMiddleware(s.healthHandler))
	mux.HandleFunc("/api/v1/time", s.withMiddleware(s.timeHandler))

	return s
}

func (s *Server) withMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()

		defer func() {
			if rec := recover(); rec != nil {
				s.logger.Printf("panic recovered: %v", rec)
				http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
			}
		}()

		// Basic request logging
		defer func() {
			s.logger.Printf(
				"%s %s %s from %s took=%s",
				r.Method,
				r.URL.Path,
				r.Proto,
				r.RemoteAddr,
				time.Since(start),
			)
		}()

		next(w, r)
	}
}

func (s *Server) healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)

	_ = json.NewEncoder(w).Encode(map[string]any{
		"status": "ok",
		"uptime": time.Now().UTC().Format(time.RFC3339),
	})
}

func (s *Server) timeHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)

	_ = json.NewEncoder(w).Encode(map[string]any{
		"unix": time.Now().Unix(),
		"utc":  time.Now().UTC().Format(time.RFC3339),
	})
}

func main() {
	logger := log.New(os.Stdout, "[server] ", log.LstdFlags|log.LUTC|log.Lmicroseconds)

	// Use all available CPUs for better concurrency.
	runtime.GOMAXPROCS(runtime.NumCPU())

	server := NewServer(logger)

	port := getEnv("PORT", "8080")

	httpServer := &http.Server{
		Addr:              ":" + port,
		Handler:           server.mux,
		ReadTimeout:       5 * time.Second,
		ReadHeaderTimeout: 2 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20, // 1 MB
	}

	// Start server in background.
	errCh := make(chan error, 1)
	go func() {
		logger.Printf("starting server on :%s", port)
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()

	// Graceful shutdown on SIGINT/SIGTERM
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	select {
	case sig := <-stop:
		logger.Printf("received signal: %s", sig)
	case err := <-errCh:
		logger.Fatalf("server error: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := httpServer.Shutdown(ctx); err != nil {
		logger.Printf("shutdown error: %v", err)
	} else {
		logger.Println("server stopped gracefully")
	}
}

func getEnv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func init() {
	// Optional: allow tuning via env without changing code.
	// Example: GOMAXPROCS=8 PORT=9090
	if v := os.Getenv("GOMAXPROCS"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			runtime.GOMAXPROCS(n)
		}
	}
}
