## `main.go`

```go
package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"strconv"
	"syscall"
	"time"
)

type Job struct {
	ID      int
	Payload string
	Result  chan string
}

type WorkerPool struct {
	jobs chan Job
}

func NewWorkerPool(workerCount int, queueSize int) *WorkerPool {
	wp := &WorkerPool{
		jobs: make(chan Job, queueSize),
	}

	for i := 0; i < workerCount; i++ {
		go func(workerID int) {
			for job := range wp.jobs {
				// Simulate CPU-bound work
				time.Sleep(10 * time.Millisecond)
				job.Result <- "processed job " + strconv.Itoa(job.ID) + " by worker " + strconv.Itoa(workerID)
			}
		}(i)
	}

	return wp
}

func (wp *WorkerPool) Submit(job Job) bool {
	select {
	case wp.jobs <- job:
		return true
	default:
		return false
	}
}

type Server struct {
	pool *WorkerPool
	mux  *http.ServeMux
}

func NewServer(pool *WorkerPool) *Server {
	mux := http.NewServeMux()

	s := &Server{
		pool: pool,
		mux:  mux,
	}

	mux.HandleFunc("/health", s.healthHandler)
	mux.HandleFunc("/process", s.processHandler)

	return s
}

func (s *Server) healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status": "ok",
	})
}

func (s *Server) processHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		ID      int    `json:"id"`
		Payload string `json:"payload"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	resultCh := make(chan string, 1)
	job := Job{
		ID:      req.ID,
		Payload: req.Payload,
		Result:  resultCh,
	}

	if ok := s.pool.Submit(job); !ok {
		http.Error(w, "server busy", http.StatusServiceUnavailable)
		return
	}

	select {
	case result := <-resultCh:
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{
			"result": result,
		})
	case <-r.Context().Done():
		http.Error(w, "request canceled", http.StatusRequestTimeout)
	case <-time.After(2 * time.Second):
		http.Error(w, "processing timeout", http.StatusGatewayTimeout)
	}
}

func main() {
	workerCount := runtime.NumCPU() * 2
	queueSize := 10000

	pool := NewWorkerPool(workerCount, queueSize)
	server := NewServer(pool)

	httpServer := &http.Server{
		Addr:              ":8080",
		Handler:           server.mux,
		ReadTimeout:       5 * time.Second,
		ReadHeaderTimeout: 2 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}

	go func() {
		log.Println("server listening on :8080")
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen error: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	log.Println("shutting down server...")

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	if err := httpServer.Shutdown(ctx); err != nil {
		log.Fatalf("shutdown error: %v", err)
	}

	log.Println("server stopped")
}
```

